    // Feet to metres conversion
    private const double FeetToMetres = 0.3048;
    // Geometry coordinates are emitted on this exact metric lattice.
    private const double IfcGeometryPrecisionMetres = 1.0e-5;
    private const double IfcDeclaredPrecisionMetres = IfcGeometryPrecisionMetres / 2;
    private static readonly Guid AdskSizeHeightParameterGuid =
        Guid.Parse("da753fe3-ecfa-465b-9a2c-02f55d0c2ff1");
    private static readonly Guid AdskSizeWidthParameterGuid =
