    private static (long X, long Y, long Z) IfcPrecisionKeyFeet(double[] point) =>
        (IfcPrecisionBinMetres(point[0] * FeetToMetres),
            IfcPrecisionBinMetres(point[1] * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres));

    private static (long X, long Y, long Z) IfcPrecisionKeyMetres(
        double x, double y, double z) =>
        (IfcPrecisionBinMetres(x), IfcPrecisionBinMetres(y), IfcPrecisionBinMetres(z));

    private static long IfcPrecisionBinMetres(double value) => checked((long)Math.Round(
        value / IfcGeometryPrecisionMetres, MidpointRounding.ToEven));

    private static bool FaceCollapsesAtIfcPrecision(GeoFace face)
    {
        if (face.OuterVertices is not { Count: >= 3 } source
            || source.Any(point => point.Length < 3
                || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;
        var vertices = new List<(long X, long Y, long Z)>();
        foreach (var point in source)
        {
            var key = IfcPrecisionKeyFeet(point);
            if (vertices.Count == 0 || vertices[^1] != key) vertices.Add(key);
        }
        if (vertices.Count > 1 && vertices[0] == vertices[^1]) vertices.RemoveAt(vertices.Count - 1);
        if (vertices.Count < 3) return true;
        var first = vertices[0];
        for (int index = 1; index + 1 < vertices.Count; index++)
        {
            var second = vertices[index];
            var third = vertices[index + 1];
            var ux = (System.Numerics.BigInteger)second.X - first.X;
            var uy = (System.Numerics.BigInteger)second.Y - first.Y;
            var uz = (System.Numerics.BigInteger)second.Z - first.Z;
            var vx = (System.Numerics.BigInteger)third.X - first.X;
            var vy = (System.Numerics.BigInteger)third.Y - first.Y;
            var vz = (System.Numerics.BigInteger)third.Z - first.Z;
            if (!(uy * vz - uz * vy).IsZero
                || !(uz * vx - ux * vz).IsZero
                || !(ux * vy - uy * vx).IsZero)
                return false;
        }
        return true;
    }

    /// <summary>Creates an exporter that writes diagnostics to <paramref name="diagnosticOutput"/> (null for none) and, with <paramref name="includeRevitPropertySets"/>, the Revit parameters as property sets.</summary>
    public IfcExporter(TextWriter? diagnosticOutput = null, bool includeRevitPropertySets = false)
    {
        _diag = diagnosticOutput;
        _includeRevitPropertySets = includeRevitPropertySets;
    }

    /// <summary>Receives the diagnostic messages of the export and of the parsers it runs; null (the default) is silent.</summary>
    public TextWriter? DiagnosticOutput { get => _diag; set => _diag = value; }

    /// <summary>Optional native project phase ID for room selection only.</summary>
    public int? RoomExportPhaseId { get; init; }

    /// <summary>
    /// Keeps the rooms of every phase for the current profile, whose default is the rooms of the
    /// last phase of the project (see <see cref="ResolveActiveRoomPhase"/>).
    /// </summary>
    public bool ExportRoomsOfAllPhases { get; init; }

    /// <summary>
    /// The IFC output dialect (see <see cref="IfcProfile"/>); <see cref="IfcProfile.Current"/> is
    /// the default and the primary target.
    /// </summary>
    public IfcProfile Profile { get; init; } = IfcProfile.Current;

    private bool CurrentProfile => Profile == IfcProfile.Current;

    /// <summary>
    /// RVTIO_X_FBSM=0 keeps the IfcShellBasedSurfaceModel of open shells in the current profile.
    /// </summary>
    private static readonly bool MeshFaceBasedSurface = Environment.GetEnvironmentVariable("RVTIO_X_FBSM") != "0";

    /// <summary>
    /// With Revit property sets enabled, write built-in parameters under their public API
    /// Definition.Name in one property set per parameter group instead of the single
    /// RevitParameters set.
    /// </summary>
    public bool RevitParameterGroups { get; init; }

    private void ValidateRoomExportPhase(RevitFileInfo info)
    {
        if (RoomExportPhaseId == null) return;
        if (RoomExportPhaseId <= 0)
            throw new ArgumentOutOfRangeException(nameof(RoomExportPhaseId), "A room export phase ID must be positive.");
        if (info.SerializedProjectPhaseIds?.Contains(RoomExportPhaseId.Value) != true)
            throw new InvalidOperationException("The requested room export phase is not in a validated project phase order.");
    }

    /// <summary>Receives the elements the export leaves out, with the class and the reason (see <see cref="ExportReport"/>). Null to collect nothing.</summary>
    public SkipLog? SkipLog { get; init; }

    /// <summary>Products written by the last export, as counted in the "IFC export:" diagnostic line.</summary>
    public int ExportedProducts { get; private set; }

    /// <summary>Writes the IFC file for <paramref name="info"/> to <paramref name="outputPath"/>.</summary>
    public void Export(RevitFileInfo info, string outputPath)
    {
        ValidateRoomExportPhase(info); // Reject invalid options before touching an existing output.
        using var fs = new StreamWriter(outputPath, false, System.Text.Encoding.ASCII);
        Export(info, fs);
    }

    private static volatile bool s_keepNonPlanarPolygons;

    /// <summary>Writes the IFC file for <paramref name="info"/> to <paramref name="output"/>.</summary>
    public void Export(RevitFileInfo info, TextWriter output)
    {
        using var diagnosticScope = DiagnosticSink.Use(_diag);
        s_keepNonPlanarPolygons = CurrentProfile && GRepParserV2.MeshEnabled;
        // The current profile exports an instance whose own geometry is only a void helper with the
        // geometry of its computed symbol (Element.SerializedComputedSymbolGeometry); the elements
        // get their own geometry back after the export.
        var computedSymbolGeometry = CurrentProfile ? UseComputedSymbolGeometryCurrent(info.Elements) : [];
        // Revit's IFC export holds the main model and the primary option of each design option set: the elements of another option are left out
        var allElements = info.Elements;
        var designOptions = DesignOptions.Of(allElements);
        info.Elements = allElements.Where(element => designOptions.InNonPrimaryOption(element) != true).ToList();
        try { ExportDocument(info, output); }
        finally
        {
            info.Elements = allElements;
            foreach (var (element, original) in computedSymbolGeometry) element.Geometry = original;
        }
    }

    private void ExportDocument(RevitFileInfo info, TextWriter output)
    {
        ValidateRoomExportPhase(info);
        _geometryUndecoded = info.GeometryUndecoded;
        _usedExportIds.Clear();
        _storeyLevels.Clear();
        _storeyGlobalIds.Clear();
        _recessOpeningEntityIds.Clear();
        _ownCutPairOpeningQuantitiesCurrent.Clear();
        _bodyItemOrigins.Clear();
        _spaceBodyGeometry.Clear();
        _othersCurrentPlans.Clear();
        var w = new StepWriter();
        // The legacy profile writes millimetres whatever the document says; the current profile
        // follows the length unit of the project (IfcLengthUnitChoice).
        _unitFamily = CurrentProfile ? IfcLengthUnitChoice.Family(info.SerializedLengthUnit) : IfcUnitFamily.Millimetre;
        _diag?.WriteLine(info.SerializedLengthUnit != null
            ? $"IFC length unit: stored option {info.SerializedLengthUnit} -> {_unitFamily}"
            : $"IFC length unit: stored option unreadable ({info.SerializedLengthUnitIssue ?? "not read"}); using the default {_unitFamily}");

        int orgId = w.Add("IFCORGANIZATION", $"$,{S("RvtIO")},$,$,$");
        int appId = w.Add("IFCAPPLICATION", $"{R(orgId)},{S("1.0")},{S("RvtIO IFC Exporter")},{S("RvtIO")}");
        int personId = w.Add("IFCPERSON", CurrentProfile ? ProjectPersonArgumentsCurrent(info) : "$,$,$,$,$,$,$,$");
        // The current profile owns the history by the project's author and organization
        // (createProject), not by the developer.
        int owningOrgId = CurrentProfile ? w.Add("IFCORGANIZATION", ProjectOrganizationArgumentsCurrent(info)) : orgId;
        int poaId = w.Add("IFCPERSONANDORGANIZATION", $"{R(personId)},{R(owningOrgId)},$");
        int ownerHistId = w.Add("IFCOWNERHISTORY", $"{R(poaId)},{R(appId)},$,.NOCHANGE.,$,$,$,0");

        // ---- Units (metric: millimetres, square metres, cubic metres).
        int lengthUnitId = w.Add("IFCSIUNIT", _unitFamily == IfcUnitFamily.Millimetre
            ? "*,.LENGTHUNIT.,.MILLI.,.METRE." : "*,.LENGTHUNIT.,$,.METRE.");
        UnitAssignmentCurrent? unitsCurrent = null;
        int unitsId;
        if (CurrentProfile)
        {
            unitsCurrent = CreateUnitAssignmentCurrent(w, lengthUnitId, _unitFamily);
            unitsId = unitsCurrent.AssignmentId;
        }
        else
        {
            int areaUnitId = w.Add("IFCSIUNIT", $"*,.AREAUNIT.,$,.SQUARE_METRE.");
            int volumeUnitId = w.Add("IFCSIUNIT", $"*,.VOLUMEUNIT.,$,.CUBIC_METRE.");
            int angleUnitId = w.Add("IFCSIUNIT", $"*,.PLANEANGLEUNIT.,$,.RADIAN.");
            int timeUnitId = w.Add("IFCSIUNIT", $"*,.TIMEUNIT.,$,.SECOND.");
            unitsId = w.Add("IFCUNITASSIGNMENT", StepWriter.List(R(lengthUnitId), R(areaUnitId), R(volumeUnitId), R(angleUnitId), R(timeUnitId)));
        }

        int originId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
        int axisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(originId)},$,$");
        // The current profile exports the site in shared coordinates (SiteTransformBasis kShared),
        // so TrueNorth is always the y axis: (cos(pi/2), sin(pi/2))
        //.
        int trueNorthId = CurrentProfile ? w.Add("IFCDIRECTION", StepWriter.List(D(Math.Cos(Math.PI / 2)), "1.")) : 0;
        int contextId = w.Add("IFCGEOMETRICREPRESENTATIONCONTEXT",
            $"{(CurrentProfile ? "''" : "$")},{S("Model")},3,{D(CurrentProfile ? (_unitFamily == IfcUnitFamily.Millimetre ? 0.1 : 0.0001) : 0.01)},{R(axisId)},{(CurrentProfile ? R(trueNorthId) : "$")}");
        // The current profile writes the four sub-contexts of CoordinationView 2.0
        // (createContextInformation), each named by its identifier with type "Model" and no target
        // scale; Box and FootPrint are used by the grids and bounding boxes.
        int bodySubCtxId = w.Add("IFCGEOMETRICREPRESENTATIONSUBCONTEXT", CurrentProfile
            ? SubContextArgumentsCurrent("Body", contextId, "MODEL_VIEW")
            : $"$,{S("Body")},*,*,*,*,{R(contextId)},0.,.MODEL_VIEW.,$");
        int axisSubCtxId = w.Add("IFCGEOMETRICREPRESENTATIONSUBCONTEXT", CurrentProfile
            ? SubContextArgumentsCurrent("Axis", contextId, "GRAPH_VIEW")
            : $"{S("Axis")},{S("Model")},*,*,*,*,{R(contextId)},$,.GRAPH_VIEW.,$");
        int footPrintSubCtxId = bodySubCtxId;
        if (CurrentProfile)
        {
            w.Add("IFCGEOMETRICREPRESENTATIONSUBCONTEXT", SubContextArgumentsCurrent("Box", contextId, "MODEL_VIEW"));
            footPrintSubCtxId = w.Add("IFCGEOMETRICREPRESENTATIONSUBCONTEXT",
                SubContextArgumentsCurrent("FootPrint", contextId, "MODEL_VIEW"));
        }

        // Shared direction entities
        int dirZId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "1."));
        int dirXId = w.Add("IFCDIRECTION", StepWriter.List("1.", "0.", "0."));
        int dirNegZId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "-1."));

        bool projectLevelGuidOverridden = HasProjectLevelGuidParameter(info);
        // The current profile passes the three strings to setObject/putAttrAnsi as they are, so an
        // empty one is '' and never unset.
        var (projectName, projectLongName, projectPhase) = CurrentProfile ? ResolveProjectAttributesCurrent(info) : ResolveProjectAttributes(info);
        string ProjectString(string? value) => CurrentProfile ? S(value ?? "") : OptionalString(value);
        string? exactProjectGlobalId = ResolveProjectLevelGlobalId(info, ProjectLevelGuidType.Project, projectLevelGuidOverridden);
        int projectId = w.Add("IFCPROJECT",
            $"{S(exactProjectGlobalId ?? IfcGuid.FromName("project"))},{R(ownerHistId)},{S(projectName)},$,$,"
            + $"{ProjectString(projectLongName)},{ProjectString(projectPhase)},{StepWriter.List(R(contextId))},{R(unitsId)}");

        // A Revit TopographySurface is the physical representation of the IFC spatial site.
        var elementByIdForTerrain = info.Elements.GroupBy(element => element.Id)
            .ToDictionary(group => group.Key, group => group.First());
        var groupDefinitionTopographyIds = info.Elements
            .Where(element => element.CategoryId == -2001340
                && (element.References ?? Enumerable.Empty<int>()).Any(referenceId =>
                    elementByIdForTerrain.TryGetValue(referenceId, out var referenced)
                    && referenced.CategoryId == -2000095))
            .Select(element => element.Id).ToHashSet();
        var placedTopographies = info.Elements
            .Where(element => element.CategoryId == -2001340
                && !element.IsBlockOnly && !element.IsDiscovered
                // A topography payload referenced through IOSModelGroups is group-definition
                // content, not a placed spatial site.
                && !groupDefinitionTopographyIds.Contains(element.Id)
                && element.Geometry?.Faces.Count(face => face.OuterVertices is { Count: >= 3 }) >= 3)
            .ToList();
        var placedTopographyById = placedTopographies.ToDictionary(element => element.Id);
        var terrainAssemblies = new List<(Element Root, List<Element> Surfaces)>();
        foreach (var root in placedTopographies)
        {
            var surfaces = new List<Element> { root };
            var surfaceIds = new HashSet<int> { root.Id };
            foreach (int referencedId in root.References ?? Enumerable.Empty<int>())
            {
                if (!elementByIdForTerrain.TryGetValue(referencedId, out var pad)
                    || pad.CategoryId != -2001263)
                    continue;
                foreach (int padReferenceId in pad.References ?? Enumerable.Empty<int>())
                    if (placedTopographyById.TryGetValue(padReferenceId, out var patch)
                        && surfaceIds.Add(patch.Id))
                        surfaces.Add(patch);
            }
            if (surfaces.Count > 1) terrainAssemblies.Add((root, surfaces));
        }

        // A replacement patch can itself reference its pad and therefore form a strict subset of
        // the root assembly.
        var maximalTerrainAssemblies = terrainAssemblies.Where(candidate =>
        {
            var candidateIds = candidate.Surfaces.Select(surface => surface.Id).ToHashSet();
            return !terrainAssemblies.Any(other => other.Root.Id != candidate.Root.Id
                && other.Surfaces.Count > candidate.Surfaces.Count
                && candidateIds.IsSubsetOf(other.Surfaces.Select(surface => surface.Id)));
        }).ToList();

        Element? spatialTopography = null;
        List<Element> spatialTerrainSurfaces = new();
        if (maximalTerrainAssemblies.Count == 1)
        {
            spatialTopography = maximalTerrainAssemblies[0].Root;
            spatialTerrainSurfaces = maximalTerrainAssemblies[0].Surfaces;
        }
        else if (placedTopographies.Count == 1)
        {
            spatialTopography = placedTopographies[0];
            spatialTerrainSurfaces.Add(spatialTopography);
        }

        int? siteShapeId = spatialTopography != null
            ? CreateFaceBasedSurfaceModels(w, spatialTerrainSurfaces.Select(surface =>
                (Faces: (IReadOnlyList<GeoFace>)surface.Geometry!.Faces,
                    Bounds: surface.BoundingBox ?? surface.Geometry.BoundingBox)).ToList(),
                bodySubCtxId)
            : null;

        int sitePlacementId;
        if (info.SharedTransform is { Length: 12 } st
            && (Math.Abs(st[1]) > 1e-9 || Math.Abs(st[9]) > 1e-6 || Math.Abs(st[10]) > 1e-6
                || (CurrentProfile && Math.Abs(st[11]) > 1e-6)))
        {
            // The current profile scales feet to millimetres (x 304.8) and prints all 17 digits of
            // the product.
            string SiteCoordinate(double feet) =>
                CurrentProfile ? StepWriter.RealFromMillimetres(feet * 304.8) : D(feet * FeetToMetres);
            int siteOriginId = w.Add("IFCCARTESIANPOINT",
                StepWriter.List(SiteCoordinate(st[9]), SiteCoordinate(st[10]), SiteCoordinate(st[11])));
            if (CurrentProfile && Math.Abs(st[0] - 1) <= 1e-10)
                sitePlacementId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(siteOriginId)},$,$");
            else
            {
                int siteRefDirId = w.Add("IFCDIRECTION", StepWriter.List(D(st[0]), D(st[1]), "0."));
                sitePlacementId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(siteOriginId)},{R(dirZId)},{R(siteRefDirId)}");
            }
        }
        else
            sitePlacementId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(originId)},$,$");
        int siteLocalPlacementId = w.Add("IFCLOCALPLACEMENT", $"$,{R(sitePlacementId)}");
        // The current profile names the surface "{Surface family label}:{id}"
        string siteName = spatialTopography == null
            ? "Default"
            : $"{(CurrentProfile ? spatialTopography.SerializedUiFamilyLabel : null) ?? "Topography"}:{spatialTopography.Id}";
        string? exactSiteGlobalId = ResolveProjectLevelGlobalId(info, ProjectLevelGuidType.Site, projectLevelGuidOverridden);
        string siteGuid = exactSiteGlobalId
            ?? (spatialTopography == null
                ? IfcGuid.FromName("site") : IfcGuid.FromElementId(spatialTopography.Id));
        // The current profile passes empty LongName and LandTitleNumber strings for the main site
        //.
        string siteEmptyString = CurrentProfile ? "''" : "$";
        // The current profile reads RefLatitude/RefLongitude from the GeoSite of the active project
        // location and RefElevation from the project base point; the
        // legacy profile leaves them unset.
        string siteGeoReference = CurrentProfile && info.SiteLatitudeRadians is double siteLatitude
            && info.SiteLongitudeRadians is double siteLongitude
            ? $"{CompoundPlaneAngle(siteLatitude)},{CompoundPlaneAngle(siteLongitude)},"
                + StepWriter.RealFromMillimetres(info.SiteElevationFeet * 304.8)
            : "$,$,$";
        // The current profile creates the postal address of the project for the site and for the
        // building but assigns it to neither: both addresses stand alone in the file.
        if (CurrentProfile) w.Add("IFCPOSTALADDRESS", PostalAddressArgumentsCurrent(info));
        int siteId = w.Add("IFCSITE",
            $"{S(siteGuid)},{R(ownerHistId)},{S(siteName)},$,$,{R(siteLocalPlacementId)},"
            + $"{(siteShapeId.HasValue ? R(siteShapeId.Value) : "$")},{siteEmptyString},.ELEMENT.,{siteGeoReference},{siteEmptyString},$");

        int bldgPlacementId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(originId)},$,$");
        int bldgLocalPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(siteLocalPlacementId)},{R(bldgPlacementId)}");
        // The current profile names the building
        // PROJECT_BUILDING_NAME, '' when it is empty, and repeats it as LongName.
        string? projectBuildingName = CurrentProfile ? ResolveBuildingNameCurrent(info) : info.ProjectInfo?.BuildingName;
        string buildingName = projectBuildingName ?? (CurrentProfile ? "" : "Building");
        if (CurrentProfile) w.Add("IFCPOSTALADDRESS", PostalAddressArgumentsCurrent(info));
        int buildingId = w.Add("IFCBUILDING",
            $"{S(ResolveProjectLevelGlobalId(info, ProjectLevelGuidType.Building, projectLevelGuidOverridden) ?? IfcGuid.FromName("building"))},{R(ownerHistId)},{S(buildingName)},$,$,{R(bldgLocalPlacementId)},$,"
            + $"{(CurrentProfile ? S(buildingName) : OptionalString(info.ProjectInfo?.BuildingName))},.ELEMENT.,$,$,$");

        w.Add("IFCRELAGGREGATES", $"{S(ContainmentCacheGlobalId(exactProjectGlobalId) ?? IfcGuid.FromName("agg:project-site"))},{R(ownerHistId)},$,$,{R(projectId)},{StepWriter.List(R(siteId))}");
        w.Add("IFCRELAGGREGATES", $"{S(ContainmentCacheGlobalId(exactSiteGlobalId) ?? IfcGuid.FromName("agg:site-building"))},{R(ownerHistId)},$,$,{R(siteId)},{StepWriter.List(R(buildingId))}");

        var storeyIds = new Dictionary<int, int>();       // level elem ID -> IFC storey entity ID
        var storeyPlacements = new Dictionary<int, int>(); // storey entity ID -> IFC placement ID
        var storeyElevationsMetres = new Dictionary<int, double>();
        var storeyContents = new Dictionary<int, List<int>>(); // storey entity ID -> element IFC IDs
        var storeyIfcIds = new List<int>();
        int defaultStoreyId;
        int defaultStoreyPlacementId;

        // Revit serializes the exact building-storey flag on every project Level.
        var levelElems = GetBuildingStoreyLevels(info.Elements);
        var levelExportNames = levelElems.ToDictionary(e => e.Id, e => e.Name!);
        // Storey names actually exported as IFCBUILDINGSTOREY, consumed by
        // SuppressLevelNameContamination.
        var levelNames = new HashSet<string>(levelExportNames.Values, StringComparer.Ordinal);

        if (levelElems.Count > 0)
        {
            foreach (var lvl in levelElems)
            {
                double elevFt = GetElevation(lvl);
                double elevM = Math.Round(elevFt * FeetToMetres, 4); // round to 0.1mm
                if (Math.Abs(elevM) < 1e-6) elevM = 0.0; // avoid -0.
                int lvlPtId = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(0), D(0), D(elevM)));
                int lvlAxisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(lvlPtId)},$,$");
                int lvlPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(bldgLocalPlacementId)},{R(lvlAxisId)}");
                string lvlName = levelExportNames[lvl.Id];
                // The legacy profile names a storey after the document GUID (CreateAlternateGUID); the current one after the level's own export id.
                string? storeyGuid = (CurrentProfile ? ResolveExactElementGlobalId(lvl, _usedExportIds, handleBased: true) : null)
                    ?? ResolveDocumentGlobalId(info, lvl.Id, _usedExportIds);
                string storeyObjectType = CurrentProfile ? OptionalString(
                    StoreyObjectType(lvl, elementByIdForTerrain.GetValueOrDefault(lvl.FamilyTypeId))) : "$";
                string storeyLongName = CurrentProfile ? S(lvlName) : "$";
                string storeyGlobalId = storeyGuid ?? IfcGuid.FromElementId(lvl.Id);
                int sid = w.Add("IFCBUILDINGSTOREY",
                    $"{S(storeyGlobalId)},{R(ownerHistId)},{S(lvlName)},$,{storeyObjectType},{R(lvlPlacementId)},$,{storeyLongName},.ELEMENT.,{D(elevM)}");
                storeyIds[lvl.Id] = sid;
                _storeyLevels[sid] = lvl;
                _storeyGlobalIds[sid] = storeyGlobalId;
                storeyPlacements[sid] = lvlPlacementId;
                storeyElevationsMetres[sid] = elevM;
                storeyContents[sid] = new List<int>();
                storeyIfcIds.Add(sid);
            }
            defaultStoreyId = storeyIfcIds[0]; // lowest level as fallback
            defaultStoreyPlacementId = storeyPlacements[defaultStoreyId];
        }
        else if (info.GeometryUndecoded || CurrentProfile)
        {
            defaultStoreyId = buildingId;
            defaultStoreyPlacementId = bldgLocalPlacementId;
            storeyPlacements[buildingId] = bldgLocalPlacementId;
            storeyContents[buildingId] = new List<int>();
        }
        else
        {
            // Fallback: single default storey at elevation 0
            int spId = w.Add("IFCLOCALPLACEMENT", $"{R(bldgLocalPlacementId)},{R(axisId)}");
            defaultStoreyId = w.Add("IFCBUILDINGSTOREY",
                $"{S(IfcGuid.FromName("default-storey"))},{R(ownerHistId)},{S("Level 0")},$,$,{R(spId)},$,$,.ELEMENT.,0.");
            defaultStoreyPlacementId = spId;
            storeyPlacements[defaultStoreyId] = spId;
            storeyContents[defaultStoreyId] = new List<int>();
            storeyIfcIds.Add(defaultStoreyId);
        }

        // Aggregate all storeys under building: CreateSubElementGUID(ProjectInformation,
        // IFCProjectSubElements.RelAggregatesBuildingStories) when the storeys are levels.
        string? buildingStoreysGlobalId = levelElems.Count > 0 && SoleProjectInformation(info) is { } projectInformation
            ? ResolveExactElementGlobalId(projectInformation, _usedExportIds, ProjectRelAggregatesBuildingStories, CurrentProfile)
            : null;
        if (storeyIfcIds.Count > 0)
            w.Add("IFCRELAGGREGATES",
                $"{S(buildingStoreysGlobalId ?? IfcGuid.FromName("agg:building-storeys"))},{R(ownerHistId)},$,$,{R(buildingId)},{StepWriter.List(storeyIfcIds.Select(R))}");

        _diag?.WriteLine($"IFC storeys: {storeyIfcIds.Count}" +
            (levelElems.Count > 0 ? " - " + string.Join(", ", levelElems.Select(l => $"{levelExportNames[l.Id]}@{GetElevation(l) * FeetToMetres:F2}m")) : " (default)"));

        // NumberOfStoreys only.
        {
            int numberOfStoreysValueId = w.Add("IFCPROPERTYSINGLEVALUE",
                $"{S("NumberOfStoreys")},$,IFCINTEGER({storeyIfcIds.Count}),$");
            int buildingCommonPsetId = w.Add("IFCPROPERTYSET",
                $"{S(IfcGuid.FromName("building-common-pset"))},{R(ownerHistId)},{S("Pset_BuildingCommon")},$,{StepWriter.List(R(numberOfStoreysValueId))}");
            w.Add("IFCRELDEFINESBYPROPERTIES",
                $"{S(IfcGuid.FromName("building-common-rel"))},{R(ownerHistId)},$,$,{StepWriter.List(R(buildingId))},{R(buildingCommonPsetId)}");
        }


        var elemById = new Dictionary<int, Element>();
        var elementIdOccurrenceCounts = new Dictionary<int, int>();
        var elementOrderById = new Dictionary<int, int>();
        for (int elementIndex = 0; elementIndex < info.Elements.Count; elementIndex++)
        {
            var e = info.Elements[elementIndex];
            elemById.TryAdd(e.Id, e);
            elementIdOccurrenceCounts.TryGetValue(e.Id, out int occurrenceCount);
            elementIdOccurrenceCounts[e.Id] = occurrenceCount + 1;
            elementOrderById.TryAdd(e.Id, elementIndex);
        }
        _elementsByIdCurrent = elemById;
        _axisExtrusionBodyCurrent.Clear();
        if (CurrentProfile)
            CreateCurrentGrids(w, ownerHistId, footPrintSubCtxId, axisId, info.Elements, info.ElemTableIsExact,
                storeyIfcIds, storeyPlacements, storeyContents);
        else
            CreateSerializedGrids(w, ownerHistId, bodySubCtxId, axisId, info.Elements,
                storeyIfcIds, storeyPlacements, storeyContents);
        var representationMapsBySymbol =
            new Dictionary<int, RepresentationMapCacheEntry>();

        static int? IntParam(Element e, int id)
        {
            object? value = e.Parameters.FirstOrDefault(p => p.Id == id)?.Value;
            return value is int n ? n : null;
        }
        static bool HasProjectPhaseReference(Element e)
        {
            int? phase = IntParam(e, -1012100); // PHASE_CREATED
            // Id 0 is a phase of Revit 2023 and later (the first project phase, a row of its
            // element table); the earlier layouts number phases from 1.
            return phase is > 0 && (e.References?.Contains(phase.Value) == true || e.SerializedCreatedPhaseId == phase.Value)
                || phase == 0 && e.SerializedCreatedPhaseId == 0;
        }

        // Element types can carry preview/type geometry in the RVT stream, but they are definitions
        // rather than placed products.
        var typeElementIds = new HashSet<int>();
        foreach (var e in info.Elements)
            foreach (var p in e.Parameters)
                if (p.Id is -1002050 or -1002052 && p.Value is int typeId && typeId > 0)
                    typeElementIds.Add(typeId);

        // A placed curtain panel/mullion references its parent wall.
        var curtainWallIds = new HashSet<int>();
        foreach (var child in info.Elements.Where(e => e.CategoryId is -2000171 or -2000170))
            foreach (int refId in child.References ?? Enumerable.Empty<int>())
                if (elemById.TryGetValue(refId, out var parent) && parent.CategoryId == -2000011)
                    curtainWallIds.Add(refId);

        var exactCurtainChildren = ResolveExactCurtainChildren(
            info.Elements, elemById, elementIdOccurrenceCounts);
        curtainWallIds.UnionWith(exactCurtainChildren.Keys);
        var curtainPanelWallIds = CurrentProfile
            ? exactCurtainChildren.Values.SelectMany(ids => ids)
                .Where(id => elemById.TryGetValue(id, out var child) && child.CategoryId == -2000011).ToHashSet()
            : [];
        var roofContainerChildren = ResolveRoofContainerChildren(info.Elements, elemById, elementIdOccurrenceCounts);
        // Roof element id -> entity id of the IfcSlab (ROOF) that holds its body (the current
        // profile, RoofIsExportedWithSlabCurrent).
        var roofSlabParts = new Dictionary<int, int>();
        var pendingCurtainParents = new Dictionary<int, (Element Element, int StoreyId, bool CountedSuppressed)>();

        // Real project walls have a decoded location curve (or, for the one curved wall, a
        // substantial mesh).
        var visibleWallIds = info.Elements
            .Where(e => e.CategoryId == -2000011)
            .Where(e =>
            {
                int rich = e.Geometry?.Faces?.Count(f => f.OuterVertices is { Count: >= 3 }) ?? 0;
                return e.Location != null || rich >= 3 || HasProjectPhaseReference(e);
            })
            .Select(e => e.Id)
            .ToHashSet();

        // Phantom-storey walls: LEVEL_PARAM resolves to a Level GetBuildingStoreyLevels above did
        // not accept as a project storey.
        var phantomStoreyWallIds = info.Elements
            .Where(candidate => candidate.CategoryId == -2000011
                && visibleWallIds.Contains(candidate.Id)
                && !(curtainWallIds.Contains(candidate.Id)
                    && candidate.Layers is not { Count: > 0 })
                && ShouldSuppressPhantomStoreyWallProduct(
                    "IFCWALLSTANDARDCASE", IntParam(candidate, -1001952), storeyIds)
                // A project Level that is not a building story is a real level, not a phantom.
                && !(IntParam(candidate, -1001952) is int levelId
                    && elemById.TryGetValue(levelId, out var wallLevel)
                    && IsProjectLevel(wallLevel)))
            .Select(candidate => candidate.Id)
            .ToHashSet();

        // Shared by every wallId-keyed opening-creation loop below (hostedElements and the
        // wall's-own-BRep-derived openings) so a suppressed host's cascade is counted exactly once
        // per pairing.
        void RecordPhantomStoreyWallHostedOpeningCascade(int wallId)
        {
            if (phantomStoreyWallIds.Contains(wallId))
                _suppressedPhantomStoreyWallHostedOpeningCount++;
        }

        // CurveDriver wall references may be serialized on either participant.
        var wallPathNeighbourIdsByWall =
            new Dictionary<int, HashSet<int>>();
        foreach (var wall in info.Elements.Where(element =>
                     element.CategoryId == -2000011))
            foreach (int referenceId in wall.References?.Distinct()
                         ?? Enumerable.Empty<int>())
            {
                if (referenceId == wall.Id
                    || !elemById.TryGetValue(referenceId, out var neighbour)
                    || neighbour.CategoryId != -2000011)
                    continue;
                if (!wallPathNeighbourIdsByWall.TryGetValue(
                        wall.Id, out var wallNeighbours))
                    wallPathNeighbourIdsByWall[wall.Id] =
                        wallNeighbours = [];
                if (!wallPathNeighbourIdsByWall.TryGetValue(
                        referenceId, out var neighbourNeighbours))
                    wallPathNeighbourIdsByWall[referenceId] =
                        neighbourNeighbours = [];
                wallNeighbours.Add(referenceId);
                neighbourNeighbours.Add(wall.Id);
            }

        var inverseHostedHostIds = new Dictionary<int, List<int>>();
        foreach (var host in info.Elements.Where(e =>
                     e.CategoryId is -2000011 or -2000032 or -2000035))
            foreach (int referencedId in SerializedHostCuttingElementIds(host).Distinct())
            {
                if (!inverseHostedHostIds.TryGetValue(referencedId, out var hostIds))
                    inverseHostedHostIds[referencedId] = hostIds = new List<int>();
                hostIds.Add(host.Id);
            }
        DiagnosticSink.WriteLine($"IFC host cut topology: "
            + $"{info.Elements.Count(element => element.CuttingElementIds != null)} exact-decoded hosts, "
            + $"{inverseHostedHostIds.Values.SelectMany(ids => ids).Distinct().Count()} indexed hosts, "
            + $"{inverseHostedHostIds.Sum(pair => pair.Value.Count)} relations");

        // A door/window's authored forward host relation is sufficient to create its separately
        // related IfcOpeningElement below, even when the host's inverse WallCutoutGStepBase list
        // was unavailable.
        var hostedDoorWindowCutterIdsByWall = new Dictionary<int, List<int>>();
        foreach (var cutter in info.Elements.Where(element =>
                     element.CategoryId is -2000023 or -2000014
                     && element.SuperInstanceId is not > 0
                     && element.BoundingBox is { Length: 6 } cutterBounds
                     && cutterBounds.All(double.IsFinite)))
            foreach (int hostId in ResolveHostedElementHostIds(
                         cutter, elemById, visibleWallIds, inverseHostedHostIds)
                     .Where(id => elemById[id].CategoryId == -2000011
                         && HostedElementCanCutHost(cutter.BoundingBox!, elemById[id])))
            {
                if (!hostedDoorWindowCutterIdsByWall.TryGetValue(
                        hostId, out var cutterIds))
                    hostedDoorWindowCutterIdsByWall[hostId] = cutterIds = [];
                if (!cutterIds.Contains(cutter.Id)) cutterIds.Add(cutter.Id);
            }

        // Precompute every hosted relation that the export loop below can turn into an
        // IfcOpeningElement.
        var emittedHostedCutterIdsByWall = new Dictionary<int, List<int>>();
        var emittedHostedOpeningOperandsByWall =
            new Dictionary<int, List<(int CutterId, HostedOpeningGeometry Operand)>>();
        var legacyHostedOpeningOperandsByWall =
            new Dictionary<int, List<(int CutterId, HostedOpeningGeometry Operand)>>();
        var ownPrimaryFamilyWriterOperands =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactJoinedWallEndProfileOpenings =
            new Dictionary<int, (
                ProfileWallThroughOpening Opening, int TagId)>();
        var exactSingleLinkedSourceOpenings =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactBoundarySlotSourceOpenings =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactBoundarySlotWriterOpenings =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactThreeOpenFamilyCutLoopWriterPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactForwardSecondaryFamilyCutPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactForwardSecondaryFamilyCutOpenings =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactReferenceOnlySixPointJoinBottomSlotFamilyCutPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactEmbeddedSingleFamilyCutBrepPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactCompleteOpenTwelveFaceFullWriterFamilyCutPairs =
            new HashSet<(int WallId, int CutterId)>();
        var verifiedExactSingleLinkedSourceOpenings =
            new HashSet<(int WallId, int CutterId)>();
        var verifiedExactBoundarySlotSourceOpenings =
            new HashSet<(int WallId, int CutterId)>();
        var exactJoinedSpanBrepSweptOpeningPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactConcordantFamilyCutBrepSweptOpeningPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactVerticalStepBrepSweptOpeningPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactCompleteOpenTenFaceSideCoincidentBrepSweptOpeningPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactCompleteOpenTenFaceSideCoincidentBrepSweptWriterOperands =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactCompleteOpenTenFaceQuarteredRevealOpeningPairs =
            new HashSet<(int WallId, int CutterId)>();
        var exactCompleteOpenTenFaceQuarteredRevealWriterOperands =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactCompleteOpenTwentyFiveFaceOpposedSidePocketWriterOperands =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        var exactCompleteOpenSixteenFaceSplitRevealWriterOperands =
            new Dictionary<(int WallId, int CutterId), HostedOpeningGeometry>();
        foreach (var cutter in info.Elements.Where(element =>
                     element.SuperInstanceId is not > 0
                     && element.BoundingBox is { Length: 6 } cutterBounds
                     && cutterBounds.All(double.IsFinite)))
        {
            bool doorOrWindow = cutter.CategoryId is -2000023 or -2000014;
            inverseHostedHostIds.TryGetValue(
                cutter.Id, out var inverseCutHosts);
            bool inverseHostedCutter =
                (cutter.SerializedHostId.HasValue || cutter.HostId.HasValue)
                && inverseCutHosts != null;
            if (!doorOrWindow && !inverseHostedCutter) continue;
            var candidateHostIds = ResolveHostedElementHostIds(
                    cutter, elemById, visibleWallIds, inverseHostedHostIds)
                .Where(id => elemById[id].CategoryId == -2000011
                    && HostedElementCanCutHost(cutter.BoundingBox!, elemById[id])
                    && (doorOrWindow || inverseCutHosts!.Contains(id)))
                .ToList();
            bool precomputeDiagnostics = Environment.GetEnvironmentVariable(
                    "RVTIO_GEOM_DBG_ID") is { } precomputeDebugIds
                && precomputeDebugIds.Split(
                        ',', StringSplitOptions.RemoveEmptyEntries
                        | StringSplitOptions.TrimEntries)
                    .Any(value => int.TryParse(value, out int id)
                        && (id == cutter.Id || candidateHostIds.Contains(id)));
            if (precomputeDiagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCHOSTPRECOMPUTE cutter={cutter.Id} "
                    + $"category={cutter.CategoryId} doorOrWindow={doorOrWindow} "
                    + $"candidates={string.Join(',', candidateHostIds)}");
            var candidateHostWalls = candidateHostIds
                .Select(id => elemById[id]).ToList();
            IReadOnlyList<Element> familyCutTypes =
                LinkedFamilyCutTypes(cutter, elemById);
            Element? hostedType = LinkedFamilyType(cutter, elemById);
            HostedOpeningGeometry commonOpening = default;
            var builtFamilyCutCandidates = new List<HostedOpeningGeometry>();
            bool allLinkedFamilyCutTypesBuilt = familyCutTypes.Count >= 2;
            foreach (var familyCutType in familyCutTypes)
            {
                if (TryBuildFamilyCutHostedOpeningGeometry(
                        cutter, familyCutType, candidateHostWalls,
                        out var familyCutCandidate))
                    builtFamilyCutCandidates.Add(familyCutCandidate);
                else
                    allLinkedFamilyCutTypesBuilt = false;
            }
            bool builtFamilyCut = builtFamilyCutCandidates.Count > 0;
            if (builtFamilyCut)
            {
                commonOpening = builtFamilyCutCandidates[0];
            }
            HostedOpeningGeometry preferredMultiHostFamilyCutOpening = default;
            bool builtExactPreferredMultiHostFamilyCut =
                builtFamilyCut
                && TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                    cutter, familyCutTypes, builtFamilyCutCandidates,
                    candidateHostWalls, inverseHostedHostIds,
                    out preferredMultiHostFamilyCutOpening);
            if (builtExactPreferredMultiHostFamilyCut)
                commonOpening = preferredMultiHostFamilyCutOpening;
            bool builtFamilyCutLoop = !builtFamilyCut && familyCutTypes.Any(type =>
                    TryBuildFamilyCutLoopHostedOpeningGeometry(
                        cutter, type, out commonOpening));
            if (!builtFamilyCut && !builtFamilyCutLoop)
            {
                bool builtPrimitiveOpening =
                    TryBuildSerializedHostedOpeningGeometry(
                        cutter, hostedType, out commonOpening);
                if (builtPrimitiveOpening
                    && candidateHostWalls.Any(hostWall =>
                        HasExactSixPointJoinShellWithTwoOpeningSourceAuthority(
                            hostWall.Geometry))
                    && TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
                        cutter, cutter.BoundingBox!, candidateHostWalls,
                        commonOpening, out var exactAuthoredEnvelope))
                    commonOpening = exactAuthoredEnvelope;
                else if (!builtPrimitiveOpening)
                    builtPrimitiveOpening = TryBuildCommonHostedOpeningGeometry(
                        cutter, cutter.BoundingBox!, candidateHostWalls,
                        out commonOpening);
                if (builtPrimitiveOpening)
                {
                    if (
                        TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                            cutter, candidateHostWalls, commonOpening,
                            out var quarteredOpening, elemById,
                            inverseHostedHostIds))
                        commonOpening = quarteredOpening;
                    else if (
                        TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                            cutter, hostedType, cutter.BoundingBox!,
                            candidateHostWalls, commonOpening,
                            out var steppedOpening))
                        commonOpening = steppedOpening;
                }
                else if (!builtPrimitiveOpening
                    && TryBuildUniqueExactSteppedMultiHostOpeningFromAuthoredHostProfiles(
                        cutter, hostedType, cutter.BoundingBox!,
                        candidateHostWalls, out var subsetSteppedOpening))
                    commonOpening = subsetSteppedOpening;
            }
            HostedOpeningGeometry preSourceSteppedOpening =
                commonOpening;
            bool builtExactSourceWallProfilesMappedBreakpoint = false;
            // A closed source-wall profile pair plus its mapped breakpoint is a stronger operand
            // definition than a reconstructed common host envelope.
            if (!builtFamilyCut && !builtFamilyCutLoop
                && TryBuildExactSteppedOpeningFromSourceWallProfilesAndMappedBreakpoint(
                    cutter, candidateHostWalls, out var sourceSteppedOpening))
            {
                commonOpening = sourceSteppedOpening;
                builtExactSourceWallProfilesMappedBreakpoint = true;
            }
            HostedOpeningGeometry
                exactCompleteOpenTenFaceQuarteredRevealOpening = default;
            bool builtExactCompleteOpenTenFaceQuarteredReveal =
                !builtFamilyCut && !builtFamilyCutLoop
                && TryBuildExactQuarteredRevealOpeningFromCompleteOpenTenFaceHoleWithDetachedPatch(
                    cutter, candidateHostWalls, elemById,
                    inverseHostedHostIds,
                    out exactCompleteOpenTenFaceQuarteredRevealOpening);
            foreach (int hostId in candidateHostIds)
            {
                if (HasExactEmbeddedSingleFamilyCutBrepAuthority(
                        elemById[hostId], cutter.Id))
                {
                    exactEmbeddedSingleFamilyCutBrepPairs.Add(
                        (hostId, cutter.Id));
                    continue;
                }
                if (!builtExactSourceWallProfilesMappedBreakpoint
                    && doorOrWindow
                    && HostedFillingProductCanBeEmitted(cutter, elemById, storeyIds, HasProjectPhaseReference(cutter))
                    && TryBuildOwnPrimaryFamilyCutout(cutter, elemById[hostId], out var ownPrimaryOpening))
                    ownPrimaryFamilyWriterOperands[(hostId, cutter.Id)] = ownPrimaryOpening;
                if (precomputeDiagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCHOSTPRECOMPUTE cutter={cutter.Id} host={hostId} "
                        + $"stage=enter familyCut={builtFamilyCut} "
                        + $"familyCutLoop={builtFamilyCutLoop} "
                        + $"writerLoop={commonOpening.IsFamilyCutLoop}");
                // The writer applies this same exact family-cut intersection before it creates an
                // IfcOpeningElement.
                bool usesExactCompleteOpenTenFaceQuarteredReveal =
                    builtExactCompleteOpenTenFaceQuarteredReveal;
                HostedOpeningGeometry targetedOpening =
                    usesExactCompleteOpenTenFaceQuarteredReveal
                        ? exactCompleteOpenTenFaceQuarteredRevealOpening
                        : commonOpening;
                if (usesExactCompleteOpenTenFaceQuarteredReveal)
                {
                    exactCompleteOpenTenFaceQuarteredRevealOpeningPairs.Add(
                        (hostId, cutter.Id));
                    exactCompleteOpenTenFaceQuarteredRevealWriterOperands[
                        (hostId, cutter.Id)] = targetedOpening;
                }
                bool usesExactForwardSecondaryFamilyCut = false;
                bool usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut =
                    !usesExactCompleteOpenTenFaceQuarteredReveal
                    && builtFamilyCutLoop
                    && TryGetExactReferenceOnlySixPointJoinBottomSlotFamilyCutOpening(
                        cutter, elemById[hostId], candidateHostIds,
                        inverseCutHosts, elemById, commonOpening,
                        out targetedOpening);
                bool usesExactJoinedFaceSubsetFamilyCut =
                    !usesExactCompleteOpenTenFaceQuarteredReveal
                    && !usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut
                    && builtFamilyCutLoop
                    && TryGetExactJoinedFaceSubsetFamilyCutOpening(
                        cutter, elemById[hostId], candidateHostIds,
                        inverseCutHosts, elemById, commonOpening,
                        out targetedOpening);
                bool usesExactCompleteOpenTwelveFaceFullWriterFamilyCut =
                    !usesExactCompleteOpenTenFaceQuarteredReveal
                    && !usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut
                    && !usesExactJoinedFaceSubsetFamilyCut
                    && builtFamilyCutLoop
                    && TryGetExactCompleteOpenTwelveFaceDetachedAlternativeFullHeightFamilyCutOpening(
                        cutter, elemById[hostId], candidateHostIds,
                        inverseCutHosts, elemById, visibleWallIds,
                        commonOpening, out targetedOpening);
                if (usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut
                    || usesExactJoinedFaceSubsetFamilyCut
                    || usesExactCompleteOpenTwelveFaceFullWriterFamilyCut)
                {
                    usesExactForwardSecondaryFamilyCut = true;
                    exactForwardSecondaryFamilyCutPairs.Add(
                        (hostId, cutter.Id));
                    exactForwardSecondaryFamilyCutOpenings[
                        (hostId, cutter.Id)] = targetedOpening;
                    if (usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut)
                        exactReferenceOnlySixPointJoinBottomSlotFamilyCutPairs.Add(
                            (hostId, cutter.Id));
                    if (usesExactCompleteOpenTwelveFaceFullWriterFamilyCut)
                        exactCompleteOpenTwelveFaceFullWriterFamilyCutPairs.Add(
                            (hostId, cutter.Id));
                }
                bool usesCompleteOpenTwelveFaceMinimumCapTouchValidation =
                    !usesExactCompleteOpenTenFaceQuarteredReveal
                    && !usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut
                    && !usesExactJoinedFaceSubsetFamilyCut
                    && !usesExactCompleteOpenTwelveFaceFullWriterFamilyCut
                    && builtFamilyCutLoop
                    && HasExactCompleteOpenTwelveFaceNoAlternativeSourceAuthority(
                        elemById[hostId].Geometry)
                    && TryGetExactForwardSecondaryFamilyCutOpening(
                        cutter, elemById[hostId], candidateHostIds,
                        inverseCutHosts, elemById, commonOpening,
                        out targetedOpening,
                        out bool exactMinimumCapTouchValidation)
                    && exactMinimumCapTouchValidation;
                if (usesCompleteOpenTwelveFaceMinimumCapTouchValidation)
                {
                    usesExactForwardSecondaryFamilyCut = true;
                    exactForwardSecondaryFamilyCutPairs.Add(
                        (hostId, cutter.Id));
                    exactForwardSecondaryFamilyCutOpenings[
                        (hostId, cutter.Id)] = targetedOpening;
                }
                else if (!usesExactCompleteOpenTenFaceQuarteredReveal
                    && !usesExactReferenceOnlySixPointJoinBottomSlotFamilyCut
                    && !usesExactJoinedFaceSubsetFamilyCut
                    && !usesExactCompleteOpenTwelveFaceFullWriterFamilyCut)
                {
                    if ((builtFamilyCut || builtFamilyCutLoop)
                        && !TryTargetCommonHostedOpeningToHost(
                            commonOpening, elemById[hostId],
                            out targetedOpening))
                    {
                        if (!builtFamilyCutLoop
                            || !TryGetExactForwardSecondaryFamilyCutOpening(
                            cutter, elemById[hostId], candidateHostIds,
                            inverseCutHosts, elemById, commonOpening,
                            out targetedOpening))
                            continue;
                        usesExactForwardSecondaryFamilyCut = true;
                        exactForwardSecondaryFamilyCutPairs.Add(
                            (hostId, cutter.Id));
                        exactForwardSecondaryFamilyCutOpenings[
                            (hostId, cutter.Id)] = targetedOpening;
                    }
                }
                if (builtFamilyCut && allLinkedFamilyCutTypesBuilt)
                {
                    var exactFamilyCutDefinitions =
                        new List<HostedOpeningGeometry>();
                    foreach (var familyCutCandidate in builtFamilyCutCandidates)
                    {
                        if (!TryTargetCommonHostedOpeningToHost(
                                familyCutCandidate, elemById[hostId],
                                out var targetedFamilyCut)
                            || !TryGetExactVerticalRectangularPrismSweptOpening(
                                targetedFamilyCut.Boundary,
                                out var exactFamilyCutDefinition))
                        {
                            exactFamilyCutDefinitions.Clear();
                            break;
                        }
                        exactFamilyCutDefinitions.Add(exactFamilyCutDefinition);
                    }
                    if (ExactSweptOpeningDefinitionsAreConcordant(
                            exactFamilyCutDefinitions)
                        || builtExactPreferredMultiHostFamilyCut)
                        exactConcordantFamilyCutBrepSweptOpeningPairs.Add(
                            (hostId, cutter.Id));
                }
                HostedOpeningGeometry exactSingleLinkedSourceOpening = default;
                bool usesBoundarySlotSourceValidation = false;
                bool recoveredExactSourceOpening =
                    TryGetExactSingleLinkedSourceOpening(
                        elemById[hostId], cutter.Id,
                        out exactSingleLinkedSourceOpening,
                        out usesBoundarySlotSourceValidation);
                bool hasExactSingleLinkedSourceOpening =
                    recoveredExactSourceOpening
                    && (candidateHostIds.Count == 1
                        || usesBoundarySlotSourceValidation);
                if (precomputeDiagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCHOSTPRECOMPUTE cutter={cutter.Id} host={hostId} "
                        + $"stage=targeted secondarySource="
                        + usesExactForwardSecondaryFamilyCut
                        + $" source={hasExactSingleLinkedSourceOpening} "
                        + $"boundarySlot={usesBoundarySlotSourceValidation}");
                if (!emittedHostedCutterIdsByWall.TryGetValue(
                        hostId, out var cutterIds))
                    emittedHostedCutterIdsByWall[hostId] = cutterIds = [];
                if (!cutterIds.Contains(cutter.Id)) cutterIds.Add(cutter.Id);

                // A FamilyCutLoop is clipped to the direct host only when the later writer also
                // emits a visible filling product.
                if (builtFamilyCutLoop && commonOpening.IsFamilyCutLoop
                    && !doorOrWindow)
                {
                    if (precomputeDiagnostics)
                        DiagnosticSink.WriteLine(
                            $"IFCHOSTPRECOMPUTE cutter={cutter.Id} host={hostId} "
                            + "stage=skip-non-door-family-loop");
                    continue;
                }
                bool directHost = cutter.SerializedHostId == hostId
                    || cutter.ExtraHostIds?.Contains(hostId) == true
                    || cutter.ExplicitHostIds?.Contains(hostId) == true;
                bool visibleFillingProductIsValidated = doorOrWindow
                    && directHost
                    && HostedFillingProductCanBeEmitted(cutter, elemById, storeyIds, HasProjectPhaseReference(cutter));
                HostedOpeningGeometry writerOpening =
                    usesExactCompleteOpenTenFaceQuarteredReveal
                        ? targetedOpening
                    : usesExactForwardSecondaryFamilyCut
                        ? targetedOpening
                    : builtFamilyCutLoop && visibleFillingProductIsValidated
                        ? targetedOpening : commonOpening;
                HostedOpeningGeometry legacyWriterOpening =
                    usesExactCompleteOpenTenFaceQuarteredReveal
                        ? commonOpening
                    : builtExactSourceWallProfilesMappedBreakpoint
                        ? preSourceSteppedOpening : writerOpening;
                HostedOpeningGeometry legacyEmittedOperand;
                if (usesExactForwardSecondaryFamilyCut)
                {
                    // Its source-owned finite slot is already the fully targeted per-host operand.
                    legacyEmittedOperand = legacyWriterOpening;
                }
                else if (!TryResolveHostedOpeningWriterOperand(
                             cutter, cutter.BoundingBox!, elemById[hostId],
                             elemById, legacyWriterOpening,
                             out legacyEmittedOperand))
                {
                    if (precomputeDiagnostics)
                        DiagnosticSink.WriteLine(
                            $"IFCHOSTPRECOMPUTE cutter={cutter.Id} host={hostId} "
                            + "stage=skip-legacy-writer-resolve");
                    continue;
                }
                HostedOpeningGeometry emittedOperand =
                    usesExactCompleteOpenTenFaceQuarteredReveal
                        ? targetedOpening : legacyEmittedOperand;
                if (builtExactSourceWallProfilesMappedBreakpoint)
                {
                    if (!TryResolveHostedOpeningWriterOperand(
                            cutter, cutter.BoundingBox!, elemById[hostId],
                            elemById, writerOpening,
                            out var exactSourceSteppedEmittedOperand))
                        continue;
                    emittedOperand = exactSourceSteppedEmittedOperand;
                }
                if (!usesExactCompleteOpenTenFaceQuarteredReveal
                    && hasExactSingleLinkedSourceOpening)
                {
                    HostedOpeningGeometry exactEmittedOperand;
                    if (usesExactForwardSecondaryFamilyCut)
                    {
                        exactEmittedOperand = exactSingleLinkedSourceOpening;
                    }
                    else if (!TryResolveHostedOpeningWriterOperand(
                                 cutter, cutter.BoundingBox!, elemById[hostId],
                                 elemById, exactSingleLinkedSourceOpening,
                                 out exactEmittedOperand))
                    {
                        if (precomputeDiagnostics)
                            DiagnosticSink.WriteLine(
                                $"IFCHOSTPRECOMPUTE cutter={cutter.Id} "
                                + $"host={hostId} "
                                + "stage=skip-exact-source-resolve");
                        continue;
                    }
                    if (usesBoundarySlotSourceValidation)
                    {
                        exactBoundarySlotSourceOpenings[(hostId, cutter.Id)] =
                            exactSingleLinkedSourceOpening;
                        if (TryBuildExactBoundarySlotOpeningWriterEnvelope(
                                cutter, elemById[hostId],
                                exactSingleLinkedSourceOpening,
                                out var exactBoundarySlotWriterOpening))
                            exactBoundarySlotWriterOpenings[(hostId, cutter.Id)] =
                                exactBoundarySlotWriterOpening;
                    }
                    else
                    {
                        exactSingleLinkedSourceOpenings[(hostId, cutter.Id)] =
                            exactSingleLinkedSourceOpening;
                        emittedOperand = exactEmittedOperand;
                    }
                }
                if (!usesExactCompleteOpenTenFaceQuarteredReveal
                    && !usesExactForwardSecondaryFamilyCut
                    && (!hasExactSingleLinkedSourceOpening
                        || usesBoundarySlotSourceValidation)
                    && (TryBuildExactSymmetricAdditionalDepthRectangularOpening(
                            cutter, elemById[hostId], candidateHostWalls,
                            legacyEmittedOperand,
                            out var parameterizedLegacyEmittedOperand)
                        || TryBuildExactContractedParameterizedRectangularOpening(
                            cutter, elemById[hostId], candidateHostWalls,
                            legacyEmittedOperand,
                            out parameterizedLegacyEmittedOperand)
                        || TryBuildExactParameterizedRevealOpening(
                            cutter, candidateHostWalls, legacyEmittedOperand,
                            out parameterizedLegacyEmittedOperand)))
                {
                    legacyEmittedOperand = parameterizedLegacyEmittedOperand;
                    if (!builtExactSourceWallProfilesMappedBreakpoint)
                        emittedOperand = parameterizedLegacyEmittedOperand;
                }
                if (exactConcordantFamilyCutBrepSweptOpeningPairs.Contains(
                        (hostId, cutter.Id)))
                    emittedOperand = emittedOperand with
                    {
                        IsExactConcordantFamilyCut = true,
                    };
                if (builtFamilyCutLoop
                    && commonOpening.IsFamilyCutLoop
                    && HasExactThreeOpenTwoProfileSourceAuthority(
                        elemById[hostId].Geometry)
                    && emittedOperand.ExactDepth
                    && emittedOperand.Boundary == null
                    && emittedOperand.SteppedProfile == null
                    && !emittedOperand.IsFamilyCutLoop)
                    exactThreeOpenFamilyCutLoopWriterPairs.Add(
                        (hostId, cutter.Id));
                if (!emittedHostedOpeningOperandsByWall.TryGetValue(
                        hostId, out var operands))
                    emittedHostedOpeningOperandsByWall[hostId] = operands = [];
                operands.Add((cutter.Id, emittedOperand));
                if (!legacyHostedOpeningOperandsByWall.TryGetValue(
                        hostId, out var legacyOperands))
                    legacyHostedOpeningOperandsByWall[hostId] =
                        legacyOperands = [];
                legacyOperands.Add((cutter.Id, legacyEmittedOperand));
                if (precomputeDiagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCHOSTPRECOMPUTE cutter={cutter.Id} host={hostId} "
                        + $"stage=materialized cutters={cutterIds.Count} "
                        + $"operands={operands.Count}");
            }
        }

        foreach (var (pair, operand) in ownPrimaryFamilyWriterOperands.ToArray())
        {
            if (HasCompetingExactHostedWriterAuthority(pair))
            {
                ownPrimaryFamilyWriterOperands.Remove(pair);
                continue;
            }
            if (!emittedHostedCutterIdsByWall.TryGetValue(pair.WallId, out var cutters))
                emittedHostedCutterIdsByWall[pair.WallId] = cutters = [];
            if (!cutters.Contains(pair.CutterId)) cutters.Add(pair.CutterId);
            foreach (var table in new[] { emittedHostedOpeningOperandsByWall, legacyHostedOpeningOperandsByWall })
            {
                if (!table.TryGetValue(pair.WallId, out var operands))
                    table[pair.WallId] = operands = [];
                operands.RemoveAll(item => item.CutterId == pair.CutterId);
                operands.Add((pair.CutterId, operand));
            }
        }

        // This is the hosted-opening writer's materialized occurrence set, not the raw inverse cut
        // graph.
        var materializedHostedOpeningCutterIds = emittedHostedOpeningOperandsByWall
            .SelectMany(entry => entry.Value)
            .Select(entry => entry.CutterId)
            .ToHashSet();

        var spatialTerrainElementIds = spatialTerrainSurfaces
            .Select(surface => surface.Id).ToHashSet();
        var standaloneOpeningIdsByWall = new Dictionary<int, List<int>>();
        var directStandaloneOpeningBoundariesByWall = new Dictionary<int,
            List<(int OpeningId, GeometryData Boundary)>>();
        foreach (var opening in info.Elements.Where(element =>
                     element.Category?.Contains("OST_SWallRectOpening",
                         StringComparison.OrdinalIgnoreCase) == true))
        {
            int hostWallId = opening.References?.FirstOrDefault(
                visibleWallIds.Contains) ?? 0;
            if (hostWallId <= 0) continue;
            if (!standaloneOpeningIdsByWall.TryGetValue(
                    hostWallId, out var openingIds))
                standaloneOpeningIdsByWall[hostWallId] = openingIds = [];
            if (!openingIds.Contains(opening.Id)) openingIds.Add(opening.Id);

            // Mirror the exact product path used below before treating this standalone opening as a
            // future Boolean operand.
            bool transformOnlyFamily = opening.Transform != null && opening.TypeId > 0
                && opening.CategoryId is null or -2000080 or -2001000 or -2001100;
            bool hasProjectPhaseReference = HasProjectPhaseReference(opening);
            bool standaloneDiagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1";
            bool RejectStandaloneWriterPath(string stage)
            {
                if (standaloneDiagnostics)
                    DiagnosticSink.WriteLine($"IFCSTANDALONEWRITERGATE wall={hostWallId} "
                        + $"opening={opening.Id} result=reject stage={stage}");
                return false;
            }
            if (spatialTerrainElementIds.Contains(opening.Id)
                || groupDefinitionTopographyIds.Contains(opening.Id))
            {
                RejectStandaloneWriterPath("spatial-terrain");
                continue;
            }
            if (opening.IsBlockOnly)
            {
                RejectStandaloneWriterPath("block-only");
                continue;
            }
            if (typeElementIds.Contains(opening.Id)
                && !hasProjectPhaseReference && !transformOnlyFamily)
            {
                RejectStandaloneWriterPath("type-definition");
                continue;
            }
            if (IsNonPhysicalCategory(opening.Category))
            {
                RejectStandaloneWriterPath("non-physical");
                continue;
            }
            if (!hasProjectPhaseReference && !transformOnlyFamily)
            {
                RejectStandaloneWriterPath("phase");
                continue;
            }
            if (IntParam(opening, -1013201) != -4)
            {
                RejectStandaloneWriterPath("design-option");
                continue;
            }
            if (opening.References?.Any(referenceId =>
                    elemById.TryGetValue(referenceId, out var referencedWall)
                    && referencedWall.CategoryId == -2000011
                    && !visibleWallIds.Contains(referenceId)) == true)
            {
                RejectStandaloneWriterPath("filtered-wall-reference");
                continue;
            }
            if (opening.TypeId <= 0
                && opening.Geometry == null && opening.Location == null)
            {
                RejectStandaloneWriterPath("undiscovered-without-geometry");
                continue;
            }
            if (opening.Geometry == null && opening.BoundingBox == null
                && opening.Transform == null)
            {
                RejectStandaloneWriterPath("instance-without-geometry");
                continue;
            }
            if (!elementOrderById.TryGetValue(hostWallId, out int hostOrder)
                || !elementOrderById.TryGetValue(opening.Id, out int openingOrder)
                || hostOrder >= openingOrder)
            {
                RejectStandaloneWriterPath("element-order");
                continue;
            }

            var explicitLevelIds = opening.Parameters
                .Where(parameter => parameter.Definition?.Name is
                    "LEVEL_PARAM" or "FAMILY_LEVEL_PARAM" or "SCHEDULE_LEVEL_PARAM"
                    or "INSTANCE_REFERENCE_LEVEL_PARAM")
                .Select(parameter => parameter.Value)
                .OfType<int>()
                .Where(levelId => levelId > 0
                    && elemById.TryGetValue(levelId, out var level)
                    && level.CategoryId == -2000240)
                .Distinct()
                .ToList();
            if (opening.Transform != null && explicitLevelIds.Count > 0
                && explicitLevelIds.All(levelId => !storeyIds.ContainsKey(levelId)))
            {
                RejectStandaloneWriterPath("level");
                continue;
            }

            double[]? openingBounds = opening.BoundingBox
                ?? opening.Geometry?.BoundingBox;
            if (openingBounds == null || InvalidBbox(openingBounds))
            {
                RejectStandaloneWriterPath("bounds");
                continue;
            }
            double openingDx = Math.Abs(openingBounds[3] - openingBounds[0])
                * FeetToMetres;
            double openingDy = Math.Abs(openingBounds[4] - openingBounds[1])
                * FeetToMetres;
            double openingDz = Math.Abs(openingBounds[5] - openingBounds[2])
                * FeetToMetres;
            if (openingDx < 0.01 && openingDy < 0.01 && openingDz < 0.01)
            {
                RejectStandaloneWriterPath("collapsed-bounds");
                continue;
            }
            if (opening.Geometry is not { } openingBoundary
                || openingBoundary.Faces.Count(face =>
                    face.OuterVertices is { Count: >= 3 }) == 0)
            {
                RejectStandaloneWriterPath("rich-faces");
                continue;
            }
            if (openingBoundary.ExactMappedInstances is { Count: > 0 })
            {
                RejectStandaloneWriterPath("mapped-representation");
                continue;
            }

            if (!directStandaloneOpeningBoundariesByWall.TryGetValue(
                    hostWallId, out var directBoundaries))
                directStandaloneOpeningBoundariesByWall[hostWallId] =
                    directBoundaries = [];
            directBoundaries.Add((opening.Id, openingBoundary));
        }

        int exportedCount = 0;
        int skippedCount = 0;
        int withFaces = 0, withBbox = 0, noGeom = 0;

        // Track wall IFC entity IDs and placements for door/window opening creation
        var wallIfcIds = new Dictionary<int, (int entityId, int placementId, int storeyId)>();
        var exportedIfcElements = new Dictionary<int, (int entityId, int placementId, string ifcType)>();
        // GlobalId written for each exported element's product; other entities that name a product
        // by its GlobalId (wall path connections) read it from here.
        var exportedGlobalIds = new Dictionary<int, string>();
        // Storey entity of each exported element's product.
        var exportedStoreyIds = new Dictionary<int, int>();
        // Shared pool of IfcPropertySingleValue instances across every class-specific Pset this
        // exporter emits (Pset_QuantityTakeOff, Pset_BuildingElementProxyCommon, Pset_DoorCommon,
        // Pset_MemberCommon, Pset_PlateCommon, Pset_ColumnCommon, Pset_OpeningElementCommon).
        var propertySingleValueIds = new Dictionary<(string PropertyName, string ValueExpr), int>();
        var slabQuantityTakeOffReferenceValueIds = new Dictionary<int, int>();
        var wallQuantityTakeOffReferenceValueIds = new Dictionary<int, int>();
        var pendingMainLoopWallOpeningPropertySets = new List<(
            Element Opening, int EntityId, int HostWallId)>();
        var pendingMemberPlatePropertySets = new List<(
            Element Element, int EntityId, string IfcType, string? ReferenceValue)>();
        var pendingColumnCommonPropertySets = new List<(
            Element Element, int EntityId, int ReferenceValueId)>();
        var pendingSlabCommonPropertySets = new List<(
            Element Element, int EntityId, int ReferenceValueId)>();
        var pendingOpeningCommonPropertySets = new List<(
            Element Element, int EntityId, string IfcType, int? ReferenceValueId)>();
        if (spatialTopography != null)
            exportedIfcElements[spatialTopography.Id] = (siteId, siteLocalPlacementId, "IFCSITE");
        var hostedElements = new List<(Element elem, int hostWallElemId, double[] bbox, int ifcEntityId)>();
        var emittedStandaloneOpeningVoidPairs =
            new HashSet<(int WallId, int OpeningId)>();
        var verifiedGrossWallCutters = new Dictionary<int, IReadOnlyList<int>>();
        var exactSourceWallOpenings =
            new Dictionary<int, IReadOnlyList<(
                RectangularWallThroughOpening Opening,
                int? SourceOwnerTagId)>>();
        var exactSourceWallOpeningSketchLinesByOwner = elemById.Values
            .Where(element => element.CategoryId == -2000045
                && element.HostId.HasValue)
            .GroupBy(element => element.HostId!.Value)
            .ToDictionary(group => group.Key,
                group => (IReadOnlyList<Element>)group
                    .OrderBy(element => element.Id).ToList());
        var exactSourceWallOpeningSketchOwners = elemById.Values
            .Where(owner => owner.SketchLoops is { Count: > 0 })
            .OrderBy(owner => owner.Id).ToList();
        var exactEditedProfileWallOpenings =
            new Dictionary<int, IReadOnlyList<(
                RectangularWallThroughOpening Opening, int TagId)>>();
        var exactEditedArbitraryProfileWallOpenings =
            new Dictionary<int, (
                ProfileWallThroughOpening Opening, int TagId)>();

        bool HasCompetingExactHostedWriterAuthority(
            (int WallId, int CutterId) pair) =>
            exactCompleteOpenTenFaceQuarteredRevealOpeningPairs.Contains(pair)
            || exactCompleteOpenTenFaceQuarteredRevealWriterOperands
                .ContainsKey(pair)
            || exactCompleteOpenTwentyFiveFaceOpposedSidePocketWriterOperands
                .ContainsKey(pair)
            || exactCompleteOpenTenFaceSideCoincidentBrepSweptOpeningPairs
                .Contains(pair)
            || exactCompleteOpenTenFaceSideCoincidentBrepSweptWriterOperands
                .ContainsKey(pair)
            || exactForwardSecondaryFamilyCutPairs.Contains(pair)
            || exactForwardSecondaryFamilyCutOpenings.ContainsKey(pair)
            || verifiedExactBoundarySlotSourceOpenings.Contains(pair)
            || exactBoundarySlotSourceOpenings.ContainsKey(pair)
            || exactBoundarySlotWriterOpenings.ContainsKey(pair)
            || verifiedExactSingleLinkedSourceOpenings.Contains(pair)
            || exactSingleLinkedSourceOpenings.ContainsKey(pair)
            || exactEmbeddedSingleFamilyCutBrepPairs.Contains(pair)
            || exactThreeOpenFamilyCutLoopWriterPairs.Contains(pair)
            || exactReferenceOnlySixPointJoinBottomSlotFamilyCutPairs
                .Contains(pair)
            || exactCompleteOpenTwelveFaceFullWriterFamilyCutPairs
                .Contains(pair)
            || exactJoinedSpanBrepSweptOpeningPairs.Contains(pair)
            || exactConcordantFamilyCutBrepSweptOpeningPairs.Contains(pair)
            || exactVerticalStepBrepSweptOpeningPairs.Contains(pair)
            || exactJoinedWallEndProfileOpenings.TryGetValue(
                pair.WallId, out var joinedProfile)
                && joinedProfile.TagId == pair.CutterId;

        _wallIndex = info.Elements.Where(e =>
            !e.IsBlockOnly && visibleWallIds.Contains(e.Id) && e.Location is { ArcRadius: null }).ToList();

        // Robust model centre: median of element bbox centres.
        bool InvalidBbox(double[] b)
        {
            if (b.Length < 6) return true;
            for (int bi = 0; bi < 6; bi++)
                if (!double.IsFinite(b[bi])) return true;
            return b[0] > b[3] || b[1] > b[4] || b[2] > b[5];
        }

        void Skip(Element skipped, string why) { skippedCount++; SkipLog?.Add(skipped.Id, RvtIO.SkipLog.ClassOf(skipped), why); }
        var exportClock = System.Diagnostics.Stopwatch.StartNew();
        _diag?.WriteLine("Timing: product loop starts");
        foreach (var elem in info.Elements)
        {
            if (spatialTerrainElementIds.Contains(elem.Id)
                || groupDefinitionTopographyIds.Contains(elem.Id))
            { Skip(elem, "terrain-or-group-topography"); continue; }
            // Orphan blocks commonly contain reusable family/type geometry.
            if (elem.IsBlockOnly) { Skip(elem, "block-only-record"); continue; }
            if (elem.IsGroupTemplate) { Skip(elem, "group-template"); continue; }
            if (CurrentProfile && info.ElemTableIsExact && elem.IsDiscovered) { Skip(elem, "record-outside-exact-element-table"); continue; }
            if (CurrentProfile && elem.SerializedFamilyId is > 0) { Skip(elem, "owned-by-family-nonspatial"); continue; }
            // Reinforcement bars are written whole (placement, swept discs, Pset) and contained by
            // the storey of their lowest point
            if (CurrentProfile && elem.RebarBars != null)
            {
                if (!WriteRebarProduct(w, elem, elemById, ownerHistId, axisId, bldgLocalPlacementId, bodySubCtxId, propertySingleValueIds,
                        int.TryParse(info.Metadata?.RevitVersion, out int revitRelease) && revitRelease >= 2026, storeyIds, defaultStoreyId, storeyContents))
                    Skip(elem, "rebar-product-not-written");
                continue;
            }
            if (CurrentProfile && HasOnlyUnfilledFacesCurrent(elem)) { Skip(elem, "only-unfilled-faces"); continue; }
            bool transformOnlyFamily = elem.Transform != null && elem.TypeId > 0
                && elem.CategoryId is null or -2000080 or -2001000 or -2001100;
            // Wall type propagation is not yet reliable enough to use for suppression:
            // system-family walls may legitimately be referenced by neighbouring walls.
            if (elem.CategoryId != -2000011 && typeElementIds.Contains(elem.Id)
                && !HasProjectPhaseReference(elem) && !transformOnlyFamily)
            { Skip(elem, "type-element"); continue; }

            if (IsNonPhysicalCategory(elem.Category)) { Skip(elem, "non-physical-category"); continue; }

            // Preview/type records inherit PHASE_CREATED during parameter propagation but do not
            // reference that phase in their own record graph.
            if (elem.CategoryId != -2000011
                && !HasProjectPhaseReference(elem) && !transformOnlyFamily)
            { Skip(elem, "no-project-phase-reference"); continue; }

            // A placed family instance must reference a project level when its serialized level
            // parameters point to Level elements.
            var explicitLevelIds = elem.Parameters
                .Where(parameter => parameter.Definition?.Name is
                    "LEVEL_PARAM" or "FAMILY_LEVEL_PARAM" or "SCHEDULE_LEVEL_PARAM"
                    or "INSTANCE_REFERENCE_LEVEL_PARAM")
                .Select(parameter => parameter.Value)
                .OfType<int>()
                .Where(levelId => levelId > 0 && elemById.TryGetValue(levelId, out var level)
                    && level.CategoryId == -2000240)
                .Distinct()
                .ToList();
            if (elem.Transform != null && explicitLevelIds.Count > 0
                && explicitLevelIds.All(levelId => !storeyIds.ContainsKey(levelId)
                    && !IsProjectLevel(elemById[levelId])))
            { Skip(elem, "level-is-not-a-project-level"); continue; }

            if (elem.CategoryId == -2000011 && !visibleWallIds.Contains(elem.Id))
            { Skip(elem, "wall-not-visible"); continue; }
            if (curtainPanelWallIds.Contains(elem.Id))
            { Skip(elem, "curtain-panel-wall"); continue; }

            if (elem.CategoryId is -2000171 or -2000170)
            {
                // The record graph is not a reliable direct parent list: many placed panels and
                // mullions are connected through CurtainGridLine/GridNode records rather than
                // referencing the host wall themselves.
                if (elem.BoundingBox == null && elem.Geometry?.BoundingBox == null && !info.GeometryUndecoded)
                { Skip(elem, "curtain-child-without-bounds"); continue; }
            }

            // An opening connected to a filtered design-option wall is a preview record.
            if (elem.Category?.Contains("OST_SWallRectOpening", StringComparison.OrdinalIgnoreCase) == true
                && (IntParam(elem, -1013201) != -4
                    || elem.References?.Any(r => elemById.TryGetValue(r, out var wall)
                        && wall.CategoryId == -2000011 && !visibleWallIds.Contains(r)) == true))
            { Skip(elem, "opening-of-hidden-wall"); continue; }

            string? ifcType = elem.Category?.Contains("OST_SWallRectOpening", StringComparison.OrdinalIgnoreCase) == true
                ? "IFCOPENINGELEMENT"
                // A serialized CompoundStructure is the defining body of a basic/stacked system
                // wall.
                : elem.CategoryId == -2000011 && curtainWallIds.Contains(elem.Id)
                    && elem.Layers is not { Count: > 0 }
                    ? "IFCCURTAINWALL"
                : elem.CategoryId == -2000011 && ShouldExportAsIfcWall(elem, CurrentProfile)
                    ? "IFCWALL"
                : MapCategoryToIfcType(elem.CategoryId)
                    ?? (elem.CategoryId == null && elem.Transform != null && elem.TypeId > 0
                        ? "IFCBUILDINGELEMENTPROXY"
                        : null);
            if (info.GeometryUndecoded && ifcType == "IFCBEAM" && elem.NativeStructuralType == 2)
                ifcType = "IFCMEMBER";
            // A wall foundation (ContFooting) is an IfcFooting; the other foundations of
            // OST_StructuralFoundation stay slabs.
            if (CurrentProfile && ifcType == "IFCSLAB" && elem.RootClassName == "ContFooting")
                ifcType = "IFCFOOTING";
            if (ifcType == null)
            {
                // Uncategorized elements with substantial REAL geometry (orphan blocks whose
                // records sit in unrecoverable stream members - e.g. heavy slabs with hundreds of
                // decoded faces) still belong in the model as proxies.
                if (elem.Geometry?.Faces?.Count(f => f.OuterVertices is { Count: >= 3 }) >= 4
                    && (!CurrentProfile || elem.TypeId > 0))
                    ifcType = "IFCBUILDINGELEMENTPROXY";
                else { Skip(elem, "no-ifc-class-for-category"); continue; }
            }
            if (CurrentProfile && elem.CategoryId == -2009000 && elem.TypeId > 0
                && ifcType == "IFCBUILDINGELEMENTPROXY")
                ifcType = "IFCREINFORCINGMESH";
            // The current profile writes a wall's openings only
            // beside a wall exported as an extrusion with an axis; the openings of a plain IfcWall
            // are cut into its Brep.
            if (CurrentProfile && ifcType == "IFCOPENINGELEMENT"
                && elem.References?.FirstOrDefault(r => visibleWallIds.Contains(r)) is int openingHostWallId
                && WallWritesNoBodyOpeningsCurrent(exportedIfcElements, openingHostWallId))
            { Skip(elem, "opening-of-wall-without-body-openings"); continue; }
            if (Environment.GetEnvironmentVariable("RVTIO_PROD_DIAG") is { Length: > 0 } prodDiag)
                File.AppendAllText(prodDiag, string.Join(',', elem.Id, ifcType, elem.IsDiscovered ? 1 : 0, elem.TypeId,
                    elem.CategoryId, elem.SerializedCreatedPhaseId, elem.SerializedDemolishedPhaseId, elem.SerializedFamilyId,
                    elem.SerializedUnplacedOwnerId, elem.SerializedOwnerDbViewId, elem.DocumentAccessHandle,
                    elem.Geometry?.Faces?.Count ?? 0, elem.Geometry?.BrepSolids?.Count ?? 0, elem.BoundingBox != null ? 1 : 0,
                    elem.Location != null ? 1 : 0, elem.Geometry?.Instances?.Count ?? 0,
                    elem.Parameters.FirstOrDefault(p => p.Id == -1019012)?.Value?.ToString() ?? "-",
                    (elem.TypeId > 0 && elemById.TryGetValue(elem.TypeId, out var diagType) ? diagType.Parameters.FirstOrDefault(p => p.Id == -1019013)?.Value?.ToString() : null) ?? "-",
                    elem.SerializedRoomId?.ToString(CultureInfo.InvariantCulture) ?? "-",
                    elem.NativeRootClassName ?? "-", elem.NativeStructuralType?.ToString(CultureInfo.InvariantCulture) ?? "-") + "\n");

            if (ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE" or "IFCCURTAINWALL"
                && IsValidatedStackedWallContainer(elem, elemById))
            { Skip(elem, "stacked-wall-container"); continue; }

            if (elem.TypeId <= 0 && elem.Geometry == null && elem.Location == null && !info.GeometryUndecoded)
            { Skip(elem, "no-geometry-or-location"); continue; }

            bool alwaysPass = elem.CategoryId is -2000011 or -2000340
                or -2000171 or -2000170; // walls, generic model, mullions, curtain panels
            if (!alwaysPass)
            {
                // Hosted elements (doors, windows) are instances if they reference a host (wall,
                // floor, roof).
                bool isHostedCategory = elem.CategoryId is -2000023 or -2000014;
                if (isHostedCategory)
                {
                    // Nested door/window components remain real IFC products, but their parent's
                    // top-level instance owns the wall cut.
                    bool hasHost = elem.SuperInstanceId is > 0
                        || ResolveHostedElementHostIds(
                            elem, elemById, visibleWallIds, inverseHostedHostIds).Count > 0;
                    if (!hasHost) { Skip(elem, "hosted-element-without-host"); continue; }
                }
                else
                {
                    // A real instance may have only an instance bbox when its family mesh lives in
                    // another stream member.
                    if (elem.Geometry == null && elem.BoundingBox == null && elem.Transform == null
                        && !roofContainerChildren.ContainsKey(elem.Id) && !info.GeometryUndecoded)
                    { Skip(elem, "no-geometry-or-bounds"); continue; }
                }
            }

            if (phantomStoreyWallIds.Contains(elem.Id))
            {
                _suppressedPhantomStoreyWallProductsByClass.TryGetValue(
                    ifcType, out int phantomStoreyWallSoFar);
                _suppressedPhantomStoreyWallProductsByClass[ifcType] =
                    phantomStoreyWallSoFar + 1;
                Skip(elem, "phantom-storey-wall");
                continue;
            }

            int elemStoreyId = ResolveStorey(elem, storeyIds, defaultStoreyId, elemById);
            if (Environment.GetEnvironmentVariable("RVTIO_STOREY_DIAG") is { Length: > 0 } storeyDiag)
                File.AppendAllText(storeyDiag, string.Join(';', elem.Id, ifcType, elem.CategoryId, elem.SuperInstanceId, elem.NativeMasterSymbolId,
                    (elem.BoundingBox ?? elem.Geometry?.BoundingBox) is { Length: >= 6 } diagBox ? diagBox[2].ToString("R", CultureInfo.InvariantCulture) : "-",
                    storeyIds.FirstOrDefault(pair => pair.Value == elemStoreyId).Key,
                    string.Join(',', elem.Parameters.Where(p => p.StorageType == StorageType.ElementId && p.Value is int)
                        .Select(p => $"{p.Id}:{p.Definition?.Name}={p.Value}"))) + "\n");

            if (ifcType == "IFCCURTAINWALL" && exactCurtainChildren.ContainsKey(elem.Id))
            {
                pendingCurtainParents[elem.Id] = (elem, elemStoreyId, false);
                continue;
            }
            // Element geometry is written in ABSOLUTE model coordinates (bboxes/solids already
            // include the level elevation), so parent placements to the BUILDING, not the storey.
            int elemStoreyPlacementId = bldgLocalPlacementId;

            double[]? bbox = elem.BoundingBox ?? elem.Geometry?.BoundingBox;
            int shapeId = 0;
            int elemPlacementId = 0;
            if (bbox == null || bbox.Length < 6)
            {
                // The geometry of a 64-bit-id file is not decoded: the product is written without a
                // representation.
                if (info.GeometryUndecoded)
                {
                    elemPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(elemStoreyPlacementId)},{R(axisId)}");
                    goto productWithoutGeometry;
                }
                if (ifcType == "IFCCURTAINWALL" && exactCurtainChildren.ContainsKey(elem.Id)
                    || ifcType == "IFCROOF" && roofContainerChildren.ContainsKey(elem.Id))
                    pendingCurtainParents[elem.Id] = (elem, elemStoreyId, false);
                noGeom++;
                continue;
            }
            // Corrupt bbox (mis-decoded doubles): one 1e168 coordinate poisons the whole scene
            // bounding box in three.js-based viewers - skip the element instead.
            if (InvalidBbox(bbox))
            {
                noGeom++;
                continue;
            }
            double dx = Math.Abs(bbox[3] - bbox[0]) * FeetToMetres;
            double dy = Math.Abs(bbox[4] - bbox[1]) * FeetToMetres;
            double dz = Math.Abs(bbox[5] - bbox[2]) * FeetToMetres;
            if (dx < 0.01 && dy < 0.01 && dz < 0.01)
            {
                if (ifcType == "IFCCURTAINWALL" && exactCurtainChildren.ContainsKey(elem.Id))
                    pendingCurtainParents[elem.Id] = (elem, elemStoreyId, false);
                noGeom++;
                continue;
            }

            // This is an authored ownership edge, not a category/name/type/geometry inference.
            if (ShouldSuppressUnplacedOwnerProxyProduct(
                    ifcType, elem.SerializedUnplacedOwnerId)
                || CurrentProfile && elem.SerializedUnplacedOwnerId is > 0)
            {
                // A nested record may still be the exact cutter for a materialized void.
                foreach (var hostEntry in emittedHostedOpeningOperandsByWall
                             .Where(entry => entry.Value.Any(operand =>
                                 operand.CutterId == elem.Id)))
                    if (!hostedElements.Any(item => item.elem.Id == elem.Id
                        && item.hostWallElemId == hostEntry.Key))
                        hostedElements.Add((elem, hostEntry.Key, bbox, 0));

                _suppressedUnplacedOwnerProxyProducts++;
                Skip(elem, "unplaced-owner-proxy");
                continue;
            }

            BodyRepresentationWriteOutcome bodyWriteOutcome = default;
            StepWriter.Checkpoint elementWriterCheckpoint = w.CreateCheckpoint();
            // Set by the one branch below that decides up front it will write no geometry at all.
            bool geometrylessPlacementDeferred = false;

            // Real tessellated BRep (GRepParserV2 world faces): a face carrying explicit
            // OuterVertices is the actual boundary in world coords.
            int decodedRichFaces = elem.Geometry?.Faces?.Count(f => f.OuterVertices is { Count: >= 3 }) ?? 0;
            bool debugGeometry = Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") is { } debugIds
                && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                    .Any(x => int.TryParse(x, out int id) && id == elem.Id);
            if (debugGeometry)
                DiagnosticSink.WriteLine($"IFCGEOM eid={elem.Id} type={ifcType} faces={decodedRichFaces} elemBox=[{string.Join(',', elem.BoundingBox ?? [])}] geoBox=[{string.Join(',', elem.Geometry?.BoundingBox ?? [])}]");
            int richFaces = decodedRichFaces;
            var straightWallBoundary = new GeometryData();
            bool hasStraightWallBoundary = ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE"
                && TryBuildStraightWallBoundary(elem, out straightWallBoundary);
            ProfileWallThroughOpening exactJoinedWallEndProfileOpening = default;
            HostedOpeningGeometry exactJoinedWallEndProfileOperand = default;
            int exactJoinedWallEndProfileCutterId = 0;
            bool hasExactJoinedWallEndProfileCandidate =
                ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary
                && TryBuildExactJoinedWallEndProfileOpening(
                    elem, bbox, straightWallBoundary, elemById,
                    wallPathNeighbourIdsByWall,
                    emittedHostedCutterIdsByWall,
                    emittedHostedOpeningOperandsByWall,
                    standaloneOpeningIdsByWall,
                    out exactJoinedWallEndProfileOpening,
                    out exactJoinedWallEndProfileOperand,
                    out exactJoinedWallEndProfileCutterId);
            if (hasExactJoinedWallEndProfileCandidate)
            {
                if (!emittedHostedCutterIdsByWall.TryGetValue(
                        elem.Id, out var joinedWallCutterIds))
                    emittedHostedCutterIdsByWall[elem.Id] =
                        joinedWallCutterIds = [];
                joinedWallCutterIds.Add(exactJoinedWallEndProfileCutterId);
                if (!emittedHostedOpeningOperandsByWall.TryGetValue(
                        elem.Id, out var joinedWallOperands))
                    emittedHostedOpeningOperandsByWall[elem.Id] =
                        joinedWallOperands = [];
                joinedWallOperands.Add((
                    exactJoinedWallEndProfileCutterId,
                    exactJoinedWallEndProfileOperand));
            }
            bool hasExactEmbeddedSingleFamilyCutBrep =
                elem.CuttingElementIds is { Count: 1 } embeddedCutters
                && exactEmbeddedSingleFamilyCutBrepPairs.Contains(
                    (elem.Id, embeddedCutters[0]));
            bool rectangularWallGateDiagnostics = Environment.GetEnvironmentVariable(
                    "RVTIO_RECT_BREP_GATE_DIAG") == "1";
            if (rectangularWallGateDiagnostics
                && ifcType == "IFCWALLSTANDARDCASE"
                && !hasStraightWallBoundary)
                DiagnosticSink.WriteLine($"IFCRECTWALLGATE wall={elem.Id} "
                    + "cutter=0 result=reject stage=straight-boundary");
            GeometryData? verifiedSweptWallBoundary = hasStraightWallBoundary
                ? straightWallBoundary : null;
            var grossWallBoundary = new GeometryData();
            IReadOnlyList<int> verifiedCutterIds = [];
            bool hasVerifiedHostedOpening = ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary
                && TryGetVerifiedGrossWallBoundaryAndCutters(
                    elem, bbox, straightWallBoundary, elemById,
                    visibleWallIds, inverseHostedHostIds,
                    hostedDoorWindowCutterIdsByWall,
                    emittedHostedCutterIdsByWall,
                    emittedHostedOpeningOperandsByWall,
                    standaloneOpeningIdsByWall,
                    out grossWallBoundary, out verifiedCutterIds);
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
                hasVerifiedHostedOpening =
                    TryGetVerifiedGrossStraightWallBoundaryWhenCompleteHostedCuttersCoverSourceHoles(
                        elem, bbox, straightWallBoundary,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
                hasVerifiedHostedOpening =
                    TryGetVerifiedGrossWallBoundaryFromExactProfileExtrusionAndSingleComplexWriterOperand(
                        elem, bbox, straightWallBoundary,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
            bool hasVerifiedTwelveFaceBoundarySlotWriterOpening = false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedHostedOpening =
                    TryGetVerifiedGrossWallBoundaryFromSingleBoundarySlotAndExactWriterOperand(
                        elem, bbox, straightWallBoundary,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedTwelveFaceBoundarySlotWriterOpening =
                    hasVerifiedHostedOpening
                    && straightWallBoundary.Faces is { Count: 12 };
            }
            bool hasVerifiedBoundaryOwnedRedundantCapCoincidentOpening = false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedBoundaryOwnedRedundantCapCoincidentOpening =
                    TryGetVerifiedBoundaryOwnedRedundantWallFromSingleExactCapCoincidentWriterOperand(
                        elem, bbox, straightWallBoundary,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedBoundaryOwnedRedundantCapCoincidentOpening;
            }
            bool hasVerifiedBoundaryOwnedCompleteOpenTwentyEightFaceOpening =
                false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedBoundaryOwnedCompleteOpenTwentyEightFaceOpening =
                    TryGetVerifiedBoundaryOwnedRedundantWallFromExactCompleteOpenTwentyEightFaceSourceAndSingleDirectHostOpening(
                        elem, bbox, straightWallBoundary, elemById,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        exactConcordantFamilyCutBrepSweptOpeningPairs,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedBoundaryOwnedCompleteOpenTwentyEightFaceOpening;
            }
            bool hasVerifiedCompleteOpenSixFaceDualAlternativeFullHeightOpening =
                false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenSixFaceDualAlternativeFullHeightOpening =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixFaceDualAlternativeFullHeightFamilyOpening(
                        elem, bbox, straightWallBoundary, elemById,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        exactConcordantFamilyCutBrepSweptOpeningPairs,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenSixFaceDualAlternativeFullHeightOpening;
            }
            bool hasVerifiedCompleteOpenFifteenFaceEmbeddedPeerTopSlotOpening =
                false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenFifteenFaceEmbeddedPeerTopSlotOpening =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenFifteenFaceEmbeddedPeerTopSlotOpening(
                        elem, bbox, straightWallBoundary, elemById,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        exactForwardSecondaryFamilyCutPairs,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenFifteenFaceEmbeddedPeerTopSlotOpening;
            }
            bool hasVerifiedCompleteOpenTenFaceSecondaryFullHeightOpening =
                false;
            bool hasVerifiedCompleteOpenFifteenFaceContainedRedundantOpenings =
                false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenFifteenFaceContainedRedundantOpenings =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenFifteenFaceContainedRedundantOpenings(
                        elem, bbox, straightWallBoundary, elemById,
                        inverseHostedHostIds,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenFifteenFaceContainedRedundantOpenings;
            }
            bool
                hasVerifiedCompleteOpenThirteenFaceDualAlternativeBottomCoincidentOpening =
                    false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenThirteenFaceDualAlternativeBottomCoincidentOpening =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenThirteenFaceDualAlternativeBottomCoincidentFamilyOpening(
                        elem, bbox, straightWallBoundary, elemById,
                        visibleWallIds, inverseHostedHostIds,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        exactConcordantFamilyCutBrepSweptOpeningPairs,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenThirteenFaceDualAlternativeBottomCoincidentOpening;
            }
            bool
                hasVerifiedCompleteOpenTwelveFaceDetachedAlternativeFullHeightOpening =
                    false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenTwelveFaceDetachedAlternativeFullHeightOpening =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenTwelveFaceDetachedAlternativeFullHeightFamilyCutOpening(
                        elem, bbox, straightWallBoundary, elemById,
                        visibleWallIds, inverseHostedHostIds,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        exactCompleteOpenTwelveFaceFullWriterFamilyCutPairs,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenTwelveFaceDetachedAlternativeFullHeightOpening;
            }
            bool
                hasVerifiedCompleteOpenEighteenFaceSteppedJoinParameterizedRevealAndDisjointOpening =
                    false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenEighteenFaceSteppedJoinParameterizedRevealAndDisjointOpening =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenEighteenFaceSteppedJoinParameterizedRevealAndDisjointOpening(
                        elem, bbox, straightWallBoundary, elemById,
                        inverseHostedHostIds,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenEighteenFaceSteppedJoinParameterizedRevealAndDisjointOpening;
            }
            bool
                hasVerifiedCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters =
                    false;
            IReadOnlyList<(int WallId, int CutterId,
                HostedOpeningGeometry Operand)>
                pendingExactCompleteOpenSixteenFaceSplitRevealWriterOperands = [];
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters(
                        elem, bbox, straightWallBoundary, elemById,
                        visibleWallIds, inverseHostedHostIds,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds,
                        out pendingExactCompleteOpenSixteenFaceSplitRevealWriterOperands);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters;
            }
            bool
                hasVerifiedCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings =
                    false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings =
                    TryGetVerifiedGrossWallBoundaryFromCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings(
                        elem, bbox, straightWallBoundary, elemById,
                        visibleWallIds, inverseHostedHostIds,
                        emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening =
                    hasVerifiedCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings;
            }
            bool hasVerifiedFourteenFaceDualAlternativeInsetCaps = false;
            bool hasVerifiedTwentyNineFaceInsetCapsAndSideSheets = false;
            bool hasVerifiedPerpendicularJoinNotchAndDoor = false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedPerpendicularJoinNotchAndDoor =
                    TryGetVerifiedGrossWallBoundaryFromPerpendicularJoinNotchAndDoor(
                        elem, bbox, straightWallBoundary, elemById,
                        emittedHostedCutterIdsByWall, emittedHostedOpeningOperandsByWall,
                        standaloneOpeningIdsByWall, out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening = hasVerifiedPerpendicularJoinNotchAndDoor;
            }
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedTwentyNineFaceInsetCapsAndSideSheets =
                    TryGetVerifiedGrossWallBoundaryFromTwentyNineFaceInsetCapsAndSideSheets(
                        elem, bbox, straightWallBoundary, elemById,
                        inverseHostedHostIds, emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall, standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening = hasVerifiedTwentyNineFaceInsetCapsAndSideSheets;
            }
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
                && hasStraightWallBoundary)
            {
                hasVerifiedFourteenFaceDualAlternativeInsetCaps =
                    TryGetVerifiedGrossWallBoundaryFromFourteenFaceDualAlternativeInsetCaps(
                        elem, bbox, straightWallBoundary, elemById,
                        inverseHostedHostIds, emittedHostedCutterIdsByWall,
                        emittedHostedOpeningOperandsByWall, standaloneOpeningIdsByWall,
                        out grossWallBoundary, out verifiedCutterIds);
                hasVerifiedHostedOpening = hasVerifiedFourteenFaceDualAlternativeInsetCaps;
            }
            bool
                hasVerifiedCompleteOpenElevenFaceAlternativeFullHeightSplitterAndDisjointOpening =
                    false;
            if (!hasVerifiedHostedOpening
                && ifcType == "IFCWALLSTANDARDCASE"
