                            ? verifiedSweptWallBoundary
                        : hasExactSubdividedVerticalProfileEdgeBoundary
                        && useBoundaryOwnedVerticalDefinition
                            ? verifiedSweptWallBoundary
                        : useVerifiedOpenSteppedMinimumCapShell
