                if (ifcType is "IFCSLAB" or "IFCCOVERING" || elem.CategoryId is -2000032 or -2000035 or -2000038)
                    AttachSketchHoles(elem);
                // Hosted doors/windows: the family mesh includes plan-swing symbol faces (flat
                // sectors at sill/head level sweeping out by the leaf width).
                if (false && ifcType is "IFCDOOR" or "IFCWINDOW")
                {
                    Element? clipHost = elem.References?
                        .Where(visibleWallIds.Contains)
                        .Select(id => elemById.TryGetValue(id, out var h) ? h : null)
                        .FirstOrDefault(h => h?.CategoryId == -2000011);
                    var clipped = ClipHostedToWallSlab(elem, geoForBrep, elemById, bbox, clipHost);
                    if (clipped != null) geoForBrep = clipped;
                }
                if (ifcType == "IFCOPENINGELEMENT" && elem.CategoryId == -2000997
                    && elem.SerializedHostId is > 0 && visibleWallIds.Contains(elem.SerializedHostId.Value)
                    && elem.References?.FirstOrDefault(visibleWallIds.Contains) == elem.SerializedHostId.Value
                    && elemById.TryGetValue(elem.SerializedHostId.Value, out var openingBodyHost)
                    && TryCreateRectangularOpeningBodyCurrent(w, geoForBrep, openingBodyHost.Location,
                        bodySubCtxId, out shapeId, out bodyWriteOutcome))
                {
                    // The standalone wall opening's own solid takes the same custom axis as hosted
                    // cuts.
                }
                else if (OthersCurrentDirectBodyApplies(ifcType, elem)
                    && TryCreateOthersCurrentProductSweptSolid(
                        w, geoForBrep, bodySubCtxId, OthersCurrentAxesZ,
                        OthersCurrentProfileName(ResolveProductFamilyAndTypeName(
                            elem, ifcType, elemById, elementIdOccurrenceCounts, CurrentProfile)),
                        out shapeId, out bodyWriteOutcome))
                {
                    // The current profile writes the body of a slab, covering or roof slab whose
                    // solids are vertical extrusions as SweptSolid.
                }
                else if (CurrentProfile && ifcType == "IFCBEAM" && OthersCurrentSymbolAxes(elem, ifcType) is { } beamAxes
                    && TryCreateOthersCurrentProductSweptSolid(
                        w, geoForBrep, bodySubCtxId, beamAxes,
                        OthersCurrentProfileName(ResolveProductFamilyAndTypeName(
                            elem, ifcType, elemById, elementIdOccurrenceCounts, CurrentProfile)),
                        out shapeId, out bodyWriteOutcome))
                {
                    // A beam is extruded along the axes of the family-instance export: its structural
                    // axis, then x and y.
                }
                else
                {
                    var facetedShape = CreateFacetedBrepWithOutcome(
                        w, geoForBrep, bodySubCtxId);
                    shapeId = facetedShape.ShapeId;
                    bodyWriteOutcome = facetedShape.Outcome;
                }
                elemPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(elemStoreyPlacementId)},{R(axisId)}");
                withFaces++;
            }
            else if (ifcType is "IFCWALLSTANDARDCASE" or "IFCWALL")
            {
                // Walls: SweptSolid with profile from bottom face or GeoSolid
                (shapeId, elemPlacementId) = CreateWallSweptSolid(
                    w, elem, bbox, bodySubCtxId, axisSubCtxId, elemStoreyPlacementId);
                withFaces++;
            }
            else if (ifcType is "IFCDOOR" or "IFCWINDOW")
            {
                // Doors/windows: the raw instance bbox includes the door SWING (open leaf + arc),
                // so its plan footprint is ~door-width squared instead of the real opening.
                shapeId = 0;
                elemPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(elemStoreyPlacementId)},{R(axisId)}");
                noGeom++;
            }
            else
            {
                // Other elements: try FacetedBrep from own face geometry, else bbox SweptSolid
                GeometryData? faceGeom = elem.Geometry;
                if (faceGeom?.Faces != null && faceGeom.Faces.Count >= 4)
                {
                    var facetedShape = CreateFacetedBrepWithOutcome(
                        w, faceGeom, bodySubCtxId);
                    shapeId = facetedShape.ShapeId;
                    bodyWriteOutcome = facetedShape.Outcome;
                    elemPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(elemStoreyPlacementId)},{R(axisId)}");
                    withFaces++;
                }
                else
                {
                    shapeId = 0;
                    elemPlacementId = 0;
                    geometrylessPlacementDeferred = true;
                    noGeom++;
                }
            }

            // A hosted insert with no authored visible body is a pure wall cut.
            if (ifcType is "IFCDOOR" or "IFCWINDOW" && shapeId <= 0)
            {
                foreach (int hostId in ResolveHostedElementHostIds(
                             elem, elemById, visibleWallIds, inverseHostedHostIds)
                         .Where(id => elemById[id].CategoryId == -2000011))
                    hostedElements.Add((elem, hostId, bbox, 0));
                exportedCount++;
                continue;
            }

            // A raw HostId/cutter edge is insufficient (closed proxy cutters remain products), and
            // an open shell alone is insufficient (such proxies are retained).
            if (ShouldSuppressOpenSurfaceHostedCutterProxyProduct(
                    ifcType, bodyWriteOutcome,
                    materializedHostedOpeningCutterIds.Contains(elem.Id)))
            {
                // The decision deliberately consumes the writer's result.
                w.Rollback(elementWriterCheckpoint);
                foreach (int symbolId in representationMapsBySymbol
                             .Where(entry => entry.Value.MapIds.Any(mapId =>
                                 mapId >= elementWriterCheckpoint.NextId))
                             .Select(entry => entry.Key).ToList())
                    representationMapsBySymbol.Remove(symbolId);

                // Preserve every opening the exact precompute materialized. hostedIfcId=0 means
                // CreateHostedOpeningAbsolute writes the void without a filling relationship or an
                // exported product dependency.
                foreach (var hostEntry in emittedHostedOpeningOperandsByWall
                             .Where(entry => entry.Value.Any(operand =>
                                 operand.CutterId == elem.Id)))
                    if (!hostedElements.Any(item => item.elem.Id == elem.Id
                        && item.hostWallElemId == hostEntry.Key))
                        hostedElements.Add((elem, hostEntry.Key, bbox, 0));

                // The surviving-product branch below also registers every exact authored
                // forward+inverse host pair before the final opening writer performs its per-host
                // targeting.
                if ((elem.SerializedHostId.HasValue || elem.HostId.HasValue)
                    && inverseHostedHostIds.TryGetValue(
                        elem.Id, out var suppressedInverseCutHosts))
                {
                    foreach (int hostId in ResolveHostedElementHostIds(
                                 elem, elemById, visibleWallIds,
                                 inverseHostedHostIds)
                             .Where(id => suppressedInverseCutHosts.Contains(id)
                                 && !emittedStandaloneOpeningVoidPairs.Contains(
                                     (id, elem.Id))
                                 && elemById[id].CategoryId == -2000011
                                 && HostedElementCanCutHost(
                                     bbox, elemById[id])))
                        if (!hostedElements.Any(item => item.elem.Id == elem.Id
                            && item.hostWallElemId == hostId))
                            hostedElements.Add((elem, hostId, bbox, 0));
                }

                _suppressedOpenSurfaceHostedCutterProxyProducts++;
                withFaces--;
                Skip(elem, "open-surface-hosted-cutter-proxy");
                continue;
            }

            // Suppress it whole: no product, no IfcRelContainedInSpatialStructure (storeyList
            // below), no Pset_QuantityTakeOff, no entry in exportedIfcElements.
            if (ShouldSuppressGeometrylessElementProduct(
                    ifcType,
                    hasEmittedRepresentation: shapeId > 0,
                    isEmittedAggregateParent: _emittedAggregateParentElementIds.Contains(elem.Id)))
            {
                if (ifcType == "IFCCURTAINWALL" && exactCurtainChildren.ContainsKey(elem.Id))
                    pendingCurtainParents[elem.Id] = (elem, elemStoreyId, true);
                // A suppressed product may still be the authored cutter of a wall void.
                if ((elem.SerializedHostId.HasValue || elem.HostId.HasValue)
                    && inverseHostedHostIds.TryGetValue(elem.Id, out var suppressedCutHosts))
                {
                    foreach (int hostId in ResolveHostedElementHostIds(
                                 elem, elemById, visibleWallIds, inverseHostedHostIds)
                             .Where(id => suppressedCutHosts.Contains(id)
                                 && elemById[id].CategoryId == -2000011
                                 && HostedElementCanCutHost(bbox, elemById[id])))
                        hostedElements.Add((elem, hostId, bbox, 0));
                }
                _suppressedGeometrylessProductsByClass.TryGetValue(ifcType, out int suppressedSoFar);
                _suppressedGeometrylessProductsByClass[ifcType] = suppressedSoFar + 1;
                Skip(elem, "geometryless-product");
                continue;
            }

            if (geometrylessPlacementDeferred)
                elemPlacementId = w.Add("IFCLOCALPLACEMENT", $"{R(elemStoreyPlacementId)},{R(axisId)}");

        productWithoutGeometry:
            // Element name: "FamilyName:TypeName:ElementId" format (matching Revit IFC export)
            string elemTypeName = ResolveProductFamilyAndTypeName(
                elem, ifcType, elemById, elementIdOccurrenceCounts, CurrentProfile);
            string elemName = $"{elemTypeName}:{elem.Id}";
            if (ifcType == "IFCSTAIR")
                elemName = ResolveNativeStairName(elem, elemById, elementIdOccurrenceCounts, CurrentProfile) ?? elemName;
            string? referenceValue = ResolveIfcReferenceValue(
                elem, elemById, (CurrentProfile ? ResolveMepCurveTypeName(elem, elemById) : null) ?? elem.Name);
            if (ifcType == "IFCCURTAINWALL")
                referenceValue = ResolveCurtainWallReference(
                    elem, elemById.GetValueOrDefault(elem.FamilyTypeId), referenceValue);
            // Cheap, duplicate re-check of the same explicit-parameter precedence
            // ResolveIfcReferenceValue already applied internally.
            Element? referenceElementType = elem.FamilyTypeId > 0
                && elemById.TryGetValue(elem.FamilyTypeId, out Element? resolvedReferenceType)
                    ? resolvedReferenceType
                    : null;
            bool referenceValueIsExplicit = ExactIfcStringParameterResolver
                .ResolveReference(elem, referenceElementType).State
                == ExactIfcStringParameterState.Value;
            bool roofWithSlab = CurrentProfile && ifcType == "IFCROOF" && shapeId > 0 && RoofIsExportedWithSlabCurrent(elem);
            string shapeArg = shapeId > 0 && !roofWithSlab ? R(shapeId) : "$";
            string productGlobalId = (ExportIdProductClasses.Contains(ifcType)
                    ? ResolveExactElementGlobalId(elem, _usedExportIds, handleBased: CurrentProfile)
                    : null)
                ?? IfcGuid.FromElementId(elem.Id);
            string elemArgs = ifcType switch
            {
                "IFCWALLSTANDARDCASE" or "IFCWALL" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())}",
                "IFCSLAB" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},.{CurrentSlabPredefinedType(elem, referenceElementType, CurrentProfile, ResolveSlabOccurrencePredefinedType(elem, referenceElementType, elementIdOccurrenceCounts))}.",
                "IFCROOF" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},.NOTDEFINED.",
                "IFCFOOTING" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},.STRIP_FOOTING.",
                "IFCSITE" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},$,.ELEMENT.,$,$,$,$,$",
                "IFCDOOR" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},{D(GetDoorWindowHeight(elem, referenceElementType))},{D(GetDoorWindowWidth(elem, referenceElementType))}",
                "IFCWINDOW" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},{D(GetDoorWindowHeight(elem, referenceElementType))},{D(GetDoorWindowWidth(elem, referenceElementType))}",
                "IFCBUILDINGELEMENTPROXY" =>
                    // It is not the spatial ELEMENT default.
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},$",
                "IFCREINFORCINGMESH" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},$,$,$,$,$,$,$,$,$",
                "IFCCOVERING" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},.{ResolveCoveringOccurrencePredefinedType(elem, referenceElementType, elementIdOccurrenceCounts)}.",
                "IFCRAILING" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},{(CurrentProfile && elem.NativeMasterSymbolId is not > 0 ? "$" : ".NOTDEFINED.")}",
                "IFCSTAIR" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},.{ResolveNativeStairShape(elem, referenceElementType, elemById, elementIdOccurrenceCounts)}.",
                "IFCRAMP" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},.NOTDEFINED.",
                "IFCSTAIRFLIGHT" =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())},{(CurrentProfile ? StairFlightAttributes(elem, elemById) : "$,$,$,$")}",
                "IFCCOLUMN" or "IFCBEAM" or "IFCMEMBER" or "IFCPLATE"
                    or "IFCRAMPFLIGHT"
                    or "IFCCURTAINWALL" or "IFCFURNISHINGELEMENT" or "IFCFLOWSEGMENT"
                    or "IFCFLOWTERMINAL" or "IFCFLOWFITTING" or "IFCFLOWCONTROLLER"
                    or "IFCDISTRIBUTIONFLOWELEMENT"
                    =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())}",
                _ =>
                    $"{S(productGlobalId)},{R(ownerHistId)},{S(elemName)},$,{S(elemTypeName)},{R(elemPlacementId)},{shapeArg},{S(elem.Id.ToString())}",
            };

            int elemEntityId = w.Add(ifcType, elemArgs);
            exportedIfcElements[elem.Id] = (elemEntityId, elemPlacementId, ifcType);
            exportedGlobalIds[elem.Id] = productGlobalId;
            int roofSlabEntityId = roofWithSlab
                ? roofSlabParts[elem.Id] = WriteRoofSlabCurrent(w, ownerHistId, elem, elemEntityId, elemName, elemTypeName,
                    elemStoreyPlacementId, axisId, shapeId)
                : 0;
            Element? mainLoopWallOpeningPropertySetHost =
                ResolveMainLoopWallOpeningPropertySetHost(
                    ifcType, elem, elemById, elementIdOccurrenceCounts);

            // A simple footprint roof is an IfcRoof container whose body is carried by an
            // aggregated IfcSlab/ROOF child in Revit's native export.
            if (!storeyContents.TryGetValue(elemStoreyId, out var storeyList))
                storeyContents[elemStoreyId] = storeyList = new List<int>();
            storeyList.Add(elemEntityId);
            exportedStoreyIds[elem.Id] = elemStoreyId;

            // Track wall entities for hosted element openings
            if (ifcType is "IFCWALLSTANDARDCASE" or "IFCWALL")
            {
                wallIfcIds[elem.Id] = (elemEntityId, elemPlacementId, elemStoreyId);
            }

            if (ifcType == "IFCOPENINGELEMENT")
            {
                int hostWallId = elem.References?.FirstOrDefault(r => visibleWallIds.Contains(r)) ?? 0;
                if (hostWallId > 0 && wallIfcIds.TryGetValue(hostWallId, out var openingWall))
                {
                    w.Add("IFCRELVOIDSELEMENT",
                        $"{S(IfcGuid.FromName($"standalone-void:{elem.Id}"))},{R(ownerHistId)},$,$,{R(openingWall.entityId)},{R(elemEntityId)}");
                    emittedStandaloneOpeningVoidPairs.Add((hostWallId, elem.Id));
                }
            }

            if (ifcType is "IFCDOOR" or "IFCWINDOW")
            {
                if (bbox is { } fillBbox)
                    foreach (int hostId in ResolveHostedElementHostIds(
                                 elem, elemById, visibleWallIds, inverseHostedHostIds)
                             .Where(id => elemById[id].CategoryId == -2000011
                                 && HostedElementCanCutHost(fillBbox, elemById[id])))
                        hostedElements.Add((elem, hostId, fillBbox, elemEntityId));
            }
            else if (bbox is { } cutterBbox
                && (elem.SerializedHostId.HasValue || elem.HostId.HasValue)
                && inverseHostedHostIds.TryGetValue(elem.Id, out var inverseCutHosts))
            {
                // Revit records a wall void as an inverse wall -> insert dependency even when the
                // cutter is a Generic Model rather than a Door/Window.
                foreach (int hostId in ResolveHostedElementHostIds(
                             elem, elemById, visibleWallIds, inverseHostedHostIds)
                         .Where(id => inverseCutHosts.Contains(id)
                             && !emittedStandaloneOpeningVoidPairs.Contains(
                                 (id, elem.Id))
                             && elemById[id].CategoryId == -2000011
                             && HostedElementCanCutHost(cutterBbox, elemById[id])))
                    hostedElements.Add((elem, hostId, cutterBbox, elemEntityId));
            }

            if (ExportsIfcTagAttribute(ifcType)
                && mainLoopWallOpeningPropertySetHost == null)
            {
                string? quantityTakeOffReferenceValue = ResolveQuantityTakeOffReferenceValue(
                    elem, ifcType, referenceValue, CurrentProfile);
                if (CurrentProfile && (quantityTakeOffReferenceValue != null
                        || ifcType == "IFCBEAM" && !elemTypeName.EndsWith($":Element {elem.Id}", StringComparison.Ordinal))
                    && ResolveTypeNameReferenceCurrent(elem, ifcType, elemTypeName, referenceElementType) is { } typeNameReference)
                    quantityTakeOffReferenceValue = typeNameReference;
                if (!referenceValueIsExplicit
                    && !(ifcType == "IFCCURTAINWALL"
                        && ResolveCurtainWallReference(elem, referenceElementType, null) != null)
                    && quantityTakeOffReferenceValue == referenceValue)
                    quantityTakeOffReferenceValue = SuppressLevelNameContamination(
                        quantityTakeOffReferenceValue, levelNames);
                int? quantityTakeOffReferenceValueId = ExportQuantityTakeOffPropertySet(
                    w, elem, elemEntityId, ownerHistId,
                    quantityTakeOffReferenceValue, propertySingleValueIds, roofSlabEntityId);
                // The slab of a roof has the common set of a slab (a roof is always external) and
                // the pitch set.
                if (roofSlabEntityId > 0 && quantityTakeOffReferenceValueId.HasValue
                    && quantityTakeOffReferenceValue is not null)
                {
                    ExportSlabCommonPropertySet(
                        w, elem, roofSlabEntityId, ownerHistId, quantityTakeOffReferenceValueId.Value,
                        isExternal: true, horizontal: false, propertySingleValueIds);
                    ExportReinforcementBarPitchOfSlabPropertySet(
                        w, elem, roofSlabEntityId, ownerHistId, quantityTakeOffReferenceValue);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCSLAB")
                {
                    slabQuantityTakeOffReferenceValueIds[elem.Id] =
                        quantityTakeOffReferenceValueId.Value;
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE")
                {
                    wallQuantityTakeOffReferenceValueIds[elem.Id] =
                        quantityTakeOffReferenceValueId.Value;
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE")
                {
                    ExportWallCommonPropertySet(
                        w, elem, elemById.GetValueOrDefault(elem.FamilyTypeId), elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValueId.Value,
                        propertySingleValueIds, CurrentProfile,
                        CurrentProfile ? ResolveOccurrenceThermalTransmittanceCurrent(elem, elemById) : null);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCSLAB")
                {
                    pendingSlabCommonPropertySets.Add(
                        (elem, elemEntityId, quantityTakeOffReferenceValueId.Value));
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && quantityTakeOffReferenceValue is not null
                    && ifcType == "IFCSLAB")
                {
                    ExportReinforcementBarPitchOfSlabPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValue);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCROOF")
                {
                    ExportRoofCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        propertySingleValueIds,
                        elem.CategoryId == RoofCategoryId && elem.ValidatedRoofOrRailingTypeReferenceName != null
                            && !elem.ValidatedRoofOrRailingTypeReferenceIsBlocked ? quantityTakeOffReferenceValueId : null,
                        CurrentProfile);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && quantityTakeOffReferenceValue is not null
                    && ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE")
                {
                    ExportReinforcementBarPitchOfWallPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValue);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ReceivesBuildingElementProxyCommonPropertySet(
                        ifcType, elem, elemById))
                {
                    ExportBuildingElementProxyCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValueId.Value);
                }
                // The current profile has no such description (its sources never create
                // Pset_ProvisionForVoid).
                if (ifcType == "IFCBUILDINGELEMENTPROXY" && !CurrentProfile
                    && ResolveProvisionForVoidDimensions(elem, elemById) is { } provisionForVoid)
                {
                    ExportProvisionForVoidPropertySet(
                        w, elem, elemEntityId, ownerHistId, propertySingleValueIds, provisionForVoid);
                }
                if (ifcType is "IFCDOOR" or "IFCWINDOW")
                {
                    pendingOpeningCommonPropertySets.Add(
                        (elem, elemEntityId, ifcType, quantityTakeOffReferenceValueId));
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCCOVERING")
                {
                    ExportCoveringCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValueId.Value,
                        ResolveCeilingFinish(elem, elemById, elementIdOccurrenceCounts, CurrentProfile),
                        CurrentProfile ? ResolveCoveringTotalThicknessMillimetresCurrent(elem, referenceElementType) : null);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCRAILING")
                {
                    ExportRailingCommonHeightPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        elem.CategoryId == -2000126 && elem.ValidatedRoofOrRailingTypeReferenceName != null
                            && !elem.ValidatedRoofOrRailingTypeReferenceIsBlocked ? quantityTakeOffReferenceValueId : null,
                        ResolveRailingIsExternal(elem, elemById, elementIdOccurrenceCounts),
                        propertySingleValueIds, CurrentProfile);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType is "IFCSTAIR" or "IFCSTAIRFLIGHT")
                {
                    ExportStairOccurrenceCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId, ifcType,
                        quantityTakeOffReferenceValueId.Value,
                        elemById, elementIdOccurrenceCounts,
                        propertySingleValueIds, CurrentProfile);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCBEAM")
                {
                    ExportBeamCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValueId.Value,
                        propertySingleValueIds,
                        CurrentProfile ? OccurrenceIsExternalCurrent(elem, elemById) ?? false : null,
                        CurrentProfile ? ResolveBeamSpanMillimetresCurrent(elem, elemById.GetValueOrDefault(elem.FamilyTypeId)) : null);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && quantityTakeOffReferenceValue is not null
                    && ifcType == "IFCBEAM")
                {
                    ExportReinforcementBarPitchOfBeamPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValue);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && (ReceivesDistributionFlowElementCommonPropertySet(ifcType, CurrentProfile)
                        || CurrentProfile && ReceivesDistributionFlowElementCommonPropertySetCurrent(ifcType)))
                {
                    ExportDistributionFlowElementCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValueId.Value);
                }
                if (quantityTakeOffReferenceValueId.HasValue
                    && ifcType == "IFCCOLUMN")
                {
                    pendingColumnCommonPropertySets.Add(
                        (elem, elemEntityId,
                            quantityTakeOffReferenceValueId.Value));
                }
                // The column pitch description of the current profile is a copy of the beam one
                // (named after the beam, applying to IfcBeam), so a column receives no such set
                // there.
                if (quantityTakeOffReferenceValueId.HasValue
                    && quantityTakeOffReferenceValue is not null
                    && ifcType == "IFCCOLUMN" && !CurrentProfile)
                {
                    ExportReinforcementBarPitchOfColumnPropertySet(
                        w, elem, elemEntityId, ownerHistId,
                        quantityTakeOffReferenceValue);
                }
            }

            if (CurrentProfile && ExportsIfcTagAttribute(ifcType) && mainLoopWallOpeningPropertySetHost == null)
                ExportInstancePropertySetsCurrent(w, elem, referenceElementType, ifcType, elemEntityId,
                    ownerHistId, propertySingleValueIds,
                    ifcType == "IFCFLOWSEGMENT" ? MepCurveType(elem, elemById) : null);

            if (ifcType == "IFCCURTAINWALL")
                ExportCurtainWallCommonPropertySet(w, elem,
                    elemById.GetValueOrDefault(elem.FamilyTypeId), elemEntityId,
                    ownerHistId, propertySingleValueIds);

            // Class-specific - attach only to the exact IFC class each Pset names, never to both,
            // so a member never picks up the plate set or vice versa (over-attachment would corrupt
            // the model even though the auditor cannot see it directly yet).
            if (ifcType == "IFCMEMBER")
            {
                pendingMemberPlatePropertySets.Add(
                    (elem, elemEntityId, ifcType, referenceValue));
            }
            else if (ifcType == "IFCPLATE")
            {
                pendingMemberPlatePropertySets.Add(
                    (elem, elemEntityId, ifcType, referenceValue));
            }
            else if (ifcType == "IFCOPENINGELEMENT")
            {
                if (mainLoopWallOpeningPropertySetHost != null)
                {
                    // The exact host QTO value may be written before or after this ordinary
                    // product.
                    pendingMainLoopWallOpeningPropertySets.Add((
                        elem, elemEntityId,
                        mainLoopWallOpeningPropertySetHost.Id));
                }
                else
                {
                    // Synthetic wall/slab cuts never enter this branch; they go through
                    // CreateOpeningElement.
                    ExportOpeningElementCommonPropertySet(
                        w, elem, elemEntityId, ownerHistId, referenceValue,
                        propertySingleValueIds);
                }
            }

            // Raw Revit parameters are intentionally opt-in.
            if (_includeRevitPropertySets && elem.Parameters.Count > 0)
            {
                ExportPropertySets(w, elem, elemEntityId, ownerHistId, elemById);
            }

            exportedCount++;
        }

        StairAggregation.Apply(w, info.Elements, exportedIfcElements, storeyContents, ownerHistId, CurrentProfile);
        var stairBodyParts = CurrentProfile
            ? StairAggregation.SplitLegacyBodies(w, info.Elements, exportedIfcElements, storeyContents, ownerHistId, axisId, _usedExportIds)
            : [];
        if (CurrentProfile)
            WriteJoistAssemblies(w, info.Elements, ownerHistId, bldgLocalPlacementId, axisId, exportedIfcElements, exportedStoreyIds,
                storeyContents, propertySingleValueIds);

        // Resolve decomposition AFTER normal product emission.
        foreach (var pending in pendingCurtainParents.Values.OrderBy(item => item.Element.Id))
        {
            var parent = pending.Element;
            if (exportedIfcElements.ContainsKey(parent.Id)) continue;
            bool roofContainer = parent.CategoryId == -2000035;
            var childEntityIds = (roofContainer ? roofContainerChildren[parent.Id] : exactCurtainChildren[parent.Id])
                .Where(id => exportedIfcElements.TryGetValue(id, out var child)
                    && child.ifcType is "IFCPLATE" or "IFCMEMBER" or "IFCDOOR" or "IFCWINDOW"
                        or "IFCWALL" or "IFCWALLSTANDARDCASE" or "IFCCURTAINWALL")
                .Select(id => exportedIfcElements[id].entityId).Order().ToArray();
            if (childEntityIds.Length == 0) continue;

            int placement = w.Add("IFCLOCALPLACEMENT", $"{R(bldgLocalPlacementId)},{R(axisId)}");
            string containerClass = roofContainer ? "IFCROOF" : "IFCCURTAINWALL";
            string parentTypeName = ResolveProductFamilyAndTypeName(
                parent, containerClass, elemById, elementIdOccurrenceCounts);
            string parentGlobalId = ResolveExactElementGlobalId(parent, _usedExportIds, handleBased: CurrentProfile)
                ?? IfcGuid.FromElementId(parent.Id);
            int entity = w.Add(containerClass,
                $"{S(parentGlobalId)},{R(ownerHistId)},"
                + $"{S($"{parentTypeName}:{parent.Id}")},$,{S(parentTypeName)},"
                + $"{R(placement)},$,{S(parent.Id.ToString())}{(roofContainer ? ",.NOTDEFINED." : "")}");
            w.Add("IFCRELAGGREGATES",
                $"{S(ResolveExactElementGlobalId(parent, _usedExportIds, CurtainWallRelAggregates, CurrentProfile) ?? IfcGuid.FromName($"curtain-aggregate:{parent.Id}"))},{R(ownerHistId)},$,$,"
                + $"{R(entity)},{StepWriter.List(childEntityIds.Select(R))}");
            exportedIfcElements[parent.Id] = (entity, placement, containerClass);
            exportedGlobalIds[parent.Id] = parentGlobalId;
            // Decomposed children keep their world placements and are no longer directly contained
            // in a storey.
            var childSet = childEntityIds.ToHashSet();
            foreach (var contents in storeyContents.Values) contents.RemoveAll(childSet.Contains);
            if (!storeyContents.TryGetValue(pending.StoreyId, out var parentStorey))
                storeyContents[pending.StoreyId] = parentStorey = new List<int>();
            parentStorey.Add(entity);
            exportedStoreyIds[parent.Id] = pending.StoreyId;

            var type = elemById.GetValueOrDefault(parent.FamilyTypeId);
            // The legacy occurrence Name may have been fanned out before canonical type resolution.
            if (roofContainer)
            {
                // The roof container reuses the type name of its family-and-type string as
                // Reference.
                string? roofReference = ResolveValidatedProductTypeName(parent, "IFCROOF", elemById) ?? parent.Name;
                int? roofReferenceId = ExportQuantityTakeOffPropertySet(
                    w, parent, entity, ownerHistId, roofReference, propertySingleValueIds);
                ExportRoofCommonPropertySet(w, parent, entity, ownerHistId, propertySingleValueIds, roofReferenceId, CurrentProfile,
                    withArea: !CurrentProfile);
            }
            else
            {
                string? quantityReference = ResolveCurtainWallReference(parent, type, null);
                ExportQuantityTakeOffPropertySet(w, parent, entity, ownerHistId, quantityReference, propertySingleValueIds);
                ExportCurtainWallCommonPropertySet(w, parent, type, entity, ownerHistId, propertySingleValueIds);
            }
            if (_includeRevitPropertySets && parent.Parameters.Count > 0)
                ExportPropertySets(w, parent, entity, ownerHistId, elemById);
            if (pending.CountedSuppressed)
            {
                skippedCount--;
                SkipLog?.Remove(parent.Id);
                _suppressedGeometrylessProductsByClass[containerClass]--;
            }
            exportedCount++;
        }

        foreach (var pending in pendingMainLoopWallOpeningPropertySets)
        {
            if (!exportedIfcElements.TryGetValue(
                    pending.HostWallId, out var emittedHost)
                || emittedHost.ifcType is not ("IFCWALL" or "IFCWALLSTANDARDCASE")
                || !wallQuantityTakeOffReferenceValueIds.TryGetValue(
                    pending.HostWallId, out int hostReferenceValueId))
            {
                // This authority is stronger than the ordinary opening Name.
                _mainLoopReferenceOmittedCount += 2;
                continue;
            }

            ExportMainLoopWallOpeningPropertySets(
                w, pending.Opening, pending.EntityId, ownerHistId,
                hostReferenceValueId);
        }

        _diag?.WriteLine($"Timing: product loop took {exportClock.Elapsed.TotalSeconds:F1}s");
        HashSet<int> exportedOccurrenceCommonIds = pendingMemberPlatePropertySets
            .Select(item => item.Element.Id)
            .Concat(pendingColumnCommonPropertySets.Select(item => item.Element.Id))
            .Concat(pendingSlabCommonPropertySets.Select(item => item.Element.Id))
            .ToHashSet();
        IReadOnlyDictionary<int, bool?> componentTypeIsExternalByElementId = new Dictionary<int, bool?>();
        // The current profile evaluates the category rule without the shared cache of
        // the legacy profile exporter.
        IReadOnlyDictionary<int, bool> occurrenceIsExternalByElementId = CurrentProfile
            ? ResolveOccurrenceIsExternalValuesCurrent(elemById, exportedOccurrenceCommonIds)
            : ResolveMemberPlateIsExternalValues(
                info.Elements, exportedOccurrenceCommonIds, out componentTypeIsExternalByElementId);
        foreach (var pending in pendingMemberPlatePropertySets)
        {
            bool isExternal = occurrenceIsExternalByElementId.TryGetValue(
                pending.Element.Id, out bool resolvedIsExternal)
                && resolvedIsExternal;
            if (pending.IfcType == "IFCMEMBER")
            {
                ExportMemberCommonPropertySet(
                    w, pending.Element, pending.EntityId, ownerHistId,
                    pending.ReferenceValue, elemById, isExternal,
                    propertySingleValueIds);
            }
            else
            {
                ExportPlateCommonPropertySet(
                    w, pending.Element, pending.EntityId, ownerHistId,
                    pending.ReferenceValue, isExternal,
                    propertySingleValueIds);
            }
        }
        foreach (var pending in pendingColumnCommonPropertySets)
        {
            bool isExternal = occurrenceIsExternalByElementId.TryGetValue(
                pending.Element.Id, out bool resolvedIsExternal)
                && resolvedIsExternal;
            ExportColumnCommonPropertySet(
                w, pending.Element, pending.EntityId, ownerHistId,
                pending.ReferenceValueId, isExternal,
                propertySingleValueIds);
        }
        // IsExternal of a door or window.
        bool HostWallIsExternal(Element opening) =>
            opening.SerializedHostId is int hostId
            && elemById.TryGetValue(hostId, out var hostWall) && hostWall.CategoryId == -2000011
            && ResolveValidatedBasicWallIsExternal(hostWall, elemById.GetValueOrDefault(hostWall.FamilyTypeId)) == true;
        bool DoorIsExternal(Element door) =>
            door.SuperInstanceId is not > 0
            && door.SerializedHostId is int hostId && elemById.GetValueOrDefault(hostId)?.CategoryId == -2000011;
        var firstWindowOfType = new HashSet<int>();
        var seenWindowTypes = new HashSet<int>();
        var doorIsExternalByType = new Dictionary<int, bool>();
        foreach (var pending in pendingOpeningCommonPropertySets.OrderBy(item => item.Element.Id))
        {
            if (pending.IfcType == "IFCWINDOW" && seenWindowTypes.Add(pending.Element.FamilyTypeId))
                firstWindowOfType.Add(pending.Element.Id);
            else if (pending.IfcType == "IFCDOOR" && !doorIsExternalByType.ContainsKey(pending.Element.FamilyTypeId))
                doorIsExternalByType[pending.Element.FamilyTypeId] = DoorIsExternal(pending.Element);
        }
        var openingTypeIsExternal = new Dictionary<int, bool?>();
        foreach (var pending in pendingOpeningCommonPropertySets)
            openingTypeIsExternal[pending.Element.FamilyTypeId] = pending.IfcType == "IFCDOOR"
                ? doorIsExternalByType[pending.Element.FamilyTypeId] : false;
        foreach (var pending in pendingOpeningCommonPropertySets)
        {
            bool? isExternal = pending.IfcType switch
            {
                "IFCWINDOW" => CurrentProfile
                    ? OccurrenceIsExternalCurrent(pending.Element, elemById)
                    : firstWindowOfType.Contains(pending.Element.Id) && HostWallIsExternal(pending.Element),
                "IFCDOOR" => pending.ReferenceValueId.HasValue
                    ? CurrentProfile ? OccurrenceIsExternalCurrent(pending.Element, elemById) ?? false
                        : doorIsExternalByType[pending.Element.FamilyTypeId]
                    : null,
                _ => null,
            };
            if (CurrentProfile && Environment.GetEnvironmentVariable("RVTIO_PSET_DIAG") is { Length: > 0 } psetDiag)
                WriteOpeningIsExternalDiagCurrent(psetDiag, pending.Element, pending.IfcType, elemById, isExternal);
            ExportOpeningCommonPropertySet(
                w, pending.Element, pending.EntityId, ownerHistId, pending.IfcType, isExternal,
                pending.ReferenceValueId, propertySingleValueIds,
                CurrentProfile ? ResolveOpeningThermalTransmittanceCurrent(pending.Element,
                    elemById.GetValueOrDefault(pending.Element.FamilyTypeId)) : null);
        }
        foreach (var pending in pendingSlabCommonPropertySets)
        {
            bool isExternal = occurrenceIsExternalByElementId.TryGetValue(
                pending.Element.Id, out bool resolvedIsExternal)
                && resolvedIsExternal;
            ExportSlabCommonPropertySet(
                w, pending.Element, pending.EntityId, ownerHistId,
                pending.ReferenceValueId, isExternal,
                !CurrentProfile && IsValidatedHorizontalSlab(pending.Element,
                    elemById.GetValueOrDefault(pending.Element.FamilyTypeId)),
                propertySingleValueIds,
                CurrentProfile ? ResolveOccurrenceThermalTransmittanceCurrent(pending.Element, elemById) : null);
        }

        // A wall promoted from an authored holed BRep to a gross swept solid must retain its
        // separately related void even if the filling product itself was filtered.
        foreach (var (wallId, cutterIds) in verifiedGrossWallCutters)
        {
            foreach (int cutterId in cutterIds)
            {
                if ((exactJoinedWallEndProfileOpenings.TryGetValue(
                        wallId, out var exactJoinedWallOpening)
                    && exactJoinedWallOpening.TagId == cutterId)
                    || hostedElements.Any(item => item.elem.Id == cutterId
                        && item.hostWallElemId == wallId)
                    || emittedStandaloneOpeningVoidPairs.Contains(
                        (wallId, cutterId))
                    || !wallIfcIds.ContainsKey(wallId)
                    || !elemById.TryGetValue(cutterId, out var cutter)
                    || cutter.BoundingBox is not { Length: 6 } cutterBounds)
                    continue;
                int cutterIfcId = exportedIfcElements.TryGetValue(
                        cutterId, out var exportedCutter)
                    ? exportedCutter.entityId : 0;
                hostedElements.Add((cutter, wallId, cutterBounds, cutterIfcId));
            }
        }

        // Some RVT wall BReps own an exact rectangular through-hole but serialize no cutter element
        // at all.
        foreach (var (wallId, sourceOwned) in exactSourceWallOpenings)
        {
            if (WallWritesNoBodyOpeningsCurrent(exportedIfcElements, wallId)) continue;
            if (!wallIfcIds.TryGetValue(wallId, out var wallInfo))
            {
                RecordPhantomStoreyWallHostedOpeningCascade(wallId);
                continue;
            }
            if (!elemById.TryGetValue(wallId, out var wallElem))
                continue;
            if (!storeyContents.TryGetValue(wallInfo.storeyId, out var wallStoreyList))
                storeyContents[wallInfo.storeyId] = wallStoreyList = new List<int>();
            for (int index = 0; index < sourceOwned.Count; index++)
                CreateExactSourceWallOpening(w, wallElem, wallInfo.entityId,
                    bldgLocalPlacementId, ownerHistId, bodySubCtxId,
                    wallStoreyList, sourceOwned[index].Opening, index,
                    elemById, propertySingleValueIds,
                    sourceOwned[index].SourceOwnerTagId);
        }

        // An edited wall profile can encode top-open through-voids only in its referenced sketch
        // owner.
        foreach (var (wallId, profileOpenings) in exactEditedProfileWallOpenings)
        {
            if (WallWritesNoBodyOpeningsCurrent(exportedIfcElements, wallId)) continue;
            if (!wallIfcIds.TryGetValue(wallId, out var wallInfo))
            {
                RecordPhantomStoreyWallHostedOpeningCascade(wallId);
                continue;
            }
            if (!elemById.TryGetValue(wallId, out var wallElem))
                continue;
            if (!storeyContents.TryGetValue(wallInfo.storeyId, out var wallStoreyList))
                storeyContents[wallInfo.storeyId] = wallStoreyList = new List<int>();
            for (int index = 0; index < profileOpenings.Count; index++)
                CreateExactSourceWallOpening(w, wallElem, wallInfo.entityId,
                    bldgLocalPlacementId, ownerHistId, bodySubCtxId,
                    wallStoreyList, profileOpenings[index].Opening, index,
                    elemById, propertySingleValueIds, profileOpenings[index].TagId);
        }

        // A bottom-open edited profile can leave a non-rectangular stair void.
        foreach (var (wallId, profileOpening)
                 in exactEditedArbitraryProfileWallOpenings)
        {
            if (WallWritesNoBodyOpeningsCurrent(exportedIfcElements, wallId)) continue;
            if (!wallIfcIds.TryGetValue(wallId, out var wallInfo))
            {
                RecordPhantomStoreyWallHostedOpeningCascade(wallId);
                continue;
            }
            if (!elemById.TryGetValue(wallId, out var wallElem))
                continue;
            if (!storeyContents.TryGetValue(
                    wallInfo.storeyId, out var wallStoreyList))
                storeyContents[wallInfo.storeyId] =
                    wallStoreyList = new List<int>();
            CreateExactSourceWallProfileOpening(w, wallElem, wallInfo.entityId,
                bldgLocalPlacementId, ownerHistId, bodySubCtxId,
                wallStoreyList, profileOpening.Opening,
                profileOpening.TagId, elemById, propertySingleValueIds);
        }

        // A vertically overlapping collinear wall join can own an explicit L-shaped
        // IfcOpeningElement whose Tag is the joined wall itself.
        foreach (var (wallId, profileOpening)
                 in exactJoinedWallEndProfileOpenings)
        {
            if (WallWritesNoBodyOpeningsCurrent(exportedIfcElements, wallId)) continue;
            if (!wallIfcIds.TryGetValue(wallId, out var wallInfo))
            {
                RecordPhantomStoreyWallHostedOpeningCascade(wallId);
                continue;
            }
            if (!elemById.TryGetValue(wallId, out var wallElem))
                continue;
            if (!storeyContents.TryGetValue(
                    wallInfo.storeyId, out var wallStoreyList))
                storeyContents[wallInfo.storeyId] =
                    wallStoreyList = new List<int>();
            CreateExactSourceWallProfileOpening(w, wallElem, wallInfo.entityId,
                bldgLocalPlacementId, ownerHistId, bodySubCtxId,
                wallStoreyList, profileOpening.Opening,
                profileOpening.TagId, elemById, propertySingleValueIds,
                propertiesFromTagElement: true);
        }

        // A single family void can cut several parallel wall-layer products.
        var commonHostedOpenings = new Dictionary<int, HostedOpeningGeometry>();
        var hostedOpeningHostWalls =
            new Dictionary<int, IReadOnlyList<Element>>();
        int familyCutAvailable = 0;
        int familyCutUsed = 0;
        foreach (var group in hostedElements.GroupBy(item => item.elem.Id))
        {
            var first = group.First();
            var hostWalls = group.Select(item => item.hostWallElemId).Distinct()
                .Select(id => elemById.TryGetValue(id, out var wall) ? wall : null)
                .Where(wall => wall != null).Cast<Element>().ToList();
            hostedOpeningHostWalls[first.elem.Id] = hostWalls;
            Element? hostedType = LinkedFamilyType(first.elem, elemById);
            IReadOnlyList<Element> familyCutTypes = LinkedFamilyCutTypes(first.elem, elemById);
            if (familyCutTypes.Count > 0) familyCutAvailable++;
            HostedOpeningGeometry familyCutOpening = default;
            var builtFamilyCutCandidates = new List<HostedOpeningGeometry>();
            foreach (var familyCutType in familyCutTypes)
                if (TryBuildFamilyCutHostedOpeningGeometry(
                        first.elem, familyCutType, hostWalls,
                        out var familyCutCandidate))
                    builtFamilyCutCandidates.Add(familyCutCandidate);
            bool builtFamilyCut = builtFamilyCutCandidates.Count > 0;
            if (builtFamilyCut)
                familyCutOpening = builtFamilyCutCandidates[0];
            if (builtFamilyCut
                && TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
                    first.elem, familyCutTypes, builtFamilyCutCandidates,
                    hostWalls, inverseHostedHostIds,
                    out var preferredMultiHostFamilyCutOpening))
                familyCutOpening = preferredMultiHostFamilyCutOpening;
            bool builtFamilyCutLoop = !builtFamilyCut && familyCutTypes.Any(familyCutType =>
                TryBuildFamilyCutLoopHostedOpeningGeometry(
                    first.elem, familyCutType, out familyCutOpening));
            if (builtFamilyCut || builtFamilyCutLoop)
            {
                commonHostedOpenings[first.elem.Id] = familyCutOpening;
                familyCutUsed++;
            }
            else
            {
                HostedOpeningGeometry primitiveOpening = default;
                bool builtPrimitiveOpening =
                    TryBuildSerializedHostedOpeningGeometry(
                        first.elem, hostedType, out primitiveOpening);
                if (builtPrimitiveOpening
                    && hostWalls.Any(hostWall =>
                        HasExactSixPointJoinShellWithTwoOpeningSourceAuthority(
                            hostWall.Geometry))
                    && TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
                        first.elem, first.bbox, hostWalls,
                        primitiveOpening, out var exactAuthoredEnvelope))
                    primitiveOpening = exactAuthoredEnvelope;
                else if (!builtPrimitiveOpening)
                    builtPrimitiveOpening = TryBuildCommonHostedOpeningGeometry(
                        first.elem, first.bbox, hostWalls,
                        out primitiveOpening);
                if (builtPrimitiveOpening)
                    commonHostedOpenings[first.elem.Id] =
                    TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
                        first.elem, hostWalls, primitiveOpening,
                        out var quarteredOpening, elemById,
                        inverseHostedHostIds)
                        ? quarteredOpening
                    : TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                            first.elem, hostedType, first.bbox, hostWalls,
                            primitiveOpening, out var steppedOpening)
                        ? steppedOpening
                        : primitiveOpening;
                else if (
                    TryBuildUniqueExactSteppedMultiHostOpeningFromAuthoredHostProfiles(
                        first.elem, hostedType, first.bbox, hostWalls,
                        out var subsetSteppedOpening))
                    commonHostedOpenings[first.elem.Id] =
                        subsetSteppedOpening;
            }
            if (!builtFamilyCut && !builtFamilyCutLoop
                && TryBuildExactSteppedOpeningFromSourceWallProfilesAndMappedBreakpoint(
                    first.elem, hostWalls, out var sourceSteppedOpening))
            {
                commonHostedOpenings[first.elem.Id] = sourceSteppedOpening;
            }
        }

        // When that cutter has exactly one forward host and a complete duplicate-free set of
        // decoded inverse hosts, partition the relations by exact positive solid intersection: the
        // direct wall receives the writer profile clipped to its exact source-owned normal
        var exactForwardHostOpeningPartitions =
            new Dictionary<int, ExactForwardHostOpeningPartition>();
        foreach (var (directHostId, verifiedCutterIds) in
                 verifiedGrossWallCutters)
        {
            if (verifiedCutterIds.Count != 1)
                continue;
            int cutterId = verifiedCutterIds[0];
            if (!elemById.TryGetValue(directHostId, out var directHost)
                || !elemById.TryGetValue(cutterId, out var cutter)
                || cutter.SerializedHostId != directHostId
                || !TryGetExactSingleLinkedSourceOpening(
                    directHost, cutterId, out var directSourceOpening,
                    out bool usesBoundarySlotSourceValidation,
                    requireDecodedCutterAuthority: false)
                || !usesBoundarySlotSourceValidation
                || !commonHostedOpenings.TryGetValue(
                    cutterId, out var secondaryWriterOpening)
                || !(secondaryWriterOpening.IsExactSerializedDefinition
                    || secondaryWriterOpening.IsFamilyCutLoop))
                continue;

            var directPair = (WallId: directHostId, CutterId: cutterId);
            var verifiedDirectPairs =
                new HashSet<(int WallId, int CutterId)> { directPair };
            var directSourceOpenings = new Dictionary<
                (int WallId, int CutterId), HostedOpeningGeometry>
            {
                [directPair] = directSourceOpening,
            };
            var secondaryWriterOpenings = new Dictionary<
                (int WallId, int CutterId), HostedOpeningGeometry>
            {
                [directPair] = secondaryWriterOpening,
            };
            bool partitionDiagnostics = Environment.GetEnvironmentVariable(
                    "RVTIO_GEOM_DBG_ID") is { } partitionInputDebugIds
                && partitionInputDebugIds.Split(
                        ',', StringSplitOptions.RemoveEmptyEntries
                        | StringSplitOptions.TrimEntries)
                    .Any(value => int.TryParse(value, out int id)
                        && (id == cutterId || id == directHostId));
            if (partitionDiagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCHOSTOPENINGPARTITIONINPUT cutter={cutterId} "
                    + $"direct={directHostId} "
                    + $"source={directSourceOpening} "
                    + $"writer={secondaryWriterOpening}");
            if (!TryGetExactForwardHostOpeningPartition(
                    cutter, elemById, inverseHostedHostIds,
                    verifiedDirectPairs, directSourceOpenings,
                    secondaryWriterOpenings,
                    out var partition))
            {
                if (partitionDiagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCHOSTOPENINGPARTITION cutter={cutterId} "
                        + $"direct={directHostId} result=reject");
                continue;
            }

            if (Environment.GetEnvironmentVariable(
                    "RVTIO_GEOM_DBG_ID") is { } partitionDebugIds
                && partitionDebugIds.Split(
                        ',', StringSplitOptions.RemoveEmptyEntries
                        | StringSplitOptions.TrimEntries)
                    .Any(value => int.TryParse(value, out int id)
                        && (id == cutterId || id == directHostId)))
                DiagnosticSink.WriteLine(
                    $"IFCHOSTOPENINGPARTITION cutter={cutterId} "
                    + $"direct={directHostId} secondary="
                    + $"{string.Join(',', partition.IntersectingSecondaryHostIds)} "
                    + $"decoded={string.Join(',', inverseHostedHostIds[cutterId])}");

            exactForwardHostOpeningPartitions[cutterId] = partition;
            var retainedHostIds = partition.IntersectingSecondaryHostIds
                .Append(partition.DirectHostId).ToHashSet();
            hostedElements.RemoveAll(item =>
                item.elem.Id == cutterId
                && !retainedHostIds.Contains(item.hostWallElemId));

            int cutterIfcId = exportedIfcElements.TryGetValue(
                    cutterId, out var exportedCutter)
                ? exportedCutter.entityId : 0;
            foreach (int hostId in retainedHostIds.OrderBy(id => id))
            {
                if (!wallIfcIds.ContainsKey(hostId)
                    || hostedElements.Any(item => item.elem.Id == cutterId
                        && item.hostWallElemId == hostId))
                    continue;
                hostedElements.Add((
                    cutter, hostId, cutter.BoundingBox!, cutterIfcId));
            }
            commonHostedOpenings[cutterId] =
                partition.SecondaryWriterOpening;
            hostedOpeningHostWalls[cutterId] = retainedHostIds
                .OrderBy(id => id).Select(id => elemById[id]).ToList();
        }

        foreach (var pair in
                 exactCompleteOpenSixteenFaceSplitRevealWriterOperands.Keys)
        {
            bool exactWriterTarget = wallIfcIds.ContainsKey(pair.WallId)
                && hostedElements.Count(item =>
                    item.hostWallElemId == pair.WallId
                    && item.elem.Id == pair.CutterId) == 1;
            bool competingForwardPartition =
                exactForwardHostOpeningPartitions.TryGetValue(
                    pair.CutterId, out var partition)
                && (pair.WallId == partition.DirectHostId
                    || partition.IntersectingSecondaryHostIds.Contains(
                        pair.WallId));
            if (!exactWriterTarget
                || competingForwardPartition
                || HasCompetingExactHostedWriterAuthority(pair))
                throw new InvalidOperationException(
                    "Split-reveal writer target is missing, duplicated, or "
                    + "owned by a competing exact authority.");
        }

        var filledHostedElementIds = new HashSet<int>();
        foreach (var (hostedElem, hostWallId, hostedBbox, hostedIfcId) in hostedElements)
        {
            if ((exactJoinedWallEndProfileOpenings.TryGetValue(
                    hostWallId, out var exactJoinedWallOpening)
                && exactJoinedWallOpening.TagId == hostedElem.Id)
                || exactEmbeddedSingleFamilyCutBrepPairs.Contains(
                    (hostWallId, hostedElem.Id)))
                continue;
            if (!wallIfcIds.TryGetValue(hostWallId, out var wallInfo))
            {
                RecordPhantomStoreyWallHostedOpeningCascade(hostWallId);
                continue;
            }
            if (!elemById.TryGetValue(hostWallId, out var wallElem)) continue;
            if (WallWritesNoBodyOpeningsCurrent(exportedIfcElements, hostWallId)
                && !(exportedIfcElements.TryGetValue(hostWallId, out var cutoutHostProduct) && cutoutHostProduct.ifcType == "IFCWALL"
                    && IsDoorWindowCutoutExtrusionCurrent(hostedElem, hostedIfcId, hostWallId, elemById)))
                continue;

            bool exactForwardHostPartitionPair =
                exactForwardHostOpeningPartitions.TryGetValue(
                    hostedElem.Id, out var exactForwardHostPartition)
                && (hostWallId == exactForwardHostPartition.DirectHostId
                    || exactForwardHostPartition.IntersectingSecondaryHostIds
                        .Contains(hostWallId));
            var hostedOpeningPair = (hostWallId, hostedElem.Id);
            HostedOpeningGeometry
                exactCompleteOpenTenFaceQuarteredRevealWriterOperand = default;
            bool exactCompleteOpenTenFaceQuarteredRevealPair =
                exactCompleteOpenTenFaceQuarteredRevealOpeningPairs.Contains(
                    hostedOpeningPair)
                && exactCompleteOpenTenFaceQuarteredRevealWriterOperands
                    .TryGetValue(hostedOpeningPair,
                        out exactCompleteOpenTenFaceQuarteredRevealWriterOperand);
            bool exactCompleteOpenTwentyFiveFaceOpposedSidePocketPair =
                exactCompleteOpenTwentyFiveFaceOpposedSidePocketWriterOperands
                    .TryGetValue(hostedOpeningPair,
                        out var exactCompleteOpenTwentyFiveFaceOpposedSidePocketWriterOperand);
            bool exactCompleteOpenSixteenFaceSplitRevealPair =
                exactCompleteOpenSixteenFaceSplitRevealWriterOperands
                    .TryGetValue(hostedOpeningPair,
                        out var exactCompleteOpenSixteenFaceSplitRevealWriterOperand);
            bool exactCompleteOpenTenFaceSideCoincidentBrepSweptPair =
                exactCompleteOpenTenFaceSideCoincidentBrepSweptWriterOperands
                    .TryGetValue(hostedOpeningPair,
                        out var exactCompleteOpenTenFaceSideCoincidentWriterOperand);
            HostedOpeningGeometry hostedOpening =
                exactCompleteOpenSixteenFaceSplitRevealPair
                    ? exactCompleteOpenSixteenFaceSplitRevealWriterOperand
                : exactCompleteOpenTenFaceQuarteredRevealPair
                    ? exactCompleteOpenTenFaceQuarteredRevealWriterOperand
                : exactCompleteOpenTwentyFiveFaceOpposedSidePocketPair
                    ? exactCompleteOpenTwentyFiveFaceOpposedSidePocketWriterOperand
                : exactCompleteOpenTenFaceSideCoincidentBrepSweptPair
                    ? exactCompleteOpenTenFaceSideCoincidentWriterOperand
                : exactForwardHostPartitionPair
                && hostWallId == exactForwardHostPartition.DirectHostId
                    ? exactForwardHostPartition.DirectHostOpening
                : exactForwardHostPartitionPair
                    ? exactForwardHostPartition.SecondaryWriterOpening
                : exactForwardSecondaryFamilyCutPairs.Contains(
                        (hostWallId, hostedElem.Id))
                    && exactForwardSecondaryFamilyCutOpenings.TryGetValue(
                        (hostWallId, hostedElem.Id),
                        out var forwardSecondarySourceOpening)
                    ? forwardSecondarySourceOpening
                : verifiedExactBoundarySlotSourceOpenings.Contains(
                    (hostWallId, hostedElem.Id))
                && exactBoundarySlotWriterOpenings.TryGetValue(
                    (hostWallId, hostedElem.Id),
                    out var boundarySlotWriterOpening)
                    ? boundarySlotWriterOpening
                : verifiedExactSingleLinkedSourceOpenings.Contains(
                    (hostWallId, hostedElem.Id))
                && exactSingleLinkedSourceOpenings.TryGetValue(
                    (hostWallId, hostedElem.Id), out var sourceOpening)
                    ? sourceOpening
                    : commonHostedOpenings.GetValueOrDefault(hostedElem.Id);
            HostedOpeningGeometry hostIntersection = hostedOpening;
            if (hostedIfcId > 0 && !exactForwardHostPartitionPair
                && !HasCompetingExactHostedWriterAuthority(hostedOpeningPair)
                && ownPrimaryFamilyWriterOperands.TryGetValue(hostedOpeningPair, out var ownPrimaryOpening))
                hostedOpening = hostIntersection = ownPrimaryOpening;
            if (!exactCompleteOpenSixteenFaceSplitRevealPair
                && !exactCompleteOpenTenFaceQuarteredRevealPair
                && !exactCompleteOpenTwentyFiveFaceOpposedSidePocketPair
                && !exactCompleteOpenTenFaceSideCoincidentBrepSweptPair
                && !exactForwardHostPartitionPair
                && !exactForwardSecondaryFamilyCutPairs.Contains(
                    (hostWallId, hostedElem.Id))
                && !TryTargetCommonHostedOpeningToHost(
                    hostedOpening, wallElem, out hostIntersection))
                continue;
            if (hostedOpening.IsFamilyCutLoop)
            {
                // The direct InsertableInst host relations use the Boolean intersection with that
                // wall body.
                bool directHost = hostedElem.SerializedHostId == hostWallId
                    || hostedElem.ExtraHostIds?.Contains(hostWallId) == true
                    || hostedElem.ExplicitHostIds?.Contains(hostWallId) == true;
                if (hostedIfcId > 0 && directHost)
                    hostedOpening = hostIntersection;
            }
            if (!exactCompleteOpenSixteenFaceSplitRevealPair
                && !exactCompleteOpenTenFaceQuarteredRevealPair
                && !exactCompleteOpenTwentyFiveFaceOpposedSidePocketPair
                && !exactCompleteOpenTenFaceSideCoincidentBrepSweptPair
                && !exactForwardHostPartitionPair
                && !exactForwardSecondaryFamilyCutPairs.Contains(
                    (hostWallId, hostedElem.Id))
                && !verifiedExactSingleLinkedSourceOpenings.Contains(
                    (hostWallId, hostedElem.Id))
                && hostedOpening.OwnPrimaryFamilyHostId == 0
                && hostedOpeningHostWalls.TryGetValue(
                    hostedElem.Id, out var parameterizedHostWalls)
                && TryResolveHostedOpeningWriterOperand(
                    hostedElem, hostedBbox, wallElem, elemById,
                    hostedOpening, out var perHostPrimitive)
                && (TryBuildExactSymmetricAdditionalDepthRectangularOpening(
                        hostedElem, wallElem, parameterizedHostWalls,
                        perHostPrimitive,
                        out var parameterizedPerHostOpening)
                    || TryBuildExactContractedParameterizedRectangularOpening(
                        hostedElem, wallElem, parameterizedHostWalls,
                        perHostPrimitive,
                        out parameterizedPerHostOpening)
                    || TryBuildExactParameterizedRevealOpening(
                        hostedElem, parameterizedHostWalls, perHostPrimitive,
                        out parameterizedPerHostOpening)))
                hostedOpening = parameterizedPerHostOpening;

            if (!storeyContents.TryGetValue(wallInfo.storeyId, out var wallStoreyList))
                storeyContents[wallInfo.storeyId] = wallStoreyList = new List<int>();

            if (CurrentProfile && TryBuildOwnSecondaryFamilyCutout(hostedElem, wallElem, elemById, out var shadowOpening))
                hostedOpening = shadowOpening;

            CreateHostedOpeningAbsolute(w, hostedElem, hostedIfcId, hostedBbox, wallElem,
                wallInfo.entityId, bldgLocalPlacementId,
                ownerHistId, bodySubCtxId, wallStoreyList, elemById,
                TryRegisterHostedOpeningFillRelationship(
                    hostedElem, hostedIfcId, hostWallId,
                    filledHostedElementIds),
                propertySingleValueIds,
                hostedOpening,
                exactJoinedSpanBrepSweptOpeningPairs.Contains(
                    (hostWallId, hostedElem.Id))
                || exactConcordantFamilyCutBrepSweptOpeningPairs.Contains(
                    (hostWallId, hostedElem.Id))
                || exactVerticalStepBrepSweptOpeningPairs.Contains(
                    (hostWallId, hostedElem.Id))
                || exactCompleteOpenTenFaceSideCoincidentBrepSweptOpeningPairs.Contains(
                    (hostWallId, hostedElem.Id))
                || exactCompleteOpenTwentyFiveFaceOpposedSidePocketPair,
                alignExactBrepPrismSweptSolidToDefinition:
                    exactCompleteOpenTwentyFiveFaceOpposedSidePocketPair);
        }

        if (CurrentProfile)
        {
            WriteCutPairOpeningsCurrent(w, wallIfcIds, exportedIfcElements, elemById,
                wallQuantityTakeOffReferenceValueIds, slabQuantityTakeOffReferenceValueIds,
                exactJoinedWallEndProfileOpenings, storeyContents,
                bldgLocalPlacementId, ownerHistId, bodySubCtxId, propertySingleValueIds);
            WriteSketchOpeningsCurrent(w, wallIfcIds, exportedIfcElements, elemById, storeyContents,
                bldgLocalPlacementId, ownerHistId, bodySubCtxId, propertySingleValueIds);
        }

        // Horizontal slab BReps already contain these void loops in their face topology, but Revit
        // also exports each authored loop as an explicit IfcOpeningElement.
        var exportedSlabIds = exportedIfcElements
            .Where(pair => !CurrentProfile && pair.Value.ifcType == "IFCSLAB")
            .Select(pair => pair.Key).ToHashSet();
        var sketchLinesBySlab = new Dictionary<int, List<Element>>();
        foreach (var sketchLine in elemById.Values.Where(element =>
                     element.CategoryId == -2000045))
            foreach (int slabId in sketchLine.References?.Distinct()
                         .Where(exportedSlabIds.Contains) ?? Enumerable.Empty<int>())
            {
                if (!sketchLinesBySlab.TryGetValue(slabId, out var lines))
                    sketchLinesBySlab[slabId] = lines = [];
                lines.Add(sketchLine);
            }
        foreach (int slabId in exportedSlabIds.Order())
        {
            if (!elemById.TryGetValue(slabId, out var slab)
                || !exportedIfcElements.TryGetValue(slabId, out var slabProduct)
                || !sketchLinesBySlab.TryGetValue(slabId, out var sketchLines))
                continue;
            var contents = storeyContents.Values
                .FirstOrDefault(items => items.Contains(slabProduct.entityId));
            if (contents == null) continue;
            int? slabQuantityTakeOffReferenceValueId =
                slabQuantityTakeOffReferenceValueIds.TryGetValue(
                    slabId, out int emittedReferenceValueId)
                    ? emittedReferenceValueId
                    : null;
            CreateSerializedSlabOpenings(w, slab, slabProduct.entityId,
                slabProduct.placementId, ownerHistId, bodySubCtxId, contents, sketchLines,
                elemById, propertySingleValueIds,
                slabQuantityTakeOffReferenceValueId);
        }

        var materialIfcIds = new Dictionary<int, int>();
        // The IfcSurfaceStyle of a material, one per material
        //; 0 for a material without a decoded colour.
        var materialSurfaceStyleIds = new Dictionary<int, int>();
        int EnsureSurfaceStyle(int materialElementId, string materialName)
        {
            if (materialSurfaceStyleIds.TryGetValue(materialElementId, out int cached))
                return cached;

            int surfaceStyleId = 0;
            if (materialElementId is RoomInteriorsMaterialId or MepSpaceInteriorsMaterialId)
            {
                bool mepSpace = materialElementId == MepSpaceInteriorsMaterialId;
                var (roomRed, roomGreen, roomBlue) = DecodePackedMaterialColor(mepSpace ? MepSpaceInteriorsColour : RoomInteriorsColour);
                int roomColourId = w.Add("IFCCOLOURRGB", $"$,{D(roomRed)},{D(roomGreen)},{D(roomBlue)}");
                int roomRenderingId = w.Add("IFCSURFACESTYLERENDERING",
                    $"{R(roomColourId)},{D(RoomInteriorsTransparencyPercent / 100.0)},$,$,$,$,"
                    + $"IFCNORMALISEDRATIOMEASURE(0.5),IFCSPECULAREXPONENT({D(RoomInteriorsShininess)}),.NOTDEFINED.");
                surfaceStyleId = w.Add("IFCSURFACESTYLE",
                    $"{S(mepSpace ? "MEP space interiors" : "Room interiors")},.BOTH.,{StepWriter.List(R(roomRenderingId))}");
            }
            else if (elemById.TryGetValue(materialElementId, out var materialElement)
                && materialElement.Parameters.FirstOrDefault(parameter =>
                    parameter.Definition?.Name == "MATERIAL_PARAM_COLOR")?.Value is int packedColor)
            {
                var (red, green, blue) = DecodePackedMaterialColor(packedColor);
                int transparencyPercent = materialElement.Parameters.FirstOrDefault(parameter =>
                    parameter.Definition?.Name == "MATERIAL_PARAM_TRANSPARENCY")?.Value is int transparency
                    ? Math.Clamp(transparency, 0, 100) : 0;
                int shininess = materialElement.Parameters.FirstOrDefault(parameter =>
                    parameter.Definition?.Name == "MATERIAL_PARAM_SHININESS")?.Value is int shine
                    ? Math.Max(0, shine) : 0;

                // The current profile writes the transparency the file stores (a float: 0.975 where
                // the parameter is 97 percent)
                double transparencyFraction = CurrentProfile && materialElement.SerializedMaterialTransparency is { } stored
                    && (int)((float)stored * 100) == transparencyPercent ? stored : transparencyPercent / 100.0;
                int colourId = w.Add("IFCCOLOURRGB", $"$,{D(red)},{D(green)},{D(blue)}");
                int renderingId = w.Add("IFCSURFACESTYLERENDERING",
                    $"{R(colourId)},{D(transparencyFraction)},$,$,$,$,"
                    + $"IFCNORMALISEDRATIOMEASURE(0.5),IFCSPECULAREXPONENT({D(shininess)}),.NOTDEFINED.");
                surfaceStyleId = w.Add("IFCSURFACESTYLE",
                    $"{S(materialName)},.BOTH.,{StepWriter.List(R(renderingId))}");
            }
            materialSurfaceStyleIds[materialElementId] = surfaceStyleId;
            return surfaceStyleId;
        }

        int EnsureMaterial(int materialElementId, string? preferredName = null)
        {
            if (materialIfcIds.TryGetValue(materialElementId, out int existing))
                return existing;

            string materialName = ResolveMaterialName(materialElementId, preferredName, elemById);
            int materialIfcId = w.Add("IFCMATERIAL", S(materialName));
            materialIfcIds[materialElementId] = materialIfcId;

            int surfaceStyleId = EnsureSurfaceStyle(materialElementId, materialName);
            if (surfaceStyleId != 0)
            {
                int assignmentId = w.Add("IFCPRESENTATIONSTYLEASSIGNMENT",
                    StepWriter.List(R(surfaceStyleId)));
                int styledItemId = w.Add("IFCSTYLEDITEM",
                    $"$,{StepWriter.List(R(assignmentId))},$");
                int styledRepresentationId = w.Add("IFCSTYLEDREPRESENTATION",
                    $"{R(contextId)},{S("Style")},{S("Material")},{StepWriter.List(R(styledItemId))}");
                w.Add("IFCMATERIALDEFINITIONREPRESENTATION",
                    $"$,$,{StepWriter.List(R(styledRepresentationId))},{R(materialIfcId)}");
            }

            return materialIfcId;
        }

        // The current profile styles of the Body items
        //, by product entity: a host object styles
        // every item with the material of the first layer of its type, any other product gives each
        var bodyStyles = new BodyStyleSources();
        // The best material of each Geometry node of a geometry
        //, read once.
        var nodeMaterialsByGeometry = new Dictionary<GeometryData, IReadOnlyDictionary<int, int>>(ReferenceEqualityComparer.Instance);
        IReadOnlyDictionary<int, int> NodeMaterials(GeometryData geometry)
        {
            if (!nodeMaterialsByGeometry.TryGetValue(geometry, out var materialByNode))
            {
                bool IsMaterialElement(int id) => elemById.TryGetValue(id, out var m) && IsSerializedMaterial(m);
                int StyleMaterial(int style) => info.GraphicsStyles?.GetValueOrDefault(style).Material ?? 0;
                var byNode = PieceMaterials(geometry, IsMaterialElement, StyleMaterial)
                    .Where(piece => piece.Node > 0).ToDictionary(piece => piece.Node, piece => piece.Material);
                // a ghost node written as triangles has no polygon, so its material is that of its
                // ghost record: the material of its faces, else that of its graphics style, else
                // none
                foreach (var node in geometry.MeshNodes ?? [])
                    if (node.Ghost && node.Node > 0 && !byNode.ContainsKey(node.Node))
                        byNode[node.Node] = node.RenderStyleId > 0 && IsMaterialElement(node.RenderStyleId) ? node.RenderStyleId
                            : node.Style > 0 && StyleMaterial(node.Style) is > 0 and int fromStyle && IsMaterialElement(fromStyle) ? fromStyle : 0;
                nodeMaterialsByGeometry[geometry] = materialByNode = byNode;
            }
            return materialByNode;
        }
        // The topography is the body of the site: each surface is an item in the dominant material
        // of its faces.
        if (CurrentProfile && siteShapeId.HasValue)
            bodyStyles.Solids[siteId] = spatialTerrainSurfaces.Select(surface => DominantFaceMaterialId(
                surface.Geometry!.Faces, id => elemById.TryGetValue(id, out var m) && IsSerializedMaterial(m)) ?? 0).ToList();

        var layerAssociatedElementIds = new HashSet<int>();
        int unnamedMaterialIfcId = 0;
        int EnsureUnnamedMaterial() =>
            unnamedMaterialIfcId != 0 ? unnamedMaterialIfcId
                : unnamedMaterialIfcId = w.Add("IFCMATERIAL", S(CurrentProfile ? " <Unnamed>" : "<Unnamed>"));

        // Layers of a host object (wall, floor, ceiling, roof) come from the compound structure of
        // its own type (HostObjAttr, native record) when the type is bound exactly; the legacy
        // public layers remain the fallback.
        (int TypeId, List<(int MaterialId, double ThicknessMm)> Layers)? NativeHostLayers(
            Element element, string ifcType)
        {
            if (element.Id <= 0 || element.SerializedSystemTypeId is not > 0
                || element.SerializedSystemTypeId == element.Id
                || elementIdOccurrenceCounts.GetValueOrDefault(element.Id) != 1
                || !elemById.TryGetValue(element.SerializedSystemTypeId.Value, out var type)
                || type.Id != element.SerializedSystemTypeId
                || elementIdOccurrenceCounts.GetValueOrDefault(type.Id) != 1
                // (the current profile: a Floor occurrence of a foundation slab type stays under
                // OST_Floors)
                || type.CategoryId != element.CategoryId
                    && !(CurrentProfile && type.CategoryId is -2001300 && element.CategoryId is -2000032)
                || type.SerializedHostTypeLayers is not { Length: > 0 } raw)
                return null;
            bool agrees = (type.SerializedSystemTypeClassId, element.CategoryId, ifcType) switch
            {
                (512, -2000011, "IFCWALL" or "IFCWALLSTANDARDCASE") => true,
                (1915, -2000032, "IFCSLAB") => true,
                (1915, -2001300, "IFCSLAB" or "IFCROOF") => true,
                (646, -2000038, "IFCCOVERING") => true,
                // The current profile: the roof export and the building pad go through
                // The host-object export too.
                (3452, -2000035, "IFCROOF") or (571, -2001263, "IFCSLAB") => CurrentProfile,
                _ => false,
            };
            if (!agrees) return null;
            var layers = new List<(int, double)>();
            foreach (var layer in raw)
            {
                double widthFeet = BitConverter.Int64BitsToDouble(layer.LayerWidthBits);
                double thicknessMm = widthFeet * 304.8;
                if (!double.IsFinite(widthFeet) || thicknessMm <= 0) continue;
                layers.Add((layer.RawMaterialId, thicknessMm));
            }
            return layers.Count == 0 ? null : (type.Id, layers);
        }
        // A layer without a material takes the material of its category (Category.Material, kept in the graphics styles of the category:
        // 'Default Floor', 'Default Wall' and 'Default Roof' in sample projects; the building pad category has none and
        // keeps the unnamed material). Only a category whose styles all name the same existing material has one.
        int? CategoryLayerMaterial(int? categoryId)
        {
            if (categoryId is null || info.GraphicsStyles is not { } styles) return null;
            var materials = styles.Values.Where(style => style.Category == categoryId && style.Material > 0).Select(style => style.Material).Distinct().ToList();
            return materials.Count == 1 && elemById.ContainsKey(materials[0]) ? materials[0] : null;
        }

        var layerSetByKey = new Dictionary<string, (int LayerSetId, double TotalThicknessMm)>();
        var layerSetByProductEntity = new Dictionary<int, int>();
        var layerUsageProductEntities = new HashSet<int>();
        var layeredProducts = exportedIfcElements
            .Select(pair => (ElementId: pair.Key, Product: pair.Value,
                Element: elemById.GetValueOrDefault(pair.Key)))
            .Where(item => item.Element != null)
            .Select(item => (item.ElementId, item.Product, Element: item.Element!,
                Native: NativeHostLayers(item.Element!, item.Product.ifcType)))
            .Where(item => item.Native != null || item.Element.Layers is { Count: > 0 })
            .GroupBy(item => item.Native is { } native
                ? $"native|{native.TypeId}|{item.Product.ifcType}|{item.Element.CategoryId}"
                    + $"|{(item.Element.SerializedWallFlipped == true ? "flipped" : "plain")}"
                : MaterialLayerSetGroupKey(item.Element, item.Product.ifcType,
                    elemById, elementIdOccurrenceCounts));

        foreach (var group in layeredProducts)
        {
            var first = group.First();
            var layers = first.Native is { } nativeLayers
                ? nativeLayers.Layers
                : first.Element.Layers!.OrderBy(layer => layer.LayerIndex)
                    .Select(layer => (MaterialId: layer.MaterialId, ThicknessMm: layer.ThicknessMm)).ToList();
            string layerSetKey = first.Native is { } ownType
                ? $"native|{ownType.TypeId}" : $"legacy|{group.Key}";
            // The host-object export: layer 0 of the compound structure,
            // whatever its width.
            int firstLayerMaterial = first.Native is { } firstNative
                ? elemById.TryGetValue(firstNative.TypeId, out var firstLayerType)
                    && firstLayerType.SerializedHostTypeLayers is { Length: > 0 } firstLayerRaw
                    && elemById.ContainsKey(firstLayerRaw[0].RawMaterialId) ? firstLayerRaw[0].RawMaterialId : 0
                : layers.Count > 0 && elemById.ContainsKey(layers[0].MaterialId) ? layers[0].MaterialId : 0;
            foreach (var item in group) bodyStyles.Uniform[item.Product.entityId] = firstLayerMaterial;
            if (!layerSetByKey.TryGetValue(layerSetKey, out var layerSet))
            {
                var materialLayerIds = new List<int>(layers.Count);
                foreach (var (layerMaterialId, layerThicknessMm) in layers)
                {
                    int materialId;
                    if (first.Native != null)
                        materialId = layerMaterialId > 0 && elemById.ContainsKey(layerMaterialId)
                            ? EnsureMaterial(layerMaterialId)
                            : CategoryLayerMaterial(first.Element.CategoryId) is > 0 and int categoryMaterial
                                ? EnsureMaterial(categoryMaterial) : EnsureUnnamedMaterial();
                    else
                        materialId = EnsureMaterial(layerMaterialId, first.Element.Layers!
                            .FirstOrDefault(l => l.MaterialId == layerMaterialId)?.MaterialName);
                    materialLayerIds.Add(w.Add("IFCMATERIALLAYER",
                        $"{R(materialId)},{StepWriter.RealFromMillimetres(layerThicknessMm)},$"));
                }

                string? ownTypeName = first.Native is { } named && elemById.TryGetValue(named.TypeId, out var namedType)
                    ? CurrentProfile && namedType is { SerializedSystemTypeClassId: 3452, CategoryId: -2000035, ValidatedHostTypeLayerSetName.Length: > 0 }
                        ? namedType.ValidatedHostTypeLayerSetName : TypeObjectName(namedType)
                    : null;
                string layerSetName = ownTypeName
                    ?? ResolveValidatedLayerSetName(group.Select(item =>
                        (item.Element, item.Product.ifcType)).ToList(), elemById, elementIdOccurrenceCounts)
                    ?? string.Join(':', new[] { first.Element.FamilyName, first.Element.Name }
                    .Where(value => !string.IsNullOrWhiteSpace(value)));
                // The current profile names the set getShortDescriptiveName(): "Family : Type".
                if (CurrentProfile) layerSetName = CurrentShortDescriptiveName(layerSetName);
                int layerSetId = w.Add("IFCMATERIALLAYERSET",
                    $"{StepWriter.List(materialLayerIds.Select(R))},{S(layerSetName)}");
                // The usage offset starts from the wall's total layer width: the wall's stored
                // width in feet, scaled once).
                double totalMm = layers.Sum(layer => layer.ThicknessMm);
                if (first.Native != null)
                {
                    double? ownFeet = first.Element.ValidatedWallTypeThicknessFeet
                        ?? (first.Element.Parameters.FirstOrDefault(parameter => parameter.Id == -1001000)?.Value as double?);
                    if (ownFeet is > 0) totalMm = ownFeet.Value * 304.8;
                }
                layerSet = (layerSetId, totalMm);
                layerSetByKey[layerSetKey] = layerSet;
            }

            foreach (var item in group) layerSetByProductEntity[item.Product.entityId] = layerSet.LayerSetId;
            var associated = CurrentProfile ? group.Where(item => item.Product.ifcType != "IFCWALL").ToList() : group.ToList();
            if (associated.Count == 0) continue;

            bool wallLayers = first.Product.ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE";
            bool directLayerSet = first.Native != null && (CurrentProfile
                ? first.Element.CategoryId == -2000035
                : first.Element.CategoryId == -2001300);
            int relatingMaterialId = layerSet.LayerSetId;
            if (!directLayerSet)
            {
                bool flipped = wallLayers && first.Element.SerializedWallFlipped == true;
                // a ceiling's usage is not flipped (the direction sense stays true for a
                // ceiling); a building pad is not a Floor, so it stays true as well
                bool negative = wallLayers ? !flipped
                    : CurrentProfile && (first.Product.ifcType == "IFCCOVERING" || first.Element.CategoryId == -2001263);
                double half = layerSet.TotalThicknessMm / 2;
                string usageOffset = !wallLayers ? CurrentProfile && first.Element.CategoryId == -2001263 ? "-0." : "0."
                    : StepWriter.RealFromMillimetres(flipped ? -half : half);
                relatingMaterialId = w.Add("IFCMATERIALLAYERSETUSAGE",
                    $"{R(layerSet.LayerSetId)},.{(wallLayers ? "AXIS2" : "AXIS3")}.,"
                    + $".{(negative ? "NEGATIVE" : "POSITIVE")}.,"
                    + usageOffset);
            }
            var relatedProducts = associated.Select(item =>
            {
                layerAssociatedElementIds.Add(item.ElementId);
                layerUsageProductEntities.Add(item.Product.entityId);
                return R(item.Product.entityId);
            }).ToList();
            w.Add("IFCRELASSOCIATESMATERIAL",
                $"{S(IfcGuid.FromName($"material-layers:{group.Key}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(relatedProducts)},{R(relatingMaterialId)}");
        }

        // The IfcSlab (ROOF) of a roof holds its body and takes the first layer material of the
        // roof type for it.
        foreach (var (roofId, slabEntityId) in roofSlabParts)
            if (exportedIfcElements.TryGetValue(roofId, out var slabRoof))
                CopyUniformStyleSource(bodyStyles, slabRoof.entityId, slabEntityId);

        var directMaterialProducts = new Dictionary<string,
            (List<int> MaterialElementIds, List<int> ProductIds)>();
        var firstMaterialTypes = new HashSet<(int TypeId, int SymbolId, string IfcType, int SystemTypeId)>();
        var pieceIdsBySource = new Dictionary<Element, List<(int Material, int Style, int Node)>>(ReferenceEqualityComparer.Instance);
        var typeOnlyMaterialProducts = new Dictionary<string, List<int>>();
        foreach (var (elementId, product) in exportedIfcElements)
        {
            if (layerAssociatedElementIds.Contains(elementId)
                || !elemById.TryGetValue(elementId, out var element)
                || element.CategoryId == -2001340
                || CurrentProfile && product.ifcType == "IFCWALL"
                || CurrentProfile && product.ifcType == "IFCFLOWSEGMENT"
                || CurrentProfile && (product.ifcType is "IFCSTAIR" or "IFCOPENINGELEMENT"
                    || product.ifcType == "IFCCURTAINWALL" && element.CategoryId == -2000011
                    || product.ifcType == "IFCROOF" && roofContainerChildren.ContainsKey(elementId)
                    || element.CategoryId == -2000181))
                continue;

            // The ceiling export sends native ceilings to the host-object material export, not the
            // family-product reference census below.
            if (product.ifcType == "IFCCOVERING" && element.CategoryId == -2000038
                && element.SerializedSystemTypeId is > 0
                && elemById.TryGetValue(element.SerializedSystemTypeId.Value, out var ceilingType)
                && ceilingType.SerializedSystemTypeClassId == 646
                && ceilingType.CategoryId == -2000038)
                continue;

            // A family product can use several authored materials.
            var sources = new List<Element> { element };
            var linkedSourceIds = element.Parameters
                .Where(parameter => parameter.Id is -1002050 or -1002052 or -1002000)
                .Select(parameter => parameter.Value).OfType<int>()
                .Concat([element.TypeId, element.FamilyTypeId,
                    element.Transform?.SymbolId ?? 0])
                .Where(id => id > 0).Distinct();
            foreach (int sourceId in linkedSourceIds)
                if (elemById.TryGetValue(sourceId, out var source)
                    && !ReferenceEquals(source, element))
                    sources.Add(source);
            // The current profile exports the geometry of the instance's own FamilySymbol
            // (the computed symbol of the instance), which carries the materials set on the instance: it is the
            if (CurrentProfile && element.ValidatedOriginalFamilySymbolId is > 0 and int ownSymbolId
                && elemById.TryGetValue(ownSymbolId, out var ownSymbol) && !ReferenceEquals(ownSymbol, element))
            {
                sources.Remove(ownSymbol);
                sources.Add(ownSymbol);
            }

            var candidateIds = new List<int>();
            foreach (var source in sources)
            {
                if (source.Geometry?.GStyleElemId is > 0)
                    candidateIds.Add(source.Geometry.GStyleElemId);
                candidateIds.AddRange(source.Parameters
                    .Where(parameter => parameter.Definition?.Name?.Contains(
                        "MATERIAL", StringComparison.OrdinalIgnoreCase) == true)
                    .Select(parameter => parameter.Value).OfType<int>());
                candidateIds.AddRange(source.References ?? Enumerable.Empty<int>());
                candidateIds.AddRange((source.Geometry?.Faces ?? []).Select(face => face.RenderStyleId).OfType<int>().Where(id => id > 0));
            }

            var materialElementIds = candidateIds.Distinct()
                .Where(candidateId => elemById.TryGetValue(candidateId, out var candidate)
                    && IsSerializedMaterial(candidate))
                .Order()
                .ToList();
            // The instance's own material values replace the values of the same parameters on its
            // type and symbol: the references of those records still hold the replaced defaults.
            {
                var instanceValues = element.Parameters.Select(parameter => parameter.Value).OfType<int>().ToHashSet();
                var overridden = new HashSet<int>();
                var kept = new HashSet<int>();
                foreach (var source in sources.Skip(1))
                    foreach (var parameter in source.Parameters)
                    {
                        if (parameter.Value is not int value) continue;
                        if (element.Parameters.Any(own => own.Id == parameter.Id && own.Value is int ownValue && ownValue > 0 && elemById.TryGetValue(ownValue, out var ownMaterial) && IsSerializedMaterial(ownMaterial))) overridden.Add(value);
                        else kept.Add(value);
                    }
                materialElementIds.RemoveAll(id => overridden.Contains(id) && !kept.Contains(id) && !instanceValues.Contains(id));
            }

            // The geometry read is that of the symbol the instance places (the last source that has
            // geometry), else its own.
            Element? geometrySource = element.CategoryId is not (-2000011 or -2000032 or -2000035 or -2000038)
                && (CurrentProfile || element.CategoryId != -2001300)
                ? sources.Skip(1).LastOrDefault(source => source.Geometry?.Faces is { Count: > 0 })
                    ?? (element.Geometry?.Faces is { Count: > 0 } ? element : null)
                : null;
            // The current profile: an instance whose own body differs from its symbol's exports
            // that body (usesInstanceGeometry), and its materials are those of the solids of that
            // one body, not the union of the materials of the instance.
            bool pieceBased = false;
            if (CurrentProfile && geometrySource != null)
            {
                bool ownBody = !ReferenceEquals(geometrySource, element) && UsesInstanceGeometry(element, geometrySource);
                if (ownBody) geometrySource = element;
                // Instances of one type share the symbol body: its solids are read once.
                if (!pieceIdsBySource.TryGetValue(geometrySource, out var pieces))
                    pieceIdsBySource[geometrySource] = pieces = PieceMaterials(geometrySource.Geometry!,
                        id => elemById.TryGetValue(id, out var m) && IsSerializedMaterial(m),
                        style => info.GraphicsStyles?.GetValueOrDefault(style).Material ?? 0);
                // getBestMaterialIdFromParameter: a solid without a face material of a structural
                // category takes the Structural Material parameter of the element or its type.
                int? structuralFallback = null;
                if (pieces.Any(piece => piece.Material == 0) && element.CategoryId is -2001330 or -2001320 or -2001300 or -2001263)
                {
                    int? structural = sources.Select(source => source.Parameters
                            .FirstOrDefault(parameter => parameter.Id == -1005500 && parameter.StorageType == StorageType.ElementId)?.Value as int?)
                        .FirstOrDefault(id => id is > 0 && elemById.TryGetValue(id.Value, out var m) && IsSerializedMaterial(m));
                    if (structural is int structuralMaterial)
                    {
                        structuralFallback = structuralMaterial;
                        pieces = pieces.Select(piece => piece.Material == 0 ? (structuralMaterial, piece.Style, piece.Node) : piece).ToList();
                    }
                }
                int keyTypeId = element.FamilyTypeId > 0 ? element.FamilyTypeId : element.TypeId;
                int keySystemTypeId = elemById.TryGetValue(keyTypeId, out var keyType)
                    ? ResolveTypeKeySystemTypeId(element, keyType) : 0;
                bool firstOfType = ownBody || ReferenceEquals(geometrySource, element)
                    || firstMaterialTypes.Add((keyTypeId, geometrySource.Id, product.ifcType, keySystemTypeId));
                // The body data names a solid after the category of its
                // graphics style, else after its material, "<Unnamed>" (no leading space, unlike
                // the material) for the null one.
                materialElementIds = firstOfType && pieces.Count > 1
                    ? pieces.OrderBy(piece => GraphicsStyleCategoryName(piece.Style)
                            ?? (piece.Material == 0 ? "<Unnamed>" : ResolveMaterialName(piece.Material, null, elemById)),
                        StringComparer.Ordinal).ThenBy(piece => piece.Material).Select(piece => piece.Material).ToList()
                    : pieces.Select(piece => piece.Material).Distinct().Order().ToList();
                int? pieceSystemMaterial = SystemTypeMaterialId(element);
                if (pieceSystemMaterial is int systemMaterial)
                    materialElementIds = [systemMaterial];
                // The Body items follow the solids in their order, each in the best material of its
                // own solid.
                bodyStyles.Solids[product.entityId] = pieceSystemMaterial is int solidSystemMaterial
                    ? pieces.Select(_ => solidSystemMaterial).ToList() : pieces.Select(piece => piece.Material).ToList();
                bodyStyles.Rules[product.entityId] = (pieceSystemMaterial, structuralFallback);
                pieceBased = true;
            }
            if (geometrySource != null && !pieceBased)
            {
                var faceMaterialIds = sources.SelectMany(source => source.Geometry?.Faces ?? [])
                    .Select(face => face.RenderStyleId).OfType<int>().Where(id => id > 0).ToHashSet();
                if (faceMaterialIds.Count > 0)
                    materialElementIds.RemoveAll(id => !faceMaterialIds.Contains(id));
            }

            var parameterMaterialIds = ParameterMaterialIds(element)
                ?? ParameterMaterialIds(element.TypeId > 0
                    && elemById.TryGetValue(element.TypeId, out var typeElement) && !ReferenceEquals(typeElement, element)
                    ? typeElement : null);
            if (parameterMaterialIds != null && !pieceBased)
            {
                bool hasNull = parameterMaterialIds.Contains(0);
                materialElementIds = (hasNull ? new List<int> { 0 } : new List<int>())
                    .Concat(parameterMaterialIds.Where(id => id > 0 && elemById.TryGetValue(id, out var m)
                        && IsSerializedMaterial(m)).Concat(materialElementIds).Distinct().Order())
                    .ToList();
            }
            if (geometrySource != null && !pieceBased
                && HasUnstyledSolid(geometrySource.Geometry!)
                && !materialElementIds.Contains(0))
                materialElementIds.Insert(0, 0);
            if (CurrentProfile && product.ifcType == "IFCCOVERING" && element.CategoryId == -2008122)
            {
                bool IsMaterialElement(int id) => elemById.TryGetValue(id, out var m) && IsSerializedMaterial(m);
                // SystemMaterialIsMain: the Material parameter of the element or its type, then
                // that of the system type, then the faces.
                int? bestInsulationMaterial = FirstParameterMaterialId(element, IsMaterialElement)
                    ?? (element.TypeId > 0 && elemById.TryGetValue(element.TypeId, out var insulationType)
                        && !ReferenceEquals(insulationType, element)
                        ? FirstParameterMaterialId(insulationType, IsMaterialElement) : null)
                    ?? SystemTypeMaterialId(element)
                    ?? DominantFaceMaterialId(element.Geometry?.Faces ?? [], IsMaterialElement);
                materialElementIds = bestInsulationMaterial is int best ? [best] : [];
            }
            if (materialElementIds.Count == 0) continue;

            string materialKey = string.Join(',', materialElementIds);
            if (!directMaterialProducts.TryGetValue(materialKey, out var association))
                association = (materialElementIds, new List<int>());
            if (pieceBased && product.ifcType == "IFCSLAB" && element.CategoryId == -2001300)
                (typeOnlyMaterialProducts.TryGetValue(materialKey, out var typeOnly)
                    ? typeOnly : typeOnlyMaterialProducts[materialKey] = []).Add(product.entityId);
            else
                association.ProductIds.Add(product.entityId);
            directMaterialProducts[materialKey] = association;
        }

        var relatingMaterialByProductEntity = new Dictionary<int, int>();
        var directRelationByRelating = new Dictionary<int, (int Index, string GuidArg, List<int> Products)>();
        foreach (var (materialKey, association) in directMaterialProducts)
        {
            var materialIds = association.MaterialElementIds
                .Select(materialElementId => materialElementId == 0
                    ? EnsureUnnamedMaterial() : EnsureMaterial(materialElementId)).ToList();
            int relatingMaterialId = materialIds.Count == 1
                ? materialIds[0]
                : w.Add("IFCMATERIALLIST", StepWriter.List(materialIds.Select(R)));
            foreach (int productEntityId in association.ProductIds)
                relatingMaterialByProductEntity[productEntityId] = relatingMaterialId;
            foreach (int productEntityId in typeOnlyMaterialProducts.GetValueOrDefault(materialKey) ?? [])
                relatingMaterialByProductEntity[productEntityId] = relatingMaterialId;
            if (association.ProductIds.Count > 0)
            {
                string guidArg = S(IfcGuid.FromName($"materials:{materialKey}"));
                directRelationByRelating[relatingMaterialId] = (w.EntityCount, guidArg, association.ProductIds);
                w.Add("IFCRELASSOCIATESMATERIAL",
                    $"{guidArg},{R(ownerHistId)},$,$,"
                    + $"{StepWriter.List(association.ProductIds.Select(R))},{R(relatingMaterialId)}");
            }
        }

        // True when a solid of the geometry has no face with a material (GFace.m_renderStyleId
        // unset).
        static bool HasUnstyledSolid(GeometryData geometry)
        {
            var groups = geometry.BrepSolids is { Count: > 0 } solids
                ? solids.Select(solid => solid.FaceIndices.Where(index => index >= 0 && index < geometry.Faces.Count).ToList())
                : [Enumerable.Range(0, geometry.Faces.Count).ToList()];
            return groups.Any(faceIndices => !faceIndices.Any(index => geometry.Faces[index].RenderStyleId is > 0));
        }

        static List<int>? ParameterMaterialIds(Element? source)
        {
            if (source == null) return null;
            List<int>? ids = null;
            foreach (var parameter in source.Parameters)
            {
                if (parameter.StorageType != StorageType.ElementId || parameter.Value is not int id) continue;
                if (!ApiParameterDefinitions.TryGet(parameter.Id, out _, out int groupId, out string dataType)
                    || groupId != -5000105 && !dataType.StartsWith("autodesk.spec.reference:material", StringComparison.Ordinal))
                    continue;
                (ids ??= new List<int>()).Add(id > 0 ? id : 0);
            }
            return ids;
        }

        // The Material (-1002107) of the MEP system type a pipe or duct product belongs to; null
        // without one.
        int? SystemTypeMaterialId(Element product)
        {
            int systemTypeId = ResolveTypeKeySystemTypeId(product, product);
            if (systemTypeId <= 0 || !elemById.TryGetValue(systemTypeId, out var systemType)) return null;
            foreach (var parameter in systemType.Parameters)
                if (parameter.Id == -1002107 && parameter.StorageType == StorageType.ElementId
                    && parameter.Value is int material and > 0
                    && elemById.TryGetValue(material, out var materialElement) && IsSerializedMaterial(materialElement))
                    return material;
            return null;
        }

        // The first material-reference parameter of the element whose value is a material element.
        static int? FirstParameterMaterialId(Element source, Func<int, bool> isMaterial) =>
            ParameterMaterialIds(source)?.Where(id => id > 0 && isMaterial(id)).Select(id => (int?)id).FirstOrDefault();

        // The body export: the material of the faces with the greatest
        // total area (equal areas: the smaller element id).
        static int? DominantFaceMaterialId(IEnumerable<GeoFace> faces, Func<int, bool> isMaterial)
        {
            var areaByMaterial = new Dictionary<int, double>();
            foreach (var face in faces)
                if ((face.RenderStyleId ?? face.NestedRenderStyleId) is > 0 and int id && isMaterial(id))
                    areaByMaterial[id] = areaByMaterial.GetValueOrDefault(id) + WallExtrusion.FaceArea(face);
            return areaByMaterial.Count == 0 ? null
                : areaByMaterial.OrderByDescending(pair => pair.Value).ThenBy(pair => pair.Key).First().Key;
        }

        // The body export: every solid of the exported geometry gets its best material
        // (the dominant face material, else the null material, id 0); one entry per solid, in the
        // order of the solids.
        static List<(int Material, int Style, int Node)> PieceMaterials(GeometryData geometry, Func<int, bool> isMaterial, Func<int, int> styleMaterial)
        {
            var pieces = geometry.Faces.Where(face => face.GeometryNode > 0).GroupBy(face => face.GeometryNode)
                .Select(node => node.ToList()).ToList();
            var unknownNode = geometry.Faces.Select((face, index) => (face, index)).Where(item => item.face.GeometryNode == 0)
                .Select(item => item.index).ToHashSet();
            if (unknownNode.Count > 0)
            {
                var shells = geometry.BrepSolids is { Count: > 0 } solids
                    ? solids.Select(solid => solid.FaceIndices.Where(index => unknownNode.Contains(index)).ToList())
                        .Where(indices => indices.Count > 0).ToList()
                    : [];
                var inShell = shells.SelectMany(indices => indices).ToHashSet();
                pieces.AddRange(shells.Select(indices => indices.Select(index => geometry.Faces[index]).ToList()));
                // (faces outside every shell were never a piece of their own: only a geometry
                // without shells has them all)
                var rest = unknownNode.Where(index => !inShell.Contains(index)).Select(index => geometry.Faces[index]).ToList();
                if (rest.Count > 0 && geometry.BrepSolids is not { Count: > 0 }) pieces.Add(rest);
            }
            var ids = new List<(int Material, int Style, int Node)>();
            foreach (var faces in pieces)
                if (faces.Count > 0)
                    ids.Add((DominantFaceMaterialId(faces, isMaterial)
                        ?? (faces[0].GeometryStyle > 0 && styleMaterial(faces[0].GeometryStyle) is > 0 and int fromStyle
                            && isMaterial(fromStyle) ? fromStyle : 0), Math.Max(faces[0].GeometryStyle, 0),
                        Math.Max(faces[0].GeometryNode, 0)));
            foreach (var (_, ghostStyle, ghostMaterial) in geometry.GhostNodes ?? [])
                ids.Add((ghostMaterial > 0 && isMaterial(ghostMaterial) ? ghostMaterial
                    : ghostStyle > 0 && styleMaterial(ghostStyle) is > 0 and int ghostFromStyle && isMaterial(ghostFromStyle)
                        ? ghostFromStyle : 0, Math.Max(ghostStyle, 0), 0));
            return ids;
        }

        // The name of the category of a graphics style; null for a
        // style without a category or whose category name was not read.
        string? GraphicsStyleCategoryName(int style) =>
            info.GraphicsStyles?.TryGetValue(style, out var graphicsStyle) == true && graphicsStyle.Category is not (0 or -1)
                ? info.CategoryNames?.GetValueOrDefault(graphicsStyle.Category) ?? EnglishCategoryNames.Get(graphicsStyle.Category)
                : null;

        // A material decoded from its shading payload (Element.HasShadingAppearance); colors read
        // from other stored fields do not make a referenced material an authored assignment.
        bool IsSerializedMaterial(Element candidate) =>
            candidate.CategoryId == -2000700
            && (candidate.HasShadingAppearance
                && candidate.Parameters.Any(parameter =>
                    parameter.Definition?.Name == "MATERIAL_PARAM_COLOR"
                    && parameter.Value is int)
                && candidate.Parameters.Any(parameter =>
                    parameter.Definition?.Name == "MATERIAL_PARAM_SHININESS"
                    && parameter.Value is int)
                || CurrentProfile && candidate.SerializedMaterialName is { Length: > 0 });

        // Other pairs keep the earlier rule: the CurveDriver references are the join graph and the
        // connection position follows from the two serialized location curves.
        var exportedWallConnections = new HashSet<(int First, int Second)>();
        var exactWallGlobalIds = _usedExportIds.Select(IfcGuid.ToIfcGuid).ToHashSet(StringComparer.Ordinal);
        int exportedWallConnectionCount = 0, exactWallConnectionCount = 0;
        bool HasExactJoins(int wallId) =>
            elemById.TryGetValue(wallId, out var wall) && wall.SerializedWallEndJoins != null;
        var pathElements = exportedIfcElements
            .Where(entry => entry.Value.ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE" or "IFCCURTAINWALL"
                && exportedStoreyIds.ContainsKey(entry.Key))
            .ToDictionary(entry => entry.Key, entry => entry.Value.entityId);
        void AddWallConnection(int relating, int related, string relatingType, string relatedType, string fallbackKey)
        {
            // The current profile's exporter has no IfcRelConnectsPathElements: none of its
            // references holds one.
            if (CurrentProfile) return;
            int relatingEntity = pathElements[relating];
            int relatedEntity = pathElements[related];
            string relationshipName = $"{exportedGlobalIds[relating]}|{exportedGlobalIds[related]}";
            string? pathGlobalId = exactProjectGlobalId != null
                && exactWallGlobalIds.Contains(exportedGlobalIds[relating])
                && exactWallGlobalIds.Contains(exportedGlobalIds[related])
                    ? WallPathConnectionGlobalId(exactProjectGlobalId, relationshipName, relatedType, relatingType)
                    : null;
            w.Add("IFCRELCONNECTSPATHELEMENTS",
                $"{S(pathGlobalId ?? IfcGuid.FromName(fallbackKey))},{R(ownerHistId)},"
                + $"{S(relationshipName)},{S("Structural")},$,{R(relatingEntity)},"
                + $"{R(relatedEntity)},(),(),.{relatedType}.,.{relatingType}.");
            exportedWallConnectionCount++;
        }

        foreach (var connection in ResolveExactWallConnections(
            pathElements.Keys.Where(HasExactJoins).ToDictionary(id => id, id => elemById[id].SerializedWallEndJoins!),
            pathElements.Keys.Where(id => exportedIfcElements[id].ifcType == "IFCCURTAINWALL").ToHashSet()))
        {
            AddWallConnection(connection.First, connection.Second, connection.FirstType, connection.SecondType,
                $"wall-path:{connection.First}:{connection.Second}:{connection.FirstType}:{connection.SecondType}");
            exactWallConnectionCount++;
        }

        foreach (int wallElementId in wallIfcIds.Keys.Order())
        {
            if (!elemById.TryGetValue(wallElementId, out var wallElement)) continue;
            foreach (int referencedId in wallElement.References ?? Enumerable.Empty<int>())
            {
                if (!wallIfcIds.ContainsKey(referencedId) || referencedId == wallElementId)
                    continue;

                var pair = wallElementId < referencedId
                    ? (wallElementId, referencedId)
                    : (referencedId, wallElementId);
                if (HasExactJoins(pair.Item1) && HasExactJoins(pair.Item2)
                    || !pathElements.ContainsKey(pair.Item1) || !pathElements.ContainsKey(pair.Item2))
                    continue;
                if (!exportedWallConnections.Add(pair)) continue;
                if (!elemById.TryGetValue(pair.Item1, out var relatingWall)
                    || !elemById.TryGetValue(pair.Item2, out var relatedWall)
                    || !TryGetWallPathConnectionTypes(relatingWall, relatedWall,
                        out string relatingType, out string relatedType))
                    continue;
                AddWallConnection(pair.Item1, pair.Item2, relatingType, relatedType,
                    $"wall-path:{pair.Item1}:{pair.Item2}");
            }
        }
        _diag?.WriteLine($"Wall path connections: {exportedWallConnectionCount} (from exact control joins: {exactWallConnectionCount})");

        int storeyRelIdx = 0;
        var spaceEntityIdByRoomId = new Dictionary<int, int>();
        var storeySpaceEntityIds = new Dictionary<int, List<int>>();
        var spaceTypeGuids = WriteSpaces(
            w, ownerHistId, info.Elements, storeyIds, storeyPlacements,
            storeyElevationsMetres, bodySubCtxId, propertySingleValueIds, ResolveActiveRoomPhase(info), spaceEntityIdByRoomId,
            storeySpaceEntityIds);
        // A space is styled like any family body: each solid of its boundary takes its best
        // material.
        var mepSpaceEntities = spaceEntityIdByRoomId
            .Where(pair => elemById.TryGetValue(pair.Key, out var room) && room.CategoryId == MepSpaceCategoryId)
            .Select(pair => pair.Value).ToHashSet();
        foreach (var (spaceEntityId, spaceBoundary) in _spaceBodyGeometry)
        {
            if (CurrentProfile && mepSpaceEntities.Contains(spaceEntityId))
            {
                bodyStyles.Uniform[spaceEntityId] = MepSpaceInteriorsMaterialId;
                continue;
            }
            var spacePieces = PieceMaterials(spaceBoundary, id => elemById.TryGetValue(id, out var m) && IsSerializedMaterial(m),
                style => info.GraphicsStyles?.GetValueOrDefault(style).Material ?? 0);
            bodyStyles.Solids[spaceEntityId] = spacePieces.Select(piece => piece.Material != 0 ? piece.Material : RoomInteriorsMaterialId).ToList();
            bodyStyles.Rules[spaceEntityId] = (null, RoomInteriorsMaterialId);
        }
        // The current profile puts a space into the containment of its storey
        // (it is handed to the level info), in front of the storey's
        // products: no IfcRelAggregates, one relation per storey.
        foreach (var (spaceStoreyId, spaceIds) in storeySpaceEntityIds)
        {
            if (!storeyContents.TryGetValue(spaceStoreyId, out var spaceStoreyList))
                storeyContents[spaceStoreyId] = spaceStoreyList = new List<int>();
            spaceStoreyList.InsertRange(0, spaceIds);
        }
        var openingEntityIds = new HashSet<int>();
        for (int index = 0; index < w.EntityCount; index++)
            if (w.EntityAt(index).Type == "IFCOPENINGELEMENT") openingEntityIds.Add(w.EntityAt(index).Id);
        foreach (var contents in storeyContents.Values) contents.RemoveAll(openingEntityIds.Contains);
        // A family instance in a room (FamInstDesignPropertyManager.m_idRoom) is contained in that
        // room's space instead of the storey; hosted doors and windows keep the storey
        // (the rule of the generic family instance path
        var spaceContents = new Dictionary<int, List<int>>();
        // The current profile tests one point of the instance against the rooms of its phase
        // instead.
        var calculatedRooms = CurrentProfile
            ? ResolveInstanceRoomsCurrent(info.Elements, elemById,
                exportedIfcElements.Select(pair => KeyValuePair.Create(pair.Key, pair.Value.ifcType)),
                info.Elements.Where(level => level.IsNativeLevel).GroupBy(level => level.Id)
                    .ToDictionary(group => group.Key, group => GetElevation(group.First())))
            : null;
        foreach (var (elementId, product) in exportedIfcElements.OrderBy(pair => pair.Key))
        {
            if (product.ifcType is "IFCDOOR" or "IFCWINDOW" or "IFCOPENINGELEMENT"
                || !elemById.TryGetValue(elementId, out var roomElement))
                continue;
            int instanceRoomId = roomElement.SerializedRoomId is > 0 ? roomElement.SerializedRoomId.Value
                : calculatedRooms != null && calculatedRooms.TryGetValue(elementId, out int calculatedRoomId) ? calculatedRoomId : 0;
            if (instanceRoomId <= 0 || !spaceEntityIdByRoomId.TryGetValue(instanceRoomId, out int roomSpaceId))
                continue;
            if (!spaceContents.TryGetValue(roomSpaceId, out var inSpace)) spaceContents[roomSpaceId] = inSpace = new List<int>();
            inSpace.Add(product.entityId);
        }
        // A ceiling that bounds exactly one room is contained in that room's space
        // (SpatialElementGeometryCalculator: the ceiling's lowest horizontal faces meet the room's
        // upper horizontal faces over a positive area).
        var roomsWithBoundary = info.Elements
            .Where(room => room.CategoryId == RoomCategoryId && spaceEntityIdByRoomId.ContainsKey(room.Id)
                && room.SerializedSpaceBoundary is { Faces.Count: > 0 })
            .Select(room => (room.Id, Tops: RoomUpperHorizontalFaces(room.SerializedSpaceBoundary!)))
            .Where(room => room.Tops.Count > 0).ToList();
        foreach (var (elementId, product) in exportedIfcElements.OrderBy(pair => pair.Key))
        {
            if (CurrentProfile || product.ifcType != "IFCCOVERING"
                || !elemById.TryGetValue(elementId, out var ceiling) || ceiling.CategoryId != -2000038
                || ceiling.Geometry is not { Faces.Count: > 0 } ceilingGeometry)
                continue;
            var bottoms = CeilingLowestHorizontalFaces(ceilingGeometry);
            if (bottoms.Count == 0) continue;
            var boundedRooms = roomsWithBoundary.Where(room => room.Tops.Any(top => bottoms.Any(bottom =>
                Math.Abs(bottom.Z - top.Z) <= 0.001 && HorizontalPolygonsOverlap(bottom.Ring, top.Ring, 0.01)))).ToList();
            if (boundedRooms.Count != 1) continue;
            int ceilingSpaceId = spaceEntityIdByRoomId[boundedRooms[0].Id];
            if (!spaceContents.TryGetValue(ceilingSpaceId, out var ceilingsInSpace)) spaceContents[ceilingSpaceId] = ceilingsInSpace = new List<int>();
            ceilingsInSpace.Add(product.entityId);
        }
        var spaceContained = spaceContents.Values.SelectMany(list => list).ToHashSet();
        foreach (var contents in storeyContents.Values) contents.RemoveAll(spaceContained.Contains);
        foreach (var (sid, contents) in storeyContents)
        {
            if (contents.Count == 0) continue;
            string? containmentGlobalId = _storeyLevels.TryGetValue(sid, out var containingLevel)
                ? ResolveExactElementGlobalId(containingLevel, _usedExportIds, StoreyRelContainedInSpatialStructure, CurrentProfile)
                : null;
            string fallbackContainmentGlobalId = IfcGuid.FromName($"rel:contain:{storeyRelIdx++}");
            w.Add("IFCRELCONTAINEDINSPATIALSTRUCTURE",
                $"{S(containmentGlobalId ?? fallbackContainmentGlobalId)},{R(ownerHistId)},$,$,{StepWriter.List(contents.Select(R))},{R(sid)}");
        }
        var spaceGlobalIds = new Dictionary<int, string>();
        for (int index = 0; index < w.EntityCount; index++)
            if (w.EntityAt(index) is { Type: "IFCSPACE" } spaceEntity
                && SplitStepArguments(spaceEntity.Args)[0] is { Length: > 2 } spaceGlobalId)
                spaceGlobalIds[spaceEntity.Id] = spaceGlobalId[1..^1];
        foreach (var (spaceEntityId, inSpace) in spaceContents.OrderBy(pair => pair.Key))
            w.Add("IFCRELCONTAINEDINSPATIALSTRUCTURE",
                $"{S(ContainmentCacheGlobalId(spaceGlobalIds.GetValueOrDefault(spaceEntityId)) ?? IfcGuid.FromName($"space-contain:{spaceEntityId}"))},{R(ownerHistId)},$,$,{StepWriter.List(inSpace.Select(R))},{R(spaceEntityId)}");

        var registeredTypeCommonValues = new Dictionary<int, bool?>(componentTypeIsExternalByElementId);
        foreach (var (id, value) in ResolveRegisteredFamilyTypeCommonValues(
            elemById, elementIdOccurrenceCounts, exportedIfcElements))
            registeredTypeCommonValues.TryAdd(id, value);
        foreach (var (id, value) in openingTypeIsExternal)
            if (!registeredTypeCommonValues.TryGetValue(id, out var validated) || validated == null)
                registeredTypeCommonValues[id] = value;
        int typeObjectsStart = w.EntityCount;
        var typedProducts = exportedIfcElements;
        if (roofSlabParts.Count > 0 || stairBodyParts.Count > 0)
        {
            typedProducts = new(exportedIfcElements);
            foreach (var (roofId, slabEntityId) in roofSlabParts)
                typedProducts[-roofId] = (slabEntityId, 0, "IFCSLAB");
            // The IfcStair that holds the body of a legacy stair has the type of the stair.
            foreach (var (stairId, bodyEntityId) in stairBodyParts)
                typedProducts[-stairId] = (bodyEntityId, 0, "IFCSTAIR");
        }
        var exactTypeGuids = WriteTypeObjectsAndRelDefinesByTypeCore(
            w, ownerHistId, elemById, typedProducts, propertySingleValueIds,
            registeredTypeCommonValues, CurrentProfile);
        // The sub-elements of a curtain wall are exported inside the call of the wall
        // (the curtain-wall export), in the order of its grid, and share the material state of the
        // body export.
        var curtainOrders = CurrentProfile
            ? CurtainExportOrdersCurrent(exactCurtainChildren.Concat(roofContainerChildren), elemById, exportedIfcElements.ContainsKey)
            : [];
        if (curtainOrders.Count > 0)
        {
            var curtainRank = new Dictionary<int, (int HostId, int Position)>();
            foreach (var (curtainHostId, order) in curtainOrders)
                for (int position = 0; position < order.Count; position++)
                    curtainRank.TryAdd(order[position], (curtainHostId, position));
            var elementIdByEntity = new Dictionary<int, int>();
            foreach (var (elementId, product) in exportedIfcElements) elementIdByEntity.TryAdd(product.entityId, elementId);
            int panelTypes = ApplyCurtainPanelTypeOrderCurrent(w, elementIdByEntity, curtainRank);
            _diag?.WriteLine($"The current profile curtain panel types in export order: {panelTypes}; curtain hosts {curtainOrders.Count}, "
                + $"with the stored panel order {curtainOrders.Count(item => elemById[item.HostId].SerializedCurtainPanelOrder != null)}");
        }
        AssociateTypeObjectMaterials(w, ownerHistId, typeObjectsStart, relatingMaterialByProductEntity,
            CurrentProfile ? new HostLayerSets(layerSetByProductEntity, layerUsageProductEntities,
                typeOnlyMaterialProducts.Values.SelectMany(products => products).ToHashSet()) : null,
            CurrentProfile ? directRelationByRelating : null);
        _diag?.WriteLine($"Timing: relations and types done at {exportClock.Elapsed.TotalSeconds:F1}s");
        var systemMembers = WriteDistributionPorts(w, ownerHistId, elemById, exportedIfcElements, CurrentProfile);
        WriteMepSystems(w, ownerHistId, buildingId, elemById, systemMembers);
        WriteModelGroups(w, ownerHistId, elemById, exportedIfcElements);
        WriteRebarSystemGroups(w, ownerHistId, elemById);
        if (CurrentProfile) WriteInsulationCoverings(w, ownerHistId, elemById, exportedIfcElements, exportedGlobalIds);

        foreach (var (typeId, globalId) in spaceTypeGuids)
            exactTypeGuids.Add(typeId, globalId);

        // Write output The current profile (initHeader): Coordination View 2.0, with the take-off
        // add-on view when base quantities are exported; the file is named after the project number
        // and the organization is the project's.
        string desc = CurrentProfile ? $"ViewDefinition [CoordinationView_V2.0{(BaseQuantities ? ", QuantityTakeOffAddOnView" : "")}]"
            : "ViewDefinition [CoordinationView]";
        string headerFileName = CurrentProfile && ProjectInformationTextCurrent(info, ProjectNumberParameterId, info.ProjectInfo?.Number) is { Length: > 0 } projectNumberText
            ? projectNumberText : "output.ifc";
        string headerOrganization = CurrentProfile ? ProjectInformationTextCurrent(info, ProjectOrganizationNameParameterId, info.ProjectInfo?.OrganizationName) ?? "" : "";
        string appName = $"RvtIO {info.Metadata?.RevitVersion ?? ""}".Trim();
        var exactGlobalIds = _usedExportIds.Select(IfcGuid.ToIfcGuid).ToHashSet(StringComparer.Ordinal);
        var productElementIdByEntity = new Dictionary<int, int>();
        foreach (var (elementId, product) in exportedIfcElements)
            productElementIdByEntity.TryAdd(product.entityId, elementId);
        foreach (var (roofId, slabEntityId) in roofSlabParts)
            productElementIdByEntity.TryAdd(slabEntityId, roofId);
        var levelIdByProductElementId = exportedStoreyIds
            .Where(entry => _storeyLevels.ContainsKey(entry.Value))
            .ToDictionary(entry => entry.Key, entry => _storeyLevels[entry.Value].Id);
        var openingOrderKeys = new Dictionary<int, (int Group, int Major, int Minor)>();
        var exactOpeningGlobalIds = ApplyDoorWindowOpeningIdentities(
            w, elemById, productElementIdByEntity, levelIdByProductElementId, exactGlobalIds, CurrentProfile, openingOrderKeys);
        _diag?.WriteLine($"Door/window opening GlobalIds from revit-ifc: {exactOpeningGlobalIds.Count}");
        var cutOpeningGlobalIds = ApplyCutOpeningIdentities(
            w, elemById, productElementIdByEntity, exactGlobalIds, exactOpeningGlobalIds, CurrentProfile, _unbuiltOpeningCuttersCurrent,
            openingOrderKeys);
        _diag?.WriteLine($"Cut opening GlobalIds from revit-ifc: {cutOpeningGlobalIds.Count}");
        exactGlobalIds.UnionWith(exactOpeningGlobalIds);
        exactGlobalIds.UnionWith(cutOpeningGlobalIds);
        if (CurrentProfile) ApplyFireRatingPropertySetsCurrent(w, elemById, exportedIfcElements, ownerHistId, propertySingleValueIds);
        if (CurrentProfile)
        {
            int slopes = ApplySlopePropertySetsCurrent(w, elemById, exportedIfcElements, propertySingleValueIds);
            _diag?.WriteLine($"The current profile Slope properties: {slopes}");
        }
        if (CurrentProfile && Environment.GetEnvironmentVariable("RVTIO_PSET_DIAG") is { Length: > 0 } thermalDiag)
            WriteThermalDiagCurrent(thermalDiag, elemById);
        int exactPropertySets = ApplyPropertySetGlobalIds(w, exactGlobalIds);
        _diag?.WriteLine($"Property set GlobalIds from exact product GlobalIds: {exactPropertySets}");
        var exactTypes = ApplyTypeGlobalIds(w, exactTypeGuids);
        _diag?.WriteLine($"Type GlobalIds from validated native sources: {exactTypes.Types}; exact type relationship GlobalIds: {exactTypes.Relationships}");
        int exactTypePropertySets = ApplyTypePropertySetGlobalIds(w, exactTypeGuids);
        _diag?.WriteLine($"Type property set GlobalIds from exact written type GlobalIds: {exactTypePropertySets}");
        int ownPlanarBodies = ApplyOwnWallPlanarBodies(w, elemById, elementIdOccurrenceCounts,
            productElementIdByEntity, bodySubCtxId, bldgLocalPlacementId, axisId);
        _diag?.WriteLine($"Own closed planar wall bodies without IFC void operands: {ownPlanarBodies}");
        if (CurrentProfile && BaseQuantities)
        {
            // A room is not in the product table: its space entity belongs to it.
            var quantityElementByEntity = new Dictionary<int, int>(productElementIdByEntity);
            foreach (var (roomId, spaceEntityId) in spaceEntityIdByRoomId) quantityElementByEntity.TryAdd(spaceEntityId, roomId);
            int quantitySets = ApplyCurrentBaseQuantities(w, elemById, quantityElementByEntity, exportedIfcElements, ownerHistId, StoreyHeightsCurrent());
            _diag?.WriteLine($"The current profile BaseQuantities sets: {quantitySets}");
        }
        if (CurrentProfile)
        {
            var openingRecess = OpeningRecessEntitiesCurrent(w, elemById, productElementIdByEntity, exportedIfcElements,
                openingOrderKeys, _recessOpeningEntityIds);
            int wallExtrusions = ApplyCurrentWallExtrusions(w, elemById, productElementIdByEntity, axisSubCtxId);
            _diag?.WriteLine($"The current profile wall extrusions in the frame of the axis: {wallExtrusions}");
            int doorWindowOpenings = ApplyCurrentDoorWindowOpenings(w, elemById, productElementIdByEntity);
            _diag?.WriteLine($"The current profile door and window openings from the cut loops of the symbols: {doorWindowOpenings}");
            int typeObjects = ApplyCurrentTypeObjects(w, elemById, productElementIdByEntity);
            int classifications = ApplyCurrentClassifications(w, ownerHistId, elemById, productElementIdByEntity);
            _diag?.WriteLine($"The current profile Uniformat classification references: {classifications}");
            int openingAttributes = ApplyCurrentOpeningAttributes(w, openingRecess, exactOpeningGlobalIds);
            // (before the empty-string pass: the colours and styled items it writes are spelled
            // like the others) The sub-elements of a curtain wall are exported inside the call of
            // the wall (the curtain-wall export), in the order of its grid.
            foreach (var (stairId, bodyEntityId) in stairBodyParts)
            {
                int container = exportedIfcElements[stairId].entityId;
                if (bodyStyles.Uniform.TryGetValue(container, out int uniform)) bodyStyles.Uniform[bodyEntityId] = uniform;
                if (bodyStyles.Solids.TryGetValue(container, out var solids)) bodyStyles.Solids[bodyEntityId] = solids;
                if (bodyStyles.Rules.TryGetValue(container, out var rule)) bodyStyles.Rules[bodyEntityId] = rule;
            }
            foreach (var (_, curtainOrder) in curtainOrders)
                bodyStyles.Sequences.Add(curtainOrder.Select(id => exportedIfcElements[id].entityId).ToList());
            var styleCounters = new SortedDictionary<string, int>(StringComparer.Ordinal);
            var styleTraceCounts = new Dictionary<string, int>();
            var styled = ApplyCurrentBodyStyles(w, bodyStyles, _bodyItemOrigins, NodeMaterials,
                materialElementId => EnsureSurfaceStyle(materialElementId, ResolveMaterialName(materialElementId, null, elemById)),
                styleCounters, _diag == null ? null : (productEntityId, productType, detail) =>
                {
                    int traced = styleTraceCounts.GetValueOrDefault(productType);
                    if (traced >= 6) return;
                    styleTraceCounts[productType] = traced + 1;
                    _diag.WriteLine($"The current profile body style trace {productType} element={productElementIdByEntity.GetValueOrDefault(productEntityId)}: {detail}");
                });
            _diag?.WriteLine($"The current profile body styles: {styled.StyledItems} items of {styled.Products} products, "
                + $"{styled.Assignments} style assignments, {styled.Skipped} items without a matching solid");
            _diag?.WriteLine("The current profile body style paths (class:path = items, products without a material source are noSource): "
                + string.Join(", ", styleCounters.Select(pair => $"{pair.Key}={pair.Value}")));
            int emptyStrings = ApplyCurrentEmptyStrings(w);
            _diag?.WriteLine($"The current profile type objects: {typeObjects}, opening ObjectType/Tag: {openingAttributes}, empty strings: {emptyStrings} entities");
            int materialRelations = ApplyCurrentMaterialRelationGlobalIds(w);
            _diag?.WriteLine($"The current profile material relation GlobalIds: {materialRelations}");
            int sharedValues = ApplyCurrentPropertyValueCache(w);
            _diag?.WriteLine($"The current profile property value cache: {sharedValues} pooled values dropped");
            // Native caches use the original string, before the text rule truncates the emitted value.
            int limitedStrings = ApplyCurrentStringPropertyByteLimits(w);
            _diag?.WriteLine($"The current profile string property byte limits: {limitedStrings} values shortened");
            FinalizeUnitAssignmentCurrent(w, unitsCurrent!);
        }
        if (CurrentProfile) ApplyCurrentOpeningOrder(w, openingOrderKeys);
        w.RewriteArguments(IfcLengthUnit.Converter(_unitFamily));
        w.WriteTo(output, headerFileName, "IFC2X3", desc, appName, headerOrganization);

        ExportedProducts = exportedCount;
        _diag?.WriteLine($"IFC export: {exportedCount} elements exported, {skippedCount} skipped (faces:{withFaces}, bbox:{withBbox}, no-geom:{noGeom})");
        _diag?.WriteLine($"IFC openings: box={_dbgOpenOk} no-host={_dbgOpenNoHost} no-param={_dbgOpenNoParam}");
        _diag?.WriteLine($"IFC family complex cutters: available={familyCutAvailable} used={familyCutUsed}");
        _diag?.WriteLine($"IFC wall path connections: {exportedWallConnectionCount}");
        _diag?.WriteLine(
            $"IFC Pset_MemberCommon.Span provenance: runtime(INSTANCE_LENGTH_PARAM via BRep)="
            + $"{_spanRuntimeInstanceLengthCount} "
            + $"calculator(explicit zero Span via BRep)={_spanBrepExactCount} "
            + $"authored(parameter)={_spanExactCount} "
            + $"total={_spanRuntimeInstanceLengthCount + _spanBrepExactCount + _spanExactCount}");
        _diag?.WriteLine(
            $"IFC openings without Pset_OpeningElementCommon/Pset_QuantityTakeOff: "
            + $"{_openingsWithoutPsetCount}");
        _diag?.WriteLine(
            $"IFC main-loop Reference property omissions (nameless element): "
            + $"{_mainLoopReferenceOmittedCount}");
        _diag?.WriteLine(
            "IFC geometry-less element products suppressed: "
            + $"{_suppressedGeometrylessProductsByClass.Values.Sum()}"
            + (_suppressedGeometrylessProductsByClass.Count > 0
                ? " - " + string.Join(", ", _suppressedGeometrylessProductsByClass
                    .Select(entry => $"{entry.Key}={entry.Value}"))
                : ""));
        _diag?.WriteLine(
            "IFC open-surface hosted-cutter proxy products suppressed: "
            + $"{_suppressedOpenSurfaceHostedCutterProxyProducts}");
        _diag?.WriteLine(
            "IFC serialized-unplaced-owner proxy products suppressed: "
            + $"{_suppressedUnplacedOwnerProxyProducts}");
        _diag?.WriteLine(
            "IFC phantom-storey wall products suppressed: "
            + $"{_suppressedPhantomStoreyWallProductsByClass.Values.Sum()}"
            + (_suppressedPhantomStoreyWallProductsByClass.Count > 0
                ? " - " + string.Join(", ", _suppressedPhantomStoreyWallProductsByClass
                    .Select(entry => $"{entry.Key}={entry.Value}"))
                : ""));
        _diag?.WriteLine(
            "IFC phantom-storey wall hosted openings suppressed (cascade): "
            + $"{_suppressedPhantomStoreyWallHostedOpeningCount}");
    }

    internal readonly record struct WallConnection(int First, int Second, string FirstType, string SecondType);

    /// <summary>Only pairs of walls that both have exact joins count.</summary>
    internal static List<WallConnection> ResolveExactWallConnections(
        IReadOnlyDictionary<int, IReadOnlyList<TfBlockDeserializer.WallEndJoin>> joinsByWall,
        IReadOnlySet<int> curtainWalls)
    {
        static string Location(int end) => end switch { 0 => "ATSTART", 1 => "ATEND", _ => "ATPATH" };
        var connections = new SortedSet<WallConnection>(Comparer<WallConnection>.Create((a, b) =>
        {
            int order = a.First.CompareTo(b.First);
            if (order == 0) order = a.Second.CompareTo(b.Second);
            if (order == 0) order = string.CompareOrdinal(a.FirstType, b.FirstType);
            return order != 0 ? order : string.CompareOrdinal(a.SecondType, b.SecondType);
        }));
        foreach (var (wall, joins) in joinsByWall)
            foreach (var join in joins)
            {
                if (join.End is not (0 or 1) || join.ElementId == wall
                    || !joinsByWall.ContainsKey(join.ElementId)
                    || curtainWalls.Contains(join.ElementId))
                    continue;
                string own = Location(join.End), other = Location(join.JoinedEnd);
                connections.Add(wall < join.ElementId
                    ? new WallConnection(wall, join.ElementId, own, other)
                    : new WallConnection(join.ElementId, wall, other, own));
            }
        return connections.ToList();
    }

    internal static bool TryGetWallPathConnectionTypes(Element relatingWall, Element relatedWall,
        out string relatingType, out string relatedType)
    {
        relatingType = relatedType = "";
        if (relatingWall.Location is not { CurveType: "Line", ArcRadius: null } relating
            || relatedWall.Location is not { CurveType: "Line", ArcRadius: null } related)
            return false;

        static bool SamePlanPoint(double[] first, double[] second) =>
            BitConverter.DoubleToInt64Bits(first[0]) == BitConverter.DoubleToInt64Bits(second[0])
            && BitConverter.DoubleToInt64Bits(first[1]) == BitConverter.DoubleToInt64Bits(second[1]);

        static string EndpointType(bool start) => start ? "ATSTART" : "ATEND";

        for (int relatingEndpoint = 0; relatingEndpoint < 2; relatingEndpoint++)
            for (int relatedEndpoint = 0; relatedEndpoint < 2; relatedEndpoint++)
            {
                double[] relatingPoint = relatingEndpoint == 0
                    ? relating.StartPoint : relating.EndPoint;
                double[] relatedPoint = relatedEndpoint == 0
                    ? related.StartPoint : related.EndPoint;
                if (!SamePlanPoint(relatingPoint, relatedPoint)) continue;
                relatingType = EndpointType(relatingEndpoint == 0);
                relatedType = EndpointType(relatedEndpoint == 0);
                return true;
            }

        double ax = relating.EndPoint[0] - relating.StartPoint[0];
        double ay = relating.EndPoint[1] - relating.StartPoint[1];
        double bx = related.EndPoint[0] - related.StartPoint[0];
        double by = related.EndPoint[1] - related.StartPoint[1];
        double qx = related.StartPoint[0] - relating.StartPoint[0];
        double qy = related.StartPoint[1] - relating.StartPoint[1];
        double denominator = ax * by - ay * bx;
        if (denominator == 0) return false;

        double relatingParameter = (qx * by - qy * bx) / denominator;
        double relatedParameter = (qx * ay - qy * ax) / denominator;
        if (relatingParameter < 0 || relatingParameter > 1
            || relatedParameter < 0 || relatedParameter > 1)
            return false;

        static string ParameterType(double parameter) =>
            parameter == 0 ? "ATSTART" : parameter == 1 ? "ATEND" : "ATPATH";

        relatingType = ParameterType(relatingParameter);
        relatedType = ParameterType(relatedParameter);
        return true;
    }

    /// <summary>
    /// The layer-set cache keys native HostObjAttr sets by the own type, not by identical
    /// material/thickness contents.
    /// </summary>
    internal static string MaterialLayerSetGroupKey(
        Element element, string ifcType, IReadOnlyDictionary<int, Element> elements,
        IReadOnlyDictionary<int, int> counts)
    {
        string direction = ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE" ? "AXIS2" : "AXIS3";
        string layers = string.Join(';', (element.Layers ?? [])
            .OrderBy(layer => layer.LayerIndex)
            .Select(layer => $"{layer.MaterialId}:{layer.ThicknessMm.ToString("R", CultureInfo.InvariantCulture)}"));
        string legacy = $"{direction}|{layers}";
        return ResolveValidatedLayerSetName([(element, ifcType)], elements, counts) != null
            ? $"{legacy}|type:{element.SerializedSystemTypeId!.Value.ToString(CultureInfo.InvariantCulture)}"
            : legacy;
    }

    /// <summary>Metadata only: retain layer contents.</summary>
    internal static string? ResolveValidatedLayerSetName(
        IReadOnlyList<(Element Element, string IfcType)> products,
        IReadOnlyDictionary<int, Element> elements,
        IReadOnlyDictionary<int, int> counts)
    {
        int? groupType = null;
        string? name = null;
        foreach (var (element, ifcType) in products)
        {
            if (element.Id <= 0 || counts.GetValueOrDefault(element.Id) != 1 || element.IsBlockOnly
                || element.SerializedSystemTypeId is not > 0 || element.SerializedSystemTypeId == element.Id
                || groupType.HasValue && groupType != element.SerializedSystemTypeId
                || !elements.TryGetValue(element.SerializedSystemTypeId.Value, out var type)
                || counts.GetValueOrDefault(type.Id) != 1 || type.IsBlockOnly
                || type.Id != element.SerializedSystemTypeId || type.CategoryId != element.CategoryId
                || type.SerializedHostTypeLayers is not { Length: > 0 } native
                || string.IsNullOrEmpty(type.ValidatedHostTypeLayerSetName)
                || HasIfcTypeOverride(element) || HasIfcTypeOverride(type)
                || type.Parameters.Any(parameter => ParameterNameEquals(parameter, "IfcMaterialLayerSet.Name")))
                return null;
            bool agrees = (type.SerializedSystemTypeClassId, element.CategoryId, ifcType) switch
            {
                (512, -2000011, "IFCWALL" or "IFCWALLSTANDARDCASE") => true,
                (1915, -2000032 or -2001300, "IFCSLAB") => true,
                (646, -2000038, "IFCCOVERING") => true,
                _ => false,
            };
            if (!agrees || element.Layers == null || element.Layers.Count != native.Length) return null;
            var layers = element.Layers.OrderBy(layer => layer.LayerIndex).ToList();
            for (int index = 0; index < native.Length; index++)
            {
                double width = BitConverter.Int64BitsToDouble(native[index].LayerWidthBits);
                double projectedWidth = Math.Round(width * 304.8, 2);
                if (!double.IsFinite(width) || width <= 0 || !double.IsFinite(projectedWidth)
                    || native[index].RawMaterialId <= 0
                    || layers[index].LayerIndex != index || layers[index].MaterialId != native[index].RawMaterialId
                    || BitConverter.DoubleToInt64Bits(layers[index].ThicknessMm)
                        != BitConverter.DoubleToInt64Bits(projectedWidth))
                    return null;
            }
            groupType = type.Id;
            name = type.ValidatedHostTypeLayerSetName;
        }
        return name;
    }

    internal static string ResolveMaterialName(int materialElementId, string? preferredName,
        IReadOnlyDictionary<int, Element> elements)
    {
        const string UnupgradedAppearance = "Rendering appearance not upgraded";
        static bool IsUsableName([System.Diagnostics.CodeAnalysis.NotNullWhen(true)] string? value) =>
            !string.IsNullOrWhiteSpace(value)
            && !value.Contains(UnupgradedAppearance, StringComparison.Ordinal)
            && !string.Equals(value, "GenericSchema", StringComparison.Ordinal);

        if (!elements.TryGetValue(materialElementId, out var material))
            return !IsUsableName(preferredName)
                ? $"Material {materialElementId}" : preferredName;

        // The naming rule starts from Material.Name, not the rendering asset's display
        // name.
        if (materialElementId > 0 && material.Id == materialElementId
            && material.SerializedMaterialName is { Length: > 0 } ownName
            && !material.Parameters.Any(parameter => ParameterNameEquals(parameter, "IfcName")
                || ParameterNameEquals(parameter, "NameOverride")))
            return ownName;

        // The tagged MATERIAL_NAME field is the authored material display name when it is present.
        string? serializedName = material.Parameters.FirstOrDefault(parameter =>
            parameter.Definition?.Name == "MATERIAL_NAME")?.Value as string;
        if (IsUsableName(serializedName)) return serializedName!;

        if (IsUsableName(material.Name))
            return material.Name;

        // In RVT the material definition references its appearance asset.
        foreach (int referenceId in material.References ?? Enumerable.Empty<int>())
            if (referenceId != materialElementId
                && elements.TryGetValue(referenceId, out var referenced)
                && referenced.TypeId == material.TypeId
                && IsUsableName(referenced.Name))
                return referenced.Name;

        if (IsUsableName(preferredName))
            return preferredName;

        return $"Material {materialElementId}";
    }

    /// <summary>Revit serializes Color.IntegerValue as 0x00BBGGRR.</summary>
    internal static (double Red, double Green, double Blue) DecodePackedMaterialColor(
        int packedColor) =>
        ((packedColor & 0xFF) / 255.0,
            ((packedColor >> 8) & 0xFF) / 255.0,
            ((packedColor >> 16) & 0xFF) / 255.0);

    /// <summary>Export the authored Revit datum curves as IFC grids on every building storey.</summary>
    private static void CreateSerializedGrids(StepWriter w, int ownerHistId, int subCtxId,
        int axisId, IReadOnlyList<Element> elements, IReadOnlyList<int> storeyIfcIds,
        IReadOnlyDictionary<int, int> storeyPlacements,
        IDictionary<int, List<int>> storeyContents)
    {
        var axes = elements
            .Where(element => element.CategoryId == -2000220
                && element.Location is { CurveType: "Line", ArcRadius: null } location
                && location.StartPoint.Length >= 2 && location.EndPoint.Length >= 2
                && location.StartPoint.Take(2).Concat(location.EndPoint.Take(2)).All(double.IsFinite)
                && (location.StartPoint[0] != location.EndPoint[0]
                    || location.StartPoint[1] != location.EndPoint[1]))
            .Select(element => (Element: element, Curve: element.Location!))
            .OrderBy(item => item.Element.Id)
            .ToList();
        if (axes.Count < 2) return;

        const double MachineEpsilon = 2.2204460492503131e-16;

        static double Cross(double ax, double ay, double bx, double by) => ax * by - ay * bx;

        static bool Intersects(LocationCurve first, LocationCurve second)
        {
            double px = first.StartPoint[0], py = first.StartPoint[1];
            double rx = first.EndPoint[0] - px, ry = first.EndPoint[1] - py;
            double qx = second.StartPoint[0], qy = second.StartPoint[1];
            double sx = second.EndPoint[0] - qx, sy = second.EndPoint[1] - qy;
            double denominator = Cross(rx, ry, sx, sy);
            double scale = Math.Max(1.0, new[] { px, py, qx, qy, rx, ry, sx, sy }
                .Select(Math.Abs).Max());
            double roundoff = 128 * MachineEpsilon * scale * scale;
            if (Math.Abs(denominator) <= roundoff) return false;
            double qpx = qx - px, qpy = qy - py;
            double t = Cross(qpx, qpy, sx, sy) / denominator;
            double u = Cross(qpx, qpy, rx, ry) / denominator;
            double parameterRoundoff = 128 * MachineEpsilon
                * Math.Max(1.0, Math.Max(Math.Abs(t), Math.Abs(u)));
            return t >= -parameterRoundoff && t <= 1 + parameterRoundoff
                && u >= -parameterRoundoff && u <= 1 + parameterRoundoff;
        }

        var parent = Enumerable.Range(0, axes.Count).ToArray();
        int Root(int index)
        {
            while (parent[index] != index)
            {
                parent[index] = parent[parent[index]];
                index = parent[index];
            }
            return index;
        }
        void Union(int first, int second)
        {
            int firstRoot = Root(first), secondRoot = Root(second);
            if (firstRoot != secondRoot) parent[secondRoot] = firstRoot;
        }
        for (int first = 0; first < axes.Count; first++)
            for (int second = first + 1; second < axes.Count; second++)
                if (Intersects(axes[first].Curve, axes[second].Curve)) Union(first, second);

        var components = Enumerable.Range(0, axes.Count)
            .GroupBy(Root)
            .Select(group => group.OrderBy(index => axes[index].Element.Id).ToList())
            .OrderBy(group => axes[group[0]].Element.Id)
            .ToList();

        foreach (var component in components)
        {
            var directionGroups = new List<List<int>>();
            foreach (int index in component)
            {
                double dx = axes[index].Curve.EndPoint[0] - axes[index].Curve.StartPoint[0];
                double dy = axes[index].Curve.EndPoint[1] - axes[index].Curve.StartPoint[1];
                double length = Math.Sqrt(dx * dx + dy * dy);
                dx /= length; dy /= length;
                int groupIndex = -1;
                for (int candidate = 0; candidate < directionGroups.Count; candidate++)
                {
                    int representative = directionGroups[candidate][0];
                    double rdx = axes[representative].Curve.EndPoint[0]
                        - axes[representative].Curve.StartPoint[0];
                    double rdy = axes[representative].Curve.EndPoint[1]
                        - axes[representative].Curve.StartPoint[1];
                    double representativeLength = Math.Sqrt(rdx * rdx + rdy * rdy);
                    rdx /= representativeLength; rdy /= representativeLength;
                    if (Math.Abs(Cross(dx, dy, rdx, rdy)) <= 128 * MachineEpsilon)
                    { groupIndex = candidate; break; }
                }
                if (groupIndex < 0) directionGroups.Add([index]);
                else directionGroups[groupIndex].Add(index);
            }
            if (directionGroups.Count < 2) continue;

            foreach (int storeyIfcId in storeyIfcIds)
            {
                var gridAxisIds = new Dictionary<int, int>();
                var curveSetIds = new List<int>();
                foreach (int index in component)
                {
                    var curve = axes[index].Curve;
                    int startId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
                        D(curve.StartPoint[0] * FeetToMetres), D(curve.StartPoint[1] * FeetToMetres)));
                    int endId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
                        D(curve.EndPoint[0] * FeetToMetres), D(curve.EndPoint[1] * FeetToMetres)));
                    int curveId = w.Add("IFCPOLYLINE", StepWriter.List(R(startId), R(endId)));
                    string? datumText = axes[index].Element.Parameters.FirstOrDefault(parameter =>
                        parameter.Id == -1008000
                        && parameter.Value is string value
                        && !string.IsNullOrWhiteSpace(value))?.Value as string;
                    string label = datumText
                        ?? (!string.IsNullOrWhiteSpace(axes[index].Element.Name)
                            ? axes[index].Element.Name : null)
                        ?? axes[index].Element.Id.ToString(CultureInfo.InvariantCulture);
                    gridAxisIds[index] = w.Add("IFCGRIDAXIS", $"{S(label)},{R(curveId)},.T.");
                    curveSetIds.Add(w.Add("IFCGEOMETRICCURVESET", StepWriter.List(R(curveId))));
                }

                int representationId = w.Add("IFCSHAPEREPRESENTATION",
                    $"{R(subCtxId)},{S("FootPrint")},{S("GeometricCurveSet")},"
                    + $"{StepWriter.List(curveSetIds.Select(R))}");
                int shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
                    $"$,$,{StepWriter.List(R(representationId))}");
                int placementId = w.Add("IFCLOCALPLACEMENT",
                    $"{R(storeyPlacements[storeyIfcId])},{R(axisId)}");
                string Axes(IEnumerable<int> indices) =>
                    StepWriter.List(indices.Select(index => R(gridAxisIds[index])));
                var remainingGroups = directionGroups.Skip(2).SelectMany(group => group).ToList();
                string wAxes = remainingGroups.Count > 0 ? Axes(remainingGroups) : "$";
                string componentKey = string.Join(',', component.Select(index => axes[index].Element.Id));
                int gridId = w.Add("IFCGRID",
                    $"{S(IfcGuid.FromName($"grid:{storeyIfcId}:{componentKey}"))},{R(ownerHistId)},"
                    + $"{S("Default Grid")},$,$,{R(placementId)},{R(shapeId)},"
                    + $"{Axes(directionGroups[0])},{Axes(directionGroups[1])},{wAxes}");
                storeyContents[storeyIfcId].Add(gridId);
            }
        }
    }

    private static void CreateDistributionPorts(StepWriter w, int ownerHistId, int axisId,
        IEnumerable<Element> elements,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> exported,
        IReadOnlyDictionary<int, Element> elemById)
    {
        foreach (var elem in elements)
        {
            if (!exported.TryGetValue(elem.Id, out var product)) continue;
            string descriptor = FamilyDescriptor(elem, elemById);
            int portCount = 0;

            if (product.ifcType == "IFCFLOWTERMINAL")
            {
                portCount = 1;
                if (elem.CategoryId == -2001160)
                {
                    int rich = elem.Geometry?.Faces?.Count(f => f.OuterVertices is { Count: >= 3 }) ?? 0;
                    if (rich is >= 80 and < 200) portCount = 6;
                    else if (rich >= 200) portCount = 3;
                    else if (descriptor.Contains("Steel", StringComparison.OrdinalIgnoreCase)
                        || descriptor.Contains("Chrome", StringComparison.OrdinalIgnoreCase))
                        portCount = 2;
                }
            }
            else if (product.ifcType == "IFCBUILDINGELEMENTPROXY")
            {
                string[] applianceHints =
                {
                    "Miele", "Rangehood", "hood enclosure", "Washing Machine",
                    "Tumble Dryer", "Cooktop", "Fridge", "Oven", "Dishwasher"
                };
                if (elem.CategoryId == -2001040
                    && descriptor.Contains("SunModule", StringComparison.OrdinalIgnoreCase))
                    portCount = 1;
                else if (applianceHints.Any(h => descriptor.Contains(h, StringComparison.OrdinalIgnoreCase)))
                    portCount = descriptor.Contains("Rangehood", StringComparison.OrdinalIgnoreCase) ? 2 : 1;
            }

            for (int i = 0; i < portCount; i++)
            {
                string direction;
                if (descriptor.Contains("Steel", StringComparison.OrdinalIgnoreCase)) direction = "SOURCE";
                else if (descriptor.Contains("Chrome", StringComparison.OrdinalIgnoreCase)) direction = "SINK";
                else if (portCount == 1) direction = "SOURCEANDSINK";
                else direction = i < portCount / 2 ? "SINK" : "SOURCE";

                string prefix = direction == "SOURCE" ? "OutPort"
                    : direction == "SINK" ? "InPort" : "Port";
                string name = $"{prefix}_{elem.Id}_{i + 1}";
                string guid = IfcGuid.FromName($"port:{elem.Id}:{i + 1}");
                int placementId = w.Add("IFCLOCALPLACEMENT", $"{R(product.placementId)},{R(axisId)}");
                int portId = w.Add("IFCDISTRIBUTIONPORT",
                    $"{S(guid)},{R(ownerHistId)},{S(name)},{S("Flow")},$,{R(placementId)},$,.{direction}.");
                w.Add("IFCRELCONNECTSPORTTOELEMENT",
                    $"{S(IfcGuid.FromName($"port-rel:{elem.Id}:{i + 1}"))},{R(ownerHistId)},{S($"{elem.Id}|{guid}")},{S("Flow")},{R(portId)},{R(product.entityId)}");
            }
        }
    }

    private int CreateOpeningElement(
        StepWriter w, string globalId, int ownerHistId, string name, int? tagId,
        Element? propertySetReferenceElement,
        IReadOnlyDictionary<int, Element> elementsById,
        int placementId, int shapeId,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        string? validatedReferenceValue = null,
        bool validatedReferenceIsBlocked = false,
        int? exactReferenceValueId = null,
        bool useExactReferenceValueId = false)
    {
        string tagArg = tagId.HasValue
            ? S(tagId.Value.ToString(CultureInfo.InvariantCulture)) : "$";
        int openingId = w.Add("IFCOPENINGELEMENT",
            $"{S(globalId)},{R(ownerHistId)},{S(name)},$,{S("Opening")},{R(placementId)},{R(shapeId)},{tagArg}");

        int? referenceValueId = exactReferenceValueId;
        if (!useExactReferenceValueId
            && !referenceValueId.HasValue
            && tagId.HasValue)
        {
            string? referenceValue = ResolveSyntheticOpeningReferenceValue(
                propertySetReferenceElement, elementsById, validatedReferenceValue,
                validatedReferenceIsBlocked);
            if (referenceValue != null)
            {
                referenceValueId = GetOrAddPropertySingleValue(
                    w, propertySingleValueIds, "Reference",
                    $"IFCIDENTIFIER({S(referenceValue)})");
            }
        }

        if (referenceValueId.HasValue)
        {
            ExportSyntheticOpeningPropertySets(
                w, globalId, openingId, ownerHistId, referenceValueId.Value);
        }
        else
        {
            _openingsWithoutPsetCount++;
        }

        if (CurrentProfile && propertySetReferenceElement != null && tagId == propertySetReferenceElement.Id)
            ExportOpeningManufacturerPropertySetCurrent(
                w, globalId, openingId, ownerHistId, propertySetReferenceElement, elementsById,
                propertySingleValueIds);

        return openingId;
    }

    /// <summary>Resolves explicit Reference with instance/type precedence.</summary>
    internal static string? ResolveSyntheticOpeningReferenceValue(
        Element? propertySetReferenceElement,
        IReadOnlyDictionary<int, Element> elementsById,
        string? validatedReferenceValue,
        bool validatedReferenceIsBlocked = false)
    {
        if (propertySetReferenceElement == null)
            return null;

        Element? sourceType = propertySetReferenceElement.FamilyTypeId > 0
            && elementsById.TryGetValue(
                propertySetReferenceElement.FamilyTypeId, out Element? resolvedType)
                ? resolvedType
                : null;
        ExactIfcStringParameterResult explicitReference =
            ExactIfcStringParameterResolver.ResolveReference(
                propertySetReferenceElement, sourceType);
        if (explicitReference.State == ExactIfcStringParameterState.Blocked)
            return null;
        if (explicitReference.State == ExactIfcStringParameterState.Value)
            return explicitReference.Value;

        if (propertySetReferenceElement.Name == null || validatedReferenceIsBlocked)
            return null;
        return validatedReferenceValue ?? propertySetReferenceElement.Name;
    }

    /// <summary>
    /// Matches ReferenceCalculator's explicit-parameter precedence without changing the IFC
    /// entity's identity fields.
    /// </summary>
    internal static string? ResolveIfcReferenceValue(
        Element element, IReadOnlyDictionary<int, Element> elementsById,
        string? fallbackReferenceValue)
    {
        Element? elementType = element.FamilyTypeId > 0
            && elementsById.TryGetValue(element.FamilyTypeId, out Element? resolvedType)
                ? resolvedType
                : null;
        ExactIfcStringParameterResult explicitReference =
            ExactIfcStringParameterResolver.ResolveReference(element, elementType);
        return explicitReference.State switch
        {
            ExactIfcStringParameterState.Value => explicitReference.Value,
            ExactIfcStringParameterState.Blocked => null,
            _ => fallbackReferenceValue,
        };
    }

    /// <summary>Null when the resolved Reference equals the name of a level of the document (a Reference never equals an unrelated level name), else the value unchanged.</summary>
    internal static string? SuppressLevelNameContamination(
        string? resolvedReferenceValue, IReadOnlySet<string>? levelNames) =>
        resolvedReferenceValue != null
            && levelNames != null
            && levelNames.Contains(resolvedReferenceValue)
                ? null
                : resolvedReferenceValue;

    /// <summary>The Reference value of the quantity take-off set: the validated type Reference of a roof, railing, distribution-flow element or ceiling covering when there is one, else the baseline value.</summary>
    internal static string? ResolveQuantityTakeOffReferenceValue(
        Element element, string ifcType, string? baselineReferenceValue, bool currentProfile = false)
    {
        if ((ifcType == "IFCROOF" && element.CategoryId == -2000035)
            || (ifcType == "IFCRAILING" && element.CategoryId == -2000126))
        {
            if (element.ValidatedRoofOrRailingTypeReferenceIsBlocked) return null;
            if (element.ValidatedRoofOrRailingTypeReferenceName == null) return baselineReferenceValue;
            if (baselineReferenceValue == null && !element.ValidatedRoofOrRailingTypeReferenceIsExplicit) return null;
            return element.ValidatedRoofOrRailingTypeReferenceName;
        }
        if (ReceivesDistributionFlowElementCommonPropertySet(ifcType, currentProfile))
        {
            if (element.ValidatedDistributionTypeReferenceIsBlocked) return null;
            if (element.ValidatedDistributionTypeReferenceName == null) return baselineReferenceValue;
            if (baselineReferenceValue == null && !element.ValidatedDistributionTypeReferenceIsExplicit) return null;
            return element.ValidatedDistributionTypeReferenceName;
        }
        if (ifcType == "IFCCOVERING" && element.CategoryId == -2000038)
        {
            if (element.ValidatedCeilingTypeReferenceIsBlocked)
                return null;
            if (element.ValidatedCeilingTypeReferenceName == null)
                return baselineReferenceValue;
            if (baselineReferenceValue == null
                && !element.ValidatedCeilingTypeReferenceIsExplicit)
                return null;
            return element.ValidatedCeilingTypeReferenceName;
        }

        if (ifcType == "IFCWINDOW" && element.CategoryId == -2000014)
        {
            if (element.ValidatedWindowTypeReferenceIsBlocked)
                return null;
            if (element.ValidatedWindowTypeReferenceName == null)
                return baselineReferenceValue;
            if (baselineReferenceValue == null
                && !element.ValidatedWindowTypeReferenceIsExplicit)
                return null;
            return element.ValidatedWindowTypeReferenceName;
        }

        // Reused verbatim by Pset_BuildingElementProxyCommon.Reference
        // (ExportBuildingElementProxyCommonPropertySet).
        if (ifcType == "IFCBUILDINGELEMENTPROXY")
        {
            if (element.ValidatedProxyTypeReferenceIsBlocked)
                return null;
            if (element.ValidatedProxyTypeReferenceName == null)
                return baselineReferenceValue;
            if (baselineReferenceValue == null
                && !element.ValidatedProxyTypeReferenceIsExplicit)
                return null;
            return element.ValidatedProxyTypeReferenceName;
        }

        if (ifcType != "IFCSLAB" || element.CategoryId != -2000032)
            return baselineReferenceValue;

        if (element.ValidatedFloorTypeReferenceIsBlocked)
            return null;

        if (element.ValidatedFloorTypeReferenceName == null)
            return baselineReferenceValue;

        // A direct parameter can create the main product property.
        if (baselineReferenceValue == null
            && !element.ValidatedFloorTypeReferenceIsExplicit)
            return null;
        return element.ValidatedFloorTypeReferenceName;
    }

    /// <summary>A door/window product fills exactly one opening, so that opening is bare.</summary>
    internal static Element? ResolveHostedOpeningPropertySetReferenceElement(
        Element hostedElement, int hostedIfcId, Element hostElement,
        bool createsFillRelationship)
    {
        if (createsFillRelationship)
            return null;

        bool isPurePrimaryDoorOrWindowCutter = hostedIfcId == 0
            && hostedElement.CategoryId is -2000023 or -2000014
            && hostedElement.SerializedHostId == hostElement.Id;
        return isPurePrimaryDoorOrWindowCutter ? null : hostedElement;
    }

    /// <summary>
    /// A door/window product fills only the opening on its authoritative serialized primary host.
    /// </summary>
    internal static bool TryRegisterHostedOpeningFillRelationship(
        Element hostedElement, int hostedIfcId, int hostWallId,
        ISet<int> filledHostedElementIds) =>
        hostedIfcId > 0
        && hostedElement.CategoryId is -2000023 or -2000014
        && hostedElement.SerializedHostId == hostWallId
        && filledHostedElementIds.Add(hostedElement.Id);

    /// <summary>
    /// Uses the wall type as Reference for a source-owned wall cut while preserving the
    /// independently authored sketch-line Tag.
    /// </summary>
    internal static Element? ResolveSourceOwnedWallOpeningPropertySetReferenceElement(
        Element wallElement, int? sourceOwnerTagId) =>
        sourceOwnerTagId.HasValue ? wallElement : null;

    /// <summary>The element that supplies the property sets of an opening cut by a wall profile: the element named by the Tag when the properties come from it, else the wall.</summary>
    internal static Element? ResolveSourceWallProfileOpeningPropertySetReferenceElement(
        Element wallElement, int tagId, IReadOnlyDictionary<int, Element> elementsById,
        bool propertiesFromTagElement) =>
        propertiesFromTagElement
            ? elementsById.GetValueOrDefault(tagId)
            : ResolveSourceOwnedWallOpeningPropertySetReferenceElement(wallElement, tagId);

    /// <summary>
    /// Selects a sketch-line Tag only when one emitted rectangular source-owned opening has one
    /// exact source contour owned directly by this wall.
    /// </summary>
    internal static IReadOnlyList<int?> SelectExactSourceOwnedWallOpeningTags(
        Element wall,
        IReadOnlyList<RectangularWallThroughOpening> openings,
        IReadOnlyDictionary<int, Element> elemById,
        int? fallbackTagId)
    {
        var selected = Enumerable.Repeat(fallbackTagId, openings.Count).ToArray();
        if (openings.Count == 0 || !elemById.ContainsKey(wall.Id))
            return selected;
        var sketchLinesByOwner = elemById.Values
            .Where(element => element.CategoryId == -2000045
                && element.HostId.HasValue)
            .GroupBy(element => element.HostId!.Value)
            .ToDictionary(group => group.Key,
                group => (IReadOnlyList<Element>)group
                    .OrderBy(element => element.Id).ToList());
        var sketchOwners = elemById.Values
            .Where(owner => owner.SketchLoops is { Count: > 0 })
            .OrderBy(owner => owner.Id).ToList();
        return SelectExactSourceOwnedWallOpeningTags(
            wall, openings, fallbackTagId,
            sketchOwners, sketchLinesByOwner);
    }

    private static IReadOnlyList<int?> SelectExactSourceOwnedWallOpeningTags(
        Element wall,
        IReadOnlyList<RectangularWallThroughOpening> openings,
        int? fallbackTagId,
        IReadOnlyList<Element> sketchOwners,
        IReadOnlyDictionary<int, IReadOnlyList<Element>> sketchLinesByOwner)
    {
        var selected = Enumerable.Repeat(fallbackTagId, openings.Count).ToArray();
        if (openings.Count == 0
            || wall.Location is not
            {
                CurveType: "Line",
                ArcRadius: null,
            } wallLocation
            || wallLocation.StartPoint.Length < 2
            || wallLocation.EndPoint.Length < 2
            || wallLocation.StartPoint.Take(2)
                .Concat(wallLocation.EndPoint.Take(2))
                .Any(value => !double.IsFinite(value)))
            return selected;
        double wallDx = wallLocation.EndPoint[0] - wallLocation.StartPoint[0];
        double wallDy = wallLocation.EndPoint[1] - wallLocation.StartPoint[1];
        double wallAxisLength = Math.Sqrt(wallDx * wallDx + wallDy * wallDy);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength))
            return selected;
        double wallAxisX = wallDx / wallAxisLength;
        double wallAxisY = wallDy / wallAxisLength;

        var owners = sketchOwners
            .Where(owner => owner.Id != wall.Id
                && owner.References?.Count(id => id == wall.Id) == 1
                && sketchLinesByOwner.ContainsKey(owner.Id))
            .ToList();
        if (owners.Count == 0)
            return selected;

        var candidatesByOpening = new List<List<(
            (int OwnerId, int LoopIndex) Contour, int TagId)>>();
        foreach (RectangularWallThroughOpening opening in openings)
        {
            var candidates = new List<(
                (int OwnerId, int LoopIndex) Contour, int TagId)>();
            bool hasExpectedRectangle = TryBuildExpectedRectangle(
                opening, wallAxisX, wallAxisY,
                out var expectedCornerLabels, out var expectedEdges);
            foreach (Element owner in owners)
            {
                IReadOnlyList<Element> ownerLines =
                    sketchLinesByOwner[owner.Id];
                for (int loopIndex = 0;
                     loopIndex < owner.SketchLoops!.Count; loopIndex++)
                {
                    IReadOnlyList<double[]> loop =
                        owner.SketchLoops[loopIndex];
                    if (hasExpectedRectangle
                        && TryGetClosedRectangleEdges(
                            loop, out var loopEdges)
                        && loopEdges.SetEquals(expectedEdges))
                    {
                        var matchingLines = new List<Element>();
                        bool invalidMatchingLine = false;
                        foreach (Element line in ownerLines)
                        {
                            if (line.Location is not
                                {
                                    CurveType: "Line",
                                    ArcRadius: null,
                                } location)
                                continue;
                            if (!TryPointKey(location.StartPoint, out var first)
                                || !TryPointKey(location.EndPoint, out var second))
                            {
                                invalidMatchingLine = true;
                                break;
                            }
                            if (first == second)
                                continue;
                            var edge = CanonicalEdge(first, second);
                            if (!expectedEdges.Contains(edge))
                                continue;
                            if (line.References?.Count(id => id == wall.Id) != 1
                                || owner.References?.Count(id => id == line.Id) != 1)
                            {
                                invalidMatchingLine = true;
                                break;
                            }
                            matchingLines.Add(line);
                        }
                        if (!invalidMatchingLine
                            && matchingLines.Count == 4
                            && matchingLines.Select(line => line.Id)
                                .Distinct().Count() == 4
                            && TryGetLineEdges(
                                matchingLines, out var matchingEdges)
                            && matchingEdges.SetEquals(expectedEdges)
                            && TrySelectDirectedTag(
                                matchingLines, expectedCornerLabels,
                                out int tagId))
                            candidates.Add(((owner.Id, loopIndex), tagId));
                    }

                    if (TrySelectExactTopNotchTag(
                            wall, owner, ownerLines, loop, opening,
                            wallAxisX, wallAxisY, out int topNotchTagId))
                        candidates.Add((
                            (owner.Id, loopIndex), topNotchTagId));
                }
            }
            candidatesByOpening.Add(candidates);
        }

        var contourUseCounts = candidatesByOpening
            .SelectMany(candidates => candidates)
            .GroupBy(candidate => candidate.Contour)
            .ToDictionary(group => group.Key, group => group.Count());
        for (int index = 0; index < candidatesByOpening.Count; index++)
        {
            var candidates = candidatesByOpening[index];
            if (candidates.Count == 1
                && contourUseCounts[candidates[0].Contour] == 1)
                selected[index] = candidates[0].TagId;
        }
        return selected;

        static bool TryPointKey(double[]? point,
            out (long X, long Y, long Z) key)
        {
            key = default;
            if (point is not { Length: >= 3 }
                || point.Take(3).Any(value => !double.IsFinite(value)))
                return false;
            try
            {
                key = IfcPrecisionKeyFeet(point);
                return true;
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        static ((long X, long Y, long Z) A,
            (long X, long Y, long Z) B) CanonicalEdge(
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);

        static bool TryWallLocalPointKey(double[]? point,
            double wallAxisX, double wallAxisY,
            out (long Along, long Normal, long Vertical) key)
        {
            key = default;
            if (point is not { Length: >= 3 }
                || point.Take(3).Any(value => !double.IsFinite(value)))
                return false;
            double alongMetres = (point[0] * wallAxisX
                + point[1] * wallAxisY) * FeetToMetres;
            double normalMetres = (-point[0] * wallAxisY
                + point[1] * wallAxisX) * FeetToMetres;
            double verticalMetres = point[2] * FeetToMetres;
            if (!double.IsFinite(alongMetres)
                || !double.IsFinite(normalMetres)
                || !double.IsFinite(verticalMetres))
                return false;
            try
            {
                key = (IfcPrecisionBinMetres(alongMetres),
                    IfcPrecisionBinMetres(normalMetres),
                    IfcPrecisionBinMetres(verticalMetres));
                return true;
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        static ((long Along, long Normal, long Vertical) A,
            (long Along, long Normal, long Vertical) B) CanonicalLocalEdge(
            (long Along, long Normal, long Vertical) first,
            (long Along, long Normal, long Vertical) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);

        static bool TryBuildExpectedWallLocalOpeningRectangle(
            RectangularWallThroughOpening opening,
            double wallAxisX, double wallAxisY,
            out HashSet<(long Along, long Normal, long Vertical)> corners,
            out HashSet<(
                (long Along, long Normal, long Vertical) A,
                (long Along, long Normal, long Vertical) B)> edges)
        {
            corners = new();
            edges = new();
            double[] values =
            [
                opening.CentreXFt, opening.CentreYFt,
                opening.AxisX, opening.AxisY, opening.WidthFt,
                opening.BaseZFt, opening.HeightFt,
                opening.NormalMinimumFt, opening.NormalMaximumFt,
            ];
            if (values.Any(value => !double.IsFinite(value))
                || !(opening.WidthFt > 0)
                || !(opening.HeightFt > 0)
                || !(opening.NormalMaximumFt > opening.NormalMinimumFt)
                || opening.AxisX != wallAxisX
                || opening.AxisY != wallAxisY)
                return false;

            double halfWidth = opening.WidthFt / 2;
            double minimumX = opening.CentreXFt - wallAxisX * halfWidth;
            double minimumY = opening.CentreYFt - wallAxisY * halfWidth;
            double maximumX = opening.CentreXFt + wallAxisX * halfWidth;
            double maximumY = opening.CentreYFt + wallAxisY * halfWidth;
            double maximumZ = opening.BaseZFt + opening.HeightFt;
            var authoredCorners = new[]
            {
                new[] { minimumX, minimumY, opening.BaseZFt },
                new[] { maximumX, maximumY, opening.BaseZFt },
                new[] { maximumX, maximumY, maximumZ },
                new[] { minimumX, minimumY, maximumZ },
            };
            var keys = new List<
                (long Along, long Normal, long Vertical)>(4);
            foreach (double[] corner in authoredCorners)
            {
                if (!TryWallLocalPointKey(
                        corner, wallAxisX, wallAxisY, out var key)
                    || !corners.Add(key))
                    return false;
                keys.Add(key);
            }
            for (int index = 0; index < keys.Count; index++)
            {
                var first = keys[index];
                var second = keys[(index + 1) % keys.Count];
                if (first == second
                    || !edges.Add(CanonicalLocalEdge(first, second)))
                    return false;
            }
            return corners.Count == 4 && edges.Count == 4;
        }

        static bool TrySelectExactTopNotchTag(
            Element wall, Element owner,
            IReadOnlyList<Element> ownerLines,
            IReadOnlyList<double[]> loop,
            RectangularWallThroughOpening opening,
            double wallAxisX, double wallAxisY,
            out int tagId)
        {
            tagId = 0;
            if (owner.SketchLoops?.Count != 1
                || loop.Count != 9
                || owner.TypeId != wall.Id
                || owner.References?.Count(id => id == wall.Id) != 1
                || ownerLines.Count != 8
                || ownerLines.Select(line => line.Id).Distinct().Count() != 8
                || ownerLines.Any(line => line.CategoryId != -2000045
                    || line.HostId != owner.Id
                    || owner.References.Count(id => id == line.Id) != 1))
                return false;

            var loopKeys = new List<
                (long Along, long Normal, long Vertical)>(9);
            foreach (double[] point in loop)
            {
                if (!TryWallLocalPointKey(
                        point, wallAxisX, wallAxisY, out var key))
                    return false;
                loopKeys.Add(key);
            }
            if (loopKeys[0] != loopKeys[^1]
                || loopKeys.Take(8).Distinct().Count() != 8)
                return false;

            var alongStations = loopKeys.Take(8)
                .Select(key => key.Along).Distinct().Order().ToList();
            var normalStations = loopKeys.Take(8)
                .Select(key => key.Normal).Distinct().ToList();
            var verticalStations = loopKeys.Take(8)
                .Select(key => key.Vertical).Distinct().Order().ToList();
            if (alongStations.Count != 4
                || normalStations.Count != 1
                || verticalStations.Count != 3)
                return false;

            long a0 = alongStations[0], a1 = alongStations[1];
            long a2 = alongStations[2], a3 = alongStations[3];
            long normal = normalStations[0];
            long z0 = verticalStations[0], z1 = verticalStations[1];
            long z2 = verticalStations[2];
            var semanticVertices = new List<
                (long Along, long Normal, long Vertical)>
            {
                (a0, normal, z2), (a0, normal, z0),
                (a3, normal, z0), (a3, normal, z2),
                (a2, normal, z2), (a2, normal, z1),
                (a1, normal, z1), (a1, normal, z2),
                (a0, normal, z2),
            };
            var expectedLoopEdges = new HashSet<(
                (long Along, long Normal, long Vertical) A,
                (long Along, long Normal, long Vertical) B)>();
            for (int index = 0;
                 index < semanticVertices.Count - 1; index++)
                if (!expectedLoopEdges.Add(CanonicalLocalEdge(
                        semanticVertices[index],
                        semanticVertices[index + 1])))
                    return false;

            var loopEdges = new HashSet<(
                (long Along, long Normal, long Vertical) A,
                (long Along, long Normal, long Vertical) B)>();
            for (int index = 0; index < loopKeys.Count - 1; index++)
                if (loopKeys[index] == loopKeys[index + 1]
                    || !loopEdges.Add(CanonicalLocalEdge(
                        loopKeys[index], loopKeys[index + 1])))
                    return false;
            if (loopEdges.Count != 8
                || !loopEdges.SetEquals(expectedLoopEdges)
                || !TryBuildExpectedWallLocalOpeningRectangle(
                    opening, wallAxisX, wallAxisY,
                    out var openingCorners, out var openingEdges))
                return false;

            var notchCorners = new HashSet<
                (long Along, long Normal, long Vertical)>
            {
                (a1, normal, z1), (a2, normal, z1),
                (a2, normal, z2), (a1, normal, z2),
            };
            var missingTopEdge = CanonicalLocalEdge(
                (a1, normal, z2), (a2, normal, z2));
            if (!openingCorners.SetEquals(notchCorners)
                || !openingEdges.Contains(missingTopEdge)
                || loopEdges.Contains(missingTopEdge)
                || openingEdges.Count(edge => loopEdges.Contains(edge)) != 3)
                return false;

            var endpointsByLineId = new Dictionary<int, (
                (long Along, long Normal, long Vertical) Start,
                (long Along, long Normal, long Vertical) End)>();
            var lineEdges = new HashSet<(
                (long Along, long Normal, long Vertical) A,
                (long Along, long Normal, long Vertical) B)>();
            foreach (Element line in ownerLines)
            {
                if (line.Location is not
                    { CurveType: "Line", ArcRadius: null } location
                    || !TryWallLocalPointKey(location.StartPoint,
                        wallAxisX, wallAxisY, out var first)
                    || !TryWallLocalPointKey(location.EndPoint,
                        wallAxisX, wallAxisY, out var second)
                    || first == second
                    || line.References?.Count(id => id == wall.Id) != 1
                    || !lineEdges.Add(CanonicalLocalEdge(first, second))
                    || !endpointsByLineId.TryAdd(
                        line.Id, (first, second)))
                    return false;
            }
            if (!lineEdges.SetEquals(expectedLoopEdges))
                return false;

            var ordered = ownerLines.OrderBy(line => line.Id).ToList();
            var seed = endpointsByLineId[ordered[0].Id];
            var traversed = new List<Element> { ordered[0] };
            var walkedVertices = new List<
                (long Along, long Normal, long Vertical)>
                { seed.Start, seed.End };
            var unused = ordered.Skip(1).ToList();
            var current = seed.End;
            while (unused.Count > 0)
            {
                var nextCandidates = new List<(
                    int Index, Element Line,
                    (long Along, long Normal, long Vertical) Other)>();
                for (int index = 0; index < unused.Count; index++)
                {
                    Element line = unused[index];
                    var endpoints = endpointsByLineId[line.Id];
                    if (endpoints.Start == current)
                        nextCandidates.Add((index, line, endpoints.End));
                    else if (endpoints.End == current)
                        nextCandidates.Add((index, line, endpoints.Start));
                }
                if (nextCandidates.Count != 1)
                    return false;
                var next = nextCandidates[0];
                unused.RemoveAt(next.Index);
                traversed.Add(next.Line);
                current = next.Other;
                walkedVertices.Add(current);
            }
            if (current != seed.Start
                || traversed.Count != 8
                || walkedVertices.Count != 9
                || !walkedVertices.SequenceEqual(semanticVertices)
                || traversed[4].TypeId != traversed[3].Id)
                return false;

            tagId = traversed[4].Id;
            return true;
        }

        static bool TryBuildExpectedRectangle(
            RectangularWallThroughOpening opening,
            double wallAxisX, double wallAxisY,
            out Dictionary<(long X, long Y, long Z),
                (int Along, int Vertical)> cornerLabels,
            out HashSet<((long X, long Y, long Z) A,
                (long X, long Y, long Z) B)> edges)
        {
            cornerLabels = new();
            edges = new();
            double[] values =
            [
                opening.CentreXFt, opening.CentreYFt,
                opening.AxisX, opening.AxisY, opening.WidthFt,
                opening.BaseZFt, opening.HeightFt,
                opening.NormalMinimumFt, opening.NormalMaximumFt,
            ];
            if (values.Any(value => !double.IsFinite(value))
                || !(opening.WidthFt > 0)
                || !(opening.HeightFt > 0)
                || !(opening.NormalMaximumFt > opening.NormalMinimumFt)
                || opening.AxisX != wallAxisX
                || opening.AxisY != wallAxisY)
                return false;

            double halfWidth = opening.WidthFt / 2;
            double minimumX = opening.CentreXFt - wallAxisX * halfWidth;
            double minimumY = opening.CentreYFt - wallAxisY * halfWidth;
            double maximumX = opening.CentreXFt + wallAxisX * halfWidth;
            double maximumY = opening.CentreYFt + wallAxisY * halfWidth;
            double maximumZ = opening.BaseZFt + opening.HeightFt;
            var authoredCorners = new[]
            {
                (Label: (Along: -1, Vertical: -1),
                    Point: new[] { minimumX, minimumY, opening.BaseZFt }),
                (Label: (Along: 1, Vertical: -1),
                    Point: new[] { maximumX, maximumY, opening.BaseZFt }),
                (Label: (Along: 1, Vertical: 1),
                    Point: new[] { maximumX, maximumY, maximumZ }),
                (Label: (Along: -1, Vertical: 1),
                    Point: new[] { minimumX, minimumY, maximumZ }),
            };
            var keysByLabel = new Dictionary<
                (int Along, int Vertical), (long X, long Y, long Z)>();
            foreach (var corner in authoredCorners)
            {
                if (!TryPointKey(corner.Point, out var key)
                    || !cornerLabels.TryAdd(key, corner.Label)
                    || !keysByLabel.TryAdd(corner.Label, key))
                    return false;
            }
            edges.Add(CanonicalEdge(
                keysByLabel[(-1, -1)], keysByLabel[(1, -1)]));
            edges.Add(CanonicalEdge(
                keysByLabel[(1, -1)], keysByLabel[(1, 1)]));
            edges.Add(CanonicalEdge(
                keysByLabel[(1, 1)], keysByLabel[(-1, 1)]));
            edges.Add(CanonicalEdge(
                keysByLabel[(-1, 1)], keysByLabel[(-1, -1)]));
            return edges.Count == 4;
        }

        static bool TryGetClosedRectangleEdges(
            IReadOnlyList<double[]> loop,
            out HashSet<((long X, long Y, long Z) A,
                (long X, long Y, long Z) B)> edges)
        {
            edges = new();
            if (loop.Count != 5)
                return false;
            var keys = new List<(long X, long Y, long Z)>(5);
            foreach (double[] point in loop)
            {
                if (!TryPointKey(point, out var key))
                    return false;
                keys.Add(key);
            }
            if (keys[0] != keys[^1]
                || keys.Take(4).Distinct().Count() != 4)
                return false;
            for (int index = 0; index < 4; index++)
            {
                if (keys[index] == keys[index + 1]
                    || !edges.Add(CanonicalEdge(
                        keys[index], keys[index + 1])))
                    return false;
            }
            return edges.Count == 4;
        }

        static bool TryGetLineEdges(IReadOnlyList<Element> lines,
            out HashSet<((long X, long Y, long Z) A,
                (long X, long Y, long Z) B)> edges)
        {
            edges = new();
            foreach (Element line in lines)
            {
                if (line.Location is not
                    {
                        CurveType: "Line",
                        ArcRadius: null,
                    } location
                    || !TryPointKey(location.StartPoint, out var first)
                    || !TryPointKey(location.EndPoint, out var second)
                    || first == second
                    || !edges.Add(CanonicalEdge(first, second)))
                    return false;
            }
            return edges.Count == 4;
        }

        static bool TrySelectDirectedTag(
            IReadOnlyList<Element> lines,
            IReadOnlyDictionary<(long X, long Y, long Z),
                (int Along, int Vertical)> cornerLabels,
            out int tagId)
        {
            tagId = 0;
            var ordered = lines.OrderBy(line => line.Id).ToList();
            if (ordered.Count != 4
                || ordered.Select(line => line.Id).Distinct().Count() != 4
                || ordered[0].Location is not
                {
                    CurveType: "Line",
                    ArcRadius: null,
                } seedLocation
                || !TryPointKey(seedLocation.StartPoint, out var start)
                || !TryPointKey(seedLocation.EndPoint, out var current)
                || start == current)
                return false;

            var traversed = new List<Element> { ordered[0] };
            var vertices = new List<(long X, long Y, long Z)>
                { start, current };
            var unused = ordered.Skip(1).ToList();
            while (unused.Count > 0)
            {
                var nextCandidates = new List<(
                    int Index, Element Line,
                    (long X, long Y, long Z) Other)>();
                for (int index = 0; index < unused.Count; index++)
                {
                    Element line = unused[index];
                    if (line.Location is not
                        {
                            CurveType: "Line",
                            ArcRadius: null,
                        } location
                        || !TryPointKey(location.StartPoint, out var first)
                        || !TryPointKey(location.EndPoint, out var second)
                        || first == second)
                        return false;
                    if (first == current)
                        nextCandidates.Add((index, line, second));
                    else if (second == current)
                        nextCandidates.Add((index, line, first));
                }
                if (nextCandidates.Count != 1)
                    return false;
                var next = nextCandidates[0];
                unused.RemoveAt(next.Index);
                traversed.Add(next.Line);
                current = next.Other;
                vertices.Add(current);
            }
            if (current != start
                || traversed.Count != 4
                || vertices.Count != 5)
                return false;

            int twiceArea = 0;
            for (int index = 0; index < vertices.Count - 1; index++)
            {
                if (!cornerLabels.TryGetValue(
                        vertices[index], out var first)
                    || !cornerLabels.TryGetValue(
                        vertices[index + 1], out var second))
                    return false;
                twiceArea += first.Along * second.Vertical
                    - second.Along * first.Vertical;
            }
            if (twiceArea == 0)
                return false;
            tagId = twiceArea > 0
                ? traversed[0].Id : traversed[1].Id;
            return true;
        }
    }

    private int CreateExactSourceWallOpening(StepWriter w, Element wall,
        int wallEntityId, int parentPlacementId, int ownerHistId, int subCtxId,
        List<int> storeyContents, RectangularWallThroughOpening opening, int index,
        IReadOnlyDictionary<int, Element> elemById,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        int? sourceOwnerTagId = null)
    {
        double width = opening.WidthFt * FeetToMetres;
        double depth = (opening.NormalMaximumFt - opening.NormalMinimumFt)
            * FeetToMetres;
        double height = opening.HeightFt * FeetToMetres;
        int placementPointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(opening.CentreXFt * FeetToMetres),
            D(opening.CentreYFt * FeetToMetres),
            D(opening.BaseZFt * FeetToMetres)));
        int refDirectionId = w.Add("IFCDIRECTION", StepWriter.List(
            D(opening.AxisX), D(opening.AxisY), "0."));
        int axisId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(placementPointId)},$,{R(refDirectionId)}");
        int placementId = w.Add("IFCLOCALPLACEMENT",
            $"{R(parentPlacementId)},{R(axisId)}");

        int profileOriginId = w.Add("IFCCARTESIANPOINT",
            StepWriter.List("0.", "0."));
        int profilePlacementId = w.Add("IFCAXIS2PLACEMENT2D",
            $"{R(profileOriginId)},$");
        int profileId = w.Add("IFCRECTANGLEPROFILEDEF",
            $".AREA.,$,{R(profilePlacementId)},{D(width)},{D(depth)}");
        int solidOriginId = w.Add("IFCCARTESIANPOINT",
            StepWriter.List("0.", "0.", "0."));
        int solidPlacementId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(solidOriginId)},$,$");
        int directionId = w.Add("IFCDIRECTION",
            StepWriter.List("0.", "0.", "1."));
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(solidPlacementId)},{R(directionId)},{D(height)}");
        int representationId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
        int shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(representationId))}");

        string key = $"source-owned-opening:{wall.Id}:{index}";
        string name = $"{wall.Name ?? "Wall"}:Opening:{index + 1}";
        string openingGlobalId = IfcGuid.FromName(key);
        // The current profile creates these from the wall's own extrusion and hands the wrapper no
        // element: no property sets.
        Element? propertySetReferenceElement = CurrentProfile ? null :
            ResolveSourceOwnedWallOpeningPropertySetReferenceElement(
                wall, sourceOwnerTagId);
        int openingId = CreateOpeningElement(w, openingGlobalId, ownerHistId, name,
            sourceOwnerTagId, propertySetReferenceElement, elemById, placementId, shapeId,
            propertySingleValueIds);
        w.Add("IFCRELVOIDSELEMENT",
            $"{S(IfcGuid.FromName($"source-owned-void:{wall.Id}:{index}"))},{R(ownerHistId)},$,$,{R(wallEntityId)},{R(openingId)}");
        storeyContents.Add(openingId);
        return openingId;
    }

    private void CreateExactSourceWallProfileOpening(StepWriter w, Element wall,
        int wallEntityId, int parentPlacementId, int ownerHistId, int subCtxId,
        List<int> storeyContents, ProfileWallThroughOpening opening, int tagId,
        IReadOnlyDictionary<int, Element> elemById,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        bool propertiesFromTagElement = false)
    {
        double minimumAlong = opening.Profile.Min(point => point.AlongFt);
        double maximumAlong = opening.Profile.Max(point => point.AlongFt);
        double baseZ = opening.Profile.Min(point => point.ZFt);
        double centreAlong = (minimumAlong + maximumAlong) / 2;
        double normalX = -opening.AxisY;
        double normalY = opening.AxisX;
        double placementX = centreAlong * opening.AxisX
            + opening.NormalMaximumFt * normalX;
        double placementY = centreAlong * opening.AxisY
            + opening.NormalMaximumFt * normalY;

        int placementPointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(placementX * FeetToMetres),
            D(placementY * FeetToMetres),
            D(baseZ * FeetToMetres)));
        int placementAxisDirectionId = w.Add("IFCDIRECTION", StepWriter.List(
            D(-normalX), D(-normalY), "0."));
        int placementRefDirectionId = w.Add("IFCDIRECTION", StepWriter.List(
            D(opening.AxisX), D(opening.AxisY), "0."));
        int placementAxisId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(placementPointId)},{R(placementAxisDirectionId)},"
            + $"{R(placementRefDirectionId)}");
        int placementId = w.Add("IFCLOCALPLACEMENT",
            $"{R(parentPlacementId)},{R(placementAxisId)}");

        var profilePointIds = opening.Profile.Select(point =>
            w.Add("IFCCARTESIANPOINT", StepWriter.List(
                D((point.AlongFt - centreAlong) * FeetToMetres),
                D((point.ZFt - baseZ) * FeetToMetres)))).ToList();
        profilePointIds.Add(profilePointIds[0]);
        int profileCurveId = w.Add("IFCPOLYLINE",
            StepWriter.List(profilePointIds.Select(R).ToArray()));
        int profileId = w.Add("IFCARBITRARYCLOSEDPROFILEDEF",
            $".AREA.,$,{R(profileCurveId)}");
        int solidOriginId = w.Add("IFCCARTESIANPOINT",
            StepWriter.List("0.", "0.", "0."));
        int solidPlacementId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(solidOriginId)},$,$");
        int extrusionDirectionId = w.Add("IFCDIRECTION",
            StepWriter.List("0.", "0.", "1."));
        double depth = (opening.NormalMaximumFt
            - opening.NormalMinimumFt) * FeetToMetres;
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(solidPlacementId)},"
            + $"{R(extrusionDirectionId)},{D(depth)}");
        int representationId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},"
            + $"{StepWriter.List(R(solidId))}");
        int shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(representationId))}");

        string key = $"source-owned-profile-opening:{wall.Id}:{tagId}";
        string name = $"{wall.Name ?? "Wall"}:Opening:{tagId}";
        string openingGlobalId = IfcGuid.FromName(key);
        Element? propertySetReferenceElement = CurrentProfile && !propertiesFromTagElement ? null :
            ResolveSourceWallProfileOpeningPropertySetReferenceElement(
                wall, tagId, elemById, propertiesFromTagElement);
        int openingId = CreateOpeningElement(w, openingGlobalId, ownerHistId, name,
            tagId, propertySetReferenceElement, elemById, placementId, shapeId,
            propertySingleValueIds);
        w.Add("IFCRELVOIDSELEMENT",
            $"{S(IfcGuid.FromName($"source-owned-profile-void:{wall.Id}:{tagId}"))},"
            + $"{R(ownerHistId)},$,$,{R(wallEntityId)},{R(openingId)}");
        storeyContents.Add(openingId);
    }


    /// <summary>Writes the native GInstance structure as IFC representation maps.</summary>

    private bool TryCreateMappedShape(StepWriter w, Element element,
        IReadOnlyDictionary<int, Element> elementsById,
        Dictionary<int, RepresentationMapCacheEntry> mapsBySymbol,
        int subCtxId, int identityAxisId,
        out int productShapeId, out BodyRepresentationWriteOutcome outcome,
        string? ifcType = null, Func<string>? profileName = null)
    {
        productShapeId = 0;
        outcome = default;
        if (element.Geometry?.ExactMappedInstances is not { Count: > 0 } instances)
            return false;
        if (CurrentProfile && element.RuleClassName == "BaseRailing")
            return false;

        // The current profile writes the whole Body of a product as extrusions or as Breps: every
        // symbol of its instances needs one.
        var symbolAxes = profileName != null ? OthersCurrentSymbolAxes(element, ifcType) : null;
        bool extrudeSymbols = CurrentProfile && profileName != null && ifcType != "IFCFLOWCONTROLLER" && instances.All(instance =>
            elementsById.TryGetValue(instance.SymbolId, out var candidate) && candidate.Geometry?.Faces is { Count: > 0 }
            && (symbolAxes != null && OthersCurrentGetPlan(candidate.Geometry, symbolAxes) != null
                || TryGetExactCircularExtrusion(candidate.Geometry, out _)));
        var mappedItems = new List<int>();
        foreach (var instance in instances)
        {
            if (!elementsById.TryGetValue(instance.SymbolId, out var symbol)
                || symbol.Geometry?.Faces is not { Count: > 0 })
                return false;

            // The extruded and the faceted map of one symbol are different maps.
            int mapKey = extrudeSymbols ? -instance.SymbolId - 1 : instance.SymbolId;
            if (!mapsBySymbol.TryGetValue(mapKey, out var mapEntry))
            {
                FacetedShapeWriteResult symbolWrite;
                if (extrudeSymbols && symbolAxes != null
                    && TryCreateOthersCurrentSweptSolid(
                        w, symbol.Geometry, subCtxId, symbolAxes, profileName!(), out var sweptSymbolWrite,
                        allowCoaxialCurvedFaces: true))
                    symbolWrite = sweptSymbolWrite;
                else if ((!CurrentProfile || extrudeSymbols) && TryGetExactCircularExtrusion(
                        symbol.Geometry, out var circularExtrusion))
                    symbolWrite = new FacetedShapeWriteResult(
                        [CreateCircularExtrusionRepresentation(
                            w, circularExtrusion, subCtxId)],
                        new BodyRepresentationWriteOutcome(
                            HasSurfaceModel: false,
                            HasClosedBrepOrSweptSolidBody: true,
                            OpenShellCount: 0,
                            OpenShellFaceCount: 0));
                else
                    symbolWrite = CreateFacetedShapeRepresentations(
                        w, symbol.Geometry, subCtxId);
                if (symbolWrite.RepresentationIds.Count == 0) return false;
                var mapIds = symbolWrite.RepresentationIds
                    .Select(representationId => w.Add("IFCREPRESENTATIONMAP",
                        $"{R(identityAxisId)},{R(representationId)}"))
                    .ToList();
                mapEntry = new RepresentationMapCacheEntry(
                    mapIds, symbolWrite.Outcome);
                mapsBySymbol[mapKey] = mapEntry;
            }

            if (!TryCreateMappingTarget(w, instance.Transform, out int targetId))
                return false;
            foreach (int mapId in mapEntry.MapIds)
                mappedItems.Add(w.Add("IFCMAPPEDITEM", $"{R(mapId)},{R(targetId)}"));
            outcome = new BodyRepresentationWriteOutcome(
                outcome.HasSurfaceModel || mapEntry.Outcome.HasSurfaceModel,
                outcome.HasClosedBrepOrSweptSolidBody
                    || mapEntry.Outcome.HasClosedBrepOrSweptSolidBody,
                outcome.OpenShellCount + mapEntry.Outcome.OpenShellCount,
                outcome.OpenShellFaceCount
                    + mapEntry.Outcome.OpenShellFaceCount);
        }

        if (mappedItems.Count == 0) return false;
        int mappedRepresentationId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("MappedRepresentation")},{StepWriter.List(mappedItems.Select(R))}");
        productShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(mappedRepresentationId))}");
        return true;
    }

    private static bool FaceCanEmitAtIfcPrecision(GeoFace face) =>
        face.OuterVertices is { Count: >= 3 } source
        && source.All(point => point.Length >= 3
            && double.IsFinite(point[0]) && double.IsFinite(point[1])
            && double.IsFinite(point[2]))
        && !FaceCollapsesAtIfcPrecision(face);

    internal static bool FacetedGeometryCannotCreateProductShapeAtIfcPrecision(
        GeometryData geometry)
    {
        IEnumerable<int> representedFaceIndices = geometry.BrepSolids is { Count: > 0 }
            ? geometry.BrepSolids.SelectMany(solid => solid.FaceIndices)
                .Distinct().Where(index => (uint)index < geometry.Faces.Count)
            : Enumerable.Range(0, geometry.Faces.Count);
        return representedFaceIndices.All(
            index => !FaceCanEmitAtIfcPrecision(geometry.Faces[index]));
    }

    /// <summary>
    /// Recovers an analytic circular extrusion only when serialized GSurface provenance and the
    /// complete BRep topology independently agree.
    /// </summary>
    internal static bool TryGetExactCircularExtrusion(
        GeometryData geometry, out CircularExtrusion extrusion)
    {
        extrusion = default;
        if (geometry.BrepSolids is not { Count: 1 }
            || !geometry.BrepSolids[0].IsClosed)
            return false;

        var faceIndices = geometry.BrepSolids[0].FaceIndices.Distinct().Order().ToList();
        if (faceIndices.Count != geometry.Faces.Count
            || faceIndices.Where((faceIndex, index) => faceIndex != index).Any())
            return false;

        static bool HasAnyCylinderProvenance(GeoFace face) =>
            face.AnalyticCylinderOrigin != null
            || face.AnalyticCylinderAxis != null
            || face.AnalyticCylinderReferenceDirection != null
            || face.AnalyticCylinderRadius != 0;
        static bool HasCompleteCylinderProvenance(GeoFace face) =>
            face.AnalyticCylinderOrigin is { Length: >= 3 }
            && face.AnalyticCylinderAxis is { Length: >= 3 }
            && face.AnalyticCylinderReferenceDirection is { Length: >= 3 }
            && double.IsFinite(face.AnalyticCylinderRadius)
            && face.AnalyticCylinderRadius > 0;

        if (geometry.Faces.Any(face => HasAnyCylinderProvenance(face)
                && !HasCompleteCylinderProvenance(face)))
            return false;
        var sideFaces = geometry.Faces.Where(HasCompleteCylinderProvenance).ToList();
        var capFaces = geometry.Faces.Where(face => !HasAnyCylinderProvenance(face)).ToList();
        if (sideFaces.Count < 3 || capFaces.Count != 2
            || sideFaces.Any(face => face.OuterVertices is not { Count: 4 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
            || capFaces.Any(face => face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }))
            return false;

        var source = sideFaces[0];
        double[] sourceOrigin = source.AnalyticCylinderOrigin!;
        double[] sourceAxis = source.AnalyticCylinderAxis!;
        double[] sourceRefDirection = source.AnalyticCylinderReferenceDirection!;
        double radiusFt = source.AnalyticCylinderRadius;
        if (sourceOrigin.Take(3).Any(value => !double.IsFinite(value))
            || sourceAxis.Take(3).Any(value => !double.IsFinite(value))
            || sourceRefDirection.Take(3).Any(value => !double.IsFinite(value))
            || sideFaces.Skip(1).Any(face =>
                !face.AnalyticCylinderOrigin!.Take(3).SequenceEqual(sourceOrigin.Take(3))
                || !face.AnalyticCylinderAxis!.Take(3).SequenceEqual(sourceAxis.Take(3))
                || !face.AnalyticCylinderReferenceDirection!.Take(3)
                    .SequenceEqual(sourceRefDirection.Take(3))
                || face.AnalyticCylinderRadius != radiusFt))
            return false;

        static double Dot(IReadOnlyList<double> first, IReadOnlyList<double> second) =>
            first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
        static double Length(IReadOnlyList<double> vector) => Math.Sqrt(Dot(vector, vector));
        static double[] Cross(IReadOnlyList<double> first, IReadOnlyList<double> second) =>
        [
            first[1] * second[2] - first[2] * second[1],
            first[2] * second[0] - first[0] * second[2],
            first[0] * second[1] - first[1] * second[0],
        ];
        static double Distance(IReadOnlyList<double> first, IReadOnlyList<double> second)
        {
            double dx = first[0] - second[0];
            double dy = first[1] - second[1];
            double dz = first[2] - second[2];
            return Math.Sqrt(dx * dx + dy * dy + dz * dz);
        }

        double axisLength = Length(sourceAxis);
        double refLength = Length(sourceRefDirection);
        if (!double.IsFinite(axisLength) || !double.IsFinite(refLength)
            || axisLength <= 1e-12 || refLength <= 1e-12
            || Math.Abs(Dot(sourceAxis, sourceRefDirection))
                > axisLength * refLength * 1e-10)
            return false;
        double[] axis = sourceAxis.Take(3).Select(value => value / axisLength).ToArray();
        double[] profileX = sourceRefDirection.Take(3)
            .Select(value => value / refLength).ToArray();
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;

        double AxialPosition(double[] point) =>
            (point[0] - sourceOrigin[0]) * axis[0]
            + (point[1] - sourceOrigin[1]) * axis[1]
            + (point[2] - sourceOrigin[2]) * axis[2];
        double[] Radial(double[] point, double axialPosition) =>
        [
            point[0] - sourceOrigin[0] - axialPosition * axis[0],
            point[1] - sourceOrigin[1] - axialPosition * axis[1],
            point[2] - sourceOrigin[2] - axialPosition * axis[2],
        ];

        var capData = new List<(GeoFace Face, double Position,
            HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)> Edges)>();
        foreach (var cap in capFaces)
        {
            var ring = cap.OuterVertices!;
            var positions = ring.Select(AxialPosition).ToList();
            double position = positions.Average();
            if (positions.Any(value => Math.Abs(value - position) > toleranceFt))
                return false;
            var radial = ring.Select((point, index) =>
            {
                var vector = Radial(point, positions[index]);
                return (Vector: vector, Length: Length(vector));
            }).ToList();
            if (radial.Any(value => !double.IsFinite(value.Length)
                    || Math.Abs(value.Length - radiusFt) > toleranceFt))
                return false;
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            if (keys.Distinct().Count() != keys.Count) return false;

            double winding = 0;
            int windingSign = 0;
            for (int index = 0; index < radial.Count; index++)
            {
                var first = radial[index].Vector;
                var second = radial[(index + 1) % radial.Count].Vector;
                double angle = Math.Atan2(Dot(axis, Cross(first, second)), Dot(first, second));
                if (!double.IsFinite(angle) || Math.Abs(angle) <= 1e-12) return false;
                int sign = Math.Sign(angle);
                if (windingSign == 0) windingSign = sign;
                else if (windingSign != sign) return false;
                winding += angle;
            }
            if (Math.Abs(Math.Abs(winding) - 2 * Math.PI) > 1e-8) return false;

            var capEdges = new HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)>();
            for (int index = 0; index < keys.Count; index++)
                capEdges.Add(EdgeKey(keys[index], keys[(index + 1) % keys.Count]));
            if (capEdges.Count != keys.Count) return false;
            capData.Add((cap, position, capEdges));
        }
        capData.Sort((first, second) => first.Position.CompareTo(second.Position));
        double lengthFt = capData[1].Position - capData[0].Position;
        if (!double.IsFinite(lengthFt) || lengthFt <= toleranceFt) return false;

        var sideCapEdges = new[]
        {
            new HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)>(),
            new HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)>(),
        };
        foreach (var side in sideFaces)
        {
            var ring = side.OuterVertices!;
            var end = new int[ring.Count];
            var radial = new double[ring.Count][];
            for (int index = 0; index < ring.Count; index++)
            {
                double position = AxialPosition(ring[index]);
                double firstDistance = Math.Abs(position - capData[0].Position);
                double secondDistance = Math.Abs(position - capData[1].Position);
                if (Math.Min(firstDistance, secondDistance) > toleranceFt) return false;
                end[index] = firstDistance <= secondDistance ? 0 : 1;
                radial[index] = Radial(ring[index], position);
                if (Math.Abs(Length(radial[index]) - radiusFt) > toleranceFt)
                    return false;
            }
            if (end.Count(value => value == 0) != 2
                || end.Count(value => value == 1) != 2)
                return false;

            int capEdgeCount = 0;
            int axialEdgeCount = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                int next = (index + 1) % ring.Count;
                if (end[index] == end[next])
                {
                    sideCapEdges[end[index]].Add(EdgeKey(
                        IfcPrecisionKeyFeet(ring[index]),
                        IfcPrecisionKeyFeet(ring[next])));
                    capEdgeCount++;
                }
                else
                {
                    if (Distance(radial[index], radial[next]) > toleranceFt)
                        return false;
                    axialEdgeCount++;
                }
            }
            if (capEdgeCount != 2 || axialEdgeCount != 2) return false;
        }
        if (!sideCapEdges[0].SetEquals(capData[0].Edges)
            || !sideCapEdges[1].SetEquals(capData[1].Edges))
            return false;

        double[] startCentreFt =
        [
            sourceOrigin[0] + capData[0].Position * axis[0],
            sourceOrigin[1] + capData[0].Position * axis[1],
            sourceOrigin[2] + capData[0].Position * axis[2],
        ];
        extrusion = new CircularExtrusion(
            startCentreFt, axis, profileX, radiusFt, lengthFt);
        return true;

        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) EdgeKey(
            (long X, long Y, long Z) first, (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);
    }

    private static int CreateCircularExtrusionRepresentation(
        StepWriter w, CircularExtrusion extrusion, int subCtxId)
    {
        int profileOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0."));
        int profilePlacementId = w.Add("IFCAXIS2PLACEMENT2D", $"{R(profileOriginId)},$");
        int profileId = w.Add("IFCCIRCLEPROFILEDEF",
            $".AREA.,$,{R(profilePlacementId)},{D(extrusion.RadiusFt * FeetToMetres)}");

        int positionPointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(extrusion.StartCentreFt[0] * FeetToMetres),
            D(extrusion.StartCentreFt[1] * FeetToMetres),
            D(extrusion.StartCentreFt[2] * FeetToMetres)));
        int positionAxisId = w.Add("IFCDIRECTION", StepWriter.List(
            D(extrusion.Axis[0]), D(extrusion.Axis[1]), D(extrusion.Axis[2])));
        int positionRefDirectionId = w.Add("IFCDIRECTION", StepWriter.List(
            D(extrusion.ProfileX[0]), D(extrusion.ProfileX[1]), D(extrusion.ProfileX[2])));
        int positionId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(positionPointId)},{R(positionAxisId)},{R(positionRefDirectionId)}");
        int extrusionDirectionId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "1."));
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(positionId)},{R(extrusionDirectionId)},"
            + D(extrusion.LengthFt * FeetToMetres));
        return w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
    }

    private static bool TryCreateMappingTarget(StepWriter w, double[] transform, out int targetId)
    {
        targetId = 0;
        if (transform.Length < 12 || transform.Any(value => !double.IsFinite(value)))
            return false;

        var axis1 = new[] { transform[0], transform[3], transform[6] };
        var axis2 = new[] { transform[1], transform[4], transform[7] };
        var axis3 = new[] { transform[2], transform[5], transform[8] };
        double scale1 = Length(axis1), scale2 = Length(axis2), scale3 = Length(axis3);
        if (scale1 <= 1e-15 || scale2 <= 1e-15 || scale3 <= 1e-15) return false;
        Normalize(axis1, scale1); Normalize(axis2, scale2); Normalize(axis3, scale3);

        int axis1Id = w.Add("IFCDIRECTION", StepWriter.List(axis1.Select(D)));
        int axis2Id = w.Add("IFCDIRECTION", StepWriter.List(axis2.Select(D)));
        int axis3Id = w.Add("IFCDIRECTION", StepWriter.List(axis3.Select(D)));
        int originId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(transform[9] * FeetToMetres),
            D(transform[10] * FeetToMetres),
            D(transform[11] * FeetToMetres)));

        const double scaleTolerance = 1e-12;
        if (Math.Abs(scale2 - scale1) <= scaleTolerance
            && Math.Abs(scale3 - scale1) <= scaleTolerance)
            targetId = w.Add("IFCCARTESIANTRANSFORMATIONOPERATOR3D",
                $"{R(axis1Id)},{R(axis2Id)},{R(originId)},{D(scale1)},{R(axis3Id)}");
        else
            targetId = w.Add("IFCCARTESIANTRANSFORMATIONOPERATOR3DNONUNIFORM",
                $"{R(axis1Id)},{R(axis2Id)},{R(originId)},{D(scale1)},{R(axis3Id)},{D(scale2)},{D(scale3)}");
        return true;

        static double Length(double[] vector) => Math.Sqrt(
            vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]);
        static void Normalize(double[] vector, double length)
        {
            vector[0] /= length; vector[1] /= length; vector[2] /= length;
        }
    }

    /// <summary>
    /// Create IfcFacetedBrep from face geometry, with optional translation offset (in feet).
    /// </summary>
    private int CreateFacetedBrep(StepWriter w, GeometryData geo, int subCtxId,
        double offX = 0, double offY = 0, double offZ = 0,
        bool preserveValidatedPlanarFaces = false,
        Func<double[], double[]>? localFrame = null)
        => CreateFacetedBrepWithOutcome(
            w, geo, subCtxId, offX, offY, offZ,
            preserveValidatedPlanarFaces, localFrame).ShapeId;

    private (int ShapeId, BodyRepresentationWriteOutcome Outcome)
        CreateFacetedBrepWithOutcome(
            StepWriter w, GeometryData geo, int subCtxId,
            double offX = 0, double offY = 0, double offZ = 0,
            bool preserveValidatedPlanarFaces = false,
            Func<double[], double[]>? localFrame = null)
    {
        var result = CreateFacetedShapeRepresentations(
            w, geo, subCtxId, offX, offY, offZ, preserveValidatedPlanarFaces,
            localFrame: localFrame);
        int shapeId = result.RepresentationIds.Count == 0 ? 0
            : w.Add("IFCPRODUCTDEFINITIONSHAPE",
                $"$,$,{StepWriter.List(result.RepresentationIds.Select(R))}");
        return (shapeId, result.Outcome);
    }

    private bool TryCreateExactEmbeddedWallBrepWithAxis(
        StepWriter w, Element wall, int cutterId,
        int bodySubCtxId, int axisSubCtxId, int parentPlacementId,
        IReadOnlyDictionary<int, Element> elements,
        out int shapeId, out int placementId)
    {
        shapeId = 0;
        placementId = 0;
        if (!TryGetExactEmbeddedSingleFamilyCutBrepAxis(
                wall, cutterId, out var frame, out var localBoundary,
                out bool hasCompletedSourceBrep,
                elements))
            return false;

        var bodyWrite = CreateFacetedShapeRepresentations(
            w, localBoundary, bodySubCtxId,
            preserveValidatedPlanarFaces: true,
            preserveValidatedCoordinates: hasCompletedSourceBrep);
        if (bodyWrite.RepresentationIds.Count != 1) return false;

        int placementOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(frame.OriginXFt * FeetToMetres),
            D(frame.OriginYFt * FeetToMetres),
            D(frame.BaseZFt * FeetToMetres)));
        int placementDirectionId = w.Add("IFCDIRECTION", StepWriter.List(
            D(frame.DirectionX), D(frame.DirectionY), "0."));
        int placementAxisId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(placementOriginId)},$,{R(placementDirectionId)}");
        placementId = w.Add("IFCLOCALPLACEMENT",
            $"{R(parentPlacementId)},{R(placementAxisId)}");

        int axisStartId = w.Add("IFCCARTESIANPOINT",
            StepWriter.List("0.", "0."));
        int axisEndId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(frame.LengthFt * FeetToMetres), "0."));
        int axisCurveId = w.Add("IFCPOLYLINE",
            StepWriter.List(R(axisStartId), R(axisEndId)));
        int axisRepresentationId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(axisSubCtxId)},{S("Axis")},{S("Curve2D")},"
            + StepWriter.List(R(axisCurveId)));
        shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE", "$,$,"
            + StepWriter.List(
                new[] { axisRepresentationId }
                    .Concat(bodyWrite.RepresentationIds).Select(R)));
        return true;
    }

    private FacetedShapeWriteResult CreateFacetedShapeRepresentations(
        StepWriter w, GeometryData geo,
        int subCtxId, double offX = 0, double offY = 0, double offZ = 0,
        bool preserveValidatedPlanarFaces = false,
        bool preserveValidatedCoordinates = false,
        Func<double[], double[]>? localFrame = null)
    {
        var closedComponents = new List<ClosedComponentCurrent>();
        // The face of geo.Faces each oriented face was made of, when the oriented list is the
        // sorted source faces one for one.
        static List<int>? OrientedSources(IEnumerable<int> indices, int orientedCount)
        {
            var sorted = indices.Distinct().Order().ToList();
            return sorted.Count == orientedCount ? sorted : null;
        }
        if (geo.BrepSolids is { Count: > 0 } serializedSolids)
        {
            // Edge.m_pFace is Revit's serialized BRep topology. It remains authoritative when
            // independently tessellated curved faces acquire T-junctions or coordinate roundoff at
            // their shared boundary.
            foreach (var solid in serializedSolids.Where(solid => solid.IsClosed || CurrentProfile && IsExactClosedDespiteOpenTopologyCurrent(geo, solid, preserveValidatedPlanarFaces)))
            {
                var sourceIndices = solid.FaceIndices.Distinct()
                    .Where(index => (uint)index < geo.Faces.Count).Order().ToList();
                if (sourceIndices.Count < 4) continue;
                var facetedIndices = sourceIndices
                    .Where(index => !FaceCollapsesAtIfcPrecision(geo.Faces[index]))
                    .ToList();
                if (facetedIndices.Count < 4) continue;

                // Some serialized solids contain a disconnected construction section in addition to
                // their real boundary (for example a mullion cut plane).
                var exactShells = GetExactFaceComponents(geo.Faces, facetedIndices)
                    .Select(component => TryOrientExactFacetedShell(
                            geo.Faces, component, out var componentFaces,
                            triangulateNonPlanarFaces: !preserveValidatedPlanarFaces)
                        ? (Indices: component, Faces: componentFaces)
                        : (Indices: (List<int>?)null, Faces: (List<GeoFace>?)null))
                    .Where(shell => shell.Indices != null && shell.Faces != null)
                    .Select(shell => (Indices: shell.Indices!, Faces: shell.Faces!))
                    .ToList();
                var exactCoveredIndices = exactShells.SelectMany(shell => shell.Indices)
                    .Distinct().ToHashSet();
                if (exactShells.Count > 1
                    && exactCoveredIndices.SetEquals(facetedIndices))
                {
                    // A serialized Face can own several disconnected coplanar regions.
                    foreach (var shell in exactShells)
                        closedComponents.Add(new(shell.Indices, shell.Faces, shell.Indices,
                            OrientedSources(shell.Indices, shell.Faces.Count)));
                    continue;
                }
                if (exactShells.Count == 1)
                {
                    var shell = exactShells[0];
                    var shellIndices = shell.Indices.ToHashSet();
                    var remainder = facetedIndices.Where(index => !shellIndices.Contains(index))
                        .ToList();
                    var crossings = remainder.ToDictionary(index => index,
                        index => IsFaceCrossingConvexClosedShell(
                            geo.Faces[index], shell.Faces));
                    if (remainder.Count > 0
                        && crossings.Values.All(crossing => crossing))
                    {
                        closedComponents.Add(new(shell.Indices, shell.Faces, sourceIndices,
                            OrientedSources(shell.Indices, shell.Faces.Count)));
                        continue;
                    }
                }

                // Quantization can collapse a chain of sub-precision tessellation strips between
                // otherwise valid facets.
                if (TryOrientPrecisionContractedFacetedShell(geo.Faces, sourceIndices,
                        out var contractedIndices, out var contractedFaces))
                {
                    var contractedComponents = GetExactFaceComponents(contractedFaces,
                        Enumerable.Range(0, contractedFaces.Count).ToList());
                    var contractedShells = contractedComponents
                        .Select(component => TryOrientExactFacetedShell(
                                contractedFaces, component, out var componentFaces,
                                triangulateNonPlanarFaces: !preserveValidatedPlanarFaces)
                            ? (Indices: component, Faces: componentFaces)
                            : (Indices: (List<int>?)null, Faces: (List<GeoFace>?)null))
                        .Where(shell => shell.Indices != null && shell.Faces != null)
                        .Select(shell => (Indices: shell.Indices!, Faces: shell.Faces!))
                        .ToList();
                    if (contractedShells.Count > 1
                        && contractedShells.SelectMany(shell => shell.Indices)
                            .Distinct().Count() == contractedFaces.Count)
                    {
                        for (int shellIndex = 0; shellIndex < contractedShells.Count; shellIndex++)
                            closedComponents.Add(new(contractedIndices,
                                contractedShells[shellIndex].Faces,
                                shellIndex == 0 ? sourceIndices : [], null));
                        continue;
                    }
                    closedComponents.Add(new(contractedIndices, contractedFaces, sourceIndices, null));
                    continue;
                }

                if (!TryOrientExactFacetedShell(geo.Faces, facetedIndices,
                        out var orientedFaces,
                        triangulateNonPlanarFaces: !preserveValidatedPlanarFaces))
                    orientedFaces = facetedIndices.Select(index => geo.Faces[index]).ToList();
                // Two independently authored BReps may share source faces.
                closedComponents.Add(new(facetedIndices, orientedFaces, sourceIndices,
                    OrientedSources(facetedIndices, orientedFaces.Count)));
            }
        }
        else
        {
            foreach (var component in GetExactFaceComponents(
                         geo.Faces, Enumerable.Range(0, geo.Faces.Count).ToList()))
                if (TryOrientExactFacetedShell(geo.Faces, component, out var orientedFaces,
                        triangulateNonPlanarFaces: !preserveValidatedPlanarFaces))
                    closedComponents.Add(new(component, orientedFaces, component,
                        OrientedSources(component, orientedFaces.Count)));
        }

        // IFC topology identity follows the exact coordinate lattice used by this writer.
        var pointIds = new Dictionary<(long X, long Y, long Z), int>();

        int CartesianPoint(double[] vertex)
        {
            if (localFrame != null) vertex = localFrame(vertex);
            double x = (vertex[0] + offX) * FeetToMetres;
            double y = (vertex[1] + offY) * FeetToMetres;
            double z = (vertex[2] + offZ) * FeetToMetres;
            var key = IfcPrecisionKeyMetres(x, y, z);
            if (!pointIds.TryGetValue(key, out int pointId))
            {
                if (!preserveValidatedCoordinates)
                {
                    x = key.X * IfcGeometryPrecisionMetres;
                    y = key.Y * IfcGeometryPrecisionMetres;
                    z = key.Z * IfcGeometryPrecisionMetres;
                }
                pointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x), D(y), D(z)));
                pointIds[key] = pointId;
            }
            return pointId;
        }

        bool SaneVertex(double[] v)
        {
            return v.Length >= 3 && double.IsFinite(v[0])
                && double.IsFinite(v[1]) && double.IsFinite(v[2]);
        }

        static bool SamePoint(double[] a, double[] b) =>
            IfcPrecisionKeyFeet(a) == IfcPrecisionKeyFeet(b);

        static List<double[]> CleanLoop(IEnumerable<double[]> source)
        {
            var clean = new List<double[]>();
            foreach (var v in source)
                if (clean.Count == 0 || !SamePoint(clean[^1], v)) clean.Add(v);
            if (clean.Count > 1 && SamePoint(clean[0], clean[^1])) clean.RemoveAt(clean.Count - 1);
            return clean;
        }

        static bool NonDegenerate(IReadOnlyList<double[]> vertices)
        {
            if (vertices.Count < 3) return false;
            var a = IfcPrecisionKeyFeet(vertices[0]);
            for (int i = 1; i + 1 < vertices.Count; i++)
            {
                var b = IfcPrecisionKeyFeet(vertices[i]);
                var c = IfcPrecisionKeyFeet(vertices[i + 1]);
                var ux = (System.Numerics.BigInteger)b.X - a.X;
                var uy = (System.Numerics.BigInteger)b.Y - a.Y;
                var uz = (System.Numerics.BigInteger)b.Z - a.Z;
                var vx = (System.Numerics.BigInteger)c.X - a.X;
                var vy = (System.Numerics.BigInteger)c.Y - a.Y;
                var vz = (System.Numerics.BigInteger)c.Z - a.Z;
                var cx = uy * vz - uz * vy;
                var cy = uz * vx - ux * vz;
                var cz = ux * vy - uy * vx;
                if (!cx.IsZero || !cy.IsZero || !cz.IsZero) return true;
            }
            return false;
        }

        bool CollapsesAtIfcPrecision(GeoFace face)
            => FaceCollapsesAtIfcPrecision(face);

        int CreateFaceEntity(GeoFace face)
        {
            if (face.OuterVertices == null || face.OuterVertices.Count < 3) return 0;

            // Skip faces with corrupt vertices: hard-corrupt doubles (1e168+/Infinity) and
            // positional outliers km away from the model median - a single such point poisons the
            // whole scene bbox in three.js/web-ifc viewers.
            if (face.OuterVertices.Any(v => !SaneVertex(v))) return 0;
            var outerVertices = CleanLoop(face.OuterVertices);
            if (!NonDegenerate(outerVertices)) return 0;

            var outerPtIds = new List<int>();
            foreach (var v in outerVertices)
                outerPtIds.Add(CartesianPoint(v));

            // Close the loop (repeat first point)
            outerPtIds.Add(outerPtIds[0]);

            int polyLoopId = w.Add("IFCPOLYLOOP", StepWriter.List(outerPtIds.SkipLast(1).Select(R)));
            int boundId = w.Add("IFCFACEOUTERBOUND", $"{R(polyLoopId)},.T.");

            var boundIds = new List<int> { boundId };

            if (face.InnerVertices != null)
            {
                foreach (var innerVerts in face.InnerVertices)
                {
                    if (innerVerts.Count < 3 || innerVerts.Any(v => !SaneVertex(v))) continue;
                    var cleanInner = CleanLoop(innerVerts);
                    if (!NonDegenerate(cleanInner)) continue;
                    var innerPtIds = new List<int>();
                    foreach (var v in cleanInner)
                        innerPtIds.Add(CartesianPoint(v));
                    int innerLoopId = w.Add("IFCPOLYLOOP", StepWriter.List(innerPtIds.Select(R)));
                    int innerBoundId = w.Add("IFCFACEBOUND", $"{R(innerLoopId)},.T.");
                    boundIds.Add(innerBoundId);
                }
            }

            return w.Add("IFCFACE", StepWriter.List(boundIds.Select(R)));
        }

        var brepIds = new List<int>();
        var assignedFaces = new HashSet<int>();
        bool hasExplicitTopology = geo.BrepSolids is { Count: > 0 };
        // The Geometry node a solid comes from (its source faces carry it); int.MaxValue when it
        // has none.
        int ComponentNode(ClosedComponentCurrent component)
        {
            int node = 0;
            foreach (int index in component.SourceIndices)
                if ((uint)index < geo.Faces.Count && geo.Faces[index].GeometryNode > node) node = geo.Faces[index].GeometryNode;
            return node > 0 ? node : int.MaxValue;
        }
        var brepSlots = new List<(int Node, List<PreparedFaceCurrent> Faces)>();
        var brepSlotByNode = new Dictionary<int, int>();

        // CreateFaceEntity writes nothing and returns 0 for exactly these faces.
        bool CanEmitFace(GeoFace face) =>
            face.OuterVertices is { Count: >= 3 } outer && outer.All(SaneVertex) && NonDegenerate(CleanLoop(outer));

        // The oriented faces of a planar solid with the Face (handle and serialized loops) each one
        // is a region of.
        List<PreparedFaceCurrent> PrepareFaces(ClosedComponentCurrent component)
        {
            List<GeoFace>? sources = null;
            if (CurrentProfile && component.OrientedSources is { } mapped && mapped.Count == component.OrientedFaces.Count
                && mapped.All(index => (uint)index < geo.Faces.Count))
            {
                sources = mapped.Select(index => geo.Faces[index]).ToList();
                if (sources.Any(source => source.CurvedSurface)) sources = null;
            }
            return component.OrientedFaces.Select((face, index) =>
                sources != null && sources[index].SourceFace != 0 && sources[index].SourceLoops != null
                    ? new PreparedFaceCurrent(face, sources[index].SourceFace, sources[index].SourceLoops)
                    : new PreparedFaceCurrent(face, 0, null)).ToList();
        }

        // One IfcFace per serialized Face of a planar solid (the current profile), the other faces
        // as they are.
        List<int> WriteFaces(IReadOnlyList<PreparedFaceCurrent> prepared)
        {
            var ids = new List<int>();
            var done = new bool[prepared.Count];
            for (int index = 0; index < prepared.Count; index++)
            {
                if (done[index]) continue;
                done[index] = true;
                var first = prepared[index];
                if (first.SourceLoops != null)
                {
                    var group = new List<int> { index };
                    for (int other = index + 1; other < prepared.Count; other++)
                        if (!done[other] && prepared[other].SourceFace == first.SourceFace
                            && ReferenceEquals(prepared[other].SourceLoops, first.SourceLoops))
                            group.Add(other);
                    if (FaceBoundsCurrent(group.Select(member => prepared[member].Face).ToList(), first.SourceLoops) is { } bounds
                        && CreateBoundedFaceEntity(bounds) is > 0 and int boundedId)
                    {
                        foreach (int member in group) done[member] = true;
                        ids.Add(boundedId);
                        continue;
                    }
                }
                int id = CreateFaceEntity(first.Face);
                if (id > 0) ids.Add(id);
            }
            return ids;
        }

        int CreateBoundedFaceEntity(IReadOnlyList<(List<double[]> Ring, bool IsOuter)> bounds)
        {
            var loops = new List<List<double[]>>();
            foreach (var (ring, _) in bounds)
            {
                if (ring.Any(vertex => !SaneVertex(vertex))) return 0;
                var clean = CleanLoop(ring);
                if (!NonDegenerate(clean)) return 0;
                loops.Add(clean);
            }
            var boundIds = new List<int>();
            for (int index = 0; index < loops.Count; index++)
            {
                int loopId = w.Add("IFCPOLYLOOP", StepWriter.List(loops[index].Select(vertex => R(CartesianPoint(vertex)))));
                boundIds.Add(w.Add(bounds[index].IsOuter ? "IFCFACEOUTERBOUND" : "IFCFACEBOUND", $"{R(loopId)},.T."));
            }
            return w.Add("IFCFACE", StepWriter.List(boundIds.Select(R)));
        }
        // The current profile lists the items in the order of its depth-first walk of the nodes,
        // nested symbols where their GInstance stands (see GRepParserV2.ComputeNodeOrders); a node
        // without a known place goes last, in the order of its id.
        var orderByNode = CurrentProfile
            ? geo.Faces.Where(face => face.GeometryNode != 0 && face.NodeOrder != 0)
                .GroupBy(face => Math.Abs(face.GeometryNode)).ToDictionary(group => group.Key, group => group.First().NodeOrder)
            : new Dictionary<int, long>();
        long OrderOf(int node) => orderByNode.GetValueOrDefault(node, long.MaxValue);
        var shellItems = new List<(long Order, int Node, int BrepId)>();
        // The current profile exports only the Geometry nodes with a visible face
        //: the faces of a node it does not take
        // (a negative node id, for example the same body at another detail level) are not part of
        bool perNode = CurrentProfile && geo.GhostNodes is not { Count: > 0 };
        bool dropUntakenNodes = perNode && geo.Faces.Any(face => face.GeometryNode > 0);
        bool geometryHasNodeIds = geo.Faces.Any(face => face.GeometryNode != 0);
        if (dropUntakenNodes)
            for (int faceIndex = 0; faceIndex < geo.Faces.Count; faceIndex++)
                if (geo.Faces[faceIndex].GeometryNode < 0) assignedFaces.Add(faceIndex);
        var referenceWritten = WriteTriangleNodes(w, geo, offX, offY, offZ, localFrame, shellItems);
        if (referenceWritten.Count > 0)
            for (int faceIndex = 0; faceIndex < geo.Faces.Count; faceIndex++)
                if (referenceWritten.Contains(Math.Abs(geo.Faces[faceIndex].GeometryNode))) assignedFaces.Add(faceIndex);
        foreach (var component in closedComponents)
        {
            int componentNodeId = ComponentNode(component);
            if (referenceWritten.Contains(componentNodeId == int.MaxValue ? 0 : Math.Abs(componentNodeId))) continue;
            if (dropUntakenNodes && component.SourceIndices.Count > 0 && (uint)component.SourceIndices[0] < geo.Faces.Count
                && geo.Faces[component.SourceIndices[0]].GeometryNode < 0)
                continue;
            var emittedFaces = PrepareFaces(component)
                .Select(face => (Face: face, Valid: CanEmitFace(face.Face),
                    Collapsed: CollapsesAtIfcPrecision(face.Face))).ToList();
            // A pole of an analytic surface can serialize zero-area facets which collapse after
            // coordinates are quantized to the IFC coordinate lattice.
            if (emittedFaces.Any(face => !face.Valid && !face.Collapsed)) continue;
            var solidFaces = emittedFaces.Where(face => face.Valid).Select(face => face.Face).ToList();
            if (solidFaces.Count < 4)
                continue;
            foreach (int faceIndex in component.ConsumedIndices) assignedFaces.Add(faceIndex);
            if (perNode)
            {
                // The current profile writes one IfcFacetedBrep per Geometry node with all its
                // faces in one closed shell, however many disjoint shells the node holds
                // (the body export adds one face set per solid).
                int componentNode = ComponentNode(component);
                bool sharesItem = componentNode != int.MaxValue || !geometryHasNodeIds;
                if (sharesItem && brepSlotByNode.TryGetValue(componentNode, out int slot))
                    brepSlots[slot].Faces.AddRange(solidFaces);
                else
                {
                    if (sharesItem) brepSlotByNode[componentNode] = brepSlots.Count;
                    brepSlots.Add((componentNode, solidFaces));
                }
                continue;
            }
            var solidFaceIds = WriteFaces(solidFaces);
            int solidShellId = w.Add("IFCCLOSEDSHELL", StepWriter.List(solidFaceIds.Select(R)));
            int brepId = w.Add("IFCFACETEDBREP", R(solidShellId));
            // The style of the item follows the Geometry node of the solid.
            int shellNode = ComponentNode(component);
            if (shellNode != int.MaxValue)
                _bodyItemOrigins[brepId] = (geo, shellNode);
            shellItems.Add((OrderOf(shellNode), shellNode, brepId));
        }
        var allItems = new List<(long Order, int Node, int BrepId)>(CurrentProfile ? shellItems.OrderBy(item => item.Order).ThenBy(item => item.Node) : shellItems.AsEnumerable());
        foreach (var (slotNode, slotFaces) in CurrentProfile ? brepSlots.OrderBy(slot => OrderOf(slot.Node)).ThenBy(slot => slot.Node).ToList() : brepSlots)
        {
            var slotFaceIds = WriteFaces(slotFaces);
            int solidShellId = w.Add("IFCCLOSEDSHELL", StepWriter.List(slotFaceIds.Select(R)));
            int brepId = w.Add("IFCFACETEDBREP", R(solidShellId));
            allItems.Add((OrderOf(slotNode), slotNode, brepId));
            if (slotNode != int.MaxValue) _bodyItemOrigins[brepId] = (geo, slotNode);
        }
        brepIds.AddRange((CurrentProfile && referenceWritten.Count > 0 ? allItems.OrderBy(item => item.Order).ThenBy(item => item.Node) : allItems.AsEnumerable())
            .Select(item => item.BrepId));

        var faceEntityByIndex = new Dictionary<int, int>();
        for (int faceIndex = 0; faceIndex < geo.Faces.Count; faceIndex++)
        {
            if (assignedFaces.Contains(faceIndex)) continue;
            int faceId = CreateFaceEntity(geo.Faces[faceIndex]);
            if (faceId > 0) faceEntityByIndex[faceIndex] = faceId;
        }
        if (brepIds.Count == 0 && faceEntityByIndex.Count == 0)
            return new FacetedShapeWriteResult([], default);

        var remainingFaceIds = faceEntityByIndex
            .Where(kv => !assignedFaces.Contains(kv.Key)).Select(kv => kv.Value).ToList();
        var representationIds = new List<int>();
        bool hasSurfaceModel = false;
        int emittedOpenShellCount = 0;
        int emittedOpenShellFaceCount = 0;
        if (brepIds.Count > 0)
            representationIds.Add(w.Add("IFCSHAPEREPRESENTATION",
                $"{R(subCtxId)},{S("Body")},{S("Brep")},{StepWriter.List(brepIds.Select(R))}"));

        // Preserve every decoded component. A family may contain exact closed details and a
        // separate open tessellated body (for example curved imported geometry).
        if (remainingFaceIds.Count > 0)
        {
            var openShellIds = new List<int>();
            var surfaceFaces = new HashSet<int>();
            var surfaceNodes = new HashSet<int>();
            // ExportBodyAsBRep: a body whose volume cannot be computed (an open shell) is one
            // IfcFaceBasedSurfaceModel of connected face sets, not an IfcShellBasedSurfaceModel of
            // open shells; beside solid items the shell stays an open shell
            bool faceBasedSurface = CurrentProfile && MeshFaceBasedSurface && brepIds.Count == 0;
            int AddFaceGroup(IEnumerable<int> faceIds) =>
                w.Add(faceBasedSurface ? "IFCCONNECTEDFACESET" : "IFCOPENSHELL", StepWriter.List(faceIds.Select(R)));
            if (hasExplicitTopology)
            {
                foreach (var solid in geo.BrepSolids!)
                {
                    var component = solid.FaceIndices.Distinct()
                        .Where(index => !assignedFaces.Contains(index)
                            && faceEntityByIndex.ContainsKey(index))
                        .ToList();
                    if (component.Count == 0) continue;
                    openShellIds.Add(AddFaceGroup(component.Select(index => faceEntityByIndex[index])));
                    emittedOpenShellCount++;
                    emittedOpenShellFaceCount += component.Count;
                    foreach (int faceIndex in component) { surfaceFaces.Add(faceIndex); surfaceNodes.Add(geo.Faces[faceIndex].GeometryNode); }
                }
            }
            // Once a serialized BRep topology exists, only its components are authoritative.
            var ungroupedFaceIds = hasExplicitTopology
                ? new List<int>()
                : faceEntityByIndex
                    .Where(kv => !assignedFaces.Contains(kv.Key)
                        && !surfaceFaces.Contains(kv.Key))
                    .Select(kv => kv.Value).ToList();
            if (ungroupedFaceIds.Count > 0)
            {
                openShellIds.Add(AddFaceGroup(ungroupedFaceIds));
                emittedOpenShellCount++;
                emittedOpenShellFaceCount += ungroupedFaceIds.Count;
                foreach (var (faceIndex, _) in faceEntityByIndex.Where(kv => !assignedFaces.Contains(kv.Key) && !surfaceFaces.Contains(kv.Key)))
                    surfaceNodes.Add(geo.Faces[faceIndex].GeometryNode);
            }

            if (openShellIds.Count > 0)
            {
                hasSurfaceModel = true;
                int surfaceId = w.Add(faceBasedSurface ? "IFCFACEBASEDSURFACEMODEL" : "IFCSHELLBASEDSURFACEMODEL",
                    StepWriter.List(openShellIds.Select(R)));
                if (CurrentProfile && brepIds.Count == 0 && surfaceNodes.Count == 1 && surfaceNodes.Single() is > 0 and int surfaceNode)
                    _bodyItemOrigins[surfaceId] = (geo, surfaceNode);
                representationIds.Add(w.Add("IFCSHAPEREPRESENTATION",
                    $"{R(subCtxId)},{S("Body")},{S("SurfaceModel")},{StepWriter.List(R(surfaceId))}"));
            }
        }

        return new FacetedShapeWriteResult(
            representationIds,
            new BodyRepresentationWriteOutcome(
                HasSurfaceModel: hasSurfaceModel,
                HasClosedBrepOrSweptSolidBody: brepIds.Count > 0,
                OpenShellCount: emittedOpenShellCount,
                OpenShellFaceCount: emittedOpenShellFaceCount));
    }

    /// <summary>
    /// Returns true only when a polygon has a positive-area intersection with the strict interior
    /// of an independently closed convex shell.
    /// </summary>
    internal static bool IsFaceCrossingConvexClosedShell(GeoFace candidate,
        IReadOnlyList<GeoFace> shellFaces)
    {
        if (candidate.OuterVertices is not { Count: >= 3 } candidateVertices
            || candidate.InnerVertices is { Count: > 0 }
            || shellFaces.Count < 4
            || shellFaces.Any(face => face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }))
            return false;

        double toleranceFeet = IfcGeometryPrecisionMetres / FeetToMetres;
        static double[] PrecisionPoint(double[] point)
        {
            var key = IfcPrecisionKeyFeet(point);
            double precisionFeet = IfcGeometryPrecisionMetres / FeetToMetres;
            return [key.X * precisionFeet, key.Y * precisionFeet, key.Z * precisionFeet];
        }
        var shellVertices = shellFaces.SelectMany(face => face.OuterVertices!)
            .Select(PrecisionPoint).ToList();
        if (shellVertices.Count < 4 || shellVertices.Any(point => point.Length < 3
                || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;
        double[] centre =
        [
            shellVertices.Average(point => point[0]),
            shellVertices.Average(point => point[1]),
            shellVertices.Average(point => point[2]),
        ];
        var clipped = candidateVertices.Select(PrecisionPoint).ToList();

        foreach (var shellFace in shellFaces)
        {
            var ring = shellFace.OuterVertices!.Select(PrecisionPoint).ToList();
            double nx = 0, ny = 0, nz = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                var current = ring[index];
                var next = ring[(index + 1) % ring.Count];
                nx += (current[1] - next[1]) * (current[2] + next[2]);
                ny += (current[2] - next[2]) * (current[0] + next[0]);
                nz += (current[0] - next[0]) * (current[1] + next[1]);
            }
            double length = Math.Sqrt(nx * nx + ny * ny + nz * nz);
            if (!(length > 0) || !double.IsFinite(length)) return false;
            nx /= length; ny /= length; nz /= length;
            double plane = nx * ring[0][0] + ny * ring[0][1] + nz * ring[0][2];
            double Distance(double[] point) =>
                nx * point[0] + ny * point[1] + nz * point[2] - plane;

            // The centroid is strictly inside a non-degenerate convex shell.
            double centreDistance = Distance(centre);
            if (Math.Abs(centreDistance) <= toleranceFeet) return false;
            if (centreDistance > 0)
            {
                nx = -nx; ny = -ny; nz = -nz; plane = -plane;
            }
            if (shellVertices.Any(point => Distance(point) > toleranceFeet)) return false;

            // A coincident authored boundary is never a construction section.
            if (candidateVertices.All(point => Math.Abs(Distance(point)) <= toleranceFeet))
                return false;

            var input = clipped;
            clipped = [];
            if (input.Count < 3) return false;
            for (int index = 0; index < input.Count; index++)
            {
                var first = input[index];
                var second = input[(index + 1) % input.Count];
                double firstDistance = Distance(first);
                double secondDistance = Distance(second);
                bool firstInside = firstDistance <= toleranceFeet;
                bool secondInside = secondDistance <= toleranceFeet;
                if (firstInside) clipped.Add(first);
                if (firstInside == secondInside) continue;
                double denominator = firstDistance - secondDistance;
                if (denominator == 0 || !double.IsFinite(denominator)) return false;
                double ratio = firstDistance / denominator;
                clipped.Add(
                [
                    first[0] + ratio * (second[0] - first[0]),
                    first[1] + ratio * (second[1] - first[1]),
                    first[2] + ratio * (second[2] - first[2]),
                ]);
            }
        }

        if (clipped.Count < 3) return false;
        double areaX = 0, areaY = 0, areaZ = 0;
        for (int index = 0; index < clipped.Count; index++)
        {
            var current = clipped[index];
            var next = clipped[(index + 1) % clipped.Count];
            areaX += (current[1] - next[1]) * (current[2] + next[2]);
            areaY += (current[2] - next[2]) * (current[0] + next[0]);
            areaZ += (current[0] - next[0]) * (current[1] + next[1]);
        }
        double areaSquared = (areaX * areaX + areaY * areaY + areaZ * areaZ) / 4;
        return double.IsFinite(areaSquared)
            && areaSquared > toleranceFeet * toleranceFeet * toleranceFeet * toleranceFeet;
    }

    /// <summary>
    /// Splits an authored topology group by shared polygon edges at the declared IFC geometric
    /// precision.
    /// </summary>
    private static List<List<int>> GetExactFaceComponents(IReadOnlyList<GeoFace> faces,
        IReadOnlyCollection<int> sourceIndices)
    {
        static (long X, long Y, long Z) PointKey(double[] point) =>
            IfcPrecisionKeyFeet(point);
        static ((long X, long Y, long Z) A, (long X, long Y, long Z) B) EdgeKey(
            (long X, long Y, long Z) first, (long X, long Y, long Z) second)
            => first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var indices = sourceIndices.Distinct()
            .Where(index => (uint)index < faces.Count).Order().ToList();
        var edgeFaces = new Dictionary<
            ((long X, long Y, long Z) A, (long X, long Y, long Z) B), List<int>>();
        foreach (int faceIndex in indices)
        {
            var face = faces[faceIndex];
            IEnumerable<IReadOnlyList<double[]>> rings = face.OuterVertices is { Count: >= 3 } outer
                ? new[] { (IReadOnlyList<double[]>)outer }
                    .Concat(face.InnerVertices ?? Enumerable.Empty<List<double[]>>())
                : Enumerable.Empty<IReadOnlyList<double[]>>();
            foreach (var ring in rings)
                for (int index = 0; index < ring.Count; index++)
                {
                    if (ring[index].Length < 3 || ring[(index + 1) % ring.Count].Length < 3)
                        continue;
                    var first = PointKey(ring[index]);
                    var second = PointKey(ring[(index + 1) % ring.Count]);
                    if (first == second) continue;
                    var edge = EdgeKey(first, second);
                    if (!edgeFaces.TryGetValue(edge, out var owners))
                        edgeFaces[edge] = owners = [];
                    if (!owners.Contains(faceIndex)) owners.Add(faceIndex);
                }
        }

        var adjacency = indices.ToDictionary(index => index, _ => new HashSet<int>());
        foreach (var owners in edgeFaces.Values)
            for (int first = 0; first < owners.Count; first++)
                for (int second = first + 1; second < owners.Count; second++)
                {
                    adjacency[owners[first]].Add(owners[second]);
                    adjacency[owners[second]].Add(owners[first]);
                }

        var result = new List<List<int>>();
        var visited = new HashSet<int>();
        foreach (int seed in indices)
        {
            if (!visited.Add(seed)) continue;
            var component = new List<int>();
            var queue = new Queue<int>();
            queue.Enqueue(seed);
            while (queue.Count > 0)
            {
                int current = queue.Dequeue();
                component.Add(current);
                foreach (int neighbour in adjacency[current].Order())
                    if (visited.Add(neighbour)) queue.Enqueue(neighbour);
            }
            component.Sort();
            result.Add(component);
        }
        return result;
    }

    /// <summary>
    /// Finds exact correspondences between the interiors of parallel residual boundary paths.
    /// </summary>
    internal static List<((long X, long Y, long Z) First,
        (long X, long Y, long Z) Second)> GetReciprocalInteriorAxisBoundaryPairs(
        IReadOnlyCollection<((long X, long Y, long Z) A,
            (long X, long Y, long Z) B)> boundaryEdges)
    {
        var incident = new Dictionary<(long X, long Y, long Z),
            List<(long X, long Y, long Z)>>();
        void Add((long X, long Y, long Z) vertex,
            (long X, long Y, long Z) other)
        {
            if (!incident.TryGetValue(vertex, out var neighbours))
                incident[vertex] = neighbours = [];
            neighbours.Add(other);
        }
        foreach (var edge in boundaryEdges)
        {
            Add(edge.A, edge.B);
            Add(edge.B, edge.A);
        }
        static System.Numerics.BigInteger BoundaryTurn(
            (long X, long Y, long Z) vertex,
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second) =>
            ((System.Numerics.BigInteger)first.X - vertex.X)
                * ((System.Numerics.BigInteger)second.X - vertex.X)
            + ((System.Numerics.BigInteger)first.Y - vertex.Y)
                * ((System.Numerics.BigInteger)second.Y - vertex.Y)
            + ((System.Numerics.BigInteger)first.Z - vertex.Z)
                * ((System.Numerics.BigInteger)second.Z - vertex.Z);
        var interior = incident
            .Where(pair => pair.Value.Count == 2
                && BoundaryTurn(pair.Key, pair.Value[0], pair.Value[1]) < 0)
            .Select(pair => pair.Key).ToHashSet();
        var nearest = new Dictionary<(long X, long Y, long Z),
            (long X, long Y, long Z)>();
        foreach (var vertex in interior)
        {
            var existingNeighbours = incident[vertex].ToHashSet();
            var candidates = interior
                .Where(candidate => candidate != vertex
                    && !existingNeighbours.Contains(candidate)
                    && ((candidate.X != vertex.X ? 1 : 0)
                        + (candidate.Y != vertex.Y ? 1 : 0)
                        + (candidate.Z != vertex.Z ? 1 : 0)) == 1)
                .Select(candidate => new
                {
                    Vertex = candidate,
                    Distance = System.Numerics.BigInteger.Abs(
                        ((System.Numerics.BigInteger)candidate.X - vertex.X)
                        + ((System.Numerics.BigInteger)candidate.Y - vertex.Y)
                        + ((System.Numerics.BigInteger)candidate.Z - vertex.Z)),
                })
                .OrderBy(candidate => candidate.Distance)
                .ToList();
            if (candidates.Count == 0) continue;
            var minimum = candidates[0].Distance;
            var minima = candidates.Where(candidate => candidate.Distance == minimum)
                .Take(2).ToList();
            if (minima.Count == 1) nearest[vertex] = minima[0].Vertex;
        }
        var result = new List<((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        foreach (var pair in nearest.OrderBy(pair => pair.Key))
            if (pair.Key.CompareTo(pair.Value) < 0
                && nearest.TryGetValue(pair.Value, out var reciprocal)
                && reciprocal == pair.Key)
                result.Add((pair.Key, pair.Value));
        return result;
    }

    /// <summary>
    /// A chain is processed to a fixed point because removing one zero-area strip can expose the
    /// next.
    /// </summary>
    internal static bool TryOrientPrecisionContractedFacetedShell(
        IReadOnlyList<GeoFace> faces, IReadOnlyCollection<int> faceIndices,
        out List<int> retainedSourceIndices, out List<GeoFace> orientedFaces)
    {
        retainedSourceIndices = [];
        orientedFaces = [];
        var indices = faceIndices.Distinct().Order().ToList();
        if (indices.Count < 4 || indices.Any(index => (uint)index >= faces.Count))
            return false;

        var parent = new Dictionary<(long X, long Y, long Z),
            (long X, long Y, long Z)>();
        IEnumerable<IReadOnlyList<double[]>> Rings(GeoFace face)
        {
            if (face.OuterVertices is { Count: > 0 } outer) yield return outer;
            foreach (var inner in face.InnerVertices ?? []) yield return inner;
        }
        foreach (int faceIndex in indices)
            foreach (var ring in Rings(faces[faceIndex]))
                foreach (var point in ring)
                    if (point.Length >= 3 && point.Take(3).All(double.IsFinite))
                    {
                        var key = IfcPrecisionKeyFeet(point);
                        parent.TryAdd(key, key);
                    }
        if (parent.Count < 4) return false;

        (long X, long Y, long Z) Find((long X, long Y, long Z) key)
        {
            var root = parent[key];
            if (root != key) parent[key] = root = Find(root);
            return root;
        }
        bool Union((long X, long Y, long Z) first, (long X, long Y, long Z) second)
        {
            first = Find(first);
            second = Find(second);
            if (first == second) return false;
            if (first.CompareTo(second) > 0) (first, second) = (second, first);
            parent[second] = first;
            return true;
        }
        static GeoFace CopyFace(GeoFace source, Func<double[], double[]> copyPoint)
        {
            List<double[]> CopyRing(IEnumerable<double[]> ring) =>
                ring.Select(copyPoint).ToList();
            return new GeoFace
            {
                Origin = (double[])source.Origin.Clone(),
                XVector = (double[])source.XVector.Clone(),
                YVector = (double[])source.YVector.Clone(),
                Normal = (double[])source.Normal.Clone(),
                Envelope = source.Envelope is null ? null : (double[])source.Envelope.Clone(),
                Area = source.Area,
                InnerLoops = source.InnerLoops?.Select(loop => (double[])loop.Clone()).ToList(),
                OuterVertices = source.OuterVertices is null
                    ? null : CopyRing(source.OuterVertices),
                InnerVertices = source.InnerVertices?.Select(CopyRing).ToList(),
                AlternativeOuterVertices = source.AlternativeOuterVertices is null
                    ? null : CopyRing(source.AlternativeOuterVertices),
                EdgeIndices = source.EdgeIndices?.ToList(),
            };
        }
        double precisionFeet = IfcGeometryPrecisionMetres / FeetToMetres;
        double precisionSquared = precisionFeet * precisionFeet;
        GeoFace Materialize(GeoFace source)
        {
            double[] Point(double[] point)
            {
                if (point.Length < 3 || !point.Take(3).All(double.IsFinite))
                    return (double[])point.Clone();
                var key = IfcPrecisionKeyFeet(point);
                // Alternative display rings are copied for metadata fidelity but do not participate
                // in the authored BRep shell.
                if (!parent.ContainsKey(key)) return (double[])point.Clone();
                var root = Find(key);
                return
                [
                    root.X * precisionFeet,
                    root.Y * precisionFeet,
                    root.Z * precisionFeet,
                ];
            }
            return CopyFace(source, Point);
        }

        bool contracted = false;
        bool changed;
        do
        {
            changed = false;
            foreach (int faceIndex in indices)
            {
                if (!FaceCollapsesAtIfcPrecision(Materialize(faces[faceIndex]))) continue;
                foreach (var ring in Rings(faces[faceIndex]))
                {
                    for (int edgeIndex = 0; edgeIndex < ring.Count; edgeIndex++)
                    {
                        var first = ring[edgeIndex];
                        var second = ring[(edgeIndex + 1) % ring.Count];
                        if (first.Length < 3 || second.Length < 3
                            || !first.Take(3).All(double.IsFinite)
                            || !second.Take(3).All(double.IsFinite))
                            continue;
                        double dx = second[0] - first[0];
                        double dy = second[1] - first[1];
                        double dz = second[2] - first[2];
                        double lengthSquared = dx * dx + dy * dy + dz * dz;
                        if (!double.IsFinite(lengthSquared)
                            || lengthSquared > precisionSquared)
                            continue;
                        var firstKey = IfcPrecisionKeyFeet(first);
                        var secondKey = IfcPrecisionKeyFeet(second);
                        if (firstKey != secondKey && Union(firstKey, secondKey))
                        {
                            contracted = true;
                            changed = true;
                        }
                    }
                }
            }
        }
        while (changed);

        var boundaryMergedKeys = new HashSet<(long X, long Y, long Z)>();
        bool UnionBoundary((long X, long Y, long Z) first,
            (long X, long Y, long Z) second)
        {
            if (!Union(first, second)) return false;
            boundaryMergedKeys.Add(first);
            boundaryMergedKeys.Add(second);
            return true;
        }

        (List<int> Sources, List<GeoFace> Faces) PrepareFaces()
        {
            static List<double[]> Clean(IEnumerable<double[]> ring)
            {
                var clean = new List<double[]>();
                foreach (var point in ring)
                    if (clean.Count == 0
                        || IfcPrecisionKeyFeet(clean[^1]) != IfcPrecisionKeyFeet(point))
                        clean.Add(point);
                if (clean.Count > 1
                    && IfcPrecisionKeyFeet(clean[0]) == IfcPrecisionKeyFeet(clean[^1]))
                    clean.RemoveAt(clean.Count - 1);
                return clean;
            }
            var boundaryRoots = boundaryMergedKeys.Select(Find).ToHashSet();
            bool HasSubPrecisionEdge(GeoFace face)
            {
                foreach (var ring in Rings(face))
                    for (int index = 0; index < ring.Count; index++)
                    {
                        var firstPoint = ring[index];
                        var secondPoint = ring[(index + 1) % ring.Count];
                        double dxFeet = secondPoint[0] - firstPoint[0];
                        double dyFeet = secondPoint[1] - firstPoint[1];
                        double dzFeet = secondPoint[2] - firstPoint[2];
                        if (dxFeet * dxFeet + dyFeet * dyFeet + dzFeet * dzFeet
                            <= precisionSquared)
                            return true;
                        var first = IfcPrecisionKeyFeet(firstPoint);
                        var second = IfcPrecisionKeyFeet(secondPoint);
                        var dx = (System.Numerics.BigInteger)second.X - first.X;
                        var dy = (System.Numerics.BigInteger)second.Y - first.Y;
                        var dz = (System.Numerics.BigInteger)second.Z - first.Z;
                        if (dx * dx + dy * dy + dz * dz <= 1
                            && (boundaryRoots.Contains(Find(first))
                                || boundaryRoots.Contains(Find(second))))
                            return true;
                    }
                return false;
            }
            var source = new List<int>();
            var result = new List<GeoFace>();
            foreach (int faceIndex in indices)
            {
                var face = Materialize(faces[faceIndex]);
                if (face.OuterVertices is not { Count: >= 3 } outer) continue;
                face.OuterVertices = Clean(outer);
                if (face.OuterVertices.Count < 3 || FaceCollapsesAtIfcPrecision(face)
                    || HasSubPrecisionEdge(face))
                    continue;
                face.InnerVertices = face.InnerVertices?
                    .Select(Clean)
                    .Where(ring => ring.Count >= 3
                        && !FaceCollapsesAtIfcPrecision(
                            new GeoFace { OuterVertices = ring }))
                    .ToList();
                source.Add(faceIndex);
                result.Add(face);
            }
            return (source, result);
        }

        // A collapsed strip can leave a sub-precision boundary cycle even when none of its
        // surviving facets is itself degenerate.
        while (true)
        {
            var prepared = PrepareFaces();
            var faceMap = Enumerable.Range(0, prepared.Faces.Count)
                .ToDictionary(index => index, index => prepared.Faces[index]);
            var preparedIndices = Enumerable.Range(0, prepared.Faces.Count).ToList();
            if (preparedIndices.Count < 4) break;
            bool closedEdges = TryGetFacetedAtomicEdgeUses(
                faceMap, preparedIndices, out var edgeUses);
            if (closedEdges)
                break;
            bool boundaryChanged = false;
            var boundaryEdges = edgeUses
                .Where(pair => pair.Value.Count == 1).Select(pair => pair.Key).ToList();
            static System.Numerics.BigInteger SquaredBins(
                (long X, long Y, long Z) first, (long X, long Y, long Z) second)
            {
                long dx = second.X - first.X;
                long dy = second.Y - first.Y;
                long dz = second.Z - first.Z;
                return (System.Numerics.BigInteger)dx * dx
                    + (System.Numerics.BigInteger)dy * dy
                    + (System.Numerics.BigInteger)dz * dz;
            }
            foreach (var edge in boundaryEdges)
            {
                if (SquaredBins(edge.A, edge.B) > 1) continue;
                if (UnionBoundary(edge.A, edge.B))
                {
                    contracted = true;
                    boundaryChanged = true;
                }
            }
            // Removing a collapsed triangular wedge leaves exactly two boundary edges incident at
            // its surviving endpoint.
            var incident = new Dictionary<(long X, long Y, long Z),
                List<(long X, long Y, long Z)>>();
            void AddIncident((long X, long Y, long Z) vertex,
                (long X, long Y, long Z) other)
            {
                if (!incident.TryGetValue(vertex, out var others))
                    incident[vertex] = others = [];
                others.Add(other);
            }
            foreach (var edge in boundaryEdges)
            {
                AddIncident(edge.A, edge.B);
                AddIncident(edge.B, edge.A);
            }
            foreach (var pair in incident.Where(pair => pair.Value.Count == 2))
            {
                var first = pair.Value[0];
                var second = pair.Value[1];
                if (first == second || SquaredBins(first, second) > 1) continue;
                if (UnionBoundary(first, second))
                {
                    contracted = true;
                    boundaryChanged = true;
                }
            }
            // A removed strip can also leave two parallel boundary chains with no shared endpoint.
            var boundaryVertices = boundaryEdges
                .SelectMany(edge => new[] { edge.A, edge.B }).Distinct().ToHashSet();
            var uniqueNear = new Dictionary<(long X, long Y, long Z),
                (long X, long Y, long Z)>();
            foreach (var vertex in boundaryVertices)
            {
                var candidates = new[]
                {
                    (vertex.X - 1, vertex.Y, vertex.Z),
                    (vertex.X + 1, vertex.Y, vertex.Z),
                    (vertex.X, vertex.Y - 1, vertex.Z),
                    (vertex.X, vertex.Y + 1, vertex.Z),
                    (vertex.X, vertex.Y, vertex.Z - 1),
                    (vertex.X, vertex.Y, vertex.Z + 1),
                }.Where(boundaryVertices.Contains).ToList();
                if (candidates.Count == 1) uniqueNear[vertex] = candidates[0];
            }
            foreach (var pair in uniqueNear)
                if (uniqueNear.TryGetValue(pair.Value, out var reciprocal)
                    && reciprocal == pair.Key
                    && UnionBoundary(pair.Key, pair.Value))
                {
                    contracted = true;
                    boundaryChanged = true;
                }
            // After a chain of individually sub-precision strips is removed, the two residual paths
            // can be more than one precision bin apart cumulatively.
            if (!boundaryChanged)
            {
                foreach (var pair in GetReciprocalInteriorAxisBoundaryPairs(boundaryEdges))
                    if (UnionBoundary(pair.First, pair.Second))
                    {
                        contracted = true;
                        boundaryChanged = true;
                    }
            }
            if (!boundaryChanged) break;
        }
        if (!contracted) return false;

        var finalFaces = PrepareFaces();
        retainedSourceIndices.AddRange(finalFaces.Sources);
        var contractedFaces = finalFaces.Faces;
        bool oriented = contractedFaces.Count >= 4
            && TryOrientExactFacetedShell(contractedFaces,
                Enumerable.Range(0, contractedFaces.Count).ToList(), out orientedFaces);
        if (!oriented)
        {
            retainedSourceIndices = [];
            orientedFaces = [];
            return false;
        }
        return true;
    }

    /// <summary>
    /// Orients every face of one closed component consistently and then chooses the outward global
    /// orientation from its signed volume.
    /// </summary>
    internal static bool TryOrientExactFacetedShell(IReadOnlyList<GeoFace> faces,
        IReadOnlyCollection<int> faceIndices, out List<GeoFace> orientedFaces,
        bool triangulateNonPlanarFaces = true)
    {
        orientedFaces = [];
        var indices = faceIndices.Distinct().Order().ToList();
        if (indices.Count < 4 || indices.Any(index => (uint)index >= faces.Count))
            return false;
        var normalizedFaces = new Dictionary<int, GeoFace>();
        foreach (int faceIndex in indices)
        {
            var normalized = CloneFace(faces[faceIndex], false);
            if (normalized.OuterVertices is not { Count: >= 3 } outer
                || outer.Any(point => point.Length < 3
                    || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2])))
                return false;
            normalized.OuterVertices = CleanPrecisionLoop(outer);
            if (normalized.OuterVertices.Count < 3
                || FaceCollapsesAtIfcPrecision(normalized))
                return false;
            normalized.InnerVertices = normalized.InnerVertices?
                .Where(ring => ring.Count >= 3 && ring.All(point => point.Length >= 3
                    && double.IsFinite(point[0]) && double.IsFinite(point[1])
                    && double.IsFinite(point[2])))
                .Select(CleanPrecisionLoop)
                .Where(ring => ring.Count >= 3
                    && !FaceCollapsesAtIfcPrecision(new GeoFace
                        { OuterVertices = ring }))
                .ToList();
            if (!TryNormalizeInnerBounds(normalized))
                return false;
            normalizedFaces[faceIndex] = normalized;
        }
        if (!TryGetFacetedAtomicEdgeUses(normalizedFaces, indices, out var edgeUses))
            return false;

        var constraints = indices.ToDictionary(index => index,
            _ => new List<(int Other, bool OppositeFlip)>());
        foreach (var uses in edgeUses.Values)
        {
            bool oppositeFlip = uses[0].Direction == uses[1].Direction;
            constraints[uses[0].FaceIndex].Add((uses[1].FaceIndex, oppositeFlip));
            constraints[uses[1].FaceIndex].Add((uses[0].FaceIndex, oppositeFlip));
        }

        var flips = new Dictionary<int, bool>();
        foreach (int seed in indices)
        {
            if (flips.ContainsKey(seed)) continue;
            flips[seed] = false;
            var queue = new Queue<int>();
            queue.Enqueue(seed);
            while (queue.Count > 0)
            {
                int current = queue.Dequeue();
                foreach (var (other, oppositeFlip) in constraints[current])
                {
                    bool required = flips[current] ^ oppositeFlip;
                    if (flips.TryGetValue(other, out bool existing))
                    {
                        if (existing != required)
                            return false;
                    }
                    else
                    {
                        flips[other] = required;
                        queue.Enqueue(other);
                    }
                }
            }
        }

        orientedFaces = indices.Select(index =>
            CloneFace(normalizedFaces[index], flips[index])).ToList();
        SplitFacetedLoopsAtSharedVertices(orientedFaces);
        var compactIndices = Enumerable.Range(0, orientedFaces.Count).ToList();
        if (!IsExactFacetedShell(orientedFaces, compactIndices))
        {
            orientedFaces = [];
            return false;
        }

        var points = orientedFaces.SelectMany(face =>
                (face.OuterVertices ?? []).Concat((face.InnerVertices ?? []).SelectMany(ring => ring)))
            .ToList();
        double[] origin =
        [
            points.Average(point => point[0]),
            points.Average(point => point[1]),
            points.Average(point => point[2]),
        ];
        double signedVolume = orientedFaces.Sum(face =>
            SignedFaceVolume(face.OuterVertices!, origin)
            + (face.InnerVertices?.Sum(ring => SignedFaceVolume(ring, origin)) ?? 0));
        if (!double.IsFinite(signedVolume) || signedVolume == 0)
        {
            orientedFaces = [];
            return false;
        }
        if (signedVolume < 0)
            orientedFaces = orientedFaces.Select(face => CloneFace(face, true)).ToList();
        if (!triangulateNonPlanarFaces || s_keepNonPlanarPolygons)
            return true;
        var triangulatedFaces = TriangulateNonPlanarFacetedFaces(orientedFaces);
        SplitFacetedLoopsAtSharedVertices(triangulatedFaces);
        if (IsExactFacetedShell(triangulatedFaces,
                Enumerable.Range(0, triangulatedFaces.Count).ToList()))
            orientedFaces = triangulatedFaces;
        return true;

        static double SignedFaceVolume(IReadOnlyList<double[]> ring, double[] origin)
        {
            double volume = 0;
            var first = ring[0];
            for (int index = 1; index + 1 < ring.Count; index++)
            {
                double ax = first[0] - origin[0], ay = first[1] - origin[1], az = first[2] - origin[2];
                double bx = ring[index][0] - origin[0], by = ring[index][1] - origin[1], bz = ring[index][2] - origin[2];
                double cx = ring[index + 1][0] - origin[0], cy = ring[index + 1][1] - origin[1], cz = ring[index + 1][2] - origin[2];
                volume += (ax * (by * cz - bz * cy) - ay * (bx * cz - bz * cx)
                    + az * (bx * cy - by * cx)) / 6;
            }
            return volume;
        }

        static bool TryNormalizeInnerBounds(GeoFace face)
        {
            if (face.InnerVertices is not { Count: > 0 }) return true;
            if (face.OuterVertices is not { Count: >= 3 } outer
                || !TryNewellNormal(outer, out var outerNormal))
                return false;
            foreach (var inner in face.InnerVertices)
            {
                if (inner.Count < 3 || !TryNewellNormal(inner, out var innerNormal))
                    return false;
                double dot = outerNormal.X * innerNormal.X
                    + outerNormal.Y * innerNormal.Y + outerNormal.Z * innerNormal.Z;
                if (!double.IsFinite(dot) || dot == 0) return false;
                bool isStrictlyContained = IsStrictlyContainedAtIfcPrecision(
                    inner, outer, outerNormal);
                bool hasSameDirection = dot > 0;
                if (isStrictlyContained == hasSameDirection) inner.Reverse();
            }
            return true;
        }

        static bool IsStrictlyContainedAtIfcPrecision(IReadOnlyList<double[]> inner,
            IReadOnlyList<double[]> outer, (double X, double Y, double Z) outerNormal)
        {
            int droppedAxis = Math.Abs(outerNormal.X) >= Math.Abs(outerNormal.Y)
                && Math.Abs(outerNormal.X) >= Math.Abs(outerNormal.Z) ? 0
                : Math.Abs(outerNormal.Y) >= Math.Abs(outerNormal.Z) ? 1 : 2;
            static (long U, long V) Project(double[] point, int droppedAxis)
            {
                var key = IfcPrecisionKeyFeet(point);
                return droppedAxis == 0 ? (key.Y, key.Z)
                    : droppedAxis == 1 ? (key.X, key.Z) : (key.X, key.Y);
            }
            static Int128 Orientation((long U, long V) first, (long U, long V) second,
                (long U, long V) point) =>
                ((Int128)second.U - first.U) * ((Int128)point.V - first.V)
                - ((Int128)second.V - first.V) * ((Int128)point.U - first.U);
            static bool OnSegment((long U, long V) point, (long U, long V) first,
                (long U, long V) second) => Orientation(first, second, point) == 0
                && point.U >= Math.Min(first.U, second.U)
                && point.U <= Math.Max(first.U, second.U)
                && point.V >= Math.Min(first.V, second.V)
                && point.V <= Math.Max(first.V, second.V);
            static bool StrictlyInside((long U, long V) point,
                IReadOnlyList<(long U, long V)> polygon)
            {
                int winding = 0;
                for (int index = 0; index < polygon.Count; index++)
                {
                    var first = polygon[index];
                    var second = polygon[(index + 1) % polygon.Count];
                    Int128 orientation = Orientation(first, second, point);
                    if (orientation == 0 && OnSegment(point, first, second)) return false;
                    if (first.V <= point.V && point.V < second.V && orientation > 0) winding++;
                    else if (second.V <= point.V && point.V < first.V && orientation < 0) winding--;
                }
                return winding != 0;
            }
            static bool Intersects((long U, long V) firstA, (long U, long V) secondA,
                (long U, long V) firstB, (long U, long V) secondB)
            {
                Int128 ab1 = Orientation(firstA, secondA, firstB);
                Int128 ab2 = Orientation(firstA, secondA, secondB);
                Int128 ba1 = Orientation(firstB, secondB, firstA);
                Int128 ba2 = Orientation(firstB, secondB, secondA);
                if (ab1 == 0 && OnSegment(firstB, firstA, secondA)) return true;
                if (ab2 == 0 && OnSegment(secondB, firstA, secondA)) return true;
                if (ba1 == 0 && OnSegment(firstA, firstB, secondB)) return true;
                if (ba2 == 0 && OnSegment(secondA, firstB, secondB)) return true;
                return (ab1 < 0) != (ab2 < 0) && (ba1 < 0) != (ba2 < 0);
            }

            var outer2d = outer.Select(point => Project(point, droppedAxis)).ToList();
            var inner2d = inner.Select(point => Project(point, droppedAxis)).ToList();
            if (outer2d.Distinct().Count() < 3 || inner2d.Distinct().Count() < 3
                || inner2d.Any(point => !StrictlyInside(point, outer2d)))
                return false;
            for (int innerIndex = 0; innerIndex < inner2d.Count; innerIndex++)
                for (int outerIndex = 0; outerIndex < outer2d.Count; outerIndex++)
                    if (Intersects(inner2d[innerIndex], inner2d[(innerIndex + 1) % inner2d.Count],
                            outer2d[outerIndex], outer2d[(outerIndex + 1) % outer2d.Count]))
                        return false;
            return true;
        }

        static bool TryNewellNormal(IReadOnlyList<double[]> ring,
            out (double X, double Y, double Z) normal)
        {
            double x = 0, y = 0, z = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                var current = ring[index];
                var next = ring[(index + 1) % ring.Count];
                if (current.Length < 3 || next.Length < 3
                    || !double.IsFinite(current[0]) || !double.IsFinite(current[1])
                    || !double.IsFinite(current[2]) || !double.IsFinite(next[0])
                    || !double.IsFinite(next[1]) || !double.IsFinite(next[2]))
                {
                    normal = default;
                    return false;
                }
                x += (current[1] - next[1]) * (current[2] + next[2]);
                y += (current[2] - next[2]) * (current[0] + next[0]);
                z += (current[0] - next[0]) * (current[1] + next[1]);
            }
            normal = (x, y, z);
            return double.IsFinite(x) && double.IsFinite(y) && double.IsFinite(z)
                && (x != 0 || y != 0 || z != 0);
        }

        static List<double[]> CleanPrecisionLoop(IEnumerable<double[]> source)
        {
            var clean = new List<double[]>();
            foreach (var point in source)
                if (clean.Count == 0
                    || IfcPrecisionKeyFeet(clean[^1]) != IfcPrecisionKeyFeet(point))
                    clean.Add((double[])point.Clone());
            if (clean.Count > 1
                && IfcPrecisionKeyFeet(clean[0]) == IfcPrecisionKeyFeet(clean[^1]))
                clean.RemoveAt(clean.Count - 1);
            return clean;
        }

        static GeoFace CloneFace(GeoFace source, bool reverse)
        {
            List<double[]> CopyRing(IEnumerable<double[]> ring)
            {
                var copy = ring.Select(point => (double[])point.Clone()).ToList();
                if (reverse) copy.Reverse();
                return copy;
            }
            return new GeoFace
            {
                Origin = (double[])source.Origin.Clone(),
                XVector = (double[])source.XVector.Clone(),
                YVector = (double[])source.YVector.Clone(),
                Normal = reverse ? source.Normal.Select(value => -value).ToArray()
                    : (double[])source.Normal.Clone(),
                Envelope = source.Envelope is null ? null : (double[])source.Envelope.Clone(),
                Area = source.Area,
                InnerLoops = source.InnerLoops?.Select(loop => (double[])loop.Clone()).ToList(),
                OuterVertices = source.OuterVertices is null ? null : CopyRing(source.OuterVertices),
                InnerVertices = source.InnerVertices?.Select(CopyRing).ToList(),
                AlternativeOuterVertices = source.AlternativeOuterVertices is null ? null
                    : source.AlternativeOuterVertices.Select(point => (double[])point.Clone()).ToList(),
                EdgeIndices = source.EdgeIndices?.ToList(),
            };
        }
    }

    /// <summary>
    /// Converts precision-nonplanar polygon faces to triangles using exact projected ear clipping.
    /// </summary>
    private static List<GeoFace> TriangulateNonPlanarFacetedFaces(
        IReadOnlyList<GeoFace> faces)
    {

        static GeoFace Triangle(GeoFace source, params double[][] vertices) => new()
        {
            Origin = (double[])source.Origin.Clone(),
            XVector = (double[])source.XVector.Clone(),
            YVector = (double[])source.YVector.Clone(),
            Normal = (double[])source.Normal.Clone(),
            Envelope = source.Envelope is null ? null : (double[])source.Envelope.Clone(),
            Area = source.Area,
            InnerLoops = source.InnerLoops?.Select(loop => (double[])loop.Clone()).ToList(),
            OuterVertices = vertices.Select(point => (double[])point.Clone()).ToList(),
            EdgeIndices = source.EdgeIndices?.ToList(),
        };
        static bool TryProjectedShape(IReadOnlyList<double[]> ring,
            out bool planar, out bool convex)
        {
            planar = false;
            convex = false;
            var points = ring.Select(IfcPrecisionKeyFeet).ToList();
            if (points.Count < 4 || points.Distinct().Count() != points.Count) return false;
            System.Numerics.BigInteger nx = 0, ny = 0, nz = 0;
            for (int index = 0; index < points.Count; index++)
            {
                var current = points[index];
                var next = points[(index + 1) % points.Count];
                nx += ((System.Numerics.BigInteger)current.Y - next.Y) * (current.Z + next.Z);
                ny += ((System.Numerics.BigInteger)current.Z - next.Z) * (current.X + next.X);
                nz += ((System.Numerics.BigInteger)current.X - next.X) * (current.Y + next.Y);
            }
            if (nx.IsZero && ny.IsZero && nz.IsZero) return false;
            var absX = System.Numerics.BigInteger.Abs(nx);
            var absY = System.Numerics.BigInteger.Abs(ny);
            var absZ = System.Numerics.BigInteger.Abs(nz);
            int droppedAxis = absX >= absY && absX >= absZ ? 0 : absY >= absZ ? 1 : 2;
            static (long U, long V) Project((long X, long Y, long Z) point, int axis) =>
                axis == 0 ? (point.Y, point.Z)
                    : axis == 1 ? (point.X, point.Z) : (point.X, point.Y);
            int sign = 0;
            for (int index = 0; index < points.Count; index++)
            {
                var first = Project(points[index], droppedAxis);
                var second = Project(points[(index + 1) % points.Count], droppedAxis);
                var third = Project(points[(index + 2) % points.Count], droppedAxis);
                var turn = ((System.Numerics.BigInteger)second.U - first.U)
                    * (third.V - second.V)
                    - ((System.Numerics.BigInteger)second.V - first.V)
                    * (third.U - second.U);
                if (turn.IsZero) continue;
                int currentSign = turn.Sign;
                if (sign != 0 && currentSign != sign) return true;
                sign = currentSign;
            }
            convex = sign != 0;

            var origin = points[0];
            (System.Numerics.BigInteger X, System.Numerics.BigInteger Y,
                System.Numerics.BigInteger Z)? normal = null;
            for (int index = 1; index + 1 < points.Count && normal == null; index++)
            {
                var first = points[index];
                var second = points[index + 1];
                var ux = (System.Numerics.BigInteger)first.X - origin.X;
                var uy = (System.Numerics.BigInteger)first.Y - origin.Y;
                var uz = (System.Numerics.BigInteger)first.Z - origin.Z;
                var vx = (System.Numerics.BigInteger)second.X - origin.X;
                var vy = (System.Numerics.BigInteger)second.Y - origin.Y;
                var vz = (System.Numerics.BigInteger)second.Z - origin.Z;
                var cross = (X: uy * vz - uz * vy, Y: uz * vx - ux * vz,
                    Z: ux * vy - uy * vx);
                if (!cross.X.IsZero || !cross.Y.IsZero || !cross.Z.IsZero)
                    normal = cross;
            }
            if (normal == null) return false;
            planar = points.All(point =>
                normal.Value.X * ((System.Numerics.BigInteger)point.X - origin.X)
                + normal.Value.Y * ((System.Numerics.BigInteger)point.Y - origin.Y)
                + normal.Value.Z * ((System.Numerics.BigInteger)point.Z - origin.Z) == 0);
            return true;
        }

        static List<GeoFace>? EarClip(GeoFace face, IReadOnlyList<double[]> ring)
        {
            var points = ring.Select(IfcPrecisionKeyFeet).ToList();
            System.Numerics.BigInteger nx = 0, ny = 0, nz = 0;
            for (int index = 0; index < points.Count; index++)
            {
                var current = points[index];
                var next = points[(index + 1) % points.Count];
                nx += ((System.Numerics.BigInteger)current.Y - next.Y) * (current.Z + next.Z);
                ny += ((System.Numerics.BigInteger)current.Z - next.Z) * (current.X + next.X);
                nz += ((System.Numerics.BigInteger)current.X - next.X) * (current.Y + next.Y);
            }
            var absX = System.Numerics.BigInteger.Abs(nx);
            var absY = System.Numerics.BigInteger.Abs(ny);
            var absZ = System.Numerics.BigInteger.Abs(nz);
            if (absX.IsZero && absY.IsZero && absZ.IsZero) return null;
            int droppedAxis = absX >= absY && absX >= absZ ? 0 : absY >= absZ ? 1 : 2;
            static (long U, long V) Project((long X, long Y, long Z) point, int axis) =>
                axis == 0 ? (point.Y, point.Z)
                    : axis == 1 ? (point.X, point.Z) : (point.X, point.Y);
            var projected = points.Select(point => Project(point, droppedAxis)).ToList();
            static System.Numerics.BigInteger Turn((long U, long V) first,
                (long U, long V) second, (long U, long V) third) =>
                ((System.Numerics.BigInteger)second.U - first.U) * (third.V - first.V)
                - ((System.Numerics.BigInteger)second.V - first.V) * (third.U - first.U);
            System.Numerics.BigInteger twiceArea = 0;
            for (int index = 0; index < projected.Count; index++)
            {
                var current = projected[index];
                var next = projected[(index + 1) % projected.Count];
                twiceArea += (System.Numerics.BigInteger)current.U * next.V
                    - (System.Numerics.BigInteger)next.U * current.V;
            }
            if (twiceArea.IsZero) return null;
            int orientation = twiceArea.Sign;
            var remaining = Enumerable.Range(0, ring.Count).ToList();
            var result = new List<GeoFace>();
            int guard = ring.Count * ring.Count;
            while (remaining.Count > 3 && guard-- > 0)
            {
                bool removed = false;
                for (int offset = 0; offset < remaining.Count; offset++)
                {
                    int previous = remaining[(offset - 1 + remaining.Count) % remaining.Count];
                    int current = remaining[offset];
                    int next = remaining[(offset + 1) % remaining.Count];
                    var turn = Turn(projected[previous], projected[current], projected[next]);
                    if (turn.Sign != orientation) continue;
                    bool contains = remaining.Any(candidate => candidate != previous
                        && candidate != current && candidate != next
                        && new[]
                        {
                            Turn(projected[previous], projected[current], projected[candidate]),
                            Turn(projected[current], projected[next], projected[candidate]),
                            Turn(projected[next], projected[previous], projected[candidate]),
                        }.All(value => value.IsZero || value.Sign == orientation));
                    if (contains) continue;
                    var triangle = Triangle(face,
                        ring[previous], ring[current], ring[next]);
                    if (FaceCollapsesAtIfcPrecision(triangle)) continue;
                    result.Add(triangle);
                    remaining.RemoveAt(offset);
                    removed = true;
                    break;
                }
                if (!removed) return null;
            }
            if (remaining.Count != 3) return null;
            var finalTriangle = Triangle(face,
                ring[remaining[0]], ring[remaining[1]], ring[remaining[2]]);
            if (FaceCollapsesAtIfcPrecision(finalTriangle)) return null;
            result.Add(finalTriangle);
            return result;
        }

        var result = new List<GeoFace>();
        foreach (var face in faces)
        {
            if (face.OuterVertices is not { Count: > 3 } ring
                || face.InnerVertices is { Count: > 0 }
                || !TryProjectedShape(ring, out bool planar, out _)
                || planar)
            {
                result.Add(face);
                continue;
            }
            result.AddRange(EarClip(face, ring) ?? [face]);
        }
        return result;
    }

    /// <summary>
    /// Materializes the same atomic edge partition used by shell validation in the actual polygon
    /// loops written to IFC.
    /// </summary>
    private static void SplitFacetedLoopsAtSharedVertices(IReadOnlyList<GeoFace> faces)
    {
        static long Axis((long X, long Y, long Z) point, int axis) =>
            axis == 0 ? point.X : axis == 1 ? point.Y : point.Z;
        static int LowerBound(List<(long X, long Y, long Z)> points, int axis, long value)
        {
            int low = 0, high = points.Count;
            while (low < high)
            {
                int middle = low + (high - low) / 2;
                if (Axis(points[middle], axis) < value) low = middle + 1;
                else high = middle;
            }
            return low;
        }
        static bool OnSegment((long X, long Y, long Z) point,
            (long X, long Y, long Z) first, (long X, long Y, long Z) second)
        {
            if (point.X < Math.Min(first.X, second.X) || point.X > Math.Max(first.X, second.X)
                || point.Y < Math.Min(first.Y, second.Y) || point.Y > Math.Max(first.Y, second.Y)
                || point.Z < Math.Min(first.Z, second.Z) || point.Z > Math.Max(first.Z, second.Z))
                return false;
            Int128 dx = (Int128)second.X - first.X;
            Int128 dy = (Int128)second.Y - first.Y;
            Int128 dz = (Int128)second.Z - first.Z;
            Int128 px = (Int128)point.X - first.X;
            Int128 py = (Int128)point.Y - first.Y;
            Int128 pz = (Int128)point.Z - first.Z;
            return dy * pz - dz * py == 0
                && dz * px - dx * pz == 0
                && dx * py - dy * px == 0;
        }

        var representative = new Dictionary<(long X, long Y, long Z), double[]>();
        foreach (var face in faces)
            foreach (var ring in (face.OuterVertices is { Count: > 0 } outer
                    ? new[] { outer }
                    : Enumerable.Empty<List<double[]>>())
                .Concat(face.InnerVertices ?? []))
                foreach (var point in ring)
                    representative.TryAdd(IfcPrecisionKeyFeet(point), point);
        var vertices = representative.Keys.ToList();
        var verticesByAxis = Enumerable.Range(0, 3)
            .Select(axis => vertices.OrderBy(point => Axis(point, axis))
                .ThenBy(point => point.X).ThenBy(point => point.Y).ThenBy(point => point.Z)
                .ToList()).ToArray();

        List<double[]> Split(IReadOnlyList<double[]> ring)
        {
            var result = new List<double[]>();
            for (int edgeIndex = 0; edgeIndex < ring.Count; edgeIndex++)
            {
                var sourceFirst = ring[edgeIndex];
                var sourceSecond = ring[(edgeIndex + 1) % ring.Count];
                var first = IfcPrecisionKeyFeet(sourceFirst);
                var second = IfcPrecisionKeyFeet(sourceSecond);
                result.Add(sourceFirst);
                if (first == second) continue;
                Int128 dx = (Int128)second.X - first.X;
                Int128 dy = (Int128)second.Y - first.Y;
                Int128 dz = (Int128)second.Z - first.Z;
                Int128 absX = Int128.Abs(dx), absY = Int128.Abs(dy), absZ = Int128.Abs(dz);
                int axis = absX >= absY && absX >= absZ ? 0 : absY >= absZ ? 1 : 2;
                long low = Math.Min(Axis(first, axis), Axis(second, axis));
                long high = Math.Max(Axis(first, axis), Axis(second, axis));
                var split = new List<(long X, long Y, long Z)>();
                var sorted = verticesByAxis[axis];
                for (int index = LowerBound(sorted, axis, low);
                     index < sorted.Count && Axis(sorted[index], axis) <= high; index++)
                    if (sorted[index] != first && sorted[index] != second
                        && OnSegment(sorted[index], first, second))
                        split.Add(sorted[index]);
                split.Sort((left, right) => Axis(left, axis).CompareTo(Axis(right, axis)));
                if (Axis(first, axis) > Axis(second, axis)) split.Reverse();
                result.AddRange(split.Select(point => representative[point]));
            }
            var clean = new List<double[]>();
            foreach (var point in result)
                if (clean.Count == 0
                    || IfcPrecisionKeyFeet(clean[^1]) != IfcPrecisionKeyFeet(point))
                    clean.Add(point);
            if (clean.Count > 1
                && IfcPrecisionKeyFeet(clean[0]) == IfcPrecisionKeyFeet(clean[^1]))
                clean.RemoveAt(clean.Count - 1);
            return clean;
        }

        foreach (var face in faces)
        {
            if (face.OuterVertices is { Count: >= 3 } outer)
                face.OuterVertices = Split(outer);
            if (face.InnerVertices is { Count: > 0 } inner)
                face.InnerVertices = inner.Select(Split).ToList();
        }
    }

    /// <summary>Builds exact shared-edge uses on the serialized IFC coordinate lattice.</summary>
    private static bool TryGetFacetedAtomicEdgeUses(IReadOnlyDictionary<int, GeoFace> faces,
        IReadOnlyCollection<int> faceIndices,
        out Dictionary<((long X, long Y, long Z) A, (long X, long Y, long Z) B),
            List<(int FaceIndex, int Direction)>> edgeUses)
    {
        static ((long X, long Y, long Z) A, (long X, long Y, long Z) B) EdgeKey(
            (long X, long Y, long Z) first, (long X, long Y, long Z) second)
            => first.CompareTo(second) <= 0 ? (first, second) : (second, first);
        static long Axis((long X, long Y, long Z) point, int axis) =>
            axis == 0 ? point.X : axis == 1 ? point.Y : point.Z;
        static int LowerBound(List<(long X, long Y, long Z)> points, int axis, long value)
        {
            int low = 0, high = points.Count;
            while (low < high)
            {
                int middle = low + (high - low) / 2;
                if (Axis(points[middle], axis) < value) low = middle + 1;
                else high = middle;
            }
            return low;
        }
        static bool OnSegment((long X, long Y, long Z) point,
            (long X, long Y, long Z) first, (long X, long Y, long Z) second)
        {
            if (point.X < Math.Min(first.X, second.X) || point.X > Math.Max(first.X, second.X)
                || point.Y < Math.Min(first.Y, second.Y) || point.Y > Math.Max(first.Y, second.Y)
                || point.Z < Math.Min(first.Z, second.Z) || point.Z > Math.Max(first.Z, second.Z))
                return false;
            Int128 dx = (Int128)second.X - first.X;
            Int128 dy = (Int128)second.Y - first.Y;
            Int128 dz = (Int128)second.Z - first.Z;
            Int128 px = (Int128)point.X - first.X;
            Int128 py = (Int128)point.Y - first.Y;
            Int128 pz = (Int128)point.Z - first.Z;
            return dy * pz - dz * py == 0
                && dz * px - dx * pz == 0
                && dx * py - dy * px == 0;
        }

        var usesByEdge = new Dictionary<
            ((long X, long Y, long Z) A, (long X, long Y, long Z) B),
            List<(int FaceIndex, int Direction)>>();
        edgeUses = usesByEdge;
        var segments = new List<(int FaceIndex, (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        foreach (int faceIndex in faceIndices)
        {
            if (!faces.TryGetValue(faceIndex, out var face)
                || face.OuterVertices is not { Count: >= 3 } outer)
                return false;
            IEnumerable<IReadOnlyList<double[]>> rings =
                new[] { (IReadOnlyList<double[]>)outer }
                    .Concat(face.InnerVertices ?? Enumerable.Empty<List<double[]>>());
            foreach (var ring in rings)
            {
                if (ring.Count < 3 || ring.Any(point => point.Length < 3
                        || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                        || !double.IsFinite(point[2])))
                    return false;
                for (int index = 0; index < ring.Count; index++)
                {
                    var first = IfcPrecisionKeyFeet(ring[index]);
                    var second = IfcPrecisionKeyFeet(ring[(index + 1) % ring.Count]);
                    if (first == second) return false;
                    segments.Add((faceIndex, first, second));
                }
            }
        }
        if (segments.Count == 0) return false;

        void AddUse(int faceIndex, (long X, long Y, long Z) first,
            (long X, long Y, long Z) second)
        {
            var edge = EdgeKey(first, second);
            if (!usesByEdge.TryGetValue(edge, out var uses)) usesByEdge[edge] = uses = [];
            uses.Add((faceIndex, first.CompareTo(second) <= 0 ? 1 : -1));
        }
        bool HasClosedMultiplicity() => usesByEdge.Count > 0
            && usesByEdge.Values.All(uses => uses.Count == 2
                && uses[0].FaceIndex != uses[1].FaceIndex);

        foreach (var segment in segments)
            AddUse(segment.FaceIndex, segment.First, segment.Second);
        if (HasClosedMultiplicity()) return true;

        usesByEdge.Clear();
        var vertices = segments.SelectMany(segment => new[] { segment.First, segment.Second })
            .Distinct().ToList();
        var verticesByAxis = Enumerable.Range(0, 3)
            .Select(axis => vertices.OrderBy(point => Axis(point, axis))
                .ThenBy(point => point.X).ThenBy(point => point.Y).ThenBy(point => point.Z)
                .ToList())
            .ToArray();
        foreach (var segment in segments)
        {
            Int128 dx = (Int128)segment.Second.X - segment.First.X;
            Int128 dy = (Int128)segment.Second.Y - segment.First.Y;
            Int128 dz = (Int128)segment.Second.Z - segment.First.Z;
            Int128 absX = Int128.Abs(dx), absY = Int128.Abs(dy), absZ = Int128.Abs(dz);
            int axis = absX >= absY && absX >= absZ ? 0 : absY >= absZ ? 1 : 2;
            long low = Math.Min(Axis(segment.First, axis), Axis(segment.Second, axis));
            long high = Math.Max(Axis(segment.First, axis), Axis(segment.Second, axis));
            var sorted = verticesByAxis[axis];
            var split = new List<(long X, long Y, long Z)>();
            for (int index = LowerBound(sorted, axis, low);
                 index < sorted.Count && Axis(sorted[index], axis) <= high; index++)
                if (OnSegment(sorted[index], segment.First, segment.Second))
                    split.Add(sorted[index]);
            if (Axis(segment.First, axis) > Axis(segment.Second, axis)) split.Reverse();
            if (split.Count < 2 || split[0] != segment.First || split[^1] != segment.Second)
                return false;
            for (int index = 0; index + 1 < split.Count; index++)
                AddUse(segment.FaceIndex, split[index], split[index + 1]);
        }
        return HasClosedMultiplicity();
    }

    /// <summary>
    /// Checks whether the emitted polygon loops satisfy IFC closed-shell topology using the same
    /// declared-precision identity as the IFC point cache.
    /// </summary>
    internal static bool IsExactFacetedShell(
        IReadOnlyList<GeoFace> faces, IReadOnlyCollection<int> faceIndices)
    {
        var faceMap = faceIndices.Distinct().ToDictionary(index => index,
            index => (uint)index < faces.Count ? faces[index] : null);
        if (faceMap.Values.Any(face => face == null)) return false;
        return TryGetFacetedAtomicEdgeUses(
                faceMap.ToDictionary(pair => pair.Key, pair => pair.Value!),
                faceIndices, out var edgeUses)
            && edgeUses.Values.All(uses => uses[0].Direction + uses[1].Direction == 0);
    }

    /// <summary>Recover a closed gable roof from a surviving six-point end face.</summary>
    private bool TryCreatePitchedRoofShape(StepWriter w, Element elem, double[] bbox,
        int subCtxId, out int shapeId)
    {
        shapeId = 0;
        if (elem.Geometry?.Faces is not { Count: > 0 } faces || bbox.Length < 6) return false;
        double spanX = bbox[3] - bbox[0], spanY = bbox[4] - bbox[1];
        if ((bbox[5] - bbox[2]) * FeetToMetres < 0.8) return false;
        bool longX = spanX >= spanY;
        double longMin = longX ? bbox[0] : bbox[1];
        double longMax = longX ? bbox[3] : bbox[4];
        double longSpan = longMax - longMin;
        if (longSpan <= 0.1) return false;

        static List<double[]> Clean(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (var p in source)
                if (p.Length >= 3 && p.All(double.IsFinite)
                    && !result.Any(q => Math.Abs(q[0] - p[0]) < 1e-5
                        && Math.Abs(q[1] - p[1]) < 1e-5 && Math.Abs(q[2] - p[2]) < 1e-5))
                    result.Add(p);
            return result;
        }

        // A gable end is the largest 5+ vertex face perpendicular to the roof's long axis.
        List<double[]>? end = faces
            .Where(f => f.OuterVertices is { Count: >= 5 })
            .Select(f => Clean(f.OuterVertices!))
            .Where(v => v.Count >= 5
                && v.Max(p => longX ? p[0] : p[1]) - v.Min(p => longX ? p[0] : p[1]) < 0.05
                && Math.Min(Math.Abs(v.Average(p => longX ? p[0] : p[1]) - longMin),
                    Math.Abs(v.Average(p => longX ? p[0] : p[1]) - longMax)) < Math.Max(0.1, longSpan * 0.02))
            .OrderByDescending(v => v.Count)
            .FirstOrDefault();
        if (end is not { Count: >= 6 }) return false;

        double Short(double[] p) => longX ? p[1] : p[0];
        double shortMin = end.Min(Short), shortMax = end.Max(Short);
        double shortSpan = shortMax - shortMin;
        if (shortSpan <= 0.1) return false;
        double edgeTolerance = Math.Max(0.03, shortSpan * 0.02);
        var lowEdge = end.Where(p => Math.Abs(Short(p) - shortMin) <= edgeTolerance).ToList();
        var highEdge = end.Where(p => Math.Abs(Short(p) - shortMax) <= edgeTolerance).ToList();
        var ridge = end.Where(p => Math.Abs(Short(p) - shortMin) > edgeTolerance
            && Math.Abs(Short(p) - shortMax) > edgeTolerance).ToList();
        if (lowEdge.Count < 2 || highEdge.Count < 2 || ridge.Count < 2) return false;

        var lowTop = lowEdge.MaxBy(p => p[2])!; var lowBottom = lowEdge.MinBy(p => p[2])!;
        var highTop = highEdge.MaxBy(p => p[2])!; var highBottom = highEdge.MinBy(p => p[2])!;
        var ridgeTop = ridge.MaxBy(p => p[2])!; var ridgeBottom = ridge.MinBy(p => p[2])!;
        if (ridgeTop[2] - Math.Max(lowTop[2], highTop[2]) < 0.5 / FeetToMetres
            || ridgeTop[2] - ridgeBottom[2] < 0.02 / FeetToMetres) return false;

        double[] Point(double along, double across, double z) => longX
            ? [along * FeetToMetres, across * FeetToMetres, z * FeetToMetres]
            : [across * FeetToMetres, along * FeetToMetres, z * FeetToMetres];
        var cross = new[]
        {
            (S: Short(lowTop), Z: lowTop[2]),
            (S: Short(ridgeTop), Z: ridgeTop[2]),
            (S: Short(highTop), Z: highTop[2]),
            (S: Short(highBottom), Z: highBottom[2]),
            (S: Short(ridgeBottom), Z: ridgeBottom[2]),
            (S: Short(lowBottom), Z: lowBottom[2]),
        };
        var points = new List<double[]>(12);
        points.AddRange(cross.Select(p => Point(longMin, p.S, p.Z)));
        points.AddRange(cross.Select(p => Point(longMax, p.S, p.Z)));

        var polygons = new List<int[]>();
        int[] cap0 = Enumerable.Range(0, 6).ToArray();
        int[] cap1 = Enumerable.Range(6, 6).AsEnumerable().Reverse().ToArray();
        if (!longX) { Array.Reverse(cap0); Array.Reverse(cap1); }
        polygons.Add(cap0); polygons.Add(cap1);
        for (int i = 0; i < 6; i++)
        {
            int j = (i + 1) % 6;
            polygons.Add(longX ? [i, 6 + i, 6 + j, j] : [i, j, 6 + j, 6 + i]);
        }

        var faceIds = new List<int>();
        foreach (var polygon in polygons)
        {
            var pointIds = polygon.Select(i => w.Add("IFCCARTESIANPOINT",
                StepWriter.List(D(points[i][0]), D(points[i][1]), D(points[i][2])))).ToList();
            int loopId = w.Add("IFCPOLYLOOP", StepWriter.List(pointIds.Select(R)));
            int boundId = w.Add("IFCFACEOUTERBOUND", $"{R(loopId)},.T.");
            faceIds.Add(w.Add("IFCFACE", StepWriter.List(R(boundId))));
        }
        int shellId = w.Add("IFCCLOSEDSHELL", StepWriter.List(faceIds.Select(R)));
        int brepId = w.Add("IFCFACETEDBREP", R(shellId));
        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("Brep")},{StepWriter.List(R(brepId))}");
        shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(R(shapeRepId))}");
        return true;
    }

    /// <summary>
    /// Its instance record contains the AABB of the array helper (about 8.3 x 7.8 ft), while the
    /// native IFC contains one 1.676 x 0.997 m, 10-degree module per instance.
    /// </summary>
    private int CreateSolarPanelShape(StepWriter w, double[] bbox, int subCtxId,
        double[]? sharedTransform)
    {
        // A local U axis which becomes global X after the site placement, and V which becomes
        // global Y.
        double ux = 1, uy = 0;
        if (sharedTransform is { Length: 12 })
        {
            ux = sharedTransform[0];
            uy = -sharedTransform[1];
            double n = Math.Sqrt(ux * ux + uy * uy);
            if (n > 1e-9) { ux /= n; uy /= n; }
            else { ux = 1; uy = 0; }
        }
        double vx = -uy, vy = ux;

        const double lengthM = 1.676;
        const double widthM = 0.997;
        const double offsetUM = 0.249;
        const double offsetVM = 0.162;
        double cx = (bbox[0] + bbox[3]) * 0.5 * FeetToMetres
            + ux * offsetUM + vx * offsetVM;
        double cy = (bbox[1] + bbox[4]) * 0.5 * FeetToMetres
            + uy * offsetUM + vy * offsetVM;
        double z0 = bbox[2] * FeetToMetres, z1 = bbox[5] * FeetToMetres;
        double dz = Math.Max(0.08, z1 - z0);
        double rise = Math.Min(widthM * Math.Tan(10 * Math.PI / 180), dz - 0.05);
        rise = Math.Max(0.03, rise);
        const double panelThickness = 0.04;

        double[] P(double u, double v, double z) =>
            [cx + u * ux + v * vx, cy + u * uy + v * vy, z];

        int AddBrep(IReadOnlyList<double[]> points, IReadOnlyList<int[]> polygons)
        {
            var faceIds = new List<int>();
            foreach (var polygon in polygons)
            {
                var pointIds = polygon.Select(i => w.Add("IFCCARTESIANPOINT",
                    StepWriter.List(D(points[i][0]), D(points[i][1]), D(points[i][2])))).ToList();
                int loopId = w.Add("IFCPOLYLOOP", StepWriter.List(pointIds.Select(R)));
                int boundId = w.Add("IFCFACEOUTERBOUND", $"{R(loopId)},.T.");
                faceIds.Add(w.Add("IFCFACE", StepWriter.List(R(boundId))));
            }
            int shellId = w.Add("IFCCLOSEDSHELL", StepWriter.List(faceIds.Select(R)));
            return w.Add("IFCFACETEDBREP", R(shellId));
        }

        double hu = lengthM / 2, hv = widthM / 2;
        double lowTop = z1 - rise, highTop = z1;
        var panel = new[]
        {
            P(-hu, -hv, lowTop), P(hu, -hv, lowTop),
            P(hu, hv, highTop), P(-hu, hv, highTop),
            P(-hu, -hv, lowTop - panelThickness), P(hu, -hv, lowTop - panelThickness),
            P(hu, hv, highTop - panelThickness), P(-hu, hv, highTop - panelThickness),
        };
        int panelBrep = AddBrep(panel,
        [
            [0, 1, 2, 3], [7, 6, 5, 4], [4, 5, 1, 0],
            [5, 6, 2, 1], [6, 7, 3, 2], [7, 4, 0, 3],
        ]);

        // Two narrow triangular rack frames reach the original bbox bottom, retaining the native
        // export's overall 0.387 m height without making the panel a thick box.
        var breps = new List<int> { panelBrep };
        double supportTop = Math.Max(z0 + 0.06, highTop - panelThickness - 0.015);
        foreach (double uc in new[] { -lengthM * 0.28, lengthM * 0.28 })
        {
            const double halfRail = 0.022;
            double sv = widthM * 0.34;
            var support = new[]
            {
                P(uc - halfRail, -sv, z0), P(uc - halfRail, sv, z0),
                P(uc - halfRail, sv, supportTop),
                P(uc + halfRail, -sv, z0), P(uc + halfRail, sv, z0),
                P(uc + halfRail, sv, supportTop),
            };
            breps.Add(AddBrep(support,
            [
                [0, 2, 1], [3, 4, 5], [0, 1, 4, 3],
                [1, 2, 5, 4], [2, 0, 3, 5],
            ]));
        }

        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("Brep")},{StepWriter.List(breps.Select(R))}");
        return w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(R(shapeRepId))}");
    }

    /// <summary>
    /// Write an open triangulated surface using the IFC2x3 representation Revit uses for
    /// TopographySurface.
    /// </summary>
    private int CreateFaceBasedSurfaceModel(StepWriter w, IReadOnlyList<GeoFace> faces,
        int subCtxId, double[]? boundsFt) =>
        CreateFaceBasedSurfaceModels(w, [(faces, boundsFt)], subCtxId);

    /// <summary>
    /// Write the root terrain and each pad-authored replacement patch as items in one IFC
    /// surface-model representation, matching their RVT ownership graph.
    /// </summary>
    private int CreateFaceBasedSurfaceModels(StepWriter w,
        IReadOnlyList<(IReadOnlyList<GeoFace> Faces, double[]? Bounds)> surfaces,
        int subCtxId)
    {
        var surfaceIds = new List<int>(surfaces.Count);
        foreach (var surface in surfaces)
            surfaceIds.Add(CreateFaceBasedSurfaceModelItem(w, surface.Faces, surface.Bounds));
        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SurfaceModel")},{StepWriter.List(surfaceIds.Select(R))}");
        return w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(R(shapeRepId))}");
    }

    private int CreateFaceBasedSurfaceModelItem(StepWriter w, IReadOnlyList<GeoFace> faces,
        double[]? boundsFt)
    {
        var faceIds = new List<int>();
        var pointIds = new Dictionary<(double X, double Y, double Z), int>();
        foreach (var face in faces)
        {
            if (face.OuterVertices is not { Count: >= 3 } vertices) continue;
            if (vertices.Any(v => v.Length < 3 || !double.IsFinite(v[0])
                || !double.IsFinite(v[1]) || !double.IsFinite(v[2]))) continue;

            var polygonPointIds = new List<int>(vertices.Count);
            foreach (var vertex in vertices)
            {
                var key = (vertex[0], vertex[1], vertex[2]);
                if (!pointIds.TryGetValue(key, out int pointId))
                {
                    pointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
                        D(vertex[0] * FeetToMetres), D(vertex[1] * FeetToMetres),
                        D(vertex[2] * FeetToMetres)));
                    pointIds[key] = pointId;
                }
                polygonPointIds.Add(pointId);
            }
            int loopId = w.Add("IFCPOLYLOOP", StepWriter.List(polygonPointIds.Select(R)));
            int boundId = w.Add("IFCFACEOUTERBOUND", $"{R(loopId)},.T.");
            faceIds.Add(w.Add("IFCFACE", StepWriter.List(R(boundId))));
        }

        if (faceIds.Count < 3)
        {
            string bounds = boundsFt is { Length: >= 6 }
                ? $" within [{string.Join(',', boundsFt)}]" : "";
            throw new InvalidDataException(
                $"A surface model requires at least three valid faces{bounds}.");
        }
        int connectedId = w.Add("IFCCONNECTEDFACESET", StepWriter.List(faceIds.Select(R)));
        return w.Add("IFCFACEBASEDSURFACEMODEL", StepWriter.List(R(connectedId)));
    }

    /// <summary>
    /// Create recognizable low-poly RPC planting while retaining the real centre, height and
    /// Revit-export-equivalent plan diameter.
    /// </summary>
    private int CreatePlantingShape(StepWriter w, double[] bbox, int subCtxId)
    {
        double cx = (bbox[0] + bbox[3]) * 0.5 * FeetToMetres;
        double cy = (bbox[1] + bbox[4]) * 0.5 * FeetToMetres;
        double z0 = bbox[2] * FeetToMetres;
        double height = Math.Max(0.5, (bbox[5] - bbox[2]) * FeetToMetres);
        double rx = Math.Max(0.25, (bbox[3] - bbox[0]) * FeetToMetres * 0.25);
        double ry = Math.Max(0.25, (bbox[4] - bbox[1]) * FeetToMetres * 0.25);

        int Polyhedron(IReadOnlyList<double[]> points, IReadOnlyList<int[]> polygons)
        {
            var faceIds = new List<int>();
            foreach (var polygon in polygons)
            {
                var ids = polygon.Select(i => w.Add("IFCCARTESIANPOINT",
                    StepWriter.List(D(points[i][0]), D(points[i][1]), D(points[i][2])))).ToList();
                int loopId = w.Add("IFCPOLYLOOP", StepWriter.List(ids.Select(R)));
                int boundId = w.Add("IFCFACEOUTERBOUND", $"{R(loopId)},.T.");
                faceIds.Add(w.Add("IFCFACE", StepWriter.List(R(boundId))));
            }
            int shellId = w.Add("IFCCLOSEDSHELL", StepWriter.List(faceIds.Select(R)));
            return w.Add("IFCFACETEDBREP", R(shellId));
        }

        const int segments = 16;
        double trunkRadius = Math.Clamp(Math.Min(rx, ry) * 0.055, 0.10, 0.34);
        double trunkTop = z0 + height * 0.42;
        var trunkPoints = new List<double[]>();
        for (int ring = 0; ring < 2; ring++)
            for (int i = 0; i < segments; i++)
            {
                double a = 2 * Math.PI * i / segments;
                trunkPoints.Add([cx + trunkRadius * Math.Cos(a), cy + trunkRadius * Math.Sin(a),
                    ring == 0 ? z0 : trunkTop]);
            }
        var trunkFaces = new List<int[]>
        {
            Enumerable.Range(0, segments).AsEnumerable().Reverse().ToArray(),
            Enumerable.Range(segments, segments).ToArray(),
        };
        for (int i = 0; i < segments; i++)
            trunkFaces.Add([i, (i + 1) % segments, segments + (i + 1) % segments, segments + i]);
        int trunkBrep = Polyhedron(trunkPoints, trunkFaces);

        // Five elliptical rings make a faceted but organic crown.
        (double Z, double R)[] profile =
        {
            (0.16, 0.28), (0.34, 0.70), (0.56, 1.00), (0.76, 0.82), (0.91, 0.48),
        };
        var crownPoints = new List<double[]>();
        for (int r = 0; r < profile.Length; r++)
            for (int i = 0; i < segments; i++)
            {
                double a = 2 * Math.PI * i / segments;
                double irregular = 0.96 + 0.04 * Math.Sin(i * 2.17 + r * 1.31);
                // RPC foliage is a crossed/square silhouette in plan.
                double planFactor = 1.0 / Math.Max(Math.Abs(Math.Cos(a)), Math.Abs(Math.Sin(a)));
                crownPoints.Add([cx + rx * profile[r].R * irregular * planFactor * Math.Cos(a),
                    cy + ry * profile[r].R * irregular * planFactor * Math.Sin(a),
                    z0 + height * profile[r].Z]);
            }
        int top = crownPoints.Count;
        crownPoints.Add([cx, cy, z0 + height]);
        var crownFaces = new List<int[]> { Enumerable.Range(0, segments).AsEnumerable().Reverse().ToArray() };
        for (int r = 0; r + 1 < profile.Length; r++)
            for (int i = 0; i < segments; i++)
            {
                int a = r * segments + i, b = r * segments + (i + 1) % segments;
                int c = (r + 1) * segments + (i + 1) % segments, d = (r + 1) * segments + i;
                crownFaces.Add([a, b, c, d]);
            }
        int lastRing = (profile.Length - 1) * segments;
        for (int i = 0; i < segments; i++)
            crownFaces.Add([lastRing + i, lastRing + (i + 1) % segments, top]);
        int crownBrep = Polyhedron(crownPoints, crownFaces);

        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("Brep")},{StepWriter.List(R(trunkBrep), R(crownBrep))}");
        return w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(R(shapeRepId))}");
    }

    /// <summary>Create a simple box geometry from bounding box.</summary>
    private int CreateBboxShape(StepWriter w, double[] bbox, int subCtxId)
    {
        double x0 = bbox[0] * FeetToMetres, y0 = bbox[1] * FeetToMetres, z0 = bbox[2] * FeetToMetres;
        double x1 = bbox[3] * FeetToMetres, y1 = bbox[4] * FeetToMetres, z1 = bbox[5] * FeetToMetres;

        // 8 corners of the box
        int[] pts = new int[8];
        pts[0] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x0), D(y0), D(z0)));
        pts[1] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x1), D(y0), D(z0)));
        pts[2] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x1), D(y1), D(z0)));
        pts[3] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x0), D(y1), D(z0)));
        pts[4] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x0), D(y0), D(z1)));
        pts[5] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x1), D(y0), D(z1)));
        pts[6] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x1), D(y1), D(z1)));
        pts[7] = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(x0), D(y1), D(z1)));

        // 6 faces of the box
        int MakeFace(int a, int b, int c, int d)
        {
            int loopId = w.Add("IFCPOLYLOOP", StepWriter.List(R(pts[a]), R(pts[b]), R(pts[c]), R(pts[d])));
            int boundId = w.Add("IFCFACEOUTERBOUND", $"{R(loopId)},.T.");
            return w.Add("IFCFACE", StepWriter.List(R(boundId)));
        }

        var faces = new int[6];
        faces[0] = MakeFace(0, 3, 2, 1); // bottom
        faces[1] = MakeFace(4, 5, 6, 7); // top
        faces[2] = MakeFace(0, 1, 5, 4); // front
        faces[3] = MakeFace(2, 3, 7, 6); // back
        faces[4] = MakeFace(0, 4, 7, 3); // left
        faces[5] = MakeFace(1, 2, 6, 5); // right

        int shellId = w.Add("IFCCLOSEDSHELL", StepWriter.List(faces.Select(R)));
        int brepId = w.Add("IFCFACETEDBREP", R(shellId));
        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("Brep")},{StepWriter.List(R(brepId))}");
        int prodShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(R(shapeRepId))}");
        return prodShapeId;
    }

    /// <summary>Create SweptSolid (extruded rectangle) from bounding box for non-wall elements.</summary>
    /// <summary>
    /// Opening-box geometry for a hosted door/window: width from family params (FAMILY_WIDTH
    /// -1001301, rough -1001305; instance first, then type), height likewise (-1001300/-1001304),
    /// depth = host wall thickness, oriented along the host wall's location line.
    /// </summary>
    /// <summary>Cut sketch hole loops into a slab's horizontal faces.</summary>
    private static void AttachSketchHoles(Element elem)
    {
        if (elem.SketchLoops is not { Count: > 1 } loops || elem.Geometry?.Faces == null) return;

        static double LoopArea(List<double[]> l)
        {
            double a = 0;
            for (int i = 0; i < l.Count; i++)
            {
                var p = l[i]; var q = l[(i + 1) % l.Count];
                a += p[0] * q[1] - q[0] * p[1];
            }
            return Math.Abs(a) / 2;
        }
        int outerIdx = 0; double best = -1;
        for (int i = 0; i < loops.Count; i++)
        {
            if (loops[i].Count < 3) continue;
            double a = LoopArea(loops[i]);
            if (a > best) { best = a; outerIdx = i; }
        }
        if (best <= 0) return;

        foreach (var face in elem.Geometry.Faces)
        {
            if (face.OuterVertices is not { Count: >= 3 } vs) continue;
            if (face.InnerVertices is { Count: > 0 }) continue;      // already has holes
            // Horizontal face (normal ~ +/-Z via Newell) with area comparable to the profile.
            double nx = 0, ny = 0, nz = 0;
            double minx = double.MaxValue, miny = double.MaxValue, maxx = double.MinValue, maxy = double.MinValue, zsum = 0;
            for (int i = 0; i < vs.Count; i++)
            {
                var p = vs[i]; var q = vs[(i + 1) % vs.Count];
                nx += (p[1] - q[1]) * (p[2] + q[2]);
                ny += (p[2] - q[2]) * (p[0] + q[0]);
                nz += (p[0] - q[0]) * (p[1] + q[1]);
                minx = Math.Min(minx, p[0]); maxx = Math.Max(maxx, p[0]);
                miny = Math.Min(miny, p[1]); maxy = Math.Max(maxy, p[1]);
                zsum += p[2];
            }
            double nlen = Math.Sqrt(nx * nx + ny * ny + nz * nz);
            if (nlen < 1e-9 || Math.Abs(nz) / nlen < 0.95) continue;
            double faceArea = nlen / 2;
            if (faceArea < best * 0.5) continue;                     // only the big top/bottom faces
            double zPlane = zsum / vs.Count;

            List<List<double[]>>? inner = null;
            for (int i = 0; i < loops.Count; i++)
            {
                if (i == outerIdx || loops[i].Count < 3) continue;
                // The hole must sit inside this face's footprint.
                double hcx = 0, hcy = 0;
                foreach (var p in loops[i]) { hcx += p[0]; hcy += p[1]; }
                hcx /= loops[i].Count; hcy /= loops[i].Count;
                if (hcx < minx || hcx > maxx || hcy < miny || hcy > maxy) continue;
                var projected = loops[i].Select(p => new[] { p[0], p[1], zPlane }).ToList();
                (inner ??= new()).Add(projected);
            }
            if (inner != null) face.InnerVertices = inner;
        }
    }

    /// <summary>
    /// The lowest-id matching line is the deterministic seed already used by this exporter.
    /// </summary>
    internal static int SelectSerializedSlabOpeningTag(
        IReadOnlyList<Element> matchingLines)
    {
        if (matchingLines.Count == 0)
            return 0;

        int seedId = matchingLines.Min(line => line.Id);
        return TrySelectSerializedSlabOpeningTagFromClosedLineLoop(
            matchingLines, out int tagId) ? tagId : seedId;
    }

    private static bool TrySelectSerializedSlabOpeningTagFromClosedLineLoop(
        IReadOnlyList<Element> matchingLines, out int tagId)
    {
        tagId = 0;
        if (matchingLines.Count == 0)
            return false;

        var ordered = matchingLines.OrderBy(line => line.Id).ToList();
        Element seed = ordered[0];
        tagId = seed.Id;
        if (ordered.Select(line => line.Id).Distinct().Count() != ordered.Count)
            return false;
        if (seed.Location is not { CurveType: "Line", ArcRadius: null } seedLocation
            || seedLocation.StartPoint.Length < 3
            || seedLocation.EndPoint.Length < 3
            || seedLocation.StartPoint.Take(3).Any(value => !double.IsFinite(value))
            || seedLocation.EndPoint.Take(3).Any(value => !double.IsFinite(value)))
            return false;

        static bool TryPointKey(double[] point, out (long X, long Y, long Z) result)
        {
            result = default;
            try
            {
                result = IfcPrecisionKeyFeet(point);
                return true;
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        if (!TryPointKey(seedLocation.StartPoint, out var start)
            || !TryPointKey(seedLocation.EndPoint, out var current))
            return false;
        if (start == current)
            return false;

        var unused = ordered.Skip(1).ToList();
        var traversed = new List<Element> { seed };
        var vertices = new List<(long X, long Y, long Z)> { start, current };
        while (unused.Count > 0)
        {
            var candidates = new List<(int Index, Element Line,
                (long X, long Y, long Z) Other)>();
            for (int index = 0; index < unused.Count; index++)
            {
                Element line = unused[index];
                if (line.Location is not
                        { CurveType: "Line", ArcRadius: null } location
                    || location.StartPoint.Length < 3
                    || location.EndPoint.Length < 3
                    || location.StartPoint.Take(3).Any(value => !double.IsFinite(value))
                    || location.EndPoint.Take(3).Any(value => !double.IsFinite(value)))
                    continue;
                if (!TryPointKey(location.StartPoint, out var first)
                    || !TryPointKey(location.EndPoint, out var second))
                    return false;
                if (first == second)
                    continue;
                if (first == current)
                    candidates.Add((index, line, second));
                else if (second == current)
                    candidates.Add((index, line, first));
            }
            if (candidates.Count != 1)
                return false;

            var next = candidates[0];
            unused.RemoveAt(next.Index);
            traversed.Add(next.Line);
            current = next.Other;
            vertices.Add(current);
        }

        if (current != start || traversed.Count < 3)
            return false;

        decimal twiceArea = 0;
        try
        {
            for (int index = 0; index < vertices.Count - 1; index++)
            {
                var first = vertices[index];
                var second = vertices[index + 1];
                twiceArea += (decimal)first.X * second.Y
                    - (decimal)second.X * first.Y;
            }
        }
        catch (OverflowException)
        {
            return false;
        }
        if (twiceArea == 0)
            return false;

        tagId = twiceArea > 0 ? traversed[1].Id : seed.Id;
        return true;
    }

    /// <summary>
    /// Extends the all-line selector only when the line walk cannot represent a curved serialized
    /// contour.
    /// </summary>
    internal static int SelectSerializedSlabOpeningTag(
        Element slab, IReadOnlyList<double[]> lowRing,
        IReadOnlyList<Element> matchingLines, IReadOnlyList<Element> sketchLines)
    {
        if (matchingLines.Count == 0)
            return 0;

        var orderedMatchingLines = matchingLines.OrderBy(line => line.Id).ToList();
        Element seed = orderedMatchingLines[0];
        if (TrySelectSerializedSlabOpeningTagFromClosedLineLoop(
                orderedMatchingLines, out int geometricTagId))
            return geometricTagId;
        if (lowRing.Count <= matchingLines.Count
            || orderedMatchingLines.Select(line => line.Id).Distinct().Count()
                != orderedMatchingLines.Count)
            return seed.Id;

        var members = sketchLines
            .Where(element => element.CategoryId == -2000045
                && element.References?.Contains(slab.Id) == true)
            .ToList();
        if (members.Count < 3
            || members.Select(element => element.Id).Distinct().Count() != members.Count)
            return seed.Id;

        var memberById = members.ToDictionary(element => element.Id);
        if (!memberById.ContainsKey(seed.Id))
            return seed.Id;

        var neighboursById = new Dictionary<int, HashSet<int>>();
        foreach (Element member in members)
        {
            var neighbours = new HashSet<int>();
            foreach (int referenceId in member.References ?? [])
                if (referenceId != member.Id
                    && memberById.TryGetValue(referenceId, out Element? referenced)
                    && referenced.References?.Contains(member.Id) == true)
                    neighbours.Add(referenceId);
            neighboursById[member.Id] = neighbours;
        }

        var componentIds = new HashSet<int>();
        var pending = new Queue<int>();
        pending.Enqueue(seed.Id);
        while (pending.Count > 0)
        {
            int currentId = pending.Dequeue();
            if (!componentIds.Add(currentId))
                continue;
            foreach (int neighbourId in neighboursById[currentId])
                pending.Enqueue(neighbourId);
        }

        if (componentIds.Count < 3
            || componentIds.Any(id => neighboursById[id].Count != 2)
            || orderedMatchingLines.Any(line => !componentIds.Contains(line.Id)))
            return seed.Id;

        var component = componentIds.Select(id => memberById[id]).ToList();
        if (!component.Any(element =>
                element.Location is not { CurveType: "Line", ArcRadius: null }))
            return seed.Id;

        static bool TryPlanKey(double[] point, out (long X, long Y) result)
        {
            result = default;
            if (point.Length < 3
                || point.Take(3).Any(value => !double.IsFinite(value)))
                return false;
            try
            {
                var key = IfcPrecisionKeyFeet(point);
                result = (key.X, key.Y);
                return true;
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        var ringEdges = new HashSet<((long X, long Y) A, (long X, long Y) B)>();
        for (int index = 0; index < lowRing.Count; index++)
        {
            if (!TryPlanKey(lowRing[index], out var first)
                || !TryPlanKey(lowRing[(index + 1) % lowRing.Count], out var second)
                || first == second)
                return seed.Id;
            ringEdges.Add(first.CompareTo(second) <= 0
                ? (first, second) : (second, first));
        }

        var straightBoundaryNodeIds = new HashSet<int>();
        foreach (Element member in component)
        {
            if (member.Location is not
                    { CurveType: "Line", ArcRadius: null } location)
                continue;
            if (!TryPlanKey(location.StartPoint, out var first)
                || !TryPlanKey(location.EndPoint, out var second))
                return seed.Id;
            var edge = first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
            if (ringEdges.Contains(edge))
                straightBoundaryNodeIds.Add(member.Id);
        }
        if (!straightBoundaryNodeIds.SetEquals(
                orderedMatchingLines.Select(line => line.Id)))
            return seed.Id;

        var reciprocalTypeMates = component.Where(candidate =>
            candidate.Id != seed.Id
            && seed.TypeId == candidate.Id
            && candidate.TypeId == seed.Id
            && candidate.Location == null
            && neighboursById[seed.Id].Contains(candidate.Id)).ToList();
        return reciprocalTypeMates.Count == 1
            ? reciprocalTypeMates[0].Id
            : seed.Id;
    }

    internal static IReadOnlyList<(int TagId, IReadOnlyList<double[]> Ring,
        double LowZFt, double HighZFt)> GetSerializedSlabOpeningProfiles(
        Element slab, IReadOnlyList<Element> sketchLines)
    {
        if (slab.Geometry?.Faces is not { Count: > 0 } faces
            || sketchLines.Count == 0)
            return [];

        static (long X, long Y) PlanKey(double[] point)
        {
            var key = IfcPrecisionKeyFeet(point);
            return (key.X, key.Y);
        }

        static bool TryPlanKey(double[] point, out (long X, long Y) result)
        {
            result = default;
            try
            {
                result = PlanKey(point);
                return true;
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            var keys = new List<(long X, long Y)>();
            foreach (var point in source)
                if (point.Length >= 3 && point.All(double.IsFinite)
                    && TryPlanKey(point, out var key)
                    && (keys.Count == 0 || keys[^1] != key))
                {
                    result.Add(point);
                    keys.Add(key);
                }
            if (result.Count > 1 && keys[0] == keys[^1])
                result.RemoveAt(result.Count - 1);
            return result;
        }

        static string CanonicalPlanKey(IReadOnlyList<double[]> ring)
        {
            var keys = ring.Select(PlanKey).ToList();
            string? best = null;
            foreach (bool reverse in new[] { false, true })
                for (int shift = 0; shift < keys.Count; shift++)
                {
                    string candidate = string.Join(';', Enumerable.Range(0, keys.Count)
                        .Select(index =>
                        {
                            int sourceIndex = reverse
                                ? (shift - index + keys.Count) % keys.Count
                                : (shift + index) % keys.Count;
                            var key = keys[sourceIndex];
                            return $"{key.X}:{key.Y}";
                        }));
                    if (best == null || string.CompareOrdinal(candidate, best) < 0)
                        best = candidate;
                }
            return best ?? string.Empty;
        }

        var horizontalRings = faces
            .SelectMany(face => face.InnerVertices ?? [])
            .Select(CleanRing)
            .Where(ring => ring.Count >= 3)
            .Where(ring =>
            {
                long z = IfcPrecisionKeyFeet(ring[0]).Z;
                return ring.All(point => IfcPrecisionKeyFeet(point).Z == z);
            })
            .GroupBy(CanonicalPlanKey)
            .ToList();

        var result = new List<(int TagId, IReadOnlyList<double[]> Ring,
            double LowZFt, double HighZFt)>();
        var usedTags = new HashSet<int>();
        foreach (var group in horizontalRings)
        {
            var ringsByZ = group
                .GroupBy(ring => IfcPrecisionKeyFeet(ring[0]).Z)
                .OrderBy(zGroup => zGroup.Key).ToList();
            if (ringsByZ.Count < 2) continue;
            var lowRing = ringsByZ[0].First();
            var highRing = ringsByZ[^1].First();
            double lowZ = lowRing.Average(point => point[2]);
            double highZ = highRing.Average(point => point[2]);
            if (!(highZ > lowZ) || !double.IsFinite(lowZ) || !double.IsFinite(highZ))
                continue;

            var edges = new HashSet<((long X, long Y) A, (long X, long Y) B)>();
            for (int index = 0; index < lowRing.Count; index++)
            {
                var first = PlanKey(lowRing[index]);
                var second = PlanKey(lowRing[(index + 1) % lowRing.Count]);
                edges.Add(first.CompareTo(second) <= 0
                    ? (first, second) : (second, first));
            }
            var matchingLines = sketchLines.Where(line =>
            {
                if (line.Location is not { CurveType: "Line", ArcRadius: null } location
                    || location.StartPoint.Length < 3 || location.EndPoint.Length < 3
                    || location.StartPoint.Take(3).Any(value => !double.IsFinite(value))
                    || location.EndPoint.Take(3).Any(value => !double.IsFinite(value)))
                    return false;
                if (!TryPlanKey(location.StartPoint, out var first)
                    || !TryPlanKey(location.EndPoint, out var second))
                    return false;
                return edges.Contains(first.CompareTo(second) <= 0
                    ? (first, second) : (second, first));
            }).OrderBy(line => line.Id).ToList();
            if (matchingLines.Count == 0) continue;
            int tagId = SelectSerializedSlabOpeningTag(
                slab, lowRing, matchingLines, sketchLines);
            if (!usedTags.Add(tagId)) continue;
            result.Add((tagId, lowRing, lowZ, highZ));
        }
        return result.OrderBy(profile => profile.TagId).ToList();
    }

    private void CreateSerializedSlabOpenings(StepWriter w, Element slab, int slabEntityId,
        int slabPlacementId, int ownerHistId, int subCtxId, List<int> storeyContents,
        IReadOnlyList<Element> sketchLines, IReadOnlyDictionary<int, Element> elemById,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        int? slabQuantityTakeOffReferenceValueId)
    {
        foreach (var profile in GetSerializedSlabOpeningProfiles(slab, sketchLines))
        {
            elemById.TryGetValue(profile.TagId, out var propertySetReferenceElement);
            if (ShouldSuppressSerializedSlabOpeningSource(
                    propertySetReferenceElement?.SerializedUnplacedOwnerId))
                continue;

            var ring = profile.Ring.ToList();
            double twiceArea = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                var first = ring[index];
                var second = ring[(index + 1) % ring.Count];
                twiceArea += first[0] * second[1] - second[0] * first[1];
            }
            if (twiceArea < 0) ring.Reverse();

            double centreXFt = (ring.Min(point => point[0]) + ring.Max(point => point[0])) / 2;
            double centreYFt = (ring.Min(point => point[1]) + ring.Max(point => point[1])) / 2;
            int placementPointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
                D(centreXFt * FeetToMetres), D(centreYFt * FeetToMetres),
                D(profile.LowZFt * FeetToMetres)));
            int placementAxisId = w.Add("IFCAXIS2PLACEMENT3D",
                $"{R(placementPointId)},$,$");
            int openingPlacementId = w.Add("IFCLOCALPLACEMENT",
                $"{R(slabPlacementId)},{R(placementAxisId)}");

            var pointIds = ring.Select(point => w.Add("IFCCARTESIANPOINT",
                StepWriter.List(D((point[0] - centreXFt) * FeetToMetres),
                    D((point[1] - centreYFt) * FeetToMetres)))).ToList();
            pointIds.Add(pointIds[0]);
            int curveId = w.Add("IFCPOLYLINE",
                StepWriter.List(pointIds.Select(R).ToArray()));
            int profileId = w.Add("IFCARBITRARYCLOSEDPROFILEDEF",
                $".AREA.,$,{R(curveId)}");
            int solidOriginId = w.Add("IFCCARTESIANPOINT",
                StepWriter.List("0.", "0.", "0."));
            int solidPositionId = w.Add("IFCAXIS2PLACEMENT3D",
                $"{R(solidOriginId)},$,$");
            int extrusionDirectionId = w.Add("IFCDIRECTION",
                StepWriter.List("0.", "0.", "1."));
            int solidId = w.Add("IFCEXTRUDEDAREASOLID",
                $"{R(profileId)},{R(solidPositionId)},{R(extrusionDirectionId)},"
                + D((profile.HighZFt - profile.LowZFt) * FeetToMetres));
            int representationId = w.Add("IFCSHAPEREPRESENTATION",
                $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
            int shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
                $"$,$,{StepWriter.List(R(representationId))}");

            string openingName = $"{slab.Name ?? "Slab"}:Opening:{profile.TagId}";
            string openingGlobalId = IfcGuid.FromName($"slab-opening:{slab.Id}:{profile.TagId}");
            bool useSlabQuantityTakeOffReference =
                CanUseSerializedSlabOpeningHostReference(
                    propertySetReferenceElement?.SerializedUnplacedOwnerId);
            int openingId = CreateOpeningElement(w, openingGlobalId, ownerHistId, openingName,
                profile.TagId, propertySetReferenceElement, elemById,
                openingPlacementId, shapeId,
                propertySingleValueIds, slab.ValidatedFloorTypeReferenceName,
                slab.ValidatedFloorTypeReferenceIsBlocked,
                useSlabQuantityTakeOffReference
                    ? slabQuantityTakeOffReferenceValueId
                    : null,
                useSlabQuantityTakeOffReference);
            w.Add("IFCRELVOIDSELEMENT",
                $"{S(IfcGuid.FromName($"slab-void:{slab.Id}:{profile.TagId}"))},"
                + $"{R(ownerHistId)},$,$,{R(slabEntityId)},{R(openingId)}");
            storeyContents.Add(openingId);
        }
    }

    /// <summary>
    /// Clip a hosted door/window family mesh to its host wall's slab: keep faces whose centroid
    /// lies within (wall thickness / 2 + trim margin) of the wall plane.
    /// </summary>
    private GeometryData? ClipHostedToWallSlab(
        Element elem, GeometryData geo, Dictionary<int, Element> elemById, double[] bbox,
        Element? resolvedHost = null)
    {
        static double P(Element e, params int[] bips)
        {
            foreach (int bip in bips)
                foreach (var p in e.Parameters)
                    if (p.Id == bip && p.Value is double d && d > 0.01 && d < 100) return d;
            return 0;
        }
        Element? host = resolvedHost;
        // The first wall reference matches Revit's primary host in this stream.
        var visibleHosts = _wallIndex.ToDictionary(w => w.Id);
        if (host == null)
            foreach (int r in elem.References ?? Enumerable.Empty<int>())
                if (r > 0 && visibleHosts.TryGetValue(r, out var referenced)
                    && referenced.Location != null)
                    { host = referenced; break; }
        if (host == null && elem.HostId is { } hid && hid > 0
            && elemById.TryGetValue(hid, out var direct)
            && direct.CategoryId == -2000011 && direct.Location != null)
            host = direct;
        if (host?.Location is not { } wl) return null;
        double thk = P(host, -1001000);
        if (thk <= 0 && host.TypeId > 0 && elemById.TryGetValue(host.TypeId, out var hty)) thk = P(hty, -1001000);
        double[]? hostBbox = host.BoundingBox ?? host.Geometry?.BoundingBox;
        if (hostBbox is { Length: >= 6 })
        {
            double bt = Math.Min(Math.Abs(hostBbox[3] - hostBbox[0]), Math.Abs(hostBbox[4] - hostBbox[1]));
            if (bt is > 0.05 and <= 3 && (thk <= 0 || thk > 3 || bt < thk * 0.8)) thk = bt;
        }
        if (thk <= 0 || thk > 3) thk = 0.66;
        double wdx = wl.EndPoint[0] - wl.StartPoint[0], wdy = wl.EndPoint[1] - wl.StartPoint[1];
        double wln = Math.Sqrt(wdx * wdx + wdy * wdy);
        if (wln < 1e-6) return null;
        double nx = -wdy / wln, ny = wdx / wln;                  // wall plane normal (plan)
        double limit = thk / 2 + 0.5;                            // trim margin ~15 cm

        // The decoded line direction is useful, but its origin can belong to a parallel template
        // wall.
        double planeX = hostBbox is { Length: >= 6 } ? (hostBbox[0] + hostBbox[3]) / 2 : wl.StartPoint[0];
        double planeY = hostBbox is { Length: >= 6 } ? (hostBbox[1] + hostBbox[4]) / 2 : wl.StartPoint[1];
        var signed = geo.Faces
            .Where(f => f.OuterVertices is { Count: >= 3 })
            .SelectMany(f => f.OuterVertices!)
            .Select(v => (v[0] - planeX) * nx + (v[1] - planeY) * ny)
            .OrderBy(v => v).ToList();
        double planeShift = signed.Count > 0 ? -(signed[0] + signed[^1]) / 2 : 0;
        if (Math.Abs(planeShift) > 1e-6)
            foreach (var f in geo.Faces)
                if (f.OuterVertices != null)
                    foreach (var v in f.OuterVertices) { v[0] += planeShift * nx; v[1] += planeShift * ny; }

        // Window type meshes sometimes keep a wider template.
        if (elem.CategoryId == -2000014)
        {
            var vertices = geo.Faces.Where(f => f.OuterVertices != null).SelectMany(f => f.OuterVertices!).ToList();
            if (vertices.Count > 0)
            {
                var along = vertices.Select(v => v[0] * (wdx / wln) + v[1] * (wdy / wln)).ToList();
                double amin = along.Min(), amax = along.Max(), actual = amax - amin;
                double target = Math.Min(Math.Abs(bbox[3] - bbox[0]), Math.Abs(bbox[4] - bbox[1]));
                if (target > 0.1 && actual > target * 1.05)
                {
                    double centre = (amin + amax) / 2, scale = target / actual;
                    double ux0 = wdx / wln, uy0 = wdy / wln;
                    foreach (var v in vertices)
                    {
                        double a = v[0] * ux0 + v[1] * uy0;
                        double delta = (centre + (a - centre) * scale) - a;
                        v[0] += delta * ux0; v[1] += delta * uy0;
                    }
                }
            }
        }
        var kept = new List<GeoFace>();
        int dropped = 0;
        foreach (var f in geo.Faces!)
        {
            if (f.OuterVertices is not { Count: >= 3 } vs) { kept.Add(f); continue; }
            double cx0 = 0, cy0 = 0;
            foreach (var v in vs) { cx0 += v[0]; cy0 += v[1]; }
            cx0 /= vs.Count; cy0 /= vs.Count;
            double dist = Math.Abs((cx0 - planeX) * nx + (cy0 - planeY) * ny);
            if (dist <= limit) kept.Add(f); else dropped++;
        }
        int keptRich = kept.Count(f => f.OuterVertices is { Count: >= 3 });
        if ((dropped == 0 && Math.Abs(planeShift) < 1e-6) || keptRich < 3) return null;
        var outGeo = new GeometryData { Faces = kept };
        double minx = double.MaxValue, miny = double.MaxValue, minz = double.MaxValue;
        double maxx = double.MinValue, maxy = double.MinValue, maxz = double.MinValue;
        foreach (var f in kept)
            if (f.OuterVertices != null)
                foreach (var v in f.OuterVertices)
                {
                    minx = Math.Min(minx, v[0]); maxx = Math.Max(maxx, v[0]);
                    miny = Math.Min(miny, v[1]); maxy = Math.Max(maxy, v[1]);
                    minz = Math.Min(minz, v[2]); maxz = Math.Max(maxz, v[2]);
                }
        if (minx <= maxx) outGeo.BoundingBox = new[] { minx, miny, minz, maxx, maxy, maxz };
        return outGeo;
    }

    private (int shapeId, int placementId)? CreateHostedOpeningBox(
        StepWriter w, Element elem, double[] bbox, Dictionary<int, Element> elemById,
        int subCtxId, int parentPlacementId)
    {
        static double P(Element e, params int[] bips)
        {
            foreach (int bip in bips)
                foreach (var p in e.Parameters)
                    if (p.Id == bip && p.Value is double d && d > 0.01 && d < 100) return d;
            return 0;
        }
        Element? host = null;
        var visibleHosts = _wallIndex.ToDictionary(w => w.Id);
        if (elem.References != null)
            foreach (var r in elem.References)
                if (r > 0 && visibleHosts.TryGetValue(r, out var h) && h.Location != null)
                { host = h; break; }
        if (host == null && elem.HostId is { } hid && hid > 0
            && visibleHosts.TryGetValue(hid, out var hh) && hh.Location != null)
            host = hh;
        if (host == null)
        {
            double pcx0 = (bbox[0] + bbox[3]) / 2, pcy0 = (bbox[1] + bbox[4]) / 2;
            double pz0 = (bbox[2] + bbox[5]) / 2;
            double best = 2.0;
            foreach (var wall in _wallIndex)
            {
                var l = wall.Location!;
                if (wall.BoundingBox is { Length: >= 6 } wb && (pz0 < wb[2] - 1 || pz0 > wb[5] + 1)) continue;
                double ax = l.StartPoint[0], ay = l.StartPoint[1];
                double bx = l.EndPoint[0], by = l.EndPoint[1];
                double vx = bx - ax, vy = by - ay;
                double l2 = vx * vx + vy * vy;
                if (l2 < 1e-9) continue;
                double t = Math.Clamp(((pcx0 - ax) * vx + (pcy0 - ay) * vy) / l2, 0, 1);
                double d = Math.Sqrt(Math.Pow(pcx0 - (ax + t * vx), 2) + Math.Pow(pcy0 - (ay + t * vy), 2));
                if (d < best) { best = d; host = wall; }
            }
        }
        if (host?.Location is not { } hl) { _dbgOpenNoHost++; return null; }

        // ACTUAL width/height first (instance, then type); ROUGH opening dims only as a last resort
        // - rough width can exceed the leaf by half a metre.
        Element? ty = elem.TypeId > 0 && elemById.TryGetValue(elem.TypeId, out var ty0) ? ty0 : null;
        double wFt = P(elem, -1001301);
        if (wFt <= 0 && ty != null) wFt = P(ty, -1001301);
        if (wFt <= 0) wFt = P(elem, -1001305);
        if (wFt <= 0 && ty != null) wFt = P(ty, -1001305);
        double hFt = P(elem, -1001300);
        if (hFt <= 0 && ty != null) hFt = P(ty, -1001300);
        if (hFt <= 0) hFt = P(elem, -1001304);
        if (hFt <= 0 && ty != null) hFt = P(ty, -1001304);
        var namedSize = Regex.Match(elem.Name ?? "", @"(\d{3,4})\s*[xX]\s*(\d{3,4})(?:\s*mm)?",
            RegexOptions.IgnoreCase);
        if (namedSize.Success)
        {
            wFt = double.Parse(namedSize.Groups[1].Value, CultureInfo.InvariantCulture) / 304.8;
            hFt = double.Parse(namedSize.Groups[2].Value, CultureInfo.InvariantCulture) / 304.8;
        }
        double thkFt = P(host, -1001000);
        if (host.TypeId > 0 && thkFt <= 0 && elemById.TryGetValue(host.TypeId, out var hty))
            thkFt = P(hty, -1001000);
        if (wFt <= 0 || hFt <= 0) { _dbgOpenNoParam++; return null; }
        _dbgOpenOk++;
        _resolvedOpenings[elem.Id] = (host.Id, wFt * FeetToMetres, hFt * FeetToMetres);
        if (thkFt > 3 && host.BoundingBox is { Length: >= 6 } hbb)
            thkFt = Math.Min(Math.Abs(hbb[3] - hbb[0]), Math.Abs(hbb[4] - hbb[1]));
        if (thkFt <= 0 || thkFt > 3) thkFt = 0.66; // ~200 mm fallback

        double dxw = hl.EndPoint[0] - hl.StartPoint[0], dyw = hl.EndPoint[1] - hl.StartPoint[1];
        double wlen = Math.Sqrt(dxw * dxw + dyw * dyw);
        if (wlen < 1e-6) return null;
        double ux = dxw / wlen, uy = dyw / wlen;
        double bboxWidthFt = Math.Abs((bbox[3] - bbox[0]) * ux)
            + Math.Abs((bbox[4] - bbox[1]) * uy);
        if (!namedSize.Success && bboxWidthFt > 0.03 && (wFt <= 0 || bboxWidthFt < wFt))
            wFt = bboxWidthFt;

        double pcx = (bbox[0] + bbox[3]) / 2, pcy = (bbox[1] + bbox[4]) / 2;
        double wallCx = host.BoundingBox is { Length: >= 6 } hostBox
            ? (hostBox[0] + hostBox[3]) / 2 : (hl.StartPoint[0] + hl.EndPoint[0]) / 2;
        double wallCy = host.BoundingBox is { Length: >= 6 } hostBox2
            ? (hostBox2[1] + hostBox2[4]) / 2 : (hl.StartPoint[1] + hl.EndPoint[1]) / 2;
        double along = (pcx - wallCx) * ux + (pcy - wallCy) * uy;
        double cx = (wallCx + along * ux) * FeetToMetres;
        double cy = (wallCy + along * uy) * FeetToMetres;
        double z0 = bbox[2] * FeetToMetres;

        int placementPtId = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(cx), D(cy), D(z0)));
        int refDirId = w.Add("IFCDIRECTION", StepWriter.List(D(ux), D(uy), "0."));
        int placementAxisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(placementPtId)},$,{R(refDirId)}");
        int placementId = w.Add("IFCLOCALPLACEMENT", $"{R(parentPlacementId)},{R(placementAxisId)}");

        int profOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0."));
        int profPlacementId = w.Add("IFCAXIS2PLACEMENT2D", $"{R(profOriginId)},$");
        int profileId = w.Add("IFCRECTANGLEPROFILEDEF",
            $".AREA.,$,{R(profPlacementId)},{D(wFt * FeetToMetres)},{D(thkFt * FeetToMetres)}");
        int extOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
        int extPositionId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(extOriginId)},$,$");
        int extDirId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "1."));
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(extPositionId)},{R(extDirId)},{D(hFt * FeetToMetres)}");
        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
        int prodShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(shapeRepId))}");
        return (prodShapeId, placementId);
    }

    private (int shapeId, int placementId) CreateBboxSweptSolid(
        StepWriter w, double[] bbox, int subCtxId, int parentPlacementId)
    {
        double x0 = bbox[0] * FeetToMetres, y0 = bbox[1] * FeetToMetres, z0 = bbox[2] * FeetToMetres;
        double x1 = bbox[3] * FeetToMetres, y1 = bbox[4] * FeetToMetres, z1 = bbox[5] * FeetToMetres;
        double dx = x1 - x0, dy = y1 - y0, dz = z1 - z0;

        // Placement at bbox center-bottom
        double cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
        int placementPtId = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(cx), D(cy), D(z0)));
        int placementAxisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(placementPtId)},$,$");
        int placementId = w.Add("IFCLOCALPLACEMENT", $"{R(parentPlacementId)},{R(placementAxisId)}");

        // Profile: rectangle dx x dy centered at origin
        int profOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0."));
        int profPlacementId = w.Add("IFCAXIS2PLACEMENT2D", $"{R(profOriginId)},$");
        int profileId = w.Add("IFCRECTANGLEPROFILEDEF",
            $".AREA.,$,{R(profPlacementId)},{D(dx)},{D(dy)}");

        // Extrusion along Z
        int extOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
        int extPositionId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(extOriginId)},$,$");
        int extDirId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "1."));
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(extPositionId)},{R(extDirId)},{D(dz)}");

        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
        int prodShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(shapeRepId))}");

        return (prodShapeId, placementId);
    }

    /// <summary>Reconstruct a rectangular beam with one authored corner notch at an end.</summary>
    internal static bool TryBuildRectangularBeamEndNotchBoundary(
        Element element, out GeometryData boundary)
    {
        boundary = null!;
        if (element.CategoryId != -2001320
            || element.Geometry is not { } geometry
            || geometry.BrepSolids is not { Count: 2 } solids)
            return false;

        var closedSolids = solids.Where(solid => solid.IsClosed).ToList();
        var openSolids = solids.Where(solid => !solid.IsClosed).ToList();
        if (closedSolids.Count != 1 || openSolids.Count != 1)
            return false;
        List<int> closedIndices = closedSolids[0].FaceIndices.Distinct().ToList();
        List<int> cutterIndices = openSolids[0].FaceIndices.Distinct().ToList();
        if (closedIndices.Count != 6 || cutterIndices.Count != 4
            || closedIndices.Concat(cutterIndices)
                .Any(index => (uint)index >= geometry.Faces.Count))
            return false;

        double toleranceFt = IfcGeometryPrecisionMetres / FeetToMetres * 2;
        static double Dot(double[] first, double[] second) =>
            first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
        static double[] Difference(double[] end, double[] start) =>
            [end[0] - start[0], end[1] - start[1], end[2] - start[2]];
        static double Length(double[] vector) => Math.Sqrt(Dot(vector, vector));
        static double[] Unit(double[] vector, double length) =>
            [vector[0] / length, vector[1] / length, vector[2] / length];
        static double Distance(double[] first, double[] second) =>
            Length(Difference(first, second));
        bool Close(double first, double second) =>
            Math.Abs(first - second) <= toleranceFt;

        bool ValidQuad(int faceIndex) =>
            geometry.Faces[faceIndex].OuterVertices is { Count: 4 } vertices
            && geometry.Faces[faceIndex].InnerVertices is not { Count: > 0 }
            && vertices.All(point => point.Length >= 3
                && point.Take(3).All(double.IsFinite));
        if (closedIndices.Concat(cutterIndices).Any(index => !ValidQuad(index)))
            return false;

        var closedVertices = new List<double[]>();
        var closedVertexByKey = new Dictionary<(long X, long Y, long Z), int>();
        var closedFaceVertices = new List<int[]>(6);
        foreach (int faceIndex in closedIndices)
        {
            var indices = new int[4];
            for (int vertexIndex = 0; vertexIndex < 4; vertexIndex++)
            {
                double[] point = geometry.Faces[faceIndex].OuterVertices![vertexIndex];
                var key = IfcPrecisionKeyFeet(point);
                if (!closedVertexByKey.TryGetValue(key, out int index))
                {
                    index = closedVertices.Count;
                    closedVertexByKey.Add(key, index);
                    closedVertices.Add(point);
                }
                indices[vertexIndex] = index;
            }
            if (indices.Distinct().Count() != 4) return false;
            closedFaceVertices.Add(indices);
        }
        if (closedVertices.Count != 8) return false;

        var neighbours = Enumerable.Range(0, 8)
            .Select(_ => new HashSet<int>()).ToArray();
        foreach (int[] face in closedFaceVertices)
            for (int index = 0; index < face.Length; index++)
            {
                int first = face[index], second = face[(index + 1) % face.Length];
                neighbours[first].Add(second);
                neighbours[second].Add(first);
            }
        if (neighbours.Any(set => set.Count != 3)) return false;

        double[] corner = closedVertices[0];
        double[][] edgeVectors = neighbours[0]
            .Select(index => Difference(closedVertices[index], corner)).ToArray();
        double[] edgeLengths = edgeVectors.Select(Length).ToArray();
        if (edgeLengths.Any(length => !double.IsFinite(length) || length <= toleranceFt))
            return false;
        for (int first = 0; first < 3; first++)
            for (int second = first + 1; second < 3; second++)
                if (Math.Abs(Dot(edgeVectors[first], edgeVectors[second]))
                    > edgeLengths[first] * edgeLengths[second] * 1e-8)
                    return false;
        for (int mask = 0; mask < 8; mask++)
        {
            var expected = new[] { corner[0], corner[1], corner[2] };
            for (int edge = 0; edge < 3; edge++)
                if ((mask & (1 << edge)) != 0)
                    for (int coordinate = 0; coordinate < 3; coordinate++)
                        expected[coordinate] += edgeVectors[edge][coordinate];
            if (!closedVertices.Any(vertex => Distance(vertex, expected) <= toleranceFt))
                return false;
        }

        int axisIndex = Enumerable.Range(0, 3)
            .OrderByDescending(index => edgeLengths[index]).First();
        double nextLength = edgeLengths.Where((_, index) => index != axisIndex).Max();
        if (edgeLengths[axisIndex] - nextLength <= toleranceFt) return false;
        double[][] basis = edgeVectors.Zip(edgeLengths)
            .Select(pair => Unit(pair.First, pair.Second)).ToArray();
        int[] profileIndices = Enumerable.Range(0, 3)
            .Where(index => index != axisIndex).ToArray();

        double[][] allPoints = geometry.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3 && point.Take(3).All(double.IsFinite))
            .ToArray();
        if (allPoints.Length == 0) return false;
        var rawMin = new double[3];
        var rawMax = new double[3];
        var closedMin = new double[3];
        var closedMax = new double[3];
        for (int coordinate = 0; coordinate < 3; coordinate++)
        {
            rawMin[coordinate] = allPoints.Min(point => Dot(point, basis[coordinate]));
            rawMax[coordinate] = allPoints.Max(point => Dot(point, basis[coordinate]));
            closedMin[coordinate] = closedVertices.Min(point => Dot(point, basis[coordinate]));
            closedMax[coordinate] = closedVertices.Max(point => Dot(point, basis[coordinate]));
        }
        foreach (int profileIndex in profileIndices)
            if (!Close(rawMin[profileIndex], closedMin[profileIndex])
                || !Close(rawMax[profileIndex], closedMax[profileIndex]))
                return false;

        // The raw face envelope may extend the placed symbol at exactly one axial end.
        bool closedTouchesRawMin = Close(closedMin[axisIndex], rawMin[axisIndex]);
        bool closedTouchesRawMax = Close(closedMax[axisIndex], rawMax[axisIndex]);
        if (closedTouchesRawMin == closedTouchesRawMax) return false;
        double axialExtension = closedTouchesRawMin
            ? rawMax[axisIndex] - closedMax[axisIndex]
            : closedMin[axisIndex] - rawMin[axisIndex];
        double maxSection = profileIndices
            .Max(index => rawMax[index] - rawMin[index]);
        if (axialExtension <= toleranceFt || axialExtension > maxSection + toleranceFt)
            return false;

        var cutterPoints = cutterIndices
            .SelectMany(index => geometry.Faces[index].OuterVertices!)
            .GroupBy(IfcPrecisionKeyFeet)
            .Select(group => group.First()).ToList();
        if (cutterPoints.Count != 8) return false;

        bool TryTwoLevels(int coordinate, out double low, out double high)
        {
            var levels = new List<double>();
            foreach (double value in cutterPoints.Select(point => Dot(point, basis[coordinate]))
                         .OrderBy(value => value))
                if (levels.Count == 0 || !Close(levels[^1], value)) levels.Add(value);
            if (levels.Count != 2)
            {
                low = high = 0;
                return false;
            }
            low = levels[0];
            high = levels[1];
            return high - low > toleranceFt;
        }

        var cutterMin = new double[3];
        var cutterMax = new double[3];
        for (int coordinate = 0; coordinate < 3; coordinate++)
            if (!TryTwoLevels(coordinate,
                    out cutterMin[coordinate], out cutterMax[coordinate]))
                return false;
        for (int mask = 0; mask < 8; mask++)
            if (!cutterPoints.Any(point => Enumerable.Range(0, 3).All(coordinate =>
                    Close(Dot(point, basis[coordinate]),
                        (mask & (1 << coordinate)) == 0
                            ? cutterMin[coordinate] : cutterMax[coordinate]))))
                return false;

        bool cutterTouchesAxisMin = Close(cutterMin[axisIndex], rawMin[axisIndex]);
        bool cutterTouchesAxisMax = Close(cutterMax[axisIndex], rawMax[axisIndex]);
        if (cutterTouchesAxisMin == cutterTouchesAxisMax) return false;
        // The notched end is also the symbol end which was not extended by the raw faces.
        if (cutterTouchesAxisMin != closedTouchesRawMin) return false;

        bool[] spansProfile = profileIndices.Select(index =>
            Close(cutterMin[index], rawMin[index])
            && Close(cutterMax[index], rawMax[index])).ToArray();
        if (spansProfile[0] == spansProfile[1]) return false;
        int spanIndex = spansProfile[0] ? profileIndices[0] : profileIndices[1];
        int partialIndex = spansProfile[0] ? profileIndices[1] : profileIndices[0];
        bool cutterTouchesProfileMin = Close(cutterMin[partialIndex], rawMin[partialIndex]);
        bool cutterTouchesProfileMax = Close(cutterMax[partialIndex], rawMax[partialIndex]);
        if (cutterTouchesProfileMin == cutterTouchesProfileMax) return false;

        // The two material-facing planes (axial inner plane and transverse inner plane) are
        // required; the remaining exterior planes can be omitted or retained by the serializer.
        var cutterPlanes = new HashSet<(int Axis, int Side)>();
        foreach (int faceIndex in cutterIndices)
        {
            var vertices = geometry.Faces[faceIndex].OuterVertices!;
            var constantAxes = new List<(int Axis, int Side)>();
            for (int coordinate = 0; coordinate < 3; coordinate++)
            {
                double[] values = vertices.Select(point => Dot(point, basis[coordinate])).ToArray();
                if (values.Max() - values.Min() > toleranceFt) continue;
                if (Close(values[0], cutterMin[coordinate]))
                    constantAxes.Add((coordinate, 0));
                else if (Close(values[0], cutterMax[coordinate]))
                    constantAxes.Add((coordinate, 1));
            }
            if (constantAxes.Count != 1 || !cutterPlanes.Add(constantAxes[0]))
                return false;
        }
        int innerAxisSide = cutterTouchesAxisMin ? 1 : 0;
        int innerProfileSide = cutterTouchesProfileMin ? 1 : 0;
        if (!cutterPlanes.Contains((axisIndex, innerAxisSide))
            || !cutterPlanes.Contains((partialIndex, innerProfileSide)))
            return false;

        var referencedFaces = closedIndices.Concat(cutterIndices).ToHashSet();
        List<int> looseFaces = Enumerable.Range(0, geometry.Faces.Count)
            .Where(index => !referencedFaces.Contains(index)).ToList();
        if (looseFaces is not { Count: >= 1 and <= 2 }
            || looseFaces.Any(index => !ValidQuad(index)))
            return false;

        bool IsFullSectionCap(int faceIndex, double axialValue)
        {
            var points = geometry.Faces[faceIndex].OuterVertices!;
            if (points.Any(point => !Close(Dot(point, basis[axisIndex]), axialValue)))
                return false;
            return Enumerable.Range(0, 4).All(mask => points.Any(point =>
                Close(Dot(point, basis[profileIndices[0]]),
                    (mask & 1) == 0 ? rawMin[profileIndices[0]] : rawMax[profileIndices[0]])
                && Close(Dot(point, basis[profileIndices[1]]),
                    (mask & 2) == 0 ? rawMin[profileIndices[1]] : rawMax[profileIndices[1]])));
        }

        double rawOppositeEnd = cutterTouchesAxisMin
            ? rawMax[axisIndex] : rawMin[axisIndex];
        double closedOppositeEnd = cutterTouchesAxisMin
            ? closedMax[axisIndex] : closedMin[axisIndex];
        if (looseFaces.Count(index => IsFullSectionCap(index, rawOppositeEnd)) != 1
            || closedIndices.Count(index => IsFullSectionCap(index, closedOppositeEnd)) != 1
            || looseFaces.Any(index => !IsFullSectionCap(index, rawOppositeEnd)
                && !IsFullSectionCap(index, closedOppositeEnd)))
            return false;

        double tOpposite = rawOppositeEnd;
        double tEnd = cutterTouchesAxisMin ? rawMin[axisIndex] : rawMax[axisIndex];
        double tInner = cutterTouchesAxisMin
            ? cutterMax[axisIndex] : cutterMin[axisIndex];
        double qOpposite = cutterTouchesProfileMin
            ? rawMax[partialIndex] : rawMin[partialIndex];
        double qEnd = cutterTouchesProfileMin
            ? rawMin[partialIndex] : rawMax[partialIndex];
        double qInner = cutterTouchesProfileMin
            ? cutterMax[partialIndex] : cutterMin[partialIndex];
        (double T, double Q)[] plan =
        [
            (tOpposite, qOpposite),
            (tEnd, qOpposite),
            (tEnd, qInner),
            (tInner, qInner),
            (tInner, qEnd),
            (tOpposite, qEnd),
        ];

        double[] Point(double t, double q, double span) =>
        [
            basis[axisIndex][0] * t + basis[partialIndex][0] * q + basis[spanIndex][0] * span,
            basis[axisIndex][1] * t + basis[partialIndex][1] * q + basis[spanIndex][1] * span,
            basis[axisIndex][2] * t + basis[partialIndex][2] * q + basis[spanIndex][2] * span,
        ];
        List<double[]> low = plan.Select(point =>
            Point(point.T, point.Q, rawMin[spanIndex])).ToList();
        List<double[]> high = plan.Select(point =>
            Point(point.T, point.Q, rawMax[spanIndex])).ToList();
        var resultFaces = new List<GeoFace>
        {
            new() { OuterVertices = low },
            new() { OuterVertices = high.AsEnumerable().Reverse().ToList() },
        };
        for (int index = 0; index < plan.Length; index++)
        {
            int next = (index + 1) % plan.Length;
            resultFaces.Add(new GeoFace
            {
                OuterVertices = [low[index], low[next], high[next], high[index]],
            });
        }
        static bool PlanarAtIfcPrecision(GeoFace face)
        {
            if (face.OuterVertices is not { Count: >= 3 } vertices) return false;
            var points = vertices.Select(IfcPrecisionKeyFeet).ToList();
            var origin = points[0];
            (System.Numerics.BigInteger X, System.Numerics.BigInteger Y,
                System.Numerics.BigInteger Z)? normal = null;
            for (int index = 1; index + 1 < points.Count && normal == null; index++)
            {
                var first = points[index];
                var second = points[index + 1];
                var ux = (System.Numerics.BigInteger)first.X - origin.X;
                var uy = (System.Numerics.BigInteger)first.Y - origin.Y;
                var uz = (System.Numerics.BigInteger)first.Z - origin.Z;
                var vx = (System.Numerics.BigInteger)second.X - origin.X;
                var vy = (System.Numerics.BigInteger)second.Y - origin.Y;
                var vz = (System.Numerics.BigInteger)second.Z - origin.Z;
                var cross = (X: uy * vz - uz * vy, Y: uz * vx - ux * vz,
                    Z: ux * vy - uy * vx);
                if (!cross.X.IsZero || !cross.Y.IsZero || !cross.Z.IsZero)
                    normal = cross;
            }
            return normal != null && points.All(point =>
                normal.Value.X * ((System.Numerics.BigInteger)point.X - origin.X)
                + normal.Value.Y * ((System.Numerics.BigInteger)point.Y - origin.Y)
                + normal.Value.Z * ((System.Numerics.BigInteger)point.Z - origin.Z) == 0);
        }
        if (resultFaces.Any(face => !PlanarAtIfcPrecision(face)))
            return false;
        double[][] resultPoints = resultFaces.SelectMany(face => face.OuterVertices!).ToArray();
        boundary = new GeometryData
        {
            Faces = resultFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = true,
                    FaceIndices = Enumerable.Range(0, resultFaces.Count).ToList(),
                },
            ],
            BoundingBox =
            [
                resultPoints.Min(point => point[0]),
                resultPoints.Min(point => point[1]),
                resultPoints.Min(point => point[2]),
                resultPoints.Max(point => point[0]),
                resultPoints.Max(point => point[1]),
                resultPoints.Max(point => point[2]),
            ],
        };
        return true;
    }

    /// <summary>
    /// Recover the nominal body of a joined straight rectangular beam without guessing from its
    /// category or type name.
    /// </summary>
    internal static bool TryGetNominalRectangularBeamExtrusion(
        Element element, out RectangularBeamExtrusion extrusion)
    {
        extrusion = default;
        if (element.CategoryId != -2001320
            || element.BoundingBox is not { Length: >= 6 } envelope
            || element.Geometry is not { } geometry
            || geometry.BrepSolids is not { Count: > 0 } solids)
            return false;

        // A family instance can serialize both its transformed symbol solid and an identical direct
        // solid.
        var solidSignatures = new List<string>(solids.Count);
        foreach (var solid in solids)
        {
            if (!solid.IsClosed || solid.FaceIndices.Distinct().Count() != 6)
                return false;
            var faceSignatures = new List<string>(6);
            foreach (int faceIndex in solid.FaceIndices.Distinct())
            {
                if (faceIndex < 0 || faceIndex >= geometry.Faces.Count
                    || geometry.Faces[faceIndex].OuterVertices is not { Count: 4 } faceVertices
                    || geometry.Faces[faceIndex].InnerVertices is { Count: > 0 })
                    return false;
                var pointSignatures = new List<string>(4);
                foreach (double[] point in faceVertices)
                {
                    if (point.Length < 3 || point.Take(3).Any(value => !double.IsFinite(value)))
                        return false;
                    var key = IfcPrecisionKeyFeet(point);
                    pointSignatures.Add($"{key.X}:{key.Y}:{key.Z}");
                }
                pointSignatures.Sort(StringComparer.Ordinal);
                faceSignatures.Add(string.Join(",", pointSignatures));
            }
            faceSignatures.Sort(StringComparer.Ordinal);
            solidSignatures.Add(string.Join("|", faceSignatures));
        }
        if (solidSignatures.Distinct(StringComparer.Ordinal).Count() != 1)
            return false;
        bool hasCoincidentDuplicateSolids = solids.Count > 1;

        double toleranceFt = IfcGeometryPrecisionMetres / FeetToMetres * 2;
        var faces = new List<GeoFace>(6);
        foreach (int faceIndex in solids[0].FaceIndices.Distinct())
        {
            if (faceIndex < 0 || faceIndex >= geometry.Faces.Count)
                return false;
            var face = geometry.Faces[faceIndex];
            if (face.OuterVertices is not { Count: 4 }
                || face.InnerVertices is { Count: > 0 })
                return false;
            faces.Add(face);
        }

        var vertices = new List<double[]>();
        var vertexByKey = new Dictionary<(long X, long Y, long Z), int>();
        var faceVertexIndices = new List<int[]>(6);
        foreach (var face in faces)
        {
            var indices = new int[4];
            for (int index = 0; index < 4; index++)
            {
                double[] point = face.OuterVertices![index];
                if (point.Length < 3 || point.Take(3).Any(value => !double.IsFinite(value)))
                    return false;
                var key = IfcPrecisionKeyFeet(point);
                if (!vertexByKey.TryGetValue(key, out int vertexIndex))
                {
                    vertexIndex = vertices.Count;
                    vertexByKey.Add(key, vertexIndex);
                    vertices.Add(point);
                }
                indices[index] = vertexIndex;
            }
            if (indices.Distinct().Count() != 4) return false;
            faceVertexIndices.Add(indices);
        }
        if (vertices.Count != 8) return false;

        var neighbours = Enumerable.Range(0, vertices.Count)
            .Select(_ => new HashSet<int>()).ToArray();
        foreach (int[] face in faceVertexIndices)
            for (int index = 0; index < face.Length; index++)
            {
                int first = face[index], second = face[(index + 1) % face.Length];
                neighbours[first].Add(second);
                neighbours[second].Add(first);
            }
        if (neighbours.Any(set => set.Count != 3)) return false;

        static double[] Difference(double[] end, double[] start) =>
            [end[0] - start[0], end[1] - start[1], end[2] - start[2]];
        static double Length(double[] vector) => Math.Sqrt(
            vector[0] * vector[0] + vector[1] * vector[1] + vector[2] * vector[2]);
        static double Dot(double[] first, double[] second) =>
            first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
        static double[] Unit(double[] vector, double length) =>
            [vector[0] / length, vector[1] / length, vector[2] / length];
        static double[] Cross(double[] first, double[] second) =>
            [first[1] * second[2] - first[2] * second[1],
             first[2] * second[0] - first[0] * second[2],
             first[0] * second[1] - first[1] * second[0]];
        static double Distance(double[] first, double[] second)
        {
            double dx = first[0] - second[0], dy = first[1] - second[1], dz = first[2] - second[2];
            return Math.Sqrt(dx * dx + dy * dy + dz * dz);
        }

        double[] corner = vertices[0];
        var edgeVectors = neighbours[0]
            .Select(index => Difference(vertices[index], corner)).ToArray();
        var edgeLengths = edgeVectors.Select(Length).ToArray();
        if (edgeLengths.Any(length => !double.IsFinite(length) || length <= toleranceFt))
            return false;
        for (int first = 0; first < 3; first++)
            for (int second = first + 1; second < 3; second++)
                if (Math.Abs(Dot(edgeVectors[first], edgeVectors[second]))
                    > edgeLengths[first] * edgeLengths[second] * 1e-8)
                    return false;

        // Orthogonality at one corner is not sufficient for an arbitrary hexahedron.
        for (int mask = 0; mask < 8; mask++)
        {
            var expected = new[] { corner[0], corner[1], corner[2] };
            for (int edge = 0; edge < 3; edge++)
                if ((mask & (1 << edge)) != 0)
                    for (int coordinate = 0; coordinate < 3; coordinate++)
                        expected[coordinate] += edgeVectors[edge][coordinate];
            if (!vertices.Any(vertex => Distance(vertex, expected) <= toleranceFt))
                return false;
        }

        int axisIndex = Enumerable.Range(0, 3)
            .OrderByDescending(index => edgeLengths[index]).First();
        double actualLengthFt = edgeLengths[axisIndex];
        double nextLengthFt = edgeLengths.Where((_, index) => index != axisIndex).Max();
        if (actualLengthFt - nextLengthFt <= toleranceFt) return false;
        int[] profileIndices = Enumerable.Range(0, 3)
            .Where(index => index != axisIndex).ToArray();
        double[] axis = Unit(edgeVectors[axisIndex], actualLengthFt);
        double profileWidthFt = edgeLengths[profileIndices[0]];
        double profileDepthFt = edgeLengths[profileIndices[1]];
        double[] profileX = Unit(edgeVectors[profileIndices[0]], profileWidthFt);
        double[] profileY = Unit(edgeVectors[profileIndices[1]], profileDepthFt);
        double[] expectedProfileY = Cross(axis, profileX);
        if (Math.Abs(Math.Abs(Dot(expectedProfileY, profileY)) - 1) > 1e-8)
            return false;

        var solidCentre = new double[3];
        foreach (double[] vertex in vertices)
            for (int coordinate = 0; coordinate < 3; coordinate++)
                solidCentre[coordinate] += vertex[coordinate] / vertices.Count;
        var envelopeCentre = new[]
        {
            (envelope[0] + envelope[3]) / 2,
            (envelope[1] + envelope[4]) / 2,
            (envelope[2] + envelope[5]) / 2,
        };
        double[] centreDelta = Difference(envelopeCentre, solidCentre);
        if (Math.Abs(Dot(centreDelta, profileX)) > toleranceFt
            || Math.Abs(Dot(centreDelta, profileY)) > toleranceFt)
            return false;
        double centreShiftAlongAxisFt = Dot(centreDelta, axis);
        var reconstructedCentreDelta = new[]
        {
            axis[0] * centreShiftAlongAxisFt,
            axis[1] * centreShiftAlongAxisFt,
            axis[2] * centreShiftAlongAxisFt,
        };
        if (Distance(centreDelta, reconstructedCentreDelta) > toleranceFt)
            return false;

        var envelopeExtents = new[]
        {
            envelope[3] - envelope[0],
            envelope[4] - envelope[1],
            envelope[5] - envelope[2],
        };
        if (envelopeExtents.Any(extent => !double.IsFinite(extent) || extent <= 0))
            return false;
        var lengthCandidates = new List<double>(3);
        for (int coordinate = 0; coordinate < 3; coordinate++)
        {
            double crossExtent = Math.Abs(profileX[coordinate]) * profileWidthFt
                + Math.Abs(profileY[coordinate]) * profileDepthFt;
            if (Math.Abs(axis[coordinate]) <= 1e-8)
            {
                if (Math.Abs(envelopeExtents[coordinate] - crossExtent) > toleranceFt)
                    return false;
                continue;
            }
            double candidate = (envelopeExtents[coordinate] - crossExtent)
                / Math.Abs(axis[coordinate]);
            if (!double.IsFinite(candidate) || candidate <= 0) return false;
            lengthCandidates.Add(candidate);
        }
        if (lengthCandidates.Count == 0) return false;
        double nominalLengthFt = lengthCandidates[0];
        if (lengthCandidates.Any(candidate => Math.Abs(candidate - nominalLengthFt) > toleranceFt))
            return false;
        for (int coordinate = 0; coordinate < 3; coordinate++)
        {
            double reconstructedExtent = Math.Abs(axis[coordinate]) * nominalLengthFt
                + Math.Abs(profileX[coordinate]) * profileWidthFt
                + Math.Abs(profileY[coordinate]) * profileDepthFt;
            if (Math.Abs(reconstructedExtent - envelopeExtents[coordinate]) > toleranceFt)
                return false;
        }

        // A single equal-length solid keeps its authored BRep.
        double totalExtensionFt = nominalLengthFt - actualLengthFt;
        double startExtensionFt = totalExtensionFt / 2 - centreShiftAlongAxisFt;
        double endExtensionFt = totalExtensionFt / 2 + centreShiftAlongAxisFt;
        double maximumExtensionFt = Math.Max(profileWidthFt, profileDepthFt) + toleranceFt;
        if (totalExtensionFt < -toleranceFt
            || (totalExtensionFt <= toleranceFt && !hasCoincidentDuplicateSolids)
            || startExtensionFt < -toleranceFt || endExtensionFt < -toleranceFt
            || startExtensionFt > maximumExtensionFt
            || endExtensionFt > maximumExtensionFt)
            return false;

        var startCentreFt = new[]
        {
            envelopeCentre[0] - axis[0] * nominalLengthFt / 2,
            envelopeCentre[1] - axis[1] * nominalLengthFt / 2,
            envelopeCentre[2] - axis[2] * nominalLengthFt / 2,
        };
        extrusion = new RectangularBeamExtrusion(
            startCentreFt, axis, profileX,
            profileWidthFt, profileDepthFt, nominalLengthFt);
        return true;
    }

    private (int shapeId, int placementId) CreateBeamSweptSolid(
        StepWriter w, RectangularBeamExtrusion beam, int subCtxId, int parentPlacementId)
    {
        int placementPointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(beam.StartCentreFt[0] * FeetToMetres),
            D(beam.StartCentreFt[1] * FeetToMetres),
            D(beam.StartCentreFt[2] * FeetToMetres)));
        int placementAxisId = w.Add("IFCDIRECTION", StepWriter.List(
            D(beam.Axis[0]), D(beam.Axis[1]), D(beam.Axis[2])));
        int placementRefDirectionId = w.Add("IFCDIRECTION", StepWriter.List(
            D(beam.ProfileX[0]), D(beam.ProfileX[1]), D(beam.ProfileX[2])));
        int placementFrameId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(placementPointId)},{R(placementAxisId)},{R(placementRefDirectionId)}");
        int placementId = w.Add("IFCLOCALPLACEMENT",
            $"{R(parentPlacementId)},{R(placementFrameId)}");

        int profileOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0."));
        int profilePlacementId = w.Add("IFCAXIS2PLACEMENT2D", $"{R(profileOriginId)},$");
        int profileId = w.Add("IFCRECTANGLEPROFILEDEF",
            $".AREA.,$,{R(profilePlacementId)},"
            + $"{D(beam.ProfileWidthFt * FeetToMetres)},{D(beam.ProfileDepthFt * FeetToMetres)}");

        int extrusionOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
        int extrusionPositionId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(extrusionOriginId)},$,$");
        int extrusionDirectionId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "1."));
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(extrusionPositionId)},{R(extrusionDirectionId)},"
            + D(beam.LengthFt * FeetToMetres));
        int shapeRepresentationId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
        int productShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(shapeRepresentationId))}");
        return (productShapeId, placementId);
    }

    /// <summary>Create SweptSolid (extruded rectangle) geometry for a wall.</summary>
    private (int shapeId, int placementId) CreateWallSweptSolid(
        StepWriter w, Element elem, double[] bbox, int subCtxId, int axisSubCtxId,
        int parentPlacementId, bool forceSerializedDefinition = false,
        GeometryData? verifiedBoundary = null,
        bool allowBoundaryOwnedVerticalDefinition = false,
        bool allowWriterLatticeBounds = false,
        bool useWriterLatticeBoundaryPlan = false,
        IReadOnlyList<double[]>? boundaryOwnedSerializedAxisPlan = null,
        bool useBoundaryOwnedSerializedPlanAxis = false,
        bool useBoundaryOwnedPlanAxis = false,
        bool useVerifiedBoundaryBoundsForVerticalDefinition = false,
        bool preserveBoundaryOwnedCollinearPlan = false,
        bool allowExactArbitraryBoundaryOwnedVerticalDefinition = false,
        bool allowExactUncutPairedSideProfileVerticalDefinition = false,
        GeometryData? boundaryOwnedAxisEnvelope = null)
    {
        var solid = elem.Geometry?.Solids?.FirstOrDefault();

        double cx, cy, z0, wallLength, wallWidth, dz;
        double refDirX, refDirY;
        List<double[]>? wallPlanFt = null;
        bool wallPlanIsExactRectangle = false;
        List<double[]>? writerLatticeAxisFt = null;
        List<double[]>? boundaryOwnedPlanFt = null;
        double boundaryOwnedBaseZFt = 0;
        double boundaryOwnedHeightFt = 0;
        bool useBoundaryOwnedVerticalDefinition = false;
        bool useBoundaryOwnedTrimmedPlan = false;

        // Reject corrupt solids (mis-decoded doubles reach 1e20+): fall back to bbox, which is
        // already range-checked by the caller.
        static bool Sane(params double[] vals)
        {
            foreach (var v in vals)
                if (!double.IsFinite(v) || Math.Abs(v) > 1e7) return false;
            return true;
        }
        double? WallWidthFt(Element e)
        {
            // CompoundStructure is the serialized definition of a basic/stacked wall's total
            // thickness.
            if ((e.ValidatedWallTypeThicknessFeet is > 0 || e.Layers is { Count: > 0 })
                && TryGetSerializedWallWidthFeet(e, out double compoundWidthFt))
                return compoundWidthFt;

            double? parameterWidth = null;
            foreach (var p in e.Parameters)
                if (p.Id == -1001000 && p.Value is double d && d > 0.001 && d < 50)
                {
                    parameterWidth = d;
                    break;
                }

            // Profile/cross-section walls occasionally expose the profile depth as
            // WALL_ATTR_WIDTH_PARAM (for example 3 m instead of the actual 202 mm).
            double bboxMinPlan = Math.Min(bbox[3] - bbox[0], bbox[4] - bbox[1]);
            if (bboxMinPlan is > 0.02 and < 3.0
                && (parameterWidth is null || parameterWidth > 3.0
                    || parameterWidth > bboxMinPlan * 2.5))
                return bboxMinPlan;

            return parameterWidth;
        }
        if (solid != null && !(Sane(solid.Position[0], solid.Position[1], solid.Position[2],
                solid.ProfileWidth, solid.ProfileDepth, solid.ExtrusionHeight)
            && solid.ExtrusionHeight > 1e-6 && solid.ProfileWidth > 1e-6))
            solid = null;

        if (elem.Location is { ArcRadius: null, CurveType: "Line" } loc0
            && Sane(loc0.StartPoint[0], loc0.StartPoint[1], loc0.StartPoint[2],
                    loc0.EndPoint[0], loc0.EndPoint[1], loc0.EndPoint[2])
            && WallWidthFt(elem) is { } widFt0 && widFt0 > 0.001)
        {
            double lx0 = loc0.EndPoint[0] - loc0.StartPoint[0], ly0 = loc0.EndPoint[1] - loc0.StartPoint[1];
            double locationLengthFt = Math.Sqrt(lx0 * lx0 + ly0 * ly0);
            if (locationLengthFt > (forceSerializedDefinition ? 0 : 0.05))
                solid = null; // take the verified location/profile branch below
        }

        if (solid != null)
        {
            cx = solid.Position[0] * FeetToMetres;
            cy = solid.Position[1] * FeetToMetres;
            z0 = solid.Position[2] * FeetToMetres;
            wallLength = solid.ProfileWidth * FeetToMetres;
            wallWidth = solid.ProfileDepth * FeetToMetres;
            dz = solid.ExtrusionHeight * FeetToMetres;
            refDirX = solid.RefDirection[0];
            refDirY = solid.RefDirection[1];
        }
        else if (elem.Location is { ArcRadius: null, CurveType: "Line" } loc
            && Sane(loc.StartPoint[0], loc.StartPoint[1], loc.StartPoint[2],
                    loc.EndPoint[0], loc.EndPoint[1], loc.EndPoint[2])
            && WallWidthFt(elem) is { } widFt && widFt > 0.001)
        {
            // Straight wall with a decoded location line: build the extrusion along it - the record
            // bbox is axis-aligned and lies about ROTATED walls' footprints.
            double lx = loc.EndPoint[0] - loc.StartPoint[0], ly = loc.EndPoint[1] - loc.StartPoint[1];
            double lenFt = Math.Sqrt(lx * lx + ly * ly);
            if (lenFt < 0.01 && !forceSerializedDefinition)
                return CreateBboxSweptSolid(w, bbox, subCtxId, parentPlacementId);
            wallLength = lenFt * FeetToMetres;
            wallWidth = widFt * FeetToMetres;
            refDirX = lx / lenFt; refDirY = ly / lenFt;
            IReadOnlyList<double> verticalDefinitionBounds =
                useVerifiedBoundaryBoundsForVerticalDefinition
                    && verifiedBoundary?.BoundingBox is { Length: 6 }
                        verifiedBoundaryBounds
                    ? verifiedBoundaryBounds : bbox;
            useBoundaryOwnedVerticalDefinition = allowBoundaryOwnedVerticalDefinition
                && verifiedBoundary != null
                && (TryGetExactStraightWallVerticalExtrusionDefinition(
                        verifiedBoundary, loc, widFt, verticalDefinitionBounds,
                        out boundaryOwnedPlanFt,
                        out boundaryOwnedBaseZFt, out boundaryOwnedHeightFt, out _,
                        allowWriterLatticeBounds)
                    || allowExactArbitraryBoundaryOwnedVerticalDefinition
                    && TryGetExactBoundaryOwnedArbitraryVerticalExtrusionDefinition(
                        verifiedBoundary, loc, widFt, verticalDefinitionBounds,
                        out boundaryOwnedPlanFt,
                        out boundaryOwnedBaseZFt, out boundaryOwnedHeightFt)
                    || allowExactUncutPairedSideProfileVerticalDefinition
                    && TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                        verifiedBoundary, loc, widFt, verticalDefinitionBounds,
                        out boundaryOwnedPlanFt,
                        out boundaryOwnedBaseZFt, out boundaryOwnedHeightFt));
            // LocationCurve and WALL_ATTR_WIDTH_PARAM are the serialized definition of a
            // StandardCase wall.
            cx = (loc.StartPoint[0] + lx / 2) * FeetToMetres;
            cy = (loc.StartPoint[1] + ly / 2) * FeetToMetres;
            if (TryResolveStraightWallPlanCentre(
                loc, widFt, bbox, out double serializedCentreXFt, out double serializedCentreYFt))
            {
                cx = serializedCentreXFt * FeetToMetres;
                cy = serializedCentreYFt * FeetToMetres;
            }
            if (boundaryOwnedSerializedAxisPlan is { Count: 4 }
                && verifiedBoundary?.BoundingBox is { Length: 6 } verifiedBounds
                && TryGetExactStraightWallVerticalExtrusionDefinition(
                    verifiedBoundary, loc, widFt, verifiedBounds,
                    out var exactTrimmedPlanFt,
                    out double exactTrimmedBaseZFt,
                    out double exactTrimmedHeightFt,
                    out string trimmedPlanReason)
                && trimmedPlanReason == "exact"
                && WallPlanMatchesSerializedBounds(
                    boundaryOwnedSerializedAxisPlan, bbox))
            {
                boundaryOwnedPlanFt = exactTrimmedPlanFt;
                boundaryOwnedBaseZFt = exactTrimmedBaseZFt;
                boundaryOwnedHeightFt = exactTrimmedHeightFt;
                wallPlanFt = boundaryOwnedPlanFt;
                useBoundaryOwnedTrimmedPlan = true;
                var axisAlong = boundaryOwnedSerializedAxisPlan
                    .Select(point => point[0] * refDirX
                        + point[1] * refDirY).ToList();
                double normalX = -refDirY, normalY = refDirX;
                var axisAcross = boundaryOwnedSerializedAxisPlan
                    .Select(point => point[0] * normalX
                        + point[1] * normalY).ToList();
                double minimumAxisAlong = axisAlong.Min();
                double maximumAxisAlong = axisAlong.Max();
                double minimumAxisAcross = axisAcross.Min();
                double maximumAxisAcross = axisAcross.Max();
                wallLength = (maximumAxisAlong - minimumAxisAlong)
                    * FeetToMetres;
                double centreAxisAlong =
                    (minimumAxisAlong + maximumAxisAlong) / 2;
                double centreAxisAcross =
                    (minimumAxisAcross + maximumAxisAcross) / 2;
                cx = (centreAxisAlong * refDirX
                    + centreAxisAcross * normalX) * FeetToMetres;
                cy = (centreAxisAlong * refDirY
                    + centreAxisAcross * normalY) * FeetToMetres;
            }
            else if (useBoundaryOwnedVerticalDefinition)
            {
                // The complete boundary is therefore the authoritative constant section and
                // vertical span, even when propagated base/height parameters describe an adjacent
                // joined segment.
                wallPlanFt = useWriterLatticeBoundaryPlan
                    ? SnapPlanToIfcWriterLattice(boundaryOwnedPlanFt!)
                    : boundaryOwnedPlanFt;
                if (!preserveBoundaryOwnedCollinearPlan
                    && useVerifiedBoundaryBoundsForVerticalDefinition
                    && verifiedBoundary?.BoundingBox is { Length: 6 }
                        exactPlanBounds
                    && TryGetExactVerticalRectangularWallPlan(
                        verifiedBoundary, loc, widFt, exactPlanBounds,
                        out var exactBoundaryPlan))
                {
                    wallPlanFt = exactBoundaryPlan;
                    wallPlanIsExactRectangle = true;
                    var boundaryAlong = exactBoundaryPlan.Select(point =>
                        point[0] * refDirX + point[1] * refDirY).ToList();
                    double normalX = -refDirY, normalY = refDirX;
                    var boundaryAcross = exactBoundaryPlan.Select(point =>
                        point[0] * normalX + point[1] * normalY).ToList();
                    double minimumAlong = boundaryAlong.Min();
                    double maximumAlong = boundaryAlong.Max();
                    double minimumAcross = boundaryAcross.Min();
                    double maximumAcross = boundaryAcross.Max();
                    wallLength = (maximumAlong - minimumAlong) * FeetToMetres;
                    double centreAlong = (minimumAlong + maximumAlong) / 2;
                    double centreAcross = (minimumAcross + maximumAcross) / 2;
                    cx = (centreAlong * refDirX + centreAcross * normalX)
                        * FeetToMetres;
                    cy = (centreAlong * refDirY + centreAcross * normalY)
                        * FeetToMetres;
                }
                if (useWriterLatticeBoundaryPlan)
                {
                    // The separately written BRep cutter is already serialized on the writer
                    // lattice.
                    wallPlanIsExactRectangle = false;
                    writerLatticeAxisFt = SnapPlanToIfcWriterLattice(
                    [
                        [loc.StartPoint[0], loc.StartPoint[1]],
                        [loc.EndPoint[0], loc.EndPoint[1]],
                    ]);
                }
            }
            else if (TryGetAuthoredStraightWallPlan(elem, widFt, out var joinedPlanFt)
                && WallPlanMatchesSerializedBounds(joinedPlanFt, bbox))
            {
                wallPlanFt = joinedPlanFt;
                var joinedAlong = joinedPlanFt
                    .Select(point => point[0] * refDirX + point[1] * refDirY).ToList();
                double normalX = -refDirY, normalY = refDirX;
                var joinedAcross = joinedPlanFt
                    .Select(point => point[0] * normalX + point[1] * normalY).ToList();
                double joinedMinAlong = joinedAlong.Min();
                double joinedMaxAlong = joinedAlong.Max();
                double joinedMinAcross = joinedAcross.Min();
                double joinedMaxAcross = joinedAcross.Max();
                wallLength = (joinedMaxAlong - joinedMinAlong) * FeetToMetres;
                double joinedCentreAlong = (joinedMinAlong + joinedMaxAlong) / 2;
                double joinedCentreAcross = (joinedMinAcross + joinedMaxAcross) / 2;
                cx = (joinedCentreAlong * refDirX + joinedCentreAcross * normalX)
                    * FeetToMetres;
                cy = (joinedCentreAlong * refDirY + joinedCentreAcross * normalY)
                    * FeetToMetres;
            }
            else if (verifiedBoundary != null
                && TryGetExactVerticalRectangularWallPlan(verifiedBoundary, loc, widFt,
                    bbox, out var boundaryPlanFt))
            {
                // A butt/miter join can extend an otherwise exact rectangle beyond both
                // LocationCurve endpoints.
                wallPlanFt = boundaryPlanFt;
                wallPlanIsExactRectangle = true;
                var boundaryAlong = boundaryPlanFt
                    .Select(point => point[0] * refDirX + point[1] * refDirY).ToList();
                double normalX = -refDirY, normalY = refDirX;
                var boundaryAcross = boundaryPlanFt
                    .Select(point => point[0] * normalX + point[1] * normalY).ToList();
                double minAlong = boundaryAlong.Min(), maxAlong = boundaryAlong.Max();
                double minAcross = boundaryAcross.Min(), maxAcross = boundaryAcross.Max();
                wallLength = (maxAlong - minAlong) * FeetToMetres;
                double centreAlong = (minAlong + maxAlong) / 2;
                double centreAcross = (minAcross + maxAcross) / 2;
                cx = (centreAlong * refDirX + centreAcross * normalX) * FeetToMetres;
                cy = (centreAlong * refDirY + centreAcross * normalY) * FeetToMetres;
            }
            double? baseOffsetFt = elem.Parameters
                .Where(parameter => (parameter.Id is -1001111 or -1001108)
                    && parameter.Value is double)
                .OrderBy(parameter => parameter.Id == -1001111 ? 0 : 1)
                .Select(parameter => (double)parameter.Value!)
                .Cast<double?>()
                .FirstOrDefault();
            double locationBaseFt = Math.Min(loc.StartPoint[2], loc.EndPoint[2]);
            double exactBaseOffsetFt = baseOffsetFt ?? 0;
            z0 = (locationBaseFt + exactBaseOffsetFt) * FeetToMetres;
            double bboxHeightFt = bbox[5] - bbox[2];
            dz = bboxHeightFt * FeetToMetres;
            double hFt = 0;
            foreach (var p in elem.Parameters)
                if (p.Id == -1001105 && p.Value is double hv && hv > 0.1 && hv < 10000) { hFt = hv; break; }
            if (hFt > 0) dz = hFt * FeetToMetres;
            if (useBoundaryOwnedVerticalDefinition
                || useBoundaryOwnedTrimmedPlan)
            {
                z0 = boundaryOwnedBaseZFt * FeetToMetres;
                dz = boundaryOwnedHeightFt * FeetToMetres;
            }
        }
        else
        {
            // Fallback: compute from bbox
            double x0 = bbox[0] * FeetToMetres, y0 = bbox[1] * FeetToMetres;
            z0 = bbox[2] * FeetToMetres;
            double x1 = bbox[3] * FeetToMetres, y1 = bbox[4] * FeetToMetres;
            double dx = x1 - x0, dy = y1 - y0;
            dz = (bbox[5] - bbox[2]) * FeetToMetres;
            bool wallAlongX = dx >= dy;
            wallLength = wallAlongX ? dx : dy;
            wallWidth = wallAlongX ? dy : dx;
            cx = (x0 + x1) / 2;
            cy = (y0 + y1) / 2;
            refDirX = wallAlongX ? 1 : 0;
            refDirY = wallAlongX ? 0 : 1;
        }

        _wallFrames[elem.Id] = (cx, cy, z0, refDirX, refDirY, wallWidth);
        double placementX = useWriterLatticeBoundaryPlan ? 0 : cx;
        double placementY = useWriterLatticeBoundaryPlan ? 0 : cy;
        double profileAxisX = useWriterLatticeBoundaryPlan ? 1 : refDirX;
        double profileAxisY = useWriterLatticeBoundaryPlan ? 0 : refDirY;

        // Element placement at center-bottom, rotated to wall direction
        int placementPtId = w.Add("IFCCARTESIANPOINT",
            StepWriter.List(D(placementX), D(placementY), D(z0)));
        int refDirId = w.Add("IFCDIRECTION",
            StepWriter.List(D(profileAxisX), D(profileAxisY), "0."));
        int placementAxisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(placementPtId)},$,{R(refDirId)}");
        int placementId = w.Add("IFCLOCALPLACEMENT", $"{R(parentPlacementId)},{R(placementAxisId)}");

        int profileId;
        if (wallPlanFt is { Count: >= 4 } && !wallPlanIsExactRectangle)
        {
            // Joined StandardCase walls remain vertical extrusions, but their two exterior side
            // planes can have different authored end coordinates.
            double normalX = -profileAxisY, normalY = profileAxisX;
            var profilePointIds = new List<int>(wallPlanFt.Count + 1);
            foreach (var point in wallPlanFt)
            {
                double worldX = point[0] * FeetToMetres;
                double worldY = point[1] * FeetToMetres;
                double localX = (worldX - placementX) * profileAxisX
                    + (worldY - placementY) * profileAxisY;
                double localY = (worldX - placementX) * normalX
                    + (worldY - placementY) * normalY;
                profilePointIds.Add(w.Add("IFCCARTESIANPOINT",
                    StepWriter.List(D(localX), D(localY))));
            }
            profilePointIds.Add(profilePointIds[0]);
            int profileCurveId = w.Add("IFCPOLYLINE",
                StepWriter.List(profilePointIds.Select(R).ToArray()));
            profileId = w.Add("IFCARBITRARYCLOSEDPROFILEDEF",
                $".AREA.,$,{R(profileCurveId)}");
        }
        else
        {
            // Unjoined wall: rectangle centered at the location-axis frame.
            int profilePtId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0."));
            int profilePlacementId = w.Add("IFCAXIS2PLACEMENT2D", $"{R(profilePtId)},$");
            profileId = w.Add("IFCRECTANGLEPROFILEDEF",
                $".AREA.,$,{R(profilePlacementId)},{D(wallLength)},{D(wallWidth)}");
        }

        // Extrusion along Z
        int extPositionOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
        int extPositionId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(extPositionOriginId)},$,$");
        int extDirId = w.Add("IFCDIRECTION", StepWriter.List("0.", "0.", "1."));
        int solidId = w.Add("IFCEXTRUDEDAREASOLID",
            $"{R(profileId)},{R(extPositionId)},{R(extDirId)},{D(dz)}");

        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},{StepWriter.List(R(solidId))}");
        List<double[]>? joinedEnvelopeAxisLocalMetres = null;
        if (boundaryOwnedAxisEnvelope?.Faces is { Count: > 0 } axisFaces)
        {
            var axisPoints = axisFaces
                .SelectMany(face => face.OuterVertices ?? [])
                .Where(point => point.Length >= 2
                    && double.IsFinite(point[0])
                    && double.IsFinite(point[1]))
                .ToList();
            if (axisPoints.Count > 0)
            {
                var alongCoordinatesFt = axisPoints.Select(point =>
                    point[0] * profileAxisX
                    + point[1] * profileAxisY).ToList();
                double minimumAlongFt = alongCoordinatesFt.Min();
                double maximumAlongFt = alongCoordinatesFt.Max();
                double placementAlongMetres = placementX * profileAxisX
                    + placementY * profileAxisY;
                if (maximumAlongFt > minimumAlongFt)
                    joinedEnvelopeAxisLocalMetres =
                    [
                        [
                            minimumAlongFt * FeetToMetres
                                - placementAlongMetres,
                            0,
                        ],
                        [
                            maximumAlongFt * FeetToMetres
                                - placementAlongMetres,
                            0,
                        ],
                    ];
            }
        }
        List<double[]>? boundaryOwnedPlanAxisLocalMetres = null;
        IReadOnlyList<double[]>? boundaryOwnedAxisPlanFt =
            useBoundaryOwnedSerializedPlanAxis
                && boundaryOwnedSerializedAxisPlan is { Count: 4 }
                ? boundaryOwnedSerializedAxisPlan
                : useBoundaryOwnedPlanAxis && wallPlanFt is { Count: 4 }
                    ? wallPlanFt : null;
        if (boundaryOwnedAxisPlanFt is { Count: 4 })
        {
            double[] axisStartFt =
            [
                (boundaryOwnedAxisPlanFt[0][0]
                    + boundaryOwnedAxisPlanFt[3][0]) / 2,
                (boundaryOwnedAxisPlanFt[0][1]
                    + boundaryOwnedAxisPlanFt[3][1]) / 2,
            ];
            double[] axisEndFt =
            [
                (boundaryOwnedAxisPlanFt[1][0]
                    + boundaryOwnedAxisPlanFt[2][0]) / 2,
                (boundaryOwnedAxisPlanFt[1][1]
                    + boundaryOwnedAxisPlanFt[2][1]) / 2,
            ];
            double normalX = -profileAxisY, normalY = profileAxisX;
            boundaryOwnedPlanAxisLocalMetres =
            [
                [
                    (axisStartFt[0] * FeetToMetres - placementX)
                        * profileAxisX
                        + (axisStartFt[1] * FeetToMetres - placementY)
                        * profileAxisY,
                    (axisStartFt[0] * FeetToMetres - placementX)
                        * normalX
                        + (axisStartFt[1] * FeetToMetres - placementY)
                        * normalY,
                ],
                [
                    (axisEndFt[0] * FeetToMetres - placementX)
                        * profileAxisX
                        + (axisEndFt[1] * FeetToMetres - placementY)
                        * profileAxisY,
                    (axisEndFt[0] * FeetToMetres - placementX)
                        * normalX
                        + (axisEndFt[1] * FeetToMetres - placementY)
                        * normalY,
                ],
            ];
        }
        int axisStartPointId = writerLatticeAxisFt is { Count: 2 }
            ? w.Add("IFCCARTESIANPOINT", StepWriter.List(
                D(writerLatticeAxisFt[0][0] * FeetToMetres),
                D(writerLatticeAxisFt[0][1] * FeetToMetres)))
            : joinedEnvelopeAxisLocalMetres is { Count: 2 }
                ? w.Add("IFCCARTESIANPOINT", StepWriter.List(
                    D(joinedEnvelopeAxisLocalMetres[0][0]),
                    D(joinedEnvelopeAxisLocalMetres[0][1])))
            : boundaryOwnedPlanAxisLocalMetres is { Count: 2 }
                ? w.Add("IFCCARTESIANPOINT", StepWriter.List(
                    D(boundaryOwnedPlanAxisLocalMetres[0][0]),
                    D(boundaryOwnedPlanAxisLocalMetres[0][1])))
                : w.Add("IFCCARTESIANPOINT",
                    StepWriter.List(D(-wallLength / 2), "0."));
        int axisEndPointId = writerLatticeAxisFt is { Count: 2 }
            ? w.Add("IFCCARTESIANPOINT", StepWriter.List(
                D(writerLatticeAxisFt[1][0] * FeetToMetres),
                D(writerLatticeAxisFt[1][1] * FeetToMetres)))
            : joinedEnvelopeAxisLocalMetres is { Count: 2 }
                ? w.Add("IFCCARTESIANPOINT", StepWriter.List(
                    D(joinedEnvelopeAxisLocalMetres[1][0]),
                    D(joinedEnvelopeAxisLocalMetres[1][1])))
            : boundaryOwnedPlanAxisLocalMetres is { Count: 2 }
                ? w.Add("IFCCARTESIANPOINT", StepWriter.List(
                    D(boundaryOwnedPlanAxisLocalMetres[1][0]),
                    D(boundaryOwnedPlanAxisLocalMetres[1][1])))
                : w.Add("IFCCARTESIANPOINT",
                    StepWriter.List(D(wallLength / 2), "0."));
        int axisCurveId = w.Add("IFCPOLYLINE",
            StepWriter.List(R(axisStartPointId), R(axisEndPointId)));
        int axisShapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(axisSubCtxId)},{S("Axis")},{S("Curve2D")},{StepWriter.List(R(axisCurveId))}");
        int prodShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
            $"$,$,{StepWriter.List(R(axisShapeRepId), R(shapeRepId))}");

        return (prodShapeId, placementId);
    }

    internal static bool WallPlanMatchesSerializedBounds(
        IReadOnlyList<double[]> plan, IReadOnlyList<double> bounds)
    {
        if (plan.Count < 3 || bounds.Count < 6) return false;
        double[] planBounds =
        [
            plan.Min(point => point[0]), plan.Min(point => point[1]),
            plan.Max(point => point[0]), plan.Max(point => point[1]),
        ];
        double scale = Math.Max(1.0,
            planBounds.Concat(bounds).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 256 * MachineEpsilon * scale;
        return Math.Abs(planBounds[0] - bounds[0]) <= roundoff
            && Math.Abs(planBounds[1] - bounds[1]) <= roundoff
            && Math.Abs(planBounds[2] - bounds[3]) <= roundoff
            && Math.Abs(planBounds[3] - bounds[4]) <= roundoff;
    }

    internal static bool WallPlanMatchesSerializedBoundsAtIfcPrecision(
        IReadOnlyList<double[]> plan, IReadOnlyList<double> bounds)
    {
        if (plan.Count < 3 || bounds.Count < 6
            || plan.Any(point => point.Length < 2
                || !double.IsFinite(point[0]) || !double.IsFinite(point[1]))
            || !double.IsFinite(bounds[0]) || !double.IsFinite(bounds[1])
            || !double.IsFinite(bounds[3]) || !double.IsFinite(bounds[4]))
            return false;
        double[] planBounds =
        [
            plan.Min(point => point[0]), plan.Min(point => point[1]),
            plan.Max(point => point[0]), plan.Max(point => point[1]),
        ];
        double[] serializedBounds = [bounds[0], bounds[1], bounds[3], bounds[4]];
        return planBounds.Select(value =>
                IfcPrecisionBinMetres(value * FeetToMetres))
            .SequenceEqual(serializedBounds.Select(value =>
                IfcPrecisionBinMetres(value * FeetToMetres)));
    }

    internal static List<double[]> SnapPlanToIfcWriterLattice(
        IEnumerable<double[]> plan) =>
        plan.Select(point =>
        {
            var key = IfcPrecisionKeyFeet([point[0], point[1], 0]);
            return new[]
            {
                key.X * IfcGeometryPrecisionMetres / FeetToMetres,
                key.Y * IfcGeometryPrecisionMetres / FeetToMetres,
            };
        }).ToList();

    /// <summary>
    /// Exact rectangular record bounds are sufficient; joined profiles additionally require a
    /// two-level authored boundary whose plan reproduces every serialized XY bound.
    /// </summary>
    internal static bool CanExportStandardCaseWallAsSweptSolid(Element element,
        IReadOnlyList<double> bounds, GeometryData? rebuiltBoundary,
        bool allowBoundaryOwnedVerticalDefinition = false,
        bool allowWriterLatticeBounds = false,
        bool allowOpenFragmentedAuthoredPlan = false,
        bool allowExactArbitraryBoundaryOwnedVerticalDefinition = false,
        bool allowExactUncutPairedSideProfileVerticalDefinition = false)
    {
        if (element.Location is not { CurveType: "Line", ArcRadius: null } location
            || bounds.Count < 6
            || !TryGetSerializedWallWidthFeet(element, out double widthFt))
            return false;

        bool verticalParametersMatch = WallVerticalParametersMatchSerializedBounds(
            element, location, bounds);
        string boundaryRejectionReason = "boundary-unavailable";
        bool exactBoundaryDefinition = false;
        if (allowBoundaryOwnedVerticalDefinition && rebuiltBoundary != null)
        {
            exactBoundaryDefinition =
                TryGetExactStraightWallVerticalExtrusionDefinition(
                    rebuiltBoundary, location, widthFt, bounds,
                    out _, out _, out _, out boundaryRejectionReason,
                    allowWriterLatticeBounds);
            if (!exactBoundaryDefinition
                && allowExactArbitraryBoundaryOwnedVerticalDefinition
                && TryGetExactBoundaryOwnedArbitraryVerticalExtrusionDefinition(
                    rebuiltBoundary, location, widthFt, bounds,
                    out _, out _, out _))
            {
                exactBoundaryDefinition = true;
                boundaryRejectionReason =
                    "exact-boundary-owned-arbitrary-profile";
            }
            if (!exactBoundaryDefinition
                && allowExactUncutPairedSideProfileVerticalDefinition
                && TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
                    rebuiltBoundary, location, widthFt, bounds,
                    out _, out _, out _))
            {
                exactBoundaryDefinition = true;
                boundaryRejectionReason =
                    "exact-uncut-paired-side-profile-vertical-extrusion";
            }
        }
        if (allowBoundaryOwnedVerticalDefinition
            && Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id) && id == element.Id))
            DiagnosticSink.WriteLine($"IFCBOUNDARYOWNEDGATE eid={element.Id} "
                + $"accepted={exactBoundaryDefinition} "
                + $"stage={boundaryRejectionReason}");
        bool exactVerticalBoundary = rebuiltBoundary != null
            && IsExactVerticalExtrusionBoundary(rebuiltBoundary);
        bool authoredPlanMatches = TryGetAuthoredStraightWallPlan(
                element, widthFt, out var plan)
            && WallPlanMatchesSerializedBounds(plan, bounds);
        bool hasClosedSourceSolid = element.Geometry?.BrepSolids?
            .Any(solid => solid.IsClosed) == true;
        bool hasExactOpenFragmentedAuthoredDefinition =
            allowOpenFragmentedAuthoredPlan
            && rebuiltBoundary != null
            && element.Geometry?.BrepSolids is { Count: > 0 }
            && !hasClosedSourceSolid
            && element.CuttingElementIds is { Count: 0 }
            && element.Geometry?.Faces?.Any(face =>
                face.AlternativeOuterVertices is { Count: > 0 }) != true
            && authoredPlanMatches
            && OpenFragmentedWallMinimumCapMatchesAuthoredPlan(
                rebuiltBoundary, location, plan, bounds);
        bool exactRectangularBoundary = false;
        if (exactVerticalBoundary)
        {
            exactRectangularBoundary = TryGetExactVerticalRectangularWallPlan(
                rebuiltBoundary!, location, widthFt, bounds,
                out _, out string rectangularBoundaryRejectionReason);
            if (!exactRectangularBoundary && allowWriterLatticeBounds
                && rectangularBoundaryRejectionReason
                    == "serialized-bounds-writer-lattice")
                exactRectangularBoundary = true;
        }
        if (Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") is { } gateDebugIds
            && gateDebugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id) && id == element.Id))
        {
            string exactDefinitionReason = "boundary-unavailable";
            bool exactDefinition = rebuiltBoundary != null
                && TryGetExactStraightWallVerticalExtrusionDefinition(
                    rebuiltBoundary, location, widthFt, bounds,
                    out _, out _, out _, out exactDefinitionReason);
            DiagnosticSink.WriteLine($"IFCSTANDARDWALLGATE wall={element.Id} "
                + $"vp={verticalParametersMatch} ev={exactVerticalBoundary} "
                + $"ap={authoredPlanMatches} rp={exactRectangularBoundary} "
                + $"fragmentedAuthored={hasExactOpenFragmentedAuthoredDefinition} "
                + $"def={exactDefinition}:{exactDefinitionReason}");
        }
        if (!verticalParametersMatch)
            return exactBoundaryDefinition;
        if (hasExactOpenFragmentedAuthoredDefinition)
            return true;

        if (TryResolveStraightWallPlanCentre(
                location, widthFt, bounds, out double nominalCentreX,
                out double nominalCentreY))
        {
            if (rebuiltBoundary == null) return true;
            if (exactVerticalBoundary)
            {
                if (authoredPlanMatches) return true;
                if (exactRectangularBoundary) return true;
                return VerticalBoundaryMatchesNominalRectangle(rebuiltBoundary!, location,
                        widthFt, nominalCentreX, nominalCentreY)
                    || exactBoundaryDefinition;
            }

            // A closed decoded solid or a complete authored plan is authoritative and must not be
            // replaced.
            return (!hasClosedSourceSolid && !authoredPlanMatches)
                || exactBoundaryDefinition;
        }

        return (exactVerticalBoundary
                && (authoredPlanMatches || exactRectangularBoundary))
            || exactBoundaryDefinition;
    }

    /// <summary>True when an open fragmented wall still carries the complete authored footprint at its minimum horizontal cap.</summary>
    internal static bool OpenFragmentedWallMinimumCapMatchesAuthoredPlan(
        GeometryData boundary, LocationCurve location,
        IReadOnlyList<double[]> authoredPlan, IReadOnlyList<double> bounds)
    {
        if (boundary.Faces is not { Count: >= 2 } faces
            || authoredPlan.Count != 4 || bounds.Count < 6
            || location is not { CurveType: "Line", ArcRadius: null }
            || !double.IsFinite(bounds[2])
            || authoredPlan.Any(point => point.Length < 2
                || !double.IsFinite(point[0]) || !double.IsFinite(point[1])))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        var planCoordinates = authoredPlan.Select(point => (
            Along: point[0] * axisX + point[1] * axisY,
            Normal: point[0] * normalX + point[1] * normalY)).ToList();
        double minimumNormal = planCoordinates.Min(value => value.Normal);
        double maximumNormal = planCoordinates.Max(value => value.Normal);
        double scale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices ?? [])
            .SelectMany(point => point.Take(3))
            .Concat(authoredPlan.SelectMany(point => point.Take(2)))
            .Append(bounds[2]).Select(Math.Abs).DefaultIfEmpty(1).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * scale;

        return SideProfileHasSingleContinuousSection(minimumNormal)
            && SideProfileHasSingleContinuousSection(maximumNormal)
            && CapCoversPlanSide(minimumNormal)
            && CapCoversPlanSide(maximumNormal);

        bool SideProfileHasSingleContinuousSection(double targetNormal)
        {
            var sideFaces = faces.Where(face =>
            {
                if (face.OuterVertices is not { Count: >= 3 } ring)
                    return false;
                return ring.All(point => point.Length >= 3
                    && double.IsFinite(point[0])
                    && double.IsFinite(point[1])
                    && double.IsFinite(point[2])
                    && Math.Abs(point[0] * normalX + point[1] * normalY
                        - targetNormal) <= roundoff);
            }).ToList();
            if (sideFaces.Count != 1
                || sideFaces[0].InnerVertices is { Count: > 0 })
                return false;

            var profile = sideFaces[0].OuterVertices!
                .Select(point => (
                    Along: point[0] * axisX + point[1] * axisY,
                    Z: point[2])).ToList();
            var levels = profile.Select(point => point.Z).Order().ToList();
            var distinctLevels = new List<double>();
            foreach (double level in levels)
                if (distinctLevels.Count == 0
                    || level - distinctLevels[^1] > roundoff)
                    distinctLevels.Add(level);
            if (distinctLevels.Count < 2)
                return false;

            // A join/attachment step remains one interval in every open horizontal band.
            for (int levelIndex = 0;
                 levelIndex + 1 < distinctLevels.Count;
                 levelIndex++)
            {
                double lower = distinctLevels[levelIndex];
                double upper = distinctLevels[levelIndex + 1];
                if (upper - lower <= 2 * roundoff)
                    continue;
                double sampleZ = lower + (upper - lower) / 2;
                var intersections = new List<double>();
                for (int index = 0; index < profile.Count; index++)
                {
                    var first = profile[index];
                    var second = profile[(index + 1) % profile.Count];
                    double minimumZ = Math.Min(first.Z, second.Z);
                    double maximumZ = Math.Max(first.Z, second.Z);
                    if (maximumZ - minimumZ <= roundoff
                        || sampleZ <= minimumZ + roundoff
                        || sampleZ >= maximumZ - roundoff)
                        continue;
                    double fraction =
                        (sampleZ - first.Z) / (second.Z - first.Z);
                    intersections.Add(first.Along
                        + fraction * (second.Along - first.Along));
                }
                intersections.Sort();
                var distinctIntersections = new List<double>();
                foreach (double intersection in intersections)
                    if (distinctIntersections.Count == 0
                        || intersection - distinctIntersections[^1] > roundoff)
                        distinctIntersections.Add(intersection);
                if (distinctIntersections.Count != 2)
                    return false;
            }
            return true;
        }

        bool CapCoversPlanSide(double targetNormal)
        {
            var sidePlan = planCoordinates
                .Where(value => Math.Abs(value.Normal - targetNormal) <= roundoff)
                .Select(value => value.Along).ToList();
            if (sidePlan.Count != 2) return false;
            double expectedMinimum = sidePlan.Min();
            double expectedMaximum = sidePlan.Max();
            if (!(expectedMaximum - expectedMinimum > roundoff))
                return false;

            var intervals = new List<(double Minimum, double Maximum)>();
            foreach (GeoFace face in faces)
            {
                if (face.OuterVertices is not { Count: >= 3 } ring)
                    continue;
                for (int index = 0; index < ring.Count; index++)
                {
                    double[] first = ring[index];
                    double[] second = ring[(index + 1) % ring.Count];
                    if (first.Length < 3 || second.Length < 3
                        || !double.IsFinite(first[0]) || !double.IsFinite(first[1])
                        || !double.IsFinite(first[2]) || !double.IsFinite(second[0])
                        || !double.IsFinite(second[1]) || !double.IsFinite(second[2])
                        || Math.Abs(first[2] - bounds[2]) > roundoff
                        || Math.Abs(second[2] - bounds[2]) > roundoff)
                        continue;
                    double firstNormal =
                        first[0] * normalX + first[1] * normalY;
                    double secondNormal =
                        second[0] * normalX + second[1] * normalY;
                    if (Math.Abs(firstNormal - targetNormal) > roundoff
                        || Math.Abs(secondNormal - targetNormal) > roundoff)
                        continue;
                    double firstAlong =
                        first[0] * axisX + first[1] * axisY;
                    double secondAlong =
                        second[0] * axisX + second[1] * axisY;
                    double intervalMinimum = Math.Min(firstAlong, secondAlong);
                    double intervalMaximum = Math.Max(firstAlong, secondAlong);
                    if (intervalMaximum - intervalMinimum > roundoff)
                        intervals.Add((intervalMinimum, intervalMaximum));
                }
            }
            if (intervals.Count == 0
                || intervals.Any(interval =>
                    interval.Minimum < expectedMinimum - roundoff
                    || interval.Maximum > expectedMaximum + roundoff))
                return false;
            intervals.Sort((left, right) =>
                left.Minimum.CompareTo(right.Minimum));
            double covered = expectedMinimum;
            foreach (var interval in intervals)
            {
                if (interval.Maximum <= covered + roundoff)
                    continue;
                if (interval.Minimum > covered + roundoff)
                    return false;
                covered = interval.Maximum;
            }
            return covered >= expectedMaximum - roundoff;
        }
    }

    /// <summary>
    /// Returns an exact uncut vertical wall prism whose two serialized exterior side profiles carry
    /// the same representation-only subdivisions.
    /// </summary>
    internal static bool
        TryGetExactUncutPairedSideProfileVerticalExtrusionDefinition(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out List<double[]> plan,
            out double baseZFt, out double heightFt)
    {
        plan = [];
        baseZFt = heightFt = 0;
        if (boundary.Faces is not { Count: >= 7 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count))
            || !IsExactFacetedShell(faces, solids[0].FaceIndices)
            || bounds.Count < 6
            || location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        double scale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices!)
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Concat(bounds.Take(6))
            .Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 8192 * MachineEpsilon * scale;

        static List<(double[] Point, (long X, long Y, long Z) Key)>
            CleanRing(GeoFace face)
        {
            var result =
                new List<(double[] Point, (long X, long Y, long Z) Key)>();
            foreach (double[] point in face.OuterVertices!)
            {
                var item = (Point: point, Key: IfcPrecisionKeyFeet(point));
                if (result.Count == 0 || result[^1].Key != item.Key)
                    result.Add(item);
            }
            if (result.Count > 1 && result[0].Key == result[^1].Key)
                result.RemoveAt(result.Count - 1);
            return result;
        }

        bool StrictlyWithinSegment(double[] point, double[] first, double[] second)
        {
            double ax = point[0] - first[0];
            double ay = point[1] - first[1];
            double az = point[2] - first[2];
            double bx = second[0] - first[0];
            double by = second[1] - first[1];
            double bz = second[2] - first[2];
            double lengthSquared = bx * bx + by * by + bz * bz;
            if (!(lengthSquared > 0)) return false;
            double projection = ax * bx + ay * by + az * bz;
            if (projection <= 0 || projection >= lengthSquared)
                return false;
            double crossX = ay * bz - az * by;
            double crossY = az * bx - ax * bz;
            double crossZ = ax * by - ay * bx;
            return Math.Sqrt(crossX * crossX + crossY * crossY
                    + crossZ * crossZ)
                <= roundoff * Math.Sqrt(lengthSquared);
        }

        List<(double[] Point, (long X, long Y, long Z) Key)> Simplify(
            IReadOnlyList<(double[] Point,
                (long X, long Y, long Z) Key)> source)
        {
            var result = source.ToList();
            bool changed;
            do
            {
                changed = false;
                if (result.Count <= 4) break;
                for (int index = 0; index < result.Count; index++)
                {
                    if (!StrictlyWithinSegment(
                            result[index].Point,
                            result[(index + result.Count - 1)
                                % result.Count].Point,
                            result[(index + 1) % result.Count].Point))
                        continue;
                    result.RemoveAt(index);
                    changed = true;
                    break;
                }
            }
            while (changed);
            return result;
        }

        var rings = faces.Select(CleanRing).ToList();
        if (rings.Any(ring => ring.Count < 3
                || ring.Select(item => item.Key).Distinct().Count()
                    != ring.Count))
            return false;
        var profileIndices = Enumerable.Range(0, faces.Count)
            .Where(index =>
            {
                var across = rings[index].Select(item =>
                    item.Point[0] * normalX
                    + item.Point[1] * normalY).ToList();
                return across.Max() - across.Min() <= roundoff;
            }).ToList();
        if (profileIndices.Count != 2)
            return false;
        var profiles = profileIndices.Select(index => new
        {
            Index = index,
            Ring = rings[index],
            Plane = rings[index].Average(item =>
                item.Point[0] * normalX + item.Point[1] * normalY),
        }).OrderBy(profile => profile.Plane).ToList();
        int profileVertexCount = profiles[0].Ring.Count;
        if (profileVertexCount < 5
            || profiles[1].Ring.Count != profileVertexCount
            || faces.Count != profileVertexCount + 2
            || Math.Abs((profiles[1].Plane - profiles[0].Plane) - widthFt)
                > roundoff)
            return false;

        var simplified = profiles.Select(profile =>
            Simplify(profile.Ring)).ToList();
        if (simplified.Any(ring => ring.Count != 4)
            || simplified.Sum(ring => ring.Count)
                >= profiles.Sum(profile => profile.Ring.Count))
            return false;

        var profileBounds = new List<(
            double MinimumAlong, double MaximumAlong,
            double MinimumZ, double MaximumZ)>();
        foreach (var ring in simplified)
        {
            var along = ring.Select(item =>
                item.Point[0] * axisX + item.Point[1] * axisY).ToList();
            var levels = ring.Select(item => item.Point[2]).ToList();
            double minimumAlong = along.Min(), maximumAlong = along.Max();
            double minimumZ = levels.Min(), maximumZ = levels.Max();
            if (!(maximumAlong - minimumAlong > roundoff)
                || !(maximumZ - minimumZ > roundoff))
                return false;
            var corners = new HashSet<(int Along, int Z)>();
            for (int index = 0; index < ring.Count; index++)
            {
                int alongSide = Math.Abs(along[index] - minimumAlong)
                        <= roundoff ? -1
                    : Math.Abs(along[index] - maximumAlong)
                        <= roundoff ? 1 : 0;
                int zSide = Math.Abs(levels[index] - minimumZ)
                        <= roundoff ? -1
                    : Math.Abs(levels[index] - maximumZ)
                        <= roundoff ? 1 : 0;
                if (alongSide == 0 || zSide == 0
                    || !corners.Add((alongSide, zSide)))
                    return false;
            }
            if (corners.Count != 4) return false;
            profileBounds.Add((minimumAlong, maximumAlong,
                minimumZ, maximumZ));
        }
        if (Math.Abs(profileBounds[0].MinimumZ
                - profileBounds[1].MinimumZ) > roundoff
            || Math.Abs(profileBounds[0].MaximumZ
                - profileBounds[1].MaximumZ) > roundoff)
            return false;

        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) EdgeKey(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        var profileEdges = profiles.Select(profile =>
            Enumerable.Range(0, profile.Ring.Count).Select(index =>
                EdgeKey(profile.Ring[index].Key,
                    profile.Ring[(index + 1) % profile.Ring.Count].Key))
                .ToDictionary(edge => edge, _ => 0)).ToList();
        foreach (int faceIndex in Enumerable.Range(0, faces.Count)
                     .Except(profileIndices))
        {
            var ring = rings[faceIndex];
            if (ring.Count != 4) return false;
            var byProfile = new[] {
                new List<(double[] Point, (long X, long Y, long Z) Key)>(),
                new List<(double[] Point, (long X, long Y, long Z) Key)>(),
            };
            foreach (var item in ring)
            {
                double plane = item.Point[0] * normalX
                    + item.Point[1] * normalY;
                int profileIndex = Math.Abs(plane - profiles[0].Plane)
                        <= roundoff ? 0
                    : Math.Abs(plane - profiles[1].Plane)
                        <= roundoff ? 1 : -1;
                if (profileIndex < 0) return false;
                byProfile[profileIndex].Add(item);
            }
            if (byProfile.Any(items => items.Count != 2
                    || items.Select(item => item.Key).Distinct().Count() != 2))
                return false;
            var firstEdge = EdgeKey(
                byProfile[0][0].Key, byProfile[0][1].Key);
            var secondEdge = EdgeKey(
                byProfile[1][0].Key, byProfile[1][1].Key);
            if (!profileEdges[0].TryGetValue(firstEdge, out int firstUses)
                || !profileEdges[1].TryGetValue(secondEdge, out int secondUses))
                return false;
            profileEdges[0][firstEdge] = firstUses + 1;
            profileEdges[1][secondEdge] = secondUses + 1;

            var firstZ = byProfile[0].Select(item => item.Key.Z)
                .Order().ToList();
            var secondZ = byProfile[1].Select(item => item.Key.Z)
                .Order().ToList();
            if (!firstZ.SequenceEqual(secondZ)) return false;
            bool horizontal = firstZ[0] == firstZ[1];
            bool vertical = !horizontal
                && byProfile.All(items =>
                    items.Select(item => (item.Key.X, item.Key.Y))
                        .Distinct().Count() == 1);
            if (!horizontal && !vertical) return false;
        }
        if (profileEdges.Any(edges => edges.Values.Any(count => count != 1)))
            return false;

        var bottomPoints = profiles.Select((profile, index) =>
            profile.Ring.Where(item => Math.Abs(item.Point[2]
                    - profileBounds[index].MinimumZ) <= roundoff)
                .GroupBy(item => (item.Key.X, item.Key.Y))
                .Select(group => group.First())
                .OrderBy(item => item.Point[0] * axisX
                    + item.Point[1] * axisY).ToList()).ToList();
        if (bottomPoints.Any(points => points.Count < 2))
            return false;
        var lowInteriorAlong = bottomPoints[0].Skip(1).SkipLast(1)
            .Select(item => item.Point[0] * axisX
                + item.Point[1] * axisY).ToList();
        var highInteriorAlong = bottomPoints[1].Skip(1).SkipLast(1)
            .Select(item => item.Point[0] * axisX
                + item.Point[1] * axisY).ToList();
        if (lowInteriorAlong.Count == 0
            || lowInteriorAlong.Count != highInteriorAlong.Count
            || lowInteriorAlong.Where((value, index) =>
                Math.Abs(value - highInteriorAlong[index]) > roundoff).Any())
            return false;

        var lowBottom = bottomPoints[0];
        var highBottom = bottomPoints[1];
        double joinedEndDifference = profileBounds[0].MaximumAlong
            - profileBounds[1].MaximumAlong;
        if (Math.Abs(joinedEndDifference) <= roundoff)
            return false;
        bool retainMinimumProfileBreakpoint = joinedEndDifference > 0;
        double[] lowEnd =
            [lowBottom[0].Point[0], lowBottom[0].Point[1]];
        double[] lowJoinedEnd =
            [lowBottom[^1].Point[0], lowBottom[^1].Point[1]];
        double[] highEnd =
            [highBottom[0].Point[0], highBottom[0].Point[1]];
        double[] highJoinedEnd =
            [highBottom[^1].Point[0], highBottom[^1].Point[1]];
        plan = retainMinimumProfileBreakpoint
            ?
            [
                lowJoinedEnd, highJoinedEnd, highEnd,
                .. lowBottom.Take(lowBottom.Count - 1).Select(item =>
                    new[] { item.Point[0], item.Point[1] }),
            ]
            :
            [
                lowJoinedEnd,
                .. highBottom.AsEnumerable().Reverse().Select(item =>
                    new[] { item.Point[0], item.Point[1] }),
                lowEnd,
            ];
        var simplifiedPlan = new[]
        {
            lowJoinedEnd, highJoinedEnd, highEnd, lowEnd,
        };
        var planKeys = simplifiedPlan.Select(point =>
            IfcPrecisionKeyFeet([point[0], point[1], 0])).ToList();
        int turn = 0;
        for (int index = 0; index < planKeys.Count; index++)
        {
            var first = planKeys[index];
            var second = planKeys[(index + 1) % planKeys.Count];
            var third = planKeys[(index + 2) % planKeys.Count];
            var cross =
                ((System.Numerics.BigInteger)second.X - first.X)
                * (third.Y - second.Y)
                - ((System.Numerics.BigInteger)second.Y - first.Y)
                * (third.X - second.X);
            if (cross == 0 || turn != 0 && cross.Sign != turn)
            {
                plan = [];
                return false;
            }
            turn = cross.Sign;
        }
        if (!WallPlanMatchesSerializedBounds(plan, bounds))
        {
            plan = [];
            return false;
        }
        baseZFt = profileBounds[0].MinimumZ;
        heightFt = profileBounds[0].MaximumZ - baseZFt;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        if (!(heightFt > 0)
            || Math.Abs(baseZFt - bounds[2]) > toleranceFt
            || Math.Abs(baseZFt + heightFt - bounds[5]) > toleranceFt)
        {
            plan = [];
            baseZFt = heightFt = 0;
            return false;
        }
        return true;
    }

    /// <summary>
    /// Returns an exact boundary-owned vertical prism with an arbitrary straight- wall plan.
    /// </summary>
    internal static bool TryGetExactBoundaryOwnedArbitraryVerticalExtrusionDefinition(
        GeometryData boundary, LocationCurve location, double widthFt,
        IReadOnlyList<double> bounds, out List<double[]> plan,
        out double baseZFt, out double heightFt)
    {
        plan = [];
        baseZFt = heightFt = 0;
        if (boundary.Faces is not { Count: >= 7 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || solids[0].FaceIndices.Count != faces.Count
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count))
            || !IsExactFacetedShell(faces, solids[0].FaceIndices)
            || bounds.Count < 6
            || location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        static List<(double[] Point, (long X, long Y, long Z) Key)> CleanRing(
            GeoFace face)
        {
            var result =
                new List<(double[] Point, (long X, long Y, long Z) Key)>();
            foreach (double[] point in face.OuterVertices!)
            {
                var item = (Point: point, Key: IfcPrecisionKeyFeet(point));
                if (result.Count == 0 || result[^1].Key != item.Key)
                    result.Add(item);
            }
            if (result.Count > 1 && result[0].Key == result[^1].Key)
                result.RemoveAt(result.Count - 1);
            return result;
        }
        static ((long X, long Y) First, (long X, long Y) Second) EdgeKey(
            (long X, long Y) first, (long X, long Y) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var rings = faces.Select(CleanRing).ToList();
        if (rings.Any(ring => ring.Count < 3
                || ring.Select(item => item.Key).Distinct().Count() != ring.Count))
            return false;
        var zLevels = rings.SelectMany(ring => ring).Select(item => item.Key.Z)
            .Distinct().Order().ToList();
        if (zLevels.Count != 2)
            return false;
        long lowZ = zLevels[0], highZ = zLevels[1];
        var lowCaps = rings.Where(ring =>
            ring.All(item => item.Key.Z == lowZ)).ToList();
        var highCaps = rings.Where(ring =>
            ring.All(item => item.Key.Z == highZ)).ToList();
        if (lowCaps.Count != 1 || highCaps.Count != 1)
            return false;
        var lowCap = lowCaps[0];
        var highCap = highCaps[0];
        if (lowCap.Count < 4 || lowCap.Count > 64
            || highCap.Count != lowCap.Count
            || !lowCap.Select(item => (item.Key.X, item.Key.Y)).ToHashSet()
                .SetEquals(highCap.Select(item =>
                    (item.Key.X, item.Key.Y))))
            return false;

        var capEdges = Enumerable.Range(0, lowCap.Count).Select(index =>
            EdgeKey(
                (lowCap[index].Key.X, lowCap[index].Key.Y),
                (lowCap[(index + 1) % lowCap.Count].Key.X,
                    lowCap[(index + 1) % lowCap.Count].Key.Y))).ToList();
        if (capEdges.Distinct().Count() != capEdges.Count)
            return false;
        var sideEdgeCounts = capEdges.ToDictionary(edge => edge, _ => 0);
        foreach (var ring in rings.Where(ring =>
                     !ring.All(item => item.Key.Z == lowZ)
                     && !ring.All(item => item.Key.Z == highZ)))
        {
            var levels = ring.Select(item => item.Key.Z).Distinct().ToList();
            var lowPoints = ring.Where(item => item.Key.Z == lowZ)
                .Select(item => (item.Key.X, item.Key.Y)).Distinct().ToList();
            var highPoints = ring.Where(item => item.Key.Z == highZ)
                .Select(item => (item.Key.X, item.Key.Y)).Distinct().ToList();
            if (ring.Count != 4 || levels.Count != 2
                || lowPoints.Count != 2 || highPoints.Count != 2
                || !lowPoints.ToHashSet().SetEquals(highPoints))
                return false;
            var edge = EdgeKey(lowPoints[0], lowPoints[1]);
            if (!sideEdgeCounts.TryGetValue(edge, out int count))
                return false;
            sideEdgeCounts[edge] = count + 1;
        }
        if (faces.Count != lowCap.Count + 2
            || sideEdgeCounts.Values.Any(count => count != 1))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double normalX = -dy / axisLength, normalY = dx / axisLength;
        var across = lowCap.Select(item =>
            item.Point[0] * normalX + item.Point[1] * normalY).ToList();
        double minimumAcross = across.Min(), maximumAcross = across.Max();
        double scale = Math.Max(1.0, across.Append(widthFt)
            .Concat(bounds.Take(6)).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 8192 * MachineEpsilon * scale;
        if (Math.Abs((maximumAcross - minimumAcross) - widthFt) > roundoff)
            return false;

        plan = lowCap.Select(item =>
            new[] { item.Point[0], item.Point[1] }).ToList();
        if (!WallPlanMatchesSerializedBounds(plan, bounds))
        {
            plan = [];
            return false;
        }
        baseZFt = lowCap.Average(item => item.Point[2]);
        double topZFt = highCap.Average(item => item.Point[2]);
        heightFt = topZFt - baseZFt;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        if (!(heightFt > 0)
            || Math.Abs(baseZFt - bounds[2]) > toleranceFt
            || Math.Abs(topZFt - bounds[5]) > toleranceFt)
        {
            plan = [];
            baseZFt = heightFt = 0;
            return false;
        }
        return true;
    }

    /// <summary>
    /// Returns a complete four-corner vertical wall extrusion only when its two side planes are
    /// parallel to the serialized straight location line and their exact source-space separation
    /// equals the serialized wall width.
    /// </summary>
    internal static bool TryGetExactStraightWallVerticalExtrusionDefinition(
        GeometryData boundary, LocationCurve location, double widthFt,
        IReadOnlyList<double> bounds, out List<double[]> plan,
        out double baseZFt, out double heightFt) =>
        TryGetExactStraightWallVerticalExtrusionDefinition(
            boundary, location, widthFt, bounds, out plan, out baseZFt,
            out heightFt, out _, allowWriterLatticeBounds: false);

    internal static bool TryGetExactStraightWallVerticalExtrusionDefinition(
        GeometryData boundary, LocationCurve location, double widthFt,
        IReadOnlyList<double> bounds, out List<double[]> plan,
        out double baseZFt, out double heightFt, out string rejectionReason,
        bool allowWriterLatticeBounds = false)
    {
        plan = [];
        baseZFt = 0;
        heightFt = 0;
        rejectionReason = "preconditions";
        if (bounds.Count < 6 || !(widthFt > 0) || !double.IsFinite(widthFt)
            || location is not { CurveType: "Line", ArcRadius: null })
            return false;
        if (!IsExactVerticalExtrusionBoundary(boundary))
        {
            if (TryGetNominalStraightWallPrismWithRedundantBoundaryFaces(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string redundantBoundaryRejectionReason))
            {
                rejectionReason = redundantBoundaryRejectionReason
                    == "exact-boundary-owned-span"
                    ? "exact-boundary-owned-redundant-faces"
                    : "exact-redundant-boundary-faces";
                return true;
            }
            if (TryGetExactStraightWallPrismWithSubdividedVerticalProfileEdge(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt))
            {
                rejectionReason =
                    "exact-subdivided-vertical-profile-edge";
                return true;
            }
            if (TryGetAxisAlignedWriterLatticeWallPrismWithRedundantBoundaryFaces(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string writerLatticeRejectionReason))
            {
                rejectionReason =
                    "exact-writer-lattice-redundant-boundary-faces";
                return true;
            }
            if (TryGetNominalStraightWallPrismWithCollinearBoundarySubdivision(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string subdivisionRejectionReason))
            {
                rejectionReason = "exact-collinear-boundary-subdivision";
                return true;
            }
            rejectionReason = "preconditions"
                + $"-redundant-{redundantBoundaryRejectionReason}"
                + $"-writer-lattice-{writerLatticeRejectionReason}"
                + $"-subdivision-{subdivisionRejectionReason}";
            return false;
        }

        var keyedFaces = boundary.Faces.Select(face => face.OuterVertices!
            .Select(point => (Point: point, Key: IfcPrecisionKeyFeet(point)))
            .ToList()).ToList();
        long lowZ = keyedFaces.SelectMany(face => face).Min(item => item.Key.Z);
        long highZ = keyedFaces.SelectMany(face => face).Max(item => item.Key.Z);
        var lowCaps = keyedFaces.Where(face =>
            face.Select(item => item.Key.Z).Distinct().SequenceEqual([lowZ])).ToList();
        var highCaps = keyedFaces.Where(face =>
            face.Select(item => item.Key.Z).Distinct().SequenceEqual([highZ])).ToList();
        if (lowCaps.Count != 1 || highCaps.Count != 1)
        {
            if (TryGetNominalStraightWallPrismWithRedundantBoundaryFaces(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string redundantBoundaryRejectionReason))
            {
                rejectionReason = redundantBoundaryRejectionReason
                    == "exact-boundary-owned-span"
                    ? "exact-boundary-owned-redundant-faces"
                    : "exact-redundant-boundary-faces";
                return true;
            }
            if (TryGetAxisAlignedWriterLatticeWallPrismWithRedundantBoundaryFaces(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string writerLatticeRejectionReason))
            {
                rejectionReason =
                    "exact-writer-lattice-redundant-boundary-faces";
                return true;
            }
            rejectionReason = $"cap-count-{lowCaps.Count}-{highCaps.Count}"
                + $"-redundant-{redundantBoundaryRejectionReason}"
                + $"-writer-lattice-{writerLatticeRejectionReason}";
            return false;
        }

        static List<(double[] Point, (long X, long Y, long Z) Key)> CleanCap(
            IEnumerable<(double[] Point, (long X, long Y, long Z) Key)> source)
        {
            var result = new List<(double[] Point, (long X, long Y, long Z) Key)>();
            foreach (var item in source)
                if (result.Count == 0 || result[^1].Key != item.Key) result.Add(item);
            if (result.Count > 1 && result[0].Key == result[^1].Key)
                result.RemoveAt(result.Count - 1);
            return result;
        }

        var lowCap = CleanCap(lowCaps[0]);
        var highCap = CleanCap(highCaps[0]);
        if (lowCap.Count != 4 || highCap.Count != lowCap.Count
            || lowCap.Select(item => (item.Key.X, item.Key.Y)).Distinct().Count()
                != lowCap.Count
            || !lowCap.Select(item => (item.Key.X, item.Key.Y)).ToHashSet().SetEquals(
                highCap.Select(item => (item.Key.X, item.Key.Y))))
        {
            if (TryGetExactStraightWallPrismWithCollinearBoundarySubdivisions(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string exactSubdivisionRejectionReason))
            {
                rejectionReason =
                    "exact-collinear-boundary-subdivision";
                return true;
            }
            if (TryGetNominalStraightWallPrismWithCollinearBoundarySubdivision(
                    boundary, location, widthFt, bounds,
                    out plan, out baseZFt, out heightFt,
                    out string subdivisionRejectionReason))
            {
                rejectionReason = "exact-collinear-boundary-subdivision";
                return true;
            }
            rejectionReason = $"cap-topology-{lowCap.Count}-{highCap.Count}"
                + $"-exact-subdivision-{exactSubdivisionRejectionReason}"
                + $"-subdivision-{subdivisionRejectionReason}";
            return false;
        }

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
        {
            rejectionReason = "axis";
            return false;
        }
        double normalX = -dy / axisLength, normalY = dx / axisLength;
        var across = lowCap.Select(item =>
            item.Point[0] * normalX + item.Point[1] * normalY).ToList();
        double minimumAcross = across.Min(), maximumAcross = across.Max();
        double scale = Math.Max(1.0, across.Append(widthFt).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * scale;
        if (Math.Abs((maximumAcross - minimumAcross) - widthFt) > roundoff
            || across.Count(value => Math.Abs(value - minimumAcross) <= roundoff) != 2
            || across.Count(value => Math.Abs(value - maximumAcross) <= roundoff) != 2)
        {
            rejectionReason = "width-side-planes";
            return false;
        }

        plan = lowCap.Select(item => new[] { item.Point[0], item.Point[1] }).ToList();
        baseZFt = lowCap.Min(item => item.Point[2]);
        double topZFt = highCap.Max(item => item.Point[2]);
        heightFt = topZFt - baseZFt;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        bool sourcePlanMatches = WallPlanMatchesSerializedBounds(plan, bounds);
        bool writerLatticePlanMatches = allowWriterLatticeBounds
            && WallPlanMatchesSerializedBoundsAtIfcPrecision(plan, bounds);
        if (!(heightFt > 0) || !double.IsFinite(baseZFt) || !double.IsFinite(heightFt)
            || Math.Abs(baseZFt - bounds[2]) > toleranceFt
            || Math.Abs(topZFt - bounds[5]) > toleranceFt
            || (!sourcePlanMatches && !writerLatticePlanMatches))
        {
            plan = [];
            baseZFt = 0;
            heightFt = 0;
            rejectionReason = "serialized-bounds";
            return false;
        }
        if (!sourcePlanMatches)
        {
            plan = lowCap.Select(item => new[]
            {
                item.Key.X * IfcGeometryPrecisionMetres / FeetToMetres,
                item.Key.Y * IfcGeometryPrecisionMetres / FeetToMetres,
            }).ToList();
            rejectionReason = "exact-writer-lattice-bounds";
        }
        else
        {
            rejectionReason = "exact";
        }
        return true;
    }

    private static bool IsExactRedundantWallDefinitionReason(string reason) =>
        reason is "exact-redundant-boundary-faces"
            or "exact-boundary-owned-redundant-faces"
            or "exact-writer-lattice-redundant-boundary-faces";

    /// <summary>
    /// Recognizes the writer-lattice quotient of an axis-aligned nominal wall prism when the source
    /// doubles differ inside one coordinate bin.
    /// </summary>
    private static bool
        TryGetAxisAlignedWriterLatticeWallPrismWithRedundantBoundaryFaces(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out List<double[]> plan,
            out double baseZFt, out double heightFt,
            out string rejectionReason)
    {
        plan = [];
        baseZFt = heightFt = 0;
        rejectionReason = "preconditions";
        if (boundary.Faces is not { Count: >= 6 } faces
            || bounds.Count < 6
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
            || !TryResolveStraightWallPlanCentre(
                location, widthFt, bounds, out double centreXFt,
                out double centreYFt))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double directionScale = Math.Max(1.0, Math.Max(Math.Abs(dx), Math.Abs(dy)));
        const double MachineEpsilon = 2.2204460492503131e-16;
        double directionRoundoff = 4096 * MachineEpsilon * directionScale;
        bool alongX = Math.Abs(dy) <= directionRoundoff
            && Math.Abs(dx) > directionRoundoff;
        bool alongY = Math.Abs(dx) <= directionRoundoff
            && Math.Abs(dy) > directionRoundoff;
        rejectionReason = "axis-alignment";
        if (!alongX && !alongY)
            return false;

        double lengthFt = alongX ? Math.Abs(dx) : Math.Abs(dy);
        double axisX = alongX ? Math.Sign(dx) : 0;
        double axisY = alongY ? Math.Sign(dy) : 0;
        double normalX = -axisY, normalY = axisX;
        double halfLength = lengthFt / 2;
        double halfWidth = widthFt / 2;
        List<double[]> nominalPlan =
        [
            [centreXFt - axisX * halfLength - normalX * halfWidth,
             centreYFt - axisY * halfLength - normalY * halfWidth],
            [centreXFt + axisX * halfLength - normalX * halfWidth,
             centreYFt + axisY * halfLength - normalY * halfWidth],
            [centreXFt + axisX * halfLength + normalX * halfWidth,
             centreYFt + axisY * halfLength + normalY * halfWidth],
            [centreXFt - axisX * halfLength + normalX * halfWidth,
             centreYFt - axisY * halfLength + normalY * halfWidth],
        ];
        rejectionReason = "serialized-plan";
        if (!WallPlanMatchesSerializedBoundsAtIfcPrecision(nominalPlan, bounds))
            return false;

        var nominalKeys = nominalPlan.Select(point =>
            IfcPrecisionKeyFeet([point[0], point[1], 0])).ToList();
        long Along((long X, long Y, long Z) key) => alongX
            ? (axisX > 0 ? key.X : -key.X)
            : (axisY > 0 ? key.Y : -key.Y);
        long Normal((long X, long Y, long Z) key) => alongX
            ? (normalY > 0 ? key.Y : -key.Y)
            : (normalX > 0 ? key.X : -key.X);
        var alongBins = nominalKeys.Select(Along).Distinct().Order().ToList();
        var normalBins = nominalKeys.Select(Normal).Distinct().Order().ToList();
        rejectionReason = "plan-lattice";
        if (alongBins.Count != 2 || normalBins.Count != 2
            || nominalKeys.Select(key => (Along(key), Normal(key)))
                .Distinct().Count() != 4)
            return false;

        double precisionFt = IfcGeometryPrecisionMetres / FeetToMetres;
        double[] Point(long along, long normal, long z) =>
        [
            (along * axisX + normal * normalX) * precisionFt,
            (along * axisY + normal * normalY) * precisionFt,
            z * precisionFt,
        ];
        double[] Snap(double[] point)
        {
            var key = IfcPrecisionKeyFeet(point);
            return
            [
                key.X * precisionFt,
                key.Y * precisionFt,
                key.Z * precisionFt,
            ];
        }

        long lowZ = IfcPrecisionKeyFeet([0, 0, bounds[2]]).Z;
        long highZ = IfcPrecisionKeyFeet([0, 0, bounds[5]]).Z;
        rejectionReason = "vertical-lattice";
        if (highZ <= lowZ)
            return false;
        long minimumAlong = alongBins[0], maximumAlong = alongBins[1];
        long minimumNormal = normalBins[0], maximumNormal = normalBins[1];
        double centreAlong = (minimumAlong + maximumAlong) * precisionFt / 2;
        double centreNormal = (minimumNormal + maximumNormal) * precisionFt / 2;
        var quantizedLocation = new LocationCurve
        {
            CurveType = "Line",
            StartPoint =
            [
                centreAlong * axisX + centreNormal * normalX
                    - (maximumAlong - minimumAlong) * precisionFt * axisX / 2,
                centreAlong * axisY + centreNormal * normalY
                    - (maximumAlong - minimumAlong) * precisionFt * axisY / 2,
                location.StartPoint[2],
            ],
            EndPoint =
            [
                centreAlong * axisX + centreNormal * normalX
                    + (maximumAlong - minimumAlong) * precisionFt * axisX / 2,
                centreAlong * axisY + centreNormal * normalY
                    + (maximumAlong - minimumAlong) * precisionFt * axisY / 2,
                location.EndPoint[2],
            ],
        };
        double quantizedWidthFt =
            (maximumNormal - minimumNormal) * precisionFt;
        double[][] quantizedCorners =
        [
            Point(minimumAlong, minimumNormal, lowZ),
            Point(maximumAlong, minimumNormal, lowZ),
            Point(maximumAlong, maximumNormal, lowZ),
            Point(minimumAlong, maximumNormal, lowZ),
        ];
        double[] quantizedBounds =
        [
            quantizedCorners.Min(point => point[0]),
            quantizedCorners.Min(point => point[1]),
            lowZ * precisionFt,
            quantizedCorners.Max(point => point[0]),
            quantizedCorners.Max(point => point[1]),
            highZ * precisionFt,
        ];
        var quantizedBoundary = new GeometryData
        {
            Faces = faces.Select(face => new GeoFace
            {
                OuterVertices = face.OuterVertices!.Select(Snap).ToList(),
            }).ToList(),
        };
        rejectionReason = "quantized-boundary";
        if (!TryGetNominalStraightWallPrismWithRedundantBoundaryFaces(
                quantizedBoundary, quantizedLocation, quantizedWidthFt,
                quantizedBounds, out plan, out baseZFt, out heightFt,
                out string quantizedReason)
            || quantizedReason != "exact")
        {
            plan = [];
            baseZFt = heightFt = 0;
            return false;
        }

        rejectionReason = "exact";
        return true;
    }

    /// <summary>
    /// Recognizes a nominal straight-wall prism whose decoded BRep contains redundant coplanar
    /// boundary facets.
    /// </summary>
    private static bool TryGetNominalStraightWallPrismWithRedundantBoundaryFaces(
        GeometryData boundary, LocationCurve location, double widthFt,
        IReadOnlyList<double> bounds, out List<double[]> plan,
        out double baseZFt, out double heightFt, out string rejectionReason)
    {
        plan = [];
        baseZFt = heightFt = 0;
        rejectionReason = "preconditions";
        if (boundary.Faces is not { Count: >= 6 } faces
            || bounds.Count < 6
            || !(widthFt > 0) || !double.IsFinite(widthFt))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double lengthFt = Math.Sqrt(dx * dx + dy * dy);
        if (!(lengthFt > 0) || !double.IsFinite(lengthFt)
            || !double.IsFinite(bounds[2]) || !double.IsFinite(bounds[5])
            || !(bounds[5] > bounds[2]))
            return false;
        double axisX = dx / lengthFt, axisY = dy / lengthFt;
        double normalX = -axisY, normalY = axisX;
        var boundaryPoints = faces
            .SelectMany(face => face.OuterVertices ?? []).ToList();
        rejectionReason = "boundary-points";
        if (boundaryPoints.Count == 0
            || boundaryPoints.Any(point => point.Length < 3
                || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;
        double minimumZ = bounds[2], maximumZ = bounds[5];
        double scale = Math.Max(1.0, boundaryPoints
            .SelectMany(point => point.Take(3)).Append(widthFt)
            .Append(lengthFt).Append(minimumZ).Append(maximumZ)
            .Select(Math.Abs).DefaultIfEmpty(1).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * scale;
        double minimumAlong;
        double maximumAlong;
        double minimumNormal;
        double maximumNormal;
        bool usesBoundaryOwnedSpan = false;
        if (TryResolveStraightWallPlanCentre(
                location, widthFt, bounds,
                out double centreXFt, out double centreYFt))
        {
            double centreAlong = centreXFt * axisX + centreYFt * axisY;
            double centreNormal = centreXFt * normalX + centreYFt * normalY;
            minimumAlong = centreAlong - lengthFt / 2;
            maximumAlong = centreAlong + lengthFt / 2;
            minimumNormal = centreNormal - widthFt / 2;
            maximumNormal = centreNormal + widthFt / 2;
        }
        else
        {
            usesBoundaryOwnedSpan = true;
            // Joined walls can retain the serialized location direction and compound width while
            // their exact post-join boundary owns a shorter or longer span.
            var projectedBoundary = boundaryPoints.Select(point => (
                Along: point[0] * axisX + point[1] * axisY,
                Normal: point[0] * normalX + point[1] * normalY)).ToList();
            minimumAlong = projectedBoundary.Min(value => value.Along);
            maximumAlong = projectedBoundary.Max(value => value.Along);
            minimumNormal = projectedBoundary.Min(value => value.Normal);
            maximumNormal = projectedBoundary.Max(value => value.Normal);
            rejectionReason = "boundary-owned-plan";
            if (!(maximumAlong - minimumAlong > roundoff)
                || Math.Abs((maximumNormal - minimumNormal) - widthFt)
                    > roundoff)
                return false;
        }

        double[] Point(double along, double normal, double z) =>
        [
            along * axisX + normal * normalX,
            along * axisY + normal * normalY,
            z,
        ];
        double[][] corners =
        [
            Point(minimumAlong, minimumNormal, minimumZ),
            Point(maximumAlong, minimumNormal, minimumZ),
            Point(maximumAlong, maximumNormal, minimumZ),
            Point(minimumAlong, maximumNormal, minimumZ),
            Point(minimumAlong, minimumNormal, maximumZ),
            Point(maximumAlong, minimumNormal, maximumZ),
            Point(maximumAlong, maximumNormal, maximumZ),
            Point(minimumAlong, maximumNormal, maximumZ),
        ];
        var areaByPlane = new double[6];
        var edgeCounts = new Dictionary<
            ((long X, long Y, long Z) First, (long X, long Y, long Z) Second), int>();

        static ((long X, long Y, long Z) First, (long X, long Y, long Z) Second)
            EdgeKey((long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);
        static double PolygonArea(IReadOnlyList<(double First, double Second)> polygon)
        {
            double twiceArea = 0;
            for (int index = 0; index < polygon.Count; index++)
            {
                var first = polygon[index];
                var second = polygon[(index + 1) % polygon.Count];
                twiceArea += first.First * second.Second - second.First * first.Second;
            }
            return Math.Abs(twiceArea) / 2;
        }

        foreach (GeoFace face in faces)
        {
            rejectionReason = "face-validity";
            if (face.OuterVertices is not { Count: >= 3 } vertices
                || face.InnerVertices is { Count: > 0 }
                || vertices.Any(point => point.Length < 3
                    || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2]))
                || !FaceCanEmitAtIfcPrecision(face))
                return false;
            var projected = vertices.Select(point => (
                Along: point[0] * axisX + point[1] * axisY,
                Normal: point[0] * normalX + point[1] * normalY,
                Z: point[2])).ToList();
            if (projected.Any(value =>
                    value.Along < minimumAlong - roundoff
                    || value.Along > maximumAlong + roundoff
                    || value.Normal < minimumNormal - roundoff
                    || value.Normal > maximumNormal + roundoff
                    || value.Z < minimumZ - roundoff
                    || value.Z > maximumZ + roundoff))
            {
                rejectionReason = "outside-prism";
                return false;
            }
            bool[] planes =
            [
                projected.All(value => Math.Abs(value.Z - minimumZ) <= roundoff),
                projected.All(value => Math.Abs(value.Z - maximumZ) <= roundoff),
                projected.All(value => Math.Abs(value.Along - minimumAlong) <= roundoff),
                projected.All(value => Math.Abs(value.Along - maximumAlong) <= roundoff),
                projected.All(value => Math.Abs(value.Normal - minimumNormal) <= roundoff),
                projected.All(value => Math.Abs(value.Normal - maximumNormal) <= roundoff),
            ];
            if (planes.Count(value => value) != 1)
            {
                rejectionReason = "boundary-plane";
                return false;
            }
            int planeIndex = Array.IndexOf(planes, true);
            var ringKeys = new List<(long X, long Y, long Z)>();
            foreach (var key in vertices.Select(IfcPrecisionKeyFeet))
                if (ringKeys.Count == 0 || ringKeys[^1] != key) ringKeys.Add(key);
            if (ringKeys.Count > 1 && ringKeys[0] == ringKeys[^1])
                ringKeys.RemoveAt(ringKeys.Count - 1);
            if (ringKeys.Count < 3 || ringKeys.Distinct().Count() != ringKeys.Count)
            {
                rejectionReason = "face-ring";
                return false;
            }
            for (int index = 0; index < ringKeys.Count; index++)
            {
                var edge = EdgeKey(ringKeys[index], ringKeys[(index + 1) % ringKeys.Count]);
                edgeCounts[edge] = edgeCounts.GetValueOrDefault(edge) + 1;
            }
            areaByPlane[planeIndex] += planeIndex switch
            {
                0 or 1 => PolygonArea(projected.Select(value =>
                    (value.Along, value.Normal)).ToList()),
                2 or 3 => PolygonArea(projected.Select(value =>
                    (value.Normal, value.Z)).ToList()),
                _ => PolygonArea(projected.Select(value =>
                    (value.Along, value.Z)).ToList()),
            };
        }
        if (edgeCounts.Values.Any(count => count != 2))
        {
            rejectionReason = "edge-incidence";
            return false;
        }
        double length = maximumAlong - minimumAlong;
        double width = maximumNormal - minimumNormal;
        double height = maximumZ - minimumZ;
        double[] expectedAreas =
        [
            length * width, length * width,
            width * height, width * height,
            length * height, length * height,
        ];
        for (int index = 0; index < areaByPlane.Length; index++)
        {
            double firstExtent = index < 2 ? length : index < 4 ? width : length;
            double secondExtent = index < 2 ? width : height;
            double areaTolerance = 2 * (firstExtent + secondExtent) *
                (IfcDeclaredPrecisionMetres / FeetToMetres);
            if (!(areaByPlane[index] > 0)
                || Math.Abs(areaByPlane[index] - expectedAreas[index]) > areaTolerance)
            {
                rejectionReason = $"plane-area-{index}";
                return false;
            }
        }

        plan =
        [
            new[] { corners[0][0], corners[0][1] },
            new[] { corners[1][0], corners[1][1] },
            new[] { corners[2][0], corners[2][1] },
            new[] { corners[3][0], corners[3][1] },
        ];
        if (!WallPlanMatchesSerializedBounds(plan, bounds))
        {
            plan = [];
            rejectionReason = "serialized-bounds";
            return false;
        }
        baseZFt = minimumZ;
        heightFt = maximumZ - minimumZ;
        rejectionReason = usesBoundaryOwnedSpan
            ? "exact-boundary-owned-span" : "exact";
        return true;
    }

    /// <summary>
    /// Recognizes an exact four-corner vertical wall prism whose two exterior profiles retain one
    /// or two collinear join vertices on the same vertical end.
    /// </summary>
    private static bool
        TryGetExactStraightWallPrismWithSubdividedVerticalProfileEdge(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out List<double[]> plan,
            out double baseZFt, out double heightFt)
    {
        plan = [];
        baseZFt = heightFt = 0;
        if (boundary.Faces is not { Count: 7 or 8 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count))
            || !IsExactFacetedShell(faces, solids[0].FaceIndices)
            || bounds.Count < 6
            || location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;
        int profileVertexCount = faces.Count - 2;
        if (faces.Count(face =>
                face.OuterVertices?.Count == profileVertexCount) != 2
            || faces.Count(face => face.OuterVertices is { Count: 4 })
                != profileVertexCount)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        double scale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices!)
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * scale;

        static List<(double[] Point, (long X, long Y, long Z) Key)>
            CleanRing(GeoFace face)
        {
            var result =
                new List<(double[] Point, (long X, long Y, long Z) Key)>();
            foreach (double[] point in face.OuterVertices!)
            {
                var item = (Point: point, Key: IfcPrecisionKeyFeet(point));
                if (result.Count == 0 || result[^1].Key != item.Key)
                    result.Add(item);
            }
            if (result.Count > 1 && result[0].Key == result[^1].Key)
                result.RemoveAt(result.Count - 1);
            return result;
        }
        static bool StrictlyWithinSegment(
            (long X, long Y, long Z) point,
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second)
        {
            var dx = (System.Numerics.BigInteger)second.X - first.X;
            var dy = (System.Numerics.BigInteger)second.Y - first.Y;
            var dz = (System.Numerics.BigInteger)second.Z - first.Z;
            var px = (System.Numerics.BigInteger)point.X - first.X;
            var py = (System.Numerics.BigInteger)point.Y - first.Y;
            var pz = (System.Numerics.BigInteger)point.Z - first.Z;
            if (dy * pz - dz * py != 0
                || dz * px - dx * pz != 0
                || dx * py - dy * px != 0)
                return false;
            var projection = px * dx + py * dy + pz * dz;
            var lengthSquared = dx * dx + dy * dy + dz * dz;
            return projection > 0 && projection < lengthSquared;
        }
        static ((int End, long Z) First, (int End, long Z) Second)
            EdgeKey((int End, long Z) first, (int End, long Z) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var profileIndices = Enumerable.Range(0, faces.Count)
            .Where(index =>
            {
                var ring = faces[index].OuterVertices;
                if (ring == null || ring.Count != profileVertexCount)
                    return false;
                var projections = ring.Select(point =>
                    point[0] * normalX + point[1] * normalY).ToList();
                return projections.Max() - projections.Min() <= roundoff;
            }).ToList();
        if (profileIndices.Count != 2)
            return false;
        var profiles = profileIndices.Select(index => new
        {
            Index = index,
            Ring = CleanRing(faces[index]),
            Normal = faces[index].OuterVertices!.Average(point =>
                point[0] * normalX + point[1] * normalY),
        }).OrderBy(profile => profile.Normal).ToList();
        if (profiles.Any(profile =>
                profile.Ring.Count != profileVertexCount
                || profile.Ring.Select(item => item.Key).Distinct().Count()
                    != profileVertexCount)
            || Math.Abs((profiles[1].Normal - profiles[0].Normal) - widthFt)
                > roundoff)
            return false;

        var simplifiedProfiles =
            new List<List<(double[] Point, (long X, long Y, long Z) Key)>>();
        var removedProfiles =
            new List<List<(double[] Point, (long X, long Y, long Z) Key)>>();
        var endpointKeys = new List<List<(long X, long Y)>>();
        var profileEdgeSets = new List<HashSet<
            ((int End, long Z) First, (int End, long Z) Second)>>();
        var splitEnds = new List<int>();
        foreach (var profile in profiles)
        {
            var simplified = profile.Ring.ToList();
            var removed =
                new List<(double[] Point, (long X, long Y, long Z) Key)>();
            bool changed;
            do
            {
                changed = false;
                for (int index = 0; index < simplified.Count; index++)
                {
                    if (!StrictlyWithinSegment(
                            simplified[index].Key,
                            simplified[(index + simplified.Count - 1)
                                % simplified.Count].Key,
                            simplified[(index + 1) % simplified.Count].Key))
                        continue;
                    removed.Add(simplified[index]);
                    simplified.RemoveAt(index);
                    changed = true;
                    break;
                }
            }
            while (changed);
            if (simplified.Count != 4
                || removed.Count != profileVertexCount - 4)
                return false;

            var xyKeys = simplified
                .Select(item => (item.Key.X, item.Key.Y))
                .Distinct()
                .OrderBy(key =>
                {
                    double xFt = key.X * IfcGeometryPrecisionMetres
                        / FeetToMetres;
                    double yFt = key.Y * IfcGeometryPrecisionMetres
                        / FeetToMetres;
                    return xFt * axisX + yFt * axisY;
                }).ToList();
            var zKeys = simplified.Select(item => item.Key.Z)
                .Distinct().Order().ToList();
            if (xyKeys.Count != 2 || zKeys.Count != 2
                || simplified.Select(item =>
                        ((item.Key.X, item.Key.Y), item.Key.Z))
                    .Distinct().Count() != 4)
                return false;

            int splitEnd = -1;
            for (int end = 0; end < xyKeys.Count; end++)
            {
                var first = (X: xyKeys[end].X, Y: xyKeys[end].Y,
                    Z: zKeys[0]);
                var second = (X: xyKeys[end].X, Y: xyKeys[end].Y,
                    Z: zKeys[1]);
                if (removed.All(item =>
                        StrictlyWithinSegment(item.Key, first, second)))
                    splitEnd = splitEnd < 0 ? end : -2;
            }
            if (splitEnd < 0)
                return false;

            (int End, long Z)? Label(
                (long X, long Y, long Z) key)
            {
                int end = xyKeys.FindIndex(value =>
                    value == (key.X, key.Y));
                return end >= 0 ? (end, key.Z) : null;
            }
            var edges = new HashSet<
                ((int End, long Z) First, (int End, long Z) Second)>();
            for (int index = 0; index < profile.Ring.Count; index++)
            {
                var first = Label(profile.Ring[index].Key);
                var second = Label(
                    profile.Ring[(index + 1) % profile.Ring.Count].Key);
                if (first == null || second == null
                    || first == second
                    || !edges.Add(EdgeKey(first.Value, second.Value)))
                    return false;
            }
            if (edges.Count != profileVertexCount)
                return false;

            simplifiedProfiles.Add(simplified);
            removedProfiles.Add(removed);
            endpointKeys.Add(xyKeys);
            profileEdgeSets.Add(edges);
            splitEnds.Add(splitEnd);
        }
        if (splitEnds[0] != splitEnds[1]
            || !removedProfiles[0].Select(item => item.Key.Z)
                .Order().SequenceEqual(removedProfiles[1]
                    .Select(item => item.Key.Z).Order())
            || !profileEdgeSets[0].SetEquals(profileEdgeSets[1]))
            return false;

        var connectorUses = profileEdgeSets[0].ToDictionary(edge => edge, _ => 0);
        foreach (int faceIndex in Enumerable.Range(0, faces.Count)
                     .Except(profileIndices))
        {
            var ring = CleanRing(faces[faceIndex]);
            if (ring.Count != 4
                || ring.Select(item => item.Key).Distinct().Count() != 4)
                return false;
            var labelsBySide = new[] {
                new List<(int End, long Z)>(),
                new List<(int End, long Z)>(),
            };
            foreach (var item in ring)
            {
                double normal = item.Point[0] * normalX
                    + item.Point[1] * normalY;
                int side = Math.Abs(normal - profiles[0].Normal) <= roundoff
                    ? 0
                    : Math.Abs(normal - profiles[1].Normal) <= roundoff
                        ? 1 : -1;
                if (side < 0)
                    return false;
                int end = endpointKeys[side].FindIndex(value =>
                    value == (item.Key.X, item.Key.Y));
                if (end < 0)
                    return false;
                labelsBySide[side].Add((end, item.Key.Z));
            }
            if (labelsBySide.Any(labels =>
                    labels.Count != 2 || labels.Distinct().Count() != 2)
                || !labelsBySide[0].ToHashSet()
                    .SetEquals(labelsBySide[1]))
                return false;
            var edge = EdgeKey(labelsBySide[0][0], labelsBySide[0][1]);
            if (!connectorUses.TryGetValue(edge, out int count))
                return false;
            connectorUses[edge] = count + 1;
        }
        if (connectorUses.Values.Any(count => count != 1))
            return false;

        var lowEndpoints = endpointKeys[0].Select(key =>
            simplifiedProfiles[0].First(item =>
                (item.Key.X, item.Key.Y) == key).Point).ToList();
        var highEndpoints = endpointKeys[1].Select(key =>
            simplifiedProfiles[1].First(item =>
                (item.Key.X, item.Key.Y) == key).Point).ToList();
        plan =
        [
            [lowEndpoints[0][0], lowEndpoints[0][1]],
            [lowEndpoints[1][0], lowEndpoints[1][1]],
            [highEndpoints[1][0], highEndpoints[1][1]],
            [highEndpoints[0][0], highEndpoints[0][1]],
        ];
        var planKeys = plan.Select(point =>
            IfcPrecisionKeyFeet([point[0], point[1], 0])).ToList();
        int turn = 0;
        for (int index = 0; index < planKeys.Count; index++)
        {
            var first = planKeys[index];
            var second = planKeys[(index + 1) % planKeys.Count];
            var third = planKeys[(index + 2) % planKeys.Count];
            var cross =
                ((System.Numerics.BigInteger)second.X - first.X)
                * (third.Y - second.Y)
                - ((System.Numerics.BigInteger)second.Y - first.Y)
                * (third.X - second.X);
            if (cross == 0
                || (turn != 0 && cross.Sign != turn))
            {
                plan = [];
                return false;
            }
            turn = cross.Sign;
        }

        var zLevels = simplifiedProfiles.SelectMany(profile => profile)
            .Select(item => item.Key.Z).Distinct().Order().ToList();
        if (zLevels.Count != 2)
        {
            plan = [];
            return false;
        }
        baseZFt = zLevels[0] * IfcGeometryPrecisionMetres / FeetToMetres;
        double topZFt =
            zLevels[1] * IfcGeometryPrecisionMetres / FeetToMetres;
        heightFt = topZFt - baseZFt;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        if (!(heightFt > 0)
            || Math.Abs(baseZFt - bounds[2]) > toleranceFt
            || Math.Abs(topZFt - bounds[5]) > toleranceFt
            || !WallPlanMatchesSerializedBoundsAtIfcPrecision(plan, bounds))
        {
            plan = [];
            baseZFt = heightFt = 0;
            return false;
        }
        return true;
    }

    /// <summary>
    /// Recognizes an exact arbitrary four-corner straight-wall prism whose caps preserve one or
    /// more path-join vertices that are collinear within the declared IFC writer lattice.
    /// </summary>
    private static bool
        TryGetExactStraightWallPrismWithCollinearBoundarySubdivisions(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out List<double[]> plan,
            out double baseZFt, out double heightFt,
            out string rejectionReason)
    {
        plan = [];
        baseZFt = heightFt = 0;
        rejectionReason = "preconditions";
        if (boundary.Faces is not { Count: >= 7 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count))
            || !IsExactFacetedShell(faces, solids[0].FaceIndices)
            || bounds.Count < 6
            || location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        static List<(double[] Point, (long X, long Y, long Z) Key)> CleanRing(
            GeoFace face)
        {
            var result =
                new List<(double[] Point, (long X, long Y, long Z) Key)>();
            foreach (double[] point in face.OuterVertices!)
            {
                var item = (Point: point, Key: IfcPrecisionKeyFeet(point));
                if (result.Count == 0 || result[^1].Key != item.Key)
                    result.Add(item);
            }
            if (result.Count > 1 && result[0].Key == result[^1].Key)
                result.RemoveAt(result.Count - 1);
            return result;
        }
        static bool StrictlyWithinOneIfcLatticeOfSegment(
            (long X, long Y, long Z) point,
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second)
        {
            var dx = (System.Numerics.BigInteger)second.X - first.X;
            var dy = (System.Numerics.BigInteger)second.Y - first.Y;
            var px = (System.Numerics.BigInteger)point.X - first.X;
            var py = (System.Numerics.BigInteger)point.Y - first.Y;
            var latticeCrossTolerance = System.Numerics.BigInteger.Max(
                System.Numerics.BigInteger.Abs(dx),
                System.Numerics.BigInteger.Abs(dy));
            if (latticeCrossTolerance == 0
                || System.Numerics.BigInteger.Abs(dx * py - dy * px)
                    > latticeCrossTolerance)
                return false;
            var projection = px * dx + py * dy;
            var lengthSquared = dx * dx + dy * dy;
            return projection > 0 && projection < lengthSquared;
        }
        static ((long X, long Y) First, (long X, long Y) Second) EdgeKey(
            (long X, long Y) first, (long X, long Y) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var rings = faces.Select(CleanRing).ToList();
        var zLevels = rings.SelectMany(ring => ring).Select(item => item.Key.Z)
            .Distinct().Order().ToList();
        rejectionReason = $"z-levels-{zLevels.Count}";
        if (zLevels.Count != 2)
            return false;
        long lowZ = zLevels[0], highZ = zLevels[1];
        var lowCaps = rings.Where(ring =>
            ring.All(item => item.Key.Z == lowZ)).ToList();
        var highCaps = rings.Where(ring =>
            ring.All(item => item.Key.Z == highZ)).ToList();
        rejectionReason = $"caps-{lowCaps.Count}-{highCaps.Count}";
        if (lowCaps.Count != 1 || highCaps.Count != 1)
            return false;
        var lowCap = lowCaps[0];
        var highCap = highCaps[0];
        rejectionReason = $"cap-topology-{lowCap.Count}-{highCap.Count}";
        if (lowCap.Count < 5 || highCap.Count != lowCap.Count
            || lowCap.Select(item => item.Key).Distinct().Count()
                != lowCap.Count
            || highCap.Select(item => item.Key).Distinct().Count()
                != highCap.Count
            || !lowCap.Select(item => (item.Key.X, item.Key.Y)).ToHashSet()
                .SetEquals(highCap.Select(item =>
                    (item.Key.X, item.Key.Y))))
            return false;

        List<(double[] Point, (long X, long Y, long Z) Key)> SimplifyCap(
            IReadOnlyList<(double[] Point,
                (long X, long Y, long Z) Key)> cap)
        {
            var result = cap.ToList();
            bool changed;
            do
            {
                changed = false;
                if (result.Count <= 4)
                    break;
                for (int index = 0; index < result.Count; index++)
                {
                    if (!StrictlyWithinOneIfcLatticeOfSegment(
                            result[index].Key,
                            result[(index + result.Count - 1)
                                % result.Count].Key,
                            result[(index + 1) % result.Count].Key))
                        continue;
                    result.RemoveAt(index);
                    changed = true;
                    break;
                }
            }
            while (changed);
            return result;
        }
        var simplifiedCap = SimplifyCap(lowCap);
        var simplifiedHighCap = SimplifyCap(highCap);
        rejectionReason = "simplified-cap";
        if (simplifiedCap.Count != 4
            || simplifiedHighCap.Count != 4
            || simplifiedCap.Select(item => (item.Key.X, item.Key.Y))
                .Distinct().Count() != 4
            || !simplifiedCap.Select(item =>
                    (item.Key.X, item.Key.Y)).ToHashSet()
                .SetEquals(simplifiedHighCap.Select(item =>
                    (item.Key.X, item.Key.Y))))
            return false;

        var capEdges = Enumerable.Range(0, lowCap.Count).Select(index =>
            EdgeKey(
                (lowCap[index].Key.X, lowCap[index].Key.Y),
                (lowCap[(index + 1) % lowCap.Count].Key.X,
                    lowCap[(index + 1) % lowCap.Count].Key.Y))).ToList();
        rejectionReason = "cap-edges";
        if (capEdges.Distinct().Count() != capEdges.Count)
            return false;
        var sideEdgeCounts = capEdges.ToDictionary(edge => edge, _ => 0);
        foreach (var ring in rings.Where(ring =>
                     !ring.All(item => item.Key.Z == lowZ)
                     && !ring.All(item => item.Key.Z == highZ)))
        {
            var faceLevels = ring.Select(item => item.Key.Z).Distinct().ToList();
            var lowPoints = ring.Where(item => item.Key.Z == lowZ)
                .Select(item => (item.Key.X, item.Key.Y)).Distinct().ToList();
            var highPoints = ring.Where(item => item.Key.Z == highZ)
                .Select(item => (item.Key.X, item.Key.Y)).Distinct().ToList();
            rejectionReason = "side-topology";
            if (ring.Count != 4 || faceLevels.Count != 2
                || lowPoints.Count != 2 || highPoints.Count != 2
                || !lowPoints.ToHashSet().SetEquals(highPoints))
                return false;
            var edge = EdgeKey(lowPoints[0], lowPoints[1]);
            rejectionReason = "side-cap-edge";
            if (!sideEdgeCounts.TryGetValue(edge, out int count))
                return false;
            sideEdgeCounts[edge] = count + 1;
        }
        rejectionReason = "side-coverage";
        if (sideEdgeCounts.Values.Any(count => count != 1)
            || faces.Count != lowCap.Count + 2)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double normalX = -dy / axisLength, normalY = dx / axisLength;
        var across = simplifiedCap.Select(item =>
            item.Point[0] * normalX + item.Point[1] * normalY).ToList();
        double minimumAcross = across.Min(), maximumAcross = across.Max();
        double scale = Math.Max(
            1.0, across.Append(widthFt).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * scale;
        rejectionReason = "width-side-planes";
        if (Math.Abs((maximumAcross - minimumAcross) - widthFt) > roundoff
            || across.Count(value =>
                Math.Abs(value - minimumAcross) <= roundoff) != 2
            || across.Count(value =>
                Math.Abs(value - maximumAcross) <= roundoff) != 2)
            return false;

        var simplifiedPlan = simplifiedCap.Select(item =>
            new[] { item.Point[0], item.Point[1] }).ToList();
        rejectionReason = "serialized-bounds";
        if (!WallPlanMatchesSerializedBounds(simplifiedPlan, bounds))
            return false;
        baseZFt = lowCap.Average(item => item.Point[2]);
        double topZFt = highCap.Average(item => item.Point[2]);
        heightFt = topZFt - baseZFt;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        rejectionReason = "vertical-span";
        if (!(heightFt > 0) || !double.IsFinite(baseZFt)
            || !double.IsFinite(heightFt)
            || Math.Abs(baseZFt - bounds[2]) > toleranceFt
            || Math.Abs(topZFt - bounds[5]) > toleranceFt)
        {
            baseZFt = heightFt = 0;
            return false;
        }

        plan = lowCap.Select(item =>
            new[] { item.Point[0], item.Point[1] }).ToList();
        rejectionReason = "exact";
        return true;
    }

    /// <summary>
    /// Recognizes a nominal rectangular prism whose single top and bottom caps carry additional
    /// collinear boundary vertices and whose vertical sides are split at exactly those vertices.
    /// </summary>
    private static bool TryGetNominalStraightWallPrismWithCollinearBoundarySubdivision(
        GeometryData boundary, LocationCurve location, double widthFt,
        IReadOnlyList<double> bounds, out List<double[]> plan,
        out double baseZFt, out double heightFt, out string rejectionReason)
    {
        plan = [];
        baseZFt = heightFt = 0;
        rejectionReason = "preconditions";
        if (boundary.Faces is not { Count: >= 8 } faces
            || bounds.Count < 6
            || !(widthFt > 0) || !double.IsFinite(widthFt))
            return false;
        rejectionReason = "plan-centre";
        if (!TryResolveStraightWallPlanCentre(
                location, widthFt, bounds, out double centreXFt, out double centreYFt))
            return false;

        static List<(double[] Point, (long X, long Y, long Z) Key)> CleanRing(
            GeoFace face)
        {
            var result = new List<(double[] Point, (long X, long Y, long Z) Key)>();
            foreach (double[] point in face.OuterVertices ?? [])
            {
                var item = (Point: point, Key: IfcPrecisionKeyFeet(point));
                if (result.Count == 0 || result[^1].Key != item.Key) result.Add(item);
            }
            if (result.Count > 1 && result[0].Key == result[^1].Key)
                result.RemoveAt(result.Count - 1);
            return result;
        }

        rejectionReason = "face-validity";
        if (faces.Any(face => face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;
        var rings = faces.Select(CleanRing).ToList();
        var zLevels = rings.SelectMany(ring => ring).Select(item => item.Key.Z)
            .Distinct().OrderBy(value => value).ToList();
        rejectionReason = $"z-levels-{zLevels.Count}";
        if (zLevels.Count != 2) return false;
        long lowZ = zLevels[0], highZ = zLevels[1];
        var lowCaps = rings.Where(ring => ring.All(item => item.Key.Z == lowZ)).ToList();
        var highCaps = rings.Where(ring => ring.All(item => item.Key.Z == highZ)).ToList();
        rejectionReason = $"caps-{lowCaps.Count}-{highCaps.Count}";
        if (lowCaps.Count != 1 || highCaps.Count != 1) return false;
        var lowCap = lowCaps[0];
        var highCap = highCaps[0];
        rejectionReason = $"cap-topology-{lowCap.Count}-{highCap.Count}";
        if (lowCap.Count < 5 || highCap.Count != lowCap.Count
            || lowCap.Select(item => item.Key).Distinct().Count() != lowCap.Count
            || highCap.Select(item => item.Key).Distinct().Count() != highCap.Count
            || !lowCap.Select(item => (item.Key.X, item.Key.Y)).ToHashSet().SetEquals(
                highCap.Select(item => (item.Key.X, item.Key.Y))))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double lengthFt = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "axis";
        if (!(lengthFt > 0) || !double.IsFinite(lengthFt)) return false;
        double axisX = dx / lengthFt, axisY = dy / lengthFt;
        double normalX = -axisY, normalY = axisX;
        double halfLength = lengthFt / 2, halfWidth = widthFt / 2;
        List<double[]> nominalPlan =
        [
            [centreXFt - axisX * halfLength - normalX * halfWidth,
             centreYFt - axisY * halfLength - normalY * halfWidth],
            [centreXFt + axisX * halfLength - normalX * halfWidth,
             centreYFt + axisY * halfLength - normalY * halfWidth],
            [centreXFt + axisX * halfLength + normalX * halfWidth,
             centreYFt + axisY * halfLength + normalY * halfWidth],
            [centreXFt - axisX * halfLength + normalX * halfWidth,
             centreYFt - axisY * halfLength + normalY * halfWidth],
        ];
        rejectionReason = "serialized-bounds";
        if (!WallPlanMatchesSerializedBounds(nominalPlan, bounds))
        {
            return false;
        }

        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        static bool PointOnSegment(IReadOnlyList<double> point,
            IReadOnlyList<double> start, IReadOnlyList<double> end, double tolerance)
        {
            double edgeX = end[0] - start[0], edgeY = end[1] - start[1];
            double edgeLength = Math.Sqrt(edgeX * edgeX + edgeY * edgeY);
            if (!(edgeLength > 0)) return false;
            double pointX = point[0] - start[0], pointY = point[1] - start[1];
            double distance = Math.Abs(edgeX * pointY - edgeY * pointX) / edgeLength;
            double projection = (pointX * edgeX + pointY * edgeY) / edgeLength;
            return distance <= tolerance
                && projection >= -tolerance && projection <= edgeLength + tolerance;
        }
        bool SegmentOnNominalBoundary(IReadOnlyList<double> first,
            IReadOnlyList<double> second) => Enumerable.Range(0, nominalPlan.Count).Any(index =>
                PointOnSegment(first, nominalPlan[index],
                    nominalPlan[(index + 1) % nominalPlan.Count], toleranceFt)
                && PointOnSegment(second, nominalPlan[index],
                    nominalPlan[(index + 1) % nominalPlan.Count], toleranceFt));
        rejectionReason = "segment-boundary";
        for (int index = 0; index < lowCap.Count; index++)
            if (!SegmentOnNominalBoundary(lowCap[index].Point,
                    lowCap[(index + 1) % lowCap.Count].Point))
            {
                plan = [];
                return false;
            }
        rejectionReason = "nominal-corners";
        if (nominalPlan.Any(corner => !lowCap.Any(item =>
                Math.Sqrt(Math.Pow(item.Point[0] - corner[0], 2)
                    + Math.Pow(item.Point[1] - corner[1], 2)) <= toleranceFt)))
        {
            plan = [];
            return false;
        }

        static ((long X, long Y) First, (long X, long Y) Second) EdgeKey(
            (long X, long Y) first, (long X, long Y) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);
        var capEdges = Enumerable.Range(0, lowCap.Count).Select(index => EdgeKey(
            (lowCap[index].Key.X, lowCap[index].Key.Y),
            (lowCap[(index + 1) % lowCap.Count].Key.X,
                lowCap[(index + 1) % lowCap.Count].Key.Y))).ToList();
        rejectionReason = "duplicate-cap-edge";
        if (capEdges.Distinct().Count() != capEdges.Count)
        {
            plan = [];
            return false;
        }
        var sideEdgeCounts = capEdges.ToDictionary(edge => edge, _ => 0);
        foreach (var ring in rings.Where(ring =>
                     !ring.All(item => item.Key.Z == lowZ)
                     && !ring.All(item => item.Key.Z == highZ)))
        {
            var faceLevels = ring.Select(item => item.Key.Z).Distinct().ToList();
            var lowPoints = ring.Where(item => item.Key.Z == lowZ)
                .Select(item => (item.Key.X, item.Key.Y)).Distinct().ToList();
            var highPoints = ring.Where(item => item.Key.Z == highZ)
                .Select(item => (item.Key.X, item.Key.Y)).Distinct().ToList();
            rejectionReason = "side-topology";
            if (faceLevels.Count != 2 || lowPoints.Count != 2 || highPoints.Count != 2
                || !lowPoints.ToHashSet().SetEquals(highPoints))
            {
                plan = [];
                return false;
            }
            var edge = EdgeKey(lowPoints[0], lowPoints[1]);
            rejectionReason = "side-cap-edge";
            if (!sideEdgeCounts.TryGetValue(edge, out int count))
            {
                plan = [];
                return false;
            }
            sideEdgeCounts[edge] = count + 1;
        }
        rejectionReason = "side-coverage";
        if (sideEdgeCounts.Values.Any(count => count != 1)
            || faces.Count != lowCap.Count + 2)
        {
            plan = [];
            return false;
        }

        baseZFt = lowCap.Average(item => item.Point[2]);
        double topZFt = highCap.Average(item => item.Point[2]);
        heightFt = topZFt - baseZFt;
        rejectionReason = "vertical-span";
        if (!(heightFt > 0) || !double.IsFinite(baseZFt) || !double.IsFinite(heightFt)
            || Math.Abs(baseZFt - bounds[2]) > toleranceFt
            || Math.Abs(topZFt - bounds[5]) > toleranceFt)
        {
            plan = [];
            baseZFt = heightFt = 0;
            return false;
        }
        plan = nominalPlan;
        rejectionReason = "exact";
        return true;
    }

    /// <summary>Extracts a rectangle from an independently rebuilt vertical boundary.</summary>
    internal static bool TryGetExactVerticalRectangularWallPlan(GeometryData boundary,
        LocationCurve location, double widthFt, IReadOnlyList<double> bounds,
        out List<double[]> plan) =>
        TryGetExactVerticalRectangularWallPlan(
            boundary, location, widthFt, bounds, out plan, out _);

    internal static bool TryGetExactVerticalRectangularWallPlan(GeometryData boundary,
        LocationCurve location, double widthFt, IReadOnlyList<double> bounds,
        out List<double[]> plan, out string rejectionReason)
    {
        plan = [];
        rejectionReason = "preconditions";
        if (!IsExactVerticalExtrusionBoundary(boundary)
            || location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || bounds.Count < 6)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength)) return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;

        rejectionReason = "vertices";
        var vertices = boundary.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3)
            .Select(point => (Point: point, Key: IfcPrecisionKeyFeet(point)))
            .ToList();
        if (vertices.Count == 0) return false;
        long lowZ = vertices.Min(item => item.Key.Z);
        var bottom = vertices.Where(item => item.Key.Z == lowZ)
            .GroupBy(item => (item.Key.X, item.Key.Y))
            .Select(group => group.First().Point)
            .ToList();
        rejectionReason = $"bottom-corners-{bottom.Count}";
        if (bottom.Count != 4) return false;

        var projected = bottom.Select(point => new
        {
            Point = point,
            Along = point[0] * axisX + point[1] * axisY,
            Across = point[0] * normalX + point[1] * normalY,
        }).ToList();
        double minAlong = projected.Min(item => item.Along);
        double maxAlong = projected.Max(item => item.Along);
        double minAcross = projected.Min(item => item.Across);
        double maxAcross = projected.Max(item => item.Across);
        double scale = Math.Max(1.0, projected
            .SelectMany(item => new[] { item.Along, item.Across })
            .Append(widthFt).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 512 * MachineEpsilon * scale;
        rejectionReason = "side-extents";
        if (!(maxAlong - minAlong > roundoff)
            || Math.Abs((maxAcross - minAcross) - widthFt) > roundoff)
            return false;

        var corners = new HashSet<(int Along, int Across)>();
        rejectionReason = "corner-classification";
        foreach (var item in projected)
        {
            int along = Math.Abs(item.Along - minAlong) <= roundoff ? -1
                : Math.Abs(item.Along - maxAlong) <= roundoff ? 1 : 0;
            int across = Math.Abs(item.Across - minAcross) <= roundoff ? -1
                : Math.Abs(item.Across - maxAcross) <= roundoff ? 1 : 0;
            if (along == 0 || across == 0 || !corners.Add((along, across)))
                return false;
        }
        if (corners.Count != 4) return false;

        double centreAlong = (minAlong + maxAlong) / 2;
        double centreAcross = (minAcross + maxAcross) / 2;
        plan = projected.OrderBy(item => Math.Atan2(
                item.Across - centreAcross, item.Along - centreAlong))
            .Select(item => new[] { item.Point[0], item.Point[1] }).ToList();
        rejectionReason = "serialized-bounds";
        if (!WallPlanMatchesSerializedBounds(plan, bounds))
        {
            if (WallPlanMatchesSerializedBoundsAtIfcPrecision(plan, bounds))
                rejectionReason = "serialized-bounds-writer-lattice";
            plan = [];
            return false;
        }
        rejectionReason = "exact";
        return true;
    }

    /// <summary>
    /// Extracts the plan and vertical interval of one exact rectangular prism without assuming that
    /// its plan axes match a host wall.
    /// </summary>
    internal static bool TryGetExactVerticalRectangularPrismPlan(
        GeometryData boundary, out List<double[]> plan,
        out double baseZFt, out double heightFt) =>
        TryGetExactVerticalRectangularPrismPlan(
            boundary, out plan, out baseZFt, out heightFt, out _);

    internal static bool TryGetExactVerticalRectangularPrismPlan(
        GeometryData boundary, out List<double[]> plan,
        out double baseZFt, out double heightFt, out string rejectionReason)
    {
        plan = [];
        baseZFt = heightFt = 0;
        rejectionReason = "boundary-topology";
        if (boundary.Faces is not { Count: 6 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count))
            || !IsExactFacetedShell(faces, solids[0].FaceIndices))
            return false;
        rejectionReason = "vertical-extrusion";
        if (!IsExactVerticalExtrusionBoundary(
                new GeometryData { Faces = faces }))
            return false;

        var points = faces.SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0]) && double.IsFinite(point[1])
                && double.IsFinite(point[2]))
            .ToList();
        rejectionReason = "points";
        if (points.Count == 0) return false;
        var keyed = points.Select(point => (
            Point: point, Key: IfcPrecisionKeyFeet(point))).ToList();
        long lowZ = keyed.Min(value => value.Key.Z);
        long highZ = keyed.Max(value => value.Key.Z);
        var bottom = keyed.Where(value => value.Key.Z == lowZ)
            .GroupBy(value => (value.Key.X, value.Key.Y))
            .Select(group => group.First().Point).ToList();
        var top = keyed.Where(value => value.Key.Z == highZ)
            .GroupBy(value => (value.Key.X, value.Key.Y))
            .Select(group => group.First().Point).ToList();
        rejectionReason = "cap-corners";
        if (bottom.Count != 4 || top.Count != 4
            || !bottom.Select(point => IfcPrecisionKeyFeet(point))
                .Select(key => (key.X, key.Y)).ToHashSet()
                .SetEquals(top.Select(point => IfcPrecisionKeyFeet(point))
                    .Select(key => (key.X, key.Y))))
            return false;

        double centreX = bottom.Average(point => point[0]);
        double centreY = bottom.Average(point => point[1]);
        var orderedPlan = bottom.OrderBy(point => Math.Atan2(
                point[1] - centreY, point[0] - centreX))
            .Select(point => new[] { point[0], point[1] }).ToList();
        var edges = Enumerable.Range(0, 4).Select(index => new[]
        {
            orderedPlan[(index + 1) % 4][0] - orderedPlan[index][0],
            orderedPlan[(index + 1) % 4][1] - orderedPlan[index][1],
        }).ToList();
        plan = orderedPlan;
        var lengths = edges.Select(edge => Math.Sqrt(
            edge[0] * edge[0] + edge[1] * edge[1])).ToList();
        rejectionReason = "edge-length";
        if (lengths.Any(length => !(length > 0) || !double.IsFinite(length)))
        {
            plan = [];
            return false;
        }
        double scale = Math.Max(1.0, points.SelectMany(point => point)
            .Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double coordinateRoundoff = 4096 * MachineEpsilon * scale;
        rejectionReason = "orthogonality";
        for (int index = 0; index < 4; index++)
        {
            double[] current = edges[index];
            double[] next = edges[(index + 1) % 4];
            double normalizedDot = (current[0] * next[0]
                    + current[1] * next[1])
                / (lengths[index] * lengths[(index + 1) % 4]);
            if (Math.Abs(normalizedDot) > 4096 * MachineEpsilon)
            {
                plan = [];
                return false;
            }
        }
        rejectionReason = "opposite-edges";
        if (Math.Abs(edges[0][0] + edges[2][0]) > coordinateRoundoff
            || Math.Abs(edges[0][1] + edges[2][1]) > coordinateRoundoff
            || Math.Abs(edges[1][0] + edges[3][0]) > coordinateRoundoff
            || Math.Abs(edges[1][1] + edges[3][1]) > coordinateRoundoff)
        {
            plan = [];
            return false;
        }

        baseZFt = points.Min(point => point[2]);
        double maximumZFt = points.Max(point => point[2]);
        heightFt = maximumZFt - baseZFt;
        rejectionReason = "height";
        if (!(heightFt > coordinateRoundoff))
        {
            plan = [];
            baseZFt = heightFt = 0;
            return false;
        }
        rejectionReason = "exact";
        return true;
    }

    /// <summary>
    /// Converts an exact closed vertical rectangular BRep prism to the geometrically identical
    /// swept-box definition without using rounded BRep vertices.
    /// </summary>
    internal static bool TryGetExactVerticalRectangularPrismSweptOpening(
        GeometryData? boundary, out HostedOpeningGeometry opening)
    {
        opening = default;
        if (boundary == null
            || !TryGetExactVerticalRectangularPrismPlan(
                boundary, out var plan,
                out double baseZFt, out double heightFt)
            || plan.Count != 4)
            return false;
        double axisX = plan[1][0] - plan[0][0];
        double axisY = plan[1][1] - plan[0][1];
        double widthFt = Math.Sqrt(axisX * axisX + axisY * axisY);
        double depthX = plan[2][0] - plan[1][0];
        double depthY = plan[2][1] - plan[1][1];
        double depthFt = Math.Sqrt(depthX * depthX + depthY * depthY);
        if (!(widthFt > 0) || !(depthFt > 0)
            || !double.IsFinite(widthFt) || !double.IsFinite(depthFt))
            return false;
        axisX /= widthFt;
        axisY /= widthFt;
        opening = new HostedOpeningGeometry(
            plan.Average(point => point[0]),
            plan.Average(point => point[1]),
            axisX, axisY, widthFt, depthFt,
            baseZFt, heightFt, ExactDepth: true);
        return true;
    }

    /// <summary>
    /// Resolves the exact rectangular profile made by a closed ten-face stepped opening only over
    /// the thickness interval of one straight wall.
    /// </summary>
    internal static bool TryGetExactSteppedOpeningSweptBoxForWall(
        GeometryData? boundary, LocationCurve wallLocation, double wallWidthFt,
        out HostedOpeningGeometry opening)
    {
        opening = default;
        if (boundary is not { Faces: { Count: 10 } faces }
            || wallLocation is not { CurveType: "Line", ArcRadius: null }
            || !(wallWidthFt > 0) || !double.IsFinite(wallWidthFt)
            || faces.Any(face => face.OuterVertices is not { Count: 4 or 8 }
                || face.InnerVertices is { Count: > 0 }))
            return false;

        double axisX = wallLocation.EndPoint[0] - wallLocation.StartPoint[0];
        double axisY = wallLocation.EndPoint[1] - wallLocation.StartPoint[1];
        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        axisX /= axisLength;
        axisY /= axisLength;
        double normalX = -axisY, normalY = axisX;

        var vertices = faces.SelectMany(face => face.OuterVertices!)
            .GroupBy(IfcPrecisionKeyFeet)
            .Select(group => group.First()).ToList();
        if (vertices.Count != 16)
            return false;
        var projected = vertices.Select(point => (
            Along: point[0] * axisX + point[1] * axisY,
            Normal: point[0] * normalX + point[1] * normalY,
            Z: point[2])).ToList();
        long Key(double feet) =>
            IfcPrecisionBinMetres(feet * FeetToMetres);
        List<double> Levels(IEnumerable<double> values) => values
            .GroupBy(Key).OrderBy(group => group.Key)
            .Select(group => group.Average()).ToList();
        bool SameLevel(double first, double second) =>
            Key(first) == Key(second);

        var normalLevels = Levels(projected.Select(value => value.Normal));
        if (normalLevels.Count != 3)
            return false;
        double minimumNormal = normalLevels[0];
        double breakpointNormal = normalLevels[1];
        double maximumNormal = normalLevels[2];
        var minimumEnd = projected.Where(value =>
            SameLevel(value.Normal, minimumNormal)).ToList();
        var breakpointVertices = projected.Where(value =>
            SameLevel(value.Normal, breakpointNormal)).ToList();
        var maximumEnd = projected.Where(value =>
            SameLevel(value.Normal, maximumNormal)).ToList();
        if (minimumEnd.Count != 4 || breakpointVertices.Count != 8
            || maximumEnd.Count != 4)
            return false;

        bool TryProfile(
            IReadOnlyList<(double Along, double Normal, double Z)> values,
            out (double CentreAlong, double Width, double BaseZ, double Height) profile)
        {
            profile = default;
            var alongLevels = Levels(values.Select(value => value.Along));
            var zLevels = Levels(values.Select(value => value.Z));
            if (alongLevels.Count != 2 || zLevels.Count != 2
                || values.Select(value => (
                        Along: SameLevel(value.Along, alongLevels[0]) ? 0 : 1,
                        Z: SameLevel(value.Z, zLevels[0]) ? 0 : 1))
                    .Distinct().Count() != 4)
                return false;
            profile = ((alongLevels[0] + alongLevels[1]) / 2,
                alongLevels[1] - alongLevels[0], zLevels[0],
                zLevels[1] - zLevels[0]);
            return Key(profile.Width) > 0 && Key(profile.Height) > 0;
        }
        if (!TryProfile(minimumEnd, out var minimumProfile)
            || !TryProfile(maximumEnd, out var maximumProfile))
            return false;
        bool minimumIsInner =
            Key(minimumProfile.Width) < Key(maximumProfile.Width)
            && Key(minimumProfile.Height) < Key(maximumProfile.Height);
        bool maximumIsInner =
            Key(maximumProfile.Width) < Key(minimumProfile.Width)
            && Key(maximumProfile.Height) < Key(minimumProfile.Height);
        if (minimumIsInner == maximumIsInner
            || Key(minimumProfile.CentreAlong)
                != Key(maximumProfile.CentreAlong)
            || Key(minimumProfile.BaseZ) != Key(maximumProfile.BaseZ))
            return false;

        double wallCentreNormal = new[]
        {
            wallLocation.StartPoint[0] * normalX
                + wallLocation.StartPoint[1] * normalY,
            wallLocation.EndPoint[0] * normalX
                + wallLocation.EndPoint[1] * normalY,
        }.Average();
        double wallMinimumNormal = wallCentreNormal - wallWidthFt / 2;
        double wallMaximumNormal = wallCentreNormal + wallWidthFt / 2;
        (double CentreAlong, double Width, double BaseZ, double Height)
            selectedProfile;
        if (Key(wallMaximumNormal) < Key(breakpointNormal)
            && Key(wallMinimumNormal) >= Key(minimumNormal))
            selectedProfile = minimumProfile;
        else if (Key(wallMinimumNormal) > Key(breakpointNormal)
            && Key(wallMaximumNormal) <= Key(maximumNormal))
            selectedProfile = maximumProfile;
        else
            return false;

        double selectedCentreX = selectedProfile.CentreAlong * axisX
            + wallCentreNormal * normalX;
        double selectedCentreY = selectedProfile.CentreAlong * axisY
            + wallCentreNormal * normalY;
        var wallHole = new RectangularWallThroughOpening(
            selectedCentreX, selectedCentreY, axisX, axisY,
            selectedProfile.Width, selectedProfile.BaseZ,
            selectedProfile.Height, wallMinimumNormal, wallMaximumNormal);
        if (!ExactSteppedOpeningBoundaryMatchesWallHole(boundary, wallHole))
            return false;

        double openingCentreNormal = (minimumNormal + maximumNormal) / 2;
        opening = new HostedOpeningGeometry(
            selectedProfile.CentreAlong * axisX
                + openingCentreNormal * normalX,
            selectedProfile.CentreAlong * axisY
                + openingCentreNormal * normalY,
            axisX, axisY, selectedProfile.Width,
            maximumNormal - minimumNormal,
            selectedProfile.BaseZ, selectedProfile.Height,
            ExactDepth: true);
        return true;
    }

    /// <summary>
    /// Preserves an independently authored rectangular cutter frame while converting its exact BRep
    /// to a swept solid.
    /// </summary>
    internal static bool
        TryGetExactVerticalRectangularPrismSweptOpeningAlignedToDefinition(
            GeometryData? boundary, HostedOpeningGeometry definition,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        if (!definition.ExactDepth
            || definition.SteppedProfile != null
            || !(definition.WidthFt > 0)
            || !(definition.DepthFt > 0)
            || !(definition.HeightFt > 0)
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                boundary, out var decoded)
            || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                decoded, definition))
            return false;

        opening = definition with { Boundary = null };
        return true;
    }

    /// <summary>
    /// A single fallback definition is insufficient: all linked variants must first build and
    /// target the host, and this final check compares their eight physical corners independently of
    /// axis direction or a width/depth swap.
    /// </summary>
    internal static bool ExactSweptOpeningDefinitionsAreConcordant(
        IReadOnlyList<HostedOpeningGeometry>? definitions)
    {
        if (definitions is not { Count: >= 2 })
            return false;

        static List<double[]>? Corners(HostedOpeningGeometry definition)
        {
            if (definition.Boundary != null
                || definition.SteppedProfile != null
                || definition.IsFamilyCutLoop
                || !definition.ExactDepth
                || !(definition.WidthFt > 0)
                || !(definition.DepthFt > 0)
                || !(definition.HeightFt > 0)
                || !double.IsFinite(definition.CentreXFt)
                || !double.IsFinite(definition.CentreYFt)
                || !double.IsFinite(definition.AxisX)
                || !double.IsFinite(definition.AxisY)
                || !double.IsFinite(definition.WidthFt)
                || !double.IsFinite(definition.DepthFt)
                || !double.IsFinite(definition.BaseZFt)
                || !double.IsFinite(definition.HeightFt))
                return null;
            double axisLength = Math.Sqrt(
                definition.AxisX * definition.AxisX
                + definition.AxisY * definition.AxisY);
            if (!(axisLength > 0) || !double.IsFinite(axisLength))
                return null;
            double axisX = definition.AxisX / axisLength;
            double axisY = definition.AxisY / axisLength;
            double normalX = -axisY;
            double normalY = axisX;
            var result = new List<double[]>(8);
            foreach (double alongSign in new[] { -1.0, 1.0 })
                foreach (double normalSign in new[] { -1.0, 1.0 })
                    foreach (double z in new[]
                    {
                        definition.BaseZFt,
                        definition.BaseZFt + definition.HeightFt,
                    })
                        result.Add(
                        [
                            definition.CentreXFt
                                + alongSign * definition.WidthFt / 2 * axisX
                                + normalSign * definition.DepthFt / 2 * normalX,
                            definition.CentreYFt
                                + alongSign * definition.WidthFt / 2 * axisY
                                + normalSign * definition.DepthFt / 2 * normalY,
                            z,
                        ]);
            return result;
        }

        var cornerSets = definitions.Select(Corners).ToList();
        if (cornerSets.Any(corners => corners is not { Count: 8 }))
            return false;
        double scale = Math.Max(1.0, cornerSets
            .SelectMany(corners => corners!)
            .SelectMany(point => point)
            .Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 16384 * MachineEpsilon * scale;
        List<double[]> reference = cornerSets[0]!;
        foreach (List<double[]> candidate in cornerSets.Skip(1).Cast<List<double[]>>())
        {
            var unmatched = Enumerable.Range(0, candidate.Count).ToList();
            foreach (double[] referenceCorner in reference)
            {
                int matchPosition = unmatched.FindIndex(index =>
                    Math.Abs(referenceCorner[0] - candidate[index][0]) <= roundoff
                    && Math.Abs(referenceCorner[1] - candidate[index][1]) <= roundoff
                    && Math.Abs(referenceCorner[2] - candidate[index][2]) <= roundoff);
                if (matchPosition < 0)
                    return false;
                unmatched.RemoveAt(matchPosition);
            }
            if (unmatched.Count != 0)
                return false;
        }
        return true;
    }

    /// <summary>
    /// Uses the placed FamilyInstance symbol as the authoritative member of a complete multi-host
    /// FamilyCut set when every linked variant independently forms an exact rectangular prism.
    /// </summary>
    internal static bool
        TryBuildExactPreferredMultiHostFamilyCutRectangularOpening(
            Element hostedElement,
            IReadOnlyList<Element>? linkedFamilyCutTypes,
            IReadOnlyList<HostedOpeningGeometry>? builtFamilyCutCandidates,
            IReadOnlyList<Element>? candidateHostWalls,
            IReadOnlyDictionary<int, List<int>>? inverseHostedHostIds,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);

        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCPREFERREDFAMILYCUTGATE cutter={hostedElement.Id} "
                    + $"result=reject stage={stage}");
            return false;
        }

        if (hostedElement.CategoryId is not (-2000023 or -2000014)
            || hostedElement.SuperInstanceId is > 0
            || hostedElement.Transform is not
                {
                    Origin.Length: >= 3,
                    BasisX.Length: >= 3,
                    BasisY.Length: >= 3,
                    BasisZ.Length: >= 3,
                    SymbolId: > 0,
                } transform
            || transform.Origin.Concat(transform.BasisX)
                .Concat(transform.BasisY).Concat(transform.BasisZ)
                .Any(value => !double.IsFinite(value)))
            return Reject("instance-contract");

        if (linkedFamilyCutTypes is not { Count: >= 2 }
            || builtFamilyCutCandidates == null
            || builtFamilyCutCandidates.Count != linkedFamilyCutTypes.Count
            || linkedFamilyCutTypes.Select(type => type.Id).Distinct().Count()
                != linkedFamilyCutTypes.Count
            || linkedFamilyCutTypes[0].Id != transform.SymbolId)
            return Reject("preferred-linked-types");

        if (candidateHostWalls is not { Count: >= 2 }
            || candidateHostWalls.Select(host => host.Id).Distinct().Count()
                != candidateHostWalls.Count
            || inverseHostedHostIds == null
            || !inverseHostedHostIds.TryGetValue(
                hostedElement.Id, out var inverseHostIds)
            || inverseHostIds.Count < 2
            || inverseHostIds.Distinct().Count() != inverseHostIds.Count
            || !candidateHostWalls.Select(host => host.Id).ToHashSet()
                .SetEquals(inverseHostIds))
            return Reject("complete-inverse-hosts");

        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        if (candidateHostWalls.Count(host => host.Id == primaryHostId) != 1
            || candidateHostWalls.Any(host =>
                host.CategoryId != -2000011
                || host.CuttingElementIds?.Count(
                    cutterId => cutterId == hostedElement.Id) != 1))
            return Reject("authored-host-relations");

        static double Dot(IReadOnlyList<double> first,
            IReadOnlyList<double> second) =>
            first[0] * second[0] + first[1] * second[1]
            + first[2] * second[2];
        static double Length(IReadOnlyList<double> vector) =>
            Math.Sqrt(Dot(vector, vector));

        const double MachineEpsilon = 2.2204460492503131e-16;
        double transformScale = Math.Max(1.0,
            transform.Origin.Concat(transform.BasisX)
                .Concat(transform.BasisY).Concat(transform.BasisZ)
                .Select(Math.Abs).Max());
        double transformRoundoff =
            16384 * MachineEpsilon * transformScale;
        double basisXLength = Length(transform.BasisX);
        double basisYLength = Length(transform.BasisY);
        double basisZLength = Length(transform.BasisZ);
        if (Math.Abs(basisXLength - 1) > transformRoundoff
            || Math.Abs(basisYLength - 1) > transformRoundoff
            || Math.Abs(basisZLength - 1) > transformRoundoff
            || Math.Abs(Dot(transform.BasisX, transform.BasisY))
                > transformRoundoff
            || Math.Abs(Dot(transform.BasisX, transform.BasisZ))
                > transformRoundoff
            || Math.Abs(Dot(transform.BasisY, transform.BasisZ))
                > transformRoundoff
            || Math.Abs(transform.BasisX[2]) > transformRoundoff
            || Math.Abs(transform.BasisY[2]) > transformRoundoff
            || Math.Abs(transform.BasisZ[0]) > transformRoundoff
            || Math.Abs(transform.BasisZ[1]) > transformRoundoff
            || Math.Abs(Math.Abs(transform.BasisZ[2]) - 1)
                > transformRoundoff)
            return Reject("orthonormal-transform");

        double transformPlanLength = Math.Sqrt(
            transform.BasisX[0] * transform.BasisX[0]
            + transform.BasisX[1] * transform.BasisX[1]);
        if (!(transformPlanLength > 0)
            || !double.IsFinite(transformPlanLength))
            return Reject("plan-axis");
        double axisX = transform.BasisX[0] / transformPlanLength;
        double axisY = transform.BasisX[1] / transformPlanLength;
        const double DirectionRoundoff = 16384 * MachineEpsilon;

        var definitions = new List<HostedOpeningGeometry>(
            builtFamilyCutCandidates.Count);
        foreach (HostedOpeningGeometry candidate in builtFamilyCutCandidates)
        {
            if (candidate.Boundary is not { Faces.Count: 6 } boundary
                || !TryGetExactVerticalRectangularPrismSweptOpening(
                    boundary, out var decoded))
                return Reject("exact-rectangular-prism");

            double decodedAxisLength = Math.Sqrt(
                decoded.AxisX * decoded.AxisX
                + decoded.AxisY * decoded.AxisY);
            if (!(decodedAxisLength > 0)
                || !double.IsFinite(decodedAxisLength))
                return Reject("decoded-axis");
            double directionDot =
                decoded.AxisX / decodedAxisLength * axisX
                + decoded.AxisY / decodedAxisLength * axisY;
            double widthFt;
            double depthFt;
            if (Math.Abs(Math.Abs(directionDot) - 1)
                <= DirectionRoundoff)
            {
                widthFt = decoded.WidthFt;
                depthFt = decoded.DepthFt;
            }
            else if (Math.Abs(directionDot) <= DirectionRoundoff)
            {
                widthFt = decoded.DepthFt;
                depthFt = decoded.WidthFt;
            }
            else
                return Reject("profile-axis");

            definitions.Add(new HostedOpeningGeometry(
                decoded.CentreXFt, decoded.CentreYFt,
                axisX, axisY, widthFt, depthFt,
                decoded.BaseZFt, decoded.HeightFt,
                ExactDepth: true));
        }

        HostedOpeningGeometry preferred = definitions[0];
        double coordinateScale = Math.Max(1.0, definitions
            .SelectMany(definition => new[]
            {
                definition.CentreXFt, definition.CentreYFt,
                definition.WidthFt, definition.DepthFt,
                definition.BaseZFt, definition.HeightFt,
            })
            .Select(Math.Abs).Max());
        double coordinateRoundoff =
            16384 * MachineEpsilon * coordinateScale;
        double preferredCentreAlong =
            preferred.CentreXFt * axisX + preferred.CentreYFt * axisY;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= coordinateRoundoff;
        if (definitions.Skip(1).Any(definition =>
            !Same(definition.CentreXFt * axisX
                    + definition.CentreYFt * axisY,
                preferredCentreAlong)
            || !Same(definition.WidthFt, preferred.WidthFt)
            || !Same(definition.BaseZFt, preferred.BaseZFt)
            || !Same(definition.HeightFt, preferred.HeightFt)))
            return Reject("shared-profile");

        static bool TryGetUniqueExternalLength(
            Element element, Guid expectedGuid, out double value)
        {
            var matches = element.Parameters.Where(parameter =>
                    parameter.Id > 0
                    && parameter.StorageType == StorageType.Double
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.external.-1:",
                        StringComparison.Ordinal) == true
                    && BipHelpers.ParseGuidFromForgeId(parameter.ForgeId)
                        == expectedGuid
                    && (parameter.Guid == null
                        || parameter.Guid == expectedGuid)
                    && (parameter.SpecType == null
                        || parameter.SpecType.Contains(
                            ":length",
                            StringComparison.OrdinalIgnoreCase))
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .Select(parameter => (double)parameter.Value!)
                .ToList();
            value = matches.Count == 1 ? matches[0] : double.NaN;
            return matches.Count == 1;
        }

        if (!TryGetUniqueExternalLength(
                hostedElement, AdskSizeWidthParameterGuid,
                out double parameterWidthFt)
            || !TryGetUniqueExternalLength(
                hostedElement, AdskSizeHeightParameterGuid,
                out double parameterHeightFt)
            || !Same(parameterWidthFt, preferred.WidthFt)
            || !Same(parameterHeightFt, preferred.HeightFt))
            return Reject("parameter-profile");

        var hostIntersections = candidateHostWalls.Select(host => (
            Host: host,
            Intersects:
                ExactDirectedOpeningHasPositiveAuthoredHostIntersection(
                    preferred, host))).ToList();
        if (diagnostics)
            foreach (var result in hostIntersections)
                DiagnosticSink.WriteLine(
                    $"IFCPREFERREDFAMILYCUTINTERSECTION "
                    + $"cutter={hostedElement.Id} host={result.Host.Id} "
                    + $"intersects={result.Intersects}");
        if (hostIntersections.Count(result => result.Intersects) != 2
            || hostIntersections.All(result => result.Intersects)
            || !hostIntersections.Single(
                result => result.Host.Id == primaryHostId).Intersects)
            return Reject("host-intersection");

        opening = preferred with
        {
            Boundary = builtFamilyCutCandidates[0].Boundary,
            IsExactConcordantFamilyCut = true,
            IsExactParameterizedRectangularCut = true,
        };
        if (!ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                opening))
            return Reject("boundary-definition");

        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCPREFERREDFAMILYCUTGATE cutter={hostedElement.Id} "
                + $"result=accept hosts={string.Join(',', inverseHostIds)} "
                + $"width={opening.WidthFt:G17} "
                + $"height={opening.HeightFt:G17} "
                + $"depth={opening.DepthFt:G17}");
        return true;
    }

    /// <summary>
    /// Recovers a gross rectangular wall from the exact eight-face folded-span shell produced when
    /// a full-height rectangular cutter has already split one wall side profile.
    /// </summary>
    internal static bool
        TryGetExactRectangularWallGrossBoundaryFromFoldedCapSpan(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData grossBoundary,
            out long foldAlongBin, out string rejectionReason)
    {
        grossBoundary = new GeometryData();
        foldAlongBin = 0;
        rejectionReason = "preconditions";
        if (location is not { CurveType: "Line", ArcRadius: null }
            || bounds.Count < 6 || !(widthFt > 0) || !double.IsFinite(widthFt)
            || boundary.Faces is not { Count: 8 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count)))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "wall-axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        double coordinateScale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices ?? [])
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Select(Math.Abs).DefaultIfEmpty(1).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * coordinateScale;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
            {
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            }
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        (long Along, long Z) ProfileKey(double[] point) => (
            IfcPrecisionBinMetres(
                (point[0] * axisX + point[1] * axisY) * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres));
        static ((long Along, long Z) First, (long Along, long Z) Second)
            EdgeKey((long Along, long Z) first,
                (long Along, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        HashSet<((long Along, long Z) First, (long Along, long Z) Second)>
            CycleEdges(IReadOnlyList<(long Along, long Z)> cycle) =>
            Enumerable.Range(0, cycle.Count)
                .Select(index => EdgeKey(
                    cycle[index], cycle[(index + 1) % cycle.Count]))
                .ToHashSet();
        HashSet<((long Along, long Z) First, (long Along, long Z) Second)>
            RingEdges(IEnumerable<double[]> ring)
        {
            var keys = ring.Select(ProfileKey).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => EdgeKey(
                    keys[index], keys[(index + 1) % keys.Count]))
                .ToHashSet();
        }

        var sideProfiles = new List<(GeoFace Face, List<double[]> Ring,
            double Plane, Dictionary<(long Along, long Z), double[]> Points)>();
        foreach (GeoFace face in faces)
        {
            if (face.OuterVertices is not { Count: >= 6 } outer
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
                continue;
            var ring = CleanRing(outer);
            if (ring.Count != 6 || !FaceCanEmitAtIfcPrecision(face))
                continue;
            var planeValues = ring
                .Select(point => point[0] * normalX + point[1] * normalY)
                .ToList();
            if (planeValues.Max() - planeValues.Min() > roundoff)
                continue;
            var points = new Dictionary<(long Along, long Z), double[]>();
            if (ring.Any(point => !points.TryAdd(ProfileKey(point), point)))
                continue;
            sideProfiles.Add((face, ring,
                (planeValues.Min() + planeValues.Max()) / 2, points));
        }
        rejectionReason = $"side-profile-count-{sideProfiles.Count}";
        if (sideProfiles.Count != 2) return false;
        sideProfiles.Sort((left, right) => left.Plane.CompareTo(right.Plane));
        var lowSide = sideProfiles[0];
        var highSide = sideProfiles[1];
        rejectionReason = "wall-width";
        if (Math.Abs((highSide.Plane - lowSide.Plane) - widthFt) > roundoff)
            return false;
        rejectionReason = "side-profile-match";
        if (!lowSide.Points.Keys.ToHashSet().SetEquals(highSide.Points.Keys))
            return false;

        var alongLevels = lowSide.Points.Keys.Select(key => key.Along)
            .Distinct().Order().ToList();
        var zLevels = lowSide.Points.Keys.Select(key => key.Z)
            .Distinct().Order().ToList();
        rejectionReason = $"fold-levels-{alongLevels.Count}-{zLevels.Count}";
        if (alongLevels.Count != 3 || zLevels.Count != 2
            || alongLevels.Zip(alongLevels.Skip(1))
                .Any(pair => pair.Second - pair.First <= 2)
            || zLevels[1] - zLevels[0] <= 2)
            return false;

        long a0 = alongLevels[0], a1 = alongLevels[1], a2 = alongLevels[2];
        long z0 = zLevels[0], z1 = zLevels[1];
        List<(long Along, long Z)>[] candidateCycles =
        [
            [
                (a0, z0), (a2, z0), (a1, z0),
                (a1, z1), (a2, z1), (a0, z1),
            ],
            [
                (a2, z0), (a0, z0), (a1, z0),
                (a1, z1), (a0, z1), (a2, z1),
            ],
        ];
        var lowEdges = RingEdges(lowSide.Ring);
        var highEdges = RingEdges(highSide.Ring);
        var matchingCycles = candidateCycles.Where(cycle =>
                lowSide.Points.Keys.ToHashSet().SetEquals(cycle)
                && lowEdges.SetEquals(CycleEdges(cycle))
                && highEdges.SetEquals(CycleEdges(cycle)))
            .ToList();
        rejectionReason = $"fold-cycle-match-{matchingCycles.Count}";
        if (matchingCycles.Count != 1) return false;
        var foldCycle = matchingCycles[0];

        var connectorFaces = faces.Where(face =>
                !ReferenceEquals(face, lowSide.Face)
                && !ReferenceEquals(face, highSide.Face))
            .ToList();
        rejectionReason = "connector-contract";
        if (connectorFaces.Count != 6
            || connectorFaces.Any(face =>
                CleanRing(face.OuterVertices ?? []).Count != 4
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;
        var remainingConnectors = connectorFaces.Select(face =>
                CleanRing(face.OuterVertices!)
                    .Select(IfcPrecisionKeyFeet).ToHashSet())
            .ToList();
        foreach (var edge in CycleEdges(foldCycle))
        {
            var expected = new HashSet<(long X, long Y, long Z)>
            {
                IfcPrecisionKeyFeet(lowSide.Points[edge.First]),
                IfcPrecisionKeyFeet(lowSide.Points[edge.Second]),
                IfcPrecisionKeyFeet(highSide.Points[edge.First]),
                IfcPrecisionKeyFeet(highSide.Points[edge.Second]),
            };
            var matches = remainingConnectors
                .Select((vertices, index) => (vertices, index))
                .Where(candidate => candidate.vertices.SetEquals(expected))
                .Select(candidate => candidate.index).ToList();
            if (matches.Count != 1)
            {
                rejectionReason = "connector-match";
                return false;
            }
            remainingConnectors.RemoveAt(matches[0]);
        }
        if (remainingConnectors.Count != 0)
        {
            rejectionReason = "remaining-connectors";
            return false;
        }

        bool TrySourceLevels(
            (GeoFace Face, List<double[]> Ring, double Plane,
                Dictionary<(long Along, long Z), double[]> Points) side,
            out Dictionary<long, double> along,
            out Dictionary<long, double> z)
        {
            along = [];
            z = [];
            foreach (long level in alongLevels)
            {
                var values = side.Points
                    .Where(entry => entry.Key.Along == level)
                    .Select(entry => entry.Value[0] * axisX
                        + entry.Value[1] * axisY).ToList();
                if (values.Count == 0
                    || values.Max() - values.Min() > roundoff)
                    return false;
                along[level] = (values.Min() + values.Max()) / 2;
            }
            foreach (long level in zLevels)
            {
                var values = side.Points
                    .Where(entry => entry.Key.Z == level)
                    .Select(entry => entry.Value[2]).ToList();
                if (values.Count == 0
                    || values.Max() - values.Min() > roundoff)
                    return false;
                z[level] = (values.Min() + values.Max()) / 2;
            }
            return true;
        }
        rejectionReason = "source-levels";
        if (!TrySourceLevels(lowSide, out var lowAlong, out var lowZ)
            || !TrySourceLevels(highSide, out var highAlong, out var highZ))
            return false;

        double[] Point(double along, double normal, double z) =>
        [
            along * axisX + normal * normalX,
            along * axisY + normal * normalY,
            z,
        ];
        List<double[]> Rectangle(
            Dictionary<long, double> along,
            Dictionary<long, double> z, double plane) =>
        [
            Point(along[a0], plane, z[z0]),
            Point(along[a2], plane, z[z0]),
            Point(along[a2], plane, z[z1]),
            Point(along[a0], plane, z[z1]),
        ];
        var lowOuter = Rectangle(lowAlong, lowZ, lowSide.Plane);
        var highOuter = Rectangle(highAlong, highZ, highSide.Plane);
        var grossFaces = new List<GeoFace>
        {
            new() { OuterVertices = lowOuter },
            new()
            {
                OuterVertices = highOuter.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < lowOuter.Count; index++)
        {
            int next = (index + 1) % lowOuter.Count;
            grossFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    lowOuter[index], highOuter[index],
                    highOuter[next], lowOuter[next],
                ],
            });
        }
        var candidateGross = new GeometryData
        {
            BoundingBox = boundary.BoundingBox is { Length: 6 } boundaryBounds
                ? (double[])boundaryBounds.Clone() : null,
            Faces = grossFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, grossFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        rejectionReason = "gross-validation";
        string grossReason = "faceted-shell";
        if (!IsExactFacetedShell(
                grossFaces, candidateGross.BrepSolids[0].FaceIndices)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                candidateGross, location, widthFt, bounds,
                out _, out _, out _, out grossReason)
            || grossReason != "exact")
        {
            rejectionReason = $"gross-validation-{grossReason}";
            return false;
        }

        grossBoundary = candidateGross;
        foldAlongBin = a1;
        rejectionReason = "exact-folded-cap-span";
        return true;
    }

    /// <summary>
    /// Promotes an exact closed wall shell whose otherwise rectangular side profiles contain one
    /// synchronized vertical end step.
    /// </summary>
    internal static bool
        TryGetExactRectangularWallGrossBoundaryFromVerticalStep(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData grossBoundary,
            out string rejectionReason) =>
        TryGetExactRectangularWallBoundaryFromVerticalStep(
            boundary, location, widthFt, bounds,
            inverseStartAndBottomTrimmedSpanOnly: false,
            returnGrossBoundaryForInverseStep: false,
            out grossBoundary, out _, out rejectionReason);

    /// <summary>Recognizes only the otherwise ambiguous inverse start-and-bottom step.</summary>
    internal static bool
        TryGetExactRectangularWallTrimmedBoundaryFromInverseVerticalStep(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData trimmedBoundary,
            out string rejectionReason) =>
        TryGetExactRectangularWallTrimmedBoundaryFromInverseVerticalStep(
            boundary, location, widthFt, bounds, out trimmedBoundary,
            out _, out rejectionReason);

    internal static bool
        TryGetExactRectangularWallTrimmedBoundaryFromInverseVerticalStep(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData trimmedBoundary,
            out List<double[]> serializedAxisPlan,
            out string rejectionReason) =>
        TryGetExactRectangularWallBoundaryFromVerticalStep(
            boundary, location, widthFt, bounds,
            inverseStartAndBottomTrimmedSpanOnly: true,
            returnGrossBoundaryForInverseStep: false,
            out trimmedBoundary, out serializedAxisPlan,
            out rejectionReason);

    /// <summary>
    /// Returns the independently validated gross rectangle for the inverse start-and-bottom cycle.
    /// </summary>
    internal static bool
        TryGetExactRectangularWallGrossBoundaryFromInverseVerticalStep(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData grossBoundary,
            out string rejectionReason) =>
        TryGetExactRectangularWallBoundaryFromVerticalStep(
            boundary, location, widthFt, bounds,
            inverseStartAndBottomTrimmedSpanOnly: true,
            returnGrossBoundaryForInverseStep: true,
            out grossBoundary, out _, out rejectionReason);

    private static bool TryGetExactRectangularWallBoundaryFromVerticalStep(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds,
            bool inverseStartAndBottomTrimmedSpanOnly,
            bool returnGrossBoundaryForInverseStep,
            out GeometryData grossBoundary,
            out List<double[]> serializedAxisPlan,
            out string rejectionReason)
    {
        grossBoundary = new GeometryData();
        serializedAxisPlan = [];
        rejectionReason = "preconditions";
        if (location is not { CurveType: "Line", ArcRadius: null }
            || bounds.Count < 6 || !(widthFt > 0) || !double.IsFinite(widthFt)
            || boundary.Faces is not { Count: 8 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count)))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "wall-axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        double coordinateScale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices ?? [])
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Select(Math.Abs).DefaultIfEmpty(1).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * coordinateScale;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
            {
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            }
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        (long Along, long Z) ProfileKey(double[] point) => (
            IfcPrecisionBinMetres(
                (point[0] * axisX + point[1] * axisY) * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres));
        static ((long Along, long Z) First, (long Along, long Z) Second)
            EdgeKey((long Along, long Z) first,
                (long Along, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        HashSet<((long Along, long Z) First, (long Along, long Z) Second)>
            CycleEdges(IReadOnlyList<(long Along, long Z)> cycle) =>
            Enumerable.Range(0, cycle.Count)
                .Select(index => EdgeKey(
                    cycle[index], cycle[(index + 1) % cycle.Count]))
                .ToHashSet();
        HashSet<((long Along, long Z) First, (long Along, long Z) Second)>
            RingEdges(IEnumerable<double[]> ring)
        {
            var keys = ring.Select(ProfileKey).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => EdgeKey(
                    keys[index], keys[(index + 1) % keys.Count]))
                .ToHashSet();
        }

        var sideProfiles = new List<(GeoFace Face, List<double[]> Ring,
            double Plane, Dictionary<(long Along, long Z), double[]> Points)>();
        foreach (GeoFace face in faces)
        {
            if (face.OuterVertices is not { Count: >= 6 } outer
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
                continue;
            var ring = CleanRing(outer);
            if (ring.Count != 6 || !FaceCanEmitAtIfcPrecision(face))
                continue;
            var planeValues = ring
                .Select(point => point[0] * normalX + point[1] * normalY)
                .ToList();
            if (planeValues.Max() - planeValues.Min() > roundoff)
                continue;
            var points = new Dictionary<(long Along, long Z), double[]>();
            if (ring.Any(point => !points.TryAdd(ProfileKey(point), point)))
                continue;
            sideProfiles.Add((face, ring,
                (planeValues.Min() + planeValues.Max()) / 2, points));
        }
        rejectionReason = $"side-profile-count-{sideProfiles.Count}";
        if (sideProfiles.Count != 2) return false;
        sideProfiles.Sort((left, right) => left.Plane.CompareTo(right.Plane));
        var lowSide = sideProfiles[0];
        var highSide = sideProfiles[1];
        rejectionReason = "wall-width";
        if (Math.Abs((highSide.Plane - lowSide.Plane) - widthFt) > roundoff)
            return false;
        rejectionReason = "side-profile-match";
        if (!lowSide.Points.Keys.ToHashSet().SetEquals(highSide.Points.Keys))
            return false;

        var alongLevels = lowSide.Points.Keys.Select(key => key.Along)
            .Distinct().Order().ToList();
        var zLevels = lowSide.Points.Keys.Select(key => key.Z)
            .Distinct().Order().ToList();
        rejectionReason = $"step-levels-{alongLevels.Count}-{zLevels.Count}";
        if (alongLevels.Count != 3 || zLevels.Count != 3
            || alongLevels.Zip(alongLevels.Skip(1))
                .Any(pair => pair.Second - pair.First <= 2)
            || zLevels.Zip(zLevels.Skip(1))
                .Any(pair => pair.Second - pair.First <= 2))
            return false;

        long a0 = alongLevels[0], a1 = alongLevels[1], a2 = alongLevels[2];
        long z0 = zLevels[0], z1 = zLevels[1], z2 = zLevels[2];
        List<(long Along, long Z)>[] candidateCycles =
            inverseStartAndBottomTrimmedSpanOnly
                ?
                [
                    [
                        (a2, z0), (a2, z2), (a0, z2),
                        (a0, z1), (a1, z1), (a1, z0),
                    ],
                ]
                :
                [
                    [
                        (a0, z0), (a2, z0), (a2, z1),
                        (a1, z1), (a1, z2), (a0, z2),
                    ],
                    [
                        (a2, z0), (a0, z0), (a0, z1),
                        (a1, z1), (a1, z2), (a2, z2),
                    ],
                    [
                        (a0, z2), (a2, z2), (a2, z1),
                        (a1, z1), (a1, z0), (a0, z0),
                    ],
                ];
        var lowEdges = RingEdges(lowSide.Ring);
        var highEdges = RingEdges(highSide.Ring);
        var matchingCycles = candidateCycles.Where(cycle =>
                lowSide.Points.Keys.ToHashSet().SetEquals(cycle)
                && lowEdges.SetEquals(CycleEdges(cycle))
                && highEdges.SetEquals(CycleEdges(cycle)))
            .ToList();
        rejectionReason = $"step-cycle-match-{matchingCycles.Count}";
        if (matchingCycles.Count != 1) return false;
        var stepCycle = matchingCycles[0];

        var connectorFaces = faces.Where(face =>
                !ReferenceEquals(face, lowSide.Face)
                && !ReferenceEquals(face, highSide.Face))
            .ToList();
        rejectionReason = "connector-contract";
        if (connectorFaces.Count != 6
            || connectorFaces.Any(face =>
                CleanRing(face.OuterVertices ?? []).Count != 4
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;
        var remainingConnectors = connectorFaces.Select(face =>
                CleanRing(face.OuterVertices!)
                    .Select(IfcPrecisionKeyFeet).ToHashSet())
            .ToList();
        foreach (var edge in CycleEdges(stepCycle))
        {
            var expected = new HashSet<(long X, long Y, long Z)>
            {
                IfcPrecisionKeyFeet(lowSide.Points[edge.First]),
                IfcPrecisionKeyFeet(lowSide.Points[edge.Second]),
                IfcPrecisionKeyFeet(highSide.Points[edge.First]),
                IfcPrecisionKeyFeet(highSide.Points[edge.Second]),
            };
            var matches = remainingConnectors
                .Select((vertices, index) => (vertices, index))
                .Where(candidate => candidate.vertices.SetEquals(expected))
                .Select(candidate => candidate.index).ToList();
            if (matches.Count != 1)
            {
                rejectionReason = "connector-match";
                return false;
            }
            remainingConnectors.RemoveAt(matches[0]);
        }
        if (remainingConnectors.Count != 0)
        {
            rejectionReason = "remaining-connectors";
            return false;
        }

        bool TrySourceLevels(
            (GeoFace Face, List<double[]> Ring, double Plane,
                Dictionary<(long Along, long Z), double[]> Points) side,
            out Dictionary<long, double> along,
            out Dictionary<long, double> z)
        {
            along = [];
            z = [];
            foreach (long level in alongLevels)
            {
                var values = side.Points
                    .Where(entry => entry.Key.Along == level)
                    .Select(entry => entry.Value[0] * axisX
                        + entry.Value[1] * axisY).ToList();
                if (values.Count == 0
                    || values.Max() - values.Min() > roundoff)
                    return false;
                along[level] = (values.Min() + values.Max()) / 2;
            }
            foreach (long level in zLevels)
            {
                var values = side.Points
                    .Where(entry => entry.Key.Z == level)
                    .Select(entry => entry.Value[2]).ToList();
                if (values.Count == 0
                    || values.Max() - values.Min() > roundoff)
                    return false;
                z[level] = (values.Min() + values.Max()) / 2;
            }
            return true;
        }
        rejectionReason = "source-levels";
        if (!TrySourceLevels(lowSide, out var lowAlong, out var lowZ)
            || !TrySourceLevels(highSide, out var highAlong, out var highZ))
            return false;

        double[] Point(double along, double normal, double z) =>
        [
            along * axisX + normal * normalX,
            along * axisY + normal * normalY,
            z,
        ];
        List<double[]> Rectangle(
            Dictionary<long, double> along,
            Dictionary<long, double> z, double plane,
            long minimumAlongLevel, long maximumAlongLevel) =>
        [
            Point(along[minimumAlongLevel], plane, z[z0]),
            Point(along[maximumAlongLevel], plane, z[z0]),
            Point(along[maximumAlongLevel], plane, z[z2]),
            Point(along[minimumAlongLevel], plane, z[z2]),
        ];
        var lowOuter = Rectangle(
            lowAlong, lowZ, lowSide.Plane, a0, a2);
        var highOuter = Rectangle(
            highAlong, highZ, highSide.Plane, a0, a2);
        var grossFaces = new List<GeoFace>
        {
            new() { OuterVertices = lowOuter },
            new()
            {
                OuterVertices = highOuter.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < lowOuter.Count; index++)
        {
            int next = (index + 1) % lowOuter.Count;
            grossFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    lowOuter[index], highOuter[index],
                    highOuter[next], lowOuter[next],
                ],
            });
        }
        var candidateGross = new GeometryData
        {
            BoundingBox = boundary.BoundingBox is { Length: 6 } boundaryBounds
                ? (double[])boundaryBounds.Clone() : null,
            Faces = grossFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, grossFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        rejectionReason = "gross-validation";
        string grossReason = "faceted-shell";
        List<double[]> fullGrossPlan;
        if (!IsExactFacetedShell(
                grossFaces, candidateGross.BrepSolids[0].FaceIndices)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                candidateGross, location, widthFt, bounds,
                out fullGrossPlan, out _, out _, out grossReason)
            || grossReason != "exact")
        {
            rejectionReason = $"gross-validation-{grossReason}";
            return false;
        }

        if (!inverseStartAndBottomTrimmedSpanOnly
            || returnGrossBoundaryForInverseStep)
        {
            grossBoundary = candidateGross;
            serializedAxisPlan = fullGrossPlan;
            rejectionReason = inverseStartAndBottomTrimmedSpanOnly
                ? "exact-inverse-vertical-step-gross-span"
                : "exact-vertical-step";
            return true;
        }

        var trimmedLowOuter = Rectangle(
            lowAlong, lowZ, lowSide.Plane, a1, a2);
        var trimmedHighOuter = Rectangle(
            highAlong, highZ, highSide.Plane, a1, a2);
        var trimmedFaces = new List<GeoFace>
        {
            new() { OuterVertices = trimmedLowOuter },
            new()
            {
                OuterVertices =
                    trimmedHighOuter.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < trimmedLowOuter.Count; index++)
        {
            int next = (index + 1) % trimmedLowOuter.Count;
            trimmedFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    trimmedLowOuter[index], trimmedHighOuter[index],
                    trimmedHighOuter[next], trimmedLowOuter[next],
                ],
            });
        }
        var trimmedPoints = trimmedFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        double[] trimmedBounds =
        [
            trimmedPoints.Min(point => point[0]),
            trimmedPoints.Min(point => point[1]),
            trimmedPoints.Min(point => point[2]),
            trimmedPoints.Max(point => point[0]),
            trimmedPoints.Max(point => point[1]),
            trimmedPoints.Max(point => point[2]),
        ];
        var candidateTrimmed = new GeometryData
        {
            BoundingBox = trimmedBounds,
            Faces = trimmedFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(
                        0, trimmedFaces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        rejectionReason = "trimmed-validation";
        string trimmedReason = "faceted-shell";
        if (!IsExactFacetedShell(
                trimmedFaces, candidateTrimmed.BrepSolids[0].FaceIndices)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                candidateTrimmed, location, widthFt, trimmedBounds,
                out _, out _, out _, out trimmedReason)
            || trimmedReason != "exact")
        {
            rejectionReason = $"trimmed-validation-{trimmedReason}";
            return false;
        }

        grossBoundary = candidateTrimmed;
        serializedAxisPlan = fullGrossPlan;
        rejectionReason = "exact-inverse-vertical-step-trimmed-span";
        return true;
    }

    /// <summary>
    /// A narrower reveal fold is allowed only when the raw closed BRep contains distinct cross-wall
    /// faces at both authored and reveal boundaries.
    /// </summary>
    internal static bool
        TryGetExactEditedWallSketchInverseStepGrossBoundaryAndOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData grossBoundary,
            out IReadOnlyList<(
                RectangularWallThroughOpening Opening, int TagId)> openings)
    {
        grossBoundary = new GeometryData();
        openings = [];
        if (bounds.Count < 6
            || bounds.Take(6).Any(value => !double.IsFinite(value))
            || wall.CuttingElementIds is not { Count: 0 }
            || emittedHostedCutterIdsByWall?.TryGetValue(
                wall.Id, out var emittedIds) == true
                && emittedIds.Count > 0
            || standaloneOpeningIdsByWall?.TryGetValue(
                wall.Id, out var standaloneIds) == true
                && standaloneIds.Count > 0
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || wall.Geometry?.Faces is not { Count: 9 } sourceFaces
            || wall.Geometry.BrepSolids is not { Count: 1 } sourceSolids
            || !sourceSolids[0].IsClosed
            || !sourceSolids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, sourceFaces.Count))
            || sourceFaces.Any(face =>
                face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
            || wall.References is not { Count: > 0 } wallReferences
            || !TryGetAuthoredStraightWallPlan(wall, widthFt, out var plan)
            || plan.Count != 4
            || !WallPlanMatchesSerializedBounds(plan, bounds)
            || !TryGetExactRectangularWallGrossBoundaryFromInverseVerticalStep(
                rebuiltBoundary, location, widthFt, bounds,
                out var confirmedGrossBoundary, out _))
            return false;

        var ownerCandidates = new List<Element>();
        foreach (int referenceId in wallReferences.Distinct())
            if (referenceId != wall.Id
                && elemById.TryGetValue(referenceId, out var candidate)
                && candidate.CategoryId == -2000011
                && candidate.TypeId == wall.Id
                && candidate.FamilyTypeId is not > 0
                && candidate.BoundingBox == null
                && candidate.Geometry?.Faces.Count is not > 0
                && candidate.SketchLoops is { Count: 1 }
                && candidate.References?.Contains(wall.Id) == true)
                ownerCandidates.Add(candidate);
        if (ownerCandidates.Count != 1)
            return false;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
            {
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            }
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }

        Element owner = ownerCandidates[0];
        var ownerRing = CleanRing(owner.SketchLoops![0]);
        if (ownerRing.Count != 6
            || ownerRing.Any(point => point.Length < 3
                || !double.IsFinite(point[0])
                || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        var planNormal = plan
            .Select(point => point[0] * normalX + point[1] * normalY)
            .ToList();
        double minimumNormal = planNormal.Min();
        double maximumNormal = planNormal.Max();
        double centreNormal = (minimumNormal + maximumNormal) / 2;
        double coordinateScale = Math.Max(1.0, ownerRing
            .Concat(rebuiltBoundary.Faces
                .SelectMany(face => face.OuterVertices ?? []))
            .SelectMany(point => point.Take(3))
            .Concat(bounds.Take(6))
            .Select(Math.Abs).DefaultIfEmpty(1).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * coordinateScale;
        bool Equal(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        List<(double Along, double Normal, double Z)> Project(
            IEnumerable<double[]> ring) =>
            ring.Select(point => (
                point[0] * axisX + point[1] * axisY,
                point[0] * normalX + point[1] * normalY,
                point[2])).ToList();

        List<double> Levels(IEnumerable<double> source)
        {
            var levels = new List<double>();
            foreach (double value in source.Order())
                if (levels.Count == 0 || !Equal(levels[^1], value))
                    levels.Add(value);
            return levels;
        }

        bool TryParseInverseProfile(
            IEnumerable<double[]> sourceRing,
            out double plane,
            out double minimumAlong,
            out double foldAlong,
            out double maximumAlong,
            out double minimumZ,
            out double foldZ,
            out double maximumZ)
        {
            plane = minimumAlong = foldAlong = maximumAlong = 0;
            minimumZ = foldZ = maximumZ = 0;
            var ring = CleanRing(sourceRing);
            if (ring.Count != 6
                || ring.Any(point => point.Length < 3
                    || !double.IsFinite(point[0])
                    || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2])))
                return false;
            var projected = Project(ring);
            double minimumPlane = projected.Min(value => value.Normal);
            double maximumPlane = projected.Max(value => value.Normal);
            var alongLevels = Levels(projected.Select(value => value.Along));
            var zLevels = Levels(projected.Select(value => value.Z));
            if (!Equal(minimumPlane, maximumPlane)
                || alongLevels.Count != 3 || zLevels.Count != 3
                || alongLevels.Zip(alongLevels.Skip(1))
                    .Any(pair => !(pair.Second - pair.First > roundoff))
                || zLevels.Zip(zLevels.Skip(1))
                    .Any(pair => !(pair.Second - pair.First > roundoff)))
                return false;

            int LevelIndex(IReadOnlyList<double> levels, double value)
            {
                for (int index = 0; index < levels.Count; index++)
                    if (Equal(levels[index], value)) return index;
                return -1;
            }
            var profile = projected.Select(value => (
                Along: LevelIndex(alongLevels, value.Along),
                Z: LevelIndex(zLevels, value.Z))).ToList();
            if (profile.Any(value => value.Along < 0 || value.Z < 0)
                || profile.Distinct().Count() != 6)
                return false;
            static ((int Along, int Z) First, (int Along, int Z) Second)
                EdgeKey((int Along, int Z) first,
                    (int Along, int Z) second) =>
                first.CompareTo(second) <= 0
                    ? (first, second) : (second, first);
            HashSet<((int Along, int Z) First,
                (int Along, int Z) Second)> CycleEdges(
                    IReadOnlyList<(int Along, int Z)> cycle) =>
                Enumerable.Range(0, cycle.Count)
                    .Select(index => EdgeKey(
                        cycle[index], cycle[(index + 1) % cycle.Count]))
                    .ToHashSet();
            List<(int Along, int Z)> inverseCycle =
            [
                (2, 0), (2, 2), (0, 2),
                (0, 1), (1, 1), (1, 0),
            ];
            if (!CycleEdges(profile).SetEquals(CycleEdges(inverseCycle)))
                return false;

            plane = (minimumPlane + maximumPlane) / 2;
            minimumAlong = alongLevels[0];
            foldAlong = alongLevels[1];
            maximumAlong = alongLevels[2];
            minimumZ = zLevels[0];
            foldZ = zLevels[1];
            maximumZ = zLevels[2];
            return true;
        }

        if (!TryParseInverseProfile(ownerRing,
                out double ownerPlane,
                out double ownerMinimumAlong,
                out double ownerFoldAlong,
                out double ownerMaximumAlong,
                out double ownerMinimumZ,
                out double ownerFoldZ,
                out double ownerMaximumZ)
            || !Equal(ownerPlane, centreNormal)
            || !Equal(ownerMinimumZ, bounds[2])
            || !Equal(ownerMaximumZ, bounds[5]))
            return false;

        var sideProfiles = new List<(double Plane,
            double MinimumAlong, double FoldAlong, double MaximumAlong,
            double MinimumZ, double FoldZ, double MaximumZ)>();
        foreach (GeoFace face in rebuiltBoundary.Faces)
        {
            if (face.OuterVertices is not { Count: >= 6 } outer
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
                continue;
            if (TryParseInverseProfile(outer,
                    out double sidePlane,
                    out double sideMinimumAlong,
                    out double sideFoldAlong,
                    out double sideMaximumAlong,
                    out double sideMinimumZ,
                    out double sideFoldZ,
                    out double sideMaximumZ))
                sideProfiles.Add((sidePlane,
                    sideMinimumAlong, sideFoldAlong, sideMaximumAlong,
                    sideMinimumZ, sideFoldZ, sideMaximumZ));
        }
        sideProfiles = sideProfiles
            .OrderBy(profile => profile.Plane).ToList();
        if (sideProfiles.Count != 2
            || !Equal(sideProfiles[0].Plane, minimumNormal)
            || !Equal(sideProfiles[1].Plane, maximumNormal)
            || !Equal(sideProfiles[0].MinimumAlong,
                sideProfiles[1].MinimumAlong)
            || !Equal(sideProfiles[0].FoldAlong,
                sideProfiles[1].FoldAlong)
            || !Equal(sideProfiles[0].MaximumAlong,
                sideProfiles[1].MaximumAlong)
            || !Equal(sideProfiles[0].MinimumZ,
                sideProfiles[1].MinimumZ)
            || !Equal(sideProfiles[0].FoldZ, sideProfiles[1].FoldZ)
            || !Equal(sideProfiles[0].MaximumZ,
                sideProfiles[1].MaximumZ)
            || !Equal(sideProfiles[0].MinimumAlong, ownerMinimumAlong)
            || !Equal(sideProfiles[0].MaximumAlong, ownerMaximumAlong)
            || !Equal(sideProfiles[0].MinimumZ, ownerMinimumZ)
            || !Equal(sideProfiles[0].FoldZ, ownerFoldZ)
            || !Equal(sideProfiles[0].MaximumZ, ownerMaximumZ)
            || !(sideProfiles[0].FoldAlong
                < ownerFoldAlong - roundoff))
            return false;

        bool TryGetCrossWallFaceAlong(GeoFace face, out double along)
        {
            along = 0;
            var ring = CleanRing(face.OuterVertices ?? []);
            if (ring.Count != 4)
                return false;
            var values = Project(ring);
            double minimumAlong = values.Min(value => value.Along);
            double maximumAlong = values.Max(value => value.Along);
            var normalLevels = Levels(values.Select(value => value.Normal));
            var zLevels = Levels(values.Select(value => value.Z));
            if (!Equal(minimumAlong, maximumAlong)
                || normalLevels.Count != 2 || zLevels.Count != 2
                || !Equal(normalLevels[0], minimumNormal)
                || !Equal(normalLevels[1], maximumNormal)
                || !Equal(zLevels[0], ownerMinimumZ)
                || !Equal(zLevels[1], ownerFoldZ))
                return false;
            var corners = values.Select(value => (
                Normal: Equal(value.Normal, normalLevels[0]) ? 0
                    : Equal(value.Normal, normalLevels[1]) ? 1 : -1,
                Z: Equal(value.Z, zLevels[0]) ? 0
                    : Equal(value.Z, zLevels[1]) ? 1 : -1)).ToList();
            if (corners.Any(value => value.Normal < 0 || value.Z < 0)
                || corners.Distinct().Count() != 4)
                return false;
            along = (minimumAlong + maximumAlong) / 2;
            return true;
        }

        var crossWallFaces = sourceFaces
            .Select(face => TryGetCrossWallFaceAlong(face, out double along)
                ? along : double.NaN)
            .Where(double.IsFinite).ToList();
        if (crossWallFaces.Count != 2
            || !crossWallFaces.Any(value =>
                Equal(value, ownerFoldAlong))
            || !crossWallFaces.Any(value =>
                Equal(value, sideProfiles[0].FoldAlong)))
            return false;

        var tagCandidates = new List<Element>();
        foreach (int referenceId in owner.References?.Distinct() ?? [])
        {
            if (!elemById.TryGetValue(referenceId, out var line)
                || line.CategoryId != -2000045
                || line.HostId != owner.Id
                || line.BoundingBox != null
                || line.Geometry?.Faces.Count is > 0
                || line.References?.Contains(wall.Id) != true
                || line.References?.Contains(owner.Id) != true
                || line.Location is not
                    { CurveType: "Line", ArcRadius: null } lineLocation
                || lineLocation.StartPoint.Length < 3
                || lineLocation.EndPoint.Length < 3)
                continue;
            var endpoints = Project(
                [lineLocation.StartPoint, lineLocation.EndPoint]);
            bool exactHorizontalOpeningCap =
                endpoints.All(value =>
                    Equal(value.Normal, ownerPlane)
                    && Equal(value.Z, ownerFoldZ))
                && (Equal(endpoints[0].Along, ownerMinimumAlong)
                    && Equal(endpoints[1].Along, ownerFoldAlong)
                    || Equal(endpoints[1].Along, ownerMinimumAlong)
                    && Equal(endpoints[0].Along, ownerFoldAlong));
            if (exactHorizontalOpeningCap)
                tagCandidates.Add(line);
        }
        if (tagCandidates.Count != 1)
            return false;

        double openingCentreAlong =
            (ownerMinimumAlong + ownerFoldAlong) / 2;
        grossBoundary = confirmedGrossBoundary;
        openings =
        [
            (
                new RectangularWallThroughOpening(
                    openingCentreAlong * axisX
                        + centreNormal * normalX,
                    openingCentreAlong * axisY
                        + centreNormal * normalY,
                    axisX, axisY,
                    ownerFoldAlong - ownerMinimumAlong,
                    ownerMinimumZ,
                    ownerFoldZ - ownerMinimumZ,
                    minimumNormal, maximumNormal),
                tagCandidates[0].Id
            ),
        ];
        return true;
    }

    /// <summary>
    /// Recovers the vertical extrusion of the unique minimum cap from an exact eight-face wall
    /// shell whose two width-side profiles contain one vertical step at different along positions.
    /// </summary>
    internal static bool
        TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData exactBoundary,
            out string rejectionReason)
    {
        exactBoundary = new GeometryData();
        rejectionReason = "preconditions";
        if (location is not { CurveType: "Line", ArcRadius: null }
            || bounds.Count < 6 || !(widthFt > 0) || !double.IsFinite(widthFt)
            || boundary.Faces is not { Count: 8 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count))
            || !IsExactFacetedShell(faces, solids[0].FaceIndices)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "wall-axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        double coordinateScale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices!)
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Select(Math.Abs).DefaultIfEmpty(1).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 4096 * MachineEpsilon * coordinateScale;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        (long Along, long Z) ProfileKey(double[] point) => (
            IfcPrecisionBinMetres(
                (point[0] * axisX + point[1] * axisY) * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres));
        static ((long Along, long Z) First, (long Along, long Z) Second)
            ProfileEdgeKey((long Along, long Z) first,
                (long Along, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) EdgeKey(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var rings = faces.Select(face => (
            Face: face,
            Ring: CleanRing(face.OuterVertices!))).ToList();
        var sideProfiles = new List<(GeoFace Face, List<double[]> Ring,
            double Plane, HashSet<(long X, long Y, long Z)> Keys,
            HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)> Edges,
            List<long> ZLevels, int Orientation)>();
        foreach (var item in rings.Where(item => item.Ring.Count == 6))
        {
            var planeValues = item.Ring.Select(point =>
                point[0] * normalX + point[1] * normalY).ToList();
            if (planeValues.Max() - planeValues.Min() > roundoff)
                continue;
            var profile = item.Ring.Select(ProfileKey).ToList();
            var alongLevels = profile.Select(key => key.Along)
                .Distinct().Order().ToList();
            var profileZLevels = profile.Select(key => key.Z)
                .Distinct().Order().ToList();
            if (profile.Distinct().Count() != 6
                || alongLevels.Count != 3 || profileZLevels.Count != 3
                || alongLevels.Zip(alongLevels.Skip(1))
                    .Any(pair => pair.Second - pair.First <= 2)
                || profileZLevels.Zip(profileZLevels.Skip(1))
                    .Any(pair => pair.Second - pair.First <= 2))
                continue;
            long a0 = alongLevels[0], a1 = alongLevels[1],
                a2 = alongLevels[2];
            long z0 = profileZLevels[0], z1 = profileZLevels[1],
                z2 = profileZLevels[2];
            List<(long Along, long Z)>[] cycles =
            [
                [
                    (a0, z0), (a2, z0), (a2, z1),
                    (a1, z1), (a1, z2), (a0, z2),
                ],
                [
                    (a2, z0), (a0, z0), (a0, z1),
                    (a1, z1), (a1, z2), (a2, z2),
                ],
                [
                    (a0, z2), (a2, z2), (a2, z1),
                    (a1, z1), (a1, z0), (a0, z0),
                ],
                [
                    (a2, z0), (a2, z2), (a0, z2),
                    (a0, z1), (a1, z1), (a1, z0),
                ],
            ];
            var profileEdges = Enumerable.Range(0, profile.Count)
                .Select(index => ProfileEdgeKey(
                    profile[index], profile[(index + 1) % profile.Count]))
                .ToHashSet();
            var matchingOrientations = cycles
                .Select((cycle, index) => (cycle, index))
                .Where(candidate =>
                    profile.ToHashSet().SetEquals(candidate.cycle)
                    && profileEdges.SetEquals(Enumerable
                        .Range(0, candidate.cycle.Count)
                        .Select(index => ProfileEdgeKey(
                            candidate.cycle[index],
                            candidate.cycle[
                                (index + 1) % candidate.cycle.Count]))))
                .Select(candidate => candidate.index).ToList();
            if (matchingOrientations.Count != 1)
                continue;

            var keys = item.Ring.Select(IfcPrecisionKeyFeet).ToList();
            sideProfiles.Add((
                item.Face, item.Ring,
                (planeValues.Min() + planeValues.Max()) / 2,
                keys.ToHashSet(),
                Enumerable.Range(0, keys.Count).Select(index =>
                    EdgeKey(keys[index], keys[(index + 1) % keys.Count]))
                    .ToHashSet(),
                profileZLevels, matchingOrientations[0]));
        }
        rejectionReason = $"side-profile-count-{sideProfiles.Count}";
        if (sideProfiles.Count != 2)
            return false;
        sideProfiles.Sort((left, right) => left.Plane.CompareTo(right.Plane));
        var lowSide = sideProfiles[0];
        var highSide = sideProfiles[1];
        rejectionReason = "wall-width";
        if (Math.Abs((highSide.Plane - lowSide.Plane) - widthFt) > roundoff)
            return false;
        rejectionReason = "side-step-contract";
        if (lowSide.Orientation != highSide.Orientation
            || !lowSide.ZLevels.SequenceEqual(highSide.ZLevels))
            return false;

        var connectorFaces = rings.Where(item =>
                !ReferenceEquals(item.Face, lowSide.Face)
                && !ReferenceEquals(item.Face, highSide.Face))
            .ToList();
        rejectionReason = "connector-topology";
        if (connectorFaces.Count != 6
            || connectorFaces.Any(item => item.Ring.Count != 4))
            return false;
        var usedLowEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        var usedHighEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        foreach (var connector in connectorFaces)
        {
            var connectorKeys = connector.Ring
                .Select(IfcPrecisionKeyFeet).ToHashSet();
            var lowPoints = connectorKeys.Where(lowSide.Keys.Contains).ToList();
            var highPoints =
                connectorKeys.Where(highSide.Keys.Contains).ToList();
            rejectionReason = "connector-side-membership";
            if (connectorKeys.Count != 4 || lowPoints.Count != 2
                || highPoints.Count != 2)
                return false;
            var lowEdge = EdgeKey(lowPoints[0], lowPoints[1]);
            var highEdge = EdgeKey(highPoints[0], highPoints[1]);
            rejectionReason = "connector-edge-bijection";
            if (!lowSide.Edges.Contains(lowEdge)
                || !highSide.Edges.Contains(highEdge)
                || !usedLowEdges.Add(lowEdge) || !usedHighEdges.Add(highEdge))
                return false;
        }
        rejectionReason = "connector-edge-coverage";
        if (!usedLowEdges.SetEquals(lowSide.Edges)
            || !usedHighEdges.SetEquals(highSide.Edges))
            return false;

        var allKeys = rings.SelectMany(item => item.Ring)
            .Select(IfcPrecisionKeyFeet).Distinct().ToList();
        var zLevels = allKeys.Select(key => key.Z).Distinct().Order().ToList();
        rejectionReason = $"z-levels-{zLevels.Count}";
        if (zLevels.Count != 3
            || zLevels.Zip(zLevels.Skip(1))
                .Any(pair => pair.Second - pair.First <= 2))
            return false;
        long minimumZ = zLevels[0], maximumZ = zLevels[^1];
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        rejectionReason = "serialized-vertical-span";
        if (Math.Abs(minimumZ * IfcGeometryPrecisionMetres / FeetToMetres
                - bounds[2]) > toleranceFt
            || Math.Abs(maximumZ * IfcGeometryPrecisionMetres / FeetToMetres
                - bounds[5]) > toleranceFt)
            return false;

        var minimumCaps = connectorFaces.Where(item =>
                item.Ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == minimumZ))
            .ToList();
        var maximumCaps = connectorFaces.Where(item =>
                item.Ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == maximumZ))
            .ToList();
        rejectionReason =
            $"horizontal-cap-count-{minimumCaps.Count}-{maximumCaps.Count}";
        if (minimumCaps.Count != 1 || maximumCaps.Count != 1)
            return false;
        var lowCap = minimumCaps[0].Ring;
        var highCap = maximumCaps[0].Ring;
        rejectionReason = "horizontal-cap-contract";
        if (lowCap.Select(IfcPrecisionKeyFeet).Distinct().Count() != 4
            || highCap.Select(IfcPrecisionKeyFeet).Distinct().Count() != 4
            || lowCap.Count(point =>
                    lowSide.Keys.Contains(IfcPrecisionKeyFeet(point))) != 2
            || lowCap.Count(point =>
                    highSide.Keys.Contains(IfcPrecisionKeyFeet(point))) != 2
            || highCap.Count(point =>
                    lowSide.Keys.Contains(IfcPrecisionKeyFeet(point))) != 2
            || highCap.Count(point =>
                    highSide.Keys.Contains(IfcPrecisionKeyFeet(point))) != 2)
            return false;

        double lowZFt = lowCap.Average(point => point[2]);
        double highZFt = highCap.Average(point => point[2]);
        var extrudedHighCap = lowCap.Select(point =>
            new[] { point[0], point[1], highZFt }).ToList();
        var exactFaces = new List<GeoFace>
        {
            new() { OuterVertices = lowCap.ToList() },
            new()
            {
                OuterVertices =
                    extrudedHighCap.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < lowCap.Count; index++)
        {
            int next = (index + 1) % lowCap.Count;
            exactFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    lowCap[index], lowCap[next],
                    extrudedHighCap[next], extrudedHighCap[index],
                ],
            });
        }
        var exactFaceIndices = Enumerable.Range(0, exactFaces.Count).ToList();
        rejectionReason = "exact-shell-orientation";
        if (!TryOrientExactFacetedShell(
                exactFaces, exactFaceIndices, out var orientedExactFaces))
            return false;
        var exactPoints = orientedExactFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        double[] exactBounds =
        [
            exactPoints.Min(point => point[0]),
            exactPoints.Min(point => point[1]),
            lowZFt,
            exactPoints.Max(point => point[0]),
            exactPoints.Max(point => point[1]),
            highZFt,
        ];
        var candidate = new GeometryData
        {
            BoundingBox = exactBounds,
            Faces = orientedExactFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = exactFaceIndices,
                    IsClosed = true,
                },
            ],
        };
        rejectionReason = "exact-minimum-cap-extrusion";
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                candidate, location, widthFt, exactBounds,
                out _, out _, out _, out string exactReason)
            || exactReason != "exact")
        {
            rejectionReason += $"-{exactReason}";
            return false;
        }

        exactBoundary = candidate;
        rejectionReason = "exact-open-stepped-minimum-cap-shell";
        return true;
    }

    /// <summary>
    /// Recovers the minimum-cap extrusion of the exact complete open twelve-face join shell when
    /// the serialized location curve is itself trimmed or offset by the join.
    /// </summary>
    internal static bool
        TryGetExactVerticalWallBoundaryFromCompleteOpenTwelveFaceMinimumCapShell(
            Element wall, GeometryData boundary,
            IReadOnlyList<double> bounds,
            out GeometryData exactBoundary,
            out LocationCurve exactLocation,
            out string rejectionReason)
    {
        exactBoundary = new GeometryData();
        exactLocation = new LocationCurve();
        rejectionReason = "source-authority";
        if (!HasExactCompleteOpenTwelveFaceNoAlternativeSourceAuthority(
                wall.Geometry)
            || !TryGetSerializedWallWidthFeet(
                wall, out double wallWidthFt)
            || bounds.Count < 6
            || bounds.Take(6).Any(value => !double.IsFinite(value))
            || wall.Geometry?.BoundingBox is not
                { Length: 6 } sourceBounds
            || IfcPrecisionKeyFeet(
                    [sourceBounds[0], sourceBounds[1], sourceBounds[2]])
                != IfcPrecisionKeyFeet(
                    [bounds[0], bounds[1], bounds[2]])
            || IfcPrecisionKeyFeet(
                    [sourceBounds[3], sourceBounds[4], sourceBounds[5]])
                != IfcPrecisionKeyFeet(
                    [bounds[3], bounds[4], bounds[5]])
            || boundary.Faces is not { Count: 8 } faces)
            return false;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }

        var rings = faces.Select(face =>
                CleanRing(face.OuterVertices ?? []))
            .ToList();
        if (rings.Any(ring => ring.Count < 3))
        {
            rejectionReason = "rebuilt-rings";
            return false;
        }
        var allKeys = rings.SelectMany(ring => ring)
            .Select(IfcPrecisionKeyFeet).ToList();
        long minimumZ = allKeys.Min(key => key.Z);
        long maximumZ = allKeys.Max(key => key.Z);
        var lowerCaps = rings.Where(ring =>
                ring.Count == 4
                && ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == minimumZ))
            .ToList();
        var upperCaps = rings.Where(ring =>
                ring.Count == 4
                && ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == maximumZ))
            .ToList();
        if (lowerCaps.Count != 1 || upperCaps.Count != 1)
        {
            rejectionReason =
                $"horizontal-cap-count-{lowerCaps.Count}-{upperCaps.Count}";
            return false;
        }

        bool TryGetRectangleLocation(List<double[]> cap,
            out LocationCurve location, out long axisLengthBin)
        {
            location = new LocationCurve();
            axisLengthBin = 0;
            var edges = Enumerable.Range(0, cap.Count)
                .Select(index =>
                {
                    double[] first = cap[index];
                    double[] second = cap[(index + 1) % cap.Count];
                    double dx = second[0] - first[0];
                    double dy = second[1] - first[1];
                    double length = Math.Sqrt(dx * dx + dy * dy);
                    return (Index: index, First: first, Second: second,
                        Dx: dx, Dy: dy, Length: length,
                        LengthBin: IfcPrecisionBinMetres(
                            length * FeetToMetres));
                }).ToList();
            long widthBin = IfcPrecisionBinMetres(
                wallWidthFt * FeetToMetres);
            var widthEdges = edges.Where(edge =>
                edge.LengthBin == widthBin).ToList();
            var axisEdges = edges.Where(edge =>
                edge.LengthBin != widthBin).ToList();
            if (widthEdges.Count != 2 || axisEdges.Count != 2
                || Math.Abs(widthEdges[0].Index - widthEdges[1].Index) != 2
                || Math.Abs(axisEdges[0].Index - axisEdges[1].Index) != 2
                || axisEdges[0].LengthBin != axisEdges[1].LengthBin
                || axisEdges[0].LengthBin <= widthBin + 2)
                return false;

            const double MachineEpsilon = 2.2204460492503131e-16;
            double coordinateScale = Math.Max(1.0, cap
                .SelectMany(point => point.Take(2))
                .Append(wallWidthFt).Select(Math.Abs).Max());
            double vectorRoundoff = 4096 * MachineEpsilon
                * coordinateScale * coordinateScale;
            double Cross(
                (int Index, double[] First, double[] Second,
                    double Dx, double Dy, double Length, long LengthBin) first,
                (int Index, double[] First, double[] Second,
                    double Dx, double Dy, double Length, long LengthBin) second) =>
                first.Dx * second.Dy - first.Dy * second.Dx;
            double Dot(
                (int Index, double[] First, double[] Second,
                    double Dx, double Dy, double Length, long LengthBin) first,
                (int Index, double[] First, double[] Second,
                    double Dx, double Dy, double Length, long LengthBin) second) =>
                first.Dx * second.Dx + first.Dy * second.Dy;
            if (Math.Abs(Cross(widthEdges[0], widthEdges[1]))
                    > vectorRoundoff
                || Math.Abs(Cross(axisEdges[0], axisEdges[1]))
                    > vectorRoundoff
                || Math.Abs(Dot(widthEdges[0], axisEdges[0]))
                    > vectorRoundoff)
                return false;

            double[] Centre(
                (int Index, double[] First, double[] Second,
                    double Dx, double Dy, double Length, long LengthBin) edge) =>
            [
                (edge.First[0] + edge.Second[0]) / 2,
                (edge.First[1] + edge.Second[1]) / 2,
                bounds[2],
            ];
            double[] start = Centre(widthEdges[0]);
            double[] end = Centre(widthEdges[1]);
            double centreLineLength = Math.Sqrt(
                Math.Pow(end[0] - start[0], 2)
                + Math.Pow(end[1] - start[1], 2));
            if (IfcPrecisionBinMetres(
                    centreLineLength * FeetToMetres)
                != axisEdges[0].LengthBin)
                return false;

            location = new LocationCurve
            {
                CurveType = "Line",
                StartPoint = start,
                EndPoint = end,
            };
            axisLengthBin = axisEdges[0].LengthBin;
            return true;
        }

        if (!TryGetRectangleLocation(lowerCaps[0],
                out LocationCurve lowerLocation,
                out long lowerAxisLengthBin)
            || !TryGetRectangleLocation(upperCaps[0],
                out LocationCurve upperLocation,
                out long upperAxisLengthBin))
        {
            rejectionReason = "horizontal-cap-rectangle";
            return false;
        }
        if (Math.Abs(lowerAxisLengthBin - upperAxisLengthBin) <= 2)
        {
            rejectionReason = "minimum-plan-cap-not-unique";
            return false;
        }

        if (!TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
                boundary, lowerLocation, wallWidthFt, bounds,
                out GeometryData lowerBoundary, out string boundaryReason))
        {
            rejectionReason = $"minimum-cap-shell-{boundaryReason}";
            return false;
        }
        if (lowerAxisLengthBin < upperAxisLengthBin)
        {
            exactBoundary = lowerBoundary;
            exactLocation = lowerLocation;
            rejectionReason =
                "exact-complete-open-twelve-face-minimum-plan-cap-shell";
            return true;
        }

        if (lowerBoundary.BoundingBox is not { Length: 6 } lowerBounds)
        {
            rejectionReason = "lower-boundary-bounds";
            return false;
        }
        double lowZFt = lowerBounds[2];
        double highZFt = lowerBounds[5];
        var lowerPlan = upperCaps[0].Select(point =>
            new[] { point[0], point[1], lowZFt }).ToList();
        var upperPlan = upperCaps[0].Select(point =>
            new[] { point[0], point[1], highZFt }).ToList();
        var exactFaces = new List<GeoFace>
        {
            new() { OuterVertices = lowerPlan },
            new()
            {
                OuterVertices = upperPlan.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < lowerPlan.Count; index++)
        {
            int next = (index + 1) % lowerPlan.Count;
            exactFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    lowerPlan[index], lowerPlan[next],
                    upperPlan[next], upperPlan[index],
                ],
            });
        }
        var exactFaceIndices = Enumerable.Range(0, exactFaces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                exactFaces, exactFaceIndices, out var orientedExactFaces))
        {
            rejectionReason = "minimum-plan-cap-shell-orientation";
            return false;
        }
        var exactPoints = orientedExactFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        double[] exactBounds =
        [
            exactPoints.Min(point => point[0]),
            exactPoints.Min(point => point[1]),
            lowZFt,
            exactPoints.Max(point => point[0]),
            exactPoints.Max(point => point[1]),
            highZFt,
        ];
        var candidate = new GeometryData
        {
            BoundingBox = exactBounds,
            Faces = orientedExactFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = exactFaceIndices,
                    IsClosed = true,
                },
            ],
        };
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                candidate, upperLocation, wallWidthFt, exactBounds,
                out _, out _, out _, out string exactReason)
            || exactReason != "exact")
        {
            rejectionReason =
                $"minimum-plan-cap-extrusion-{exactReason}";
            return false;
        }

        exactBoundary = candidate;
        exactLocation = upperLocation;
        rejectionReason =
            "exact-complete-open-twelve-face-minimum-plan-cap-shell";
        return true;
    }

    /// <summary>
    /// Recovers a constant vertical wall extrusion from the exact closed shell produced when one
    /// horizontal cap is split into two or three collinear quads.
    /// </summary>
    internal static bool
        TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, HostedOpeningGeometry operand,
            out GeometryData exactBoundary, out string rejectionReason)
        => TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
            boundary, location, widthFt, bounds, operand,
            out exactBoundary, out _, out rejectionReason);

    internal static bool
        TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, HostedOpeningGeometry operand,
            out GeometryData exactBoundary, out int matchedSubdivisionCount,
            out string rejectionReason,
            bool retainMatchedOpeningSubdivisions = true)
    {
        exactBoundary = new GeometryData();
        matchedSubdivisionCount = 0;
        rejectionReason = "preconditions";
        if (location is not { CurveType: "Line", ArcRadius: null }
            || bounds.Count < 6 || !(widthFt > 0) || !double.IsFinite(widthFt))
            return false;
        rejectionReason = "shell-topology";
        if (boundary.Faces is not { Count: 7 or 8 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count)))
            return false;
        rejectionReason = "shell-authority";
        if (!IsExactFacetedShell(faces, solids[0].FaceIndices)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || face.OuterVertices.Any(point =>
                    point.Length < 3
                    || !double.IsFinite(point[0])
                    || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2]))
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        HostedOpeningGeometry profileOperand = operand;
        bool convertedFromBrep = operand.Boundary is not null;
        rejectionReason = "opening-prism";
        if (convertedFromBrep
            && !TryGetExactVerticalRectangularPrismSweptOpening(
                operand.Boundary, out profileOperand)
            && !TryGetExactSteppedOpeningSweptBoxForWall(
                operand.Boundary, location, widthFt, out profileOperand))
            return false;
        rejectionReason = "opening-definition";
        if (!profileOperand.ExactDepth
            || !(profileOperand.WidthFt > 0)
            || !(profileOperand.DepthFt > 0)
            || !(profileOperand.HeightFt > 0)
            || !double.IsFinite(profileOperand.CentreXFt)
            || !double.IsFinite(profileOperand.CentreYFt)
            || !double.IsFinite(profileOperand.AxisX)
            || !double.IsFinite(profileOperand.AxisY)
            || !double.IsFinite(profileOperand.WidthFt)
            || !double.IsFinite(profileOperand.DepthFt)
            || !double.IsFinite(profileOperand.BaseZFt)
            || !double.IsFinite(profileOperand.HeightFt))
            return false;
        double openingAxisLength = Math.Sqrt(
            profileOperand.AxisX * profileOperand.AxisX
            + profileOperand.AxisY * profileOperand.AxisY);
        rejectionReason = "wall-opening-axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength)
            || !(openingAxisLength > 0)
            || !double.IsFinite(openingAxisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        double openingAxisX = profileOperand.AxisX / openingAxisLength;
        double openingAxisY = profileOperand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        if (Math.Abs(openingAxisX * axisY - openingAxisY * axisX)
                > 4096 * MachineEpsilon
            && Math.Abs(openingAxisX * axisX + openingAxisY * axisY)
                <= 4096 * MachineEpsilon)
        {
            profileOperand = profileOperand with
            {
                AxisX = -openingAxisY,
                AxisY = openingAxisX,
                WidthFt = profileOperand.DepthFt,
                DepthFt = profileOperand.WidthFt,
            };
            openingAxisX = profileOperand.AxisX;
            openingAxisY = profileOperand.AxisY;
        }
        if (Math.Abs(openingAxisX * axisY - openingAxisY * axisX)
                > 4096 * MachineEpsilon)
        {
            rejectionReason = "opening-axis-alignment";
            return false;
        }
        double coordinateScale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices!)
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Select(Math.Abs).DefaultIfEmpty(1).Max());
        double roundoff = 4096 * MachineEpsilon * coordinateScale;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        (long Along, long Z) ProfileKey(double[] point) => (
            IfcPrecisionBinMetres(
                (point[0] * axisX + point[1] * axisY) * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres));
        static ((long Along, long Z) First, (long Along, long Z) Second)
            ProfileEdgeKey((long Along, long Z) first,
                (long Along, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) EdgeKey(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var rings = faces.Select(face => (
            Face: face, Ring: CleanRing(face.OuterVertices!))).ToList();
        var sideProfiles = new List<(GeoFace Face, List<double[]> Ring,
            double Plane, HashSet<(long X, long Y, long Z)> Keys,
            HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)> Edges,
            long SplitZ, long IntactZ, List<double[]> SplitPoints,
            List<double[]> IntactPoints)>();
        foreach (var item in rings.Where(item =>
                     item.Ring.Count is 5 or 6))
        {
            var planeValues = item.Ring.Select(point =>
                point[0] * normalX + point[1] * normalY).ToList();
            if (planeValues.Max() - planeValues.Min() > roundoff)
                continue;
            var profile = item.Ring.Select(ProfileKey).ToList();
            var zGroups = item.Ring.GroupBy(point => ProfileKey(point).Z)
                .OrderBy(group => group.Key).ToList();
            int profileVertexCount = item.Ring.Count;
            int profileSplitPointCount = profileVertexCount - 2;
            if (profile.Distinct().Count() != profileVertexCount
                || zGroups.Count != 2
                || !zGroups.Select(group => group.Count()).Order()
                    .SequenceEqual([2, profileSplitPointCount]))
                continue;
            var splitGroup = zGroups.Single(group =>
                group.Count() == profileSplitPointCount);
            var intactGroup = zGroups.Single(group => group.Count() == 2);
            var splitPoints = splitGroup.ToList();
            var intactPoints = intactGroup.ToList();
            var splitAlong = splitPoints.Select(point =>
                    ProfileKey(point).Along)
                .Distinct().Order().ToList();
            var intactAlong = intactPoints.Select(point =>
                    ProfileKey(point).Along)
                .Distinct().Order().ToList();
            if (splitAlong.Count != profileSplitPointCount
                || intactAlong.Count != 2
                || splitAlong[0] != intactAlong[0]
                || splitAlong[^1] != intactAlong[^1]
                || splitAlong.Zip(splitAlong.Skip(1))
                    .Any(pair => pair.Second - pair.First <= 2))
                continue;

            var profileEdges = Enumerable.Range(0, profile.Count)
                .Select(index => ProfileEdgeKey(
                    profile[index], profile[(index + 1) % profile.Count]))
                .ToHashSet();
            var expectedProfileEdges = new HashSet<(
                (long Along, long Z) First,
                (long Along, long Z) Second)>();
            for (int index = 0; index + 1 < splitAlong.Count; index++)
                expectedProfileEdges.Add(ProfileEdgeKey(
                    (splitAlong[index], splitGroup.Key),
                    (splitAlong[index + 1], splitGroup.Key)));
            expectedProfileEdges.Add(ProfileEdgeKey(
                (intactAlong[0], intactGroup.Key),
                (intactAlong[1], intactGroup.Key)));
            expectedProfileEdges.Add(ProfileEdgeKey(
                (intactAlong[0], intactGroup.Key),
                (splitAlong[0], splitGroup.Key)));
            expectedProfileEdges.Add(ProfileEdgeKey(
                (intactAlong[1], intactGroup.Key),
                (splitAlong[^1], splitGroup.Key)));
            if (!profileEdges.SetEquals(expectedProfileEdges))
                continue;

            var keys = item.Ring.Select(IfcPrecisionKeyFeet).ToList();
            sideProfiles.Add((
                item.Face, item.Ring,
                (planeValues.Min() + planeValues.Max()) / 2,
                keys.ToHashSet(),
                Enumerable.Range(0, keys.Count).Select(index =>
                    EdgeKey(keys[index], keys[(index + 1) % keys.Count]))
                    .ToHashSet(),
                splitGroup.Key, intactGroup.Key, splitPoints, intactPoints));
        }
        rejectionReason = $"side-profile-count-{sideProfiles.Count}";
        if (sideProfiles.Count != 2)
            return false;
        sideProfiles.Sort((left, right) => left.Plane.CompareTo(right.Plane));
        var lowSide = sideProfiles[0];
        var highSide = sideProfiles[1];
        rejectionReason = "wall-width";
        if (Math.Abs((highSide.Plane - lowSide.Plane) - widthFt) > roundoff)
            return false;
        rejectionReason = "side-profile-contract";
        if (lowSide.SplitZ != highSide.SplitZ
            || lowSide.IntactZ != highSide.IntactZ)
            return false;

        var connectorFaces = rings.Where(item =>
                !ReferenceEquals(item.Face, lowSide.Face)
                && !ReferenceEquals(item.Face, highSide.Face))
            .ToList();
        rejectionReason = "connector-topology";
        int splitPointCount = lowSide.SplitPoints.Count;
        if (splitPointCount is not (3 or 4)
            || highSide.SplitPoints.Count != splitPointCount
            || connectorFaces.Count != splitPointCount + 2
            || connectorFaces.Any(item => item.Ring.Count != 4))
            return false;
        var usedLowEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        var usedHighEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        foreach (var connector in connectorFaces)
        {
            var connectorKeys = connector.Ring
                .Select(IfcPrecisionKeyFeet).ToHashSet();
            var lowPoints = connectorKeys.Where(lowSide.Keys.Contains).ToList();
            var highPoints =
                connectorKeys.Where(highSide.Keys.Contains).ToList();
            rejectionReason = "connector-side-membership";
            if (connectorKeys.Count != 4 || lowPoints.Count != 2
                || highPoints.Count != 2)
                return false;
            var lowEdge = EdgeKey(lowPoints[0], lowPoints[1]);
            var highEdge = EdgeKey(highPoints[0], highPoints[1]);
            rejectionReason = "connector-edge-bijection";
            if (!lowSide.Edges.Contains(lowEdge)
                || !highSide.Edges.Contains(highEdge)
                || !usedLowEdges.Add(lowEdge) || !usedHighEdges.Add(highEdge))
                return false;
        }
        rejectionReason = "connector-edge-coverage";
        if (!usedLowEdges.SetEquals(lowSide.Edges)
            || !usedHighEdges.SetEquals(highSide.Edges))
            return false;

        var allPoints = rings.SelectMany(item => item.Ring).ToList();
        var zLevels = allPoints.Select(IfcPrecisionKeyFeet)
            .Select(key => key.Z).Distinct().Order().ToList();
        rejectionReason = $"z-levels-{zLevels.Count}";
        if (zLevels.Count != 2 || zLevels[0] != Math.Min(
                lowSide.SplitZ, lowSide.IntactZ)
            || zLevels[1] != Math.Max(lowSide.SplitZ, lowSide.IntactZ)
            || zLevels[1] - zLevels[0] <= 2)
            return false;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        double lowZFt = allPoints
            .Where(point => IfcPrecisionKeyFeet(point).Z == zLevels[0])
            .Average(point => point[2]);
        double highZFt = allPoints
            .Where(point => IfcPrecisionKeyFeet(point).Z == zLevels[1])
            .Average(point => point[2]);
        rejectionReason = "serialized-vertical-span";
        if (Math.Abs(lowZFt - bounds[2]) > toleranceFt
            || Math.Abs(highZFt - bounds[5]) > toleranceFt)
            return false;

        var splitCaps = connectorFaces.Where(item =>
                item.Ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == lowSide.SplitZ))
            .ToList();
        var intactCaps = connectorFaces.Where(item =>
                item.Ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == lowSide.IntactZ))
            .ToList();
        rejectionReason =
            $"horizontal-cap-count-{splitCaps.Count}-{intactCaps.Count}";
        if (splitCaps.Count != splitPointCount - 1
            || intactCaps.Count != 1)
            return false;
        static (long X, long Y) PlanKey(double[] point)
        {
            var key = IfcPrecisionKeyFeet(point);
            return (key.X, key.Y);
        }
        var lowSplitPoints = lowSide.SplitPoints
            .OrderBy(point => ProfileKey(point).Along).ToList();
        var highSplitPoints = highSide.SplitPoints
            .OrderBy(point => ProfileKey(point).Along).ToList();
        var lowIntactEndpointKeys = lowSide.IntactPoints
            .Select(PlanKey).ToHashSet();
        var highIntactEndpointKeys = highSide.IntactPoints
            .Select(PlanKey).ToHashSet();
        var splitEndpointKeys = new[]
        {
            lowSplitPoints[0], lowSplitPoints[^1],
            highSplitPoints[0], highSplitPoints[^1],
        }.Select(PlanKey).ToHashSet();
        var intactCapPlanKeys =
            intactCaps[0].Ring.Select(PlanKey).ToHashSet();
        rejectionReason = "intact-cap-contract";
        if (intactCapPlanKeys.Count != 4
            || lowIntactEndpointKeys.Count != 2
            || highIntactEndpointKeys.Count != 2
            || lowIntactEndpointKeys.Overlaps(highIntactEndpointKeys)
            || !intactCapPlanKeys.SetEquals(
                lowIntactEndpointKeys.Concat(highIntactEndpointKeys))
            || !intactCapPlanKeys.SetEquals(splitEndpointKeys))
            return false;

        var splitCapEdgeCounts = new Dictionary<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second), int>();
        foreach (var splitCap in splitCaps)
        {
            rejectionReason = "split-cap-contract";
            var keys = splitCap.Ring
                .Select(IfcPrecisionKeyFeet).ToList();
            if (keys.Distinct().Count() != 4)
                return false;
            for (int index = 0; index < keys.Count; index++)
            {
                var edge = EdgeKey(
                    keys[index], keys[(index + 1) % keys.Count]);
                splitCapEdgeCounts[edge] =
                    splitCapEdgeCounts.GetValueOrDefault(edge) + 1;
            }
        }
        var expectedBoundaryEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        foreach (var splitSidePoints in new[]
                 {
                     lowSplitPoints, highSplitPoints,
                 })
            for (int index = 0;
                 index + 1 < splitSidePoints.Count; index++)
                expectedBoundaryEdges.Add(EdgeKey(
                    IfcPrecisionKeyFeet(splitSidePoints[index]),
                    IfcPrecisionKeyFeet(splitSidePoints[index + 1])));
        expectedBoundaryEdges.Add(EdgeKey(
            IfcPrecisionKeyFeet(lowSplitPoints[0]),
            IfcPrecisionKeyFeet(highSplitPoints[0])));
        expectedBoundaryEdges.Add(EdgeKey(
            IfcPrecisionKeyFeet(lowSplitPoints[^1]),
            IfcPrecisionKeyFeet(highSplitPoints[^1])));
        var expectedInternalEdges = Enumerable.Range(
                1, splitPointCount - 2)
            .Select(index => EdgeKey(
                IfcPrecisionKeyFeet(lowSplitPoints[index]),
                IfcPrecisionKeyFeet(highSplitPoints[index])))
            .ToHashSet();
        var actualBoundaryEdges = splitCapEdgeCounts
            .Where(item => item.Value == 1)
            .Select(item => item.Key).ToHashSet();
        var actualInternalEdges = splitCapEdgeCounts
            .Where(item => item.Value == 2)
            .Select(item => item.Key).ToHashSet();
        rejectionReason = "split-cap-coverage";
        if (splitCapEdgeCounts.Values.Any(count => count is not (1 or 2))
            || !actualBoundaryEdges.SetEquals(expectedBoundaryEdges)
            || !actualInternalEdges.SetEquals(expectedInternalEdges))
            return false;

        double openingCentreAlongFt =
            profileOperand.CentreXFt * axisX
            + profileOperand.CentreYFt * axisY;
        var openingEndBins = new HashSet<long>
        {
            IfcPrecisionBinMetres(
                (openingCentreAlongFt - profileOperand.WidthFt / 2)
                * FeetToMetres),
            IfcPrecisionBinMetres(
                (openingCentreAlongFt + profileOperand.WidthFt / 2)
                * FeetToMetres),
        };
        var highIntactPoints = highSide.IntactPoints
            .OrderBy(point => ProfileKey(point).Along).ToList();
        var highSplitAlong = highSide.SplitPoints
            .Select(point => ProfileKey(point).Along)
            .Distinct().Order().ToList();
        var matchedHighSideSubdivisions = highSide.SplitPoints
            .Where(point =>
            {
                long along = ProfileKey(point).Along;
                return along != highSplitAlong[0]
                    && along != highSplitAlong[^1]
                    && openingEndBins.Contains(along);
            })
            .GroupBy(point => ProfileKey(point).Along)
            .Select(group => group.First())
            .OrderByDescending(point => ProfileKey(point).Along)
            .ToList();
        var selectedHighSideSubdivisions =
            retainMatchedOpeningSubdivisions
                ? matchedHighSideSubdivisions : [];
        var lowIntactPoints = lowSide.IntactPoints
            .OrderBy(point => ProfileKey(point).Along).ToList();
        rejectionReason = "intact-side-endpoints";
        if (lowIntactPoints.Count != 2 || highIntactPoints.Count != 2)
            return false;
        var plan =
            new List<double[]>(4 + selectedHighSideSubdivisions.Count)
            {
                new[] { lowIntactPoints[0][0], lowIntactPoints[0][1] },
                new[] { lowIntactPoints[1][0], lowIntactPoints[1][1] },
                new[] { highIntactPoints[1][0], highIntactPoints[1][1] },
            };
        plan.AddRange(selectedHighSideSubdivisions.Select(point =>
            new[] { point[0], point[1] }));
        plan.Add(
            new[] { highIntactPoints[0][0], highIntactPoints[0][1] });
        if (splitPointCount == 3
            && selectedHighSideSubdivisions.Count == 0)
        {
            var planAlong = plan.Select(point =>
                point[0] * axisX + point[1] * axisY).ToList();
            var planAcross = plan.Select(point =>
                point[0] * normalX + point[1] * normalY).ToList();
            double minimumAlong = planAlong.Min();
            double maximumAlong = planAlong.Max();
            double minimumAcross = planAcross.Min();
            double maximumAcross = planAcross.Max();
            double[] WorldPlanPoint(double along, double across) =>
            [
                along * axisX + across * normalX,
                along * axisY + across * normalY,
            ];
            var latticeRectangle =
                new List<double[]>
                {
                    WorldPlanPoint(minimumAlong, minimumAcross),
                    WorldPlanPoint(maximumAlong, minimumAcross),
                    WorldPlanPoint(maximumAlong, maximumAcross),
                    WorldPlanPoint(minimumAlong, maximumAcross),
                };
            static (long X, long Y) PlanPrecisionKey(double[] point) => (
                IfcPrecisionBinMetres(point[0] * FeetToMetres),
                IfcPrecisionBinMetres(point[1] * FeetToMetres));
            if (plan.Select(PlanPrecisionKey).ToHashSet().SetEquals(
                    latticeRectangle.Select(PlanPrecisionKey))
                && WallPlanMatchesSerializedBoundsAtIfcPrecision(
                    latticeRectangle, bounds))
            {
                // Do so only when every authored corner is in a one-to-one IFC-lattice bin with
                // that rectangle; a genuine miter or join remains distinct.
                plan = latticeRectangle;
            }
        }

        var minimumCap = plan.Select(point =>
            new[] { point[0], point[1], lowZFt }).ToList();
        var maximumCap = plan.Select(point =>
            new[] { point[0], point[1], highZFt }).ToList();
        var exactFaces = new List<GeoFace>
        {
            new() { OuterVertices = minimumCap },
            new()
            {
                OuterVertices =
                    maximumCap.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < minimumCap.Count; index++)
        {
            int next = (index + 1) % minimumCap.Count;
            exactFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    minimumCap[index], minimumCap[next],
                    maximumCap[next], maximumCap[index],
                ],
            });
        }
        var exactFaceIndices = Enumerable.Range(0, exactFaces.Count).ToList();
        rejectionReason = "exact-shell-orientation";
        if (!TryOrientExactFacetedShell(
                exactFaces, exactFaceIndices, out var orientedExactFaces,
                triangulateNonPlanarFaces: false))
            return false;
        var exactPoints = orientedExactFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        double[] exactBounds =
        [
            exactPoints.Min(point => point[0]),
            exactPoints.Min(point => point[1]),
            lowZFt,
            exactPoints.Max(point => point[0]),
            exactPoints.Max(point => point[1]),
            highZFt,
        ];
        var candidate = new GeometryData
        {
            BoundingBox = exactBounds,
            Faces = orientedExactFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = exactFaceIndices,
                    IsClosed = true,
                },
            ],
        };
        rejectionReason = "exact-vertical-definition";
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                candidate, location, widthFt, bounds,
                out var verifiedPlan, out _, out _, out string exactReason)
            || exactReason is not ("exact"
                or "exact-collinear-boundary-subdivision")
            || verifiedPlan.Count != plan.Count)
        {
            rejectionReason += $"-{exactReason}";
            return false;
        }

        exactBoundary = candidate;
        matchedSubdivisionCount =
            matchedHighSideSubdivisions.Count;
        rejectionReason =
            $"exact-single-collinear-cap-subdivision-"
            + $"{matchedSubdivisionCount}";
        return true;
    }

    /// <summary>
    /// Recovers the exact four-corner gross from the separate seven-face shell whose paired
    /// five-vertex exterior profiles contain one matching strict collinear subdivision on a
    /// vertical end edge.
    /// </summary>
    internal static bool
        TryGetExactVerticalWallBoundaryFromSingleCollinearVerticalEdgeSubdivisionShell(
            GeometryData boundary, LocationCurve location, double widthFt,
            IReadOnlyList<double> bounds, out GeometryData exactBoundary,
            out string rejectionReason)
    {
        exactBoundary = new GeometryData();
        rejectionReason = "preconditions";
        if (location is not { CurveType: "Line", ArcRadius: null }
            || bounds.Count < 6 || !(widthFt > 0) || !double.IsFinite(widthFt))
            return false;
        rejectionReason = "shell-topology";
        if (boundary.Faces is not { Count: 7 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, faces.Count)))
            return false;
        rejectionReason = "shell-authority";
        if (!IsExactFacetedShell(faces, solids[0].FaceIndices)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 }
                || face.OuterVertices.Any(point =>
                    point.Length < 3
                    || !double.IsFinite(point[0])
                    || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2]))
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        rejectionReason = "axis";
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = dx / axisLength, axisY = dy / axisLength;
        double normalX = -axisY, normalY = axisX;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double coordinateScale = Math.Max(1.0, faces
            .SelectMany(face => face.OuterVertices!)
            .SelectMany(point => point.Take(3))
            .Append(widthFt).Select(Math.Abs).DefaultIfEmpty(1).Max());
        double roundoff = 4096 * MachineEpsilon * coordinateScale;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        (long Along, long Z) ProfileKey(double[] point) => (
            IfcPrecisionBinMetres(
                (point[0] * axisX + point[1] * axisY) * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres));
        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) EdgeKey(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0 ? (first, second) : (second, first);

        var rings = faces.Select(face => (
            Face: face, Ring: CleanRing(face.OuterVertices!))).ToList();
        var sideProfiles = new List<(GeoFace Face, List<double[]> Ring,
            double Plane, HashSet<(long X, long Y, long Z)> Keys,
            HashSet<((long X, long Y, long Z) First,
                (long X, long Y, long Z) Second)> Edges,
            long MinimumZ, long MaximumZ, long SubdivisionZ)>();
        foreach (var item in rings.Where(item => item.Ring.Count == 5))
        {
            var planeValues = item.Ring.Select(point =>
                point[0] * normalX + point[1] * normalY).ToList();
            if (planeValues.Max() - planeValues.Min() > roundoff)
                continue;
            var profile = item.Ring.Select(ProfileKey).ToList();
            var alongGroups = profile.GroupBy(point => point.Along)
                .OrderBy(group => group.Key).ToList();
            var zGroups = profile.GroupBy(point => point.Z)
                .OrderBy(group => group.Key).ToList();
            if (profile.Distinct().Count() != 5
                || alongGroups.Count != 2
                || !alongGroups.Select(group => group.Count()).Order()
                    .SequenceEqual([2, 3])
                || zGroups.Count != 3
                || !zGroups.Select(group => group.Count()).Order()
                    .SequenceEqual([1, 2, 2]))
                continue;
            long minimumZ = zGroups[0].Key;
            long maximumZ = zGroups[^1].Key;
            var splitGroup = alongGroups.Single(group => group.Count() == 3);
            var intactGroup = alongGroups.Single(group => group.Count() == 2);
            var splitZ = splitGroup.Select(point => point.Z)
                .Distinct().Order().ToList();
            var intactZ = intactGroup.Select(point => point.Z)
                .Distinct().Order().ToList();
            if (splitZ.Count != 3 || intactZ.Count != 2
                || splitZ[0] != minimumZ || splitZ[^1] != maximumZ
                || intactZ[0] != minimumZ || intactZ[^1] != maximumZ
                || splitZ[1] - splitZ[0] <= 2
                || splitZ[2] - splitZ[1] <= 2
                || zGroups[1].Count() != 1
                || zGroups[1].Single().Along != splitGroup.Key)
                continue;
            var profileEdges = Enumerable.Range(0, profile.Count)
                .Select(index =>
                {
                    var first = profile[index];
                    var second = profile[(index + 1) % profile.Count];
                    return first.CompareTo(second) <= 0
                        ? (first, second) : (second, first);
                }).ToHashSet();
            var expectedEdges = new HashSet<(
                (long Along, long Z) First,
                (long Along, long Z) Second)>
            {
                ((splitGroup.Key, splitZ[0]),
                    (splitGroup.Key, splitZ[1])),
                ((splitGroup.Key, splitZ[1]),
                    (splitGroup.Key, splitZ[2])),
                ((intactGroup.Key, minimumZ),
                    (intactGroup.Key, maximumZ)),
            };
            foreach (long z in new[] { minimumZ, maximumZ })
            {
                var first = (splitGroup.Key, z);
                var second = (intactGroup.Key, z);
                expectedEdges.Add(first.CompareTo(second) <= 0
                    ? (first, second) : (second, first));
            }
            if (!profileEdges.SetEquals(expectedEdges))
                continue;

            var keys = item.Ring.Select(IfcPrecisionKeyFeet).ToList();
            sideProfiles.Add((
                item.Face, item.Ring,
                (planeValues.Min() + planeValues.Max()) / 2,
                keys.ToHashSet(),
                Enumerable.Range(0, keys.Count).Select(index =>
                    EdgeKey(keys[index], keys[(index + 1) % keys.Count]))
                    .ToHashSet(),
                minimumZ, maximumZ, splitZ[1]));
        }
        rejectionReason = $"side-profile-count-{sideProfiles.Count}";
        if (sideProfiles.Count != 2)
            return false;
        sideProfiles.Sort((left, right) => left.Plane.CompareTo(right.Plane));
        var lowSide = sideProfiles[0];
        var highSide = sideProfiles[1];
        rejectionReason = "side-profile-contract";
        if (Math.Abs((highSide.Plane - lowSide.Plane) - widthFt) > roundoff
            || lowSide.MinimumZ != highSide.MinimumZ
            || lowSide.MaximumZ != highSide.MaximumZ
            || lowSide.SubdivisionZ != highSide.SubdivisionZ)
            return false;

        var connectorFaces = rings.Where(item =>
                !ReferenceEquals(item.Face, lowSide.Face)
                && !ReferenceEquals(item.Face, highSide.Face))
            .ToList();
        rejectionReason = "connector-topology";
        if (connectorFaces.Count != 5
            || connectorFaces.Any(item => item.Ring.Count != 4))
            return false;
        var usedLowEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        var usedHighEdges = new HashSet<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)>();
        foreach (var connector in connectorFaces)
        {
            var connectorKeys = connector.Ring
                .Select(IfcPrecisionKeyFeet).ToHashSet();
            var lowPoints = connectorKeys.Where(lowSide.Keys.Contains).ToList();
            var highPoints =
                connectorKeys.Where(highSide.Keys.Contains).ToList();
            rejectionReason = "connector-side-membership";
            if (connectorKeys.Count != 4 || lowPoints.Count != 2
                || highPoints.Count != 2)
                return false;
            var lowEdge = EdgeKey(lowPoints[0], lowPoints[1]);
            var highEdge = EdgeKey(highPoints[0], highPoints[1]);
            rejectionReason = "connector-edge-bijection";
            if (!lowSide.Edges.Contains(lowEdge)
                || !highSide.Edges.Contains(highEdge)
                || !usedLowEdges.Add(lowEdge) || !usedHighEdges.Add(highEdge))
                return false;
        }
        rejectionReason = "connector-edge-coverage";
        if (!usedLowEdges.SetEquals(lowSide.Edges)
            || !usedHighEdges.SetEquals(highSide.Edges))
            return false;

        var allPoints = rings.SelectMany(item => item.Ring).ToList();
        var zLevels = allPoints.Select(IfcPrecisionKeyFeet)
            .Select(key => key.Z).Distinct().Order().ToList();
        rejectionReason = $"z-levels-{zLevels.Count}";
        if (zLevels.Count != 3 || zLevels[2] - zLevels[0] <= 2)
            return false;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        double lowZFt = allPoints
            .Where(point => IfcPrecisionKeyFeet(point).Z == zLevels[0])
            .Average(point => point[2]);
        double highZFt = allPoints
            .Where(point => IfcPrecisionKeyFeet(point).Z == zLevels[^1])
            .Average(point => point[2]);
        rejectionReason = "serialized-vertical-span";
        if (Math.Abs(lowZFt - bounds[2]) > toleranceFt
            || Math.Abs(highZFt - bounds[5]) > toleranceFt)
            return false;

        List<double[]> SidePlanEndpoints(
            (GeoFace Face, List<double[]> Ring, double Plane,
                HashSet<(long X, long Y, long Z)> Keys,
                HashSet<((long X, long Y, long Z) First,
                    (long X, long Y, long Z) Second)> Edges,
                long MinimumZ, long MaximumZ, long SubdivisionZ) side) =>
            side.Ring.GroupBy(point =>
            {
                var key = IfcPrecisionKeyFeet(point);
                return (key.X, key.Y);
            }).Select(group => group.First())
                .OrderBy(point =>
                    point[0] * axisX + point[1] * axisY).ToList();
        var lowEndpoints = SidePlanEndpoints(lowSide);
        var highEndpoints = SidePlanEndpoints(highSide);
        rejectionReason =
            $"authored-endpoints-{lowEndpoints.Count}-{highEndpoints.Count}";
        if (lowEndpoints.Count != 2 || highEndpoints.Count != 2)
            return false;
        var plan = new List<double[]>
        {
            new[] { lowEndpoints[0][0], lowEndpoints[0][1] },
            new[] { lowEndpoints[1][0], lowEndpoints[1][1] },
            new[] { highEndpoints[1][0], highEndpoints[1][1] },
            new[] { highEndpoints[0][0], highEndpoints[0][1] },
        };
        rejectionReason = "authored-plan";
        if (plan.Select(point =>
                {
                    var key = IfcPrecisionKeyFeet([point[0], point[1], 0]);
                    return (key.X, key.Y);
                }).Distinct().Count() != 4
            || !WallPlanMatchesSerializedBoundsAtIfcPrecision(plan, bounds))
            return false;

        var minimumCap = plan.Select(point =>
            new[] { point[0], point[1], lowZFt }).ToList();
        var maximumCap = plan.Select(point =>
            new[] { point[0], point[1], highZFt }).ToList();
        var exactFaces = new List<GeoFace>
        {
            new() { OuterVertices = minimumCap },
            new()
            {
                OuterVertices =
                    maximumCap.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < minimumCap.Count; index++)
        {
            int next = (index + 1) % minimumCap.Count;
            exactFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    minimumCap[index], minimumCap[next],
                    maximumCap[next], maximumCap[index],
                ],
            });
        }
        var exactFaceIndices = Enumerable.Range(0, exactFaces.Count).ToList();
        rejectionReason = "exact-shell-orientation";
        if (!TryOrientExactFacetedShell(
                exactFaces, exactFaceIndices, out var orientedExactFaces,
                triangulateNonPlanarFaces: false))
            return false;
        var exactPoints = orientedExactFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        double[] exactBounds =
        [
            exactPoints.Min(point => point[0]),
            exactPoints.Min(point => point[1]),
            lowZFt,
            exactPoints.Max(point => point[0]),
            exactPoints.Max(point => point[1]),
            highZFt,
        ];
        var candidate = new GeometryData
        {
            BoundingBox = exactBounds,
            Faces = orientedExactFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = exactFaceIndices,
                    IsClosed = true,
                },
            ],
        };
        rejectionReason = "exact-vertical-definition";
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                candidate, location, widthFt, exactBounds,
                out var verifiedPlan, out _, out _, out string exactReason)
            || exactReason != "exact" || verifiedPlan.Count != 4)
        {
            rejectionReason += $"-{exactReason}";
            return false;
        }

        exactBoundary = candidate;
        rejectionReason =
            "exact-single-collinear-vertical-edge-subdivision";
        return true;
    }

    /// <summary>
    /// Adds the single collinear profile vertex created where a joined or overlapping wall
    /// component meets the post-join authored boundary of a referenced wall at its path.
    /// </summary>
    internal static bool TryGetUniquePathWallMinimumCapSubdivision(
        Element wall, IReadOnlyDictionary<int, Element> elemById,
        GeometryData exactBoundary, out GeometryData subdividedBoundary,
        out string rejectionReason) =>
        TryGetPathWallMinimumCapSubdivisionsCore(
            wall, elemById, exactBoundary,
            allowExactSameWidthReferencedPlan: false,
            requireUniqueIntersection: true,
            preferExplicitPathConnection: false,
            requireLongitudinalNeighbourEdge: false,
            includeExactSourceMinimumCapBoundarySubdivisions: false,
            requireUniqueReciprocalEndConnectorSubdivision: false,
            out subdividedBoundary, out rejectionReason);

    /// <summary>
    /// Preserves every exact collinear minimum-cap vertex contributed by referenced peer walls on
    /// the same path elevation and IFC width lattice.
    /// </summary>
    internal static bool TryGetExactReferencedPeerWallMinimumCapSubdivisions(
        Element wall, IReadOnlyDictionary<int, Element> elemById,
        GeometryData exactBoundary, out GeometryData subdividedBoundary,
        out string rejectionReason) =>
        TryGetPathWallMinimumCapSubdivisionsCore(
            wall, elemById, exactBoundary,
            allowExactSameWidthReferencedPlan: true,
            requireUniqueIntersection: false,
            preferExplicitPathConnection: false,
            requireLongitudinalNeighbourEdge: false,
            includeExactSourceMinimumCapBoundarySubdivisions: false,
            requireUniqueReciprocalEndConnectorSubdivision: false,
            out subdividedBoundary, out rejectionReason);

    /// <summary>
    /// Preserves one exact minimum-cap subdivision produced by the longitudinal exterior side of an
    /// explicitly connected referenced wall.
    /// </summary>
    internal static bool
        TryGetUniquePathWallLongitudinalSideMinimumCapSubdivision(
            Element wall, IReadOnlyDictionary<int, Element> elemById,
            GeometryData exactBoundary, out GeometryData subdividedBoundary,
            out string rejectionReason) =>
        TryGetPathWallMinimumCapSubdivisionsCore(
            wall, elemById, exactBoundary,
            allowExactSameWidthReferencedPlan: false,
            requireUniqueIntersection: true,
            preferExplicitPathConnection: true,
            requireLongitudinalNeighbourEdge: true,
            includeExactSourceMinimumCapBoundarySubdivisions: false,
            requireUniqueReciprocalEndConnectorSubdivision: false,
            out subdividedBoundary, out rejectionReason);

    /// <summary>
    /// Preserves the unique explicit path-connection subdivision and exact boundary vertices from
    /// additional source minimum-cap faces.
    /// </summary>
    internal static bool
        TryGetExactSourceOpeningWallMinimumCapSubdivisions(
            Element wall, IReadOnlyDictionary<int, Element> elemById,
            GeometryData exactBoundary, out GeometryData subdividedBoundary,
            out string rejectionReason) =>
        TryGetPathWallMinimumCapSubdivisionsCore(
            wall, elemById, exactBoundary,
            allowExactSameWidthReferencedPlan: false,
            requireUniqueIntersection: true,
            preferExplicitPathConnection: true,
            requireLongitudinalNeighbourEdge: false,
            includeExactSourceMinimumCapBoundarySubdivisions: true,
            requireUniqueReciprocalEndConnectorSubdivision: false,
            out subdividedBoundary, out rejectionReason);

    /// <summary>
    /// The two location paths must share an endpoint on the IFC geometry lattice; one connector
    /// endpoint must equal a recovered cap corner and the other must be strictly inside that same
    /// cap edge.
    /// </summary>
    internal static bool
        TryGetUniqueReciprocalEndConnectorMinimumCapSubdivision(
            Element wall, IReadOnlyDictionary<int, Element> elemById,
            GeometryData exactBoundary, out GeometryData subdividedBoundary,
            out string rejectionReason) =>
        TryGetPathWallMinimumCapSubdivisionsCore(
            wall, elemById, exactBoundary,
            allowExactSameWidthReferencedPlan: false,
            requireUniqueIntersection: true,
            preferExplicitPathConnection: true,
            requireLongitudinalNeighbourEdge: false,
            includeExactSourceMinimumCapBoundarySubdivisions: false,
            requireUniqueReciprocalEndConnectorSubdivision: true,
            out subdividedBoundary, out rejectionReason);

    private static bool TryGetPathWallMinimumCapSubdivisionsCore(
        Element wall, IReadOnlyDictionary<int, Element> elemById,
        GeometryData exactBoundary,
        bool allowExactSameWidthReferencedPlan,
        bool requireUniqueIntersection,
        bool preferExplicitPathConnection,
        bool requireLongitudinalNeighbourEdge,
        bool includeExactSourceMinimumCapBoundarySubdivisions,
        bool requireUniqueReciprocalEndConnectorSubdivision,
        out GeometryData subdividedBoundary,
        out string rejectionReason)
    {
        subdividedBoundary = new GeometryData();
        rejectionReason = "preconditions";
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double wallWidthFt)
            || exactBoundary.BoundingBox is not { Length: 6 } exactBounds
            || exactBoundary.Faces is not { Count: 6 } exactFaces
            || wall.References is not { Count: > 0 } references)
            return false;
        if (TryGetExactVerticalRectangularWallPlan(
                exactBoundary, location, wallWidthFt, exactBounds, out _))
        {
            rejectionReason = "exact-rectangular-minimum-cap";
            return false;
        }

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        static bool PointWithinOneIfcLatticeOfSegment(
            (long X, long Y, long Z) point,
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second)
        {
            var dx = (System.Numerics.BigInteger)second.X - first.X;
            var dy = (System.Numerics.BigInteger)second.Y - first.Y;
            var dz = (System.Numerics.BigInteger)second.Z - first.Z;
            var px = (System.Numerics.BigInteger)point.X - first.X;
            var py = (System.Numerics.BigInteger)point.Y - first.Y;
            var pz = (System.Numerics.BigInteger)point.Z - first.Z;
            var latticeCrossTolerance = new[]
            {
                System.Numerics.BigInteger.Abs(dx),
                System.Numerics.BigInteger.Abs(dy),
                System.Numerics.BigInteger.Abs(dz),
            }.Max();
            if (latticeCrossTolerance == 0
                || System.Numerics.BigInteger.Abs(dy * pz - dz * py)
                    > latticeCrossTolerance
                || System.Numerics.BigInteger.Abs(dz * px - dx * pz)
                    > latticeCrossTolerance
                || System.Numerics.BigInteger.Abs(dx * py - dy * px)
                    > latticeCrossTolerance)
                return false;
            var projection = px * dx + py * dy + pz * dz;
            var lengthSquared = dx * dx + dy * dy + dz * dz;
            return projection > 0 && projection < lengthSquared;
        }
        static bool KeysShareIfcLatticeCell(
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second) =>
            System.Numerics.BigInteger.Abs(
                (System.Numerics.BigInteger)first.X - second.X) <= 1
            && System.Numerics.BigInteger.Abs(
                (System.Numerics.BigInteger)first.Y - second.Y) <= 1
            && System.Numerics.BigInteger.Abs(
                (System.Numerics.BigInteger)first.Z - second.Z) <= 1;
        static bool PointIsStrictlyInsideConvexCapBeyondOneIfcLatticeCell(
            (long X, long Y, long Z) point,
            IReadOnlyList<(long X, long Y, long Z)> polygon)
        {
            int orientation = 0;
            for (int index = 0; index < polygon.Count; index++)
            {
                var first = polygon[index];
                var second = polygon[(index + 1) % polygon.Count];
                var edgeX = (System.Numerics.BigInteger)second.X - first.X;
                var edgeY = (System.Numerics.BigInteger)second.Y - first.Y;
                var pointX = (System.Numerics.BigInteger)point.X - first.X;
                var pointY = (System.Numerics.BigInteger)point.Y - first.Y;
                var cross = edgeX * pointY - edgeY * pointX;
                var oneCellCross = System.Numerics.BigInteger.Max(
                    System.Numerics.BigInteger.Abs(edgeX),
                    System.Numerics.BigInteger.Abs(edgeY));
                if (oneCellCross == 0
                    || System.Numerics.BigInteger.Abs(cross) <= oneCellCross)
                    return false;
                int currentOrientation = cross.Sign;
                if (orientation == 0)
                    orientation = currentOrientation;
                else if (currentOrientation != orientation)
                    return false;
            }
            return orientation != 0;
        }
        static List<(long X, long Y, long Z)> CleanIfcPrecisionKeyRing(
            IEnumerable<double[]> points)
        {
            var result = new List<(long X, long Y, long Z)>();
            foreach (double[] point in points)
            {
                var key = IfcPrecisionKeyFeet(point);
                if (result.Count == 0 || result[^1] != key)
                    result.Add(key);
            }
            if (result.Count > 1 && result[0] == result[^1])
                result.RemoveAt(result.Count - 1);
            return result;
        }
        static bool RingIsStrictlyConvexAtIfcPrecision(
            IReadOnlyList<(long X, long Y, long Z)> ring)
        {
            int orientation = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                var first = ring[index];
                var second = ring[(index + 1) % ring.Count];
                var third = ring[(index + 2) % ring.Count];
                var firstX = (System.Numerics.BigInteger)second.X - first.X;
                var firstY = (System.Numerics.BigInteger)second.Y - first.Y;
                var secondX = (System.Numerics.BigInteger)third.X - second.X;
                var secondY = (System.Numerics.BigInteger)third.Y - second.Y;
                var cross = firstX * secondY - firstY * secondX;
                if (cross.IsZero)
                    return false;
                if (orientation == 0)
                    orientation = cross.Sign;
                else if (cross.Sign != orientation)
                    return false;
            }
            return orientation != 0;
        }

        long minimumZ = exactFaces.SelectMany(face => face.OuterVertices!)
            .Select(IfcPrecisionKeyFeet).Min(key => key.Z);
        var minimumCaps = exactFaces
            .Select(face => CleanRing(face.OuterVertices!))
            .Where(ring => ring.All(point =>
                IfcPrecisionKeyFeet(point).Z == minimumZ))
            .ToList();
        if (minimumCaps.Count != 1 || minimumCaps[0].Count != 4)
        {
            rejectionReason = $"minimum-cap-{minimumCaps.Count}";
            return false;
        }
        var minimumCap = minimumCaps[0];
        var capKeys = minimumCap.Select(IfcPrecisionKeyFeet).ToList();
        double lowZFt = minimumCap.Average(point => point[2]);
        const double MachineEpsilon = 2.2204460492503131e-16;
        double parameterRoundoff = 4096 * MachineEpsilon;
        var candidates = new Dictionary<
            (long X, long Y, long Z), (int EdgeIndex, double[] Point)>();
        var explicitPathCandidateKeys =
            new HashSet<(long X, long Y, long Z)>();
        var reciprocalConnectorBoundaryCandidates = new Dictionary<
            (long X, long Y, long Z), (int EdgeIndex, double[] Point)>();
        var candidateSource = new List<string>();
        string? diagnosticIds = Environment.GetEnvironmentVariable(
            "RVTIO_OPEN_STEP_MINIMUM_CAP_DIAG");
        bool diagnostics = diagnosticIds?.Split(',',
                StringSplitOptions.RemoveEmptyEntries
                | StringSplitOptions.TrimEntries)
            .Any(value => int.TryParse(value, out int id)
                && id == wall.Id) == true;

        foreach (int referenceId in references.Distinct())
        {
            if (referenceId == wall.Id
                || !elemById.TryGetValue(referenceId, out var neighbour)
                || neighbour.CategoryId != -2000011
                || neighbour.Location is not
                    { CurveType: "Line", ArcRadius: null } neighbourLocation
                || !TryGetSerializedWallWidthFeet(
                    neighbour, out double neighbourWidthFt))
                continue;
            bool hasPathConnection = TryGetWallPathConnectionTypes(
                wall, neighbour,
                out string wallConnectionType,
                out string neighbourConnectionType);
            bool hasIfcLatticeEndpointConnection =
                new[] { location.StartPoint, location.EndPoint }.Any(
                    wallEndpoint =>
                    new[]
                    {
                        neighbourLocation.StartPoint,
                        neighbourLocation.EndPoint,
                    }.Any(neighbourEndpoint =>
                        IfcPrecisionKeyFeet(
                        [
                            wallEndpoint[0], wallEndpoint[1], lowZFt,
                        ]) == IfcPrecisionKeyFeet(
                        [
                            neighbourEndpoint[0], neighbourEndpoint[1],
                            lowZFt,
                        ])));
            bool HasExactParallelOverlappingPath()
            {
                double wallDx =
                    location.EndPoint[0] - location.StartPoint[0];
                double wallDy =
                    location.EndPoint[1] - location.StartPoint[1];
                double neighbourDx =
                    neighbourLocation.EndPoint[0]
                    - neighbourLocation.StartPoint[0];
                double neighbourDy =
                    neighbourLocation.EndPoint[1]
                    - neighbourLocation.StartPoint[1];
                double wallLength =
                    Math.Sqrt(wallDx * wallDx + wallDy * wallDy);
                double neighbourLength = Math.Sqrt(
                    neighbourDx * neighbourDx
                    + neighbourDy * neighbourDy);
                var values = location.StartPoint
                    .Concat(location.EndPoint)
                    .Concat(neighbourLocation.StartPoint)
                    .Concat(neighbourLocation.EndPoint)
                    .Append(wallLength).Append(neighbourLength)
                    .ToList();
                if (!(wallLength > 0) || !(neighbourLength > 0)
                    || values.Any(value => !double.IsFinite(value)))
                    return false;
                double directionCross =
                    wallDx * neighbourDy - wallDy * neighbourDx;
                double productScale = Math.Max(1.0, new[]
                {
                    wallDx * neighbourDy, wallDy * neighbourDx,
                }.Select(Math.Abs).Max());
                double roundoff =
                    4096 * MachineEpsilon * productScale;
                if (Math.Abs(directionCross) > roundoff)
                    return false;
                if (IfcPrecisionKeyFeet(location.StartPoint).Z
                        != IfcPrecisionKeyFeet(
                            neighbourLocation.StartPoint).Z
                    || IfcPrecisionKeyFeet(location.EndPoint).Z
                        != IfcPrecisionKeyFeet(
                            neighbourLocation.EndPoint).Z)
                    return false;
                double axisX = wallDx / wallLength;
                double axisY = wallDy / wallLength;
                double wallMinimum = Math.Min(
                    location.StartPoint[0] * axisX
                        + location.StartPoint[1] * axisY,
                    location.EndPoint[0] * axisX
                        + location.EndPoint[1] * axisY);
                double wallMaximum = Math.Max(
                    location.StartPoint[0] * axisX
                        + location.StartPoint[1] * axisY,
                    location.EndPoint[0] * axisX
                        + location.EndPoint[1] * axisY);
                double neighbourMinimum = Math.Min(
                    neighbourLocation.StartPoint[0] * axisX
                        + neighbourLocation.StartPoint[1] * axisY,
                    neighbourLocation.EndPoint[0] * axisX
                        + neighbourLocation.EndPoint[1] * axisY);
                double neighbourMaximum = Math.Max(
                    neighbourLocation.StartPoint[0] * axisX
                        + neighbourLocation.StartPoint[1] * axisY,
                    neighbourLocation.EndPoint[0] * axisX
                        + neighbourLocation.EndPoint[1] * axisY);
                double intervalScale = Math.Max(1.0, new[]
                {
                    wallMinimum, wallMaximum,
                    neighbourMinimum, neighbourMaximum,
                }.Select(Math.Abs).Max());
                double intervalRoundoff =
                    4096 * MachineEpsilon * intervalScale;
                return Math.Min(wallMaximum, neighbourMaximum)
                    - Math.Max(wallMinimum, neighbourMinimum)
                    > intervalRoundoff;
            }
            bool hasExactParallelOverlappingPath =
                HasExactParallelOverlappingPath();
            bool hasExactSameWidthReferencedPlan =
                allowExactSameWidthReferencedPlan
                && IfcPrecisionBinMetres(neighbourWidthFt * FeetToMetres)
                    == IfcPrecisionBinMetres(wallWidthFt * FeetToMetres)
                && IfcPrecisionKeyFeet(location.StartPoint).Z
                    == IfcPrecisionKeyFeet(neighbourLocation.StartPoint).Z
                && IfcPrecisionKeyFeet(location.EndPoint).Z
                    == IfcPrecisionKeyFeet(neighbourLocation.EndPoint).Z;
            bool eligibleReference = allowExactSameWidthReferencedPlan
                ? hasPathConnection || hasExactSameWidthReferencedPlan
                : hasPathConnection
                    || hasIfcLatticeEndpointConnection
                    || hasExactParallelOverlappingPath;
            bool hasReciprocalConnectorReference =
                (includeExactSourceMinimumCapBoundarySubdivisions
                    || requireUniqueReciprocalEndConnectorSubdivision)
                && neighbour.References?.Contains(wall.Id) == true
                && (!requireUniqueReciprocalEndConnectorSubdivision
                    || hasPathConnection
                    || hasIfcLatticeEndpointConnection)
                && IfcPrecisionKeyFeet(location.StartPoint).Z
                    == IfcPrecisionKeyFeet(neighbourLocation.StartPoint).Z
                && IfcPrecisionKeyFeet(location.EndPoint).Z
                    == IfcPrecisionKeyFeet(neighbourLocation.EndPoint).Z;
            if ((!eligibleReference
                    && !hasReciprocalConnectorReference)
                || requireLongitudinalNeighbourEdge
                    && !hasPathConnection)
                continue;
            if (!TryGetAuthoredStraightWallPlan(
                    neighbour, neighbourWidthFt, out var neighbourPlan)
                || neighbourPlan.Count != 4)
                continue;

            // A joined wall whose reference is serialized in both directions can terminate part-way
            // across this wall's minimum-cap connector.
            if (hasReciprocalConnectorReference)
            {
                foreach (int connectorEdgeIndex in new[] { 1, 3 })
                {
                    double[] connectorFirst =
                        neighbourPlan[connectorEdgeIndex];
                    double[] connectorSecond = neighbourPlan[
                        (connectorEdgeIndex + 1) % neighbourPlan.Count];
                    double[] firstPoint =
                        [connectorFirst[0], connectorFirst[1], lowZFt];
                    double[] secondPoint =
                        [connectorSecond[0], connectorSecond[1], lowZFt];
                    var firstKey = IfcPrecisionKeyFeet(firstPoint);
                    var secondKey = IfcPrecisionKeyFeet(secondPoint);
                    foreach (int capEdgeIndex in
                             Enumerable.Range(0, capKeys.Count))
                    {
                        var capFirstKey = capKeys[capEdgeIndex];
                        var capSecondKey = capKeys[
                            (capEdgeIndex + 1) % capKeys.Count];
                        bool firstIsCorner =
                            KeysShareIfcLatticeCell(
                                firstKey, capFirstKey)
                            || KeysShareIfcLatticeCell(
                                firstKey, capSecondKey);
                        bool secondIsCorner =
                            KeysShareIfcLatticeCell(
                                secondKey, capFirstKey)
                            || KeysShareIfcLatticeCell(
                                secondKey, capSecondKey);
                        bool firstIsInterior =
                            PointWithinOneIfcLatticeOfSegment(
                                firstKey, capFirstKey, capSecondKey);
                        bool secondIsInterior =
                            PointWithinOneIfcLatticeOfSegment(
                                secondKey, capFirstKey, capSecondKey);
                        if (firstIsCorner == secondIsCorner
                            || firstIsInterior == secondIsInterior
                            || !(firstIsCorner && secondIsInterior
                                || secondIsCorner && firstIsInterior))
                            continue;
                        var candidateKey = firstIsInterior
                            ? firstKey : secondKey;
                        double[] candidatePoint = firstIsInterior
                            ? firstPoint : secondPoint;
                        reciprocalConnectorBoundaryCandidates.TryAdd(
                            candidateKey, (capEdgeIndex, candidatePoint));
                        if (diagnostics)
                            candidateSource.Add(
                                $"{referenceId}:RECIPROCAL-CONNECTOR:"
                                + $"cap-{capEdgeIndex}:"
                                + $"neighbour-{connectorEdgeIndex}:"
                                + $"key-{candidateKey.X},"
                                + $"{candidateKey.Y},{candidateKey.Z}");
                    }
                }
            }
            if (!eligibleReference)
                continue;
            for (int capEdgeIndex = 0;
                capEdgeIndex < minimumCap.Count; capEdgeIndex++)
            {
                double[] first =
                    minimumCap[capEdgeIndex];
                double[] second =
                    minimumCap[(capEdgeIndex + 1) % minimumCap.Count];
                double capDx = second[0] - first[0];
                double capDy = second[1] - first[1];
                for (int neighbourEdgeIndex = 0;
                    neighbourEdgeIndex < neighbourPlan.Count;
                    neighbourEdgeIndex++)
                {
                    // TryGetAuthoredStraightWallPlan always returns its two longitudinal exterior
                    // sides as edges 0 and 2; edges 1 and 3 are the end connectors.
                    if (requireLongitudinalNeighbourEdge
                        && neighbourEdgeIndex is not (0 or 2))
                        continue;
                    double[] neighbourFirst =
                        neighbourPlan[neighbourEdgeIndex];
                    double[] neighbourSecond =
                        neighbourPlan[
                            (neighbourEdgeIndex + 1) % neighbourPlan.Count];
                    double neighbourEdgeDx =
                        neighbourSecond[0] - neighbourFirst[0];
                    double neighbourEdgeDy =
                        neighbourSecond[1] - neighbourFirst[1];
                    double denominator =
                        capDx * neighbourEdgeDy
                        - capDy * neighbourEdgeDx;
                    double denominatorScale = Math.Max(
                        1.0, Math.Max(
                            Math.Abs(capDx * neighbourEdgeDy),
                            Math.Abs(capDy * neighbourEdgeDx)));
                    if (Math.Abs(denominator)
                        <= 4096 * MachineEpsilon * denominatorScale)
                        continue;
                    double offsetX = neighbourFirst[0] - first[0];
                    double offsetY = neighbourFirst[1] - first[1];
                    double capParameter =
                        (offsetX * neighbourEdgeDy
                            - offsetY * neighbourEdgeDx)
                        / denominator;
                    double neighbourParameter =
                        (offsetX * capDy - offsetY * capDx)
                        / denominator;
                    if (!(capParameter > parameterRoundoff)
                        || !(capParameter < 1 - parameterRoundoff)
                        || neighbourParameter < -parameterRoundoff
                        || neighbourParameter > 1 + parameterRoundoff)
                        continue;
                    double[] point =
                    [
                        first[0] + capParameter * capDx,
                        first[1] + capParameter * capDy,
                        lowZFt,
                    ];
                    var key = IfcPrecisionKeyFeet(point);
                    if (capKeys.Any(corner =>
                            KeysShareIfcLatticeCell(key, corner))
                        || !PointWithinOneIfcLatticeOfSegment(
                            key, capKeys[capEdgeIndex],
                            capKeys[(capEdgeIndex + 1) % capKeys.Count]))
                        continue;
                    var neighbourFirstKey = IfcPrecisionKeyFeet(
                    [
                        neighbourFirst[0], neighbourFirst[1], lowZFt,
                    ]);
                    var neighbourSecondKey = IfcPrecisionKeyFeet(
                    [
                        neighbourSecond[0], neighbourSecond[1], lowZFt,
                    ]);
                    if (!PointWithinOneIfcLatticeOfSegment(
                            key, neighbourFirstKey, neighbourSecondKey)
                        && !KeysShareIfcLatticeCell(
                            key, neighbourFirstKey)
                        && !KeysShareIfcLatticeCell(
                            key, neighbourSecondKey))
                        continue;
                    if (hasPathConnection)
                        explicitPathCandidateKeys.Add(key);
                    if (candidates.TryAdd(
                            key, (capEdgeIndex, point)))
                        candidateSource.Add(
                            $"{referenceId}:"
                             + (hasPathConnection
                                 ? $"{wallConnectionType}"
                                     + $"/{neighbourConnectionType}"
                                 : hasExactParallelOverlappingPath
                                     ? "EXACT-PARALLEL-OVERLAP"
                                     : hasExactSameWidthReferencedPlan
                                         ? "EXACT-SAME-WIDTH-REFERENCED-PLAN"
                                     : "IFC-LATTICE-ENDPOINT")
                            + $":cap-{capEdgeIndex}"
                            + $":neighbour-{neighbourEdgeIndex}"
                            + $":key-{key.X},{key.Y},{key.Z}");
                }
            }
        }
        if (preferExplicitPathConnection
            && explicitPathCandidateKeys.Count > 0)
        {
            foreach (var key in candidates.Keys
                         .Where(key =>
                             !explicitPathCandidateKeys.Contains(key))
                         .ToList())
                candidates.Remove(key);
        }
        if (requireUniqueReciprocalEndConnectorSubdivision)
        {
            if (reciprocalConnectorBoundaryCandidates.Count != 1)
            {
                rejectionReason =
                    "reciprocal-end-connector-subdivisions-"
                    + reciprocalConnectorBoundaryCandidates.Count;
                return false;
            }
            candidates.Clear();
            var connectorCandidate =
                reciprocalConnectorBoundaryCandidates.Single();
            candidates.Add(
                connectorCandidate.Key, connectorCandidate.Value);
        }
        int pathIntersectionCount = candidates.Count;
        if (pathIntersectionCount == 0
            || requireUniqueIntersection && pathIntersectionCount != 1)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCPATHWALLMINIMUMCAP wall={wall.Id} "
                    + $"candidates={candidateSource.Count} "
                    + $"source={string.Join('|', candidateSource)}");
            rejectionReason =
                $"path-intersections-{pathIntersectionCount}";
            return false;
        }

        foreach (var connectorCandidate in
                 reciprocalConnectorBoundaryCandidates)
        {
            if (candidates.TryGetValue(
                    connectorCandidate.Key, out var existing)
                && existing.EdgeIndex
                    != connectorCandidate.Value.EdgeIndex)
            {
                rejectionReason =
                    "reciprocal-connector-boundary-conflict";
                return false;
            }
        }
        var newReciprocalConnectorBoundaryCandidates =
            reciprocalConnectorBoundaryCandidates
                .Where(candidate =>
                    !candidates.ContainsKey(candidate.Key))
                .ToList();
        if (newReciprocalConnectorBoundaryCandidates.Count > 1)
        {
            rejectionReason =
                "reciprocal-connector-boundary-subdivisions-"
                + newReciprocalConnectorBoundaryCandidates.Count;
            return false;
        }
        foreach (var connectorCandidate in
                 newReciprocalConnectorBoundaryCandidates)
        {
            candidates.TryAdd(
                connectorCandidate.Key, connectorCandidate.Value);
        }
        if (includeExactSourceMinimumCapBoundarySubdivisions)
        {
            if (wall.Geometry is not
                    { Faces: { Count: > 0 } sourceFaces,
                        BrepSolids: { Count: > 0 } sourceSolids })
            {
                rejectionReason = "source-minimum-cap-container";
                return false;
            }
            var representedSourceFaceIndices = sourceSolids
                .SelectMany(solid => solid.FaceIndices)
                .Distinct().ToList();
            if (representedSourceFaceIndices.Any(index =>
                    index < 0 || index >= sourceFaces.Count))
            {
                rejectionReason = "source-minimum-cap-indices";
                return false;
            }
            var representedSourceFaceIndexSet =
                representedSourceFaceIndices.ToHashSet();
            bool IsUnindexedProjectedCapVariantOfRepresentedOpenComponent(
                int sourceFaceIndex,
                IReadOnlyList<(long X, long Y, long Z)> sourceRingKeys)
            {
                if (representedSourceFaceIndexSet.Contains(sourceFaceIndex))
                    return false;
                if (sourceSolids.Count < 2)
                    return false;
                var orphanRing = sourceRingKeys
                    .Where((key, index) => index == 0
                        || key != sourceRingKeys[index - 1])
                    .ToList();
                if (orphanRing.Count > 1
                    && orphanRing[0] == orphanRing[^1])
                    orphanRing.RemoveAt(orphanRing.Count - 1);
                if (orphanRing.Count != 4
                    || orphanRing.Select(key => (key.X, key.Y))
                        .Distinct().Count() != 4
                    || !RingIsStrictlyConvexAtIfcPrecision(orphanRing))
                    return false;
                var orphanPlan = orphanRing
                    .Select(key => (key.X, key.Y)).ToHashSet();

                foreach (GeoBrepSolid solid in sourceSolids)
                {
                    if (solid.FaceIndices.Distinct().Count() < 6)
                        continue;
                    var representedCaps = solid.FaceIndices
                        .Distinct()
                        .Select(index => (Index: index, Face: sourceFaces[index]))
                        .Where(item =>
                            item.Face.OuterVertices is { Count: >= 3 }
                            && item.Face.InnerVertices is not { Count: > 0 }
                            && item.Face.AlternativeOuterVertices
                                is not { Count: > 0 }
                            && FaceCanEmitAtIfcPrecision(item.Face))
                        .Select(item =>
                        {
                            var keys = CleanIfcPrecisionKeyRing(
                                item.Face.OuterVertices!);
                            return (item.Index, Keys: keys,
                                Horizontal: keys.Count >= 3
                                    && keys.Select(key => key.Z)
                                        .Distinct().Count() == 1);
                        })
                        .Where(item => item.Horizontal
                            && item.Keys.Count == 4
                            && item.Keys.Select(key => (key.X, key.Y))
                                .Distinct().Count() == 4
                            && item.Keys[0].Z > minimumZ
                            && RingIsStrictlyConvexAtIfcPrecision(item.Keys))
                        .Select(item => (item.Index, item.Keys,
                            Z: item.Keys[0].Z,
                            Plan: item.Keys.Select(key => (key.X, key.Y))
                                .ToHashSet()))
                        .ToList();
                    foreach (var cap in representedCaps)
                    {
                        if (cap.Plan.Intersect(orphanPlan).Count() != 3)
                            continue;
                        var capOnly = cap.Keys.Single(key =>
                            !orphanPlan.Contains((key.X, key.Y)));
                        var orphanOnly = orphanRing.Single(key =>
                            !cap.Plan.Contains((key.X, key.Y)));
                        var shiftX = (System.Numerics.BigInteger)orphanOnly.X
                            - capOnly.X;
                        var shiftY = (System.Numerics.BigInteger)orphanOnly.Y
                            - capOnly.Y;
                        long maximumShift = checked((long)Math.Ceiling(
                            wallWidthFt * FeetToMetres
                            / IfcGeometryPrecisionMetres)) + 1;
                        var maximumShiftSquared =
                            (System.Numerics.BigInteger)maximumShift
                            * maximumShift;
                        if (shiftX.IsZero && shiftY.IsZero
                            || shiftX * shiftX + shiftY * shiftY
                                > maximumShiftSquared)
                            continue;
                        int capOnlyIndex = cap.Keys.IndexOf(capOnly);
                        bool shiftFollowsAdjacentCapEdge = new[]
                        {
                            cap.Keys[(capOnlyIndex + cap.Keys.Count - 1)
                                % cap.Keys.Count],
                            cap.Keys[(capOnlyIndex + 1) % cap.Keys.Count],
                        }.Any(adjacent =>
                        {
                            var edgeX =
                                (System.Numerics.BigInteger)adjacent.X
                                - capOnly.X;
                            var edgeY =
                                (System.Numerics.BigInteger)adjacent.Y
                                - capOnly.Y;
                            var cross = edgeX * shiftY - edgeY * shiftX;
                            var oneCellCross = System.Numerics.BigInteger.Max(
                                System.Numerics.BigInteger.Abs(edgeX),
                                System.Numerics.BigInteger.Abs(edgeY));
                            return oneCellCross > 0
                                && System.Numerics.BigInteger.Abs(cross)
                                    <= oneCellCross;
                        });
                        if (shiftFollowsAdjacentCapEdge)
                            return true;
                    }
                }
                return false;
            }
            // Some joined-wall cap fragments are serialized as source faces but are not referenced
            // by a decoded BrepSolid.
            var sourceFaceIndices =
                Enumerable.Range(0, sourceFaces.Count).ToList();
            int additionalSourceMinimumCapFaces = 0;
            foreach (int sourceFaceIndex in sourceFaceIndices)
            {
                GeoFace sourceFace = sourceFaces[sourceFaceIndex];
                if (sourceFace.OuterVertices is not { Count: >= 3 } outer
                    || outer.Any(point => point.Length < 3
                        || !double.IsFinite(point[0])
                        || !double.IsFinite(point[1])
                        || !double.IsFinite(point[2])))
                    continue;
                var ring = CleanRing(outer);
                if (ring.Count < 3
                    || !ring.All(point =>
                        IfcPrecisionKeyFeet(point).Z == minimumZ))
                    continue;
                var ringKeys = ring.Select(IfcPrecisionKeyFeet).ToList();
                if (ringKeys.ToHashSet().SetEquals(capKeys))
                    continue;
                additionalSourceMinimumCapFaces++;
                if (sourceFace.InnerVertices is { Count: > 0 }
                    || sourceFace.AlternativeOuterVertices is { Count: > 0 }
                    || !FaceCanEmitAtIfcPrecision(sourceFace))
                {
                    rejectionReason =
                        $"source-minimum-cap-face-{sourceFaceIndex}";
                    return false;
                }

                int faceBoundarySubdivisionCount = 0;
                foreach (var point in ring)
                {
                    var key = IfcPrecisionKeyFeet(point);
                    if (capKeys.Any(corner =>
                            KeysShareIfcLatticeCell(key, corner)))
                        continue;
                    var matchingEdges = Enumerable.Range(0, capKeys.Count)
                        .Where(edgeIndex =>
                            PointWithinOneIfcLatticeOfSegment(
                                key, capKeys[edgeIndex],
                                capKeys[
                                    (edgeIndex + 1) % capKeys.Count]))
                        .ToList();
                    if (matchingEdges.Count == 0)
                        continue;
                    if (matchingEdges.Count != 1)
                    {
                        rejectionReason =
                            $"source-minimum-cap-edge-ambiguity-"
                            + $"{sourceFaceIndex}-{matchingEdges.Count}";
                        return false;
                    }
                    int edgeIndex = matchingEdges[0];
                    if (candidates.TryGetValue(key, out var existing)
                        && existing.EdgeIndex != edgeIndex)
                    {
                        rejectionReason =
                            $"source-minimum-cap-edge-conflict-"
                            + $"{sourceFaceIndex}";
                        return false;
                    }
                    if (candidates.TryAdd(key, (edgeIndex, point)))
                        candidateSource.Add(
                            $"source-face-{sourceFaceIndex}:"
                            + $"cap-{edgeIndex}:"
                            + $"key-{key.X},{key.Y},{key.Z}");
                    faceBoundarySubdivisionCount++;
                }
                if (faceBoundarySubdivisionCount == 0)
                {
                    // An unindexed coplanar fragment can belong to a separate joined component
                    // without changing the gross wall envelope.
                    if (ringKeys.All(key =>
                            PointIsStrictlyInsideConvexCapBeyondOneIfcLatticeCell(
                                key, capKeys)))
                    {
                        if (diagnostics)
                            candidateSource.Add(
                                $"source-interior-face-{sourceFaceIndex}");
                        continue;
                    }
                    if (IsUnindexedProjectedCapVariantOfRepresentedOpenComponent(
                            sourceFaceIndex, ringKeys))
                    {
                        if (diagnostics)
                            candidateSource.Add(
                                $"source-projected-component-cap-"
                                + $"{sourceFaceIndex}");
                        continue;
                    }
                    rejectionReason =
                        $"source-minimum-cap-nonboundary-face-"
                        + $"{sourceFaceIndex}";
                    return false;
                }
            }
            if (diagnostics)
                candidateSource.Add(
                    $"source-minimum-cap-faces-"
                    + $"{additionalSourceMinimumCapFaces}");
        }
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCPATHWALLMINIMUMCAP wall={wall.Id} "
                + $"candidates={candidateSource.Count} "
                + $"source={string.Join('|', candidateSource)}");

        var subdividedMinimumCap = new List<double[]>();
        for (int index = 0; index < minimumCap.Count; index++)
        {
            subdividedMinimumCap.Add(minimumCap[index]);
            var firstKey = capKeys[index];
            var secondKey = capKeys[(index + 1) % capKeys.Count];
            var edgeDx =
                (System.Numerics.BigInteger)secondKey.X - firstKey.X;
            var edgeDy =
                (System.Numerics.BigInteger)secondKey.Y - firstKey.Y;
            var edgeDz =
                (System.Numerics.BigInteger)secondKey.Z - firstKey.Z;
            foreach (var subdivision in candidates
                         .Where(candidate =>
                             candidate.Value.EdgeIndex == index)
                         .Select(candidate => new
                         {
                             candidate.Key,
                             candidate.Value.Point,
                             Projection =
                                 ((System.Numerics.BigInteger)candidate.Key.X
                                     - firstKey.X) * edgeDx
                                 + ((System.Numerics.BigInteger)candidate.Key.Y
                                     - firstKey.Y) * edgeDy
                                 + ((System.Numerics.BigInteger)candidate.Key.Z
                                     - firstKey.Z) * edgeDz,
                         })
                         .OrderBy(candidate => candidate.Projection)
                         .ThenBy(candidate => candidate.Key.X)
                         .ThenBy(candidate => candidate.Key.Y)
                         .ThenBy(candidate => candidate.Key.Z))
                subdividedMinimumCap.Add(subdivision.Point);
        }
        double highZFt = exactBounds[5];
        var subdividedMaximumCap = subdividedMinimumCap.Select(point =>
            new[] { point[0], point[1], highZFt }).ToList();
        var subdividedFaces = new List<GeoFace>
        {
            new() { OuterVertices = subdividedMinimumCap },
            new()
            {
                OuterVertices =
                    subdividedMaximumCap.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < subdividedMinimumCap.Count; index++)
        {
            int next = (index + 1) % subdividedMinimumCap.Count;
            subdividedFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    subdividedMinimumCap[index],
                    subdividedMinimumCap[next],
                    subdividedMaximumCap[next],
                    subdividedMaximumCap[index],
                ],
            });
        }
        var faceIndices =
            Enumerable.Range(0, subdividedFaces.Count).ToList();
        // The subdivision points are exact on the IFC lattice but independently calculated source
        // doubles can make a cap appear infinitesimally non-planar.
        if (!TryOrientExactFacetedShell(
                subdividedFaces, faceIndices, out var orientedFaces,
                triangulateNonPlanarFaces: false))
        {
            rejectionReason = "shell-orientation";
            return false;
        }
        var candidate = new GeometryData
        {
            BoundingBox = (double[])exactBounds.Clone(),
            Faces = orientedFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = faceIndices,
                    IsClosed = true,
                },
            ],
        };
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                candidate, location, wallWidthFt, exactBounds,
                out _, out _, out _, out string reason)
            || reason != "exact-collinear-boundary-subdivision")
        {
            rejectionReason = $"vertical-definition-{reason}";
            return false;
        }

        subdividedBoundary = candidate;
        rejectionReason = requireUniqueReciprocalEndConnectorSubdivision
            ? "exact-reciprocal-end-connector-minimum-cap-subdivision"
            : includeExactSourceMinimumCapBoundarySubdivisions
            ? "exact-source-opening-wall-minimum-cap-subdivisions"
            : requireLongitudinalNeighbourEdge
                ? "exact-path-wall-longitudinal-side-minimum-cap-subdivision"
            : requireUniqueIntersection
                ? "exact-path-wall-minimum-cap-subdivision"
                : "exact-referenced-peer-wall-minimum-cap-subdivisions";
        return true;
    }

    /// <summary>
    /// Separates the exact rebuilt twelve-face wall-with-reveal shell from the three-component
    /// source contract that produced it.
    /// </summary>
    internal static bool
        TryGetExactMixedComponentOpenSteppedMinimumCapSourceAuthority(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary, HostedOpeningGeometry operand,
            out GeometryData outerSteppedBoundary,
            out IReadOnlyList<GeoFace> authoritativeSourceFaces,
            out string rejectionReason)
    {
        outerSteppedBoundary = new GeometryData();
        authoritativeSourceFaces = [];
        rejectionReason = "preconditions";
        if (!IsExactSourceWallProfilesMappedBreakpointOpening(operand)
            || operand.SteppedProfile is not { } steppedProfile
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || location.StartPoint is not { Length: >= 3 }
            || location.EndPoint is not { Length: >= 3 }
            || location.StartPoint.Take(3).Concat(location.EndPoint.Take(3))
                .Any(value => !double.IsFinite(value))
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || bounds.Count < 6
            || bounds.Take(6).Any(value => !double.IsFinite(value))
            || wall.Geometry is not
            {
                Faces: { Count: 26 or 27 } sourceFaces,
                BrepSolids: { Count: 3 } sourceSolids,
            }
            || rebuiltBoundary.Faces is not { Count: 12 } rebuiltFaces
            || rebuiltBoundary.BrepSolids is not
                [{ IsClosed: true } rebuiltSolid]
            || !rebuiltSolid.FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, rebuiltFaces.Count)))
            return false;

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }

        static ((long X, long Y, long Z) A,
            (long X, long Y, long Z) B) Edge(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);

        static HashSet<((long X, long Y, long Z) A,
            (long X, long Y, long Z) B)> CycleEdges(
                IReadOnlyList<double[]> ring)
        {
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => Edge(
                    keys[index], keys[(index + 1) % keys.Count]))
                .ToHashSet();
        }

        static HashSet<((long X, long Y) A, (long X, long Y) B)>
            PlanCycleEdges(IReadOnlyList<double[]> ring)
        {
            var keys = ring.Select(IfcPrecisionKeyFeet)
                .Select(key => (key.X, key.Y)).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => keys[index].CompareTo(
                        keys[(index + 1) % keys.Count]) <= 0
                    ? (keys[index], keys[(index + 1) % keys.Count])
                    : (keys[(index + 1) % keys.Count], keys[index]))
                .ToHashSet();
        }

        static bool RingsEqual(
            IReadOnlyList<double[]> first, IReadOnlyList<double[]> second) =>
            CleanRing(first).Count == CleanRing(second).Count
            && CycleEdges(CleanRing(first)).SetEquals(
                CycleEdges(CleanRing(second)));

        static bool FacesEqual(GeoFace first, GeoFace second)
        {
            if (first.OuterVertices is not { } firstOuter
                || second.OuterVertices is not { } secondOuter
                || !RingsEqual(firstOuter, secondOuter))
                return false;
            var firstInner = first.InnerVertices ?? [];
            var secondInner = second.InnerVertices ?? [];
            if (firstInner.Count != secondInner.Count)
                return false;
            var unmatched = Enumerable.Range(0, secondInner.Count).ToList();
            foreach (var ring in firstInner)
            {
                int position = unmatched.FindIndex(index =>
                    RingsEqual(ring, secondInner[index]));
                if (position < 0)
                    return false;
                unmatched.RemoveAt(position);
            }
            return unmatched.Count == 0;
        }

        static bool TopologyMatches(
            IReadOnlyList<GeoFace> faces, bool includeInnerRings,
            int expectedVertices, int expectedFaceEdgeUses,
            int expectedEdges, IReadOnlyDictionary<int, int> expectedIncidence,
            IReadOnlyList<int> expectedComponentSizes)
        {
            var vertices = new HashSet<(long X, long Y, long Z)>();
            var owners = new Dictionary<
                ((long X, long Y, long Z) A,
                 (long X, long Y, long Z) B), HashSet<int>>();
            var edgesByFace = Enumerable.Range(0, faces.Count)
                .ToDictionary(index => index, _ => new HashSet<
                    ((long X, long Y, long Z) A,
                     (long X, long Y, long Z) B)>());
            int faceEdgeUses = 0;
            for (int faceIndex = 0; faceIndex < faces.Count; faceIndex++)
            {
                var rings = new List<IReadOnlyList<double[]>>();
                if (faces[faceIndex].OuterVertices is not { } outer)
                    return false;
                rings.Add(CleanRing(outer));
                if (includeInnerRings)
                    rings.AddRange((faces[faceIndex].InnerVertices ?? [])
                        .Select(CleanRing));
                foreach (var ring in rings)
                {
                    var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
                    var edges = CycleEdges(ring);
                    if (keys.Count < 3
                        || keys.Distinct().Count() != keys.Count
                        || edges.Count != keys.Count
                        || edgesByFace[faceIndex].Overlaps(edges))
                        return false;
                    vertices.UnionWith(keys);
                    edgesByFace[faceIndex].UnionWith(edges);
                    faceEdgeUses += edges.Count;
                    foreach (var edge in edges)
                    {
                        if (!owners.TryGetValue(edge, out var edgeOwners))
                            owners[edge] = edgeOwners = [];
                        edgeOwners.Add(faceIndex);
                    }
                }
            }

            var incidence = owners.Values.GroupBy(set => set.Count)
                .ToDictionary(group => group.Key, group => group.Count());
            if (vertices.Count != expectedVertices
                || faceEdgeUses != expectedFaceEdgeUses
                || owners.Count != expectedEdges
                || incidence.Count != expectedIncidence.Count
                || expectedIncidence.Any(pair =>
                    incidence.GetValueOrDefault(pair.Key) != pair.Value))
                return false;

            var remaining = Enumerable.Range(0, faces.Count).ToHashSet();
            var componentSizes = new List<int>();
            while (remaining.Count > 0)
            {
                int seed = remaining.Min();
                remaining.Remove(seed);
                var component = new HashSet<int> { seed };
                var queue = new Queue<int>();
                queue.Enqueue(seed);
                while (queue.Count > 0)
                {
                    int current = queue.Dequeue();
                    foreach (int candidate in remaining.ToList())
                    {
                        if (!edgesByFace[current].Overlaps(
                                edgesByFace[candidate]))
                            continue;
                        remaining.Remove(candidate);
                        component.Add(candidate);
                        queue.Enqueue(candidate);
                    }
                }
                componentSizes.Add(component.Count);
            }
            return componentSizes.OrderDescending().SequenceEqual(
                expectedComponentSizes.OrderDescending());
        }

        static bool PointCanMapToIfcPrecision(IReadOnlyList<double>? point) =>
            point is { Count: >= 3 }
            && CanMapFeetToIfcPrecisionBin(point[0])
            && CanMapFeetToIfcPrecisionBin(point[1])
            && CanMapFeetToIfcPrecisionBin(point[2]);

        bool ExactFaceAuthority(GeoFace face) =>
            face.OuterVertices is { Count: >= 3 } outer
            && face.AlternativeOuterVertices is not { Count: > 0 }
            && outer.All(PointCanMapToIfcPrecision)
            && (face.InnerVertices ?? []).All(ring =>
                ring.Count >= 3 && ring.All(PointCanMapToIfcPrecision))
            && FaceCanEmitAtIfcPrecision(face)
            && !FaceCollapsesAtIfcPrecision(face);

        if (sourceFaces.Any(face => !ExactFaceAuthority(face))
            || rebuiltFaces.Any(face => !ExactFaceAuthority(face)))
        {
            rejectionReason = "face-authority";
            return false;
        }

        var ownedIndices = new HashSet<int>();
        foreach (GeoBrepSolid solid in sourceSolids)
        {
            if (solid.FaceIndices.Distinct().Count()
                    != solid.FaceIndices.Count
                || solid.FaceIndices.Any(index =>
                    index < 0 || index >= sourceFaces.Count)
                || solid.FaceIndices.Any(index =>
                    !ownedIndices.Add(index)))
            {
                rejectionReason = "solid-face-ownership";
                return false;
            }
        }

        List<GeoFace> SolidFaces(GeoBrepSolid solid) =>
            solid.FaceIndices.Select(index => sourceFaces[index]).ToList();
        bool ExactPrimary(GeoBrepSolid solid)
        {
            var faces = SolidFaces(solid);
            return !solid.IsClosed
                && faces.Count == 12
                && faces.Count(face =>
                    CleanRing(face.OuterVertices!).Count == 6
                    && face.InnerVertices is [{ Count: 4 }]) == 2
                && faces.Count(face =>
                    CleanRing(face.OuterVertices!).Count == 4
                    && face.InnerVertices is not { Count: > 0 }) == 10
                && TopologyMatches(faces, includeInnerRings: false,
                    20, 52, 30,
                    new Dictionary<int, int> { [1] = 8, [2] = 22 },
                    [8, 4])
                && TopologyMatches(faces, includeInnerRings: true,
                    20, 60, 30,
                    new Dictionary<int, int> { [2] = 30 }, [12]);
        }
        bool ExactClosedFragment(GeoBrepSolid solid)
        {
            var faces = SolidFaces(solid);
            return solid.IsClosed
                && faces.Count == 10
                && faces.All(face =>
                    CleanRing(face.OuterVertices!).Count == 4)
                && faces.Count(face =>
                    face.InnerVertices is [{ Count: 4 }]) == 2
                && faces.Count(face =>
                    face.InnerVertices is not { Count: > 0 }) == 8
                && TopologyMatches(faces, includeInnerRings: false,
                    16, 40, 24,
                    new Dictionary<int, int> { [1] = 8, [2] = 16 },
                    [6, 4])
                && TopologyMatches(faces, includeInnerRings: true,
                    16, 48, 24,
                    new Dictionary<int, int> { [2] = 24 }, [10]);
        }
        bool ExactOpenTube(GeoBrepSolid solid)
        {
            var faces = SolidFaces(solid);
            return !solid.IsClosed
                && faces.Count == 4
                && faces.All(face =>
                    CleanRing(face.OuterVertices!).Count == 4
                    && face.InnerVertices is not { Count: > 0 })
                && TopologyMatches(faces, includeInnerRings: false,
                    8, 16, 12,
                    new Dictionary<int, int> { [1] = 8, [2] = 4 }, [4]);
        }

        var primaryCandidates = sourceSolids.Where(ExactPrimary).ToList();
        var closedCandidates = sourceSolids.Where(ExactClosedFragment).ToList();
        var openTubeCandidates = sourceSolids.Where(ExactOpenTube).ToList();
        if (primaryCandidates.Count != 1
            || closedCandidates.Count != 1
            || openTubeCandidates.Count != 1
            || new[]
            {
                primaryCandidates[0], closedCandidates[0],
                openTubeCandidates[0],
            }.Distinct(ReferenceEqualityComparer.Instance).Count() != 3)
        {
            rejectionReason = "solid-roles";
            return false;
        }
        GeoBrepSolid primarySolid = primaryCandidates[0];
        GeoBrepSolid closedSolid = closedCandidates[0];
        GeoBrepSolid openTubeSolid = openTubeCandidates[0];
        var primaryFaces = SolidFaces(primarySolid);
        var closedFaces = SolidFaces(closedSolid);
        var openTubeFaces = SolidFaces(openTubeSolid);

        if (!TopologyMatches(rebuiltFaces, includeInnerRings: false,
                20, 52, 30,
                new Dictionary<int, int> { [1] = 8, [2] = 22 }, [8, 4])
            || !TopologyMatches(rebuiltFaces, includeInnerRings: true,
                20, 60, 30,
                new Dictionary<int, int> { [2] = 30 }, [12])
            || primaryFaces.Any(sourceFace =>
                rebuiltFaces.Count(rebuiltFace =>
                    FacesEqual(sourceFace, rebuiltFace)) != 1)
            || rebuiltFaces.Any(rebuiltFace =>
                primaryFaces.Count(sourceFace =>
                    FacesEqual(sourceFace, rebuiltFace)) != 1)
            || closedFaces.Concat(openTubeFaces).Any(sourceFace =>
                rebuiltFaces.Any(rebuiltFace => RingsEqual(
                    sourceFace.OuterVertices!, rebuiltFace.OuterVertices!))))
        {
            rejectionReason = "source-rebuilt-bijection";
            return false;
        }

        var unownedIndices = Enumerable.Range(0, sourceFaces.Count)
            .Where(index => !ownedIndices.Contains(index)).ToList();
        var primaryOuterPoints = primaryFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        long primaryMinimumZ = primaryOuterPoints
            .Select(IfcPrecisionKeyFeet).Min(key => key.Z);
        long primaryMaximumZ = primaryOuterPoints
            .Select(IfcPrecisionKeyFeet).Max(key => key.Z);
        var primaryMinimumCaps = primaryFaces.Where(face =>
                face.InnerVertices is not { Count: > 0 }
                && CleanRing(face.OuterVertices!).Count == 4
                && face.OuterVertices!.Select(IfcPrecisionKeyFeet)
                    .All(key => key.Z == primaryMinimumZ))
            .ToList();
        var primaryMaximumCaps = primaryFaces.Where(face =>
                face.InnerVertices is not { Count: > 0 }
                && CleanRing(face.OuterVertices!).Count == 4
                && face.OuterVertices!.Select(IfcPrecisionKeyFeet)
                    .All(key => key.Z == primaryMaximumZ))
            .ToList();
        if (unownedIndices.Count > 1
            || primaryMinimumCaps.Count != 1
            || primaryMaximumCaps.Count != 1)
        {
            rejectionReason = "unowned-face-count-or-cap-role";
            return false;
        }

        double wallDx = location.EndPoint[0] - location.StartPoint[0];
        double wallDy = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(wallDx * wallDx + wallDy * wallDy);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength))
        {
            rejectionReason = "wall-axis";
            return false;
        }
        double wallAxisX = wallDx / wallAxisLength;
        double wallAxisY = wallDy / wallAxisLength;
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        (long Along, long Normal, long Z) ProjectInWallFrame(
            IReadOnlyList<double> point) =>
        (
            IfcPrecisionBinMetres((point[0] * wallAxisX
                + point[1] * wallAxisY) * FeetToMetres),
            IfcPrecisionBinMetres((point[0] * wallNormalX
                + point[1] * wallNormalY) * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres)
        );

        bool ExactAxisAlignedRectangle(
            IEnumerable<double[]> points,
            out (long AlongMinimum, long AlongMaximum,
                long NormalMinimum, long NormalMaximum) rectangle)
        {
            rectangle = default;
            var projected = points.Select(ProjectInWallFrame).ToList();
            var along = projected.Select(value => value.Along)
                .Distinct().Order().ToList();
            var normal = projected.Select(value => value.Normal)
                .Distinct().Order().ToList();
            if (projected.Count != 4 || projected.Distinct().Count() != 4
                || along.Count != 2 || normal.Count != 2
                || projected.Select(value => (value.Along, value.Normal))
                    .Distinct().Count() != 4)
                return false;
            rectangle = (along[0], along[1], normal[0], normal[1]);
            return rectangle.AlongMaximum - rectangle.AlongMinimum > 2
                && rectangle.NormalMaximum - rectangle.NormalMinimum > 2;
        }

        if (unownedIndices.Count == 1)
        {
            GeoFace unownedFace = sourceFaces[unownedIndices[0]];
            var unownedRing = CleanRing(unownedFace.OuterVertices ?? []);
            var minimumCapRing = CleanRing(
                primaryMinimumCaps[0].OuterVertices!);
            var maximumCapRing = CleanRing(
                primaryMaximumCaps[0].OuterVertices!);
            if (!ExactFaceAuthority(unownedFace)
                || unownedFace.InnerVertices is { Count: > 0 }
                || unownedRing.Count != 4
                || unownedRing.Select(ProjectInWallFrame)
                    .Any(key => key.Z != primaryMaximumZ)
                || !PlanCycleEdges(unownedRing)
                    .SetEquals(PlanCycleEdges(minimumCapRing))
                || !ExactAxisAlignedRectangle(
                    unownedRing, out var unownedRectangle)
                || !ExactAxisAlignedRectangle(
                    maximumCapRing, out var maximumCapRectangle)
                || unownedRectangle.AlongMinimum
                    < maximumCapRectangle.AlongMinimum
                || unownedRectangle.AlongMaximum
                    > maximumCapRectangle.AlongMaximum
                || unownedRectangle.NormalMinimum
                    < maximumCapRectangle.NormalMinimum
                || unownedRectangle.NormalMaximum
                    > maximumCapRectangle.NormalMaximum)
            {
                rejectionReason = "unowned-maximum-cap-mate";
                return false;
            }
        }

        var rebuiltSides = rebuiltFaces.Where(face =>
                CleanRing(face.OuterVertices!).Count == 6
                && face.InnerVertices is [{ Count: 4 }])
            .ToList();
        var rebuiltConnectors = rebuiltFaces.Except(rebuiltSides).ToList();
        if (rebuiltSides.Count != 2
            || rebuiltConnectors.Count != 10
            || rebuiltConnectors.Any(face =>
                CleanRing(face.OuterVertices!).Count != 4
                || face.InnerVertices is { Count: > 0 }))
        {
            rejectionReason = "rebuilt-side-connector-contract";
            return false;
        }
        var outerSideKeys = rebuiltSides.SelectMany(face =>
                CleanRing(face.OuterVertices!))
            .Select(IfcPrecisionKeyFeet).ToHashSet();
        var holeSideKeys = rebuiltSides.SelectMany(face =>
                CleanRing(face.InnerVertices![0]))
            .Select(IfcPrecisionKeyFeet).ToHashSet();
        var outerConnectors = rebuiltConnectors.Where(face =>
                CleanRing(face.OuterVertices!).Select(IfcPrecisionKeyFeet)
                    .All(outerSideKeys.Contains))
            .ToList();
        var holeConnectors = rebuiltConnectors.Where(face =>
                CleanRing(face.OuterVertices!).Select(IfcPrecisionKeyFeet)
                    .All(holeSideKeys.Contains))
            .ToList();
        if (outerSideKeys.Overlaps(holeSideKeys)
            || outerConnectors.Count != 6 || holeConnectors.Count != 4
            || outerConnectors.Concat(holeConnectors).Distinct(
                    ReferenceEqualityComparer.Instance).Count() != 10)
        {
            rejectionReason = "outer-reveal-partition";
            return false;
        }

        static GeoFace WithoutHoles(GeoFace source) => new()
        {
            Origin = (double[])source.Origin.Clone(),
            Normal = (double[])source.Normal.Clone(),
            OuterVertices = source.OuterVertices is { } outer
                ? new List<double[]>(outer) : null,
        };
        var outerFaces = rebuiltSides.Select(WithoutHoles)
            .Concat(outerConnectors.Select(WithoutHoles)).ToList();
        var outerIndices = Enumerable.Range(0, outerFaces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                outerFaces, outerIndices, out var orientedOuterFaces,
                triangulateNonPlanarFaces: false))
        {
            rejectionReason = "outer-shell";
            return false;
        }
        var revealFaces = rebuiltSides.Select(face => new GeoFace
            {
                OuterVertices = new List<double[]>(face.InnerVertices![0]),
            })
            .Concat(holeConnectors.Select(WithoutHoles)).ToList();
        var revealIndices = Enumerable.Range(0, revealFaces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                revealFaces, revealIndices, out _,
                triangulateNonPlanarFaces: false))
        {
            rejectionReason = "reveal-shell";
            return false;
        }

        outerSteppedBoundary = new GeometryData
        {
            BoundingBox = rebuiltBoundary.BoundingBox is { Length: 6 }
                rebuiltBounds ? (double[])rebuiltBounds.Clone()
                : bounds.Take(6).ToArray(),
            Faces = orientedOuterFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = outerIndices,
                    IsClosed = true,
                },
            ],
        };
        if (!TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
                outerSteppedBoundary, location, widthFt, bounds,
                out var minimumCapBoundary, out string minimumCapReason))
        {
            rejectionReason = $"minimum-cap-{minimumCapReason}";
            outerSteppedBoundary = new GeometryData();
            return false;
        }

        (long MinimumAlong, long MaximumAlong, long MinimumNormal,
            long MaximumNormal, long MinimumZ, long MaximumZ) Range(
                IEnumerable<GeoFace> faces)
        {
            var values = faces.SelectMany(face =>
                    (face.OuterVertices ?? []).Concat(
                        (face.InnerVertices ?? []).SelectMany(ring => ring)))
                .Select(ProjectInWallFrame).ToList();
            return (values.Min(value => value.Along),
                values.Max(value => value.Along),
                values.Min(value => value.Normal),
                values.Max(value => value.Normal),
                values.Min(value => value.Z),
                values.Max(value => value.Z));
        }
        var grossRange = Range(minimumCapBoundary.Faces!);
        var closedRange = Range(closedFaces);
        var openTubeRange = Range(openTubeFaces);
        bool StrictlyInsideAlongAndZ(
            (long MinimumAlong, long MaximumAlong, long MinimumNormal,
                long MaximumNormal, long MinimumZ, long MaximumZ) value) =>
            grossRange.MinimumAlong + 2 < value.MinimumAlong
            && value.MinimumAlong + 2 < value.MaximumAlong
            && value.MaximumAlong + 2 < grossRange.MaximumAlong
            && grossRange.MinimumZ + 2 < value.MinimumZ
            && value.MinimumZ + 2 < value.MaximumZ
            && value.MaximumZ + 2 < grossRange.MaximumZ;
        bool positiveExteriorOrder =
            grossRange.MaximumNormal + 2 < closedRange.MinimumNormal
            && closedRange.MinimumNormal + 2 < closedRange.MaximumNormal
            && closedRange.MaximumNormal + 2 < openTubeRange.MinimumNormal
            && openTubeRange.MinimumNormal + 2 < openTubeRange.MaximumNormal;
        bool negativeExteriorOrder =
            openTubeRange.MaximumNormal + 2 < closedRange.MinimumNormal
            && closedRange.MinimumNormal + 2 < closedRange.MaximumNormal
            && closedRange.MaximumNormal + 2 < grossRange.MinimumNormal
            && openTubeRange.MinimumNormal + 2 < openTubeRange.MaximumNormal;
        if (!StrictlyInsideAlongAndZ(closedRange)
            || !StrictlyInsideAlongAndZ(openTubeRange)
            || positiveExteriorOrder == negativeExteriorOrder)
        {
            rejectionReason = "detached-fragment-frame";
            outerSteppedBoundary = new GeometryData();
            return false;
        }

        double operandAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(operandAxisLength > 0) || !double.IsFinite(operandAxisLength)
            || Math.Abs(Math.Abs((operand.AxisX * wallAxisX
                    + operand.AxisY * wallAxisY) / operandAxisLength) - 1)
                > 4096 * 2.2204460492503131e-16)
        {
            rejectionReason = "operand-axis";
            outerSteppedBoundary = new GeometryData();
            return false;
        }
        double operandAxisX = operand.AxisX / operandAxisLength;
        double operandAxisY = operand.AxisY / operandAxisLength;
        double operandNormalX = -operandAxisY;
        double operandNormalY = operandAxisX;
        long OperandAlong(double value) =>
            IfcPrecisionBinMetres(value * FeetToMetres);
        long operandCentreAlong = OperandAlong(
            operand.CentreXFt * operandAxisX
            + operand.CentreYFt * operandAxisY);
        long operandCentreNormal = OperandAlong(
            operand.CentreXFt * operandNormalX
            + operand.CentreYFt * operandNormalY);
        long operandMinimumNormal = OperandAlong(
            operand.CentreXFt * operandNormalX
            + operand.CentreYFt * operandNormalY - operand.DepthFt / 2);
        long operandMaximumNormal = OperandAlong(
            operand.CentreXFt * operandNormalX
            + operand.CentreYFt * operandNormalY + operand.DepthFt / 2);
        long breakpointNormal = OperandAlong(
            steppedProfile.BreakpointNormalFt);
        var outerProfile = (
            MinimumAlong: OperandAlong(
                operand.CentreXFt * operandAxisX
                + operand.CentreYFt * operandAxisY - operand.WidthFt / 2),
            MaximumAlong: OperandAlong(
                operand.CentreXFt * operandAxisX
                + operand.CentreYFt * operandAxisY + operand.WidthFt / 2),
            MinimumZ: OperandAlong(operand.BaseZFt),
            MaximumZ: OperandAlong(operand.BaseZFt + operand.HeightFt));
        var innerProfile = (
            MinimumAlong: OperandAlong(
                operand.CentreXFt * operandAxisX
                + operand.CentreYFt * operandAxisY
                - steppedProfile.InnerWidthFt / 2),
            MaximumAlong: OperandAlong(
                operand.CentreXFt * operandAxisX
                + operand.CentreYFt * operandAxisY
                + steppedProfile.InnerWidthFt / 2),
            MinimumZ: OperandAlong(operand.BaseZFt),
            MaximumZ: OperandAlong(
                operand.BaseZFt + steppedProfile.InnerHeightFt));
        if (!(outerProfile.MinimumAlong < innerProfile.MinimumAlong
                && innerProfile.MaximumAlong < outerProfile.MaximumAlong
                && innerProfile.MinimumZ == outerProfile.MinimumZ
                && innerProfile.MaximumZ < outerProfile.MaximumZ)
            || operandMinimumNormal >= operandMaximumNormal
            || breakpointNormal <= operandMinimumNormal
            || breakpointNormal >= operandMaximumNormal
            || operandCentreAlong is long.MinValue or long.MaxValue
            || operandCentreNormal is long.MinValue or long.MaxValue)
        {
            rejectionReason = "operand-profile";
            outerSteppedBoundary = new GeometryData();
            return false;
        }

        bool TryHoleRole(GeoFace face, out bool isInner,
            out int breakpointSide, out string holeReason)
        {
            isInner = false;
            breakpointSide = 0;
            holeReason = "inner-ring";
            if (face.InnerVertices is not [{ Count: 4 } innerSource])
                return false;
            var ring = CleanRing(innerSource);
            var projected = ring.Select(point => (
                Along: OperandAlong(point[0] * operandAxisX
                    + point[1] * operandAxisY),
                Normal: OperandAlong(point[0] * operandNormalX
                    + point[1] * operandNormalY),
                Z: OperandAlong(point[2]))).ToList();
            static List<(long Minimum, long Maximum)> Levels(
                IEnumerable<long> source)
            {
                var values = source.Distinct().Order().ToList();
                var result = new List<(long Minimum, long Maximum)>();
                foreach (long value in values)
                {
                    if (result.Count == 0
                        || value - result[^1].Maximum > 2)
                    {
                        result.Add((value, value));
                        continue;
                    }
                    result[^1] = (result[^1].Minimum, value);
                }
                return result;
            }
            static bool Near(long first, long second) =>
                Math.Abs(first - second) <= 2;
            var along = Levels(projected.Select(value => value.Along));
            var normal = Levels(projected.Select(value => value.Normal));
            var z = Levels(projected.Select(value => value.Z));
            if (projected.Count != 4 || projected.Distinct().Count() != 4
                || along.Count != 2 || normal.Count != 1 || z.Count != 2
                || projected.Select(value => (
                        Along: along.FindIndex(level =>
                            value.Along >= level.Minimum
                            && value.Along <= level.Maximum),
                        Z: z.FindIndex(level =>
                            value.Z >= level.Minimum
                            && value.Z <= level.Maximum)))
                    .Distinct().Count() != 4
                || normal[0].Minimum < operandMinimumNormal - 2
                || normal[0].Maximum > operandMaximumNormal + 2)
            {
                holeReason =
                    $"levels-a{string.Join(',', along.Select(level => $"{level.Minimum}..{level.Maximum}"))}"
                    + $"-n{string.Join(',', normal.Select(level => $"{level.Minimum}..{level.Maximum}"))}"
                    + $"-z{string.Join(',', z.Select(level => $"{level.Minimum}..{level.Maximum}"))}"
                    + $"-depth{operandMinimumNormal}..{operandMaximumNormal}";
                return false;
            }
            bool ProfileMatches((long MinimumAlong, long MaximumAlong,
                    long MinimumZ, long MaximumZ) expected) =>
                Near(along[0].Minimum, expected.MinimumAlong)
                && Near(along[0].Maximum, expected.MinimumAlong)
                && Near(along[1].Minimum, expected.MaximumAlong)
                && Near(along[1].Maximum, expected.MaximumAlong)
                && Near(z[0].Minimum, expected.MinimumZ)
                && Near(z[0].Maximum, expected.MinimumZ)
                && Near(z[1].Minimum, expected.MaximumZ)
                && Near(z[1].Maximum, expected.MaximumZ);
            bool matchesOuter = ProfileMatches(outerProfile);
            bool matchesInner = ProfileMatches(innerProfile);
            if (matchesOuter == matchesInner)
            {
                holeReason =
                    $"profile-a{along[0].Minimum}..{along[0].Maximum},"
                    + $"{along[1].Minimum}..{along[1].Maximum}"
                    + $"-z{z[0].Minimum}..{z[0].Maximum},"
                    + $"{z[1].Minimum}..{z[1].Maximum}"
                    + $"-outer{outerProfile.MinimumAlong}..{outerProfile.MaximumAlong},"
                    + $"{outerProfile.MinimumZ}..{outerProfile.MaximumZ}"
                    + $"-inner{innerProfile.MinimumAlong}..{innerProfile.MaximumAlong},"
                    + $"{innerProfile.MinimumZ}..{innerProfile.MaximumZ}";
                return false;
            }
            if (normal[0].Maximum < breakpointNormal - 2)
                breakpointSide = -1;
            else if (normal[0].Minimum > breakpointNormal + 2)
                breakpointSide = 1;
            else if (normal[0].Minimum < breakpointNormal - 2
                     || normal[0].Maximum > breakpointNormal + 2)
            {
                holeReason =
                    $"breakpoint-straddle-n{normal[0].Minimum}..{normal[0].Maximum}"
                    + $"-at{breakpointNormal}";
                return false;
            }
            isInner = matchesInner;
            holeReason = "exact-profile-role";
            return true;
        }

        var primaryProfileRoles = new List<bool>();
        var primaryProfileSides = new List<int>();
        foreach (GeoFace face in primaryFaces.Where(face =>
                     face.InnerVertices is { Count: > 0 }))
        {
            if (!TryHoleRole(face, out bool isInner,
                    out int breakpointSide,
                    out string holeReason))
            {
                rejectionReason = $"primary-writer-profile-{holeReason}";
                outerSteppedBoundary = new GeometryData();
                return false;
            }
            primaryProfileRoles.Add(isInner);
            primaryProfileSides.Add(breakpointSide);
        }
        var closedProfileRoles = new List<bool>();
        var closedProfileSides = new List<int>();
        foreach (GeoFace face in closedFaces.Where(face =>
                     face.InnerVertices is { Count: > 0 }))
        {
            if (!TryHoleRole(face, out bool isInner,
                    out int breakpointSide,
                    out string holeReason))
            {
                rejectionReason = $"closed-writer-profile-{holeReason}";
                outerSteppedBoundary = new GeometryData();
                return false;
            }
            closedProfileRoles.Add(isInner);
            closedProfileSides.Add(breakpointSide);
        }
        int innerSide = steppedProfile.InnerAtMinimum ? -1 : 1;
        int outerSide = -innerSide;
        if (primaryProfileRoles.Count != 2
            || primaryProfileRoles.Any(isInner => !isInner)
            || closedProfileRoles.Count != 2
            || closedProfileRoles.Any(isInner => isInner)
            || primaryProfileSides.Any(side => side != 0 && side != innerSide)
            || !primaryProfileSides.Contains(innerSide)
            || closedProfileSides.Any(side => side != 0 && side != outerSide)
            || !closedProfileSides.Contains(outerSide))
        {
            rejectionReason = "writer-profile-pairs";
            outerSteppedBoundary = new GeometryData();
            return false;
        }

        authoritativeSourceFaces = primaryFaces;
        rejectionReason = "exact-mixed-component-open-stepped-minimum-cap";
        return true;
    }

    /// <summary>
    /// Uses the exact minimum-cap extrusion of an open stepped join shell when the only emitted
    /// opening has the independent source-wall-profile/mapped-breakpoint contract.
    /// </summary>
    internal static bool
        TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithExactSourceOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData exactBoundary,
            out IReadOnlyList<int> cutterElementIds)
        => TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithExactSourceOpening(
            wall, bounds, rebuiltBoundary, elemById,
            emittedHostedCutterIdsByWall,
            emittedHostedOpeningOperandsByWall,
            standaloneOpeningIdsByWall,
            out exactBoundary, out cutterElementIds,
            out _);

    internal static bool
        TryGetVerifiedWallBoundaryFromOpenSteppedMinimumCapShellWithExactSourceOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData exactBoundary,
            out IReadOnlyList<int> cutterElementIds,
            out bool usesExactMixedComponentSourceAuthority)
    {
        exactBoundary = new GeometryData();
        cutterElementIds = [];
        usesExactMixedComponentSourceAuthority = false;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1"
            || Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, int cutterId = 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCOPENSTEPEXACTSOURCEGATE wall={wall.Id} "
                    + $"cutter={cutterId} result=reject stage={stage}");
            return false;
        }

        if (standaloneOpeningIdsByWall != null
            && standaloneOpeningIdsByWall.TryGetValue(
                wall.Id, out var standaloneIds)
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (emittedHostedCutterIdsByWall == null
            || !emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedIds)
            || emittedIds.Count != 1
            || emittedIds.Distinct().Count() != emittedIds.Count)
            return Reject($"emitted-cutters-{(emittedHostedCutterIdsByWall != null
                && emittedHostedCutterIdsByWall.TryGetValue(
                    wall.Id, out var rejectedIds)
                    ? rejectedIds.Count : 0)}");
        int cutterId = emittedIds[0];
        if (wall.CuttingElementIds is { Count: > 0 } decodedIds
            && (decodedIds.Distinct().Count() != decodedIds.Count
                || !decodedIds.ToHashSet().SetEquals(emittedIds)))
            return Reject("decoded-cutter-set", cutterId);
        if (emittedHostedOpeningOperandsByWall == null
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var emittedOperands)
            || emittedOperands.Count != 1
            || emittedOperands[0].CutterId != cutterId)
            return Reject($"emitted-operands-{(
                emittedHostedOpeningOperandsByWall != null
                && emittedHostedOpeningOperandsByWall.TryGetValue(
                    wall.Id, out var rejectedOperands)
                    ? rejectedOperands.Count : 0)}", cutterId);
        HostedOpeningGeometry operand = emittedOperands[0].Operand;
        bool exactSourceWallProfilesMappedBreakpointOpening =
            IsExactSourceWallProfilesMappedBreakpointOpening(operand);
        bool exactCompleteOpenTwelveFaceMinimumCapWriter =
            HasExactCompleteOpenTwelveFaceNoAlternativeSourceAuthority(
                wall.Geometry)
            && operand.ExactDepth
            && operand.Boundary == null
            && operand.SteppedProfile == null
            && !operand.IsFamilyCutLoop
            && operand.IsExactFamilyCutLoopWriterBox
            && !operand.IsExactSerializedDefinition
            && !operand.IsExactConcordantFamilyCut
            && !operand.IsExactMappedSideShell
            && !operand.IsExactSourceWallProfilesMappedBreakpoint
            && !operand.IsExactParameterizedRectangularCut
            && !operand.IsExactAuthoredMultiHostEnvelope
            && !operand.IsExactRecoveredClosedFamilyCutProfile
            && !operand.IsExactAuthoredRevealWriterBox
            && !operand.IsExactParameterizedReveal;
        if (!exactSourceWallProfilesMappedBreakpointOpening
            && !exactCompleteOpenTwelveFaceMinimumCapWriter)
            return Reject("operand-provenance", cutterId);
        if (wall.Geometry is not
                { Faces: { Count: >= 8 } sourceFaces,
                    BrepSolids: { Count: > 0 } sourceSolids })
            return Reject("open-source-shell", cutterId);
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || location.StartPoint is not { Length: >= 3 }
            || location.EndPoint is not { Length: >= 3 }
            || location.StartPoint.Take(3).Concat(location.EndPoint.Take(3))
                .Any(value => !double.IsFinite(value))
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, bounds))
            return Reject("wall-definition", cutterId);
        bool exactMixedComponentSource = false;
        GeometryData mixedComponentOuterSteppedBoundary = new();
        IReadOnlyList<GeoFace> mixedComponentAuthoritativeSourceFaces = [];
        if (sourceSolids.Any(solid => solid.IsClosed))
        {
            string mixedComponentReason = "operand-provenance";
            if (!exactSourceWallProfilesMappedBreakpointOpening
                || !TryGetExactMixedComponentOpenSteppedMinimumCapSourceAuthority(
                    wall, bounds, rebuiltBoundary, operand,
                    out mixedComponentOuterSteppedBoundary,
                    out mixedComponentAuthoritativeSourceFaces,
                    out mixedComponentReason))
                return Reject(
                    $"mixed-source-{mixedComponentReason}", cutterId);
            exactMixedComponentSource = true;
        }
        GeometryData candidateBoundary;
        LocationCurve exactMinimumCapLocation = location;
        string boundaryReason;
        if (exactCompleteOpenTwelveFaceMinimumCapWriter)
        {
            if (!elemById.TryGetValue(cutterId, out var exactForwardCutter)
                || exactForwardCutter.SerializedHostId is not
                    { } exactDirectHostId
                || exactDirectHostId == wall.Id
                || !elemById.TryGetValue(
                    exactDirectHostId, out var exactDirectHost)
                || exactDirectHost.CategoryId != -2000011
                || !TryGetSerializedWallWidthFeet(
                    exactDirectHost, out double exactDirectHostWidthFt)
                || IfcPrecisionBinMetres(
                        operand.DepthFt * FeetToMetres)
                    != IfcPrecisionBinMetres(
                        exactDirectHostWidthFt * FeetToMetres)
                || (exactForwardCutter.ExtraHostIds?
                        .Count(id => id == wall.Id) ?? 0)
                    + (exactForwardCutter.ExplicitHostIds?
                        .Count(id => id == wall.Id) ?? 0) != 1
                || exactForwardCutter.References?
                    .Count(id => id == wall.Id) != 1
                || wall.References?.Count(id => id == cutterId) != 1
                || exactForwardCutter.References?
                    .Count(id => id == exactDirectHostId) != 1
                || exactDirectHost.References?
                    .Count(id => id == cutterId) != 1)
                return Reject("forward-direct-host-authority", cutterId);
            if (!TryGetExactVerticalWallBoundaryFromCompleteOpenTwelveFaceMinimumCapShell(
                    wall, rebuiltBoundary, bounds,
                    out candidateBoundary,
                    out exactMinimumCapLocation,
                    out boundaryReason))
                return Reject(boundaryReason, cutterId);
        }
        else if (!TryGetExactVerticalWallBoundaryFromOpenSteppedMinimumCapShell(
                     exactMixedComponentSource
                         ? mixedComponentOuterSteppedBoundary
                         : rebuiltBoundary,
                     location, widthFt, bounds,
                     out candidateBoundary, out boundaryReason))
            return Reject(boundaryReason, cutterId);

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }

        var sourceIndexedFaces = new List<GeoFace>();
        if (exactMixedComponentSource)
        {
            sourceIndexedFaces.AddRange(
                mixedComponentAuthoritativeSourceFaces);
        }
        else
        {
            foreach (GeoBrepSolid sourceSolid in sourceSolids)
            {
                if (sourceSolid.FaceIndices.Count < 4
                    || sourceSolid.FaceIndices.Distinct().Count()
                        != sourceSolid.FaceIndices.Count
                    || sourceSolid.FaceIndices.Any(index =>
                        index < 0 || index >= sourceFaces.Count))
                    return Reject("source-face-indices", cutterId);
                sourceIndexedFaces.AddRange(sourceSolid.FaceIndices
                    .Select(index => sourceFaces[index]));
            }
        }
        var sourceInnerRings = sourceIndexedFaces
            .SelectMany(face => face.InnerVertices ?? [])
            .ToList();
        bool HasBasicOuterAuthority(GeoFace face) =>
            face.OuterVertices is { Count: >= 3 } outer
            && face.AlternativeOuterVertices is not { Count: > 0 }
            && outer.All(point => point.Length >= 3
                && double.IsFinite(point[0])
                && double.IsFinite(point[1])
                && double.IsFinite(point[2]));
        int invalidSourceOuterFaces = sourceIndexedFaces.Count(face =>
            !HasBasicOuterAuthority(face));
        int collapsedSourceOuterFaces = sourceIndexedFaces.Count(face =>
            HasBasicOuterAuthority(face)
            && FaceCollapsesAtIfcPrecision(face));
        int collapsedSourceOuterFacesWithInner =
            sourceIndexedFaces.Count(face =>
                HasBasicOuterAuthority(face)
                && FaceCollapsesAtIfcPrecision(face)
                && face.InnerVertices is { Count: > 0 });
        int invalidSourceInnerRings = sourceInnerRings.Count(ring =>
            ring.Count < 3
            || !FaceCanEmitAtIfcPrecision(
                new GeoFace { OuterVertices = ring }));
        bool exactSourceFaceAuthority =
            invalidSourceOuterFaces == 0
            && collapsedSourceOuterFacesWithInner == 0
            && invalidSourceInnerRings == 0
            && (exactCompleteOpenTwelveFaceMinimumCapWriter
                ? collapsedSourceOuterFaces == 0
                    && sourceInnerRings.Count == 0
                : sourceInnerRings.Count >= 2);
        if (!exactSourceFaceAuthority)
            return Reject("source-face-authority"
                + $"-outer-{invalidSourceOuterFaces}"
                + $"-collapsed-{collapsedSourceOuterFaces}"
                + $"-collapsed-inner-{collapsedSourceOuterFacesWithInner}"
                + $"-inner-{sourceInnerRings.Count}"
                + $"-invalid-inner-{invalidSourceInnerRings}", cutterId);

        long minimumZ = candidateBoundary.Faces
            .SelectMany(face => face.OuterVertices!)
            .Select(IfcPrecisionKeyFeet).Min(key => key.Z);
        var candidateMinimumCaps = candidateBoundary.Faces
            .Select(face => CleanRing(face.OuterVertices!))
            .Where(ring => ring.All(point =>
                IfcPrecisionKeyFeet(point).Z == minimumZ))
            .ToList();
        if (candidateMinimumCaps.Count != 1)
            return Reject(
                $"minimum-cap-count-{candidateMinimumCaps.Count}", cutterId);
        var minimumCapKeys = candidateMinimumCaps[0]
            .Select(IfcPrecisionKeyFeet).ToHashSet();
        var minimumCapPlanKeys = minimumCapKeys
            .Select(key => (key.X, key.Y)).ToHashSet();
        int matchingSourceMinimumCaps = sourceIndexedFaces.Count(face =>
        {
            if (face.InnerVertices is { Count: > 0 })
                return false;
            var ring = CleanRing(face.OuterVertices!);
            if (ring.Count != 4)
                return false;
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return exactCompleteOpenTwelveFaceMinimumCapWriter
                ? keys.Select(key => key.Z).Distinct().Count() == 1
                    && keys.Select(key => (key.X, key.Y)).ToHashSet()
                        .SetEquals(minimumCapPlanKeys)
                : keys.All(key => key.Z == minimumZ)
                    && keys.ToHashSet().SetEquals(minimumCapKeys);
        });
        if (matchingSourceMinimumCaps != 1)
            return Reject(
                $"source-minimum-cap-matches-{matchingSourceMinimumCaps}",
                cutterId);

        string openingReason;
        string subdivisionReason = "not-required";
        if (exactCompleteOpenTwelveFaceMinimumCapWriter)
        {
            bool exactBoundaryTouch =
                candidateBoundary.BoundingBox is
                    { Length: 6 } exactMinimumCapBounds
                && HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
                    exactMinimumCapLocation, widthFt,
                    exactMinimumCapBounds, candidateBoundary, operand);
            openingReason = exactBoundaryTouch
                ? "exact-direct-host-clipped-vertical-plan-boundary-touch"
                : "direct-host-clipped-opening-not-boundary-touching";
            if (!exactBoundaryTouch)
                return Reject($"opening-{openingReason}", cutterId);
        }
        else
        {
            IReadOnlyList<double> openingWallBounds = bounds;
            if (exactMixedComponentSource)
            {
                if (candidateBoundary.BoundingBox is not
                        { Length: 6 } exactMixedBodyBounds
                    || exactMixedBodyBounds.Any(value =>
                        !double.IsFinite(value)))
                    return Reject(
                        "mixed-source-body-bounds", cutterId);
                openingWallBounds = exactMixedBodyBounds;
            }
            if (!ExactSourceSteppedOpeningIsRobustInteriorThroughCutOfExactWall(
                    wall, openingWallBounds, candidateBoundary, operand,
                    out openingReason))
                return Reject($"opening-{openingReason}", cutterId);

            if (exactMixedComponentSource)
            {
                subdivisionReason =
                    "not-required-exact-mixed-source-rectangular-minimum-cap";
            }
            else
            {
                if (!TryGetExactSourceOpeningWallMinimumCapSubdivisions(
                        wall, elemById, candidateBoundary,
                        out var subdividedBoundary, out subdivisionReason))
                    return Reject(
                        $"subdivision-{subdivisionReason}", cutterId);
                candidateBoundary = subdividedBoundary;
            }
        }

        exactBoundary = candidateBoundary;
        cutterElementIds = [cutterId];
        usesExactMixedComponentSourceAuthority = exactMixedComponentSource;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCOPENSTEPEXACTSOURCEGATE wall={wall.Id} "
                + $"cutter={cutterId} result=accept "
                + $"stage={(exactCompleteOpenTwelveFaceMinimumCapWriter
                    ? openingReason
                    : exactMixedComponentSource
                    ? "exact-mixed-component-open-stepped-minimum-cap-source-opening"
                    : "exact-open-stepped-minimum-cap-source-opening")} "
                + $"pathSubdivisionStage={subdivisionReason}");
        return true;
    }

    /// <summary>
    /// Promotes the complete reference-only 14-face bottom-slot source only when precomputation
    /// materialized the same exact family writer.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromCompleteOpenFourteenFaceBottomSlotFamilyCutOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            IReadOnlySet<(int WallId, int CutterId)>?
                exactReferenceOnlySixPointJoinBottomSlotFamilyCutPairs,
            out GeometryData grossBoundary,
            out IReadOnlyList<int> cutterElementIds)
    {
        grossBoundary = new GeometryData();
        cutterElementIds = [];
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, int cutterId = 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCFOURTEENFACEBOTTOMSLOTGATE wall={wall.Id} "
                    + $"cutter={cutterId} result=reject stage={stage}");
            return false;
        }

        if (standaloneOpeningIdsByWall?.TryGetValue(
                wall.Id, out var standaloneIds) == true
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (wall.CuttingElementIds is { Count: > 0 })
            return Reject("decoded-cutters");
        if (emittedHostedCutterIdsByWall == null
            || !emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedIds)
            || emittedIds.Count != 1
            || emittedIds.Distinct().Count() != 1)
            return Reject($"emitted-cutters-{(
                emittedHostedCutterIdsByWall != null
                && emittedHostedCutterIdsByWall.TryGetValue(
                    wall.Id, out var rejectedIds)
                    ? rejectedIds.Count : 0)}");
        int cutterId = emittedIds[0];
        if (exactReferenceOnlySixPointJoinBottomSlotFamilyCutPairs == null
            || !exactReferenceOnlySixPointJoinBottomSlotFamilyCutPairs
                .Contains((wall.Id, cutterId)))
            return Reject("precomputed-pair", cutterId);
        if (emittedHostedOpeningOperandsByWall == null
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var emittedOperands)
            || emittedOperands.Count != 1
            || emittedOperands[0].CutterId != cutterId)
            return Reject($"emitted-operands-{(
                emittedHostedOpeningOperandsByWall != null
                && emittedHostedOpeningOperandsByWall.TryGetValue(
                    wall.Id, out var rejectedOperands)
                    ? rejectedOperands.Count : 0)}", cutterId);
        HostedOpeningGeometry operand = emittedOperands[0].Operand;
        if (!TryGetExactCompleteOpenFourteenFaceBottomSlotFamilyCutGeometry(
                wall, bounds, rebuiltBoundary, operand,
                out grossBoundary, out var verifiedWriter,
                out string geometryReason))
            return Reject($"geometry-{geometryReason}", cutterId);
        if (!RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                operand, verifiedWriter)
            || operand.IsFamilyCutLoop
            || !operand.IsExactFamilyCutLoopWriterBox
            || operand.Boundary != null
            || operand.SteppedProfile != null)
        {
            grossBoundary = new GeometryData();
            return Reject("emitted-writer", cutterId);
        }

        cutterElementIds = [cutterId];
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCFOURTEENFACEBOTTOMSLOTGATE wall={wall.Id} "
                + $"cutter={cutterId} result=accept "
                + "stage=exact-complete-open-fourteen-face-bottom-slot-family-cut");
        return true;
    }

    /// <summary>
    /// Recovers one exact non-rectangular gross extrusion from the paired 55/56-face joined-wall
    /// source contracts.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromExactSixPointJoinShellAndTwoProfileConcordantOpenings(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData grossBoundary,
            out IReadOnlyList<int> cutterElementIds)
    {
        grossBoundary = new GeometryData();
        cutterElementIds = [];
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1"
            || Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, IEnumerable<int>? rejectedIds = null)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCSIXPOINTTWOOPENINGGATE wall={wall.Id} "
                    + $"cutters={string.Join(',', rejectedIds ?? [])} "
                    + $"result=reject stage={stage}");
            return false;
        }

        if (standaloneOpeningIdsByWall?.TryGetValue(
                wall.Id, out var standaloneIds) == true
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (emittedHostedCutterIdsByWall == null
            || !emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedIds)
            || emittedIds.Count != 2
            || emittedIds.Distinct().Count() != 2)
            return Reject($"emitted-cutters-{(
                emittedHostedCutterIdsByWall != null
                && emittedHostedCutterIdsByWall.TryGetValue(
                    wall.Id, out var rejectedEmittedIds)
                    ? rejectedEmittedIds.Count : 0)}");
        if (wall.CuttingElementIds is { Count: > 0 } decodedIds
            && (decodedIds.Distinct().Count() != decodedIds.Count
                || !decodedIds.ToHashSet().SetEquals(emittedIds)))
            return Reject("decoded-cutter-set", emittedIds);
        if (emittedHostedOpeningOperandsByWall == null
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var emittedOperands)
            || emittedOperands.Count != 2
            || emittedOperands.Select(item => item.CutterId)
                .Distinct().Count() != 2
            || !emittedOperands.Select(item => item.CutterId)
                .ToHashSet().SetEquals(emittedIds))
            return Reject("emitted-operand-set", emittedIds);
        if (wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, bounds))
            return Reject("wall-definition", emittedIds);
        if (!HasExactSixPointJoinShellWithTwoOpeningSourceAuthority(
                wall.Geometry))
            return Reject("source-authority", emittedIds);
        if (!TryGetExactVerticalWallBoundaryFromClosedMinimumCapJoinShell(
                rebuiltBoundary, location, widthFt, bounds,
                out var exactMinimumCapBoundary,
                out string minimumCapReason,
                requireExactSixPointSideProfiles: true)
            || exactMinimumCapBoundary.BoundingBox is not { Length: 6 }
                exactMinimumCapBounds)
            return Reject($"minimum-cap-{minimumCapReason}", emittedIds);

        static List<double[]> CleanRing(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (double[] point in source)
                if (result.Count == 0
                    || IfcPrecisionKeyFeet(result[^1])
                        != IfcPrecisionKeyFeet(point))
                    result.Add(point);
            if (result.Count > 1
                && IfcPrecisionKeyFeet(result[0])
                    == IfcPrecisionKeyFeet(result[^1]))
                result.RemoveAt(result.Count - 1);
            return result;
        }
        long minimumZ = exactMinimumCapBoundary.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Select(IfcPrecisionKeyFeet).Min(key => key.Z);
        var exactMinimumCaps = exactMinimumCapBoundary.Faces
            .Select(face => CleanRing(face.OuterVertices ?? []))
            .Where(ring => ring.Count == 4
                && ring.All(point =>
                    IfcPrecisionKeyFeet(point).Z == minimumZ))
            .ToList();
        if (exactMinimumCaps.Count != 1
            || wall.Geometry?.Faces is not { Count: > 1 } sourceFaces
            || CleanRing(sourceFaces[1].OuterVertices ?? [])
                .Select(IfcPrecisionKeyFeet).ToHashSet()
                .SetEquals(exactMinimumCaps[0]
                    .Select(IfcPrecisionKeyFeet)) == false
            || sourceFaces.Count(face =>
            {
                var ring = CleanRing(face.OuterVertices ?? []);
                return ring.Count == 4
                    && ring.All(point =>
                        IfcPrecisionKeyFeet(point).Z == minimumZ)
                    && ring.Select(IfcPrecisionKeyFeet).ToHashSet()
                        .SetEquals(exactMinimumCaps[0]
                            .Select(IfcPrecisionKeyFeet));
            }) != 1)
            return Reject("source-minimum-cap", emittedIds);

        if (!TryGetUniqueReciprocalEndConnectorMinimumCapSubdivision(
                wall, elemById, exactMinimumCapBoundary,
                out var subdividedBoundary, out string subdivisionReason)
            || subdivisionReason
                != "exact-reciprocal-end-connector-minimum-cap-subdivision"
            || subdividedBoundary.BoundingBox is not { Length: 6 }
                subdividedBounds
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                subdividedBoundary, location, widthFt, subdividedBounds,
                out var subdividedPlan, out _, out _,
                out string subdividedDefinitionReason)
            || subdividedDefinitionReason
                != "exact-collinear-boundary-subdivision"
            || subdividedPlan.Count != 5)
            return Reject($"path-subdivision-{subdivisionReason}", emittedIds);

        var exactRevealDefinitions = new List<HostedOpeningGeometry>(2);
        int exactAuthoredEnvelopeCount = 0;
        int exactContainingFamilyBoundaryCount = 0;
        foreach (var emitted in emittedOperands)
        {
            if (!elemById.TryGetValue(emitted.CutterId, out var cutter)
                || cutter.BoundingBox is not { Length: 6 } cutterBounds
                || cutterBounds.Any(value => !double.IsFinite(value)))
                return Reject("cutter-definition", [emitted.CutterId]);
            double[] associationBox =
                BuildHostedOpeningAssociationBox(cutter, cutterBounds);
            if (!TryBuildHostedOpeningBoundary(
                    wall, associationBox, out var authoredReveal)
                || authoredReveal.Faces.Count != 6
                || !TryGetExactVerticalRectangularPrismSweptOpening(
                    authoredReveal, out var exactReveal))
                return Reject("authored-reveal", [emitted.CutterId]);

            HostedOpeningGeometry operand = emitted.Operand;
            if (!operand.ExactDepth
                || operand.SteppedProfile != null
                || operand.IsFamilyCutLoop)
                return Reject("operand-shape", [emitted.CutterId]);
            HostedOpeningGeometry writerDefinition = operand;
            if (operand.Boundary != null)
            {
                if (operand.Boundary.Faces.Count != 6
                    || !TryGetExactVerticalRectangularPrismSweptOpening(
                        operand.Boundary, out var boundaryDefinition)
                    || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                        boundaryDefinition, operand))
                    return Reject("operand-boundary", [emitted.CutterId]);
            }
            else if (!operand.IsExactSerializedDefinition
                && !operand.IsExactConcordantFamilyCut
                && !operand.IsExactMappedSideShell
                && !operand.IsExactParameterizedRectangularCut
                && !operand.IsExactFamilyCutLoopWriterBox
                && !operand.IsExactAuthoredMultiHostEnvelope
                && !operand.IsExactRecoveredClosedFamilyCutProfile
                && !operand.IsExactAuthoredRevealWriterBox)
                return Reject("operand-provenance", [emitted.CutterId]);

            bool revealMatchesWriter =
                RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                    exactReveal, writerDefinition);
            bool exactFamilyBoundaryContainsReveal =
                operand.Boundary != null
                && RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
                    exactReveal, writerDefinition);
            HostedOpeningGeometry sweptWriterDefinition =
                writerDefinition with { Boundary = null };
            bool robustWriterThroughCut =
                HostedOpeningWriterOperandIsRobustInteriorThroughCutOfExactWall(
                    wall, exactMinimumCapBounds, exactMinimumCapBoundary,
                    sweptWriterDefinition);
            bool singleSidePlaneCoincidentWriterRecess =
                HostedOpeningWriterOperandIsWriterPrecisionSingleSidePlaneCoincidentInteriorCutOfExactWall(
                    wall, exactMinimumCapBounds, exactMinimumCapBoundary,
                    sweptWriterDefinition);
            bool stableWriterCut = robustWriterThroughCut
                || operand.IsExactAuthoredMultiHostEnvelope
                && revealMatchesWriter
                && singleSidePlaneCoincidentWriterRecess;
            if ((operand.IsExactAuthoredMultiHostEnvelope
                    ? !revealMatchesWriter
                    : !exactFamilyBoundaryContainsReveal)
                || !stableWriterCut)
            {
                if (diagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCSIXPOINTTWOOPENINGMATCH wall={wall.Id} "
                        + $"cutter={emitted.CutterId} "
                        + $"authoredEnvelope={operand.IsExactAuthoredMultiHostEnvelope} "
                        + $"boundary={operand.Boundary != null} "
                        + $"full={revealMatchesWriter} "
                        + $"contains={exactFamilyBoundaryContainsReveal} "
                        + $"robust={robustWriterThroughCut} "
                        + $"singleSideRecess={singleSidePlaneCoincidentWriterRecess} "
                        + $"reveal=({exactReveal.CentreXFt:R},{exactReveal.CentreYFt:R};"
                        + $"{exactReveal.AxisX:R},{exactReveal.AxisY:R};"
                        + $"{exactReveal.WidthFt:R},{exactReveal.DepthFt:R};"
                        + $"{exactReveal.BaseZFt:R},{exactReveal.HeightFt:R}) "
                        + $"writer=({writerDefinition.CentreXFt:R},{writerDefinition.CentreYFt:R};"
                        + $"{writerDefinition.AxisX:R},{writerDefinition.AxisY:R};"
                        + $"{writerDefinition.WidthFt:R},{writerDefinition.DepthFt:R};"
                        + $"{writerDefinition.BaseZFt:R},{writerDefinition.HeightFt:R})");
                return Reject("reveal-writer-match", [emitted.CutterId]);
            }
            exactRevealDefinitions.Add(exactReveal);
            if (operand.IsExactAuthoredMultiHostEnvelope)
                exactAuthoredEnvelopeCount++;
            if (exactFamilyBoundaryContainsReveal)
                exactContainingFamilyBoundaryCount++;
        }
        if (exactRevealDefinitions.Count != 2
            || exactAuthoredEnvelopeCount != 1
            || exactContainingFamilyBoundaryCount != 1
            || RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                exactRevealDefinitions[0], exactRevealDefinitions[1]))
            return Reject("opening-bijection", emittedIds);

        grossBoundary = subdividedBoundary;
        cutterElementIds = emittedIds.ToArray();
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCSIXPOINTTWOOPENINGGATE wall={wall.Id} "
                + $"cutters={string.Join(',', emittedIds)} result=accept "
                + "stage=exact-six-point-join-shell-two-profile-concordant-openings "
                + $"pathSubdivisionStage={subdivisionReason}");
        return true;
    }

    internal static bool
        HasExactSixPointJoinShellWithTwoOpeningSourceAuthority(
            GeometryData? geometry)
    {
        if (geometry is not
            {
                Faces: { } faces,
                BrepSolids: { Count: 4 } solids,
            }
            || faces.Count is not (55 or 56))
            return false;
        bool firstVariant = faces.Count == 55;
        bool SolidMatches(int solidIndex, bool closed,
            IEnumerable<int> expectedIndices) =>
            solids[solidIndex].IsClosed == closed
            && solids[solidIndex].FaceIndices
                .SequenceEqual(expectedIndices);
        bool exactSolids = firstVariant
            ? SolidMatches(0, false,
                Enumerable.Range(0, 18).Concat(Enumerable.Range(40, 15)))
                && SolidMatches(1, true, Enumerable.Range(18, 10))
                && SolidMatches(2, true, Enumerable.Range(28, 6))
                && SolidMatches(3, true, Enumerable.Range(34, 6))
            : SolidMatches(0, false,
                Enumerable.Range(0, 18).Concat(Enumerable.Range(40, 16)))
                && SolidMatches(1, true, Enumerable.Range(18, 6))
                && SolidMatches(2, true, Enumerable.Range(24, 6))
                && SolidMatches(3, true, Enumerable.Range(30, 10));
        if (!exactSolids)
            return false;

        var expectedOuterCounts = firstVariant
            ? new Dictionary<int, int> { [4] = 51, [6] = 1, [8] = 3 }
            : new Dictionary<int, int> { [4] = 52, [6] = 1, [8] = 3 };
        var actualOuterCounts = faces
            .GroupBy(face => face.OuterVertices?.Count ?? 0)
            .ToDictionary(group => group.Key, group => group.Count());
        if (actualOuterCounts.Count != expectedOuterCounts.Count
            || expectedOuterCounts.Any(pair =>
                !actualOuterCounts.TryGetValue(pair.Key, out int count)
                || count != pair.Value)
            || faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 } outer
                || outer.Any(point => point.Length < 3
                    || !point.Take(3).All(double.IsFinite))
                || !FaceCanEmitAtIfcPrecision(face)))
            return false;

        if (faces[0].InnerVertices is not [{ Count: 4 } sourceHole]
            || sourceHole.Any(point => point.Length < 3
                || !point.Take(3).All(double.IsFinite))
            || faces.Skip(1).Any(face =>
                face.InnerVertices is { Count: > 0 }))
            return false;
        var expectedAlternatives = firstVariant
            ? new Dictionary<int, int> { [2] = 6, [9] = 5 }
            : new Dictionary<int, int> { [2] = 6, [9] = 4, [11] = 4 };
        for (int index = 0; index < faces.Count; index++)
        {
            int actualCount = faces[index].AlternativeOuterVertices?.Count ?? 0;
            int expectedCount = expectedAlternatives.TryGetValue(
                index, out int count) ? count : 0;
            if (actualCount != expectedCount)
                return false;
            if (actualCount > 0
                && (faces[index].AlternativeOuterVertices!.Any(point =>
                    point.Length < 3
                    || !point.Take(3).All(double.IsFinite))
                    || !FaceCanEmitAtIfcPrecision(new GeoFace
                    {
                        OuterVertices =
                            faces[index].AlternativeOuterVertices,
                    })))
                return false;
        }
        return faces[1].OuterVertices is { Count: 4 }
            && faces[1].InnerVertices is not { Count: > 0 }
            && faces[1].AlternativeOuterVertices is not { Count: > 0 };
    }

    /// <summary>
    /// Promotes either of the two exact uncut joined-shell source contracts whose rebuilt boundary
    /// is already a complete four-corner vertical wall extrusion with redundant coplanar faces.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromExactRedundantJoinShellWithoutOpenings(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData exactBoundary)
    {
        exactBoundary = new GeometryData();
        string? diagnosticIds = Environment.GetEnvironmentVariable(
            "RVTIO_REDUNDANT_JOIN_NO_OPENING_DIAG");
        bool diagnostics = diagnosticIds?.Split(',',
                StringSplitOptions.RemoveEmptyEntries
                | StringSplitOptions.TrimEntries)
            .Any(value => int.TryParse(value, out int id)
                && id == wall.Id) == true
            || diagnosticIds == "1"
            && Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID")
                is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id) && id == wall.Id);
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCREDUNDANTJOINNOOPENINGGATE wall={wall.Id} "
                    + $"result=reject stage={stage}");
            return false;
        }

        if (wall.CuttingElementIds is not { Count: 0 })
            return Reject("decoded-cutters");
        if (emittedHostedCutterIdsByWall != null
            && emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedIds)
            && emittedIds.Count > 0)
            return Reject($"emitted-cutters-{emittedIds.Count}");
        if (standaloneOpeningIdsByWall != null
            && standaloneOpeningIdsByWall.TryGetValue(
                wall.Id, out var standaloneIds)
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (bounds.Count < 6
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, bounds))
            return Reject("wall-definition");
        if (wall.Geometry is not
            {
                Faces: { Count: > 0 } sourceFaces,
                BrepSolids: { Count: > 0 } sourceSolids,
            }
            || sourceFaces.Any(face =>
                face.OuterVertices is not { Count: >= 4 } outer
                || face.InnerVertices is { Count: > 0 }
                || outer.Any(point => point.Length < 3
                    || !double.IsFinite(point[0])
                    || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2]))))
            return Reject("source-face-authority");
        var alternativeFaces = sourceFaces.Where(face =>
            face.AlternativeOuterVertices is { Count: > 0 }).ToList();
        if (alternativeFaces is not
            [{ AlternativeOuterVertices: { } alternative }]
            || alternative.Select(IfcPrecisionKeyFeet).Distinct().Count()
                != alternative.Count
            || !FaceCanEmitAtIfcPrecision(
                new GeoFace { OuterVertices = alternative }))
            return Reject("source-alternative-topology");

        var solidSignature = sourceSolids.Select(solid =>
            (solid.FaceIndices.Count, solid.IsClosed)).ToList();
        var faceHistogram = sourceFaces.GroupBy(face =>
                face.OuterVertices!.Count)
            .ToDictionary(group => group.Key, group => group.Count());
        var latticeDeficits = sourceFaces.Select((face, index) =>
            (Index: index, Vertices: face.OuterVertices!.Count,
                Distinct: face.OuterVertices.Select(IfcPrecisionKeyFeet)
                    .Distinct().Count()))
            .Where(item => item.Distinct != item.Vertices).ToList();
        var nonEmittableIndices = sourceFaces.Select((face, index) =>
                (face, index))
            .Where(item => !FaceCanEmitAtIfcPrecision(item.face))
            .Select(item => item.index).ToList();
        bool firstAuthority = sourceFaces.Count == 65
            && alternative.Count == 11
            && solidSignature.SequenceEqual(
            [
                (29, false), (5, false), (5, false), (10, true),
                (4, false), (6, false), (6, false),
            ])
            && faceHistogram.Count == 5
            && faceHistogram.GetValueOrDefault(4) == 57
            && faceHistogram.GetValueOrDefault(5) == 1
            && faceHistogram.GetValueOrDefault(6) == 4
            && faceHistogram.GetValueOrDefault(7) == 1
            && faceHistogram.GetValueOrDefault(8) == 2
            && latticeDeficits.SequenceEqual(
            [
                (6, 4, 2), (21, 5, 4),
            ])
            && nonEmittableIndices.SequenceEqual([6]);
        bool secondAuthority = sourceFaces.Count == 75
            && alternative.Count == 7
            && solidSignature.SequenceEqual(
            [
                (31, false), (10, true), (5, false), (7, false),
                (7, false), (5, false), (5, false), (5, false),
            ])
            && faceHistogram.Count == 5
            && faceHistogram.GetValueOrDefault(4) == 66
            && faceHistogram.GetValueOrDefault(5) == 2
            && faceHistogram.GetValueOrDefault(6) == 4
            && faceHistogram.GetValueOrDefault(7) == 1
            && faceHistogram.GetValueOrDefault(8) == 2
            && latticeDeficits.SequenceEqual(
            [
                (6, 4, 2), (12, 5, 4), (14, 5, 4),
            ])
            && nonEmittableIndices.SequenceEqual([6]);
        if (!firstAuthority && !secondAuthority)
            return Reject("source-signature");
        var indexedFaces = sourceSolids.SelectMany(solid => solid.FaceIndices)
            .ToList();
        if (sourceSolids.Any(solid =>
                solid.FaceIndices.Distinct().Count()
                    != solid.FaceIndices.Count
                || solid.FaceIndices.Any(index =>
                    index < 0 || index >= sourceFaces.Count))
            || indexedFaces.Count != sourceFaces.Count
            || !indexedFaces.Order().SequenceEqual(
                Enumerable.Range(0, sourceFaces.Count)))
            return Reject("source-solid-partition");

        var alternativeKeys = alternative.Select(IfcPrecisionKeyFeet).ToHashSet();
        int matchingRebuiltFaces = rebuiltBoundary.Faces.Count(face =>
            face.OuterVertices is { } ring
            && ring.Count == alternative.Count
            && ring.Select(IfcPrecisionKeyFeet).ToHashSet()
                .SetEquals(alternativeKeys));
        if (matchingRebuiltFaces != 1)
            return Reject(
                $"source-alternative-rebuilt-face-match-{matchingRebuiltFaces}");
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                rebuiltBoundary, location, widthFt, bounds,
                out var exactPlan, out double baseZFt, out double heightFt,
                out string redundantReason)
            || redundantReason is not (
                "exact-boundary-owned-redundant-faces"
                or "exact-redundant-boundary-faces")
            || exactPlan.Count != 4)
            return Reject($"redundant-boundary-{redundantReason}");

        var minimumCap = exactPlan.Select(point =>
            new[] { point[0], point[1], baseZFt }).ToList();
        var maximumCap = exactPlan.Select(point =>
            new[] { point[0], point[1], baseZFt + heightFt }).ToList();
        var exactFaces = new List<GeoFace>
        {
            new() { OuterVertices = minimumCap },
            new()
            {
                OuterVertices = maximumCap.AsEnumerable().Reverse().ToList(),
            },
        };
        for (int index = 0; index < minimumCap.Count; index++)
        {
            int next = (index + 1) % minimumCap.Count;
            exactFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    minimumCap[index], minimumCap[next],
                    maximumCap[next], maximumCap[index],
                ],
            });
        }
        var exactIndices = Enumerable.Range(0, exactFaces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                exactFaces, exactIndices, out var orientedFaces))
            return Reject("exact-shell-orientation");
        var points = orientedFaces.SelectMany(face => face.OuterVertices!).ToList();
        double[] exactBounds =
        [
            points.Min(point => point[0]), points.Min(point => point[1]),
            baseZFt,
            points.Max(point => point[0]), points.Max(point => point[1]),
            baseZFt + heightFt,
        ];
        var candidate = new GeometryData
        {
            BoundingBox = exactBounds,
            Faces = orientedFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = exactIndices,
                    IsClosed = true,
                },
            ],
        };
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                candidate, location, widthFt, bounds,
                out var verifiedPlan, out _, out _, out string exactReason)
            || exactReason != "exact" || verifiedPlan.Count != 4)
            return Reject($"exact-boundary-{exactReason}");

        exactBoundary = candidate;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCREDUNDANTJOINNOOPENINGGATE wall={wall.Id} "
                + "result=accept stage=exact-redundant-join-shell-no-opening "
                + $"source={(firstAuthority ? "65/7" : "75/8")}");
        return true;
    }

    /// <summary>
    /// Promotes the exact closed eight-face shell whose one horizontal cap is split into three
    /// collinear quads when the source contains no opening at all.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellWithoutOpenings(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData exactBoundary)
    {
        exactBoundary = new GeometryData();
        string? diagnosticIds = Environment.GetEnvironmentVariable(
            "RVTIO_COLLINEAR_CAP_NO_OPENING_DIAG");
        bool diagnostics = diagnosticIds?.Split(',',
                StringSplitOptions.RemoveEmptyEntries
                | StringSplitOptions.TrimEntries)
            .Any(value => int.TryParse(value, out int id)
                && id == wall.Id) == true
            || diagnosticIds == "1"
            && Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID")
                is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id) && id == wall.Id);
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOLLINEARCAPNOOPENINGGATE wall={wall.Id} "
                    + $"result=reject stage={stage}");
            return false;
        }

        if (wall.CuttingElementIds is not { Count: 0 })
            return Reject("decoded-cutters");
        if (emittedHostedCutterIdsByWall != null
            && emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedIds)
            && emittedIds.Count > 0)
            return Reject($"emitted-cutters-{emittedIds.Count}");
        if (standaloneOpeningIdsByWall != null
            && standaloneOpeningIdsByWall.TryGetValue(
                wall.Id, out var standaloneIds)
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (bounds.Count < 6
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, bounds))
            return Reject("wall-definition");
        if (wall.Geometry is not
            {
                Faces: { Count: 36 } sourceFaces,
                BrepSolids: [{ IsClosed: false } sourceSolid],
            }
            || !sourceSolid.FaceIndices.SequenceEqual(
                Enumerable.Range(0, sourceFaces.Count))
            || sourceFaces.Any(face =>
                face.OuterVertices is not { Count: 4 } outer
                || outer.Select(IfcPrecisionKeyFeet).Distinct().Count() != 4
                || face.InnerVertices is { Count: > 0 }
                || !FaceCanEmitAtIfcPrecision(face)))
            return Reject("source-topology");
        var alternativeFaces = sourceFaces.Where(face =>
            face.AlternativeOuterVertices is { Count: > 0 }).ToList();
        if (alternativeFaces is not
            [{ AlternativeOuterVertices: { Count: 6 } alternative }]
            || alternative.Select(IfcPrecisionKeyFeet).Distinct().Count() != 6
            || !FaceCanEmitAtIfcPrecision(
                new GeoFace { OuterVertices = alternative }))
            return Reject("source-alternative-topology");
        var alternativeKeys = alternative.Select(IfcPrecisionKeyFeet).ToHashSet();
        int matchingRebuiltFaces = rebuiltBoundary.Faces.Count(face =>
            face.OuterVertices is { Count: 6 } ring
            && ring.Select(IfcPrecisionKeyFeet).ToHashSet()
                .SetEquals(alternativeKeys));
        if (matchingRebuiltFaces != 1)
            return Reject(
                $"source-alternative-rebuilt-face-match-{matchingRebuiltFaces}");

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(dx * dx + dy * dy);
        double heightFt = bounds[5] - bounds[2];
        if (!(axisLength > 0) || !double.IsFinite(axisLength)
            || !(heightFt > 0) || !double.IsFinite(heightFt))
            return Reject("neutral-validation-operand");
        var neutralOperand = new HostedOpeningGeometry(
            CentreXFt: (location.StartPoint[0] + location.EndPoint[0]) / 2,
            CentreYFt: (location.StartPoint[1] + location.EndPoint[1]) / 2,
            AxisX: dx / axisLength, AxisY: dy / axisLength,
            WidthFt: axisLength, DepthFt: widthFt,
            BaseZFt: bounds[2], HeightFt: heightFt,
            ExactDepth: true);
        string rectangularReason = "not-tested";
        if (!TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
                rebuiltBoundary, location, widthFt, bounds, neutralOperand,
                out var candidateBoundary, out _, out string boundaryReason,
                retainMatchedOpeningSubdivisions: false)
            || candidateBoundary.Faces.Count != 6
            || !TryGetExactVerticalRectangularWallPlan(
                candidateBoundary, location, widthFt, bounds,
                out var exactPlan, out rectangularReason)
            || exactPlan.Count != 4)
            return Reject($"boundary-{boundaryReason}-{rectangularReason}");

        exactBoundary = candidateBoundary;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCCOLLINEARCAPNOOPENINGGATE wall={wall.Id} "
                + "result=accept stage=exact-single-collinear-cap-subdivision-no-opening");
        return true;
    }

    /// <summary>
    /// Promotes the exact closed eight-face shell whose one horizontal cap is split into three
    /// collinear quads only for one independently exact swept opening.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            IReadOnlyDictionary<(int WallId, int CutterId),
                HostedOpeningGeometry>? exactSingleLinkedSourceOpenings,
            IReadOnlySet<(int WallId, int CutterId)>?
                exactConcordantFamilyCutBrepSweptOpeningPairs,
            out GeometryData exactBoundary,
            out IReadOnlyList<int> cutterElementIds,
            bool requireCompleteDecodedCutterSet = true)
    {
        exactBoundary = new GeometryData();
        cutterElementIds = [];
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1"
            || Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, int cutterId = 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOLLINEARCAPOPENINGGATE wall={wall.Id} "
                    + $"cutter={cutterId} result=reject stage={stage}");
            return false;
        }

        if (standaloneOpeningIdsByWall != null
            && standaloneOpeningIdsByWall.TryGetValue(
                wall.Id, out var standaloneIds)
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (emittedHostedCutterIdsByWall == null
            || !emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedIds)
            || emittedIds.Count != 1
            || emittedIds.Distinct().Count() != emittedIds.Count)
            return Reject($"emitted-cutters-{(
                emittedHostedCutterIdsByWall != null
                && emittedHostedCutterIdsByWall.TryGetValue(
                    wall.Id, out var rejectedIds)
                    ? rejectedIds.Count : 0)}");
        int cutterId = emittedIds[0];
        if (requireCompleteDecodedCutterSet
            && wall.CuttingElementIds is { Count: > 0 } decodedIds
            && (decodedIds.Distinct().Count() != decodedIds.Count
                || !decodedIds.ToHashSet().SetEquals(emittedIds)))
            return Reject("decoded-cutter-set", cutterId);
        if (emittedHostedOpeningOperandsByWall == null
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var emittedOperands)
            || emittedOperands.Count != 1
            || emittedOperands[0].CutterId != cutterId)
            return Reject($"emitted-operands-{(
                emittedHostedOpeningOperandsByWall != null
                && emittedHostedOpeningOperandsByWall.TryGetValue(
                    wall.Id, out var rejectedOperands)
                    ? rejectedOperands.Count : 0)}", cutterId);
        HostedOpeningGeometry operand = emittedOperands[0].Operand;
        bool hasExactSourceOpening =
            exactSingleLinkedSourceOpenings != null
            && exactSingleLinkedSourceOpenings.ContainsKey(
                (wall.Id, cutterId));
        bool hasExactConcordantFamilyCut =
            operand.IsExactConcordantFamilyCut
            && exactConcordantFamilyCutBrepSweptOpeningPairs != null
            && exactConcordantFamilyCutBrepSweptOpeningPairs.Contains(
                (wall.Id, cutterId));
        bool hasExactSerializedDefinition =
            operand.IsExactSerializedDefinition;
        bool hasExactParameterizedReveal =
            operand.IsExactParameterizedReveal
            && !operand.IsExactSerializedDefinition
            && !operand.IsExactConcordantFamilyCut
            && !operand.IsExactMappedSideShell
            && !operand.IsExactSourceWallProfilesMappedBreakpoint
            && !operand.IsFamilyCutLoop
            && ExactParameterizedRevealOpeningDefinitionsAreConcordant(
                [operand, operand]);
        if (wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, bounds))
            return Reject("wall-definition", cutterId);
        bool verticalEdgeSubdivision = false;
        GeometryData candidateBoundary;
        int matchedSubdivisionCount;
        string boundaryReason;
        if (!TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
                rebuiltBoundary, location, widthFt, bounds, operand,
                out candidateBoundary, out matchedSubdivisionCount,
                out boundaryReason,
                retainMatchedOpeningSubdivisions: false))
        {
            string horizontalReason = boundaryReason;
            if (!TryGetExactVerticalWallBoundaryFromSingleCollinearVerticalEdgeSubdivisionShell(
                    rebuiltBoundary, location, widthFt, bounds,
                    out candidateBoundary, out boundaryReason))
                return Reject(
                    $"boundary-horizontal-{horizontalReason}"
                    + $"-vertical-{boundaryReason}",
                    cutterId);
            matchedSubdivisionCount = 0;
            verticalEdgeSubdivision = true;
        }
        bool hasExactShellLinkedOpening =
            operand.Boundary is null
            && operand.ExactDepth
            && matchedSubdivisionCount == 2;
        if (!hasExactSourceOpening && !hasExactConcordantFamilyCut
            && !hasExactSerializedDefinition
            && !hasExactParameterizedReveal
            && !hasExactShellLinkedOpening)
            return Reject("operand-provenance", cutterId);
        bool exactRectangularGross =
            TryGetExactVerticalRectangularWallPlan(
                candidateBoundary, location, widthFt, bounds,
                out _, out _);
        if ((hasExactSourceOpening || hasExactShellLinkedOpening)
            && !exactRectangularGross)
        {
            if (verticalEdgeSubdivision
                || !TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
                    rebuiltBoundary, location, widthFt, bounds, operand,
                    out candidateBoundary, out int retainedMatchCount,
                    out boundaryReason,
                    retainMatchedOpeningSubdivisions: true)
                || retainedMatchCount != matchedSubdivisionCount)
                return Reject("source-subdivision-rebuild", cutterId);
        }
        else if (hasExactParameterizedReveal
            && !verticalEdgeSubdivision
            && matchedSubdivisionCount == 1)
        {
            // The reveal-edge subdivision belongs to the Boolean result and is removed from the
            // gross.
            if (TryGetUniquePathWallMinimumCapSubdivision(
                    wall, elemById, candidateBoundary,
                    out var pathSubdividedBoundary, out string pathReason))
            {
                candidateBoundary = pathSubdividedBoundary;
                boundaryReason += "-path-subdivision";
            }
            else if (!exactRectangularGross)
                return Reject(
                    $"parameterized-reveal-path-subdivision-{pathReason}",
                    cutterId);
        }
        else if (hasExactConcordantFamilyCut
            && !exactRectangularGross
            && (rebuiltBoundary.Faces is { Count: 8 }
                || verticalEdgeSubdivision))
        {
            // A non-rectangular vertical-edge form reaches this branch only when an explicitly
            // connected wall's longitudinal exterior side contributes one independently exact plan
            // subdivision.
            bool hasPathSubdivision = verticalEdgeSubdivision
                ? TryGetUniquePathWallLongitudinalSideMinimumCapSubdivision(
                    wall, elemById, candidateBoundary,
                    out var pathSubdividedBoundary, out _)
                : TryGetUniquePathWallMinimumCapSubdivision(
                    wall, elemById, candidateBoundary,
                    out pathSubdividedBoundary, out _);
            if (hasPathSubdivision)
                candidateBoundary = pathSubdividedBoundary;
            else if (!verticalEdgeSubdivision
                && matchedSubdivisionCount == 1)
            {
                if (!TryGetExactVerticalWallBoundaryFromSingleCollinearCapSubdivisionShell(
                        rebuiltBoundary, location, widthFt, bounds, operand,
                        out candidateBoundary, out int retainedMatchCount,
                        out boundaryReason,
                        retainMatchedOpeningSubdivisions: true)
                    || retainedMatchCount != 1)
                    return Reject(
                        "family-single-subdivision-rebuild",
                        cutterId);
            }
            else
                return Reject(
                    $"family-path-subdivision-unconfirmed"
                    + $"-matches-{matchedSubdivisionCount}",
                    cutterId);
        }

        HostedOpeningGeometry validationOperand = operand;
        bool validationUsesExactSteppedBrep = false;
        if (operand.Boundary is not null
            && !TryGetExactVerticalRectangularPrismSweptOpening(
                operand.Boundary, out validationOperand))
        {
            validationUsesExactSteppedBrep =
                TryGetExactSteppedOpeningSweptBoxForWall(
                    operand.Boundary, location, widthFt, out validationOperand);
            if (!validationUsesExactSteppedBrep)
                return Reject("opening-prism-validation", cutterId);
        }
        double wallAxisX =
            location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY =
            location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            validationOperand.AxisX * validationOperand.AxisX
            + validationOperand.AxisY * validationOperand.AxisY);
        const double MachineEpsilon = 2.2204460492503131e-16;
        if (wallAxisLength > 0 && double.IsFinite(wallAxisLength)
            && openingAxisLength > 0
            && double.IsFinite(openingAxisLength))
        {
            wallAxisX /= wallAxisLength;
            wallAxisY /= wallAxisLength;
            double openingAxisX =
                validationOperand.AxisX / openingAxisLength;
            double openingAxisY =
                validationOperand.AxisY / openingAxisLength;
            double cross = openingAxisX * wallAxisY
                - openingAxisY * wallAxisX;
            double dot = openingAxisX * wallAxisX
                + openingAxisY * wallAxisY;
            if (Math.Abs(cross) > 4096 * MachineEpsilon
                && Math.Abs(dot) <= 4096 * MachineEpsilon)
                validationOperand = validationOperand with
                {
                    AxisX = -openingAxisY,
                    AxisY = openingAxisX,
                    WidthFt = validationOperand.DepthFt,
                    DepthFt = validationOperand.WidthFt,
                };
        }
        bool robustInteriorThrough =
            HostedOpeningWriterOperandIsRobustInteriorThroughCutOfExactWall(
                wall, bounds, candidateBoundary, validationOperand);
        bool robustCapCoincidentThrough =
            HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
                wall, bounds, candidateBoundary, validationOperand,
                out string capCoincidentThroughReason);
        bool robustInterior =
            HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
                wall, bounds, candidateBoundary, validationOperand);
        bool robustlyDisjoint =
            HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, candidateBoundary, validationOperand);
        bool exactCollinearInteriorThrough =
            HostedOpeningWriterOperandIsInteriorThroughCutOfExactCollinearSubdivisionWall(
                wall, bounds, candidateBoundary, validationOperand);
        bool exactShellLinkedWriterPrecisionCap =
            hasExactShellLinkedOpening
            && HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactCollinearSubdivisionWall(
                wall, bounds, candidateBoundary, validationOperand);
        bool exactSteppedHorizontalBoundaryThrough =
            validationUsesExactSteppedBrep
            && HostedOpeningWriterOperandIsRobustSingleHorizontalBoundaryThroughCutOfExactCollinearSubdivisionWall(
                wall, bounds, candidateBoundary, validationOperand);
        bool robustOpening = robustInteriorThrough
            || robustCapCoincidentThrough || robustInterior
            || robustlyDisjoint
            || exactCollinearInteriorThrough
            || exactShellLinkedWriterPrecisionCap
            || exactSteppedHorizontalBoundaryThrough;
        if (hasExactSerializedDefinition
            && !hasExactSourceOpening
            && !hasExactConcordantFamilyCut
            && !hasExactShellLinkedOpening
            && !robustlyDisjoint)
            return Reject("serialized-intersecting-opening", cutterId);
        if (!robustOpening)
            return Reject(
                $"opening-validation-through-{robustInteriorThrough}"
                + $"-cap-{capCoincidentThroughReason}"
                + $"-interior-{robustInterior}"
                + $"-disjoint-{robustlyDisjoint}"
                + $"-collinear-through-{exactCollinearInteriorThrough}"
                + $"-shell-cap-{exactShellLinkedWriterPrecisionCap}"
                + $"-stepped-boundary-{exactSteppedHorizontalBoundaryThrough}",
                cutterId);

        exactBoundary = candidateBoundary;
        cutterElementIds = [cutterId];
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCCOLLINEARCAPOPENINGGATE wall={wall.Id} "
                + $"cutter={cutterId} result=accept "
                + $"stage={boundaryReason} "
                + $"source={hasExactSourceOpening} "
                + $"family={hasExactConcordantFamilyCut} "
                + $"serialized={hasExactSerializedDefinition} "
                + $"parameterizedReveal={hasExactParameterizedReveal} "
                + $"shellLinked={hasExactShellLinkedOpening}");
        return true;
    }

    /// <summary>
    /// Recovers the authored eight-point gross profile only for the exact complete-source/split-cap
    /// contract whose sole writer operand is a finite mapped four-side shell tangent to one
    /// exterior wall side.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromSingleCollinearCapSubdivisionShellAndExactMappedSideTangentOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlySet<int> visibleWallIds,
            IReadOnlyDictionary<int, List<int>> inverseHostedHostIds,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData exactBoundary,
            out IReadOnlyList<int> cutterElementIds,
            out bool preserveExactMappedSideTangentCollinearPlan)
    {
        exactBoundary = new GeometryData();
        cutterElementIds = [];
        preserveExactMappedSideTangentCollinearPlan = false;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1"
            || Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, int cutterId = 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOLLINEARMAPPEDSIDETANGENTGATE wall={wall.Id} "
                    + $"cutter={cutterId} result=reject stage={stage}");
            return false;
        }

        static bool Empty(IReadOnlyCollection<int>? values) =>
            values == null || values.Count == 0;

        bool PointCanMapToIfcPrecision(IReadOnlyList<double>? point)
        {
            if (point is not { Count: >= 3 }
                || !CanMapFeetToIfcPrecisionBin(point[0])
                || !CanMapFeetToIfcPrecisionBin(point[1])
                || !CanMapFeetToIfcPrecisionBin(point[2]))
                return false;
            double horizontalBin = (Math.Abs(point[0]) + Math.Abs(point[1]))
                * FeetToMetres / IfcGeometryPrecisionMetres;
            return double.IsFinite(horizontalBin)
                && horizontalBin < long.MaxValue;
        }

        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) Edge3(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);

        HashSet<((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second)> RingEdges(
                IReadOnlyList<double[]> ring)
        {
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => Edge3(
                    keys[index], keys[(index + 1) % keys.Count]))
                .ToHashSet();
        }

        bool ExactRing(IReadOnlyList<double[]>? ring) =>
            ring is { Count: >= 3 }
            && ring.All(PointCanMapToIfcPrecision)
            && ring.Select(IfcPrecisionKeyFeet).Distinct().Count() == ring.Count
            && RingEdges(ring).Count == ring.Count
            && FaceCanEmitAtIfcPrecision(new GeoFace
            {
                OuterVertices = ring.ToList(),
            });

        bool TopologyMatches(
            IReadOnlyList<GeoFace> faces,
            IReadOnlyCollection<int> faceIndices,
            bool useAlternatives,
            int expectedVertices,
            int expectedFaceEdgeUses,
            int expectedEdges,
            IReadOnlyList<int> expectedIncidence,
            IReadOnlyList<int> expectedComponentSizes)
        {
            if (faceIndices.Count == 0
                || faceIndices.Distinct().Count() != faceIndices.Count)
                return false;
            var selectedFaces = faces.Select(face => new GeoFace
            {
                OuterVertices = useAlternatives
                    && face.AlternativeOuterVertices is { Count: > 0 } alternative
                        ? alternative : face.OuterVertices,
            }).ToList();
            var vertices = new HashSet<(long X, long Y, long Z)>();
            var edgeUses = new Dictionary<
                ((long X, long Y, long Z) First,
                 (long X, long Y, long Z) Second), int>();
            int faceEdgeUses = 0;
            foreach (int faceIndex in faceIndices)
            {
                if ((uint)faceIndex >= selectedFaces.Count
                    || selectedFaces[faceIndex].OuterVertices
                        is not { Count: >= 3 } ring
                    || !ExactRing(ring))
                    return false;
                vertices.UnionWith(ring.Select(IfcPrecisionKeyFeet));
                var edges = RingEdges(ring);
                faceEdgeUses += edges.Count;
                foreach (var edge in edges)
                    edgeUses[edge] = edgeUses.GetValueOrDefault(edge) + 1;
            }
            if (vertices.Count != expectedVertices
                || faceEdgeUses != expectedFaceEdgeUses
                || edgeUses.Count != expectedEdges
                || edgeUses.Values.Any(count =>
                    count < 1 || count > expectedIncidence.Count)
                || !Enumerable.Range(1, expectedIncidence.Count).All(useCount =>
                    edgeUses.Values.Count(count => count == useCount)
                        == expectedIncidence[useCount - 1]))
                return false;
            var componentSizes = GetExactFaceComponents(
                    selectedFaces, faceIndices)
                .Select(component => component.Count)
                .OrderDescending().ToList();
            return componentSizes.SequenceEqual(expectedComponentSizes);
        }

        if (wall.Id <= 0 || wall.CategoryId != -2000011
            || bounds.Count < 6
            || bounds.Take(6).Any(value => !double.IsFinite(value))
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !PointCanMapToIfcPrecision(location.StartPoint)
            || !PointCanMapToIfcPrecision(location.EndPoint)
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !(widthFt > 0) || !double.IsFinite(widthFt)
