        bool TryProject(IReadOnlyList<double> point,
            out (long Along, long Normal, long Z) projected)
        {
            projected = default;
            if (point.Count < 3) return false;
            double alongMetres = (point[0] * axisX + point[1] * axisY)
                * FeetToMetres;
            double normalMetres = (point[0] * normalX + point[1] * normalY)
                * FeetToMetres;
            double zMetres = point[2] * FeetToMetres;
            if (new[] { alongMetres, normalMetres, zMetres }.Any(value =>
                    !double.IsFinite(value)
                    || Math.Abs(value / IfcGeometryPrecisionMetres)
                        >= long.MaxValue))
                return false;
            projected = (
                IfcPrecisionBinMetres(alongMetres),
                IfcPrecisionBinMetres(normalMetres),
                IfcPrecisionBinMetres(zMetres));
            return true;
        }
        bool TryProjectRing(IReadOnlyList<double[]> ring,
            out List<(double[] Point,
                (long Along, long Normal, long Z) Key)> projected)
        {
            projected = [];
            foreach (double[] point in ring)
            {
                if (!TryProject(point, out var key))
                {
                    projected = [];
                    return false;
                }
                projected.Add((point, key));
            }
            return true;
