        List<double[]> BoxCorners(HostedOpeningGeometry definition)
        {
            double definitionAxisLength = Math.Sqrt(
                definition.AxisX * definition.AxisX
                + definition.AxisY * definition.AxisY);
            if (!(definitionAxisLength > 0)
                || !double.IsFinite(definitionAxisLength)
                || !(definition.WidthFt > 0)
                || !(definition.DepthFt > 0)
                || !(definition.HeightFt > 0))
                return [];
            double definitionAxisX = definition.AxisX / definitionAxisLength;
            double definitionAxisY = definition.AxisY / definitionAxisLength;
            double definitionNormalX = -definitionAxisY;
            double definitionNormalY = definitionAxisX;
            var corners = new List<double[]>(8);
            foreach (double z in new[]
                     {
                         definition.BaseZFt,
                         definition.BaseZFt + definition.HeightFt,
                     })
                foreach (double along in new[]
                         {
                             -definition.WidthFt / 2,
                             definition.WidthFt / 2,
                         })
                    foreach (double normal in new[]
                             {
                                 -definition.DepthFt / 2,
                                 definition.DepthFt / 2,
                             })
                        corners.Add(
                        [
                            definition.CentreXFt
                                + along * definitionAxisX
                                + normal * definitionNormalX,
                            definition.CentreYFt
                                + along * definitionAxisY
                                + normal * definitionNormalY,
                            z,
                        ]);
            return corners;
