            .Distinct().Order().ToList();
        var openingNormal = openingProjected.Select(item => item.Key.Normal)
            .Distinct().Order().ToList();
        var openingZ = openingProjected.Select(item => item.Key.Z)
            .Distinct().Order().ToList();
