        bool touchesFiveMaximum = fiveNormal == wallMaximumNormal
            && openingNormal is [{ } openingMinimumNormal2, { } openingMaximumNormal2]
            && openingMinimumNormal2 == fiveNormal
            && openingMaximumNormal2 - fiveNormal > 2;
        if (openingAlong.Count != 2 || openingNormal.Count != 2
            || openingZ.Count != 2
            || touchesFiveMinimum == touchesFiveMaximum
            || openingAlong.Any(value =>
                !StrictlyBetween(value, fiveOtherAlong, commonAlong))
