        IReadOnlyCollection<int> robustInteriorBrepThroughCutIds,
        IReadOnlyCollection<int> exactVerticalPlanBoundaryTouchIds,
        IReadOnlyCollection<int> exactHorizontalCapCoincidentThroughCutIds,
        IReadOnlyCollection<int> robustInteriorCutIds)
        => HostedOpeningWriterOperandValidationsCoverAllCutters(
            operandIds, robustlyDisjointIds, exactHorizontalCapTouchIds,
            exactEndCoincidentThroughNotchIds, robustBoundaryCutIds,
            robustInteriorThroughCutIds, robustInteriorBrepThroughCutIds, [],
            exactVerticalPlanBoundaryTouchIds,
            exactHorizontalCapCoincidentThroughCutIds, robustInteriorCutIds);

    internal static bool HostedOpeningWriterOperandValidationsCoverAllCutters(
        IReadOnlyCollection<int> operandIds,
        IReadOnlyCollection<int> robustlyDisjointIds,
        IReadOnlyCollection<int> exactHorizontalCapTouchIds,
        IReadOnlyCollection<int> exactEndCoincidentThroughNotchIds,
        IReadOnlyCollection<int> robustBoundaryCutIds,
        IReadOnlyCollection<int> robustInteriorThroughCutIds,
        IReadOnlyCollection<int> robustInteriorBrepThroughCutIds,
        IReadOnlyCollection<int> exactHorizontalCapCoincidentBrepThroughCutIds,
        IReadOnlyCollection<int> exactVerticalPlanBoundaryTouchIds,
        IReadOnlyCollection<int> exactHorizontalCapCoincidentThroughCutIds,
        IReadOnlyCollection<int> robustInteriorCutIds)
    {
        if (operandIds.Count == 0) return false;
        var operands = operandIds.ToHashSet();
        if (operands.Count != operandIds.Count) return false;
        var validated = robustlyDisjointIds.Concat(exactHorizontalCapTouchIds)
            .Concat(exactEndCoincidentThroughNotchIds)
            .Concat(robustBoundaryCutIds)
            .Concat(robustInteriorThroughCutIds)
            .Concat(robustInteriorBrepThroughCutIds)
            .Concat(exactHorizontalCapCoincidentBrepThroughCutIds)
            .Concat(exactVerticalPlanBoundaryTouchIds)
            .Concat(exactHorizontalCapCoincidentThroughCutIds)
            .Concat(robustInteriorCutIds).ToHashSet();
        return validated.SetEquals(operands);
    }

    /// <summary>
    /// Uses exact forward InsertableInst host ownership only when the host's inverse cut phase was
    /// unavailable, every top-level primary-host cutter referenced by that wall is emitted exactly
    /// once, and the emitted operand IDs form the same complete set.
    /// </summary>
    internal static bool
        ForwardPrimaryHostRelationsConfirmCompleteEmittedCutterSet(
            Element wall, IReadOnlyDictionary<int, Element> elemById,
            IReadOnlyCollection<int> emittedCutterIds,
            IReadOnlyCollection<(int CutterId, HostedOpeningGeometry Operand)>
                emittedOperands)
    {
        if (wall.CuttingElementIds != null
            || emittedCutterIds.Count == 0
            || emittedOperands.Count != emittedCutterIds.Count)
            return false;
        var emittedIds = emittedCutterIds.ToHashSet();
        var operandIds = emittedOperands
            .Select(item => item.CutterId).ToHashSet();
        if (emittedIds.Count != emittedCutterIds.Count
            || operandIds.Count != emittedOperands.Count
            || !operandIds.SetEquals(emittedIds))
            return false;

        var primaryForwardIds = new List<int>();
        foreach (int referenceId in wall.References
                     ?? Enumerable.Empty<int>())
        {
            if (!elemById.TryGetValue(referenceId, out var referenced)
                || referenced.SerializedHostId != wall.Id
                || referenced.SuperInstanceId is > 0)
                continue;
            primaryForwardIds.Add(referenceId);
        }
        if (primaryForwardIds.Count != emittedIds.Count
            || primaryForwardIds.Distinct().Count()
                != primaryForwardIds.Count
            || !primaryForwardIds.ToHashSet().SetEquals(emittedIds))
            return false;

        foreach (int cutterId in emittedIds)
        {
            if (!elemById.TryGetValue(cutterId, out var cutter)
                || cutter.SerializedHostId != wall.Id
                || cutter.HostId is { } compatibilityHostId
                    && compatibilityHostId != wall.Id
                || cutter.SuperInstanceId is > 0
                || wall.References?.Count(id => id == cutterId) != 1)
                return false;
            int forwardHostMentions =
                (cutter.SerializedHostId == wall.Id ? 1 : 0)
                + (cutter.ExtraHostIds?.Count(id => id == wall.Id) ?? 0)
                + (cutter.ExplicitHostIds?.Count(id => id == wall.Id) ?? 0);
            if (forwardHostMentions != 1)
                return false;
        }
        return true;
    }

    /// <summary>True when the two operands are covered by an end-coincident through notch and a side-plane coextensive interior cut.</summary>
    internal static bool
        HostedOpeningWriterOperandValidationsConfirmEndCoincidentAndSidePlaneCoextensiveInteriorJoinedSpan(
            IReadOnlyCollection<int> operandIds,
            IReadOnlyCollection<int> endCoincidentThroughNotchIds,
