    {
        if (operandIds.Count != 2
            || endCoincidentThroughNotchIds.Count != 1
            || sidePlaneCoextensiveInteriorCutIds.Count != 1)
            return false;
        var operands = operandIds.ToHashSet();
        var endCoincident = endCoincidentThroughNotchIds.ToHashSet();
        var sidePlaneInterior =
            sidePlaneCoextensiveInteriorCutIds.ToHashSet();
        return operands.Count == operandIds.Count
            && endCoincident.Count == endCoincidentThroughNotchIds.Count
            && sidePlaneInterior.Count
                == sidePlaneCoextensiveInteriorCutIds.Count
            && !endCoincident.Overlaps(sidePlaneInterior)
            && endCoincident.Concat(sidePlaneInterior).ToHashSet()
                .SetEquals(operands);
    }

