            IReadOnlyCollection<int> planBoundaryTouchIds,
            IReadOnlyCollection<int> endCoincidentIds,
            IReadOnlyCollection<int> sidePlaneInteriorIds,
            IReadOnlyCollection<int> endSideCapNotchIds,
            IReadOnlyCollection<int> singleEndCrossingSidePlaneInteriorIds,
            IReadOnlyCollection<int> sidePlaneCapIds)
    {
        if (operandIds.Count != 6
            || planBoundaryTouchIds.Count != 1
            || endCoincidentIds.Count != 1
            || sidePlaneInteriorIds.Count != 1
            || endSideCapNotchIds.Count != 1
            || singleEndCrossingSidePlaneInteriorIds.Count != 1
            || sidePlaneCapIds.Count != 1)
            return false;
        var operands = operandIds.ToHashSet();
        var validated = planBoundaryTouchIds
            .Concat(endCoincidentIds)
            .Concat(sidePlaneInteriorIds)
            .Concat(endSideCapNotchIds)
            .Concat(singleEndCrossingSidePlaneInteriorIds)
            .Concat(sidePlaneCapIds).ToList();
        return operands.Count == operandIds.Count
            && validated.Distinct().Count() == validated.Count
            && validated.ToHashSet().SetEquals(operands);
    }

    /// <summary>
    /// Every class ID must be distinct and their union must equal all seven unique writer operands.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandValidationsConfirmBidirectionalSevenOperandPanelWithSingleEndCrossingJoinedSpan(
            IReadOnlyCollection<int> operandIds,
            IReadOnlyCollection<int> planBoundaryTouchIds,
            IReadOnlyCollection<int> endCoincidentIds,
            IReadOnlyCollection<int> sidePlaneInteriorIds,
            IReadOnlyCollection<int> endSideCapNotchIds,
            IReadOnlyCollection<int> singleEndCrossingSidePlaneInteriorIds,
            IReadOnlyCollection<int> sidePlaneCapIds)
    {
        if (operandIds.Count != 7
            || planBoundaryTouchIds.Count != 1
            || endCoincidentIds.Count != 2
            || sidePlaneInteriorIds.Count != 1
            || endSideCapNotchIds.Count != 1
            || singleEndCrossingSidePlaneInteriorIds.Count != 1
            || sidePlaneCapIds.Count != 1)
            return false;
        var operands = operandIds.ToHashSet();
        var validated = planBoundaryTouchIds
            .Concat(endCoincidentIds)
            .Concat(sidePlaneInteriorIds)
            .Concat(endSideCapNotchIds)
            .Concat(singleEndCrossingSidePlaneInteriorIds)
            .Concat(sidePlaneCapIds).ToList();
        return operands.Count == operandIds.Count
            && validated.Distinct().Count() == validated.Count
            && validated.ToHashSet().SetEquals(operands);
    }

    /// <summary>No IFC precision or model-scale tolerance is used.</summary>
    internal static bool
        ExactStraightWallPlanEndpointsUseHalfWidthLattice(
            LocationCurve location, double widthFt, GeometryData boundary)
    {
        if (location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || boundary.BoundingBox is not { Length: 6 } bounds
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                boundary, location, widthFt, bounds,
                out var plan, out _, out _, out _)
            || plan.Count != 4)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double lengthFt = Math.Sqrt(dx * dx + dy * dy);
        if (!(lengthFt > 0) || !double.IsFinite(lengthFt))
            return false;
        double axisX = dx / lengthFt, axisY = dy / lengthFt;
        double locationMinimum = Math.Min(
            location.StartPoint[0] * axisX
                + location.StartPoint[1] * axisY,
            location.EndPoint[0] * axisX
                + location.EndPoint[1] * axisY);
        double locationMaximum = Math.Max(
            location.StartPoint[0] * axisX
                + location.StartPoint[1] * axisY,
            location.EndPoint[0] * axisX
                + location.EndPoint[1] * axisY);
        var projected = plan.Select(point =>
            point[0] * axisX + point[1] * axisY).ToList();
        double minimumDelta = projected.Min() - locationMinimum;
        double maximumDelta = projected.Max() - locationMaximum;

        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, plan.SelectMany(point => point)
            .Concat(location.StartPoint.Take(2))
            .Concat(location.EndPoint.Take(2))
            .Append(widthFt).Select(Math.Abs).Max());
        double roundoff = 4096 * MachineEpsilon * scale;
        double halfWidthFt = widthFt / 2;
        bool ZeroOrHalfWidth(double value) =>
            Math.Abs(value) <= roundoff
            || Math.Abs(Math.Abs(value) - halfWidthFt) <= roundoff;
        return ZeroOrHalfWidth(minimumDelta)
            && ZeroOrHalfWidth(maximumDelta)
            && (Math.Abs(minimumDelta) > roundoff
                || Math.Abs(maximumDelta) > roundoff);
    }

    /// <summary>
    /// The untrimmed end must remain on the serialized LocationCurve, while both corners of the
    /// trimmed end must lie on the same unique longitudinal side of the connected neighbour derived
    /// from its serialized line and width.
    /// </summary>
    internal static bool
        ExactStraightWallPlanHasSingleInwardEndTrimByReciprocalPathNeighbourSideLattice(
            Element wall, IReadOnlyDictionary<int, Element> elemById,
            GeometryData boundary)
    {
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || boundary.BoundingBox is not { Length: 6 } bounds
            || wall.References is not { Count: > 0 } references
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                boundary, location, widthFt, bounds,
                out var plan, out _, out _, out _)
            || plan.Count != 4)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double lengthFt = Math.Sqrt(dx * dx + dy * dy);
        if (!(lengthFt > 0) || !double.IsFinite(lengthFt))
            return false;
        double axisX = dx / lengthFt, axisY = dy / lengthFt;
        double normalX = -axisY, normalY = axisX;
        double locationStartAlong =
            location.StartPoint[0] * axisX
            + location.StartPoint[1] * axisY;
        double locationEndAlong =
            location.EndPoint[0] * axisX
            + location.EndPoint[1] * axisY;
        double locationMinimum = Math.Min(
            locationStartAlong, locationEndAlong);
        double locationMaximum = Math.Max(
            locationStartAlong, locationEndAlong);
        string minimumConnectionType =
            locationStartAlong <= locationEndAlong ? "ATSTART" : "ATEND";
        string maximumConnectionType =
            locationStartAlong <= locationEndAlong ? "ATEND" : "ATSTART";

        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, plan.SelectMany(point => point)
            .Concat(location.StartPoint.Take(2))
            .Concat(location.EndPoint.Take(2))
            .Append(widthFt).Select(Math.Abs).Max());
        double roundoff = 4096 * MachineEpsilon * scale;
        var projected = plan.Select(point => (
            Point: point,
            Along: point[0] * axisX + point[1] * axisY,
            Normal: point[0] * normalX + point[1] * normalY)).ToList();
        double wallMinimum = projected.Min(item => item.Along);
        double wallMaximum = projected.Max(item => item.Along);
        double minimumNormal = projected.Min(item => item.Normal);
        double maximumNormal = projected.Max(item => item.Normal);
        var minimumEnd = projected
            .Where(item => Math.Abs(item.Along - wallMinimum) <= roundoff)
            .OrderBy(item => item.Normal).ToList();
        var maximumEnd = projected
            .Where(item => Math.Abs(item.Along - wallMaximum) <= roundoff)
            .OrderBy(item => item.Normal).ToList();
        if (minimumEnd.Count != 2 || maximumEnd.Count != 2
            || Math.Abs(maximumNormal - minimumNormal - widthFt) > roundoff)
            return false;

        double minimumDelta = wallMinimum - locationMinimum;
        double maximumDelta = wallMaximum - locationMaximum;
        bool minimumTrimmed = minimumDelta > roundoff
            && Math.Abs(maximumDelta) <= roundoff;
        bool maximumTrimmed = maximumDelta < -roundoff
            && Math.Abs(minimumDelta) <= roundoff;
        if (minimumTrimmed == maximumTrimmed)
            return false;
        var trimmedEnd = minimumTrimmed ? minimumEnd : maximumEnd;
        string connectionType = minimumTrimmed
            ? minimumConnectionType : maximumConnectionType;
        double[] originalEndpoint = connectionType == "ATSTART"
            ? location.StartPoint : location.EndPoint;

        var commonMatches = new HashSet<(int ReferenceId, int SideIndex)>();
        bool firstEndpoint = true;
        foreach (var targetEndpoint in trimmedEnd)
        {
            var endpointKey = IfcPrecisionKeyFeet(
                [targetEndpoint.Point[0], targetEndpoint.Point[1], 0]);
            var endpointMatches = new HashSet<(int ReferenceId, int SideIndex)>();
            foreach (int referenceId in references.Distinct())
            {
                if (referenceId == wall.Id
                    || !elemById.TryGetValue(referenceId, out var neighbour)
                    || neighbour.CategoryId != -2000011
                    || neighbour.References?.Count(id => id == wall.Id) != 1
                    || neighbour.Location is not
                        { CurveType: "Line", ArcRadius: null } neighbourLocation
                    || !PointIsOnPlanSegmentAtIfcPrecision(
                        originalEndpoint, neighbourLocation.StartPoint,
                        neighbourLocation.EndPoint)
                    || !TryGetSerializedWallWidthFeet(
                        neighbour, out double neighbourWidthFt)
                    || !StrictVerticalBoundsOverlap(wall, neighbour))
                    continue;

                double neighbourDx = neighbourLocation.EndPoint[0]
                    - neighbourLocation.StartPoint[0];
                double neighbourDy = neighbourLocation.EndPoint[1]
                    - neighbourLocation.StartPoint[1];
                double neighbourLength = Math.Sqrt(
                    neighbourDx * neighbourDx
                    + neighbourDy * neighbourDy);
                if (!(neighbourLength > 0)
                    || !double.IsFinite(neighbourLength)
                    || !(neighbourWidthFt > 0)
                    || !double.IsFinite(neighbourWidthFt))
                    continue;
                double neighbourNormalX = -neighbourDy / neighbourLength;
                double neighbourNormalY = neighbourDx / neighbourLength;
                for (int sideIndex = 0; sideIndex < 2; sideIndex++)
                {
                    double offset = (sideIndex == 0 ? -0.5 : 0.5)
                        * neighbourWidthFt;
                    double firstX = neighbourLocation.StartPoint[0]
                        + neighbourNormalX * offset;
                    double firstY = neighbourLocation.StartPoint[1]
                        + neighbourNormalY * offset;
                    double secondX = neighbourLocation.EndPoint[0]
                        + neighbourNormalX * offset;
                    double secondY = neighbourLocation.EndPoint[1]
                        + neighbourNormalY * offset;
                    double sideDx = secondX - firstX;
                    double sideDy = secondY - firstY;
                    double denominator = axisX * sideDy - axisY * sideDx;
                    double denominatorScale = Math.Max(1.0,
                        Math.Max(Math.Abs(axisX * sideDy),
                            Math.Abs(axisY * sideDx)));
                    if (Math.Abs(denominator)
                        <= 4096 * MachineEpsilon * denominatorScale)
                        continue;
                    double endpointNormal =
                        targetEndpoint.Point[0] * normalX
                        + targetEndpoint.Point[1] * normalY;
                    double originX = normalX * endpointNormal;
                    double originY = normalY * endpointNormal;
                    double offsetX = firstX - originX;
                    double offsetY = firstY - originY;
                    double lineParameter =
                        (offsetX * sideDy - offsetY * sideDx)
                        / denominator;
                    double intersectionX = originX + lineParameter * axisX;
                    double intersectionY = originY + lineParameter * axisY;
                    if (IfcPrecisionKeyFeet(
                            [intersectionX, intersectionY, 0])
                        == endpointKey)
                        endpointMatches.Add((referenceId, sideIndex));
                }
            }
            if (firstEndpoint)
            {
                commonMatches = endpointMatches;
                firstEndpoint = false;
            }
            else
            {
                commonMatches.IntersectWith(endpointMatches);
            }
        }
        return commonMatches.Count == 1;

        static bool StrictVerticalBoundsOverlap(Element first, Element second)
        {
            var firstBounds = first.BoundingBox ?? first.Geometry?.BoundingBox;
            var secondBounds = second.BoundingBox ?? second.Geometry?.BoundingBox;
            if (firstBounds is not { Length: >= 6 }
                || secondBounds is not { Length: >= 6 })
                return false;
            double valuesScale = Math.Max(1.0,
                firstBounds.Concat(secondBounds).Select(Math.Abs).Max());
            double valuesRoundoff =
                4096 * MachineEpsilon * valuesScale;
            return Math.Min(firstBounds[5], secondBounds[5])
                - Math.Max(firstBounds[2], secondBounds[2])
                > valuesRoundoff;
        }

        static bool PointIsOnPlanSegmentAtIfcPrecision(
            double[] point, double[] first, double[] second)
        {
            if (point.Length < 2 || first.Length < 2 || second.Length < 2
                || point.Take(2).Concat(first.Take(2)).Concat(second.Take(2))
                    .Any(value => !double.IsFinite(value)))
                return false;
            var pointKey = IfcPrecisionKeyFeet([point[0], point[1], 0]);
            var firstKey = IfcPrecisionKeyFeet([first[0], first[1], 0]);
            var secondKey = IfcPrecisionKeyFeet([second[0], second[1], 0]);
            var dx = (System.Numerics.BigInteger)secondKey.X - firstKey.X;
            var dy = (System.Numerics.BigInteger)secondKey.Y - firstKey.Y;
            var px = (System.Numerics.BigInteger)pointKey.X - firstKey.X;
            var py = (System.Numerics.BigInteger)pointKey.Y - firstKey.Y;
            var oneCellCross = System.Numerics.BigInteger.Max(
                System.Numerics.BigInteger.Abs(dx),
                System.Numerics.BigInteger.Abs(dy));
            if (oneCellCross == 0
                || System.Numerics.BigInteger.Abs(dx * py - dy * px)
                    > oneCellCross)
                return false;
            var projection = px * dx + py * dy;
            var lengthSquared = dx * dx + dy * dy;
            return projection >= -oneCellCross
                && projection <= lengthSquared + oneCellCross;
        }
    }

    /// <summary>
    /// Each shifted endpoint on both exterior wall sides must equal the unique IFC-lattice
    /// intersection with the authored longitudinal side plane of one explicitly connected
    /// referenced wall.
    /// </summary>
    internal static bool
        ExactStraightWallPlanEndpointsUseExplicitPathNeighbourLattice(
            Element wall, IReadOnlyDictionary<int, Element> elemById,
            GeometryData boundary,
            IReadOnlyCollection<int>? connectedNeighbourIds = null,
            bool requireBothEndsInwardTrim = false)
    {
        IReadOnlyCollection<int> references = connectedNeighbourIds
            ?? wall.References?.Distinct().ToArray()
            ?? [];
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || boundary.BoundingBox is not { Length: 6 } bounds
            || references.Count == 0
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                boundary, location, widthFt, bounds,
                out var plan, out _, out _, out _)
            || plan.Count != 4)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double lengthFt = Math.Sqrt(dx * dx + dy * dy);
        if (!(lengthFt > 0) || !double.IsFinite(lengthFt))
            return false;
        double axisX = dx / lengthFt, axisY = dy / lengthFt;
        double normalX = -axisY, normalY = axisX;
        double locationStartAlong =
            location.StartPoint[0] * axisX
            + location.StartPoint[1] * axisY;
        double locationEndAlong =
            location.EndPoint[0] * axisX
            + location.EndPoint[1] * axisY;
        double locationMinimum = Math.Min(
            locationStartAlong, locationEndAlong);
        double locationMaximum = Math.Max(
            locationStartAlong, locationEndAlong);
        string minimumConnectionType =
            locationStartAlong <= locationEndAlong ? "ATSTART" : "ATEND";
        string maximumConnectionType =
            locationStartAlong <= locationEndAlong ? "ATEND" : "ATSTART";

        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, plan.SelectMany(point => point)
            .Concat(location.StartPoint.Take(2))
            .Concat(location.EndPoint.Take(2))
            .Append(widthFt).Select(Math.Abs).Max());
        double roundoff = 4096 * MachineEpsilon * scale;
        var projected = plan.Select(point => (
            Point: point,
            Along: point[0] * axisX + point[1] * axisY,
            Normal: point[0] * normalX + point[1] * normalY)).ToList();
        double minimumNormal = projected.Min(item => item.Normal);
        double maximumNormal = projected.Max(item => item.Normal);
        var minimumSide = projected
            .Where(item =>
                Math.Abs(item.Normal - minimumNormal) <= roundoff)
            .OrderBy(item => item.Along).ToList();
        var maximumSide = projected
            .Where(item =>
                Math.Abs(item.Normal - maximumNormal) <= roundoff)
            .OrderBy(item => item.Along).ToList();
        if (minimumSide.Count != 2 || maximumSide.Count != 2
            || Math.Abs(
                maximumNormal - minimumNormal - widthFt) > roundoff)
            return false;
        double wallMinimum = projected.Min(item => item.Along);
        double wallMaximum = projected.Max(item => item.Along);
        if (requireBothEndsInwardTrim
            && (!(wallMinimum - locationMinimum > roundoff)
                || !(locationMaximum - wallMaximum > roundoff)))
            return false;

        bool shifted = false;
        return EndpointIsConfirmed(
                minimumSide[0].Point, minimumSide[0].Along,
                locationMinimum, minimumConnectionType)
            && EndpointIsConfirmed(
                maximumSide[0].Point, maximumSide[0].Along,
                locationMinimum, minimumConnectionType)
            && EndpointIsConfirmed(
                minimumSide[1].Point, minimumSide[1].Along,
                locationMaximum, maximumConnectionType)
            && EndpointIsConfirmed(
                maximumSide[1].Point, maximumSide[1].Along,
                locationMaximum, maximumConnectionType)
            && shifted;

        bool EndpointIsConfirmed(
            double[] endpoint, double endpointAlong,
            double locationAlong, string connectionType)
        {
            if (Math.Abs(endpointAlong - locationAlong) <= roundoff)
                return true;
            shifted = true;
            var endpointKey = IfcPrecisionKeyFeet(
                [endpoint[0], endpoint[1], 0]);
            var matches = new HashSet<(int ReferenceId, int EdgeIndex)>();
            double[] originalEndpoint = connectionType == "ATSTART"
                ? location.StartPoint : location.EndPoint;
            foreach (int referenceId in references.Distinct())
            {
                if (referenceId == wall.Id
                    || !elemById.TryGetValue(referenceId, out var neighbour)
                    || neighbour.CategoryId != -2000011
                    || !TryGetSerializedWallWidthFeet(
                        neighbour, out double neighbourWidthFt)
                    || !TryGetAuthoredStraightWallPlan(
                        neighbour, neighbourWidthFt, out var neighbourPlan)
                    || neighbourPlan.Count != 4)
                    continue;
                bool pathMatches;
                if (requireBothEndsInwardTrim)
                {
                    int forwardReferences = wall.References?
                        .Count(id => id == referenceId) ?? 0;
                    int inverseReferences = neighbour.References?
                        .Count(id => id == wall.Id) ?? 0;
                    pathMatches = forwardReferences <= 1
                        && inverseReferences <= 1
                        && forwardReferences + inverseReferences > 0
                        && neighbour.Location is
                            { CurveType: "Line", ArcRadius: null }
                            neighbourLocation
                        && PointIsOnPlanSegmentAtIfcPrecision(
                            originalEndpoint, neighbourLocation.StartPoint,
                            neighbourLocation.EndPoint)
                        && StrictVerticalBoundsOverlap(wall, neighbour);
                }
                else
                {
                    pathMatches = TryGetWallPathConnectionTypes(
                            wall, neighbour, out string wallConnectionType,
                            out _)
                        && wallConnectionType == connectionType;
                }
                if (!pathMatches)
                    continue;

                foreach (int edgeIndex in new[] { 0, 2 })
                {
                    double[] first = neighbourPlan[edgeIndex];
                    double[] second =
                        neighbourPlan[(edgeIndex + 1) % neighbourPlan.Count];
                    double edgeDx = second[0] - first[0];
                    double edgeDy = second[1] - first[1];
                    double denominator =
                        axisX * edgeDy - axisY * edgeDx;
                    double denominatorScale = Math.Max(1.0,
                        Math.Max(Math.Abs(axisX * edgeDy),
                            Math.Abs(axisY * edgeDx)));
                    if (Math.Abs(denominator)
                        <= 4096 * MachineEpsilon * denominatorScale)
                        continue;
                    double endpointNormal =
                        endpoint[0] * normalX + endpoint[1] * normalY;
                    double originX = normalX * endpointNormal;
                    double originY = normalY * endpointNormal;
                    double offsetX = first[0] - originX;
                    double offsetY = first[1] - originY;
                    double lineParameter =
                        (offsetX * edgeDy - offsetY * edgeDx)
                        / denominator;
                    double intersectionX =
                        originX + lineParameter * axisX;
                    double intersectionY =
                        originY + lineParameter * axisY;
                    if (IfcPrecisionKeyFeet(
                            [intersectionX, intersectionY, 0])
                        == endpointKey)
                        matches.Add((referenceId, edgeIndex));
                }
            }
            return matches.Count == 1;
        }

        static bool StrictVerticalBoundsOverlap(Element first, Element second)
        {
            var firstBounds = first.BoundingBox ?? first.Geometry?.BoundingBox;
            var secondBounds = second.BoundingBox ?? second.Geometry?.BoundingBox;
            if (firstBounds is not { Length: >= 6 }
                || secondBounds is not { Length: >= 6 })
                return false;
            const double MachineEpsilon = 2.2204460492503131e-16;
            double valuesScale = Math.Max(1.0,
                firstBounds.Concat(secondBounds).Select(Math.Abs).Max());
            double valuesRoundoff =
                4096 * MachineEpsilon * valuesScale;
            return Math.Min(firstBounds[5], secondBounds[5])
                - Math.Max(firstBounds[2], secondBounds[2])
                > valuesRoundoff;
        }

        static bool PointIsOnPlanSegmentAtIfcPrecision(
            double[] point, double[] first, double[] second)
        {
            if (point.Length < 2 || first.Length < 2 || second.Length < 2
                || point.Take(2).Concat(first.Take(2)).Concat(second.Take(2))
                    .Any(value => !double.IsFinite(value)))
                return false;
            var pointKey = IfcPrecisionKeyFeet([point[0], point[1], 0]);
            var firstKey = IfcPrecisionKeyFeet([first[0], first[1], 0]);
            var secondKey = IfcPrecisionKeyFeet([second[0], second[1], 0]);
            var dx = (System.Numerics.BigInteger)secondKey.X - firstKey.X;
            var dy = (System.Numerics.BigInteger)secondKey.Y - firstKey.Y;
            var px = (System.Numerics.BigInteger)pointKey.X - firstKey.X;
            var py = (System.Numerics.BigInteger)pointKey.Y - firstKey.Y;
            var oneCellCross = System.Numerics.BigInteger.Max(
                System.Numerics.BigInteger.Abs(dx),
                System.Numerics.BigInteger.Abs(dy));
            if (oneCellCross == 0
                || System.Numerics.BigInteger.Abs(dx * py - dy * px)
                    > oneCellCross)
                return false;
            var projection = px * dx + py * dy;
            var lengthSquared = dx * dx + dy * dy;
            return projection >= -oneCellCross
                && projection <= lengthSquared + oneCellCross;
        }
    }

    /// <summary>
    /// BRep caps use the same lattice and G15 formatting as <see cref="CreateFacetedBrep"/>; swept
    /// intervals use the exact decimal sum of the placement and extrusion values written to STEP.
    /// </summary>
    internal static bool HostedOpeningWriterOperandOnlyTouchesExactWallHorizontalCapAfterSerialization(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand)
    {
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out double wallBaseZFt, out double wallHeightFt)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ))
            return false;

        decimal openingMinimumZ;
        decimal openingMaximumZ;
        if (operand.Boundary is { Faces.Count: > 0 } openingBoundary)
        {
            if (!TryGetExactVerticalRectangularPrismPlan(
                    openingBoundary, out _, out _, out _))
                return false;
            var openingKeys = openingBoundary.Faces
                .SelectMany(face => face.OuterVertices ?? [])
                .Select(IfcPrecisionKeyFeet).ToList();
            if (openingKeys.Count == 0
                || !TryGetSerializedIfcReal(
                    openingKeys.Min(point => point.Z)
                        * IfcGeometryPrecisionMetres,
                    out openingMinimumZ)
                || !TryGetSerializedIfcReal(
                    openingKeys.Max(point => point.Z)
                        * IfcGeometryPrecisionMetres,
                    out openingMaximumZ))
                return false;
        }
        else
        {
            if (!operand.ExactDepth
                || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
                || !double.IsFinite(operand.CentreXFt)
                || !double.IsFinite(operand.CentreYFt)
                || !double.IsFinite(operand.AxisX)
                || !double.IsFinite(operand.AxisY)
                || !double.IsFinite(operand.WidthFt)
                || !double.IsFinite(operand.DepthFt)
                || !TryGetSerializedSweptVerticalIntervalMetres(
                    operand.BaseZFt, operand.HeightFt,
                    out openingMinimumZ, out openingMaximumZ))
                return false;
        }

        return openingMinimumZ < openingMaximumZ
            && ((openingMaximumZ == wallMinimumZ
                    && openingMinimumZ < wallMinimumZ)
                || (openingMinimumZ == wallMaximumZ
                    && openingMaximumZ > wallMaximumZ));
    }

    private static bool TryGetSerializedSweptVerticalIntervalMetres(
        double baseZFt, double heightFt,
        out decimal minimumZ, out decimal maximumZ)
    {
        minimumZ = maximumZ = 0;
        if (!double.IsFinite(baseZFt) || !double.IsFinite(heightFt)
            || !(heightFt > 0)
            || !TryGetSerializedIfcReal(baseZFt * FeetToMetres, out minimumZ)
            || !TryGetSerializedIfcReal(heightFt * FeetToMetres,
                out decimal serializedHeight))
            return false;
        maximumZ = minimumZ + serializedHeight;
        return maximumZ > minimumZ;
    }

    private static bool TryGetSerializedIfcReal(double value, out decimal serialized) =>
        decimal.TryParse(StepWriter.Real(value), NumberStyles.Float,
            CultureInfo.InvariantCulture, out serialized);

    /// <summary>
    /// The cutter must remain more than two writer steps inside both wall ends and extend more than
    /// two steps through both wall side planes.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand) =>
        HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand, out _);

    internal static bool
        HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand, out string rejectionReason)
    {
        rejectionReason = "invalid-input-or-wall-definition";
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt)
            || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                operand.BaseZFt, operand.HeightFt,
                out decimal openingMinimumZ, out decimal openingMaximumZ))
            return false;

        decimal verticalGap = (decimal)(2 * IfcGeometryPrecisionMetres);
        bool sharesMinimumCap = openingMinimumZ == wallMinimumZ;
        bool sharesMaximumCap = openingMaximumZ == wallMaximumZ;
        if (!sharesMinimumCap && !sharesMaximumCap)
        {
            rejectionReason = "no-exact-serialized-cap";
            return false;
        }
        if ((!sharesMinimumCap
                && !(openingMinimumZ - wallMinimumZ > verticalGap))
            || (!sharesMaximumCap
                && !(wallMaximumZ - openingMaximumZ > verticalGap)))
        {
            rejectionReason = "nonshared-cap-not-robustly-interior";
            return false;
        }

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
        {
            rejectionReason = "invalid-axis";
            return false;
        }
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double cross = openingAxisX * wallAxisY
            - openingAxisY * wallAxisX;
        double dot = openingAxisX * wallAxisX
            + openingAxisY * wallAxisY;
        if (Math.Min(Math.Abs(cross), Math.Abs(dot))
                > 4096 * MachineEpsilon)
        {
            rejectionReason = "oblique-axis";
            return false;
        }

        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = operand.WidthFt / 2;
        double halfDepth = operand.DepthFt / 2;
        double[][] openingPlan =
        [
            [operand.CentreXFt - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [operand.CentreXFt - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMinimumNormal = wallPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumNormal = wallPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMinimumAlong = openingPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMaximumAlong = openingPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMinimumNormal = openingPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMaximumNormal = openingPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double planGapFt = 2 * IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(openingMinimumAlong - wallMinimumAlong > planGapFt)
            || !(wallMaximumAlong - openingMaximumAlong > planGapFt))
        {
            rejectionReason = "end-clearance";
            return false;
        }
        if (!(wallMinimumNormal - openingMinimumNormal > planGapFt)
            || !(openingMaximumNormal - wallMaximumNormal > planGapFt))
        {
            rejectionReason = "side-through-clearance";
            return false;
        }
        rejectionReason = "accepted";
        return true;
    }

    /// <summary>True when the operand is a writer-precision complementary cap-coincident through cut of an exact wall with a redundant boundary.</summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionComplementaryCapCoincidentThroughCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                operand.BaseZFt, operand.HeightFt,
                out decimal openingMinimumZ, out decimal openingMaximumZ))
            return false;

        bool sharesMinimumCapExactly = openingMinimumZ == wallMinimumZ;
        bool sharesMaximumCapExactly = openingMaximumZ == wallMaximumZ;
        if (sharesMinimumCapExactly == sharesMaximumCapExactly)
            return false;

        decimal sharedTolerance = (decimal)IfcDeclaredPrecisionMetres;
        if (sharesMinimumCapExactly
            ? !(openingMaximumZ < wallMaximumZ
                && wallMaximumZ - openingMaximumZ <= sharedTolerance)
            : !(openingMinimumZ > wallMinimumZ
                && openingMinimumZ - wallMinimumZ <= sharedTolerance))
            return false;

        var capSnappedOperand = operand with
        {
            BaseZFt = wallBaseZFt,
            HeightFt = wallHeightFt,
        };
        return HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
            wall, bounds, wallBoundary, capSnappedOperand);
    }

    /// <summary>
    /// The opposite cap must remain robustly interior by more than two writer geometry steps.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                operand.BaseZFt, operand.HeightFt,
                out decimal openingMinimumZ, out decimal openingMaximumZ))
            return false;

        decimal sharedTolerance = (decimal)IfcDeclaredPrecisionMetres;
        decimal robustGap = (decimal)(2 * IfcGeometryPrecisionMetres);
        decimal minimumGap = openingMinimumZ - wallMinimumZ;
        decimal maximumGap = wallMaximumZ - openingMaximumZ;
        bool nearMinimumCap = minimumGap > 0
            && minimumGap <= sharedTolerance;
        bool nearMaximumCap = maximumGap > 0
            && maximumGap <= sharedTolerance;
        if (nearMinimumCap == nearMaximumCap
            || (nearMinimumCap && !(maximumGap > robustGap))
            || (nearMaximumCap && !(minimumGap > robustGap)))
            return false;

        var capSnappedOperand = operand with
        {
            BaseZFt = wallBaseZFt,
            HeightFt = wallHeightFt,
        };
        return HostedOpeningWriterOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactWall(
            wall, bounds, wallBoundary, capSnappedOperand);
    }

    /// <summary>
    /// The shared cap must be non-exact after G15 serialization but within the declared IFC
    /// precision; the opposite cap remains robustly interior.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand) =>
        HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
            wall, bounds, wallBoundary, operand, out _);

    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionEndSideAndCapCoincidentNotchOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand, out string rejectionReason)
    {
        rejectionReason = "invalid-input-or-wall-definition";
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                operand.BaseZFt, operand.HeightFt,
                out decimal openingMinimumZ, out decimal openingMaximumZ))
            return false;

        decimal sharedTolerance = (decimal)IfcDeclaredPrecisionMetres;
        bool sharesMinimumCap =
            Math.Abs(openingMinimumZ - wallMinimumZ) <= sharedTolerance;
        bool sharesMaximumCap =
            Math.Abs(openingMaximumZ - wallMaximumZ) <= sharedTolerance;
        if (sharesMinimumCap == sharesMaximumCap
            || openingMinimumZ == wallMinimumZ
            || openingMaximumZ == wallMaximumZ)
        {
            rejectionReason = "not-single-nonexact-cap";
            return false;
        }

        decimal robustGap = (decimal)(2 * IfcGeometryPrecisionMetres);
        if ((!sharesMinimumCap
                && !(openingMinimumZ - wallMinimumZ > robustGap))
            || (!sharesMaximumCap
                && !(wallMaximumZ - openingMaximumZ > robustGap)))
        {
            rejectionReason = "opposite-cap-clearance";
            return false;
        }

        var capInteriorOperand = operand with
        {
            BaseZFt = wallBaseZFt + wallHeightFt / 4,
            HeightFt = wallHeightFt / 2,
        };
        bool serializedEndNotch =
            HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWall(
                wall, bounds, wallBoundary, capInteriorOperand,
                out string serializedEndNotchRejectionReason);
        rejectionReason = serializedEndNotch
            ? "accepted"
            : $"serialized-end-notch-{serializedEndNotchRejectionReason}";
        return serializedEndNotch;
    }

    /// <summary>
    /// Every cutter plane and wall plane must retain more than two writer lattice steps of
    /// clearance.
    /// </summary>
    internal static bool HostedOpeningWriterOperandIsRobustInteriorCutOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand) =>
        HostedOpeningWriterOperandIsInteriorCutOfExactWallCore(
            wall, bounds, wallBoundary, operand,
            requireSingleSidePlaneCoincidence: false);

    /// <summary>
    /// The opposite cutter plane must remain more than two writer lattice steps inside the wall,
    /// and both wall ends and horizontal caps retain the same clearance.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionSingleSidePlaneCoincidentInteriorCutOfExactWall(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData wallBoundary, HostedOpeningGeometry operand) =>
            HostedOpeningWriterOperandIsInteriorCutOfExactWallCore(
                wall, bounds, wallBoundary, operand,
                requireSingleSidePlaneCoincidence: true);

    private static bool HostedOpeningWriterOperandIsInteriorCutOfExactWallCore(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand, bool requireSingleSidePlaneCoincidence)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt)
            || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !double.IsFinite(operand.BaseZFt))
            return false;

        double gapFt = 2 * IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(operand.WidthFt > gapFt)
            || !(operand.DepthFt > gapFt)
            || !(operand.HeightFt > gapFt))
            return false;
        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double cross = openingAxisX * wallAxisY
            - openingAxisY * wallAxisX;
        double dot = openingAxisX * wallAxisX
            + openingAxisY * wallAxisY;
        if (Math.Min(Math.Abs(cross), Math.Abs(dot))
                > 4096 * MachineEpsilon)
            return false;

        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = operand.WidthFt / 2;
        double halfDepth = operand.DepthFt / 2;
        double[][] openingPlan =
        [
            [operand.CentreXFt - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [operand.CentreXFt - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMinimumNormal = wallPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumNormal = wallPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMinimumAlong = openingPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMaximumAlong = openingPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMinimumNormal = openingPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMaximumNormal = openingPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumZFt = wallBaseZFt + wallHeightFt;
        double openingMaximumZFt = operand.BaseZFt + operand.HeightFt;
        double sharedPlaneToleranceFt =
            IfcDeclaredPrecisionMetres / FeetToMetres;
        bool sharesMinimumSidePlane =
            Math.Abs(openingMinimumNormal - wallMinimumNormal)
                <= sharedPlaneToleranceFt;
        bool sharesMaximumSidePlane =
            Math.Abs(openingMaximumNormal - wallMaximumNormal)
                <= sharedPlaneToleranceFt;
        bool normalIntervalMatchesContract =
            requireSingleSidePlaneCoincidence
                ? (sharesMinimumSidePlane ^ sharesMaximumSidePlane)
                    && (sharesMinimumSidePlane
                        ? wallMaximumNormal - openingMaximumNormal > gapFt
                        : openingMinimumNormal - wallMinimumNormal > gapFt)
                : openingMinimumNormal - wallMinimumNormal > gapFt
                    && wallMaximumNormal - openingMaximumNormal > gapFt;
        return openingMinimumAlong - wallMinimumAlong > gapFt
            && wallMaximumAlong - openingMaximumAlong > gapFt
            && normalIntervalMatchesContract
            && operand.BaseZFt - wallBaseZFt > gapFt
            && wallMaximumZFt - openingMaximumZFt > gapFt;
    }

    /// <summary>
    /// A matched subdivision of one vertical profile edge is the same exact gross prism and is
    /// admitted explicitly.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionReason)
            || !(IsExactRedundantWallDefinitionReason(wallDefinitionReason)
                || wallDefinitionReason
                    == "exact-subdivided-vertical-profile-edge")
            || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !double.IsFinite(operand.BaseZFt))
            return false;

        double gapFt = 2 * IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(operand.WidthFt > gapFt)
            || !(operand.DepthFt > gapFt)
            || !(operand.HeightFt > gapFt))
            return false;
        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double cross = openingAxisX * wallAxisY
            - openingAxisY * wallAxisX;
        double dot = openingAxisX * wallAxisX
            + openingAxisY * wallAxisY;
        if (Math.Min(Math.Abs(cross), Math.Abs(dot))
                > 4096 * MachineEpsilon)
            return false;

        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = operand.WidthFt / 2;
        double halfDepth = operand.DepthFt / 2;
        double[][] openingPlan =
        [
            [operand.CentreXFt - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [operand.CentreXFt - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMinimumNormal = wallPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumNormal = wallPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMinimumAlong = openingPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMaximumAlong = openingPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMinimumNormal = openingPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMaximumNormal = openingPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumZFt = wallBaseZFt + wallHeightFt;
        double openingMaximumZFt = operand.BaseZFt + operand.HeightFt;
        double sharedPlaneToleranceFt =
            IfcDeclaredPrecisionMetres / FeetToMetres;
        return openingMinimumAlong - wallMinimumAlong > gapFt
            && wallMaximumAlong - openingMaximumAlong > gapFt
            && Math.Abs(openingMinimumNormal - wallMinimumNormal)
                <= sharedPlaneToleranceFt
            && Math.Abs(openingMaximumNormal - wallMaximumNormal)
                <= sharedPlaneToleranceFt
            && operand.BaseZFt - wallBaseZFt > gapFt
            && wallMaximumZFt - openingMaximumZFt > gapFt;
    }

    /// <summary>The crossing and remaining overlap must each exceed two writer lattice steps.</summary>
    internal static bool
        HostedOpeningWriterOperandIsRobustSingleEndCrossingSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionReason)
            || !(IsExactRedundantWallDefinitionReason(wallDefinitionReason)
                || wallDefinitionReason
                    == "exact-subdivided-vertical-profile-edge")
            || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !double.IsFinite(operand.BaseZFt))
            return false;

        double gapFt = 2 * IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(operand.WidthFt > gapFt)
            || !(operand.DepthFt > gapFt)
            || !(operand.HeightFt > gapFt))
            return false;
        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double cross = openingAxisX * wallAxisY
            - openingAxisY * wallAxisX;
        double dot = openingAxisX * wallAxisX
            + openingAxisY * wallAxisY;
        if (Math.Min(Math.Abs(cross), Math.Abs(dot))
                > 4096 * MachineEpsilon)
            return false;

        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = operand.WidthFt / 2;
        double halfDepth = operand.DepthFt / 2;
        double[][] openingPlan =
        [
            [operand.CentreXFt - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [operand.CentreXFt - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMinimumNormal = wallPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumNormal = wallPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMinimumAlong = openingPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMaximumAlong = openingPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double openingMinimumNormal = openingPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double openingMaximumNormal = openingPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumZFt = wallBaseZFt + wallHeightFt;
        double openingMaximumZFt = operand.BaseZFt + operand.HeightFt;
        double sharedPlaneToleranceFt =
            IfcDeclaredPrecisionMetres / FeetToMetres;
        bool crossesMinimumEndOnly =
            wallMinimumAlong - openingMinimumAlong > gapFt
            && openingMaximumAlong - wallMinimumAlong > gapFt
            && wallMaximumAlong - openingMaximumAlong > gapFt;
        bool crossesMaximumEndOnly =
            openingMaximumAlong - wallMaximumAlong > gapFt
            && wallMaximumAlong - openingMinimumAlong > gapFt
            && openingMinimumAlong - wallMinimumAlong > gapFt;
        return crossesMinimumEndOnly != crossesMaximumEndOnly
            && Math.Abs(openingMinimumNormal - wallMinimumNormal)
                <= sharedPlaneToleranceFt
            && Math.Abs(openingMaximumNormal - wallMaximumNormal)
                <= sharedPlaneToleranceFt
            && operand.BaseZFt - wallBaseZFt > gapFt
            && wallMaximumZFt - openingMaximumZFt > gapFt;
    }

    /// <summary>True when the operand is a writer-precision full-plan coextensive interior cut of an exact boundary-owned wall.</summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionFullPlanCoextensiveInteriorCutOfExactBoundaryOwnedWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !(operand.WidthFt > 0)
            || !double.IsFinite(operand.WidthFt)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY))
            return false;

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        if (Math.Abs(openingAxisX * wallAxisY
                - openingAxisY * wallAxisX) > 4096 * MachineEpsilon)
            return false;

        double halfSpanWidthFt = operand.WidthFt / 2;
        var interiorValidation = operand with { WidthFt = halfSpanWidthFt };
        if (!HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, wallBoundary, interiorValidation))
            return false;

        double quarterSpanFt = operand.WidthFt / 4;
        var firstEndValidation = interiorValidation with
        {
            CentreXFt = operand.CentreXFt
                - quarterSpanFt * openingAxisX,
            CentreYFt = operand.CentreYFt
                - quarterSpanFt * openingAxisY,
        };
        var secondEndValidation = interiorValidation with
        {
            CentreXFt = operand.CentreXFt
                + quarterSpanFt * openingAxisX,
            CentreYFt = operand.CentreYFt
                + quarterSpanFt * openingAxisY,
        };
        return HostedOpeningWriterOperandsAnchorBothEndsOfExactWall(
            wall, bounds, wallBoundary, [firstEndValidation, secondEndValidation]);
    }

    /// <summary>Direct BReps, exact/crossing caps, and nonparallel boxes fail.</summary>
    internal static bool
        HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveCapCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY))
            return false;

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        if (Math.Abs(openingAxisX * wallAxisY
                - openingAxisY * wallAxisX) > 4096 * MachineEpsilon)
            return false;

        double verticalMarginFt =
            4 * IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(wallHeightFt > 2 * verticalMarginFt))
            return false;
        var interiorCapValidation = operand with
        {
            BaseZFt = wallBaseZFt + verticalMarginFt,
            HeightFt = wallHeightFt - 2 * verticalMarginFt,
        };
        if (!HostedOpeningWriterOperandIsWriterPrecisionSidePlaneCoextensiveInteriorCutOfExactRedundantBoundaryWall(
                wall, bounds, wallBoundary, interiorCapValidation))
            return false;

        double throughDepthFt = widthFt
            + 8 * IfcGeometryPrecisionMetres / FeetToMetres;
        var capValidation = operand with { DepthFt = throughDepthFt };
        return HostedOpeningWriterOperandIsWriterPrecisionSingleCapCoincidentThroughCutOfExactRedundantBoundaryWall(
            wall, bounds, wallBoundary, capValidation);
    }

    /// <summary>The opposite cutter plane must remain more than two steps outside.</summary>
    internal static bool HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand)
    {
        if (wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt))
            return false;
        return HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
            location, widthFt, bounds, wallBoundary, operand);
    }

    internal static bool HostedOpeningWriterOperandOnlyTouchesExactWallVerticalPlanBoundaryAfterSerialization(
        LocationCurve location, double widthFt,
        IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not null || !operand.ExactDepth
            || location is not { CurveType: "Line", ArcRadius: null }
            || !(widthFt > 0) || !double.IsFinite(widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt)
            || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                operand.BaseZFt, operand.HeightFt,
                out decimal openingMinimumZ, out decimal openingMaximumZ))
            return false;

        double rawWallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double rawWallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double rawWallAxisLength = Math.Sqrt(
            rawWallAxisX * rawWallAxisX + rawWallAxisY * rawWallAxisY);
        double rawOpeningAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(rawWallAxisLength > 0) || !double.IsFinite(rawWallAxisLength)
            || !(rawOpeningAxisLength > 0)
            || !double.IsFinite(rawOpeningAxisLength))
            return false;
        rawWallAxisX /= rawWallAxisLength;
        rawWallAxisY /= rawWallAxisLength;
        double rawOpeningAxisX = operand.AxisX / rawOpeningAxisLength;
        double rawOpeningAxisY = operand.AxisY / rawOpeningAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double rawCross = rawOpeningAxisX * rawWallAxisY
            - rawOpeningAxisY * rawWallAxisX;
        double rawDot = rawOpeningAxisX * rawWallAxisX
            + rawOpeningAxisY * rawWallAxisY;
        if (Math.Min(Math.Abs(rawCross), Math.Abs(rawDot))
                > 4096 * MachineEpsilon)
            return false;

        static bool TrySerialize(double value, out double serialized) =>
            double.TryParse(StepWriter.Real(value), NumberStyles.Float,
                CultureInfo.InvariantCulture, out serialized)
            && double.IsFinite(serialized);
        static bool TryNormalize(double x, double y,
            out double normalizedX, out double normalizedY)
        {
            normalizedX = normalizedY = 0;
            double length = Math.Sqrt(x * x + y * y);
            if (!(length > 0) || !double.IsFinite(length)) return false;
            normalizedX = x / length;
            normalizedY = y / length;
            return true;
        }

        double centreXFt = (location.StartPoint[0] + location.EndPoint[0]) / 2;
        double centreYFt = (location.StartPoint[1] + location.EndPoint[1]) / 2;
        if (TryResolveStraightWallPlanCentre(
                location, widthFt, bounds,
                out double resolvedCentreXFt, out double resolvedCentreYFt))
        {
            centreXFt = resolvedCentreXFt;
            centreYFt = resolvedCentreYFt;
        }
        double rawWallCentreX = centreXFt * FeetToMetres;
        double rawWallCentreY = centreYFt * FeetToMetres;
        if (!TrySerialize(rawWallCentreX, out double wallCentreX)
            || !TrySerialize(rawWallCentreY, out double wallCentreY)
            || !TrySerialize(rawWallAxisX, out double serializedWallAxisX)
            || !TrySerialize(rawWallAxisY, out double serializedWallAxisY)
            || !TryNormalize(serializedWallAxisX, serializedWallAxisY,
                out double wallAxisX, out double wallAxisY))
            return false;
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double rawWallNormalX = -rawWallAxisY;
        double rawWallNormalY = rawWallAxisX;
        var serializedWallPlan = new List<double[]>(wallPlan.Count);
        foreach (double[] point in wallPlan)
        {
            double worldX = point[0] * FeetToMetres;
            double worldY = point[1] * FeetToMetres;
            double localX = (worldX - rawWallCentreX) * rawWallAxisX
                + (worldY - rawWallCentreY) * rawWallAxisY;
            double localY = (worldX - rawWallCentreX) * rawWallNormalX
                + (worldY - rawWallCentreY) * rawWallNormalY;
            if (!TrySerialize(localX, out double serializedLocalX)
                || !TrySerialize(localY, out double serializedLocalY))
                return false;
            serializedWallPlan.Add(
            [
                wallCentreX + serializedLocalX * wallAxisX
                    + serializedLocalY * wallNormalX,
                wallCentreY + serializedLocalX * wallAxisY
                    + serializedLocalY * wallNormalY,
            ]);
        }

        if (!TrySerialize(operand.CentreXFt * FeetToMetres,
                out double openingCentreX)
            || !TrySerialize(operand.CentreYFt * FeetToMetres,
                out double openingCentreY)
            || !TrySerialize(rawOpeningAxisX,
                out double serializedOpeningAxisX)
            || !TrySerialize(rawOpeningAxisY,
                out double serializedOpeningAxisY)
            || !TryNormalize(serializedOpeningAxisX, serializedOpeningAxisY,
                out double openingAxisX, out double openingAxisY)
            || !TrySerialize(operand.WidthFt * FeetToMetres,
                out double openingWidth)
            || !TrySerialize(operand.DepthFt * FeetToMetres,
                out double openingDepth)
            || !(openingWidth > 0) || !(openingDepth > 0))
            return false;
        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = openingWidth / 2;
        double halfDepth = openingDepth / 2;
        List<double[]> serializedOpeningPlan =
        [
            [openingCentreX - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             openingCentreY - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [openingCentreX + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             openingCentreY + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [openingCentreX + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             openingCentreY + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [openingCentreX - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             openingCentreY - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];

        double[] wallAlong = serializedWallPlan.Select(point =>
            point[0] * wallAxisX + point[1] * wallAxisY).ToArray();
        double[] wallNormal = serializedWallPlan.Select(point =>
            point[0] * wallNormalX + point[1] * wallNormalY).ToArray();
        double[] openingAlong = serializedOpeningPlan.Select(point =>
            point[0] * wallAxisX + point[1] * wallAxisY).ToArray();
        double[] openingNormal = serializedOpeningPlan.Select(point =>
            point[0] * wallNormalX + point[1] * wallNormalY).ToArray();
        double wallMinimumAlong = wallAlong.Min();
        double wallMaximumAlong = wallAlong.Max();
        double wallMinimumNormal = wallNormal.Min();
        double wallMaximumNormal = wallNormal.Max();
        double openingMinimumAlong = openingAlong.Min();
        double openingMaximumAlong = openingAlong.Max();
        double openingMinimumNormal = openingNormal.Min();
        double openingMaximumNormal = openingNormal.Max();
        double gap = 2 * IfcGeometryPrecisionMetres;

        static bool HasSingleEdgeAtExtreme(
            IReadOnlyList<double> coordinates, double extreme)
        {
            long extremeBin = IfcPrecisionBinMetres(extreme);
            int[] indices = coordinates.Select((value, index) => (value, index))
                .Where(item => IfcPrecisionBinMetres(item.value) == extremeBin)
                .Select(item => item.index).ToArray();
            return indices.Length == 2
                && (Math.Abs(indices[0] - indices[1]) == 1
                    || Math.Abs(indices[0] - indices[1])
                        == coordinates.Count - 1);
        }

        static bool SharesMinimumBoundary(
            IReadOnlyList<double> wallCoordinates,
            IReadOnlyList<double> openingCoordinates,
            double wallMinimum, double openingMinimum,
            double openingMaximum, double requiredGap) =>
            IfcPrecisionBinMetres(openingMaximum)
                == IfcPrecisionBinMetres(wallMinimum)
            && HasSingleEdgeAtExtreme(wallCoordinates, wallMinimum)
            && HasSingleEdgeAtExtreme(openingCoordinates, openingMaximum)
            && wallMinimum - openingMinimum > requiredGap;
        static bool SharesMaximumBoundary(
            IReadOnlyList<double> wallCoordinates,
            IReadOnlyList<double> openingCoordinates,
            double wallMaximum, double openingMinimum,
            double openingMaximum, double requiredGap) =>
            IfcPrecisionBinMetres(openingMinimum)
                == IfcPrecisionBinMetres(wallMaximum)
            && HasSingleEdgeAtExtreme(wallCoordinates, wallMaximum)
            && HasSingleEdgeAtExtreme(openingCoordinates, openingMinimum)
            && openingMaximum - wallMaximum > requiredGap;

        return SharesMinimumBoundary(
                wallAlong, openingAlong, wallMinimumAlong,
                openingMinimumAlong, openingMaximumAlong, gap)
            || SharesMaximumBoundary(
                wallAlong, openingAlong, wallMaximumAlong,
                openingMinimumAlong, openingMaximumAlong, gap)
            || SharesMinimumBoundary(
                wallNormal, openingNormal, wallMinimumNormal,
                openingMinimumNormal, openingMaximumNormal, gap)
            || SharesMaximumBoundary(
                wallNormal, openingNormal, wallMaximumNormal,
                openingMinimumNormal, openingMaximumNormal, gap);
    }

    /// <summary>True when the BRep operand only touches a vertical plane boundary of the wall on the writer lattice.</summary>
    internal static bool
        HostedOpeningWriterBrepOperandOnlyTouchesWriterLatticeWallVerticalPlanBoundary(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not { } openingBoundary
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt)
            || !TryGetExactVerticalRectangularPrismPlan(
                openingBoundary, out var openingPlan,
                out double openingBaseZFt, out double openingHeightFt))
            return false;

        var wallMinimumZ = IfcPrecisionKeyFeet([0, 0, wallBaseZFt]).Z;
        var wallMaximumZ =
            IfcPrecisionKeyFeet([0, 0, wallBaseZFt + wallHeightFt]).Z;
        var openingMinimumZ = IfcPrecisionKeyFeet([0, 0, openingBaseZFt]).Z;
        var openingMaximumZ =
            IfcPrecisionKeyFeet([0, 0, openingBaseZFt + openingHeightFt]).Z;
        if (Math.Min(wallMaximumZ, openingMaximumZ)
                - Math.Max(wallMinimumZ, openingMinimumZ) <= 2)
            return false;

        static List<(long X, long Y)> Keys(IReadOnlyList<double[]> plan) =>
            plan.Select(point => IfcPrecisionKeyFeet([point[0], point[1], 0]))
                .Select(key => (key.X, key.Y)).ToList();
        var wallKeys = Keys(wallPlan);
        var openingKeys = Keys(openingPlan);
        if (wallKeys.Count != 4 || openingKeys.Count != 4
            || wallKeys.Distinct().Count() != 4
            || openingKeys.Distinct().Count() != 4)
            return false;

        static System.Numerics.BigInteger Cross(
            (long X, long Y) first, (long X, long Y) second,
            (long X, long Y) point) =>
            ((System.Numerics.BigInteger)second.X - first.X)
                * (point.Y - first.Y)
            - ((System.Numerics.BigInteger)second.Y - first.Y)
                * (point.X - first.X);
        static bool IsStrictlyConvex(IReadOnlyList<(long X, long Y)> polygon)
        {
            int orientation = 0;
            for (int index = 0; index < polygon.Count; index++)
            {
                var value = Cross(
                    polygon[index],
                    polygon[(index + 1) % polygon.Count],
                    polygon[(index + 2) % polygon.Count]);
                int sign = value.Sign;
                if (sign == 0) return false;
                if (orientation == 0) orientation = sign;
                else if (orientation != sign) return false;
            }
            return true;
        }
        if (!IsStrictlyConvex(wallKeys) || !IsStrictlyConvex(openingKeys))
            return false;

        int sharedSupportingEdges = 0;
        for (int wallIndex = 0; wallIndex < wallKeys.Count; wallIndex++)
        {
            var first = wallKeys[wallIndex];
            var second = wallKeys[(wallIndex + 1) % wallKeys.Count];
            var wallSides = wallKeys.Select(point => Cross(first, second, point)).ToList();
            var openingSides =
                openingKeys.Select(point => Cross(first, second, point)).ToList();
            var wallZeroIndices = wallSides.Select((value, index) => (value, index))
                .Where(item => item.value.IsZero).Select(item => item.index).ToList();
            var openingZeroIndices = openingSides.Select((value, index) => (value, index))
                .Where(item => item.value.IsZero).Select(item => item.index).ToList();
            if (wallZeroIndices.Count != 2 || openingZeroIndices.Count != 2
                || !(Math.Abs(openingZeroIndices[0] - openingZeroIndices[1]) == 1
                    || Math.Abs(openingZeroIndices[0] - openingZeroIndices[1])
                        == openingKeys.Count - 1))
                continue;

            int wallSide = wallSides.First(value => !value.IsZero).Sign;
            int openingSide = openingSides.First(value => !value.IsZero).Sign;
            if (wallSide == openingSide
                || wallSides.Any(value => !value.IsZero && value.Sign != wallSide)
                || openingSides.Any(value =>
                    !value.IsZero && value.Sign != openingSide))
                continue;

            var dx = (System.Numerics.BigInteger)second.X - first.X;
            var dy = (System.Numerics.BigInteger)second.Y - first.Y;
            var wallLengthSquared = dx * dx + dy * dy;
            System.Numerics.BigInteger Projection((long X, long Y) point) =>
                ((System.Numerics.BigInteger)point.X - first.X) * dx
                + ((System.Numerics.BigInteger)point.Y - first.Y) * dy;
            var openingProjections = openingZeroIndices
                .Select(index => Projection(openingKeys[index])).ToList();
            var overlapMinimum = System.Numerics.BigInteger.Max(
                System.Numerics.BigInteger.Zero, openingProjections.Min());
            var overlapMaximum = System.Numerics.BigInteger.Min(
                wallLengthSquared, openingProjections.Max());
            if (overlapMaximum > overlapMinimum) sharedSupportingEdges++;
        }
        return sharedSupportingEdges == 1;
    }

    /// <summary>True when the operand is a serialized end-coincident through notch of an exact wall.</summary>
    internal static bool HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand) =>
        HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWall(
            wall, bounds, wallBoundary, operand, out _);

    internal static bool HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand, out string rejectionReason)
        => HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWallCore(
            wall, bounds, wallBoundary, operand,
            requireRobustSideCrossing: false, out rejectionReason);

    private static bool
        HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWallCore(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData wallBoundary, HostedOpeningGeometry operand,
            bool requireRobustSideCrossing, out string rejectionReason)
    {
        rejectionReason = "invalid-input-or-wall-definition";
        if (operand.Boundary is not null || !operand.ExactDepth
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt)
            || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                wallBaseZFt, wallHeightFt,
                out decimal wallMinimumZ, out decimal wallMaximumZ)
            || !TryGetSerializedSweptVerticalIntervalMetres(
                operand.BaseZFt, operand.HeightFt,
                out decimal openingMinimumZ, out decimal openingMaximumZ))
            return false;

        decimal robustGap = (decimal)(2 * IfcGeometryPrecisionMetres);
        if (!(openingMinimumZ - wallMinimumZ > robustGap)
            || !(wallMaximumZ - openingMaximumZ > robustGap))
        {
            rejectionReason = "cap-clearance";
            return false;
        }

        double rawWallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double rawWallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double rawWallAxisLength = Math.Sqrt(
            rawWallAxisX * rawWallAxisX + rawWallAxisY * rawWallAxisY);
        double rawOpeningAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(rawWallAxisLength > 0) || !double.IsFinite(rawWallAxisLength)
            || !(rawOpeningAxisLength > 0) || !double.IsFinite(rawOpeningAxisLength))
        {
            rejectionReason = "invalid-axis";
            return false;
        }
        rawWallAxisX /= rawWallAxisLength;
        rawWallAxisY /= rawWallAxisLength;
        double rawOpeningAxisX = operand.AxisX / rawOpeningAxisLength;
        double rawOpeningAxisY = operand.AxisY / rawOpeningAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        if (Math.Abs(rawOpeningAxisX * rawWallAxisY
                - rawOpeningAxisY * rawWallAxisX) > 4096 * MachineEpsilon)
        {
            rejectionReason = "nonparallel-axis";
            return false;
        }

        static bool TrySerialize(double value, out double serialized) =>
            double.TryParse(StepWriter.Real(value), NumberStyles.Float,
                CultureInfo.InvariantCulture, out serialized)
            && double.IsFinite(serialized);
        static bool TryNormalize(double x, double y,
            out double normalizedX, out double normalizedY)
        {
            normalizedX = normalizedY = 0;
            double length = Math.Sqrt(x * x + y * y);
            if (!(length > 0) || !double.IsFinite(length)) return false;
            normalizedX = x / length;
            normalizedY = y / length;
            return true;
        }

        double centreXFt = (location.StartPoint[0] + location.EndPoint[0]) / 2;
        double centreYFt = (location.StartPoint[1] + location.EndPoint[1]) / 2;
        if (TryResolveStraightWallPlanCentre(
                location, widthFt, bounds,
                out double resolvedCentreXFt, out double resolvedCentreYFt))
        {
            centreXFt = resolvedCentreXFt;
            centreYFt = resolvedCentreYFt;
        }
        double rawWallCentreX = centreXFt * FeetToMetres;
        double rawWallCentreY = centreYFt * FeetToMetres;
        if (!TrySerialize(rawWallCentreX, out double wallCentreX)
            || !TrySerialize(rawWallCentreY, out double wallCentreY)
            || !TrySerialize(rawWallAxisX, out double serializedWallAxisX)
            || !TrySerialize(rawWallAxisY, out double serializedWallAxisY)
            || !TryNormalize(serializedWallAxisX, serializedWallAxisY,
                out double wallAxisX, out double wallAxisY))
        {
            rejectionReason = "wall-plan-serialization";
            return false;
        }
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;

        var serializedWallPlan = new List<double[]>(wallPlan.Count);
        double rawWallNormalX = -rawWallAxisY;
        double rawWallNormalY = rawWallAxisX;
        foreach (double[] point in wallPlan)
        {
            double worldX = point[0] * FeetToMetres;
            double worldY = point[1] * FeetToMetres;
            double localX = (worldX - rawWallCentreX) * rawWallAxisX
                + (worldY - rawWallCentreY) * rawWallAxisY;
            double localY = (worldX - rawWallCentreX) * rawWallNormalX
                + (worldY - rawWallCentreY) * rawWallNormalY;
            if (!TrySerialize(localX, out double serializedLocalX)
                || !TrySerialize(localY, out double serializedLocalY))
            {
                rejectionReason = "wall-vertex-serialization";
                return false;
            }
            serializedWallPlan.Add(
            [
                wallCentreX + serializedLocalX * wallAxisX
                    + serializedLocalY * wallNormalX,
                wallCentreY + serializedLocalX * wallAxisY
                    + serializedLocalY * wallNormalY,
            ]);
        }

        if (!TrySerialize(operand.CentreXFt * FeetToMetres,
                out double openingCentreX)
            || !TrySerialize(operand.CentreYFt * FeetToMetres,
                out double openingCentreY)
            || !TrySerialize(rawOpeningAxisX,
                out double serializedOpeningAxisX)
            || !TrySerialize(rawOpeningAxisY,
                out double serializedOpeningAxisY)
            || !TryNormalize(serializedOpeningAxisX, serializedOpeningAxisY,
                out double openingAxisX, out double openingAxisY)
            || !TrySerialize(operand.WidthFt * FeetToMetres,
                out double openingWidth)
            || !TrySerialize(operand.DepthFt * FeetToMetres,
                out double openingDepth)
            || !(openingWidth > 0) || !(openingDepth > 0))
        {
            rejectionReason = "opening-plan-serialization";
            return false;
        }
        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = openingWidth / 2;
        double halfDepth = openingDepth / 2;
        List<double[]> serializedOpeningPlan =
        [
            [openingCentreX - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             openingCentreY - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [openingCentreX + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             openingCentreY + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [openingCentreX + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             openingCentreY + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [openingCentreX - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             openingCentreY - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];

        double[] wallAlong = serializedWallPlan.Select(point =>
            point[0] * wallAxisX + point[1] * wallAxisY).ToArray();
        double[] wallNormal = serializedWallPlan.Select(point =>
            point[0] * wallNormalX + point[1] * wallNormalY).ToArray();
        double[] openingAlong = serializedOpeningPlan.Select(point =>
            point[0] * wallAxisX + point[1] * wallAxisY).ToArray();
        double[] openingNormal = serializedOpeningPlan.Select(point =>
            point[0] * wallNormalX + point[1] * wallNormalY).ToArray();
        double wallMinimumAlong = wallAlong.Min();
        double wallMaximumAlong = wallAlong.Max();
        double wallMinimumNormal = wallNormal.Min();
        double wallMaximumNormal = wallNormal.Max();
        double openingMinimumAlong = openingAlong.Min();
        double openingMaximumAlong = openingAlong.Max();
        double openingMinimumNormal = openingNormal.Min();
        double openingMaximumNormal = openingNormal.Max();
        double sharedTolerance = IfcDeclaredPrecisionMetres;
        double gap = 2 * IfcGeometryPrecisionMetres;

        static bool HasSingleEdgeAtExtreme(
            IReadOnlyList<double> coordinates, double extreme, double tolerance)
        {
            int[] indices = coordinates.Select((value, index) => (value, index))
                .Where(item => Math.Abs(item.value - extreme) <= tolerance)
                .Select(item => item.index).ToArray();
            return indices.Length == 2
                && (Math.Abs(indices[0] - indices[1]) == 1
                    || Math.Abs(indices[0] - indices[1]) == coordinates.Count - 1);
        }

        bool sharesMinimumEnd =
            Math.Abs(openingMinimumAlong - wallMinimumAlong) <= sharedTolerance
            && HasSingleEdgeAtExtreme(wallAlong, wallMinimumAlong, sharedTolerance)
            && HasSingleEdgeAtExtreme(openingAlong, openingMinimumAlong, sharedTolerance)
            && openingMaximumAlong - wallMinimumAlong > gap
            && wallMaximumAlong - openingMaximumAlong > gap;
        bool sharesMaximumEnd =
            Math.Abs(openingMaximumAlong - wallMaximumAlong) <= sharedTolerance
            && HasSingleEdgeAtExtreme(wallAlong, wallMaximumAlong, sharedTolerance)
            && HasSingleEdgeAtExtreme(openingAlong, openingMaximumAlong, sharedTolerance)
            && wallMaximumAlong - openingMinimumAlong > gap
            && openingMinimumAlong - wallMinimumAlong > gap;
        if (sharesMinimumEnd == sharesMaximumEnd)
        {
            rejectionReason = "not-single-shared-end";
            return false;
        }
        bool stableSidePlanes = requireRobustSideCrossing
            ? openingMinimumNormal < wallMinimumNormal - gap
                && openingMaximumNormal > wallMaximumNormal + gap
            : Math.Abs(openingMinimumNormal - wallMinimumNormal) <= sharedTolerance
                && Math.Abs(openingMaximumNormal - wallMaximumNormal) <= sharedTolerance;
        if (!stableSidePlanes)
        {
            rejectionReason = FormattableString.Invariant(
                $"side-plane-{(requireRobustSideCrossing ? "crossing" : "coincidence")}-minimumDelta={openingMinimumNormal - wallMinimumNormal:G17}-maximumDelta={openingMaximumNormal - wallMaximumNormal:G17}-tolerance={sharedTolerance:G17}");
            return false;
        }

        static double SignedArea(IReadOnlyList<double[]> polygon)
        {
            double twiceArea = 0;
            for (int index = 0; index < polygon.Count; index++)
            {
                double[] first = polygon[index];
                double[] second = polygon[(index + 1) % polygon.Count];
                twiceArea += first[0] * second[1] - second[0] * first[1];
            }
            return twiceArea / 2;
        }
        double openingArea = Math.Abs(SignedArea(serializedOpeningPlan));
        if (!(openingArea > gap * gap))
        {
            rejectionReason = "opening-area";
            return false;
        }
        if (!requireRobustSideCrossing)
        {
            bool wallCounterClockwise = SignedArea(serializedWallPlan) > 0;
            foreach (double[] point in serializedOpeningPlan)
                for (int index = 0; index < serializedWallPlan.Count; index++)
                {
                    double[] first = serializedWallPlan[index];
                    double[] second = serializedWallPlan[
                        (index + 1) % serializedWallPlan.Count];
                    double edgeX = second[0] - first[0];
                    double edgeY = second[1] - first[1];
                    double edgeLength = Math.Sqrt(edgeX * edgeX + edgeY * edgeY);
                    if (!(edgeLength > gap))
                    {
                        rejectionReason = "wall-edge-length";
                        return false;
                    }
                    double signedDistance = (edgeX * (point[1] - first[1])
                        - edgeY * (point[0] - first[0])) / edgeLength;
                    if (wallCounterClockwise
                            ? signedDistance < -sharedTolerance
                            : signedDistance > sharedTolerance)
                    {
                        rejectionReason = "plan-containment";
                        return false;
                    }
                }
        }
        rejectionReason = "accepted";
        return true;
    }

    /// <summary>A single operand cannot anchor both ends.</summary>
    internal static bool HostedOpeningWriterOperandsAnchorBothEndsOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        IReadOnlyList<HostedOpeningGeometry> operands)
    {
        if (operands.Count < 2
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out _, out _, out string definitionReason)
            || definitionReason != "exact-boundary-owned-redundant-faces")
            return false;

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        bool anchorsMinimum = false;
        bool anchorsMaximum = false;
        foreach (HostedOpeningGeometry operand in operands)
        {
            if (!HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWall(
                    wall, bounds, wallBoundary, operand))
                continue;
            double openingAxisLength = Math.Sqrt(
                operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
            if (!(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
                return false;
            double openingAxisX = operand.AxisX / openingAxisLength;
            double openingAxisY = operand.AxisY / openingAxisLength;
            double openingNormalX = -openingAxisY;
            double openingNormalY = openingAxisX;
            double centreAlong = operand.CentreXFt * wallAxisX
                + operand.CentreYFt * wallAxisY;
            double halfAlong = Math.Abs(openingAxisX * wallAxisX
                    + openingAxisY * wallAxisY) * operand.WidthFt / 2
                + Math.Abs(openingNormalX * wallAxisX
                    + openingNormalY * wallAxisY) * operand.DepthFt / 2;
            double openingMinimumAlong = centreAlong - halfAlong;
            double openingMaximumAlong = centreAlong + halfAlong;
            bool ownsMinimum =
                Math.Abs(openingMinimumAlong - wallMinimumAlong) <= toleranceFt;
            bool ownsMaximum =
                Math.Abs(openingMaximumAlong - wallMaximumAlong) <= toleranceFt;
            if (ownsMinimum == ownsMaximum) return false;
            anchorsMinimum |= ownsMinimum;
            anchorsMaximum |= ownsMaximum;
        }
        return anchorsMinimum && anchorsMaximum;
    }

    /// <summary>
    /// Extensions, two changed ends, two unchanged ends, and an operand on the retained
    /// LocationCurve end are rejected.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandAnchorsSoleInwardShiftedEndOfExactWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || location.StartPoint.Length < 2 || location.EndPoint.Length < 2
            || !HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWall(
                wall, bounds, wallBoundary, operand)
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out _, out _, out string definitionReason)
            || definitionReason != "exact-boundary-owned-redundant-faces")
            return false;

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;

        double startAlong = location.StartPoint[0] * wallAxisX
            + location.StartPoint[1] * wallAxisY;
        double endAlong = location.EndPoint[0] * wallAxisX
            + location.EndPoint[1] * wallAxisY;
        double locationMinimumAlong = Math.Min(startAlong, endAlong);
        double locationMaximumAlong = Math.Max(startAlong, endAlong);
        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);

        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, wallPlan.SelectMany(point => point)
            .Concat(location.StartPoint.Take(2))
            .Concat(location.EndPoint.Take(2))
            .Select(Math.Abs).Max());
        double roundoff = 4096 * MachineEpsilon * scale;
        double minimumDelta = wallMinimumAlong - locationMinimumAlong;
        double maximumDelta = wallMaximumAlong - locationMaximumAlong;
        bool minimumUnchanged = Math.Abs(minimumDelta) <= roundoff;
        bool maximumUnchanged = Math.Abs(maximumDelta) <= roundoff;
        if (minimumUnchanged == maximumUnchanged)
            return false;
        bool minimumTrimmed = maximumUnchanged && minimumDelta > roundoff;
        bool maximumTrimmed = minimumUnchanged && maximumDelta < -roundoff;
        if (minimumTrimmed == maximumTrimmed)
            return false;

        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double centreAlong = operand.CentreXFt * wallAxisX
            + operand.CentreYFt * wallAxisY;
        double halfAlong = Math.Abs(openingAxisX * wallAxisX
                + openingAxisY * wallAxisY) * operand.WidthFt / 2
            + Math.Abs(openingNormalX * wallAxisX
                + openingNormalY * wallAxisY) * operand.DepthFt / 2;
        double openingMinimumAlong = centreAlong - halfAlong;
        double openingMaximumAlong = centreAlong + halfAlong;
        double toleranceFt = IfcDeclaredPrecisionMetres / FeetToMetres;
        bool ownsMinimum =
            Math.Abs(openingMinimumAlong - wallMinimumAlong) <= toleranceFt;
        bool ownsMaximum =
            Math.Abs(openingMaximumAlong - wallMaximumAlong) <= toleranceFt;
        if (ownsMinimum == ownsMaximum)
            return false;
        return minimumTrimmed ? ownsMinimum : ownsMaximum;
    }

    /// <summary>
    /// A gap must exceed two writer lattice steps, covering the independent rounding of both
    /// operands; touching and sub-precision gaps are rejected.
    /// </summary>
    internal static bool HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand)
    {
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt))
            return false;

        const double SerializationGapMetres = 2 * IfcGeometryPrecisionMetres;
        static bool Separated(double leftMinimum, double leftMaximum,
            double rightMinimum, double rightMaximum)
        {
            double gap = Math.Max(
                rightMinimum - leftMaximum, leftMinimum - rightMaximum);
            return gap * FeetToMetres > SerializationGapMetres;
        }
        static bool ConvexPlansAreRobustlySeparated(
            IReadOnlyList<double[]> first, IReadOnlyList<double[]> second)
        {
            static bool IsStrictlyConvex(IReadOnlyList<double[]> polygon)
            {
                if (polygon.Count < 3) return false;
                int direction = 0;
                for (int index = 0; index < polygon.Count; index++)
                {
                    double[] a = polygon[index];
                    double[] b = polygon[(index + 1) % polygon.Count];
                    double[] c = polygon[(index + 2) % polygon.Count];
                    double cross = (b[0] - a[0]) * (c[1] - b[1])
                        - (b[1] - a[1]) * (c[0] - b[0]);
                    if (cross == 0 || !double.IsFinite(cross)) return false;
                    int current = Math.Sign(cross);
                    if (direction == 0) direction = current;
                    else if (current != direction) return false;
                }
                return true;
            }
            if (!IsStrictlyConvex(first) || !IsStrictlyConvex(second))
                return false;
            foreach (var polygon in new[] { first, second })
                for (int index = 0; index < polygon.Count; index++)
                {
                    double[] start = polygon[index];
                    double[] end = polygon[(index + 1) % polygon.Count];
                    double axisX = -(end[1] - start[1]);
                    double axisY = end[0] - start[0];
                    double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
                    if (!(axisLength > 0) || !double.IsFinite(axisLength))
                        return false;
                    axisX /= axisLength;
                    axisY /= axisLength;
                    double firstMinimum = first.Min(point =>
                        point[0] * axisX + point[1] * axisY);
                    double firstMaximum = first.Max(point =>
                        point[0] * axisX + point[1] * axisY);
                    double secondMinimum = second.Min(point =>
                        point[0] * axisX + point[1] * axisY);
                    double secondMaximum = second.Max(point =>
                        point[0] * axisX + point[1] * axisY);
                    if (Separated(firstMinimum, firstMaximum,
                            secondMinimum, secondMaximum))
                        return true;
                }
            return false;
        }

        double wallTopZFt = wallBaseZFt + wallHeightFt;
        if (operand.Boundary is { Faces.Count: > 0 } openingBoundary)
        {
            var openingPoints = openingBoundary.Faces
                .SelectMany(face => face.OuterVertices ?? [])
                .Where(point => point.Length >= 3
                    && double.IsFinite(point[0]) && double.IsFinite(point[1])
                    && double.IsFinite(point[2]))
                .ToList();
            if (openingPoints.Count == 0) return false;
            if (Separated(wallBaseZFt, wallTopZFt,
                    openingPoints.Min(point => point[2]),
                    openingPoints.Max(point => point[2])))
                return true;
            if (TryGetExactVerticalRectangularPrismPlan(
                    openingBoundary, out var boundaryOpeningPlan,
                    out _, out _)
                && ConvexPlansAreRobustlySeparated(
                    wallPlan, boundaryOpeningPlan))
                return true;
            double wallMinimumX = wallPlan.Min(point => point[0]);
            double wallMaximumX = wallPlan.Max(point => point[0]);
            double wallMinimumY = wallPlan.Min(point => point[1]);
            double wallMaximumY = wallPlan.Max(point => point[1]);
            return Separated(wallMinimumX, wallMaximumX,
                       openingPoints.Min(point => point[0]),
                       openingPoints.Max(point => point[0]))
                || Separated(wallMinimumY, wallMaximumY,
                       openingPoints.Min(point => point[1]),
                       openingPoints.Max(point => point[1]));
        }

        if (!(operand.WidthFt > 0) || !(operand.DepthFt > 0)
            || !(operand.HeightFt > 0)
            || !double.IsFinite(operand.CentreXFt)
            || !double.IsFinite(operand.CentreYFt)
            || !double.IsFinite(operand.AxisX)
            || !double.IsFinite(operand.AxisY)
            || !double.IsFinite(operand.BaseZFt)
            || !double.IsFinite(operand.WidthFt)
            || !double.IsFinite(operand.DepthFt)
            || !double.IsFinite(operand.HeightFt))
            return false;
        if (Separated(wallBaseZFt, wallTopZFt,
                operand.BaseZFt, operand.BaseZFt + operand.HeightFt))
            return true;

        double openingAxisLength = Math.Sqrt(
            operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
        if (!(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        double openingAxisX = operand.AxisX / openingAxisLength;
        double openingAxisY = operand.AxisY / openingAxisLength;
        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double halfWidth = operand.WidthFt / 2;
        double halfDepth = operand.DepthFt / 2;
        double[][] openingPlan =
        [
            [operand.CentreXFt - halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                - halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                - halfDepth * openingNormalY],
            [operand.CentreXFt + halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt + halfWidth * openingAxisY
                + halfDepth * openingNormalY],
            [operand.CentreXFt - halfWidth * openingAxisX
                + halfDepth * openingNormalX,
             operand.CentreYFt - halfWidth * openingAxisY
                + halfDepth * openingNormalY],
        ];

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double[][] axes =
        [
            [wallAxisX, wallAxisY], [wallNormalX, wallNormalY],
            [openingAxisX, openingAxisY], [openingNormalX, openingNormalY],
        ];
        foreach (double[] axis in axes)
        {
            double wallMinimum = wallPlan.Min(point =>
                point[0] * axis[0] + point[1] * axis[1]);
            double wallMaximum = wallPlan.Max(point =>
                point[0] * axis[0] + point[1] * axis[1]);
            double openingMinimum = openingPlan.Min(point =>
                point[0] * axis[0] + point[1] * axis[1]);
            double openingMaximum = openingPlan.Max(point =>
                point[0] * axis[0] + point[1] * axis[1]);
            if (Separated(wallMinimum, wallMaximum,
                    openingMinimum, openingMaximum))
                return true;
        }
        return false;
    }

    /// <summary>
    /// The cutter must pass completely through the wall thickness, leave the wall through an end or
    /// its vertical boundary, and keep every cutter plane more than two IFC lattice steps from
    /// every parallel wall plane.
    /// </summary>
    internal static bool HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand) =>
        HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
            wall, bounds, wallBoundary, operand, out _);

    internal static bool HostedOpeningWriterOperandIsRobustBoundaryCutOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand, out string rejectionReason)
        => HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand,
            requireBoundaryCrossing: true,
            allowSerializedHorizontalCapCoincidence: false,
            allowSerializedFullHeightCapCoincidence: false,
            out rejectionReason);

    /// <summary>
    /// The cutter must remain more than two IFC lattice steps inside both wall ends and horizontal
    /// caps while extending more than two steps through both wall side planes.
    /// </summary>
    internal static bool HostedOpeningWriterOperandIsRobustInteriorThroughCutOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand) =>
        operand.Boundary == null
        && HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand,
            requireBoundaryCrossing: false,
            allowSerializedHorizontalCapCoincidence: false,
            allowSerializedFullHeightCapCoincidence: false, out _);

    /// <summary>
    /// The prism must stay more than two IFC lattice steps inside both wall ends and horizontal
    /// caps while extending more than two steps through both wall side planes.
    /// </summary>
    internal static bool
        HostedOpeningWriterBrepOperandIsRobustInteriorThroughCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not { Faces.Count: > 0 }
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out _, out _, out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason))
            return false;
        return HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand,
            requireBoundaryCrossing: false,
            allowSerializedHorizontalCapCoincidence: false,
            allowSerializedFullHeightCapCoincidence: false, out _);
    }

    /// <summary>
    /// The stored shell must exactly reproduce its stepped definition, remain strictly inside both
    /// wall ends, and cross both wall side planes by more than two writer lattice steps.
    /// </summary>
    internal static bool
        HostedOpeningWriterExactSteppedOperandIsRobustThroughCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (!operand.IsExactParameterizedReveal
            || operand.IsExactSerializedDefinition
            || operand.IsExactConcordantFamilyCut
            || operand.IsExactMappedSideShell
            || operand.IsExactSourceWallProfilesMappedBreakpoint
            || operand.IsFamilyCutLoop
            || !operand.ExactDepth
            || !ExactSteppedOpeningBoundaryMatchesDefinition(operand)
            || operand.Boundary is not { Faces.Count: 10 } openingBoundary
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt,
                out double wallHeightFt, out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason))
            return false;

        double axisX = location.EndPoint[0] - location.StartPoint[0];
        double axisY = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        axisX /= axisLength;
        axisY /= axisLength;
        double normalX = -axisY;
        double normalY = axisX;

        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * axisX + point[1] * axisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * axisX + point[1] * axisY);
        double wallMinimumNormal = wallPlan.Min(point =>
            point[0] * normalX + point[1] * normalY);
        double wallMaximumNormal = wallPlan.Max(point =>
            point[0] * normalX + point[1] * normalY);
        double wallMaximumZFt = wallBaseZFt + wallHeightFt;

        var openingPoints = openingBoundary.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3
                && point.Take(3).All(double.IsFinite))
            .ToList();
        if (openingPoints.Count == 0)
            return false;
        double openingMinimumAlong = openingPoints.Min(point =>
            point[0] * axisX + point[1] * axisY);
        double openingMaximumAlong = openingPoints.Max(point =>
            point[0] * axisX + point[1] * axisY);
        double openingMinimumNormal = openingPoints.Min(point =>
            point[0] * normalX + point[1] * normalY);
        double openingMaximumNormal = openingPoints.Max(point =>
            point[0] * normalX + point[1] * normalY);
        double openingMinimumZ = openingPoints.Min(point => point[2]);
        double openingMaximumZ = openingPoints.Max(point => point[2]);
        double serializationGapFt =
            2 * IfcGeometryPrecisionMetres / FeetToMetres;
        bool verticallyInterior =
            openingMinimumZ > wallBaseZFt + serializationGapFt
            && openingMaximumZ < wallMaximumZFt - serializationGapFt;
        bool crossesMinimumCapOnly =
            wallBaseZFt - openingMinimumZ > serializationGapFt
            && openingMaximumZ < wallMaximumZFt - serializationGapFt;
        bool crossesMaximumCapOnly =
            openingMinimumZ > wallBaseZFt + serializationGapFt
            && openingMaximumZ - wallMaximumZFt > serializationGapFt;

        return openingMinimumAlong
                > wallMinimumAlong + serializationGapFt
            && openingMaximumAlong
                < wallMaximumAlong - serializationGapFt
            && (verticallyInterior
                || crossesMinimumCapOnly
                || crossesMaximumCapOnly)
            && wallMinimumNormal
                - openingMinimumNormal > serializationGapFt
            && openingMaximumNormal
                - wallMaximumNormal > serializationGapFt;
    }

    /// <summary>
    /// The prism is reoriented deterministically to the wall axis when its decoded first edge is
    /// the perpendicular rectangle side.
    /// </summary>
    internal static bool
        HostedOpeningWriterBrepOperandIsSerializedEndCoincidentThroughNotchOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not { Faces.Count: > 0 }
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out _, out _, out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason)
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                operand.Boundary, out HostedOpeningGeometry exactOperand))
            return false;

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        double openingAxisLength = Math.Sqrt(
            exactOperand.AxisX * exactOperand.AxisX
            + exactOperand.AxisY * exactOperand.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double openingAxisX = exactOperand.AxisX / openingAxisLength;
        double openingAxisY = exactOperand.AxisY / openingAxisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double cross = openingAxisX * wallAxisY
            - openingAxisY * wallAxisX;
        double dot = openingAxisX * wallAxisX
            + openingAxisY * wallAxisY;
        if (Math.Abs(cross) > 4096 * MachineEpsilon
            && Math.Abs(dot) <= 4096 * MachineEpsilon)
            exactOperand = exactOperand with
            {
                AxisX = -openingAxisY,
                AxisY = openingAxisX,
                WidthFt = exactOperand.DepthFt,
                DepthFt = exactOperand.WidthFt,
            };

        return HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWallCore(
            wall, bounds, wallBoundary, exactOperand,
            requireRobustSideCrossing: true, out _);
    }

    /// <summary>The opposite cap stays more than two writer steps inside the wall.</summary>
    internal static bool
        HostedOpeningWriterBrepOperandIsSerializedHorizontalCapCoincidentThroughCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
            HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not { Faces.Count: > 0 }
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out _, out _, out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason))
            return false;
        return HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand,
            requireBoundaryCrossing: false,
            allowSerializedHorizontalCapCoincidence: true,
            allowSerializedFullHeightCapCoincidence: false, out _);
    }

    /// <summary>
    /// The cutter is robustly inside both wall ends and beyond both side planes, shares exactly one
    /// serialized horizontal wall cap, and crosses the opposite cap by more than two writer lattice
    /// steps.
    /// </summary>
    internal static bool
        HostedOpeningWriterBrepOperandIsSerializedFullHeightInteriorThroughCutOfExactRedundantBoundaryWall(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData wallBoundary, HostedOpeningGeometry operand)
    {
        if (operand.Boundary is not { Faces.Count: > 0 }
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out _, out _, out _, out string wallDefinitionReason)
            || !IsExactRedundantWallDefinitionReason(wallDefinitionReason)
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                operand.Boundary, out _))
            return false;
        return HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand,
            requireBoundaryCrossing: true,
            allowSerializedHorizontalCapCoincidence: false,
            allowSerializedFullHeightCapCoincidence: true, out _);
    }

    /// <summary>
    /// The resulting subtraction is therefore constant through the full wall height and splits the
    /// gross plan into stable spans.
    /// </summary>
    internal static bool
        HostedOpeningWriterOperandIsSerializedFullHeightInteriorThroughCutOfExactWall(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData wallBoundary, HostedOpeningGeometry operand,
            out string rejectionReason)
    {
        if (operand.Boundary is not null || !operand.ExactDepth)
        {
            rejectionReason = "swept-operand";
            return false;
        }
        return HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
            wall, bounds, wallBoundary, operand,
            requireBoundaryCrossing: true,
            allowSerializedHorizontalCapCoincidence: false,
            allowSerializedFullHeightCapCoincidence: true,
            out rejectionReason);
    }

    private static bool HostedOpeningWriterOperandIsRobustThroughCutOfExactWall(
        Element wall, IReadOnlyList<double> bounds, GeometryData wallBoundary,
        HostedOpeningGeometry operand, bool requireBoundaryCrossing,
        bool allowSerializedHorizontalCapCoincidence,
        bool allowSerializedFullHeightCapCoincidence,
        out string rejectionReason)
    {
        rejectionReason = "wall-definition";
        if (wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt))
            return false;
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                wallBoundary, location, widthFt, bounds,
                out var wallPlan, out double wallBaseZFt, out double wallHeightFt,
                out string wallDefinitionRejectionReason))
        {
            rejectionReason = $"wall-definition-{wallDefinitionRejectionReason}";
            return false;
        }

        double wallAxisX = location.EndPoint[0] - location.StartPoint[0];
        double wallAxisY = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallAxisX * wallAxisX + wallAxisY * wallAxisY);
        rejectionReason = "wall-axis";
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength))
            return false;
        wallAxisX /= wallAxisLength;
        wallAxisY /= wallAxisLength;
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;

        double wallMinimumAlong = wallPlan.Min(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMaximumAlong = wallPlan.Max(point =>
            point[0] * wallAxisX + point[1] * wallAxisY);
        double wallMinimumNormal = wallPlan.Min(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumNormal = wallPlan.Max(point =>
            point[0] * wallNormalX + point[1] * wallNormalY);
        double wallMaximumZFt = wallBaseZFt + wallHeightFt;

        double openingMinimumAlong;
        double openingMaximumAlong;
        double openingMinimumNormal;
        double openingMaximumNormal;
        double openingMinimumZ;
        double openingMaximumZ;
        List<double[]> openingPlan;
        if (operand.Boundary is { Faces.Count: > 0 } openingBoundary)
        {
            if (!TryGetExactVerticalRectangularPrismPlan(
                    openingBoundary, out openingPlan,
                    out openingMinimumZ, out double openingHeightFt,
                    out string prismRejectionReason))
            {
                rejectionReason = $"opening-prism-{prismRejectionReason}";
                return false;
            }
            var projected = openingPlan.Select(point => (
                Along: point[0] * wallAxisX + point[1] * wallAxisY,
                Normal: point[0] * wallNormalX + point[1] * wallNormalY)).ToList();
            openingMinimumAlong = projected.Min(value => value.Along);
            openingMaximumAlong = projected.Max(value => value.Along);
            openingMinimumNormal = projected.Min(value => value.Normal);
            openingMaximumNormal = projected.Max(value => value.Normal);
            openingMaximumZ = openingMinimumZ + openingHeightFt;
        }
        else
        {
            rejectionReason = "opening-box";
            if (!operand.ExactDepth
                || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
                || !(operand.HeightFt > 0)
                || !double.IsFinite(operand.CentreXFt)
                || !double.IsFinite(operand.CentreYFt)
                || !double.IsFinite(operand.AxisX)
                || !double.IsFinite(operand.AxisY)
                || !double.IsFinite(operand.BaseZFt)
                || !double.IsFinite(operand.WidthFt)
                || !double.IsFinite(operand.DepthFt)
                || !double.IsFinite(operand.HeightFt))
                return false;
            double openingAxisLength = Math.Sqrt(
                operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY);
            rejectionReason = "opening-axis";
            if (!(openingAxisLength > 0) || !double.IsFinite(openingAxisLength))
                return false;
            double openingAxisX = operand.AxisX / openingAxisLength;
            double openingAxisY = operand.AxisY / openingAxisLength;
            const double MachineEpsilon = 2.2204460492503131e-16;
            rejectionReason = "opening-axis-alignment";
            if (Math.Abs(openingAxisX * wallAxisY
                    - openingAxisY * wallAxisX) > 4096 * MachineEpsilon)
                return false;
            double centreAlong = operand.CentreXFt * wallAxisX
                + operand.CentreYFt * wallAxisY;
            double centreNormal = operand.CentreXFt * wallNormalX
                + operand.CentreYFt * wallNormalY;
            openingMinimumAlong = centreAlong - operand.WidthFt / 2;
            openingMaximumAlong = centreAlong + operand.WidthFt / 2;
            openingMinimumNormal = centreNormal - operand.DepthFt / 2;
            openingMaximumNormal = centreNormal + operand.DepthFt / 2;
            openingMinimumZ = operand.BaseZFt;
            openingMaximumZ = operand.BaseZFt + operand.HeightFt;
            double openingNormalX = -openingAxisY;
            double openingNormalY = openingAxisX;
            double halfWidth = operand.WidthFt / 2;
            double halfDepth = operand.DepthFt / 2;
            openingPlan =
            [
                [operand.CentreXFt - halfWidth * openingAxisX
                    - halfDepth * openingNormalX,
                 operand.CentreYFt - halfWidth * openingAxisY
                    - halfDepth * openingNormalY],
                [operand.CentreXFt + halfWidth * openingAxisX
                    - halfDepth * openingNormalX,
                 operand.CentreYFt + halfWidth * openingAxisY
                    - halfDepth * openingNormalY],
                [operand.CentreXFt + halfWidth * openingAxisX
                    + halfDepth * openingNormalX,
                 operand.CentreYFt + halfWidth * openingAxisY
                    + halfDepth * openingNormalY],
                [operand.CentreXFt - halfWidth * openingAxisX
                    + halfDepth * openingNormalX,
                 operand.CentreYFt - halfWidth * openingAxisY
                    + halfDepth * openingNormalY],
            ];
        }

        double serializationGapFt =
            2 * IfcGeometryPrecisionMetres / FeetToMetres;
        bool hasSerializedHorizontalCapCoincidence = false;
        if (allowSerializedHorizontalCapCoincidence)
        {
            rejectionReason = "serialized-horizontal-cap";
            if (operand.Boundary is not { Faces.Count: > 0 } serializedBoundary
                || !TryGetSerializedSweptVerticalIntervalMetres(
                    wallBaseZFt, wallHeightFt,
                    out decimal serializedWallMinimumZ,
                    out decimal serializedWallMaximumZ))
                return false;
            var openingKeys = serializedBoundary.Faces
                .SelectMany(face => face.OuterVertices ?? [])
                .Select(IfcPrecisionKeyFeet).ToList();
            if (openingKeys.Count == 0
                || !TryGetSerializedIfcReal(
                    openingKeys.Min(point => point.Z)
                        * IfcGeometryPrecisionMetres,
                    out decimal serializedOpeningMinimumZ)
                || !TryGetSerializedIfcReal(
                    openingKeys.Max(point => point.Z)
                        * IfcGeometryPrecisionMetres,
                    out decimal serializedOpeningMaximumZ))
                return false;
            decimal verticalGap = (decimal)(2 * IfcGeometryPrecisionMetres);
            bool sharesMinimumCap =
                serializedOpeningMinimumZ == serializedWallMinimumZ;
            bool sharesMaximumCap =
                serializedOpeningMaximumZ == serializedWallMaximumZ;
            hasSerializedHorizontalCapCoincidence =
                sharesMinimumCap ^ sharesMaximumCap;
            if (!hasSerializedHorizontalCapCoincidence
                || (sharesMinimumCap
                    && !(serializedWallMaximumZ
                        - serializedOpeningMaximumZ > verticalGap))
                || (sharesMaximumCap
                    && !(serializedOpeningMinimumZ
                        - serializedWallMinimumZ > verticalGap)))
                return false;
        }
        bool hasSerializedFullHeightCapCoincidence = false;
        if (allowSerializedFullHeightCapCoincidence)
        {
            rejectionReason = "serialized-full-height-cap";
            if (!TryGetSerializedSweptVerticalIntervalMetres(
                    wallBaseZFt, wallHeightFt,
                    out decimal serializedWallMinimumZ,
                    out decimal serializedWallMaximumZ))
                return false;
            decimal serializedOpeningMinimumZ;
            decimal serializedOpeningMaximumZ;
            if (operand.Boundary is { Faces.Count: > 0 } serializedBoundary)
            {
                var openingKeys = serializedBoundary.Faces
                    .SelectMany(face => face.OuterVertices ?? [])
                    .Select(IfcPrecisionKeyFeet).ToList();
                if (openingKeys.Count == 0
                    || !TryGetSerializedIfcReal(
                        openingKeys.Min(point => point.Z)
                            * IfcGeometryPrecisionMetres,
                        out serializedOpeningMinimumZ)
                    || !TryGetSerializedIfcReal(
                        openingKeys.Max(point => point.Z)
                            * IfcGeometryPrecisionMetres,
                        out serializedOpeningMaximumZ))
                    return false;
            }
            else if (!TryGetSerializedSweptVerticalIntervalMetres(
                         operand.BaseZFt, operand.HeightFt,
                         out serializedOpeningMinimumZ,
                         out serializedOpeningMaximumZ))
            {
                return false;
            }
            long wallMinimumZBin = IfcPrecisionBinMetres(
                (double)serializedWallMinimumZ);
            long wallMaximumZBin = IfcPrecisionBinMetres(
                (double)serializedWallMaximumZ);
            long openingMinimumZBin = IfcPrecisionBinMetres(
                (double)serializedOpeningMinimumZ);
            long openingMaximumZBin = IfcPrecisionBinMetres(
                (double)serializedOpeningMaximumZ);
            bool sharesMinimumCap =
                openingMinimumZBin == wallMinimumZBin;
            bool sharesMaximumCap =
                openingMaximumZBin == wallMaximumZBin;
            bool crossesMinimumCap =
                wallMinimumZBin - openingMinimumZBin > 2;
            bool crossesMaximumCap =
                openingMaximumZBin - wallMaximumZBin > 2;
            hasSerializedFullHeightCapCoincidence =
                (sharesMinimumCap && crossesMaximumCap)
                ^ (sharesMaximumCap && crossesMinimumCap);
            if (!hasSerializedFullHeightCapCoincidence)
                return false;
        }
        static bool RobustlyOverlaps(double firstMinimum, double firstMaximum,
            double secondMinimum, double secondMaximum, double gap) =>
            Math.Min(firstMaximum, secondMaximum)
                - Math.Max(firstMinimum, secondMinimum) > gap;
        static bool RobustlyAwayFromBothBoundaries(
            double openingMinimum, double openingMaximum,
            double wallMinimum, double wallMaximum, double gap) =>
            Math.Abs(openingMinimum - wallMinimum) > gap
            && Math.Abs(openingMinimum - wallMaximum) > gap
            && Math.Abs(openingMaximum - wallMinimum) > gap
            && Math.Abs(openingMaximum - wallMaximum) > gap;
        static bool IsStrictlyConvex(IReadOnlyList<double[]> polygon, double gap)
        {
            if (polygon.Count < 3) return false;
            int direction = 0;
            for (int index = 0; index < polygon.Count; index++)
            {
                double[] first = polygon[index];
                double[] second = polygon[(index + 1) % polygon.Count];
                double[] third = polygon[(index + 2) % polygon.Count];
                double cross = (second[0] - first[0]) * (third[1] - second[1])
                    - (second[1] - first[1]) * (third[0] - second[0]);
                if (Math.Abs(cross) <= gap * gap) return false;
                int current = Math.Sign(cross);
                if (direction == 0) direction = current;
                else if (current != direction) return false;
            }
            return true;
        }
        static double ConvexIntersectionArea(IReadOnlyList<double[]> subject,
            IReadOnlyList<double[]> clip, double coordinateRoundoff)
        {
            if (subject.Count < 3 || clip.Count < 3) return 0;
            static double Cross(IReadOnlyList<double> first,
                IReadOnlyList<double> second, IReadOnlyList<double> point) =>
                (second[0] - first[0]) * (point[1] - first[1])
                - (second[1] - first[1]) * (point[0] - first[0]);
            static double SignedArea(IReadOnlyList<double[]> polygon)
            {
                double twiceArea = 0;
                for (int index = 0; index < polygon.Count; index++)
                {
                    double[] first = polygon[index];
                    double[] second = polygon[(index + 1) % polygon.Count];
                    twiceArea += first[0] * second[1] - second[0] * first[1];
                }
                return twiceArea / 2;
            }

            bool clipCounterClockwise = SignedArea(clip) > 0;
            var output = subject.Select(point =>
                new[] { point[0], point[1] }).ToList();
            for (int edge = 0; edge < clip.Count && output.Count > 0; edge++)
            {
                double[] edgeStart = clip[edge];
                double[] edgeEnd = clip[(edge + 1) % clip.Count];
                var input = output;
                output = [];
                double[] previous = input[^1];
                double previousCross = Cross(edgeStart, edgeEnd, previous);
                bool previousInside = clipCounterClockwise
                    ? previousCross >= -coordinateRoundoff
                    : previousCross <= coordinateRoundoff;
                foreach (double[] current in input)
                {
                    double currentCross = Cross(edgeStart, edgeEnd, current);
                    bool currentInside = clipCounterClockwise
                        ? currentCross >= -coordinateRoundoff
                        : currentCross <= coordinateRoundoff;
                    if (currentInside != previousInside)
                    {
                        double denominator = previousCross - currentCross;
                        if (Math.Abs(denominator) > coordinateRoundoff)
                        {
                            double fraction = previousCross / denominator;
                            output.Add(
                            [
                                previous[0] + fraction * (current[0] - previous[0]),
                                previous[1] + fraction * (current[1] - previous[1]),
                            ]);
                        }
                    }
                    if (currentInside) output.Add(current);
                    previous = current;
                    previousCross = currentCross;
                    previousInside = currentInside;
                }
            }
            return output.Count >= 3 ? Math.Abs(SignedArea(output)) : 0;
        }

        bool crossesWallBoundary =
            openingMinimumAlong < wallMinimumAlong - serializationGapFt
            || openingMaximumAlong > wallMaximumAlong + serializationGapFt
            || openingMinimumZ < wallBaseZFt - serializationGapFt
            || openingMaximumZ > wallMaximumZFt + serializationGapFt;
        rejectionReason = requireBoundaryCrossing
            ? "boundary-crossing" : "interior-boundary-crossing";
        if (crossesWallBoundary != requireBoundaryCrossing) return false;
        rejectionReason = "wall-convexity";
        if (!IsStrictlyConvex(wallPlan, serializationGapFt)) return false;
        rejectionReason = "opening-convexity";
        if (!IsStrictlyConvex(openingPlan, serializationGapFt)) return false;
        rejectionReason = "plan-intersection";
        if (!(ConvexIntersectionArea(wallPlan, openingPlan,
                serializationGapFt) > serializationGapFt * serializationGapFt))
            return false;
        rejectionReason = "thickness-minimum";
        if (!(openingMinimumNormal < wallMinimumNormal - serializationGapFt))
            return false;
        rejectionReason = "thickness-maximum";
        if (!(openingMaximumNormal > wallMaximumNormal + serializationGapFt))
            return false;
        rejectionReason = "along-overlap";
        if (!RobustlyOverlaps(openingMinimumAlong, openingMaximumAlong,
                wallMinimumAlong, wallMaximumAlong, serializationGapFt))
            return false;
        rejectionReason = "vertical-overlap";
        if (!RobustlyOverlaps(openingMinimumZ, openingMaximumZ,
                wallBaseZFt, wallMaximumZFt, serializationGapFt))
            return false;
        rejectionReason = "along-clearance";
        if (!RobustlyAwayFromBothBoundaries(
                openingMinimumAlong, openingMaximumAlong,
                wallMinimumAlong, wallMaximumAlong, serializationGapFt))
            return false;
        rejectionReason = "normal-clearance";
        if (!RobustlyAwayFromBothBoundaries(
                openingMinimumNormal, openingMaximumNormal,
                wallMinimumNormal, wallMaximumNormal, serializationGapFt))
            return false;
        rejectionReason = "vertical-clearance";
        if (!hasSerializedHorizontalCapCoincidence
            && !hasSerializedFullHeightCapCoincidence
            && !RobustlyAwayFromBothBoundaries(
                openingMinimumZ, openingMaximumZ,
                wallBaseZFt, wallMaximumZFt, serializationGapFt))
            return false;
        rejectionReason = "exact";
        return true;
    }

    /// <summary>
    /// Resolves the exact rectangular operand written by <see cref="CreateHostedOpeningAbsolute"/>.
    /// </summary>
    internal static bool TryResolveHostedOpeningBox(Element hostedElem, double[] bbox,
        Element wallElem, IReadOnlyDictionary<int, Element> elemById,
        HostedOpeningGeometry commonOpening, out HostedOpeningGeometry opening)
    {
        opening = default;
        double[] wallBbox = wallElem.BoundingBox
            ?? wallElem.Geometry?.BoundingBox ?? Array.Empty<double>();
        if (bbox.Length < 6 || wallBbox.Length < 6) return false;

        double[] associationBox = BuildHostedOpeningAssociationBox(hostedElem, bbox);
        bool hasSerializedInsertion = TryGetSerializedInsertionOrigin(
            hostedElem, out double insertionXFt, out double insertionYFt);
        bool hasAuthoredOpening = TryBuildHostedOpeningBoundary(
            wallElem, associationBox, out var authoredOpening);
        double authoredWidthFt = 0;
        double authoredBaseZFt = 0;
        double authoredHeightFt = 0;
        bool hasAuthoredSpan = hasAuthoredOpening
            && TryGetAuthoredHostedOpeningSpan(wallElem, authoredOpening,
                out _, out authoredWidthFt,
                out authoredBaseZFt, out authoredHeightFt);

        double ux, uy, centreXFt, centreYFt;
        if (wallElem.Location is { ArcRadius: null } wallLocation)
        {
            double vx = wallLocation.EndPoint[0] - wallLocation.StartPoint[0];
            double vy = wallLocation.EndPoint[1] - wallLocation.StartPoint[1];
            double length = Math.Sqrt(vx * vx + vy * vy);
            if (!(length >= 1e-6) || !double.IsFinite(length)) return false;
            ux = vx / length;
            uy = vy / length;
            double px = hasSerializedInsertion
                ? insertionXFt : (bbox[0] + bbox[3]) / 2;
            double py = hasSerializedInsertion
                ? insertionYFt : (bbox[1] + bbox[4]) / 2;
            if (hasSerializedInsertion)
            {
                // Preserve the authored cutter frame for secondary/crossing hosts.
                centreXFt = px;
                centreYFt = py;
            }
            else
            {
                double wallCx = (wallBbox[0] + wallBbox[3]) / 2;
                double wallCy = (wallBbox[1] + wallBbox[4]) / 2;
                double along = (px - wallCx) * ux + (py - wallCy) * uy;
                centreXFt = wallCx + along * ux;
                centreYFt = wallCy + along * uy;
            }
        }
        else
        {
            double dx = wallBbox[3] - wallBbox[0];
            double dy = wallBbox[4] - wallBbox[1];
            ux = dx >= dy ? 1 : 0;
            uy = dx >= dy ? 0 : 1;
            centreXFt = (bbox[0] + bbox[3]) / 2;
            centreYFt = (bbox[1] + bbox[4]) / 2;
        }

        bool hasCommonOpening = commonOpening.WidthFt > 0
            && commonOpening.DepthFt > 0 && commonOpening.HeightFt > 0;
        if (hasCommonOpening)
        {
            ux = commonOpening.AxisX;
            uy = commonOpening.AxisY;
            centreXFt = commonOpening.CentreXFt;
            centreYFt = commonOpening.CentreYFt;
        }

        Element? hostedType = LinkedFamilyType(hostedElem, elemById);
        Element? wallType = LinkedFamilyType(wallElem, elemById);
        double wallThicknessFt = GetSerializedPositiveDimension(
            wallElem, wallType, -1001000);
        double bboxThicknessFt = Math.Min(
            Math.Abs(wallBbox[3] - wallBbox[0]),
            Math.Abs(wallBbox[4] - wallBbox[1]));
        if (bboxThicknessFt is > 0.05 and <= 3
            && (wallThicknessFt <= 0 || wallThicknessFt > 3
                || bboxThicknessFt < wallThicknessFt * 0.8))
            wallThicknessFt = bboxThicknessFt;
        if (wallThicknessFt <= 0 || wallThicknessFt > 3)
            wallThicknessFt = 0.66;

        var fallbackDimensions = ResolveHostedOpeningDimensions(
            hostedElem, hostedType, bbox, ux, uy);
        double widthFt = hasCommonOpening
            ? commonOpening.WidthFt : hasAuthoredSpan
                ? authoredWidthFt : fallbackDimensions.WidthFt;
        if (!hasCommonOpening && TryResolveSerializedClearOpeningWidth(
                hostedElem, hostedType, widthFt, wallThicknessFt,
                out double clearWidthFt))
            widthFt = clearWidthFt;
        double heightFt = hasCommonOpening
            ? commonOpening.HeightFt : hasAuthoredSpan
                ? authoredHeightFt : fallbackDimensions.HeightFt;
        if (!(widthFt > 0.03) || !(heightFt > 0.03)
            || !double.IsFinite(widthFt) || !double.IsFinite(heightFt))
            return false;

        double authoredNormalDepthFt = 0;
        bool hasAuthoredNormalDepth = hasAuthoredSpan
            && TryGetAuthoredHostedOpeningNormalDepth(
                wallElem, authoredOpening, out authoredNormalDepthFt);
        const double MachineEpsilon = 2.2204460492503131e-16;
        double depthScale = Math.Max(1.0,
            Math.Max(wallThicknessFt,
                hasAuthoredNormalDepth ? authoredNormalDepthFt : 0));
        double depthRoundoff = 1024 * MachineEpsilon * depthScale;
        const double BooleanClearanceM = 1.0e-4;
        double depthFt = hasCommonOpening
            ? commonOpening.DepthFt
                + (commonOpening.ExactDepth ? 0
                    : 2 * BooleanClearanceM / FeetToMetres)
            : hasAuthoredNormalDepth
                && authoredNormalDepthFt > wallThicknessFt + depthRoundoff
                ? authoredNormalDepthFt
                : wallThicknessFt + 2 * BooleanClearanceM / FeetToMetres;
        double baseZFt = hasCommonOpening
            ? commonOpening.BaseZFt : hasAuthoredSpan
                ? authoredBaseZFt : bbox[2];
        if (!(depthFt > 0) || !double.IsFinite(depthFt)
            || !double.IsFinite(baseZFt)
            || !double.IsFinite(centreXFt) || !double.IsFinite(centreYFt)
            || !double.IsFinite(ux) || !double.IsFinite(uy))
            return false;

        opening = new HostedOpeningGeometry(
            centreXFt, centreYFt, ux, uy, widthFt, depthFt,
            baseZFt, heightFt, ExactDepth: true,
            IsExactSerializedDefinition:
                hasCommonOpening
                && commonOpening.IsExactSerializedDefinition,
            IsExactMappedSideShell:
                hasCommonOpening
                && commonOpening.IsExactMappedSideShell,
            IsExactAuthoredMultiHostEnvelope:
                hasCommonOpening
                && commonOpening.IsExactAuthoredMultiHostEnvelope,
            IsExactFamilyCutLoopWriterBox:
                hasCommonOpening && commonOpening.IsFamilyCutLoop);
        if (hasAuthoredOpening
            && authoredOpening.Faces.Count == 6
            && TryGetExactVerticalRectangularPrismSweptOpening(
                authoredOpening, out var exactAuthoredReveal)
            && (RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                    exactAuthoredReveal, opening)
                || opening.IsExactFamilyCutLoopWriterBox
                && ExactAuthoredRectangularRevealIsCoveredByFamilyCutWriterBox(
                    wallElem, authoredOpening, opening)))
            opening = opening with
            {
                IsExactAuthoredRevealWriterBox = true,
            };
        return true;
    }

    private static bool
        ExactAuthoredRectangularRevealIsCoveredByFamilyCutWriterBox(
            Element wallElem, GeometryData authoredReveal,
            HostedOpeningGeometry writerBox)
    {
        if (!writerBox.IsExactFamilyCutLoopWriterBox
            || wallElem.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                authoredReveal, out _))
            return false;

        double wallDx = location.EndPoint[0] - location.StartPoint[0];
        double wallDy = location.EndPoint[1] - location.StartPoint[1];
        double wallAxisLength = Math.Sqrt(
            wallDx * wallDx + wallDy * wallDy);
        double writerAxisLength = Math.Sqrt(
            writerBox.AxisX * writerBox.AxisX
            + writerBox.AxisY * writerBox.AxisY);
        if (!(wallAxisLength > 0) || !double.IsFinite(wallAxisLength)
            || !(writerAxisLength > 0) || !double.IsFinite(writerAxisLength))
            return false;
        double wallAxisX = wallDx / wallAxisLength;
        double wallAxisY = wallDy / wallAxisLength;
        double wallNormalX = -wallAxisY;
        double wallNormalY = wallAxisX;
        double writerAxisX = writerBox.AxisX / writerAxisLength;
        double writerAxisY = writerBox.AxisY / writerAxisLength;
        double writerNormalX = -writerAxisY;
        double writerNormalY = writerAxisX;
        double halfWidth = writerBox.WidthFt / 2;
        double halfDepth = writerBox.DepthFt / 2;
        var writerCorners = new List<double[]>(8);
        foreach (double z in new[]
                 {
                     writerBox.BaseZFt,
                     writerBox.BaseZFt + writerBox.HeightFt,
                 })
            foreach (double along in new[] { -halfWidth, halfWidth })
                foreach (double normal in new[] { -halfDepth, halfDepth })
                    writerCorners.Add(
                    [
                        writerBox.CentreXFt + along * writerAxisX
                            + normal * writerNormalX,
                        writerBox.CentreYFt + along * writerAxisY
                            + normal * writerNormalY,
                        z,
                    ]);
        var revealPoints = authoredReveal.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3
                && point.Take(3).All(double.IsFinite))
            .ToList();
        if (revealPoints.Count < 8)
            return false;

        long Key(double feet) =>
            IfcPrecisionBinMetres(feet * FeetToMetres);
        long[] Coordinates(
            IEnumerable<double[]> points, double axisX, double axisY) =>
            points.Select(point => Key(
                    point[0] * axisX + point[1] * axisY))
                .Distinct().Order().ToArray();
        long[] Elevations(IEnumerable<double[]> points) =>
            points.Select(point => Key(point[2]))
                .Distinct().Order().ToArray();

        long[] revealAlong = Coordinates(
            revealPoints, wallAxisX, wallAxisY);
        long[] revealNormal = Coordinates(
            revealPoints, wallNormalX, wallNormalY);
        long[] revealZ = Elevations(revealPoints);
        long[] writerAlong = Coordinates(
            writerCorners, wallAxisX, wallAxisY);
        long[] writerNormal = Coordinates(
            writerCorners, wallNormalX, wallNormalY);
        long[] writerZ = Elevations(writerCorners);
        return revealAlong.Length == 2
            && revealNormal.Length == 2
            && revealZ.Length == 2
            && writerAlong.Length == 2
            && writerNormal.Length == 2
            && writerZ.Length == 2
            && revealAlong.SequenceEqual(writerAlong)
            && revealZ.SequenceEqual(writerZ)
            && writerNormal[0] <= revealNormal[0]
            && writerNormal[1] >= revealNormal[1];
    }

    /// <summary>Create a hosted void directly in the building/model frame.</summary>
    private void CreateHostedOpeningAbsolute(StepWriter w, Element hostedElem, int hostedIfcId,
        double[] bbox, Element wallElem, int wallEntityId, int parentPlacementId,
        int ownerHistId, int subCtxId, List<int> storeyContents,
        IReadOnlyDictionary<int, Element> elemById, bool createFillRelationship,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        HostedOpeningGeometry commonOpening = default,
        bool writeExactBrepPrismAsSweptSolid = false,
        bool alignExactBrepPrismSweptSolidToDefinition = false)
    {
        double[] wallBbox = wallElem.BoundingBox ?? wallElem.Geometry?.BoundingBox ?? Array.Empty<double>();
        if (wallBbox.Length < 6) return;
        if (CurrentProfile && hostedIfcId <= 0 && !createFillRelationship
            && TryBuildOwnUnfilledPrimaryFamilyCutout(hostedElem, wallElem, out var ownUnfilled))
        {
            CreateHostedOpeningSweptBox(w, hostedElem, hostedIfcId, wallElem, wallEntityId,
                parentPlacementId, ownerHistId, subCtxId, storeyContents, elemById,
                createFillRelationship, propertySingleValueIds, ownUnfilled);
            return;
        }
        Element? propertySetReferenceElement =
            ResolveHostedOpeningPropertySetReferenceElement(
                hostedElem, hostedIfcId, wallElem, createFillRelationship);

        if (commonOpening.OwnPrimaryFamilyHostId > 0)
        {
            if (commonOpening.OwnPrimaryFamilyHostId == wallElem.Id)
                CreateHostedOpeningSweptBox(w, hostedElem, hostedIfcId, wallElem, wallEntityId,
                    parentPlacementId, ownerHistId, subCtxId, storeyContents, elemById,
                    createFillRelationship, propertySingleValueIds, commonOpening);
            return;
        }

        // Keeping the two non-convex eight-vertex faces axis-aligned makes them exactly planar
        // after STEP quantization; absolute rotated coordinates can otherwise move alternate
        // vertices onto adjacent writer-lattice planes.
        if (commonOpening.SteppedProfile is { } steppedProfile)
        {
            double axisLength = Math.Sqrt(
                commonOpening.AxisX * commonOpening.AxisX
                + commonOpening.AxisY * commonOpening.AxisY);
            if (!(axisLength > 0) || !double.IsFinite(axisLength))
                return;
            double axisX = commonOpening.AxisX / axisLength;
            double axisY = commonOpening.AxisY / axisLength;
            double normalX = -axisY, normalY = axisX;
            double centreNormal =
                commonOpening.CentreXFt * normalX
                + commonOpening.CentreYFt * normalY;
            var localOpening = new HostedOpeningGeometry(
                0, 0, 1, 0, commonOpening.WidthFt, commonOpening.DepthFt,
                0, commonOpening.HeightFt, ExactDepth: true);
            if (!TryBuildExactSteppedOpeningBoundary(
                    localOpening, steppedProfile.InnerWidthFt,
                    steppedProfile.InnerHeightFt,
                    steppedProfile.BreakpointNormalFt - centreNormal,
                    steppedProfile.InnerAtMinimum, out var localBoundary))
                return;
            int steppedShapeId = CreateFacetedBrep(
                w, localBoundary, subCtxId,
                preserveValidatedPlanarFaces: true);
            if (steppedShapeId <= 0) return;

            int steppedOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
                D(commonOpening.CentreXFt * FeetToMetres),
                D(commonOpening.CentreYFt * FeetToMetres),
                D(commonOpening.BaseZFt * FeetToMetres)));
            int steppedRefDirectionId = w.Add("IFCDIRECTION",
                StepWriter.List(D(axisX), D(axisY), "0."));
            int steppedAxisId = w.Add("IFCAXIS2PLACEMENT3D",
                $"{R(steppedOriginId)},$,{R(steppedRefDirectionId)}");
            int steppedPlacementId = w.Add("IFCLOCALPLACEMENT",
                $"{R(parentPlacementId)},{R(steppedAxisId)}");
            string steppedName = hostedElem.FamilyName ?? hostedElem.Name
                ?? $"Element {hostedElem.Id}";
            int steppedOpeningId = CreateOpeningElement(w,
                IfcGuid.FromName($"hosted-opening:{hostedElem.Id}:{wallElem.Id}"), ownerHistId,
                steppedName, hostedElem.Id, propertySetReferenceElement,
                elemById, steppedPlacementId, steppedShapeId, propertySingleValueIds);
            w.Add("IFCRELVOIDSELEMENT",
                $"{S(IfcGuid.FromName($"hosted-void:{hostedElem.Id}:{wallElem.Id}"))},{R(ownerHistId)},$,$,{R(wallEntityId)},{R(steppedOpeningId)}");
            if (createFillRelationship)
                w.Add("IFCRELFILLSELEMENT",
                    $"{S(IfcGuid.FromName($"hosted-fill:{hostedElem.Id}"))},{R(ownerHistId)},$,$,{R(steppedOpeningId)},{R(hostedIfcId)}");
            storeyContents.Add(steppedOpeningId);
            return;
        }

        if (commonOpening.IsExactParameterizedRectangularCut
            && ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                commonOpening))
        {
            CreateHostedOpeningSweptBox(
                w, hostedElem, hostedIfcId, wallElem, wallEntityId,
                parentPlacementId, ownerHistId, subCtxId, storeyContents,
                elemById, createFillRelationship, propertySingleValueIds, commonOpening);
            return;
        }

        // FamilySymbol.m_complexCutGeoms is the actual authored Boolean operand.
        if (commonOpening.Boundary is { Faces.Count: > 0 } familyCutBoundary)
        {
            HostedOpeningGeometry sweptOpening = default;
            bool hasExactSweptOpening = (writeExactBrepPrismAsSweptSolid || CurrentProfile)
                && (alignExactBrepPrismSweptSolidToDefinition
                    || commonOpening.IsExactRecoveredClosedFamilyCutProfile
                    ? TryGetExactVerticalRectangularPrismSweptOpeningAlignedToDefinition(
                        familyCutBoundary, commonOpening, out sweptOpening)
                    : TryGetExactVerticalRectangularPrismSweptOpening(
                        familyCutBoundary, out sweptOpening));
            if (hasExactSweptOpening && !writeExactBrepPrismAsSweptSolid && CurrentProfile)
                hasExactSweptOpening = RectangularOpeningHasWallExtrusionAxisCurrent(sweptOpening, wallElem.Location);
            if (hasExactSweptOpening)
            {
                CreateHostedOpeningSweptBox(
                    w, hostedElem, hostedIfcId, wallElem, wallEntityId,
                    parentPlacementId, ownerHistId, subCtxId, storeyContents,
                    elemById, createFillRelationship, propertySingleValueIds, sweptOpening);
                return;
            }
            int familyCutShapeId = CreateFacetedBrep(w, familyCutBoundary, subCtxId);
            if (familyCutShapeId > 0)
            {
                int originId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
                int axisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(originId)},$,$");
                int placementId = w.Add("IFCLOCALPLACEMENT", $"{R(parentPlacementId)},{R(axisId)}");
                string name = hostedElem.FamilyName ?? hostedElem.Name
                    ?? $"Element {hostedElem.Id}";
                int openingId = CreateOpeningElement(w,
                    IfcGuid.FromName($"hosted-opening:{hostedElem.Id}:{wallElem.Id}"),
                    ownerHistId, name, hostedElem.Id, propertySetReferenceElement,
                    elemById, placementId, familyCutShapeId, propertySingleValueIds);
                w.Add("IFCRELVOIDSELEMENT",
                    $"{S(IfcGuid.FromName($"hosted-void:{hostedElem.Id}:{wallElem.Id}"))},{R(ownerHistId)},$,$,{R(wallEntityId)},{R(openingId)}");
                if (createFillRelationship)
                    w.Add("IFCRELFILLSELEMENT",
                        $"{S(IfcGuid.FromName($"hosted-fill:{hostedElem.Id}"))},{R(ownerHistId)},$,$,{R(openingId)},{R(hostedIfcId)}");
                storeyContents.Add(openingId);
                return;
            }
        }

        // Revit serializes the bottom and head reveal faces in the host wall GRep.
        double[] associationBox = BuildHostedOpeningAssociationBox(hostedElem, bbox);
        bool hasAuthoredOpening = TryBuildHostedOpeningBoundary(
            wallElem, associationBox, out var authoredOpening);
        bool hasAuthoredSpan = hasAuthoredOpening
            && TryGetAuthoredHostedOpeningSpan(wallElem, authoredOpening,
                out _, out _, out _, out _);
        if (hasAuthoredOpening && !hasAuthoredSpan)
        {
            int authoredShapeId = CreateFacetedBrep(w, authoredOpening, subCtxId);
            if (authoredShapeId > 0)
            {
                int openOriginId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
                int openAxisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(openOriginId)},$,$");
                int authoredPlacementId = w.Add("IFCLOCALPLACEMENT",
                    $"{R(parentPlacementId)},{R(openAxisId)}");
                string authoredName = hostedElem.FamilyName ?? hostedElem.Name
                    ?? $"Element {hostedElem.Id}";
                int authoredOpeningId = CreateOpeningElement(w,
                    IfcGuid.FromName($"hosted-opening:{hostedElem.Id}:{wallElem.Id}"),
                    ownerHistId, authoredName, hostedElem.Id,
                    propertySetReferenceElement, elemById,
                    authoredPlacementId, authoredShapeId,
                    propertySingleValueIds);
                w.Add("IFCRELVOIDSELEMENT",
                    $"{S(IfcGuid.FromName($"hosted-void:{hostedElem.Id}:{wallElem.Id}"))},{R(ownerHistId)},$,$,{R(wallEntityId)},{R(authoredOpeningId)}");
                if (createFillRelationship)
                    w.Add("IFCRELFILLSELEMENT",
                        $"{S(IfcGuid.FromName($"hosted-fill:{hostedElem.Id}"))},{R(ownerHistId)},$,$,{R(authoredOpeningId)},{R(hostedIfcId)}");
                storeyContents.Add(authoredOpeningId);
                return;
            }
        }

        if (!TryResolveHostedOpeningBox(hostedElem, bbox, wallElem, elemById,
                commonOpening, out var resolvedOpening))
            return;
        double ux = resolvedOpening.AxisX;
        double uy = resolvedOpening.AxisY;
        double centreXFt = resolvedOpening.CentreXFt;
        double centreYFt = resolvedOpening.CentreYFt;
        double openWidthFt = resolvedOpening.WidthFt;
        double openHeightFt = resolvedOpening.HeightFt;
        if (Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") is { } openingDebugIds
            && openingDebugIds.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id) && id == wallElem.Id))
            DiagnosticSink.WriteLine($"IFCOPENINGSPAN host={wallElem.Id} insert={hostedElem.Id} resolved={openWidthFt:G17}x{openHeightFt:G17} position=({centreXFt:G17},{centreYFt:G17},{resolvedOpening.BaseZFt:G17})");
        CreateHostedOpeningSweptBox(
            w, hostedElem, hostedIfcId, wallElem, wallEntityId,
            parentPlacementId, ownerHistId, subCtxId, storeyContents,
            elemById, createFillRelationship, propertySingleValueIds, resolvedOpening);
    }

    private int CreateHostedOpeningSweptBox(
        StepWriter w, Element hostedElem, int hostedIfcId, Element wallElem,
        int wallEntityId, int parentPlacementId, int ownerHistId, int subCtxId,
        List<int> storeyContents, IReadOnlyDictionary<int, Element> elemById,
        bool createFillRelationship,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        HostedOpeningGeometry opening, int? exactReferenceValueId = null)
    {
        double wallThick = opening.DepthFt * FeetToMetres;
        if (Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") is { } depthDebugIds
            && depthDebugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wallElem.Id))
            DiagnosticSink.WriteLine($"IFCOPENINGDEPTH host={wallElem.Id} "
                + $"insert={hostedElem.Id} selectedM={wallThick:G17}");
        double openWidth = opening.WidthFt * FeetToMetres;
        double openHeight = opening.HeightFt * FeetToMetres;
        double z0 = opening.BaseZFt * FeetToMetres;

        bool ownCutPair = TryCreateOwnCutPairOpeningBodyCurrent(w, hostedElem, wallElem, opening,
            subCtxId, out int openShapeId, out var ownQuantities, out var brepFrame);
        // A Brep opening sits at the minimum corner of its solid with the orientation of the wall
        //.
        int openPtId = w.Add("IFCCARTESIANPOINT", StepWriter.List(
            D(brepFrame is { } corner ? corner.OriginFt[0] * FeetToMetres : ownCutPair ? 0 : opening.CentreXFt * FeetToMetres),
            D(brepFrame is { } corner1 ? corner1.OriginFt[1] * FeetToMetres : ownCutPair ? 0 : opening.CentreYFt * FeetToMetres),
            D(brepFrame is { } corner2 ? corner2.OriginFt[2] * FeetToMetres : ownCutPair ? 0 : z0)));
        int openRefDirId = w.Add("IFCDIRECTION", StepWriter.List(
            D(brepFrame is { } axisFrame ? axisFrame.AxisX : ownCutPair ? 1 : opening.AxisX),
            D(brepFrame is { } axisFrame1 ? axisFrame1.AxisY : ownCutPair ? 0 : opening.AxisY), "0."));
        int openAxId = w.Add("IFCAXIS2PLACEMENT3D",
            $"{R(openPtId)},$,{R(openRefDirId)}");
        int openPlacementId = w.Add("IFCLOCALPLACEMENT",
            $"{R(parentPlacementId)},{R(openAxId)}");

        if (!ownCutPair && !TryCreateOwnFamilyCutoutBodyCurrent(w, hostedElem, wallElem, elemById,
                opening, subCtxId, out openShapeId))
        {
            int profOriginId = w.Add("IFCCARTESIANPOINT",
                StepWriter.List("0.", "0."));
            int profPlacementId = w.Add("IFCAXIS2PLACEMENT2D",
                $"{R(profOriginId)},$");
            int profileId = w.Add("IFCRECTANGLEPROFILEDEF",
                $".AREA.,$,{R(profPlacementId)},{D(openWidth)},{D(wallThick)}");
            int extOriginId = w.Add("IFCCARTESIANPOINT",
                StepWriter.List("0.", "0.", "0."));
            int extPositionId = w.Add("IFCAXIS2PLACEMENT3D",
                $"{R(extOriginId)},$,$");
            int extDirId = w.Add("IFCDIRECTION",
                StepWriter.List("0.", "0.", "1."));
            int solidId = w.Add("IFCEXTRUDEDAREASOLID",
                $"{R(profileId)},{R(extPositionId)},{R(extDirId)},{D(openHeight)}");
            int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
                $"{R(subCtxId)},{S("Body")},{S("SweptSolid")},"
                + $"{StepWriter.List(R(solidId))}");
            openShapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
                $"$,$,{StepWriter.List(R(shapeRepId))}");
        }

        string elemName = hostedElem.FamilyName ?? hostedElem.Name
            ?? $"Element {hostedElem.Id}";
        Element? propertySetReferenceElement =
            ResolveHostedOpeningPropertySetReferenceElement(
                hostedElem, hostedIfcId, wallElem, createFillRelationship);
        int openElemId = CreateOpeningElement(w,
            IfcGuid.FromName($"hosted-opening:{hostedElem.Id}:{wallElem.Id}"), ownerHistId,
            elemName, hostedElem.Id, propertySetReferenceElement,
            elemById, openPlacementId, openShapeId, propertySingleValueIds,
            exactReferenceValueId: exactReferenceValueId,
            useExactReferenceValueId: exactReferenceValueId.HasValue);
        if (ownCutPair) _ownCutPairOpeningQuantitiesCurrent[openElemId] = ownQuantities!;
        w.Add("IFCRELVOIDSELEMENT",
            $"{S(IfcGuid.FromName($"hosted-void:{hostedElem.Id}:{wallElem.Id}"))},"
            + $"{R(ownerHistId)},$,$,{R(wallEntityId)},{R(openElemId)}");
        if (createFillRelationship)
            w.Add("IFCRELFILLSELEMENT",
                $"{S(IfcGuid.FromName($"hosted-fill:{hostedElem.Id}"))},"
                + $"{R(ownerHistId)},$,$,{R(openElemId)},{R(hostedIfcId)}");
        storeyContents.Add(openElemId);
        // The opening rule: a cut shorter than its host's width across the wall is a
        // "Recess".
        if (CurrentProfile && TryGetSerializedWallWidthFeet(wallElem, out double hostWidthFt)
            && opening.DepthFt < hostWidthFt - RecessToleranceFt)
            _recessOpeningEntityIds.Add(openElemId);
        return openElemId;
    }

    /// <summary>
    /// Opening entities whose cut is shallower than the host wall (ObjectType "Recess" in the
    /// current profile).
    /// </summary>
    private readonly HashSet<int> _recessOpeningEntityIds = new();
    private const double RecessToleranceFt = 1e-5;

    /// <summary>Reconstructs the exact FamilySymbol complex-cut BRep in model coordinates.</summary>
    internal static bool TryBuildFamilyCutHostedOpeningGeometry(Element hostedElement,
        Element? hostedType, IReadOnlyList<Element> hostWalls,
        out HostedOpeningGeometry opening)
    {
        opening = default;
        if (hostedType?.FamilyCutGeometry is not { Faces.Count: >= 4 } localCut
            || localCut.BrepSolids is not { Count: > 0 }
            || hostWalls.Count == 0)
            return false;
        if (!TryGetSerializedInstanceTransform(hostedElement, out var transform))
            return false;

        static double Dot(double[] first, double[] second) =>
            first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
        static double[]? Unit(double[] vector)
        {
            double length = Math.Sqrt(Dot(vector, vector));
            return length > 0 && double.IsFinite(length)
                ? [vector[0] / length, vector[1] / length, vector[2] / length]
                : null;
        }
        static double[] TransformVector(InstanceTransform value, double[] vector) =>
        [
            vector[0] * value.BasisX[0] + vector[1] * value.BasisY[0]
                + vector[2] * value.BasisZ[0],
            vector[0] * value.BasisX[1] + vector[1] * value.BasisY[1]
                + vector[2] * value.BasisZ[1],
            vector[0] * value.BasisX[2] + vector[1] * value.BasisY[2]
                + vector[2] * value.BasisZ[2],
        ];
        static double[] TransformPoint(InstanceTransform value, double[] point) =>
        [
            value.Origin[0] + point[0] * value.BasisX[0]
                + point[1] * value.BasisY[0] + point[2] * value.BasisZ[0],
            value.Origin[1] + point[0] * value.BasisX[1]
                + point[1] * value.BasisY[1] + point[2] * value.BasisZ[1],
            value.Origin[2] + point[0] * value.BasisX[2]
                + point[1] * value.BasisY[2] + point[2] * value.BasisZ[2],
        ];

        double[]? closureOrigin = hostedType.FamilyCutClosurePlaneOrigin;
        double[]? closureNormalSource = hostedType.FamilyCutClosurePlaneNormal;
        bool hasClosurePlane = closureOrigin is { Length: 3 }
            && closureNormalSource is { Length: 3 };
        double[] localNormal;
        double closureCoordinate;
        if (hasClosurePlane)
        {
            double[]? normalizedClosureNormal = Unit((double[])closureNormalSource!.Clone());
            if (normalizedClosureNormal == null
                || closureOrigin!.Any(value => !double.IsFinite(value)))
                return false;
            localNormal = normalizedClosureNormal;
            closureCoordinate = Dot(closureOrigin!, localNormal);
            if (!double.IsFinite(closureCoordinate) || closureCoordinate == 0) return false;
            if (closureCoordinate < 0)
            {
                for (int coordinate = 0; coordinate < 3; coordinate++)
                    localNormal[coordinate] = -localNormal[coordinate];
                closureCoordinate = -closureCoordinate;
            }
        }
        else
        {
            // A complete FamilySymbol cutter needs no dummy-host reconstruction.
            localNormal = [0, 1, 0];
            closureCoordinate = 0;
        }
        double dummyHalfDepth = closureCoordinate;
        double[]? worldNormal = Unit(TransformVector(transform, localNormal));
        if (worldNormal == null) return false;

        if (!TryGetClosedFamilyCutFaces(localCut, localNormal, closureCoordinate,
                out var localBoundaryFaces, out var localBoundarySolids,
                out bool recoveredClosedFlagProfile))
            return false;
        if (!hasClosurePlane && localBoundarySolids.Any(solid => !solid.IsClosed
                || !IsExactFacetedShell(localBoundaryFaces, solid.FaceIndices)))
            return false;

        var localPoints = localBoundaryFaces
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat((face.InnerVertices ?? []).SelectMany(loop => loop)))
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0]) && double.IsFinite(point[1])
                && double.IsFinite(point[2])).ToList();
        if (localPoints.Count < 8) return false;
        double scale = Math.Max(1.0, localPoints.SelectMany(point => point).Select(Math.Abs).Max());
        double roundoff = 2048 * 2.2204460492503131e-16 * scale;

        double hostMinimum = double.PositiveInfinity;
        double hostMaximum = double.NegativeInfinity;
        // m_hostId is the exact Revit host.
        if (hasClosurePlane)
        {
            double localMinimum = localPoints.Min(point => Dot(point, localNormal));
            double localMaximum = localPoints.Max(point => Dot(point, localNormal));
            if (localMinimum > -dummyHalfDepth + roundoff
                || localMaximum < dummyHalfDepth - roundoff)
                return false;

            int primaryHostId = hostedElement.SerializedHostId is > 0
                ? hostedElement.SerializedHostId.Value
                : hostedElement.HostId is > 0 ? hostedElement.HostId.Value : -1;
            if (primaryHostId <= 0) return false;
            Element? primaryHost = hostWalls.FirstOrDefault(wall => wall.Id == primaryHostId);
            if (primaryHost?.Location is not { CurveType: "Line", ArcRadius: null } location
                || !TryGetSerializedWallWidthFeet(primaryHost, out double primaryWidthFt))
                return false;
            double lineX = location.EndPoint[0] - location.StartPoint[0];
            double lineY = location.EndPoint[1] - location.StartPoint[1];
            double lineLength = Math.Sqrt(lineX * lineX + lineY * lineY);
            if (!(lineLength > 0) || !double.IsFinite(lineLength)
                || Math.Abs(lineX / lineLength * worldNormal[0]
                    + lineY / lineLength * worldNormal[1]) > roundoff)
                return false;
            double hostCentre = Dot(transform.Origin, worldNormal);
            hostMinimum = hostCentre - primaryWidthFt / 2;
            hostMaximum = hostCentre + primaryWidthFt / 2;
            if (!(hostMaximum > hostMinimum) || !double.IsFinite(hostMinimum)
                || !double.IsFinite(hostMaximum))
                return false;
        }

        var pointCache = new Dictionary<(long X, long Y, long Z), double[]>();
        double[] MapPoint(double[] localPoint)
        {
            var key = (BitConverter.DoubleToInt64Bits(localPoint[0]),
                BitConverter.DoubleToInt64Bits(localPoint[1]),
                BitConverter.DoubleToInt64Bits(localPoint[2]));
            if (pointCache.TryGetValue(key, out var existing)) return existing;

            if (!hasClosurePlane)
            {
                double[] transformed = TransformPoint(transform, localPoint);
                pointCache[key] = transformed;
                return transformed;
            }

            double localCoordinate = Dot(localPoint, localNormal);
            double targetCoordinate;
            if (localCoordinate >= dummyHalfDepth - roundoff)
                targetCoordinate = hostMaximum + localCoordinate - dummyHalfDepth;
            else if (localCoordinate <= -dummyHalfDepth + roundoff)
                targetCoordinate = hostMinimum + localCoordinate + dummyHalfDepth;
            else
                targetCoordinate = hostMinimum
                    + (localCoordinate + dummyHalfDepth) / (2 * dummyHalfDepth)
                    * (hostMaximum - hostMinimum);

            double[] worldPoint = TransformPoint(transform, localPoint);
            double correction = targetCoordinate - Dot(worldPoint, worldNormal);
            var mapped = new[]
            {
                worldPoint[0] + correction * worldNormal[0],
                worldPoint[1] + correction * worldNormal[1],
                worldPoint[2] + correction * worldNormal[2],
            };
            pointCache[key] = mapped;
            return mapped;
        }

        static double[] FaceNormal(IReadOnlyList<double[]> ring)
        {
            var normal = new double[3];
            for (int index = 0; index < ring.Count; index++)
            {
                var current = ring[index];
                var next = ring[(index + 1) % ring.Count];
                normal[0] += (current[1] - next[1]) * (current[2] + next[2]);
                normal[1] += (current[2] - next[2]) * (current[0] + next[0]);
                normal[2] += (current[0] - next[0]) * (current[1] + next[1]);
            }
            double length = Math.Sqrt(Dot(normal, normal));
            return length > 0
                ? [normal[0] / length, normal[1] / length, normal[2] / length]
                : [0, 0, 0];
        }

        var boundary = new GeometryData { Faces = new List<GeoFace>() };
        foreach (GeoFace face in localBoundaryFaces)
        {
            if (face.OuterVertices is not { Count: >= 3 } outer) return false;
            var mappedOuter = outer.Select(MapPoint).ToList();
            boundary.Faces.Add(new GeoFace
            {
                Origin = mappedOuter[0],
                Normal = FaceNormal(mappedOuter),
                OuterVertices = mappedOuter,
                InnerVertices = face.InnerVertices?.Select(loop =>
                    loop.Select(MapPoint).ToList()).ToList(),
                AlternativeOuterVertices = face.AlternativeOuterVertices?.Select(MapPoint).ToList(),
            });
        }
        boundary.BrepSolids = localBoundarySolids.Select(solid => new GeoBrepSolid
        {
            FaceIndices = new List<int>(solid.FaceIndices),
            IsClosed = solid.IsClosed,
        }).ToList();
        var mappedPoints = boundary.Faces.SelectMany(face => face.OuterVertices ?? []).ToList();
        if (mappedPoints.Count < 8) return false;
        boundary.Vertices = pointCache.Values.ToList();
        boundary.BoundingBox =
        [
            mappedPoints.Min(point => point[0]), mappedPoints.Min(point => point[1]),
            mappedPoints.Min(point => point[2]), mappedPoints.Max(point => point[0]),
            mappedPoints.Max(point => point[1]), mappedPoints.Max(point => point[2]),
        ];

        double[]? widthDirection = Unit(TransformVector(transform, [1, 0, 0]));
        if (widthDirection == null) return false;
        double width = mappedPoints.Max(point => Dot(point, widthDirection))
            - mappedPoints.Min(point => Dot(point, widthDirection));
        double depth = mappedPoints.Max(point => Dot(point, worldNormal))
            - mappedPoints.Min(point => Dot(point, worldNormal));
        double baseZ = mappedPoints.Min(point => point[2]);
        double height = mappedPoints.Max(point => point[2]) - baseZ;
        if (!(width > 0) || !(depth > 0) || !(height > 0)) return false;
        opening = new HostedOpeningGeometry(
            (boundary.BoundingBox[0] + boundary.BoundingBox[3]) / 2,
            (boundary.BoundingBox[1] + boundary.BoundingBox[4]) / 2,
            widthDirection[0], widthDirection[1], width, depth, baseZ, height,
            ExactDepth: true, Boundary: boundary,
            IsExactRecoveredClosedFamilyCutProfile:
                recoveredClosedFlagProfile);
        return true;
    }

    /// <summary>Builds the exact rectangular profile stored by InsertableObj.m_pCutLoops.</summary>
    internal static bool TryBuildFamilyCutLoopHostedOpeningGeometry(Element hostedElement,
        Element? hostedType, out HostedOpeningGeometry opening)
    {
        opening = default;
        if (hostedType?.FamilyCutLoops is not { Count: 1 } cutLoops
            || cutLoops[0] is not { Vertices.Count: 4, Direction.Length: >= 3 } loop
            || !TryGetSerializedInstanceTransform(hostedElement, out var transform))
            return false;

        return TryBuildRectangularFamilyCutLoop(cutLoops[0], transform, 10.0, out opening);
    }

    private static bool TryBuildRectangularFamilyCutLoop(FamilyCutLoopData loop,
        InstanceTransform transform, double depthFeet, out HostedOpeningGeometry opening)
    {
        opening = default;

        static double Dot(IReadOnlyList<double> first, IReadOnlyList<double> second) =>
            first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
        static double[]? Unit(double[] vector)
        {
            double length = Math.Sqrt(Dot(vector, vector));
            return length > 0 && double.IsFinite(length)
                ? [vector[0] / length, vector[1] / length, vector[2] / length]
                : null;
        }
        static double[] TransformVector(InstanceTransform value,
            IReadOnlyList<double> vector) =>
        [
            vector[0] * value.BasisX[0] + vector[1] * value.BasisY[0]
                + vector[2] * value.BasisZ[0],
            vector[0] * value.BasisX[1] + vector[1] * value.BasisY[1]
                + vector[2] * value.BasisZ[1],
            vector[0] * value.BasisX[2] + vector[1] * value.BasisY[2]
                + vector[2] * value.BasisZ[2],
        ];
        static double[] TransformPoint(InstanceTransform value,
            IReadOnlyList<double> point) =>
        [
            value.Origin[0] + point[0] * value.BasisX[0]
                + point[1] * value.BasisY[0] + point[2] * value.BasisZ[0],
            value.Origin[1] + point[0] * value.BasisX[1]
                + point[1] * value.BasisY[1] + point[2] * value.BasisZ[1],
            value.Origin[2] + point[0] * value.BasisX[2]
                + point[1] * value.BasisY[2] + point[2] * value.BasisZ[2],
        ];

        if (loop.Vertices.Any(vertex => vertex.Length < 3
                || vertex.Any(value => !double.IsFinite(value)))
            || loop.Direction.Any(value => !double.IsFinite(value)))
            return false;
        double[]? normal = Unit(TransformVector(transform, loop.Direction));
        double[]? widthDirection = Unit(TransformVector(transform, [1, 0, 0]));
        double[]? vertical = Unit(TransformVector(transform, [0, 0, 1]));
        if (normal == null || widthDirection == null || vertical == null) return false;

        var points = loop.Vertices.Select(vertex => TransformPoint(transform, vertex)).ToList();
        if (points.SelectMany(point => point).Any(value => !double.IsFinite(value))) return false;
        double scale = Math.Max(1.0, points.SelectMany(point => point).Select(Math.Abs).Max());
        double roundoff = 4096 * 2.2204460492503131e-16 * scale;
        if (Math.Abs(Dot(normal, widthDirection)) > roundoff
            || Math.Abs(normal[2]) > roundoff
            || Math.Abs(widthDirection[2]) > roundoff
            || Math.Abs(Math.Abs(vertical[2]) - 1) > roundoff)
            return false;

        var along = points.Select(point => Dot(point, widthDirection)).ToList();
        var normalCoordinates = points.Select(point => Dot(point, normal)).ToList();
        double minimumAlong = along.Min(), maximumAlong = along.Max();
        double minimumZ = points.Min(point => point[2]), maximumZ = points.Max(point => point[2]);
        double planeCoordinate = normalCoordinates.Average();
        double width = maximumAlong - minimumAlong;
        double height = maximumZ - minimumZ;
        if (!(width > roundoff) || !(height > roundoff)
            || normalCoordinates.Any(value => Math.Abs(value - planeCoordinate) > roundoff)
            || along.Any(value => Math.Min(Math.Abs(value - minimumAlong),
                    Math.Abs(value - maximumAlong)) > roundoff)
            || points.Any(point => Math.Min(Math.Abs(point[2] - minimumZ),
                    Math.Abs(point[2] - maximumZ)) > roundoff))
            return false;

        int widthEdges = 0, verticalEdges = 0;
        for (int index = 0; index < points.Count; index++)
        {
            double[] first = points[index];
            double[] second = points[(index + 1) % points.Count];
            var edge = new[]
            {
                second[0] - first[0], second[1] - first[1], second[2] - first[2],
            };
            double widthComponent = Math.Abs(Dot(edge, widthDirection));
            double normalComponent = Math.Abs(Dot(edge, normal));
            double verticalComponent = Math.Abs(edge[2]);
            if (normalComponent > roundoff) return false;
            if (widthComponent > roundoff && verticalComponent <= roundoff) widthEdges++;
            else if (verticalComponent > roundoff && widthComponent <= roundoff) verticalEdges++;
            else return false;
        }
        if (widthEdges != 2 || verticalEdges != 2) return false;

        opening = new HostedOpeningGeometry(
            points.Average(point => point[0]), points.Average(point => point[1]),
            widthDirection[0], widthDirection[1], width, depthFeet,
            minimumZ, height, ExactDepth: true, IsFamilyCutLoop: true);
        return true;
    }

    /// <summary>Plan overlap uses the separating-axis theorem over both exact convex plans.</summary>
    internal static bool ExactDirectedOpeningHasPositiveAuthoredHostIntersection(
        HostedOpeningGeometry authored, Element host)
    {
        if (!authored.ExactDepth
            || authored.Boundary != null
            || authored.SteppedProfile != null
            || !(authored.WidthFt > 0)
            || !(authored.DepthFt > 0)
            || !(authored.HeightFt > 0)
            || !double.IsFinite(authored.CentreXFt)
            || !double.IsFinite(authored.CentreYFt)
            || !double.IsFinite(authored.AxisX)
            || !double.IsFinite(authored.AxisY)
            || !double.IsFinite(authored.BaseZFt))
            return false;

        double axisLength = Math.Sqrt(
            authored.AxisX * authored.AxisX
            + authored.AxisY * authored.AxisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        double axisX = authored.AxisX / axisLength;
        double axisY = authored.AxisY / axisLength;
        double normalX = -axisY;
        double normalY = axisX;
        double centreAlong =
            authored.CentreXFt * axisX + authored.CentreYFt * axisY;
        double centreNormal =
            authored.CentreXFt * normalX + authored.CentreYFt * normalY;
        double minimumAlong = centreAlong - authored.WidthFt / 2;
        double maximumAlong = centreAlong + authored.WidthFt / 2;
        double minimumNormal = centreNormal - authored.DepthFt / 2;
        double maximumNormal = centreNormal + authored.DepthFt / 2;
        var cutterPlan = new List<double[]>
        {
            new[] { minimumAlong * axisX + minimumNormal * normalX,
                minimumAlong * axisY + minimumNormal * normalY },
            new[] { maximumAlong * axisX + minimumNormal * normalX,
                maximumAlong * axisY + minimumNormal * normalY },
            new[] { maximumAlong * axisX + maximumNormal * normalX,
                maximumAlong * axisY + maximumNormal * normalY },
            new[] { minimumAlong * axisX + maximumNormal * normalX,
                minimumAlong * axisY + maximumNormal * normalY },
        };

        double hostWidthFt =
            GetSerializedPositiveDimension(host, null, -1001000);
        if (!(hostWidthFt > 0))
            return false;
        List<double[]> hostPlan = [];
        IReadOnlyList<double> hostBounds =
            host.BoundingBox ?? host.Geometry?.BoundingBox ?? [];
        bool hasExactRebuiltPlan =
            host.Location is { CurveType: "Line", ArcRadius: null } location
            && hostBounds.Count >= 6
            && TryBuildStraightWallBoundary(
                host, out var rebuiltBoundary)
            && TryGetExactVerticalRectangularWallPlan(
                rebuiltBoundary, location, hostWidthFt, hostBounds,
                out hostPlan);
        if (!hasExactRebuiltPlan
            && !TryGetAuthoredStraightWallPlan(
                host, hostWidthFt, out hostPlan))
            return false;
        var hostPoints = host.Geometry?.Faces?
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat(face.AlternativeOuterVertices ?? [])
                .Concat((face.InnerVertices ?? [])
                    .SelectMany(ring => ring)))
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0])
                && double.IsFinite(point[1])
                && double.IsFinite(point[2]))
            .ToList() ?? [];
        if (hostPoints.Count < 4)
            return false;

        long Key(double feet) =>
            IfcPrecisionBinMetres(feet * FeetToMetres);
        long overlapMinimumZ = Math.Max(
            Key(authored.BaseZFt),
            Key(hostPoints.Min(point => point[2])));
        long overlapMaximumZ = Math.Min(
            Key(authored.BaseZFt + authored.HeightFt),
            Key(hostPoints.Max(point => point[2])));
        if (overlapMaximumZ <= overlapMinimumZ)
            return false;

        foreach (var polygon in new IReadOnlyList<double[]>[]
                 {
                     cutterPlan, hostPlan,
                 })
        {
            for (int index = 0; index < polygon.Count; index++)
            {
                var first = polygon[index];
                var second = polygon[(index + 1) % polygon.Count];
                double edgeX = second[0] - first[0];
                double edgeY = second[1] - first[1];
                double edgeLength = Math.Sqrt(
                    edgeX * edgeX + edgeY * edgeY);
                if (!(edgeLength > 0) || !double.IsFinite(edgeLength))
                    return false;
                double separatingX = -edgeY / edgeLength;
                double separatingY = edgeX / edgeLength;
                long cutterMinimum = cutterPlan.Min(point =>
                    Key(point[0] * separatingX
                        + point[1] * separatingY));
                long cutterMaximum = cutterPlan.Max(point =>
                    Key(point[0] * separatingX
                        + point[1] * separatingY));
                long hostMinimum = hostPlan.Min(point =>
                    Key(point[0] * separatingX
                        + point[1] * separatingY));
                long hostMaximum = hostPlan.Max(point =>
                    Key(point[0] * separatingX
                        + point[1] * separatingY));
                if (Math.Min(cutterMaximum, hostMaximum)
                    <= Math.Max(cutterMinimum, hostMinimum))
                    return false;
            }
        }
        return true;
    }

    /// <summary>Associates a directed FamilySymbol cut-loop prism with exact decoded host geometry.</summary>
    internal static bool TryIntersectFamilyCutLoopWithHost(
        HostedOpeningGeometry authored, Element host,
        out HostedOpeningGeometry intersection)
    {
        intersection = default;
        return authored.IsFamilyCutLoop
            && TryIntersectDirectedHostedOpeningWithHost(
                authored, host, out intersection);
    }

    /// <summary>
    /// Intersects an exact directed rectangular writer operand with a host using the same
    /// source-plan/reveal test as a FamilyCutLoop, without changing the operand.
    /// </summary>
    internal static bool TryIntersectExactDirectedHostedOpeningWithHost(
        HostedOpeningGeometry authored, Element host,
        out HostedOpeningGeometry intersection)
    {
        intersection = default;
        return authored.ExactDepth
            && !authored.IsFamilyCutLoop
            && authored.SteppedProfile == null
            && TryIntersectDirectedHostedOpeningWithHost(
                authored, host, out intersection);
    }

    private static bool TryIntersectDirectedHostedOpeningWithHost(
        HostedOpeningGeometry authored, Element host,
        out HostedOpeningGeometry intersection)
    {
        intersection = default;
        if (authored.Boundary != null
            || !(authored.WidthFt > 0) || !(authored.DepthFt > 0)
            || !(authored.HeightFt > 0)
            || !double.IsFinite(authored.CentreXFt)
            || !double.IsFinite(authored.CentreYFt)
            || !double.IsFinite(authored.AxisX)
            || !double.IsFinite(authored.AxisY))
            return false;

        double axisLength = Math.Sqrt(
            authored.AxisX * authored.AxisX + authored.AxisY * authored.AxisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength)) return false;
        double axisX = authored.AxisX / axisLength;
        double axisY = authored.AxisY / axisLength;
        double normalX = -axisY;
        double normalY = axisX;

        double centreAlong = authored.CentreXFt * axisX
            + authored.CentreYFt * axisY;
        double centreNormal = authored.CentreXFt * normalX
            + authored.CentreYFt * normalY;
        double cutterMinAlong = centreAlong - authored.WidthFt / 2;
        double cutterMaxAlong = centreAlong + authored.WidthFt / 2;
        double cutterMinNormal = centreNormal - authored.DepthFt / 2;
        double cutterMaxNormal = centreNormal + authored.DepthFt / 2;
        double cutterMinZ = authored.BaseZFt;
        double cutterMaxZ = authored.BaseZFt + authored.HeightFt;

        var cutterPlan = new List<double[]>
        {
            new[] { cutterMinAlong * axisX + cutterMinNormal * normalX,
                cutterMinAlong * axisY + cutterMinNormal * normalY },
            new[] { cutterMaxAlong * axisX + cutterMinNormal * normalX,
                cutterMaxAlong * axisY + cutterMinNormal * normalY },
            new[] { cutterMaxAlong * axisX + cutterMaxNormal * normalX,
                cutterMaxAlong * axisY + cutterMaxNormal * normalY },
            new[] { cutterMinAlong * axisX + cutterMaxNormal * normalX,
                cutterMinAlong * axisY + cutterMaxNormal * normalY },
        };
        double[] cutterBounds =
        [
            cutterPlan.Min(point => point[0]), cutterPlan.Min(point => point[1]), cutterMinZ,
            cutterPlan.Max(point => point[0]), cutterPlan.Max(point => point[1]), cutterMaxZ,
        ];
        bool hasReveal =
            TryBuildHostedOpeningBoundary(host, cutterBounds, out var boundary)
            && boundary.Faces is { Count: >= 2 }
            && boundary.Faces[0].OuterVertices is { Count: >= 4 };
        var revealPoints = (hasReveal ? boundary.Faces : [])
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0]) && double.IsFinite(point[1])
                && double.IsFinite(point[2]))
            .ToList();
        hasReveal &= revealPoints.Count >= 8;
        var hostPoints = host.Geometry?.Faces?
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat(face.AlternativeOuterVertices ?? [])
                .Concat((face.InnerVertices ?? []).SelectMany(ring => ring)))
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0]) && double.IsFinite(point[1])
                && double.IsFinite(point[2]))
            .ToList() ?? [];
        if (!hasReveal && hostPoints.Count < 4) return false;

        double scale = Math.Max(1.0, revealPoints.Concat(hostPoints)
            .SelectMany(point => point)
            .Append(authored.CentreXFt).Append(authored.CentreYFt)
            .Select(Math.Abs).Max());
        double roundoff = 4096 * 2.2204460492503131e-16 * scale;
        bool revealIntersection = hasReveal
            && ConvexIntersectionArea(
                boundary.Faces[0].OuterVertices!
                    .Select(point => new[] { point[0], point[1] }).ToList(),
                cutterPlan, roundoff) > roundoff * roundoff;

        bool planIntersection = false;
        if (hostPoints.Count >= 4)
        {
            double hostWidthFt = GetSerializedPositiveDimension(host, null, -1001000);
            if (hostWidthFt > 0
                && TryGetAuthoredStraightWallPlan(host, hostWidthFt, out var hostPlan))
            {
                double hostMinAlong = hostPoints.Min(point =>
                    point[0] * axisX + point[1] * axisY);
                double hostMaxAlong = hostPoints.Max(point =>
                    point[0] * axisX + point[1] * axisY);
                double hostMinNormal = hostPoints.Min(point =>
                    point[0] * normalX + point[1] * normalY);
                double hostMaxNormal = hostPoints.Max(point =>
                    point[0] * normalX + point[1] * normalY);
                double hostMinZ = hostPoints.Min(point => point[2]);
                double hostMaxZ = hostPoints.Max(point => point[2]);
                planIntersection = Math.Min(cutterMaxAlong, hostMaxAlong)
                        - Math.Max(cutterMinAlong, hostMinAlong) > roundoff
                    && Math.Min(cutterMaxNormal, hostMaxNormal)
                        - Math.Max(cutterMinNormal, hostMinNormal) > roundoff
                    && Math.Min(cutterMaxZ, hostMaxZ)
                        - Math.Max(cutterMinZ, hostMinZ) > roundoff
                    && ConvexIntersectionArea(cutterPlan, hostPlan, roundoff)
                        > roundoff * roundoff;
            }
        }
        if (!revealIntersection && !planIntersection)
            return false;

        intersection = authored;
        if (host.Location is not { CurveType: "Line", ArcRadius: null } location)
            return true;
        double hostDx = location.EndPoint[0] - location.StartPoint[0];
        double hostDy = location.EndPoint[1] - location.StartPoint[1];
        double hostAxisLength = Math.Sqrt(hostDx * hostDx + hostDy * hostDy);
        if (!(hostAxisLength > 0) || !double.IsFinite(hostAxisLength)) return true;
        double hostAxisX = hostDx / hostAxisLength;
        double hostAxisY = hostDy / hostAxisLength;
        double directionRoundoff = 4096 * 2.2204460492503131e-16;
        if (Math.Abs(hostAxisX * axisY - hostAxisY * axisX) > directionRoundoff)
            return true;

        var depthPoints = revealIntersection ? revealPoints : hostPoints;
        var normalCoordinates = depthPoints
            .Select(point => point[0] * normalX + point[1] * normalY).ToList();
        double overlapNormalMin = Math.Max(cutterMinNormal, normalCoordinates.Min());
        double overlapNormalMax = Math.Min(cutterMaxNormal, normalCoordinates.Max());
        double overlapNormal = overlapNormalMax - overlapNormalMin;
        if (!(overlapNormal > roundoff)) return false;
        double clippedNormal = (overlapNormalMin + overlapNormalMax) / 2;
        intersection = authored with
        {
            CentreXFt = centreAlong * axisX + clippedNormal * normalX,
            CentreYFt = centreAlong * axisY + clippedNormal * normalY,
            AxisX = axisX,
            AxisY = axisY,
            DepthFt = overlapNormal,
        };
        return true;

        static double ConvexIntersectionArea(IReadOnlyList<double[]> subject,
            IReadOnlyList<double[]> clip, double coordinateRoundoff)
        {
            if (subject.Count < 3 || clip.Count < 3) return 0;
            static double Cross(IReadOnlyList<double> first,
                IReadOnlyList<double> second, IReadOnlyList<double> point) =>
                (second[0] - first[0]) * (point[1] - first[1])
                - (second[1] - first[1]) * (point[0] - first[0]);
            static double SignedArea(IReadOnlyList<double[]> polygon)
            {
                double twiceArea = 0;
                for (int index = 0; index < polygon.Count; index++)
                {
                    var first = polygon[index];
                    var second = polygon[(index + 1) % polygon.Count];
                    twiceArea += first[0] * second[1] - second[0] * first[1];
                }
                return twiceArea / 2;
            }

            double clipOrientation = Math.Sign(SignedArea(clip));
            if (clipOrientation == 0) return 0;
            var output = subject.Select(point => (double[])point.Clone()).ToList();
            double crossRoundoff = coordinateRoundoff * Math.Max(1.0,
                clip.SelectMany(point => point).Select(Math.Abs).Max());
            for (int edgeIndex = 0; edgeIndex < clip.Count; edgeIndex++)
            {
                var edgeStart = clip[edgeIndex];
                var edgeEnd = clip[(edgeIndex + 1) % clip.Count];
                var input = output;
                output = [];
                if (input.Count == 0) break;
                var previous = input[^1];
                double previousCross = clipOrientation
                    * Cross(edgeStart, edgeEnd, previous);
                bool previousInside = previousCross >= -crossRoundoff;
                foreach (var current in input)
                {
                    double currentCross = clipOrientation
                        * Cross(edgeStart, edgeEnd, current);
                    bool currentInside = currentCross >= -crossRoundoff;
                    if (currentInside != previousInside)
                    {
                        double denominator = previousCross - currentCross;
                        if (denominator == 0) return 0;
                        double fraction = previousCross / denominator;
                        output.Add(
                        [
                            previous[0] + fraction * (current[0] - previous[0]),
                            previous[1] + fraction * (current[1] - previous[1]),
                        ]);
                    }
                    if (currentInside) output.Add((double[])current.Clone());
                    previous = current;
                    previousCross = currentCross;
                    previousInside = currentInside;
                }
            }
            return Math.Abs(SignedArea(output));
        }
    }

    /// <summary>
    /// Returns a topologically closed family cutter. FamilySymbol.m_complexCutGeoms may omit the
    /// side faces inside its dummy host: Revit stores the exact closure profile, both normal end
    /// caps, and only the exterior side faces.
    /// </summary>
    internal static bool TryGetClosedFamilyCutFaces(GeometryData localCut,
        double[] localNormal, double closureCoordinate,
        out List<GeoFace> closedFaces, out List<GeoBrepSolid> closedSolids,
        out bool recoveredClosedFlagProfile)
    {
        closedFaces = [];
        closedSolids = [];
        recoveredClosedFlagProfile = false;
        if (localNormal.Length < 3 || localCut.Faces.Count < 4
            || localCut.BrepSolids is not { Count: > 0 })
            return false;

        var sourceSolids = localCut.BrepSolids
            .Where(solid => solid.FaceIndices.Count >= 4)
            .ToList();
        if (sourceSolids.Count == 0) return false;

        // Some GBReps are already complete, but their per-face Orient flags can leave adjacent
        // polygon rings pointing in the same direction.
        if (sourceSolids.All(solid => solid.IsClosed))
        {
            bool orientedEverySolid = true;
            foreach (var solid in sourceSolids)
            {
                if (!TryOrientExactFacetedShell(
                        localCut.Faces, solid.FaceIndices, out var orientedFaces))
                {
                    orientedEverySolid = false;
                    break;
                }
                int firstFace = closedFaces.Count;
                closedFaces.AddRange(orientedFaces);
                closedSolids.Add(new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(firstFace, orientedFaces.Count).ToList(),
                    IsClosed = true,
                });
            }
            if (orientedEverySolid)
                return closedSolids.Count > 0;

            // Some FamilySymbol complex-cut records carry IsClosed=true even though their edge
            // incidence still omits the dummy-host interval.
            closedFaces = [];
            closedSolids = [];
            recoveredClosedFlagProfile = true;
        }

        // A single omitted dummy-host interval is reconstructed independently.
        if (sourceSolids.Count != 1) return false;
        var sourceIndices = sourceSolids[0].FaceIndices.Distinct()
            .Where(index => (uint)index < localCut.Faces.Count).Order().ToList();
        if (sourceIndices.Count < 4) return false;
        var sourceFaces = sourceIndices.Select(index => localCut.Faces[index]).ToList();
        if (sourceFaces.Any(face => face.OuterVertices is not { Count: >= 3 }
                || face.InnerVertices is { Count: > 0 }))
            return false;

        static double Dot(IReadOnlyList<double> first, IReadOnlyList<double> second) =>
            first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
        double normalLength = Math.Sqrt(Dot(localNormal, localNormal));
        if (!(normalLength > 0) || !double.IsFinite(normalLength)) return false;
        var normal = new[]
        {
            localNormal[0] / normalLength,
            localNormal[1] / normalLength,
            localNormal[2] / normalLength,
        };
        var allPoints = sourceFaces.SelectMany(face => face.OuterVertices!).ToList();
        if (allPoints.Count < 8 || allPoints.Any(point => point.Length < 3
                || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;
        double minimum = allPoints.Min(point => Dot(point, normal));
        double maximum = allPoints.Max(point => Dot(point, normal));
        double precisionFeet = IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(maximum - minimum > 2 * precisionFeet)
            || closureCoordinate <= minimum + precisionFeet
            || closureCoordinate >= maximum - precisionFeet)
            return false;

        (long X, long Y, long Z) ProjectedKey(double[] point)
        {
            double coordinate = Dot(point, normal);
            return IfcPrecisionKeyFeet(
            [
                point[0] - coordinate * normal[0],
                point[1] - coordinate * normal[1],
                point[2] - coordinate * normal[2],
            ]);
        }
        static string RingSignature(IEnumerable<(long X, long Y, long Z)> keys) =>
            string.Join(';', keys.Order().Select(key => $"{key.X},{key.Y},{key.Z}"));

        var planarRings = new List<(List<double[]> Ring, double Coordinate, string Signature)>();
        foreach (GeoFace face in sourceFaces)
        {
            var ring = face.OuterVertices!;
            double coordinate = ring.Average(point => Dot(point, normal));
            if (ring.Any(point => Math.Abs(Dot(point, normal) - coordinate) > precisionFeet))
                continue;
            var keys = ring.Select(ProjectedKey).ToList();
            if (keys.Distinct().Count() != ring.Count) continue;
            planarRings.Add((ring, coordinate, RingSignature(keys)));
        }

        var closureSignatures = planarRings
            .Where(item => Math.Abs(item.Coordinate - closureCoordinate) <= precisionFeet)
            .Select(item => item.Signature).Distinct().ToHashSet();
        var minimumSignatures = planarRings
            .Where(item => Math.Abs(item.Coordinate - minimum) <= precisionFeet)
            .Select(item => item.Signature).Distinct().ToHashSet();
        var maximumSignatures = planarRings
            .Where(item => Math.Abs(item.Coordinate - maximum) <= precisionFeet)
            .Select(item => item.Signature).Distinct().ToHashSet();
        var matchingSignatures = closureSignatures
            .Where(minimumSignatures.Contains).Where(maximumSignatures.Contains).ToList();
        if (matchingSignatures.Count != 1) return false;

        string profileSignature = matchingSignatures[0];
        var closureRing = planarRings.First(item => item.Signature == profileSignature
            && Math.Abs(item.Coordinate - closureCoordinate) <= precisionFeet).Ring;
        var minimumRing = planarRings.First(item => item.Signature == profileSignature
            && Math.Abs(item.Coordinate - minimum) <= precisionFeet).Ring;
        var maximumRing = planarRings.First(item => item.Signature == profileSignature
            && Math.Abs(item.Coordinate - maximum) <= precisionFeet).Ring;
        var minimumByProjection = minimumRing.ToDictionary(ProjectedKey);
        var maximumByProjection = maximumRing.ToDictionary(ProjectedKey);
        var profileKeys = closureRing.Select(ProjectedKey).ToList();
        if (minimumByProjection.Count != profileKeys.Count
            || maximumByProjection.Count != profileKeys.Count
            || profileKeys.Any(key => !minimumByProjection.ContainsKey(key)
                || !maximumByProjection.ContainsKey(key)))
            return false;

        // Every serialized vertex must lie on one of the constant-section generators.
        var profileKeySet = profileKeys.ToHashSet();
        if (allPoints.Any(point => !profileKeySet.Contains(ProjectedKey(point))
                || Dot(point, normal) < minimum - precisionFeet
                || Dot(point, normal) > maximum + precisionFeet))
            return false;

        var minimumProfile = profileKeys
            .Select(key => (double[])minimumByProjection[key].Clone()).ToList();
        var maximumProfile = profileKeys
            .Select(key => (double[])maximumByProjection[key].Clone()).ToList();
        static GeoFace Face(IEnumerable<double[]> vertices) => new()
        {
            OuterVertices = vertices.Select(point => (double[])point.Clone()).ToList(),
        };
        var reconstructed = new List<GeoFace>
        {
            Face(minimumProfile),
            Face(maximumProfile),
        };
        for (int index = 0; index < profileKeys.Count; index++)
        {
            int next = (index + 1) % profileKeys.Count;
            reconstructed.Add(Face(
            [
                minimumProfile[index], minimumProfile[next],
                maximumProfile[next], maximumProfile[index],
            ]));
        }
        var reconstructedIndices = Enumerable.Range(0, reconstructed.Count).ToList();
        if (!TryOrientExactFacetedShell(
                reconstructed, reconstructedIndices, out var oriented))
            return false;

        closedFaces = oriented;
        closedSolids =
        [
            new GeoBrepSolid
            {
                FaceIndices = Enumerable.Range(0, oriented.Count).ToList(),
                IsClosed = true,
            },
        ];
        return true;
    }

    /// <summary>Uses a hosted cutter's unique exact-mapped finite four-side shell.</summary>
    internal static bool TryBuildExactMappedHostedSideShellGeometry(
        Element hostedElement, out HostedOpeningGeometry opening)
    {
        opening = default;
        if (hostedElement.Geometry is not { Faces.Count: 4 } mappedGeometry
            || mappedGeometry.ExactMappedInstances is not { Count: 1 }
            || mappedGeometry.BrepSolids is not { Count: 1 } solids
            || solids[0].IsClosed
            || solids[0].FaceIndices.Count != 4
            || !solids[0].FaceIndices.Distinct().Order()
                .SequenceEqual(Enumerable.Range(0, mappedGeometry.Faces.Count))
            || mappedGeometry.Faces.Any(face =>
                face.OuterVertices is not { Count: 4 }
                || face.InnerVertices is { Count: > 0 })
            || !TryGetSerializedPlanAxis(
                hostedElement, out double axisX, out double axisY))
            return false;

        static bool UsesBothExtents(
            IReadOnlyList<double> values, double minimum, double maximum,
            double roundoff) =>
            values.All(value => Math.Min(
                    Math.Abs(value - minimum),
                    Math.Abs(value - maximum)) <= roundoff)
            && values.Any(value => Math.Abs(value - minimum) <= roundoff)
            && values.Any(value => Math.Abs(value - maximum) <= roundoff);

        var mappedFaces = mappedGeometry.Faces
            .Select(face => face.OuterVertices!.ToList()).ToList();
        var points = mappedFaces.SelectMany(face => face).ToList();
        if (points.Any(point => point.Length < 3
                || point.Any(value => !double.IsFinite(value))))
            return false;
        var projected = points.Select(point => (
            Along: point[0] * axisX + point[1] * axisY,
            Normal: point[0] * -axisY + point[1] * axisX,
            Z: point[2])).ToList();
        double minimumAlong = projected.Min(value => value.Along);
        double maximumAlong = projected.Max(value => value.Along);
        double minimumNormal = projected.Min(value => value.Normal);
        double maximumNormal = projected.Max(value => value.Normal);
        double minimumZ = projected.Min(value => value.Z);
        double maximumZ = projected.Max(value => value.Z);
        double widthFt = maximumAlong - minimumAlong;
        double depthFt = maximumNormal - minimumNormal;
        double heightFt = maximumZ - minimumZ;
        double scale = Math.Max(1.0, points.SelectMany(point => point)
            .Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 8192 * MachineEpsilon * scale;
        if (!(widthFt > roundoff) || !(depthFt > roundoff)
            || !(heightFt > roundoff))
            return false;

        int constantAlongFaces = 0;
        int constantZFaces = 0;
        foreach (var face in mappedFaces)
        {
            var values = face.Select(point => (
                Along: point[0] * axisX + point[1] * axisY,
                Normal: point[0] * -axisY + point[1] * axisX,
                Z: point[2])).ToList();
            bool constantAlong =
                values.Max(value => value.Along)
                    - values.Min(value => value.Along) <= roundoff
                && UsesBothExtents(values.Select(value => value.Normal).ToList(),
                    minimumNormal, maximumNormal, roundoff)
                && UsesBothExtents(values.Select(value => value.Z).ToList(),
                    minimumZ, maximumZ, roundoff);
            bool constantZ =
                values.Max(value => value.Z)
                    - values.Min(value => value.Z) <= roundoff
                && UsesBothExtents(values.Select(value => value.Along).ToList(),
                    minimumAlong, maximumAlong, roundoff)
                && UsesBothExtents(values.Select(value => value.Normal).ToList(),
                    minimumNormal, maximumNormal, roundoff);
            if (constantAlong == constantZ)
                return false;
            if (constantAlong) constantAlongFaces++;
            else constantZFaces++;
        }
        if (constantAlongFaces != 2 || constantZFaces != 2
            || points.Select(IfcPrecisionKeyFeet).Distinct().Count() != 8)
            return false;

        double centreAlong = (minimumAlong + maximumAlong) / 2;
        double centreNormal = (minimumNormal + maximumNormal) / 2;
        opening = new HostedOpeningGeometry(
            centreAlong * axisX - centreNormal * axisY,
            centreAlong * axisY + centreNormal * axisX,
            axisX, axisY,
            widthFt, depthFt, minimumZ, heightFt,
            ExactDepth: true, IsExactMappedSideShell: true);
        return true;
    }

    /// <summary>
    /// Non-loop operands are already complete; a family cut loop targets a host only when their
    /// authored solids have a positive intersection.
    /// </summary>
    internal static bool TryTargetCommonHostedOpeningToHost(
        HostedOpeningGeometry authored, Element host,
        out HostedOpeningGeometry targeted)
    {
        targeted = authored;
        if (authored.OwnPrimaryFamilyHostId > 0) return authored.OwnPrimaryFamilyHostId == host.Id;
        return !authored.IsFamilyCutLoop
            || TryIntersectFamilyCutLoopWithHost(authored, host, out targeted);
    }

    /// <summary>
    /// Builds a family-authored cutter from the stable shared-parameter contract used by
    /// coordinated wall openings.
    /// </summary>
    internal static bool TryBuildSerializedHostedOpeningGeometry(Element hostedElement,
        Element? hostedType, out HostedOpeningGeometry opening)
    {
        opening = default;
        if (TryBuildExactMappedHostedSideShellGeometry(
                hostedElement, out opening))
            return true;

        if (!TryGetSerializedHostedOpeningDimensions(
                hostedElement.Parameters, out double widthFt,
                out double heightFt, out double depthFt)
            && (hostedType == null || !TryGetSerializedHostedOpeningDimensions(
                hostedType.Parameters, out widthFt, out heightFt, out depthFt)))
            return false;
        if (!(widthFt > 0.03) || !(heightFt > 0.03) || !(depthFt > 0)
            || !TryGetSerializedPlanAxis(hostedElement, out double axisX, out double axisY)
            || hostedElement.Geometry?.Faces is not { Count: > 0 } faces)
            return false;

        double centreX;
        double centreY;
        double baseZ;
        if (!TryGetExactSerializedHostedOpeningMarkerPlacement(
                hostedElement.Geometry, axisX, axisY, widthFt, heightFt,
                out centreX, out centreY, out baseZ))
        {
            var points = faces.SelectMany(face => face.OuterVertices ?? [])
                .Where(point => point.Length >= 3
                    && double.IsFinite(point[0]) && double.IsFinite(point[1])
                    && double.IsFinite(point[2])).ToList();
            if (points.Count < 4) return false;
            double minX = points.Min(point => point[0]);
            double maxX = points.Max(point => point[0]);
            double minY = points.Min(point => point[1]);
            double maxY = points.Max(point => point[1]);
            double minZ = points.Min(point => point[2]);
            double maxZ = points.Max(point => point[2]);
            double centreZ = (minZ + maxZ) / 2;
            if (!double.IsFinite(centreZ)) return false;
            centreX = (minX + maxX) / 2;
            centreY = (minY + maxY) / 2;
            baseZ = centreZ - heightFt / 2;
        }

        opening = new HostedOpeningGeometry(
            centreX, centreY,
            axisX, axisY, widthFt, depthFt,
            baseZ, heightFt, ExactDepth: true,
            IsExactSerializedDefinition: true);
        return true;
    }

    /// <summary>
    /// Finds the unique closed rectangular marker solid whose authored width and height exactly
    /// match the shared-parameter opening contract.
    /// </summary>
    internal static bool TryGetExactSerializedHostedOpeningMarkerPlacement(
        GeometryData geometry, double axisX, double axisY,
        double widthFt, double heightFt,
        out double centreXFt, out double centreYFt, out double baseZFt)
    {
        centreXFt = centreYFt = baseZFt = 0;
        if (geometry.Faces is not { Count: > 0 } faces
            || geometry.BrepSolids is not { Count: > 0 } solids
            || !double.IsFinite(axisX) || !double.IsFinite(axisY)
            || !double.IsFinite(widthFt) || !double.IsFinite(heightFt))
            return false;

        var matches = new List<(double CentreX, double CentreY, double BaseZ)>();
        foreach (GeoBrepSolid solid in solids)
        {
            var indices = solid.FaceIndices.Distinct().ToList();
            if (!solid.IsClosed || solid.FaceIndices.Count != 6
                || indices.Count != 6
                || indices.Any(index => index < 0 || index >= faces.Count))
                continue;
            var markerFaces = indices.Select(index => faces[index]).ToList();
            if (!TryOrientExactFacetedShell(
                    markerFaces, Enumerable.Range(0, markerFaces.Count).ToList(),
                    out markerFaces, triangulateNonPlanarFaces: false))
                continue;
            var marker = new GeometryData
            {
                Faces = markerFaces,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(0, markerFaces.Count).ToList(),
                        IsClosed = true,
                    },
                ],
            };
            if (!TryGetExactVerticalRectangularPrismPlan(
                    marker, out var plan, out double markerBaseZFt,
                    out double markerHeightFt))
                continue;

            var along = plan.Select(point =>
                point[0] * axisX + point[1] * axisY).ToList();
            double markerWidthFt = along.Max() - along.Min();
            double scale = Math.Max(1.0, plan.SelectMany(point => point)
                .Append(markerBaseZFt).Append(markerHeightFt)
                .Append(widthFt).Append(heightFt)
                .Select(Math.Abs).Max());
            const double MachineEpsilon = 2.2204460492503131e-16;
            double roundoff = 8192 * MachineEpsilon * scale;
            if (Math.Abs(markerWidthFt - widthFt) > roundoff
                || Math.Abs(markerHeightFt - heightFt) > roundoff)
                continue;

            matches.Add((
                plan.Average(point => point[0]),
                plan.Average(point => point[1]),
                markerBaseZFt));
        }

        if (matches.Count != 1) return false;
        centreXFt = matches[0].CentreX;
        centreYFt = matches[0].CentreY;
        baseZFt = matches[0].BaseZ;
        return true;
    }

    private static bool TryGetSerializedPlanAxis(Element element,
        out double axisX, out double axisY)
    {
        axisX = axisY = 0;
        if (!TryGetSerializedInstanceTransform(element, out var transform)) return false;
        double[] basis = transform.BasisX;
        if (!double.IsFinite(basis[0]) || !double.IsFinite(basis[1])) return false;
        double length = Math.Sqrt(basis[0] * basis[0] + basis[1] * basis[1]);
        if (!(length > 0) || !double.IsFinite(length)) return false;
        axisX = basis[0] / length;
        axisY = basis[1] / length;
        return true;
    }

    /// <summary>
    /// Returns the exact FamilyInstance transform, either from the decoded instance record or from
    /// its single top-level GInstance representation.
    /// </summary>
    internal static bool TryGetSerializedInstanceTransform(Element element,
        out InstanceTransform transform)
    {
        transform = null!;
        if (element.Transform is { Origin.Length: >= 3, BasisX.Length: >= 3,
                BasisY.Length: >= 3, BasisZ.Length: >= 3 } direct
            && direct.Origin.Concat(direct.BasisX).Concat(direct.BasisY)
                .Concat(direct.BasisZ).All(double.IsFinite))
        {
            transform = direct;
            return true;
        }

        var instances = element.Geometry?.ExactMappedInstances is { Count: > 0 } exact
            ? exact : element.Geometry?.Instances;
        if (instances is not { Count: 1 }
            || instances[0].Transform is not { Length: >= 12 } matrix
            || matrix.Any(value => !double.IsFinite(value)))
            return false;

        transform = new InstanceTransform
        {
            BasisX = [matrix[0], matrix[3], matrix[6]],
            BasisY = [matrix[1], matrix[4], matrix[7]],
            BasisZ = [matrix[2], matrix[5], matrix[8]],
            Origin = [matrix[9], matrix[10], matrix[11]],
            SymbolId = instances[0].SymbolId,
        };
        return true;
    }

    /// <summary>
    /// Reconstruct one world-space cutter for a family void related to several parallel wall-layer
    /// products.
    /// </summary>
    internal static bool TryBuildCommonHostedOpeningGeometry(Element hostedElement,
        double[] hostedBbox, IReadOnlyList<Element> hostWalls,
        out HostedOpeningGeometry opening)
    {
        opening = default;
        if (hostWalls.Count < 2 || hostedBbox.Length < 6) return false;

        Element primary = hostWalls.FirstOrDefault(wall =>
                wall.Id == hostedElement.SerializedHostId || wall.Id == hostedElement.HostId)
            ?? hostWalls[0];
        if (primary.Location is not { CurveType: "Line", ArcRadius: null } primaryLine)
            return false;
        double primaryDx = primaryLine.EndPoint[0] - primaryLine.StartPoint[0];
        double primaryDy = primaryLine.EndPoint[1] - primaryLine.StartPoint[1];
        double primaryLength = Math.Sqrt(primaryDx * primaryDx + primaryDy * primaryDy);
        if (!(primaryLength > 0) || !double.IsFinite(primaryLength)) return false;
        double axisX = primaryDx / primaryLength, axisY = primaryDy / primaryLength;
        double normalX = -axisY, normalY = axisX;

        const double MachineEpsilon = 2.2204460492503131e-16;
        double directionRoundoff = 1024 * MachineEpsilon;
        double commonMinAlong = double.NegativeInfinity;
        double commonMaxAlong = double.PositiveInfinity;
        double commonBaseZ = double.NegativeInfinity;
        double commonHeadZ = double.PositiveInfinity;
        double bodyMinNormal = double.PositiveInfinity;
        double bodyMaxNormal = double.NegativeInfinity;
        int exactRevealCount = 0;
        double[] associationBox = BuildHostedOpeningAssociationBox(hostedElement, hostedBbox);

        foreach (var wall in hostWalls)
        {
            if (wall.Location is not { CurveType: "Line", ArcRadius: null } line)
                return false;
            double dx = line.EndPoint[0] - line.StartPoint[0];
            double dy = line.EndPoint[1] - line.StartPoint[1];
            double length = Math.Sqrt(dx * dx + dy * dy);
            if (!(length > 0) || !double.IsFinite(length)) return false;
            double ux = dx / length, uy = dy / length;
            if (Math.Abs(Math.Abs(ux * axisX + uy * axisY) - 1) > directionRoundoff)
                return false;

            if (TryBuildHostedOpeningBoundary(wall, associationBox, out var boundary))
            {
                // A decoded non-prismatic boundary must remain an exact per-host BRep; it cannot be
                // replaced by the common rectangular layered-wall cutter.
                if (!TryGetAuthoredHostedOpeningSpan(wall, boundary,
                        out _, out _, out _, out _))
                    return false;
                var revealPoints = boundary.Faces
                    .SelectMany(face => face.OuterVertices ?? [])
                    .Where(point => point.Length >= 3
                        && double.IsFinite(point[0]) && double.IsFinite(point[1])
                        && double.IsFinite(point[2])).ToList();
                if (revealPoints.Count < 8) return false;
                commonMinAlong = Math.Max(commonMinAlong,
                    revealPoints.Min(point => point[0] * axisX + point[1] * axisY));
                commonMaxAlong = Math.Min(commonMaxAlong,
                    revealPoints.Max(point => point[0] * axisX + point[1] * axisY));
                commonBaseZ = Math.Max(commonBaseZ,
                    revealPoints.Min(point => point[2]));
                commonHeadZ = Math.Min(commonHeadZ,
                    revealPoints.Max(point => point[2]));
                exactRevealCount++;
            }

            var bodyPoints = wall.Geometry?.Faces
                .SelectMany(face => face.OuterVertices ?? [])
                .Where(point => point.Length >= 2
                    && double.IsFinite(point[0]) && double.IsFinite(point[1])).ToList();
            if (bodyPoints is not { Count: >= 4 }) return false;
            bodyMinNormal = Math.Min(bodyMinNormal,
                bodyPoints.Min(point => point[0] * normalX + point[1] * normalY));
            bodyMaxNormal = Math.Max(bodyMaxNormal,
                bodyPoints.Max(point => point[0] * normalX + point[1] * normalY));
        }

        if (exactRevealCount == 0) return false;
        double width = commonMaxAlong - commonMinAlong;
        double depth = bodyMaxNormal - bodyMinNormal;
        double height = commonHeadZ - commonBaseZ;
        double scale = Math.Max(1.0, new[]
        {
            commonMinAlong, commonMaxAlong, bodyMinNormal, bodyMaxNormal,
            commonBaseZ, commonHeadZ,
        }.Select(Math.Abs).Max());
        double roundoff = 2048 * MachineEpsilon * scale;
        // CreateHostedOpeningAbsolute cannot represent a collapsed common interval and deliberately
        // retains its per-host fallback below this existing exporter limit.
        if (!(width > 0.03) || !(height > 0.03) || !(depth > roundoff)
            || !double.IsFinite(width) || !double.IsFinite(depth)
            || !double.IsFinite(height))
            return false;

        double centreAlong = (commonMinAlong + commonMaxAlong) / 2;
        double centreNormal = (bodyMinNormal + bodyMaxNormal) / 2;
        opening = new HostedOpeningGeometry(
            centreAlong * axisX + centreNormal * normalX,
            centreAlong * axisY + centreNormal * normalY,
            axisX, axisY, width, depth, commonBaseZ, height,
            ExactDepth: true,
            IsExactAuthoredMultiHostEnvelope: true);
        if (TryExpandCommonOpeningFromPairedSourceCaps(
                hostedElement, primary, opening, out var expanded)
            || TryExpandCommonOpeningFromPairedSourceJambs(
                hostedElement, primary, opening, out expanded)
            || TryExpandCommonOpeningFromConcordantHostCaps(
                hostedElement, primary, hostWalls, opening, out expanded)
            || TryExpandCommonOpeningFromAnchoredSecondaryJambs(
                hostedElement, primary, hostWalls, opening, out expanded))
            opening = expanded;
        return true;
    }

    /// <summary>
    /// A decoded primary-host cut can retain full cutter depth in paired alternative sill/head
    /// caps, while its ordinary caps stop at wall faces.
    /// </summary>
    internal static bool TryExpandCommonOpeningFromPairedSourceCaps(
        Element cutter, Element primary, HostedOpeningGeometry common,
        out HostedOpeningGeometry expanded)
        => TryExpandCommonOpeningFromPairedSourceReveals(cutter, primary, common,
            useJambs: false, out expanded);

    /// <summary>
    /// A single jamb is insufficient. A failed competing sill/head claim may not be bypassed by
    /// falling back to a different pair of alternative faces.
    /// </summary>
    internal static bool TryExpandCommonOpeningFromPairedSourceJambs(
        Element cutter, Element primary, HostedOpeningGeometry common,
        out HostedOpeningGeometry expanded)
        => TryExpandCommonOpeningFromPairedSourceReveals(cutter, primary, common,
            useJambs: true, out expanded);

    private static bool TryExpandCommonOpeningFromPairedSourceReveals(
        Element cutter, Element primary, HostedOpeningGeometry common, bool useJambs,
        out HostedOpeningGeometry expanded)
    {
        expanded = default;
        if (cutter.SerializedHostId != primary.Id
            || primary.CuttingElementIds is not { Count: > 0 } cuts
            || cuts.Count(id => id == cutter.Id) != 1 || cuts.Distinct().Count() != cuts.Count
            || cutter.References?.Count(id => id == primary.Id) != 1) return false;
        return TryBuildSourceRevealGeometry(cutter, primary, common, useJambs, out expanded);
    }

    /// <summary>
    /// A primary host with an undecoded (not authoritatively empty) cut roster can be corroborated
    /// by one reciprocally linked, decoded adjacent host.
    /// </summary>
    internal static bool TryExpandCommonOpeningFromConcordantHostCaps(
        Element cutter, Element primary, IReadOnlyList<Element> hosts,
        HostedOpeningGeometry common, out HostedOpeningGeometry expanded)
    {
        expanded = default;
        if (primary.Id <= 0 || cutter.SerializedHostId != primary.Id
            || primary.CuttingElementIds != null
            || cutter.References?.Count(id => id == primary.Id) != 1
            || hosts.Count < 2 || hosts.Any(host => host.Id <= 0 || host.CategoryId != -2000011)
            || hosts.Select(host => host.Id).Distinct().Count() != hosts.Count
            || !hosts.Any(host => ReferenceEquals(host, primary))) return false;
        // Select by serialized association before geometry. Competing associated hosts are not
        // resolved by choosing the deepest or best-fitting cap pair.
        var witnesses = hosts.Where(host => host.Id != primary.Id
            && host.CuttingElementIds?.Contains(cutter.Id) == true
            && primary.References?.Contains(host.Id) == true
            && host.References?.Contains(primary.Id) == true).ToList();
        if (witnesses.Count != 1) return false;
        var secondary = witnesses[0];
        var cuts = secondary.CuttingElementIds!;
        if (cuts.Count(id => id == cutter.Id) != 1 || cuts.Distinct().Count() != cuts.Count
            || primary.References!.Count(id => id == secondary.Id) != 1
            || secondary.References!.Count(id => id == primary.Id) != 1
            || !TryBuildSourceRevealGeometry(cutter, primary, common, false, out var own)
            || !TryBuildSourceRevealGeometry(cutter, secondary, common, false, out var other)
            || !HaveConcordantAdjacentSourceReveals(cutter,primary,secondary,common,own,other)) return false;
        expanded=own;
        return true;
    }

    /// <summary>
    /// A decoded primary cut with exactly one full-depth jamb can anchor a complete jamb pair in
    /// one adjacent, reciprocally linked secondary host whose cut roster is undecoded.
    /// </summary>
    internal static bool TryExpandCommonOpeningFromAnchoredSecondaryJambs(
        Element cutter, Element primary, IReadOnlyList<Element> hosts,
        HostedOpeningGeometry common, out HostedOpeningGeometry expanded)
    {
        expanded=default;
        if (primary.Id<=0 || cutter.SerializedHostId!=primary.Id
            || primary.CuttingElementIds is not { Count: > 0 } cuts
            || cuts.Count(id=>id==cutter.Id)!=1 || cuts.Distinct().Count()!=cuts.Count
            || cutter.References?.Count(id=>id==primary.Id)!=1
            || hosts.Count<2 || hosts.Any(host=>host.Id<=0 || host.CategoryId!=-2000011)
            || hosts.Select(host=>host.Id).Distinct().Count()!=hosts.Count
            || !hosts.Any(host=>ReferenceEquals(host,primary))
            || !TryBuildSourceRevealGeometry(cutter,primary,common,true,out var anchor,singleJambOnly:true)
            || !TryGetSerializedInstanceTransform(cutter,out var transform)) return false;
        long Key(double value)=>IfcPrecisionBinMetres(value*FeetToMetres);
        bool Project(double[]? p,out (long Along,long Normal,long Z) result)
        {
            result=default;
            if(p is not {Length:3} || p.Any(v=>!CanMapFeetToIfcPrecisionBin(v))) return false;
            double x=p[0]-transform.Origin[0],y=p[1]-transform.Origin[1];
            double along=x*common.AxisX+y*common.AxisY,normal=-x*common.AxisY+y*common.AxisX;
            double z=p[2]-transform.Origin[2];
            if(!CanMapFeetToIfcPrecisionBin(along) || !CanMapFeetToIfcPrecisionBin(normal)
                || !CanMapFeetToIfcPrecisionBin(z)) return false;
            result=(Key(along),Key(normal),Key(z));
            return true;
        }
        long left=Key(-common.WidthFt/2),right=Key(common.WidthFt/2);
        var witnesses=new List<Element>();
        foreach(var host in hosts)
        {
            if(host.Id==primary.Id || host.CuttingElementIds!=null
                || primary.References?.Contains(host.Id)!=true
                || host.References?.Contains(primary.Id)!=true
                || host.References?.Contains(cutter.Id)!=true) continue;
            if(host.Location is not {CurveType:"Line",ArcRadius:null} line
                || !Project(line.StartPoint,out var start) || !Project(line.EndPoint,out var end)) return false;
            if(start.Normal!=end.Normal || start.Z!=end.Z || start.Along==end.Along) return false;
            if(Math.Min(start.Along,end.Along)<=left && Math.Max(start.Along,end.Along)>=right)
                witnesses.Add(host);
        }
        if(witnesses.Count!=1) return false;
        var secondary=witnesses[0];
        if(primary.References!.Count(id=>id==secondary.Id)!=1
            || secondary.References!.Count(id=>id==primary.Id)!=1
            || !TryBuildSourceRevealGeometry(cutter,secondary,common,true,out var pair)
            || !HaveConcordantAdjacentSourceReveals(cutter,primary,secondary,common,anchor,pair)) return false;
        expanded=pair;
        return true;
    }

    private static bool HaveConcordantAdjacentSourceReveals(Element cutter,Element primary,Element secondary,
        HostedOpeningGeometry common,HostedOpeningGeometry own,HostedOpeningGeometry other)
    {
        if(!TryGetSerializedInstanceTransform(cutter,out var transform)) return false;

        double Normal(double x, double y) =>
            -(x-transform.Origin[0])*common.AxisY+(y-transform.Origin[1])*common.AxisX;
        bool Interval(double centre, double depth, out (long Low,long High) interval)
        {
            interval=default;
            double low=centre-depth/2,high=centre+depth/2;
            if (!CanMapFeetToIfcPrecisionBin(low) || !CanMapFeetToIfcPrecisionBin(high)) return false;
            interval=(IfcPrecisionBinMetres(low*FeetToMetres),IfcPrecisionBinMetres(high*FeetToMetres));
            return interval.Low<interval.High;
        }
        bool WallInterval(Element wall, out (long Low,long High) interval)
        {
            interval=default;
            return TryGetSerializedWallWidthFeet(wall,out double width)
                && Interval(Normal(wall.Location!.StartPoint[0],wall.Location.StartPoint[1]),width,out interval);
        }
        if (!Interval(Normal(own.CentreXFt,own.CentreYFt),own.DepthFt,out var ownCut)
            || !Interval(Normal(other.CentreXFt,other.CentreYFt),other.DepthFt,out var otherCut)
            || ownCut!=otherCut || !WallInterval(primary,out var ownWall)
            || !WallInterval(secondary,out var otherWall)
            || !(ownWall.Low==otherWall.High || ownWall.High==otherWall.Low)) return false;
        return true;
    }

    private static bool TryBuildSourceRevealGeometry(
        Element cutter, Element primary, HostedOpeningGeometry common, bool useJambs,
        out HostedOpeningGeometry expanded, bool singleJambOnly = false)
    {
        expanded = default;
        bool Point(double[]? p) => p is { Length: 3 }
            && p.All(v => double.IsFinite(v) && CanMapFeetToIfcPrecisionBin(v));
        if (singleJambOnly && !useJambs || cutter.Id <= 0 || cutter.CategoryId != -2000023 || cutter.SuperInstanceId is > 0
            || primary.CategoryId != -2000011
            || primary.References?.Count(id => id == cutter.Id) != 1
            || primary.Geometry is not { Faces: { Count: > 0 } faces, BrepSolids: [var solid] }
            || solid.FaceIndices.Distinct().Count() != solid.FaceIndices.Count
            || solid.FaceIndices.Any(i => i < 0 || i >= faces.Count)
            || !common.IsExactAuthoredMultiHostEnvelope || !common.ExactDepth
            || common.IsFamilyCutLoop || common.Boundary != null || common.SteppedProfile != null
            || !(common.WidthFt > 0) || !(common.DepthFt > 0) || !(common.HeightFt > 0)
            || new[] { common.CentreXFt, common.CentreYFt, common.AxisX, common.AxisY,
                common.WidthFt, common.DepthFt, common.BaseZFt, common.HeightFt }
                .Any(v => !double.IsFinite(v) || !CanMapFeetToIfcPrecisionBin(v))
            || !TryGetSerializedInstanceTransform(cutter, out var transform)
            || !Point(transform.Origin) || !Point(transform.BasisX)
            || !Point(transform.BasisY) || !Point(transform.BasisZ)
            || primary.Location is not { CurveType: "Line", ArcRadius: null } location
            || !Point(location.StartPoint) || !Point(location.EndPoint)
            || !TryGetSerializedWallWidthFeet(primary, out double wallWidth)
            || !CanMapFeetToIfcPrecisionBin(wallWidth)) return false;
        const double roundoff = 8192 * 2.2204460492503131e-16;
        double dx = common.AxisX, dy = common.AxisY;
        if (Math.Abs(dx*dx+dy*dy-1) > roundoff
            || Math.Abs(transform.BasisX[0]*transform.BasisX[0]+transform.BasisX[1]*transform.BasisX[1]-1) > roundoff
            || Math.Abs(transform.BasisX[2]) > roundoff
            || Math.Abs(Math.Abs(dx*transform.BasisX[0]+dy*transform.BasisX[1])-1) > roundoff
            || Math.Abs(transform.BasisZ[0])+Math.Abs(transform.BasisZ[1])+Math.Abs(transform.BasisZ[2]-1) > roundoff
            || Math.Abs(transform.BasisY[2]) > roundoff
            || Math.Abs(transform.BasisY[0]*transform.BasisY[0]+transform.BasisY[1]*transform.BasisY[1]-1) > roundoff
            || Math.Abs(transform.BasisX[0]*transform.BasisY[0]+transform.BasisX[1]*transform.BasisY[1]) > roundoff)
            return false;
        long Key(double v) => IfcPrecisionBinMetres(v * FeetToMetres);
        bool Project(double[] p, out (long X,long Y,long Z) point)
        {
            point=default;
            if (!Point(p)) return false;
            double x=(p[0]-transform.Origin[0])*dx+(p[1]-transform.Origin[1])*dy;
            double y=-(p[0]-transform.Origin[0])*dy+(p[1]-transform.Origin[1])*dx;
            double z=p[2]-transform.Origin[2];
            if (!CanMapFeetToIfcPrecisionBin(x) || !CanMapFeetToIfcPrecisionBin(y)
                || !CanMapFeetToIfcPrecisionBin(z)) return false;
            point=(Key(x),Key(y),Key(z));
            return true;
        }
        bool ProjectRing(List<double[]> ring, out (long X,long Y,long Z)[] points)
        {
            points=new (long X,long Y,long Z)[ring.Count];
            for (int i=0;i<ring.Count;i++)
                if (!Project(ring[i],out points[i])) return false;
            return true;
        }
        bool Cycle(List<double[]>? ring, (long X,long Y,long Z)[] expected)
        {
            if (ring == null || ring.Count != expected.Length || !ring.All(Point)) return false;
            if (!ProjectRing(ring,out var points)) return false;
            return Enumerable.Range(0,points.Length).Any(start=>new[] {-1,1}.Any(direction=>
                Enumerable.Range(0,points.Length).All(i=>points[(start+direction*i+points.Length)%points.Length]==expected[i])));
        }
        long left=Key(-common.WidthFt/2),right=Key(common.WidthFt/2),height=Key(common.HeightFt);
        long spanLow=useJambs?0:left,spanHigh=useJambs?height:right;
        long planeLow=useJambs?left:0,planeHigh=useJambs?right:height;
        long Span((long X,long Y,long Z) p) => useJambs?p.Z:p.X;
        long Plane((long X,long Y,long Z) p) => useJambs?p.X:p.Z;
        (long X,long Y,long Z) RevealPoint(long span,long normal,long plane) =>
            useJambs?(plane,normal,span):(span,normal,plane);
        if (!Project([common.CentreXFt,common.CentreYFt,common.BaseZFt],out var centre)
            || !Project(location.StartPoint,out var start) || !Project(location.EndPoint,out var end)) return false;
        if (centre.X!=0 || centre.Z!=0 || left>=right || height<=0 || start.Z!=end.Z
            || start.Y!=end.Y || start.X==end.X || Key(wallWidth)<=0) return false;
        var owned=solid.FaceIndices.ToHashSet();
        var witnesses=new List<(long Z,long Low,long High,long InnerLow,long InnerHigh,double LowFeet,double HighFeet)>();
        for (int index=0;index<faces.Count;index++)
        {
            var face=faces[index];
            if (face.AlternativeOuterVertices is not { Count: > 0 } alternative) continue;
            if (face.OuterVertices is not { Count: 4 } original || !original.All(Point)) continue;
            if (!ProjectRing(original,out var points)) return false;
            if (useJambs && (points[0].Z==0 || points[0].Z==height)
                && points.All(p=>p.Z==points[0].Z)
                && points.Min(p=>p.X)==left && points.Max(p=>p.X)==right) return false;
            long z=Plane(points[0]);
            if (z!=planeLow && z!=planeHigh || points.Any(p=>Plane(p)!=z)
                || points.Min(Span)!=spanLow || points.Max(Span)!=spanHigh) continue;
            long innerLow=points.Min(p=>p.Y),innerHigh=points.Max(p=>p.Y);
            if (!owned.Contains(index) || face.InnerVertices is { Count: > 0 }
                || (decimal)innerHigh-innerLow!=Key(wallWidth) || (decimal)innerLow+innerHigh!=2m*start.Y
                || !Cycle(original,[RevealPoint(spanLow,innerLow,z),RevealPoint(spanHigh,innerLow,z),
                    RevealPoint(spanHigh,innerHigh,z),RevealPoint(spanLow,innerHigh,z)])
                || alternative.Count!=5 || !alternative.All(Point)) return false;
            if (!ProjectRing(alternative,out var outer)) return false;
            long low=outer.Min(p=>p.Y),high=outer.Max(p=>p.Y);
            if (!(low<innerLow && innerLow<innerHigh && innerHigh<high)) return false;
            var rectangle=new[] {RevealPoint(spanLow,low,z),RevealPoint(spanHigh,low,z),
                RevealPoint(spanHigh,high,z),RevealPoint(spanLow,high,z)};
            // The fifth serialized point is an original reveal corner on a normal edge; only this
            // exact collinear subdivision may be removed.
            int matches=0;
            foreach(long x in new[] {spanLow,spanHigh})
            foreach(long y in new[] {innerLow,innerHigh})
            for(int edge=0;edge<4;edge++)
            {
                var p=rectangle[edge]; var q=rectangle[(edge+1)%4];
                if (Span(p)!=x || Span(q)!=x || y<=Math.Min(p.Y,q.Y) || y>=Math.Max(p.Y,q.Y)) continue;
                var cycle=rectangle.ToList(); cycle.Insert(edge+1,RevealPoint(x,y,z));
                if(Cycle(alternative,cycle.ToArray())) matches++;
            }
            if(matches!=1) return false;
            var normal=alternative.Select(p=>-(p[0]-transform.Origin[0])*dy+(p[1]-transform.Origin[1])*dx).ToArray();
            witnesses.Add((z,low,high,innerLow,innerHigh,normal.Min(),normal.Max()));
        }
        if (singleJambOnly ? witnesses.Count!=1
            : witnesses.Count!=2 || witnesses.Count(p=>p.Z==planeLow)!=1 || witnesses.Count(p=>p.Z==planeHigh)!=1)
            return false;
        var lower=singleJambOnly?witnesses[0]:witnesses.Single(p=>p.Z==planeLow);
        var upper=singleJambOnly?witnesses[0]:witnesses.Single(p=>p.Z==planeHigh);
        double commonNormal=-(common.CentreXFt-transform.Origin[0])*dy+(common.CentreYFt-transform.Origin[1])*dx;
        double commonLowFeet=commonNormal-common.DepthFt/2,commonHighFeet=commonNormal+common.DepthFt/2;
        if (!CanMapFeetToIfcPrecisionBin(commonLowFeet) || !CanMapFeetToIfcPrecisionBin(commonHighFeet)) return false;
        long commonLow=Key(commonLowFeet);
        long commonHigh=Key(commonHighFeet);
        if ((lower.Low,lower.High,lower.InnerLow,lower.InnerHigh)!=(upper.Low,upper.High,upper.InnerLow,upper.InnerHigh)
            || lower.Low>commonLow || lower.High<commonHigh || (decimal)lower.High-lower.Low<=Key(common.DepthFt)) return false;
        double normalCentre=(lower.LowFeet+lower.HighFeet)/2;
        double centreX=transform.Origin[0]-normalCentre*dy,centreY=transform.Origin[1]+normalCentre*dx;
        double depth=lower.HighFeet-lower.LowFeet;
        if (!CanMapFeetToIfcPrecisionBin(centreX) || !CanMapFeetToIfcPrecisionBin(centreY)
            || !CanMapFeetToIfcPrecisionBin(depth)) return false;
        expanded=common with
        {
            CentreXFt=centreX,
            CentreYFt=centreY,
            DepthFt=depth,
        };
        if ((Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID")??"")
            .Split(',',StringSplitOptions.TrimEntries).Contains(cutter.Id.ToString()))
            DiagnosticSink.WriteLine($"IFCPAIREDALTREVEALOPENING jambs={useJambs} cutter={cutter.Id} host={primary.Id} depth={expanded.DepthFt:G17}");
        return true;
    }

    /// <summary>Identical reveals from several hosts count as one source definition.</summary>
    internal static bool TryBuildExactProfileConcordantAuthoredMultiHostEnvelope(
        Element hostedElement, double[] hostedBbox,
        IReadOnlyList<Element> hostWalls,
        HostedOpeningGeometry serializedOpening,
        out HostedOpeningGeometry opening)
    {
        opening = default;
        if (!serializedOpening.IsExactSerializedDefinition
            || !serializedOpening.ExactDepth
            || serializedOpening.Boundary != null
            || serializedOpening.SteppedProfile != null
            || serializedOpening.IsFamilyCutLoop
            || hostWalls.Count < 2
            || hostedBbox.Length < 6)
            return false;

        double serializedAxisLength = Math.Sqrt(
            serializedOpening.AxisX * serializedOpening.AxisX
            + serializedOpening.AxisY * serializedOpening.AxisY);
        if (!(serializedAxisLength > 0)
            || !double.IsFinite(serializedAxisLength)
            || !(serializedOpening.WidthFt > 0)
            || !(serializedOpening.DepthFt > 0)
            || !(serializedOpening.HeightFt > 0))
            return false;

        bool HasExactProfileConcordance(
            HostedOpeningGeometry authoredDefinition)
        {
            if (!authoredDefinition.ExactDepth
                || authoredDefinition.Boundary != null
                || authoredDefinition.SteppedProfile != null
                || authoredDefinition.IsFamilyCutLoop)
                return false;
            double authoredAxisLength = Math.Sqrt(
                authoredDefinition.AxisX * authoredDefinition.AxisX
                + authoredDefinition.AxisY * authoredDefinition.AxisY);
            var values = new[]
            {
                serializedOpening.CentreXFt, serializedOpening.CentreYFt,
                serializedOpening.AxisX, serializedOpening.AxisY,
                serializedOpening.WidthFt, serializedOpening.DepthFt,
                serializedOpening.BaseZFt, serializedOpening.HeightFt,
                authoredDefinition.CentreXFt, authoredDefinition.CentreYFt,
                authoredDefinition.AxisX, authoredDefinition.AxisY,
                authoredDefinition.WidthFt, authoredDefinition.DepthFt,
                authoredDefinition.BaseZFt, authoredDefinition.HeightFt,
                serializedAxisLength, authoredAxisLength,
            };
            if (values.Any(value => !double.IsFinite(value))
                || !(authoredAxisLength > 0)
                || !(authoredDefinition.WidthFt > 0)
                || !(authoredDefinition.DepthFt > 0)
                || !(authoredDefinition.HeightFt > 0))
                return false;

            double serializedAxisX =
                serializedOpening.AxisX / serializedAxisLength;
            double serializedAxisY =
                serializedOpening.AxisY / serializedAxisLength;
            double authoredAxisX =
                authoredDefinition.AxisX / authoredAxisLength;
            double authoredAxisY =
                authoredDefinition.AxisY / authoredAxisLength;
            double axisDot = serializedAxisX * authoredAxisX
                + serializedAxisY * authoredAxisY;
            double serializedCentreAlong =
                serializedOpening.CentreXFt * authoredAxisX
                + serializedOpening.CentreYFt * authoredAxisY;
            double authoredCentreAlong =
                authoredDefinition.CentreXFt * authoredAxisX
                + authoredDefinition.CentreYFt * authoredAxisY;
            double scale = Math.Max(1.0, values
                .Append(serializedCentreAlong)
                .Append(authoredCentreAlong)
                .Select(Math.Abs).Max());
            const double MachineEpsilon = 2.2204460492503131e-16;
            double roundoff = 8192 * MachineEpsilon * scale;
            bool Same(double first, double second) =>
                Math.Abs(first - second) <= roundoff;
            return Math.Abs(Math.Abs(axisDot) - 1) <= roundoff
                && Same(serializedOpening.WidthFt,
                    authoredDefinition.WidthFt)
                && Same(serializedOpening.DepthFt,
                    authoredDefinition.DepthFt)
                && Same(serializedOpening.BaseZFt,
                    authoredDefinition.BaseZFt)
                && Same(serializedOpening.HeightFt,
                    authoredDefinition.HeightFt)
                && Same(serializedCentreAlong, authoredCentreAlong);
        }

        double[] associationBox =
            BuildHostedOpeningAssociationBox(hostedElement, hostedBbox);
        var uniqueRevealDefinitions = new List<HostedOpeningGeometry>();
        foreach (Element hostWall in hostWalls)
        {
            if (!TryBuildHostedOpeningBoundary(
                    hostWall, associationBox, out var revealBoundary)
                || revealBoundary.Faces.Count != 6
                || !TryGetExactVerticalRectangularPrismSweptOpening(
                    revealBoundary, out var decodedRevealDefinition)
                || !TryAlignRectangularDefinitionToSerializedAxis(
                    decodedRevealDefinition, out var revealDefinition)
                || !HasExactProfileConcordance(revealDefinition)
                || uniqueRevealDefinitions.Any(existing =>
                    RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                        existing, revealDefinition)))
                continue;
            uniqueRevealDefinitions.Add(revealDefinition);
        }
        if (uniqueRevealDefinitions.Count == 1)
        {
            opening = uniqueRevealDefinitions[0] with
            {
                IsExactAuthoredMultiHostEnvelope = true,
            };
            return true;
        }

        if (uniqueRevealDefinitions.Count > 1
            || !TryBuildCommonHostedOpeningGeometry(
                hostedElement, hostedBbox, hostWalls,
                out var authoredEnvelope)
            || !authoredEnvelope.IsExactAuthoredMultiHostEnvelope
            || !HasExactProfileConcordance(authoredEnvelope))
            return false;

        opening = authoredEnvelope;
        return true;

        bool TryAlignRectangularDefinitionToSerializedAxis(
            HostedOpeningGeometry definition,
            out HostedOpeningGeometry alignedDefinition)
        {
            alignedDefinition = default;
            double definitionAxisLength = Math.Sqrt(
                definition.AxisX * definition.AxisX
                + definition.AxisY * definition.AxisY);
            if (!(definitionAxisLength > 0)
                || !double.IsFinite(definitionAxisLength))
                return false;
            double definitionAxisX =
                definition.AxisX / definitionAxisLength;
            double definitionAxisY =
                definition.AxisY / definitionAxisLength;
            double serializedAxisX =
                serializedOpening.AxisX / serializedAxisLength;
            double serializedAxisY =
                serializedOpening.AxisY / serializedAxisLength;
            double dot = definitionAxisX * serializedAxisX
                + definitionAxisY * serializedAxisY;
            double cross = definitionAxisX * serializedAxisY
                - definitionAxisY * serializedAxisX;
            const double MachineEpsilon = 2.2204460492503131e-16;
            double directionRoundoff = 8192 * MachineEpsilon;
            if (Math.Abs(Math.Abs(dot) - 1) <= directionRoundoff)
            {
                alignedDefinition = definition;
                return true;
            }
            if (Math.Abs(dot) > directionRoundoff
                || Math.Abs(Math.Abs(cross) - 1) > directionRoundoff)
                return false;
            alignedDefinition = definition with
            {
                AxisX = -definition.AxisY,
                AxisY = definition.AxisX,
                WidthFt = definition.DepthFt,
                DepthFt = definition.WidthFt,
            };
            return true;
        }
    }

    /// <summary>
    /// Returns whether an exact straight-wall hole has the same authored centre/sill and either the
    /// outer or a strictly nested profile of the coordinated opening.
    /// </summary>
    private static bool ExactWallHoleCanBelongToCommonOpening(
        HostedOpeningGeometry commonOpening,
        RectangularWallThroughOpening hole)
    {
        double commonAxisLength = Math.Sqrt(
            commonOpening.AxisX * commonOpening.AxisX
            + commonOpening.AxisY * commonOpening.AxisY);
        double holeAxisLength = Math.Sqrt(
            hole.AxisX * hole.AxisX + hole.AxisY * hole.AxisY);
        if (!(commonAxisLength > 0) || !double.IsFinite(commonAxisLength)
            || !(holeAxisLength > 0) || !double.IsFinite(holeAxisLength))
            return false;
        double axisX = commonOpening.AxisX / commonAxisLength;
        double axisY = commonOpening.AxisY / commonAxisLength;
        double holeAxisX = hole.AxisX / holeAxisLength;
        double holeAxisY = hole.AxisY / holeAxisLength;
        double commonCentreAlong =
            commonOpening.CentreXFt * axisX
            + commonOpening.CentreYFt * axisY;
        double holeCentreAlong =
            hole.CentreXFt * axisX + hole.CentreYFt * axisY;
        var dimensions = new[]
        {
            commonOpening.CentreXFt, commonOpening.CentreYFt,
            commonOpening.WidthFt, commonOpening.BaseZFt,
            commonOpening.HeightFt, commonCentreAlong,
            hole.CentreXFt, hole.CentreYFt, hole.WidthFt,
            hole.BaseZFt, hole.HeightFt, holeCentreAlong,
        };
        if (dimensions.Any(value => !double.IsFinite(value)))
            return false;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, dimensions.Select(Math.Abs).Max());
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        bool sameOuterProfile =
            Same(hole.WidthFt, commonOpening.WidthFt)
            && Same(hole.HeightFt, commonOpening.HeightFt);
        bool strictlyNestedProfile =
            hole.WidthFt < commonOpening.WidthFt - roundoff
            && hole.HeightFt < commonOpening.HeightFt - roundoff;
        return Math.Abs(Math.Abs(
                holeAxisX * axisX + holeAxisY * axisY) - 1) <= roundoff
            && Same(holeCentreAlong, commonCentreAlong)
            && Same(hole.BaseZFt, commonOpening.BaseZFt)
            && (sameOuterProfile || strictlyNestedProfile);
    }

    /// <summary>
    /// Recovers the gross rectangular prism and the independently retained through-opening profile
    /// from the exact split-reveal pathology.
    /// </summary>
    private static bool
        TryGetExactGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealSource(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            out GeometryData grossBoundary,
            out HostedOpeningGeometry sourceThroughOpening,
            out string rejectionReason)
    {
        grossBoundary = new GeometryData();
        sourceThroughOpening = default;
        rejectionReason = "source-authority";

        bool PointIsExact(IReadOnlyList<double>? point) =>
            point is { Count: >= 3 }
            && CanMapFeetToIfcPrecisionBin(point[0])
            && CanMapFeetToIfcPrecisionBin(point[1])
            && CanMapFeetToIfcPrecisionBin(point[2])
            && double.IsFinite((Math.Abs(point[0]) + Math.Abs(point[1]))
                * FeetToMetres / IfcGeometryPrecisionMetres)
            && (Math.Abs(point[0]) + Math.Abs(point[1]))
                * FeetToMetres / IfcGeometryPrecisionMetres < long.MaxValue;

        static ((long X, long Y, long Z) A,
                (long X, long Y, long Z) B) Edge(
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);

        HashSet<((long X, long Y, long Z) A,
            (long X, long Y, long Z) B)> CycleEdges(
                IReadOnlyList<double[]> ring)
        {
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => Edge(
                    keys[index], keys[(index + 1) % keys.Count]))
                .ToHashSet();
        }

        bool RingIsExact(IReadOnlyList<double[]>? ring)
        {
            if (ring is not { Count: 4 }
                || ring.Any(point => !PointIsExact(point)))
                return false;
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return keys.Distinct().Count() == 4
                && CycleEdges(ring).Count == 4
                && FaceCanEmitAtIfcPrecision(
                    new GeoFace { OuterVertices = ring.ToList() });
        }

        bool CyclesMatch(
            IReadOnlyList<double[]> first,
            IReadOnlyList<double[]> second) =>
            RingIsExact(first) && RingIsExact(second)
            && CycleEdges(first).SetEquals(CycleEdges(second));

        bool TryGetOuterTopology(
            IReadOnlyList<GeoFace> faces,
            out HashSet<(long X, long Y, long Z)> vertices,
            out Dictionary<((long X, long Y, long Z) A,
                (long X, long Y, long Z) B), List<int>> owners,
            out List<HashSet<int>> components)
        {
            vertices = [];
            owners = [];
            components = [];
            var edgesByFace = new Dictionary<int, HashSet<(
                (long X, long Y, long Z) A,
                (long X, long Y, long Z) B)>>();
            for (int faceIndex = 0; faceIndex < faces.Count; faceIndex++)
            {
                if (!RingIsExact(faces[faceIndex].OuterVertices)) return false;
                var ring = faces[faceIndex].OuterVertices!;
                foreach (var point in ring) vertices.Add(IfcPrecisionKeyFeet(point));
                var edges = CycleEdges(ring);
                edgesByFace[faceIndex] = edges;
                foreach (var edge in edges)
                {
                    if (!owners.TryGetValue(edge, out var edgeOwners))
                        owners[edge] = edgeOwners = [];
                    edgeOwners.Add(faceIndex);
                }
            }

            var remaining = Enumerable.Range(0, faces.Count).ToHashSet();
            while (remaining.Count > 0)
            {
                int seed = remaining.Min();
                remaining.Remove(seed);
                var component = new HashSet<int>();
                var queue = new Queue<int>();
                queue.Enqueue(seed);
                while (queue.Count > 0)
                {
                    int current = queue.Dequeue();
                    component.Add(current);
                    foreach (int candidate in remaining.ToList())
                    {
                        if (!edgesByFace[current].Overlaps(
                                edgesByFace[candidate]))
                            continue;
                        remaining.Remove(candidate);
                        queue.Enqueue(candidate);
                    }
                }
                components.Add(component);
            }
            components = components
                .OrderByDescending(component => component.Count)
                .ThenBy(component => component.Min()).ToList();
            return true;
        }

        static bool ComponentsMatch(
            IReadOnlyList<HashSet<int>> actual,
            params int[][] expected) =>
            actual.Count == expected.Length
            && expected.All(expectedComponent => actual.Any(
                component => component.SetEquals(expectedComponent)));

        if (wall.Id <= 0
            || bounds.Count < 6
            || bounds.Take(6).Any(value => !CanMapFeetToIfcPrecisionBin(value))
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !PointIsExact(location.StartPoint)
            || !PointIsExact(location.EndPoint)
            || !TryGetSerializedWallWidthFeet(wall, out double wallWidthFt)
            || !(wallWidthFt > 0) || !double.IsFinite(wallWidthFt)
            || !CanMapFeetToIfcPrecisionBin(wallWidthFt)
            || wall.Geometry is not
                {
                    Faces: { Count: 16 } sourceFaces,
                    BrepSolids: [{ IsClosed: false } sourceSolid],
                    BoundingBox: { Length: 6 } sourceBounds,
                }
            || !sourceSolid.FaceIndices.SequenceEqual(
                Enumerable.Range(0, sourceFaces.Count))
            || sourceFaces.Any(face =>
                !RingIsExact(face.OuterVertices)
                || face.AlternativeOuterVertices is { Count: > 0 })
            || sourceFaces.Select((face, index) => (face, index)).Any(item =>
                item.index is 0 or 2
                    ? item.face.InnerVertices is not { Count: 1 }
                        || !RingIsExact(item.face.InnerVertices[0])
                    : item.face.InnerVertices is { Count: > 0 })
            || !BoundsMatchAtIfcPrecision(sourceBounds, bounds))
        {
            rejectionReason = "source-authority";
            return false;
        }

        if (!TryGetOuterTopology(sourceFaces,
                out var sourceVertices, out var sourceOwners,
                out var sourceComponents)
            || sourceVertices.Count != 22
            || sourceOwners.Count != 35
            || sourceOwners.Values.Sum(owners => owners.Count) != 64
            || sourceOwners.Values.Count(owners => owners.Count == 1) != 7
            || sourceOwners.Values.Count(owners => owners.Count == 2) != 27
            || sourceOwners.Values.Count(owners => owners.Count == 3) != 1
            || sourceOwners.Values.Single(owners => owners.Count == 3)
                .Distinct().Order().SequenceEqual([6, 7, 13]) == false
            || !ComponentsMatch(sourceComponents,
                Enumerable.Range(6, 10).ToArray(),
                Enumerable.Range(0, 6).ToArray()))
        {
            rejectionReason = "source-topology";
            return false;
        }

        if (rebuiltBoundary.Faces is not { Count: 10 } rebuiltFaces
            || rebuiltBoundary.BrepSolids is not
                [{ IsClosed: true } rebuiltSolid]
            || !rebuiltSolid.FaceIndices.SequenceEqual(
                Enumerable.Range(0, rebuiltFaces.Count))
            || rebuiltBoundary.BoundingBox is not
                { Length: 6 } rebuiltBounds
            || !BoundsMatchAtIfcPrecision(rebuiltBounds, sourceBounds)
            || rebuiltFaces.Any(face =>
                !RingIsExact(face.OuterVertices)
                || face.AlternativeOuterVertices is { Count: > 0 })
            || rebuiltFaces.Select((face, index) => (face, index)).Any(item =>
                item.index is 0 or 1
                    ? item.face.InnerVertices is not { Count: 1 }
                        || !RingIsExact(item.face.InnerVertices[0])
                    : item.face.InnerVertices is { Count: > 0 })
            || !TryGetOuterTopology(rebuiltFaces,
                out var rebuiltVertices, out var rebuiltOwners,
                out var rebuiltComponents)
            || rebuiltVertices.Count != 16
            || rebuiltOwners.Count != 24
            || rebuiltOwners.Values.Sum(owners => owners.Count) != 40
            || rebuiltOwners.Values.Count(owners => owners.Count == 1) != 8
            || rebuiltOwners.Values.Count(owners => owners.Count == 2) != 16
            || rebuiltOwners.Values.Any(owners => owners.Count is not (1 or 2))
            || !ComponentsMatch(rebuiltComponents,
                Enumerable.Range(0, 6).ToArray(),
                Enumerable.Range(6, 4).ToArray()))
        {
            rejectionReason = "rebuilt-topology";
            return false;
        }

        int[] sourceToRebuilt = [0, 5, 1, 2, 3, 4];
        if (Enumerable.Range(0, sourceToRebuilt.Length).Any(index =>
                !CyclesMatch(sourceFaces[index].OuterVertices!,
                    rebuiltFaces[sourceToRebuilt[index]].OuterVertices!))
            || !CyclesMatch(sourceFaces[0].InnerVertices![0],
                rebuiltFaces[0].InnerVertices![0])
            || !CyclesMatch(sourceFaces[2].InnerVertices![0],
                rebuiltFaces[1].InnerVertices![0]))
        {
            rejectionReason = "source-rebuilt-cycle-map";
            return false;
        }

        double axisX = location.EndPoint[0] - location.StartPoint[0];
        double axisY = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
        {
            rejectionReason = "wall-axis";
            return false;
        }
        axisX /= axisLength;
        axisY /= axisLength;
        double normalX = -axisY;
        double normalY = axisX;
        long ProjectionKey(double valueFt) =>
            IfcPrecisionBinMetres(valueFt * FeetToMetres);
        (long Along, long Normal, long Z) Project(double[] point) =>
            (ProjectionKey(point[0] * axisX + point[1] * axisY),
             ProjectionKey(point[0] * normalX + point[1] * normalY),
             ProjectionKey(point[2]));
        bool ProjectedCycleMatches(
            IReadOnlyList<double[]> ring,
            params (long Along, long Normal, long Z)[] expected) =>
            ring.Count == expected.Length
            && ring.Select(Project).ToHashSet().SetEquals(expected);

        var sourceProjected = sourceFaces
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat(face.InnerVertices?.SelectMany(ring => ring) ?? []))
            .Select(Project).ToList();
        var along = sourceProjected.Select(point => point.Along)
            .Distinct().Order().ToList();
        var normal = sourceProjected.Select(point => point.Normal)
            .Distinct().Order().ToList();
        var z = sourceProjected.Select(point => point.Z)
            .Distinct().Order().ToList();
        if (along.Count != 4 || normal.Count != 3 || z.Count != 5)
        {
            rejectionReason = "source-projected-levels";
            return false;
        }
        long a0 = along[0], a1 = along[1], a2 = along[2], a3 = along[3];
        long n0 = normal[0], n1 = normal[1], n2 = normal[2];
        long z0 = z[0], z1 = z[1], z2 = z[2], z3 = z[3], z4 = z[4];
        long wallWidthBin = ProjectionKey(wallWidthFt);
        long locationLengthBin = ProjectionKey(axisLength);
        if (new[]
            {
                a1 - a0, a2 - a1, a3 - a2,
                n1 - n0, n2 - n1,
                z1 - z0, z2 - z1, z3 - z2, z4 - z3,
            }.Any(value => value <= 2)
            || n2 - n1 != wallWidthBin
            || (n1 - n0) * 10 != wallWidthBin
            || locationLengthBin - (a3 - a0) != wallWidthBin / 2
            || wallWidthBin % 2 != 0)
        {
            rejectionReason = "source-projected-lattice";
            return false;
        }

        bool sourceCyclesMatch =
            ProjectedCycleMatches(sourceFaces[0].OuterVertices!,
                (a0, n1, z0), (a0, n1, z4),
                (a3, n1, z4), (a3, n1, z0))
            && ProjectedCycleMatches(sourceFaces[0].InnerVertices![0],
                (a1, n1, z1), (a1, n1, z2),
                (a2, n1, z2), (a2, n1, z1))
            && ProjectedCycleMatches(sourceFaces[1].OuterVertices!,
                (a0, n1, z0), (a0, n2, z0),
                (a3, n2, z0), (a3, n1, z0))
            && ProjectedCycleMatches(sourceFaces[2].OuterVertices!,
                (a0, n2, z0), (a0, n2, z4),
                (a3, n2, z4), (a3, n2, z0))
            && ProjectedCycleMatches(sourceFaces[2].InnerVertices![0],
                (a1, n2, z2), (a1, n2, z3),
                (a2, n2, z3), (a2, n2, z2))
            && ProjectedCycleMatches(sourceFaces[3].OuterVertices!,
                (a3, n1, z0), (a3, n2, z0),
                (a3, n2, z4), (a3, n1, z4))
            && ProjectedCycleMatches(sourceFaces[4].OuterVertices!,
                (a0, n1, z4), (a0, n2, z4),
                (a3, n2, z4), (a3, n1, z4))
            && ProjectedCycleMatches(sourceFaces[5].OuterVertices!,
                (a0, n1, z0), (a0, n2, z0),
                (a0, n2, z4), (a0, n1, z4))
            && ProjectedCycleMatches(sourceFaces[6].OuterVertices!,
                (a1, n1, z1), (a1, n1, z2),
                (a2, n1, z2), (a2, n1, z1))
            && ProjectedCycleMatches(sourceFaces[7].OuterVertices!,
                (a1, n0, z2), (a1, n1, z2),
                (a2, n1, z2), (a2, n0, z2))
            && ProjectedCycleMatches(sourceFaces[8].OuterVertices!,
                (a1, n0, z1), (a1, n0, z2),
                (a2, n0, z2), (a2, n0, z1))
            && ProjectedCycleMatches(sourceFaces[9].OuterVertices!,
                (a1, n0, z1), (a1, n1, z1),
                (a2, n1, z1), (a2, n0, z1))
            && ProjectedCycleMatches(sourceFaces[10].OuterVertices!,
                (a1, n1, z3), (a1, n2, z3),
                (a2, n2, z3), (a2, n1, z3))
            && ProjectedCycleMatches(sourceFaces[11].OuterVertices!,
                (a2, n1, z2), (a2, n1, z3),
                (a2, n2, z3), (a2, n2, z2))
            && ProjectedCycleMatches(sourceFaces[12].OuterVertices!,
                (a1, n1, z2), (a1, n1, z3),
                (a1, n2, z3), (a1, n2, z2))
            && ProjectedCycleMatches(sourceFaces[13].OuterVertices!,
                (a1, n1, z2), (a1, n2, z2),
                (a2, n2, z2), (a2, n1, z2))
            && ProjectedCycleMatches(sourceFaces[14].OuterVertices!,
                (a1, n0, z1), (a1, n0, z2),
                (a1, n1, z2), (a1, n1, z1))
            && ProjectedCycleMatches(sourceFaces[15].OuterVertices!,
                (a2, n0, z1), (a2, n0, z2),
                (a2, n1, z2), (a2, n1, z1));
        if (!sourceCyclesMatch)
        {
            rejectionReason = "source-projected-cycles";
            return false;
        }

        var rebuiltProjected = rebuiltFaces
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat(face.InnerVertices?.SelectMany(ring => ring) ?? []))
            .Select(Project).ToList();
        if (!rebuiltProjected.Select(point => point.Along).Distinct().Order()
                .SequenceEqual(along)
            || !rebuiltProjected.Select(point => point.Normal).Distinct().Order()
                .SequenceEqual([n1, n2])
            || !rebuiltProjected.Select(point => point.Z).Distinct().Order()
                .SequenceEqual(z)
            || !ProjectedCycleMatches(rebuiltFaces[6].OuterVertices!,
                (a1, n1, z1), (a1, n1, z2),
                (a1, n2, z2), (a1, n2, z3))
            || !ProjectedCycleMatches(rebuiltFaces[7].OuterVertices!,
                (a1, n1, z2), (a1, n2, z3),
                (a2, n2, z3), (a2, n1, z2))
            || !ProjectedCycleMatches(rebuiltFaces[8].OuterVertices!,
                (a2, n1, z1), (a2, n1, z2),
                (a2, n2, z2), (a2, n2, z3))
            || !ProjectedCycleMatches(rebuiltFaces[9].OuterVertices!,
                (a1, n1, z1), (a1, n2, z2),
                (a2, n2, z2), (a2, n1, z1)))
        {
            rejectionReason = "rebuilt-projected-cycles";
            return false;
        }

        var grossFaces = sourceFaces.Take(6).Select(face => new GeoFace
        {
            OuterVertices = face.OuterVertices!.ToList(),
        }).ToList();
        var grossIndices = Enumerable.Range(0, grossFaces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                grossFaces, grossIndices, out var orientedGrossFaces))
        {
            rejectionReason = "gross-orientation";
            return false;
        }
        var grossPoints = grossFaces.SelectMany(face => face.OuterVertices!).ToList();
        double[] grossBounds =
        [
            grossPoints.Min(point => point[0]),
            grossPoints.Min(point => point[1]),
            grossPoints.Min(point => point[2]),
            grossPoints.Max(point => point[0]),
            grossPoints.Max(point => point[1]),
            grossPoints.Max(point => point[2]),
        ];
        var candidateGross = new GeometryData
        {
            BoundingBox = grossBounds,
            Faces = orientedGrossFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = grossIndices,
                    IsClosed = true,
                },
            ],
        };
        if (!BoundsMatchAtIfcPrecision(grossBounds, sourceBounds)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, sourceBounds)
            || !TryGetExactWallVerticalParameterDefinition(
                wall, sourceBounds, out double baseZFt, out double topZFt)
            || ProjectionKey(baseZFt) != z0
            || ProjectionKey(topZFt) != z4
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                candidateGross, location, wallWidthFt, sourceBounds,
                out var grossPlan, out double grossBaseZFt,
                out double grossHeightFt, out string grossReason)
            || grossReason != "exact" || grossPlan.Count != 4
            || ProjectionKey(grossBaseZFt) != z0
            || ProjectionKey(grossBaseZFt + grossHeightFt) != z4
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                candidateGross, out _))
        {
            rejectionReason = "gross-definition";
            return false;
        }

        double latticeFeet = IfcGeometryPrecisionMetres / FeetToMetres;
        double openingAlongFt = (a1 + a2) * latticeFeet / 2;
        double openingNormalFt = (n1 + n2) * latticeFeet / 2;
        sourceThroughOpening = new HostedOpeningGeometry(
            openingAlongFt * axisX + openingNormalFt * normalX,
            openingAlongFt * axisY + openingNormalFt * normalY,
            axisX, axisY,
            (a2 - a1) * latticeFeet,
            (n2 - n1) * latticeFeet,
            z2 * latticeFeet,
            (z3 - z2) * latticeFeet,
            ExactDepth: true);
        if (!RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                sourceThroughOpening,
                new HostedOpeningGeometry(
                    sourceThroughOpening.CentreXFt,
                    sourceThroughOpening.CentreYFt,
                    sourceThroughOpening.AxisX,
                    sourceThroughOpening.AxisY,
                    sourceThroughOpening.WidthFt,
                    wallWidthFt,
                    sourceThroughOpening.BaseZFt,
                    sourceThroughOpening.HeightFt,
                    ExactDepth: true)))
        {
            rejectionReason = "source-through-opening";
            return false;
        }

        grossBoundary = candidateGross;
        rejectionReason = "exact";
        return true;
    }

    // Here the complete missing prism must be owned by one reciprocal, perpendicular source wall.
    internal static bool TryGetVerifiedGrossWallBoundaryFromPerpendicularJoinNotchAndDoor(
        Element wall, IReadOnlyList<double> bounds, GeometryData rebuilt,
        IReadOnlyDictionary<int, Element> elements,
        IReadOnlyDictionary<int, List<int>>? emittedIds,
        IReadOnlyDictionary<int, List<(int CutterId, HostedOpeningGeometry Operand)>>? emittedOperands,
        IReadOnlyDictionary<int, List<int>>? standaloneIds,
        out GeometryData grossBoundary, out IReadOnlyList<int> cutterIds)
    {
        grossBoundary = new GeometryData(); cutterIds = [];
        bool diagnostics = (Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") ?? "")
            .Split(',', StringSplitOptions.TrimEntries).Contains(wall.Id.ToString());
        bool Reject(string stage)
        {
            if (diagnostics) DiagnosticSink.WriteLine($"IFCJOINNOTCHGATE wall={wall.Id} result=reject stage={stage}");
            return false;
        }
        bool Point(double[]? p) => p is { Length: 3 }
            && p.All(v => double.IsFinite(v) && CanMapFeetToIfcPrecisionBin(v));
        bool NoOtherCuts(Element e) => e.SketchLoops is not { Count: > 0 }
            && e.FamilyCutGeometry == null && e.FamilyCutLoops is not { Count: > 0 }
            && e.FamilyCutClosurePlaneOrigin == null && e.FamilyCutClosurePlaneNormal == null;
        if (wall.Id <= 0 || wall.CategoryId != -2000011 || !NoOtherCuts(wall)
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !Point(location.StartPoint) || !Point(location.EndPoint)
            || bounds.Count != 6 || bounds.Any(v => !double.IsFinite(v) || !CanMapFeetToIfcPrecisionBin(v))
            || !TryGetSerializedWallWidthFeet(wall, out double width) || !(width > 0)
            || wall.Geometry is not { Faces: { Count: 16 } faces,
                BrepSolids: [{ IsClosed: false } solid], BoundingBox: { Length: 6 } sourceBounds }
            || !solid.FaceIndices.SequenceEqual(Enumerable.Range(0, 12))
            || !BoundsMatchAtIfcPrecision(bounds, sourceBounds)) return Reject("source-authority");
        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double length = Math.Sqrt(dx * dx + dy * dy);
        if (!double.IsFinite(length) || !(length > width)) return Reject("axis");
        dx /= length; dy /= length;
        long Key(double v) => IfcPrecisionBinMetres(v * FeetToMetres);
        (long X, long Y, long Z) Project(double[] p) =>
            (Key((p[0]-location.StartPoint[0])*dx+(p[1]-location.StartPoint[1])*dy),
             Key(-(p[0]-location.StartPoint[0])*dy+(p[1]-location.StartPoint[1])*dx), Key(p[2]));
        bool Cycle(IReadOnlyList<double[]>? ring, params (long X, long Y, long Z)[] expected)
        {
            if (ring == null || ring.Count != expected.Length || !ring.All(Point)) return false;
            var keys = ring.Select(Project).ToArray();
            return Enumerable.Range(0, keys.Length).Any(start => new[] { -1, 1 }.Any(direction =>
                Enumerable.Range(0, keys.Length).All(i =>
                    keys[(start+direction*i+keys.Length)%keys.Length] == expected[i])));
        }
        double[] Bounds(IEnumerable<double[]> points)
        {
            var all = points.ToArray();
            return [all.Min(p=>p[0]),all.Min(p=>p[1]),all.Min(p=>p[2]),
                all.Max(p=>p[0]),all.Max(p=>p[1]),all.Max(p=>p[2])];
        }
        for (int i = 0; i < faces.Count; i++)
            if (faces[i].OuterVertices?.Count != (i is 0 or 2 ? 6 : 4)
                || !faces[i].OuterVertices!.All(Point)
                || faces[i].AlternativeOuterVertices is { Count: > 0 }
                || (faces[i].InnerVertices?.Count ?? 0) != (i is 0 or 2 ? 1 : 0)
                || faces[i].InnerVertices?.Any(r => r.Count != 4 || !r.All(Point)) == true)
                return Reject("source-face");
        if (!BoundsMatchAtIfcPrecision(bounds, Bounds(faces.SelectMany(f=>f.OuterVertices!))))
            return Reject("source-bounds");
        var cap = faces[3].OuterVertices!.Select(Project).ToArray();
        long a=cap.Min(p=>p.X), b=cap.Max(p=>p.X), n=cap.Min(p=>p.Y), m=cap.Max(p=>p.Y);
        long bottom=Key(bounds[2]), top=Key(bounds[5]);
        long notch=faces[1].OuterVertices!.Select(Project).Max(p=>p.X);
        long head=faces[4].OuterVertices!.Select(Project).Min(p=>p.Z);
        var hole = faces[0].InnerVertices![0].Select(Project).ToArray();
        long left=hole.Min(p=>p.X), right=hole.Max(p=>p.X), sill=hole.Min(p=>p.Z), lintel=hole.Max(p=>p.Z);
        if (!(0 < a && a < left && left < right && right < notch && notch < b)
            || !(bottom < sill && sill < lintel && lintel < head && head < top)
            || Project(location.EndPoint) != (b,0,Key(location.StartPoint[2]))
            || n >= 0 || n != -m || m-n != Key(width) || sill != Key(location.StartPoint[2]))
            return Reject("source-intervals");
        (long X,long Y,long Z)[] Side(long x0,long x1,long y,long z0,long z1) =>
            [(x0,y,z0),(x1,y,z0),(x1,y,z1),(x0,y,z1)];
        (long X,long Y,long Z)[] End(long x,long z0,long z1) =>
            [(x,n,z0),(x,m,z0),(x,m,z1),(x,n,z1)];
        (long X,long Y,long Z)[] Cap(long x0,long x1,long z) =>
            [(x0,n,z),(x1,n,z),(x1,m,z),(x0,m,z)];
        (long X,long Y,long Z)[] Step(long y) =>
            [(a,y,bottom),(a,y,top),(b,y,top),(b,y,head),(notch,y,head),(notch,y,bottom)];
        var core = new (long X,long Y,long Z)[][]
        {
            Step(n),Cap(a,notch,bottom),Step(m),Cap(a,b,top),End(b,head,top),
            End(right,sill,lintel),Cap(left,right,sill),End(left,sill,lintel),
            Cap(left,right,lintel),End(notch,bottom,head),Cap(notch,b,head),End(a,bottom,top),
        };
        for (int i=0;i<core.Length;i++)
            if (!Cycle(faces[i].OuterVertices,core[i])
                || i is 0 or 2 && !Cycle(faces[i].InnerVertices![0],Side(left,right,i==0?n:m,sill,lintel)))
                return Reject("core-cycles");
        // They may not define or enlarge its envelope.
        for (int i=12;i<16;i++)
        {
            var sheet=faces[i].OuterVertices!.Select(Project).ToArray();
            long lo=sheet.Min(p=>p.X), hi=sheet.Max(p=>p.X);
            if (!(a < lo && lo < hi && hi < b)
                || !Cycle(faces[i].OuterVertices,i<14?Cap(lo,hi,top):Side(lo,hi,i==14?n:m,sill,head)))
                return Reject("detached-sheet");
        }
        bool MatchesCore(GeoFace f,int i) => Cycle(f.OuterVertices,core[i])
            && f.AlternativeOuterVertices is not { Count: > 0 }
            && (f.InnerVertices?.Count??0)==(i is 0 or 2?1:0)
            && (i is not (0 or 2) || Cycle(f.InnerVertices![0],Side(left,right,i==0?n:m,sill,lintel)));
        if (rebuilt.Faces.Count!=12 || rebuilt.BrepSolids is not [{ IsClosed: true } rebuiltSolid]
            || !rebuiltSolid.FaceIndices.SequenceEqual(Enumerable.Range(0,12))
            || Enumerable.Range(0,12).Any(i=>rebuilt.Faces.Count(f=>MatchesCore(f,i))!=1)
            || rebuilt.Faces.Any(f=>Enumerable.Range(0,12).Count(i=>MatchesCore(f,i))!=1)
            || rebuilt.BoundingBox is not { Length: 6 } rebuiltBounds
            || !BoundsMatchAtIfcPrecision(bounds,rebuiltBounds)) return Reject("rebuilt-cycles");

        // Identify ownership before checking geometry: do not choose a convenient match from
        // multiple end-joined perpendicular wall claims.
        var neighbours = new List<Element>();
        foreach (int id in (wall.References ?? []).Distinct())
        {
            if (!elements.TryGetValue(id,out var e) || e.Id==wall.Id || e.CategoryId!=-2000011
                || e.Location is not { CurveType: "Line", ArcRadius: null } loc
                || !Point(loc.StartPoint) || !Point(loc.EndPoint)) continue;
            var p=Project(loc.StartPoint); var q=Project(loc.EndPoint);
            if (p.X==b && q.X==b && p.Z==sill && q.Z==sill && p.Y!=q.Y
                && (p==(b,0,sill) || q==(b,0,sill))) neighbours.Add(e);
        }
        if (neighbours.Count!=1) return Reject("join-ambiguity");
        var neighbour=neighbours[0];
        if (wall.References!.Count(id=>id==neighbour.Id)!=1
            || neighbour.References?.Count(id=>id==wall.Id)!=1 || !NoOtherCuts(neighbour)
            || neighbour.CuttingElementIds is not { Count: 0 }
            || !TryGetSerializedWallWidthFeet(neighbour,out double neighbourWidth)
            || !(neighbourWidth>0) || !double.IsFinite(neighbourWidth)
            || neighbour.Geometry is not { Faces: { Count: 11 } nf,
                BrepSolids: [{ IsClosed: false } ns], BoundingBox: { Length: 6 } nb }
            || !ns.FaceIndices.SequenceEqual(Enumerable.Range(0,6))) return Reject("join-authority");
        for (int i=0;i<11;i++)
            if (nf[i].OuterVertices is not { Count: 4 } || !nf[i].OuterVertices!.All(Point)
                || nf[i].InnerVertices is { Count: > 0 }
                || (nf[i].AlternativeOuterVertices?.Count??0)!=(i==5?5:0)
                || nf[i].AlternativeOuterVertices?.Any(p=>!Point(p))==true) return Reject("join-face");
        var nc=nf[1].OuterVertices!.Select(Project).ToArray();
        long j0=nc.Min(p=>p.X),j1=nc.Max(p=>p.X),y0=nc.Min(p=>p.Y),y1=nc.Max(p=>p.Y);
        long band=nf[4].OuterVertices!.Select(Project).Min(p=>p.Z);
        var far=Project(neighbour.Location!.StartPoint);
        if (far.Y==0) far=Project(neighbour.Location.EndPoint);
        if (j0!=notch || j1-b!=b-j0 || j1-j0!=Key(neighbourWidth)
            || y0!=n || y1!=far.Y-m || y1<=m || !(bottom<band && band<head)
            || !BoundsMatchAtIfcPrecision(nb,Bounds(nf.SelectMany(f=>f.OuterVertices!)))
            || neighbour.BoundingBox is not { Length: 6 } eb || !BoundsMatchAtIfcPrecision(nb,eb)
            || !WallVerticalParametersMatchSerializedBounds(neighbour,neighbour.Location,nb)
            || !TryGetExactWallVerticalParameterDefinition(neighbour,nb,out double jb,out double jt)
            || Key(jb)!=bottom || Key(jt)!=head) return Reject("join-intersection");
        (long X,long Y,long Z)[] JoinSide(long x,long lo,long hi,long z0,long z1) =>
            [(x,lo,z0),(x,hi,z0),(x,hi,z1),(x,lo,z1)];
        (long X,long Y,long Z)[] JoinCap(long z) =>
            [(j0,y0,z),(j1,y0,z),(j1,y1,z),(j0,y1,z)];
        (long X,long Y,long Z)[] JoinEnd(long y,long z0,long z1) => Side(j0,j1,y,z0,z1);
        var joinCore = new (long X,long Y,long Z)[][]
        {
            JoinSide(j0,y0,y1,bottom,head),JoinCap(bottom),JoinSide(j1,y0,y1,bottom,head),
            JoinCap(head),JoinEnd(y1,band,head),JoinEnd(y0,band,head),
        };
        if (Enumerable.Range(0,6).Any(i=>!Cycle(nf[i].OuterVertices,joinCore[i]))
            || !Cycle(nf[5].AlternativeOuterVertices,(j1,y0,bottom),(j0,y0,bottom),
                (j0,y0,head),(b,y0,head),(j1,y0,head))) return Reject("join-core");
        long previous=y1;
        for (int i=6;i<11;i++)
        {
            var sheet=nf[i].OuterVertices!.Select(Project).ToArray();
            long lo=sheet.Min(p=>p.Y),hi=sheet.Max(p=>p.Y);
            if (!(y0<lo && lo<hi && hi<y1) || (i>6 && hi!=previous)
                || !Cycle(nf[i].OuterVertices,JoinSide(j1,lo,hi,bottom,band))) return Reject("join-sheet");
            previous=lo;
        }
        if (!TryBuildStraightWallBoundary(neighbour,out var joined) || joined.Faces.Count!=6
            || joined.BrepSolids is not [{ IsClosed: true } js]
            || !js.FaceIndices.SequenceEqual(Enumerable.Range(0,6))) return Reject("join-rebuilt");
        var joinedCycles=joinCore.Take(4).Concat(new[] { JoinEnd(y0,bottom,head),JoinEnd(y1,bottom,head) }).ToArray();
        if (joined.Faces.Any(f=>f.InnerVertices is { Count: > 0 } || f.AlternativeOuterVertices is { Count: > 0 })
            || joinedCycles.Any(c=>joined.Faces.Count(f=>Cycle(f.OuterVertices,c))!=1)
            || joined.Faces.Any(f=>joinedCycles.Count(c=>Cycle(f.OuterVertices,c))!=1)
            || !IsExactFacetedShell(joined.Faces,js.FaceIndices)) return Reject("join-rebuilt-cycles");

        if (wall.CuttingElementIds is not [int cutterId] || cutterId<=0
            || wall.References!.Count(id=>id==cutterId)!=1
            || !elements.TryGetValue(cutterId,out var cutter) || cutter.Id!=cutterId
            || cutter.CategoryId!=-2000023 || cutter.SerializedHostId!=wall.Id
            || cutter.SuperInstanceId is >0 || cutter.References?.Count(id=>id==wall.Id)!=1
            || cutter.FamilyCutGeometry!=null || cutter.FamilyCutLoops is { Count: >0 }
            || emittedIds==null || !emittedIds.TryGetValue(wall.Id,out var ids) || ids is not [int emittedId] || emittedId!=cutterId
            || emittedOperands==null || !emittedOperands.TryGetValue(wall.Id,out var operands)
            || operands.Count!=1 || operands[0].CutterId!=cutterId
            || standaloneIds==null || standaloneIds.TryGetValue(wall.Id,out var standalone) && standalone.Count!=0)
            return Reject("door-authority");
        var op=operands[0].Operand;
        if (op.Boundary!=null || op.SteppedProfile!=null || op.IsFamilyCutLoop
            || !(op.WidthFt>0) || !(op.DepthFt>0) || !(op.HeightFt>0)
            || new[] { op.CentreXFt,op.CentreYFt,op.AxisX,op.AxisY,op.WidthFt,op.DepthFt,op.BaseZFt,op.HeightFt }
                .Any(v=>!double.IsFinite(v) || !CanMapFeetToIfcPrecisionBin(v))
            || Math.Abs(op.AxisX*op.AxisX+op.AxisY*op.AxisY-1)>8192*2.2204460492503131e-16)
            return Reject("door-operand");
        var corners=new List<(long X,long Y,long Z)>();
        foreach(double x in new[] {-op.WidthFt/2,op.WidthFt/2})
        foreach(double y in new[] {-op.DepthFt/2,op.DepthFt/2})
        foreach(double z in new[] {op.BaseZFt,op.BaseZFt+op.HeightFt})
            corners.Add(Project([op.CentreXFt+x*op.AxisX-y*op.AxisY,op.CentreYFt+x*op.AxisY+y*op.AxisX,z]));
        long c0=corners.Min(p=>p.Y),c1=corners.Max(p=>p.Y);
        if (c0>n || c1<m || corners.Distinct().Count()!=8 || !corners.ToHashSet().SetEquals(
            from x in new[] {left,right} from y in new[] {c0,c1} from z in new[] {sill,lintel} select (x,y,z)))
            return Reject("door-intersection");

        var upper=faces[3].OuterVertices!;
        var lower=upper.Select(p=>new[] {p[0],p[1],bounds[2]}).ToList();
        var grossFaces=new List<GeoFace> { new() {OuterVertices=lower},new() {OuterVertices=upper} };
        for(int i=0;i<4;i++) grossFaces.Add(new() {OuterVertices=[lower[i],lower[(i+1)%4],upper[(i+1)%4],upper[i]]});
        var indices=Enumerable.Range(0,6).ToList();
        if (!TryOrientExactFacetedShell(grossFaces,indices,out var oriented)) return Reject("gross-orientation");
        var gross=new GeometryData {Faces=oriented,BoundingBox=Bounds(lower.Concat(upper)),
            BrepSolids=[new() {IsClosed=true,FaceIndices=indices}]};
        if (!WallVerticalParametersMatchSerializedBounds(wall,location,bounds)
            || !TryGetExactWallVerticalParameterDefinition(wall,bounds,out double baseZ,out double topZ)
            || Key(baseZ)!=bottom || Key(topZ)!=top
            || !TryGetExactStraightWallVerticalExtrusionDefinition(gross,location,width,gross.BoundingBox,
                out var plan,out _,out _,out string reason) || reason!="exact" || plan.Count!=4
            || !IsExactFacetedShell(oriented,indices)) return Reject("gross-definition");
        grossBoundary=gross; cutterIds=[cutterId];
        if (diagnostics) DiagnosticSink.WriteLine($"IFCJOINNOTCHGATE wall={wall.Id} result=accept neighbour={neighbour.Id}");
        return true;
    }

    /// <summary>Both opening boxes are fully owned by six surviving source faces.</summary>
    internal static bool TryGetVerifiedGrossWallBoundaryFromTwentyNineFaceInsetCapsAndSideSheets(
        Element wall, IReadOnlyList<double> bounds, GeometryData rebuilt,
        IReadOnlyDictionary<int, Element> elements,
        IReadOnlyDictionary<int, List<int>> inverseHosts,
        IReadOnlyDictionary<int, List<int>>? emittedIds,
        IReadOnlyDictionary<int, List<(int CutterId, HostedOpeningGeometry Operand)>>? emittedOperands,
        IReadOnlyDictionary<int, List<int>>? standaloneIds,
        out GeometryData grossBoundary, out IReadOnlyList<int> cutterIds)
    {
        grossBoundary = new GeometryData();
        cutterIds = [];
        bool diagnostics = (Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") ?? "")
            .Split(',', StringSplitOptions.TrimEntries).Contains(wall.Id.ToString());
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine($"IFC29INSETCAPSHEETGATE wall={wall.Id} result=reject stage={stage}");
            return false;
        }
        bool Point(double[]? p) => p is { Length: 3 }
            && p.All(v => double.IsFinite(v) && CanMapFeetToIfcPrecisionBin(v));
        if (wall.Id <= 0 || wall.CategoryId != -2000011
            || wall.Location is not { CurveType: "Line", ArcRadius: null } location
            || !Point(location.StartPoint) || !Point(location.EndPoint)
            || bounds.Count != 6 || bounds.Any(v => !double.IsFinite(v) || !CanMapFeetToIfcPrecisionBin(v))
            || !TryGetSerializedWallWidthFeet(wall, out double width) || !(width > 0)
            || !CanMapFeetToIfcPrecisionBin(width)
            || wall.Geometry is not { Faces: { Count: 29 } faces,
                BrepSolids: [{ IsClosed: false } sourceSolid], BoundingBox: { Length: 6 } sourceBounds }
            || !sourceSolid.FaceIndices.SequenceEqual(Enumerable.Range(0, 29))
            || !BoundsMatchAtIfcPrecision(bounds, sourceBounds)
            || wall.FamilyCutGeometry != null || wall.FamilyCutLoops is { Count: > 0 }
            || wall.FamilyCutClosurePlaneOrigin != null || wall.FamilyCutClosurePlaneNormal != null)
            return Reject("source-authority");
        for (int i = 0; i < faces.Count; i++)
        {
            int count = i == 0 ? 6 : i is 21 or 22 or 27 or 28 ? 5 : 4;
            var face = faces[i];
