            value = double.NaN;
            var claims = cutter.Parameters.Where(p => p.Guid == guid
                || BipHelpers.ParseGuidFromForgeId(p.ForgeId ?? "") == guid).ToList();
            if (claims.Count != 1) return false;
            var claim = claims[0];
            if (claim.Id <= 0 || claim.StorageType != StorageType.Double
                || claim.ForgeId?.StartsWith("autodesk.parameter.aec.revit.external.-1:", StringComparison.Ordinal) != true
                || BipHelpers.ParseGuidFromForgeId(claim.ForgeId) != guid
                || claim.Guid is { } other && other != guid
                || claim.SpecType != null && !claim.SpecType.Contains(":length", StringComparison.OrdinalIgnoreCase)
                || claim.Value is not double number || !(number > 0)
                || !double.IsFinite(number) || !CanMapFeetToIfcPrecisionBin(number)) return false;
            value = number;
            return true;
        }
        var matched = new HashSet<int>();
        foreach (var (id, operand) in operands)
        {
            if (!elements.TryGetValue(id, out var cutter) || cutter.CategoryId != -2000151
                || cutter.SuperInstanceId is > 0 || cutter.References?.Count(r => r == wall.Id) != 1
                || !inverseHosts.TryGetValue(id, out var hosts) || hosts.Count(h => h == wall.Id) != 1
                || hosts.Distinct().Count() != hosts.Count
                || !operand.ExactDepth || operand.Boundary != null || operand.SteppedProfile != null
                || operand.IsFamilyCutLoop || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
                || !(operand.HeightFt > 0)
                || Math.Abs(operand.AxisX * operand.AxisX + operand.AxisY * operand.AxisY - 1)
                    > 8192 * 2.2204460492503131e-16
                || new[] { operand.CentreXFt, operand.CentreYFt, operand.AxisX, operand.AxisY,
                    operand.WidthFt, operand.DepthFt, operand.BaseZFt, operand.HeightFt }
                    .Any(v => !double.IsFinite(v) || !CanMapFeetToIfcPrecisionBin(v)))
                return Reject("cutter-authority");
            // Compare actual writer corners, not only Width/Depth, so swapped or rotated axes
            // cannot silently satisfy the projected source size constraints.
            var corners = new List<double[]>();
            foreach (double x in new[] { -operand.WidthFt / 2, operand.WidthFt / 2 })
                foreach (double y in new[] { -operand.DepthFt / 2, operand.DepthFt / 2 })
                    foreach (double z in new[] { operand.BaseZFt, operand.BaseZFt + operand.HeightFt })
                        corners.Add([operand.CentreXFt + x * operand.AxisX - y * operand.AxisY,
                            operand.CentreYFt + x * operand.AxisY + y * operand.AxisX, z]);
            var actual = corners.Select(Project).ToHashSet();
            bool Matches(long low, long high, long lowZ, long highZ) => actual.Count == 8 && actual.SetEquals(
                from x in new[] { low, high }
                from y in new[] { n, m }
                from z in new[] { lowZ, highZ }
                select (x,y,z));
            // All six faces of the interior cutter survive in the source.
            bool interiorMatches = Matches(left, right, holeBottom, holeTop);
            // The end notch's retained side stops at the wall cap.
            bool endMatches = ExactLength(cutter, new Guid("cef807ab-6704-4013-8d86-96c5a31b2d1e"), out double ownWidth)
                && ExactLength(cutter, new Guid("e140a591-7a59-4036-b7e4-074fbd8222ff"), out double ownDepth)
                && ExactLength(cutter, new Guid("e31864ac-8135-4bea-a7d3-f2a96b81a6ea"), out double ownHeight)
                && Key(operand.WidthFt) == Key(ownWidth) && Key(operand.DepthFt) == Key(ownDepth)
                && Key(operand.HeightFt) == Key(ownHeight)
                && end - Key(ownWidth) < a - 2
                && Matches(end - Key(ownWidth), end, sill, head);
            if (interiorMatches == endMatches || !matched.Add(interiorMatches ? 1 : 0))
                return Reject("source-writer-bijection");
        }
        grossBoundary = gross;
        cutterIds = decoded.ToArray();
        if (diagnostics)
            DiagnosticSink.WriteLine($"IFCFOURTEENFACEDUALCAPGATE wall={wall.Id} result=accept stage=source-caps-cycles-two-writer-boxes");
        return true;
    }

    /// <summary>
    /// Recovers the gross rectangle from the complete 52-face source pathology only when its two
    /// exact cap cycles, four-solid topology, nine-face rebuilt shell, two decoded cutters and
    /// every materialized inverse-host operand form one exact writer-lattice contract.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromCompleteOpenFiftyTwoFaceInsetCapsAndTwoExactOpenings(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlySet<int> visibleWallIds,
            IReadOnlyDictionary<int, List<int>> inverseHostedHostIds,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData grossBoundary,
            out IReadOnlyList<int> cutterElementIds)
    {
        grossBoundary = new GeometryData();
        cutterElementIds = [];
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1"
            || Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, IEnumerable<int>? rejectedIds = null)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOMPLETE52INSETCAPTWOGATE wall={wall.Id} "
                    + $"cutters={string.Join(',', rejectedIds ?? [])} "
                    + $"result=reject stage={stage}");
            return false;
        }

        bool ExactPoint(double[]? point) =>
            point is { Length: >= 3 }
            && point.Take(3).All(double.IsFinite)
            && CanMapFeetToIfcPrecisionBin(point[0])
            && CanMapFeetToIfcPrecisionBin(point[1])
            && CanMapFeetToIfcPrecisionBin(point[2]);

        static ((long X, long Y, long Z) A,
                (long X, long Y, long Z) B) Edge(
            (long X, long Y, long Z) first,
            (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);

        HashSet<((long X, long Y, long Z) A,
            (long X, long Y, long Z) B)> CycleEdges(
                IReadOnlyList<double[]> ring)
        {
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return Enumerable.Range(0, keys.Count)
                .Select(index => Edge(
                    keys[index], keys[(index + 1) % keys.Count]))
                .ToHashSet();
        }

        bool ExactRing(IReadOnlyList<double[]>? ring)
        {
            if (ring is not { Count: >= 3 }
                || ring.Any(point => !ExactPoint(point)))
                return false;
            var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
            return keys.Distinct().Count() == ring.Count
                && CycleEdges(ring).Count == ring.Count
                && FaceCanEmitAtIfcPrecision(
                    new GeoFace { OuterVertices = ring.ToList() });
        }

        bool TryGetTopology(
            IReadOnlyList<GeoFace> faces,
            IReadOnlyList<int> faceIndices,
            out int vertexCount,
            out Dictionary<int, int> edgeOwnerCounts,
            out List<int> componentSizes)
        {
            vertexCount = 0;
            edgeOwnerCounts = [];
            componentSizes = [];
            var vertices = new HashSet<(long X, long Y, long Z)>();
            var owners = new Dictionary<(
                (long X, long Y, long Z) A,
                (long X, long Y, long Z) B), List<int>>();
            var edgesByFace = new Dictionary<int, HashSet<(
                (long X, long Y, long Z) A,
                (long X, long Y, long Z) B)>>();
            foreach (int faceIndex in faceIndices)
            {
                if (faceIndex < 0 || faceIndex >= faces.Count
                    || !ExactRing(faces[faceIndex].OuterVertices))
                    return false;
                var ring = faces[faceIndex].OuterVertices!;
                foreach (double[] point in ring)
                    vertices.Add(IfcPrecisionKeyFeet(point));
                var edges = CycleEdges(ring);
                edgesByFace[faceIndex] = edges;
                foreach (var edge in edges)
                {
                    if (!owners.TryGetValue(edge, out var edgeOwners))
                        owners[edge] = edgeOwners = [];
                    edgeOwners.Add(faceIndex);
                }
            }

            var remaining = faceIndices.ToHashSet();
            while (remaining.Count > 0)
            {
                int seed = remaining.Min();
                remaining.Remove(seed);
                int size = 0;
                var queue = new Queue<int>();
                queue.Enqueue(seed);
                while (queue.Count > 0)
                {
                    int current = queue.Dequeue();
                    size++;
                    foreach (int candidate in remaining.ToList())
                    {
                        if (!edgesByFace[current].Overlaps(
                                edgesByFace[candidate]))
                            continue;
                        remaining.Remove(candidate);
                        queue.Enqueue(candidate);
                    }
                }
                componentSizes.Add(size);
            }
            componentSizes.Sort((first, second) => second.CompareTo(first));
            vertexCount = vertices.Count;
            edgeOwnerCounts = owners.Values.GroupBy(value => value.Count)
                .ToDictionary(group => group.Key, group => group.Count());
            return true;
        }

        static bool OwnerCountsMatch(
            IReadOnlyDictionary<int, int> actual,
            params (int Owners, int Count)[] expected) =>
            actual.Count == expected.Length
            && expected.All(item => actual.TryGetValue(
                item.Owners, out int count) && count == item.Count);

        if (wall.Id <= 0
            || bounds.Count < 6
            || bounds.Take(6).Any(value => !double.IsFinite(value)
                || !CanMapFeetToIfcPrecisionBin(value))
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !ExactPoint(location.StartPoint)
            || !ExactPoint(location.EndPoint)
            || !TryGetSerializedWallWidthFeet(
                wall, out double wallWidthFt)
            || !(wallWidthFt > 0) || !double.IsFinite(wallWidthFt)
            || !CanMapFeetToIfcPrecisionBin(wallWidthFt)
            || wall.Geometry is not
                {
                    Faces: { Count: 52 } sourceFaces,
                    BrepSolids: { Count: 4 } sourceSolids,
                    BoundingBox: { Length: 6 } sourceBounds,
                }
            || !BoundsMatchAtIfcPrecision(sourceBounds, bounds))
            return Reject("source-authority");

        int[][] exactSourceSolidIndices =
        [
            Enumerable.Range(0, 21)
                .Concat(Enumerable.Range(33, 14)).ToArray(),
            Enumerable.Range(21, 6).ToArray(),
            Enumerable.Range(27, 6).ToArray(),
            Enumerable.Range(47, 5).ToArray(),
        ];
        bool[] exactSourceSolidClosure = [false, true, true, false];
        if (Enumerable.Range(0, sourceSolids.Count).Any(index =>
                sourceSolids[index].IsClosed
                    != exactSourceSolidClosure[index]
                || !sourceSolids[index].FaceIndices.SequenceEqual(
                    exactSourceSolidIndices[index]))
            || sourceSolids.SelectMany(solid => solid.FaceIndices).Count()
                != sourceFaces.Count
            || sourceSolids.SelectMany(solid => solid.FaceIndices)
                .Distinct().Count() != sourceFaces.Count)
            return Reject("source-solid-roster");

        var expectedAlternativeArities = new Dictionary<int, int>
        {
            [0] = 7, [11] = 5, [12] = 5, [16] = 5, [20] = 7,
        };
        for (int index = 0; index < sourceFaces.Count; index++)
        {
            GeoFace face = sourceFaces[index];
            int expectedOuterArity = index is 33 or 34 ? 3
                : index is 36 or 42 ? 6 : 4;
            if (face.OuterVertices?.Count != expectedOuterArity
                || !ExactRing(face.OuterVertices)
                || face.InnerVertices is { Count: > 0 })
                return Reject($"source-face-{index}");
            if (expectedAlternativeArities.TryGetValue(index, out int arity)
                ? face.AlternativeOuterVertices?.Count != arity
                    || !ExactRing(face.AlternativeOuterVertices)
                : face.AlternativeOuterVertices is { Count: > 0 })
                return Reject($"source-alternative-{index}");
        }

        if (!TryGetTopology(sourceFaces, exactSourceSolidIndices[0],
                out int firstSourceVertexCount,
                out var firstSourceOwnerCounts,
                out var firstSourceComponents)
            || firstSourceVertexCount != 62
            || !OwnerCountsMatch(firstSourceOwnerCounts,
                (1, 38), (2, 46), (3, 4))
            || !firstSourceComponents.SequenceEqual(
                [16, 6, 5, 3, 1, 1, 1, 1, 1])
            || !TryGetTopology(sourceFaces, exactSourceSolidIndices[1],
                out int secondSourceVertexCount,
                out var secondSourceOwnerCounts,
                out var secondSourceComponents)
            || secondSourceVertexCount != 8
            || !OwnerCountsMatch(secondSourceOwnerCounts, (2, 12))
            || !secondSourceComponents.SequenceEqual([6])
            || !TryGetTopology(sourceFaces, exactSourceSolidIndices[2],
                out int thirdSourceVertexCount,
                out var thirdSourceOwnerCounts,
                out var thirdSourceComponents)
            || thirdSourceVertexCount != 8
            || !OwnerCountsMatch(thirdSourceOwnerCounts, (2, 12))
            || !thirdSourceComponents.SequenceEqual([6])
            || !TryGetTopology(sourceFaces, exactSourceSolidIndices[3],
                out int fourthSourceVertexCount,
                out var fourthSourceOwnerCounts,
                out var fourthSourceComponents)
            || fourthSourceVertexCount != 8
            || !OwnerCountsMatch(fourthSourceOwnerCounts,
                (1, 4), (2, 8))
            || !fourthSourceComponents.SequenceEqual([5]))
            return Reject("source-topology");

        if (rebuiltBoundary.Faces is not { Count: 9 } rebuiltFaces
            || rebuiltBoundary.BrepSolids is not
                [{ IsClosed: true } rebuiltSolid]
            || !rebuiltSolid.FaceIndices.SequenceEqual(
                Enumerable.Range(0, rebuiltFaces.Count))
            || rebuiltBoundary.BoundingBox is not
                { Length: 6 } rebuiltBounds
            || !BoundsMatchAtIfcPrecision(rebuiltBounds, sourceBounds)
            || rebuiltFaces.Count(face =>
                face.OuterVertices?.Count == 7) != 2
            || rebuiltFaces.Count(face =>
                face.OuterVertices?.Count == 4) != 7
            || rebuiltFaces.Any(face =>
                !ExactRing(face.OuterVertices)
                || face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
            || !TryGetTopology(rebuiltFaces, rebuiltSolid.FaceIndices,
                out int rebuiltVertexCount,
                out var rebuiltOwnerCounts,
                out var rebuiltComponents)
            || rebuiltVertexCount != 14
            || !OwnerCountsMatch(rebuiltOwnerCounts, (2, 21))
            || !rebuiltComponents.SequenceEqual([9]))
            return Reject("rebuilt-topology");

        double axisX = location.EndPoint[0] - location.StartPoint[0];
        double axisY = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        if (!(axisLength > wallWidthFt) || !double.IsFinite(axisLength))
            return Reject("wall-axis");
        axisX /= axisLength;
        axisY /= axisLength;
        double normalX = -axisY;
        double normalY = axisX;
        long ProjectionKey(double valueFt) =>
            IfcPrecisionBinMetres(valueFt * FeetToMetres);
        (long Along, long Normal, long Z) Project(double[] point) =>
            (ProjectionKey(point[0] * axisX + point[1] * axisY),
             ProjectionKey(point[0] * normalX + point[1] * normalY),
             ProjectionKey(point[2]));

        bool ProjectedCycleMatches(
            IReadOnlyList<double[]> ring,
            IReadOnlyList<(long Along, long Normal, long Z)> expected)
        {
            var actualKeys = ring.Select(Project).ToList();
            var expectedKeys = expected.ToList();
            if (actualKeys.Count != expectedKeys.Count
                || !actualKeys.ToHashSet().SetEquals(expectedKeys))
                return false;
            var actualEdges = Enumerable.Range(0, actualKeys.Count)
                .Select(index => Edge(actualKeys[index],
                    actualKeys[(index + 1) % actualKeys.Count]))
                .ToHashSet();
            var expectedEdges = Enumerable.Range(0, expectedKeys.Count)
                .Select(index => Edge(expectedKeys[index],
                    expectedKeys[(index + 1) % expectedKeys.Count]))
                .ToHashSet();
            return actualEdges.SetEquals(expectedEdges);
        }

        bool ProjectedBoxMatches(IReadOnlyList<int> faceIndices)
        {
            var boxFaces = faceIndices.Select(index => sourceFaces[index])
                .ToList();
            if (boxFaces.Count != 6 || boxFaces.Any(face =>
                    face.OuterVertices is not { Count: 4 }))
                return false;
            var keys = boxFaces.SelectMany(face => face.OuterVertices!)
                .Select(Project).Distinct().ToList();
            var along = keys.Select(key => key.Along)
                .Distinct().Order().ToList();
            var normal = keys.Select(key => key.Normal)
                .Distinct().Order().ToList();
            var z = keys.Select(key => key.Z)
                .Distinct().Order().ToList();
            if (keys.Count != 8 || along.Count != 2
                || normal.Count != 2 || z.Count != 2)
                return false;
            var expectedCorners = (
                from alongValue in along
                from normalValue in normal
                from zValue in z
                select (Along: alongValue, Normal: normalValue, Z: zValue))
                .ToHashSet();
            if (!keys.ToHashSet().SetEquals(expectedCorners))
                return false;
            var expectedCycles = new List<IReadOnlyList<(
                long Along, long Normal, long Z)>>();
            foreach (long alongValue in along)
                expectedCycles.Add(
                [
                    (alongValue, normal[0], z[0]),
                    (alongValue, normal[1], z[0]),
                    (alongValue, normal[1], z[1]),
                    (alongValue, normal[0], z[1]),
                ]);
            foreach (long normalValue in normal)
                expectedCycles.Add(
                [
                    (along[0], normalValue, z[0]),
                    (along[1], normalValue, z[0]),
                    (along[1], normalValue, z[1]),
                    (along[0], normalValue, z[1]),
                ]);
            foreach (long zValue in z)
                expectedCycles.Add(
                [
                    (along[0], normal[0], zValue),
                    (along[1], normal[0], zValue),
                    (along[1], normal[1], zValue),
                    (along[0], normal[1], zValue),
                ]);
            return expectedCycles.All(expected => boxFaces.Count(face =>
                    ProjectedCycleMatches(
                        face.OuterVertices!, expected)) == 1)
                && boxFaces.All(face => expectedCycles.Count(expected =>
                    ProjectedCycleMatches(
                        face.OuterVertices!, expected)) == 1);
        }

        if (!ProjectedBoxMatches(exactSourceSolidIndices[1])
            || !ProjectedBoxMatches(exactSourceSolidIndices[2]))
            return Reject("source-closed-insert-lattice");

        var rebuiltProjected = rebuiltFaces
            .SelectMany(face => face.OuterVertices!)
            .Select(Project).ToList();
        var rebuiltAlong = rebuiltProjected.Select(point => point.Along)
            .Distinct().Order().ToList();
        var rebuiltNormal = rebuiltProjected.Select(point => point.Normal)
            .Distinct().Order().ToList();
        var rebuiltZ = rebuiltProjected.Select(point => point.Z)
            .Distinct().Order().ToList();
        var rebuiltSideProfiles = rebuiltFaces.Where(face =>
                face.OuterVertices is { Count: 7 } ring
                && ring.Select(Project).Select(point => point.Normal)
                    .Distinct().Count() == 1)
            .ToList();
        if (rebuiltAlong.Count != 2
            || rebuiltNormal.Count != 2
            || rebuiltZ.Count != 5
            || rebuiltSideProfiles.Count != 2
            || rebuiltSideProfiles.Select(face =>
                    Project(face.OuterVertices![0]).Normal)
                .Distinct().Count() != 2)
            return Reject("rebuilt-projected-topology");

        long minimumAlong = rebuiltAlong[0];
        long maximumAlong = rebuiltAlong[1];
        long minimumNormal = rebuiltNormal[0];
        long maximumNormal = rebuiltNormal[1];
        long minimumZ = rebuiltZ[0];
        long firstStepZ = rebuiltZ[1];
        long secondStepZ = rebuiltZ[2];
        long thirdStepZ = rebuiltZ[3];
        long maximumZ = rebuiltZ[4];
        var expectedSideCycles = rebuiltNormal.Select(normal =>
            (IReadOnlyList<(long Along, long Normal, long Z)>)
            new List<(long Along, long Normal, long Z)>
            {
                (minimumAlong, normal, minimumZ),
                (maximumAlong, normal, minimumZ),
                (maximumAlong, normal, firstStepZ),
                (maximumAlong, normal, thirdStepZ),
                (maximumAlong, normal, secondStepZ),
                (maximumAlong, normal, maximumZ),
                (minimumAlong, normal, maximumZ),
            }).ToList();
        var rebuiltQuads = rebuiltFaces.Where(face =>
            face.OuterVertices is { Count: 4 }).ToList();
        var expectedQuadCycles = new List<IReadOnlyList<(
            long Along, long Normal, long Z)>>
        {
            new List<(long Along, long Normal, long Z)>
            {
                (minimumAlong, minimumNormal, minimumZ),
                (maximumAlong, minimumNormal, minimumZ),
                (maximumAlong, maximumNormal, minimumZ),
                (minimumAlong, maximumNormal, minimumZ),
            },
            new List<(long Along, long Normal, long Z)>
            {
                (maximumAlong, minimumNormal, minimumZ),
                (maximumAlong, maximumNormal, minimumZ),
                (maximumAlong, maximumNormal, firstStepZ),
                (maximumAlong, minimumNormal, firstStepZ),
            },
            new List<(long Along, long Normal, long Z)>
            {
                (maximumAlong, minimumNormal, firstStepZ),
                (maximumAlong, maximumNormal, firstStepZ),
                (maximumAlong, maximumNormal, thirdStepZ),
                (maximumAlong, minimumNormal, thirdStepZ),
            },
            new List<(long Along, long Normal, long Z)>
            {
                (maximumAlong, minimumNormal, thirdStepZ),
                (maximumAlong, maximumNormal, thirdStepZ),
                (maximumAlong, maximumNormal, secondStepZ),
                (maximumAlong, minimumNormal, secondStepZ),
            },
            new List<(long Along, long Normal, long Z)>
            {
                (maximumAlong, minimumNormal, secondStepZ),
                (maximumAlong, maximumNormal, secondStepZ),
                (maximumAlong, maximumNormal, maximumZ),
                (maximumAlong, minimumNormal, maximumZ),
            },
            new List<(long Along, long Normal, long Z)>
            {
                (minimumAlong, minimumNormal, maximumZ),
                (maximumAlong, minimumNormal, maximumZ),
                (maximumAlong, maximumNormal, maximumZ),
                (minimumAlong, maximumNormal, maximumZ),
            },
            new List<(long Along, long Normal, long Z)>
            {
                (minimumAlong, minimumNormal, minimumZ),
                (minimumAlong, maximumNormal, minimumZ),
                (minimumAlong, maximumNormal, maximumZ),
                (minimumAlong, minimumNormal, maximumZ),
            },
        };
        if (expectedSideCycles.Any(expected =>
                rebuiltSideProfiles.Count(face => ProjectedCycleMatches(
                    face.OuterVertices!, expected)) != 1)
            || rebuiltSideProfiles.Any(face => expectedSideCycles.Count(
                expected => ProjectedCycleMatches(
                    face.OuterVertices!, expected)) != 1)
            || expectedQuadCycles.Any(expected =>
                rebuiltQuads.Count(face => ProjectedCycleMatches(
                    face.OuterVertices!, expected)) != 1)
            || rebuiltQuads.Any(face => expectedQuadCycles.Count(expected =>
                ProjectedCycleMatches(face.OuterVertices!, expected)) != 1))
            return Reject("rebuilt-strip-cycle-bijection");

        if (!ProjectedCycleMatches(sourceFaces[0].AlternativeOuterVertices!,
                expectedSideCycles[0])
            || !ProjectedCycleMatches(sourceFaces[20].AlternativeOuterVertices!,
            [
                (maximumAlong, maximumNormal, minimumZ),
                (maximumAlong, minimumNormal, minimumZ),
                (maximumAlong, minimumNormal, maximumZ),
                (maximumAlong, minimumNormal, secondStepZ),
                (maximumAlong, minimumNormal, firstStepZ),
                (maximumAlong, maximumNormal, firstStepZ),
                (maximumAlong, maximumNormal, maximumZ),
            ]))
            return Reject("source-rebuilt-alternative-cycles");

        var lowerCap = sourceFaces[2].OuterVertices!;
        var upperCap = sourceFaces[6].OuterVertices!;
        if (lowerCap.Count != 4 || upperCap.Count != 4)
            return Reject("source-caps");
        var lowerKeys = lowerCap.Select(IfcPrecisionKeyFeet).ToList();
        var upperKeys = upperCap.Select(IfcPrecisionKeyFeet).ToList();
        var lowerXy = lowerKeys.Select(key => (key.X, key.Y)).ToHashSet();
        var upperXy = upperKeys.Select(key => (key.X, key.Y)).ToHashSet();
        var lowerZ = lowerKeys.Select(key => key.Z).Distinct().ToList();
        var upperZ = upperKeys.Select(key => key.Z).Distinct().ToList();
        long minimumBoundZ = ProjectionKey(sourceBounds[2]);
        long maximumBoundZ = ProjectionKey(sourceBounds[5]);
        if (!lowerXy.SetEquals(upperXy)
            || lowerZ.Count != 1 || lowerZ[0] != minimumBoundZ
            || upperZ.Count != 1 || upperZ[0] != maximumBoundZ
            || maximumBoundZ - minimumBoundZ <= 2
            || !rebuiltFaces.Any(face =>
                CycleEdges(face.OuterVertices!)
                    .SetEquals(CycleEdges(lowerCap)))
            || !rebuiltFaces.Any(face =>
                CycleEdges(face.OuterVertices!)
                    .SetEquals(CycleEdges(upperCap))))
            return Reject("source-rebuilt-caps");

        var capProjected = lowerCap.Select(Project).ToList();
        var capAlong = capProjected.Select(point => point.Along)
            .Distinct().Order().ToList();
        var capNormal = capProjected.Select(point => point.Normal)
            .Distinct().Order().ToList();
        long startAlong = ProjectionKey(
            location.StartPoint[0] * axisX
            + location.StartPoint[1] * axisY);
        long endAlong = ProjectionKey(
            location.EndPoint[0] * axisX
            + location.EndPoint[1] * axisY);
        long startNormal = ProjectionKey(
            location.StartPoint[0] * normalX
            + location.StartPoint[1] * normalY);
        long endNormal = ProjectionKey(
            location.EndPoint[0] * normalX
            + location.EndPoint[1] * normalY);
        long widthBin = ProjectionKey(wallWidthFt);
        long locationLengthBin = ProjectionKey(axisLength);
        if (capAlong.Count != 2 || capNormal.Count != 2
            || widthBin <= 2 || widthBin % 2 != 0
            || locationLengthBin - (capAlong[1] - capAlong[0])
                != widthBin
            || capAlong[0] - startAlong != widthBin / 2
            || endAlong - capAlong[1] != widthBin / 2
            || capNormal[1] - capNormal[0] != widthBin
            || startNormal != endNormal
            || capNormal[0] + capNormal[1] != 2 * startNormal)
            return Reject("source-inset-cap-lattice");

        var upperByXy = upperCap.ToDictionary(point =>
        {
            var key = IfcPrecisionKeyFeet(point);
            return (key.X, key.Y);
        });
        var rawGrossFaces = new List<GeoFace>
        {
            new()
            {
                OuterVertices = lowerCap
                    .Select(point => (double[])point.Clone()).ToList(),
            },
            new()
            {
                OuterVertices = upperCap
                    .Select(point => (double[])point.Clone()).ToList(),
            },
        };
        for (int index = 0; index < lowerCap.Count; index++)
        {
            double[] firstLower = lowerCap[index];
            double[] secondLower = lowerCap[(index + 1) % lowerCap.Count];
            var firstKey = IfcPrecisionKeyFeet(firstLower);
            var secondKey = IfcPrecisionKeyFeet(secondLower);
            rawGrossFaces.Add(new GeoFace
            {
                OuterVertices =
                [
                    (double[])firstLower.Clone(),
                    (double[])secondLower.Clone(),
                    (double[])upperByXy[(secondKey.X, secondKey.Y)].Clone(),
                    (double[])upperByXy[(firstKey.X, firstKey.Y)].Clone(),
                ],
            });
        }
        var grossIndices = Enumerable.Range(
            0, rawGrossFaces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                rawGrossFaces, grossIndices, out var orientedGrossFaces))
            return Reject("gross-orientation");
        var grossPoints = rawGrossFaces
            .SelectMany(face => face.OuterVertices!).ToList();
        double[] grossBounds =
        [
            grossPoints.Min(point => point[0]),
            grossPoints.Min(point => point[1]),
            grossPoints.Min(point => point[2]),
            grossPoints.Max(point => point[0]),
            grossPoints.Max(point => point[1]),
            grossPoints.Max(point => point[2]),
        ];
        var candidateGross = new GeometryData
        {
            BoundingBox = grossBounds,
            Faces = orientedGrossFaces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = grossIndices,
                    IsClosed = true,
                },
            ],
        };
        if (!BoundsMatchAtIfcPrecision(grossBounds, sourceBounds)
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, sourceBounds)
            || !TryGetExactWallVerticalParameterDefinition(
                wall, sourceBounds, out double baseZFt, out double topZFt)
            || ProjectionKey(baseZFt) != minimumBoundZ
            || ProjectionKey(topZFt) != maximumBoundZ
            || !IsExactFacetedShell(
                orientedGrossFaces, grossIndices)
            || !TryGetExactStraightWallVerticalExtrusionDefinition(
                candidateGross, location, wallWidthFt, sourceBounds,
                out var grossPlan, out double grossBaseZFt,
                out double grossHeightFt, out string grossReason)
            || grossReason != "exact" || grossPlan.Count != 4
            || ProjectionKey(grossBaseZFt) != minimumBoundZ
            || ProjectionKey(grossBaseZFt + grossHeightFt)
                != maximumBoundZ
            || !TryGetExactVerticalRectangularWallPlan(
                candidateGross, location, wallWidthFt, sourceBounds,
                out _, out _)
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                candidateGross, out _))
            return Reject("gross-definition");

        IReadOnlyList<int>? decodedIds = wall.CuttingElementIds;
        if (decodedIds is not { Count: 2 }
            || decodedIds.Any(id => id <= 0)
            || decodedIds.Distinct().Count() != 2
            || wall.References == null
            || decodedIds.Any(id =>
                wall.References.Count(reference => reference == id) != 1)
            || wall.FamilyCutGeometry != null
            || wall.FamilyCutClosurePlaneOrigin != null
            || wall.FamilyCutClosurePlaneNormal != null
            || wall.FamilyCutLoops is { Count: > 0 }
            || emittedHostedCutterIdsByWall == null
            || emittedHostedOpeningOperandsByWall == null
            || standaloneOpeningIdsByWall == null)
            return Reject("cutter-authority", decodedIds ?? []);

        if (!emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var targetEmittedIds)
            || targetEmittedIds.Count != 2
            || targetEmittedIds.Distinct().Count() != 2
            || !targetEmittedIds.ToHashSet().SetEquals(decodedIds)
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var targetEmittedOperands)
            || targetEmittedOperands.Count != 2
            || targetEmittedOperands.Select(item => item.CutterId)
                .Distinct().Count() != 2
            || !targetEmittedOperands.Select(item => item.CutterId)
                .ToHashSet().SetEquals(decodedIds))
            return Reject("target-emitted-bijection", decodedIds);

        var inverseSets = new List<(int CutterId, HashSet<int> HostIds)>();
        foreach (int cutterId in decodedIds)
        {
            if (!elemById.TryGetValue(cutterId, out var cutter)
                || cutter.CategoryId is not (-2000023 or -2000014)
                || cutter.SuperInstanceId is > 0
                || cutter.BoundingBox is not { Length: 6 } cutterBounds
                || cutterBounds.Any(value => !double.IsFinite(value))
                || !HostedElementCanCutHost(cutterBounds, wall)
                || !inverseHostedHostIds.TryGetValue(
                    cutterId, out var inverseHostIds)
                || inverseHostIds.Count != inverseHostIds.Distinct().Count()
                || !inverseHostIds.Contains(wall.Id))
                return Reject("cutter-graph", [cutterId]);
            var hostSet = inverseHostIds.ToHashSet();
            if (hostSet.Any(hostId =>
                    !visibleWallIds.Contains(hostId)
                    || !elemById.TryGetValue(hostId, out var host)
                    || host.CategoryId != -2000011
                    || SerializedHostCuttingElementIds(host)
                        .Count(id => id == cutterId) != 1
                    || !HostedElementCanCutHost(cutterBounds, host)))
                return Reject("inverse-host-authority", [cutterId]);
            inverseSets.Add((cutterId, hostSet));
        }
        var broadInverseSet = inverseSets
            .OrderByDescending(item => item.HostIds.Count).First();
        var narrowInverseSet = inverseSets
            .OrderBy(item => item.HostIds.Count).First();
        if (broadInverseSet.HostIds.Count != 12
            || narrowInverseSet.HostIds.Count != 5
            || broadInverseSet.CutterId == narrowInverseSet.CutterId
            || !narrowInverseSet.HostIds.IsProperSubsetOf(
                broadInverseSet.HostIds))
            return Reject("inverse-host-lattice", decodedIds);

        bool TryNormalizeExactOperand(
            HostedOpeningGeometry operand,
            out HostedOpeningGeometry normalized)
        {
            normalized = default;
            if (!operand.ExactDepth || operand.IsFamilyCutLoop
                || operand.SteppedProfile != null
                || !(operand.WidthFt > 0) || !(operand.DepthFt > 0)
                || !(operand.HeightFt > 0))
                return false;
            if (operand.Boundary is { } boundary)
            {
                if (boundary.Faces.Count != 6
                    || !TryGetExactVerticalRectangularPrismSweptOpening(
                        boundary, out normalized)
                    || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                        normalized, operand))
                    return false;
            }
            else
            {
                normalized = operand with { Boundary = null };
            }
            return normalized.ExactDepth
                && normalized.Boundary == null
                && normalized.SteppedProfile == null
                && normalized.WidthFt > 0
                && normalized.DepthFt > 0
                && normalized.HeightFt > 0
                && new[]
                {
                    normalized.CentreXFt, normalized.CentreYFt,
                    normalized.AxisX, normalized.AxisY,
                    normalized.WidthFt, normalized.DepthFt,
                    normalized.BaseZFt, normalized.HeightFt,
                }.All(value => double.IsFinite(value)
                    && CanMapFeetToIfcPrecisionBin(value));
        }

        // Anchor each cut to all its source reveal cycles; the second cut shares the wall end plane
        // and has only one retained side cycle.
        bool SourceOpeningMatches(HostedOpeningGeometry operand,
            int sideIndex, int? oppositeSideIndex, int[] revealIndices)
        {
            var side = sourceFaces[sideIndex].OuterVertices!;
            var projected = side.Select(Project).ToList();
            var along = projected.Select(point => point.Along)
                .Distinct().Order().ToList();
            var normal = projected.Select(point => point.Normal)
                .Distinct().ToList();
            var z = projected.Select(point => point.Z)
                .Distinct().Order().ToList();
            if (along.Count != 2 || normal.Count != 1 || z.Count != 2
                || !capNormal.Contains(normal[0]))
                return false;
            double centreAlong = operand.CentreXFt * axisX
                + operand.CentreYFt * axisY;
            if (ProjectionKey(centreAlong - operand.WidthFt / 2) != along[0]
                || ProjectionKey(centreAlong + operand.WidthFt / 2) != along[1]
                || ProjectionKey(operand.BaseZFt) != z[0]
                || ProjectionKey(operand.BaseZFt + operand.HeightFt) != z[1])
                return false;
            double centreNormal = operand.CentreXFt * normalX
                + operand.CentreYFt * normalY;
            long normalLow = ProjectionKey(centreNormal - operand.DepthFt / 2);
            long normalHigh = ProjectionKey(centreNormal + operand.DepthFt / 2);
            if (sideIndex == 0)
            {
                if (!ProjectedCycleMatches(sourceFaces[16].AlternativeOuterVertices!,
                [
                    (along[0], normalHigh, z[0]), (along[1], normalHigh, z[0]),
                    (along[1], normalLow, z[0]), (along[0], normalLow, z[0]),
                    (along[0], capNormal[0], z[0]),
                ]))
                    return false;
            }
            else if (!ProjectedCycleMatches(sourceFaces[11].AlternativeOuterVertices!,
                [
                    (along[1], normalHigh, z[0]), (along[1], normalHigh, z[1]),
                    (along[1], normalLow, z[1]), (along[1], normalLow, z[0]),
                    (along[1], capNormal[0], z[0]),
                ])
                || !ProjectedCycleMatches(sourceFaces[12].AlternativeOuterVertices!,
                [
                    (along[1], normalHigh, z[1]), (along[0], normalHigh, z[1]),
                    (along[0], capNormal[0], z[1]), (along[0], normalLow, z[1]),
                    (along[1], normalLow, z[1]),
                ]))
                return false;
            List<(long Along, long Normal, long Z)> Side(long plane) =>
            [
                (along[0], plane, z[0]), (along[1], plane, z[0]),
                (along[1], plane, z[1]), (along[0], plane, z[1]),
            ];
            if (!ProjectedCycleMatches(side, Side(normal[0]))
                || oppositeSideIndex is { } otherIndex
                && !ProjectedCycleMatches(sourceFaces[otherIndex].OuterVertices!,
                    Side(capNormal.Single(value => value != normal[0]))))
                return false;
            var expectedReveals = new List<IReadOnlyList<(
                long Along, long Normal, long Z)>>();
            foreach (long a in along)
                expectedReveals.Add(
                [
                    (a, capNormal[0], z[0]), (a, capNormal[1], z[0]),
                    (a, capNormal[1], z[1]), (a, capNormal[0], z[1]),
                ]);
            foreach (long height in z)
                expectedReveals.Add(
                [
                    (along[0], capNormal[0], height),
                    (along[1], capNormal[0], height),
                    (along[1], capNormal[1], height),
                    (along[0], capNormal[1], height),
                ]);
            return expectedReveals.All(expected => revealIndices.Count(index =>
                    ProjectedCycleMatches(sourceFaces[index].OuterVertices!,
                        expected)) == 1)
                && revealIndices.All(index => expectedReveals.Count(expected =>
                    ProjectedCycleMatches(sourceFaces[index].OuterVertices!,
                        expected)) == 1);
        }

        var targetDefinitions = new List<HostedOpeningGeometry>(2);
        var matchedSourceCuts = new HashSet<int>();
        var allGraphHostIds = inverseSets
            .SelectMany(item => item.HostIds).Distinct().ToList();
        if (allGraphHostIds.Any(hostId =>
                standaloneOpeningIdsByWall.TryGetValue(
                    hostId, out var standaloneIds)
                && standaloneIds.Count > 0))
            return Reject("standalone-opening-graph", decodedIds);
        foreach (var inverse in inverseSets)
        {
            var emittedIdClaims = emittedHostedCutterIdsByWall
                .Where(pair => pair.Value.Contains(inverse.CutterId))
                .ToList();
            var emittedOperandClaims = emittedHostedOpeningOperandsByWall
                .Where(pair => pair.Value.Any(item =>
                    item.CutterId == inverse.CutterId))
                .ToList();
            if (emittedIdClaims.Any(pair =>
                    pair.Value.Count(id => id == inverse.CutterId) != 1)
                || !emittedIdClaims.Select(pair => pair.Key).ToHashSet()
                    .SetEquals(inverse.HostIds)
                || emittedOperandClaims.Any(pair =>
                    pair.Value.Count(item =>
                        item.CutterId == inverse.CutterId) != 1)
                || !emittedOperandClaims.Select(pair => pair.Key).ToHashSet()
                    .SetEquals(inverse.HostIds))
                return Reject("materialized-host-bijection",
                    [inverse.CutterId]);

            HostedOpeningGeometry targetOperand = targetEmittedOperands
                .Single(item => item.CutterId == inverse.CutterId).Operand;
            if (!TryNormalizeExactOperand(
                    targetOperand, out var targetDefinition))
                return Reject("target-operand", [inverse.CutterId]);
            bool interiorSourceCut = SourceOpeningMatches(
                    targetDefinition, 0, 4, [15, 16, 17, 18])
                && HostedOpeningWriterOperandIsRobustInteriorThroughCutOfExactWall(
                    wall, sourceBounds, candidateGross, targetDefinition);
            bool endSourceMatches = SourceOpeningMatches(
                targetDefinition, 3, null, [9, 10, 11, 12]);
            bool endWriterMatches = HostedOpeningWriterOperandIsSerializedEndCoincidentThroughNotchOfExactWallCore(
                wall, sourceBounds, candidateGross, targetDefinition,
                requireRobustSideCrossing: true, out string endWriterReason);
            bool endSourceCut = endSourceMatches && endWriterMatches;
            if (interiorSourceCut == endSourceCut
                || !matchedSourceCuts.Add(interiorSourceCut ? 0 : 1))
                return Reject($"source-opening-bijection-end-{endSourceMatches}-{endWriterReason}",
                    [inverse.CutterId]);
            foreach (var claim in emittedOperandClaims)
            {
                HostedOpeningGeometry claimedOperand = claim.Value
                    .Single(item =>
                        item.CutterId == inverse.CutterId).Operand;
                if (!TryNormalizeExactOperand(
                        claimedOperand, out var claimedDefinition)
                    || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                        targetDefinition, claimedDefinition))
                    return Reject("operand-lattice", [inverse.CutterId]);
            }
            targetDefinitions.Add(targetDefinition);
        }

        if (targetDefinitions.Count != 2
            || RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                targetDefinitions[0], targetDefinitions[1]))
            return Reject("opening-bijection", decodedIds);
        var openingIntervals = targetDefinitions.Select(operand =>
        {
            double centreAlong = operand.CentreXFt * axisX
                + operand.CentreYFt * axisY;
            return (Minimum: centreAlong - operand.WidthFt / 2,
                Maximum: centreAlong + operand.WidthFt / 2);
        }).OrderBy(interval => interval.Minimum).ToList();
        double writerGapFt =
            2 * IfcGeometryPrecisionMetres / FeetToMetres;
        if (openingIntervals[1].Minimum
                - openingIntervals[0].Maximum <= writerGapFt)
            return Reject("opening-separation", decodedIds);

        grossBoundary = candidateGross;
        cutterElementIds = decodedIds.ToArray();
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCCOMPLETE52INSETCAPTWOGATE wall={wall.Id} "
                + $"cutters={string.Join(',', cutterElementIds)} "
                + "result=accept stage=exact-source-rebuilt-inset-caps-"
                + "inverse-host-writer-lattice");
        return true;
    }

    /// <summary>
    /// Promotes the exact split-reveal wall only when its two mapped window cutters retain the
    /// complete serialized host graph and their instance-owned external dimensions.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealAndExactMappedInstanceParameters(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elemById,
            IReadOnlySet<int> visibleWallIds,
            IReadOnlyDictionary<int, List<int>> inverseHostedHostIds,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData grossBoundary,
            out IReadOnlyList<int> cutterElementIds,
            out IReadOnlyList<(int WallId, int CutterId,
                HostedOpeningGeometry Operand)> writerOverrides)
    {
        grossBoundary = new GeometryData();
        cutterElementIds = [];
        writerOverrides = [];
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_RECT_BREP_GATE_DIAG") == "1"
            || Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, int cutterId = 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOMPLETE16SPLITREVEALGATE wall={wall.Id} "
                    + $"cutter={cutterId} result=reject stage={stage}");
            return false;
        }

        if (!TryGetExactGrossWallBoundaryFromCompleteOpenSixteenFaceSplitRevealSource(
                wall, bounds, rebuiltBoundary,
                out var candidateGross, out var sourceThroughOpening,
                out string sourceReason))
            return Reject($"source-{sourceReason}");

        static bool Empty(IReadOnlyCollection<int>? values) =>
            values is not { Count: > 0 };

        static bool EmptyFamilyGeometry(Element element) =>
            element.FamilyCutGeometry == null
            && element.FamilyCutClosurePlaneOrigin == null
            && element.FamilyCutClosurePlaneNormal == null
            && element.FamilyCutLoops is not { Count: > 0 }
            && (element.Geometry == null
                || element.Geometry.Faces.Count == 0
                && element.Geometry.BrepSolids is not { Count: > 0 }
                && element.Geometry.Solids is not { Count: > 0 }
                && element.Geometry.Instances is not { Count: > 0 }
                && element.Geometry.ExactMappedInstances is not { Count: > 0 });

        static bool TryGetUniqueExternalLength(
            Element element, Guid expectedGuid, bool expectedReadOnly,
            out double value)
        {
            value = double.NaN;
            var claims = element.Parameters.Where(parameter =>
            {
                Guid? forgeGuid = parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.external.-1:",
                        StringComparison.Ordinal) == true
                    ? BipHelpers.ParseGuidFromForgeId(parameter.ForgeId)
                    : null;
                return forgeGuid == expectedGuid
                    || parameter.Guid == expectedGuid;
            }).ToList();
            if (claims.Count != 1) return false;
            Parameter parameter = claims[0];
            if (parameter.Id <= 0
                || parameter.StorageType != StorageType.Double
                || parameter.IsReadOnly != expectedReadOnly
                || parameter.ForgeId?.StartsWith(
                    "autodesk.parameter.aec.revit.external.-1:",
                    StringComparison.Ordinal) != true
                || BipHelpers.ParseGuidFromForgeId(parameter.ForgeId)
                    != expectedGuid
                || parameter.Guid != null && parameter.Guid != expectedGuid
                || parameter.SpecType != null
                    && !parameter.SpecType.Contains(
                        ":length", StringComparison.OrdinalIgnoreCase)
                 || parameter.Value is not double parameterValue
                 || !(parameterValue > 0)
                 || !double.IsFinite(parameterValue)
                 || !CanMapFeetToIfcPrecisionBin(parameterValue))
                 return false;
            value = parameterValue;
            return true;
        }

        static bool SimpleWriterBox(HostedOpeningGeometry operand)
        {
            double axisLengthSquared = operand.AxisX * operand.AxisX
                + operand.AxisY * operand.AxisY;
            return operand.ExactDepth
                && operand.Boundary == null
                && !operand.IsFamilyCutLoop
                && operand.SteppedProfile == null
                && new[]
                {
                    operand.CentreXFt, operand.CentreYFt,
                    operand.AxisX, operand.AxisY,
                    operand.WidthFt, operand.DepthFt,
                    operand.BaseZFt, operand.HeightFt,
                    axisLengthSquared,
                }.All(double.IsFinite)
                && operand.WidthFt > 0 && operand.DepthFt > 0
                && operand.HeightFt > 0
                && Math.Abs(axisLengthSquared - 1)
                    <= 8192 * 2.2204460492503131e-16;
        }

        static bool SameDirection(
            double firstX, double firstY,
            double secondX, double secondY)
        {
            double firstLength = Math.Sqrt(
                firstX * firstX + firstY * firstY);
            double secondLength = Math.Sqrt(
                secondX * secondX + secondY * secondY);
            if (!(firstLength > 0) || !(secondLength > 0)
                || !double.IsFinite(firstLength)
                || !double.IsFinite(secondLength))
                return false;
            double dot = (firstX * secondX + firstY * secondY)
                / (firstLength * secondLength);
            double cross = (firstX * secondY - firstY * secondX)
                / (firstLength * secondLength);
            const double directionRoundoff =
                8192 * 2.2204460492503131e-16;
            return Math.Abs(Math.Abs(dot) - 1) <= directionRoundoff
                && Math.Abs(cross) <= directionRoundoff;
        }

        static bool WriterBoxesMatchAtIfcPrecision(
            HostedOpeningGeometry actual,
            HostedOpeningGeometry expected)
        {
            if (!SimpleWriterBox(actual) || !SimpleWriterBox(expected)
                || !SameDirection(actual.AxisX, actual.AxisY,
                    expected.AxisX, expected.AxisY))
                return false;
            try
            {
                return IfcPrecisionKeyFeet(
                        [actual.CentreXFt, actual.CentreYFt, actual.BaseZFt])
                    == IfcPrecisionKeyFeet(
                        [expected.CentreXFt, expected.CentreYFt,
                            expected.BaseZFt])
                    && IfcPrecisionBinMetres(
                        actual.WidthFt * FeetToMetres)
                        == IfcPrecisionBinMetres(
                            expected.WidthFt * FeetToMetres)
                    && IfcPrecisionBinMetres(
                        actual.DepthFt * FeetToMetres)
                        == IfcPrecisionBinMetres(
                            expected.DepthFt * FeetToMetres)
                    && IfcPrecisionBinMetres(
                        actual.HeightFt * FeetToMetres)
                        == IfcPrecisionBinMetres(
                            expected.HeightFt * FeetToMetres)
                    && IfcPrecisionBinMetres(
                        (actual.BaseZFt + actual.HeightFt) * FeetToMetres)
                        == IfcPrecisionBinMetres(
                            (expected.BaseZFt + expected.HeightFt)
                                * FeetToMetres);
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        static bool WriterBoxMatchesSerializedBoundsAtIfcPrecision(
            Element cutter, HostedOpeningGeometry operand)
        {
            if (cutter.BoundingBox is not { Length: 6 } serializedBounds
                || serializedBounds.Any(value => !double.IsFinite(value))
                || serializedBounds[0] >= serializedBounds[3]
                || serializedBounds[1] >= serializedBounds[4]
                || serializedBounds[2] >= serializedBounds[5]
                || !SimpleWriterBox(operand))
                return false;

            double halfWidth = operand.WidthFt / 2;
            double halfDepth = operand.DepthFt / 2;
            double normalX = -operand.AxisY;
            double normalY = operand.AxisX;
            var plan = new List<(double X, double Y)>(4);
            foreach (double alongSign in new[] { -1.0, 1.0 })
                foreach (double normalSign in new[] { -1.0, 1.0 })
                    plan.Add((
                        operand.CentreXFt
                            + alongSign * halfWidth * operand.AxisX
                            + normalSign * halfDepth * normalX,
                        operand.CentreYFt
                            + alongSign * halfWidth * operand.AxisY
                            + normalSign * halfDepth * normalY));
            double[] expectedBounds =
            [
                plan.Min(point => point.X),
                plan.Min(point => point.Y),
                operand.BaseZFt,
                plan.Max(point => point.X),
                plan.Max(point => point.Y),
                operand.BaseZFt + operand.HeightFt,
            ];
            try
            {
                return Enumerable.Range(0, expectedBounds.Length).All(index =>
                    IfcPrecisionBinMetres(
                        expectedBounds[index] * FeetToMetres)
                    == IfcPrecisionBinMetres(
                        serializedBounds[index] * FeetToMetres));
            }
            catch (OverflowException)
            {
                return false;
            }
        }

        bool TryGetExactMappedTransform(
            Element cutter, out InstanceTransform transform,
            out int mappedSymbolId)
        {
            transform = null!;
            mappedSymbolId = -1;
            if (cutter.Geometry is not { Faces.Count: 0 } geometry
                || geometry.BrepSolids is { Count: > 0 }
                || geometry.Solids is { Count: > 0 }
                || cutter.FamilyCutGeometry != null
                || cutter.FamilyCutClosurePlaneOrigin != null
                || cutter.FamilyCutClosurePlaneNormal != null
                || cutter.FamilyCutLoops is { Count: > 0 }
                || LinkedFamilyCutTypes(cutter, elemById).Count != 0)
                return false;

            if (geometry.ExactMappedInstances is { Count: > 0 }
                || geometry.Instances is not [{ } mapped]
                || mapped.SymbolId <= 0 || mapped.SymbolId == cutter.Id
                || mapped.Transform is not { Length: 12 } matrix
                || matrix.Any(value => !double.IsFinite(value))
                || cutter.Transform is not
                {
                    Origin.Length: 3,
                    BasisX.Length: 3,
                    BasisY.Length: 3,
                    BasisZ.Length: 3,
                } direct
                || direct.SymbolId != mapped.SymbolId
                || direct.Origin.Concat(direct.BasisX)
                    .Concat(direct.BasisY).Concat(direct.BasisZ)
                    .Any(value => !double.IsFinite(value)))
                return false;

            double scale = Math.Max(1.0, matrix.Concat(direct.Origin)
                .Concat(direct.BasisX).Concat(direct.BasisY)
                .Concat(direct.BasisZ).Select(Math.Abs).Max());
            double roundoff = 8192 * 2.2204460492503131e-16 * scale;
            bool Same(double first, double second) =>
                Math.Abs(first - second) <= roundoff;
            double basisXLengthSquared = direct.BasisX
                .Select(value => value * value).Sum();
            double basisYLengthSquared = direct.BasisY
                .Select(value => value * value).Sum();
            double basisZLengthSquared = direct.BasisZ
                .Select(value => value * value).Sum();
            double xyDot = Enumerable.Range(0, 3)
                .Sum(index => direct.BasisX[index] * direct.BasisY[index]);
            if (!Same(matrix[0], direct.BasisX[0])
                || !Same(matrix[3], direct.BasisX[1])
                || !Same(matrix[6], direct.BasisX[2])
                || !Same(matrix[1], direct.BasisY[0])
                || !Same(matrix[4], direct.BasisY[1])
                || !Same(matrix[7], direct.BasisY[2])
                || !Same(matrix[2], direct.BasisZ[0])
                || !Same(matrix[5], direct.BasisZ[1])
                || !Same(matrix[8], direct.BasisZ[2])
                || !Same(matrix[9], direct.Origin[0])
                || !Same(matrix[10], direct.Origin[1])
                || !Same(matrix[11], direct.Origin[2])
                || !Same(basisXLengthSquared, 1)
                || !Same(basisYLengthSquared, 1)
                || !Same(basisZLengthSquared, 1)
                || !Same(xyDot, 0)
                || !Same(direct.BasisX[2], 0)
                || !Same(direct.BasisY[2], 0)
                || !Same(direct.BasisZ[0], 0)
                || !Same(direct.BasisZ[1], 0)
                || !Same(direct.BasisZ[2], 1))
                return false;
            transform = direct;
            mappedSymbolId = mapped.SymbolId;
            return true;
        }

        if (wall.CuttingElementIds is not { Count: 2 } decodedCutterIds
            || decodedCutterIds.Any(id => id <= 0 || id == wall.Id)
            || decodedCutterIds.Distinct().Count() != 2
            || wall.References == null
            || decodedCutterIds.Any(id =>
                wall.References.Count(reference => reference == id) != 1)
            || emittedHostedCutterIdsByWall == null
            || emittedHostedOpeningOperandsByWall == null
            || standaloneOpeningIdsByWall == null)
            return Reject("cutter-authority");

        if (!emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var targetEmittedCutterIds)
            || targetEmittedCutterIds is not { Count: 2 }
            || targetEmittedCutterIds.Distinct().Count() != 2
            || !targetEmittedCutterIds.ToHashSet().SetEquals(decodedCutterIds)
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var targetEmittedOperands)
            || targetEmittedOperands is not { Count: 2 }
            || targetEmittedOperands.Select(item => item.CutterId)
                .Distinct().Count() != 2
            || !targetEmittedOperands.Select(item => item.CutterId)
                .ToHashSet().SetEquals(decodedCutterIds))
            return Reject("target-emitted-cutter-operand-bijection");

        var cutters = new List<Element>();
        foreach (int cutterId in decodedCutterIds)
        {
            if (!elemById.TryGetValue(cutterId, out var cutter)
                || cutter.Id != cutterId || cutter.IsBlockOnly
                || cutter.CategoryId != -2000014
                || cutter.SuperInstanceId is > 0
                || cutter.BoundingBox is not { Length: 6 } cutterBounds
                || cutterBounds.Any(value => !double.IsFinite(value))
                || !inverseHostedHostIds.TryGetValue(
                    cutterId, out var inverseIds)
                || inverseIds.Any(id => id <= 0)
                || inverseIds.Distinct().Count() != inverseIds.Count
                || !TryGetExactMappedTransform(
                    cutter, out _, out _))
                return Reject("mapped-cutter-authority", cutterId);
            cutters.Add(cutter);
        }

        var sevenHostCutters = cutters.Where(cutter =>
            inverseHostedHostIds[cutter.Id].Count == 7).ToList();
        var twoHostCutters = cutters.Where(cutter =>
            inverseHostedHostIds[cutter.Id].Count == 2).ToList();
        if (sevenHostCutters.Count != 1 || twoHostCutters.Count != 1)
            return Reject("cutter-role-cardinality");
        Element sevenHostCutter = sevenHostCutters[0];
        Element twoHostCutter = twoHostCutters[0];
        var sevenHostIds = inverseHostedHostIds[sevenHostCutter.Id];
        var twoHostIds = inverseHostedHostIds[twoHostCutter.Id];

        if (sevenHostCutter.HostId is not int correctDirectHostId
            || sevenHostCutter.SerializedHostId != correctDirectHostId
            || correctDirectHostId == wall.Id
            || sevenHostCutter.ExtraHostIds is not { Count: 1 }
            || sevenHostCutter.ExtraHostIds[0] != wall.Id
            || !Empty(sevenHostCutter.ExplicitHostIds)
            || twoHostCutter.HostId != wall.Id
            || twoHostCutter.SerializedHostId != wall.Id
            || !Empty(twoHostCutter.ExtraHostIds)
            || !Empty(twoHostCutter.ExplicitHostIds)
            || !sevenHostIds.Contains(correctDirectHostId)
            || !sevenHostIds.Contains(wall.Id)
            || !twoHostIds.Contains(wall.Id)
            || !sevenHostIds.ToHashSet().IsSupersetOf(twoHostIds)
            || !sevenHostIds.ToHashSet().Intersect(twoHostIds)
                .ToHashSet().SetEquals(twoHostIds)
            || correctDirectHostId == twoHostIds.Single(
                id => id != wall.Id))
            return Reject("direct-extra-common-host-graph");

        bool ExactForwardReferences(
            Element cutter, IReadOnlyList<int> inverseIds,
            IReadOnlySet<int> explicitHostIds)
        {
            if (cutter.References == null) return false;
            return explicitHostIds.All(hostId =>
                    cutter.References.Count(id => id == hostId) == 1)
                && inverseIds.Where(id => !explicitHostIds.Contains(id)).All(hostId =>
                    cutter.References.Count(id => id == hostId) == 0);
        }
        if (!ExactForwardReferences(
                sevenHostCutter, sevenHostIds,
                new HashSet<int> { correctDirectHostId, wall.Id })
            || !ExactForwardReferences(
                twoHostCutter, twoHostIds,
                new HashSet<int> { wall.Id }))
            return Reject("forward-host-reference-graph");

        foreach (var cutter in cutters)
        {
            var inverseIds = inverseHostedHostIds[cutter.Id];
            foreach (int hostId in inverseIds)
            {
                if (!visibleWallIds.Contains(hostId)
                    || !elemById.TryGetValue(hostId, out var host)
                    || host.Id != hostId || host.IsBlockOnly
                    || host.CategoryId != -2000011
                    || host.BoundingBox is not { Length: 6 } hostBounds
                    || hostBounds.Any(value => !double.IsFinite(value))
                    || host.Location is not
                        { CurveType: "Line", ArcRadius: null }
                    || host.References?.Count(id => id == cutter.Id) != 1
                    || !TryGetSerializedWallWidthFeet(host, out double hostWidthFt)
                    || !(hostWidthFt > 0) || !double.IsFinite(hostWidthFt))
                    return Reject("inverse-host-reciprocity", cutter.Id);
            }
            var resolvedIds = ResolveHostedElementHostIds(
                cutter, elemById, visibleWallIds, inverseHostedHostIds);
            if (resolvedIds.Count != inverseIds.Count
                || resolvedIds.Distinct().Count() != resolvedIds.Count
                || !resolvedIds.ToHashSet().SetEquals(inverseIds))
                return Reject("resolved-host-graph", cutter.Id);
        }

        int familyRootId = sevenHostCutter.FamilyTypeId;
        if (familyRootId <= 0
            || twoHostCutter.FamilyTypeId != familyRootId
            || familyRootId == sevenHostCutter.Id
            || familyRootId == twoHostCutter.Id
            || !elemById.TryGetValue(familyRootId, out var familyRoot)
            || familyRoot.Id != familyRootId || familyRoot.IsBlockOnly
            || familyRoot.CategoryId != -2000014
            || !EmptyFamilyGeometry(familyRoot)
            || !TryGetExactMappedTransform(
                sevenHostCutter, out var sevenHostTransform,
                out int sevenHostSymbolId)
            || !TryGetExactMappedTransform(
                twoHostCutter, out var twoHostTransform,
                out int twoHostSymbolId)
            || sevenHostSymbolId == twoHostSymbolId
            || sevenHostSymbolId == familyRootId
            || twoHostSymbolId == familyRootId
            || !elemById.TryGetValue(sevenHostSymbolId,
                out var sevenHostSymbol)
            || !elemById.TryGetValue(twoHostSymbolId,
                out var twoHostSymbol)
            || sevenHostSymbol.Id != sevenHostSymbolId
            || twoHostSymbol.Id != twoHostSymbolId
            || sevenHostSymbol.IsBlockOnly || twoHostSymbol.IsBlockOnly
            || sevenHostSymbol.CategoryId != -2000014
            || twoHostSymbol.CategoryId != -2000014
            || sevenHostSymbol.FamilyTypeId != familyRootId
            || twoHostSymbol.FamilyTypeId != familyRootId
            || !EmptyFamilyGeometry(sevenHostSymbol)
            || !EmptyFamilyGeometry(twoHostSymbol)
            || sevenHostCutter.References?.Count(
                id => id == familyRootId) != 2
            || twoHostCutter.References?.Count(
                id => id == familyRootId) != 2
            || sevenHostCutter.References?.Count(
                id => id == sevenHostSymbolId) != 2
            || twoHostCutter.References?.Count(
                id => id == twoHostSymbolId) != 2
            || sevenHostSymbol.References?.Count(
                id => id == familyRootId) != 1
            || twoHostSymbol.References?.Count(
                id => id == familyRootId) != 1
            || LinkedFamilyCutTypes(sevenHostCutter, elemById).Count != 0
            || LinkedFamilyCutTypes(twoHostCutter, elemById).Count != 0)
            return Reject("family-mapped-symbol-hierarchy");

        if (!TryGetUniqueExternalLength(
                sevenHostCutter, AdskSizeWidthParameterGuid,
                expectedReadOnly: true, out double sevenHostWidthFt)
            || !TryGetUniqueExternalLength(
                sevenHostCutter, AdskSizeHeightParameterGuid,
                expectedReadOnly: true, out double sevenHostHeightFt)
            || !TryGetUniqueExternalLength(
                sevenHostCutter, HostedWallThicknessParameterGuid,
                expectedReadOnly: true, out double sevenHostThicknessFt)
            || !TryGetUniqueExternalLength(
                twoHostCutter, AdskSizeWidthParameterGuid,
                expectedReadOnly: true, out double twoHostWidthFt)
            || !TryGetUniqueExternalLength(
                twoHostCutter, AdskSizeHeightParameterGuid,
                expectedReadOnly: true, out double twoHostHeightFt)
            || !TryGetUniqueExternalLength(
                twoHostCutter, HostedWallThicknessParameterGuid,
                expectedReadOnly: true, out double twoHostThicknessFt)
            || !TryGetUniqueExternalLength(
                sevenHostSymbol, AdskSizeWidthParameterGuid,
                expectedReadOnly: false, out double symbolWidthFt)
            || !TryGetUniqueExternalLength(
                sevenHostSymbol, AdskSizeHeightParameterGuid,
                expectedReadOnly: false, out double symbolHeightFt)
            || !TryGetUniqueExternalLength(
                sevenHostSymbol, HostedWallThicknessParameterGuid,
                expectedReadOnly: false, out double symbolThicknessFt)
            || !TryGetUniqueExternalLength(
                twoHostSymbol, AdskSizeWidthParameterGuid,
                expectedReadOnly: false, out double secondSymbolWidthFt)
            || !TryGetUniqueExternalLength(
                twoHostSymbol, AdskSizeHeightParameterGuid,
                expectedReadOnly: false, out double secondSymbolHeightFt)
            || !TryGetUniqueExternalLength(
                twoHostSymbol, HostedWallThicknessParameterGuid,
                expectedReadOnly: false, out double secondSymbolThicknessFt))
            return Reject("external-guid-parameter-authority");

        long DimensionKey(double feet) =>
            IfcPrecisionBinMetres(feet * FeetToMetres);
        if (DimensionKey(symbolWidthFt) != DimensionKey(secondSymbolWidthFt)
            || DimensionKey(symbolHeightFt) != DimensionKey(secondSymbolHeightFt)
            || DimensionKey(symbolThicknessFt)
                != DimensionKey(secondSymbolThicknessFt)
            || DimensionKey(symbolWidthFt) == DimensionKey(sevenHostWidthFt)
            || DimensionKey(symbolWidthFt) == DimensionKey(twoHostWidthFt)
            || DimensionKey(symbolHeightFt) == DimensionKey(sevenHostHeightFt)
            || DimensionKey(symbolHeightFt) == DimensionKey(twoHostHeightFt)
            || DimensionKey(symbolThicknessFt)
                == DimensionKey(sevenHostThicknessFt)
            || DimensionKey(symbolThicknessFt)
                == DimensionKey(twoHostThicknessFt))
            return Reject("conflicting-symbol-defaults");

        HostedOpeningGeometry Desired(
            Element cutter, InstanceTransform transform,
            double widthFt, double thicknessFt, double heightFt) =>
            new(
                transform.Origin[0], transform.Origin[1],
                transform.BasisX[0], transform.BasisX[1],
                widthFt, thicknessFt,
                cutter.BoundingBox![2], heightFt,
                ExactDepth: true);
        HostedOpeningGeometry sevenHostDesired = Desired(
            sevenHostCutter, sevenHostTransform,
            sevenHostWidthFt, sevenHostThicknessFt,
            sevenHostHeightFt);
        HostedOpeningGeometry twoHostDesired = Desired(
            twoHostCutter, twoHostTransform,
            twoHostWidthFt, twoHostThicknessFt,
            twoHostHeightFt);
        if (!SimpleWriterBox(sevenHostDesired)
            || !SimpleWriterBox(twoHostDesired)
            || !WriterBoxMatchesSerializedBoundsAtIfcPrecision(
                sevenHostCutter, sevenHostDesired)
            || !WriterBoxMatchesSerializedBoundsAtIfcPrecision(
                twoHostCutter, twoHostDesired)
            || DimensionKey(sevenHostThicknessFt)
                != DimensionKey(sourceThroughOpening.DepthFt)
            || DimensionKey(twoHostThicknessFt)
                != DimensionKey(sourceThroughOpening.DepthFt)
            || DimensionKey(sevenHostHeightFt)
                != DimensionKey(sourceThroughOpening.HeightFt)
            || DimensionKey(twoHostHeightFt)
                != DimensionKey(sourceThroughOpening.HeightFt)
            || DimensionKey(twoHostWidthFt)
                != DimensionKey(sourceThroughOpening.WidthFt)
            || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                twoHostDesired, sourceThroughOpening)
            || !HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                wall, bounds, candidateGross, sevenHostDesired))
            return Reject("instance-parameter-source-definition");

        HashSet<int> MaterializedHosts(int cutterId) =>
            emittedHostedCutterIdsByWall
                .Where(pair => pair.Value.Count(id => id == cutterId) == 1)
                .Select(pair => pair.Key).ToHashSet();
        HashSet<int> OperandHosts(int cutterId) =>
            emittedHostedOpeningOperandsByWall
                .Where(pair => pair.Value.Count(item =>
                    item.CutterId == cutterId) == 1)
                .Select(pair => pair.Key).ToHashSet();
        bool NoDuplicateMaterializedPair(int cutterId) =>
            emittedHostedCutterIdsByWall.All(pair =>
                pair.Value.Count(id => id == cutterId) <= 1)
            && emittedHostedOpeningOperandsByWall.All(pair =>
                pair.Value.Count(item => item.CutterId == cutterId) <= 1);

        HashSet<int> CandidateHosts(Element cutter,
            IReadOnlyList<int> resolvedIds) =>
            resolvedIds.Where(hostId =>
                elemById[hostId].CategoryId == -2000011
                && HostedElementCanCutHost(
                    cutter.BoundingBox!, elemById[hostId]))
                .ToHashSet();
        var sevenCandidateHosts = CandidateHosts(
            sevenHostCutter, sevenHostIds);
        var twoCandidateHosts = CandidateHosts(
            twoHostCutter, twoHostIds);
        var sevenMaterializedHosts = MaterializedHosts(sevenHostCutter.Id);
        var twoMaterializedHosts = MaterializedHosts(twoHostCutter.Id);
        if (sevenCandidateHosts.Count != 6
            || twoCandidateHosts.Count != 2
            || !sevenCandidateHosts.Contains(correctDirectHostId)
            || !sevenCandidateHosts.Contains(wall.Id)
            || sevenHostIds.Count(id => !sevenCandidateHosts.Contains(id)) != 1
            || !twoCandidateHosts.SetEquals(twoHostIds))
            return Reject("candidate-host-partition");

        var sevenReferenceOnlyHostIds = sevenHostIds.Where(hostId =>
            elemById[hostId].CuttingElementIds == null).ToList();
        if (sevenReferenceOnlyHostIds.Count != 1)
            return Reject("host-cutting-roster-partition",
                sevenHostCutter.Id);
        int sevenReferenceOnlyHostId = sevenReferenceOnlyHostIds[0];
        if (!sevenCandidateHosts.Contains(sevenReferenceOnlyHostId)
            || sevenReferenceOnlyHostId == wall.Id
            || sevenReferenceOnlyHostId == correctDirectHostId
            || twoHostIds.Contains(sevenReferenceOnlyHostId)
            || sevenHostIds.Where(id => id != sevenReferenceOnlyHostId)
                .Any(id => elemById[id].CuttingElementIds?.Count(
                    cutterId => cutterId == sevenHostCutter.Id) != 1)
            || twoHostIds.Any(id =>
                elemById[id].CuttingElementIds?.Count(
                    cutterId => cutterId == twoHostCutter.Id) != 1))
            return Reject("host-cutting-roster-partition");

        if (!NoDuplicateMaterializedPair(sevenHostCutter.Id)
            || !NoDuplicateMaterializedPair(twoHostCutter.Id)
            || !sevenMaterializedHosts.SetEquals(sevenCandidateHosts)
            || !twoMaterializedHosts.SetEquals(twoCandidateHosts)
            || !OperandHosts(sevenHostCutter.Id).SetEquals(sevenCandidateHosts)
            || !OperandHosts(twoHostCutter.Id).SetEquals(twoCandidateHosts))
            return Reject("precompute-materialized-host-bijection");

        var allHostIds = sevenHostIds.Concat(twoHostIds).Distinct().ToList();
        if (allHostIds.Any(hostId =>
                standaloneOpeningIdsByWall.TryGetValue(
                    hostId, out var standaloneIds)
                && standaloneIds is not { Count: 0 }))
            return Reject("standalone-opening-graph");

        double writerStepFt = IfcGeometryPrecisionMetres / FeetToMetres;
        bool TryBuildSevenHostLegacy(
            Element host, out HostedOpeningGeometry opening)
        {
            opening = default;
            double[] hostBounds = host.BoundingBox
                ?? host.Geometry?.BoundingBox ?? [];
            if (host.Location is not
                {
                    CurveType: "Line", ArcRadius: null,
                    StartPoint.Length: >= 3,
                    EndPoint.Length: >= 3,
                } location
                || location.StartPoint.Take(3).Any(value => !double.IsFinite(value))
                || location.EndPoint.Take(3).Any(value => !double.IsFinite(value))
                || hostBounds.Length < 6
                || hostBounds.Take(6).Any(value => !double.IsFinite(value)))
                return false;
            double hostWidthFt = GetSerializedPositiveDimension(
                host, LinkedFamilyType(host, elemById), -1001000);
            double bboxThicknessFt = Math.Min(
                Math.Abs(hostBounds[3] - hostBounds[0]),
                Math.Abs(hostBounds[4] - hostBounds[1]));
            if (bboxThicknessFt is > 0.05 and <= 3
                && (hostWidthFt <= 0 || hostWidthFt > 3
                    || bboxThicknessFt < hostWidthFt * 0.8))
                hostWidthFt = bboxThicknessFt;
            if (hostWidthFt <= 0 || hostWidthFt > 3)
                hostWidthFt = 0.66;
            if (!double.IsFinite(hostWidthFt)
                || !CanMapFeetToIfcPrecisionBin(hostWidthFt))
                return false;
            double axisX = location.EndPoint[0] - location.StartPoint[0];
            double axisY = location.EndPoint[1] - location.StartPoint[1];
            double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
            if (!(axisLength > 0) || !double.IsFinite(axisLength))
                return false;
            axisX /= axisLength;
            axisY /= axisLength;
            opening = new HostedOpeningGeometry(
                sevenHostTransform.Origin[0],
                sevenHostTransform.Origin[1],
                axisX, axisY,
                sevenHostWidthFt + sevenHostThicknessFt,
                hostWidthFt + 20 * writerStepFt,
                sevenHostDesired.BaseZFt,
                sevenHostHeightFt,
                ExactDepth: true);
            return SimpleWriterBox(opening);
        }
        double twoNormalX = twoHostTransform.BasisX[1];
        double twoNormalY = -twoHostTransform.BasisX[0];
        var twoHostLegacy = new HostedOpeningGeometry(
            twoHostTransform.Origin[0] + twoNormalX * 1000 * writerStepFt,
            twoHostTransform.Origin[1] + twoNormalY * 1000 * writerStepFt,
            twoHostTransform.BasisX[0], twoHostTransform.BasisX[1],
            twoHostWidthFt,
            twoHostThicknessFt + 2000 * writerStepFt,
            twoHostDesired.BaseZFt, twoHostHeightFt,
            ExactDepth: true);

        HostedOpeningGeometry MaterializedOperand(int hostId, int cutterId) =>
            emittedHostedOpeningOperandsByWall[hostId]
                .Single(item => item.CutterId == cutterId).Operand;
        static string WriterBoxDiagnostics(HostedOpeningGeometry value)
        {
            static string Number(double number) =>
                number.ToString("G17", CultureInfo.InvariantCulture);
            return $"centreXY=({Number(value.CentreXFt)},"
                + $"{Number(value.CentreYFt)}) "
                + $"axisXY=({Number(value.AxisX)},{Number(value.AxisY)}) "
                + $"width={Number(value.WidthFt)} "
                + $"depth={Number(value.DepthFt)} "
                + $"base={Number(value.BaseZFt)} "
                + $"height={Number(value.HeightFt)} "
                + $"exactDepth={value.ExactDepth} "
                + $"boundaryNull={value.Boundary == null} "
                + $"boundaryFaces={value.Boundary?.Faces.Count ?? 0} "
                + $"familyCutLoop={value.IsFamilyCutLoop} "
                + $"steppedNull={value.SteppedProfile == null} "
                + $"steppedCount={(value.SteppedProfile == null ? 0 : 1)}";
        }
        foreach (int hostId in sevenCandidateHosts)
        {
            HostedOpeningGeometry current = MaterializedOperand(
                hostId, sevenHostCutter.Id);
            HostedOpeningGeometry expected = sevenHostDesired;
            if (hostId != correctDirectHostId
                && !TryBuildSevenHostLegacy(
                    elemById[hostId], out expected))
                return Reject("seven-host-current-writer-axis",
                    sevenHostCutter.Id);
            bool simple = SimpleWriterBox(current);
            bool matchExpected = WriterBoxesMatchAtIfcPrecision(
                current, expected);
            bool matchDesired = WriterBoxesMatchAtIfcPrecision(
                current, sevenHostDesired);
            bool mismatch = !matchExpected
                || hostId != correctDirectHostId && matchDesired;
            if (mismatch && diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOMPLETE16SPLITREVEALWRITER wall={wall.Id} "
                    + $"cutter={sevenHostCutter.Id} host={hostId} "
                    + "role=seven-host "
                    + $"simple={simple} matchExpected={matchExpected} "
                    + $"matchDesired={matchDesired} "
                    + $"current=[{WriterBoxDiagnostics(current)}] "
                    + $"expected=[{WriterBoxDiagnostics(expected)}]");
            if (mismatch)
                return Reject("seven-host-current-writer-lattice",
                    sevenHostCutter.Id);
        }
        foreach (int hostId in twoCandidateHosts)
        {
            HostedOpeningGeometry current = MaterializedOperand(
                hostId, twoHostCutter.Id);
            bool simple = SimpleWriterBox(current);
            bool matchExpected = WriterBoxesMatchAtIfcPrecision(
                current, twoHostLegacy);
            bool matchDesired = WriterBoxesMatchAtIfcPrecision(
                current, twoHostDesired);
            bool mismatch = !matchExpected || matchDesired;
            if (mismatch && diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCOMPLETE16SPLITREVEALWRITER wall={wall.Id} "
                    + $"cutter={twoHostCutter.Id} host={hostId} "
                    + "role=two-host "
                    + $"simple={simple} matchExpected={matchExpected} "
                    + $"matchDesired={matchDesired} "
                    + $"current=[{WriterBoxDiagnostics(current)}] "
                    + $"expected=[{WriterBoxDiagnostics(twoHostLegacy)}]");
            if (mismatch)
                return Reject("two-host-current-writer-lattice",
                    twoHostCutter.Id);
        }

        int inverseOnlyLateHostId = sevenHostIds.Single(
            id => !sevenCandidateHosts.Contains(id));
        if (!TryBuildSevenHostLegacy(
                elemById[inverseOnlyLateHostId],
                out var inverseOnlyLateLegacy)
            || WriterBoxesMatchAtIfcPrecision(
                inverseOnlyLateLegacy, sevenHostDesired)
            || emittedHostedCutterIdsByWall.TryGetValue(
                inverseOnlyLateHostId, out var lateIds)
                && lateIds.Contains(sevenHostCutter.Id)
            || emittedHostedOpeningOperandsByWall.TryGetValue(
                inverseOnlyLateHostId, out var lateOperands)
                && lateOperands.Any(item =>
                    item.CutterId == sevenHostCutter.Id))
            return Reject("inverse-only-late-writer-lattice",
                sevenHostCutter.Id);

        var exactOverrides = new List<(int WallId, int CutterId,
            HostedOpeningGeometry Operand)>(8);
        foreach (int hostId in sevenHostIds
                     .Where(id => id != correctDirectHostId))
            exactOverrides.Add((
                hostId, sevenHostCutter.Id, sevenHostDesired));
        foreach (int hostId in twoHostIds)
            exactOverrides.Add((
                hostId, twoHostCutter.Id, twoHostDesired));
        if (exactOverrides.Count != 8
            || exactOverrides.Select(item =>
                (item.WallId, item.CutterId)).Distinct().Count() != 8
            || exactOverrides.Any(item =>
                item.WallId == correctDirectHostId
                && item.CutterId == sevenHostCutter.Id))
            return Reject("writer-override-bijection");

        grossBoundary = candidateGross;
        cutterElementIds = decodedCutterIds.ToList();
        writerOverrides = exactOverrides;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCCOMPLETE16SPLITREVEALGATE wall={wall.Id} "
                + $"cutters={string.Join(',', cutterElementIds)} "
                + $"overrides={writerOverrides.Count} result=accept "
                + "stage=exact-source-graph-instance-guid-writer-lattice");
        return true;
    }

    /// <summary>
    /// Recovers one exact gross wall and two opposed blind side-pocket writer operands from the
    /// complete redundant source contract.
    /// </summary>
    internal static bool
        TryGetVerifiedGrossWallBoundaryFromCompleteOpenTwentyFiveFaceOpposedSidePocketsAndThroughOpening(
            Element wall, IReadOnlyList<double> bounds,
            GeometryData rebuiltBoundary,
            IReadOnlyDictionary<int, Element> elementsById,
            IReadOnlyDictionary<int, List<int>> inverseHostedHostIds,
            IReadOnlyDictionary<int, List<int>>?
                emittedHostedCutterIdsByWall,
            IReadOnlyDictionary<int,
                List<(int CutterId, HostedOpeningGeometry Operand)>>?
                emittedHostedOpeningOperandsByWall,
            IReadOnlyDictionary<int, List<int>>? standaloneOpeningIdsByWall,
            out GeometryData grossBoundary,
            out IReadOnlyList<int> cutterElementIds,
            out IReadOnlyList<(int CutterId,
                HostedOpeningGeometry Operand)> exactSidePocketWriterOperands)
    {
        grossBoundary = new GeometryData();
        cutterElementIds = [];
        exactSidePocketWriterOperands = [];
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == wall.Id);
        bool Reject(string stage, int cutterId = 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFC25FACEPOCKETGATE wall={wall.Id} "
                    + $"cutter={cutterId} result=reject stage={stage}");
            return false;
        }

        static bool Empty(IReadOnlyCollection<int>? values) =>
            values is not { Count: > 0 };
        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) OrderedWorldEdge(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        static bool ExactWorldCycle(
            IReadOnlyList<double[]>? ring, int expectedCount)
        {
            if (ring == null || ring.Count != expectedCount
                || ring.Any(point => point.Length < 3
                    || point.Take(3).Any(value => !double.IsFinite(value))))
                return false;
            try
            {
                var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
                return keys.Distinct().Count() == expectedCount
                    && Enumerable.Range(0, keys.Count)
                        .Select(index => OrderedWorldEdge(
                            keys[index], keys[(index + 1) % keys.Count]))
                        .Distinct().Count() == expectedCount;
            }
            catch (OverflowException)
            {
                return false;
            }
        }
        static bool WorldRingMatches(
            IReadOnlyList<double[]>? first,
            IReadOnlyList<double[]>? second)
        {
            if (first == null || second == null
                || first.Count != second.Count
                || !ExactWorldCycle(first, first.Count)
                || !ExactWorldCycle(second, second.Count))
                return false;
            var firstKeys = first.Select(IfcPrecisionKeyFeet).ToList();
            var secondKeys = second.Select(IfcPrecisionKeyFeet).ToList();
            var firstEdges = Enumerable.Range(0, firstKeys.Count)
                .Select(index => OrderedWorldEdge(
                    firstKeys[index], firstKeys[(index + 1) % firstKeys.Count]))
                .ToHashSet();
            var secondEdges = Enumerable.Range(0, secondKeys.Count)
                .Select(index => OrderedWorldEdge(
                    secondKeys[index],
                    secondKeys[(index + 1) % secondKeys.Count]))
                .ToHashSet();
            return firstKeys.ToHashSet().SetEquals(secondKeys)
                && firstEdges.SetEquals(secondEdges);
        }
        static bool FaceMatches(GeoFace first, GeoFace second)
        {
            if (!WorldRingMatches(first.OuterVertices, second.OuterVertices)
                || (first.AlternativeOuterVertices is { Count: > 0 })
                    != (second.AlternativeOuterVertices is { Count: > 0 })
                || first.AlternativeOuterVertices is { Count: > 0 }
                    && !WorldRingMatches(first.AlternativeOuterVertices,
                        second.AlternativeOuterVertices))
                return false;
            var firstInner = first.InnerVertices ?? [];
            var secondInner = second.InnerVertices ?? [];
            if (firstInner.Count != secondInner.Count)
                return false;
            var unmatched = Enumerable.Range(0, secondInner.Count).ToHashSet();
            foreach (var ring in firstInner)
            {
                var matches = unmatched.Where(index =>
                    WorldRingMatches(ring, secondInner[index])).ToList();
                if (matches.Count != 1)
                    return false;
                unmatched.Remove(matches[0]);
            }
            return unmatched.Count == 0;
        }
        static bool BoundaryMatches(
            GeometryData first, GeometryData second)
        {
            if (first.Faces.Count != second.Faces.Count
                || first.BrepSolids is not [{ IsClosed: true } firstSolid]
                || second.BrepSolids is not [{ IsClosed: true } secondSolid]
                || !firstSolid.FaceIndices.Distinct().Order()
                    .SequenceEqual(Enumerable.Range(0, first.Faces.Count))
                || !secondSolid.FaceIndices.Distinct().Order()
                    .SequenceEqual(Enumerable.Range(0, second.Faces.Count)))
                return false;
            var unmatched = Enumerable.Range(0, second.Faces.Count).ToHashSet();
            foreach (GeoFace face in first.Faces)
            {
                var matches = unmatched.Where(index =>
                    FaceMatches(face, second.Faces[index])).ToList();
                if (matches.Count != 1)
                    return false;
                unmatched.Remove(matches[0]);
            }
            return unmatched.Count == 0;
        }

        if (wall.CategoryId != -2000011
            || bounds.Count < 6 || bounds.Take(6).Any(value => !double.IsFinite(value))
            || wall.BoundingBox is not { Length: 6 } wallBounds
            || wallBounds.Any(value => !double.IsFinite(value))
            || !BoundsMatchAtIfcPrecision(wallBounds, bounds)
            || wall.Location is not
                { CurveType: "Line", ArcRadius: null } location
            || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
            || wall.Geometry is not { } sourceGeometry
            || sourceGeometry.BoundingBox is not
                { Length: 6 } sourceBounds
            || sourceBounds.Any(value => !double.IsFinite(value))
            || !BoundsMatchAtIfcPrecision(sourceBounds, bounds)
            || sourceGeometry.Faces is not { Count: 25 } sourceFaces
            || sourceGeometry.BrepSolids is not
                [{ IsClosed: false } sourceSolid]
            || !sourceSolid.FaceIndices.SequenceEqual(
                Enumerable.Range(0, 25))
            || !WallVerticalParametersMatchSerializedBounds(
                wall, location, bounds))
            return Reject("source-contract");

        var alternativeFaces = sourceFaces
            .Select((face, index) => (face, index))
            .Where(item => item.face.AlternativeOuterVertices
                is { Count: > 0 }).ToList();
        if (sourceFaces.Any(face =>
                !ExactWorldCycle(face.OuterVertices, 4)
                || !FaceCanEmitAtIfcPrecision(face))
            || alternativeFaces is not [{ face: { } alternativeFace }]
            || !ExactWorldCycle(
                alternativeFace.AlternativeOuterVertices, 5)
            || sourceFaces.Count(face =>
                face.InnerVertices is { Count: > 0 }) != 2
            || sourceFaces.Where(face =>
                    face.InnerVertices is { Count: > 0 })
                .Any(face => face.InnerVertices is not
                    [{ Count: 4 }, { Count: 4 }]
                    || face.InnerVertices.Any(ring =>
                        !ExactWorldCycle(ring, 4))))
            return Reject("face-contract");

        bool TryGetOuterTopology(bool useAlternatives,
            out List<List<int>> components,
            out int vertexCount, out int edgeCount,
            out int useCount, out int singleCount,
            out int doubleCount)
        {
            components = [];
            vertexCount = edgeCount = useCount = singleCount = doubleCount = 0;
            var strippedFaces = new List<GeoFace>(sourceFaces.Count);
            var vertices = new HashSet<(long X, long Y, long Z)>();
            var edgeUses = new Dictionary<
                ((long X, long Y, long Z) First,
                 (long X, long Y, long Z) Second), int>();
            foreach (GeoFace face in sourceFaces)
            {
                IReadOnlyList<double[]> ring = useAlternatives
                    && face.AlternativeOuterVertices is { Count: > 0 }
                        ? face.AlternativeOuterVertices
                        : face.OuterVertices!;
                if (!ExactWorldCycle(ring, ring.Count))
                    return false;
                var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
                strippedFaces.Add(new GeoFace
                {
                    OuterVertices = ring.Select(point =>
                        (double[])point.Clone()).ToList(),
                });
                for (int index = 0; index < keys.Count; index++)
                {
                    vertices.Add(keys[index]);
                    var edge = OrderedWorldEdge(
                        keys[index], keys[(index + 1) % keys.Count]);
                    edgeUses[edge] = edgeUses.GetValueOrDefault(edge) + 1;
                }
            }
            if (edgeUses.Values.Any(value => value is not (1 or 2)))
                return false;
            components = GetExactFaceComponents(
                strippedFaces,
                Enumerable.Range(0, sourceFaces.Count).ToList());
            vertexCount = vertices.Count;
            edgeCount = edgeUses.Count;
            useCount = edgeUses.Values.Sum();
            singleCount = edgeUses.Values.Count(value => value == 1);
            doubleCount = edgeUses.Values.Count(value => value == 2);
            return true;
        }
        if (!TryGetOuterTopology(false,
                out var primaryComponents,
                out int primaryVertices, out int primaryEdges,
                out int primaryUses, out int primarySingles,
                out int primaryDoubles)
            || primaryVertices != 44 || primaryEdges != 60
            || primaryUses != 100 || primarySingles != 20
            || primaryDoubles != 40
            || !primaryComponents.Select(component => component.Count)
                .Order().SequenceEqual(new[] { 1, 1, 1, 4, 6, 6, 6 })
            || !TryGetOuterTopology(true,
                out var alternativeComponents,
                out int alternativeVertices, out int alternativeEdges,
                out int alternativeUses, out int alternativeSingles,
                out int alternativeDoubles)
            || alternativeVertices != 44 || alternativeEdges != 61
            || alternativeUses != 101 || alternativeSingles != 21
            || alternativeDoubles != 40
            || !alternativeComponents.Select(component => component.Count)
                .Order().SequenceEqual(new[] { 1, 3, 3, 6, 6, 6 }))
            return Reject("outer-topology");

        double axisX = location.EndPoint[0] - location.StartPoint[0];
        double axisY = location.EndPoint[1] - location.StartPoint[1];
        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return Reject("wall-axis");
        axisX /= axisLength;
        axisY /= axisLength;
        double normalX = -axisY, normalY = axisX;
        (double Along, double Normal, double Z) Project(
            IReadOnlyList<double> point) =>
        (
            point[0] * axisX + point[1] * axisY,
            point[0] * normalX + point[1] * normalY,
            point[2]
        );
        (long Along, long Normal, long Z) ProjectKey(
            IReadOnlyList<double> point)
        {
            var value = Project(point);
            return (
                IfcPrecisionBinMetres(value.Along * FeetToMetres),
                IfcPrecisionBinMetres(value.Normal * FeetToMetres),
                IfcPrecisionBinMetres(value.Z * FeetToMetres));
        }
        static long[] Levels(IEnumerable<long> values) =>
            values.Distinct().Order().ToArray();

        bool TryGetProjectedRectangularBox(
            IReadOnlyList<int> faceIndices,
            out ExactProjectedRectangularBox box)
        {
            box = default;
            if (faceIndices.Count != 6
                || faceIndices.Distinct().Count() != 6
                || faceIndices.Any(index =>
                    index < 0 || index >= sourceFaces.Count
                    || sourceFaces[index].OuterVertices is not { Count: 4 }
                    || sourceFaces[index].AlternativeOuterVertices
                        is { Count: > 0 }))
                return false;
            var stripped = faceIndices.Select(index => new GeoFace
            {
                OuterVertices = sourceFaces[index].OuterVertices!
                    .Select(point => (double[])point.Clone()).ToList(),
            }).ToList();
            if (!TryOrientExactFacetedShell(
                    stripped, Enumerable.Range(0, stripped.Count).ToList(),
                    out var oriented,
                    triangulateNonPlanarFaces: false))
                return false;
            var points = oriented.SelectMany(face => face.OuterVertices!).ToList();
            var keys = points.Select(ProjectKey).ToList();
            long[] along = Levels(keys.Select(key => key.Along));
            long[] normal = Levels(keys.Select(key => key.Normal));
            long[] z = Levels(keys.Select(key => key.Z));
            if (along.Length != 2 || normal.Length != 2 || z.Length != 2
                || keys.Distinct().Count() != 8
                || !along.SelectMany(a => normal.SelectMany(n =>
                        z.Select(level => (a, n, level))))
                    .All(corner => keys.Contains((
                        corner.a, corner.n, corner.level))))
                return false;

            int alongFaces = 0, normalFaces = 0, zFaces = 0;
            foreach (GeoFace face in oriented)
            {
                var faceKeys = face.OuterVertices!.Select(ProjectKey).ToList();
                int constantAxes = 0;
                if (faceKeys.Select(key => key.Along).Distinct().Count() == 1)
                {
                    alongFaces++;
                    constantAxes++;
                }
                if (faceKeys.Select(key => key.Normal).Distinct().Count() == 1)
                {
                    normalFaces++;
                    constantAxes++;
                }
                if (faceKeys.Select(key => key.Z).Distinct().Count() == 1)
                {
                    zFaces++;
                    constantAxes++;
                }
                if (constantAxes != 1)
                    return false;
            }
            if (alongFaces != 2 || normalFaces != 2 || zFaces != 2)
                return false;

            var projected = points.Select(Project).ToList();
            double minimumAlong = projected.Min(value => value.Along);
            double maximumAlong = projected.Max(value => value.Along);
            double minimumNormal = projected.Min(value => value.Normal);
            double maximumNormal = projected.Max(value => value.Normal);
            double minimumZ = projected.Min(value => value.Z);
            double maximumZ = projected.Max(value => value.Z);
            double centreAlong = (minimumAlong + maximumAlong) / 2;
            double centreNormal = (minimumNormal + maximumNormal) / 2;
            var definition = new HostedOpeningGeometry(
                centreAlong * axisX + centreNormal * normalX,
                centreAlong * axisY + centreNormal * normalY,
                axisX, axisY,
                maximumAlong - minimumAlong,
                maximumNormal - minimumNormal,
                minimumZ, maximumZ - minimumZ,
                ExactDepth: true,
                IsExactSerializedDefinition: true);
            var boxBounds = new[]
            {
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            };
            var boundary = new GeometryData
            {
                BoundingBox = boxBounds,
                Faces = oriented,
                BrepSolids =
                [
                    new GeoBrepSolid
                    {
                        FaceIndices = Enumerable.Range(0, 6).ToList(),
                        IsClosed = true,
                    },
                ],
            };
            if (!TryGetExactVerticalRectangularPrismSweptOpening(
                    boundary, out var recovered)
                || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                    definition, recovered))
                return false;
            box = new ExactProjectedRectangularBox(
                faceIndices.ToList(), boundary, definition,
                along[0], along[1], normal[0], normal[1], z[0], z[1]);
            return true;
        }

        var sixFaceComponents = primaryComponents
            .Where(component => component.Count == 6).ToList();
        var grossComponentMatches = sixFaceComponents.Where(component =>
                component.Count(index => sourceFaces[index].InnerVertices
                    is [{ Count: 4 }, { Count: 4 }]) == 2
                && component.Where(index => sourceFaces[index].InnerVertices
                        is not [{ Count: 4 }, { Count: 4 }])
                    .All(index => sourceFaces[index].InnerVertices
                        is not { Count: > 0 }))
            .ToList();
        if (grossComponentMatches.Count != 1
            || !TryGetProjectedRectangularBox(
                grossComponentMatches[0], out var grossBox)
            || grossBox.MaximumNormal - grossBox.MinimumNormal
                != IfcPrecisionBinMetres(widthFt * FeetToMetres))
            return Reject("gross-component");
        var pocketComponents = sixFaceComponents
            .Where(component => !ReferenceEquals(
                component, grossComponentMatches[0]))
            .ToList();
        var pocketBoxes = new List<ExactProjectedRectangularBox>();
        foreach (var component in pocketComponents)
        {
            if (component.Any(index =>
                    sourceFaces[index].InnerVertices is { Count: > 0 })
                || !TryGetProjectedRectangularBox(component, out var pocketBox))
                return Reject("pocket-component");
            pocketBoxes.Add(pocketBox);
        }
        if (pocketBoxes.Count != 2)
            return Reject("pocket-count");

        grossBoundary = grossBox.Boundary;
        grossBoundary.BoundingBox = (double[])wallBounds.Clone();
        if (!TryGetExactStraightWallVerticalExtrusionDefinition(
                grossBoundary, location, widthFt, bounds,
                out _, out _, out _, out string grossReason)
            || !CanExportStandardCaseWallAsSweptSolid(
                wall, bounds, grossBoundary,
                allowBoundaryOwnedVerticalDefinition: true))
            return Reject($"gross-definition-{grossReason}");

        var grossSideFaces = grossComponentMatches[0]
            .Select(index => (Index: index, Face: sourceFaces[index],
                Keys: sourceFaces[index].OuterVertices!
                    .Select(ProjectKey).ToList()))
            .Where(item => item.Keys.Select(key => key.Normal)
                .Distinct().Count() == 1)
            .OrderBy(item => item.Keys[0].Normal).ToList();
        if (grossSideFaces.Count != 2
            || grossSideFaces[0].Keys[0].Normal != grossBox.MinimumNormal
            || grossSideFaces[1].Keys[0].Normal != grossBox.MaximumNormal
            || grossSideFaces.Any(item => item.Face.InnerVertices
                is not [{ Count: 4 }, { Count: 4 }]))
            return Reject("gross-side-faces");

        var sideProfiles = new List<(int Side, List<double[]> Ring,
            long Normal, long[] Along, long[] Z)>();
        for (int sideIndex = 0; sideIndex < grossSideFaces.Count; sideIndex++)
        {
            var sideFace = grossSideFaces[sideIndex];
            foreach (var ring in sideFace.Face.InnerVertices!)
            {
                var keys = ring.Select(ProjectKey).ToList();
                long[] normalLevels = Levels(keys.Select(key => key.Normal));
                if (normalLevels.Length != 1
                    || normalLevels[0] != sideFace.Keys[0].Normal)
                    return Reject("side-profile-plane");
                sideProfiles.Add((sideIndex, ring, normalLevels[0],
                    Levels(keys.Select(key => key.Along)),
                    Levels(keys.Select(key => key.Z))));
            }
        }
        if (sideProfiles.Any(profile =>
                profile.Along.Length != 2 || profile.Z.Length != 2)
            || sideProfiles.Count != 4)
            return Reject("side-profiles");
        var crossSideProfilePairs =
            (from minimum in sideProfiles.Where(profile => profile.Side == 0)
             from maximum in sideProfiles.Where(profile => profile.Side == 1)
             where minimum.Along.SequenceEqual(maximum.Along)
                 && minimum.Z.SequenceEqual(maximum.Z)
             select (Minimum: minimum, Maximum: maximum)).ToList();
        if (crossSideProfilePairs.Count != 1)
            return Reject("through-profile-pair");
        var throughProfiles = crossSideProfilePairs[0];
        var pocketProfiles = sideProfiles.Where(profile =>
                !ReferenceEquals(profile.Ring, throughProfiles.Minimum.Ring)
                && !ReferenceEquals(profile.Ring, throughProfiles.Maximum.Ring))
            .ToList();
        if (pocketProfiles.Count != 2
            || pocketProfiles.Select(profile => profile.Side)
                .Distinct().Count() != 2)
            return Reject("pocket-profiles");

        bool PocketMatchesProfile(
            ExactProjectedRectangularBox pocket,
            (int Side, List<double[]> Ring, long Normal,
             long[] Along, long[] Z) profile) =>
            pocket.MinimumAlong == profile.Along[0]
            && pocket.MaximumAlong == profile.Along[1]
            && pocket.MinimumZ == profile.Z[0]
            && pocket.MaximumZ == profile.Z[1]
            && (profile.Side == 0
                ? pocket.MinimumNormal == grossBox.MinimumNormal
                    && pocket.MaximumNormal >
                        (grossBox.MinimumNormal + grossBox.MaximumNormal) / 2
                    && pocket.MaximumNormal < grossBox.MaximumNormal
                : pocket.MaximumNormal == grossBox.MaximumNormal
                    && pocket.MinimumNormal <
                        (grossBox.MinimumNormal + grossBox.MaximumNormal) / 2
                    && pocket.MinimumNormal > grossBox.MinimumNormal);
        var sourcePocketProfileMatches = new bool[2, 2];
        for (int pocketIndex = 0; pocketIndex < 2; pocketIndex++)
            for (int profileIndex = 0; profileIndex < 2; profileIndex++)
                sourcePocketProfileMatches[pocketIndex, profileIndex] =
                    PocketMatchesProfile(
                        pocketBoxes[pocketIndex], pocketProfiles[profileIndex]);
        if (Enumerable.Range(0, 2).Any(index =>
                Enumerable.Range(0, 2).Count(profile =>
                    sourcePocketProfileMatches[index, profile]) != 1)
            || Enumerable.Range(0, 2).Any(profile =>
                Enumerable.Range(0, 2).Count(index =>
                    sourcePocketProfileMatches[index, profile]) != 1))
            return Reject("source-pocket-profile-bijection");
        var minimumSidePocket = pocketBoxes.Single(pocket =>
            pocket.MinimumNormal == grossBox.MinimumNormal);
        var maximumSidePocket = pocketBoxes.Single(pocket =>
            pocket.MaximumNormal == grossBox.MaximumNormal);
        if (minimumSidePocket.MaximumNormal
                + maximumSidePocket.MinimumNormal
            != grossBox.MinimumNormal + grossBox.MaximumNormal
            || minimumSidePocket.MaximumNormal
                    - minimumSidePocket.MinimumNormal
                != maximumSidePocket.MaximumNormal
                    - maximumSidePocket.MinimumNormal
            || minimumSidePocket.MaximumAlong - minimumSidePocket.MinimumAlong
                != maximumSidePocket.MaximumAlong
                    - maximumSidePocket.MinimumAlong
            || minimumSidePocket.MaximumZ - minimumSidePocket.MinimumZ
                != maximumSidePocket.MaximumZ - maximumSidePocket.MinimumZ)
            return Reject("opposed-pocket-symmetry");

        var fourFaceComponents = primaryComponents
            .Where(component => component.Count == 4).ToList();
        if (fourFaceComponents.Count != 1)
            return Reject("through-component-count");
        var throughComponent = fourFaceComponents[0];
        var throughPoints = throughComponent.SelectMany(index =>
            sourceFaces[index].OuterVertices!).ToList();
        var throughKeys = throughPoints.Select(ProjectKey).ToList();
        int alternativeFaceIndex = alternativeFaces[0].index;
        long[] throughAlong = Levels(throughKeys.Select(key => key.Along));
        long[] throughNormal = Levels(throughKeys.Select(key => key.Normal));
        long[] throughZ = Levels(throughKeys.Select(key => key.Z));
        int throughAlongFaces = 0, throughNormalFaces = 0, throughZFaces = 0;
        foreach (int index in throughComponent)
        {
            var keys = sourceFaces[index].OuterVertices!
                .Select(ProjectKey).ToList();
            if (keys.Select(key => key.Along).Distinct().Count() == 1)
                throughAlongFaces++;
            if (keys.Select(key => key.Normal).Distinct().Count() == 1)
                throughNormalFaces++;
            if (keys.Select(key => key.Z).Distinct().Count() == 1)
                throughZFaces++;
        }
        if (throughAlong.Length != 2 || throughNormal.Length != 2
            || throughZ.Length != 2 || throughKeys.Distinct().Count() != 8
            || throughNormal[0] != grossBox.MinimumNormal
            || throughNormal[1] != grossBox.MaximumNormal
            || throughAlongFaces != 2 || throughNormalFaces != 0
            || throughZFaces != 2
            || !throughAlong.SequenceEqual(throughProfiles.Minimum.Along)
            || !throughZ.SequenceEqual(throughProfiles.Minimum.Z)
            || !throughComponent.Contains(alternativeFaceIndex))
            return Reject("through-component");

        var singletonComponents = primaryComponents
            .Where(component => component.Count == 1).ToList();
        if (singletonComponents.Count != 3)
            return Reject("singleton-count");
        var outerThroughFaces = new List<(int Index, long Normal)>();
        foreach (var component in singletonComponents)
        {
            int index = component[0];
            var keys = sourceFaces[index].OuterVertices!
                .Select(ProjectKey).ToList();
            long[] faceAlong = Levels(keys.Select(key => key.Along));
            long[] faceNormal = Levels(keys.Select(key => key.Normal));
            long[] faceZ = Levels(keys.Select(key => key.Z));
            if (faceAlong.SequenceEqual(throughAlong)
                && faceNormal.Length == 1
                && faceZ.SequenceEqual(throughZ)
                && (faceNormal[0] < grossBox.MinimumNormal
                    || faceNormal[0] > grossBox.MaximumNormal))
                outerThroughFaces.Add((index, faceNormal[0]));
        }
        if (outerThroughFaces.Count != 2
            || outerThroughFaces.Count(face =>
                face.Normal < grossBox.MinimumNormal) != 1
            || outerThroughFaces.Count(face =>
                face.Normal > grossBox.MaximumNormal) != 1)
            return Reject("outer-through-faces");
        var detachedComponents = singletonComponents.Where(component =>
            !outerThroughFaces.Any(face => face.Index == component[0])).ToList();
        if (detachedComponents.Count != 1)
            return Reject("detached-count");
        var detachedKeys = sourceFaces[detachedComponents[0][0]]
            .OuterVertices!.Select(ProjectKey).ToList();
        long[] detachedAlong = Levels(detachedKeys.Select(key => key.Along));
        long[] detachedNormal = Levels(detachedKeys.Select(key => key.Normal));
        long[] detachedZ = Levels(detachedKeys.Select(key => key.Z));
        long[] locationAlong = Levels(new[]
        {
            ProjectKey(location.StartPoint).Along,
            ProjectKey(location.EndPoint).Along,
        });
        if (detachedAlong.Length != 1 || detachedNormal.Length != 2
            || !detachedZ.SequenceEqual(
                new[] { grossBox.MinimumZ, grossBox.MaximumZ })
            || detachedNormal[0] <= grossBox.MinimumNormal
            || detachedNormal[1] >= grossBox.MaximumNormal
            || detachedNormal[0] + detachedNormal[1]
                != grossBox.MinimumNormal + grossBox.MaximumNormal
            || !locationAlong.Contains(detachedAlong[0])
            || detachedAlong[0] >= grossBox.MinimumAlong
                && detachedAlong[0] <= grossBox.MaximumAlong
            || locationAlong.Length != 2
            || locationAlong[0] >= grossBox.MinimumAlong
            || locationAlong[1] <= grossBox.MaximumAlong)
            return Reject("detached-patch");

        var outerThroughNormals = outerThroughFaces
            .Select(face => face.Normal).Order().ToArray();
        if (alternativeFace.AlternativeOuterVertices is not { } alternativeOuter)
            return Reject("face-contract");
        var alternativeKeys = alternativeOuter
            .Select(ProjectKey).ToList();
        long[] alternativeAlong = Levels(
            alternativeKeys.Select(key => key.Along));
        long[] alternativeNormal = Levels(
            alternativeKeys.Select(key => key.Normal));
        long[] alternativeZ = Levels(alternativeKeys.Select(key => key.Z));
        long redundantNormal = alternativeNormal.Length == 3
            ? alternativeNormal[1] : long.MinValue;
        if (alternativeAlong.Length != 1
            || !throughAlong.Contains(alternativeAlong[0])
            || alternativeNormal.Length != 3
            || alternativeNormal[0] != outerThroughNormals[0]
            || alternativeNormal[2] != outerThroughNormals[1]
            || redundantNormal != grossBox.MinimumNormal
                && redundantNormal != grossBox.MaximumNormal
            || !alternativeZ.SequenceEqual(throughZ)
            || alternativeKeys.Count(key =>
                key.Normal == redundantNormal) != 1)
            return Reject("alternative-through-end");
        int redundantIndex = alternativeKeys.FindIndex(key =>
            key.Normal == redundantNormal);
        var alternativeWithoutRedundant = alternativeOuter
            .Where((_, index) => index != redundantIndex).ToList();
        var expectedAlternativeCorners = new List<double[]>();
        double alternativeAlongFt = Project(
            alternativeOuter[0]).Along;
        double minimumOuterNormalFt = outerThroughFaces
            .Where(face => face.Normal == outerThroughNormals[0])
            .SelectMany(face => sourceFaces[face.Index].OuterVertices!)
            .Select(point => Project(point).Normal).Min();
        double maximumOuterNormalFt = outerThroughFaces
            .Where(face => face.Normal == outerThroughNormals[1])
            .SelectMany(face => sourceFaces[face.Index].OuterVertices!)
            .Select(point => Project(point).Normal).Max();
        double minimumThroughZFt = throughPoints.Min(point => point[2]);
        double maximumThroughZFt = throughPoints.Max(point => point[2]);
        foreach (var corner in new[]
                 {
                     (Normal: minimumOuterNormalFt, Z: minimumThroughZFt),
                     (Normal: maximumOuterNormalFt, Z: minimumThroughZFt),
                     (Normal: maximumOuterNormalFt, Z: maximumThroughZFt),
                     (Normal: minimumOuterNormalFt, Z: maximumThroughZFt),
                 })
            expectedAlternativeCorners.Add(
            [
                alternativeAlongFt * axisX + corner.Normal * normalX,
                alternativeAlongFt * axisY + corner.Normal * normalY,
                corner.Z,
            ]);
        if (!WorldRingMatches(
                alternativeWithoutRedundant, expectedAlternativeCorners))
            return Reject("alternative-cycle");

        if (!TryBuildStraightWallBoundary(wall, out var exactRebuilt)
            || exactRebuilt.Faces is not { Count: 14 } exactRebuiltFaces
            || exactRebuiltFaces.Count(face =>
                face.InnerVertices is [{ Count: 4 }, { Count: 4 }]) != 2
            || exactRebuiltFaces.Where(face =>
                    face.InnerVertices is not [{ Count: 4 }, { Count: 4 }])
                .Any(face => face.InnerVertices is { Count: > 0 })
            || exactRebuiltFaces.Any(face =>
                !ExactWorldCycle(face.OuterVertices, 4)
                || face.AlternativeOuterVertices is { Count: > 0 })
            || !BoundaryMatches(exactRebuilt, rebuiltBoundary))
            return Reject("rebuilt-contract");
        var sourceOuterRings = sourceFaces.Select(face =>
            face.OuterVertices!).ToList();
        int retainedSourceOuterCycles = exactRebuiltFaces.Count(face =>
            sourceOuterRings.Any(ring =>
                WorldRingMatches(ring, face.OuterVertices)));
        int exactInnerCycles = exactRebuiltFaces
            .SelectMany(face => face.InnerVertices ?? [])
            .Count(ring => sourceFaces
                .SelectMany(face => face.InnerVertices ?? [])
                .Any(sourceRing => WorldRingMatches(sourceRing, ring)));
        if (retainedSourceOuterCycles != 10 || exactInnerCycles != 4)
            return Reject("rebuilt-cycle-map");

        if (standaloneOpeningIdsByWall != null
            && standaloneOpeningIdsByWall.TryGetValue(
                wall.Id, out var standaloneIds)
            && standaloneIds.Count > 0)
            return Reject($"standalone-openings-{standaloneIds.Count}");
        if (wall.CuttingElementIds is not { Count: 3 } decodedCutterIds
            || decodedCutterIds.Distinct().Count() != 3
            || emittedHostedCutterIdsByWall == null
            || !emittedHostedCutterIdsByWall.TryGetValue(
                wall.Id, out var emittedCutterIds)
            || emittedCutterIds.Count != 3
            || emittedCutterIds.Distinct().Count() != 3
            || !decodedCutterIds.ToHashSet().SetEquals(emittedCutterIds)
            || emittedHostedOpeningOperandsByWall == null
            || !emittedHostedOpeningOperandsByWall.TryGetValue(
                wall.Id, out var emittedOperands)
            || emittedOperands.Count != 3
            || emittedOperands.Select(item => item.CutterId)
                .Distinct().Count() != 3
            || !emittedOperands.Select(item => item.CutterId)
                .ToHashSet().SetEquals(decodedCutterIds))
            return Reject("emitted-cutter-contract");

        var cutters = new List<Element>(3);
        foreach (int cutterId in decodedCutterIds)
        {
            if (!elementsById.TryGetValue(cutterId, out var cutter)
                || cutter.BoundingBox is not { Length: 6 } cutterBounds
                || cutterBounds.Any(value => !double.IsFinite(value))
                || cutter.HostId is not > 0
                || cutter.SerializedHostId != cutter.HostId
                || cutter.HostId != wall.Id
                || !Empty(cutter.ExtraHostIds)
                || !Empty(cutter.ExplicitHostIds)
                || cutter.SuperInstanceId is > 0
                || cutter.References?.Count(id => id == wall.Id) != 1
                || wall.References?.Count(id => id == cutterId) != 1
                || !inverseHostedHostIds.TryGetValue(
                    cutterId, out var inverseIds)
                || inverseIds.Count != 1 || inverseIds[0] != wall.Id
                || !HostedElementCanCutHost(cutterBounds, wall))
                return Reject("cutter-graph", cutterId);
            cutters.Add(cutter);
        }
        var genericCutters = cutters
            .Where(cutter => cutter.CategoryId == -2000151).ToList();
        var doorCutters = cutters
            .Where(cutter => cutter.CategoryId == -2000023).ToList();
        if (genericCutters.Count != 2 || doorCutters.Count != 1
            || cutters.Any(cutter => cutter.CategoryId
                is not (-2000151 or -2000023)))
            return Reject("cutter-roles");

        var genericFamilyTypeIds = new List<int>(2);
        var genericSymbolIds = new HashSet<int>();
        var legacyGenericOpenings = new List<
            (Element Cutter, HostedOpeningGeometry Opening)>();
        foreach (Element cutter in genericCutters)
        {
            var familyTypeParameters = cutter.Parameters.Where(parameter =>
                    parameter.Definition?.Name == "ELEM_TYPE_PARAM")
                .ToList();
            if (familyTypeParameters is not
                [{ Id: -1002050, StorageType: StorageType.ElementId,
                    Value: int familyTypeId }]
                || familyTypeId <= 0 || familyTypeId == cutter.Id
                || !elementsById.TryGetValue(
                    familyTypeId, out var familyType)
                || cutter.Transform is not
                    { SymbolId: > 0 } transform
                || !genericSymbolIds.Add(transform.SymbolId)
                || cutter.Geometry?.ExactMappedInstances
                    is not [{ } mappedInstance]
                || mappedInstance.SymbolId != transform.SymbolId
                || mappedInstance.Transform.Length < 12
                || mappedInstance.Transform.Any(value => !double.IsFinite(value))
                || !elementsById.TryGetValue(
                    transform.SymbolId, out var mappedSymbol)
                || mappedSymbol.Id == familyTypeId
                || mappedSymbol.FamilyCutGeometry != null
                || mappedSymbol.FamilyCutClosurePlaneOrigin != null
                || mappedSymbol.FamilyCutClosurePlaneNormal != null
                || mappedSymbol.FamilyCutLoops is { Count: > 0 }
                || familyType.FamilyCutGeometry != null
                || familyType.FamilyCutClosurePlaneOrigin != null
                || familyType.FamilyCutClosurePlaneNormal != null
                || familyType.FamilyCutLoops is { Count: > 0 }
                || LinkedFamilyCutTypes(cutter, elementsById).Count != 0)
                return Reject("generic-family-contract", cutter.Id);
            genericFamilyTypeIds.Add(familyTypeId);
            if (!TryBuildSerializedHostedOpeningGeometry(
                    cutter, LinkedFamilyType(cutter, elementsById),
                    out var legacyOpening)
                || !legacyOpening.ExactDepth
                || !legacyOpening.IsExactSerializedDefinition
                || legacyOpening.IsFamilyCutLoop
                || legacyOpening.Boundary != null
                || legacyOpening.SteppedProfile != null)
                return Reject("generic-legacy-opening", cutter.Id);
            var emitted = emittedOperands.Where(item =>
                item.CutterId == cutter.Id).ToList();
            if (emitted.Count != 1
                || !RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                    emitted[0].Operand, legacyOpening))
                return Reject("generic-emitted-opening", cutter.Id);
            legacyGenericOpenings.Add((cutter, legacyOpening));
        }
        if (genericFamilyTypeIds.Distinct().Count() != 1)
            return Reject("generic-family-bijection");

        (long[] Along, long[] Normal, long[] Z) OpeningLevels(
            HostedOpeningGeometry opening)
        {
            double openingAxisLength = Math.Sqrt(
                opening.AxisX * opening.AxisX
                + opening.AxisY * opening.AxisY);
            if (!(openingAxisLength > 0) || !double.IsFinite(openingAxisLength)
                || !(opening.WidthFt > 0) || !(opening.DepthFt > 0)
                || !(opening.HeightFt > 0))
                return ([], [], []);
            double openingAxisX = opening.AxisX / openingAxisLength;
            double openingAxisY = opening.AxisY / openingAxisLength;
            double openingNormalX = -openingAxisY;
            double openingNormalY = openingAxisX;
            var corners = new List<double[]>(8);
            foreach (double z in new[]
                     { opening.BaseZFt,
                       opening.BaseZFt + opening.HeightFt })
                foreach (double along in new[]
                         { -opening.WidthFt / 2, opening.WidthFt / 2 })
                    foreach (double normal in new[]
                             { -opening.DepthFt / 2,
                               opening.DepthFt / 2 })
                        corners.Add(
                        [
                            opening.CentreXFt + along * openingAxisX
                                + normal * openingNormalX,
                            opening.CentreYFt + along * openingAxisY
                                + normal * openingNormalY,
                            z,
                        ]);
            var keys = corners.Select(ProjectKey).ToList();
            return (Levels(keys.Select(key => key.Along)),
                Levels(keys.Select(key => key.Normal)),
                Levels(keys.Select(key => key.Z)));
        }

        var legacyPocketMatches = new bool[2, 2];
        for (int cutterIndex = 0; cutterIndex < 2; cutterIndex++)
        {
            var levels = OpeningLevels(
                legacyGenericOpenings[cutterIndex].Opening);
            if (levels.Along.Length != 2 || levels.Normal.Length != 2
                || levels.Z.Length != 2
                || levels.Normal[0] + levels.Normal[1]
                    != grossBox.MinimumNormal + grossBox.MaximumNormal)
                return Reject("generic-legacy-levels",
                    legacyGenericOpenings[cutterIndex].Cutter.Id);
            for (int pocketIndex = 0; pocketIndex < 2; pocketIndex++)
            {
                ExactProjectedRectangularBox pocket = pocketBoxes[pocketIndex];
                legacyPocketMatches[cutterIndex, pocketIndex] =
                    levels.Along.SequenceEqual(
                        new[] { pocket.MinimumAlong, pocket.MaximumAlong })
                    && levels.Z.SequenceEqual(
                        new[] { pocket.MinimumZ, pocket.MaximumZ })
                    && levels.Normal[1] - levels.Normal[0]
                        == pocket.MaximumNormal - pocket.MinimumNormal;
            }
        }
        if (Enumerable.Range(0, 2).Any(cutter =>
                Enumerable.Range(0, 2).Count(pocket =>
                    legacyPocketMatches[cutter, pocket]) != 1)
            || Enumerable.Range(0, 2).Any(pocket =>
                Enumerable.Range(0, 2).Count(cutter =>
                    legacyPocketMatches[cutter, pocket]) != 1))
            return Reject("generic-pocket-bijection");

        var correctedWriterOperands = new List<
            (int CutterId, HostedOpeningGeometry Operand)>(2);
        for (int cutterIndex = 0; cutterIndex < 2; cutterIndex++)
        {
            int pocketIndex = Enumerable.Range(0, 2).Single(index =>
                legacyPocketMatches[cutterIndex, index]);
            ExactProjectedRectangularBox pocket = pocketBoxes[pocketIndex];
            HostedOpeningGeometry corrected = pocket.Definition with
            {
                Boundary = pocket.Boundary,
                ExactDepth = true,
                IsExactSerializedDefinition = true,
            };
            if (!TryGetExactVerticalRectangularPrismSweptOpeningAlignedToDefinition(
                    corrected.Boundary, corrected, out _))
                return Reject("corrected-pocket-definition",
                    legacyGenericOpenings[cutterIndex].Cutter.Id);
            correctedWriterOperands.Add((
                legacyGenericOpenings[cutterIndex].Cutter.Id, corrected));
        }

        Element door = doorCutters[0];
        var emittedDoor = emittedOperands.Where(item =>
            item.CutterId == door.Id).ToList();
        if (emittedDoor.Count != 1)
            return Reject("door-emitted-opening", door.Id);
        HostedOpeningGeometry doorOpening = emittedDoor[0].Operand;
        if (!doorOpening.ExactDepth || doorOpening.IsFamilyCutLoop
            || doorOpening.SteppedProfile != null
            || doorOpening.Boundary != null
                && !TryGetExactVerticalRectangularPrismSweptOpeningAlignedToDefinition(
                    doorOpening.Boundary, doorOpening, out _))
            return Reject("door-opening", door.Id);
        double doorMinimumAlongFt = throughPoints
            .Select(point => Project(point).Along).Min();
        double doorMaximumAlongFt = throughPoints
            .Select(point => Project(point).Along).Max();
        double doorCentreAlongFt =
            (doorMinimumAlongFt + doorMaximumAlongFt) / 2;
        double doorCentreNormalFt =
            (minimumOuterNormalFt + maximumOuterNormalFt) / 2;
        var sourceDoorOpening = new HostedOpeningGeometry(
            doorCentreAlongFt * axisX + doorCentreNormalFt * normalX,
            doorCentreAlongFt * axisY + doorCentreNormalFt * normalY,
            axisX, axisY,
            doorMaximumAlongFt - doorMinimumAlongFt,
            maximumOuterNormalFt - minimumOuterNormalFt,
            minimumThroughZFt,
            maximumThroughZFt - minimumThroughZFt,
            ExactDepth: true);
        if (!RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                sourceDoorOpening, doorOpening))
            return Reject("door-source-envelope", door.Id);

        cutterElementIds = emittedCutterIds.ToList();
        exactSidePocketWriterOperands = correctedWriterOperands;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFC25FACEPOCKETGATE wall={wall.Id} "
                + $"cutters={string.Join(',', cutterElementIds)} "
                + $"pockets={string.Join(',', correctedWriterOperands
                    .Select(item => item.CutterId))} "
                + "result=accept stage=exact-source-bijection");
        return true;
    }

    /// <summary>
    /// Recovers one exact quartered reveal from a deliberately redundant RVT source contract.
    /// </summary>
    internal static bool
        TryBuildExactQuarteredRevealOpeningFromCompleteOpenTenFaceHoleWithDetachedPatch(
            Element hostedElement,
            IReadOnlyList<Element> candidateHostWalls,
            IReadOnlyDictionary<int, Element> elementsById,
            IReadOnlyDictionary<int, List<int>> inverseHostedHostIds,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCQUARTEREDSOURCEGATE cutter={hostedElement.Id} "
                    + $"result=reject stage={stage}");
            return false;
        }

        static bool Empty(IReadOnlyCollection<int>? values) =>
            values is not { Count: > 0 };
        static ((long X, long Y, long Z) First,
            (long X, long Y, long Z) Second) OrderedWorldEdge(
                (long X, long Y, long Z) first,
                (long X, long Y, long Z) second) =>
            first.CompareTo(second) <= 0
                ? (first, second) : (second, first);
        static bool ExactWorldCycle(
            IReadOnlyList<double[]>? ring, int expectedCount)
        {
            if (ring == null || ring.Count != expectedCount
                || ring.Any(point => point.Length < 3
                    || point.Take(3).Any(value => !double.IsFinite(value))))
                return false;
            try
            {
                var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
                return keys.Distinct().Count() == expectedCount
                    && Enumerable.Range(0, keys.Count)
                        .Select(index => OrderedWorldEdge(
                            keys[index], keys[(index + 1) % keys.Count]))
                        .Distinct().Count() == expectedCount;
            }
            catch (OverflowException)
            {
                return false;
            }
        }
        static bool WorldRingMatches(
            IReadOnlyList<double[]>? first,
            IReadOnlyList<double[]>? second)
        {
            if (first == null || second == null
                || first.Count != second.Count
                || !ExactWorldCycle(first, first.Count)
                || !ExactWorldCycle(second, second.Count))
                return false;
            var firstKeys = first.Select(IfcPrecisionKeyFeet).ToList();
            var secondKeys = second.Select(IfcPrecisionKeyFeet).ToList();
            var firstEdges = Enumerable.Range(0, firstKeys.Count)
                .Select(index => OrderedWorldEdge(
                    firstKeys[index], firstKeys[(index + 1) % firstKeys.Count]))
                .ToHashSet();
            var secondEdges = Enumerable.Range(0, secondKeys.Count)
                .Select(index => OrderedWorldEdge(
                    secondKeys[index],
                    secondKeys[(index + 1) % secondKeys.Count]))
                .ToHashSet();
            return firstKeys.ToHashSet().SetEquals(secondKeys)
                && firstEdges.SetEquals(secondEdges);
        }
        static bool PrimaryFaceMatches(GeoFace source, GeoFace rebuilt)
        {
            if (!WorldRingMatches(source.OuterVertices, rebuilt.OuterVertices)
                || rebuilt.AlternativeOuterVertices is { Count: > 0 })
                return false;
            var sourceInner = source.InnerVertices ?? [];
            var rebuiltInner = rebuilt.InnerVertices ?? [];
            if (sourceInner.Count != rebuiltInner.Count)
                return false;
            var unused = Enumerable.Range(0, rebuiltInner.Count).ToHashSet();
            foreach (var sourceRing in sourceInner)
            {
                var matches = unused.Where(index =>
                    WorldRingMatches(sourceRing, rebuiltInner[index])).ToList();
                if (matches.Count != 1)
                    return false;
                unused.Remove(matches[0]);
            }
            return unused.Count == 0;
        }

        bool HasOuterTopology(
            IReadOnlyList<GeoFace> faces,
            IReadOnlyList<int> faceIndices,
            bool useAlternatives,
            int expectedVertices, int expectedEdges, int expectedUses,
            int expectedSingle, int expectedDouble, int expectedTriple,
            IReadOnlyList<int> expectedComponentSizes)
        {
            var vertices = new HashSet<(long X, long Y, long Z)>();
            var edgeUses = new Dictionary<
                ((long X, long Y, long Z) First,
                 (long X, long Y, long Z) Second), int>();
            var edgesByFace = new Dictionary<int, HashSet<
                ((long X, long Y, long Z) First,
                 (long X, long Y, long Z) Second)>>();
            foreach (int faceIndex in faceIndices)
            {
                if (faceIndex < 0 || faceIndex >= faces.Count)
                    return false;
                GeoFace face = faces[faceIndex];
                IReadOnlyList<double[]>? ring = useAlternatives
                    && face.AlternativeOuterVertices is { Count: > 0 }
                        ? face.AlternativeOuterVertices
                        : face.OuterVertices;
                if (ring == null || !ExactWorldCycle(ring, ring.Count))
                    return false;
                var keys = ring.Select(IfcPrecisionKeyFeet).ToList();
                var faceEdges = new HashSet<
                    ((long X, long Y, long Z) First,
                     (long X, long Y, long Z) Second)>();
                for (int index = 0; index < keys.Count; index++)
                {
                    vertices.Add(keys[index]);
                    var edge = OrderedWorldEdge(
                        keys[index], keys[(index + 1) % keys.Count]);
                    if (!faceEdges.Add(edge))
                        return false;
                    edgeUses[edge] = edgeUses.GetValueOrDefault(edge) + 1;
                }
                edgesByFace[faceIndex] = faceEdges;
            }
            var componentSizes = new List<int>();
            var unvisited = faceIndices.ToHashSet();
            while (unvisited.Count > 0)
            {
                int seed = unvisited.Min();
                unvisited.Remove(seed);
                int size = 0;
                var queue = new Queue<int>();
                queue.Enqueue(seed);
                while (queue.Count > 0)
                {
                    int current = queue.Dequeue();
                    size++;
                    foreach (int candidate in unvisited.ToList())
                        if (edgesByFace[current].Overlaps(edgesByFace[candidate]))
                        {
                            unvisited.Remove(candidate);
                            queue.Enqueue(candidate);
                        }
                }
                componentSizes.Add(size);
            }
            return vertices.Count == expectedVertices
                && edgeUses.Count == expectedEdges
                && edgeUses.Values.Sum() == expectedUses
                && edgeUses.Values.Count(value => value == 1) == expectedSingle
                && edgeUses.Values.Count(value => value == 2) == expectedDouble
                && edgeUses.Values.Count(value => value == 3) == expectedTriple
                && edgeUses.Values.All(value => value is 1 or 2 or 3)
                && componentSizes.Order()
                    .SequenceEqual(expectedComponentSizes.Order());
        }

        bool TryGetExactSource(
            Element wall,
            out GeometryData grossBoundary,
            out RectangularWallThroughOpening hole,
            out HostedOpeningGeometry outerPrimitive)
        {
            grossBoundary = new GeometryData();
            hole = default;
            outerPrimitive = default;
            bool SourceReject(string stage)
            {
                if (diagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCQUARTEREDSOURCEGATE cutter={hostedElement.Id} "
                        + $"wall={wall.Id} source=reject stage={stage}");
                return false;
            }
            if (wall.BoundingBox is not { Length: 6 } bounds
                || bounds.Any(value => !double.IsFinite(value))
                || wall.Location is not
                    { CurveType: "Line", ArcRadius: null } location
                || !TryGetSerializedWallWidthFeet(wall, out double widthFt)
                || wall.Geometry is not { } sourceGeometry
                || sourceGeometry.BoundingBox is not
                    { Length: 6 } sourceBounds
                || sourceBounds.Any(value => !double.IsFinite(value))
                || !BoundsMatchAtIfcPrecision(sourceBounds, bounds)
                || sourceGeometry.Faces is not { Count: 11 } sourceFaces
                || sourceGeometry.BrepSolids is not { Count: 1 } sourceSolids
                || sourceSolids[0].IsClosed
                || !sourceSolids[0].FaceIndices.SequenceEqual(
                    Enumerable.Range(0, 10))
                || !WallVerticalParametersMatchSerializedBounds(
                    wall, location, bounds))
                return SourceReject("source-contract");
            if (sourceFaces.Any(face =>
                    !ExactWorldCycle(face.OuterVertices, 4)
                    || !FaceCanEmitAtIfcPrecision(face))
                || sourceFaces[0].InnerVertices is not [{ Count: 4 } firstSourceHole]
                || sourceFaces[2].InnerVertices is not [{ Count: 4 } thirdSourceHole]
                || !ExactWorldCycle(firstSourceHole, 4)
                || !ExactWorldCycle(thirdSourceHole, 4)
                || sourceFaces.Where((_, index) => index is not 0 and not 2)
                    .Any(face => face.InnerVertices is { Count: > 0 })
                || sourceFaces.Where((_, index) => index is not 6 and not 7)
                    .Any(face => face.AlternativeOuterVertices
                        is { Count: > 0 })
                || !ExactWorldCycle(
                    sourceFaces[6].AlternativeOuterVertices, 4)
                || !ExactWorldCycle(
                    sourceFaces[7].AlternativeOuterVertices, 9))
                return SourceReject("face-contract");

            if (!TryBuildStraightWallBoundary(wall, out var rebuiltBoundary))
                return SourceReject("rebuilt-build");
            if (rebuiltBoundary.Faces is not { Count: 10 } rebuiltFaces)
                return SourceReject(
                    $"rebuilt-shell-faces-{rebuiltBoundary.Faces?.Count ?? -1}");
            if (rebuiltBoundary.BrepSolids is not { Count: 1 } rebuiltSolids)
                return SourceReject(
                    $"rebuilt-solid-count-"
                    + $"{rebuiltBoundary.BrepSolids?.Count ?? -1}");
            GeoBrepSolid rebuiltSolid = rebuiltSolids[0];
            if (!rebuiltSolid.IsClosed
                || !rebuiltSolid.FaceIndices.SequenceEqual(
                    Enumerable.Range(0, 10)))
                return SourceReject(
                    $"rebuilt-solid-closed-{rebuiltSolid.IsClosed}-"
                    + $"indices-{string.Join(',', rebuiltSolid.FaceIndices)}");
            if (!TryGetExactStraightWallGrossBoundaryAndOpenings(
                    rebuiltBoundary, location, widthFt, bounds,
                    out var candidateGross, out var holes,
                    out string grossReason)
                || holes.Count != 1)
                return SourceReject(
                    $"rebuilt-gross-{grossReason}-holes-{holes.Count}");
            var exactHole = holes[0];

            int[] expectedRebuiltMatches =
                [0, 5, 1, 3, 4, 2, 6, 7, 8, 9];
            var actualRebuiltMatches = new List<int>(10);
            for (int sourceIndex = 0; sourceIndex < 10; sourceIndex++)
            {
                var matches = rebuiltFaces
                    .Select((face, index) => (face, index))
                    .Where(item => PrimaryFaceMatches(
                        sourceFaces[sourceIndex], item.face))
                    .Select(item => item.index).ToList();
                if (matches.Count != 1)
                    return SourceReject(
                        $"source-rebuilt-face-{sourceIndex}-"
                        + string.Join(',', matches));
                actualRebuiltMatches.Add(matches[0]);
            }
            if (!actualRebuiltMatches.SequenceEqual(expectedRebuiltMatches))
                return SourceReject("source-rebuilt-map-"
                    + string.Join(',', actualRebuiltMatches));
            if (rebuiltFaces.Any(face =>
                    PrimaryFaceMatches(sourceFaces[10], face)))
                return SourceReject("detached-rebuilt-match");
            var ownedIndices = Enumerable.Range(0, 10).ToList();
            var completeIndices = Enumerable.Range(0, 11).ToList();
            if (!HasOuterTopology(sourceFaces, ownedIndices, false,
                    16, 24, 40, 8, 16, 0, [6, 4])
                || !HasOuterTopology(sourceFaces, completeIndices, false,
                    18, 27, 44, 11, 15, 1, [7, 4])
                || !HasOuterTopology(sourceFaces, ownedIndices, true,
                    25, 32, 45, 19, 13, 0, [6, 2, 1, 1])
                || !HasOuterTopology(sourceFaces, completeIndices, true,
                    27, 35, 49, 22, 12, 1, [7, 2, 1, 1]))
                return SourceReject("topology");

            double axisX = location.EndPoint[0] - location.StartPoint[0];
            double axisY = location.EndPoint[1] - location.StartPoint[1];
            double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
            if (!(axisLength > 0) || !double.IsFinite(axisLength))
                return SourceReject("axis");
            axisX /= axisLength;
            axisY /= axisLength;
            double normalX = -axisY, normalY = axisX;
            (long Along, long Normal, long Z) Project(
                IReadOnlyList<double> point) =>
            (
                IfcPrecisionBinMetres(
                    (point[0] * axisX + point[1] * axisY) * FeetToMetres),
                IfcPrecisionBinMetres(
                    (point[0] * normalX + point[1] * normalY) * FeetToMetres),
                IfcPrecisionBinMetres(point[2] * FeetToMetres)
            );
            static ((long Along, long Normal, long Z) First,
                (long Along, long Normal, long Z) Second)
                OrderedProjectedEdge(
                    (long Along, long Normal, long Z) first,
                    (long Along, long Normal, long Z) second) =>
                first.CompareTo(second) <= 0
                    ? (first, second) : (second, first);
            static HashSet<
                ((long Along, long Normal, long Z) First,
                 (long Along, long Normal, long Z) Second)>
                ProjectedEdges(
                    IReadOnlyList<(long Along, long Normal, long Z)> cycle) =>
                Enumerable.Range(0, cycle.Count)
                    .Select(index => OrderedProjectedEdge(
                        cycle[index], cycle[(index + 1) % cycle.Count]))
                    .ToHashSet();
            bool ProjectedCycleMatches(
                IReadOnlyList<double[]> ring,
                IReadOnlyList<(long Along, long Normal, long Z)> expected)
            {
                var actual = ring.Select(Project).ToList();
                return actual.Count == expected.Count
                    && actual.Distinct().Count() == actual.Count
                    && actual.ToHashSet().SetEquals(expected)
                    && ProjectedEdges(actual).SetEquals(ProjectedEdges(expected));
            }
            static List<long> Levels(IEnumerable<long> values) =>
                values.Distinct().Order().ToList();

            var firstOuter = sourceFaces[0].OuterVertices!
                .Select(Project).ToList();
            var secondOuter = sourceFaces[2].OuterVertices!
                .Select(Project).ToList();
            var firstHole = sourceFaces[0].InnerVertices![0]
                .Select(Project).ToList();
            var secondHole = sourceFaces[2].InnerVertices![0]
                .Select(Project).ToList();
            var grossAlong = Levels(firstOuter.Select(value => value.Along));
            var grossZ = Levels(firstOuter.Select(value => value.Z));
            var firstNormal = Levels(firstOuter.Select(value => value.Normal));
            var secondNormal = Levels(secondOuter.Select(value => value.Normal));
            var holeAlong = Levels(firstHole.Select(value => value.Along));
            var holeZ = Levels(firstHole.Select(value => value.Z));
            if (grossAlong.Count != 2 || grossZ.Count != 2
                || firstNormal is not [{ } minimumNormal]
                || secondNormal is not [{ } maximumNormal]
                || maximumNormal - minimumNormal
                    != IfcPrecisionBinMetres(widthFt * FeetToMetres)
                || minimumNormal >= maximumNormal
                || holeAlong.Count != 2 || holeZ.Count != 2
                || !Levels(secondHole.Select(value => value.Along))
                    .SequenceEqual(holeAlong)
                || !Levels(secondHole.Select(value => value.Z))
                    .SequenceEqual(holeZ)
                || Levels(firstHole.Select(value => value.Normal))
                    is not [{ } firstHoleNormal]
                || Levels(secondHole.Select(value => value.Normal))
                    is not [{ } secondHoleNormal]
                || firstHoleNormal != minimumNormal
                || secondHoleNormal != maximumNormal)
                return SourceReject("profile-levels");

            var patch = sourceFaces[10].OuterVertices!.Select(Project).ToList();
            var patchAlong = Levels(patch.Select(value => value.Along));
            var patchNormal = Levels(patch.Select(value => value.Normal));
            var patchZ = Levels(patch.Select(value => value.Z));
            var expectedPatch = new List<(long Along, long Normal, long Z)>
            {
                (grossAlong[0], minimumNormal, grossZ[0]),
                (grossAlong[1], minimumNormal, grossZ[0]),
                (grossAlong[1], minimumNormal, patchZ.Count == 2
                    ? patchZ[1] : grossZ[0]),
                (grossAlong[0], minimumNormal, patchZ.Count == 2
                    ? patchZ[1] : grossZ[0]),
            };
            if (patchAlong.Count != 2
                || !patchAlong.SequenceEqual(grossAlong)
                || patchNormal is not [{ } patchNormalLevel]
                || patchNormalLevel != minimumNormal
                || patchZ.Count != 2 || patchZ[0] != grossZ[0]
                || patchZ[1] - patchZ[0] != IfcPrecisionBinMetres(0.1)
                || patchZ[1] >= holeZ[0]
                || !ProjectedCycleMatches(
                    sourceFaces[10].OuterVertices!, expectedPatch))
                return SourceReject("detached-patch");

            var alternativeSide = sourceFaces[6].AlternativeOuterVertices!;
            var sideProjected = alternativeSide.Select(Project).ToList();
            var sideAlong = Levels(sideProjected.Select(value => value.Along));
            var sideNormal = Levels(sideProjected.Select(value => value.Normal));
            var sideZ = Levels(sideProjected.Select(value => value.Z));
            var expectedSide = sideNormal.Count == 2
                ? new List<(long Along, long Normal, long Z)>
                {
                    (holeAlong[1], sideNormal[0], holeZ[0]),
                    (holeAlong[1], sideNormal[1], holeZ[0]),
                    (holeAlong[1], sideNormal[1], holeZ[1]),
                    (holeAlong[1], sideNormal[0], holeZ[1]),
                }
                : [];
            if (sideAlong is not [{ } sideAlongLevel]
                || sideAlongLevel != holeAlong[1]
                || sideNormal.Count != 2
                || sideNormal[0] >= minimumNormal - 2
                || sideNormal[1] <= maximumNormal + 2
                || !sideZ.SequenceEqual(holeZ)
                || !ProjectedCycleMatches(alternativeSide, expectedSide))
                return SourceReject("alternative-side");

            var alternativeBottom = sourceFaces[7]
                .AlternativeOuterVertices!;
            var alternativeBottomKeys = alternativeBottom.Select(Project).ToList();
            var redundantKey = (
                Along: holeAlong[1], Normal: minimumNormal, Z: holeZ[0]);
            if (alternativeBottomKeys.Count(key => key == redundantKey) != 1
                || alternativeBottomKeys.Where(key => key != redundantKey)
                    .Distinct().Count() != 8)
                return SourceReject("alternative-bottom");

            double NormalFeet(double[] point) =>
                point[0] * normalX + point[1] * normalY;
            var sideNormalFeet = alternativeSide
                .GroupBy(point => IfcPrecisionBinMetres(
                    NormalFeet(point) * FeetToMetres))
                .OrderBy(group => group.Key)
                .Select(group => group.Average(NormalFeet)).ToList();
            if (sideNormalFeet.Count != 2
                || !(sideNormalFeet[1] > sideNormalFeet[0]))
                return SourceReject("alternative-normal");
            double centreAlong = exactHole.CentreXFt * axisX
                + exactHole.CentreYFt * axisY;
            double centreNormal = (sideNormalFeet[0] + sideNormalFeet[1]) / 2;
            outerPrimitive = new HostedOpeningGeometry(
                centreAlong * axisX + centreNormal * normalX,
                centreAlong * axisY + centreNormal * normalY,
                axisX, axisY, exactHole.WidthFt,
                sideNormalFeet[1] - sideNormalFeet[0],
                exactHole.BaseZFt, exactHole.HeightFt, ExactDepth: true);
            grossBoundary = candidateGross;
            hole = exactHole;
            return true;
        }

        if (hostedElement.CategoryId != -2000014
            || hostedElement.BoundingBox is not { Length: 6 } hostedBounds
            || hostedBounds.Any(value => !double.IsFinite(value))
            || hostedElement.HostId is not > 0
            || hostedElement.SerializedHostId != hostedElement.HostId
            || !Empty(hostedElement.ExtraHostIds)
            || !Empty(hostedElement.ExplicitHostIds)
            || hostedElement.SuperInstanceId is > 0
            || candidateHostWalls.Count != 7
            || candidateHostWalls.Select(wall => wall.Id).Distinct().Count()
                != candidateHostWalls.Count
            || candidateHostWalls.Any(wall => wall.CategoryId != -2000011
                || wall.BoundingBox is not { Length: 6 } wallBounds
                || wallBounds.Any(value => !double.IsFinite(value))
                || !HostedElementCanCutHost(hostedBounds, wall)))
            return Reject("instance-host-set");

        var familyTypeParameters = hostedElement.Parameters
            .Where(parameter => parameter.Definition?.Name == "ELEM_TYPE_PARAM")
            .ToList();
        if (familyTypeParameters is not
            [{ Id: -1002050, StorageType: StorageType.ElementId,
                Value: int familyTypeId }]
            || familyTypeId <= 0
            || familyTypeId == hostedElement.Id)
            return Reject("family-type-parameter");
        if (hostedElement.Transform is not
            {
                SymbolId: > 0,
                Origin.Length: >= 3,
                BasisX.Length: >= 3,
                BasisY.Length: >= 3,
                BasisZ.Length: >= 3,
            } transform
            || transform.Origin.Concat(transform.BasisX)
                .Concat(transform.BasisY).Concat(transform.BasisZ)
                .Any(value => !double.IsFinite(value))
            || hostedElement.Geometry?.ExactMappedInstances
                is not [{ } mappedInstance]
            || mappedInstance.SymbolId != transform.SymbolId
            || mappedInstance.Transform.Length < 12
            || mappedInstance.Transform.Any(value => !double.IsFinite(value))
            || !elementsById.TryGetValue(
                mappedInstance.SymbolId, out var mappedSymbol)
            || familyTypeId <= 0 || familyTypeId == mappedSymbol.Id
            || !elementsById.TryGetValue(familyTypeId, out var familyType)
            || mappedSymbol.FamilyCutGeometry != null
            || mappedSymbol.FamilyCutClosurePlaneOrigin != null
            || mappedSymbol.FamilyCutClosurePlaneNormal != null
            || mappedSymbol.FamilyCutLoops is { Count: > 0 }
            || familyType.FamilyCutGeometry != null
            || familyType.FamilyCutClosurePlaneOrigin != null
            || familyType.FamilyCutClosurePlaneNormal != null
            || familyType.FamilyCutLoops is { Count: > 0 }
            || LinkedFamilyType(hostedElement, elementsById)?.Id
                != mappedSymbol.Id
            || LinkedFamilyCutTypes(hostedElement, elementsById).Count != 0
            || TryBuildSerializedHostedOpeningGeometry(
                hostedElement, mappedSymbol, out _))
            return Reject("mapped-family-contract");

        var sourceMatches = new List<(
            Element Wall, GeometryData Gross,
            RectangularWallThroughOpening Hole,
            HostedOpeningGeometry Primitive)>();
        foreach (Element wall in candidateHostWalls)
            if (TryGetExactSource(wall, out var gross, out var hole,
                    out var primitive))
                sourceMatches.Add((wall, gross, hole, primitive));
        if (sourceMatches.Count != 1)
            return Reject($"source-count-{sourceMatches.Count}");
        var source = sourceMatches[0];

        int primaryHostId = hostedElement.SerializedHostId.Value;
        var primaryHosts = candidateHostWalls
            .Where(wall => wall.Id == primaryHostId).ToList();
        if (primaryHosts.Count != 1 || source.Wall.Id == primaryHostId
            || source.Wall.CuttingElementIds is not
                { Count: 4 } targetCutterIds
            || targetCutterIds.Distinct().Count() != 4
            || !targetCutterIds.Contains(hostedElement.Id))
            return Reject("source-cutter-set");

        var candidateHostIds = candidateHostWalls
            .Select(wall => wall.Id).ToHashSet();
        var cutters = new List<Element>(targetCutterIds.Count);
        foreach (int cutterId in targetCutterIds)
        {
            if (!elementsById.TryGetValue(cutterId, out var cutter)
                || cutter.BoundingBox is not { Length: 6 } cutterBounds
                || cutterBounds.Any(value => !double.IsFinite(value))
                || cutter.HostId is not > 0
                || cutter.SerializedHostId != cutter.HostId
                || !candidateHostIds.Contains(cutter.HostId.Value)
                || !Empty(cutter.ExtraHostIds)
                || !Empty(cutter.ExplicitHostIds)
                || cutter.SuperInstanceId is > 0
                || cutter.References == null
                || cutter.References.Count(id => id == cutter.HostId.Value) != 1
                || cutter.References.Count(candidateHostIds.Contains) != 1
                || !inverseHostedHostIds.TryGetValue(
                    cutterId, out var inverseIds)
                || inverseIds.Count != candidateHostWalls.Count
                || inverseIds.Distinct().Count()
                    != candidateHostWalls.Count
                || !inverseIds.ToHashSet().SetEquals(candidateHostIds)
                || candidateHostWalls.Any(host =>
                    host.References?.Count(id => id == cutterId) != 1
                    || SerializedHostCuttingElementIds(host)
                        .Count(id => id == cutterId) != 1
                    || !HostedElementCanCutHost(cutterBounds, host)))
                return Reject($"cutter-graph-{cutterId}");
            cutters.Add(cutter);
        }
        if (cutters.Count(cutter => cutter.CategoryId == -2000014) != 1
            || cutters.Single(cutter => cutter.CategoryId == -2000014).Id
                != hostedElement.Id
            || cutters.Count(cutter => cutter.CategoryId == -2000023) != 3
            || cutters.Any(cutter => cutter.CategoryId
                is not (-2000014 or -2000023)))
            return Reject("cutter-role-set");

        if (!TryBuildExactQuarteredAdditionalDepthRevealOpening(
                hostedElement, primaryHosts[0], candidateHostWalls,
                source.Primitive, out var candidateOpening,
                requireCalculatedInsertionAgreement: false,
                allowExactSerializedPrimaryHostCuttingReference: true)
            || !candidateOpening.IsExactParameterizedReveal
            || !candidateOpening.ExactDepth
            || candidateOpening.IsFamilyCutLoop
            || candidateOpening.SteppedProfile is not { } steppedProfile
            || steppedProfile.InnerAtMinimum
            || candidateOpening.Boundary is not
                { Faces: { Count: 10 } openingFaces } openingBoundary
            || openingBoundary.BrepSolids is not
                [{ IsClosed: true } openingSolid]
            || !openingSolid.FaceIndices.SequenceEqual(
                Enumerable.Range(0, 10))
            || openingFaces.Count(face => face.OuterVertices?.Count == 4) != 8
            || openingFaces.Count(face => face.OuterVertices?.Count == 8) != 2
            || openingFaces.Any(face => face.InnerVertices is { Count: > 0 }
                || face.AlternativeOuterVertices is { Count: > 0 })
            || openingFaces.SelectMany(face => face.OuterVertices!)
                .Select(IfcPrecisionKeyFeet).Distinct().Count() != 16
            || !ExactSteppedOpeningBoundaryMatchesDefinition(candidateOpening)
            || !ExactSteppedOpeningBoundaryMatchesWallHole(
                openingBoundary, source.Hole)
            || !ExactParameterizedRevealOpeningProfileMatchesWallSide(
                candidateOpening, source.Hole))
            return Reject("parameterized-opening");

        var sourceFaces = source.Wall.Geometry!.Faces;
        var alternativeSide = sourceFaces[6].AlternativeOuterVertices!;
        int sideMatches = openingFaces.Count(face =>
            WorldRingMatches(alternativeSide, face.OuterVertices));
        double sourceAxisX = source.Wall.Location!.EndPoint[0]
            - source.Wall.Location.StartPoint[0];
        double sourceAxisY = source.Wall.Location.EndPoint[1]
            - source.Wall.Location.StartPoint[1];
        double sourceAxisLength = Math.Sqrt(
            sourceAxisX * sourceAxisX + sourceAxisY * sourceAxisY);
        sourceAxisX /= sourceAxisLength;
        sourceAxisY /= sourceAxisLength;
        double sourceNormalX = -sourceAxisY, sourceNormalY = sourceAxisX;
        (long Along, long Normal, long Z) ProjectSource(
            IReadOnlyList<double> point) =>
        (
            IfcPrecisionBinMetres(
                (point[0] * sourceAxisX + point[1] * sourceAxisY)
                * FeetToMetres),
            IfcPrecisionBinMetres(
                (point[0] * sourceNormalX + point[1] * sourceNormalY)
                * FeetToMetres),
            IfcPrecisionBinMetres(point[2] * FeetToMetres)
        );
        long sourceMinimumNormal = sourceFaces[0].OuterVertices!
            .Select(ProjectSource).Select(key => key.Normal)
            .Distinct().Single();
        if (sourceFaces[0].InnerVertices is not [var sourceHole, ..])
            return Reject("source-contract");
        long sourceHoleMaximumAlong = sourceHole
            .Select(ProjectSource).Max(key => key.Along);
        long sourceHoleBaseZ = sourceHole
            .Select(ProjectSource).Min(key => key.Z);
        var redundantKey = (Along: sourceHoleMaximumAlong,
            Normal: sourceMinimumNormal, Z: sourceHoleBaseZ);
        var bottomWithoutRedundant = sourceFaces[7]
            .AlternativeOuterVertices!
            .Where(point => ProjectSource(point) != redundantKey).ToList();
        int bottomMatches = openingFaces.Count(face =>
            face.OuterVertices?.Count == 8
            && WorldRingMatches(bottomWithoutRedundant, face.OuterVertices));
        if (sideMatches != 1 || bottomWithoutRedundant.Count != 8
            || bottomMatches != 1)
            return Reject("alternative-cycle-bijection");

        opening = candidateOpening;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCQUARTEREDSOURCEGATE cutter={hostedElement.Id} "
                + $"wall={source.Wall.Id} "
                + $"hosts={string.Join(',', candidateHostIds.Order())} "
                + "result=accept stage=exact-open-ten-face-quarter-reveal");
        return true;
    }

    /// <summary>
    /// Resolves the unique serialized primary host before applying the exact quartered-reveal
    /// contract to a primitive that was already reconstructed by the normal hosted-opening path.
    /// </summary>
    internal static bool
        TryBuildExactQuarteredAdditionalDepthRevealOpeningFromPrimitive(
            Element hostedElement, IReadOnlyList<Element> candidateHostWalls,
            HostedOpeningGeometry primitiveOpening,
            out HostedOpeningGeometry opening,
            IReadOnlyDictionary<int, Element>? elementsById = null,
            IReadOnlyDictionary<int, List<int>>?
                inverseHostedHostIds = null)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);
        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        var primaryHosts = candidateHostWalls
            .Where(host => host.Id == primaryHostId).ToList();
        if (primaryHosts.Count != 1)
            return false;
        bool hasCalculatedInsertionAgreement =
            TryBuildExactQuarteredAdditionalDepthRevealOpening(
                hostedElement, primaryHosts[0], candidateHostWalls,
                primitiveOpening, out opening);
        if (!hasCalculatedInsertionAgreement
            && !TryBuildExactQuarteredAdditionalDepthRevealOpening(
                hostedElement, primaryHosts[0], candidateHostWalls,
                primitiveOpening, out opening,
                requireCalculatedInsertionAgreement: false))
            return false;

        HostedOpeningGeometry reconstructedOpening = opening;
        double openingAxisLength = Math.Sqrt(
            reconstructedOpening.AxisX * reconstructedOpening.AxisX
            + reconstructedOpening.AxisY * reconstructedOpening.AxisY);
        if (!(openingAxisLength > 0)
            || !double.IsFinite(openingAxisLength)
            || !(reconstructedOpening.DepthFt > 0)
            || !double.IsFinite(reconstructedOpening.DepthFt))
        {
            opening = default;
            return false;
        }
        double openingAxisX =
            reconstructedOpening.AxisX / openingAxisLength;
        double openingAxisY =
            reconstructedOpening.AxisY / openingAxisLength;
        double openingNormalX = -openingAxisY;
        double openingNormalY = openingAxisX;
        double openingCentreNormal =
            reconstructedOpening.CentreXFt * openingNormalX
            + reconstructedOpening.CentreYFt * openingNormalY;
        double openingMinimumNormal =
            openingCentreNormal - reconstructedOpening.DepthFt / 2;
        double openingMaximumNormal =
            openingCentreNormal + reconstructedOpening.DepthFt / 2;

        bool ExactHolePositivelyIntersectsOpening(
            RectangularWallThroughOpening hole)
        {
            if (!ExactParameterizedRevealOpeningProfileMatchesWallHole(
                    reconstructedOpening, hole))
                return false;
            double holeAxisLength = Math.Sqrt(
                hole.AxisX * hole.AxisX + hole.AxisY * hole.AxisY);
            if (!(holeAxisLength > 0)
                || !double.IsFinite(holeAxisLength)
                || !double.IsFinite(hole.NormalMinimumFt)
                || !double.IsFinite(hole.NormalMaximumFt))
                return false;
            double holeAxisX = hole.AxisX / holeAxisLength;
            double holeAxisY = hole.AxisY / holeAxisLength;
            double holeNormalX = -holeAxisY;
            double holeNormalY = holeAxisX;
            double directionDot =
                holeAxisX * openingAxisX + holeAxisY * openingAxisY;
            double scale = Math.Max(1.0, new[]
            {
                reconstructedOpening.CentreXFt,
                reconstructedOpening.CentreYFt,
                reconstructedOpening.DepthFt,
                openingMinimumNormal,
                openingMaximumNormal,
                hole.CentreXFt, hole.CentreYFt,
                hole.NormalMinimumFt, hole.NormalMaximumFt,
            }.Select(Math.Abs).Max());
            const double MachineEpsilon = 2.2204460492503131e-16;
            double roundoff = 16384 * MachineEpsilon * scale;
            if (Math.Abs(Math.Abs(directionDot) - 1) > roundoff)
                return false;
            double holeCentreAlong =
                hole.CentreXFt * holeAxisX + hole.CentreYFt * holeAxisY;
            double ProjectNormal(double holeNormal)
            {
                double x = holeCentreAlong * holeAxisX
                    + holeNormal * holeNormalX;
                double y = holeCentreAlong * holeAxisY
                    + holeNormal * holeNormalY;
                return x * openingNormalX + y * openingNormalY;
            }
            double firstNormal = ProjectNormal(hole.NormalMinimumFt);
            double secondNormal = ProjectNormal(hole.NormalMaximumFt);
            double holeMinimumNormal = Math.Min(firstNormal, secondNormal);
            double holeMaximumNormal = Math.Max(firstNormal, secondNormal);
            return Math.Min(openingMaximumNormal, holeMaximumNormal)
                > Math.Max(openingMinimumNormal, holeMinimumNormal)
                    + roundoff;
        }

        bool TryAlignMismatchedCalculationToUniquePhysicalWall(
            out HostedOpeningGeometry alignedOpening)
        {
            alignedOpening = default;
            if (hasCalculatedInsertionAgreement
                || reconstructedOpening.SteppedProfile is not { } stepped
                || !TryGetSerializedWallWidthFeet(
                    primaryHosts[0], out double sourceWallWidthFt)
                || !TryGetAuthoredStraightWallPlan(
                    primaryHosts[0], sourceWallWidthFt,
                    out var sourceWallPlan))
                return false;

            double sourceMinimumNormal = sourceWallPlan.Min(point =>
                point[0] * openingNormalX + point[1] * openingNormalY);
            double sourceMaximumNormal = sourceWallPlan.Max(point =>
                point[0] * openingNormalX + point[1] * openingNormalY);
            var alignmentCandidates = new List<double>();
            foreach (Element host in candidateHostWalls)
            {
                if (host.Id == primaryHosts[0].Id
                    || host.BoundingBox is not { Length: 6 } hostBounds
                    || hostBounds.Any(value => !double.IsFinite(value))
                    || host.Location is not
                        { CurveType: "Line", ArcRadius: null } hostLocation
                    || !TryGetSerializedWallWidthFeet(
                        host, out double validationWallWidthFt)
                    || !TryBuildStraightWallBoundary(
                        host, out var hostBoundary)
                    || !TryGetExactStraightWallGrossBoundaryAndOpenings(
                        hostBoundary, hostLocation, validationWallWidthFt,
                        hostBounds, out _, out var holes, out _)
                    || holes.Count(ExactHolePositivelyIntersectsOpening) != 1)
                    continue;

                var values = new[]
                {
                    sourceMinimumNormal, sourceMaximumNormal,
                    sourceWallWidthFt, validationWallWidthFt,
                    openingMinimumNormal, openingMaximumNormal,
                    stepped.BreakpointNormalFt,
                };
                if (values.Any(value => !double.IsFinite(value)))
                    continue;
                const double MachineEpsilon = 2.2204460492503131e-16;
                double scale = Math.Max(
                    1.0, values.Select(Math.Abs).Max());
                double roundoff = 16384 * MachineEpsilon * scale;
                bool Same(double first, double second) =>
                    Math.Abs(first - second) <= roundoff;
                if (!Same(sourceMaximumNormal - sourceMinimumNormal,
                        sourceWallWidthFt))
                    continue;

                if (Same(openingMaximumNormal, sourceMaximumNormal)
                    && Same(sourceMinimumNormal
                            - stepped.BreakpointNormalFt,
                        validationWallWidthFt)
                    && Same(openingMaximumNormal
                            - stepped.BreakpointNormalFt,
                        sourceWallWidthFt + validationWallWidthFt))
                    alignmentCandidates.Add(validationWallWidthFt);
                if (Same(openingMinimumNormal, sourceMinimumNormal)
                    && Same(stepped.BreakpointNormalFt
                            - sourceMaximumNormal,
                        validationWallWidthFt)
                    && Same(stepped.BreakpointNormalFt
                            - openingMinimumNormal,
                        sourceWallWidthFt + validationWallWidthFt))
                    alignmentCandidates.Add(-validationWallWidthFt);
            }
            if (alignmentCandidates.Count != 1)
                return false;

            double translationNormalFt = alignmentCandidates[0];
            var translatedOuter = reconstructedOpening with
            {
                CentreXFt = reconstructedOpening.CentreXFt
                    + translationNormalFt * openingNormalX,
                CentreYFt = reconstructedOpening.CentreYFt
                    + translationNormalFt * openingNormalY,
                Boundary = null,
            };
            double translatedBreakpoint =
                stepped.BreakpointNormalFt + translationNormalFt;
            if (!TryBuildExactSteppedOpeningBoundary(
                    translatedOuter, stepped.InnerWidthFt,
                    stepped.InnerHeightFt, translatedBreakpoint,
                    stepped.InnerAtMinimum, out var translatedBoundary))
                return false;
            alignedOpening = translatedOuter with
            {
                Boundary = translatedBoundary,
                SteppedProfile = stepped with
                {
                    BreakpointNormalFt = translatedBreakpoint,
                },
            };
            return true;
        }

        bool hasMismatchedCalculationPhysicalAlignment =
            TryAlignMismatchedCalculationToUniquePhysicalWall(
                out var physicallyAlignedOpening);
        if (!hasCalculatedInsertionAgreement
            && !hasMismatchedCalculationPhysicalAlignment)
        {
            opening = default;
            return false;
        }
        if (hasMismatchedCalculationPhysicalAlignment)
        {
            reconstructedOpening = physicallyAlignedOpening;
            opening = physicallyAlignedOpening;
            openingCentreNormal =
                reconstructedOpening.CentreXFt * openingNormalX
                + reconstructedOpening.CentreYFt * openingNormalY;
            openingMinimumNormal = openingCentreNormal
                - reconstructedOpening.DepthFt / 2;
            openingMaximumNormal = openingCentreNormal
                + reconstructedOpening.DepthFt / 2;
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCQUARTEREDPRIMITIVEGATE "
                    + $"cutter={hostedElement.Id} "
                    + "calculatedMismatchPhysicalAlignment=True");
        }

        bool ExactSteppedOpeningPositivelyIntersectsExactWall(
            HostedOpeningGeometry candidate, Element host,
            IReadOnlyList<double> bounds,
            LocationCurve location, double wallWidthFt,
            GeometryData straightBoundary)
        {
            if (candidate.SteppedProfile is not { } stepped
                || !TryGetExactVerticalRectangularWallPlan(
                    straightBoundary, location, wallWidthFt, bounds,
                    out _))
                return false;

            double candidateAxisLength = Math.Sqrt(
                candidate.AxisX * candidate.AxisX
                + candidate.AxisY * candidate.AxisY);
            if (!(candidateAxisLength > 0)
                || !double.IsFinite(candidateAxisLength)
                || !(candidate.DepthFt > 0)
                || !double.IsFinite(candidate.DepthFt))
                return false;
            double candidateAxisX = candidate.AxisX / candidateAxisLength;
            double candidateAxisY = candidate.AxisY / candidateAxisLength;
            double candidateNormalX = -candidateAxisY;
            double candidateNormalY = candidateAxisX;
            double candidateCentreNormal =
                candidate.CentreXFt * candidateNormalX
                + candidate.CentreYFt * candidateNormalY;
            double candidateMinimumNormal =
                candidateCentreNormal - candidate.DepthFt / 2;
            double candidateMaximumNormal =
                candidateCentreNormal + candidate.DepthFt / 2;
            HostedOpeningGeometry Segment(bool inner)
            {
                double minimumNormal;
                double maximumNormal;
                if (inner == stepped.InnerAtMinimum)
                {
                    minimumNormal = candidateMinimumNormal;
                    maximumNormal = stepped.BreakpointNormalFt;
                }
                else
                {
                    minimumNormal = stepped.BreakpointNormalFt;
                    maximumNormal = candidateMaximumNormal;
                }
                double centreNormal =
                    (minimumNormal + maximumNormal) / 2;
                double centreAlong =
                    candidate.CentreXFt * candidateAxisX
                    + candidate.CentreYFt * candidateAxisY;
                return new HostedOpeningGeometry(
                    centreAlong * candidateAxisX
                        + centreNormal * candidateNormalX,
                    centreAlong * candidateAxisY
                        + centreNormal * candidateNormalY,
                    candidateAxisX, candidateAxisY,
                    inner ? stepped.InnerWidthFt
                        : candidate.WidthFt,
                    maximumNormal - minimumNormal,
                    candidate.BaseZFt,
                    inner ? stepped.InnerHeightFt
                        : candidate.HeightFt,
                    ExactDepth: true);
            }

            return ExactDirectedOpeningHasPositiveAuthoredHostIntersection(
                    Segment(inner: true), host)
                || ExactDirectedOpeningHasPositiveAuthoredHostIntersection(
                    Segment(inner: false), host);
        }

        int exactIntersectionMatches = 0;
        foreach (Element host in candidateHostWalls)
        {
            if (host.CuttingElementIds?.Count(
                    id => id == hostedElement.Id) != 1
                || host.BoundingBox is not { Length: 6 } bounds
                || bounds.Any(value => !double.IsFinite(value))
                || host.Location is not
                    { CurveType: "Line", ArcRadius: null } location
                || !TryGetSerializedWallWidthFeet(
                    host, out double wallWidthFt)
                || !TryBuildStraightWallBoundary(
                    host, out var straightBoundary))
                continue;
            int hostMatches = 0;
            if (TryGetExactStraightWallGrossBoundaryAndOpenings(
                    straightBoundary, location, wallWidthFt, bounds,
                    out _, out var holes, out _))
                hostMatches = holes.Count(hole =>
                    ExactHolePositivelyIntersectsOpening(hole));
            if (hostMatches > 1)
            {
                opening = default;
                return false;
            }
            bool exactSegmentIntersection =
                ExactSteppedOpeningPositivelyIntersectsExactWall(
                    reconstructedOpening, host, bounds, location,
                    wallWidthFt, straightBoundary);
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCQUARTEREDPRIMITIVEGATE cutter={hostedElement.Id} "
                    + $"host={host.Id} holes={hostMatches} "
                    + $"segmentIntersection={exactSegmentIntersection}");
            if (hostMatches == 1 || exactSegmentIntersection)
                exactIntersectionMatches++;
        }
        if (exactIntersectionMatches == 0
            && elementsById != null
            && inverseHostedHostIds != null
            && inverseHostedHostIds.TryGetValue(
                hostedElement.Id, out var currentInverseHostIds))
        {
            bool SameNormalContract(
                HostedOpeningGeometry first,
                HostedOpeningGeometry second)
            {
                if (!first.IsExactParameterizedReveal
                    || !second.IsExactParameterizedReveal
                    || first.SteppedProfile is not { } firstStep
                    || second.SteppedProfile is not { } secondStep)
                    return false;
                double firstAxisLength = Math.Sqrt(
                    first.AxisX * first.AxisX
                    + first.AxisY * first.AxisY);
                double secondAxisLength = Math.Sqrt(
                    second.AxisX * second.AxisX
                    + second.AxisY * second.AxisY);
                if (!(firstAxisLength > 0)
                    || !(secondAxisLength > 0)
                    || !double.IsFinite(firstAxisLength)
                    || !double.IsFinite(secondAxisLength))
                    return false;
                double firstAxisX = first.AxisX / firstAxisLength;
                double firstAxisY = first.AxisY / firstAxisLength;
                double secondAxisX = second.AxisX / secondAxisLength;
                double secondAxisY = second.AxisY / secondAxisLength;
                double directionDot =
                    firstAxisX * secondAxisX
                    + firstAxisY * secondAxisY;
                double firstNormalX = -firstAxisY;
                double firstNormalY = firstAxisX;
                double secondNormalX = -secondAxisY;
                double secondNormalY = secondAxisX;
                double firstCentreNormal =
                    first.CentreXFt * firstNormalX
                    + first.CentreYFt * firstNormalY;
                double secondCentreNormal =
                    second.CentreXFt * secondNormalX
                    + second.CentreYFt * secondNormalY;
                var values = new[]
                {
                    first.WidthFt, first.DepthFt,
                    first.BaseZFt, first.HeightFt,
                    second.WidthFt, second.DepthFt,
                    second.BaseZFt, second.HeightFt,
                    firstCentreNormal, secondCentreNormal,
                    firstStep.InnerWidthFt, firstStep.InnerHeightFt,
                    firstStep.BreakpointNormalFt,
                    secondStep.InnerWidthFt, secondStep.InnerHeightFt,
                    secondStep.BreakpointNormalFt,
                };
                if (values.Any(value => !double.IsFinite(value)))
                    return false;
                const double MachineEpsilon =
                    2.2204460492503131e-16;
                double scale = Math.Max(
                    1.0, values.Select(Math.Abs).Max());
                double roundoff =
                    16384 * MachineEpsilon * scale;
                bool Same(double left, double right) =>
                    Math.Abs(left - right) <= roundoff;
                return Math.Abs(directionDot - 1) <= roundoff
                    && Same(first.WidthFt, second.WidthFt)
                    && Same(first.DepthFt, second.DepthFt)
                    && Same(first.BaseZFt, second.BaseZFt)
                    && Same(first.HeightFt, second.HeightFt)
                    && Same(firstCentreNormal, secondCentreNormal)
                    && Same(firstStep.InnerWidthFt,
                        secondStep.InnerWidthFt)
                    && Same(firstStep.InnerHeightFt,
                        secondStep.InnerHeightFt)
                    && Same(firstStep.BreakpointNormalFt,
                        secondStep.BreakpointNormalFt)
                    && firstStep.InnerAtMinimum
                        == secondStep.InnerAtMinimum;
            }

            var currentInverseSet = currentInverseHostIds
                .Distinct().Order().ToList();
            var commonPeerIds = candidateHostWalls
                .Select(host => (host.CuttingElementIds ?? [])
                    .Where(id => id != hostedElement.Id)
                    .ToHashSet())
                .Aggregate(
                    (IEnumerable<int>?)null,
                    (common, ids) => common == null
                        ? ids
                        : common.Intersect(ids))
                ?.Distinct().ToList() ?? [];
            var peerValidationIds = new List<int>();
            foreach (int peerId in commonPeerIds)
            {
                if (!elementsById.TryGetValue(peerId, out var peer)
                    || peer.CategoryId is not (-2000023 or -2000014)
                    || !inverseHostedHostIds.TryGetValue(
                        peerId, out var peerInverseHostIds)
                    || !currentInverseSet.SequenceEqual(
                        peerInverseHostIds.Distinct().Order())
                    || candidateHostWalls.Any(host =>
                        host.CuttingElementIds?.Count(
                            id => id == hostedElement.Id) != 1
                        || host.CuttingElementIds?.Count(
                            id => id == peerId) != 1))
                    continue;
                int peerPrimaryHostId =
                    peer.SerializedHostId is > 0
                        ? peer.SerializedHostId.Value
                        : peer.HostId is > 0
                            ? peer.HostId.Value : -1;
                var peerPrimaryHosts = candidateHostWalls
                    .Where(host => host.Id == peerPrimaryHostId)
                    .ToList();
                if (peerPrimaryHosts.Count != 1)
                    continue;
                Element? peerType = LinkedFamilyType(
                    peer, elementsById);
                HostedOpeningGeometry peerPrimitive = default;
                bool builtPeerPrimitive =
                    TryBuildSerializedHostedOpeningGeometry(
                        peer, peerType, out peerPrimitive)
                    || peer.BoundingBox is { Length: 6 } peerBounds
                    && TryBuildCommonHostedOpeningGeometry(
                        peer, peerBounds, candidateHostWalls,
                        out peerPrimitive);
                if (!builtPeerPrimitive
                    || !TryBuildExactQuarteredAdditionalDepthRevealOpening(
                        peer, peerPrimaryHosts[0],
                        candidateHostWalls, peerPrimitive,
                        out var peerOpening,
                        requireCalculatedInsertionAgreement: false)
                    || !SameNormalContract(
                        reconstructedOpening, peerOpening))
                    continue;
                bool peerHasPhysicalValidation =
                    candidateHostWalls.Any(host =>
                        host.BoundingBox is { Length: 6 } hostBounds
                        && hostBounds.All(double.IsFinite)
                        && host.Location is
                            { CurveType: "Line", ArcRadius: null }
                                hostLocation
                        && TryGetSerializedWallWidthFeet(
                            host, out double hostWidthFt)
                        && TryBuildStraightWallBoundary(
                            host, out var hostBoundary)
                        && ExactSteppedOpeningPositivelyIntersectsExactWall(
                            peerOpening, host, hostBounds,
                            hostLocation, hostWidthFt, hostBoundary));
                if (peerHasPhysicalValidation)
                    peerValidationIds.Add(peerId);
            }
            if (peerValidationIds.Count == 1)
            {
                exactIntersectionMatches = 1;
                if (diagnostics)
                    DiagnosticSink.WriteLine(
                        $"IFCQUARTEREDPRIMITIVEGATE "
                        + $"cutter={hostedElement.Id} "
                        + $"peerValidation={peerValidationIds[0]}");
            }
        }
        if (exactIntersectionMatches == 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCQUARTEREDPRIMITIVEGATE cutter={hostedElement.Id} "
                    + "result=reject stage=no-physical-validation");
            opening = default;
            return false;
        }
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCQUARTEREDPRIMITIVEGATE cutter={hostedElement.Id} "
                + $"result=accept validations={exactIntersectionMatches}");
        return true;
    }

    /// <summary>
    /// Reconstructs an exact two-profile family reveal whose calculated parameters directly store
    /// the inner opening, the outer sill opening, the upper quarter, the two directed additional
    /// depths and two concordant insertion depths.
    /// </summary>
    internal static bool TryBuildExactQuarteredAdditionalDepthRevealOpening(
        Element hostedElement, Element sourceHost,
        IReadOnlyList<Element> candidateHostWalls,
        HostedOpeningGeometry primitiveOpening,
        out HostedOpeningGeometry opening,
        bool requireCalculatedInsertionAgreement = true,
        bool allowExactSerializedPrimaryHostCuttingReference = false)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);
        void Diagnose(string stage) => DiagnosticSink.WriteLine(
            $"IFCQUARTEREDREVEALGATE cutter={hostedElement.Id} stage={stage}");
        if (!primitiveOpening.ExactDepth
            || primitiveOpening.Boundary != null
            || primitiveOpening.IsFamilyCutLoop
            || primitiveOpening.SteppedProfile != null
            || !(primitiveOpening.WidthFt > 0.03)
            || !(primitiveOpening.DepthFt > 0)
            || !(primitiveOpening.HeightFt > 0.03)
            || !TryGetSerializedInstanceTransform(
                hostedElement, out var transform))
            return false;
        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        var primaryHosts = candidateHostWalls
            .Where(host => host.Id == primaryHostId).ToList();
        bool hasExactPrimaryHostCuttingReference =
            sourceHost.CuttingElementIds?.Count(
                id => id == hostedElement.Id) == 1
            || allowExactSerializedPrimaryHostCuttingReference
                && sourceHost.CuttingElementIds == null
                && SerializedHostCuttingElementIds(sourceHost).Count(
                    id => id == hostedElement.Id) == 1;
        if (primaryHosts.Count != 1
            || sourceHost.Id != primaryHostId
            || !hasExactPrimaryHostCuttingReference
            || !TryGetSerializedWallWidthFeet(
                primaryHosts[0], out double serializedWallWidthFt))
        {
            if (diagnostics)
                Diagnose($"primary-host id={primaryHostId} "
                    + $"count={primaryHosts.Count} source={sourceHost.Id}");
            return false;
        }

        bool TryGetExactInstanceFamilyLength(
            string name, out double value)
        {
            var parameters = hostedElement.Parameters
                .Where(parameter => parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .ToList();
            value = parameters.Count == 1
                ? (double)parameters[0].Value! : double.NaN;
            return parameters.Count == 1;
        }

        if (!TryGetExactInstanceFamilyLength(
                "Доп Глубина Внутренняя", out double innerDepthFt)
            || !TryGetExactInstanceFamilyLength(
                "Доп Глубина Наружная", out double outerDepthFt)
            || !TryGetExactInstanceFamilyLength(
                "Проем_Наружный_Ширина", out double innerWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "Проем_Наружный_Высота", out double innerHeightFt)
            || !TryGetExactInstanceFamilyLength(
                "Подоконник_Проем_Ширина", out double outerWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "Четверть Сверху", out double upperQuarterFt)
            || !TryGetExactInstanceFamilyLength(
                "Вставка окна", out double insertionDepthFt)
            || !TryGetExactInstanceFamilyLength(
                "Вставка_Расчет", out double calculatedInsertionDepthFt))
        {
            if (diagnostics) Diagnose("parameters");
            return false;
        }
        double outerHeightFt = innerHeightFt + upperQuarterFt;
        var values = new[]
        {
            primitiveOpening.CentreXFt, primitiveOpening.CentreYFt,
            primitiveOpening.WidthFt, primitiveOpening.DepthFt,
            primitiveOpening.BaseZFt, primitiveOpening.HeightFt,
            innerDepthFt, outerDepthFt,
            innerWidthFt, innerHeightFt,
            outerWidthFt, upperQuarterFt, outerHeightFt,
            serializedWallWidthFt, insertionDepthFt,
            calculatedInsertionDepthFt,
        };
        if (values.Concat(transform.Origin).Concat(transform.BasisX)
            .Concat(transform.BasisY)
            .Any(value => !double.IsFinite(value)))
            return false;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0,
            values.Concat(transform.Origin).Concat(transform.BasisX)
                .Concat(transform.BasisY)
                .Select(Math.Abs).Max());
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        if (!Same(insertionDepthFt, serializedWallWidthFt)
            || requireCalculatedInsertionAgreement
                && !Same(calculatedInsertionDepthFt,
                    insertionDepthFt
                    + (innerDepthFt + outerDepthFt) / 2)
            || !(outerWidthFt > innerWidthFt + roundoff)
            || !(outerHeightFt > innerHeightFt + roundoff))
        {
            if (diagnostics)
                Diagnose($"parameter-contract wall={serializedWallWidthFt:G17} "
                    + $"insertion={insertionDepthFt:G17} "
                    + $"calculated={calculatedInsertionDepthFt:G17} "
                    + $"expectedCalculated="
                    + $"{insertionDepthFt
                        + (innerDepthFt + outerDepthFt) / 2:G17}");
            return false;
        }
        bool primitiveIsOuter =
            Same(primitiveOpening.WidthFt, outerWidthFt)
            && Same(primitiveOpening.HeightFt, outerHeightFt);
        bool primitiveIsInner =
            Same(primitiveOpening.WidthFt, innerWidthFt)
            && Same(primitiveOpening.HeightFt, innerHeightFt);
        if (primitiveIsOuter == primitiveIsInner)
            return false;

        double axisLength = Math.Sqrt(
            primitiveOpening.AxisX * primitiveOpening.AxisX
            + primitiveOpening.AxisY * primitiveOpening.AxisY);
        double basisXLength = Math.Sqrt(
            transform.BasisX[0] * transform.BasisX[0]
            + transform.BasisX[1] * transform.BasisX[1]);
        double basisYLength = Math.Sqrt(
            transform.BasisY[0] * transform.BasisY[0]
            + transform.BasisY[1] * transform.BasisY[1]);
        if (!(axisLength > 0)
            || !(basisXLength > 0)
            || !(basisYLength > 0)
            || !double.IsFinite(axisLength)
            || !double.IsFinite(basisXLength)
            || !double.IsFinite(basisYLength))
            return false;
        double axisX = primitiveOpening.AxisX / axisLength;
        double axisY = primitiveOpening.AxisY / axisLength;
        double normalX = -axisY, normalY = axisX;
        double basisXx = transform.BasisX[0] / basisXLength;
        double basisXy = transform.BasisX[1] / basisXLength;
        double basisYx = transform.BasisY[0] / basisYLength;
        double basisYy = transform.BasisY[1] / basisYLength;
        double basisXDot = basisXx * axisX + basisXy * axisY;
        double basisYNormalDot =
            basisYx * normalX + basisYy * normalY;
        if (Math.Abs(Math.Abs(basisXDot) - 1) > roundoff
            || Math.Abs(Math.Abs(basisYNormalDot) - 1) > roundoff
            || Math.Abs(basisXx * basisYx + basisXy * basisYy)
                > roundoff
            || Math.Abs(transform.BasisX[2]) > roundoff
            || Math.Abs(transform.BasisY[2]) > roundoff)
            return false;

        bool innerAtMinimum = basisYNormalDot < 0;
        double primitiveCentreAlong =
            primitiveOpening.CentreXFt * axisX
            + primitiveOpening.CentreYFt * axisY;
        double transformCentreAlong =
            transform.Origin[0] * axisX + transform.Origin[1] * axisY;
        if (!Same(primitiveCentreAlong, transformCentreAlong))
            return false;
        double primitiveCentreNormal =
            primitiveOpening.CentreXFt * normalX
            + primitiveOpening.CentreYFt * normalY;
        double primitiveMinimumNormal =
            primitiveCentreNormal - primitiveOpening.DepthFt / 2;
        double primitiveMaximumNormal =
            primitiveCentreNormal + primitiveOpening.DepthFt / 2;
        // The family captions describe the building-side direction, not the nested profile that
        // occupies that side: the "outer" additional depth belongs to the smaller inner profile,
        // and the "inner" additional depth belongs to the larger outer profile.
        double innerProfileDepthFt = outerDepthFt;
        double outerProfileDepthFt = innerDepthFt;
        double breakpointNormal;
        double completeMinimumNormal;
        double completeMaximumNormal;
        if (primitiveIsInner)
        {
            if (innerAtMinimum)
            {
                completeMinimumNormal = primitiveMinimumNormal;
                breakpointNormal =
                    completeMinimumNormal + innerProfileDepthFt;
                completeMaximumNormal =
                    breakpointNormal + outerProfileDepthFt;
            }
            else
            {
                completeMaximumNormal = primitiveMaximumNormal;
                breakpointNormal =
                    completeMaximumNormal - innerProfileDepthFt;
                completeMinimumNormal =
                    breakpointNormal - outerProfileDepthFt;
            }
        }
        else if (innerAtMinimum)
        {
            completeMaximumNormal = primitiveMaximumNormal;
            breakpointNormal =
                completeMaximumNormal - outerProfileDepthFt;
            completeMinimumNormal =
                breakpointNormal - innerProfileDepthFt;
        }
        else
        {
            completeMinimumNormal = primitiveMinimumNormal;
            breakpointNormal =
                completeMinimumNormal + outerProfileDepthFt;
            completeMaximumNormal =
                breakpointNormal + innerProfileDepthFt;
        }
        double completeCentreNormal =
            (completeMinimumNormal + completeMaximumNormal) / 2;
        if (!(completeMaximumNormal
                > completeMinimumNormal + roundoff))
            return false;

        var outerOpening = primitiveOpening with
        {
            CentreXFt = primitiveCentreAlong * axisX
                + completeCentreNormal * normalX,
            CentreYFt = primitiveCentreAlong * axisY
                + completeCentreNormal * normalY,
            AxisX = axisX,
            AxisY = axisY,
            WidthFt = outerWidthFt,
            DepthFt = completeMaximumNormal - completeMinimumNormal,
            HeightFt = outerHeightFt,
        };
        if (!TryBuildExactSteppedOpeningBoundary(
                outerOpening, innerWidthFt, innerHeightFt,
                breakpointNormal, innerAtMinimum, out var boundary))
            return false;
        opening = outerOpening with
        {
            Boundary = boundary,
            SteppedProfile = new ExactSteppedOpeningProfile(
                innerWidthFt, innerHeightFt,
                breakpointNormal, innerAtMinimum),
            IsExactParameterizedReveal = true,
        };
        if (diagnostics)
            Diagnose($"accept source={sourceHost.Id} "
                + $"primitiveOuter={primitiveIsOuter} "
                + $"primitiveCentre={primitiveOpening.CentreXFt:G17},"
                + $"{primitiveOpening.CentreYFt:G17} "
                + $"primitiveDepth={primitiveOpening.DepthFt:G17} "
                + $"primitiveNormal={primitiveCentreNormal:G17} "
                + $"transformOrigin={transform.Origin[0]:G17},"
                + $"{transform.Origin[1]:G17} "
                + $"completeCentre={completeCentreNormal:G17} "
                + $"breakpoint={breakpointNormal:G17} "
                + $"minimum={completeMinimumNormal:G17} "
                + $"maximum={completeMaximumNormal:G17}");
        return true;
    }

    /// <summary>
    /// Expands a contracted writer primitive into the exact directed rectangular opening defined by
    /// independent instance contracts.
    /// </summary>
    internal static bool
        TryBuildExactContractedParameterizedRectangularOpening(
            Element hostedElement, Element sourceHost,
            IReadOnlyList<Element> candidateHostWalls,
            HostedOpeningGeometry primitiveOpening,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && (id == hostedElement.Id || id == sourceHost.Id));
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCCONTRACTEDRECTANGULARGATE wall={sourceHost.Id} "
                    + $"cutter={hostedElement.Id} result=reject stage={stage}");
            return false;
        }

        if (!primitiveOpening.ExactDepth
            || primitiveOpening.Boundary != null
            || primitiveOpening.IsFamilyCutLoop
            || primitiveOpening.IsExactFamilyCutLoopWriterBox
                && primitiveOpening.IsExactSerializedDefinition
            || primitiveOpening.SteppedProfile != null
            || primitiveOpening.IsExactParameterizedReveal
            || primitiveOpening.IsExactConcordantFamilyCut
            || primitiveOpening.IsExactMappedSideShell
            || primitiveOpening.IsExactSourceWallProfilesMappedBreakpoint
            || primitiveOpening.IsExactParameterizedRectangularCut
            || primitiveOpening.IsExactAuthoredMultiHostEnvelope)
            return Reject("contracted-loop");

        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        var primaryHosts = candidateHostWalls
            .Where(host => host.Id == primaryHostId).ToList();
        if (hostedElement.CategoryId != -2000014
            || primaryHosts.Count != 1
            || sourceHost.Id != primaryHostId
            || sourceHost.CuttingElementIds?.Count(
                id => id == hostedElement.Id) != 1
            || sourceHost.BoundingBox is not { Length: 6 } hostBounds
            || hostBounds.Any(value => !double.IsFinite(value))
            || sourceHost.Location is not
                { CurveType: "Line", ArcRadius: null } hostLocation
            || !TryGetSerializedWallWidthFeet(
                sourceHost, out double wallWidthFt)
            || !TryGetAuthoredStraightWallPlan(
                sourceHost, wallWidthFt, out var hostPlan)
            || hostPlan.Count != 4
            || !WallPlanMatchesSerializedBounds(hostPlan, hostBounds)
            || !TryGetSerializedInstanceTransform(
                hostedElement, out var transform))
            return Reject("primary-host");

        static bool TryGetUniqueExternalLength(
            Element element, Guid expectedGuid, out double value)
        {
            var matches = element.Parameters.Where(parameter =>
                    parameter.Id > 0
                    && parameter.StorageType == StorageType.Double
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.external.-1:",
                        StringComparison.Ordinal) == true
                    && BipHelpers.ParseGuidFromForgeId(parameter.ForgeId)
                        == expectedGuid
                    && (parameter.Guid == null
                        || parameter.Guid == expectedGuid)
                    && (parameter.SpecType == null
                        || parameter.SpecType.Contains(
                            ":length",
                            StringComparison.OrdinalIgnoreCase))
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .Select(parameter => (double)parameter.Value!)
                .ToList();
            value = matches.Count == 1 ? matches[0] : double.NaN;
            return matches.Count == 1;
        }

        bool TryGetUniqueFamilyLength(string name, out double value)
        {
            var matches = hostedElement.Parameters.Where(parameter =>
                    parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && parameter.StorageType == StorageType.Double
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .Select(parameter => (double)parameter.Value!)
                .ToList();
            value = matches.Count == 1 ? matches[0] : double.NaN;
            return matches.Count == 1;
        }

        var sillParameters = hostedElement.Parameters
            .Where(parameter => parameter.Id == -1001361
                && parameter.StorageType == StorageType.Double
                && parameter.Value is double value
                && value >= 0
                && double.IsFinite(value))
            .ToList();
        if (!TryGetUniqueExternalLength(
                hostedElement, AdskSizeWidthParameterGuid,
                out double externalWidthFt)
            || !TryGetUniqueExternalLength(
                hostedElement, AdskSizeHeightParameterGuid,
                out double externalHeightFt)
            || !TryGetUniqueFamilyLength(
                "Доп Глубина Внутренняя", out double innerDepthFt)
            || !TryGetUniqueFamilyLength(
                "Доп Глубина Наружная", out double outerDepthFt)
            || !TryGetUniqueFamilyLength(
                "Проем_Наружный_Ширина", out double familyWidthFt)
            || !TryGetUniqueFamilyLength(
                "Проем_Наружный_Высота", out double familyHeightFt)
            || !TryGetUniqueFamilyLength(
                "Подоконник_Проем_Ширина", out double sillOpeningWidthFt)
            || !TryGetUniqueFamilyLength(
                "Монтажный зазор Слева", out double leftGapFt)
            || !TryGetUniqueFamilyLength(
                "Монтажный зазор Справа", out double rightGapFt)
            || sillParameters.Count != 1)
            return Reject("parameter-contract");
        double sillHeightFt = (double)sillParameters[0].Value!;

        var values = new[]
        {
            primitiveOpening.CentreXFt, primitiveOpening.CentreYFt,
            primitiveOpening.AxisX, primitiveOpening.AxisY,
            primitiveOpening.WidthFt, primitiveOpening.DepthFt,
            primitiveOpening.BaseZFt, primitiveOpening.HeightFt,
            wallWidthFt, externalWidthFt, externalHeightFt,
            familyWidthFt, familyHeightFt, sillOpeningWidthFt,
            leftGapFt, rightGapFt, innerDepthFt, outerDepthFt,
            sillHeightFt,
        };
        if (values.Concat(transform.Origin)
            .Concat(transform.BasisX).Concat(transform.BasisY)
            .Concat(transform.BasisZ)
            .Any(value => !double.IsFinite(value)))
            return Reject("finite-values");
        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(
            1.0, values.Concat(transform.Origin)
                .Concat(transform.BasisX).Concat(transform.BasisY)
                .Concat(transform.BasisZ)
                .Concat(hostPlan.SelectMany(point => point))
                .Select(Math.Abs).Max());
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;

        static double Length(IReadOnlyList<double> vector) =>
            Math.Sqrt(vector[0] * vector[0]
                + vector[1] * vector[1] + vector[2] * vector[2]);
        static double Dot(
            IReadOnlyList<double> first, IReadOnlyList<double> second) =>
            first[0] * second[0] + first[1] * second[1]
                + first[2] * second[2];
        double basisXLength = Length(transform.BasisX);
        double basisYLength = Length(transform.BasisY);
        double basisZLength = Length(transform.BasisZ);
        if (!Same(basisXLength, 1)
            || !Same(basisYLength, 1)
            || !Same(basisZLength, 1)
            || Math.Abs(Dot(transform.BasisX, transform.BasisY)) > roundoff
            || Math.Abs(Dot(transform.BasisX, transform.BasisZ)) > roundoff
            || Math.Abs(Dot(transform.BasisY, transform.BasisZ)) > roundoff
            || Math.Abs(transform.BasisX[2]) > roundoff
            || Math.Abs(transform.BasisY[2]) > roundoff
            || Math.Abs(transform.BasisZ[0]) > roundoff
            || Math.Abs(transform.BasisZ[1]) > roundoff
            || !Same(transform.BasisZ[2], 1)
            || !Same(transform.BasisY[0], -transform.BasisX[1])
            || !Same(transform.BasisY[1], transform.BasisX[0]))
            return Reject("instance-frame");

        double hostDx =
            hostLocation.EndPoint[0] - hostLocation.StartPoint[0];
        double hostDy =
            hostLocation.EndPoint[1] - hostLocation.StartPoint[1];
        double hostAxisLength =
            Math.Sqrt(hostDx * hostDx + hostDy * hostDy);
        double primitiveAxisLength = Math.Sqrt(
            primitiveOpening.AxisX * primitiveOpening.AxisX
            + primitiveOpening.AxisY * primitiveOpening.AxisY);
        if (!(hostAxisLength > 0)
            || !double.IsFinite(hostAxisLength)
            || !(primitiveAxisLength > 0)
            || !double.IsFinite(primitiveAxisLength)
            || Math.Abs(Math.Abs(
                    hostDx / hostAxisLength * transform.BasisX[0]
                    + hostDy / hostAxisLength * transform.BasisX[1]) - 1)
                > roundoff
            || Math.Abs(Math.Abs(
                    primitiveOpening.AxisX / primitiveAxisLength
                        * transform.BasisX[0]
                    + primitiveOpening.AxisY / primitiveAxisLength
                        * transform.BasisX[1]) - 1)
                > roundoff)
            return Reject("host-axis");

        const double FamilyCutLoopIfcDepthFeet = 10.0;
        if (!Same(externalWidthFt, familyWidthFt)
            || !Same(externalWidthFt, sillOpeningWidthFt)
            || !Same(externalHeightFt, familyHeightFt)
            || !Same(primitiveOpening.WidthFt
                    + leftGapFt + rightGapFt,
                externalWidthFt)
            || !Same(primitiveOpening.HeightFt, externalHeightFt)
            || !Same(primitiveOpening.DepthFt,
                FamilyCutLoopIfcDepthFeet)
            || !Same(primitiveOpening.BaseZFt, sillHeightFt)
            || !Same(primitiveOpening.CentreXFt, transform.Origin[0])
            || !Same(primitiveOpening.CentreYFt, transform.Origin[1]))
            return Reject("contracted-profile");

        double axisX = transform.BasisX[0];
        double axisY = transform.BasisX[1];
        double normalX = transform.BasisY[0];
        double normalY = transform.BasisY[1];
        var hostNormals = hostPlan.Select(point =>
            point[0] * normalX + point[1] * normalY).ToList();
        double hostMinimumNormal = hostNormals.Min();
        double hostMaximumNormal = hostNormals.Max();
        if (!Same(hostMaximumNormal - hostMinimumNormal, wallWidthFt))
            return Reject("host-width");

        double minimumNormal = hostMinimumNormal - innerDepthFt;
        double maximumNormal = hostMaximumNormal + outerDepthFt;
        double centreNormal = (minimumNormal + maximumNormal) / 2;
        double centreAlong =
            transform.Origin[0] * axisX + transform.Origin[1] * axisY;
        var candidate = new HostedOpeningGeometry(
            CentreXFt: centreAlong * axisX + centreNormal * normalX,
            CentreYFt: centreAlong * axisY + centreNormal * normalY,
            AxisX: axisX,
            AxisY: axisY,
            WidthFt: externalWidthFt,
            DepthFt: maximumNormal - minimumNormal,
            BaseZFt: sillHeightFt,
            HeightFt: externalHeightFt,
            ExactDepth: true,
            IsExactParameterizedRectangularCut: true);
        var hostAlong = hostPlan.Select(point =>
            point[0] * axisX + point[1] * axisY).ToList();
        var hostPoints = sourceHost.Geometry?.Faces?
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat(face.AlternativeOuterVertices ?? [])
                .Concat((face.InnerVertices ?? [])
                    .SelectMany(ring => ring)))
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0])
                && double.IsFinite(point[1])
                && double.IsFinite(point[2]))
            .ToList() ?? [];
        if (hostPoints.Count < 4)
            return Reject("host-points");
        long Key(double feet) =>
            IfcPrecisionBinMetres(feet * FeetToMetres);
        long overlapMinimumAlong = Math.Max(
            Key(centreAlong - externalWidthFt / 2),
            Key(hostAlong.Min()));
        long overlapMaximumAlong = Math.Min(
            Key(centreAlong + externalWidthFt / 2),
            Key(hostAlong.Max()));
        long overlapMinimumZ = Math.Max(
            Key(sillHeightFt),
            Key(hostPoints.Min(point => point[2])));
        long overlapMaximumZ = Math.Min(
            Key(sillHeightFt + externalHeightFt),
            Key(hostPoints.Max(point => point[2])));
        if (overlapMaximumAlong <= overlapMinimumAlong
            || overlapMaximumZ <= overlapMinimumZ)
            return Reject("host-intersection");
        if (!TryBuildExactRectangularOpeningBoundary(
                candidate, out var boundary))
            return Reject("exact-boundary");

        opening = candidate with { Boundary = boundary };
        if (!ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
                opening))
        {
            opening = default;
            return Reject("boundary-definition");
        }
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCCONTRACTEDRECTANGULARGATE wall={sourceHost.Id} "
                + $"cutter={hostedElement.Id} result=accept "
                + $"width={opening.WidthFt:G17} "
                + $"height={opening.HeightFt:G17} "
                + $"depth={opening.DepthFt:G17} "
                + $"centre={opening.CentreXFt:G17},"
                + $"{opening.CentreYFt:G17},{opening.BaseZFt:G17}");
        return true;
    }

    /// <summary>
    /// Replaces a six-face family-cut prism with its exact parameterized rectangular definition
    /// when the placed source supplies four independent contracts: stable shared width/height
    /// GUIDs, equal positive inside/outside family-cut depths, the serialized primary-wall width.
    /// </summary>
    internal static bool
        TryBuildExactSymmetricAdditionalDepthRectangularOpening(
            Element hostedElement, Element sourceHost,
            IReadOnlyList<Element> candidateHostWalls,
            HostedOpeningGeometry primitiveOpening,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && (id == hostedElement.Id || id == sourceHost.Id));
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCPARAMRECTANGULARGATE wall={sourceHost.Id} "
                    + $"cutter={hostedElement.Id} result=reject stage={stage}");
            return false;
        }

        if (!primitiveOpening.ExactDepth
            || primitiveOpening.Boundary is not { Faces.Count: 6 } boundary
            || primitiveOpening.IsFamilyCutLoop
            || primitiveOpening.SteppedProfile != null
            || primitiveOpening.IsExactParameterizedReveal
            || primitiveOpening.IsExactSerializedDefinition
            || primitiveOpening.IsExactConcordantFamilyCut
            || primitiveOpening.IsExactMappedSideShell
            || primitiveOpening.IsExactSourceWallProfilesMappedBreakpoint
            || primitiveOpening.IsExactParameterizedRectangularCut
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                boundary, out var sourceDefinition))
            return Reject("source-prism");

        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        var primaryHosts = candidateHostWalls
            .Where(host => host.Id == primaryHostId).ToList();
        if (primaryHosts.Count != 1
            || sourceHost.Id != primaryHostId
            || sourceHost.CuttingElementIds is not { Count: 1 } sourceCutters
            || sourceCutters[0] != hostedElement.Id
            || sourceHost.Location is not
                { CurveType: "Line", ArcRadius: null } hostLocation
            || !TryGetSerializedWallWidthFeet(
                sourceHost, out double wallWidthFt)
            || !TryGetSerializedInstanceTransform(
                hostedElement, out var transform))
            return Reject("primary-host");

        static bool TryGetUniqueExternalLength(
            Element element, Guid expectedGuid, out double value)
        {
            var matches = element.Parameters.Where(parameter =>
                    parameter.Id > 0
                    && parameter.StorageType == StorageType.Double
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.external.-1:",
                        StringComparison.Ordinal) == true
                    && BipHelpers.ParseGuidFromForgeId(parameter.ForgeId)
                        == expectedGuid
                    && (parameter.Guid == null
                        || parameter.Guid == expectedGuid)
                    && (parameter.SpecType == null
                        || parameter.SpecType.Contains(
                            ":length",
                            StringComparison.OrdinalIgnoreCase))
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .Select(parameter => (double)parameter.Value!)
                .ToList();
            value = matches.Count == 1 ? matches[0] : double.NaN;
            return matches.Count == 1;
        }

        bool TryGetUniqueFamilyLength(string name, out double value)
        {
            var matches = hostedElement.Parameters.Where(parameter =>
                    parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && parameter.StorageType == StorageType.Double
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .Select(parameter => (double)parameter.Value!)
                .ToList();
            value = matches.Count == 1 ? matches[0] : double.NaN;
            return matches.Count == 1;
        }

        var sillParameters = hostedElement.Parameters
            .Where(parameter => parameter.Id == -1001361
                && parameter.StorageType == StorageType.Double
                && parameter.Value is double value
                && double.IsFinite(value))
            .ToList();
        if (!TryGetUniqueExternalLength(
                hostedElement, AdskSizeWidthParameterGuid,
                out double widthFt)
            || !TryGetUniqueExternalLength(
                hostedElement, AdskSizeHeightParameterGuid,
                out double heightFt)
            || !TryGetUniqueFamilyLength(
                "Вырез_Снаружи", out double outsideDepthFt)
            || !TryGetUniqueFamilyLength(
                "Вырез_Внутри", out double insideDepthFt)
            || sillParameters.Count != 1
            || (double)sillParameters[0].Value! != 0)
            return Reject("parameter-contract");

        double depthFt =
            wallWidthFt + outsideDepthFt + insideDepthFt;
        var values = new[]
        {
            wallWidthFt, widthFt, heightFt,
            outsideDepthFt, insideDepthFt, depthFt,
        };
        if (values.Concat(transform.Origin)
            .Concat(transform.BasisX).Concat(transform.BasisY)
            .Concat(transform.BasisZ)
            .Any(value => !double.IsFinite(value)))
            return Reject("finite-values");
        double scale = Math.Max(
            1.0, values.Concat(transform.Origin)
                .Concat(transform.BasisX).Concat(transform.BasisY)
                .Concat(transform.BasisZ)
                .Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        if (!(widthFt > 0.03) || !(heightFt > 0.03)
            || !(depthFt > roundoff)
            || !Same(outsideDepthFt, insideDepthFt))
            return Reject("symmetric-depth");

        static double Length(IReadOnlyList<double> vector) =>
            Math.Sqrt(vector[0] * vector[0]
                + vector[1] * vector[1] + vector[2] * vector[2]);
        static double Dot(
            IReadOnlyList<double> first, IReadOnlyList<double> second) =>
            first[0] * second[0] + first[1] * second[1]
                + first[2] * second[2];
        double basisXLength = Length(transform.BasisX);
        double basisYLength = Length(transform.BasisY);
        double basisZLength = Length(transform.BasisZ);
        if (!Same(basisXLength, 1)
            || !Same(basisYLength, 1)
            || !Same(basisZLength, 1)
            || Math.Abs(Dot(transform.BasisX, transform.BasisY)) > roundoff
            || Math.Abs(Dot(transform.BasisX, transform.BasisZ)) > roundoff
            || Math.Abs(Dot(transform.BasisY, transform.BasisZ)) > roundoff
            || Math.Abs(transform.BasisX[2]) > roundoff
            || Math.Abs(transform.BasisY[2]) > roundoff
            || Math.Abs(transform.BasisZ[0]) > roundoff
            || Math.Abs(transform.BasisZ[1]) > roundoff
            || !Same(transform.BasisZ[2], 1))
            return Reject("instance-frame");

        double hostDx =
            hostLocation.EndPoint[0] - hostLocation.StartPoint[0];
        double hostDy =
            hostLocation.EndPoint[1] - hostLocation.StartPoint[1];
        double hostAxisLength =
            Math.Sqrt(hostDx * hostDx + hostDy * hostDy);
        if (!(hostAxisLength > 0)
            || !double.IsFinite(hostAxisLength)
            || Math.Abs(Math.Abs(
                    hostDx / hostAxisLength * transform.BasisX[0]
                    + hostDy / hostAxisLength * transform.BasisX[1]) - 1)
                > roundoff)
            return Reject("host-axis");

        var candidate = new HostedOpeningGeometry(
            CentreXFt: transform.Origin[0],
            CentreYFt: transform.Origin[1],
            AxisX: transform.BasisX[0],
            AxisY: transform.BasisX[1],
            WidthFt: widthFt,
            DepthFt: depthFt,
            BaseZFt: transform.Origin[2],
            HeightFt: heightFt,
            ExactDepth: true,
            Boundary: boundary,
            IsExactParameterizedRectangularCut: true);

        if (!RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
                sourceDefinition, candidate))
            return Reject("source-parameter-lattice");

        opening = candidate;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCPARAMRECTANGULARGATE wall={sourceHost.Id} "
                + $"cutter={hostedElement.Id} result=accept "
                + $"width={widthFt:G17} height={heightFt:G17} "
                + $"depth={depthFt:G17} centre="
                + $"{candidate.CentreXFt:G17},{candidate.CentreYFt:G17},"
                + $"{candidate.BaseZFt:G17}");
        return true;
    }

    internal static bool TryBuildExactRectangularOpeningBoundary(
        HostedOpeningGeometry definition, out GeometryData boundary)
    {
        boundary = new GeometryData();
        double axisLength = Math.Sqrt(
            definition.AxisX * definition.AxisX
            + definition.AxisY * definition.AxisY);
        if (!(axisLength > 0)
            || !double.IsFinite(axisLength)
            || !(definition.WidthFt > 0)
            || !(definition.DepthFt > 0)
            || !(definition.HeightFt > 0)
            || !double.IsFinite(definition.CentreXFt)
            || !double.IsFinite(definition.CentreYFt)
            || !double.IsFinite(definition.BaseZFt)
            || !double.IsFinite(definition.WidthFt)
            || !double.IsFinite(definition.DepthFt)
            || !double.IsFinite(definition.HeightFt))
            return false;

        double axisX = definition.AxisX / axisLength;
        double axisY = definition.AxisY / axisLength;
        double normalX = -axisY;
        double normalY = axisX;
        double centreAlong =
            definition.CentreXFt * axisX + definition.CentreYFt * axisY;
        double centreNormal =
            definition.CentreXFt * normalX + definition.CentreYFt * normalY;
        double minimumAlong = centreAlong - definition.WidthFt / 2;
        double maximumAlong = centreAlong + definition.WidthFt / 2;
        double minimumNormal = centreNormal - definition.DepthFt / 2;
        double maximumNormal = centreNormal + definition.DepthFt / 2;
        double minimumZ = definition.BaseZFt;
        double maximumZ = minimumZ + definition.HeightFt;
        double[] Point(double along, double normal, double z) =>
        [
            along * axisX + normal * normalX,
            along * axisY + normal * normalY,
            z,
        ];

        double[] lowMinimumMinimum =
            Point(minimumAlong, minimumNormal, minimumZ);
        double[] lowMaximumMinimum =
            Point(maximumAlong, minimumNormal, minimumZ);
        double[] lowMaximumMaximum =
            Point(maximumAlong, maximumNormal, minimumZ);
        double[] lowMinimumMaximum =
            Point(minimumAlong, maximumNormal, minimumZ);
        double[] highMinimumMinimum =
            Point(minimumAlong, minimumNormal, maximumZ);
        double[] highMaximumMinimum =
            Point(maximumAlong, minimumNormal, maximumZ);
        double[] highMaximumMaximum =
            Point(maximumAlong, maximumNormal, maximumZ);
        double[] highMinimumMaximum =
            Point(minimumAlong, maximumNormal, maximumZ);
        static GeoFace Face(params double[][] vertices) => new()
        {
            OuterVertices = vertices.ToList(),
        };
        var faces = new List<GeoFace>
        {
            Face(lowMinimumMinimum, lowMaximumMinimum,
                lowMaximumMaximum, lowMinimumMaximum),
            Face(highMinimumMinimum, highMinimumMaximum,
                highMaximumMaximum, highMaximumMinimum),
            Face(lowMinimumMinimum, highMinimumMinimum,
                highMaximumMinimum, lowMaximumMinimum),
            Face(lowMaximumMinimum, highMaximumMinimum,
                highMaximumMaximum, lowMaximumMaximum),
            Face(lowMaximumMaximum, highMaximumMaximum,
                highMinimumMaximum, lowMinimumMaximum),
            Face(lowMinimumMaximum, highMinimumMaximum,
                highMinimumMinimum, lowMinimumMinimum),
        };
        if (!TryOrientExactFacetedShell(
                faces, Enumerable.Range(0, faces.Count).ToList(),
                out var oriented, triangulateNonPlanarFaces: false))
            return false;
        var points = oriented.SelectMany(
            face => face.OuterVertices!).ToList();
        boundary = new GeometryData
        {
            BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ],
            Faces = oriented,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices =
                        Enumerable.Range(0, oriented.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        return true;
    }

    internal static bool
        ExactParameterizedRectangularOpeningBoundaryMatchesDefinition(
            HostedOpeningGeometry opening)
    {
        if (!opening.IsExactParameterizedRectangularCut
            || opening.IsExactParameterizedReveal
            || opening.SteppedProfile != null
            || opening.Boundary is not { Faces.Count: 6 } boundary
            || !TryGetExactVerticalRectangularPrismSweptOpening(
                boundary, out var sourceDefinition))
            return false;
        return RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
            sourceDefinition, opening);
    }

    private static bool
        RectangularOpeningDefinitionsMatchWithinIfcGeometryLattice(
            HostedOpeningGeometry first, HostedOpeningGeometry second)
    {
        static List<double[]> Corners(HostedOpeningGeometry definition)
        {
            double axisLength = Math.Sqrt(
                definition.AxisX * definition.AxisX
                + definition.AxisY * definition.AxisY);
            if (!(axisLength > 0) || !double.IsFinite(axisLength))
                return [];
            double axisX = definition.AxisX / axisLength;
            double axisY = definition.AxisY / axisLength;
            double normalX = -axisY;
            double normalY = axisX;
            double halfWidth = definition.WidthFt / 2;
            double halfDepth = definition.DepthFt / 2;
            var corners = new List<double[]>(8);
            foreach (double z in new[]
                     {
                         definition.BaseZFt,
                         definition.BaseZFt + definition.HeightFt,
                     })
                foreach (double along in new[] { -halfWidth, halfWidth })
                    foreach (double normal in new[] { -halfDepth, halfDepth })
                        corners.Add(
                        [
                            definition.CentreXFt + along * axisX
                                + normal * normalX,
                            definition.CentreYFt + along * axisY
                                + normal * normalY,
                            z,
                        ]);
            return corners;
        }

        List<double[]> firstCorners = Corners(first);
        List<double[]> secondCorners = Corners(second);
        if (firstCorners.Count != 8 || secondCorners.Count != 8)
            return false;
        double writerStepFt =
            IfcGeometryPrecisionMetres / FeetToMetres;
        var unmatchedFirstCorners =
            new List<double[]>(firstCorners);
        foreach (double[] secondCorner in secondCorners)
        {
            int matchIndex = unmatchedFirstCorners.FindIndex(firstCorner =>
                Enumerable.Range(0, 3).All(coordinate =>
                    Math.Abs(firstCorner[coordinate]
                        - secondCorner[coordinate]) <= writerStepFt));
            if (matchIndex < 0)
                return false;
            unmatchedFirstCorners.RemoveAt(matchIndex);
        }
        return unmatchedFirstCorners.Count == 0;
    }

    /// <summary>
    /// Requires the same longitudinal/vertical rectangular profile while the second definition
    /// covers the first definition's complete normal interval.
    /// </summary>
    internal static bool
        RectangularOpeningProfileMatchesAndSecondContainsFirstNormalWithinIfcGeometryLattice(
            HostedOpeningGeometry first, HostedOpeningGeometry second)
    {
        double firstAxisLength = Math.Sqrt(
            first.AxisX * first.AxisX + first.AxisY * first.AxisY);
        double secondAxisLength = Math.Sqrt(
            second.AxisX * second.AxisX + second.AxisY * second.AxisY);
        var values = new[]
        {
            first.CentreXFt, first.CentreYFt,
            first.AxisX, first.AxisY,
            first.WidthFt, first.DepthFt, first.BaseZFt, first.HeightFt,
            second.CentreXFt, second.CentreYFt,
            second.AxisX, second.AxisY,
            second.WidthFt, second.DepthFt,
            second.BaseZFt, second.HeightFt,
            firstAxisLength, secondAxisLength,
        };
        if (values.Any(value => !double.IsFinite(value))
            || !(firstAxisLength > 0) || !(secondAxisLength > 0)
            || !(first.WidthFt > 0) || !(first.DepthFt > 0)
            || !(first.HeightFt > 0)
            || !(second.WidthFt > 0) || !(second.DepthFt > 0)
            || !(second.HeightFt > 0))
            return false;

        double firstAxisX = first.AxisX / firstAxisLength;
        double firstAxisY = first.AxisY / firstAxisLength;
        double secondAxisX = second.AxisX / secondAxisLength;
        double secondAxisY = second.AxisY / secondAxisLength;
        double directionDot = firstAxisX * secondAxisX
            + firstAxisY * secondAxisY;
        double directionCross = firstAxisX * secondAxisY
            - firstAxisY * secondAxisX;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double directionRoundoff = 8192 * MachineEpsilon;
        if (Math.Abs(Math.Abs(directionDot) - 1) > directionRoundoff)
        {
            if (Math.Abs(directionDot) > directionRoundoff
                || Math.Abs(Math.Abs(directionCross) - 1)
                    > directionRoundoff)
                return false;
            first = first with
            {
                AxisX = -first.AxisY,
                AxisY = first.AxisX,
                WidthFt = first.DepthFt,
                DepthFt = first.WidthFt,
            };
            firstAxisX = first.AxisX / firstAxisLength;
            firstAxisY = first.AxisY / firstAxisLength;
            directionDot = firstAxisX * secondAxisX
                + firstAxisY * secondAxisY;
            if (Math.Abs(Math.Abs(directionDot) - 1)
                > directionRoundoff)
                return false;
        }

        double normalX = -secondAxisY;
        double normalY = secondAxisX;
        double firstCentreAlong = first.CentreXFt * secondAxisX
            + first.CentreYFt * secondAxisY;
        double secondCentreAlong = second.CentreXFt * secondAxisX
            + second.CentreYFt * secondAxisY;
        double firstCentreNormal = first.CentreXFt * normalX
            + first.CentreYFt * normalY;
        double secondCentreNormal = second.CentreXFt * normalX
            + second.CentreYFt * normalY;
        double firstMinimumNormal = firstCentreNormal - first.DepthFt / 2;
        double firstMaximumNormal = firstCentreNormal + first.DepthFt / 2;
        double secondMinimumNormal = secondCentreNormal - second.DepthFt / 2;
        double secondMaximumNormal = secondCentreNormal + second.DepthFt / 2;
        double writerStepFt = IfcGeometryPrecisionMetres / FeetToMetres;
        bool SameWriterCoordinate(double firstValue, double secondValue) =>
            Math.Abs(firstValue - secondValue) <= writerStepFt;
        return SameWriterCoordinate(first.WidthFt, second.WidthFt)
            && SameWriterCoordinate(first.BaseZFt, second.BaseZFt)
            && SameWriterCoordinate(
                first.BaseZFt + first.HeightFt,
                second.BaseZFt + second.HeightFt)
            && SameWriterCoordinate(firstCentreAlong, secondCentreAlong)
            && secondMinimumNormal <= firstMinimumNormal + writerStepFt
            && secondMaximumNormal >= firstMaximumNormal - writerStepFt;
    }

    /// <summary>
    /// Reconstructs a two-profile reveal only when two independent exact parameter systems agree
    /// with the serialized primitive.
    /// </summary>
    internal static bool TryBuildExactParameterizedRevealOpening(
        Element hostedElement, IReadOnlyList<Element> candidateHostWalls,
        HostedOpeningGeometry primitiveOpening,
        out HostedOpeningGeometry opening)
    {
        opening = default;
        if (!primitiveOpening.ExactDepth
            || primitiveOpening.Boundary != null
            || primitiveOpening.IsFamilyCutLoop
            || primitiveOpening.SteppedProfile != null
            || !(primitiveOpening.WidthFt > 0.03)
            || !(primitiveOpening.DepthFt > 0)
            || !(primitiveOpening.HeightFt > 0.03))
            return false;
        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        var primaryHosts = candidateHostWalls
            .Where(host => host.Id == primaryHostId).ToList();
        if (primaryHosts.Count != 1
            || !TryGetSerializedWallWidthFeet(
                    primaryHosts[0], out double serializedWallWidthFt)
            || !TryGetSerializedInstanceTransform(
                    hostedElement, out var transform))
            return false;

        bool TryGetExactInstanceFamilyLength(
            string name, out double value)
        {
            var parameters = hostedElement.Parameters
                .Where(parameter => parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .ToList();
            value = parameters.Count == 1
                ? (double)parameters[0].Value! : double.NaN;
            return parameters.Count == 1;
        }

        if (!TryGetExactInstanceFamilyLength(
                "Регулировка выступа выреза проёма вовнутрь",
                out double innerProjectionFt)
            || !TryGetExactInstanceFamilyLength(
                "Регулировка выступа выреза проёма наружу",
                out double outerProjectionFt)
            || !TryGetExactInstanceFamilyLength(
                "Регулировка глубины вставки окна",
                out double insertionDepthFt)
            || !TryGetExactInstanceFamilyLength(
                "стена_толщина", out double wallWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "Четверть сверху", out double topQuarterFt)
            || !TryGetExactInstanceFamilyLength(
                "Четверть слева", out double leftQuarterFt)
            || !TryGetExactInstanceFamilyLength(
                "Четверть справа", out double rightQuarterFt)
            || !TryGetExactInstanceFamilyLength(
                "створка_слева_ширина", out double leftSashWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "створка_справа_ширина", out double rightSashWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "импост_ширина", out double mullionWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "каркас_ширина", out double frameWidthFt)
            || !TryGetExactInstanceFamilyLength(
                "Монтажные зазоры", out double mountingGapFt)
            || !TryGetExactInstanceFamilyLength(
                "створка_высота", out double sashHeightFt))
            return false;

        double outerWidthFt =
            leftSashWidthFt + rightSashWidthFt + mullionWidthFt
            + 2 * frameWidthFt + 2 * mountingGapFt;
        double outerHeightFt =
            sashHeightFt + 2 * frameWidthFt + 2 * mountingGapFt;
        double innerWidthFt =
            outerWidthFt - leftQuarterFt - rightQuarterFt;
        double innerHeightFt = outerHeightFt - topQuarterFt;
        double innerDepthFt = innerProjectionFt + insertionDepthFt;
        double outerDepthFt =
            outerProjectionFt + wallWidthFt - insertionDepthFt;
        double completeDepthFt =
            innerProjectionFt + outerProjectionFt + wallWidthFt;
        var values = new[]
        {
            primitiveOpening.CentreXFt, primitiveOpening.CentreYFt,
            primitiveOpening.WidthFt, primitiveOpening.DepthFt,
            primitiveOpening.BaseZFt, primitiveOpening.HeightFt,
            serializedWallWidthFt, innerProjectionFt, outerProjectionFt,
            insertionDepthFt, wallWidthFt, topQuarterFt,
            leftQuarterFt, rightQuarterFt, leftSashWidthFt,
            rightSashWidthFt, mullionWidthFt, frameWidthFt,
            mountingGapFt, sashHeightFt, outerWidthFt, outerHeightFt,
            innerWidthFt, innerHeightFt, innerDepthFt, outerDepthFt,
            completeDepthFt,
        };
        if (values.Concat(transform.Origin)
            .Concat(transform.BasisX).Concat(transform.BasisY)
            .Any(value => !double.IsFinite(value)))
            return false;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(
            1.0, values.Concat(transform.Origin)
                .Concat(transform.BasisX).Concat(transform.BasisY)
                .Select(Math.Abs).Max());
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        if (!Same(wallWidthFt, serializedWallWidthFt)
            || !(innerWidthFt > 0.03)
            || !(innerHeightFt > 0.03)
            || !(innerDepthFt > roundoff)
            || !(outerDepthFt > roundoff)
            || !(completeDepthFt > roundoff))
            return false;

        bool primitiveIsOuter =
            Same(primitiveOpening.WidthFt, outerWidthFt)
            && Same(primitiveOpening.HeightFt, outerHeightFt);
        bool primitiveIsOuterWithFrame =
            Same(primitiveOpening.WidthFt, outerWidthFt + frameWidthFt)
            && Same(primitiveOpening.HeightFt, outerHeightFt);
        bool primitiveIsInner =
            Same(primitiveOpening.WidthFt, innerWidthFt)
            && Same(primitiveOpening.HeightFt, innerHeightFt);
        if ((primitiveIsOuter ? 1 : 0)
                + (primitiveIsOuterWithFrame ? 1 : 0)
                + (primitiveIsInner ? 1 : 0) != 1)
            return false;

        double axisLength = Math.Sqrt(
            primitiveOpening.AxisX * primitiveOpening.AxisX
            + primitiveOpening.AxisY * primitiveOpening.AxisY);
        double basisXLength = Math.Sqrt(
            transform.BasisX[0] * transform.BasisX[0]
            + transform.BasisX[1] * transform.BasisX[1]);
        double basisYLength = Math.Sqrt(
            transform.BasisY[0] * transform.BasisY[0]
            + transform.BasisY[1] * transform.BasisY[1]);
        if (!(axisLength > 0) || !(basisXLength > 0)
            || !(basisYLength > 0)
            || !double.IsFinite(axisLength)
            || !double.IsFinite(basisXLength)
            || !double.IsFinite(basisYLength))
            return false;
        double axisX = primitiveOpening.AxisX / axisLength;
        double axisY = primitiveOpening.AxisY / axisLength;
        double normalX = -axisY, normalY = axisX;
        double basisXx = transform.BasisX[0] / basisXLength;
        double basisXy = transform.BasisX[1] / basisXLength;
        double basisYx = transform.BasisY[0] / basisYLength;
        double basisYy = transform.BasisY[1] / basisYLength;
        double basisXDot =
            basisXx * axisX + basisXy * axisY;
        double basisYNormalDot =
            basisYx * normalX + basisYy * normalY;
        if (Math.Abs(Math.Abs(basisXDot) - 1) > roundoff
            || Math.Abs(Math.Abs(basisYNormalDot) - 1) > roundoff
            || Math.Abs(basisXx * basisYx + basisXy * basisYy)
                > roundoff
            || Math.Abs(transform.BasisX[2]) > roundoff
            || Math.Abs(transform.BasisY[2]) > roundoff)
            return false;

        double centreAlong =
            primitiveOpening.CentreXFt * axisX
            + primitiveOpening.CentreYFt * axisY;
        double originNormal =
            transform.Origin[0] * normalX
            + transform.Origin[1] * normalY;
        double centreNormal = originNormal
            + basisYNormalDot
                * (innerProjectionFt - outerProjectionFt) / 2;
        double breakpointNormal = originNormal
            + basisYNormalDot * (wallWidthFt / 2 - insertionDepthFt);
        var outerOpening = primitiveOpening with
        {
            CentreXFt =
                centreAlong * axisX + centreNormal * normalX,
            CentreYFt =
                centreAlong * axisY + centreNormal * normalY,
            AxisX = axisX,
            AxisY = axisY,
            WidthFt = outerWidthFt,
            DepthFt = completeDepthFt,
            HeightFt = outerHeightFt,
        };
        bool innerAtMinimum = basisYNormalDot < 0;
        if (!TryBuildExactSteppedOpeningBoundary(
                outerOpening, innerWidthFt, innerHeightFt,
                breakpointNormal, innerAtMinimum, out var boundary))
            return false;
        opening = outerOpening with
        {
            Boundary = boundary,
            SteppedProfile = new ExactSteppedOpeningProfile(
                innerWidthFt, innerHeightFt,
                breakpointNormal, innerAtMinimum),
            IsExactParameterizedReveal = true,
        };
        return true;
    }

    /// <summary>
    /// Forward-only and robustly disjoint candidate hosts remain part of the legacy emitted
    /// topology but cannot enlarge the authored operand.
    /// </summary>
    internal static bool
        TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
            Element hostedElement, Element? hostedType, double[] hostedBbox,
            IReadOnlyList<Element> candidateHostWalls,
            HostedOpeningGeometry candidateCommonOpening,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);
        void Diagnose(string stage) =>
            DiagnosticSink.WriteLine($"IFCSTEPPEDHOSTGATE cutter={hostedElement.Id} "
                + $"stage={stage}");
        bool RobustlyDisjointFromCandidateOpening(Element host)
        {
            return host.BoundingBox is { Length: 6 } bounds
                && bounds.All(double.IsFinite)
                && host.Location is
                    { CurveType: "Line", ArcRadius: null } location
                && TryGetSerializedWallWidthFeet(host, out double widthFt)
                && TryBuildStraightWallBoundary(host, out var boundary)
                && TryGetExactStraightWallGrossBoundaryAndOpenings(
                    boundary, location, widthFt, bounds,
                    out var gross, out _, out _)
                && HostedOpeningWriterOperandIsRobustlyDisjointFromExactWall(
                    host, bounds, gross, candidateCommonOpening);
        }
        double axisLength = Math.Sqrt(
            candidateCommonOpening.AxisX * candidateCommonOpening.AxisX
            + candidateCommonOpening.AxisY * candidateCommonOpening.AxisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
        {
            if (diagnostics) Diagnose("candidate-axis");
            return false;
        }
        double axisX = candidateCommonOpening.AxisX / axisLength;
        double axisY = candidateCommonOpening.AxisY / axisLength;
        double normalX = -axisY, normalY = axisX;
        var decodedCutHostWalls = candidateHostWalls
            .Where(host => host.CuttingElementIds?.Count(
                id => id == hostedElement.Id) == 1)
            .ToList();
        if (decodedCutHostWalls.Select(host => host.Id).Distinct().Count()
            != decodedCutHostWalls.Count)
        {
            if (diagnostics) Diagnose("duplicate-host");
            return false;
        }
        var exactSerializedPrimaryHosts =
            hostedElement.SerializedHostId is > 0
                ? candidateHostWalls.Where(host =>
                    host.Id == hostedElement.SerializedHostId.Value)
                    .ToList()
                : [];
        if (exactSerializedPrimaryHosts.Count > 1)
        {
            if (diagnostics) Diagnose("duplicate-serialized-primary-host");
            return false;
        }
        var exactValidationHostWalls = decodedCutHostWalls
            .Concat(exactSerializedPrimaryHosts)
            .DistinctBy(host => host.Id)
            .ToList();
        var authoredCutHostWalls = exactValidationHostWalls
            .Where(host => !RobustlyDisjointFromCandidateOpening(host))
            .ToList();
        if (diagnostics)
            Diagnose($"hosts candidate={string.Join(',', candidateHostWalls.Select(
                host => host.Id))} decoded={string.Join(',', decodedCutHostWalls.Select(
                host => host.Id))} authored={string.Join(',', authoredCutHostWalls.Select(
                    host => host.Id))}");
        bool TryGetValidationNormalEnvelope(IReadOnlyList<Element> hosts,
            out double minimumNormal, out double maximumNormal,
            out double breakpointNormal)
        {
            minimumNormal = double.PositiveInfinity;
            maximumNormal = double.NegativeInfinity;
            breakpointNormal = double.NaN;
            double innerMinimumNormal = double.PositiveInfinity;
            double innerMaximumNormal = double.NegativeInfinity;
            double[] associationBox = BuildHostedOpeningAssociationBox(
                hostedElement, hostedBbox);
            foreach (var host in hosts)
            {
                if (!TryBuildStraightWallBoundary(host, out var straightBoundary))
                    return false;
                if (host.BoundingBox is { Length: 6 } wallBounds
                    && wallBounds.All(double.IsFinite)
                    && host.Location is
                        { CurveType: "Line", ArcRadius: null } location
                    && TryGetSerializedWallWidthFeet(
                        host, out double wallWidthFt)
                    && TryGetExactStraightWallGrossBoundaryAndOpenings(
                        straightBoundary, location, wallWidthFt, wallBounds,
                        out _, out var holes, out _))
                {
                    var matchingHoles = holes.Where(hole =>
                            ExactWallHoleCanBelongToCommonOpening(
                                candidateCommonOpening, hole))
                        .ToList();
                    if (matchingHoles.Count != 1)
                        return false;
                    var exactHole = matchingHoles[0];
                    double holeAxisLength = Math.Sqrt(
                        exactHole.AxisX * exactHole.AxisX
                        + exactHole.AxisY * exactHole.AxisY);
                    if (!(holeAxisLength > 0)
                        || !double.IsFinite(holeAxisLength))
                        return false;
                    double holeAxisX = exactHole.AxisX / holeAxisLength;
                    double holeAxisY = exactHole.AxisY / holeAxisLength;
                    double holeNormalX = -holeAxisY;
                    double holeNormalY = holeAxisX;
                    double holeCentreAlong =
                        exactHole.CentreXFt * holeAxisX
                        + exactHole.CentreYFt * holeAxisY;
                    double ProjectNormal(double holeNormal)
                    {
                        double x = holeCentreAlong * holeAxisX
                            + holeNormal * holeNormalX;
                        double y = holeCentreAlong * holeAxisY
                            + holeNormal * holeNormalY;
                        return x * normalX + y * normalY;
                    }
                    double firstNormal =
                        ProjectNormal(exactHole.NormalMinimumFt);
                    double secondNormal =
                        ProjectNormal(exactHole.NormalMaximumFt);
                    minimumNormal = Math.Min(minimumNormal,
                        Math.Min(firstNormal, secondNormal));
                    maximumNormal = Math.Max(maximumNormal,
                        Math.Max(firstNormal, secondNormal));
                    if (exactHole.WidthFt < candidateCommonOpening.WidthFt
                        && exactHole.HeightFt
                            < candidateCommonOpening.HeightFt)
                    {
                        innerMinimumNormal = Math.Min(innerMinimumNormal,
                            Math.Min(firstNormal, secondNormal));
                        innerMaximumNormal = Math.Max(innerMaximumNormal,
                            Math.Max(firstNormal, secondNormal));
                    }
                    continue;
                }

                if (!TryBuildHostedOpeningBoundary(
                        host, associationBox, out var authoredBoundary)
                    || !TryGetAuthoredHostedOpeningSpan(
                        host, authoredBoundary, out _, out _, out _, out _))
                    return false;
                var normalCoordinates = authoredBoundary.Faces
                    .SelectMany(face => face.OuterVertices ?? [])
                    .Where(point => point.Length >= 3
                        && double.IsFinite(point[0])
                        && double.IsFinite(point[1])
                        && double.IsFinite(point[2]))
                    .Select(point =>
                        point[0] * normalX + point[1] * normalY)
                    .ToList();
                if (normalCoordinates.Count < 8) return false;
                minimumNormal = Math.Min(
                    minimumNormal, normalCoordinates.Min());
                maximumNormal = Math.Max(
                    maximumNormal, normalCoordinates.Max());
            }
            if (!double.IsFinite(minimumNormal)
                || !double.IsFinite(maximumNormal)
                || !double.IsFinite(innerMinimumNormal)
                || !double.IsFinite(innerMaximumNormal))
                return false;
            var normalValues = new[]
            {
                minimumNormal, maximumNormal,
                innerMinimumNormal, innerMaximumNormal,
            };
            const double MachineEpsilon = 2.2204460492503131e-16;
            double scale = Math.Max(
                1.0, normalValues.Select(Math.Abs).Max());
            double roundoff = 8192 * MachineEpsilon * scale;
            double minimumEndGap = innerMinimumNormal - minimumNormal;
            double maximumEndGap = maximumNormal - innerMaximumNormal;
            if (maximumNormal - minimumNormal <= roundoff
                || innerMaximumNormal - innerMinimumNormal <= roundoff
                || minimumEndGap < -roundoff
                || maximumEndGap < -roundoff
                || Math.Abs(minimumEndGap - maximumEndGap) <= roundoff)
                return false;
            breakpointNormal = minimumEndGap < maximumEndGap
                ? innerMaximumNormal : innerMinimumNormal;
            return double.IsFinite(breakpointNormal);
        }
        bool TryGetExactInstanceFamilyLength(
            string name, bool requireWritable, out double value)
        {
            var parameters = hostedElement.Parameters
                .Where(parameter => parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && (!requireWritable || !parameter.IsReadOnly)
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.Value is double value
                    && value > 0 && double.IsFinite(value)
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true)
                .ToList();
            value = parameters.Count == 1
                ? (double)parameters[0].Value! : double.NaN;
            return parameters.Count == 1;
        }
        bool TryGetExactAdditionalDepths(
            out double innerDepth, out double outerDepth)
        {
            innerDepth = double.NaN;
            outerDepth = double.NaN;
            return TryGetExactInstanceFamilyLength(
                    "Доп Глубина Внутренняя",
                    requireWritable: false, out innerDepth)
                && TryGetExactInstanceFamilyLength(
                    "Доп Глубина Наружная",
                    requireWritable: false, out outerDepth)
                && innerDepth != outerDepth;
        }
        bool TryBuildDirectSteppedSideOpening(
            out HostedOpeningGeometry builtOpening)
        {
            // Some direct hosts preserve exact wall-side profiles while triangulating only their
            // connector faces.
            builtOpening = default;
            var directHostIds = new[]
                {
                    hostedElement.HostId,
                    hostedElement.SerializedHostId,
                }
                .Where(id => id is > 0)
                .Distinct()
                .ToHashSet();
            var directHosts = candidateHostWalls
                .Where(host => directHostIds.Contains(host.Id))
                .ToList();
            if (directHosts.Count != 1
                || !candidateCommonOpening.ExactDepth
                || candidateCommonOpening.Boundary != null
                || candidateCommonOpening.IsFamilyCutLoop
                || !TryGetExactAdditionalDepths(
                    out _, out double innerSegmentDepth)
                || !TryGetExactInstanceFamilyLength(
                    "Проем_Наружный_Ширина",
                    requireWritable: false, out double innerWidth)
                || !TryGetExactInstanceFamilyLength(
                    "Проем_Наружный_Высота",
                    requireWritable: false, out double innerHeight)
                || !TryGetExactInstanceFamilyLength(
                    "Подоконник_Проем_Ширина",
                    requireWritable: false, out double outerWidth)
                || !TryGetExactInstanceFamilyLength(
                    "Четверть Сверху",
                    requireWritable: false, out double upperQuarter))
                return false;
            Element directHost = directHosts[0];
            if (directHost.CuttingElementIds is { Count: > 0 } cuttingIds
                && cuttingIds.Count(id => id == hostedElement.Id) != 1)
                return false;
            if (!TryBuildStraightWallBoundary(
                    directHost, out var directBoundary)
                || directBoundary.Faces is not { Count: >= 10 } faces
                || directBoundary.BrepSolids is not { Count: 1 } solids
                || !solids[0].IsClosed
                || !solids[0].FaceIndices.Distinct().Order()
                    .SequenceEqual(Enumerable.Range(0, faces.Count))
                || !TryOrientExactFacetedShell(
                    faces, solids[0].FaceIndices, out _,
                    triangulateNonPlanarFaces: false))
                return false;

            var values = new[]
            {
                innerWidth, innerHeight, outerWidth, upperQuarter,
                innerSegmentDepth,
                candidateCommonOpening.CentreXFt,
                candidateCommonOpening.CentreYFt,
                candidateCommonOpening.WidthFt,
                candidateCommonOpening.DepthFt,
                candidateCommonOpening.BaseZFt,
                candidateCommonOpening.HeightFt,
            };
            if (values.Any(value => !double.IsFinite(value)))
                return false;
            double outerHeight = innerHeight + upperQuarter;
            const double MachineEpsilon = 2.2204460492503131e-16;
            double scale = Math.Max(1.0, values.Append(outerHeight)
                .Select(Math.Abs).Max());
            double roundoff = 8192 * MachineEpsilon * scale;
            bool Same(double first, double second) =>
                Math.Abs(first - second) <= roundoff;
            bool candidateHasExactProfile =
                (Same(candidateCommonOpening.WidthFt, innerWidth)
                    && Same(candidateCommonOpening.HeightFt, innerHeight))
                || (Same(candidateCommonOpening.WidthFt, outerWidth)
                    && Same(candidateCommonOpening.HeightFt, outerHeight));
            if (!(outerWidth > innerWidth + roundoff)
                || !(outerHeight > innerHeight + roundoff)
                || !(innerSegmentDepth > roundoff)
                || !(candidateCommonOpening.DepthFt
                    > innerSegmentDepth + roundoff)
                || !candidateHasExactProfile)
                return false;

            bool TryGetSideProfile(GeoFace face,
                out (double CentreAlong, double Width, double BaseZ,
                    double Height, double Plane) profile)
            {
                profile = default;
                if (face.InnerVertices is not { Count: 1 } inner
                    || inner[0] is not { Count: 4 } ring
                    || ring.Any(point => point.Length < 3
                        || !double.IsFinite(point[0])
                        || !double.IsFinite(point[1])
                        || !double.IsFinite(point[2])))
                    return false;
                var projected = ring.Select(point => (
                    Along: point[0] * axisX + point[1] * axisY,
                    Plane: point[0] * normalX + point[1] * normalY,
                    Z: point[2])).ToList();
                double minimumAlong =
                    projected.Min(value => value.Along);
                double maximumAlong =
                    projected.Max(value => value.Along);
                double minimumPlane =
                    projected.Min(value => value.Plane);
                double maximumPlane =
                    projected.Max(value => value.Plane);
                double minimumZ = projected.Min(value => value.Z);
                double maximumZ = projected.Max(value => value.Z);
                if (maximumPlane - minimumPlane > roundoff
                    || !(maximumAlong - minimumAlong > roundoff)
                    || !(maximumZ - minimumZ > roundoff))
                    return false;
                var corners = projected.Select(value => (
                        Along: Same(value.Along, minimumAlong) ? -1
                            : Same(value.Along, maximumAlong) ? 1 : 0,
                        Z: Same(value.Z, minimumZ) ? -1
                            : Same(value.Z, maximumZ) ? 1 : 0))
                    .ToList();
                if (corners.Any(corner =>
                        corner.Along == 0 || corner.Z == 0)
                    || corners.Distinct().Count() != 4)
                    return false;
                profile = (
                    (minimumAlong + maximumAlong) / 2,
                    maximumAlong - minimumAlong,
                    minimumZ, maximumZ - minimumZ,
                    (minimumPlane + maximumPlane) / 2);
                return true;
            }

            var sideProfiles = faces
                .Where(face => face.InnerVertices is { Count: 1 })
                .Select(face => TryGetSideProfile(face, out var profile)
                    ? (Valid: true, Profile: profile)
                    : (Valid: false, Profile: default))
                .ToList();
            if (sideProfiles.Count != 2
                || sideProfiles.Any(item => !item.Valid))
                return false;
            var exactInnerProfiles = sideProfiles
                .Where(item =>
                    Same(item.Profile.Width, innerWidth)
                    && Same(item.Profile.Height, innerHeight))
                .Select(item => item.Profile).ToList();
            var exactOuterProfiles = sideProfiles
                .Where(item =>
                    Same(item.Profile.Width, outerWidth)
                    && Same(item.Profile.Height, outerHeight))
                .Select(item => item.Profile).ToList();
            if (exactInnerProfiles.Count != 1
                || exactOuterProfiles.Count != 1)
                return false;
            var innerProfile = exactInnerProfiles[0];
            var outerProfile = exactOuterProfiles[0];
            double candidateCentreAlong =
                candidateCommonOpening.CentreXFt * axisX
                + candidateCommonOpening.CentreYFt * axisY;
            if (!Same(innerProfile.CentreAlong, candidateCentreAlong)
                || !Same(outerProfile.CentreAlong, candidateCentreAlong)
                || !Same(innerProfile.BaseZ,
                    candidateCommonOpening.BaseZFt)
                || !Same(outerProfile.BaseZ,
                    candidateCommonOpening.BaseZFt))
                return false;

            double candidateCentreNormal =
                candidateCommonOpening.CentreXFt * normalX
                + candidateCommonOpening.CentreYFt * normalY;
            double minimumNormal = candidateCentreNormal
                - candidateCommonOpening.DepthFt / 2;
            double maximumNormal = candidateCentreNormal
                + candidateCommonOpening.DepthFt / 2;
            bool InSegment(double plane, double minimum, double maximum) =>
                plane >= minimum - roundoff
                && plane <= maximum + roundoff;
            var orientations =
                new List<(double Breakpoint, bool InnerAtMinimum)>();
            double minimumBreakpoint =
                minimumNormal + innerSegmentDepth;
            if (InSegment(innerProfile.Plane,
                    minimumNormal, minimumBreakpoint)
                && InSegment(outerProfile.Plane,
                    minimumBreakpoint, maximumNormal))
                orientations.Add((minimumBreakpoint, true));
            double maximumBreakpoint =
                maximumNormal - innerSegmentDepth;
            if (InSegment(innerProfile.Plane,
                    maximumBreakpoint, maximumNormal)
                && InSegment(outerProfile.Plane,
                    minimumNormal, maximumBreakpoint))
                orientations.Add((maximumBreakpoint, false));
            if (orientations.Count != 1)
                return false;
            var orientation = orientations[0];
            var exactOuterOpening = candidateCommonOpening with
            {
                WidthFt = outerWidth,
                HeightFt = outerHeight,
            };
            if (!TryBuildExactSteppedOpeningBoundary(
                    exactOuterOpening, innerWidth, innerHeight,
                    orientation.Breakpoint, orientation.InnerAtMinimum,
                    out var boundary))
                return false;
            builtOpening = exactOuterOpening with
            {
                Boundary = boundary,
                SteppedProfile = new ExactSteppedOpeningProfile(
                    innerWidth, innerHeight,
                    orientation.Breakpoint,
                    orientation.InnerAtMinimum),
            };
            return true;
        }
        bool TryBuildDirectClosedOuterProfileOpening(
            out HostedOpeningGeometry builtOpening)
        {
            // The reconstructed wall may retain only the inner through-hole while a separate exact
            // closed source solid carries both outer side profiles.
            builtOpening = default;
            var directHostIds = new[]
                {
                    hostedElement.HostId,
                    hostedElement.SerializedHostId,
                }
                .Where(id => id is > 0)
                .Distinct()
                .ToHashSet();
            var directHosts = candidateHostWalls
                .Where(host => directHostIds.Contains(host.Id))
                .ToList();
            if (directHosts.Count != 1
                || !candidateCommonOpening.ExactDepth
                || candidateCommonOpening.Boundary != null
                || candidateCommonOpening.IsFamilyCutLoop
                || !TryGetExactAdditionalDepths(
                    out double firstDepth, out double secondDepth)
                || !TryGetExactInstanceFamilyLength(
                    "Проем_Наружный_Ширина",
                    requireWritable: false, out double innerWidth)
                || !TryGetExactInstanceFamilyLength(
                    "Проем_Наружный_Высота",
                    requireWritable: false, out double innerHeight)
                || !TryGetExactInstanceFamilyLength(
                    "Подоконник_Проем_Ширина",
                    requireWritable: false, out double outerWidth)
                || !TryGetExactInstanceFamilyLength(
                    "Четверть Сверху",
                    requireWritable: false, out double upperQuarter))
                return false;
            double outerHeight = innerHeight + upperQuarter;
            var values = new[]
            {
                firstDepth, secondDepth,
                innerWidth, innerHeight, outerWidth, outerHeight,
                candidateCommonOpening.CentreXFt,
                candidateCommonOpening.CentreYFt,
                candidateCommonOpening.WidthFt,
                candidateCommonOpening.DepthFt,
                candidateCommonOpening.BaseZFt,
                candidateCommonOpening.HeightFt,
            };
            if (values.Any(value => !double.IsFinite(value)))
                return false;
            Element directHost = directHosts[0];
            if (directHost.CuttingElementIds is { Count: > 0 } cuttingIds
                && cuttingIds.Count(id => id == hostedElement.Id) != 1)
                return false;
            if (directHost.BoundingBox is not { Length: 6 } wallBounds
                || !wallBounds.All(double.IsFinite)
                || directHost.Location is not
                    { CurveType: "Line", ArcRadius: null } location
                || !TryGetSerializedWallWidthFeet(
                    directHost, out double wallWidthFt)
                || !TryBuildStraightWallBoundary(
                    directHost, out var straightBoundary)
                || !TryGetExactStraightWallGrossBoundaryAndOpenings(
                    straightBoundary, location, wallWidthFt, wallBounds,
                    out _, out var holes, out _)
                || directHost.Geometry?.Faces is not
                    { Count: > 0 } sourceFaces
                || directHost.Geometry.BrepSolids is not
                    { Count: > 0 } sourceSolids)
                return false;

            const double MachineEpsilon = 2.2204460492503131e-16;
            double sourceScale = sourceFaces
                .SelectMany(face => (face.OuterVertices ?? [])
                    .Concat((face.InnerVertices ?? [])
                        .SelectMany(ring => ring)))
                .Where(point => point.Length >= 3)
                .SelectMany(point => point.Take(3))
                .Where(double.IsFinite)
                .Select(Math.Abs)
                .DefaultIfEmpty(1.0)
                .Max();
            double scale = Math.Max(1.0,
                Math.Max(sourceScale, values.Select(Math.Abs).Max()));
            double roundoff = 8192 * MachineEpsilon * scale;
            bool Same(double first, double second) =>
                Math.Abs(first - second) <= roundoff;
            if (!Same(candidateCommonOpening.WidthFt, outerWidth)
                || !Same(candidateCommonOpening.HeightFt, outerHeight)
                || !(outerWidth > innerWidth + roundoff)
                || !(outerHeight > innerHeight + roundoff))
                return false;

            double candidateCentreAlong =
                candidateCommonOpening.CentreXFt * axisX
                + candidateCommonOpening.CentreYFt * axisY;
            var matchingInnerHoles = holes.Where(hole =>
                    Same(hole.WidthFt, innerWidth)
                    && Same(hole.HeightFt, innerHeight)
                    && ExactWallHoleCanBelongToCommonOpening(
                        candidateCommonOpening, hole))
                .ToList();
            if (matchingInnerHoles.Count != 1)
                return false;
            var innerHole = matchingInnerHoles[0];
            double holeAxisLength = Math.Sqrt(
                innerHole.AxisX * innerHole.AxisX
                + innerHole.AxisY * innerHole.AxisY);
            if (!(holeAxisLength > 0) || !double.IsFinite(holeAxisLength))
                return false;
            double holeAxisX = innerHole.AxisX / holeAxisLength;
            double holeAxisY = innerHole.AxisY / holeAxisLength;
            double holeNormalX = -holeAxisY;
            double holeNormalY = holeAxisX;
            double holeCentreAlong =
                innerHole.CentreXFt * holeAxisX
                + innerHole.CentreYFt * holeAxisY;
            if (!Same(holeCentreAlong, candidateCentreAlong)
                || !Same(innerHole.BaseZFt,
                    candidateCommonOpening.BaseZFt))
                return false;
            double ProjectNormal(double holeNormal)
            {
                double x = holeCentreAlong * holeAxisX
                    + holeNormal * holeNormalX;
                double y = holeCentreAlong * holeAxisY
                    + holeNormal * holeNormalY;
                return x * normalX + y * normalY;
            }
            double firstInnerNormal =
                ProjectNormal(innerHole.NormalMinimumFt);
            double secondInnerNormal =
                ProjectNormal(innerHole.NormalMaximumFt);
            double innerMinimumNormal =
                Math.Min(firstInnerNormal, secondInnerNormal);
            double innerMaximumNormal =
                Math.Max(firstInnerNormal, secondInnerNormal);
            if (!(innerMaximumNormal
                > innerMinimumNormal + roundoff))
                return false;

            bool TryGetExactOuterRing(
                IReadOnlyList<double[]> ring,
                out double plane)
            {
                plane = double.NaN;
                if (ring.Count != 4
                    || ring.Any(point => point.Length < 3
                        || !double.IsFinite(point[0])
                        || !double.IsFinite(point[1])
                        || !double.IsFinite(point[2])))
                    return false;
                var projected = ring.Select(point => (
                    Along: point[0] * axisX + point[1] * axisY,
                    Plane: point[0] * normalX + point[1] * normalY,
                    Z: point[2])).ToList();
                double minimumAlong =
                    projected.Min(value => value.Along);
                double maximumAlong =
                    projected.Max(value => value.Along);
                double minimumPlane =
                    projected.Min(value => value.Plane);
                double maximumPlane =
                    projected.Max(value => value.Plane);
                double minimumZ = projected.Min(value => value.Z);
                double maximumZ = projected.Max(value => value.Z);
                if (!Same(minimumPlane, maximumPlane)
                    || !Same(maximumAlong - minimumAlong, outerWidth)
                    || !Same(maximumZ - minimumZ, outerHeight)
                    || !Same((minimumAlong + maximumAlong) / 2,
                        candidateCentreAlong)
                    || !Same(minimumZ,
                        candidateCommonOpening.BaseZFt))
                    return false;
                var corners = projected.Select(value => (
                        Along: Same(value.Along, minimumAlong) ? -1
                            : Same(value.Along, maximumAlong) ? 1 : 0,
                        Z: Same(value.Z, minimumZ) ? -1
                            : Same(value.Z, maximumZ) ? 1 : 0))
                    .ToList();
                if (corners.Any(corner =>
                        corner.Along == 0 || corner.Z == 0)
                    || corners.Distinct().Count() != 4)
                    return false;
                plane = (minimumPlane + maximumPlane) / 2;
                return true;
            }

            var outerProfileSolids =
                new List<(double Minimum, double Maximum)>();
            foreach (var solid in sourceSolids)
            {
                var faceIndices = solid.FaceIndices.Distinct()
                    .Order().ToList();
                if (!solid.IsClosed
                    || faceIndices.Count != solid.FaceIndices.Count
                    || faceIndices.Count < 6
                    || faceIndices.Any(index =>
                        index < 0 || index >= sourceFaces.Count)
                    || !TryOrientExactFacetedShell(
                        sourceFaces, faceIndices, out _,
                        triangulateNonPlanarFaces: false))
                    continue;
                var innerRings = faceIndices
                    .SelectMany(index =>
                        sourceFaces[index].InnerVertices ?? [])
                    .ToList();
                if (innerRings.Count != 2)
                    continue;
                var planes = new List<double>();
                foreach (var ring in innerRings)
                {
                    if (!TryGetExactOuterRing(ring, out double plane))
                    {
                        planes.Clear();
                        break;
                    }
                    planes.Add(plane);
                }
                if (planes.Count == 2
                    && Math.Abs(planes[1] - planes[0]) > roundoff)
                    outerProfileSolids.Add((
                        planes.Min(), planes.Max()));
            }
            if (outerProfileSolids.Count != 1)
                return false;
            var outerProfiles = outerProfileSolids[0];
            double validationMinimum = Math.Min(
                innerMinimumNormal, outerProfiles.Minimum);
            double validationMaximum = Math.Max(
                innerMaximumNormal, outerProfiles.Maximum);
            double minimumEndGap =
                innerMinimumNormal - validationMinimum;
            double maximumEndGap =
                validationMaximum - innerMaximumNormal;
            if (!(validationMaximum > validationMinimum + roundoff)
                || minimumEndGap < -roundoff
                || maximumEndGap < -roundoff
                || Same(minimumEndGap, maximumEndGap))
                return false;
            bool innerAtMinimum =
                minimumEndGap < maximumEndGap;
            double breakpoint = innerAtMinimum
                ? innerMaximumNormal : innerMinimumNormal;
            bool InSegment(double minimum, double maximum,
                double segmentMinimum, double segmentMaximum) =>
                minimum >= segmentMinimum - roundoff
                && maximum <= segmentMaximum + roundoff;
            var candidates = new List<HostedOpeningGeometry>();
            foreach (var depths in new[]
                {
                    (Minimum: firstDepth, Maximum: secondDepth),
                    (Minimum: secondDepth, Maximum: firstDepth),
                }.Distinct())
            {
                double minimumNormal =
                    breakpoint - depths.Minimum;
                double maximumNormal =
                    breakpoint + depths.Maximum;
                bool innerInSegment = innerAtMinimum
                    ? InSegment(innerMinimumNormal, innerMaximumNormal,
                        minimumNormal, breakpoint)
                    : InSegment(innerMinimumNormal, innerMaximumNormal,
                        breakpoint, maximumNormal);
                bool outerInSegment = innerAtMinimum
                    ? InSegment(outerProfiles.Minimum,
                        outerProfiles.Maximum,
                        breakpoint, maximumNormal)
                    : InSegment(outerProfiles.Minimum,
                        outerProfiles.Maximum,
                        minimumNormal, breakpoint);
                if (!innerInSegment || !outerInSegment)
                    continue;
                double centreNormal =
                    (minimumNormal + maximumNormal) / 2;
                var exactOuterOpening =
                    candidateCommonOpening with
                    {
                        CentreXFt = candidateCentreAlong * axisX
                            + centreNormal * normalX,
                        CentreYFt = candidateCentreAlong * axisY
                            + centreNormal * normalY,
                        WidthFt = outerWidth,
                        DepthFt = depths.Minimum + depths.Maximum,
                        HeightFt = outerHeight,
                    };
                if (!TryBuildExactSteppedOpeningBoundary(
                        exactOuterOpening, innerWidth, innerHeight,
                        breakpoint, innerAtMinimum,
                        out var boundary))
                    continue;
                candidates.Add(exactOuterOpening with
                {
                    Boundary = boundary,
                    SteppedProfile = new ExactSteppedOpeningProfile(
                        innerWidth, innerHeight,
                        breakpoint, innerAtMinimum),
                });
            }
            if (candidates.Count == 0)
                return false;
            HostedOpeningGeometry uniqueCandidate = candidates[0];
            builtOpening = uniqueCandidate;
            return candidates.Skip(1).All(candidate =>
                SameSteppedOpening(uniqueCandidate, candidate));
        }
        bool TryBuildDirectNestedOpening(
            out HostedOpeningGeometry builtOpening)
        {
            builtOpening = default;
            var directHostIds = new[]
                {
                    hostedElement.HostId,
                    hostedElement.SerializedHostId,
                }
                .Where(id => id is > 0)
                .Distinct()
                .ToHashSet();
            var directHosts = candidateHostWalls
                .Where(host => directHostIds.Contains(host.Id))
                .ToList();
            if (directHosts.Count != 1
                || !candidateCommonOpening.ExactDepth
                || candidateCommonOpening.Boundary != null
                || candidateCommonOpening.IsFamilyCutLoop)
                return false;
            Element directHost = directHosts[0];
            if (directHost.CuttingElementIds is { Count: > 0 } cuttingIds
                && cuttingIds.Count(id => id == hostedElement.Id) != 1)
                return false;
            if (directHost.BoundingBox is not { Length: 6 } wallBounds
                || !wallBounds.All(double.IsFinite)
                || directHost.Location is not
                    { CurveType: "Line", ArcRadius: null } location
                || !TryGetSerializedWallWidthFeet(
                    directHost, out double wallWidthFt)
                || !TryBuildStraightWallBoundary(
                    directHost, out var straightBoundary)
                || !TryGetExactStraightWallGrossBoundaryAndOpenings(
                    straightBoundary, location, wallWidthFt, wallBounds,
                    out _, out var holes, out _))
                return false;
            var nestedHoles = holes.Where(hole =>
                    ExactWallHoleCanBelongToCommonOpening(
                        candidateCommonOpening, hole)
                    && hole.WidthFt < candidateCommonOpening.WidthFt
                    && hole.HeightFt < candidateCommonOpening.HeightFt)
                .ToList();
            if (nestedHoles.Count != 1
                || !TryGetExactAdditionalDepths(
                    out double innerDepth, out double outerDepth)
                || !TryGetExactInstanceFamilyLength(
                    "Проем_Наружный_Ширина",
                    requireWritable: false, out double nestedWidth)
                || !TryGetExactInstanceFamilyLength(
                    "Проем_Наружный_Высота",
                    requireWritable: false, out double nestedHeight)
                || !TryGetExactInstanceFamilyLength(
                    "Подоконник_Проем_Ширина",
                    requireWritable: false, out double outerWidth)
                || !TryGetExactInstanceFamilyLength(
                    "Четверть Сверху",
                    requireWritable: false, out double upperQuarter))
                return false;
            var hole = nestedHoles[0];
            double holeAxisLength = Math.Sqrt(
                hole.AxisX * hole.AxisX + hole.AxisY * hole.AxisY);
            if (!(holeAxisLength > 0) || !double.IsFinite(holeAxisLength))
                return false;
            double holeAxisX = hole.AxisX / holeAxisLength;
            double holeAxisY = hole.AxisY / holeAxisLength;
            double holeNormalX = -holeAxisY;
            double holeNormalY = holeAxisX;
            double holeCentreAlong =
                hole.CentreXFt * holeAxisX + hole.CentreYFt * holeAxisY;
            double ProjectNormal(double holeNormal)
            {
                double x = holeCentreAlong * holeAxisX
                    + holeNormal * holeNormalX;
                double y = holeCentreAlong * holeAxisY
                    + holeNormal * holeNormalY;
                return x * normalX + y * normalY;
            }
            double firstHoleNormal = ProjectNormal(hole.NormalMinimumFt);
            double secondHoleNormal = ProjectNormal(hole.NormalMaximumFt);
            double holeMinimumNormal =
                Math.Min(firstHoleNormal, secondHoleNormal);
            double holeMaximumNormal =
                Math.Max(firstHoleNormal, secondHoleNormal);
            double commonCentreNormal =
                candidateCommonOpening.CentreXFt * normalX
                + candidateCommonOpening.CentreYFt * normalY;
            double commonMinimumNormal = commonCentreNormal
                - candidateCommonOpening.DepthFt / 2;
            double commonMaximumNormal = commonCentreNormal
                + candidateCommonOpening.DepthFt / 2;
            var values = new[]
            {
                nestedWidth, nestedHeight, outerWidth, upperQuarter,
                innerDepth, outerDepth, hole.WidthFt, hole.HeightFt,
                commonMinimumNormal, commonMaximumNormal,
                holeMinimumNormal, holeMaximumNormal,
            };
            if (values.Any(value => !double.IsFinite(value)))
                return false;
            const double MachineEpsilon = 2.2204460492503131e-16;
            double scale = Math.Max(1.0, values.Select(Math.Abs).Max());
            double roundoff = 8192 * MachineEpsilon * scale;
            bool Same(double first, double second) =>
                Math.Abs(first - second) <= roundoff;
            if (!Same(hole.WidthFt, nestedWidth)
                || !Same(hole.HeightFt, nestedHeight)
                || !Same(candidateCommonOpening.WidthFt, outerWidth)
                || !Same(candidateCommonOpening.HeightFt,
                    nestedHeight + upperQuarter)
                || !Same(candidateCommonOpening.DepthFt,
                    innerDepth + outerDepth))
                return false;
            bool InSegment(double minimum, double maximum) =>
                holeMinimumNormal >= minimum - roundoff
                && holeMaximumNormal <= maximum + roundoff;
            var orientations = new List<(double Breakpoint, bool InnerAtMinimum)>();
            double minimumBreakpoint = commonMinimumNormal + outerDepth;
            if (InSegment(commonMinimumNormal, minimumBreakpoint))
                orientations.Add((minimumBreakpoint, true));
            double maximumBreakpoint = commonMaximumNormal - outerDepth;
            if (InSegment(maximumBreakpoint, commonMaximumNormal))
                orientations.Add((maximumBreakpoint, false));
            if (orientations.Count != 1)
                return false;
            var orientation = orientations[0];
            if (!TryBuildExactSteppedOpeningBoundary(
                    candidateCommonOpening, hole.WidthFt, hole.HeightFt,
                    orientation.Breakpoint, orientation.InnerAtMinimum,
                    out var boundary))
                return false;
            builtOpening = candidateCommonOpening with
            {
                Boundary = boundary,
                SteppedProfile = new ExactSteppedOpeningProfile(
                    hole.WidthFt, hole.HeightFt,
                    orientation.Breakpoint, orientation.InnerAtMinimum),
            };
            return true;
        }
        bool hasDirectNestedOpening = TryBuildDirectNestedOpening(
            out var directNestedOpening);
        bool hasDirectSteppedSideOpening =
            TryBuildDirectSteppedSideOpening(
                out var directSteppedSideOpening);
        bool hasDirectClosedOuterProfileOpening =
            TryBuildDirectClosedOuterProfileOpening(
                out var directClosedOuterProfileOpening);
        int directValidationCount =
            (hasDirectNestedOpening ? 1 : 0)
            + (hasDirectSteppedSideOpening ? 1 : 0)
            + (hasDirectClosedOuterProfileOpening ? 1 : 0);
        if (directValidationCount > 1)
        {
            if (diagnostics) Diagnose("ambiguous-direct-validations");
            return false;
        }
        bool hasDirectOpening = hasDirectNestedOpening
            || hasDirectSteppedSideOpening
            || hasDirectClosedOuterProfileOpening;
        HostedOpeningGeometry directOpening =
            hasDirectSteppedSideOpening
                ? directSteppedSideOpening
                : hasDirectClosedOuterProfileOpening
                    ? directClosedOuterProfileOpening
                    : directNestedOpening;
        string directOpeningStage = hasDirectSteppedSideOpening
            ? "direct-stepped-side"
            : hasDirectClosedOuterProfileOpening
                ? "direct-closed-outer-profile"
                : "direct-nested";
        if (authoredCutHostWalls.Count < 2)
        {
            if (hasDirectOpening)
            {
                opening = directOpening;
                if (diagnostics) Diagnose(directOpeningStage);
                return true;
            }
            if (diagnostics) Diagnose("authored-host-count");
            return false;
        }
        bool TryBuildForHosts(IReadOnlyList<Element> hosts,
            bool useValidationNormalEnvelope,
            out HostedOpeningGeometry builtOpening)
        {
            builtOpening = default;
            if (!useValidationNormalEnvelope
                && (candidateCommonOpening.IsExactSerializedDefinition
                    || candidateCommonOpening
                        .IsExactAuthoredMultiHostEnvelope)
                && TryBuildExactSteppedMultiHostOpeningGeometry(
                    hostedElement, hostedType, hostedBbox,
                    hosts, candidateCommonOpening,
                    out builtOpening))
                return true;
            if (!TryBuildCommonHostedOpeningGeometry(
                    hostedElement, hostedBbox, hosts,
                    out var authoredHostEnvelope))
                return false;
            double centreAlong =
                candidateCommonOpening.CentreXFt * axisX
                + candidateCommonOpening.CentreYFt * axisY;
            if (useValidationNormalEnvelope)
            {
                if (!TryGetValidationNormalEnvelope(
                        hosts, out double minimumNormal,
                        out double maximumNormal,
                        out double breakpointNormal))
                    return false;
                if (!TryGetExactAdditionalDepths(
                        out double innerDepth,
                        out double outerDepth))
                    return false;
                var additionalDepths = new[] { innerDepth, outerDepth }
                    .Order()
                    .ToList();

                double bodyCentreNormal =
                    authoredHostEnvelope.CentreXFt * normalX
                    + authoredHostEnvelope.CentreYFt * normalY;
                double bodyMinimumNormal =
                    bodyCentreNormal - authoredHostEnvelope.DepthFt / 2;
                double bodyMaximumNormal =
                    bodyCentreNormal + authoredHostEnvelope.DepthFt / 2;
                var normalValues = new[]
                {
                    minimumNormal, maximumNormal, breakpointNormal,
                    bodyMinimumNormal, bodyMaximumNormal,
                };
                if (normalValues.Any(value => !double.IsFinite(value)))
                    return false;
                const double MachineEpsilon = 2.2204460492503131e-16;
                double scale = Math.Max(
                    1.0, normalValues.Select(Math.Abs).Max());
                double roundoff = 8192 * MachineEpsilon * scale;
                double minimumValidationDepth =
                    breakpointNormal - minimumNormal;
                double maximumValidationDepth =
                    maximumNormal - breakpointNormal;
                double minimumBodyDepth =
                    breakpointNormal - bodyMinimumNormal;
                double maximumBodyDepth =
                    bodyMaximumNormal - breakpointNormal;
                double minimumUnconfirmedDepth =
                    minimumBodyDepth - minimumValidationDepth;
                double maximumUnconfirmedDepth =
                    maximumBodyDepth - maximumValidationDepth;
                double completeAdditionalDepth =
                    additionalDepths.Sum();
                if (minimumUnconfirmedDepth < -roundoff
                    || maximumUnconfirmedDepth < -roundoff
                    || minimumUnconfirmedDepth + maximumUnconfirmedDepth
                        <= completeAdditionalDepth + roundoff)
                    return false;
                var minimumDepths = additionalDepths.Where(value =>
                        value >= minimumValidationDepth - roundoff
                        && value <= minimumBodyDepth + roundoff)
                    .ToList();
                var maximumDepths = additionalDepths.Where(value =>
                        value >= maximumValidationDepth - roundoff
                        && value <= maximumBodyDepth + roundoff)
                    .ToList();
                if (diagnostics)
                    Diagnose($"serialized-envelope "
                        + $"hosts={string.Join(',', hosts.Select(
                            host => host.Id))} "
                        + $"validation={minimumValidationDepth:G17},"
                        + $"{maximumValidationDepth:G17} "
                        + $"body={minimumBodyDepth:G17},"
                        + $"{maximumBodyDepth:G17} "
                        + $"minimum=[{string.Join(',', minimumDepths.Select(
                            value => value.ToString("G17",
                                CultureInfo.InvariantCulture)))}] "
                        + $"maximum=[{string.Join(',', maximumDepths.Select(
                            value => value.ToString("G17",
                                CultureInfo.InvariantCulture)))}]");
                var expandedOpenings = new List<HostedOpeningGeometry>();
                foreach (double minimumDepth in minimumDepths)
                foreach (double maximumDepth in maximumDepths)
                {
                    double expandedMinimumNormal =
                        breakpointNormal - minimumDepth;
                    double expandedMaximumNormal =
                        breakpointNormal + maximumDepth;
                    double expandedCentreNormal =
                        (expandedMinimumNormal + expandedMaximumNormal) / 2;
                    var expandedCommonOpening =
                        candidateCommonOpening with
                        {
                            CentreXFt = centreAlong * axisX
                                + expandedCentreNormal * normalX,
                            CentreYFt = centreAlong * axisY
                                + expandedCentreNormal * normalY,
                            DepthFt = minimumDepth + maximumDepth,
                            IsFamilyCutLoop = false,
                        };
                    if (TryBuildExactSteppedMultiHostOpeningGeometry(
                            hostedElement, hostedType, hostedBbox,
                            hosts, expandedCommonOpening,
                            out var expandedOpening))
                        expandedOpenings.Add(expandedOpening);
                }
                if (expandedOpenings.Count == 0)
                    return false;
                HostedOpeningGeometry uniqueExpanded =
                    expandedOpenings[0];
                if (expandedOpenings.Skip(1).Any(candidate =>
                        !SameSteppedOpening(
                            uniqueExpanded, candidate)))
                    return false;
                builtOpening = uniqueExpanded;
                return true;
            }
            double centreNormal =
                authoredHostEnvelope.CentreXFt * normalX
                + authoredHostEnvelope.CentreYFt * normalY;
            double depth = authoredHostEnvelope.DepthFt;
            var authoredCommonOpening = candidateCommonOpening with
            {
                CentreXFt = centreAlong * axisX + centreNormal * normalX,
                CentreYFt = centreAlong * axisY + centreNormal * normalY,
                DepthFt = depth,
                IsFamilyCutLoop = false,
                IsExactSerializedDefinition = false,
                IsExactAuthoredMultiHostEnvelope = true,
            };
            bool result = TryBuildExactSteppedMultiHostOpeningGeometry(
                hostedElement, hostedType, hostedBbox,
                hosts, authoredCommonOpening, out builtOpening);
            if (diagnostics)
                Diagnose($"primitive result={result} "
                    + $"hosts={string.Join(',', hosts.Select(host => host.Id))} "
                    + $"envelope={(useValidationNormalEnvelope ? "validation" : "body")} "
                    + $"candidate={candidateCommonOpening.WidthFt:G17}x"
                    + $"{candidateCommonOpening.HeightFt:G17}x"
                    + $"{candidateCommonOpening.DepthFt:G17} "
                    + $"authoredDepth={authoredCommonOpening.DepthFt:G17}");
            return result;
        }
        if (TryBuildForHosts(
                authoredCutHostWalls, useValidationNormalEnvelope: false,
                out opening))
        {
            if (diagnostics) Diagnose("full-host-set");
            return true;
        }
        // Two authored hosts have no proper subset of size two.
        if (TryBuildForHosts(
                authoredCutHostWalls, useValidationNormalEnvelope: true,
                out opening))
        {
            if (diagnostics) Diagnose("full-host-validation-envelope");
            return true;
        }

        // The complete inverse cut-set can contain another coordinated wall system which the same
        // family instance also cuts.
        const int MaximumExhaustiveHostCount = 6;
        if (authoredCutHostWalls.Count > MaximumExhaustiveHostCount)
        {
            if (hasDirectOpening)
            {
                opening = directOpening;
                if (diagnostics) Diagnose(directOpeningStage);
                return true;
            }
            if (diagnostics) Diagnose("subset-limit");
            return false;
        }
        var accepted = new List<(HostedOpeningGeometry Opening,
            IReadOnlyList<Element> Hosts)>();
        int fullMask = (1 << authoredCutHostWalls.Count) - 1;
        for (int mask = 1; mask < fullMask; mask++)
        {
            if (System.Numerics.BitOperations.PopCount((uint)mask) < 2)
                continue;
            var subset = authoredCutHostWalls
                .Where((_, index) => (mask & (1 << index)) != 0)
                .ToList();
            if (TryBuildForHosts(
                    subset, useValidationNormalEnvelope: false,
                    out var subsetOpening)
                || TryBuildForHosts(
                    subset, useValidationNormalEnvelope: true,
                    out subsetOpening))
                accepted.Add((subsetOpening, subset));
        }
        if (accepted.Count == 0)
        {
            if (hasDirectOpening)
            {
                opening = directOpening;
                if (diagnostics) Diagnose(directOpeningStage);
                return true;
            }
            if (diagnostics) Diagnose("no-authored-subset");
            return false;
        }
        static bool SameSteppedOpening(
            HostedOpeningGeometry first, HostedOpeningGeometry second)
        {
            if (first.SteppedProfile is not { } firstStep
                || second.SteppedProfile is not { } secondStep
                || firstStep.InnerAtMinimum != secondStep.InnerAtMinimum)
                return false;
            var firstValues = new[]
            {
                first.CentreXFt, first.CentreYFt, first.AxisX, first.AxisY,
                first.WidthFt, first.DepthFt, first.BaseZFt, first.HeightFt,
                firstStep.InnerWidthFt, firstStep.InnerHeightFt,
                firstStep.BreakpointNormalFt,
            };
            var secondValues = new[]
            {
                second.CentreXFt, second.CentreYFt, second.AxisX, second.AxisY,
                second.WidthFt, second.DepthFt, second.BaseZFt, second.HeightFt,
                secondStep.InnerWidthFt, secondStep.InnerHeightFt,
                secondStep.BreakpointNormalFt,
            };
            if (firstValues.Concat(secondValues).Any(
                    value => !double.IsFinite(value)))
                return false;
            const double MachineEpsilon = 2.2204460492503131e-16;
            double scale = Math.Max(1.0,
                firstValues.Concat(secondValues).Select(Math.Abs).Max());
            double roundoff = 8192 * MachineEpsilon * scale;
            return firstValues.Zip(secondValues)
                .All(pair => Math.Abs(pair.First - pair.Second) <= roundoff);
        }
        HostedOpeningGeometry uniqueOpening = accepted[0].Opening;
        if (accepted.Skip(1).Any(candidate =>
                !SameSteppedOpening(uniqueOpening, candidate.Opening)))
        {
            if (diagnostics)
                Diagnose($"ambiguous-subsets={string.Join('|', accepted.Select(
                    candidate => string.Join(',', candidate.Hosts.Select(
                        host => host.Id))))}");
            return false;
        }
        opening = uniqueOpening;
        if (diagnostics)
            Diagnose($"unique-subset={string.Join('|', accepted.Select(
                candidate => string.Join(',', candidate.Hosts.Select(
                    host => host.Id))))}");
        return true;
    }

    /// <summary>
    /// Recovers one exact stepped operand when a complete resolved host graph contains more than
    /// one wall direction and therefore cannot itself define a common primitive.
    /// </summary>
    internal static bool
        TryBuildUniqueExactSteppedMultiHostOpeningFromAuthoredHostProfiles(
            Element hostedElement, Element? hostedType, double[] hostedBbox,
            IReadOnlyList<Element> candidateHostWalls,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        const int MaximumResolvedHostCount = 10;
        if (candidateHostWalls.Count is < 2 or > MaximumResolvedHostCount
            || candidateHostWalls.Select(host => host.Id).Distinct().Count()
                != candidateHostWalls.Count
            || hostedBbox.Length < 6
            || !TryGetSerializedPlanAxis(
                hostedElement, out double axisX, out double axisY))
            return false;

        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return false;
        axisX /= axisLength;
        axisY /= axisLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double directionRoundoff = 8192 * MachineEpsilon;
        var parallelHostWalls = candidateHostWalls.Where(host =>
        {
            if (host.Location is not
                { CurveType: "Line", ArcRadius: null } location
                || location.StartPoint is not { Length: >= 2 } start
                || location.EndPoint is not { Length: >= 2 } end)
                return false;
            double dx = end[0] - start[0];
            double dy = end[1] - start[1];
            double length = Math.Sqrt(dx * dx + dy * dy);
            if (!(length > 0) || !double.IsFinite(length))
                return false;
            double dot = dx / length * axisX + dy / length * axisY;
            return double.IsFinite(dot)
                && Math.Abs(Math.Abs(dot) - 1) <= directionRoundoff;
        }).ToList();
        if (parallelHostWalls.Count < 2)
            return false;

        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);
        var accepted = new List<(HostedOpeningGeometry Opening,
            Element Host)>();
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCSTEPPEDPROFILEGATE cutter={hostedElement.Id} "
                + "stage=parallel-hosts "
                + $"hosts={string.Join(',', parallelHostWalls.Select(
                    host => host.Id))}");
        double normalX = -axisY, normalY = axisX;
        double[] associationBox = BuildHostedOpeningAssociationBox(
            hostedElement, hostedBbox);
        var associationNormalCoordinates = new[]
        {
            associationBox[0] * normalX + associationBox[1] * normalY,
            associationBox[0] * normalX + associationBox[4] * normalY,
            associationBox[3] * normalX + associationBox[1] * normalY,
            associationBox[3] * normalX + associationBox[4] * normalY,
        };
        double associationMinimumNormal =
            associationNormalCoordinates.Min();
        double associationMaximumNormal =
            associationNormalCoordinates.Max();
        double associationScale = Math.Max(1.0,
            associationNormalCoordinates.Select(Math.Abs).Max());
        double associationRoundoff =
            8192 * MachineEpsilon * associationScale;
        bool TryGetExactInstanceFamilyLength(
            string name, bool requireWritable, out double value)
        {
            var parameters = hostedElement.Parameters
                .Where(parameter => parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && (!requireWritable || !parameter.IsReadOnly)
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue)
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true)
                .ToList();
            value = parameters.Count == 1
                ? (double)parameters[0].Value! : double.NaN;
            return parameters.Count == 1;
        }
        double firstAdditionalDepth = double.NaN;
        double secondAdditionalDepth = double.NaN;
        bool hasAdditionalDepths =
            TryGetExactInstanceFamilyLength(
                "Доп Глубина Внутренняя",
                requireWritable: false, out firstAdditionalDepth)
            && TryGetExactInstanceFamilyLength(
                "Доп Глубина Наружная",
                requireWritable: false, out secondAdditionalDepth)
            && firstAdditionalDepth != secondAdditionalDepth;
        var depthPairs = hasAdditionalDepths
            ? new[]
                {
                    (Minimum: firstAdditionalDepth,
                        Maximum: secondAdditionalDepth),
                    (Minimum: secondAdditionalDepth,
                        Maximum: firstAdditionalDepth),
                }.Distinct().ToList()
            : [];
        var validationHostWalls = parallelHostWalls
            .Where(host => host.CuttingElementIds?.Count(
                id => id == hostedElement.Id) == 1)
            .ToList();
        Element? primaryValidationHost = validationHostWalls.FirstOrDefault(host =>
                host.Id == hostedElement.SerializedHostId
                || host.Id == hostedElement.HostId)
            ?? validationHostWalls.FirstOrDefault();
        int primaryValidationIndex = primaryValidationHost == null
            ? -1 : validationHostWalls.IndexOf(primaryValidationHost);
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCSTEPPEDPROFILEGATE cutter={hostedElement.Id} "
                + $"stage=depth-validation available={hasAdditionalDepths} "
                + $"depths={firstAdditionalDepth:G17},"
                + $"{secondAdditionalDepth:G17} "
                + $"pairs={depthPairs.Count} "
                + $"decoded={string.Join(',', validationHostWalls.Select(
                    host => host.Id))}");
        foreach (var host in parallelHostWalls)
        {
            if (!TryBuildHostedOpeningBoundary(
                    host, associationBox, out var boundary)
                || !TryGetAuthoredHostedOpeningSpan(
                    host, boundary, out _, out double authoredWidth,
                    out double authoredBaseZ, out double authoredHeight))
                continue;
            var points = boundary.Faces
                .SelectMany(face => face.OuterVertices ?? [])
                .Where(point => point.Length >= 3
                    && double.IsFinite(point[0])
                    && double.IsFinite(point[1])
                    && double.IsFinite(point[2]))
                .ToList();
            if (points.Count < 8)
                continue;
            var along = points.Select(point =>
                point[0] * axisX + point[1] * axisY).ToList();
            var normal = points.Select(point =>
                point[0] * normalX + point[1] * normalY).ToList();
            var vertical = points.Select(point => point[2]).ToList();
            double minimumAlong = along.Min(), maximumAlong = along.Max();
            double minimumNormal = normal.Min(), maximumNormal = normal.Max();
            double minimumZ = vertical.Min(), maximumZ = vertical.Max();
            var values = new[]
            {
                minimumAlong, maximumAlong,
                minimumNormal, maximumNormal,
                minimumZ, maximumZ,
                authoredWidth, authoredBaseZ, authoredHeight,
            };
            if (values.Any(value => !double.IsFinite(value)))
                continue;
            double scale = Math.Max(
                1.0, values.Select(Math.Abs).Max());
            double roundoff = 8192 * MachineEpsilon * scale;
            double width = maximumAlong - minimumAlong;
            double depth = maximumNormal - minimumNormal;
            double height = maximumZ - minimumZ;
            if (!(width > 0.03)
                || !(depth > roundoff)
                || !(height > 0.03)
                || Math.Abs(width - authoredWidth) > roundoff
                || Math.Abs(minimumZ - authoredBaseZ) > roundoff
                || Math.Abs(height - authoredHeight) > roundoff)
                continue;
            double centreAlong = (minimumAlong + maximumAlong) / 2;
            double centreNormal =
                (minimumNormal + maximumNormal) / 2;
            var profile = new HostedOpeningGeometry(
                centreAlong * axisX + centreNormal * normalX,
                centreAlong * axisY + centreNormal * normalY,
                axisX, axisY, width, depth, minimumZ, height,
                ExactDepth: true);
            if (TryBuildExactQuarteredAdditionalDepthRevealOpening(
                    hostedElement, host, candidateHostWalls, profile,
                    out var exactQuarteredOpening))
            {
                accepted.Add((exactQuarteredOpening, host));
                continue;
            }
            if (!TryBuildExactSteppedMultiHostOpeningFromAuthoredCutHosts(
                    hostedElement, hostedType, hostedBbox,
                    parallelHostWalls, profile,
                    out var steppedOpening))
            {
                int sourceValidationIndex = validationHostWalls.IndexOf(host);
                if (depthPairs.Count == 0
                    || validationHostWalls.Count is < 2 or > 6
                    || primaryValidationIndex < 0
                    || sourceValidationIndex < 0)
                    continue;
                double profileCentreAlong =
                    profile.CentreXFt * axisX + profile.CentreYFt * axisY;
                int fullMask = (1 << validationHostWalls.Count) - 1;
                foreach (double breakpoint in new[]
                    {
                        minimumNormal, maximumNormal,
                    }.Distinct())
                foreach (var depths in depthPairs)
                for (int mask = 1; mask <= fullMask; mask++)
                {
                    if ((mask & (1 << primaryValidationIndex)) == 0
                        || (mask & (1 << sourceValidationIndex)) == 0
                        || System.Numerics.BitOperations.PopCount(
                            (uint)mask) < 2)
                        continue;
                    double expandedMinimumNormal =
                        breakpoint - depths.Minimum;
                    double expandedMaximumNormal =
                        breakpoint + depths.Maximum;
                    if (expandedMinimumNormal
                            < associationMinimumNormal
                                - associationRoundoff
                        || expandedMaximumNormal
                            > associationMaximumNormal
                                + associationRoundoff)
                        continue;
                    double expandedCentreNormal =
                        (expandedMinimumNormal
                            + expandedMaximumNormal) / 2;
                    var expandedProfile = profile with
                    {
                        CentreXFt = profileCentreAlong * axisX
                            + expandedCentreNormal * normalX,
                        CentreYFt = profileCentreAlong * axisY
                            + expandedCentreNormal * normalY,
                        DepthFt = depths.Minimum + depths.Maximum,
                        IsFamilyCutLoop = false,
                    };
                    var subset = validationHostWalls
                        .Where((_, index) =>
                            (mask & (1 << index)) != 0)
                        .ToList();
                    if (TryBuildExactSteppedMultiHostOpeningGeometry(
                            hostedElement, hostedType, hostedBbox,
                            subset, expandedProfile,
                            out var expandedOpening))
                        accepted.Add((expandedOpening, host));
                }
                continue;
            }
            accepted.Add((steppedOpening, host));
        }
        if (accepted.Count == 0)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCSTEPPEDPROFILEGATE cutter={hostedElement.Id} "
                    + "stage=no-validation");
            return false;
        }

        HostedOpeningGeometry unique = accepted[0].Opening;
        if (accepted.Skip(1).Any(candidate =>
                !SameExactSteppedOpening(unique, candidate.Opening)))
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCSTEPPEDPROFILEGATE cutter={hostedElement.Id} "
                    + "stage=ambiguous "
                    + $"hosts={string.Join(',', accepted.Select(
                        candidate => candidate.Host.Id))}");
            return false;
        }
        opening = unique;
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCSTEPPEDPROFILEGATE cutter={hostedElement.Id} "
                + "stage=accept "
                + $"hosts={string.Join(',', accepted.Select(
                    candidate => candidate.Host.Id))}");
        return true;

        static bool SameExactSteppedOpening(
            HostedOpeningGeometry first, HostedOpeningGeometry second)
        {
            if (first.SteppedProfile is not { } firstStep
                || second.SteppedProfile is not { } secondStep
                || firstStep.InnerAtMinimum != secondStep.InnerAtMinimum)
                return false;
            var firstValues = new[]
            {
                first.CentreXFt, first.CentreYFt, first.AxisX, first.AxisY,
                first.WidthFt, first.DepthFt, first.BaseZFt, first.HeightFt,
                firstStep.InnerWidthFt, firstStep.InnerHeightFt,
                firstStep.BreakpointNormalFt,
            };
            var secondValues = new[]
            {
                second.CentreXFt, second.CentreYFt,
                second.AxisX, second.AxisY,
                second.WidthFt, second.DepthFt,
                second.BaseZFt, second.HeightFt,
                secondStep.InnerWidthFt, secondStep.InnerHeightFt,
                secondStep.BreakpointNormalFt,
            };
            if (firstValues.Concat(secondValues).Any(
                    value => !double.IsFinite(value)))
                return false;
            const double MachineEpsilon = 2.2204460492503131e-16;
            double scale = Math.Max(1.0,
                firstValues.Concat(secondValues).Select(Math.Abs).Max());
            double roundoff = 8192 * MachineEpsilon * scale;
            return firstValues.Zip(secondValues).All(pair =>
                Math.Abs(pair.First - pair.Second) <= roundoff);
        }
    }

    /// <summary>
    /// Reconstructs a stepped cutter from three independent exact source contracts: nested
    /// rectangular wall-side profiles, a normal span repeated by at least two resolved wall shells,
    /// and the unique mapped-family normal endpoint carrying an inner-loop face.
    /// </summary>
    internal static bool
        TryBuildExactSteppedOpeningFromSourceWallProfilesAndMappedBreakpoint(
            Element hostedElement, IReadOnlyList<Element> candidateHostWalls,
            out HostedOpeningGeometry opening)
    {
        opening = default;
        if (candidateHostWalls.Count < 2
            || hostedElement.Geometry is not
                { Faces.Count: > 0 } mappedGeometry
            || mappedGeometry.ExactMappedInstances is not { Count: 1 }
            || !TryGetSerializedInstanceTransform(
                hostedElement, out var transform)
            || transform.BasisX.Length < 3
            || transform.BasisY.Length < 3)
            return false;

        var relatedHostIds = new[]
            {
                hostedElement.HostId,
                hostedElement.SerializedHostId,
            }
            .Concat(hostedElement.ExtraHostIds?.Select(id => (int?)id)
                ?? [])
            .Concat(hostedElement.ExplicitHostIds?.Select(id => (int?)id)
                ?? [])
            .Where(id => id is > 0)
            .Select(id => id!.Value)
            .ToHashSet();
        bool hasForwardRelation = candidateHostWalls.Any(
            host => relatedHostIds.Contains(host.Id));
        bool hasInverseRelation = candidateHostWalls.Any(host =>
            host.CuttingElementIds?.Count(
                id => id == hostedElement.Id) == 1);
        if (!hasForwardRelation && !hasInverseRelation)
            return false;

        double axisLength = Math.Sqrt(
            transform.BasisX[0] * transform.BasisX[0]
            + transform.BasisX[1] * transform.BasisX[1]);
        double basisNormalLength = Math.Sqrt(
            transform.BasisY[0] * transform.BasisY[0]
            + transform.BasisY[1] * transform.BasisY[1]);
        if (!(axisLength > 0) || !double.IsFinite(axisLength)
            || !(basisNormalLength > 0)
            || !double.IsFinite(basisNormalLength))
            return false;
        double axisX = transform.BasisX[0] / axisLength;
        double axisY = transform.BasisX[1] / axisLength;
        double normalX = -axisY, normalY = axisX;
        double serializedNormalX =
            transform.BasisY[0] / basisNormalLength;
        double serializedNormalY =
            transform.BasisY[1] / basisNormalLength;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double basisRoundoff = 8192 * MachineEpsilon;
        if (Math.Abs(transform.BasisX[2]) > basisRoundoff
            || Math.Abs(transform.BasisY[2]) > basisRoundoff
            || Math.Abs(serializedNormalX * normalX
                + serializedNormalY * normalY - 1) > basisRoundoff)
            return false;

        var mappedPoints = mappedGeometry.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .ToList();
        if (mappedPoints.Count == 0
            || mappedGeometry.Faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 })
            || mappedPoints.Any(point => point.Length < 3
                || !double.IsFinite(point[0])
                || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;
        var sourcePoints = candidateHostWalls
            .SelectMany(host => host.Geometry?.Faces ?? [])
            .SelectMany(face => (face.OuterVertices ?? [])
                .Concat((face.InnerVertices ?? [])
                    .SelectMany(ring => ring)))
            .Where(point => point.Length >= 3
                && point.Take(3).All(double.IsFinite))
            .ToList();
        double scale = Math.Max(1.0,
            mappedPoints.Concat(sourcePoints)
                .SelectMany(point => point.Take(3))
                .Select(Math.Abs).DefaultIfEmpty(1.0).Max());
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        double ProjectAlong(IReadOnlyList<double> point) =>
            point[0] * axisX + point[1] * axisY;
        double ProjectNormal(IReadOnlyList<double> point) =>
            point[0] * normalX + point[1] * normalY;

        var mappedNormals = mappedPoints.Select(ProjectNormal).ToList();
        double mappedMinimumNormal = mappedNormals.Min();
        double mappedMaximumNormal = mappedNormals.Max();
        bool EndpointCarriesInnerLoopFace(double endpoint)
        {
            return mappedGeometry.Faces.Any(face =>
            {
                if (face.OuterVertices is not { Count: >= 3 } outer
                    || face.InnerVertices is not { Count: > 0 } inner
                    || inner.Any(ring => ring.Count < 3
                        || ring.Any(point => point.Length < 3
                            || !double.IsFinite(point[0])
                            || !double.IsFinite(point[1])
                            || !double.IsFinite(point[2]))))
                    return false;
                var normalValues =
                    outer.Select(ProjectNormal).ToList();
                return Same(normalValues.Min(), endpoint)
                    && Same(normalValues.Max(), endpoint);
            });
        }
        bool minimumCarriesInnerLoop =
            EndpointCarriesInnerLoopFace(mappedMinimumNormal);
        bool maximumCarriesInnerLoop =
            EndpointCarriesInnerLoopFace(mappedMaximumNormal);
        if (minimumCarriesInnerLoop == maximumCarriesInnerLoop)
            return false;
        double breakpoint = minimumCarriesInnerLoop
            ? mappedMinimumNormal : mappedMaximumNormal;

        bool TryGetRectangularProfile(IReadOnlyList<double[]> ring,
            out (double CentreAlong, double Width, double BaseZ,
                double Height, double Plane) profile)
        {
            profile = default;
            if (ring.Count != 4
                || ring.Any(point => point.Length < 3
                    || !double.IsFinite(point[0])
                    || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2])))
                return false;
            var projected = ring.Select(point => (
                Along: ProjectAlong(point),
                Normal: ProjectNormal(point),
                Z: point[2])).ToList();
            double minimumAlong =
                projected.Min(value => value.Along);
            double maximumAlong =
                projected.Max(value => value.Along);
            double minimumNormal =
                projected.Min(value => value.Normal);
            double maximumNormal =
                projected.Max(value => value.Normal);
            double minimumZ = projected.Min(value => value.Z);
            double maximumZ = projected.Max(value => value.Z);
            if (!Same(minimumNormal, maximumNormal)
                || !(maximumAlong > minimumAlong + roundoff)
                || !(maximumZ > minimumZ + roundoff))
                return false;
            var corners = projected.Select(value => (
                    Along: Same(value.Along, minimumAlong) ? -1
                        : Same(value.Along, maximumAlong) ? 1 : 0,
                    Vertical: Same(value.Z, minimumZ) ? -1
                        : Same(value.Z, maximumZ) ? 1 : 0))
                .ToList();
            if (corners.Any(corner =>
                    corner.Along == 0 || corner.Vertical == 0)
                || corners.Distinct().Count() != 4)
                return false;
            profile = (
                (minimumAlong + maximumAlong) / 2,
                maximumAlong - minimumAlong,
                minimumZ, maximumZ - minimumZ,
                (minimumNormal + maximumNormal) / 2);
            return true;
        }

        var profiles = candidateHostWalls
            .SelectMany(host => host.Geometry?.Faces ?? [])
            .SelectMany(face => face.InnerVertices ?? [])
            .Select(ring => TryGetRectangularProfile(
                    ring, out var profile)
                ? (Valid: true, Profile: profile)
                : (Valid: false, Profile: default))
            .Where(item => item.Valid)
            .Select(item => item.Profile)
            .ToList();
        var profileGroups = new List<(
            double CentreAlong, double Width, double BaseZ,
            double Height,
            List<(double CentreAlong, double Width, double BaseZ,
                double Height, double Plane)> Profiles)>();
        foreach (var profile in profiles)
        {
            var group = profileGroups.FirstOrDefault(candidate =>
                Same(candidate.CentreAlong, profile.CentreAlong)
                && Same(candidate.Width, profile.Width)
                && Same(candidate.BaseZ, profile.BaseZ)
                && Same(candidate.Height, profile.Height));
            if (group.Profiles != null)
            {
                group.Profiles.Add(profile);
                continue;
            }
            profileGroups.Add((
                profile.CentreAlong, profile.Width,
                profile.BaseZ, profile.Height, [profile]));
        }
        var nestedPairs = (
            from outer in profileGroups
            from inner in profileGroups
            where Same(outer.CentreAlong, inner.CentreAlong)
                && Same(outer.BaseZ, inner.BaseZ)
                && outer.Width > inner.Width + roundoff
                && outer.Height > inner.Height + roundoff
            select (Outer: outer, Inner: inner)).ToList();
        if (nestedPairs.Count != 1)
            return false;
        var nested = nestedPairs[0];

        bool ProfileOccursInSegment(
            List<(double CentreAlong, double Width, double BaseZ,
                double Height, double Plane)> group,
            double minimum, double maximum) =>
            group.Any(profile =>
                profile.Plane >= minimum - roundoff
                && profile.Plane <= maximum + roundoff);
        var candidates = new List<(
            int HostId, int SolidIndex,
            HostedOpeningGeometry Opening)>();
        foreach (var host in candidateHostWalls)
        {
            if (host.Geometry is not
                { Faces: { } hostFaces,
                    BrepSolids: { Count: > 0 } hostSolids })
                continue;
            for (int solidIndex = 0;
                 solidIndex < hostSolids.Count; solidIndex++)
            {
                var indices = hostSolids[solidIndex].FaceIndices;
                if (indices.Count < 4
                    || indices.Distinct().Count() != indices.Count
                    || indices.Any(index =>
                        index < 0 || index >= hostFaces.Count))
                    continue;
                var solidFaces = indices
                    .Select(index => hostFaces[index]).ToList();
                if (solidFaces.Any(face =>
                        face.OuterVertices is not { Count: >= 3 }))
                    continue;
                var points = solidFaces
                    .SelectMany(face => face.OuterVertices!)
                    .ToList();
                if (points.Any(point => point.Length < 3
                        || !double.IsFinite(point[0])
                        || !double.IsFinite(point[1])
                        || !double.IsFinite(point[2])))
                    continue;
                var normalValues =
                    points.Select(ProjectNormal).ToList();
                double minimumNormal = normalValues.Min();
                double maximumNormal = normalValues.Max();
                if (!(breakpoint > minimumNormal + roundoff)
                    || !(breakpoint < maximumNormal - roundoff))
                    continue;

                bool outerAtMinimum = ProfileOccursInSegment(
                        nested.Outer.Profiles,
                        minimumNormal, breakpoint)
                    && ProfileOccursInSegment(
                        nested.Inner.Profiles,
                        breakpoint, maximumNormal);
                bool innerAtMinimum = ProfileOccursInSegment(
                        nested.Inner.Profiles,
                        minimumNormal, breakpoint)
                    && ProfileOccursInSegment(
                        nested.Outer.Profiles,
                        breakpoint, maximumNormal);
                foreach (bool innerAtMinimumCandidate in new[]
                    {
                        false, true,
                    }.Where(value => value
                        ? innerAtMinimum : outerAtMinimum))
                {
                    double centreNormal =
                        (minimumNormal + maximumNormal) / 2;
                    var outerOpening = new HostedOpeningGeometry(
                        nested.Outer.CentreAlong * axisX
                            + centreNormal * normalX,
                        nested.Outer.CentreAlong * axisY
                            + centreNormal * normalY,
                        axisX, axisY,
                        nested.Outer.Width,
                        maximumNormal - minimumNormal,
                        nested.Outer.BaseZ,
                        nested.Outer.Height,
                        ExactDepth: true);
                    if (!TryBuildExactSteppedOpeningBoundary(
                            outerOpening, nested.Inner.Width,
                            nested.Inner.Height, breakpoint,
                            innerAtMinimumCandidate, out var boundary))
                        continue;
                    candidates.Add((host.Id, solidIndex,
                        outerOpening with
                        {
                            Boundary = boundary,
                            SteppedProfile =
                                new ExactSteppedOpeningProfile(
                                    nested.Inner.Width,
                                    nested.Inner.Height,
                                    breakpoint,
                                    innerAtMinimumCandidate),
                            IsExactSourceWallProfilesMappedBreakpoint = true,
                        }));
                }
            }
        }
        if (candidates.Select(candidate => candidate.HostId)
                .Distinct().Count() < 2)
            return false;

        bool SameOpening(
            HostedOpeningGeometry first,
            HostedOpeningGeometry second)
        {
            if (first.SteppedProfile is not { } firstStep
                || second.SteppedProfile is not { } secondStep
                || firstStep.InnerAtMinimum
                    != secondStep.InnerAtMinimum)
                return false;
            var firstValues = new[]
            {
                first.CentreXFt, first.CentreYFt,
                first.AxisX, first.AxisY,
                first.WidthFt, first.DepthFt,
                first.BaseZFt, first.HeightFt,
                firstStep.InnerWidthFt,
                firstStep.InnerHeightFt,
                firstStep.BreakpointNormalFt,
            };
            var secondValues = new[]
            {
                second.CentreXFt, second.CentreYFt,
                second.AxisX, second.AxisY,
                second.WidthFt, second.DepthFt,
                second.BaseZFt, second.HeightFt,
                secondStep.InnerWidthFt,
                secondStep.InnerHeightFt,
                secondStep.BreakpointNormalFt,
            };
            return firstValues.Zip(secondValues)
                .All(pair => Same(pair.First, pair.Second));
        }
        HostedOpeningGeometry uniqueOpening =
            candidates[0].Opening;
        if (candidates.Skip(1).Any(candidate =>
                !SameOpening(uniqueOpening, candidate.Opening)))
            return false;
        opening = uniqueOpening;
        return true;
    }

    /// <summary>
    /// Reconstructs the exact two-profile Boolean operand used by a coordinated family opening
    /// across several parallel wall-layer products.
    /// </summary>
    internal static bool TryBuildExactSteppedMultiHostOpeningGeometry(
        Element hostedElement, Element? hostedType, double[] hostedBbox,
        IReadOnlyList<Element> hostWalls, HostedOpeningGeometry commonOpening,
        out HostedOpeningGeometry opening)
    {
        opening = default;
        bool diagnostics = Environment.GetEnvironmentVariable(
                "RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id)
                    && id == hostedElement.Id);
        bool Reject(string stage)
        {
            if (diagnostics)
                DiagnosticSink.WriteLine(
                    $"IFCSTEPPEDMULTIGATE cutter={hostedElement.Id} "
                    + $"hosts={string.Join(',', hostWalls.Select(
                        host => host.Id))} stage={stage}");
            return false;
        }
        if (hostWalls.Count < 2 || hostedBbox.Length < 6
            || commonOpening.Boundary != null || commonOpening.IsFamilyCutLoop
            || !(commonOpening.WidthFt > 0.03)
            || !(commonOpening.DepthFt > 0)
            || !(commonOpening.HeightFt > 0.03))
            return Reject("preconditions");

        double axisLength = Math.Sqrt(
            commonOpening.AxisX * commonOpening.AxisX
            + commonOpening.AxisY * commonOpening.AxisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength))
            return Reject("axis");
        double axisX = commonOpening.AxisX / axisLength;
        double axisY = commonOpening.AxisY / axisLength;
        double normalX = -axisY, normalY = axisX;
        double commonCentreAlong =
            commonOpening.CentreXFt * axisX + commonOpening.CentreYFt * axisY;
        double commonCentreNormal =
            commonOpening.CentreXFt * normalX + commonOpening.CentreYFt * normalY;
        double commonMinimumNormal =
            commonCentreNormal - commonOpening.DepthFt / 2;
        double commonMaximumNormal =
            commonCentreNormal + commonOpening.DepthFt / 2;

        var dimensions = new[]
        {
            commonOpening.CentreXFt, commonOpening.CentreYFt,
            commonOpening.WidthFt, commonOpening.DepthFt,
            commonOpening.BaseZFt, commonOpening.HeightFt,
            commonMinimumNormal, commonMaximumNormal,
        };
        if (dimensions.Any(value => !double.IsFinite(value)))
            return false;
        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, dimensions.Select(Math.Abs).Max());
        double roundoff = 8192 * MachineEpsilon * scale;
        bool Same(double first, double second) =>
            Math.Abs(first - second) <= roundoff;
        bool ExactHoleMatchesProfileAtCommonOrigin(
            RectangularWallThroughOpening hole,
            double width, double height)
        {
            double holeAxisLength = Math.Sqrt(
                hole.AxisX * hole.AxisX + hole.AxisY * hole.AxisY);
            if (!(holeAxisLength > 0)
                || !double.IsFinite(holeAxisLength))
                return false;
            double holeAxisX = hole.AxisX / holeAxisLength;
            double holeAxisY = hole.AxisY / holeAxisLength;
            return Math.Abs(Math.Abs(
                    holeAxisX * axisX + holeAxisY * axisY) - 1)
                    <= roundoff
                && Same(hole.CentreXFt * axisX
                        + hole.CentreYFt * axisY,
                    commonCentreAlong)
                && Same(hole.BaseZFt, commonOpening.BaseZFt)
                && Same(hole.WidthFt, width)
                && Same(hole.HeightFt, height);
        }
        bool ExactHoleStrictlyEnclosesCommonProfile(
            RectangularWallThroughOpening hole) =>
            hole.WidthFt
                > commonOpening.WidthFt + roundoff
            && hole.HeightFt
                > commonOpening.HeightFt + roundoff
            && ExactHoleMatchesProfileAtCommonOrigin(
                hole, hole.WidthFt, hole.HeightFt);
        double[] associationBox = BuildHostedOpeningAssociationBox(
            hostedElement, hostedBbox);
        var validations = new List<(double CentreAlong, double Width,
            double BaseZ, double Height, double MinimumNormal,
            double MaximumNormal, bool ExactHole)>();
        foreach (var host in hostWalls)
        {
            int inverseCutCount = host.CuttingElementIds?.Count(
                id => id == hostedElement.Id) ?? 0;
            bool exactSerializedPrimaryHost =
                hostedElement.SerializedHostId is > 0
                && host.Id == hostedElement.SerializedHostId.Value;
            if (inverseCutCount != 1
                && !(inverseCutCount == 0
                    && exactSerializedPrimaryHost))
                return Reject($"cutting-set-{host.Id}");

            bool hasExactHole = false;
            RectangularWallThroughOpening exactHole = default;
            if (host.BoundingBox is { Length: 6 } wallBounds
                && wallBounds.All(double.IsFinite)
                && TryGetSerializedWallWidthFeet(host, out double wallWidthFt)
                && TryBuildStraightWallBoundary(host, out var straightBoundary)
                && TryGetExactStraightWallGrossBoundaryAndOpenings(
                    straightBoundary, host.Location!, wallWidthFt, wallBounds,
                out _, out var holes, out _))
            {
                var matchingHoles = holes
                    .Where(hole =>
                        ExactWallHoleCanBelongToCommonOpening(
                            commonOpening, hole)
                        || ExactHoleStrictlyEnclosesCommonProfile(
                            hole))
                    .ToList();
                if (matchingHoles.Count != 1)
                    return Reject(
                        $"matching-holes-{host.Id}-{matchingHoles.Count}-of-{holes.Count}");
                exactHole = matchingHoles[0];
                hasExactHole = true;
            }

            if (hasExactHole)
            {
                double holeAxisLength = Math.Sqrt(
                    exactHole.AxisX * exactHole.AxisX
                    + exactHole.AxisY * exactHole.AxisY);
                if (!(holeAxisLength > 0) || !double.IsFinite(holeAxisLength))
                    return Reject($"hole-axis-{host.Id}");
                double holeAxisX = exactHole.AxisX / holeAxisLength;
                double holeAxisY = exactHole.AxisY / holeAxisLength;
                if (Math.Abs(Math.Abs(holeAxisX * axisX + holeAxisY * axisY) - 1)
                    > roundoff)
                    return Reject($"hole-direction-{host.Id}");
                double holeNormalX = -holeAxisY, holeNormalY = holeAxisX;
                double holeCentreAlong =
                    exactHole.CentreXFt * holeAxisX
                    + exactHole.CentreYFt * holeAxisY;
                double ProjectNormal(double holeNormal)
                {
                    double x = holeCentreAlong * holeAxisX
                        + holeNormal * holeNormalX;
                    double y = holeCentreAlong * holeAxisY
                        + holeNormal * holeNormalY;
                    return x * normalX + y * normalY;
                }
                double firstNormal = ProjectNormal(exactHole.NormalMinimumFt);
                double secondNormal = ProjectNormal(exactHole.NormalMaximumFt);
                validations.Add((
                    exactHole.CentreXFt * axisX + exactHole.CentreYFt * axisY,
                    exactHole.WidthFt, exactHole.BaseZFt, exactHole.HeightFt,
                    Math.Min(firstNormal, secondNormal),
                    Math.Max(firstNormal, secondNormal), true));
                continue;
            }

            if (!TryBuildHostedOpeningBoundary(
                    host, associationBox, out var authoredBoundary)
                || !TryGetAuthoredHostedOpeningSpan(
                    host, authoredBoundary, out _, out _, out _, out _))
                return Reject($"authored-boundary-{host.Id}");
            var points = authoredBoundary.Faces
                .SelectMany(face => face.OuterVertices ?? [])
                .Where(point => point.Length >= 3
                    && double.IsFinite(point[0])
                    && double.IsFinite(point[1])
                    && double.IsFinite(point[2]))
                .ToList();
            if (points.Count < 8) return Reject($"authored-points-{host.Id}");
            var along = points
                .Select(point => point[0] * axisX + point[1] * axisY).ToList();
            var normal = points
                .Select(point => point[0] * normalX + point[1] * normalY).ToList();
            var vertical = points.Select(point => point[2]).ToList();
            validations.Add(((along.Min() + along.Max()) / 2,
                along.Max() - along.Min(), vertical.Min(),
                vertical.Max() - vertical.Min(), normal.Min(), normal.Max(), false));
        }
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCSTEPPEDMULTIGATE cutter={hostedElement.Id} "
                + $"hosts={string.Join(',', hostWalls.Select(host => host.Id))} "
                + "stage=validations "
                + string.Join('|', validations.Select(validation =>
                    $"{validation.Width:G17}x{validation.Height:G17}:"
                    + $"{validation.MinimumNormal:G17}..{validation.MaximumNormal:G17}:"
                    + (validation.ExactHole ? "hole" : "boundary"))));

        if (validations.Count != hostWalls.Count
            || validations.Any(validation =>
                validation.MinimumNormal < commonMinimumNormal - roundoff
                || validation.MaximumNormal > commonMaximumNormal + roundoff
                || validation.MaximumNormal - validation.MinimumNormal <= roundoff
                || !Same(validation.CentreAlong, commonCentreAlong)
                || !Same(validation.BaseZ, commonOpening.BaseZFt)))
            return Reject("validation-alignment");

        var commonProfileValidations = validations.Where(validation =>
                Same(validation.Width, commonOpening.WidthFt)
                && Same(validation.Height, commonOpening.HeightFt))
            .ToList();
        var nestedProfileValidations = validations.Where(validation =>
                validation.ExactHole
                && validation.Width < commonOpening.WidthFt - roundoff
                && validation.Height < commonOpening.HeightFt - roundoff)
            .ToList();
        var enclosingProfileValidations = validations.Where(validation =>
                validation.Width > commonOpening.WidthFt + roundoff
                && validation.Height > commonOpening.HeightFt + roundoff)
            .ToList();
        bool usesEnclosingOuterProfile =
            commonProfileValidations.Count > 0
            && nestedProfileValidations.Count == 0
            && enclosingProfileValidations.Count > 0
            && commonProfileValidations.Count
                + enclosingProfileValidations.Count == validations.Count;
        var outerValidations = usesEnclosingOuterProfile
            ? enclosingProfileValidations : commonProfileValidations;
        var innerValidations = usesEnclosingOuterProfile
            ? commonProfileValidations : nestedProfileValidations;
        if (outerValidations.Count == 0 || innerValidations.Count == 0
            || outerValidations.Count + innerValidations.Count != validations.Count)
            return Reject(
                $"profile-classification-outer-{outerValidations.Count}-inner-{innerValidations.Count}");
        double outerWidth = outerValidations[0].Width;
        double outerHeight = outerValidations[0].Height;
        if (outerValidations.Any(validation =>
                !Same(validation.Width, outerWidth)
                || !Same(validation.Height, outerHeight)))
            return Reject("outer-profile-consistency");
        double innerWidth = innerValidations[0].Width;
        double innerHeight = innerValidations[0].Height;
        if (innerValidations.Any(validation =>
                !Same(validation.Width, innerWidth)
                || !Same(validation.Height, innerHeight)))
            return Reject("inner-profile-consistency");

        double innerMinimumNormal =
            innerValidations.Min(validation => validation.MinimumNormal);
        double innerMaximumNormal =
            innerValidations.Max(validation => validation.MaximumNormal);
        double minimumEndGap =
            innerMinimumNormal - commonMinimumNormal;
        double maximumEndGap =
            commonMaximumNormal - innerMaximumNormal;
        if (minimumEndGap < -roundoff || maximumEndGap < -roundoff
            || Math.Abs(minimumEndGap - maximumEndGap) <= roundoff)
            return Reject("breakpoint-gaps");
        bool innerAtMinimum = minimumEndGap < maximumEndGap;
        double breakpoint = innerAtMinimum
            ? innerMaximumNormal : innerMinimumNormal;
        double minimumSegmentDepth = breakpoint - commonMinimumNormal;
        double maximumSegmentDepth = commonMaximumNormal - breakpoint;
        if (!(minimumSegmentDepth > roundoff)
            || !(maximumSegmentDepth > roundoff))
            return Reject("segment-depth");

        bool InSegment((double CentreAlong, double Width, double BaseZ,
                double Height, double MinimumNormal, double MaximumNormal,
                bool ExactHole) validation,
            double minimum, double maximum) =>
            validation.MinimumNormal >= minimum - roundoff
            && validation.MaximumNormal <= maximum + roundoff;
        double innerSegmentMinimum = innerAtMinimum
            ? commonMinimumNormal : breakpoint;
        double innerSegmentMaximum = innerAtMinimum
            ? breakpoint : commonMaximumNormal;
        double outerSegmentMinimum = innerAtMinimum
            ? breakpoint : commonMinimumNormal;
        double outerSegmentMaximum = innerAtMinimum
            ? commonMaximumNormal : breakpoint;
        if (innerValidations.Any(validation => !InSegment(
                validation, innerSegmentMinimum, innerSegmentMaximum))
            || outerValidations.Any(validation => !InSegment(
                validation, outerSegmentMinimum, outerSegmentMaximum)))
            return Reject("segment-containment");

        var serializedLengths = hostedElement.Parameters
            .Concat(hostedType?.Parameters ?? Enumerable.Empty<Parameter>())
            .Where(parameter => parameter.Value is double value
                && value > 0 && double.IsFinite(value)
                && parameter.SpecType?.Contains(
                    ":length", StringComparison.OrdinalIgnoreCase) == true)
            .Select(parameter => (double)parameter.Value!)
            .ToList();
        const string InnerAdditionalDepthName =
            "Доп Глубина Внутренняя";
        const string OuterAdditionalDepthName =
            "Доп Глубина Наружная";
        const string InnerWidthName =
            "Проем_Наружный_Ширина";
        const string InnerHeightName =
            "Проем_Наружный_Высота";
        const string OuterWidthName =
            "Подоконник_Проем_Ширина";
        const string UpperQuarterName =
            "Четверть Сверху";
        var directedDepthParameters = hostedElement.Parameters
            .Where(parameter =>
                parameter.Definition?.Name is
                    InnerAdditionalDepthName
                    or OuterAdditionalDepthName)
            .ToList();
        bool TryGetUniqueFamilyLength(
            string name, out double value)
        {
            var matches = hostedElement.Parameters
                .Where(parameter =>
                    parameter.Definition?.Name == name
                    && parameter.Id > 0
                    && parameter.Guid == null
                    && parameter.ForgeId?.StartsWith(
                        "autodesk.parameter.aec.revit.family:",
                        StringComparison.Ordinal) == true
                    && parameter.SpecType?.Contains(
                        ":length",
                        StringComparison.OrdinalIgnoreCase) == true
                    && parameter.Value is double parameterValue
                    && parameterValue > 0
                    && double.IsFinite(parameterValue))
                .Select(parameter => (double)parameter.Value!)
                .ToList();
            value = matches.Count == 1
                ? matches[0] : double.NaN;
            return matches.Count == 1;
        }
        double innerAdditionalDepth = double.NaN;
        double outerAdditionalDepth = double.NaN;
        bool hasDirectedDepthPair =
            TryGetUniqueFamilyLength(
                InnerAdditionalDepthName, out innerAdditionalDepth)
            && TryGetUniqueFamilyLength(
                OuterAdditionalDepthName, out outerAdditionalDepth)
            && !Same(innerAdditionalDepth, outerAdditionalDepth);
        bool directedProfilesMatch =
            TryGetUniqueFamilyLength(
                InnerWidthName, out double parameterizedInnerWidth)
            && TryGetUniqueFamilyLength(
                InnerHeightName, out double parameterizedInnerHeight)
            && TryGetUniqueFamilyLength(
                OuterWidthName, out double parameterizedOuterWidth)
            && TryGetUniqueFamilyLength(
                UpperQuarterName, out double parameterizedUpperQuarter)
            && Same(parameterizedInnerWidth, innerWidth)
            && Same(parameterizedInnerHeight, innerHeight)
            && Same(parameterizedOuterWidth, outerWidth)
            && Same(parameterizedInnerHeight + parameterizedUpperQuarter,
                outerHeight);
        int primaryHostId = hostedElement.SerializedHostId is > 0
            ? hostedElement.SerializedHostId.Value
            : hostedElement.HostId is > 0
                ? hostedElement.HostId.Value : -1;
        var primaryHosts = hostWalls
            .Where(host => host.Id == primaryHostId)
            .ToList();
        bool hasSourceVerifiedCalculatedInsertionMismatch =
            primaryHosts.Count == 1
            && TryGetSerializedWallWidthFeet(
                primaryHosts[0], out double primaryWallWidth)
            && TryGetUniqueFamilyLength(
                "Вставка окна", out double insertionDepth)
            && TryGetUniqueFamilyLength(
                "Вставка_Расчет", out double calculatedInsertionDepth)
            && Same(insertionDepth, primaryWallWidth)
            && !Same(calculatedInsertionDepth,
                insertionDepth
                + (innerAdditionalDepth + outerAdditionalDepth) / 2);
        double directedMinimumDepth = innerAtMinimum
            ? outerAdditionalDepth : innerAdditionalDepth;
        double directedMaximumDepth = innerAtMinimum
            ? innerAdditionalDepth : outerAdditionalDepth;
        bool directedDepthsMatch =
            hasDirectedDepthPair
            && Same(minimumSegmentDepth, directedMinimumDepth)
            && Same(maximumSegmentDepth, directedMaximumDepth);
        double directedMinimumNormal =
            breakpoint - directedMinimumDepth;
        double directedMaximumNormal =
            breakpoint + directedMaximumDepth;
        double directedInnerMinimum = innerAtMinimum
            ? directedMinimumNormal : breakpoint;
        double directedInnerMaximum = innerAtMinimum
            ? breakpoint : directedMaximumNormal;
        double directedOuterMinimum = innerAtMinimum
            ? breakpoint : directedMinimumNormal;
        double directedOuterMaximum = innerAtMinimum
            ? directedMaximumNormal : breakpoint;
        bool sourceVerifiedDirectedEnvelope =
            !directedDepthsMatch
            && hasDirectedDepthPair
            && directedProfilesMatch
            && hasSourceVerifiedCalculatedInsertionMismatch
            && (commonOpening.IsExactSerializedDefinition
                || commonOpening.IsExactAuthoredMultiHostEnvelope)
            && directedMinimumDepth > roundoff
            && directedMaximumDepth > roundoff
            && directedMinimumNormal
                >= commonMinimumNormal - roundoff
            && directedMaximumNormal
                <= commonMaximumNormal + roundoff
            && innerValidations.All(validation => InSegment(
                validation, directedInnerMinimum, directedInnerMaximum))
            && outerValidations.All(validation => InSegment(
                validation, directedOuterMinimum, directedOuterMaximum));
        bool genericSegmentDepthsMatch =
            serializedLengths.Any(value =>
                Math.Abs(value - minimumSegmentDepth) <= roundoff)
            && serializedLengths.Any(value =>
                Math.Abs(value - maximumSegmentDepth) <= roundoff);
        bool exactSerializedTotalDepthValidation =
            directedDepthParameters.Count == 0
            && usesEnclosingOuterProfile
            && (commonOpening.IsExactSerializedDefinition
                || commonOpening.IsExactAuthoredMultiHostEnvelope)
            && innerValidations.Any(validation => validation.ExactHole)
            && outerValidations.Any(validation => validation.ExactHole)
            && Same(commonOpening.DepthFt,
                minimumSegmentDepth + maximumSegmentDepth);
        if (!directedDepthsMatch
            && !genericSegmentDepthsMatch
            && !exactSerializedTotalDepthValidation
            && !sourceVerifiedDirectedEnvelope)
            return Reject(
                $"serialized-depths-{minimumSegmentDepth:G17}-"
                + $"{maximumSegmentDepth:G17}"
                + $"-directed-{directedDepthParameters.Count}-"
                + $"{hasDirectedDepthPair}-generic-"
                + $"{genericSegmentDepthsMatch}-serialized-"
                + $"{commonOpening.IsExactSerializedDefinition}-"
                + $"{commonOpening.IsExactAuthoredMultiHostEnvelope}-"
                + $"{usesEnclosingOuterProfile}-holes-"
                + $"{innerValidations.Count(validation => validation.ExactHole)}-"
                + $"{outerValidations.Count(validation => validation.ExactHole)}"
                + $"-profiles-{directedProfilesMatch}-"
                + "calculated-mismatch-"
                + $"{hasSourceVerifiedCalculatedInsertionMismatch}-"
                + $"contracted-{sourceVerifiedDirectedEnvelope}");

        HostedOpeningGeometry outerOpening =
            usesEnclosingOuterProfile
                ? commonOpening with
                {
                    WidthFt = outerWidth,
                    HeightFt = outerHeight,
                }
                : commonOpening;
        if (sourceVerifiedDirectedEnvelope)
        {
            double directedCentreNormal =
                (directedMinimumNormal + directedMaximumNormal) / 2;
            outerOpening = outerOpening with
            {
                CentreXFt = commonCentreAlong * axisX
                    + directedCentreNormal * normalX,
                CentreYFt = commonCentreAlong * axisY
                    + directedCentreNormal * normalY,
                DepthFt =
                    directedMaximumNormal - directedMinimumNormal,
                IsExactParameterizedReveal = true,
            };
        }
        if (!TryBuildExactSteppedOpeningBoundary(
                outerOpening, innerWidth, innerHeight,
                breakpoint, innerAtMinimum, out var steppedBoundary))
            return Reject("boundary");
        opening = outerOpening with
        {
            Boundary = steppedBoundary,
            SteppedProfile = new ExactSteppedOpeningProfile(
                innerWidth, innerHeight, breakpoint, innerAtMinimum),
        };
        if (diagnostics)
            DiagnosticSink.WriteLine(
                $"IFCSTEPPEDMULTIGATE cutter={hostedElement.Id} "
                + $"hosts={string.Join(',', hostWalls.Select(host => host.Id))} "
                + "stage=accept");
        return true;
    }

    /// <summary>
    /// Builds the closed ten-face union of two centred rectangular opening profiles which share
    /// their sill elevation and meet at one exact normal plane.
    /// </summary>
    internal static bool TryBuildExactSteppedOpeningBoundary(
        HostedOpeningGeometry outerOpening, double innerWidthFt,
        double innerHeightFt, double breakpointNormalFt,
        bool innerAtMinimum, out GeometryData boundary)
    {
        boundary = new GeometryData();
        double axisLength = Math.Sqrt(
            outerOpening.AxisX * outerOpening.AxisX
            + outerOpening.AxisY * outerOpening.AxisY);
        if (!(axisLength > 0) || !double.IsFinite(axisLength)
            || !(innerWidthFt > 0) || !(innerHeightFt > 0)
            || !(innerWidthFt < outerOpening.WidthFt)
            || !(innerHeightFt < outerOpening.HeightFt))
            return false;
        double axisX = outerOpening.AxisX / axisLength;
        double axisY = outerOpening.AxisY / axisLength;
        double normalX = -axisY, normalY = axisX;
        double centreAlong =
            outerOpening.CentreXFt * axisX + outerOpening.CentreYFt * axisY;
        double centreNormal =
            outerOpening.CentreXFt * normalX + outerOpening.CentreYFt * normalY;
        double minimumNormal = centreNormal - outerOpening.DepthFt / 2;
        double maximumNormal = centreNormal + outerOpening.DepthFt / 2;
        if (!double.IsFinite(breakpointNormalFt)
            || !(breakpointNormalFt > minimumNormal)
            || !(breakpointNormalFt < maximumNormal))
            return false;

        double innerEndNormal = innerAtMinimum
            ? minimumNormal : maximumNormal;
        double outerEndNormal = innerAtMinimum
            ? maximumNormal : minimumNormal;
        double outerMinimumAlong = centreAlong - outerOpening.WidthFt / 2;
        double outerMaximumAlong = centreAlong + outerOpening.WidthFt / 2;
        double innerMinimumAlong = centreAlong - innerWidthFt / 2;
        double innerMaximumAlong = centreAlong + innerWidthFt / 2;
        double baseZ = outerOpening.BaseZFt;
        double outerHeadZ = baseZ + outerOpening.HeightFt;
        double innerHeadZ = baseZ + innerHeightFt;
        double[] Point(double along, double normal, double z) =>
        [
            along * axisX + normal * normalX,
            along * axisY + normal * normalY,
            z,
        ];

        double[] iLb = Point(innerMinimumAlong, innerEndNormal, baseZ);
        double[] iLt = Point(innerMinimumAlong, innerEndNormal, innerHeadZ);
        double[] iRt = Point(innerMaximumAlong, innerEndNormal, innerHeadZ);
        double[] iRb = Point(innerMaximumAlong, innerEndNormal, baseZ);
        double[] biLb = Point(innerMinimumAlong, breakpointNormalFt, baseZ);
        double[] biLt = Point(innerMinimumAlong, breakpointNormalFt, innerHeadZ);
        double[] biRt = Point(innerMaximumAlong, breakpointNormalFt, innerHeadZ);
        double[] biRb = Point(innerMaximumAlong, breakpointNormalFt, baseZ);
        double[] boLb = Point(outerMinimumAlong, breakpointNormalFt, baseZ);
        double[] boLt = Point(outerMinimumAlong, breakpointNormalFt, outerHeadZ);
        double[] boRt = Point(outerMaximumAlong, breakpointNormalFt, outerHeadZ);
        double[] boRb = Point(outerMaximumAlong, breakpointNormalFt, baseZ);
        double[] oLb = Point(outerMinimumAlong, outerEndNormal, baseZ);
        double[] oLt = Point(outerMinimumAlong, outerEndNormal, outerHeadZ);
        double[] oRt = Point(outerMaximumAlong, outerEndNormal, outerHeadZ);
        double[] oRb = Point(outerMaximumAlong, outerEndNormal, baseZ);
        static GeoFace Face(params double[][] vertices) => new()
        {
            OuterVertices = vertices.ToList(),
        };
        var faces = new List<GeoFace>
        {
            Face(iLb, iRb, iRt, iLt),
            Face(oLb, oLt, oRt, oRb),
            Face(iLb, iLt, biLt, biLb),
            Face(iLt, iRt, biRt, biLt),
            Face(iRt, iRb, biRb, biRt),
            Face(boLb, boLt, oLt, oLb),
            Face(boLt, boRt, oRt, oLt),
            Face(boRt, boRb, oRb, oRt),
            Face(iLb, iRb, biRb, boRb, oRb, oLb, boLb, biLb),
            Face(boLb, boLt, boRt, boRb, biRb, biRt, biLt, biLb),
        };
        if (!TryOrientExactFacetedShell(
                faces, Enumerable.Range(0, faces.Count).ToList(),
                out var oriented, triangulateNonPlanarFaces: false))
            return false;
        var points = oriented.SelectMany(face => face.OuterVertices!).ToList();
        boundary = new GeometryData
        {
            BoundingBox =
            [
                points.Min(point => point[0]),
                points.Min(point => point[1]),
                points.Min(point => point[2]),
                points.Max(point => point[0]),
                points.Max(point => point[1]),
                points.Max(point => point[2]),
            ],
            Faces = oriented,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, oriented.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        return true;
    }

    private static double[] BuildHostedOpeningAssociationBox(
        Element hostedElement, double[] bbox)
    {
        double[] associationBox = (double[])bbox.Clone();
        if (bbox.Length < 6 || !TryGetSerializedInsertionOrigin(
                hostedElement, out double insertionXFt, out double insertionYFt))
            return associationBox;
        double halfX = (bbox[3] - bbox[0]) / 2;
        double halfY = (bbox[4] - bbox[1]) / 2;
        associationBox[0] = insertionXFt - halfX;
        associationBox[3] = insertionXFt + halfX;
        associationBox[1] = insertionYFt - halfY;
        associationBox[4] = insertionYFt + halfY;
        return associationBox;
    }

    /// <summary>
    /// Returns the exact FamilyInstance placement translation serialized in the RVT instance
    /// transform.
    /// </summary>
    internal static bool TryGetSerializedInsertionOrigin(Element element,
        out double xFt, out double yFt)
    {
        xFt = yFt = 0;
        if (!TryGetSerializedInstanceTransform(element, out var transform)) return false;
        xFt = transform.Origin[0];
        yFt = transform.Origin[1];
        return true;
    }

    internal static bool TryBuildHostedOpeningBoundary(Element wallElem, double[] hostedBbox,
        out GeometryData boundary)
    {
        boundary = new GeometryData();
        bool debugOpening = Environment.GetEnvironmentVariable("RVTIO_GEOM_DBG_ID") is { } debugIds
            && debugIds.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Any(value => int.TryParse(value, out int id) && id == wallElem.Id);
        if (hostedBbox.Length < 6 || wallElem.Geometry?.Faces is not { Count: > 0 } wallFaces)
            return false;

        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, hostedBbox.Select(Math.Abs).Max());
        double roundoff = 256 * MachineEpsilon * scale;
        var horizontal = new List<(List<double[]> Ring, double Z, double Area)>();
        foreach (var face in wallFaces)
        {
            var sourceRings = new List<List<double[]>>();
            if (face.OuterVertices is { Count: >= 4 } outer) sourceRings.Add(outer);
            if (face.AlternativeOuterVertices is { Count: >= 4 } alternative)
                sourceRings.Add(alternative);
            sourceRings.AddRange((face.InnerVertices ?? [])
                .Where(ring => ring.Count >= 4));
            foreach (var source in sourceRings)
            {
                if (source.Any(point => point.Length < 3
                        || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                        || !double.IsFinite(point[2])))
                    continue;
                var ring = RemoveRepeated(source);
                if (ring.Count < 4) continue;
                double zMin = ring.Min(point => point[2]);
                double zMax = ring.Max(point => point[2]);
                if (zMax - zMin > roundoff
                    || zMin < hostedBbox[2] - roundoff || zMax > hostedBbox[5] + roundoff)
                    continue;
                double area = Math.Abs(SignedPlanArea(ring));
                if (area > roundoff * roundoff)
                    horizontal.Add((ring, (zMin + zMax) / 2, area));
            }
        }
        if (horizontal.Count < 2) return false;

        // Associate the insert with the authored bottom/head reveal pair that contains its
        // serialized insertion centre.
        double centreX = (hostedBbox[0] + hostedBbox[3]) / 2;
        double centreY = (hostedBbox[1] + hostedBbox[4]) / 2;
        var wallLocation = wallElem.Location;
        bool hasWallAxis = wallLocation is { CurveType: "Line", ArcRadius: null };
        double wallAxisX = 0, wallAxisY = 0, hostedCentreAlong = 0;
        if (hasWallAxis)
        {
            double axisDx = wallLocation!.EndPoint[0] - wallLocation.StartPoint[0];
            double axisDy = wallLocation.EndPoint[1] - wallLocation.StartPoint[1];
            double axisLength = Math.Sqrt(axisDx * axisDx + axisDy * axisDy);
            if (axisLength > 0 && double.IsFinite(axisLength))
            {
                wallAxisX = axisDx / axisLength;
                wallAxisY = axisDy / axisLength;
                hostedCentreAlong = centreX * wallAxisX + centreY * wallAxisY;
            }
            else hasWallAxis = false;
        }
        var pairs = new List<(List<double[]> Low, List<double[]> High,
            double LowZ, double HighZ, double ZError, double AlongGap,
            double AlongCentreDistance, double Area, double CentreDistance)>();
        for (int firstIndex = 0; firstIndex < horizontal.Count; firstIndex++)
            for (int secondIndex = firstIndex + 1; secondIndex < horizontal.Count; secondIndex++)
            {
                var first = horizontal[firstIndex];
                var second = horizontal[secondIndex];
                if (Math.Abs(first.Z - second.Z) <= roundoff
                    || first.Ring.Count != second.Ring.Count)
                    continue;
                var lowCandidate = first.Z <= second.Z ? first : second;
                var highCandidate = first.Z <= second.Z ? second : first;
                var alignedHigh = AlignPlanRing(
                    lowCandidate.Ring, highCandidate.Ring, roundoff);
                if (alignedHigh.Count != lowCandidate.Ring.Count
                    || !PlanRingIntersectsBox(lowCandidate.Ring, hostedBbox, roundoff))
                    continue;
                double ringCentreX = lowCandidate.Ring.Average(point => point[0]);
                double ringCentreY = lowCandidate.Ring.Average(point => point[1]);
                double alongGap = 0;
                double alongCentreDistance = 0;
                if (hasWallAxis)
                {
                    var along = lowCandidate.Ring
                        .Select(point => point[0] * wallAxisX + point[1] * wallAxisY)
                        .ToList();
                    double minAlong = along.Min(), maxAlong = along.Max();
                    alongGap = hostedCentreAlong < minAlong
                        ? minAlong - hostedCentreAlong
                        : hostedCentreAlong > maxAlong
                            ? hostedCentreAlong - maxAlong : 0;
                    alongCentreDistance = Math.Abs(
                        (minAlong + maxAlong) / 2 - hostedCentreAlong);
                }
                pairs.Add((lowCandidate.Ring, alignedHigh,
                    lowCandidate.Z, highCandidate.Z,
                    Math.Abs(lowCandidate.Z - hostedBbox[2])
                        + Math.Abs(highCandidate.Z - hostedBbox[5]),
                    alongGap, alongCentreDistance,
                    lowCandidate.Area + highCandidate.Area,
                    Math.Sqrt((ringCentreX - centreX) * (ringCentreX - centreX)
                        + (ringCentreY - centreY) * (ringCentreY - centreY))));
            }
        if (pairs.Count == 0) return false;
        double minimumZError = pairs.Min(pair => pair.ZError);
        // The two rings are decoded independently, so a mathematically identical head or sill can
        // differ by a few ulps.
        double zAssociationRoundoff = 1024 * MachineEpsilon * scale;
        var selected = pairs
            .Where(pair => pair.ZError <= minimumZError + zAssociationRoundoff)
            // Associate an insert with the reveal at the same authored longitudinal position before
            // choosing between nested layer returns at that position.
            .OrderBy(pair => pair.AlongGap)
            .ThenBy(pair => pair.AlongCentreDistance)
            // Nested horizontal pairs are successive wall-layer returns around the same void.
            .ThenByDescending(pair => pair.Area)
            .ThenBy(pair => pair.CentreDistance)
            .ThenBy(pair => pair.LowZ)
            .First();
        if (debugOpening)
            DiagnosticSink.WriteLine($"IFCOPENINGBOUNDARY host={wallElem.Id} bbox=[{string.Join(',', hostedBbox.Select(value => value.ToString("G17", CultureInfo.InvariantCulture)))}] pairs=[{string.Join(';', pairs.Select(pair => $"z{pair.LowZ:G9}..{pair.HighZ:G9}:zg{pair.ZError:G9}:ug{pair.AlongGap:G9}:uc{pair.AlongCentreDistance:G9}:a{pair.Area:G9}"))}] selected=z{selected.LowZ:G9}..{selected.HighZ:G9}:ug{selected.AlongGap:G9}:uc{selected.AlongCentreDistance:G9}:a{selected.Area:G9}");
        var highRing = selected.High;
        var lowRing = new List<double[]>(selected.Low);
        if (SignedPlanArea(lowRing) > 0) lowRing.Reverse();
        highRing = AlignPlanRing(lowRing, highRing, roundoff);
        if (highRing.Count != lowRing.Count) return false;

        // Keep the corresponding top vertices in the same cyclic order as the bottom while
        // constructing the side faces.
        var topRing = new List<double[]>(highRing);
        topRing.Reverse();

        var faces = new List<GeoFace>
        {
            NewFace(lowRing),
            NewFace(topRing),
        };
        for (int index = 0; index < lowRing.Count; index++)
        {
            int next = (index + 1) % lowRing.Count;
            faces.Add(NewFace(
            [
                lowRing[index], highRing[index], highRing[next], lowRing[next],
            ]));
        }
        var points = lowRing.Concat(highRing).ToList();
        boundary = new GeometryData
        {
            BoundingBox =
            [
                points.Min(point => point[0]), points.Min(point => point[1]), points.Min(point => point[2]),
                points.Max(point => point[0]), points.Max(point => point[1]), points.Max(point => point[2]),
            ],
            Faces = faces,
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    FaceIndices = Enumerable.Range(0, faces.Count).ToList(),
                    IsClosed = true,
                },
            ],
        };
        return true;

        static List<double[]> RemoveRepeated(IEnumerable<double[]> source)
        {
            var result = new List<double[]>();
            foreach (var point in source)
                if (result.Count == 0 || !SamePlanPoint(result[^1], point, 0)) result.Add(point);
            if (result.Count > 1 && SamePlanPoint(result[0], result[^1], 0)) result.RemoveAt(result.Count - 1);
            return result;
        }
        static bool SamePlanPoint(double[] first, double[] second, double tolerance) =>
            Math.Abs(first[0] - second[0]) <= tolerance
            && Math.Abs(first[1] - second[1]) <= tolerance;
        static bool PointInPlanRing(IReadOnlyList<double[]> ring,
            double x, double y, double tolerance)
        {
            bool inside = false;
            for (int index = 0, previous = ring.Count - 1;
                 index < ring.Count; previous = index++)
            {
                double ax = ring[previous][0], ay = ring[previous][1];
                double bx = ring[index][0], by = ring[index][1];
                double cross = (x - ax) * (by - ay) - (y - ay) * (bx - ax);
                double edgeScale = Math.Max(1.0,
                    new[] { x, y, ax, ay, bx, by }.Select(Math.Abs).Max());
                if (Math.Abs(cross) <= tolerance * edgeScale
                    && x >= Math.Min(ax, bx) - tolerance && x <= Math.Max(ax, bx) + tolerance
                    && y >= Math.Min(ay, by) - tolerance && y <= Math.Max(ay, by) + tolerance)
                    return true;
                if ((ay > y) != (by > y)
                    && x < (bx - ax) * (y - ay) / (by - ay) + ax)
                    inside = !inside;
            }
            return inside;
        }
        static bool PlanRingIntersectsBox(IReadOnlyList<double[]> ring,
            double[] bounds, double tolerance)
        {
            bool InBox(double[] point) =>
                point[0] >= bounds[0] - tolerance && point[0] <= bounds[3] + tolerance
                && point[1] >= bounds[1] - tolerance && point[1] <= bounds[4] + tolerance;
            if (ring.Any(InBox)) return true;
            double[][] corners =
            [
                [bounds[0], bounds[1]], [bounds[3], bounds[1]],
                [bounds[3], bounds[4]], [bounds[0], bounds[4]],
            ];
            if (corners.Any(corner => PointInPlanRing(
                    ring, corner[0], corner[1], tolerance)))
                return true;

            static double Cross(double ax, double ay, double bx, double by,
                double cx, double cy) => (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
            static bool Intersects(double[] first, double[] second,
                double[] third, double[] fourth, double tolerance)
            {
                double c1 = Cross(first[0], first[1], second[0], second[1], third[0], third[1]);
                double c2 = Cross(first[0], first[1], second[0], second[1], fourth[0], fourth[1]);
                double c3 = Cross(third[0], third[1], fourth[0], fourth[1], first[0], first[1]);
                double c4 = Cross(third[0], third[1], fourth[0], fourth[1], second[0], second[1]);
                return ((c1 <= tolerance && c2 >= -tolerance) || (c2 <= tolerance && c1 >= -tolerance))
                    && ((c3 <= tolerance && c4 >= -tolerance) || (c4 <= tolerance && c3 >= -tolerance));
            }
            for (int ringIndex = 0; ringIndex < ring.Count; ringIndex++)
                for (int boxIndex = 0; boxIndex < corners.Length; boxIndex++)
                    if (Intersects(ring[ringIndex], ring[(ringIndex + 1) % ring.Count],
                        corners[boxIndex], corners[(boxIndex + 1) % corners.Length], tolerance))
                        return true;
            return false;
        }
        static double SignedPlanArea(IReadOnlyList<double[]> ring)
        {
            double twiceArea = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                var first = ring[index];
                var second = ring[(index + 1) % ring.Count];
                twiceArea += first[0] * second[1] - second[0] * first[1];
            }
            return twiceArea / 2;
        }
        static List<double[]> AlignPlanRing(IReadOnlyList<double[]> target,
            IReadOnlyList<double[]> candidate, double tolerance)
        {
            foreach (bool reverse in new[] { false, true })
                for (int shift = 0; shift < candidate.Count; shift++)
                {
                    var aligned = Enumerable.Range(0, candidate.Count)
                        .Select(index => candidate[reverse
                            ? (shift - index + candidate.Count) % candidate.Count
                            : (shift + index) % candidate.Count]).ToList();
                    if (Enumerable.Range(0, target.Count).All(index =>
                        SamePlanPoint(target[index], aligned[index], tolerance)))
                        return aligned;
                }
            return [];
        }
        static GeoFace NewFace(List<double[]> vertices) => new()
        {
            OuterVertices = new List<double[]>(vertices),
        };
    }

    /// <summary>
    /// Extract the exact longitudinal span and elevation of a constant-height opening from its
    /// authored bottom/head reveal rings.
    /// </summary>
    internal static bool TryGetAuthoredHostedOpeningSpan(Element wallElem,
        GeometryData boundary, out double centreAlongFt, out double widthFt,
        out double baseZFt, out double heightFt)
    {
        centreAlongFt = widthFt = baseZFt = heightFt = 0;
        if (wallElem.Location is not { CurveType: "Line", ArcRadius: null } location
            || boundary.Faces is not { Count: >= 6 } faces
            || boundary.BrepSolids is not { Count: 1 } solids
            || solids[0].FaceIndices.Count != faces.Count
            || faces[0].OuterVertices is not { Count: >= 4 } lowRing
            || faces[1].OuterVertices is not { Count: >= 4 } highRing
            || lowRing.Count != highRing.Count)
            return false;

        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double length = Math.Sqrt(dx * dx + dy * dy);
        if (!(length > 0) || !double.IsFinite(length)) return false;
        double axisX = dx / length, axisY = dy / length;
        if (lowRing.Concat(highRing).Any(point => point.Length < 3
            || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
            || !double.IsFinite(point[2])))
            return false;

        double lowMinZ = lowRing.Min(point => point[2]);
        double lowMaxZ = lowRing.Max(point => point[2]);
        double highMinZ = highRing.Min(point => point[2]);
        double highMaxZ = highRing.Max(point => point[2]);
        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, lowRing.Concat(highRing)
            .SelectMany(point => point).Select(Math.Abs).Max());
        double roundoff = 256 * MachineEpsilon * scale;
        if (lowMaxZ - lowMinZ > roundoff || highMaxZ - highMinZ > roundoff)
            return false;
        baseZFt = (lowMinZ + lowMaxZ) / 2;
        double headZFt = (highMinZ + highMaxZ) / 2;
        if (headZFt < baseZFt)
            (baseZFt, headZFt) = (headZFt, baseZFt);

        var along = lowRing.Select(point => point[0] * axisX + point[1] * axisY)
            .ToList();
        double minAlong = along.Min(), maxAlong = along.Max();
        widthFt = maxAlong - minAlong;
        heightFt = headZFt - baseZFt;
        centreAlongFt = (minAlong + maxAlong) / 2;
        return widthFt > roundoff && heightFt > roundoff
            && double.IsFinite(centreAlongFt);
    }

    /// <summary>
    /// Returns the exact plan depth of an authored reveal/cutter perpendicular to a straight host
    /// wall.
    /// </summary>
    internal static bool TryGetAuthoredHostedOpeningNormalDepth(Element wallElem,
        GeometryData boundary, out double depthFt)
    {
        depthFt = 0;
        if (wallElem.Location is not { CurveType: "Line", ArcRadius: null } location
            || boundary.Faces is not { Count: >= 2 } faces)
            return false;
        double dx = location.EndPoint[0] - location.StartPoint[0];
        double dy = location.EndPoint[1] - location.StartPoint[1];
        double length = Math.Sqrt(dx * dx + dy * dy);
        if (!(length > 0) || !double.IsFinite(length)) return false;
        double normalX = -dy / length, normalY = dx / length;
        var points = faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 2
                && double.IsFinite(point[0]) && double.IsFinite(point[1]))
            .ToList();
        if (points.Count < 4) return false;
        var normalCoordinates = points
            .Select(point => point[0] * normalX + point[1] * normalY).ToList();
        depthFt = normalCoordinates.Max() - normalCoordinates.Min();
        if (!(depthFt > 0) || !double.IsFinite(depthFt)) return false;

        // A decoded wall face can carry Revit's exact cutter/reveal contour as its alternative loop
        // while OuterVertices contains the clipped visible wall face.
        if (wallElem.Geometry?.Faces is not { Count: > 0 } wallFaces)
            return true;
        double boundaryLowZ = points.Min(point => point[2]);
        double boundaryHighZ = points.Max(point => point[2]);
        double scale = Math.Max(1.0, points.SelectMany(point => point).Select(Math.Abs).Max());
        const double MachineEpsilon = 2.2204460492503131e-16;
        double roundoff = 1024 * MachineEpsilon * scale;
        var boundaryAlong = points.Select(point => point[0] * dx / length
            + point[1] * dy / length).ToList();
        double boundaryMinAlong = boundaryAlong.Min();
        double boundaryMaxAlong = boundaryAlong.Max();
        double boundaryCentreAlong = (boundaryMinAlong + boundaryMaxAlong) / 2;
        var candidates = new List<(double AlongGap, double CentreDistance, double Depth)>();
        foreach (var face in wallFaces)
        {
            if (face.AlternativeOuterVertices is not { Count: >= 4 } alternative
                || alternative.Any(point => point.Length < 3
                    || !double.IsFinite(point[0]) || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2])))
                continue;
            double lowZ = alternative.Min(point => point[2]);
            double highZ = alternative.Max(point => point[2]);
            if (Math.Abs(lowZ - boundaryLowZ) > roundoff
                || Math.Abs(highZ - boundaryHighZ) > roundoff)
                continue;
            var along = alternative.Select(point => point[0] * dx / length
                + point[1] * dy / length).ToList();
            double minAlong = along.Min(), maxAlong = along.Max();
            double alongGap = maxAlong < boundaryMinAlong
                ? boundaryMinAlong - maxAlong
                : minAlong > boundaryMaxAlong ? minAlong - boundaryMaxAlong : 0;
            var normal = alternative.Select(point => point[0] * normalX
                + point[1] * normalY).ToList();
            double alternativeDepth = normal.Max() - normal.Min();
            if (alternativeDepth > roundoff && double.IsFinite(alternativeDepth))
                candidates.Add((alongGap,
                    Math.Abs((minAlong + maxAlong) / 2 - boundaryCentreAlong),
                    alternativeDepth));
        }
        if (candidates.Count > 0)
        {
            var selected = candidates
                .OrderBy(candidate => candidate.AlongGap)
                .ThenBy(candidate => candidate.CentreDistance)
                .ThenByDescending(candidate => candidate.Depth)
                .First();
            if (selected.AlongGap <= roundoff && selected.Depth > depthFt + roundoff)
                depthFt = selected.Depth;
        }
        return true;
    }

    internal static (double WidthFt, double HeightFt) ResolveHostedOpeningDimensions(
        Element hostedElem, Element? hostedType, double[] bbox, double wallAxisX, double wallAxisY)
    {
        double widthFt = GetSerializedPositiveDimension(
            hostedElem, hostedType, -1001301, -1001305);
        double heightFt = GetSerializedPositiveDimension(
            hostedElem, hostedType, -1001300, -1001304);
        if (widthFt <= 0 && bbox.Length >= 6)
            widthFt = Math.Abs((bbox[3] - bbox[0]) * wallAxisX)
                + Math.Abs((bbox[4] - bbox[1]) * wallAxisY);
        if (heightFt <= 0 && bbox.Length >= 6)
            heightFt = bbox[5] - bbox[2];
        return (widthFt, heightFt);
    }

    /// <summary>Some reveal rings include one wall-thickness return beyond the clear opening.</summary>
    internal static bool TryResolveSerializedClearOpeningWidth(
        Element hostedElem, Element? hostedType, double authoredWidthFt,
        double wallThicknessFt, out double clearWidthFt)
    {
        clearWidthFt = 0;
        if (!(authoredWidthFt > 0) || !(wallThicknessFt > 0)
            || !double.IsFinite(authoredWidthFt) || !double.IsFinite(wallThicknessFt))
            return false;
        double candidate = authoredWidthFt - wallThicknessFt;
        if (!(candidate > 0) || !double.IsFinite(candidate)) return false;

        const double MachineEpsilon = 2.2204460492503131e-16;
        double scale = Math.Max(1.0, Math.Max(authoredWidthFt, wallThicknessFt));
        double roundoff = 1024 * MachineEpsilon * scale;
        var matches = hostedElem.Parameters
            .Concat(hostedType?.Parameters ?? Enumerable.Empty<Parameter>())
            .Where(parameter => parameter.Value is double value && value > 0
                && double.IsFinite(value)
                && (parameter.SpecType?.Contains(":length", StringComparison.OrdinalIgnoreCase) == true
                    || parameter.Guid == AdskSizeWidthParameterGuid)
                && Math.Abs(value - candidate) <= roundoff)
            .Select(parameter => (double)parameter.Value!)
            .ToList();
        if (matches.Count == 0) return false;
        clearWidthFt = matches.Average();
        return Math.Abs(clearWidthFt - candidate) <= roundoff;
    }

    private static double GetSerializedPositiveDimension(
        Element elem, Element? typeElem, params int[] ids)
    {
        foreach (int id in ids)
            foreach (var parameter in elem.Parameters.Concat(
                         typeElem?.Parameters ?? Enumerable.Empty<Parameter>()))
                if (parameter.Id == id && parameter.Value is double value
                    && value > 0 && double.IsFinite(value))
                    return value;
        return 0;
    }

    private static bool TryGetSerializedHostedOpeningDimensions(
        IEnumerable<Parameter> parameters,
        out double widthFt, out double heightFt, out double depthFt)
    {
        widthFt = heightFt = depthFt = 0;
        foreach (var parameter in parameters)
        {
            if (parameter.Value is not double value
                || !(value > 0) || !double.IsFinite(value))
                continue;
            if (parameter.Guid == HostedOpeningWidthParameterGuid) widthFt = value;
            else if (parameter.Guid == HostedOpeningHeightParameterGuid) heightFt = value;
            else if (parameter.Guid == HostedOpeningDepthParameterGuid) depthFt = value;
        }
        return widthFt > 0 && heightFt > 0 && depthFt > 0;
    }

    private int CreateEmptyShape(StepWriter w, int subCtxId)
    {
        int ptId = w.Add("IFCCARTESIANPOINT", StepWriter.List("0.", "0.", "0."));
        int shapeRepId = w.Add("IFCSHAPEREPRESENTATION",
            $"{R(subCtxId)},{S("Body")},{S("Brep")},{StepWriter.List(R(ptId))}");
        return w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(R(shapeRepId))}");
    }


    /// <summary>
    /// True for every ifcType whose elemArgs switch above writes a real Tag attribute
    /// (S(elem.Id.ToString())) rather than "$".
    /// </summary>
    internal static bool ExportsIfcTagAttribute(string ifcType) => ifcType != "IFCSITE";


    /// <summary>
    /// True only for the IFC classes this exporter emits that are subclasses of IfcElement.
    /// </summary>
    internal static bool IsIfcElementSubclassProduct(string ifcType) => ifcType switch
    {
        "IFCBEAM" or "IFCBUILDINGELEMENTPROXY" or "IFCCOLUMN" or "IFCCOVERING"
            or "IFCCURTAINWALL" or "IFCDISTRIBUTIONFLOWELEMENT" or "IFCDOOR"
            or "IFCFLOWCONTROLLER" or "IFCFLOWFITTING" or "IFCFLOWSEGMENT" or "IFCFLOWTERMINAL"
            or "IFCFURNISHINGELEMENT" or "IFCMEMBER" or "IFCOPENINGELEMENT"
            or "IFCPLATE" or "IFCRAILING" or "IFCRAMP" or "IFCRAMPFLIGHT"
            or "IFCROOF" or "IFCSLAB" or "IFCSTAIR" or "IFCSTAIRFLIGHT" or "IFCREINFORCINGMESH"
            or "IFCWALL" or "IFCWALLSTANDARDCASE" or "IFCWINDOW" => true,
        // IFCSITE, IFCBUILDING, IFCBUILDINGSTOREY, IFCSPACE (IfcSpatialStructureElement),
        // IFCDISTRIBUTIONPORT (IfcPort), IFCANNOTATION, IFCGRID - IfcProducts, NOT IfcElements.
        _ => false,
    };

    /// <summary>
    /// Both inputs are downstream writer outcomes: <paramref name="bodyOutcome"/> describes the
    /// representation items actually emitted (including representation-map payloads).
    /// </summary>
    internal static bool ShouldSuppressOpenSurfaceHostedCutterProxyProduct(
        string ifcType,
        BodyRepresentationWriteOutcome bodyOutcome,
        bool hasMaterializedHostedOpeningOperand) =>
        ifcType == "IFCBUILDINGELEMENTPROXY"
        && bodyOutcome.HasSurfaceModel
        && !bodyOutcome.HasClosedBrepOrSweptSolidBody
        && bodyOutcome.OpenShellCount == 1
        && bodyOutcome.OpenShellFaceCount == 4
        && hasMaterializedHostedOpeningOperand;

    /// <summary>Exact product-role authority recovered from Element.m_unplacedOwnerId.</summary>
    internal static bool ShouldSuppressUnplacedOwnerProxyProduct(
        string ifcType, int? serializedUnplacedOwnerId) =>
        ifcType == "IFCBUILDINGELEMENTPROXY"
        && serializedUnplacedOwnerId is > 0;

    /// <summary>
    /// True when a wall's own LEVEL_PARAM points at a real, positive Level element id that is not a
    /// key of <paramref name="acceptedStoreyLevelIds"/>.
    /// </summary>
    internal static bool ShouldSuppressPhantomStoreyWallProduct(
        string ifcType, int? levelParamElementId,
        IReadOnlyDictionary<int, int> acceptedStoreyLevelIds) =>
        ifcType is "IFCWALL" or "IFCWALLSTANDARDCASE"
        && levelParamElementId is > 0
        && !acceptedStoreyLevelIds.ContainsKey(levelParamElementId.Value);

    /// <summary>The wall export skips a StackedWall parent, not its source record or children.</summary>
    internal static bool IsValidatedStackedWallContainer(
        Element element, IReadOnlyDictionary<int, Element> elementsById) =>
        element.CategoryId == -2000011 && element.FamilyTypeId > 0
        && elementsById.TryGetValue(element.FamilyTypeId, out var type)
        && type.Id == element.FamilyTypeId && type.CategoryId == -2003500
        && type.IsSerializedStackedWallType;

    /// <summary>
    /// A positive Element.m_unplacedOwnerId is an authored ownership edge to another record, so the
    /// selected sketch line is not an independent opening source.
    /// </summary>
    internal static bool ShouldSuppressSerializedSlabOpeningSource(
        int? serializedUnplacedOwnerId) => serializedUnplacedOwnerId is > 0;

    /// <summary>ElementId -1 is the serialized "no unplaced owner" sentinel.</summary>
    internal static bool CanUseSerializedSlabOpeningHostReference(
        int? serializedUnplacedOwnerId) => serializedUnplacedOwnerId == -1;

    /// <summary>
    /// Otherwise write neither the product, nor its IfcRelContainedInSpatialStructure, nor its
    /// Pset_QuantityTakeOff.
    /// </summary>

    internal static bool ShouldSuppressGeometrylessElementProduct(
        string ifcType, bool hasEmittedRepresentation, bool isEmittedAggregateParent) =>
        !hasEmittedRepresentation
        && !isEmittedAggregateParent
        && IsIfcElementSubclassProduct(ifcType);

    /// <summary>
    /// Registers <paramref name="elementId"/> as the RelatingObject of an element-level
    /// IfcRelAggregates whose parts this export emits, exempting it from <see
    /// cref="ShouldSuppressGeometrylessElementProduct"/>.
    /// </summary>
    internal void RegisterEmittedAggregateParent(int elementId) =>
        _emittedAggregateParentElementIds.Add(elementId);

    /// <summary>
    /// Emits Pset_QuantityTakeOff (single property: Reference = the element's type name) and its
    /// IfcRelDefinesByProperties attachment for one qualifying element.
    /// </summary>
    private int? ExportQuantityTakeOffPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string? referenceValue, Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        int additionalEntityId = 0)
    {
        if (referenceValue == null)
        {
            _mainLoopReferenceOmittedCount++;
            return null;
        }
        int valueId = GetOrAddPropertySingleValue(
            w, valuePool, "Reference", $"IFCIDENTIFIER({S(referenceValue)})");
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"qto-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_QuantityTakeOff")},$,{StepWriter.List(R(valueId))}");
        // The slab of a roof shares the set of the roof (the current profile: one
        // IfcRelDefinesByProperties for both).
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"qto-rel:{elem.Id}"))},{R(ownerHistId)},$,$,"
            + $"{(additionalEntityId > 0 ? StepWriter.List(R(elemEntityId), R(additionalEntityId)) : StepWriter.List(R(elemEntityId)))},{R(psetId)}");
        return valueId;
    }

    /// <summary>The wall that owns the property sets of an opening element: its serialized host, when both occur once and the host is a wall without cutting elements.</summary>
    internal static Element? ResolveMainLoopWallOpeningPropertySetHost(
        string ifcType, Element opening,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts)
    {
        if (ifcType != "IFCOPENINGELEMENT"
            || opening.CategoryId != -2000997
            || opening.SerializedHostId is not > 0
            || opening.SerializedHostId.Value == opening.Id
            || !elementIdOccurrenceCounts.TryGetValue(
                opening.Id, out int openingOccurrences)
            || openingOccurrences != 1)
            return null;

        int hostId = opening.SerializedHostId.Value;
        if (!elementIdOccurrenceCounts.TryGetValue(
                hostId, out int hostOccurrences)
            || hostOccurrences != 1
            || !elementsById.TryGetValue(hostId, out Element? host)
            || host.Id != hostId
            || host.CategoryId != -2000011
            || host.CuttingElementIds is not { Count: 0 })
            return null;

        return host;
    }

    /// <summary>
    /// A successfully emitted proxy with QTO is excluded only when its exact serialized host is a
    /// decoded floor cutter roster, either directly or through exactly one serialized intermediary.
    /// </summary>
    internal static bool ReceivesBuildingElementProxyCommonPropertySet(
        string ifcType, Element elem,
        IReadOnlyDictionary<int, Element> elementsById)
    {
        if (ifcType != "IFCBUILDINGELEMENTPROXY") return false;
        if (!elem.SerializedHostId.HasValue || elem.SerializedHostId.Value <= 0)
            return true;

        int directHostId = elem.SerializedHostId.Value;
        if (directHostId == elem.Id) return true;
        elementsById.TryGetValue(directHostId, out Element? directHost);
        if (directHost != null && directHost.Id != directHostId) return true;

        int? materializedParentId = directHost?.SerializedHostId;
        int? carriedParentId = elem.SerializedHostParentId;
        Element floor;
        if (directHost?.CategoryId == FloorCategoryId
            && materializedParentId is not > 0
            && carriedParentId is not > 0)
        {
            floor = directHost;
        }
        else
        {
            if (materializedParentId.HasValue
                && carriedParentId.HasValue
                && materializedParentId.Value != carriedParentId.Value)
            {
                return true;
            }

            int? resolvedParentId = materializedParentId ?? carriedParentId;
            if (!resolvedParentId.HasValue || resolvedParentId.Value <= 0)
                return true;

            int floorId = resolvedParentId.Value;
            if (floorId == elem.Id
                || floorId == directHostId
                || !elementsById.TryGetValue(floorId, out Element? resolvedFloor)
                || resolvedFloor.Id != floorId
                || resolvedFloor.CategoryId != FloorCategoryId)
            {
                return true;
            }
            floor = resolvedFloor;
        }

        return floor.CuttingElementIds?.Contains(elem.Id) != true;
    }

