    }

    /// <summary>Dimensions in millimetres; null when the symbol is no box.</summary>
    internal static (double Width, double Height, double Depth)? ResolveProvisionForVoidDimensions(
        Element proxy, IReadOnlyDictionary<int, Element> elementsById)
    {
        if (proxy.Geometry?.ExactMappedInstances is not { Count: 1 } mapped
            || !elementsById.TryGetValue(mapped[0].SymbolId, out var symbol)
            || symbol.Geometry is not { Faces.Count: 6, BrepSolids: { Count: 1 } solids } geometry
            || !solids[0].IsClosed)
            return null;
        var points = geometry.Faces.SelectMany(face => face.OuterVertices ?? []).ToList();
        if (points.Count == 0 || geometry.Faces.Any(face => face.OuterVertices is not { Count: >= 3 })) return null;
        var min = new double[3];
        var max = new double[3];
        for (int axis = 0; axis < 3; axis++)
        {
            min[axis] = points.Min(point => point[axis]);
            max[axis] = points.Max(point => point[axis]);
        }
        const double Tolerance = 1e-6;
        var sides = new HashSet<(int Axis, bool High)>();
        foreach (var face in geometry.Faces)
        {
            bool matched = false;
            for (int axis = 0; axis < 3 && !matched; axis++)
                foreach (bool high in new[] { false, true })
                {
                    double plane = high ? max[axis] : min[axis];
                    if (face.OuterVertices!.All(point => Math.Abs(point[axis] - plane) <= Tolerance)
                        && max[axis] - min[axis] > Tolerance)
                    {
                        matched = sides.Add((axis, high));
                        break;
                    }
                }
            if (!matched) return null;
        }
        double sideX = (max[0] - min[0]) * 304.8, sideY = (max[1] - min[1]) * 304.8;
        return (Math.Max(sideX, sideY), Math.Min(sideX, sideY), Math.Min(sideX, sideY));
    }

    private static void ExportProvisionForVoidPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        (double Width, double Height, double Depth) dimensions)
    {
        int Length(string name, double millimetres) => GetOrAddPropertySingleValue(
            w, valuePool, name, $"IFCPOSITIVELENGTHMEASURE({D17(millimetres)})");
        var values = new[] { Length("Width", dimensions.Width), Length("Height", dimensions.Height), Length("Depth", dimensions.Depth) };
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"provision-for-void-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_ProvisionForVoid")},$,{StepWriter.List(values.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"provision-for-void-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

