    private static void ExportOpeningCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId, string ifcType, bool? isExternal,
        int? referenceValueId, Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        double? thermalTransmittance = null)
    {
        var valueIds = new List<int>();
        if (thermalTransmittance is double transmittance)
            valueIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                $"{S("ThermalTransmittance")},$,IFCTHERMALTRANSMITTANCEMEASURE({D17(transmittance)}),$"));
        if (isExternal is bool external)
            valueIds.Add(GetOrAddPropertySingleValue(w, valuePool, "IsExternal", external ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));
        if (referenceValueId.HasValue) valueIds.Add(referenceValueId.Value);
        if (valueIds.Count == 0) return;
        string prefix = ifcType == "IFCDOOR" ? "door" : "window";
        string psetName = ifcType == "IFCDOOR" ? "Pset_DoorCommon" : "Pset_WindowCommon";
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"{prefix}-common-pset:{elem.Id}"))},{R(ownerHistId)},{S(psetName)},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"{prefix}-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

