            valueIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                $"{S("Finish")},$,IFCTEXT({S(finish)}),$"));
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"covering-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_CoveringCommon")},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"covering-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    /// <summary>
    /// ProcessEntry reads a "Finish" parameter on the covering itself; for a ceiling,
    /// FinishCalculator then reads it on the occurrence and its type, and for a Ceiling joins the
    /// names of the distinct Finish1/Finish2 layer materials of the type's CompoundStructure.
    /// </summary>
    internal static string? ResolveCeilingFinish(
        Element ceiling,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts, bool currentProfile = false)
    {
        const int CeilingsCategoryId = -2000038;
        (bool Blocked, string? Value) occurrenceFinish = ResolveExactNamedText(ceiling, "Finish");
        if (occurrenceFinish.Blocked) return null;
        if (occurrenceFinish.Value != null)
            return occurrenceFinish.Value.Length > 0 ? occurrenceFinish.Value : null;

        if (ceiling.CategoryId != CeilingsCategoryId
            || ceiling.SerializedCeilingTypeId is not int typeId
            || typeId <= 0 || typeId == ceiling.Id
            || elementIdOccurrenceCounts.GetValueOrDefault(typeId) != 1
            || elementIdOccurrenceCounts.GetValueOrDefault(ceiling.Id) != 1
            || !elementsById.TryGetValue(typeId, out Element? type)
            || type.CategoryId != CeilingsCategoryId)
            return null;
        (bool Blocked, string? Value) typeFinish = ResolveExactNamedText(type, "Finish");
        if (typeFinish.Blocked) return null;
        if (!string.IsNullOrEmpty(typeFinish.Value)) return typeFinish.Value;

        if (type.SerializedCeilingTypeLayers is not { } layers) return null;
        var materialIds = new List<int>();
        foreach (var layer in layers)
        {
            if (layer.RawFunction is not (4 or 5)) continue;
            if (layer.RawMaterialId <= 0) return null;
            if (!materialIds.Contains(layer.RawMaterialId)) materialIds.Add(layer.RawMaterialId);
        }

        // The current profile collects the finish materials in a std::set of element ids, so they
        // come in id order.
        if (currentProfile) materialIds.Sort();
        var finish = new System.Text.StringBuilder();
        foreach (int materialId in materialIds)
        {
            if (elementIdOccurrenceCounts.GetValueOrDefault(materialId) != 1
                || !elementsById.TryGetValue(materialId, out Element? material)
                || material.SerializedMaterialName is not string name
                || material.Parameters.Any(parameter =>
                    ParameterNameEquals(parameter, "IfcName")
                    || ParameterNameEquals(parameter, "NameOverride")))
                return null;
            if (string.IsNullOrWhiteSpace(name)) continue;
            finish.Append(name).Append(';');
        }
        return finish.Length > 0 ? finish.ToString() : null;
    }

    /// <summary>
    /// An exact text parameter by name: absent (null value), blocked when any match is approximate,
    /// non-text or conflicting, else its value.
    /// </summary>
    private static (bool Blocked, string? Value) ResolveExactNamedText(Element element, string name)
    {
        List<Parameter> matches = element.Parameters
            .Where(parameter => ParameterNameEquals(parameter, name)).ToList();
        if (matches.Count == 0) return (false, null);
        if (matches.Any(parameter => parameter.IsApproximate
                || parameter.StorageType != StorageType.String
                || parameter.Value is not string))
            return (true, null);
        var values = matches.Select(parameter => (string)parameter.Value!).Distinct().ToList();
        return values.Count == 1 ? (false, values[0]) : (true, null);
    }

    /// <summary>
    /// The parser sets both serialized fields only after confirming a BaseRailing occurrence's own
    /// m_stairsRailingAttrId, a BaseRailingAttr-subclass target with matching owner id, and that
    /// target's named finite m_topRailHeight.
    /// </summary>
    private static void ExportRailingCommonHeightPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId, int? referenceValueId,
        bool? isExternal, Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        bool currentProfile = false)
    {
        var values = new List<int>();
        if (isExternal is bool external)
            values.Add(GetOrAddPropertySingleValue(
                w, valuePool, "IsExternal", external ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));
        if (referenceValueId.HasValue) values.Add(referenceValueId.Value);
        if (elem.SerializedStairsRailingAttrId is int attributeId
            && attributeId > 0 && attributeId != elem.Id
            && elem.SerializedRailingTopHeightFeet is double heightFeet
            && double.IsFinite(heightFeet) && heightFeet > 0)
        {
            double heightMillimetres = currentProfile ? 0 : heightFeet * 304.8;
            if (double.IsFinite(heightMillimetres) && (currentProfile || heightMillimetres > 0))
                values.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                    $"{S("Height")},$,IFCPOSITIVELENGTHMEASURE({D17(heightMillimetres)}),$"));
        }
        if (values.Count == 0) return;
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"railing-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_RailingCommon")},$,{StepWriter.List(values.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"railing-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    /// <summary>
    /// The localized system family name of an occurrence's own type: the type element named by
    /// FamilyTypeId must be unique, of the same category and carry <see
    /// cref="Element.ValidatedSystemFamilyName"/>.
    /// </summary>
    internal static string? ResolveSystemFamilyName(
        Element occurrence,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts)
    {
        // BaseRailing.getTypeId_ reads the own m_stairsRailingAttrId (+178).
        int typeId = occurrence.FamilyTypeId;
        if (occurrence.SerializedStairsRailingAttrId is int railingTypeId)
        {
            bool ownNativeRailingType = occurrence.RuleClassName == "BaseRailing"
                && occurrence.CategoryId == -2000126
                && elementIdOccurrenceCounts.GetValueOrDefault(occurrence.Id) == 1;
            if (typeId > 0 && typeId != railingTypeId && !ownNativeRailingType) return null;
            typeId = railingTypeId;
        }
        if (occurrence.SerializedStairTypeLinkIsResolved && occurrence.SerializedStairTypeId is int stairTypeId)
        {
            if (typeId > 0 && typeId != stairTypeId) return null;
            typeId = stairTypeId;
        }
        // A ceiling's own m_ceilingAttributesId is exact where ELEM_TYPE_PARAM can be a guess.
        if (occurrence.SerializedCeilingTypeId is int ceilingTypeId)
            typeId = ceilingTypeId;
        if (typeId <= 0 || typeId == occurrence.Id
            || !elementIdOccurrenceCounts.TryGetValue(typeId, out int count) || count != 1
            || !elementsById.TryGetValue(typeId, out Element? type)
            || (type.CategoryId != occurrence.CategoryId
                && !(IsFloorElementCategory(type.CategoryId) && IsFloorElementCategory(occurrence.CategoryId))))
            return null;
        return type.ValidatedSystemFamilyName;
    }

    // A Floor element is filed under OST_Floors or, for a foundation slab type,
    // OST_StructuralFoundation; both are the same native FloorAttributes family.
    private static bool IsFloorElementCategory(int? categoryId) =>
        categoryId is -2000032 or -2001300;

    /// <summary>
    /// OST_StairsRailing is neither a roof nor a mass wall category and a BaseRailing is not a
    /// FamilyInstance, so genuine absence of both parameters is the official internal result.
    /// </summary>
    internal static bool? ResolveRailingIsExternal(
        Element occurrence,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts)
    {
        if (occurrence.CategoryId == -2000126 && occurrence.NativeMasterSymbolId is > 0)
            return false;
        if (occurrence.CategoryId != -2000126
            || occurrence.SerializedStairsRailingAttrId is not int typeId
            || typeId <= 0
            || typeId == occurrence.Id
            || !elementIdOccurrenceCounts.TryGetValue(occurrence.Id, out int occurrenceCount)
            || occurrenceCount != 1
            || !elementIdOccurrenceCounts.TryGetValue(typeId, out int typeCount)
            || typeCount != 1
            || !elementsById.TryGetValue(typeId, out Element? type)
            || type.Id != typeId
            || type.CategoryId != occurrence.CategoryId)
            return null;

        ExactIsExternalParameterResult named = ResolveExactIsExternalParameter(occurrence, type);
        if (named.State == ExactIsExternalParameterState.Value) return named.Value != 0;
        if (named.State == ExactIsExternalParameterState.Blocked) return null;

        ExactIsExternalParameterResult function = ResolveExactFunctionParameter(
            type, includeSerializedCurtainWallFunction: false);
        if (function.State == ExactIsExternalParameterState.Value) return function.Value != 0;
        if (function.State == ExactIsExternalParameterState.Blocked) return null;
        return false;
    }

    /// <summary>
    /// IsExternal precedes the shared QTO Reference; numeric values remain private per occurrence.
    /// </summary>
    private static void ExportStairOccurrenceCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string ifcType, int referenceValueId,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool, bool currentProfile = false)
    {
        (string psetName, string seedPrefix) = ifcType switch
        {
            "IFCSTAIR" => ("Pset_StairCommon", "stair-common"),
            "IFCSTAIRFLIGHT" => ("Pset_StairFlightCommon", "stair-flight-common"),
            _ => throw new ArgumentOutOfRangeException(nameof(ifcType), ifcType, null),
        };
        var valueIds = new List<int> { referenceValueId };
        Element? stairType = ifcType == "IFCSTAIR"
            ? ResolveExactSerializedStairType(
                elem, elementsById, elementIdOccurrenceCounts)
            : null;
        if (stairType != null)
        {
            ExactIsExternalParameterResult isExternal =
                ResolveExactIsExternalParameter(elem, stairType);
            if (isExternal.State == ExactIsExternalParameterState.Absent)
                isExternal = ResolveExactFunctionParameter(
                    stairType, includeSerializedCurtainWallFunction: false);
            if (isExternal.State == ExactIsExternalParameterState.Value)
            {
                valueIds.Insert(0, GetOrAddPropertySingleValue(
                    w, valuePool, "IsExternal",
                    isExternal.Value != 0
                        ? "IFCBOOLEAN(.T.)"
                        : "IFCBOOLEAN(.F.)"));
            }

            // The current profile writes neither NumberOfRiser nor NumberOfTreads (the calculators
            // find no run data).
            if (!currentProfile && elem.SerializedActualNumberOfRisers is int numberOfRisers
                && numberOfRisers > 0
                && !HasStairCommonOverrideCandidate(
                    elem, stairType, "NumberOfRiser"))
            {
                valueIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                    $"{S("NumberOfRiser")},$,IFCCOUNTMEASURE({D17(numberOfRisers)}),$"));
            }

            if (elem.SerializedActualRiserHeightFeet is double riserHeightFeet
                && double.IsFinite(riserHeightFeet)
                && riserHeightFeet > 0
                && !HasStairCommonOverrideCandidate(
                    elem, stairType, "RiserHeight"))
            {
                double riserHeightMillimetres = riserHeightFeet * 304.8;
                if (double.IsFinite(riserHeightMillimetres)
                    && riserHeightMillimetres > 0)
                {
                    valueIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                        $"{S("RiserHeight")},$,IFCPOSITIVELENGTHMEASURE({D17(riserHeightMillimetres)}),$"));
                }
            }

            if (elem.SerializedActualTreadDepthFeet is double treadDepthFeet
                && double.IsFinite(treadDepthFeet)
                && treadDepthFeet > 0
                && !HasStairCommonOverrideCandidate(
                    elem, stairType, "TreadLength"))
            {
                double treadLengthMillimetres = treadDepthFeet * 304.8;
                if (double.IsFinite(treadLengthMillimetres)
                    && treadLengthMillimetres > 0)
                {
                    valueIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                        $"{S("TreadLength")},$,IFCPOSITIVELENGTHMEASURE({D17(treadLengthMillimetres)}),$"));
                }
            }
        }
        if (ifcType == "IFCSTAIRFLIGHT")
            AddStairFlightProperties(w, elem, elementsById, valueIds, currentProfile);
        else if (ifcType == "IFCSTAIR" && stairType != null && !currentProfile)
            AddStairTreadCount(w, elem, elementsById, stairType, valueIds);
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"{seedPrefix}-pset:{elem.Id}"))},{R(ownerHistId)},{S(psetName)},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"{seedPrefix}-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    private static int StairRunRisers(TfBlockDeserializer.StairRunNumbers numbers) =>
        numbers.TopRiserIndex - numbers.BaseRiserIndex;

    private static bool StairRunCountsAgree(Element run, IReadOnlyDictionary<int, Element> elementsById,
        TfBlockDeserializer.StairRunNumbers numbers)
    {
        int stairsId = run.SerializedStairRunInput!.StairsId;
        if (!elementsById.TryGetValue(stairsId, out var stairs) || stairs.SerializedActualNumberOfRisers is not int stored)
            return true;
        int runsOfStairs = elementsById.Values.Count(other => other.SerializedStairRunInput?.StairsId == stairsId);
        return runsOfStairs != 1 || stored == StairRunRisers(numbers);
    }

    private static int? StairRunTreads(TfBlockDeserializer.StairRunNumbers numbers) =>
        numbers.BeginWithRiser is 0 or 1 && numbers.EndWithRiser is 0 or 1
            ? StairRunRisers(numbers) - 1 + (numbers.BeginWithRiser == 0 ? 1 : 0) + (numbers.EndWithRiser == 0 ? 1 : 0)
            : null;

    /// <summary>
    /// Pset_StairCommon.NumberOfTreads of a stair: the sum of the tread counts of its runs.
    /// </summary>
    private static void AddStairTreadCount(StepWriter w, Element stair,
        IReadOnlyDictionary<int, Element> elementsById, Element stairType, List<int> valueIds)
    {
        if (HasStairCommonOverrideCandidate(stair, stairType, "NumberOfTreads")) return;
        int treads = 0, runs = 0;
        foreach (var run in elementsById.Values)
        {
            if (run.SerializedStairRunInput is not { Numbers: { } numbers } input || input.StairsId != stair.Id) continue;
            if (!StairRunCountsAgree(run, elementsById, numbers) || StairRunTreads(numbers) is not int runTreads) return;
            treads += runTreads; runs++;
        }
        if (runs == 0 || treads <= 0) return;
        int at = valueIds.Count;
        for (int index = 0; index < valueIds.Count; index++)
            if (EntityPropertyName(w, valueIds[index]) == "NumberOfRiser") { at = index + 1; break; }
        valueIds.Insert(at, w.Add("IFCPROPERTYSINGLEVALUE",
            $"{S("NumberOfTreads")},$,IFCCOUNTMEASURE({D17(treads)}),$"));
    }

    private static string? EntityPropertyName(StepWriter w, int entityId)
    {
        for (int index = w.EntityCount - 1; index >= 0; index--)
        {
            var entity = w.EntityAt(index);
            if (entity.Id != entityId) continue;
            if (entity.Type != "IFCPROPERTYSINGLEVALUE" || !entity.Args.StartsWith("'", StringComparison.Ordinal)) return null;
            int end = entity.Args.IndexOf('\'', 1);
            return end < 0 ? null : entity.Args[1..end];
        }
        return null;
    }

    /// <summary>
    /// Pset_StairFlightCommon of a stair run (the stair export): risers and treads of the run, the
    /// riser height from its elevations, the tread length of its stairs, the nosing length of its
    /// run type, the walking line offset (half the run width.
    /// </summary>
    private static void AddStairFlightProperties(StepWriter w, Element run,
        IReadOnlyDictionary<int, Element> elementsById, List<int> valueIds, bool currentProfile = false)
    {
        bool includeCounts = !currentProfile;
        if (run.SerializedStairRunInput is not { Numbers: { } numbers } input || input.OwnerId != run.Id
            || !elementsById.TryGetValue(run.FamilyTypeId > 0 ? run.FamilyTypeId : run.TypeId, out var runType)
            || runType.Id == run.Id || runType.CategoryId != run.CategoryId
            || StairRunRisers(numbers) <= 0) return;
        elementsById.TryGetValue(input.StairsId, out var stairs);
        Element? stairsType = stairs?.SerializedStairTypeId is int stairsTypeId
            && elementsById.TryGetValue(stairsTypeId, out var foundType) ? foundType : null;
        bool Free(string name) => !HasStairCommonOverrideCandidate(run, runType, name);
        void Add(string name, string value) => valueIds.Add(w.Add("IFCPROPERTYSINGLEVALUE", $"{S(name)},$,{value},$"));
        string Length(string measure, double millimetres) => $"{measure}({D17(millimetres)})";

        int risers = StairRunRisers(numbers);
        bool countsAgree = StairRunCountsAgree(run, elementsById, numbers);
        if (includeCounts && countsAgree && Free("NumberOfRiser")) Add("NumberOfRiser", $"IFCCOUNTMEASURE({D17(risers)})");
        if (includeCounts && countsAgree && Free("NumberOfTreads") && StairRunTreads(numbers) is int treads && treads > 0)
            Add("NumberOfTreads", $"IFCCOUNTMEASURE({D17(treads)})");
        double riserHeight = (numbers.TopElevation - numbers.BottomElevation) / risers * 304.8;
        if (Free("RiserHeight") && double.IsFinite(riserHeight) && riserHeight > 0)
            Add("RiserHeight", Length("IFCPOSITIVELENGTHMEASURE", riserHeight));
        double? treadDepthFeet = stairs?.SerializedActualTreadDepthFeet;
        if (Free("TreadLength") && treadDepthFeet is > 0)
            Add("TreadLength", Length("IFCPOSITIVELENGTHMEASURE", treadDepthFeet.Value * 304.8));
        if (Free("NosingLength") && runType.SerializedStairRunTypeNosingFeet is double nosingFeet)
            Add("NosingLength", Length("IFCLENGTHMEASURE", nosingFeet * 304.8));
        if (Free("WalkingLineOffset") && numbers.ActualRunWidth > 0)
            Add("WalkingLineOffset", Length("IFCPOSITIVELENGTHMEASURE",
                currentProfile ? numbers.ActualRunWidth / 2 * 304.8 : numbers.ActualRunWidth / 2));
        if (Free("TreadLengthAtOffset") && treadDepthFeet is > 0)
            Add("TreadLengthAtOffset", Length("IFCPOSITIVELENGTHMEASURE", treadDepthFeet.Value * 304.8));
        double? inner = stairsType?.SerializedStairsTypeMinInsideTreadFeet is double minInside
            ? (minInside > 0 ? minInside : treadDepthFeet) : null;
        if (Free("TreadLengthAtInnerSide") && inner is > 0)
            Add("TreadLengthAtInnerSide", Length("IFCPOSITIVELENGTHMEASURE", inner.Value * 304.8));
    }

    /// <summary>The stair type of a stair occurrence when the serialized link is resolved, both ids are unique, the type is a stair of the same category and carries the stair type class marker.</summary>
    internal static Element? ResolveExactSerializedStairType(
        Element occurrence,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts)
    {
        if (occurrence.CategoryId != -2000120
            || !occurrence.SerializedStairTypeLinkIsResolved
            || occurrence.SerializedStairTypeId is not int typeId
            || typeId <= 0
            || typeId == occurrence.Id
            || !elementIdOccurrenceCounts.TryGetValue(
                occurrence.Id, out int occurrenceCount)
            || occurrenceCount != 1
            || !elementIdOccurrenceCounts.TryGetValue(typeId, out int typeCount)
            || typeCount != 1
            || !elementsById.TryGetValue(typeId, out Element? type)
            || type.Id != typeId
            || type.CategoryId != occurrence.CategoryId
            || type.SerializedStairsTypeClassId != 3742)
        {
            return null;
        }

        return type;
    }

    private static bool HasStairCommonOverrideCandidate(
        Element occurrence, Element type, string propertyName) =>
        occurrence.Parameters.Any(parameter =>
            ParameterNameEquals(parameter, propertyName))
        || type.Parameters.Any(parameter =>
            ParameterNameEquals(parameter, propertyName)
            || ParameterNameEquals(parameter, propertyName + "[Type]"));

    /// <summary>The exact QTO property entity is reused.</summary>
    private static void ExportBeamCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        int referenceValueId,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        bool? isExternal = null, double? spanMillimetres = null)
    {
        var valueIds = new List<int> { referenceValueId };
        if (spanMillimetres is double span)
            valueIds.Add(GetOrAddPropertySingleValue(w, valuePool, "Span", $"IFCPOSITIVELENGTHMEASURE({D17(span)})"));
        if (isExternal is bool beamExternal)
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "IsExternal", beamExternal ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));
        ExactIsExternalParameterResult loadBearing =
            ResolveExactOccurrenceBooleanParameter(elem, "LoadBearing");
        if (loadBearing.State == ExactIsExternalParameterState.Value)
        {
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "LoadBearing",
                loadBearing.Value != 0
                    ? "IFCBOOLEAN(.T.)"
                    : "IFCBOOLEAN(.F.)"));
        }
        else if (loadBearing.State == ExactIsExternalParameterState.Absent
            && elem.CategoryId == StructuralFramingCategoryId)
        {
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "LoadBearing", "IFCBOOLEAN(.T.)"));
        }

        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"beam-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_BeamCommon")},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"beam-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

