    private const int WallStructuralUsageParamId = -1001119;

    private static ExactIsExternalParameterResult ResolveExactWallStructuralUsageParameter(
        Element element)
    {
        List<Parameter> matches = element.Parameters
            .Where(parameter => parameter.Definition?.Id == WallStructuralUsageParamId)
            .ToList();
        if (matches.Count == 0)
            return new(ExactIsExternalParameterState.Absent);

        var candidates = new List<ExactIsExternalParameterResult>(matches.Count);
        foreach (Parameter parameter in matches)
        {
            if (parameter.IsApproximate
                || parameter.StorageType != StorageType.Integer
                || parameter.Value is not int integerValue)
            {
                candidates.Add(new(ExactIsExternalParameterState.Blocked));
            }
            else
            {
                candidates.Add(new(
                    ExactIsExternalParameterState.Value, integerValue));
            }
        }
        return MergeExactIntCandidates(candidates);
    }

    /// <summary>
    /// Attaches the exact occurrence-only Pset_WallCommon subset to a successfully emitted, tagged
    /// wall product (IFCWALL/IFCWALLSTANDARDCASE) that already emitted Pset_QuantityTakeOff.
    /// </summary>
    private static void ExportWallCommonPropertySet(
        StepWriter w, Element elem, Element? wallType, int elemEntityId, int ownerHistId,
        int referenceValueId,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool, bool currentProfile = false,
        double? thermalTransmittance = null)
    {
        var valueIds = new List<int> { referenceValueId };
        if (thermalTransmittance is double transmittance)
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "ThermalTransmittance", ThermalTransmittanceLiteralCurrent(transmittance)));

        if (ResolveValidatedBasicWallIsExternal(elem, wallType) is bool isExternal)
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "IsExternal", isExternal ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));

        ExactIsExternalParameterResult loadBearing =
            ResolveExactWallStructuralUsageParameter(elem);
        if (currentProfile)
        {
            valueIds.Add(GetOrAddPropertySingleValue(w, valuePool, "LoadBearing", "IFCBOOLEAN(.T.)"));
        }
        else if (loadBearing.State == ExactIsExternalParameterState.Value)
        {
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "LoadBearing",
                loadBearing.Value != 0
                    ? "IFCBOOLEAN(.T.)"
                    : "IFCBOOLEAN(.F.)"));
        }

        if (ResolveWallExtendToStructure(elem, currentProfile) is bool extendToStructure)
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "ExtendToStructure",
                extendToStructure ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));

        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"wall-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_WallCommon")},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"wall-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    /// <summary>IFCSITE here is a site-category family instance, not the project's site.</summary>
    private static readonly HashSet<string> ExportIdProductClasses = new(StringComparer.Ordinal)
    {
        "IFCWALL", "IFCWALLSTANDARDCASE", "IFCCURTAINWALL", "IFCSLAB", "IFCROOF", "IFCFOOTING",
        "IFCDOOR", "IFCWINDOW", "IFCBUILDINGELEMENTPROXY", "IFCRAILING", "IFCCOVERING",
        "IFCSTAIR", "IFCSTAIRFLIGHT", "IFCCOLUMN", "IFCBEAM", "IFCMEMBER", "IFCPLATE",
        "IFCFURNISHINGELEMENT", "IFCFLOWSEGMENT", "IFCFLOWTERMINAL", "IFCFLOWFITTING",
        "IFCFLOWCONTROLLER", "IFCDISTRIBUTIONFLOWELEMENT", "IFCSITE", "IFCREINFORCINGMESH",
    };

    /// <summary>
    /// IFCFamilyInstanceSubElements.InstanceAsType: the sub-element index of a type created from
    /// one instance, such as the IfcSpaceType of a room.
    /// </summary>
    internal const int InstanceAsTypeSubElementIndex = 2048;

    /// <summary>
    /// The door sub-element rule: the sub-element of the symbol that names its door or window
    /// style.
    /// </summary>
    internal const int DoorStyleSubElementIndex = 21;

    /// <summary>
    /// The exact GlobalId of an element's product (<paramref name="subElementIndex"/> 0) or of one
    /// of its sub-elements: the GlobalId is the export id (<see
    /// cref="Element.SerializedExportId"/>) unless an IfcGUID parameter overrides it.
    /// </summary>
    internal static string? ResolveExactElementGlobalId(
        Element element, ISet<Guid> usedExportIds, int subElementIndex = 0, bool handleBased = false)
    {
        if (element.SerializedExportId is not Guid exportId) return null;
        if (subElementIndex == 0 && HasIfcGuidOverride(element.Parameters, handleBased)) return null;
        Guid guid = subElementIndex == 0 ? exportId
            : ElementExportIds.SubElementId(handleBased ? element.SerializedHandleExportId ?? exportId : exportId, subElementIndex);
        return usedExportIds.Add(guid) ? IfcGuid.ToIfcGuid(guid) : null;
    }

    /// <summary>
    /// The GlobalId rule: the ids the export id combines with the document GUID for the
    /// project, building and site.
    /// </summary>
    internal enum ProjectLevelGuidType { Building = -15, Project = -16, Site = -14 }

    /// <summary>
    /// The GlobalId of a document-level id: the export-id rule of a
    /// project-level id and <c>ExporterIFCUtils.CreateAlternateGUID(level)</c> are the document
    /// GUID (<see cref="RevitFileInfo.SerializedDocumentGuid"/>) with the id XORed into its last
    /// 32.
    /// </summary>
    /// <summary>
    /// IfcProject Name, LongName and Phase. Without a project number the earlier name stays the
    /// Name and LongName is left out.
    /// </summary>
    internal static (string Name, string? LongName, string? Phase) ResolveProjectAttributes(RevitFileInfo info)
    {
        ProjectInfo? project = info.ProjectInfo;
        string? number = string.IsNullOrEmpty(project?.Number) ? null : project.Number;
        string? name = string.IsNullOrEmpty(project?.Name) ? null : project.Name;
        string? status = string.IsNullOrEmpty(project?.Status) ? null : project.Status;
        return number != null
            ? (number, name, status)
            : (name ?? info.Metadata?.LastSavePath ?? "Revit Project", null, status);
    }

    private static string OptionalString(string? value) => string.IsNullOrEmpty(value) ? "$" : S(value);

    internal static string? ResolveDocumentGlobalId(RevitFileInfo info, int id, ISet<Guid> usedExportIds)
    {
        if (info.SerializedDocumentGuid is not Guid documentGuid) return null;
        Guid guid = ElementExportIds.ExportId(documentGuid, unchecked((uint)id));
        return usedExportIds.Add(guid) ? IfcGuid.ToIfcGuid(guid) : null;
    }

    /// <summary>
    /// The GlobalId rule (and CreateSiteGUID, which falls back to it): an "IfcProject
    /// GUID"/"IfcBuilding GUID"/"IfcSite GUID" parameter wins, otherwise the export id of the
    /// project-level id.
    /// </summary>
    private string? ResolveProjectLevelGlobalId(RevitFileInfo info, ProjectLevelGuidType type, bool overridden) =>
        overridden ? null : ResolveDocumentGlobalId(info, (int)type, _usedExportIds);

    internal static bool HasProjectLevelGuidParameter(RevitFileInfo info) =>
        info.Elements.Any(element => element.Parameters.Any(parameter =>
            parameter.Id is (int)BuiltIns.BuiltInParameter.IFC_PROJECT_GUID
                or (int)BuiltIns.BuiltInParameter.IFC_BUILDING_GUID or (int)BuiltIns.BuiltInParameter.IFC_SITE_GUID
            || parameter.Definition?.Id is (int)BuiltIns.BuiltInParameter.IFC_PROJECT_GUID
                or (int)BuiltIns.BuiltInParameter.IFC_BUILDING_GUID or (int)BuiltIns.BuiltInParameter.IFC_SITE_GUID
            || parameter.Definition?.Name is "IfcProject GUID" or "IfcBuilding GUID" or "IfcSite GUID" or "IfcSiteGUID"));

    private static readonly Regex SingleObjectPropertyRelation = new(
        @"^'[0-9A-Za-z_$]{22}',#\d+,\$,\$,\(#(\d+)\),#(\d+)$", RegexOptions.Compiled);
    private static readonly Regex PropertySetName = new(
        @"^'[0-9A-Za-z_$]{22}',#\d+,'((?:[^']|'')*)',", RegexOptions.Compiled);
    private static readonly Regex EntityReference = new(@"#(\d+)", RegexOptions.Compiled);

    /// <summary>A GUID that is already in the file leaves both entities unchanged.</summary>
    internal static int ApplyPropertySetGlobalIds(StepWriter w, IReadOnlySet<string> exactGlobalIds)
    {
        var indexById = new Dictionary<int, int>(w.EntityCount);
        var globalIds = new HashSet<string>(StringComparer.Ordinal);
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (id, _, args) = w.EntityAt(i);
            indexById[id] = i;
            if (FirstGlobalId(args) is { } globalId) globalIds.Add(globalId);
        }

        // IFC2X3 references a property set from IfcRelDefinesByProperties and from the
        // HasPropertySets of type objects (types and styles).
        var propertySetReferences = new Dictionary<int, int>();
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (_, type, args) = w.EntityAt(i);
            if (type != "IFCRELDEFINESBYPROPERTIES" && !type.EndsWith("TYPE", StringComparison.Ordinal)
                && !type.EndsWith("STYLE", StringComparison.Ordinal))
                continue;
            foreach (Match reference in EntityReference.Matches(args))
            {
                int target = int.Parse(reference.Groups[1].ValueSpan, CultureInfo.InvariantCulture);
                if (indexById.TryGetValue(target, out int targetIndex) && w.EntityAt(targetIndex).Type == "IFCPROPERTYSET")
                    propertySetReferences[target] = propertySetReferences.GetValueOrDefault(target) + 1;
            }
        }

        int renamed = 0;
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (_, type, args) = w.EntityAt(i);
            if (type != "IFCRELDEFINESBYPROPERTIES") continue;
            var relation = SingleObjectPropertyRelation.Match(args);
            if (!relation.Success) continue;
            int objectId = int.Parse(relation.Groups[1].ValueSpan, CultureInfo.InvariantCulture);
            int propertySetId = int.Parse(relation.Groups[2].ValueSpan, CultureInfo.InvariantCulture);
            if (!indexById.TryGetValue(objectId, out int objectIndex)
                || !indexById.TryGetValue(propertySetId, out int propertySetIndex)
                || propertySetReferences.GetValueOrDefault(propertySetId) != 1
                || FirstGlobalId(w.EntityAt(objectIndex).Args) is not { } objectGlobalId
                || !exactGlobalIds.Contains(objectGlobalId))
                continue;
            var (_, propertySetType, propertySetArgs) = w.EntityAt(propertySetIndex);
            var nameMatch = PropertySetName.Match(propertySetArgs);
            if (propertySetType != "IFCPROPERTYSET" || !nameMatch.Success
                || StepWriter.Unescape(nameMatch.Groups[1].Value) is not { } name)
                continue;

            string propertySetGlobalId = IfcGuid.FromMd5($"IfcPropertySet:{name}:{objectGlobalId}");
            string relationGlobalId = IfcGuid.FromMd5($"IfcRelDefinesByProperties::{propertySetGlobalId}");
            if (globalIds.Contains(propertySetGlobalId) || globalIds.Contains(relationGlobalId)) continue;
            globalIds.Remove(FirstGlobalId(propertySetArgs)!);
            globalIds.Remove(FirstGlobalId(args)!);
            globalIds.Add(propertySetGlobalId);
            globalIds.Add(relationGlobalId);
            w.ReplaceArgs(propertySetIndex, $"'{propertySetGlobalId}'{propertySetArgs[24..]}");
            w.ReplaceArgs(i, $"'{relationGlobalId}'{args[24..]}");
            renamed++;
        }
        return renamed;
    }

    private static string? FirstGlobalId(string args) =>
        args.Length >= 24 && args[0] == '\'' && args[23] == '\'' ? args[1..23] : null;

    /// <summary>
    /// Resolve both atomically against the complete initial writer: ambiguous owners or GUID
    /// collisions keep legacy IDs.
    /// </summary>
    internal static (int Types, int Relationships) ApplyTypeGlobalIds(
        StepWriter w, IReadOnlyDictionary<int, string> exactTypeGuids)
    {
        if (exactTypeGuids.Count == 0) return (0, 0);
        var globalIdCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        var desiredIdCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        var typeIndexes = new Dictionary<int, int>();
        var typeClassById = new Dictionary<int, string>();
        var owners = new Dictionary<int, List<int>>();
        foreach (string globalId in exactTypeGuids.Values)
        {
            desiredIdCounts[globalId] = desiredIdCounts.GetValueOrDefault(globalId) + 1;
            string relationGlobalId = IfcGuid.FromMd5($"IfcRelDefinesByType:{globalId}");
            desiredIdCounts[relationGlobalId] = desiredIdCounts.GetValueOrDefault(relationGlobalId) + 1;
        }
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (id, type, args) = w.EntityAt(i);
            if (FirstGlobalId(args) is { } globalId)
                globalIdCounts[globalId] = globalIdCounts.GetValueOrDefault(globalId) + 1;
            if (exactTypeGuids.ContainsKey(id)) { typeIndexes[id] = i; typeClassById[id] = type; }
            if (type != "IFCRELDEFINESBYTYPE") continue;
            string[] arguments = SplitStepArguments(args);
            if (arguments.Length != 6 || !TryEntityId(arguments[5], out int typeId)
                || !exactTypeGuids.ContainsKey(typeId))
                continue;
            if (!owners.TryGetValue(typeId, out var relations))
                owners[typeId] = relations = [];
            relations.Add(i);
        }

        var typeClasses = TypeClassByProductClass.Values.ToHashSet(StringComparer.Ordinal);
        typeClasses.UnionWith(CategoryRefinedTypeClasses);
        var sharedSegmentGuids = exactTypeGuids.GroupBy(pair => pair.Value, StringComparer.Ordinal)
            .Where(group => group.Count() > 1 && group.All(pair =>
                typeClassById.GetValueOrDefault(pair.Key) is "IFCPIPESEGMENTTYPE" or "IFCDUCTSEGMENTTYPE" or "IFCTYPEPRODUCT"))
            .Select(group => group.Key).ToHashSet(StringComparer.Ordinal);
        var rewrites = new List<(int TypeIndex, int RelationIndex, string TypeGuid, string RelationGuid)>();
        foreach (var (typeId, typeGlobalId) in exactTypeGuids)
        {
            if (IfcGuid.Parse(typeGlobalId) == null
                || !typeIndexes.TryGetValue(typeId, out int typeIndex)
                || !owners.TryGetValue(typeId, out var relations) || relations.Count != 1)
                continue;
            var (_, typeClass, typeArgs) = w.EntityAt(typeIndex);
            int relationIndex = relations[0];
            string relationArgs = w.EntityAt(relationIndex).Args;
            string[] arguments = SplitStepArguments(relationArgs);
            if (!typeClasses.Contains(typeClass)
                || !HasGuidAttribute(typeArgs) || !HasGuidAttribute(relationArgs)
                || arguments[4].Length < 3 || arguments[4][0] != '(' || arguments[4][^1] != ')'
                || !SplitStepArguments(arguments[4][1..^1]).All(arg => TryEntityId(arg, out _)))
                continue;
            string relationGlobalId = IfcGuid.FromMd5($"IfcRelDefinesByType:{typeGlobalId}");
            if (!sharedSegmentGuids.Contains(typeGlobalId)
                && (desiredIdCounts[typeGlobalId] != 1 || desiredIdCounts[relationGlobalId] != 1)
                || !Available(typeGlobalId, typeArgs) || !Available(relationGlobalId, relationArgs))
                continue;
            rewrites.Add((typeIndex, relationIndex, typeGlobalId, relationGlobalId));
        }

        int types = 0, relationships = 0;
        foreach (var rewrite in rewrites)
        {
            string typeArgs = w.EntityAt(rewrite.TypeIndex).Args;
            string relationArgs = w.EntityAt(rewrite.RelationIndex).Args;
            if (FirstGlobalId(typeArgs) != rewrite.TypeGuid)
            {
                w.ReplaceArgs(rewrite.TypeIndex, $"'{rewrite.TypeGuid}'{typeArgs[24..]}");
                types++;
            }
            if (FirstGlobalId(relationArgs) != rewrite.RelationGuid)
            {
                w.ReplaceArgs(rewrite.RelationIndex, $"'{rewrite.RelationGuid}'{relationArgs[24..]}");
                relationships++;
            }
        }
        return (types, relationships);

        bool Available(string desired, string args) => globalIdCounts.GetValueOrDefault(desired) == 0
            || (FirstGlobalId(args) == desired && globalIdCounts[desired] == 1);
        static bool HasGuidAttribute(string args) => args.Length > 24 && args[24] == ','
            && FirstGlobalId(args) is { } globalId && IfcGuid.Parse(globalId) != null;
        static bool TryEntityId(string arg, out int id)
        {
            id = 0;
            return arg.Length > 1 && arg[0] == '#'
                && int.TryParse(arg.AsSpan(1), NumberStyles.None, CultureInfo.InvariantCulture, out id) && id > 0;
        }
    }

    /// <summary>
    /// The property-set rule uses the MD5 of "IfcPropertySet:{decoded
    /// name}:{written type GlobalId}".
    /// </summary>
    internal static int ApplyTypePropertySetGlobalIds(
        StepWriter w, IReadOnlyDictionary<int, string> exactTypeGuids)
    {
        if (exactTypeGuids.Count == 0) return 0;
        var globalIdCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        var validationCounts = exactTypeGuids.Values.GroupBy(value => value, StringComparer.Ordinal)
            .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);
        var typeIndexes = new Dictionary<int, int>();
        var psetIndexes = new Dictionary<int, int>();
        var duplicateIds = new HashSet<int>();
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (id, type, args) = w.EntityAt(i);
            if (FirstGlobalId(args) is { } guid)
                globalIdCounts[guid] = globalIdCounts.GetValueOrDefault(guid) + 1;
            if (exactTypeGuids.ContainsKey(id) && !typeIndexes.TryAdd(id, i))
                duplicateIds.Add(id);
            if (type == "IFCPROPERTYSET" && !psetIndexes.TryAdd(id, i))
                duplicateIds.Add(id);
        }

        // Count actual unquoted references in the whole writer, not just references from recognised
        // type classes.
        var references = new Dictionary<int, int>();
        var relevantIdCounts = new Dictionary<int, int>();
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (entityId, _, args) = w.EntityAt(i);
            if (psetIndexes.ContainsKey(entityId) || exactTypeGuids.ContainsKey(entityId))
            {
                int count = relevantIdCounts.GetValueOrDefault(entityId) + 1;
                relevantIdCounts[entityId] = count;
                if (count > 1) duplicateIds.Add(entityId);
            }
            bool quoted = false;
            for (int p = 0; p < args.Length; p++)
            {
                if (args[p] == '\'') { quoted = !quoted; continue; }
                if (quoted || args[p] != '#') continue;
                int start = ++p;
                while (p < args.Length && char.IsAsciiDigit(args[p])) p++;
                if (int.TryParse(args.AsSpan(start, p - start), NumberStyles.None,
                    CultureInfo.InvariantCulture, out int target) && psetIndexes.ContainsKey(target))
                    references[target] = references.GetValueOrDefault(target) + 1;
                p--;
            }
        }

        var typeClasses = TypeClassByProductClass.Values.ToHashSet(StringComparer.Ordinal);
        typeClasses.UnionWith(CategoryRefinedTypeClasses);
        var candidates = new List<(int Index, string Current, string Desired)>();
        var desiredCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var (id, exactGuid) in exactTypeGuids)
        {
            if (duplicateIds.Contains(id) || validationCounts[exactGuid] != 1
                || IfcGuid.Parse(exactGuid) == null || globalIdCounts.GetValueOrDefault(exactGuid) != 1
                || !typeIndexes.TryGetValue(id, out int index)) continue;
            var (_, typeClass, typeArgs) = w.EntityAt(index);
            if (!typeClasses.Contains(typeClass) || FirstGlobalId(typeArgs) != exactGuid) continue;
            string[] typeArguments = SplitStepArguments(typeArgs);
            if (typeArguments.Length < 8 || typeArguments[5].Length < 3
                || typeArguments[5][0] != '(' || typeArguments[5][^1] != ')') continue;
            string[] slots = SplitStepArguments(typeArguments[5][1..^1]);
            if (!slots.All(slot => TryPsetId(slot, out _))) continue;
            foreach (string slot in slots)
            {
                _ = TryPsetId(slot, out int psetId);
                if (duplicateIds.Contains(psetId) || references.GetValueOrDefault(psetId) != 1
                    || !psetIndexes.TryGetValue(psetId, out int psetIndex)) continue;
                string psetArgs = w.EntityAt(psetIndex).Args;
                if (FirstGlobalId(psetArgs) is not { } current || IfcGuid.Parse(current) == null
                    || globalIdCounts.GetValueOrDefault(current) != 1) continue;
                var name = PropertySetName.Match(psetArgs);
                if (!name.Success || StepWriter.Unescape(name.Groups[1].Value) is not { } decodedName) continue;
                string desired = IfcGuid.FromMd5($"IfcPropertySet:{decodedName}:{exactGuid}");
                candidates.Add((psetIndex, current, desired));
                desiredCounts[desired] = desiredCounts.GetValueOrDefault(desired) + 1;
            }
        }

        int renamed = 0;
        foreach (var candidate in candidates)
        {
            if (desiredCounts[candidate.Desired] != 1 || candidate.Current == candidate.Desired
                || globalIdCounts.GetValueOrDefault(candidate.Desired) != 0) continue;
            string args = w.EntityAt(candidate.Index).Args;
            w.ReplaceArgs(candidate.Index, $"'{candidate.Desired}'{args[24..]}");
            renamed++;
        }
        return renamed;

        static bool TryPsetId(string slot, out int id)
        {
            id = 0;
            return slot.Length > 1 && slot[0] == '#'
                && int.TryParse(slot.AsSpan(1), NumberStyles.None, CultureInfo.InvariantCulture, out id) && id > 0;
        }
    }

    /// <summary>How a delayed door or window opening is built: from the cutout extrusion of the exported instance or from the solids of the host wall opening data.</summary>
    internal enum DoorWindowOpeningKind { Extrusion, Solid }

    /// <summary>
    /// The GlobalId of a delayed door/window opening: the GlobalId rule applied to <c>(door, "Level:
    /// {levelId}" + " IfcOpeningElement: 0")</c> for an extrusion and <c>"Level:
    /// {levelId}IfcOpeningElement: 0"</c> (no space) for a solid.
    /// </summary>
    internal static string DoorWindowOpeningGlobalId(
        Guid doorExportId, int levelId, DoorWindowOpeningKind kind, bool currentProfile = false) =>
        IfcGuid.FromMd5(IfcGuid.ToIfcGuid(doorExportId) + "Sub-element:"
            + $"Level: {levelId.ToString(CultureInfo.InvariantCulture)}"
            + (kind == DoorWindowOpeningKind.Extrusion || currentProfile ? " " : "") + "IfcOpeningElement: 0");

    /// <summary>
    /// Applied after all entities are written; an opening is left as it is when its Tag, host,
    /// symbol, storey or export id is not exact, when another opening of the same host has the same
    /// Tag, or when the GUID is already in the file.
    /// </summary>
    internal static HashSet<string> ApplyDoorWindowOpeningIdentities(
        StepWriter w,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> productElementIdByEntity,
        IReadOnlyDictionary<int, int> levelIdByProductElementId,
        IReadOnlySet<string> exactGlobalIds,
        bool currentProfile = false,
        Dictionary<int, (int Group, int Major, int Minor)>? orderKeys = null)
    {
        const int DoorsCategoryId = -2000023, WindowsCategoryId = -2000014, WallsCategoryId = -2000011;
        var indexById = new Dictionary<int, int>(w.EntityCount);
        var globalIds = new HashSet<string>(StringComparer.Ordinal);
        var voidByOpening = new Dictionary<int, (int Index, int Host)>();
        var fillByOpening = new Dictionary<int, (int Index, int Door)>();
        var openings = new List<int>();
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (id, type, args) = w.EntityAt(i);
            indexById[id] = i;
            if (FirstGlobalId(args) is { } globalId) globalIds.Add(globalId);
            if (type == "IFCOPENINGELEMENT") openings.Add(i);
            else if (type is "IFCRELVOIDSELEMENT" or "IFCRELFILLSELEMENT")
            {
                var references = EntityReference.Matches(args);
                if (references.Count < 3) continue;
                int relating = int.Parse(references[^2].Groups[1].ValueSpan, CultureInfo.InvariantCulture);
                int related = int.Parse(references[^1].Groups[1].ValueSpan, CultureInfo.InvariantCulture);
                if (type == "IFCRELVOIDSELEMENT") voidByOpening[related] = (i, relating);
                else fillByOpening[relating] = (i, related);
            }
        }

        var productElementIds = productElementIdByEntity.Values.ToHashSet();
        var parsed = new List<(int Index, string[] Args, int Host, int Tag)>();
        var openingsPerHostTag = new Dictionary<(int Host, int Tag), int>();
        foreach (int index in openings)
        {
            var (id, _, args) = w.EntityAt(index);
            string[] arguments = SplitStepArguments(args);
            if (arguments.Length != 8 || !voidByOpening.TryGetValue(id, out var voids)
                || arguments[7].Length < 3 || arguments[7][0] != '\''
                || !int.TryParse(arguments[7].AsSpan(1, arguments[7].Length - 2), NumberStyles.Integer,
                    CultureInfo.InvariantCulture, out int tag))
                continue;
            parsed.Add((index, arguments, voids.Host, tag));
            openingsPerHostTag[(voids.Host, tag)] = openingsPerHostTag.GetValueOrDefault((voids.Host, tag)) + 1;
        }

        var assigned = new HashSet<string>(StringComparer.Ordinal);
        foreach (var (index, arguments, hostEntity, tag) in parsed)
        {
            int openingEntity = w.EntityAt(index).Id;
            if (openingsPerHostTag[(hostEntity, tag)] != 1
                || !elementsById.TryGetValue(tag, out Element? insert)
                || insert.CategoryId is not (DoorsCategoryId or WindowsCategoryId)
                || insert.SerializedExportId is not Guid insertExportId
                || !productElementIdByEntity.TryGetValue(hostEntity, out int hostId)
                || !elementsById.TryGetValue(hostId, out Element? host)
                || host.CategoryId != WallsCategoryId
                || insert.SerializedHostId != host.Id
                || !indexById.TryGetValue(hostEntity, out int hostIndex))
                continue;
            var (_, hostType, hostArgs) = w.EntityAt(hostIndex);
            if (hostType is not ("IFCWALL" or "IFCWALLSTANDARDCASE")) continue;

            int? doorEntity = fillByOpening.TryGetValue(openingEntity, out var fill) ? fill.Door : null;
            bool written = doorEntity is int filledBy
                && productElementIdByEntity.TryGetValue(filledBy, out int filledById) && filledById == insert.Id;
            if (doorEntity != null && !written) continue;
            if (doorEntity == null && productElementIds.Contains(insert.Id)) continue;
            // An IFC class override can take the instance off the door/window path.
            if (HasIfcTypeOverride(insert, unsetIntegerIsNoOverride: true)
                || insert.FamilyTypeId > 0 && elementsById.TryGetValue(insert.FamilyTypeId, out Element? insertType)
                    && HasIfcTypeOverride(insertType, unsetIntegerIsNoOverride: true))
                continue;

            DoorWindowOpeningKind kind = DoorWindowOpeningKind.Solid;
            if (written)
            {
                if (insert.FamilyTypeId <= 0
                    || !elementsById.TryGetValue(insert.FamilyTypeId, out Element? symbol)
                    || symbol.SerializedCutLoopCount is not int cutLoopCount)
                    continue;
                if (cutLoopCount > 0) kind = DoorWindowOpeningKind.Extrusion;
            }
            if (!levelIdByProductElementId.TryGetValue(written ? insert.Id : host.Id, out int levelId))
                continue;

            string openingGlobalId = DoorWindowOpeningGlobalId(insertExportId, levelId, kind, currentProfile);
            if (globalIds.Contains(openingGlobalId)) continue;

            string name = arguments[2];
            bool nameOverride = insert.Parameters.Any(parameter =>
                ParameterNameEquals(parameter, "IfcName") || ParameterNameEquals(parameter, "NameOverride"));
            if (!nameOverride)
            {
                if (kind == DoorWindowOpeningKind.Solid)
                    name = SplitStepArguments(hostArgs) is { Length: > 2 } hostArguments ? hostArguments[2] : name;
                else if (indexById.TryGetValue(doorEntity!.Value, out int doorIndex)
                    && SplitStepArguments(w.EntityAt(doorIndex).Args) is { Length: > 2 } doorArguments
                    && doorArguments[2].Length >= 2 && doorArguments[2][0] == '\'')
                    // The current profile no longer appends the opening index (the NamePlusIndex
                    // override is commented out).
                    name = currentProfile ? doorArguments[2] : doorArguments[2][..^1] + ":1'";
            }

            globalIds.Remove(arguments[0][1..^1]);
            globalIds.Add(openingGlobalId);
            assigned.Add(openingGlobalId);
            arguments[0] = $"'{openingGlobalId}'";
            arguments[2] = name;
            w.ReplaceArgs(index, string.Join(",", arguments));
            if (orderKeys != null) orderKeys[openingEntity] = (OpeningOrderDelayed, insert.Id, 0);

            var (voidIndex, _) = voidByOpening[openingEntity];
            string? hostGlobalId = FirstGlobalId(hostArgs);
            string? voidGlobalId = kind == DoorWindowOpeningKind.Extrusion
                ? IfcGuid.ToIfcGuid(ElementExportIds.SubElementId(insertExportId, DoorOpeningRelVoid))
                : hostGlobalId != null && exactGlobalIds.Contains(hostGlobalId)
                    ? IfcGuid.FromMd5($"IfcRelVoidsElement:{hostGlobalId}{openingGlobalId}")
                    : null;
            ReplaceRelationGlobalId(w, voidIndex, voidGlobalId, globalIds);

            if (written && indexById.TryGetValue(doorEntity!.Value, out int filledIndex)
                && FirstGlobalId(w.EntityAt(filledIndex).Args) is { } doorGlobalId
                && exactGlobalIds.Contains(doorGlobalId))
                ReplaceRelationGlobalId(w, fill.Index,
                    IfcGuid.FromMd5($"IfcRelFillsElement:{openingGlobalId}{doorGlobalId}"), globalIds);
        }
        return assigned;
    }

    private const int SketchLinesCategoryId = -2000045;

    private static string? CutOpeningName(
        StepWriter w, int hostEntity, int tag,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> productElementIdByEntity,
        IReadOnlyDictionary<int, int> indexById)
    {
        if (!elementsById.TryGetValue(tag, out Element? cutter)
            || !productElementIdByEntity.TryGetValue(hostEntity, out int hostId)
            || tag == hostId
            || !elementsById.TryGetValue(hostId, out Element? host)
            || cutter.CategoryId is -2000023 or -2000014 && cutter.SerializedHostId == hostId
            || cutter.Parameters.Any(parameter =>
                ParameterNameEquals(parameter, "IfcName") || ParameterNameEquals(parameter, "NameOverride"))
            || !indexById.TryGetValue(hostEntity, out int hostIndex)
            || SplitStepArguments(w.EntityAt(hostIndex).Args) is not { Length: > 2 } hostArguments
            || hostArguments[2].Length < 2 || hostArguments[2][0] != '\'')
            return null;
        if (cutter.CategoryId != SketchLinesCategoryId) return hostArguments[2];
        return host.FamilyTypeId is > 0 and int hostTypeId
            ? SketchOpeningName(hostArguments[2], host.Id, hostTypeId)
            : null;
    }

    /// <summary>Null when the host's Name is not of that form.</summary>
    internal static string? SketchOpeningName(string hostNameArgument, int hostId, int hostTypeId)
    {
        string suffix = $":{hostId.ToString(CultureInfo.InvariantCulture)}'";
        return hostNameArgument.Length > suffix.Length + 1 && hostNameArgument[0] == '\''
            && hostNameArgument.EndsWith(suffix, StringComparison.Ordinal)
                ? $"{hostNameArgument[..^suffix.Length]}:{hostTypeId.ToString(CultureInfo.InvariantCulture)}'"
                : null;
    }

    private static bool IsWallRectangularOpening(Element element) =>
        element.Category?.Contains("OST_SWallRectOpening", StringComparison.OrdinalIgnoreCase) == true;

    // The door sub-element rule (= WindowOpeningRelVoid).
    internal const int DoorOpeningRelVoid = 20;

    /// <summary>
    /// The GlobalId of an opening cut with a solid:
    /// the MD5 of
    /// "Opening:{openingIndex}Solid:{solidIndex}{host export GlobalId}{cutter export GlobalId}" (no
    /// level range.
    /// </summary>
    internal static string CutOpeningGlobalId(Guid hostExportId, Guid cutterExportId, int openingIndex, int solidIndex) =>
        IfcGuid.FromMd5(string.Create(CultureInfo.InvariantCulture, $"Opening:{openingIndex}Solid:{solidIndex}")
            + IfcGuid.ToIfcGuid(hostExportId) + IfcGuid.ToIfcGuid(cutterExportId));

    /// <summary>
    /// An opening is left as it is when the host's steps are not decoded, its Tag is not among
    /// them, another opening of the host has the same Tag, an export id is missing or the GUID is
    /// already in the file.
    /// </summary>
    internal static HashSet<string> ApplyCutOpeningIdentities(
        StepWriter w,
        IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> productElementIdByEntity,
        IReadOnlySet<string> exactGlobalIds,
        IReadOnlySet<string> doorWindowOpeningGlobalIds,
        bool currentProfile = false,
        IReadOnlyDictionary<int, HashSet<int>>? unbuiltCutters = null,
        Dictionary<int, (int Group, int Major, int Minor)>? orderKeys = null)
    {
        var indexById = new Dictionary<int, int>(w.EntityCount);
        var globalIds = new HashSet<string>(StringComparer.Ordinal);
        var voidByOpening = new Dictionary<int, (int Index, int Host)>();
        var openings = new List<int>();
        for (int i = 0; i < w.EntityCount; i++)
        {
            var (id, type, args) = w.EntityAt(i);
            indexById[id] = i;
            if (FirstGlobalId(args) is { } globalId) globalIds.Add(globalId);
            if (type == "IFCOPENINGELEMENT") openings.Add(i);
            else if (type == "IFCRELVOIDSELEMENT")
            {
                var references = EntityReference.Matches(args);
                if (references.Count < 3) continue;
                voidByOpening[int.Parse(references[^1].Groups[1].ValueSpan, CultureInfo.InvariantCulture)] =
                    (i, int.Parse(references[^2].Groups[1].ValueSpan, CultureInfo.InvariantCulture));
            }
        }

        var parsed = new List<(int Index, string[] Args, int Host, int Tag)>();
        var tagsByHost = new Dictionary<int, Dictionary<int, int>>();
        foreach (int index in openings)
        {
            var (id, _, args) = w.EntityAt(index);
            string[] arguments = SplitStepArguments(args);
            if (arguments.Length != 8 || !voidByOpening.TryGetValue(id, out var voids)
                || arguments[7].Length < 3 || arguments[7][0] != '\''
                || !int.TryParse(arguments[7].AsSpan(1, arguments[7].Length - 2), NumberStyles.Integer,
                    CultureInfo.InvariantCulture, out int tag))
                continue;
            parsed.Add((index, arguments, voids.Host, tag));
            if (!tagsByHost.TryGetValue(voids.Host, out var tags)) tagsByHost[voids.Host] = tags = new();
            tags[tag] = tags.GetValueOrDefault(tag) + 1;
        }

        var ranksByHost = new Dictionary<int, Dictionary<int, int>?>();
        Dictionary<int, int>? Ranks(int hostEntity)
        {
            if (ranksByHost.TryGetValue(hostEntity, out var cached)) return cached;
            Dictionary<int, int>? ranks = null;
            // The current profile numbers the cutters of the cut-out phases in step order, the
            // host-to-host cut pairs included.
            IEnumerable<int>? cutterOrder = null;
            if (productElementIdByEntity.TryGetValue(hostEntity, out int hostId)
                && elementsById.TryGetValue(hostId, out Element? host)
                && (currentProfile && host.CutOutSteps is { } cutOutSteps
                    ? (cutterOrder = cutOutSteps.Select(step => step.ElementId)) != null
                    : (cutterOrder = host.CuttingElementIds) != null))
            {
                ranks = new Dictionary<int, int>();
                foreach (int rectangularOpening in tagsByHost[hostEntity].Keys.Where(tag =>
                             elementsById.TryGetValue(tag, out Element? opening) && IsWallRectangularOpening(opening)).Order())
                    ranks[rectangularOpening] = ranks.Count + 1;
                HashSet<int>? unbuilt = null;
                if (currentProfile) unbuiltCutters?.TryGetValue(hostId, out unbuilt);
                foreach (int cutter in cutterOrder!)
                    if ((tagsByHost[hostEntity].ContainsKey(cutter) || unbuilt?.Contains(cutter) == true) && !ranks.ContainsKey(cutter))
                        ranks[cutter] = ranks.Count + 1;
            }
            return ranksByHost[hostEntity] = ranks;
        }

        var sketchIndexByHost = new Dictionary<int, Dictionary<int, int>?>();
        Dictionary<int, int>? SketchIndexes(int hostEntity)
        {
            if (sketchIndexByHost.TryGetValue(hostEntity, out var cached)) return cached;
            Dictionary<int, int>? indexes = null;
            if (productElementIdByEntity.TryGetValue(hostEntity, out int hostId))
            {
                int others = 0;
                var keys = new Dictionary<int, int>();
                bool validated = true;
                foreach (var (tag, count) in tagsByHost[hostEntity])
                {
                    if (tag == hostId) continue;
                    if (!elementsById.TryGetValue(tag, out Element? cutter)
                        || cutter.CategoryId != SketchLinesCategoryId)
                    {
                        others += count;
                        continue;
                    }
                    if (count != 1 || cutter.SketchLoopKey is not int key) { validated = false; continue; }
                    keys[tag] = key;
                }
                if (validated && keys.Count > 0 && keys.Values.Distinct().Count() == keys.Count)
                {
                    var order = keys.Values.Order().Select((key, rank) => (key, rank)).ToDictionary(item => item.key, item => item.rank);
                    // The current profile numbers the host extrusion's openings from the last loop
                    //.
                    indexes = keys.ToDictionary(item => item.Key,
                        item => currentProfile ? keys.Count - order[item.Value] : others + order[item.Value] + 1);
                }
            }
            return sketchIndexByHost[hostEntity] = indexes;
        }

        var assigned = new HashSet<string>(StringComparer.Ordinal);
        foreach (var (index, arguments, hostEntity, tag) in parsed)
        {
            if (currentProfile && elementsById.TryGetValue(tag, out Element? sketchCutter)
                && sketchCutter.CategoryId == SketchLinesCategoryId)
            {
                if (tagsByHost[hostEntity][tag] == 1
                    && SketchIndexes(hostEntity) is { } loopNumbers && loopNumbers.TryGetValue(tag, out int loopNumber)
                    && indexById.TryGetValue(hostEntity, out int loopHostIndex)
                    && FirstGlobalId(w.EntityAt(loopHostIndex).Args) is { } loopHostGlobalId
                    && exactGlobalIds.Contains(loopHostGlobalId)
                    && SplitStepArguments(w.EntityAt(loopHostIndex).Args) is { Length: > 2 } loopHostArguments
                    && loopHostArguments[2].Length >= 2 && loopHostArguments[2][0] == '\'')
                {
                    string loopGlobalId = IfcGuid.FromMd5(string.Create(
                        CultureInfo.InvariantCulture, $"IfcOpeningElement:{loopNumber}:{loopHostGlobalId}"));
                    if (!globalIds.Contains(loopGlobalId))
                    {
                        globalIds.Remove(arguments[0][1..^1]);
                        globalIds.Add(loopGlobalId);
                        assigned.Add(loopGlobalId);
                        arguments[0] = $"'{loopGlobalId}'";
                        arguments[2] = string.Create(CultureInfo.InvariantCulture,
                            $"{loopHostArguments[2][..^1]}:{loopNumber}'");
                        w.ReplaceArgs(index, string.Join(",", arguments));
                        if (orderKeys != null) orderKeys[w.EntityAt(index).Id] = (OpeningOrderOwnLoop, loopNumber, 0);
                        ReplaceRelationGlobalId(w, voidByOpening[w.EntityAt(index).Id].Index,
                            IfcGuid.FromMd5($"IfcRelVoidsElement:{loopHostGlobalId}{loopGlobalId}"), globalIds);
                    }
                }
                continue;
            }

            // The door/window path and the host's own extrusion openings (Tag = host) are named
            // otherwise.
            if (!doorWindowOpeningGlobalIds.Contains(arguments[0].Trim('\''))
                && CutOpeningName(w, hostEntity, tag, elementsById, productElementIdByEntity, indexById)
                    is { } cutOpeningName
                && cutOpeningName != arguments[2])
            {
                arguments[2] = cutOpeningName;
                w.ReplaceArgs(index, string.Join(",", arguments));
            }

            int openingIndex = 0;
            if (doorWindowOpeningGlobalIds.Contains(arguments[0].Trim('\''))
                || tagsByHost[hostEntity][tag] != 1
                || !(SketchIndexes(hostEntity) is { } sketchIndexes && sketchIndexes.TryGetValue(tag, out openingIndex)
                    || Ranks(hostEntity) is { } ranks && ranks.TryGetValue(tag, out openingIndex))
                || !elementsById.TryGetValue(tag, out Element? cutter)
                || cutter.SerializedExportId is not Guid cutterExportId
                || !elementsById.TryGetValue(productElementIdByEntity[hostEntity], out Element? host)
                || host.SerializedExportId is not Guid hostExportId
                || !indexById.TryGetValue(hostEntity, out int hostIndex))
                continue;
            // The current profile counts the solids of a wall opening (the first loop of the openings step) from 0, those of every other cutter (its second loop) from 1.
            int solidIndex = currentProfile && IsWallRectangularOpening(cutter) ? 0 : 1;
            string openingGlobalId = CutOpeningGlobalId(hostExportId, cutterExportId, openingIndex, solidIndex);
            if (globalIds.Contains(openingGlobalId)) continue;

            string hostArgs = w.EntityAt(hostIndex).Args;
            int openingEntity = w.EntityAt(index).Id;
            if (orderKeys != null) orderKeys[openingEntity] = (OpeningOrderCutter, openingIndex, solidIndex);
            globalIds.Remove(arguments[0][1..^1]);
            globalIds.Add(openingGlobalId);
            assigned.Add(openingGlobalId);
            arguments[0] = $"'{openingGlobalId}'";
            w.ReplaceArgs(index, string.Join(",", arguments));

            string? hostGlobalId = FirstGlobalId(hostArgs);
            ReplaceRelationGlobalId(w, voidByOpening[openingEntity].Index,
                hostGlobalId != null && exactGlobalIds.Contains(hostGlobalId)
                    ? IfcGuid.FromMd5($"IfcRelVoidsElement:{hostGlobalId}{openingGlobalId}")
                    : null,
                globalIds);
        }
        return assigned;
    }

    private static void ReplaceRelationGlobalId(StepWriter w, int index, string? globalId, HashSet<string> globalIds)
    {
        string args = w.EntityAt(index).Args;
        if (globalId == null || globalIds.Contains(globalId) || FirstGlobalId(args) is not { } current) return;
        globalIds.Remove(current);
        globalIds.Add(globalId);
        w.ReplaceArgs(index, $"'{globalId}'{args[24..]}");
    }

    /// <summary>
    /// The top-level arguments of a STEP entity's argument list, split at commas outside strings
    /// and nested lists.
    /// </summary>
    internal static string[] SplitStepArguments(string args)
    {
        var result = new List<string>();
        int depth = 0, start = 0;
        bool inString = false;
        for (int i = 0; i < args.Length; i++)
        {
            char c = args[i];
            if (c == '\'') inString = !inString;
            else if (inString) continue;
            else if (c == '(') depth++;
            else if (c == ')') depth--;
            else if (c == ',' && depth == 0)
            {
                result.Add(args[start..i]);
                start = i + 1;
            }
        }
        result.Add(args[start..]);
        return result.ToArray();
    }

    internal const int StoreyRelContainedInSpatialStructure = 1;
    internal const int StoreyRelAggregates = 2;
    internal const int ProjectRelAggregatesBuildingStories = 3;
    internal const int CurtainWallRelAggregates = 1024;
    private const int ProjectInformationCategoryId = -2003101;

    /// <summary>GlobalId of the containment relation of an exact container: the MD5 name hash of "IfcRelContainedInSpatialStructure:{container GlobalId}".</summary>
    internal static string? ContainmentCacheGlobalId(string? exactContainerGlobalId) =>
        exactContainerGlobalId == null ? null : IfcGuid.FromMd5($"IfcRelContainedInSpatialStructure:{exactContainerGlobalId}");

    /// <summary>
    /// IfcRelConnectsPathElements GlobalId: the GlobalId string of (IfcRelConnectsPathElements, key), the
    /// MD5 of the project GlobalId, "IfcRelConnectsPathElements:", the relation name ("{relating
    /// GlobalId}|{related GlobalId}") and the two connection types as written (related.
    /// </summary>
    internal static string WallPathConnectionGlobalId(
        string projectGlobalId, string name, string relatedType, string relatingType) =>
        IfcGuid.FromMd5($"{projectGlobalId}IfcRelConnectsPathElements:{name}:"
            + $"{ConnectionTypeName(relatedType)}:{ConnectionTypeName(relatingType)}");

    private static string ConnectionTypeName(string stepEnum) => stepEnum switch
    {
        "ATSTART" => "AtStart",
        "ATEND" => "AtEnd",
        "ATPATH" => "AtPath",
        "NOTDEFINED" => "NotDefined",
        _ => throw new ArgumentOutOfRangeException(nameof(stepEnum), stepEnum, null),
    };

    /// <summary>
    /// The model's ProjectInformation element, when exactly one element id carries that category.
    /// </summary>
    private static Element? SoleProjectInformation(RevitFileInfo info)
    {
        var candidates = info.Elements.Where(element => element.CategoryId == ProjectInformationCategoryId).ToList();
        return candidates.Select(element => element.Id).Distinct().Count() == 1 ? candidates[0] : null;
    }

    private static bool IsIfcGuidParameterId(int? id) =>
        id is (int)BuiltIns.BuiltInParameter.IFC_GUID or (int)BuiltIns.BuiltInParameter.IFC_TYPE_GUID;
    private static bool HasIfcGuidOverride(IEnumerable<Parameter> parameters, bool currentProfile) =>
        !currentProfile && parameters.Any(parameter =>
            (IsIfcGuidParameterId(parameter.Id) || IsIfcGuidParameterId(parameter.Definition?.Id))
            && parameter.StorageType == StorageType.String && parameter.Value is string { Length: > 0 });

    /// <summary>Pset_WallCommon.ExtendToStructure.</summary>
    internal static bool? ResolveWallExtendToStructure(Element wall, bool currentProfile = false)
    {
        if (wall.CategoryId != -2000011) return null;
        ExactIsExternalParameterResult named =
            ResolveExactNamedIntParameter(wall, "ExtendToStructure");
        if (named.State == ExactIsExternalParameterState.Value) return named.Value != 0;
        if (named.State == ExactIsExternalParameterState.Blocked) return null;
        return wall.SerializedWallJoinedToTop ?? (currentProfile ? false : null);
    }

    /// <summary>
    /// This method is reached only after the same emitted wall product has successfully emitted
    /// Pset_QuantityTakeOff.Reference.
    /// </summary>
    private static void ExportReinforcementBarPitchOfWallPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string referenceValue)
    {
        int referenceValueId = w.Add("IFCPROPERTYSINGLEVALUE",
            $"{S("Reference")},$,IFCLABEL({S(referenceValue)}),$");
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"reinforcement-bar-pitch-wall-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_ReinforcementBarPitchOfWall")},$,{StepWriter.List(R(referenceValueId))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"reinforcement-bar-pitch-wall-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }


    private const int FloorParamIsStructuralId = -1001954;

    private static ExactIsExternalParameterResult ResolveExactFloorParamIsStructural(
        Element element)
    {
        if (element.CategoryId != FloorCategoryId)
            return new(ExactIsExternalParameterState.Absent);

        List<Parameter> matches = element.Parameters
            .Where(parameter => parameter.Definition?.Id == FloorParamIsStructuralId)
            .ToList();
        if (matches.Count == 0)
            return new(ExactIsExternalParameterState.Absent);

        var candidates = new List<ExactIsExternalParameterResult>(matches.Count);
        foreach (Parameter parameter in matches)
        {
            if (parameter.IsApproximate
                || parameter.StorageType != StorageType.Integer
                || parameter.Value is not int integerValue)
            {
                candidates.Add(new(ExactIsExternalParameterState.Blocked));
            }
            else
            {
                candidates.Add(new(
                    ExactIsExternalParameterState.Value, integerValue));
            }
        }
        return MergeExactIntCandidates(candidates);
    }

    /// <summary>
    /// Attaches the exact occurrence-only Pset_SlabCommon subset to a successfully emitted, tagged
    /// IFCSLAB product that already emitted Pset_QuantityTakeOff.
    /// </summary>
    private static void ExportSlabCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        int referenceValueId, bool isExternal, bool horizontal,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        double? thermalTransmittance = null)
    {
        var valueIds = new List<int>
        {
            GetOrAddPropertySingleValue(
                w, valuePool, "IsExternal", isExternal ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"),
            referenceValueId,
        };
        if (thermalTransmittance is double transmittance)
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "ThermalTransmittance", ThermalTransmittanceLiteralCurrent(transmittance)));

        ExactIsExternalParameterResult loadBearing =
            ResolveExactFloorParamIsStructural(elem);
        if (loadBearing.State == ExactIsExternalParameterState.Value)
        {
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "LoadBearing",
                loadBearing.Value != 0
                    ? "IFCBOOLEAN(.T.)"
                    : "IFCBOOLEAN(.F.)"));
        }

        if (horizontal)
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "PitchAngle", "IFCPLANEANGLEMEASURE(0.)"));

        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"slab-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_SlabCommon")},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"slab-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    private const int RampMinInverseSlopeParamId = -1008301;
    private const int BeamEnd0ElevationParamId = -1001571;
    private const int BeamEnd1ElevationParamId = -1001572;

    /// <summary>Whether Pset_SlabCommon.PitchAngle is exactly 0.</summary>
    internal static bool IsValidatedHorizontalSlab(Element slab, Element? type)
    {
        if (type == null || type.Id == slab.Id
            || slab.Parameters.Any(parameter =>
                ParameterNameEquals(parameter, "PitchAngle")
                || ParameterNameEquals(parameter, "Slope")
                || parameter.Id is RampMinInverseSlopeParamId
                    or BeamEnd0ElevationParamId or BeamEnd1ElevationParamId)
            || type.Parameters.Any(parameter => ParameterNameEquals(parameter, "Slope")))
            return false;

        GeometryData? geometry = slab.Geometry;
        if (geometry == null || geometry.BrepSolids is not { Count: > 0 } || geometry.Faces.Count == 0)
            return false;
        if (geometry.Transform is { Length: 12 } transform
            && (transform[2] != 0 || transform[6] != 0
                || transform[8] != 0 || transform[9] != 0 || transform[10] != 1))
            return false;

        double[] NormalOf(GeoFace face)
        {
            double[] fx = face.XVector, fy = face.YVector;
            return fx.Length == 3 && fy.Length == 3 && fx.Any(value => value != 0) && fy.Any(value => value != 0)
                ? [fx[1] * fy[2] - fx[2] * fy[1], fx[2] * fy[0] - fx[0] * fy[2], fx[0] * fy[1] - fx[1] * fy[0]]
                : face.Normal;
        }

        // Exactly horizontal: a serialized plane with no Z in either direction vector, or a
        // polygonal face without a serialized basis whose vertices all share one Z.
        static bool IsLevel(GeoFace face)
        {
            double[] x = face.XVector, y = face.YVector;
            if (x.Length != 3 || y.Length != 3) return false;
            if (x.Any(value => value != 0) && y.Any(value => value != 0)) return x[2] == 0 && y[2] == 0;
            if (face.OuterVertices is not { Count: >= 3 } outer) return false;
            double z = outer[0][2];
            return outer.All(vertex => vertex.Length == 3 && vertex[2] == z)
                && (face.InnerVertices ?? []).All(loop => loop.All(vertex => vertex.Length == 3 && vertex[2] == z));
        }

        // Exactly vertical: no Z in the plane's normal.
        bool IsPlumb(GeoFace face) => NormalOf(face) is { Length: 3 } normal && normal[2] == 0;

        var upward = new List<(GeoFace Face, double Area)>();
        foreach (GeoFace face in geometry.Faces)
        {
            if (NormalOf(face) is not { Length: 3 } normal || !(normal[2] > 0)) continue;
            double area = face.Area
                ?? PolygonAreaOf(face.OuterVertices) - (face.InnerVertices ?? []).Sum(PolygonAreaOf);
            upward.Add((face, area));
        }
        if (upward.Count == 0) return false;

        // Every face exactly horizontal or vertical: whichever face is the largest upward one is
        // level.
        if (geometry.Faces.All(face => IsLevel(face) || IsPlumb(face))) return true;

        // Otherwise the largest upward face must be level and unambiguous: a second upward face of
        // nearly the same area (a slab's mis-oriented underside) leaves the choice undetermined.
        var ordered = upward.OrderByDescending(item => item.Area).ToList();
        return ordered[0].Area > 0 && IsLevel(ordered[0].Face)
            && (ordered.Count == 1 || ordered[1].Area <= ordered[0].Area / 2);

        static double PolygonAreaOf(IReadOnlyList<double[]>? ring)
        {
            if (ring == null) return 0;
            double sx = 0, sy = 0, sz = 0;
            for (int index = 0; index < ring.Count; index++)
            {
                double[] a = ring[index], b = ring[(index + 1) % ring.Count];
                sx += a[1] * b[2] - a[2] * b[1];
                sy += a[2] * b[0] - a[0] * b[2];
                sz += a[0] * b[1] - a[1] * b[0];
            }
            return 0.5 * Math.Sqrt(sx * sx + sy * sy + sz * sz);
        }
    }

    /// <summary>
    /// Reached only after the same emitted IFCSLAB product has successfully emitted
    /// Pset_QuantityTakeOff.Reference.
    /// </summary>
    private static void ExportReinforcementBarPitchOfSlabPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string referenceValue)
    {
        int referenceValueId = w.Add("IFCPROPERTYSINGLEVALUE",
            $"{S("Reference")},$,IFCLABEL({S(referenceValue)}),$");
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"reinforcement-bar-pitch-slab-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_ReinforcementBarPitchOfSlab")},$,{StepWriter.List(R(referenceValueId))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"reinforcement-bar-pitch-slab-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }


    /// <summary>
    /// IsExternal only. Reached only after the same emitted IFCROOF product has successfully
    /// emitted Pset_QuantityTakeOff.Reference.
    /// </summary>
    internal static void ExportRoofCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool, int? referenceValueId,
        bool currentProfile = false, bool withArea = true)
    {
        int isExternalValueId = GetOrAddPropertySingleValue(
            w, valuePool, "IsExternal", "IFCBOOLEAN(.T.)");
        var values = new List<int> { isExternalValueId };
        if (referenceValueId.HasValue) values.Insert(0, referenceValueId.Value);
        if (withArea && elem.Parameters.FirstOrDefault(parameter => parameter.Id == -1012805)?.Value is double hostAreaFeet
            && double.IsFinite(hostAreaFeet) && hostAreaFeet > 0)
        {
            if (currentProfile && elem.ValidatedProfileRoofAreaFeet is double ownArea) hostAreaFeet = ownArea;
            // The current profile maps TotalArea to the same parameter and never computes
            // ProjectedArea.
            values.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                $"{S(currentProfile ? "TotalArea" : "ProjectedArea")},$,IFCAREAMEASURE({D17(hostAreaFeet * FeetToMetres * FeetToMetres)}),$"));
        }
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"roof-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_RoofCommon")},$,{StepWriter.List(values.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"roof-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    /// <summary>
    /// Looks up (or creates) the IfcPropertySingleValue instance for one (property name, value
    /// literal) pair in the shared pool, and returns its entity id.
    /// </summary>
    private static int GetOrAddPropertySingleValue(
        StepWriter w, Dictionary<(string PropertyName, string ValueExpr), int> valuePool,
        string propertyName, string valueExpr)
    {
        var key = (propertyName, valueExpr);
        if (!valuePool.TryGetValue(key, out int id))
        {
            id = w.Add("IFCPROPERTYSINGLEVALUE", $"{S(propertyName)},$,{valueExpr},$");
            valuePool[key] = id;
        }
        return id;
    }


    /// <summary>OST_CurtainWallMullions.</summary>
    private const int CurtainWallMullionCategoryId = -2000171;
    private const int CurtainWallPanelCategoryId = -2000170;
    private const int StructuralFramingCategoryId = -2001320;
    private const int StructuralColumnCategoryId = -2001330;
    private const int FloorCategoryId = -2000032;
    private const int RoofCategoryId = -2000035;
    private const int CurtainSystemCategoryId = -2000090;
    private const int MassExteriorWallCategoryId = -2003413;
    private const int MassInteriorWallCategoryId = -2003412;
    private const int FunctionParamId = -1001006;

    private enum ExactIsExternalParameterState
    {
        Absent,
        Value,
        Blocked,
    }

    private readonly record struct ExactIsExternalParameterResult(
        ExactIsExternalParameterState State,
        int Value = 0);

    /// <summary>
    /// Replays the observable category rule cache order for successfully exported
    /// occurrence-common-Pset targets (currently IFCMEMBER, IFCPLATE, and IFCCOLUMN).
    /// </summary>
    internal static IReadOnlyDictionary<int, bool>
        ResolveMemberPlateIsExternalValues(
            IReadOnlyList<Element> elements,
            IReadOnlyCollection<int>? eligibleComponentIds = null)
        => ResolveMemberPlateIsExternalValues(elements, eligibleComponentIds, out _);

    private static IReadOnlyDictionary<int, bool> ResolveMemberPlateIsExternalValues(
        IReadOnlyList<Element> elements,
        IReadOnlyCollection<int>? eligibleComponentIds,
        out IReadOnlyDictionary<int, bool?> typeValues)
    {
        var elementsById = new Dictionary<int, Element>();
        foreach (Element element in elements)
            elementsById.TryAdd(element.Id, element);

        HashSet<int>? eligibleIds = eligibleComponentIds?.ToHashSet();
        // Without an explicit set, every mullion/panel occurrence; an element another element names
        // as its type is that type, not a product registry entry of its own.
        HashSet<int> typeIds = eligibleIds != null ? [] : elements
            .Where(element => element.FamilyTypeId > 0 && element.FamilyTypeId != element.Id)
            .Select(element => element.FamilyTypeId).ToHashSet();
        List<Element> targets = elements.Where(element =>
            eligibleIds != null
                ? eligibleIds.Contains(element.Id)
                : element.CategoryId is CurtainWallMullionCategoryId
                    or CurtainWallPanelCategoryId
                    && !typeIds.Contains(element.Id))
            .GroupBy(element => element.Id)
            .Select(group => group.First()).ToList();
        var values = new Dictionary<int, bool>();
        foreach (Element target in targets)
            values.TryAdd(target.Id, false);
        List<Element> curtainComponents = targets.Where(element =>
            element.CategoryId is CurtainWallMullionCategoryId
                or CurtainWallPanelCategoryId).ToList();
        var cache = new Dictionary<int, bool>();
        var visiting = new HashSet<int>();
        Element? ResolveElementType(Element element, bool asType)
        {
            if (asType)
                return element;
            if (element.FamilyTypeId > 0
                && elementsById.TryGetValue(
                    element.FamilyTypeId, out Element? resolvedType))
                return resolvedType;
            return null;
        }

        bool Evaluate(Element element, bool asType = false)
        {
            if (cache.TryGetValue(element.Id, out bool cachedValue))
                return cachedValue;
            if (!visiting.Add(element.Id))
                return false;

            try
            {
                int familyTypeId = asType ? element.Id : element.FamilyTypeId;
                Element? elementType = ResolveElementType(element, asType);

                ExactIsExternalParameterResult explicitResult =
                    ResolveExactIsExternalParameter(element, elementType);
                if (explicitResult.State == ExactIsExternalParameterState.Value)
                {
                    bool explicitValue = explicitResult.Value != 0;
                    cache[element.Id] = explicitValue;
                    return explicitValue;
                }
                if (explicitResult.State == ExactIsExternalParameterState.Blocked)
                {
                    cache[element.Id] = false;
                    return false;
                }

                // The official Document can still resolve this positive type id and inspect its
                // parameter/cache/FUNCTION_PARAM branches.
                if (!asType && familyTypeId > 0 && elementType == null)
                {
                    cache[element.Id] = false;
                    return false;
                }

                // The category rule consults the shared type cache before evaluating a host.
                if (elementType != null
                    && elementType.Id != element.Id
                    && cache.TryGetValue(elementType.Id, out bool cachedTypeValue))
                    return cachedTypeValue;

                if (elementType != null)
                {
                    ExactIsExternalParameterResult functionResult =
                        ResolveExactFunctionParameter(elementType);
                    if (functionResult.State == ExactIsExternalParameterState.Value)
                    {
                        bool functionValue = functionResult.Value != 0;
                        if (elementType.Id != element.Id)
                            cache[elementType.Id] = functionValue;
                        cache[element.Id] = functionValue;
                        return functionValue;
                    }
                    if (functionResult.State == ExactIsExternalParameterState.Blocked)
                    {
                        cache[element.Id] = false;
                        return false;
                    }
                }

                if (element.CategoryId is RoofCategoryId or MassExteriorWallCategoryId)
                {
                    cache[element.Id] = true;
                    return true;
                }
                if (element.CategoryId == MassInteriorWallCategoryId)
                {
                    cache[element.Id] = false;
                    return false;
                }

                // The official host-recursion return intentionally does not cache the occurrence.
                if (element.SerializedHostId is int hostId
                    && elementsById.TryGetValue(hostId, out Element? host))
                    return Evaluate(host);

                cache[element.Id] = false;
                return false;
            }
            finally
            {
                visiting.Remove(element.Id);
            }
        }

        var childrenByHostId = curtainComponents
            .Where(component => component.SerializedHostId is int hostId
                && elementsById.TryGetValue(hostId, out Element? host)
                && (host.CategoryId is -2000011
                    or RoofCategoryId
                    or CurtainSystemCategoryId))
            .GroupBy(component => component.SerializedHostId!.Value)
            .ToDictionary(group => group.Key, group => group.ToList());
        HashSet<int> groupedComponentIds = childrenByHostId.Values
            .SelectMany(children => children)
            .Select(component => component.Id).ToHashSet();

        // Every successful occurrence is evaluated before Dispose() generates the root and
        // first-created child types.
        var roots = childrenByHostId.Keys.Select(hostId => (Id: hostId, IsHost: true))
            .Concat(targets.Where(target => !groupedComponentIds.Contains(target.Id))
                .Select(target => (target.Id, IsHost: false)))
            .OrderBy(root => root.Id).ThenBy(root => root.IsHost);
        foreach (var (rootId, isHost) in roots)
        {
            if (!isHost)
            {
                Element target = elementsById[rootId];
                values[target.Id] = Evaluate(target);
                Element? targetType = ResolveElementType(target, asType: false);
                if (targetType != null && targetType.Id != target.Id)
                    _ = Evaluate(targetType, asType: true);
                continue;
            }

            Element host = elementsById[rootId];
            _ = Evaluate(host);
            List<Element> children = childrenByHostId[host.Id];
            foreach (Element child in children)
                values[child.Id] = Evaluate(child);

            if (host.FamilyTypeId > 0
                && elementsById.TryGetValue(host.FamilyTypeId, out Element? hostType))
                _ = Evaluate(hostType, asType: true);
            var evaluatedChildTypeIds = new HashSet<int>();
            foreach (Element child in children)
                if (child.FamilyTypeId > 0
                    && evaluatedChildTypeIds.Add(child.FamilyTypeId)
                    && elementsById.TryGetValue(
                        child.FamilyTypeId, out Element? childType))
                    _ = Evaluate(childType, asType: true);
        }

        // The product registry evaluates canonical ElementTypes after their occurrences.
        var exactTypeValues = new Dictionary<int, bool?>();
        foreach (Element target in targets)
        {
            Element? type = ResolveElementType(target, asType: false);
            if (type == null || type.Id == target.Id || values.ContainsKey(type.Id)
                || type.CategoryId != target.CategoryId || type.SerializedHostId != null
                || !cache.TryGetValue(type.Id, out bool typeValue))
                continue;
            var named = ResolveExactIsExternalParameter(type, type);
            if (named.State == ExactIsExternalParameterState.Blocked
                || named.State == ExactIsExternalParameterState.Absent
                    && ResolveExactFunctionParameter(type).State == ExactIsExternalParameterState.Blocked)
            {
                exactTypeValues[type.Id] = null;
                continue;
            }
            exactTypeValues[type.Id] = typeValue;
        }
        typeValues = exactTypeValues;
        return values;
    }

    private static ExactIsExternalParameterResult ResolveExactIsExternalParameter(
        Element element, Element? elementType)
    {
        ExactIsExternalParameterResult result = ResolveExactNamedIntParameter(
            element, "IsExternal");
        if (result.State != ExactIsExternalParameterState.Absent)
            return result;

        Element? typeScope = elementType;
        if (typeScope != null && typeScope.Id != element.Id)
        {
            result = ResolveExactNamedIntParameter(typeScope, "IsExternal");
            if (result.State != ExactIsExternalParameterState.Absent)
                return result;
        }

        if (typeScope == null)
            return new(ExactIsExternalParameterState.Absent);
        return ResolveExactNamedIntParameter(typeScope, "IsExternal[Type]");
    }

    private static ExactIsExternalParameterResult ResolveExactNamedIntParameter(
        Element element, string name)
    {
        List<ExactIsExternalParameterResult> candidates = element.Parameters
            .Where(parameter => ParameterNameEquals(parameter, name))
            .Select(ClassifyExactNamedIntParameter).ToList();
        return MergeExactIntCandidates(candidates);
    }

    /// <summary>
    /// Strict occurrence-only boolean lookup used by generated property-set entries whose
    /// calculator fallback is legal only when the parameter is genuinely absent.
    /// </summary>
    private static ExactIsExternalParameterResult
        ResolveExactOccurrenceBooleanParameter(Element element, string name)
    {
        List<Parameter> matches = element.Parameters
            .Where(parameter => ParameterNameEquals(parameter, name))
            .ToList();
        if (matches.Count == 0)
            return new(ExactIsExternalParameterState.Absent);

        var candidates = new List<ExactIsExternalParameterResult>(matches.Count);
        foreach (Parameter parameter in matches)
        {
            if (parameter.IsApproximate
                || parameter.StorageType != StorageType.Integer
                || parameter.Value is not int integerValue)
            {
                candidates.Add(new(ExactIsExternalParameterState.Blocked));
            }
            else
            {
                candidates.Add(new(
                    ExactIsExternalParameterState.Value, integerValue));
            }
        }
        return MergeExactIntCandidates(candidates);
    }

    private static ExactIsExternalParameterResult ClassifyExactNamedIntParameter(
        Parameter parameter)
    {
        if (parameter.IsApproximate)
            return new(ExactIsExternalParameterState.Blocked);
        if (parameter.Value == null)
            return new(ExactIsExternalParameterState.Absent);

        switch (parameter.StorageType)
        {
            case StorageType.Integer:
                return parameter.Value is int integerValue
                    ? new(ExactIsExternalParameterState.Value, integerValue)
                    : new(ExactIsExternalParameterState.Blocked);
            case StorageType.Double:
                if (parameter.Value is not double doubleValue
                    || !double.IsFinite(doubleValue))
                    return new(ExactIsExternalParameterState.Blocked);
                double truncatedValue = Math.Truncate(doubleValue);
                if (truncatedValue < int.MinValue || truncatedValue > int.MaxValue)
                    return new(ExactIsExternalParameterState.Blocked);
                return new(
                    ExactIsExternalParameterState.Value, (int)truncatedValue);
            case StorageType.String:
                if (parameter.Value is not string stringValue)
                    return new(ExactIsExternalParameterState.Blocked);
                string trimmed = stringValue.Trim();
                bool expression = trimmed.EndsWith('}')
                    && (trimmed.StartsWith('{')
                        || trimmed.Length > 1 && trimmed[1] == '{');
                if (expression)
                    return new(ExactIsExternalParameterState.Blocked);
                return int.TryParse(
                    trimmed, NumberStyles.Integer, CultureInfo.InvariantCulture,
                    out int parsedValue)
                    ? new(ExactIsExternalParameterState.Value, parsedValue)
                    : new(ExactIsExternalParameterState.Absent);
            case StorageType.None:
            case StorageType.ElementId:
                return new(ExactIsExternalParameterState.Absent);
            default:
                return new(ExactIsExternalParameterState.Blocked);
        }
    }

    private static ExactIsExternalParameterResult ResolveExactFunctionParameter(
        Element elementType,
        bool includeSerializedCurtainWallFunction = true,
        bool includeFamilySymbolFunction = false)
    {
        // The current profile: the FUNCTION_PARAM the symbol stores in its own FamilyParams is the
        // value the category rule reads; it is authoritative over the parameters other decoders derived
        // for the same symbol.
        if (includeFamilySymbolFunction && elementType.SerializedFamilySymbolFunction is int symbolFunction)
            return new(ExactIsExternalParameterState.Value, symbolFunction);
        var candidates = new List<ExactIsExternalParameterResult>();
        if (includeSerializedCurtainWallFunction
            && elementType.SerializedCurtainWallFunction is int serializedFunction)
            candidates.Add(new(
                ExactIsExternalParameterState.Value, serializedFunction));

        foreach (Parameter parameter in elementType.Parameters.Where(
                     parameter => parameter.Id == FunctionParamId))
        {
            if (parameter.IsApproximate)
            {
                candidates.Add(new(ExactIsExternalParameterState.Blocked));
            }
            else if (parameter.Value == null)
            {
                candidates.Add(new(ExactIsExternalParameterState.Absent));
            }
            else if (parameter.StorageType == StorageType.Integer
                && parameter.Value is int integerValue)
            {
                candidates.Add(new(
                    ExactIsExternalParameterState.Value, integerValue));
            }
            else
            {
                candidates.Add(new(ExactIsExternalParameterState.Blocked));
            }
        }

        return MergeExactIntCandidates(candidates);
    }

    private static ExactIsExternalParameterResult MergeExactIntCandidates(
        IReadOnlyList<ExactIsExternalParameterResult> candidates)
    {
        if (candidates.Count == 0
            || candidates.All(candidate =>
                candidate.State == ExactIsExternalParameterState.Absent))
            return new(ExactIsExternalParameterState.Absent);

        if (candidates.All(candidate =>
                candidate.State == ExactIsExternalParameterState.Value)
            && candidates.Select(candidate => candidate.Value).Distinct().Count() == 1)
            return candidates[0];

        return new(ExactIsExternalParameterState.Blocked);
    }

    /// <summary>CURVE_ELEM_LENGTH built-in parameter id.</summary>
    private const int CurveElemLengthParamId = -1004005;
    private const int InstanceLengthParamId = -1001375;

    internal enum MemberSpanSource
    {
        DirectCanonical,
        DirectLength,
        CalculatorCanonical,
        BrepScaledLength,
        RuntimeInstanceLength,
    }

    private enum ExactSpanParameterState
    {
        Absent,
        Value,
        Blocked,
    }

    private readonly record struct ExactSpanParameterResult(
        ExactSpanParameterState State,
        Parameter? Parameter = null,
        double Value = 0);

    /// <summary>
    /// Emits Pset_MemberCommon for one IFCMEMBER product: IsExternal, Reference, and - for curtain
    /// wall mullions only - Span.
    /// </summary>
    private void ExportMemberCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string? referenceValue, IReadOnlyDictionary<int, Element> elementsById,
        bool isExternal,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool)
    {
        var valueIds = new List<int>
        {
            // IsExternal has no extracted per-element source for structural framing (unlike walls,
            // which have FUNCTION_PARAM).
            GetOrAddPropertySingleValue(
                w, valuePool, "IsExternal",
                isExternal ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"),
        };
        if (referenceValue != null)
        {
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "Reference", $"IFCIDENTIFIER({S(referenceValue)})"));
        }
        else
        {
            _mainLoopReferenceOmittedCount++;
        }
        if (elem.CategoryId == CurtainWallMullionCategoryId && !CurrentProfile)
        {
            Element? elementType = elem.FamilyTypeId > 0
                && elementsById.TryGetValue(
                    elem.FamilyTypeId, out Element? resolvedType)
                    ? resolvedType
                    : null;
            if (TryResolveExactMemberSpanMillimetres(
                    elem, elementType, out double spanMm,
                    out MemberSpanSource spanSource))
            {
                valueIds.Add(GetOrAddPropertySingleValue(
                    w, valuePool, "Span", $"IFCPOSITIVELENGTHMEASURE({D(spanMm)})"));
                if (spanSource == MemberSpanSource.RuntimeInstanceLength)
                    _spanRuntimeInstanceLengthCount++;
                else if (spanSource == MemberSpanSource.BrepScaledLength)
                    _spanBrepExactCount++;
                else
                    _spanExactCount++;
            }
        }
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"member-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_MemberCommon")},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"member-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

    /// <summary>
    /// Direct instance Span wins; only when it is genuinely absent is authored instance Length
    /// considered.
    /// </summary>
    internal static bool TryResolveExactMemberSpanMillimetres(
        Element element, Element? elementType, out double spanMillimetres,
        out MemberSpanSource source)
    {
        spanMillimetres = 0;
        source = default;
        if (element.CategoryId != CurtainWallMullionCategoryId)
            return false;

        List<Parameter> instanceSpanCandidates = element.Parameters.Where(
            parameter => ParameterNameEquals(parameter, "Span")).ToList();
        ExactSpanParameterResult instanceSpan = ResolveExactSpanParameter(
            instanceSpanCandidates);
        if (instanceSpan.State == ExactSpanParameterState.Blocked)
            return false;

        if (instanceSpan.State == ExactSpanParameterState.Value
            && instanceSpan.Value > 1e-9)
        {
            if (!TryScaleDirectSpanParameter(
                    instanceSpan.Parameter!, instanceSpan.Value,
                    out spanMillimetres)
                || spanMillimetres <= 1e-9)
                return false;
            source = MemberSpanSource.DirectCanonical;
            return true;
        }

        Parameter? runtimeLengthMarker =
            TryGetSyntheticRuntimeInstanceLengthMarker(element, out Parameter? marker)
                ? marker
                : null;
        List<Parameter> directLengthCandidates = element.Parameters.Where(parameter =>
            IsDirectLengthDisplayNameCandidate(parameter)
            && !ReferenceEquals(parameter, runtimeLengthMarker)).ToList();

        // PropertySetEntryMap consults the built-in/display-name Length mapping only when no
        // instance Span parameter was found.
        ExactSpanParameterResult directLength =
            new(ExactSpanParameterState.Absent);
        if (instanceSpanCandidates.Count == 0)
        {
            directLength = ResolveExactSpanParameter(directLengthCandidates);
            if (directLength.State == ExactSpanParameterState.Blocked)
                return false;
            if (directLength.State == ExactSpanParameterState.Value
                && directLength.Value > 1e-9)
            {
                if (!TryScaleDirectSpanParameter(
                        directLength.Parameter!, directLength.Value,
                        out spanMillimetres)
                    || spanMillimetres <= 1e-9)
                    return false;
                source = MemberSpanSource.DirectLength;
                return true;
            }
        }

        List<Parameter> typeSpanCandidates = elementType?.Parameters.Where(
            parameter => ParameterNameEquals(parameter, "Span")).ToList() ?? [];
        List<Parameter> typeSpanTypeCandidates = elementType?.Parameters.Where(
            parameter => ParameterNameEquals(parameter, "Span[Type]")).ToList() ?? [];
        ExactSpanParameterResult calculatorSpan = instanceSpan;
        if (calculatorSpan.State == ExactSpanParameterState.Absent
            && elementType != null)
        {
            calculatorSpan = ResolveExactSpanParameter(typeSpanCandidates);
            if (calculatorSpan.State == ExactSpanParameterState.Absent)
                calculatorSpan = ResolveExactSpanParameter(typeSpanTypeCandidates);
        }

        if (calculatorSpan.State == ExactSpanParameterState.Blocked)
            return false;

        if (calculatorSpan.State == ExactSpanParameterState.Value
            && calculatorSpan.Value > 1e-9)
        {
            spanMillimetres = calculatorSpan.Value * FeetToMetres * 1000;
            if (!double.IsFinite(spanMillimetres) || spanMillimetres <= 1e-9)
                return false;
            source = MemberSpanSource.CalculatorCanonical;
            return true;
        }

        if (calculatorSpan.State == ExactSpanParameterState.Value)
        {
            if (calculatorSpan.Value != 0
                || !TryGetExactMullionBrepSpanMillimetres(
                    element, out spanMillimetres)
                || spanMillimetres <= 1e-9)
                return false;

            source = MemberSpanSource.BrepScaledLength;
            return true;
        }

        bool hasAnyAuthoredCandidate = instanceSpanCandidates.Count > 0
            || directLengthCandidates.Count > 0
            || typeSpanCandidates.Count > 0
            || typeSpanTypeCandidates.Count > 0;
        if (hasAnyAuthoredCandidate
            || runtimeLengthMarker == null
            || !TryGetExactMullionBrepSpanMillimetres(
                element, out spanMillimetres)
            || spanMillimetres <= 1e-9)
            return false;

        source = MemberSpanSource.RuntimeInstanceLength;
        return true;
    }

    private static ExactSpanParameterResult ResolveExactSpanParameter(
        Element element, Func<Parameter, bool> predicate)
        => ResolveExactSpanParameter(element.Parameters.Where(predicate).ToList());

    private static ExactSpanParameterResult ResolveExactSpanParameter(
        IReadOnlyList<Parameter> candidates)
    {
        if (candidates.Count == 0)
            return new ExactSpanParameterResult(ExactSpanParameterState.Absent);

        // Revit's winner depends on ParameterGroup, visibility, then signed id.
        if (candidates.Count != 1)
            return new ExactSpanParameterResult(ExactSpanParameterState.Blocked);

        Parameter parameter = candidates[0];
        if (parameter.IsApproximate)
            return new ExactSpanParameterResult(ExactSpanParameterState.Blocked);
        if (parameter.Value == null)
            return new ExactSpanParameterResult(ExactSpanParameterState.Absent);

        double value;
        if (parameter.StorageType == StorageType.Double
            && parameter.Value is double doubleValue)
            value = doubleValue;
        else if (parameter.StorageType == StorageType.Integer
            && parameter.Value is int integerValue)
            value = integerValue;
        else
            return new ExactSpanParameterResult(ExactSpanParameterState.Blocked);

        return double.IsFinite(value)
            ? new ExactSpanParameterResult(
                ExactSpanParameterState.Value, parameter, value)
            : new ExactSpanParameterResult(ExactSpanParameterState.Blocked);
    }

    private static bool TryGetSyntheticRuntimeInstanceLengthMarker(
        Element element, out Parameter? marker)
    {
        marker = null;
        List<Parameter> candidates = element.Parameters.Where(
            parameter => parameter.Id == CurveElemLengthParamId).ToList();
        if (candidates.Count != 1)
            return false;

        Parameter candidate = candidates[0];
        if (!candidate.IsApproximate
            || candidate.Id != CurveElemLengthParamId
            || candidate.Definition.Id != CurveElemLengthParamId
            || !string.Equals(
                candidate.Definition.Name, "CURVE_ELEM_LENGTH",
                StringComparison.Ordinal)
            || !string.Equals(
                candidate.Definition.BuiltInParameter, "CURVE_ELEM_LENGTH",
                StringComparison.Ordinal)
            || candidate.StorageType != StorageType.Double
            || candidate.Value is not double value
            || !double.IsFinite(value)
            || value <= 0)
            return false;

        marker = candidate;
        return true;
    }

    private static bool ParameterNameEquals(Parameter parameter, string name) =>
        parameter.Definition?.Name is string parameterName
        && string.Equals(
            parameterName.Replace(" ", null), name.Replace(" ", null),
            StringComparison.InvariantCultureIgnoreCase);

    private static bool IsDirectLengthDisplayNameCandidate(Parameter parameter) =>
        parameter.Id is InstanceLengthParamId or CurveElemLengthParamId
        || ParameterNameEquals(parameter, "Length");

    private static bool TryScaleDirectSpanParameter(
        Parameter parameter, double value, out double scaledValue)
    {
        scaledValue = 0;
        bool scaleAsLength;
        if (parameter.Id is InstanceLengthParamId or CurveElemLengthParamId)
        {
            scaleAsLength = true;
        }
        else if (parameter.SpecType?.StartsWith(
                     "autodesk.spec.aec:number-",
                     StringComparison.OrdinalIgnoreCase) == true)
        {
            scaleAsLength = false;
        }
        else if (parameter.SpecType?.StartsWith(
                     "autodesk.spec.aec:length-",
                     StringComparison.OrdinalIgnoreCase) == true)
        {
            scaleAsLength = true;
        }
        else
        {
            return false;
        }

        scaledValue = scaleAsLength
            ? value * FeetToMetres * 1000
            : value;
        return double.IsFinite(scaledValue);
    }

    /// <summary>Same value-pooling contract as ExportQuantityTakeOffPropertySet.</summary>
    private void ExportPlateCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string? referenceValue, bool isExternal,
        Dictionary<(string PropertyName, string ValueExpr), int> valuePool)
    {
        var valueIds = new List<int>
        {
            GetOrAddPropertySingleValue(
                w, valuePool, "IsExternal",
                isExternal ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"),
        };
        if (referenceValue != null)
        {
            valueIds.Add(GetOrAddPropertySingleValue(
                w, valuePool, "Reference", $"IFCIDENTIFIER({S(referenceValue)})"));
        }
        else
        {
            _mainLoopReferenceOmittedCount++;
        }
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"plate-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_PlateCommon")},$,{StepWriter.List(valueIds.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"plate-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }


    /// <summary>
    /// Used by the main element loop for the rare real Revit "Opening" category element; <paramref
    /// name="elem"/> is both the Pset/GUID source and the legacy decoded Reference source.
    /// </summary>
    private void ExportOpeningElementCommonPropertySet(
        StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        string? referenceValue, Dictionary<(string PropertyName, string ValueExpr), int> valuePool)
    {
        if (referenceValue == null)
        {
            _mainLoopReferenceOmittedCount++;
            return;
        }
        int valueId = GetOrAddPropertySingleValue(
            w, valuePool, "Reference", $"IFCIDENTIFIER({S(referenceValue)})");
        int psetId = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"opening-common-pset:{elem.Id}"))},{R(ownerHistId)},{S("Pset_OpeningElementCommon")},$,{StepWriter.List(R(valueId))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"opening-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
    }

