    }

    /// <summary>
    /// All topology decisions are made on the same 1e-5 metre, midpoint-to-even lattice used by the
    /// IFC geometry writer.
    /// </summary>
    internal static bool TryGetExactMullionBrepSpanMillimetres(
        Element elem, out double spanMillimetres)
    {
        spanMillimetres = 0;
        if (elem.CategoryId != CurtainWallMullionCategoryId
            || elem.Transform is not { SymbolId: > 0 } transform
            || elem.SerializedHostId is not > 0
            || !TryFiniteMullionPoint(transform.Origin)
            || !TryMullionUnitVector(transform.BasisX, out _)
            || !TryMullionUnitVector(transform.BasisY, out _)
            || !TryMullionUnitVector(transform.BasisZ, out double[] axis)
            || elem.Geometry is not { } geometry
            || geometry.BrepSolids is not { Count: 1 } solids
            || !solids[0].IsClosed)
            return false;

        GeoBrepSolid solid = solids[0];
        if (solid.FaceIndices.Count != geometry.Faces.Count
            || solid.FaceIndices.Any(index => (uint)index >= geometry.Faces.Count)
            || solid.FaceIndices.Distinct().Count() != solid.FaceIndices.Count
            || !solid.FaceIndices.ToHashSet().SetEquals(
                Enumerable.Range(0, geometry.Faces.Count)))
            return false;

        var faceRings = new List<List<(double[] Point,
            (long X, long Y, long Z) Key, double AlongFeet, long AlongBin)>>(
                geometry.Faces.Count);
        double minimumAlongFeet = double.PositiveInfinity;
        double maximumAlongFeet = double.NegativeInfinity;
        long minimumAlongBin = long.MaxValue;
        long maximumAlongBin = long.MinValue;

        foreach (GeoFace face in geometry.Faces)
        {
            if (face.AlternativeOuterVertices is not null
                || face.OuterVertices is not { Count: >= 3 } sourceRing)
                return false;

            var ring = new List<(double[] Point, (long X, long Y, long Z) Key,
                double AlongFeet, long AlongBin)>(sourceRing.Count);
            foreach (double[] point in sourceRing)
            {
                if (!TryFiniteMullionPoint(point)
                    || !TryMullionLatticeKey(point, out var key))
                    return false;
                if (ring.Count > 0 && ring[^1].Key == key) continue;

                double alongFeet = MullionDot(
                    point[0] - transform.Origin[0],
                    point[1] - transform.Origin[1],
                    point[2] - transform.Origin[2], axis);
                if (!double.IsFinite(alongFeet)
                    || !TryMullionFeetBin(alongFeet, out long alongBin))
                    return false;
                ring.Add((point, key, alongFeet, alongBin));
            }
            if (ring.Count > 1 && ring[0].Key == ring[^1].Key)
                ring.RemoveAt(ring.Count - 1);
            if (ring.Count < 3 || ring.Select(item => item.Key).Distinct().Count() < 3)
                return false;

            foreach (var item in ring)
            {
                minimumAlongFeet = Math.Min(minimumAlongFeet, item.AlongFeet);
                maximumAlongFeet = Math.Max(maximumAlongFeet, item.AlongFeet);
                minimumAlongBin = Math.Min(minimumAlongBin, item.AlongBin);
                maximumAlongBin = Math.Max(maximumAlongBin, item.AlongBin);
            }
            faceRings.Add(ring);
        }

        if (faceRings.Count == 0 || minimumAlongBin >= maximumAlongBin)
            return false;
        int minimumTerminalFaces = faceRings.Count(ring =>
            ring.All(item => item.AlongBin == minimumAlongBin));
        int maximumTerminalFaces = faceRings.Count(ring =>
            ring.All(item => item.AlongBin == maximumAlongBin));
        if (minimumTerminalFaces != 1 || maximumTerminalFaces != 1)
            return false;

        double spanFeet = maximumAlongFeet - minimumAlongFeet;
        if (!(spanFeet > 0) || !double.IsFinite(spanFeet)
            || !TryMullionFeetBin(spanFeet, out long spanBin)
            || spanBin <= 0)
            return false;

        var edges = new Dictionary<(
            (long X, long Y, long Z) First,
            (long X, long Y, long Z) Second),
            (double[] First, double[] Second, long FirstAlong, long SecondAlong)>();
        foreach (var ring in faceRings)
        {
            for (int index = 0; index < ring.Count; index++)
            {
                var first = ring[index];
                var second = ring[(index + 1) % ring.Count];
                var edgeKey = MullionCanonicalEdge(first.Key, second.Key);
                edges.TryAdd(edgeKey,
                    (first.Point, second.Point, first.AlongBin, second.AlongBin));
            }
        }

        int longitudinalEdges = 0;
        foreach (var edge in edges.Values)
        {
            bool joinsTerminals =
                edge.FirstAlong == minimumAlongBin
                    && edge.SecondAlong == maximumAlongBin
                || edge.FirstAlong == maximumAlongBin
                    && edge.SecondAlong == minimumAlongBin;
            if (!joinsTerminals
                || !MullionEdgeIsParallelOnLattice(edge.First, edge.Second, axis))
                continue;
            double dx = edge.Second[0] - edge.First[0];
            double dy = edge.Second[1] - edge.First[1];
            double dz = edge.Second[2] - edge.First[2];
            double lengthFeet = Math.Sqrt(dx * dx + dy * dy + dz * dz);
            if (double.IsFinite(lengthFeet)
                && TryMullionFeetBin(lengthFeet, out long lengthBin)
                && lengthBin == spanBin)
                longitudinalEdges++;
        }
        if (longitudinalEdges < 2) return false;

        spanMillimetres = spanFeet * FeetToMetres * 1000;
        return spanMillimetres > 0 && double.IsFinite(spanMillimetres);
    }

    private static bool TryFiniteMullionPoint(IReadOnlyList<double>? point) =>
        point is { Count: >= 3 }
        && double.IsFinite(point[0])
        && double.IsFinite(point[1])
        && double.IsFinite(point[2]);

    private static bool TryMullionUnitVector(
        IReadOnlyList<double>? source, out double[] unit)
    {
        unit = [];
        if (!TryFiniteMullionPoint(source)) return false;
        double length = Math.Sqrt(
            source![0] * source[0] + source[1] * source[1] + source[2] * source[2]);
        if (!(length > 0) || !double.IsFinite(length)) return false;
        unit = [source[0] / length, source[1] / length, source[2] / length];
        return unit.All(double.IsFinite);
    }

    private static bool TryMullionLatticeKey(
        IReadOnlyList<double> point, out (long X, long Y, long Z) key)
    {
        key = default;
        return TryMullionMetresBin(point[0] * FeetToMetres, out key.X)
            && TryMullionMetresBin(point[1] * FeetToMetres, out key.Y)
            && TryMullionMetresBin(point[2] * FeetToMetres, out key.Z);
    }

    private static bool TryMullionFeetBin(double feet, out long bin) =>
        TryMullionMetresBin(feet * FeetToMetres, out bin);

    private static bool TryMullionMetresBin(double metres, out long bin)
    {
        bin = 0;
        if (!double.IsFinite(metres)) return false;
        double scaled = metres / IfcGeometryPrecisionMetres;
        if (!double.IsFinite(scaled)) return false;
        try
        {
            bin = checked((long)Math.Round(scaled, MidpointRounding.ToEven));
            return true;
        }
        catch (OverflowException)
        {
            return false;
        }
    }

    private static double MullionDot(
        double x, double y, double z, IReadOnlyList<double> vector) =>
        x * vector[0] + y * vector[1] + z * vector[2];

    private static ((long X, long Y, long Z) First,
        (long X, long Y, long Z) Second) MullionCanonicalEdge(
        (long X, long Y, long Z) first,
        (long X, long Y, long Z) second)
    {
        int comparison = first.X.CompareTo(second.X);
        if (comparison == 0) comparison = first.Y.CompareTo(second.Y);
        if (comparison == 0) comparison = first.Z.CompareTo(second.Z);
        return comparison <= 0 ? (first, second) : (second, first);
    }

    private static bool MullionEdgeIsParallelOnLattice(
        IReadOnlyList<double> first, IReadOnlyList<double> second,
        IReadOnlyList<double> axis)
    {
        double dx = second[0] - first[0];
        double dy = second[1] - first[1];
        double dz = second[2] - first[2];
        double along = MullionDot(dx, dy, dz, axis);
        if (!double.IsFinite(along)) return false;
        return TryMullionFeetBin(dx - along * axis[0], out long residualX)
            && residualX == 0
            && TryMullionFeetBin(dy - along * axis[1], out long residualY)
            && residualY == 0
            && TryMullionFeetBin(dz - along * axis[2], out long residualZ)
            && residualZ == 0;
    }


    /// <summary>
    /// Value typed by the parameter's public API spec, in the file's units: millimetre, square
    /// metre, cubic metre, and the plane angle in radians, or in degrees when <paramref
    /// name="angleInDegrees"/> (the The current profile plane angle unit).
    /// </summary>
    internal static string? TypedApiParameterValue(Element elem, Parameter p, string dataType,
        IReadOnlyDictionary<int, Element> elemById, bool angleInDegrees = false)
    {
        // Element references and the type-derived identity parameters are written as the referenced
        // text, as Revit's parameter display does.
        const int symbolIdParam = -1002000, symbolNameParam = -1002001, allModelFamilyName = -1002002;
        const int elemTypeParam = -1002050, elemFamilyParam = -1002051, elemFamilyAndTypeParam = -1002052;
        const int elemCategoryParam = -1140362, elemCategoryParamMt = -1140363;
        Element? typeOf(Element e) =>
            e.Parameters.FirstOrDefault(q => q.Id == elemTypeParam)?.Value is int typeId
                && elemById.TryGetValue(typeId, out var t) ? t : null;
        switch (p.Id)
        {
            case elemCategoryParam or elemCategoryParamMt when p.Value is int categoryId
                && Enum.IsDefined(typeof(BuiltIns.BuiltInCategory), categoryId):
                return $"IFCLABEL({S(((BuiltIns.BuiltInCategory)categoryId).ToString())})";
            case symbolIdParam when typeOf(elem) is { } symbol:
                return $"IFCLABEL({S(symbol.Id.ToString(System.Globalization.CultureInfo.InvariantCulture))})";
            case symbolNameParam when typeOf(elem) is { Name: { } typeName }:
                return $"IFCTEXT({S(typeName)})";
            case allModelFamilyName when typeOf(elem) is { FamilyName: { } familyName }:
                return $"IFCTEXT({S(familyName)})";
            case elemTypeParam when typeOf(elem) is { Name: { } typeName }:
                return $"IFCLABEL({S(typeName)})";
            case elemFamilyParam when typeOf(elem) is { FamilyName: { } familyName }:
                return $"IFCLABEL({S(familyName)})";
            case elemFamilyAndTypeParam when typeOf(elem) is { Name: { } typeName, FamilyName: { } familyName }:
                return $"IFCLABEL({S(familyName + " : " + typeName)})";
        }
        if (p.StorageType == StorageType.ElementId && p.Value is int referenced
            && elemById.TryGetValue(referenced, out var target) && target.Name is { } targetName)
            return $"IFCLABEL({S(targetName)})";
        switch (p.StorageType)
        {
            case StorageType.Double when p.Value is double d && double.IsFinite(d):
                return dataType switch
                {
                    "autodesk.spec.aec:length" => $"IFCLENGTHMEASURE({D17(d * 304.8)})",
                    "autodesk.spec.aec:area" => $"IFCAREAMEASURE({D(d * FeetToMetres * FeetToMetres)})",
                    "autodesk.spec.aec:volume" => $"IFCVOLUMEMEASURE({D(d * FeetToMetres * FeetToMetres * FeetToMetres)})",
                    "autodesk.spec.aec:angle" => $"IFCPLANEANGLEMEASURE({(angleInDegrees ? D17(d * (180.0 / Math.PI)) : D(d))})",
                    _ => null,
                };
            case StorageType.Integer when dataType == "autodesk.spec:spec.bool" && p.Value is int b:
                return b == 0 ? "IFCBOOLEAN(.F.)" : "IFCBOOLEAN(.T.)";
            case StorageType.String:
                return $"IFCTEXT({S(p.Value?.ToString() ?? "")})";
            default:
                return null;
        }
    }

    private void ExportPropertySets(StepWriter w, Element elem, int elemEntityId, int ownerHistId,
        IReadOnlyDictionary<int, Element> elemById)
    {
        // Group parameters by a common property set name Revit params -> "PSet_Revit_Parameters"
        var propIds = new List<int>();
        var propIdsByGroup = new Dictionary<string, List<int>>(StringComparer.Ordinal);

        foreach (var p in elem.Parameters)
        {
            if (p.Value == null) continue;

            string propValue;

            switch (p.StorageType)
            {
                case StorageType.Double:
                    if (p.Value is double dv && double.IsFinite(dv))
                    {
                        propValue = $"IFCREAL({D(dv)})";
                    }
                    else continue;
                    break;
                case StorageType.String:
                    propValue = $"IFCLABEL({S(p.Value.ToString() ?? "")})";
                    break;
                case StorageType.Integer:
                    propValue = $"IFCINTEGER({p.Value})";
                    break;
                case StorageType.ElementId:
                    propValue = $"IFCINTEGER({p.Value})";
                    break;
                default:
                    continue;
            }

            string paramName = p.Definition?.Name ?? $"Param_{p.Id}";
            string groupName = "Other";
            if (RevitParameterGroups && Parsing.ApiParameterDefinitions.TryGet(
                    p.Id, out string apiName, out int apiGroupId, out string apiDataType))
            {
                paramName = p.Id switch
                {
                    -1002502 => "Classification Number",
                    -1002503 => "Classification Title",
                    _ => apiName,
                };
                if (BuiltIns.BuiltInParameterGroupLabels.ToEnglishLabel((BuiltIns.BuiltInParameterGroup)apiGroupId, out string label))
                    groupName = label;
                propValue = TypedApiParameterValue(elem, p, apiDataType, elemById, CurrentProfile) ?? propValue;
            }
            int propId = w.Add("IFCPROPERTYSINGLEVALUE", $"{S(paramName)},$,{propValue},$");
            if (RevitParameterGroups)
            {
                if (!propIdsByGroup.TryGetValue(groupName, out var groupIds))
                    propIdsByGroup[groupName] = groupIds = new List<int>();
                groupIds.Add(propId);
            }
            else propIds.Add(propId);
        }

        foreach (var (groupName, groupIds) in propIdsByGroup.OrderBy(g => g.Key, StringComparer.Ordinal))
        {
            int groupPsetId = w.Add("IFCPROPERTYSET",
                $"{S(IfcGuid.FromName($"pset:{elem.Id}:{groupName}"))},{R(ownerHistId)},{S(groupName)},$,{StepWriter.List(groupIds.Select(R))}");
            w.Add("IFCRELDEFINESBYPROPERTIES",
                $"{S(IfcGuid.FromName($"rel:pset:{elem.Id}:{groupName}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(groupPsetId)}");
        }

        if (propIds.Count == 0) return;

        // Split into chunks of 100 to avoid overly large property sets
        const int chunkSize = 100;
        for (int i = 0; i < propIds.Count; i += chunkSize)
        {
            var chunk = propIds.Skip(i).Take(chunkSize).ToList();
            string setName = i == 0 ? "RevitParameters" : $"RevitParameters_{i / chunkSize + 1}";
            int psetId = w.Add("IFCPROPERTYSET",
                $"{S(IfcGuid.FromName($"pset:{elem.Id}:{i}"))},{R(ownerHistId)},{S(setName)},$,{StepWriter.List(chunk.Select(R))}");
            w.Add("IFCRELDEFINESBYPROPERTIES",
                $"{S(IfcGuid.FromName($"rel:pset:{elem.Id}:{i}"))},{R(ownerHistId)},$,$,{StepWriter.List(R(elemEntityId))},{R(psetId)}");
        }
    }


    /// <summary>
    /// Final fallback for family instances whose category block was one of the few unrecoverable
    /// stream members.
    /// </summary>
    internal static Element? LinkedFamilyType(Element elem, IReadOnlyDictionary<int, Element> elemById)
    {
        // FamilyInstanceData.SymbolId is the symbol reference serialized immediately after the
        // instance transform.
        int serializedSymbolId = elem.Transform?.SymbolId ?? -1;
        if (serializedSymbolId > 0 && serializedSymbolId != elem.Id
            && elemById.TryGetValue(serializedSymbolId, out var serializedSymbol))
            return serializedSymbol;

        int familyTypeId = elem.FamilyTypeId;
        if (familyTypeId > 0 && familyTypeId != elem.Id
            && elemById.TryGetValue(familyTypeId, out var familyType))
            return familyType;
        return null;
    }

    /// <summary>Resolves authored complex cutters from most-specific to generic.</summary>
    internal static IReadOnlyList<Element> LinkedFamilyCutTypes(Element elem,
        IReadOnlyDictionary<int, Element> elemById)
    {
        var mappedInstances = elem.Geometry?.ExactMappedInstances is { Count: > 0 } exact
            ? exact : elem.Geometry?.Instances;
        int mappedSymbolId = mappedInstances is { Count: 1 }
            ? mappedInstances[0].SymbolId : -1;
        int transformSymbolId = elem.Transform?.SymbolId ?? -1;
        return new[] { mappedSymbolId, transformSymbolId, elem.FamilyTypeId }
            .Where(id => id > 0 && id != elem.Id).Distinct()
            .Select(id => elemById.TryGetValue(id, out var candidate) ? candidate : null)
            .Where(candidate => candidate?.FamilyCutGeometry != null
                || candidate?.FamilyCutLoops is { Count: > 0 })
            .Cast<Element>().ToList();
    }

    private static string FamilyDescriptor(Element elem, IReadOnlyDictionary<int, Element> elemById)
    {
        Element? type = LinkedFamilyType(elem, elemById);
        return $"{elem.FamilyName} {elem.Name} {type?.FamilyName} {type?.Name}";
    }

    private static string? InferUncategorizedFamilyIfcType(
        Element elem, IReadOnlyDictionary<int, Element> elemById)
    {
        if (elem.CategoryId != null || elem.Transform == null || elem.TypeId <= 0) return null;
        string text = FamilyDescriptor(elem, elemById);
        string[] furnishingHints =
        {
            "chair", "seat", "sofa", "ottoman", "table", "cabinet", "wardrobe", "tv"
        };
        return furnishingHints.Any(h => text.Contains(h, StringComparison.OrdinalIgnoreCase))
            ? "IFCFURNISHINGELEMENT"
            : "IFCBUILDINGELEMENTPROXY";
    }

    /// <summary>
    /// Create an oriented instance box when the RVT contains placement and family dimensions but
    /// the family mesh itself is absent.
    /// </summary>
    private static double[]? BuildTransformFallbackBbox(
        Element elem, IReadOnlyDictionary<int, Element> elemById)
    {
        if (elem.Transform is not { } t) return null;
        Element? type = LinkedFamilyType(elem, elemById);

        static double NamedDimension(Element e, Element? type, string token)
        {
            foreach (var p in e.Parameters.Concat(type?.Parameters ?? Enumerable.Empty<Parameter>()))
                if (p.Value is double d && d > 0.03 && d < 100
                    && p.Definition?.Name?.Contains(token, StringComparison.OrdinalIgnoreCase) == true)
                    return d;
            return 0;
        }

        double width = NamedDimension(elem, type, "Width");
        double depth = NamedDimension(elem, type, "Depth");
        double height = NamedDimension(elem, type, "Height");
        string text = FamilyDescriptor(elem, elemById);

        // Common Revit type-name dimension formats: W600XD600XH530 and 1800 x 900 mm.
        var whd = Regex.Match(text, @"W\s*(\d+)\s*X\s*D\s*(\d+)(?:\s*X\s*H\s*(\d+))?",
            RegexOptions.IgnoreCase);
        if (whd.Success)
        {
            if (width <= 0) width = double.Parse(whd.Groups[1].Value, CultureInfo.InvariantCulture) / 304.8;
            if (depth <= 0) depth = double.Parse(whd.Groups[2].Value, CultureInfo.InvariantCulture) / 304.8;
            if (height <= 0 && whd.Groups[3].Success)
                height = double.Parse(whd.Groups[3].Value, CultureInfo.InvariantCulture) / 304.8;
        }
        var twoDims = Regex.Match(text, @"(\d{3,4})\s*[xX]\s*(\d{3,4})\s*mm", RegexOptions.IgnoreCase);
        if (twoDims.Success)
        {
            if (width <= 0) width = double.Parse(twoDims.Groups[1].Value, CultureInfo.InvariantCulture) / 304.8;
            if (depth <= 0) depth = double.Parse(twoDims.Groups[2].Value, CultureInfo.InvariantCulture) / 304.8;
        }

        bool chair = text.Contains("chair", StringComparison.OrdinalIgnoreCase)
            || text.Contains("seat", StringComparison.OrdinalIgnoreCase);
        bool table = text.Contains("table", StringComparison.OrdinalIgnoreCase);
        bool sofa = text.Contains("sofa", StringComparison.OrdinalIgnoreCase)
            || text.Contains("ottoman", StringComparison.OrdinalIgnoreCase);
        bool cabinet = text.Contains("cabinet", StringComparison.OrdinalIgnoreCase)
            || text.Contains("wardrobe", StringComparison.OrdinalIgnoreCase)
            || text.Contains("tv", StringComparison.OrdinalIgnoreCase);
        bool compactTrackLight = text.Contains("Trck_Bswy", StringComparison.OrdinalIgnoreCase);
        if (compactTrackLight)
        {
            // This family's named Height parameter is its mounting elevation, not the fixture body
            // height.
            width = 0.70 / FeetToMetres;
            depth = 0.70 / FeetToMetres;
            height = 0.35 / FeetToMetres;
        }
        if (width <= 0) width = (compactTrackLight ? 0.70 : table ? 1.2 : sofa ? 0.9 : chair ? 0.6 : cabinet ? 1.0 : 0.5) / FeetToMetres;
        if (depth <= 0) depth = (compactTrackLight ? 0.70 : table ? 0.8 : sofa ? 0.9 : chair ? 0.6 : cabinet ? 0.4 : 0.5) / FeetToMetres;
        if (height <= 0) height = (compactTrackLight ? 0.35 : table ? 0.75 : sofa ? 0.55 : chair ? 1.0 : cabinet ? 0.8 : 0.5) / FeetToMetres;

        double minX = double.MaxValue, minY = double.MaxValue, minZ = double.MaxValue;
        double maxX = double.MinValue, maxY = double.MinValue, maxZ = double.MinValue;
        foreach (double x in new[] { -width / 2, width / 2 })
            foreach (double y in new[] { -depth / 2, depth / 2 })
                foreach (double z in new[] { 0d, height })
                {
                    double wx = t.Origin[0] + x * t.BasisX[0] + y * t.BasisY[0] + z * t.BasisZ[0];
                    double wy = t.Origin[1] + x * t.BasisX[1] + y * t.BasisY[1] + z * t.BasisZ[1];
                    double wz = t.Origin[2] + x * t.BasisX[2] + y * t.BasisY[2] + z * t.BasisZ[2];
                    minX = Math.Min(minX, wx); maxX = Math.Max(maxX, wx);
                    minY = Math.Min(minY, wy); maxY = Math.Max(maxY, wy);
                    minZ = Math.Min(minZ, wz); maxZ = Math.Max(maxZ, wz);
                }
        return [minX, minY, minZ, maxX, maxY, maxZ];
    }

