    /// <summary>
    /// Prefers the type element's own name-table entry and parent-family chain, isolated from
    /// instance-name propagation.
    /// </summary>
    /// <summary>
    /// The geometry rule: a family instance gets a type of its own when its
    /// geometry holds more than a GInstance and its node summary differs from its symbol's.
    /// </summary>
    internal static bool UsesInstanceGeometry(Element instance, Element symbol, bool withSolids = false)
    {
        if (instance.Geometry?.StoredNodeSummary is not { } own
            || symbol.Geometry?.StoredNodeSummary is not { } shared)
            return false;
        int ownSolids = withSolids ? instance.Geometry.StoredSolids ?? 0 : 0;
        int sharedSolids = withSolids ? symbol.Geometry.StoredSolids ?? 0 : 0;
        return (own != (0, 0) || ownSolids > 0) && (own != shared || ownSolids != sharedSolids);
    }

    private static string? TypeObjectName(Element typeElem) => TypeObjectNameParts(typeElem).Full;

    /// <summary>
    /// The "Family:Type" name of a type and the type name alone, which the current profile writes
    /// as the Name of the type object (the naming rule for a type is the element name;
    /// the legacy profile prefixed the family).
    /// </summary>
    internal static (string? Full, string? Own) TypeObjectNameParts(Element typeElem, bool currentProfile = false)
    {
        if (typeElem.ValidatedIfcTypeObjectName != null)
            return (typeElem.ValidatedIfcTypeObjectName, typeElem.ValidatedIfcTypeOwnName);
        // General Name and FamilyName may have been overwritten by a nested/reference-voted symbol.
        if ((typeElem.SerializedSystemTypeClassId, typeElem.CategoryId)
                is (646, -2000038) or (1915, -2000032 or -2001300)
            && typeElem.ValidatedHostTypeLayerSetName is { Length: > 0 } ownHostName)
            return (ownHostName, typeElem.ValidatedSystemFamilyName is { Length: > 0 } hostFamily
                && ownHostName.StartsWith(hostFamily + ":", StringComparison.Ordinal)
                    ? ownHostName[(hostFamily.Length + 1)..] : null);
        if (typeElem.CategoryId == -2000011 && typeElem.SerializedSystemTypeClassId == 2559
            && !typeElem.IsBlockOnly && typeElem.SerializedCurtainWallFunction is >= 0 and <= 5
            && typeElem.SerializedBasicWallTypeFunction == null
            && typeElem.SerializedCurtainWallTypeName is { Length: > 0 } ownCurtainName
            && typeElem.ValidatedSystemFamilyName is { Length: > 0 } ownCurtainFamily)
            return ($"{ownCurtainFamily}:{ownCurtainName}", ownCurtainName);
        // CorniceAttr and StairsSupportType also inherit the same own SymbolInfo getter.
        string? ownComponentName = typeElem.CategoryId switch
        {
            -2000181 => typeElem.ValidatedCorniceTypeName,
            -2000123 => typeElem.ValidatedStairComponentTypeName,
            _ => null,
        };
        if (!typeElem.IsBlockOnly && ownComponentName is { Length: > 0 }
            && typeElem.ValidatedSystemFamilyName is { Length: > 0 } ownComponentFamily)
            return ($"{ownComponentFamily}:{ownComponentName}", ownComponentName);
        string? family = !string.IsNullOrEmpty(typeElem.FamilyName)
            ? typeElem.FamilyName : typeElem.ValidatedSystemFamilyName ?? (currentProfile ? typeElem.ValidatedMepFamilyName : null);
        string? name = (typeElem.CategoryId == -2000123 ? null : typeElem.ValidatedStairComponentTypeName)
            ?? typeElem.ValidatedDuctTypeName ?? (currentProfile ? typeElem.ValidatedMepTypeName : null) ?? typeElem.Name;
        return (!string.IsNullOrEmpty(family) && !string.IsNullOrEmpty(name)
            ? $"{family}:{name}"
            : name, name);
    }

    /// <summary>
    /// The Name of a type object: the type name alone in the current profile, "Family:Type" in the
    /// legacy profile.
    /// </summary>
    private static string? TypeObjectName(Element typeElem, bool currentProfile)
    {
        var (full, own) = TypeObjectNameParts(typeElem);
        if (!currentProfile || full == null) return full;
        return own ?? full[(full.IndexOf(':') + 1)..];
    }

    /// <summary>
    /// Reads the type objects and IfcRelDefinesByType relations written since <paramref
    /// name="startIndex"/>; a curtain wall is a container without a body of its own and its type
    /// gets no material.
    /// </summary>
    private static void AssociateTypeObjectMaterials(
        StepWriter w, int ownerHistId, int startIndex,
        IReadOnlyDictionary<int, int> relatingMaterialByProductEntity, HostLayerSets? layerSets = null,
        IReadOnlyDictionary<int, (int Index, string GuidArg, List<int> Products)>? directRelations = null)
    {
        var typeClassByEntity = new Dictionary<int, string>();
        var firstMemberByType = new List<(int TypeEntityId, int FirstMemberEntityId)>();
        for (int index = startIndex; index < w.EntityCount; index++)
        {
            var (id, type, args) = w.EntityAt(index);
            if (type.EndsWith("TYPE", StringComparison.Ordinal) || type is "IFCDOORSTYLE" or "IFCWINDOWSTYLE" or "IFCTYPEPRODUCT")
                typeClassByEntity[id] = type;
            if (type != "IFCRELDEFINESBYTYPE") continue;
            string[] relation = SplitStepArguments(args);
            string[] members = SplitStepArguments(relation[4][1..^1]);
            if (members.Length == 0 || !int.TryParse(relation[5].AsSpan(1), out int typeEntityId)
                || !int.TryParse(members[0].AsSpan(1), out int firstMember))
                continue;
            firstMemberByType.Add((typeEntityId, firstMember));
        }

        var typesByRelatingMaterial = new SortedDictionary<int, List<int>>();
        var typesByLayerSet = new SortedDictionary<int, List<int>>();
        foreach (var (typeEntityId, firstMember) in firstMemberByType)
        {
            if (layerSets != null && typeClassByEntity.GetValueOrDefault(typeEntityId) == "IFCSTAIRFLIGHTTYPE") continue;
            // The current profile: a wall type takes the layer set of its walls
            // (the wall type rule), a slab type the one of its floors when they got a
            // usage (the host-object export with the type handle); ceilings and roofs do not.
            if (layerSets != null && typeClassByEntity.GetValueOrDefault(typeEntityId) is { } hostTypeClass
                && (hostTypeClass == "IFCWALLTYPE" || hostTypeClass == "IFCSLABTYPE" && layerSets.UsageProducts.Contains(firstMember))
                && layerSets.ByProduct.TryGetValue(firstMember, out int typeLayerSet))
            {
                if (!typesByLayerSet.TryGetValue(typeLayerSet, out var typed)) typesByLayerSet[typeLayerSet] = typed = new List<int>();
                typed.Add(typeEntityId);
                continue;
            }
            // Host objects (walls, floors, ceilings, roofs) give their type the layer set instead.
            string? hostOrFamilyTypeClass = typeClassByEntity.GetValueOrDefault(typeEntityId);
            bool slabFamilyType = layerSets != null && hostOrFamilyTypeClass == "IFCSLABTYPE"
                && layerSets.TypeOnlyProducts.Contains(firstMember);
            bool hostType = hostOrFamilyTypeClass is null or "IFCCURTAINWALLTYPE" or "IFCWALLTYPE"
                or "IFCSLABTYPE" or "IFCCOVERINGTYPE" or "IFCROOFTYPE";
            if (hostType && !slabFamilyType
                || !relatingMaterialByProductEntity.TryGetValue(firstMember, out int relatingMaterial))
                continue;
            if (!typesByRelatingMaterial.TryGetValue(relatingMaterial, out var types))
                typesByRelatingMaterial[relatingMaterial] = types = new List<int>();
            types.Add(typeEntityId);
        }
        foreach (var (relatingMaterial, typeEntityIds) in typesByRelatingMaterial)
        {
            if (directRelations != null && directRelations.TryGetValue(relatingMaterial, out var direct))
            {
                w.ReplaceArgs(direct.Index, $"{direct.GuidArg},{R(ownerHistId)},$,$,"
                    + $"{StepWriter.List(direct.Products.Concat(typeEntityIds).Select(R))},{R(relatingMaterial)}");
                continue;
            }
            w.Add("IFCRELASSOCIATESMATERIAL",
                $"{S(IfcGuid.FromName($"type-materials:{relatingMaterial}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(typeEntityIds.Select(R))},{R(relatingMaterial)}");
        }
        foreach (var (layerSet, typeEntityIds) in typesByLayerSet)
            w.Add("IFCRELASSOCIATESMATERIAL",
                $"{S(IfcGuid.FromName($"type-layer-set:{layerSet}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(typeEntityIds.Select(R))},{R(layerSet)}");
    }

    /// <summary>
    /// The pipe, duct or fitting whose insulation or lining <see cref="WriteInsulationCoverings"/>
    /// relates: a pipe or duct curve, or a pipe or duct fitting written as an IFCFLOWSEGMENT /
    /// IFCFLOWFITTING.
    /// </summary>
    internal static bool CanHaveInsulationOrLining(string ifcType, int? categoryId) => (ifcType, categoryId) is
        ("IFCFLOWSEGMENT", -2008044 or -2008000) or ("IFCFLOWFITTING", -2008049 or -2008010);

    /// <summary>Returns the number of relations written.</summary>
    private static int WriteInsulationCoverings(
        StepWriter w, int ownerHistId, IReadOnlyDictionary<int, Element> elemById,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> products,
        IReadOnlyDictionary<int, string> globalIds)
    {
        var coveringsByHost = new SortedDictionary<int, List<int>>();
        foreach (var (id, product) in products.OrderBy(pair => pair.Key))
            if (product.ifcType == "IFCCOVERING"
                && elemById.TryGetValue(id, out var covering)
                && covering.CategoryId is -2008122 or -2008123 or -2008124
                && covering.SerializedOwningElementId is int hostId and > 0
                && products.TryGetValue(hostId, out var host)
                && elemById.TryGetValue(hostId, out var hostElement)
                && CanHaveInsulationOrLining(host.ifcType, hostElement.CategoryId))
            {
                if (!coveringsByHost.TryGetValue(hostId, out var coverings)) coveringsByHost[hostId] = coverings = [];
                coverings.Add(product.entityId);
            }
        int written = 0;
        foreach (var (hostId, coverings) in coveringsByHost)
        {
            if (!globalIds.TryGetValue(hostId, out string? hostGlobalId)) continue;
            w.Add("IFCRELCOVERSBLDGELEMENTS",
                $"{S(IfcGuid.FromMd5($"IfcRelCoversBldgElements:{hostGlobalId}"))},{R(ownerHistId)},$,$,"
                + $"{R(products[hostId].entityId)},{StepWriter.List(coverings.Select(R))}");
            written++;
        }
        return written;
    }

    /// <summary>
    /// The layer sets of the host objects of one export: by product entity, and which products got
    /// a usage.
    /// </summary>
    private sealed record HostLayerSets(IReadOnlyDictionary<int, int> ByProduct, IReadOnlySet<int> UsageProducts,
        IReadOnlySet<int> TypeOnlyProducts);

    /// <summary>
    /// The connector export creates a distribution port for every unconnected connector of an MEP
    /// element and attaches it with IfcRelConnectsPortToElement (IFC2x3).
    /// </summary>
    /// <summary>
    /// The group export / the group relation pass of the export: every model group instance that holds
    /// an exported product (or a non-empty nested group) becomes an IfcGroup named "family:group
    /// type:id" with the family and type as object type.
    /// </summary>
    private void WriteModelGroups(
        StepWriter w, int ownerHistId, IReadOnlyDictionary<int, Element> elemById,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> products)
    {
        var membersByGroup = new Dictionary<int, List<int>>();
        foreach (var elem in elemById.Values.OrderBy(item => item.Id))
            if (elem.SerializedGroupId is int groupId && groupId != elem.Id)
            {
                if (!membersByGroup.TryGetValue(groupId, out var members)) membersByGroup[groupId] = members = [];
                members.Add(elem.Id);
            }

        var groupEntityIds = new Dictionary<int, int?>();
        // Nesting deeper than a few levels does not occur in a valid model; a deeper chain yields
        // no group.
        const int MaxGroupNesting = 32;
        int? Write(int groupId, int depth = 0)
        {
            if (depth > MaxGroupNesting) return null;
            if (groupEntityIds.TryGetValue(groupId, out int? done)) return done;
            groupEntityIds[groupId] = null; // a cycle yields no group
            if (!elemById.TryGetValue(groupId, out var group) || group.CategoryId != -2000095
                || group.SerializedGroupFamilyLabel is not { Length: > 0 } label
                || !membersByGroup.TryGetValue(groupId, out var memberIds))
                return null;
            string? typeName = group.RefStrings?.GetValueOrDefault("Ref_T1333")?.FirstOrDefault() ?? group.Name;
            if (string.IsNullOrEmpty(typeName)) return null;
            var memberEntities = new List<int>();
            foreach (int memberId in memberIds)
            {
                if (products.TryGetValue(memberId, out var product))
                {
                    memberEntities.Add(product.entityId);
                    if (CurrentProfile && _cutPairOpeningsByHostCurrent.TryGetValue(memberId, out var memberOpenings))
                        memberEntities.AddRange(memberOpenings);
                }
                else if (Write(memberId, depth + 1) is int nested) memberEntities.Add(nested);
            }
            if (memberEntities.Count == 0) return null;
            string objectType = $"{(CurrentProfile ? "Model Group" : label)}:{typeName}";
            int groupEntity = w.Add("IFCGROUP",
                $"{S(ResolveExactElementGlobalId(group, _usedExportIds, handleBased: CurrentProfile) ?? IfcGuid.FromName($"model-group:{groupId}"))},{R(ownerHistId)},"
                + $"{S($"{objectType}:{groupId.ToString(CultureInfo.InvariantCulture)}")},$,{S(objectType)}");
            w.Add("IFCRELASSIGNSTOGROUP",
                $"{S(ResolveExactElementGlobalId(group, _usedExportIds, 1, CurrentProfile) ?? IfcGuid.FromName($"model-group-rel:{groupId}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(memberEntities.Select(R))},$,{R(groupEntity)}");
            groupEntityIds[groupId] = groupEntity;
            return groupEntity;
        }
        foreach (int groupId in membersByGroup.Keys.OrderBy(id => id)) Write(groupId);
    }

    /// <summary>
    /// Systems are written in element id order. Not covered: the base equipment of a system,
    /// electrical circuits and the name override parameter.
    /// </summary>
    private void WriteMepSystems(
        StepWriter w, int ownerHistId, int buildingId, IReadOnlyDictionary<int, Element> elemById,
        SortedDictionary<int, SortedSet<int>> membersBySystem)
    {
        foreach (var (systemId, members) in membersBySystem)
        {
            if (members.Count == 0 || !elemById.TryGetValue(systemId, out var system)
                || system.SerializedMepSystem is not var (name, typeId))
                continue;
            string objectType = elemById.TryGetValue(typeId, out var type) ? type.Name ?? "" : "";
            string globalId = ResolveExactElementGlobalId(system, _usedExportIds, handleBased: CurrentProfile) ?? IfcGuid.FromName($"mep-system:{systemId}");
            int systemEntity = w.Add("IFCSYSTEM", $"{S(globalId)},{R(ownerHistId)},{S(name)},'',{S(objectType)}");
            w.Add("IFCRELSERVICESBUILDINGS",
                $"{S(IfcGuid.FromName($"mep-system-building:{systemId}"))},{R(ownerHistId)},'','',{R(systemEntity)},{StepWriter.List(R(buildingId))}");
            w.Add("IFCRELASSIGNSTOGROUP",
                $"{S(IfcGuid.FromMd5($"IfcRelAssignsToGroup:{globalId}"))},{R(ownerHistId)},'','',{StepWriter.List(members.Select(R))},$,{R(systemEntity)}");
        }
    }

    /// <summary>Writes the distribution ports of the MEP hosts.</summary>
    private static SortedDictionary<int, SortedSet<int>> WriteDistributionPorts(
        StepWriter w, int ownerHistId, IReadOnlyDictionary<int, Element> elemById,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> products, bool currentProfile)
    {
        var hostEntityIds = products.Values.Select(product => product.entityId).ToHashSet();
        var hostGlobalIds = new Dictionary<int, string>();
        for (int index = 0; index < w.EntityCount; index++)
            if (w.EntityAt(index) is var entity && hostEntityIds.Contains(entity.Id)
                && SplitStepArguments(entity.Args)[0] is { Length: > 2 } hostGlobalId)
                hostGlobalIds[entity.Id] = hostGlobalId[1..^1];
        if (currentProfile) return WriteConnectorGraphPorts(w, ownerHistId, elemById, products, hostGlobalIds);
        // The flow direction is a property of the family type's connector.
        static (string prefix, string flow)? PortKind(int direction, int systemType) => (direction, systemType) switch
        {
            (-1, _) => ("Port_", "SOURCEANDSINK"),
            (1, _) => ("InPort_", "SINK"),
            (2, 16) => ("OutPort_", "SOURCE"),
            (0, not 0) => ("Port_", "SOURCEANDSINK"),
            _ => null,
        };
        var portKindByTypeAndIndex = new Dictionary<(int TypeId, int Index), (string prefix, string flow)>();
        foreach (var (id, product) in products)
            if (product.ifcType is not "IFCFURNISHINGELEMENT"
                && elemById.TryGetValue(id, out var typed) && typed.SerializedMepConnectors is { Count: > 0 } typedConnectors)
                foreach (var (index, direction, systemType) in typedConnectors)
                    if (PortKind(direction, systemType) is { } known)
                        portKindByTypeAndIndex.TryAdd((typed.FamilyTypeId, index), known);
        foreach (var (id, product) in products.OrderBy(pair => pair.Key))
        {
            // Only products of the MEP exporters get ports; furnishing elements with connectors do
            // not.
            if (product.ifcType is "IFCFURNISHINGELEMENT"
                || !elemById.TryGetValue(id, out var elem) || elem.SerializedMepConnectors is not { Count: > 0 } connectors)
                continue;
            foreach (var (index, direction, systemType) in connectors)
            {
                (string prefix, string flow)? kind = PortKind(direction, systemType)
                    ?? (portKindByTypeAndIndex.TryGetValue((elem.FamilyTypeId, index), out var typeKind) ? typeKind : null);
                if (kind is not { } port) continue;
                string portGuid = hostGlobalIds.TryGetValue(product.entityId, out string? hostGuid)
                    ? IfcGuid.FromMd5($"{hostGuid}Sub-element:IfcDistributionPort Connector: {index.ToString(CultureInfo.InvariantCulture)}")
                    : IfcGuid.FromName($"distribution-port:{id}:{index}");
                int portId = w.Add("IFCDISTRIBUTIONPORT",
                    $"{S(portGuid)},{R(ownerHistId)},{S($"{port.prefix}{id.ToString(CultureInfo.InvariantCulture)}_{index.ToString(CultureInfo.InvariantCulture)}")},"
                    + $"{S("Flow")},{(currentProfile ? "''" : "$")},$,$,.{port.flow}.");
                string relGuid = IfcGuid.FromMd5($"IfcRelConnectsPortToElement:{index.ToString(CultureInfo.InvariantCulture)}:{portGuid}");
                // The current profile names the relation after its own GlobalId, the legacy profile
                // after the port's.
                w.Add("IFCRELCONNECTSPORTTOELEMENT",
                    $"{S(relGuid)},{R(ownerHistId)},"
                    + $"{S($"{id.ToString(CultureInfo.InvariantCulture)}|{(currentProfile ? relGuid : portGuid)}")},{S("Flow")},{R(portId)},{R(product.entityId)}");
            }
        }
        return [];
    }

    private static readonly HashSet<string> PortHostClasses = new(StringComparer.Ordinal)
    {
        "IFCDISTRIBUTIONELEMENT", "IFCDISTRIBUTIONCONTROLELEMENT", "IFCDISTRIBUTIONFLOWELEMENT", "IFCDISTRIBUTIONCHAMBERELEMENT",
        "IFCENERGYCONVERSIONDEVICE", "IFCFLOWCONTROLLER", "IFCFLOWFITTING", "IFCFLOWMOVINGDEVICE", "IFCFLOWSEGMENT",
        "IFCFLOWSTORAGEDEVICE", "IFCFLOWTERMINAL", "IFCFLOWTREATMENTDEVICE", "IFCELECTRICDISTRIBUTIONPOINT",
        "IFCBUILDINGELEMENTPROXY",
    };

    private static void DumpConnectorGraph(
        string path, IReadOnlyDictionary<int, Element> elemById,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> products)
    {
        string Kind(int id) => !elemById.TryGetValue(id, out var target) ? "A" : target.IsDiscovered ? "D" : target.IsBlockOnly ? "B"
            : products.TryGetValue(id, out var product) ? "P" + product.ifcType : "L";
        var lines = new List<string>();
        foreach (var (id, product) in products.OrderBy(pair => pair.Key))
        {
            elemById.TryGetValue(id, out var element);
            if (element?.SerializedConnectorGraph is { } connectors)
                lines.Add($"H\t{id}\t{product.ifcType}\t{(element.IsDiscovered ? 1 : 0)}\t{element.CategoryId}\t" + string.Join(" ",
                    connectors.Select((connector, position) => $"{connector.Index};{connector.Direction};"
                        + $"{(element.SerializedConnectorSystems is { } systems && position < systems.Count ? systems[position] : 0)};"
                        + string.Join(",", connector.Refs.Select(reference => $"{reference.Id}:{reference.Index}:{reference.Type}:{Kind(reference.Id)}")))));
            else if (PortHostClasses.Contains(product.ifcType))
                lines.Add($"N\t{id}\t{product.ifcType}\t{element?.CategoryId}");
        }
        File.WriteAllLines(path, lines);
    }

    /// <summary>
    /// The connector export of the current profile for every MEP host (<see cref="PortHostClasses"/>).
    /// </summary>
    private static SortedDictionary<int, SortedSet<int>> WriteConnectorGraphPorts(
        StepWriter w, int ownerHistId, IReadOnlyDictionary<int, Element> elemById,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> products,
        IReadOnlyDictionary<int, string> hostGlobalIds)
    {
        var graph = new SortedDictionary<int, List<(int Index, int Direction, int System, List<(int Id, int Index, int Type)> Refs)>>();
        if (Environment.GetEnvironmentVariable("RVTIO_PORT_GRAPH_DUMP") is { Length: > 0 } dumpPath)
            DumpConnectorGraph(dumpPath, elemById, products);
        foreach (var (id, product) in products)
            if (PortHostClasses.Contains(product.ifcType)
                && elemById.TryGetValue(id, out var host) && !host.IsDiscovered
                && host.SerializedConnectorGraph is { Count: > 0 } connectors
                && host.NativeRootClassName == null
                && hostGlobalIds.ContainsKey(product.entityId))
                graph[id] = connectors.Select((connector, position) => (connector.Index, connector.Direction,
                    host.SerializedConnectorSystems is { } systems && position < systems.Count ? systems[position] : 0,
                    new List<(int Id, int Index, int Type)>(connector.Refs))).ToList();
        foreach (var (hostId, connectors) in graph)
            foreach (var connector in connectors)
                foreach (var reference in connector.Refs.ToList())
                    if (reference.Id != hostId && graph.TryGetValue(reference.Id, out var other)
                        && other.FirstOrDefault(candidate => candidate.Index == reference.Index) is { Refs: { } otherRefs }
                        && !otherRefs.Any(candidate => candidate.Id == hostId))
                        otherRefs.Add((hostId, connector.Index, reference.Type));

        string Invariant(int value) => value.ToString(CultureInfo.InvariantCulture);
        string PortName(string flow, int hostId, int index) =>
            $"{(flow == "SINK" ? "InPort_" : flow == "SOURCE" ? "OutPort_" : "Port_")}{Invariant(hostId)}_{Invariant(index)}";
        const int DirectionIn = 1, DirectionOut = 2;
        var connected = new HashSet<(int, int)>();
        var systemMembers = new SortedDictionary<int, SortedSet<int>>();
        void Join(int system, params int[] entityIds)
        {
            if (system <= 0) return;
            if (!systemMembers.TryGetValue(system, out var members)) systemMembers[system] = members = [];
            members.UnionWith(entityIds);
        }

        void Standalone(int hostId, int index, int direction, int system)
        {
            string flow = direction is not (DirectionIn or DirectionOut) ? "SOURCEANDSINK" : direction == DirectionOut ? "SINK" : "SOURCE";
            int entityId = products[hostId].entityId;
            string portGuid = IfcGuid.FromMd5($"{hostGlobalIds[entityId]}Sub-element:IfcDistributionPort Connector: {Invariant(index)}");
            int portId = w.Add("IFCDISTRIBUTIONPORT",
                $"{S(portGuid)},{R(ownerHistId)},{S(PortName(flow, hostId, index))},{S("Flow")},'',$,$,.{flow}.");
            string relGuid = IfcGuid.FromMd5($"IfcRelConnectsPortToElement:{Invariant(index)}:{portGuid}");
            w.Add("IFCRELCONNECTSPORTTOELEMENT",
                $"{S(relGuid)},{R(ownerHistId)},{S($"{Invariant(hostId)}|{relGuid}")},{S("Flow")},{R(portId)},{R(entityId)}");
            Join(system, entityId, portId);
        }

        void Pair(int inHost, int outHost, int index, bool bidirectional)
        {
            if (connected.Contains((inHost, outHost)) || (bidirectional && connected.Contains((outHost, inHost)))) return;
            string inFlow = bidirectional ? "SOURCEANDSINK" : "SINK", outFlow = bidirectional ? "SOURCEANDSINK" : "SOURCE";
            int inEntity = products[inHost].entityId, outEntity = products[outHost].entityId;
            string inGlobalId = hostGlobalIds[inEntity], outGlobalId = hostGlobalIds[outEntity];
            string portInGuid = IfcGuid.FromMd5($"InPort{Invariant(index)}{inGlobalId}{outGlobalId}");
            string portOutGuid = IfcGuid.FromMd5($"OutPort{Invariant(index)}{outGlobalId}{inGlobalId}");
            int portIn = w.Add("IFCDISTRIBUTIONPORT",
                $"{S(portInGuid)},{R(ownerHistId)},{S(PortName(inFlow, inHost, index))},{S("Flow")},'',$,$,.{inFlow}.");
            string relInGuid = IfcGuid.FromMd5($"InPortRelConnects{Invariant(index)}{inGlobalId}{outGlobalId}");
            w.Add("IFCRELCONNECTSPORTTOELEMENT",
                $"{S(relInGuid)},{R(ownerHistId)},{S($"{Invariant(inHost)}|{relInGuid}")},{S("Flow")},{R(portIn)},{R(inEntity)}");
            int portOut = w.Add("IFCDISTRIBUTIONPORT",
                $"{S(portOutGuid)},{R(ownerHistId)},{S(PortName(outFlow, outHost, index))},{S("Flow")},'',$,$,.{outFlow}.");
            string relOutGuid = IfcGuid.FromMd5($"OutPortRelConnects{Invariant(index)}{outGlobalId}{inGlobalId}");
            w.Add("IFCRELCONNECTSPORTTOELEMENT",
                $"{S(relOutGuid)},{R(ownerHistId)},{S($"{Invariant(outHost)}|{relOutGuid}")},{S("Flow")},{R(portOut)},{R(outEntity)}");
            w.Add("IFCRELCONNECTSPORTS",
                $"{S(IfcGuid.FromMd5($"IfcRelConnectsPorts:{portInGuid}{portOutGuid}"))},{R(ownerHistId)},"
                + $"{S($"{portInGuid}|{portOutGuid}")},{S("Flow")},{R(portIn)},{R(portOut)},$");
            connected.Add((inHost, outHost));
            Join(graph[inHost].First(candidate => candidate.Index == index).System, inEntity, outEntity, portIn, portOut);
        }

        foreach (var (hostId, connectors) in graph)
            foreach (var connector in connectors)
            {
                // A connector with a reference to another registered MEP host counts as connected
                // whether or not that host has a connector graph of its own: it gets no port of its
                // own.
                bool IsConnected() => connector.Refs.Any(reference => reference.Id != hostId
                    && products.TryGetValue(reference.Id, out var target) && PortHostClasses.Contains(target.ifcType)
                    && elemById.TryGetValue(reference.Id, out var referenced) && !referenced.IsDiscovered);
                var neighbours = connector.Refs.Where(reference => reference.Id != hostId && graph.ContainsKey(reference.Id)).ToList();
                if (!IsConnected()) { Standalone(hostId, connector.Index, connector.Direction, connector.System); continue; }
                bool bidirectional = connector.Direction is not (DirectionIn or DirectionOut);
                foreach (var reference in neighbours)
                    if (graph[reference.Id].Any(candidate => candidate.Index == connector.Index))
                    {
                        if (connector.Direction == DirectionOut) Pair(reference.Id, hostId, connector.Index, false);
                        else Pair(hostId, reference.Id, connector.Index, bidirectional);
                    }
            }
        return systemMembers;
    }

    private static Dictionary<int, string> WriteTypeObjectsAndRelDefinesByType(
        StepWriter w, int ownerHistId, Dictionary<int, Element> elemById,
        Dictionary<int, (int entityId, int placementId, string ifcType)> exportedProducts,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        IReadOnlyDictionary<int, bool?> componentTypeIsExternalValues) =>
        WriteTypeObjectsAndRelDefinesByTypeCore(w, ownerHistId, elemById, exportedProducts,
            propertySingleValueIds, componentTypeIsExternalValues, currentProfile: false);

    private static Dictionary<int, string> WriteTypeObjectsAndRelDefinesByTypeCore(
        StepWriter w, int ownerHistId, Dictionary<int, Element> elemById,
        Dictionary<int, (int entityId, int placementId, string ifcType)> exportedProducts,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        IReadOnlyDictionary<int, bool?> componentTypeIsExternalValues, bool currentProfile)
    {
        var exactTypeGuids = new Dictionary<int, string>();
        var firstInstanceIfcType = new Dictionary<(int typeId, int symbolId, string typeClass, int ownerId, int systemTypeId), string>();
        // ownerId is the family instance whose own geometry created the type
        // (UsesInstanceGeometry), else 0. systemTypeId is the instance's MEP system type for mapped
        // family instances of the pipe and duct categories (TypeObjectKey.systemTypeId), else 0.
        var typeGroups = new Dictionary<(int typeId, int symbolId, string typeClass, int ownerId, int systemTypeId), List<int>>();
        var typeGroupOrder = new List<(int typeId, int symbolId, string typeClass, int ownerId, int systemTypeId)>();
        var predefinedTypes = new Dictionary<(int typeId, int symbolId, string typeClass, int ownerId, int systemTypeId), string>();
        var exactSystemTypeGroups = new HashSet<(int typeId, int symbolId, string typeClass, int ownerId, int systemTypeId)>();
        var firstMemberElementId = new Dictionary<(int typeId, int symbolId, string typeClass, int ownerId, int systemTypeId), int>();
        var connectedSystemTypes = currentProfile ? ResolveConnectedSystemTypes(elemById) : null;
        var stairShapes = currentProfile ? ReadProductAttributes(w, exportedProducts,
            exportedProducts.Where(pair => pair.Value.ifcType == "IFCSTAIR").Select(pair => pair.Key), 8) : null;

        foreach (var (productKey, product) in exportedProducts)
        {
            // The IfcSlab of a roof (the current profile) is keyed by the negated id of the roof
            // and typed by the type of the roof.
            int elementId = productKey < 0 && !elemById.ContainsKey(productKey) ? -productKey : productKey;
            if (!elemById.TryGetValue(elementId, out var instElem))
                continue;
            // A roof that only holds a curtain system has no body: it is typed by the curtain wall
            // type of its roof type.
            bool roofContainer = product.ifcType == "IFCROOF" && instElem.CategoryId == -2000035
                && instElem.Geometry?.Faces is not { Count: > 0 }
                && (instElem.BoundingBox ?? instElem.Geometry?.BoundingBox) is not { Length: >= 6 };
            string? typeClass = null;
            if (roofContainer) typeClass = "IFCCURTAINWALLTYPE";
            // IFC2X3 has no IfcStairType: the current profile types a stair by the generic
            // IfcTypeProduct.
            else if (currentProfile && product.ifcType == "IFCSTAIR") typeClass = "IFCTYPEPRODUCT";
            else if (!TypeClassByProductClass.TryGetValue(product.ifcType, out typeClass)
                && product.ifcType is not ("IFCFLOWFITTING" or "IFCFLOWCONTROLLER"))
                continue;

            if (product.ifcType == "IFCRAILING" && instElem.NativeMasterSymbolId is not > 0)
                continue;
            if (product.ifcType == "IFCCOVERING" && instElem.CategoryId == -2008122)
                continue;

            int typeElemId = ResolveTypeObjectElementId(instElem, elemById, currentProfile);
            if (typeElemId <= 0 || !elemById.TryGetValue(typeElemId, out var canonicalType))
                continue;

            // An occurrence's category or display name cannot substitute for the canonical type
            // record.
            typeClass = (product.ifcType, canonicalType.CategoryId) switch
            {
                ("IFCFLOWTERMINAL", -2001120) => "IFCLIGHTFIXTURETYPE", // OST_LightingFixtures
                ("IFCFURNISHINGELEMENT", -2001100) => "IFCSYSTEMFURNITUREELEMENTTYPE", // OST_FurnitureSystems
                ("IFCFLOWSEGMENT", -2008000) => "IFCDUCTSEGMENTTYPE", // OST_DuctCurves
                ("IFCFLOWSEGMENT", -2008044 or -2008050) => "IFCPIPESEGMENTTYPE", // OST_PipeCurves, OST_FlexPipeCurves
                ("IFCFLOWSEGMENT", -2008130) => "IFCCABLECARRIERSEGMENTTYPE", // OST_CableTray
                ("IFCFLOWFITTING", -2008049) => "IFCPIPEFITTINGTYPE", // OST_PipeFitting
                ("IFCFLOWFITTING", -2008126 or -2008128) => "IFCCABLECARRIERFITTINGTYPE", // OST_CableTrayFitting, OST_ConduitFitting
                ("IFCFLOWFITTING", -2008010) => "IFCDUCTFITTINGTYPE", // OST_DuctFitting
                ("IFCFLOWSEGMENT", -2008020) => "IFCDUCTSEGMENTTYPE", // OST_FlexDuctCurves
                ("IFCFLOWSEGMENT", -2008132) => "IFCCABLECARRIERSEGMENTTYPE", // OST_Conduit
                ("IFCFLOWTERMINAL", -2008013) => "IFCAIRTERMINALTYPE", // OST_DuctTerminal
                ("IFCFLOWTERMINAL", -2008083) => "IFCELECTRICAPPLIANCETYPE", // OST_DataDevices
                ("IFCFLOWTERMINAL", -2008099) => "IFCFIRESUPPRESSIONTERMINALTYPE", // OST_Sprinklers
                ("IFCFLOWCONTROLLER", -2008055) => "IFCVALVETYPE", // OST_PipeAccessory
                _ => typeClass,
            };
            if (typeClass == null) continue;

            // The family-instance export keys TypeObjectKey by
            // GetOriginalSymbol, not familyInstance.Symbol (the display type).
            int originalSymbolId = 0;
            int ownerId = 0;
            if (product.ifcType is "IFCDOOR" or "IFCWINDOW"
                && instElem.ValidatedOriginalFamilySymbolId is > 0)
            {
                int ownSymbolId = instElem.ValidatedOriginalFamilySymbolId.Value;
                if (ownSymbolId != instElem.Id && elemById.TryGetValue(ownSymbolId, out var ownSymbol)
                    && ownSymbol.Id == ownSymbolId)
                    originalSymbolId = ownSymbolId;
            }
            if ((product.ifcType is "IFCMEMBER" or "IFCPLATE" or "IFCCOLUMN"
                or "IFCBUILDINGELEMENTPROXY" or "IFCREINFORCINGMESH" or "IFCFURNISHINGELEMENT"
                or "IFCFLOWTERMINAL" or "IFCFLOWSEGMENT" or "IFCFLOWFITTING" or "IFCFLOWCONTROLLER"
                or "IFCSLAB" or "IFCSTAIRFLIGHT" || currentProfile && product.ifcType == "IFCBEAM")
                && instElem.Geometry?.ExactMappedInstances is { Count: > 0 } mapped
                // The runs and landings of a stair are not family instances: their type is the type
                // element.
                && !(currentProfile && instElem.CategoryId is StairsRunsCategoryId or StairsLandingsCategoryId))
            {
                var mappedSymbol = mapped.Count == 1 ? mapped[0] : !currentProfile ? null
                    : mapped.LastOrDefault(instance => elemById.TryGetValue(instance.SymbolId, out var candidate)
                        && candidate.SerializedExportId != null) ?? mapped[^1];
                if (mappedSymbol != null && mappedSymbol.SymbolId > 0
                    && mappedSymbol.SymbolId != instElem.Id
                    && elemById.TryGetValue(mappedSymbol.SymbolId, out var originalSymbol)
                    && originalSymbol.Id == mappedSymbol.SymbolId)
                {
                    originalSymbolId = originalSymbol.Id;
                    if (product.ifcType == "IFCBUILDINGELEMENTPROXY" && (currentProfile
                            ? UsesInstanceGeometryOfSymbolCurrent(instElem, originalSymbol)
                            : UsesInstanceGeometry(instElem, originalSymbol)))
                        ownerId = instElem.Id;
                }
                else
                    continue;
            }
            // A beam, column, and a proxy or furnishing element without a GInstance, is keyed by
            // its type element and gets a type of its own when it carries geometry of its own.
            if (currentProfile && originalSymbolId == 0 && product.ifcType is "IFCBEAM" or "IFCCOLUMN" or "IFCBUILDINGELEMENTPROXY" or "IFCFURNISHINGELEMENT"
                && UsesInstanceGeometryOfTypeCurrent(instElem, canonicalType))
                ownerId = instElem.Id;
            if (TypeKeyDiagnostics(product.ifcType))
                DiagnosticSink.WriteLine($"TKD {product.ifcType} element={elementId} type={typeElemId} symbol={originalSymbolId} own={ownerId}"
                    + $" instance[{DescribeStoredGeometry(instElem)}] symbol[{DescribeStoredGeometry(originalSymbolId > 0 ? elemById[originalSymbolId] : null)}]"
                    + $" type[{DescribeStoredGeometry(canonicalType)}]");
            int systemTypeId = originalSymbolId > 0 || currentProfile && product.ifcType == "IFCFLOWSEGMENT"
                ? ResolveTypeKeySystemTypeId(instElem, canonicalType, connectedSystemTypes) : 0;
            // The slot holds the shape of a stair (no stair has a system type): its types split by
            // shape.
            if (stairShapes != null && stairShapes.TryGetValue(elementId, out string? stairShape))
                systemTypeId = StairShapeKeyCurrent(stairShape);
            // So does the type of a stair run, by the style of the run
            // (getValidatedStairFlightType).
            if (currentProfile && typeClass == "IFCSTAIRFLIGHTTYPE") systemTypeId = StairRunStyleKeyCurrent(instElem);
            var key = (typeElemId, originalSymbolId, typeClass, ownerId, systemTypeId);
            bool exactSystemType = originalSymbolId == 0 && instElem.SerializedSystemTypeId == typeElemId
                && instElem.TypeId == typeElemId && instElem.CategoryId == canonicalType.CategoryId
                && (product.ifcType, canonicalType.SerializedSystemTypeClassId, canonicalType.CategoryId) switch
                {
                    ("IFCWALL" or "IFCWALLSTANDARDCASE" or "IFCCURTAINWALL", 512 or 2559, -2000011) => true,
                    ("IFCSLAB", 1915, -2000032 or -2001300) => true,
                    ("IFCCOVERING", 646, -2000038) => true,
                    ("IFCSLAB", 3452, RoofCategoryId) => currentProfile,
                    _ => false,
                };
            string predefinedType = currentProfile && typeClass == "IFCSTAIRFLIGHTTYPE" ? StairFlightTypePredefinedTypeCurrent(instElem)
                : ResolveNativeTypePredefinedType(canonicalType, instElem, typeClass, currentProfile);
            if (!typeGroups.TryGetValue(key, out var members))
            {
                typeGroups[key] = members = new List<int>();
                typeGroupOrder.Add(key);
                predefinedTypes[key] = predefinedType;
                if (exactSystemType) exactSystemTypeGroups.Add(key);
            }
            else
            {
                if (predefinedTypes[key] != predefinedType) predefinedTypes[key] = "NOTDEFINED";
                if (!exactSystemType) exactSystemTypeGroups.Remove(key);
            }
            members.Add(product.entityId);
            firstInstanceIfcType.TryAdd(key, product.ifcType);
            firstMemberElementId[key] = firstMemberElementId.TryGetValue(key, out int earlier)
                ? Math.Min(earlier, elementId) : elementId;
        }

        // A native type may govern both walls and curtain walls.
        var classCounts = typeGroupOrder.GroupBy(key => (key.typeId, key.symbolId, key.ownerId, key.systemTypeId))
            .ToDictionary(group => group.Key, group => group.Select(key => key.typeClass).Distinct().Count());
        var guidClaimant = typeGroupOrder.Where(key => key.symbolId > 0)
            .GroupBy(key => (key.symbolId, key.ownerId))
            .ToDictionary(group => group.Key, group => group.MinBy(key => firstMemberElementId[key]));
        // The Name literal written for the door or window that made each style, read back from the
        // writer.
        var creatorNames = currentProfile ? ReadProductAttributes(w, exportedProducts,
            typeGroupOrder.Where(key => key.typeClass is "IFCDOORSTYLE" or "IFCWINDOWSTYLE")
                .Select(key => firstMemberElementId[key]), 2)
            .Where(pair => pair.Value.Length >= 2 && pair.Value[0] == '\'')
            .ToDictionary(pair => pair.Key, pair => pair.Value) : null;
        var usedExportIds = new HashSet<Guid>();
        foreach (var key in typeGroupOrder)
        {
            var (typeElemId, originalSymbolId, typeClass, ownerId, systemTypeId) = key;
            var memberEntityIds = typeGroups[key];
            var typeElem = elemById[typeElemId];
            // The current profile makes a window style from the original family symbol
            // (createWindowStyle), and tags it by it.
            string tagArg = S((typeClass == "IFCPLATETYPE" ? firstMemberElementId[key]
                    : currentProfile && typeClass == "IFCWINDOWSTYLE" && originalSymbolId > 0 ? originalSymbolId : typeElemId)
                .ToString(CultureInfo.InvariantCulture));
            string nameArg = S(typeClass == "IFCTYPEPRODUCT" ? TypeObjectName(typeElem, currentProfile) : TypeObjectNameParts(typeElem, currentProfile).Full);
            string identityKey = originalSymbolId == 0
                ? typeElemId.ToString(CultureInfo.InvariantCulture)
                : $"{typeElemId.ToString(CultureInfo.InvariantCulture)}:symbol:{originalSymbolId.ToString(CultureInfo.InvariantCulture)}";
            if (ownerId > 0) identityKey += $":instance:{ownerId.ToString(CultureInfo.InvariantCulture)}";
            if (systemTypeId > 0) identityKey += $":system:{systemTypeId.ToString(CultureInfo.InvariantCulture)}";
            if (classCounts[(typeElemId, originalSymbolId, ownerId, systemTypeId)] > 1)
                identityKey += $":{typeClass}";
            string guidArg = S(IfcGuid.FromName($"type:{identityKey}"));
            int firstElementId = firstMemberElementId[key];
            IReadOnlyList<int> styleDefinitions = creatorNames != null && typeClass is "IFCDOORSTYLE" or "IFCWINDOWSTYLE"
                && creatorNames.TryGetValue(firstElementId, out string? creatorNameLiteral)
                    ? BuildOpeningStyleDefinitionsCurrent(w, ownerHistId, typeClass, elemById[firstElementId], creatorNameLiteral,
                        usedExportIds)
                    : [];
            string hasPropertySetsArg = currentProfile
                ? BuildTypeHasPropertySetsCurrent(w, ownerHistId, typeClass, firstInstanceIfcType[key],
                    typeElem, propertySingleValueIds, identityKey, styleDefinitions, elemById)
                : BuildTypeHasPropertySets(
                    w, ownerHistId, typeClass, typeElem, propertySingleValueIds,
                    componentTypeIsExternalValues, identityKey);

            int typeEntityId;
            if (typeClass is "IFCDOORSTYLE" or "IFCWINDOWSTYLE")
            {
                typeEntityId = w.Add(typeClass,
                    $"{guidArg},{R(ownerHistId)},{nameArg},$,$,{hasPropertySetsArg},$,{tagArg},"
                    + ".NOTDEFINED.,.NOTDEFINED.,.F.,.F.");
            }
            else if (typeClass == "IFCTYPEPRODUCT")
            {
                // An IfcTypeProduct has no ElementType: GlobalId, OwnerHistory, Name, Description,
                // ApplicableOccurrence, HasPropertySets, RepresentationMaps, Tag.
                typeEntityId = w.Add(typeClass, $"{guidArg},{R(ownerHistId)},{nameArg},$,$,{hasPropertySetsArg},$,{tagArg}");
            }
            else
            {
                string trailingArgs = TypeClassesWithPredefinedType.Contains(typeClass)
                    ? $",.{predefinedTypes[key]}."
                    : typeClass == "IFCFURNITURETYPE" ? ",$" : "";
                typeEntityId = w.Add(typeClass,
                    $"{guidArg},{R(ownerHistId)},{nameArg},$,$,{hasPropertySetsArg},$,{tagArg},$" + trailingArgs);
            }

            // The GlobalId rule uses the original symbol's own ExportId for mapped types, except
            // overrides/collisions.
            bool typeElementGuid = exactSystemTypeGroups.Contains(key)
                || typeClass is "IFCPIPESEGMENTTYPE" or "IFCCABLECARRIERSEGMENTTYPE"
                || currentProfile && (typeClass is "IFCDUCTSEGMENTTYPE" or "IFCSTAIRFLIGHTTYPE" or "IFCTYPEPRODUCT" or "IFCRAILINGTYPE"
                    || typeClass == "IFCSLABTYPE" && typeElem.CategoryId == StairsLandingsCategoryId);
            int guidSourceId = originalSymbolId > 0
                ? guidClaimant[(originalSymbolId, ownerId)] == key ? originalSymbolId : 0
                : typeElementGuid ? typeElemId : 0;
            // A type made from one instance's own geometry takes that instance's InstanceAsType
            // GUID.
            if (ownerId > 0)
            {
                if (elemById[ownerId].SerializedExportId is { } ownerExportId)
                    exactTypeGuids[typeEntityId] = IfcGuid.ToIfcGuid(ElementExportIds.SubElementId(
                        currentProfile ? elemById[ownerId].SerializedHandleExportId ?? ownerExportId : ownerExportId, InstanceAsTypeSubElementIndex));
            }
            else if (guidSourceId > 0 && elemById[guidSourceId] is { } source
                && source.SerializedExportId is { } exportId
                && !HasIfcGuidOverride(source.Parameters.Concat(typeElem.Parameters), currentProfile))
                // The current profile gives a door or window style the DoorStyle sub-element (21) of the symbol's ExportId.
                exactTypeGuids[typeEntityId] = IfcGuid.ToIfcGuid(currentProfile && typeClass is "IFCDOORSTYLE" or "IFCWINDOWSTYLE"
                    ? ElementExportIds.SubElementId(source.SerializedHandleExportId ?? exportId, DoorStyleSubElementIndex) : exportId);

            w.Add("IFCRELDEFINESBYTYPE",
                $"{S(IfcGuid.FromName($"rel-defines-by-type:{identityKey}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(memberEntityIds.Select(R))},{R(typeEntityId)}");
        }
        return exactTypeGuids;
    }

    /// <summary>
    /// Zero when the category or the parameter is absent, or the instance belongs to several
    /// systems (the parameter is then -1).
    /// </summary>
    internal static int ResolveTypeKeySystemTypeId(Element instance, Element type,
        IReadOnlyDictionary<int, int>? connectedSystemTypes = null)
    {
        int parameterId = type.CategoryId switch
        {
            // OST_FlexPipeCurves, PipeCurves, PlaceHolderPipes, PlumbingFixtures, PipeAccessory,
            // PipeFitting, PipeInsulations, Sprinklers
            -2008050 or -2008044 or -2008161 or -2001160 or -2008055 or -2008049 or -2008122 or -2008099 => -1140334,
            // OST_DuctAccessory, DuctCurves, DuctFitting, DuctInsulations, DuctLinings,
            // DuctTerminal, FlexDuctCurves, PlaceHolderDucts
            -2008016 or -2008000 or -2008010 or -2008123 or -2008124 or -2008013 or -2008020 or -2008160 => -1140333,
            _ => 0,
        };
        if (parameterId == 0) return 0;
        if (instance.SerializedCurveSystemTypeId is > 0 and var stored) return stored;
        if (instance.Parameters.FirstOrDefault(p => p.Id == parameterId)?.Value is int id and > 0) return id;
        return connectedSystemTypes != null && connectedSystemTypes.TryGetValue(instance.Id, out int connected) ? connected : 0;
    }

    /// <summary>The stair export supplies LANDING for OST_StairsLandings.</summary>
    internal static string ResolveSlabOccurrencePredefinedType(Element occurrence, Element? type,
        IReadOnlyDictionary<int, int> occurrenceCounts)
        => occurrence.Id > 0 && !occurrence.IsBlockOnly && occurrence.CategoryId is -2000920 or -2001300
            && occurrenceCounts.GetValueOrDefault(occurrence.Id) == 1
            && !HasIfcTypeOverride(occurrence)
            && (type == null || type.Id > 0 && type.Id != occurrence.Id
                && occurrence.FamilyTypeId == type.Id && type.CategoryId == occurrence.CategoryId
                && occurrenceCounts.GetValueOrDefault(type.Id) == 1 && !HasIfcTypeOverride(type))
            ? occurrence.CategoryId == -2000920 ? "LANDING" : "BASESLAB" : "FLOOR";

    /// <summary>Other categories and unresolved overrides retain legacy NOTDEFINED.</summary>
    internal static string ResolveCoveringOccurrencePredefinedType(Element occurrence, Element? type,
        IReadOnlyDictionary<int, int> occurrenceCounts)
        => occurrence.Id > 0 && !occurrence.IsBlockOnly && occurrence.CategoryId is -2000038 or -2008122
            && occurrenceCounts.GetValueOrDefault(occurrence.Id) == 1
            && !HasIfcTypeOverride(occurrence)
            && (type == null || type.Id > 0 && type.Id != occurrence.Id
                && occurrence.FamilyTypeId == type.Id && type.CategoryId == occurrence.CategoryId
                && occurrenceCounts.GetValueOrDefault(type.Id) == 1 && !HasIfcTypeOverride(type))
            ? occurrence.CategoryId == -2008122 ? "INSULATION" : "CEILING" : "NOTDEFINED";

    /// <summary>Both the own type and occurrence must agree on category.</summary>
    private static string ResolveNativeTypePredefinedType(Element type, Element occurrence, string typeClass, bool currentProfile = false)
    {
        if (currentProfile && typeClass == "IFCSLABTYPE" && type.CategoryId == CurrentFoundationCategoryId
            && occurrence.CategoryId is CurrentFloorCategoryId or CurrentFoundationCategoryId
            && !HasIfcTypeOverride(type) && !HasIfcTypeOverride(occurrence))
            return "BASESLAB";
        if (currentProfile && typeClass == "IFCSLABTYPE" && type.CategoryId == RoofCategoryId && occurrence.CategoryId == RoofCategoryId
            && !HasIfcTypeOverride(type) && !HasIfcTypeOverride(occurrence))
            return "ROOF";
        if (type.CategoryId == null || type.CategoryId != occurrence.CategoryId)
            return "NOTDEFINED";
        string value = (typeClass, type.CategoryId) switch
        {
            ("IFCWALLTYPE", -2000011) when type.SerializedBasicWallTypeFunction is >= 0 and <= 5 => "STANDARD",
            ("IFCSLABTYPE", -2000032) => "FLOOR",
            ("IFCSLABTYPE", -2000920) => "LANDING",
            ("IFCCOVERINGTYPE", -2000038) => "CEILING",
            ("IFCMEMBERTYPE", -2000171) => "MULLION",
            ("IFCPLATETYPE", -2000170) => "CURTAIN_PANEL",
            ("IFCPIPESEGMENTTYPE", -2008050) => "FLEXIBLESEGMENT",
            ("IFCDUCTSEGMENTTYPE", -2008020) => "FLEXIBLESEGMENT",
            ("IFCCABLECARRIERSEGMENTTYPE", -2008132) => "CONDUITSEGMENT",
            ("IFCCABLECARRIERSEGMENTTYPE", -2008130) => "CABLETRAYSEGMENT",
            _ => "NOTDEFINED",
        };
        return value == "NOTDEFINED" || HasIfcTypeOverride(type) || HasIfcTypeOverride(occurrence)
            ? "NOTDEFINED" : value;
    }

    /// <summary>
    /// A roof without geometry of its own that holds a curtain system: its panels and mullions
    /// point to it as their host.
    /// </summary>
    internal static Dictionary<int, List<int>> ResolveRoofContainerChildren(
        IEnumerable<Element> elements, IReadOnlyDictionary<int, Element> byId,
        IReadOnlyDictionary<int, int> occurrenceCounts)
    {
        var result = new Dictionary<int, List<int>>();
        foreach (var child in elements)
        {
            if (child.Id <= 0 || child.CategoryId is not (-2000170 or -2000171)
                || occurrenceCounts.GetValueOrDefault(child.Id) != 1)
                continue;
            int hostId = child.SerializedCurtainHostId is > 0 ? child.SerializedCurtainHostId.Value
                : child.SerializedHostId ?? 0;
            if (hostId <= 0 || !byId.TryGetValue(hostId, out var roof) || roof.Id != hostId
                || roof.CategoryId != -2000035 || roof.IsBlockOnly
                || occurrenceCounts.GetValueOrDefault(roof.Id) != 1
                || (roof.BoundingBox ?? roof.Geometry?.BoundingBox) is { Length: >= 6 }
                || roof.Geometry?.Faces is { Count: > 0 })
                continue;
            if (!result.TryGetValue(roof.Id, out var children))
                result[roof.Id] = children = new List<int>();
            children.Add(child.Id);
        }
        return result;
    }

    internal static Dictionary<int, List<int>> ResolveExactCurtainChildren(
        IEnumerable<Element> elements, IReadOnlyDictionary<int, Element> byId,
        IReadOnlyDictionary<int, int> occurrenceCounts)
    {
        var result = new Dictionary<int, List<int>>();
        foreach (var child in elements)
        {
            if (child.Id <= 0 || child.CategoryId is not (-2000170 or -2000171 or -2000014 or -2000023 or -2000011)
                || child.SerializedCurtainHostId is not > 0
                || occurrenceCounts.GetValueOrDefault(child.Id) != 1
                || !byId.TryGetValue(child.SerializedCurtainHostId.Value, out var parent)
                || parent.Id != child.SerializedCurtainHostId.Value || parent.Id == child.Id
                || parent.CategoryId != -2000011 || parent.IsBlockOnly
                || occurrenceCounts.GetValueOrDefault(parent.Id) != 1
                || parent.FamilyTypeId <= 0 || !byId.TryGetValue(parent.FamilyTypeId, out var type)
                || type.Id != parent.FamilyTypeId || occurrenceCounts.GetValueOrDefault(type.Id) != 1
                || type.CategoryId != -2000011 || type.SerializedCurtainWallFunction is not (>= 0 and <= 5)
                || type.SerializedBasicWallTypeFunction != null || type.IsSerializedStackedWallType
                || HasIfcTypeOverride(parent) || HasIfcTypeOverride(type))
                continue;
            if (!result.TryGetValue(parent.Id, out var children))
                result[parent.Id] = children = new List<int>();
            children.Add(child.Id);
        }
        return result;
    }

    private static Element? MepCurveType(Element occurrence, IReadOnlyDictionary<int, Element> elementsById) =>
        occurrence.SerializedMepCurveTypeId is int typeId && typeId > 0
            && elementsById.TryGetValue(typeId, out Element? type) && type.Id == typeId ? type : null;

    /// <summary>
    /// The own SymbolInfo name of the RbsCurve type of a pipe, flex pipe, pipe insulation, round
    /// duct or cable tray; null when the link or the name is unvalidated.
    /// </summary>
    internal static string? ResolveMepCurveTypeName(Element occurrence, IReadOnlyDictionary<int, Element> elementsById) =>
        MepCurveType(occurrence, elementsById) is { } type
            && (type.ValidatedMepTypeName ?? type.ValidatedDuctTypeName) is { Length: > 0 } name ? name : null;

    /// <summary>"{system family}:{type name}" of an MEP curve occurrence, only when both parts are validated.</summary>
    internal static string? ResolveMepCurveFamilyAndTypeName(
        Element occurrence, IReadOnlyDictionary<int, Element> elementsById) =>
        MepCurveType(occurrence, elementsById) is { } type
            && (type.ValidatedMepFamilyName ?? type.ValidatedSystemFamilyName) is { Length: > 0 } family
            && (type.ValidatedMepTypeName ?? type.ValidatedDuctTypeName) is { Length: > 0 } name
            ? $"{family}:{name}" : null;

    /// <summary>The "Family:Type" name of a product: the MEP curve name, the type object name of a family type, or the validated type name with its family.</summary>
    internal static string ResolveProductFamilyAndTypeName(
        Element element, string ifcType, IReadOnlyDictionary<int, Element> elementsById,
        IReadOnlyDictionary<int, int> elementIdOccurrenceCounts, bool currentProfile = false)
    {
        // The current profile names a pipe, pipe insulation or cable tray after its own RbsCurve
        // type and that type's system family ("Pipe Types:{type}", "Pipe Insulation:{type}", "Cable
        // Tray with Fittings:{type}").
        if (currentProfile && ResolveMepCurveFamilyAndTypeName(element, elementsById) is { } mepFamilyAndType)
            return mepFamilyAndType;
        if (element.FamilyTypeId > 0 && element.TypeId == element.FamilyTypeId
            && element.FamilyTypeId != element.Id
            && elementIdOccurrenceCounts.GetValueOrDefault(element.FamilyTypeId) == 1
            && elementsById.TryGetValue(element.FamilyTypeId, out Element? type)
            && type.ValidatedIfcTypeObjectName is { } familyAndType)
            return familyAndType;
        string typeName = ResolveValidatedProductTypeName(element, ifcType, elementsById, currentProfile)
            ?? element.Name ?? $"Element {element.Id}";
        if (currentProfile && ifcType == "IFCSLAB" && element.CategoryId == -2000920) return typeName;
        string familyName = (currentProfile && ifcType == "IFCSTAIR" && element.RootClassName == "Stairs" ? element.ValidatedStairOccurrenceName : null)
            ?? ResolveSystemFamilyName(element, elementsById, elementIdOccurrenceCounts)
            ?? element.FamilyName
            ?? element.Category ?? ifcType;
        return $"{familyName}:{typeName}";
    }

    /// <summary>Null keeps the general <see cref="Element.Name"/>.</summary>
    internal static string? ResolveValidatedProductTypeName(
        Element element, string ifcType, IReadOnlyDictionary<int, Element> elementsById, bool currentProfile = false)
    {
        static string? Own(string? name, bool isExplicit, bool isBlocked) =>
            isExplicit || isBlocked || string.IsNullOrWhiteSpace(name) ? null : name;

        if ((ifcType, element.CategoryId) is ("IFCSTAIRFLIGHT", -2000919) or ("IFCSLAB", -2000920)
            && element.FamilyTypeId > 0 && element.FamilyTypeId != element.Id
            && elementsById.GetValueOrDefault(element.FamilyTypeId) is { } componentType
            && componentType.CategoryId == element.CategoryId)
            return componentType.ValidatedStairComponentTypeName;
        if (ifcType == "IFCCURTAINWALL")
            return ResolveValidatedWallTypeName(element, elementsById.GetValueOrDefault(element.FamilyTypeId));
        if (ifcType == "IFCSLAB" && element.CategoryId == -2000032)
            return Own(element.ValidatedFloorTypeReferenceName, element.ValidatedFloorTypeReferenceIsExplicit,
                element.ValidatedFloorTypeReferenceIsBlocked);
        if (ifcType == "IFCCOVERING" && element.CategoryId == -2000038)
            return Own(element.ValidatedCeilingTypeReferenceName, element.ValidatedCeilingTypeReferenceIsExplicit,
                element.ValidatedCeilingTypeReferenceIsBlocked);
        if (ifcType == "IFCWINDOW" && element.CategoryId == -2000014)
            return Own(element.ValidatedWindowTypeReferenceName, element.ValidatedWindowTypeReferenceIsExplicit,
                element.ValidatedWindowTypeReferenceIsBlocked);
        if (ifcType == "IFCBUILDINGELEMENTPROXY")
            return Own(element.ValidatedProxyTypeReferenceName, element.ValidatedProxyTypeReferenceIsExplicit,
                element.ValidatedProxyTypeReferenceIsBlocked);
        if ((ifcType == "IFCROOF" && element.CategoryId == -2000035)
            || (ifcType == "IFCRAILING" && element.CategoryId == -2000126))
            return Own(element.ValidatedRoofOrRailingTypeReferenceName, element.ValidatedRoofOrRailingTypeReferenceIsExplicit,
                element.ValidatedRoofOrRailingTypeReferenceIsBlocked);
        if (ReceivesDistributionFlowElementCommonPropertySet(ifcType, currentProfile))
            return Own(element.ValidatedDistributionTypeReferenceName, element.ValidatedDistributionTypeReferenceIsExplicit,
                element.ValidatedDistributionTypeReferenceIsBlocked);
        return null;
    }

    /// <summary>
    /// A basic or curtain wall's own type name, under the conditions of <see
    /// cref="ResolveCurtainWallReference"/> without its explicit-parameter branch.
    /// </summary>
    internal static string? ResolveValidatedWallTypeName(Element element, Element? type)
    {
        if (element.CategoryId != -2000011 || element.FamilyTypeId <= 0
            || type == null || type.Id != element.FamilyTypeId || type.CategoryId != -2000011
            || type.IsSerializedStackedWallType
            || HasIfcTypeOverride(element) || HasIfcTypeOverride(type))
            return null;
        string? ownName = type.SerializedCurtainWallFunction is >= 0 and <= 5
                && type.SerializedBasicWallTypeFunction == null
            ? type.SerializedCurtainWallTypeName
            : type.SerializedBasicWallTypeFunction is >= 0 and <= 5
                && type.SerializedCurtainWallFunction == null
                ? type.SerializedBasicWallTypeName : null;
        return string.IsNullOrWhiteSpace(ownName) ? null : ownName;
    }

    internal static string? ResolveCurtainWallReference(Element element, Element? type, string? legacyFallback)
    {
        var explicitReference = ExactIfcStringParameterResolver.ResolveReference(element, type);
        if (explicitReference.State != ExactIfcStringParameterState.Absent)
            return explicitReference.State == ExactIfcStringParameterState.Value ? explicitReference.Value : null;
        if (element.CategoryId != -2000011 || element.FamilyTypeId <= 0
            || type == null || type.Id != element.FamilyTypeId || type.CategoryId != -2000011
            || type.IsSerializedStackedWallType
            || HasIfcTypeOverride(element) || HasIfcTypeOverride(type))
            return legacyFallback;
        string? ownName = type.SerializedCurtainWallFunction is >= 0 and <= 5
                && type.SerializedBasicWallTypeFunction == null
            ? type.SerializedCurtainWallTypeName
            : type.SerializedBasicWallTypeFunction is >= 0 and <= 5
                && type.SerializedCurtainWallFunction == null
                ? type.SerializedBasicWallTypeName : null;
        return string.IsNullOrWhiteSpace(ownName) ? legacyFallback : ownName;
    }

    private static void ExportCurtainWallCommonPropertySet(
        StepWriter w, Element element, Element? type, int entityId, int ownerHistoryId,
        Dictionary<(string PropertyName, string ValueExpr), int> values)
    {
        var properties = new List<int>();
        // Never copy the legacy fallback.
        if (ResolveCurtainWallReference(element, type, null) is string reference)
            properties.Add(GetOrAddPropertySingleValue(w, values, "Reference", $"IFCIDENTIFIER({S(reference)})"));
        if (ResolveValidatedCurtainWallIsExternal(element, type) is bool isExternal)
            properties.Add(GetOrAddPropertySingleValue(w, values, "IsExternal",
                isExternal ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));
        if (properties.Count == 0) return;
        int pset = w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"curtain-wall-common-pset:{element.Id}"))},{R(ownerHistoryId)},"
            + $"{S("Pset_CurtainWallCommon")},$,{StepWriter.List(properties.Select(R))}");
        w.Add("IFCRELDEFINESBYPROPERTIES",
            $"{S(IfcGuid.FromName($"curtain-wall-common-rel:{element.Id}"))},{R(ownerHistoryId)},$,$,"
            + $"{StepWriter.List(R(entityId))},{R(pset)}");
    }

    /// <summary>Native GetStairsRuns SET order and cached GetStairsPath directions.</summary>
    internal static string ResolveNativeStairShape(Element parent, Element? type,
        IReadOnlyDictionary<int, Element> elementsById, IReadOnlyDictionary<int, int> occurrenceCounts)
    {
        const string fallback = "NOTDEFINED";
        if (parent.Id <= 0 || parent.IsBlockOnly || parent.CategoryId != -2000120
            || parent.RuleClassName != "StairsElement"
            || occurrenceCounts.GetValueOrDefault(parent.Id) != 1
            || parent.SerializedStairCore is not { Length: > 0 } core
            || HasIfcTypeOverride(parent) || type != null && HasIfcTypeOverride(type)) return fallback;
        if (core.Select(child => child.Id).Distinct().Count() != core.Length) return fallback;
        var runs = new List<Parsing.TfBlockDeserializer.StairRunInput>();
        int landings = 0;
        foreach (var child in core.OrderBy(child => child.Id))
        {
            if (child.Id <= 0 || child.Id == parent.Id || child.ClassId is not (3708 or 3686 or 3727)
                || occurrenceCounts.GetValueOrDefault(child.Id) != 1
                || !elementsById.TryGetValue(child.Id, out var element) || element.IsBlockOnly
                || element.SerializedOwnElementClassId != child.ClassId
                || element.SerializedOwningElementId != parent.Id) return fallback;
            if (child.ClassId == 3686) landings++;
            if (child.ClassId != 3708) continue;
            if (element.SerializedStairRunInput is not { } input || input.OwnerId != child.Id
                || input.StairsId != parent.Id || HasIfcTypeOverride(element)
                || element.FamilyTypeId > 0 && elementsById.TryGetValue(element.FamilyTypeId, out var runType)
                    && HasIfcTypeOverride(runType)) return fallback;
            runs.Add(input);
        }
        return StairShape.Classify(runs, landings) ?? fallback;
    }

    /// <summary>
    /// The original naming rule uses the instance's API Name, not ElementType.Name.
    /// </summary>
    internal static string? ResolveNativeStairName(Element stair,
        IReadOnlyDictionary<int, Element> elementsById, IReadOnlyDictionary<int, int> occurrenceCounts,
        bool currentProfile = false)
    {
        if (stair.Id <= 0 || stair.IsBlockOnly || stair.CategoryId != -2000120
            || stair.RuleClassName != "StairsElement" || occurrenceCounts.GetValueOrDefault(stair.Id) != 1
            || stair.SerializedStairCore is not { Length: > 0 }
            || stair.ValidatedStairOccurrenceName is not { Length: > 0 } instanceName
            || !stair.SerializedStairTypeLinkIsResolved || stair.SerializedStairTypeId is not > 0
            || !elementsById.TryGetValue(stair.SerializedStairTypeId.Value, out var type)
            || type.IsBlockOnly || type.SerializedStairsTypeClassId != 3742
            || HasIfcTypeOverride(stair) || HasIfcTypeOverride(type)
            || ResolveSystemFamilyName(stair, elementsById, occurrenceCounts) is not { Length: > 0 } family)
            return null;
        // The current profile names a stair after its type (ElementType.getTypeName), the legacy
        // profile after the instance name "Stair".
        if (currentProfile && type.Name is { Length: > 0 } typeName) instanceName = typeName;
        string original = $"{family}:{instanceName}:{stair.Id.ToString(CultureInfo.InvariantCulture)}";
        // The naming rule applies the first lookup; creating the stair applies it again
        // using that result as originalValue.
        string? ifcName = ResolveNativeStairNameOverride(stair, original);
        return ifcName == null ? null : ResolveNativeStairNameOverride(stair, ifcName);
    }

    // Both parent and native components are instances. IfcName[Type] and a type's occurrence
    // parameter cannot override them.
    internal static string? ResolveNativeStairNameOverride(Element element, string original)
    {
        if (element.SerializedStairNameParameters == null) return null;
        var own = new Element { Parameters = element.SerializedStairNameParameters };
        var value = ExactIfcStringParameterResolver.Resolve(own, "IfcName");
        if (value.State == ExactIfcStringParameterState.Blocked) return null;
        if (value.State == ExactIfcStringParameterState.Value && value.Value != original) return value.Value;
        value = ExactIfcStringParameterResolver.Resolve(own, "NameOverride");
        return value.State switch
        {
            ExactIfcStringParameterState.Absent => original,
            ExactIfcStringParameterState.Value => value.Value,
            _ => null,
        };
    }

    /// <summary>With <paramref name="unsetIntegerIsNoOverride"/> an Integer -1 in the IFC export parameter range is the
    /// default the 2022 file layout reads for a parameter nobody set (e.g. IFC_EXPORT_ELEMENT_AS,
    /// a String parameter, as Integer -1), not an override. Only the door and window opening identity uses it so far.</summary>
    private static bool HasIfcTypeOverride(Element element, bool unsetIntegerIsNoOverride = false)
    {
        foreach (string name in new[] { "IfcExportAs", "IfcExportType", "IfcType",
            "IfcExportAs[Type]", "IfcExportType[Type]", "IfcType[Type]" })
            if (ExactIfcStringParameterResolver.Resolve(element, name).State != ExactIfcStringParameterState.Absent)
                return true;
        return element.Parameters.Any(parameter => parameter.Id is >= -1019017 and <= -1019012
            && parameter.Value != null
            && !(unsetIntegerIsNoOverride && parameter.StorageType == StorageType.Integer && parameter.Value is -1)
            && (parameter.Value is not string value || value.Length != 0));
    }

    /// <summary>
    /// Builds type-held property sets through HasPropertySets, never through
    /// IfcRelDefinesByProperties.
    /// </summary>
    private static string BuildTypeHasPropertySets(
        StepWriter w, int ownerHistId, string typeClass, Element typeElem,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        IReadOnlyDictionary<int, bool?> componentTypeIsExternalValues, string typeIdentityKey)
    {
        int? commonPsetId = BuildTypeCommonPropertySet(
            w, ownerHistId, typeClass, typeElem, propertySingleValueIds,
            componentTypeIsExternalValues, typeIdentityKey);
        int? manufacturerPsetId = BuildTypeManufacturerPropertySet(
            w, ownerHistId, typeElem, typeIdentityKey);
        var psetIds = typeClass == "IFCWINDOWSTYLE"
            ? new[] { manufacturerPsetId, commonPsetId }
            : new[] { commonPsetId, manufacturerPsetId };
        var present = psetIds.Where(id => id.HasValue).Select(id => R(id!.Value)).ToList();
        return present.Count == 0 ? "$" : StepWriter.List(present);
    }

    /// <summary>
    /// Pset_ManufacturerTypeInformation.Manufacturer: the exporter maps the property to
    /// ALL_MODEL_MANUFACTURER (PropertySetDescription) and writes it when the type holds a
    /// non-empty string.
    /// </summary>
    private static int? BuildTypeManufacturerPropertySet(
        StepWriter w, int ownerHistId, Element typeElem, string typeIdentityKey)
    {
        const int allModelManufacturerParamId = -1010108;
        if (typeElem.Parameters.FirstOrDefault(parameter => parameter.Id == allModelManufacturerParamId)?.Value
            is not string { Length: > 0 } manufacturer)
            return null;
        int propertyId = w.Add("IFCPROPERTYSINGLEVALUE", $"{S("Manufacturer")},$,IFCLABEL({S(manufacturer)}),$");
        return w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"type-manufacturer-pset:{typeIdentityKey}"))},{R(ownerHistId)},"
            + $"{S("Pset_ManufacturerTypeInformation")},$,{StepWriter.List(R(propertyId))}");
    }

    private static int? BuildTypeCommonPropertySet(
        StepWriter w, int ownerHistId, string typeClass, Element typeElem,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        IReadOnlyDictionary<int, bool?> componentTypeIsExternalValues, string typeIdentityKey)
    {
        string psetName;
        string guidPrefix;
        bool? isExternal;
        double? totalThicknessMm = null;
        string psetIdentity = typeElem.Id.ToString(CultureInfo.InvariantCulture);
        if (typeClass == "IFCRAILINGTYPE")
        {
            psetName = "Pset_RailingCommon";
            guidPrefix = "type-railing-common-pset";
            isExternal = false;
        }
        else if (typeClass == "IFCWALLTYPE"
            && ResolveValidatedBasicWallIsExternal(typeElem, typeElem) is bool wallIsExternal)
        {
            psetName = "Pset_WallCommon";
            guidPrefix = "type-wall-common-pset";
            isExternal = wallIsExternal;
        }
        else if (typeClass == "IFCCURTAINWALLTYPE"
            && ResolveValidatedCurtainWallIsExternal(typeElem, typeElem) is bool curtainIsExternal)
        {
            psetName = "Pset_CurtainWallCommon";
            guidPrefix = "type-curtain-wall-common-pset";
            isExternal = curtainIsExternal;
        }
        else if (typeClass is "IFCMEMBERTYPE" or "IFCPLATETYPE" or "IFCCOLUMNTYPE" or "IFCSLABTYPE"
            or "IFCDOORSTYLE" or "IFCWINDOWSTYLE" or "IFCBEAMTYPE"
            && (typeClass switch
            {
                "IFCDOORSTYLE" => typeElem.CategoryId == -2000023,
                "IFCWINDOWSTYLE" => typeElem.CategoryId == -2000014,
                "IFCBEAMTYPE" => typeElem.CategoryId == StructuralFramingCategoryId,
                _ => true,
            })
            // A STRINGER placeholder is created without type-property registration.
            && (typeClass != "IFCMEMBERTYPE" || typeElem.CategoryId == CurtainWallMullionCategoryId)
            && componentTypeIsExternalValues.TryGetValue(typeElem.Id, out bool? componentIsExternal))
        {
            (psetName, guidPrefix) = typeClass switch
            {
                "IFCMEMBERTYPE" => ("Pset_MemberCommon", "type-member-common-pset"),
                "IFCPLATETYPE" => ("Pset_PlateCommon", "type-plate-common-pset"),
                "IFCCOLUMNTYPE" => ("Pset_ColumnCommon", "type-column-common-pset"),
                "IFCDOORSTYLE" => ("Pset_DoorCommon", "type-door-common-pset"),
                "IFCWINDOWSTYLE" => ("Pset_WindowCommon", "type-window-common-pset"),
                "IFCBEAMTYPE" => ("Pset_BeamCommon", "type-beam-common-pset"),
                _ => ("Pset_SlabCommon", "type-slab-common-pset"),
            };
            isExternal = componentIsExternal;
            // One canonical symbol can produce multiple geometry-qualified IFC types.
            psetIdentity = typeIdentityKey;
        }
        else if (typeClass == "IFCCOVERINGTYPE" && typeElem.CategoryId == -2000038
            && typeElem.ValidatedCeilingTypeThicknessFeet is double ceilingThicknessFeet
            && ceilingThicknessFeet > 0)
        {
            // PropertySetDescription maps Pset_CoveringCommon.TotalThickness to CEILING_THICKNESS,
            // which a compound ceiling type computes from its layers.
            psetName = "Pset_CoveringCommon";
            guidPrefix = "type-covering-common-pset";
            isExternal = null;
            totalThicknessMm = ceilingThicknessFeet * 304.8;
        }
        else return null;

        var propertyIds = new List<int>();
        if (isExternal is bool external)
            propertyIds.Add(GetOrAddPropertySingleValue(
                w, propertySingleValueIds, "IsExternal", external ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));
        if (typeClass == "IFCWINDOWSTYLE" && typeElem.CategoryId == -2000014)
        {
            // PropertySetDescription maps ThermalTransmittance to
            // ANALYTICAL_HEAT_TRANSFER_COEFFICIENT; the stored value is written unchanged.
            const int heatTransferCoefficientParamId = -1005430;
            if (typeElem.Parameters.FirstOrDefault(parameter => parameter.Id == heatTransferCoefficientParamId)?.Value
                    is double thermalTransmittance
                && double.IsFinite(thermalTransmittance) && thermalTransmittance > 0)
                propertyIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                    $"{S("ThermalTransmittance")},$,IFCTHERMALTRANSMITTANCEMEASURE({D17(thermalTransmittance)}),$"));
        }
        if (totalThicknessMm is double thicknessMm)
            propertyIds.Add(w.Add("IFCPROPERTYSINGLEVALUE",
                $"{S("TotalThickness")},$,IFCPOSITIVELENGTHMEASURE({D17(thicknessMm)}),$"));
        if (typeClass is "IFCCOLUMNTYPE" or "IFCBEAMTYPE")
        {
            // IFC2X3 ColumnCommon/BeamCommon have no localized-name map.
            var loadBearing = ResolveExactNamedIntParameter(typeElem, "LoadBearing");
            if (loadBearing.State == ExactIsExternalParameterState.Absent)
                loadBearing = ResolveExactNamedIntParameter(typeElem, "LoadBearing[Type]");
            bool structuralCategory = typeElem.CategoryId is StructuralColumnCategoryId or StructuralFramingCategoryId
                or (int)BuiltIns.BuiltInCategory.OST_StructuralFramingSystem
                or (int)BuiltIns.BuiltInCategory.OST_StructuralTruss;
            if (loadBearing.State == ExactIsExternalParameterState.Value
                || loadBearing.State == ExactIsExternalParameterState.Absent && structuralCategory)
            {
                bool bearing = loadBearing.State == ExactIsExternalParameterState.Absent || loadBearing.Value != 0;
                propertyIds.Add(GetOrAddPropertySingleValue(
                    w, propertySingleValueIds, "LoadBearing", bearing ? "IFCBOOLEAN(.T.)" : "IFCBOOLEAN(.F.)"));
            }
        }
        if (propertyIds.Count == 0) return null;
        return w.Add("IFCPROPERTYSET",
            $"{S(IfcGuid.FromName($"{guidPrefix}:{psetIdentity}"))},{R(ownerHistId)},"
            + $"{S(psetName)},$,{StepWriter.List(propertyIds.Select(R))}");
    }

    /// <summary>
    /// The family-instance export registers the canonical display FamilySymbol for Door/Window/Beam
    /// type properties, independently of the geometry symbol.
    /// </summary>
    private static IReadOnlyDictionary<int, bool?> ResolveRegisteredFamilyTypeCommonValues(
        IReadOnlyDictionary<int, Element> elements,
        IReadOnlyDictionary<int, int> elementCounts,
        IReadOnlyDictionary<int, (int entityId, int placementId, string ifcType)> products)
    {
        var result = new Dictionary<int, bool?>();
        foreach (var (id, product) in products)
        {
            int category = product.ifcType switch
            {
                "IFCDOOR" => -2000023,
                "IFCWINDOW" => -2000014,
                "IFCBEAM" => StructuralFramingCategoryId,
                _ => 0,
            };
            if (category == 0 || elementCounts.GetValueOrDefault(id) != 1
                || !elements.TryGetValue(id, out var occurrence)
                || occurrence.CategoryId != category || occurrence.IsBlockOnly
                || occurrence.FamilyTypeId <= 0 || occurrence.FamilyTypeId == id
                || elementCounts.GetValueOrDefault(occurrence.FamilyTypeId) != 1
                || !elements.TryGetValue(occurrence.FamilyTypeId, out var type)
                || type.CategoryId != category || type.IsBlockOnly
                || type.SerializedHostId != null || products.ContainsKey(type.Id))
                continue;

            var named = ResolveExactIsExternalParameter(type, type);
            bool? value = null;
            if (named.State == ExactIsExternalParameterState.Value)
                value = named.Value != 0;
            else if (named.State == ExactIsExternalParameterState.Absent)
            {
                var function = ResolveExactFunctionParameter(type);
                if (function.State == ExactIsExternalParameterState.Value)
                    value = function.Value != 0;
            }
            result[type.Id] = value;
        }
        return result;
    }

    private static bool? ResolveValidatedCurtainWallIsExternal(Element element, Element? elementType)
    {
        if (elementType?.SerializedCurtainWallFunction == null)
            return ResolveValidatedBasicWallIsExternal(element, elementType);
        if (element.CategoryId != -2000011 || elementType?.CategoryId != -2000011
            || elementType.SerializedBasicWallTypeFunction != null
            || elementType.SerializedCurtainWallFunction is not (>= 0 and <= 5)
            || ResolveExactIsExternalParameter(element, elementType).State != ExactIsExternalParameterState.Absent)
            return null;
        var function = ResolveExactFunctionParameter(elementType);
        return function.State == ExactIsExternalParameterState.Value
            && function.Value == elementType.SerializedCurtainWallFunction
                ? function.Value != 0 : null;
    }

    /// <summary>
    /// The native BasicWallType function is authoritative only with absent named overrides and no
    /// conflicting FUNCTION_PARAM.
    /// </summary>
    private static bool? ResolveValidatedBasicWallIsExternal(Element element, Element? elementType)
    {
        if (element.CategoryId != -2000011 || elementType?.CategoryId != -2000011
            || elementType.SerializedBasicWallTypeFunction is not (>= 0 and <= 5)
            || ResolveExactIsExternalParameter(element, elementType).State != ExactIsExternalParameterState.Absent)
            return null;
        var parameter = ResolveExactFunctionParameter(elementType, includeSerializedCurtainWallFunction: false);
        if (parameter.State == ExactIsExternalParameterState.Blocked
            || parameter.State == ExactIsExternalParameterState.Value
                && parameter.Value != elementType.SerializedBasicWallTypeFunction)
            return null;
        return elementType.SerializedBasicWallTypeFunction != 0;
    }

    private const int RoomCategoryId = -2000160;
    private const int AreaCategoryId = -2003200;      // OST_Areas also exports as IfcSpace
    private const int MepSpaceCategoryId = -2003600;  // OST_MEPSpaces
    private const int RoomLevelIdParam = -1006916;   // BuiltInParameter.ROOM_LEVEL_ID
    private const int LevelParamId = -1001952;        // BuiltInParameter.LEVEL_PARAM
    private const int RoomNumberParam = -1006901;     // BuiltInParameter.ROOM_NUMBER
    private const int RoomNameParam = -1006900;       // BuiltInParameter.ROOM_NAME

    /// <summary>
    /// Spaces subsystem: <c>IfcSpace</c> + <c>IfcRelAggregates</c> (storey decomposition, NOT
    /// <c>IfcRelContainedInSpatialStructure</c>) + a private, non-shared <c>IfcSpaceType</c> +
    /// <c>IfcRelDefinesByType</c> + the one-property <c>Pset_SpaceCommon</c> (<c>Reference</c>
    /// only).
    /// </summary>
    private Dictionary<int, string> WriteSpaces(
        StepWriter w, int ownerHistId, List<Element> allElements,
        Dictionary<int, int> storeyIds, Dictionary<int, int> storeyPlacements,
        Dictionary<int, double> storeyElevationsMetres, int bodySubCtxId,
        Dictionary<(string PropertyName, string ValueExpr), int> propertySingleValueIds,
        int? exportPhaseId, Dictionary<int, int> spaceEntityIdByRoomId, Dictionary<int, List<int>> storeySpaceEntityIds)
    {
        var exactTypeGuids = new Dictionary<int, string>();
        var storeySpaces = new Dictionary<int, List<int>>(); // storey entity id -> space entity ids
        var areaSchemeSpaces = new SortedDictionary<int, List<int>>(); // area scheme element id -> area space entity ids
        Dictionary<int, double>? storeyHeightsCurrent = null;
        var roomsByPhase = new SortedDictionary<int, int>();
        int roomsOutOfPhase = 0, roomsLocationless = 0;
        int? buildingContainerId = CurrentProfile && storeyIds.Count == 0 && storeyPlacements.Count == 1 ? storeyPlacements.Keys.Single() : null;

        foreach (var elem in allElements.Where(e => e.CategoryId is RoomCategoryId or AreaCategoryId
            || (_geometryUndecoded || CurrentProfile) && e.CategoryId == MepSpaceCategoryId).OrderBy(e => e.Id))
        {
            // Apply only an explicitly selected phase.
            bool phased = elem.CategoryId == RoomCategoryId || (_geometryUndecoded || CurrentProfile) && elem.CategoryId == MepSpaceCategoryId;
            if (phased && elem.SerializedRoomPhaseId is > 0)
                roomsByPhase[elem.SerializedRoomPhaseId.Value] = roomsByPhase.GetValueOrDefault(elem.SerializedRoomPhaseId.Value) + 1;
            if (phased && exportPhaseId is > 0
                && elem.SerializedRoomPhaseId is > 0
                && elem.SerializedRoomPhaseId != exportPhaseId)
            {
                roomsOutOfPhase++;
                continue;
            }
            // The space export returns for a locationless (unplaced) room.
            if (CurrentProfile && elem.CategoryId is RoomCategoryId or MepSpaceCategoryId && elem.SerializedRoomIsLocationless == true)
            {
                roomsLocationless++;
                continue;
            }
            int? levelParamId = RoomIntParam(elem, LevelParamId);
            int? roomLevelId = RoomIntParam(elem, RoomLevelIdParam);
            int? levelElemId = levelParamId ?? roomLevelId;
            int storeyId;
            if (levelElemId is int lvl && storeyIds.TryGetValue(lvl, out int levelStoreyId)) storeyId = levelStoreyId;
            else if (buildingContainerId is int container) storeyId = container;
            else continue;

            string? number = RoomStringParam(elem, RoomNumberParam);
            // A 64-bit-id file keeps the name of a room only as its ROOM_NAME parameter (no scanned
            // fallback name).
            string? longName = elem.Name ?? (_geometryUndecoded ? RoomStringParam(elem, RoomNameParam) : null);
            if (string.IsNullOrEmpty(number) || string.IsNullOrEmpty(longName))
                continue;

            int storeyPlacementId = storeyPlacements[storeyId];
            int originPointId = w.Add("IFCCARTESIANPOINT", StepWriter.List(D(0), D(0), D(0)));
            int axisId = w.Add("IFCAXIS2PLACEMENT3D", $"{R(originPointId)},$,$");
            int placementId = w.Add("IFCLOCALPLACEMENT", $"{R(storeyPlacementId)},{R(axisId)}");

            int shapeId = 0;
            GeometryData? writtenBoundary = null;
            if (CurrentProfile && elem.CategoryId is RoomCategoryId or MepSpaceCategoryId
                && elem.SerializedCurvedSpaceBoundary is { MeshNodes: { Count: > 0 } } meshedBoundary
                && storeyElevationsMetres.TryGetValue(storeyId, out double meshedElevationMetres)
                && meshedBoundary.BrepSolids is { Count: 1 }
                && meshedBoundary.BrepSolids[0].IsClosed
                && meshedBoundary.BrepSolids[0].FaceIndices.Order().SequenceEqual(Enumerable.Range(0, meshedBoundary.Faces.Count))
                && (TryCreateOthersCurrentSweptSolid(w, meshedBoundary, bodySubCtxId, OthersCurrentAxesZ, string.Empty, out var meshedBody,
                        offZ: -meshedElevationMetres / FeetToMetres, allowCoaxialCurvedFaces: true)
                    || TryWriteMeshedSpaceBodyCurrent(w, meshedBoundary, bodySubCtxId, -meshedElevationMetres / FeetToMetres, out meshedBody)))
            {
                shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE", $"$,$,{StepWriter.List(meshedBody.RepresentationIds.Select(R))}");
                writtenBoundary = meshedBoundary;
            }
            else if (elem.CategoryId is RoomCategoryId or MepSpaceCategoryId
                && elem.SerializedSpaceBoundary is { } boundary
                && storeyElevationsMetres.TryGetValue(storeyId, out double elevationMetres)
                && boundary.BrepSolids is { Count: 1 }
                && boundary.BrepSolids[0].IsClosed
                && boundary.BrepSolids[0].FaceIndices.Order()
                    .SequenceEqual(Enumerable.Range(0, boundary.Faces.Count))
                && TryOrientExactFacetedShell(boundary.Faces,
                    boundary.BrepSolids[0].FaceIndices, out _, triangulateNonPlanarFaces: false)
                // A disconnected closed component may be a cavity, not another filled solid.
                && GetExactFaceComponents(boundary.Faces,
                    boundary.BrepSolids[0].FaceIndices).Count == 1)
            {
                // Cached vertices are already in project coordinates.
                var written = CurrentProfile && TryCreateOthersCurrentSweptSolid(
                        w, boundary, bodySubCtxId, OthersCurrentAxesZ, string.Empty, out var sweptRoom,
                        offZ: -elevationMetres / FeetToMetres)
                    ? sweptRoom
                    : CreateFacetedShapeRepresentations(w, boundary, bodySubCtxId,
                        offZ: -elevationMetres / FeetToMetres,
                        preserveValidatedPlanarFaces: true, preserveValidatedCoordinates: true);
                if (written.RepresentationIds.Count == 1
                    && written.Outcome.HasClosedBrepOrSweptSolidBody
                    && !written.Outcome.HasSurfaceModel)
                {
                    shapeId = w.Add("IFCPRODUCTDEFINITIONSHAPE",
                        $"$,$,{StepWriter.List(written.RepresentationIds.Select(R))}");
                    writtenBoundary = boundary;
                }
            }
            // A room whose welded cache is refused or is no manifold shell: the cache as the
            // coedges give it (a sliver face, a gap between two Edges, an Edge shared by four
            // Faces).
            if (shapeId == 0 && CurrentProfile && elem.CategoryId is RoomCategoryId or MepSpaceCategoryId && elem.SerializedLiteralSpaceBoundary is { } literalBoundary
                && storeyElevationsMetres.TryGetValue(storeyId, out double literalElevationMetres)
                && TryWriteLiteralSpaceBodyCurrent(w, literalBoundary, bodySubCtxId, -literalElevationMetres / FeetToMetres, out int literalShapeId))
            {
                shapeId = literalShapeId;
                writtenBoundary = literalBoundary;
            }
            // An element without geometry of its own is extruded from the outline of its circuit in
            // the level room plan.
            if (shapeId == 0 && CurrentProfile && elem.SerializedPlanBoundary != null
                && (storeyHeightsCurrent ??= StoreyHeightsCurrent()).TryGetValue(storeyId, out double planStoreyHeightMetres)
                && TryWritePlanSpaceBodyCurrent(w, elem, bodySubCtxId, planStoreyHeightMetres, out int planShapeId))
                shapeId = planShapeId;

            string spaceGuid = ResolveExactElementGlobalId(elem, _usedExportIds, handleBased: CurrentProfile)
                ?? IfcGuid.FromName($"space:{elem.Id}");
            // The current profile: Description is the Comments
            // parameter, ObjectType the empty string and ElevationWithFlooring 0 (the Revit
            // exporter's IfcElevationWithFlooring is not read).
            string description = CurrentProfile && RoomStringParam(elem, SpaceCommentsParamId) is { } comments ? S(comments) : "$";
            int spaceEntityId = w.Add("IFCSPACE",
                $"{S(spaceGuid)},{R(ownerHistId)},{S(number)},{description},{(CurrentProfile ? "''" : "$")},{R(placementId)},"
                + $"{(shapeId > 0 ? R(shapeId) : "$")},{S(longName)},.ELEMENT.,.INTERNAL.,{(CurrentProfile ? "0." : "$")}");
            spaceEntityIdByRoomId[elem.Id] = spaceEntityId;
            if (writtenBoundary != null) _spaceBodyGeometry[spaceEntityId] = writtenBoundary;
            if (CurrentProfile && elem.CategoryId == AreaCategoryId && RoomIntParam(elem, AreaSchemeIdParam) is > 0 and int schemeId)
            {
                if (!areaSchemeSpaces.TryGetValue(schemeId, out var schemeSpaces))
                    areaSchemeSpaces[schemeId] = schemeSpaces = new List<int>();
                schemeSpaces.Add(spaceEntityId);
            }

            string referenceText = $"{longName} {number}";
            int referenceValueId = GetOrAddPropertySingleValue(
                w, propertySingleValueIds, "Reference", $"IFCIDENTIFIER({S(referenceText)})");
            int psetId = w.Add("IFCPROPERTYSET",
                $"{S(IfcGuid.FromName($"space-common-pset:{elem.Id}"))},{R(ownerHistId)},"
                + $"{S("Pset_SpaceCommon")},$,{StepWriter.List(R(referenceValueId))}");
            w.Add("IFCRELDEFINESBYPROPERTIES",
                $"{S(IfcGuid.FromName($"space-common-rel:{elem.Id}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(R(spaceEntityId))},{R(psetId)}");

            string typeName = $"{longName} {number}:{elem.Id}";
            string? exactSpaceTypeGuid = ResolveExactElementGlobalId(
                elem, _usedExportIds, InstanceAsTypeSubElementIndex, CurrentProfile);
            string spaceTypeGuid = exactSpaceTypeGuid ?? IfcGuid.FromName($"space-type:{elem.Id}");
            int typeEntityId = w.Add("IFCSPACETYPE",
                $"{S(spaceTypeGuid)},{R(ownerHistId)},{S(typeName)},$,$,$,$,"
                + $"{S(elem.Id.ToString(CultureInfo.InvariantCulture))},$,.NOTDEFINED.");
            if (exactSpaceTypeGuid != null) exactTypeGuids[typeEntityId] = exactSpaceTypeGuid;
            w.Add("IFCRELDEFINESBYTYPE",
                $"{S(IfcGuid.FromName($"space-rel-defines-by-type:{elem.Id}"))},{R(ownerHistId)},$,$,"
                + $"{StepWriter.List(R(spaceEntityId))},{R(typeEntityId)}");

            if (!storeySpaces.TryGetValue(storeyId, out var spaceList))
                storeySpaces[storeyId] = spaceList = new List<int>();
            spaceList.Add(spaceEntityId);
        }

        _diag?.WriteLine(
            $"IFC rooms: {spaceEntityIdByRoomId.Count} spaces written, active room phase {(exportPhaseId is > 0 ? exportPhaseId.ToString() : "none")}, "
            + $"{roomsOutOfPhase} rooms of another phase and {roomsLocationless} locationless rooms skipped; room phases: "
            + string.Join(", ", roomsByPhase.Select(entry => $"{entry.Key}={entry.Value}")));
        if (CurrentProfile)
        {
            foreach (var (storeyId, spaceEntityIds) in storeySpaces)
                if (storeyId == buildingContainerId)
                    w.Add("IFCRELAGGREGATES",
                        $"{S(IfcGuid.FromName($"space-agg:{storeyId}"))},{R(ownerHistId)},$,$,{R(storeyId)},{StepWriter.List(spaceEntityIds.Select(R))}");
                else storeySpaceEntityIds[storeyId] = spaceEntityIds;
            WriteAreaSchemeGroups(w, ownerHistId, allElements, areaSchemeSpaces);
            return exactTypeGuids;
        }
        foreach (var (storeyId, spaceEntityIds) in storeySpaces.OrderBy(kv => kv.Key))
        {
            string? spaceAggregateGlobalId = _storeyLevels.TryGetValue(storeyId, out var spaceLevel)
                ? ResolveExactElementGlobalId(spaceLevel, _usedExportIds, StoreyRelAggregates)
                : null;
            w.Add("IFCRELAGGREGATES",
                $"{S(spaceAggregateGlobalId ?? IfcGuid.FromName($"space-agg:{storeyId}"))},{R(ownerHistId)},$,$,"
                + $"{R(storeyId)},{StepWriter.List(spaceEntityIds.Select(R))}");
        }
        return exactTypeGuids;
    }

    private const int SpaceCommentsParamId = -1010106;   // BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS
    private const int AreaSchemeIdParam = -1012704;      // RoomElem.m_areaSchemeId
    private const int PhaseCategoryId = -2000112;        // OST_Phases

    /// <summary>The phase whose rooms the current profile exports.</summary>
    private int? ResolveActiveRoomPhase(RevitFileInfo info)
    {
        if (RoomExportPhaseId != null) return RoomExportPhaseId;
        if (!CurrentProfile || ExportRoomsOfAllPhases || info.SerializedProjectPhaseIds is not { Length: > 0 } order) return null;
        var phases = info.Elements.Where(element => element.CategoryId == PhaseCategoryId
                && !(info.ElemTableIsExact && element.IsDiscovered))
            .Select(element => element.Id).ToHashSet();
        for (int index = order.Length - 1; index >= 0; index--)
            if (phases.Contains(order[index])) return order[index];
        return null;
    }

    private void WriteAreaSchemeGroups(
        StepWriter w, int ownerHistId, List<Element> allElements, SortedDictionary<int, List<int>> areaSchemeSpaces)
    {
        if (areaSchemeSpaces.Count == 0) return;
        var schemes = allElements.Where(element => areaSchemeSpaces.ContainsKey(element.Id)
            && element.SerializedAreaScheme != null).GroupBy(element => element.Id).ToDictionary(g => g.Key, g => g.First());
        foreach (var (schemeId, spaces) in areaSchemeSpaces)
        {
            if (!schemes.TryGetValue(schemeId, out var scheme) || scheme.SerializedAreaScheme is not { } text) continue;
            string globalId = ResolveExactElementGlobalId(scheme, _usedExportIds, handleBased: CurrentProfile) ?? IfcGuid.FromName($"area-scheme:{schemeId}");
            int group = w.Add("IFCGROUP", $"{S(globalId)},{R(ownerHistId)},{S(text.Name)},{S(text.Description)},''");
            w.Add("IFCRELASSIGNSTOGROUP",
                $"{S(IfcGuid.FromMd5($"IfcRelAssignsToGroup:{globalId}"))},{R(ownerHistId)},'','',"
                + $"{StepWriter.List(spaces.Select(R))},$,{R(group)}");
        }
    }

    private static List<(double Z, List<(double X, double Y)> Ring)> HorizontalFaces(GeometryData geometry)
    {
        var faces = new List<(double Z, List<(double X, double Y)> Ring)>();
        foreach (var face in geometry.Faces)
        {
            if (face.OuterVertices is not { Count: >= 3 } outer) continue;
            double z = outer[0][2];
            if (outer.Any(vertex => Math.Abs(vertex[2] - z) > 0.001)) continue;
            faces.Add((z, outer.Select(vertex => (vertex[0], vertex[1])).ToList()));
        }
        return faces;
    }

    /// <summary>The horizontal faces of a room's boundary solid above its middle elevation.</summary>
    private static List<(double Z, List<(double X, double Y)> Ring)> RoomUpperHorizontalFaces(GeometryData boundary)
    {
        var heights = boundary.Faces.Where(face => face.OuterVertices != null)
            .SelectMany(face => face.OuterVertices!).Select(vertex => vertex[2]).ToList();
        if (heights.Count == 0) return [];
        double middle = (heights.Min() + heights.Max()) / 2;
        return HorizontalFaces(boundary).Where(face => face.Z > middle).ToList();
    }

    private static List<(double Z, List<(double X, double Y)> Ring)> CeilingLowestHorizontalFaces(GeometryData geometry)
    {
        var faces = HorizontalFaces(geometry);
        if (faces.Count == 0) return faces;
        double lowest = faces.Min(face => face.Z);
        return faces.Where(face => face.Z - lowest <= 0.001).ToList();
    }

    /// <summary>
    /// Whether two simple polygons overlap over more than <paramref name="minimumArea"/>: the sum
    /// of the areas of the intersections of their ear-clipped triangles.
    /// </summary>
    internal static bool HorizontalPolygonsOverlap(
        IReadOnlyList<(double X, double Y)> first, IReadOnlyList<(double X, double Y)> second, double minimumArea)
    {
        if (first.Max(point => point.X) < second.Min(point => point.X) || second.Max(point => point.X) < first.Min(point => point.X)
            || first.Max(point => point.Y) < second.Min(point => point.Y) || second.Max(point => point.Y) < first.Min(point => point.Y))
            return false;
        double total = 0;
        foreach (var triangle in TriangulatePolygon(first))
            foreach (var other in TriangulatePolygon(second))
            {
                total += ConvexIntersectionAreaOf(triangle, other);
                if (total > minimumArea) return true;
            }
        return false;
    }

    private static double SignedPolygonArea(IReadOnlyList<(double X, double Y)> ring)
    {
        double area = 0;
        for (int index = 0; index < ring.Count; index++)
        {
            var a = ring[index]; var b = ring[(index + 1) % ring.Count];
            area += a.X * b.Y - b.X * a.Y;
        }
        return area / 2;
    }

    private static List<(double X, double Y)[]> TriangulatePolygon(IReadOnlyList<(double X, double Y)> ring)
    {
        var points = ring.ToList();
        if (SignedPolygonArea(points) < 0) points.Reverse();
        var triangles = new List<(double X, double Y)[]>();
        int guard = points.Count * points.Count + 8;
        while (points.Count > 3 && guard-- > 0)
        {
            bool clipped = false;
            for (int index = 0; index < points.Count; index++)
            {
                var previous = points[(index + points.Count - 1) % points.Count];
                var current = points[index];
                var next = points[(index + 1) % points.Count];
                double cross = (current.X - previous.X) * (next.Y - previous.Y) - (current.Y - previous.Y) * (next.X - previous.X);
                if (cross <= 1e-12) continue;
                bool containsPoint = points.Any(point => !point.Equals(previous) && !point.Equals(current) && !point.Equals(next)
                    && PointInTriangle(point, previous, current, next));
                if (containsPoint) continue;
                triangles.Add([previous, current, next]);
                points.RemoveAt(index);
                clipped = true;
                break;
            }
            if (!clipped) break;
        }
        if (points.Count == 3) triangles.Add([points[0], points[1], points[2]]);
        return triangles;
    }

    private static bool PointInTriangle((double X, double Y) p, (double X, double Y) a, (double X, double Y) b, (double X, double Y) c)
    {
        double d1 = (p.X - b.X) * (a.Y - b.Y) - (a.X - b.X) * (p.Y - b.Y);
        double d2 = (p.X - c.X) * (b.Y - c.Y) - (b.X - c.X) * (p.Y - c.Y);
        double d3 = (p.X - a.X) * (c.Y - a.Y) - (c.X - a.X) * (p.Y - a.Y);
        bool negative = d1 < 0 || d2 < 0 || d3 < 0, positive = d1 > 0 || d2 > 0 || d3 > 0;
        return !(negative && positive);
    }

    private static double ConvexIntersectionAreaOf((double X, double Y)[] subject, (double X, double Y)[] clip)
    {
        var output = subject.ToList();
        if (SignedPolygonArea(clip) < 0) clip = Enumerable.Reverse(clip).ToArray();
        for (int edge = 0; edge < clip.Length && output.Count > 0; edge++)
        {
            var a = clip[edge]; var b = clip[(edge + 1) % clip.Length];
            var input = output; output = new List<(double X, double Y)>();
            for (int index = 0; index < input.Count; index++)
            {
                var current = input[index]; var previous = input[(index + input.Count - 1) % input.Count];
                double currentSide = (b.X - a.X) * (current.Y - a.Y) - (b.Y - a.Y) * (current.X - a.X);
                double previousSide = (b.X - a.X) * (previous.Y - a.Y) - (b.Y - a.Y) * (previous.X - a.X);
                if (currentSide >= 0)
                {
                    if (previousSide < 0) output.Add(Cross(previous, current, previousSide, currentSide));
                    output.Add(current);
                }
                else if (previousSide >= 0) output.Add(Cross(previous, current, previousSide, currentSide));
            }
        }
        return output.Count < 3 ? 0 : Math.Abs(SignedPolygonArea(output));

        static (double X, double Y) Cross((double X, double Y) from, (double X, double Y) to, double fromSide, double toSide)
        {
            double t = fromSide / (fromSide - toSide);
            return (from.X + t * (to.X - from.X), from.Y + t * (to.Y - from.Y));
        }
    }

    private static int? RoomIntParam(Element e, int paramId)
    {
        object? value = e.Parameters.FirstOrDefault(p => p.Id == paramId)?.Value;
        return value is int n ? n : null;
    }

    private static string? RoomStringParam(Element e, int paramId)
    {
        object? value = e.Parameters.FirstOrDefault(p => p.Id == paramId)?.Value;
        return value is string s && !string.IsNullOrEmpty(s) ? s : null;
    }

