    /// <summary>IfcWallStandardCase requires a clean, constant rectangular extrusion.</summary>
    private static bool ShouldExportAsIfcWall(Element elem, bool currentProfile = false)
    {
        if (Environment.GetEnvironmentVariable("RVTIO_WALL_DIAG") is { Length: > 0 } diagPath) AppendWallDiag(diagPath, elem);
        if (elem.Location is not { CurveType: "Line" or "Arc" }) return true;
        // The current profile writes IfcWallStandardCase only for a body it can reproduce as a
        // vertical extrusion; a body it cannot judge (no decoded BRep) keeps the earlier rule
        // below.
        if (currentProfile && WallExtrusion.IsStandardCaseBody(elem.Geometry, elem.OwnWallHelper, elem.OwnWallTrimmedAxis is { Length: 2 } trimmed
                ? Math.Sqrt(Enumerable.Range(0, 3).Sum(axis => Math.Pow(trimmed[1][axis] - trimmed[0][axis], 2))) : null) is { } standardCase) return !standardCase;
        // An explicitly serialized wall sketch is an edited profile.
        return elem.SketchLoops is { Count: > 0 }
            || elem.CuttingElementIds is { Count: 1 } cutters
                && HasExactEmbeddedSingleFamilyCutBrepAuthority(
                    elem, cutters[0]);
    }

    private static void AppendWallDiag(string path, Element wall)
    {
        var faces = wall.Geometry?.Faces ?? new List<GeoFace>();
        var solids = wall.Geometry?.BrepSolids;
        IEnumerable<int> firstSolid = solids is { Count: > 0 } ? solids[0].FaceIndices : Enumerable.Range(0, faces.Count);
        var unpaired = new List<double>();
        int tilted = 0, vertical = 0, horizontal = 0;
        foreach (int index in firstSolid)
        {
            if (index < 0 || index >= faces.Count) continue;
            var face = faces[index];
            double[] n = face.Normal;
            double length = Math.Sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);
            if (length == 0) continue;
            double z = Math.Abs(n[2] / length);
            if (z > 1 - 1e-9) { horizontal++; continue; }
            if (z > 1e-9) { tilted++; continue; }
            vertical++;
            double area = WallExtrusion.FaceArea(face);
            int match = unpaired.FindIndex(other => Math.Abs(other - area) <= 1e-5);
            if (match >= 0) unpaired.RemoveAt(match); else unpaired.Add(area);
        }
        // The wall export route 2: the body exporter finds a vertical extrusion
        // (IFCExtrusionCalculatorUtils:: CalculateExtrusionData, axis Z) when two parallel faces of
        // equal area are the only horizontal ones and no face is tilted or a vertical face carries
        var planar = firstSolid.Where(index => index >= 0 && index < faces.Count).Select(index => faces[index]).ToList();
        string extrusion = "n/a";
        if (solids is { Count: 1 }) extrusion = WallExtrusion.TryFindVerticalExtrusion(planar, out string reason) ? "ok" : reason;
        bool simple = WallExtrusion.IsSimpleRectangularWall(planar, wall.OwnWallHelper, wall.Geometry?.InactiveFaces);
        string bottoms = string.Join('+', planar.Where(f => f.Normal[2] < -0.999999999).Select(f => f.OuterVertices?.Count ?? 0));
        string tops = string.Join('+', planar.Where(f => f.Normal[2] > 0.999999999).Select(f => f.OuterVertices?.Count ?? 0));
        string line = string.Join(',', wall.Id, wall.Location?.CurveType ?? "-", faces.Count, solids?.Count ?? -1,
            solids is { Count: > 0 } ? solids[0].IsClosed : false, horizontal, vertical, tilted, unpaired.Count,
            wall.SketchLoops?.Count ?? 0, wall.CuttingElementIds?.Count ?? 0, wall.Layers?.Count ?? 0, extrusion, bottoms, tops, DiagAxisAngle(wall), simple ? 1 : 0,
            // The profile helper cell (root class / none or C|I and the curve count of each loop)
            // and, per solid, the face test of the first-solid rule.
            wall.OwnWallHelper is { } helper ? helper.RootClassId + "/" + (helper.Present ? (helper.Complete ? "C" : "I") + string.Join('+', helper.LoopCurveCounts) : "-") : "?",
            string.Join('+', (solids ?? []).Select(s => WallExtrusion.IsSimpleRectangularWall(
                s.FaceIndices.Where(i => (uint)i < (uint)faces.Count).Select(i => faces[i]).ToList(),
                wall.OwnWallHelper, wall.Geometry?.InactiveFaces) ? 1 : 0)));
        lock (WallDiagLock) File.AppendAllText(path, line + "\n");
        if (Environment.GetEnvironmentVariable("RVTIO_WALL_DIAG_IDS") is { Length: > 0 } ids
            && ids.Split(',').Contains(wall.Id.ToString()))
        {
            var detail = new System.Text.StringBuilder().Append("# wall ").Append(wall.Id).Append(" name=").Append(wall.Name).Append(" cat=").Append(wall.CategoryId).Append('\n');
            foreach (var p in wall.Parameters) detail.Append("  p ").Append(p.Id).Append(' ').Append(p.Definition?.Name).Append(" = ").Append(p.Value).Append('\n');
            for (int fi = 0; fi < faces.Count; fi++)
            {
                var f = faces[fi];
                detail.Append("  f ").Append(fi).Append(" n=").Append(string.Join(' ', f.Normal.Select(v => v.ToString("0.####")))).Append(" area=").Append(WallExtrusion.FaceArea(f).ToString("0.####")).Append(" src=").Append(f.SourceFace).Append(" curved=").Append(f.CurvedSurface).Append(" ov=").Append(f.OuterVertices?.Count).Append(" iv=").Append(f.InnerVertices?.Count ?? 0).Append(" v=").Append(string.Join(';', (f.OuterVertices ?? []).Select(v => string.Join(',', v.Select(c => c.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture)))))).Append('\n');
            }
            foreach (var face in wall.Geometry?.InactiveFaces ?? [])
                detail.Append("  inactive src=").Append(face.SourceFace).Append(" node=").Append(face.GeometryNode)
                    .Append(" curved=").Append(face.CurvedSurface).Append(" n=")
                    .Append(string.Join(' ', face.Normal.Select(value => value.ToString("G17", System.Globalization.CultureInfo.InvariantCulture)))).Append('\n');
            lock (WallDiagLock) File.AppendAllText(path + ".detail", detail.ToString());
        }
    }

    private static readonly object WallDiagLock = new();

    private static string DiagAxisAngle(Element wall)
    {
        if (wall.Location is not { } loc) return "-";
        double angle = Math.Atan2(loc.EndPoint[1] - loc.StartPoint[1], loc.EndPoint[0] - loc.StartPoint[0]) * 180 / Math.PI;
        return angle.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture);
    }

    /// <summary>
    /// Identifies the exact incomplete source BRep contract in which the one decoded family cut is
    /// already embedded in the wall body.
    /// </summary>
    internal static bool HasExactEmbeddedSingleFamilyCutBrepAuthority(
        Element wall, int cutterId)
    {
        if (cutterId <= 0
            || wall.CategoryId != -2000011
            || wall.Location is not { CurveType: "Line", ArcRadius: null }
            || wall.SketchLoops is { Count: > 0 }
            || wall.CuttingElementIds is not { Count: 1 } cutters
            || cutters[0] != cutterId
            || wall.References?.Count(id => id == cutterId) != 1
            || wall.Geometry is not { Faces.Count: 10 } source
            || source.BrepSolids is not { Count: 1 } solids
            || solids[0].IsClosed
            || solids[0].FaceIndices.Count != 9
            || solids[0].FaceIndices.Distinct().Count() != 9
            || solids[0].FaceIndices.Any(index =>
                (uint)index >= source.Faces.Count)
            || source.Faces.Any(face =>
                face.OuterVertices is not { Count: >= 3 } vertices
                || vertices.Any(point => point.Length < 3
                    || !double.IsFinite(point[0])
                    || !double.IsFinite(point[1])
                    || !double.IsFinite(point[2]))))
            return false;

        var ownedFaceIndices = solids[0].FaceIndices.ToHashSet();
        if (Enumerable.Range(0, source.Faces.Count)
                .Count(index => !ownedFaceIndices.Contains(index)) != 1)
            return false;
        var alternativeFaceIndices = Enumerable.Range(0, source.Faces.Count)
            .Where(index => source.Faces[index].AlternativeOuterVertices
                is { Count: > 0 })
            .ToList();
        if (alternativeFaceIndices.Count != 1
            || !ownedFaceIndices.Contains(alternativeFaceIndices[0])
            || source.Faces[alternativeFaceIndices[0]].AlternativeOuterVertices
                is not { Count: 6 } alternative
            || alternative.Any(point => point.Length < 3
                || !double.IsFinite(point[0])
                || !double.IsFinite(point[1])
                || !double.IsFinite(point[2])))
            return false;

        return TryBuildStraightWallBoundary(wall, out var rebuiltBoundary)
            && rebuiltBoundary.Faces.Count == 8;
    }

    /// <summary>Builds the wall-local Axis frame owned by the exact embedded-cut BRep.</summary>
    internal static bool TryGetExactEmbeddedSingleFamilyCutBrepAxis(
        Element wall, int cutterId,
        out ExactEmbeddedWallAxisFrame frame,
        out GeometryData localBoundary,
        out bool hasCompletedSourceBrep,
        IReadOnlyDictionary<int, Element>? elements = null)
    {
        frame = default;
        localBoundary = new GeometryData();
        hasCompletedSourceBrep = false;
        if (!HasExactEmbeddedSingleFamilyCutBrepAuthority(wall, cutterId)
            || wall.Location is not { } location
            || !TryBuildStraightWallBoundary(wall, out var boundary)
            || boundary.Faces.Count != 8)
            return false;

        var vertices = boundary.Faces
            .SelectMany(face => face.OuterVertices ?? [])
            .Where(point => point.Length >= 3
                && double.IsFinite(point[0])
                && double.IsFinite(point[1])
                && double.IsFinite(point[2]))
            .ToList();
        if (vertices.Count == 0) return false;
        long minimumZBin = vertices.Min(point =>
            IfcPrecisionBinMetres(point[2] * FeetToMetres));
        var bottom = vertices
            .Where(point => IfcPrecisionBinMetres(point[2] * FeetToMetres)
                == minimumZBin)
            .GroupBy(IfcPrecisionKeyFeet)
            .Select(group => group.First())
            .ToList();
        if (bottom.Count != 4) return false;

        double locationX = location.EndPoint[0] - location.StartPoint[0];
        double locationY = location.EndPoint[1] - location.StartPoint[1];
        double locationLength = Math.Sqrt(
            locationX * locationX + locationY * locationY);
        if (!(locationLength > 0) || !double.IsFinite(locationLength))
            return false;
        locationX /= locationLength;
        locationY /= locationLength;
        double normalX = -locationY;
        double normalY = locationX;

        var projected = bottom.Select(point => new
        {
            Point = point,
            Along = point[0] * locationX + point[1] * locationY,
            Across = point[0] * normalX + point[1] * normalY,
        }).ToList();
        var alongGroups = projected
            .GroupBy(item => IfcPrecisionBinMetres(
                item.Along * FeetToMetres))
            .OrderBy(group => group.Key).ToList();
        var acrossGroups = projected
            .GroupBy(item => IfcPrecisionBinMetres(
                item.Across * FeetToMetres))
            .OrderBy(group => group.Key).ToList();
        if (alongGroups.Count != 2
            || alongGroups.Any(group => group.Count() != 2)
            || acrossGroups.Count != 2
            || acrossGroups.Any(group => group.Count() != 2)
            || projected.Select(item => (
                    Along: IfcPrecisionBinMetres(
                        item.Along * FeetToMetres),
                    Across: IfcPrecisionBinMetres(
                        item.Across * FeetToMetres)))
                .Distinct().Count() != 4)
            return false;

        double[] start =
        [
            alongGroups[0].Average(item => item.Point[0]),
            alongGroups[0].Average(item => item.Point[1]),
        ];
        double[] end =
        [
            alongGroups[1].Average(item => item.Point[0]),
            alongGroups[1].Average(item => item.Point[1]),
        ];
        double axisX = end[0] - start[0];
        double axisY = end[1] - start[1];
        double axisLength = Math.Sqrt(axisX * axisX + axisY * axisY);
        double wallWidth = Math.Abs(
            acrossGroups[1].Average(item => item.Across)
            - acrossGroups[0].Average(item => item.Across));
        double precisionFeet = IfcGeometryPrecisionMetres / FeetToMetres;
        if (!(axisLength > precisionFeet)
            || !(wallWidth > precisionFeet)
            || !double.IsFinite(axisLength)
            || !double.IsFinite(wallWidth))
            return false;
        axisX /= axisLength;
        axisY /= axisLength;
        if (axisX * locationX + axisY * locationY < 1 - 1e-10)
            return false;

        double baseZ = bottom.Average(point => point[2]);
        var bodyAlong = vertices.Select(point =>
            (point[0] - start[0]) * axisX
            + (point[1] - start[1]) * axisY).ToList();
        if (bodyAlong.Min() < -precisionFeet
            || bodyAlong.Max() > axisLength + precisionFeet
            || Math.Abs(bodyAlong.Min()) > precisionFeet
            || Math.Abs(bodyAlong.Max() - axisLength) > precisionFeet)
            return false;
        double localNormalX = -axisY;
        double localNormalY = axisX;
        double coordinateRoundoff = 1024 * 2.2204460492503131e-16
            * Math.Max(1.0, vertices
                .SelectMany(point => point.Take(3)).Select(Math.Abs).Max());
        double Clean(double value, double? upper = null)
        {
            if (Math.Abs(value) <= coordinateRoundoff) return 0;
            if (upper is { } limit
                && Math.Abs(value - limit) <= coordinateRoundoff)
                return limit;
            return value;
        }
        double[] Transform(double[] point)
        {
            double dx = point[0] - start[0];
            double dy = point[1] - start[1];
            return
            [
                Clean(dx * axisX + dy * axisY, axisLength),
                Clean(dx * localNormalX + dy * localNormalY),
                Clean(point[2] - baseZ),
            ];
        }
        List<double[]> TransformRing(IEnumerable<double[]> ring) =>
            ring.Select(Transform).ToList();

        localBoundary = new GeometryData
        {
            Faces = boundary.Faces.Select(face => new GeoFace
            {
                OuterVertices = face.OuterVertices is { } outer
                    ? TransformRing(outer) : null,
                InnerVertices = face.InnerVertices?.Select(TransformRing).ToList(),
                AlternativeOuterVertices = face.AlternativeOuterVertices is { } alternative
                    ? TransformRing(alternative) : null,
            }).ToList(),
        };
        var localVertices = localBoundary.Faces
            .SelectMany(face => face.OuterVertices ?? []).ToList();
        if (localVertices.Count == 0) return false;
        localBoundary.BoundingBox =
        [
            localVertices.Min(point => point[0]),
            localVertices.Min(point => point[1]),
            localVertices.Min(point => point[2]),
            localVertices.Max(point => point[0]),
            localVertices.Max(point => point[1]),
            localVertices.Max(point => point[2]),
        ];
        localBoundary.BrepSolids =
        [
            new GeoBrepSolid
            {
                IsClosed = true,
                FaceIndices = Enumerable.Range(
                    0, localBoundary.Faces.Count).ToList(),
            },
        ];
        frame = new ExactEmbeddedWallAxisFrame(
            start[0], start[1], baseZ,
            axisX, axisY, axisLength);
        if (elements is not null
            && TryBuildExactEmbeddedSingleFamilyCutCompletedBrep(
                wall, frame, localBoundary, elements,
                out var completedBoundary))
        {
            localBoundary = completedBoundary;
            hasCompletedSourceBrep = true;
        }
        return true;
    }

    /// <summary>Completes the exact open source shell owned by the embedded family cut.</summary>
    private static bool TryBuildExactEmbeddedSingleFamilyCutCompletedBrep(
        Element wall, ExactEmbeddedWallAxisFrame frame,
        GeometryData rebuiltLocalBoundary,
        IReadOnlyDictionary<int, Element> elements,
        out GeometryData completedBoundary)
    {
        completedBoundary = new GeometryData();
        if (wall.Geometry is not { Faces.Count: 10 } source
            || source.BrepSolids is not { Count: 1 } sourceSolids
            || rebuiltLocalBoundary.BoundingBox is not { Length: >= 6 } bounds)
            return false;

        double precisionFeet = IfcGeometryPrecisionMetres / FeetToMetres;
        double normalX = -frame.DirectionY;
        double normalY = frame.DirectionX;
        double[] Local(double[] point)
        {
            double dx = point[0] - frame.OriginXFt;
            double dy = point[1] - frame.OriginYFt;
            return
            [
                dx * frame.DirectionX + dy * frame.DirectionY,
                dx * normalX + dy * normalY,
                point[2] - frame.BaseZFt,
            ];
        }
        List<double[]> LocalRing(IEnumerable<double[]> ring) =>
            ring.Select(Local).ToList();

        var localFaces = source.Faces.Select(face => new GeoFace
        {
            OuterVertices = face.OuterVertices is { } outer
                ? LocalRing(outer) : null,
            InnerVertices = face.InnerVertices?.Select(LocalRing).ToList(),
            AlternativeOuterVertices = face.AlternativeOuterVertices is { } alternative
                ? LocalRing(alternative) : null,
        }).ToList();
        if (localFaces.Any(face => face.OuterVertices is not { Count: 4 }
                || face.InnerVertices is { Count: > 0 }))
            return false;

        long Bin(double value) =>
            IfcPrecisionBinMetres(value * FeetToMetres);
        bool Same(double first, double second) => Bin(first) == Bin(second);
        List<double> Groups(IEnumerable<double> values) => values
            .Where(double.IsFinite)
            .GroupBy(Bin)
            .OrderBy(group => group.Key)
            .Select(group => group.Average())
            .ToList();
        HashSet<(long X, long Y, long Z)> Keys(IEnumerable<double[]> points) =>
            points.Select(point => (Bin(point[0]), Bin(point[1]), Bin(point[2])))
                .ToHashSet();
        HashSet<(long X, long Y, long Z)> Set(params double[][] points) =>
            Keys(points);
        string Signature(HashSet<(long X, long Y, long Z)> keys) => string.Join(";",
            keys.OrderBy(key => key.X).ThenBy(key => key.Y).ThenBy(key => key.Z)
                .Select(key => $"{key.X},{key.Y},{key.Z}"));
        HashSet<(long X, long Y, long Z)> Rectangle(
            double first0, double first1,
            double second0, double second1,
            int constantAxis, double constant)
        {
            double[] Point(double first, double second) => constantAxis switch
            {
                0 => [constant, first, second],
                1 => [first, constant, second],
                _ => [first, second, constant],
            };
            return Set(
                Point(first0, second0), Point(first1, second0),
                Point(first1, second1), Point(first0, second1));
        }

        double along0 = 0;
        double along1 = frame.LengthFt;
        double normalMinimum = bounds[1];
        double normalMaximum = bounds[4];
        double baseZ = 0;
        double topZ = bounds[5];
        if (!Same(bounds[0], along0) || !Same(bounds[3], along1)
            || !(normalMaximum - normalMinimum > precisionFeet)
            || !(topZ > precisionFeet))
            return false;

        var owned = sourceSolids[0].FaceIndices.ToHashSet();
        var unownedIndices = Enumerable.Range(0, localFaces.Count)
            .Where(index => !owned.Contains(index)).ToList();
        var alternativeIndices = Enumerable.Range(0, localFaces.Count)
            .Where(index => localFaces[index].AlternativeOuterVertices
                is { Count: > 0 }).ToList();
        if (owned.Count != 9 || unownedIndices.Count != 1
            || alternativeIndices.Count != 1
            || !owned.Contains(alternativeIndices[0]))
            return false;

        int alternativeIndex = alternativeIndices[0];
        GeoFace fragmentFace = localFaces[alternativeIndex];
        List<double[]> alternative = fragmentFace.AlternativeOuterVertices!;
        var alternativeAlong = Groups(alternative.Select(point => point[0]));
        var alternativeNormal = Groups(alternative.Select(point => point[1]));
        var alternativeZ = Groups(alternative.Select(point => point[2]));
        GeoFace unownedBottom = localFaces[unownedIndices[0]];
        if (fragmentFace.OuterVertices is not { } fragmentOuter
            || unownedBottom.OuterVertices is not { } bottomOuter)
            return false;
        var fragmentAlong = Groups(fragmentOuter.Select(point => point[0]));
        var fragmentNormal = Groups(fragmentOuter.Select(point => point[1]));
        var fragmentZ = Groups(fragmentOuter.Select(point => point[2]));
        var bottomAlong = Groups(bottomOuter.Select(point => point[0]));
        var bottomNormal = Groups(bottomOuter.Select(point => point[1]));
        var bottomZ = Groups(bottomOuter.Select(point => point[2]));
        var allPrimaryZ = Groups(localFaces.SelectMany(face =>
            face.OuterVertices!).Select(point => point[2]));
        var allPrimaryNormal = Groups(localFaces.SelectMany(face =>
            face.OuterVertices!).Select(point => point[1]));
        if (alternativeAlong.Count != 4
            || alternativeNormal.Count != 1
            || alternativeZ.Count != 2
            || fragmentAlong.Count != 2
            || fragmentNormal.Count != 1
            || fragmentZ.Count != 2
            || bottomAlong.Count != 2
            || bottomNormal.Count != 2
            || bottomZ.Count != 1
            || allPrimaryZ.Count != 4
            || allPrimaryNormal.Count != 3)
            return false;

        double markerAlong = alternativeAlong[1];
        double cutRightAlong = alternativeAlong[2];
        double cutLeftAlong = fragmentAlong[0];
        double throughStartAlong = bottomAlong[1];
        double shallowBottomZ = fragmentZ[0];
        double throughTopZ = allPrimaryZ[2];
        double insetNormal = allPrimaryNormal[1];
        if (!Same(alternativeAlong[0], along0)
            || !Same(alternativeAlong[3], along1)
            || !Same(alternativeNormal[0], normalMinimum)
            || !Same(alternativeZ[0], baseZ)
            || !Same(alternativeZ[1], topZ)
            || !Same(fragmentAlong[1], markerAlong)
            || !Same(fragmentNormal[0], normalMinimum)
            || !Same(fragmentZ[1], topZ)
            || !Same(bottomAlong[0], along0)
            || !Same(bottomNormal[0], normalMinimum)
            || !Same(bottomNormal[1], normalMaximum)
            || !Same(bottomZ[0], baseZ)
            || !Same(allPrimaryZ[0], baseZ)
            || !Same(allPrimaryZ[1], shallowBottomZ)
            || !Same(allPrimaryZ[3], topZ)
            || !Same(allPrimaryNormal[0], normalMinimum)
            || !Same(allPrimaryNormal[2], normalMaximum)
            || !(along0 + precisionFeet < cutLeftAlong
                && cutLeftAlong + precisionFeet < markerAlong
                && markerAlong + precisionFeet < cutRightAlong
                && cutRightAlong + precisionFeet < throughStartAlong
                && throughStartAlong + precisionFeet < along1)
            || !(baseZ + precisionFeet < shallowBottomZ
                && shallowBottomZ + precisionFeet < throughTopZ
                && throughTopZ + precisionFeet < topZ)
            || !(normalMinimum + precisionFeet < insetNormal
                && insetNormal + precisionFeet < normalMaximum))
            return false;

        var alternativeExpected = Set(
            [along0, normalMinimum, baseZ],
            [along1, normalMinimum, baseZ],
            [along1, normalMinimum, topZ],
            [cutRightAlong, normalMinimum, topZ],
            [markerAlong, normalMinimum, topZ],
            [along0, normalMinimum, topZ]);
        if (alternative.Count != alternativeExpected.Count
            || !Keys(alternative).SetEquals(alternativeExpected))
            return false;

        var expectedOwned = new List<HashSet<(long X, long Y, long Z)>>
        {
            Rectangle(cutLeftAlong, markerAlong, shallowBottomZ, topZ,
                1, normalMinimum),
            Rectangle(throughStartAlong, along1, normalMinimum, normalMaximum,
                2, baseZ),
            Rectangle(throughStartAlong, along1, baseZ, throughTopZ,
                1, normalMaximum),
            Rectangle(cutLeftAlong, markerAlong, normalMinimum, insetNormal,
                2, topZ),
            Rectangle(throughStartAlong, along1, normalMinimum, normalMaximum,
                2, throughTopZ),
            Rectangle(normalMinimum, normalMaximum, baseZ, throughTopZ,
                0, throughStartAlong),
            Rectangle(cutLeftAlong, markerAlong, normalMinimum, insetNormal,
                2, shallowBottomZ),
            Rectangle(normalMinimum, normalMaximum, baseZ, topZ,
                0, along0),
            Rectangle(normalMinimum, normalMaximum, throughTopZ, topZ,
                0, along1),
        };
        var expectedUnowned = Rectangle(
            along0, throughStartAlong, normalMinimum, normalMaximum,
            2, baseZ);
        var actualOwnedSignatures = owned.Select(index =>
                Signature(Keys(localFaces[index].OuterVertices!)))
            .Order().ToList();
        var expectedOwnedSignatures = expectedOwned.Select(Signature)
            .Order().ToList();
        if (!actualOwnedSignatures.SequenceEqual(expectedOwnedSignatures)
            || !Keys(unownedBottom.OuterVertices!).SetEquals(expectedUnowned))
            return false;

        var joinedNeighbours = (wall.References ?? [])
            .Distinct()
            .Where(id => id != wall.Id && elements.TryGetValue(id, out var candidate)
                && candidate.CategoryId == -2000011
                && candidate.Geometry?.Faces is { Count: > 0 })
            .Select(id => elements[id])
            .Select(candidate => new
            {
                Wall = candidate,
                Points = candidate.Geometry!.Faces
                    .SelectMany(face => face.OuterVertices ?? [])
                    .Where(point => point.Length >= 3
                        && point.Take(3).All(double.IsFinite))
                    .Select(Local).ToList(),
            })
            .Where(candidate => candidate.Points.Count > 0
                && candidate.Points.Any(point => Math.Abs(point[0]) <= precisionFeet
                    && point[1] >= normalMinimum - precisionFeet
                    && point[1] <= normalMaximum + precisionFeet))
            .Select(candidate => new
            {
                candidate.Wall.Id,
                MinimumZ = candidate.Points.Min(point => point[2]),
                MaximumZ = candidate.Points.Max(point => point[2]),
            })
            .ToList();
        var splitCandidates = new List<double>();
        foreach (var lower in joinedNeighbours)
            foreach (var upper in joinedNeighbours)
                if (lower.Id != upper.Id
                    && Same(lower.MinimumZ, baseZ)
                    && Same(lower.MaximumZ, upper.MinimumZ)
                    && lower.MaximumZ > baseZ + precisionFeet
                    && lower.MaximumZ < topZ - precisionFeet)
                    splitCandidates.Add((lower.MaximumZ + upper.MinimumZ) / 2);
        var splitGroups = Groups(splitCandidates);
        if (splitGroups.Count != 1) return false;
        double startCapSplitZ = splitGroups[0];

        double[] P(double along, double normal, double z) => [along, normal, z];
        GeoFace Face(params double[][] points) => new() { OuterVertices = points.ToList() };
        var faces = new List<GeoFace>
        {
            Face(
                P(along0, normalMinimum, baseZ),
                P(throughStartAlong, normalMinimum, baseZ),
                P(throughStartAlong, normalMinimum, throughTopZ),
                P(along1, normalMinimum, throughTopZ),
                P(along1, normalMinimum, topZ),
                P(cutRightAlong, normalMinimum, topZ),
                P(cutRightAlong, normalMinimum, shallowBottomZ),
                P(markerAlong, normalMinimum, shallowBottomZ),
                P(cutLeftAlong, normalMinimum, shallowBottomZ),
                P(cutLeftAlong, normalMinimum, topZ),
                P(along0, normalMinimum, topZ),
                P(along0, normalMinimum, startCapSplitZ)),
            Face(
                P(along0, normalMaximum, topZ),
                P(along1, normalMaximum, topZ),
                P(along1, normalMaximum, throughTopZ),
                P(throughStartAlong, normalMaximum, throughTopZ),
                P(throughStartAlong, normalMaximum, baseZ),
                P(along0, normalMaximum, baseZ)),
            Face(
                P(throughStartAlong, normalMinimum, baseZ),
                P(along0, normalMinimum, baseZ),
                P(along0, normalMaximum, baseZ),
                P(throughStartAlong, normalMaximum, baseZ)),
            Face(
                P(along1, normalMaximum, topZ),
                P(along0, normalMaximum, topZ),
                P(along0, normalMinimum, topZ),
                P(cutLeftAlong, normalMinimum, topZ),
                P(cutLeftAlong, insetNormal, topZ),
                P(cutRightAlong, insetNormal, topZ),
                P(cutRightAlong, normalMinimum, topZ),
                P(along1, normalMinimum, topZ)),
            Face(
                P(throughStartAlong, normalMaximum, throughTopZ),
                P(throughStartAlong, normalMinimum, throughTopZ),
                P(throughStartAlong, normalMinimum, baseZ),
                P(throughStartAlong, normalMaximum, baseZ)),
            Face(
                P(throughStartAlong, normalMinimum, throughTopZ),
                P(throughStartAlong, normalMaximum, throughTopZ),
                P(along1, normalMaximum, throughTopZ),
                P(along1, normalMinimum, throughTopZ)),
            Face(
                P(cutRightAlong, insetNormal, shallowBottomZ),
                P(cutRightAlong, insetNormal, topZ),
                P(cutLeftAlong, insetNormal, topZ),
                P(cutLeftAlong, insetNormal, shallowBottomZ),
                P(markerAlong, insetNormal, shallowBottomZ)),
            Face(
                P(cutRightAlong, insetNormal, shallowBottomZ),
                P(markerAlong, insetNormal, shallowBottomZ),
                P(cutLeftAlong, insetNormal, shallowBottomZ),
                P(cutLeftAlong, normalMinimum, shallowBottomZ),
                P(markerAlong, normalMinimum, shallowBottomZ),
                P(cutRightAlong, normalMinimum, shallowBottomZ)),
            Face(
                P(cutLeftAlong, normalMinimum, shallowBottomZ),
                P(cutLeftAlong, insetNormal, shallowBottomZ),
                P(cutLeftAlong, insetNormal, topZ),
                P(cutLeftAlong, normalMinimum, topZ)),
            Face(
                P(cutRightAlong, insetNormal, shallowBottomZ),
                P(cutRightAlong, normalMinimum, shallowBottomZ),
                P(cutRightAlong, normalMinimum, topZ),
                P(cutRightAlong, insetNormal, topZ)),
            Face(
                P(along0, normalMinimum, baseZ),
                P(along0, normalMinimum, startCapSplitZ),
                P(along0, normalMinimum, topZ),
                P(along0, normalMaximum, topZ),
                P(along0, normalMaximum, baseZ)),
            Face(
                P(along1, normalMaximum, topZ),
                P(along1, normalMinimum, topZ),
                P(along1, normalMinimum, throughTopZ),
                P(along1, normalMaximum, throughTopZ)),
        };
        var indices = Enumerable.Range(0, faces.Count).ToList();
        if (!TryOrientExactFacetedShell(
                faces, indices, out var orientedFaces,
                triangulateNonPlanarFaces: false)
            || !IsExactFacetedShell(orientedFaces, indices))
            return false;
        var vertices = orientedFaces.SelectMany(face => face.OuterVertices!).ToList();
        completedBoundary = new GeometryData
        {
            Faces = orientedFaces,
            BoundingBox =
            [
                vertices.Min(point => point[0]),
                vertices.Min(point => point[1]),
                vertices.Min(point => point[2]),
                vertices.Max(point => point[0]),
                vertices.Max(point => point[1]),
                vertices.Max(point => point[2]),
            ],
            BrepSolids =
            [
                new GeoBrepSolid
                {
                    IsClosed = true,
                    FaceIndices = indices,
                },
            ],
        };
        return true;
    }


    /// <summary>
    /// Returns true if the Category string indicates a non-physical element (annotation, link,
    /// symbol, etc).
    /// </summary>
    private static bool IsNonPhysicalCategory(string? category)
    {
        if (string.IsNullOrEmpty(category)) return false; // null category handled by MapCategoryToIfcType
        // Annotations, symbols, links, views, grids, etc.
        return category.Contains("Annotation", StringComparison.OrdinalIgnoreCase)
            || category.Contains("RvtLink", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Symbol", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Tag", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Schedule", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Legend", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Titleblock", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Detail", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Camera", StringComparison.OrdinalIgnoreCase)
            || category.Contains("Analytical", StringComparison.OrdinalIgnoreCase)
            // Spatial/compound sub-elements are represented by their parent IFC entity, not as
            // independent building-element proxies.
            || category.Contains("OST_Rooms", StringComparison.OrdinalIgnoreCase)
            || category.Contains("OST_MEPSpaces", StringComparison.OrdinalIgnoreCase)
            || category.Contains("OST_RailingTopRail", StringComparison.OrdinalIgnoreCase)
            || category.Contains("OST_RailingHandRail", StringComparison.OrdinalIgnoreCase)
            || category.Contains("OST_StairsTrisers", StringComparison.OrdinalIgnoreCase)
            || category.Contains("OST_StairsRailingBaluster", StringComparison.OrdinalIgnoreCase)
            || category.Equals("OST_Parts", StringComparison.OrdinalIgnoreCase);
    }


    /// <summary>
    /// The storey of an element, replaying the storey rule: the base-level
    /// parameter of its kind (a nested family instance reads its top-level instance), then any
    /// stored level reference.
    /// </summary>
    private int ResolveStorey(Element elem, Dictionary<int, int> storeyIds, int defaultStoreyId,
        IReadOnlyDictionary<int, Element> elemById)
    {
        // The current profile reads STAIRS_BASE_LEVEL_PARAM, which is StairsElement.m_baseLevelId.
        if (CurrentProfile && elem.CategoryId == -2000120 && elem.SerializedStairBaseLevelId is int stairBaseLevelId
            && storeyIds.TryGetValue(stairBaseLevelId, out int stairBaseStoreyId))
            return stairBaseStoreyId;
        Element parameterSource = elem.SuperInstanceId is > 0 && elemById.TryGetValue(elem.SuperInstanceId.Value, out var top)
            ? top : elem;
        int[] baseLevelParameters = elem.CategoryId switch
        {
            -2000011 => [-1001107],                 // WALL_BASE_CONSTRAINT
            -2000035 => [-1001651],                 // ROOF_CONSTRAINT_LEVEL_PARAM
            -2000120 => [-1007200],                 // STAIRS_BASE_LEVEL_PARAM
            _ when elem.NativeMasterSymbolId is > 0 => [-1001350, -1001365, -1001383],
            _ => [],
        };
        foreach (int parameterId in baseLevelParameters)
            if (parameterSource.Parameters.FirstOrDefault(parameter => parameter.Id == parameterId)?.Value is int levelId
                && storeyIds.TryGetValue(levelId, out int storeyId))
                return storeyId;

        if (CurrentProfile)
        {
            // LEVEL_PARAM, SCHEDULE_LEVEL_PARAM, RBS_START_LEVEL_PARAM, FAMILY_BASE_LEVEL_PARAM,
            // INSTANCE_SCHEDULE_ONLY_LEVEL_PARAM, INSTANCE_REFERENCE_LEVEL_PARAM,
            // SCHEDULE_BASE_LEVEL_PARAM.
            foreach (int parameterId in elem.CategoryId is -2000035 or -2000120
                         ? new[] { -1001952, -1002062, -1114000, -1001350, -1001365, -1001383, -1002063, -1001352 }
                         : new[] { -1001952, -1002062, -1114000, -1001350, -1001365, -1001383, -1002063 })
                if (elem.Parameters.FirstOrDefault(parameter => parameter.Id == parameterId)?.Value is int assocLevelId
                    && storeyIds.TryGetValue(assocLevelId, out int assocStoreyId))
                    return assocStoreyId;
        }
        // Try to find LEVEL_PARAM or BASE_LEVEL_PARAM in element's parameters
        else foreach (var p in elem.Parameters)
        {
            if (p.StorageType == StorageType.ElementId && p.Value is int refId && refId > 0)
            {
                string? pName = p.Definition?.Name;
                if (pName != null && (pName.Contains("LEVEL") || pName.Contains("CONSTRAINT") || pName.Contains("Level")))
                {
                    if (storeyIds.TryGetValue(refId, out int sid))
                        return sid;
                }
            }
        }

        // No stored level: the highest storey at or below the bottom of the element.
        if (CurrentProfile && storeyIds.Count > 0)
        {
            int byBottom = ResolveStoreyByBottomCurrent(
                (elem.BoundingBox ?? elem.Geometry?.BoundingBox) is { Length: >= 6 } box ? box[2] : null,
                storeyIds, elemById);
            return byBottom != 0 ? byBottom : defaultStoreyId;
        }
        if ((elem.BoundingBox ?? elem.Geometry?.BoundingBox) is { Length: >= 6 } bounds && storeyIds.Count > 0)
        {
            const double Tolerance = 1e-6;
            int best = defaultStoreyId;
            double bestElevation = double.NegativeInfinity;
            foreach (var (levelId, storeyId) in storeyIds)
                if (elemById.TryGetValue(levelId, out var level))
                {
                    double elevation = GetElevation(level);
                    if (elevation <= bounds[2] + Tolerance && elevation > bestElevation)
                    {
                        best = storeyId;
                        bestElevation = elevation;
                    }
                }
            return best;
        }

        return defaultStoreyId;
    }

    /// <summary>10 cm in feet: the storey rule, how far below a level its storey starts.</summary>
    private const double StoreyExtensionFeet = 10.0 / (12.0 * 2.54);

    private Dictionary<int, int>? _storeyRangeSource;
    private (int StoreyId, double Start, double Height)[] _storeyRanges = [];
    private int _storeyRangeBottom;

    /// <summary>The placement rule for an element without a stored level.</summary>
    private int ResolveStoreyByBottomCurrent(double? bottom, Dictionary<int, int> storeyIds,
        IReadOnlyDictionary<int, Element> elemById)
    {
        if (!ReferenceEquals(_storeyRangeSource, storeyIds))
        {
            var levels = storeyIds
                .Where(pair => elemById.ContainsKey(pair.Key))
                .Select(pair => (LevelId: pair.Key, StoreyId: pair.Value, Elevation: GetElevation(elemById[pair.Key])))
                .OrderBy(level => level.Elevation).ThenBy(level => level.LevelId).ToList();
            var ranges = new List<(int LevelId, int StoreyId, double Start, double Height)>();
            for (int i = 0; i < levels.Count; i++)
            {
                double height = 0;
                for (int j = i + 1; j < levels.Count; j++)
                    if (Math.Abs(levels[j].Elevation - levels[i].Elevation) > 1e-7)
                    {
                        height = levels[j].Elevation - levels[i].Elevation;
                        break;
                    }
                ranges.Add((levels[i].LevelId, levels[i].StoreyId, levels[i].Elevation - StoreyExtensionFeet, height));
            }
            ranges.Sort((a, b) => a.LevelId.CompareTo(b.LevelId));
            _storeyRanges = ranges.Select(range => (range.StoreyId, range.Start, range.Height)).ToArray();
            _storeyRangeBottom = 0;
            double lowest = double.MaxValue;
            foreach (var range in _storeyRanges)
                if (range.Start < lowest + 1e-8)
                {
                    _storeyRangeBottom = range.StoreyId;
                    lowest = range.Start;
                }
            _storeyRangeSource = storeyIds;
        }
        int chosen = 0;
        if (bottom is double z)
            foreach (var (storeyId, start, height) in _storeyRanges)
                // Both bounds move by the same tolerance, so no bottom falls between two ranges.
                if (z > start + 1e-9 && (Math.Abs(height) < 1e-10 || z <= start + height + 1e-9))
                    chosen = storeyId;
        return chosen != 0 ? chosen : _storeyRangeBottom;
    }

    // A project Level (building story or not) has no owning family, unplaced instance or DB view;
    // loaded-family reference levels carry an exact owner in one of these serialized fields.
    internal static bool IsProjectLevel(Element level) => level.IsNativeLevel
        && level.SerializedFamilyId == -1
        && level.SerializedUnplacedOwnerId == -1
        && level.SerializedOwnerDbViewId == -1;

    internal static List<Element> GetBuildingStoreyLevels(IEnumerable<Element> elements)
    {
        var candidates = elements
            .Where(element => element.IsNativeLevel
                // A project Level has no owning family, unplaced instance, or DB view.
                && element.SerializedFamilyId == -1
                && element.SerializedUnplacedOwnerId == -1
                && element.SerializedOwnerDbViewId == -1
                && !string.IsNullOrWhiteSpace(element.Name)
                && element.Parameters.Any(parameter => parameter.Id == -1007102
                    && parameter.StorageType == StorageType.Double
                    && parameter.Value is double elevation
                    && double.IsFinite(elevation))
                && element.Parameters.Any(parameter => parameter.Id == -1007111
                    && parameter.StorageType == StorageType.Integer
                    && parameter.Value is int isBuildingStory
                    && isBuildingStory == 1))
            .ToList();

        return candidates
            .OrderBy(GetElevation)
            .ThenBy(element => element.Id)
            .ToList();
    }

    private static double GetElevation(Element level)
    {
        // Look for LEVEL_ELEV parameter
        foreach (var p in level.Parameters)
        {
            string? pName = p.Definition?.Name;
            if (pName != null && pName.Contains("LEVEL_ELEV") && p.StorageType == StorageType.Double && p.Value is double d)
                return d;
        }
        // Fallback: bbox Z
        if (level.BoundingBox != null && level.BoundingBox.Length >= 3)
            return level.BoundingBox[2];
        return 0;
    }


    /// <summary>Get door/window height in mm from params, frame extent, or bbox.</summary>
    private static double GetDoorWindowHeight(Element elem, Element? type)
    {
        double? paramFeet = ExactNamedParameterFeetCurrent(elem, type, "Height", true, -1001300, -1010300);
        if (paramFeet != null && paramFeet > 0)
            return paramFeet.Value * FeetToMetres * 1000;
        double? frameExtent = InstanceFrameExtentMetresCurrent(elem, 2);
        if (frameExtent != null && frameExtent > 0)
            return frameExtent.Value * 1000;
        double[]? bbox = elem.Geometry?.BoundingBox ?? elem.BoundingBox;
        if (bbox != null && bbox.Length >= 6)
            return Math.Abs(bbox[5] - bbox[2]) * FeetToMetres * 1000;
        return 0;
    }

    /// <summary>Get door/window width in mm from params, frame extent, or bbox.</summary>
    private static double GetDoorWindowWidth(Element elem, Element? type)
    {
        double? paramFeet = ExactNamedParameterFeetCurrent(elem, type, "Width", true, -1001301, -1010301);
        if (paramFeet != null && paramFeet > 0)
            return paramFeet.Value * FeetToMetres * 1000;
        double? frameExtent = InstanceFrameExtentMetresCurrent(elem, 0);
        if (frameExtent != null && frameExtent > 0)
            return frameExtent.Value * 1000;
        double[]? bbox = elem.Geometry?.BoundingBox ?? elem.BoundingBox;
        if (bbox != null && bbox.Length >= 6)
        {
            double dx = Math.Abs(bbox[3] - bbox[0]) * FeetToMetres * 1000;
            double dy = Math.Abs(bbox[4] - bbox[1]) * FeetToMetres * 1000;
            return Math.Max(dx, dy);
        }
        return 0;
    }

    // Shorthand helpers
    private static string R(int id) => StepWriter.Ref(id);
    private static string S(string? s) => StepWriter.Str(s);
    private static string D(double v) => StepWriter.Real(v);

    /// <summary>
    /// Kept separate from the exporter's legacy G15 geometry formatter so this narrow property
    /// slice cannot perturb existing IFC data.
    /// </summary>
    private static string D17(double value)
    {
        string result = value.ToString("G17", CultureInfo.InvariantCulture);
        int exponentIndex = result.IndexOfAny(['E', 'e']);
        if (exponentIndex >= 0)
        {
            string mantissa = result[..exponentIndex];
            if (!mantissa.Contains('.')) mantissa += ".0";
            return mantissa + result[exponentIndex..];
        }
        return result.Contains('.') ? result : result + ".";
    }
}
